function findMissingNumber(nums) {
    // calculate the sum of numbers from 1 to n using Gauss' formula
    let n = nums.length;
    let expectedSum = ((n + 1) * (n + 2)) / 2;
    // calculate the actual sum of numbers in the array
    let actualSum = 0;
    for (let i = 0; i < n; i++) {
        actualSum += nums[i];
    }
    // return the difference between the expected sum and the actual sum
    return expectedSum - actualSum;
}

function numberSpiral(y, x) {
    if (y > x) {
        let ans = (y - 1) * (y - 1);
        return y % 2 !== 0 ? ans + x : ans + 2 * y - x;
    } else {
        let ans = (x - 1) * (x - 1);
        return x % 2 === 0 ? ans + y : ans + 2 * x - y;
    }
}

function josephusOrder(n) {
    const people = [];
    for (let i = 1; i <= n; i++) people.push(i);
    const order = [];
    let idx = 0;
    while (people.length > 0) {
        idx = (idx + 1) % people.length;
        order.push(people[idx]);
        people.splice(idx, 1);
        if (idx === people.length) idx = 0;
    }
    return order;
}

