}

function apartments(m, a, b) {
    a.sort((x, y) => x - y); // sorting the array of available apartments
    b.sort((x, y) => x - y); // sorting the array of required apartments
    let i = 0, j = 0, count = 0; // initializing pointers and count
    while (i < a.length && j < b.length) { // iterating through both arrays
        if (Math.abs(a[i] - b[j]) <= m) { // checking if the difference is within the allowed range
            i++; j++; count++; // incrementing pointers and count
        } else if (a[i] < b[j]) { // if the available apartment is smaller
            i++; // incrementing the available apartment pointer
        } else { // if the required apartment is smaller
            j++; // incrementing the required apartment pointer
        }
    }
    return count; // returning the count of matched apartments
    // This algorithm is already optimal with a time complexity of O(n log n) due to sorting
}

function ferrisWheel(people, limit) {
    people.sort((a, b) => a - b);
    let left = 0, right = people.length - 1;
    let gondolas = 0;
    while (left <= right) {
        if (left === right) {
            gondolas++;
            break;
        }
        if (people[left] + people[right] <= limit) {
            left++;
        }
        right--;
        gondolas++;
    }
    return gondolas;
}

function concertTickets(prices, payments) {
    const sorted = [...prices].sort((a, b) => a - b);
    const result = [];
    for (const pay of payments) {
        // binary search for the rightmost price <= pay
        let lo = 0, hi = sorted.length - 1, idx = -1;
        while (lo <= hi) {
            const mid = (lo + hi) >> 1;
            if (sorted[mid] <= pay) { idx = mid; lo = mid + 1; }
            else hi = mid - 1;
        }
        if (idx === -1) {
            result.push(-1);
        } else {
            result.push(sorted[idx]);
            sorted.splice(idx, 1);
        }
    }
    return result;
}

function restaurantCustomers(arrivals, departures) {
    // Sort the arrival times in ascending order
    arrivals.sort((a, b) => a - b);
    // Sort the departure times in ascending order
    departures.sort((a, b) => a - b);
    let maxCustomers = 0, currentCustomers = 0, i = 0, j = 0;
    // Traverse through the sorted arrival and departure times
    while (i < arrivals.length && j < departures.length) {
        // If the current arrival time is less than or equal to the current departure time, increment the current customers
        if (arrivals[i] <= departures[j]) {
            currentCustomers++;
            i++;
        } 
        // If the current arrival time is greater than the current departure time, decrement the current customers
        else {
            currentCustomers--;
            j++;
        }
        // Update the maximum customers
        maxCustomers = Math.max(maxCustomers, currentCustomers);
    }
    return maxCustomers;
}

function diceCombinations(dice, target) {
    // Create a dp array to store the number of combinations for each sum
    var dp = new Array(target + 1).fill(0);
    dp[0] = 1; // base case: there is one way to get a sum of 0 (no dice)
    // For each possible sum from 1 to target
    for (var i = 1; i <= target; i++) {
        // For each possible outcome of a single die
        for (var j = 1; j <= Math.min(i, dice); j++) {
            // Add the number of combinations for the current sum minus the current outcome
            dp[i] = (dp[i] + dp[i - j]) % 1000000007;
        }
    }
    // Return the number of combinations for the target sum
    return dp[target];
}

function minimizingCoins(coins, amount) {
    // Create a dynamic programming table to store the minimum number of coins for each amount
    var dp = new Array(amount + 1).fill(Infinity);
    dp[0] = 0; // Base case: 0 coins are needed to make 0 amount
    // Iterate over each coin and update the dp table
    for (var i = 1; i <= amount; i++) {
        // For each coin, check if it can be used to make the current amount
        for (var j = 0; j < coins.length; j++) {
            // If the coin is less than or equal to the current amount, update the dp table
            if (coins[j] <= i) {
                dp[i] = Math.min(dp[i], dp[i - coins[j]] + 1); // Update the minimum number of coins
            }
        }
    }
    // If no combination of coins can make the amount, return -1
    return dp[amount] === Infinity ? -1 : dp[amount]; // Return the minimum number of coins
}

function coinChange(coins, amount) {
