    dp[0] = 1;
    for (let i = 1; i <= amount; i++) {
        for (const coin of coins) {
            if (coin <= i) {
                dp[i] = (dp[i] + dp[i - coin]) % 1000000007;
            }
        }
    }
    return dp[amount];
}

function coinChange(amount, coins) {
