function removingDigits(n) {
    const dp = new Array(n + 1).fill(Infinity);
    dp[0] = 0;
    for (let i = 1; i <= n; i++) {
        let temp = i;
        while (temp > 0) {
            const d = temp % 10;
            if (d > 0) dp[i] = Math.min(dp[i], dp[i - d] + 1);
            temp = Math.floor(temp / 10);
        }
    }
    return dp[n];
}

function bookShop(prices, pages, budget) {
    // Initialize a 2D array to store the maximum number of pages for each subproblem
    var dp = Array(prices.length + 1).fill(0).map(function() { return Array(budget + 1).fill(0); });

    // Fill the dp array in a bottom-up manner
    for (var i = 1; i <= prices.length; i++) {
        // For each book, consider including or excluding it
        for (var j = 1; j <= budget; j++) {
            // If the current book's price is greater than the current budget, exclude it
            if (prices[i - 1] > j) {
                // The maximum number of pages is the same as the previous book
                dp[i][j] = dp[i - 1][j]; 
            } else {
                // The maximum number of pages is the maximum of including or excluding the current book
                dp[i][j] = Math.max(dp[i - 1][j], dp[i - 1][j - prices[i - 1]] + pages[i - 1]); 
            }
        }
    }

    // The maximum number of pages is stored in the last cell of the dp array
    return dp[prices.length][budget];
}

function countRooms(grid) {
    // Initialize variables to store the number of rooms and the directions for DFS
    var rooms = 0, directions = [[0, 1], [0, -1], [1, 0], [-1, 0]];
    // Create a visited set to keep track of visited cells
    var visited = new Set();
    // Iterate over each cell in the grid
    for (var i = 0; i < grid.length; i++) {
        for (var j = 0; j < grid[0].length; j++) {
            // If the cell is not a wall and has not been visited, perform DFS
            if (grid[i][j] === 0 && !visited.has(i + ',' + j)) {
                // Increment the number of rooms
                rooms++;
                // Perform DFS from the current cell
                dfs(grid, i, j, visited, directions);
            }
        }
    }
    // Return the number of rooms
    return rooms;
}

// Helper function to perform DFS
function dfs(grid, x, y, visited, directions) {
    // Mark the current cell as visited
    visited.add(x + ',' + y);
    // Iterate over each direction
    for (var i = 0; i < directions.length; i++) {
        // Calculate the new coordinates
        var newX = x + directions[i][0], newY = y + directions[i][1];
        // If the new coordinates are within the grid and the cell is not a wall and has not been visited, perform DFS
        if (newX >= 0 && newX < grid.length && newY >= 0 && newY < grid[0].length && grid[newX][newY] === 0 && !visited.has(newX + ',' + newY)) {
            dfs(grid, newX, newY, visited, directions);
        }
    }
}

function buildingRoads(n, connections) {
    // Create an adjacency list to represent the graph
    var graph = Array.from({length: n}, () => []);
    for (var i = 0; i < connections.length; i++) {
        // Add edges to the graph
        graph[connections[i][0]].push(connections[i][1]);
        graph[connections[i][1]].push(connections[i][0]);
    }
    var visited = Array(n).fill(false);
    var count = 0;
    for (var i = 0; i < n; i++) {
        // If a node is not visited, perform DFS and increment the count of connected components
        if (!visited[i]) {
            dfs(graph, visited, i);
            count++;
        }
    }
    return count - 1; // The number of roads to be built is the number of connected components minus one
}

function dfs(graph, visited, node) {
    // Mark the current node as visited
    visited[node] = true;
    for (var i = 0; i < graph[node].length; i++) {
        // Recursively visit all the adjacent nodes
        if (!visited[graph[node][i]]) {
            dfs(graph, visited, graph[node][i]);
        }
    }
}

function messageRoute(graph, start, end) {
    // Create a visited set to keep track of visited nodes
    var visited = new Set();
    // Create a queue for BFS, enqueue the start node
    var queue = [[start]];
    while (queue.length > 0) {
        // Dequeue the first path from the queue
        var path = queue.shift();
        // Get the last node from the path
        var node = path[path.length - 1];
        // If the node is the end node, return the path
        if (node === end) return path;
        // Mark the node as visited
        visited.add(node);
        // Get the neighbors of the node
        var neighbors = graph[node];
        // For each neighbor that has not been visited
        for (var neighbor of neighbors) {
            // If the neighbor has not been visited, create a new path and enqueue it
            if (!visited.has(neighbor)) queue.push([...path, neighbor]);
        }
    }
    // If there is no path from start to end, return null
    return null;
}

function buildTeams(n, edges) {
    const graph = Array.from({ length: n }, () => []);
    for (const [a, b] of edges) {
        graph[a].push(b);
        graph[b].push(a);
    }
    const team = new Array(n).fill(0);
    for (let start = 0; start < n; start++) {
        if (team[start] !== 0) continue;
        team[start] = 1;
        const queue = [start];
        while (queue.length) {
            const node = queue.shift();
            for (const nb of graph[node]) {
                if (team[nb] === 0) {
                    team[nb] = team[node] === 1 ? 2 : 1;
                    queue.push(nb);
                } else if (team[nb] === team[node]) {
                    return null; // IMPOSSIBLE
                }
            }
        }
    }
    return team;
}

function investigation(n, edges) {
    const MOD = 1000000007;
    const graph = Array.from({ length: n }, () => []);
    for (const [a, b, c] of edges) graph[a].push([b, c]);
    const dist = new Array(n).fill(Infinity);
    const ways = new Array(n).fill(0);
    const minF = new Array(n).fill(Infinity);
    const maxF = new Array(n).fill(-Infinity);
    dist[0] = 0; ways[0] = 1; minF[0] = 0; maxF[0] = 0;
    const pq = [[0, 0]];
    while (pq.length) {
        pq.sort((a, b) => a[0] - b[0]);
        const [d, u] = pq.shift();
        if (d > dist[u]) continue;
        for (const [v, w] of graph[u]) {
            const nd = dist[u] + w;
            if (nd < dist[v]) {
                dist[v] = nd;
                ways[v] = ways[u];
                minF[v] = minF[u] + 1;
                maxF[v] = maxF[u] + 1;
                pq.push([nd, v]);
            } else if (nd === dist[v]) {
                ways[v] = (ways[v] + ways[u]) % MOD;
                minF[v] = Math.min(minF[v], minF[u] + 1);
                maxF[v] = Math.max(maxF[v], maxF[u] + 1);
            }
        }
    }
    return [dist[n-1], ways[n-1], minF[n-1], maxF[n-1]];
}

function shortestRoutes(graph, start) {
    // Initialize distances array with infinity for all nodes except the start node
    var distances = new Array(graph.length).fill(Infinity);
    distances[start] = 0;

    // Relax edges repeatedly
    for (var i = 0; i < graph.length - 1; i++) {
        // Iterate over all edges
        for (var u = 0; u < graph.length; u++) {
            for (var v = 0; v < graph[u].length; v++) {
                // If there is an edge from u to v and the distance to v through u is less than the current distance to v
                if (graph[u][v] !== 0 && distances[u] + graph[u][v] < distances[v]) {
                    // Update the distance to v
                    distances[v] = distances[u] + graph[u][v];
                }
            }
        }
    }

    // Check for negative-weight cycles
    for (var u = 0; u < graph.length; u++) {
        for (var v = 0; v < graph[u].length; v++) {
            // If there is an edge from u to v and the distance to v through u is less than the current distance to v
            if (graph[u][v] !== 0 && distances[u] + graph[u][v] < distances[v]) {
                // Negative-weight cycle detected
                throw new Error("Graph contains a negative-weight cycle");
            }
        }
    }

    return distances;
}

function shortestRoutes(n, edges, src, dest) {
    const graph = Array.from({ length: n }, () => []);
    for (const [u, v, w] of edges) {
        graph[u].push([v, w]);
        graph[v].push([u, w]);
    }
    const dist = new Array(n).fill(Infinity);
    dist[src] = 0;
    const visited = new Array(n).fill(false);
    const pq = [[0, src]];
    while (pq.length) {
        pq.sort((a, b) => a[0] - b[0]);
        const [d, node] = pq.shift();
        if (visited[node]) continue;
        visited[node] = true;
        for (const [nb, w] of graph[node]) {
            if (dist[node] + w < dist[nb]) {
                dist[nb] = dist[node] + w;
                pq.push([dist[nb], nb]);
            }
        }
    }
    return dist[dest] === Infinity ? -1 : dist[dest];
}

function treeMatching(n, edges) {
    const adj = Array.from({ length: n }, () => []);
    for (const [a, b] of edges) {
        adj[a].push(b);
        adj[b].push(a);
    }
    const order = [];
    const parent = new Array(n).fill(-1);
    const visited = new Array(n).fill(false);
    const stack = [0];
    visited[0] = true;
    while (stack.length) {
        const node = stack.pop();
        order.push(node);
        for (const nb of adj[node]) {
            if (!visited[nb]) {
                visited[nb] = true;
                parent[nb] = node;
                stack.push(nb);
            }
        }
    }
    const matched = new Array(n).fill(false);
    let count = 0;
    for (let i = order.length - 1; i >= 0; i--) {
        const node = order[i];
        const p = parent[node];
        if (p !== -1 && !matched[node] && !matched[p]) {
            matched[node] = true;
            matched[p] = true;
            count++;
        }
    }
    return count;
}

function treeDistances(n, edges) {
    const adj = Array.from({ length: n }, () => []);
    for (const [a, b] of edges) {
        adj[a].push(b);
        adj[b].push(a);
    }
    function bfs(src) {
        const dist = new Array(n).fill(-1);
        dist[src] = 0;
        const queue = [src];
        let qi = 0;
        while (qi < queue.length) {
            const node = queue[qi++];
            for (const nb of adj[node]) {
                if (dist[nb] === -1) {
                    dist[nb] = dist[node] + 1;
                    queue.push(nb);
                }
            }
        }
        return dist;
    }
    const d0 = bfs(0);
    let a = 0;
    for (let i = 0; i < n; i++) if (d0[i] > d0[a]) a = i;
    const dA = bfs(a);
    let b = 0;
    for (let i = 0; i < n; i++) if (dA[i] > dA[b]) b = i;
    const dB = bfs(b);
    const result = new Array(n);
    for (let i = 0; i < n; i++) result[i] = Math.max(dA[i], dB[i]);
    return result;
}

function wordCombinations(s, words) {
    const n = s.length;
    const dp = new Array(n + 1).fill(0);
    dp[0] = 1;
    for (let i = 1; i <= n; i++) {
        for (const w of words) {
            const L = w.length;
            if (L <= i && s.slice(i - L, i) === w) {
                dp[i] = (dp[i] + dp[i - L]) % 1000000007;
            }
        }
    }
    return dp[n];
}

function stringMatching(text, pattern) {
    // Preprocess the pattern to build the lps (longest proper prefix which is also a proper suffix) array
    let lps = new Array(pattern.length).fill(0);
    let j = 0;
    // Build the lps array
    for (let i = 1; i < pattern.length; i++) {
        // If the current character in the pattern matches the current character in the lps, increment both pointers
        while (j > 0 && pattern[i] !== pattern[j]) j = lps[j - 1];
        // If the current character in the pattern matches the current character in the lps, increment both pointers
        if (pattern[i] === pattern[j]) j++;
        // Update the lps array
        lps[i] = j;
    }
    j = 0;
    let count = 0;
    // Search for the pattern in the text
    for (let i = 0; i < text.length; i++) {
        // If the current character in the text matches the current character in the pattern, increment both pointers
        while (j > 0 && text[i] !== pattern[j]) j = lps[j - 1];
        // If the current character in the text matches the current character in the pattern, increment both pointers
        if (text[i] === pattern[j]) j++;
        if (j === pattern.length) {
            count++;
            j = lps[j - 1];
        }
    }
    return count;
}

function findBorders(word) {
    // Preprocess the word to build the border array
    var border = new Array(word.length).fill(0);
    var i = 1, j = 0;
    while (i < word.length) {
        // If the current character matches the character at the current border index, increment both indices
        if (word[i] === word[j]) {
            j++;
            border[i] = j;
            i++;
        } 
        // If the current character does not match and the current border index is not zero, reset the border index
        else if (j !== 0) {
            j = border[j - 1];
        } 
        // If the current character does not match and the current border index is zero, move to the next character
        else {
            i++;
        }
    }
    return border;
}

function twoSum(nums, target) {
  // Create a hash table to store the numbers we've seen so far and their indices
  var numToIndex = {};
  for (var i = 0; i < nums.length; i++) {
    // Calculate the complement of the current number with respect to the target
    var complement = target - nums[i];
    // Check if we've seen the complement before
    if (complement in numToIndex) {
      // If we have, return the indices of the current number and its complement
      return [numToIndex[complement], i];
    }
    // If not, add the current number and its index to the hash table
    numToIndex[nums[i]] = i;
  }
}

function addTwoNumbers(l1, l2) {
  // create a dummy node to simplify the code
  let dummy = new ListNode(0);
  let current = dummy;
  let carry = 0;
  // iterate through the linked lists until we reach the end of both
  while (l1 || l2 || carry) {
    // calculate the sum of the current nodes and the carry
    let sum = (l1 ? l1.val : 0) + (l2 ? l2.val : 0) + carry;
    // update the carry for the next iteration
    carry = Math.floor(sum / 10);
    // create a new node with the digit value of the sum
    current.next = new ListNode(sum % 10);
    // move to the next node
    current = current.next;
    // move to the next nodes in the linked lists
    l1 = l1 ? l1.next : null;
    l2 = l2 ? l2.next : null;
  }
  // return the next node of the dummy node, which is the start of the result linked list
  return dummy.next;
}

