function lengthOfLongestSubstring(s) {
    // Initialize variables to store the longest substring length and the current window's character set
    let maxLength = 0, windowStart = 0, charIndexMap = {};
    // Iterate over the string
    for (let windowEnd = 0; windowEnd < s.length; windowEnd++) {
        // Get the current character
        let rightChar = s[windowEnd];
        // If the character is already in the map, update the window start
        if (rightChar in charIndexMap) {
            // Update the window start to be the maximum of the current window start and the character's previous index + 1
            windowStart = Math.max(windowStart, charIndexMap[rightChar] + 1);
        }
        // Update the character's index in the map
        charIndexMap[rightChar] = windowEnd;
        // Update the maximum length
        maxLength = Math.max(maxLength, windowEnd - windowStart + 1);
    }
    // Return the maximum length
    return maxLength;
}

function findMedianSortedArrays(nums1, nums2) {
    // ensure that nums1 is the smaller array to simplify the logic
    if (nums1.length > nums2.length) return findMedianSortedArrays(nums2, nums1);
    let x = nums1.length, y = nums2.length;
    let start = 0, end = x;
    while (start <= end) {
        // calculate the partition point for nums1
        let partitionX = Math.floor((start + end) / 2);
        // calculate the partition point for nums2
        let partitionY = Math.floor((x + y + 1) / 2) - partitionX;
        // calculate the values at the partition points
        let maxLeftX = partitionX === 0 ? -Infinity : nums1[partitionX - 1];
        let minRightX = partitionX === x ? Infinity : nums1[partitionX];
        let maxLeftY = partitionY === 0 ? -Infinity : nums2[partitionY - 1];
        let minRightY = partitionY === y ? Infinity : nums2[partitionY];
        // check if the partition is correct
        if (maxLeftX <= minRightY && maxLeftY <= minRightX) {
            // calculate the median
            if ((x + y) % 2 === 0) return (Math.max(maxLeftX, maxLeftY) + Math.min(minRightX, minRightY)) / 2;
            else return Math.max(maxLeftX, maxLeftY);
        } else if (maxLeftX > minRightY) {
            // if the partition is too far to the right, move it to the left
            end = partitionX - 1;
        } else {
            // if the partition is too far to the left, move it to the right
            start = partitionX + 1;
        }
    }
}

