function longestPalindromicSubstring(s) {
  // The algorithm solution is already optimal, using a dynamic programming approach with two pointers
  var n = s.length;
  var dp = new Array(n);
  for (var i = 0; i < n; i++) {
    dp[i] = new Array(n).fill(false);
  }
  var maxLength = 1;
  var start = 0;
  for (var i = n - 1; i >= 0; i--) {
    // Check for palindrome of length 1
    dp[i][i] = true;
    for (var j = i + 1; j < n; j++) {
      // Check for palindrome of length 2
      if (s[i] === s[j] && (j - i === 1 || dp[i + 1][j - 1])) {
        dp[i][j] = true;
        // Update maxLength and start if a longer palindrome is found
        if (j - i + 1 > maxLength) {
          maxLength = j - i + 1;
          start = i;
        }
      }
    }
  }
  return s.substring(start, start + maxLength);
}

function convert(s, numRows) {
    if (numRows === 1) return s; // base case
    let result = ''; // initialize result string
    for (let i = 0; i < numRows; i++) { // iterate over each row
        let j = i; // initialize column index
        while (j < s.length) { // while column index is within string bounds
            result += s[j]; // add character to result string
            // calculate next column index based on zigzag pattern
            if (i !== 0 && i !== numRows - 1) j += (numRows - i - 1) * 2; 
            else j += (numRows - 1) * 2; 
        }
    }
    return result; // return result string
}

function myAtoi(s) {
    // Remove leading whitespace
    s = s.trim();
    // Check if string is empty
    if (s.length === 0) return 0;
    // Initialize sign and result
    let sign = 1, result = 0;
    // Check for negative sign
    if (s[0] === '-') { sign = -1; s = s.slice(1); }
    // Check for positive sign
    else if (s[0] === '+') { s = s.slice(1); }
    // Iterate over the string
    for (let i = 0; i < s.length; i++) {
        // Check if character is a digit
        if (isNaN(parseInt(s[i]))) break;
        // Update result
        result = result * 10 + parseInt(s[i]);
        // Check for overflow
        if (result * sign > 2**31 - 1) return 2**31 - 1;
        // Check for underflow
        else if (result * sign < -(2**31)) return -(2**31);
    }
    // Return the final result
    return result * sign;
}

function isPalindrome(x) {
  // if x is negative, it's not a palindrome
  if (x < 0) return false;
  // convert the number to a string to easily reverse it
  let reversed = 0, original = x;
  // reverse the number
  while (x !== 0) { 
    // get the last digit of x
    let remainder = x % 10;
    // append the last digit to the reversed number
    reversed = reversed * 10 + remainder;
    // remove the last digit from x
    x = Math.floor(x / 10);
  }
  // check if the reversed number is equal to the original number
  return original === reversed;
}

function isMatch(s, p) {
    // Create a 2D array to store the dynamic programming table
    let dp = Array(s.length + 1).fill(false).map(() => Array(p.length + 1).fill(false));
    dp[s.length][p.length] = true; 
    // Fill the dp table in a bottom-up manner
    for (let i = s.length; i >= 0; i--) {
        for (let j = p.length - 1; j >= 0; j--) {
            // Check if the current characters in s and p match
            let match = i < s.length && (p[j] === s[i] || p[j] === '.');
            // If the current character in p is '*', then check the two possible cases
            if (j + 1 < p.length && p[j + 1] === '*') {
                // Case 1: '*' matches zero characters
                dp[i][j] = dp[i][j + 2];
                // Case 2: '*' matches one or more characters
                if (match) {
                    dp[i][j] = dp[i][j] || dp[i + 1][j];
                }
            } else {
                // If the current character in p is not '*', then check if the current characters in s and p match
                dp[i][j] = match && dp[i + 1][j + 1];
            }
        }
    }
    // The result is stored in the top-left corner of the dp table
    return dp[0][0];
}

function maxArea(height) {
  let left = 0, right = height.length - 1; // initialize two pointers
  let maxArea = 0;
  while (left < right) { // loop until two pointers meet
    // calculate the area between two lines and update maxArea if necessary
    let area = Math.min(height[left], height[right]) * (right - left);
    maxArea = Math.max(maxArea, area);
    // move the pointer with the smaller height to the center
    if (height[left] < height[right]) left++; 
    else right--;
  }
  return maxArea; // return the maximum area found
}

function intToRoman(num) {
    // define the mapping of decimal values to their corresponding Roman numerals
    var decimalValues = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1];
    var romanNumerals = ['M', 'CM', 'D', 'CD', 'C', 'XC', 'L', 'XL', 'X', 'IX', 'V', 'IV', 'I'];
    var result = '';
    // iterate over the decimal values and append the corresponding Roman numerals to the result
    for (var i = 0; i < decimalValues.length; i++) {
        // calculate how many times the current decimal value fits into the number
        while (num >= decimalValues[i]) {
            // append the corresponding Roman numeral to the result
            result += romanNumerals[i];
            // subtract the decimal value from the number
            num -= decimalValues[i];
        }
    }
    return result;
}

function romanToInt(s) {
  // create a hash table to store the values of roman numerals
  var romanValues = { 'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000 };
  var result = 0;
  // iterate over the string and add the value of the current numeral to the result
  for (var i = 0; i < s.length; i++) {
    // if the current numeral is less than the next one, subtract its value from the result
    if (i < s.length - 1 && romanValues[s[i]] < romanValues[s[i + 1]]) {
      result -= romanValues[s[i]]; // subtract the value if the current numeral is less than the next one
    } else {
