    let prefix = "";
    for (let i = 0; i < strs[0].length; i++) {
        // If characters at the current position are the same, add to the prefix
        if (strs[0][i] === strs[strs.length - 1][i]) prefix += strs[0][i];
        // If characters are different, break the loop
        else break;
    }
    return prefix;
}

