function threeSumClosest(nums, target) {
  // Sort the array to apply two-pointer technique
  nums.sort((a, b) => a - b);
  let closestSum = nums[0] + nums[1] + nums[2];
  // Iterate over the array and use two pointers to find the closest sum
  for (let i = 0; i < nums.length - 2; i++) {
    // Initialize two pointers, one at the next element and one at the end of the array
    let left = i + 1;
    let right = nums.length - 1;
    while (left < right) {
      // Calculate the current sum
      let currentSum = nums[i] + nums[left] + nums[right];
      // Update the closest sum if the current sum is closer to the target
      if (Math.abs(currentSum - target) < Math.abs(closestSum - target)) {
        closestSum = currentSum;
      }
      // Move the pointers based on the current sum
      if (currentSum < target) {
        left++;
      } else {
        right--;
      }
    }
  }
  return closestSum;
}

function threeSum(nums) {
    // Sort the array to apply two-pointer technique
    nums.sort((a, b) => a - b);
    var result = [];
    for (var i = 0; i < nums.length - 2; i++) {
        // Skip the same result
        if (i > 0 && nums[i] === nums[i - 1]) continue;
        var left = i + 1, right = nums.length - 1;
        while (left < right) {
            // Calculate the sum of three numbers
            var sum = nums[i] + nums[left] + nums[right];
            if (sum < 0) {
                // If sum is less than 0, move left pointer to increase sum
                left++;
            } else if (sum > 0) {
                // If sum is greater than 0, move right pointer to decrease sum
                right--;
            } else {
                // If sum is equal to 0, add the triplet to result and move both pointers
                result.push([nums[i], nums[left], nums[right]]);
                // Skip the same result
                while (left < right && nums[left] === nums[left + 1]) left++;
                // Skip the same result
                while (left < right && nums[right] === nums[right - 1]) right--;
                left++;
                right--;
            }
        }
    }
    return result;
}

function letterCombinations(digits) {
  // define the mapping of digits to letters
  const phoneMapping = {
    "2": "abc",
    "3": "def",
    "4": "ghi",
    "5": "jkl",
    "6": "mno",
    "7": "pqrs",
    "8": "tuv",
    "9": "wxyz"
  };

  // base case: if input is empty, return empty array
  if (digits.length === 0) return [];

  // initialize result array
  let result = [];

  // define a helper function for backtracking
  function backtrack(combination, nextDigits) {
    // if there are no more digits to process, add the current combination to the result
    if (nextDigits.length === 0) {
      // add the current combination to the result
      result.push(combination);
    } else {
      // get the letters for the next digit
      const letters = phoneMapping[nextDigits[0]];
      // for each letter, recursively call the backtrack function
      for (let i = 0; i < letters.length; i++) {
        // recursively call the backtrack function with the updated combination and remaining digits
        backtrack(combination + letters[i], nextDigits.slice(1));
      }
    }
  }

  // start the backtracking process
  backtrack("", digits);

  // return the result
  return result;
}

function removeNthFromEnd(head, n) {
    // Initialize two pointers, both at the head of the list
    let first = head;
    let second = head;
    // Move the first pointer n steps ahead
    for (let i = 0; i < n; i++) first = first.next;
    // If the first pointer is null, it means we need to remove the head
    if (first === null) return head.next;
    // Move both pointers until the first pointer reaches the end of the list
    while (first.next !== null) {
        // Move both pointers one step at a time
        first = first.next;
        second = second.next;
    }
    // Remove the nth node from the end
    second.next = second.next.next;
    return head;
}

function isValid(s) {
    // Create a dictionary to store the corresponding closing brackets for each opening bracket
    var bracketMap = {')': '(', '}': '{', ']': '['};
    // Initialize an empty stack to store the opening brackets
    var stack = [];
    // Iterate over each character in the input string
    for (var i = 0; i < s.length; i++) {
        // If the character is an opening bracket, push it onto the stack
        if (s[i] === '(' || s[i] === '{' || s[i] === '[') {
            stack.push(s[i]);
        } 
        // If the character is a closing bracket, check if the stack is empty or the top of the stack does not match the current closing bracket
        else if (s[i] === ')' || s[i] === '}' || s[i] === ']') {
            if (stack.length === 0 || stack.pop() !== bracketMap[s[i]]) {
                return false;
            }
        }
    }
    // If the stack is empty after iterating over the entire string, the string is valid
    return stack.length === 0;
}

function mergeTwoLists(list1, list2) {
    // if list1 is empty, return list2 as it's already sorted
    if (!list1) return list2;
    // if list2 is empty, return list1 as it's already sorted
    if (!list2) return list1;
    // if list1's value is smaller, set it as the head and recursively merge the rest of list1 and list2
    if (list1.val < list2.val) return { val: list1.val, next: mergeTwoLists(list1.next, list2) };
    // if list2's value is smaller, set it as the head and recursively merge the rest of list1 and list2
    return { val: list2.val, next: mergeTwoLists(list1, list2.next) };
}

function swapPairs(head) {
    // base case: if list is empty or only has one node, return head as it is
    if (!head || !head.next) return head;
    // store the next node to be swapped
    let nextNode = head.next;
    // swap the nodes
    head.next = swapPairs(nextNode.next);
    // swap the nodes
    nextNode.next = head;
    // return the new head
    return nextNode;
}

function generateParenthesis(n) {
    // Initialize an empty array to store the result
    let result = [];
    // Define a helper function for backtracking
    function backtrack(open, close, current) {
        // If the length of the current string is equal to 2n, add it to the result
        if (current.length === 2 * n) {
            result.push(current);
            return;
        }
        // If the number of open parentheses is less than n, add an open parenthesis
        if (open < n) {
            // Recursively call the backtrack function with the updated current string and open count
            backtrack(open + 1, close, current + "(");
        }
        // If the number of close parentheses is less than the number of open parentheses, add a close parenthesis
        if (close < open) {
            // Recursively call the backtrack function with the updated current string and close count
            backtrack(open, close + 1, current + ")");
        }
    }
    // Call the backtrack function with initial values
    backtrack(0, 0, "");
    // Return the result
    return result;
}

