function mergeKLists(lists) {
  // Create a min-heap to store the current smallest node from each list
  const minHeap = [];
  for (let i = 0; i < lists.length; i++) {
    // Push the first node of each list into the min-heap
    if (lists[i]) {
      minHeap.push({ val: lists[i].val, listIndex: i, node: lists[i] });
    }
  }

  // Create a result linked list
  const dummyHead = new ListNode(0);
  let current = dummyHead;

  // Heapify the min-heap
  minHeap.sort((a, b) => a.val - b.val);

  // Merge the linked lists
  while (minHeap.length > 0) {
    // Get the smallest node from the min-heap
    const smallestNode = minHeap.shift();
    // Add the smallest node to the result linked list
    current.next = smallestNode.node;
    current = current.next;
    // If the current list has more nodes, push the next node into the min-heap
    if (smallestNode.node.next) {
      minHeap.push({ val: smallestNode.node.next.val, listIndex: smallestNode.listIndex, node: smallestNode.node.next });
      // Heapify the min-heap again
      minHeap.sort((a, b) => a.val - b.val);
    }
  }

  // Return the result linked list
  return dummyHead.next;
}

function removeDuplicates(nums) {
    // Initialize two pointers, one for the unique elements and one for the current element
    let uniqueIndex = 1;
    for (let currentIndex = 1; currentIndex < nums.length; currentIndex++) {
        // If the current element is different from the previous one, move it to the unique index
        if (nums[currentIndex] !== nums[currentIndex - 1]) {
            nums[uniqueIndex] = nums[currentIndex];
            uniqueIndex++;
        }
    }
    return uniqueIndex;
}

function reverseKGroup(head, k) {
    // check if the length of the linked list is less than k
    let length = 0;
    let temp = head;
    while (temp !== null) {
        length++;
        temp = temp.next;
    }
    if (length < k) return head;

    // reverse the first k nodes
    let prev = null;
    let curr = head;
    for (let i = 0; i < k; i++) {
        // store the next node before reversing the link
        let next = curr.next;
        // reverse the link
        curr.next = prev;
        // move to the next node
        prev = curr;
        curr = next;
    }

    // recursively reverse the remaining nodes
    head.next = reverseKGroup(curr, k);
    // return the new head of the reversed list
    return prev;
}

function removeElement(nums, val) {
