        // if the current element is not equal to val, swap it with the element at the first pointer
        if (nums[i] !== val) {
            // swap elements
            nums[k] = nums[i];
            // move the first pointer forward
            k++;
        }
    }
    // return the number of elements not equal to val
    return k;
}

