function divide(dividend, divisor) {
    if (divisor === 0) {
        throw new Error("Cannot divide by zero");
    }
    let sign = (dividend < 0) ^ (divisor < 0) ? -1 : 1;
    let a = Math.abs(dividend);
    let b = Math.abs(divisor);
    let quotient = 0;
    while (a >= b) {
        let shift = 0;
        while ((b << shift) <= a) {
            shift++;
        }
        a -= (b << (shift - 1));
        quotient += (1 << (shift - 1));
    }
    quotient *= sign;
    if (quotient > (2**31) - 1) {
        return (2**31) - 1;
    } else if (quotient < -(2**31)) {
        return -(2**31);
    }
    return quotient;
}

function findSubstring(s, words) {
    // Define the length of a single word and the total number of words
    var wordLength = words[0].length;
    var totalWords = words.length;
    var totalLength = wordLength * totalWords;
    var wordCount = {};
    for (var word of words) {
        // Count the frequency of each word in the words array
        if (wordCount[word]) {
            wordCount[word]++;
        } else {
            wordCount[word] = 1;
        }
    }
    var result = [];
    for (var i = 0; i <= s.length - totalLength; i++) {
        // Initialize a copy of the wordCount object for each window
        var windowCount = Object.assign({}, wordCount);
        for (var j = 0; j < totalWords; j++) {
            // Extract the word at the current position in the window
            var word = s.substring(i + j * wordLength, i + (j + 1) * wordLength);
            // If the word is not in the wordCount object or its frequency is 0, break the loop
            if (!windowCount[word] || windowCount[word] === 0) {
                break;
            }
            // Decrement the frequency of the word in the windowCount object
            windowCount[word]--;
            // If all words have been found in the window, add the starting index to the result
            if (j === totalWords - 1) {
                result.push(i);
            }
        }
    }
    return result;
}

function nextPermutation(nums) {
  // Find the first decreasing element from the right
  let i = nums.length - 2;
  while (i >= 0 && nums[i] >= nums[i + 1]) i--;

  // If no decreasing element is found, the array is the last permutation, so we reverse it
  if (i === -1) return nums.reverse();

  // Find the smallest element to the right of i that is greater than nums[i]
  let j = nums.length - 1;
  while (nums[j] <= nums[i]) j--;

  // Swap nums[i] and nums[j]
  [nums[i], nums[j]] = [nums[j], nums[i]];

  // Reverse the elements to the right of i
  let left = i + 1, right = nums.length - 1;
  while (left < right) {
    // Swap nums[left] and nums[right]
    [nums[left], nums[right]] = [nums[right], nums[left]];
    left++;
    right--;
  }
}

function longestValidParentheses(s) {
  let maxLength = 0; // initialize max length
  let stack = [-1]; // stack to store indices of unmatched parentheses
  for (let i = 0; i < s.length; i++) { // iterate over string
    if (s[i] === '(') { // if open parenthesis, push index to stack
      stack.push(i);
    } else { // if close parenthesis
      stack.pop(); // pop index from stack
      if (stack.length === 0) { // if stack is empty, push current index
        stack.push(i);
      } else { // calculate length of current valid substring
        maxLength = Math.max(maxLength, i - stack[stack.length - 1]); // update max length
      }
    }
  }
  return maxLength; // return max length
}

function search(nums, target) {
  let left = 0, right = nums.length - 1;
  // Perform binary search and adjust the search space based on whether the left or right half is sorted
  while (left <= right) {
    let mid = Math.floor((left + right) / 2);
    // If the target is found, return its index
    if (nums[mid] === target) return mid;
    // If the left half is sorted
    if (nums[left] <= nums[mid]) {
      // If the target is in the sorted left half, update the right pointer
      if (nums[left] <= target && target < nums[mid]) right = mid - 1;
      // Otherwise, update the left pointer
      else left = mid + 1;
    }
    // If the right half is sorted
    else {
      // If the target is in the sorted right half, update the left pointer
      if (nums[mid] < target && target <= nums[right]) left = mid + 1;
      // Otherwise, update the right pointer
      else right = mid - 1;
    }
  }
  // If the target is not found, return -1
  return -1;
}

function searchRange(nums, target) {
    function binarySearch(findFirst) {
        let left = 0, right = nums.length - 1, result = -1;
        // Use binary search to find the first or last occurrence of the target
        while (left <= right) {
            let mid = Math.floor((left + right) / 2);
            if (nums[mid] === target) {
                result = mid;
                // If finding the first occurrence, move the right pointer to the left
                if (findFirst) right = mid - 1;
                // If finding the last occurrence, move the left pointer to the right
                else left = mid + 1;
            } else if (nums[mid] < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return result;
    }
    // Find the first and last occurrences of the target
    let first = binarySearch(true), last = binarySearch(false);
    return [first, last];
}

function searchInsert(nums, target) {
    // Initialize two pointers for binary search
    let left = 0, right = nums.length - 1;
    // Continue searching while the two pointers haven't crossed each other
    while (left <= right) {
        // Calculate the middle index
        let mid = Math.floor((left + right) / 2);
        // If the target is found, return the index
        if (nums[mid] === target) return mid;
        // If the target is less than the middle element, move the right pointer
        else if (nums[mid] > target) right = mid - 1;
        // If the target is greater than the middle element, move the left pointer
        else left = mid + 1;
    }
    // If the target is not found, return the index where it should be inserted
    return left;
}

function isValidSudoku(board) {
    let rows = Array(9).fill(0).map(() => new Set());
    let cols = Array(9).fill(0).map(() => new Set());
    let boxes = Array(9).fill(0).map(() => new Set());
    // Iterate over each cell in the board
    for (let i = 0; i < 9; i++) {
        for (let j = 0; j < 9; j++) {
            let val = board[i][j];
            // If the cell is empty, skip it
            if (val === '.') continue;
            // Calculate the box index
            let boxIndex = Math.floor(i / 3) * 3 + Math.floor(j / 3);
            // Check if the value already exists in the row, column, or box
            if (rows[i].has(val) || cols[j].has(val) || boxes[boxIndex].has(val)) return false;
            // Add the value to the row, column, and box sets
            rows[i].add(val);
            cols[j].add(val);
            boxes[boxIndex].add(val);
        }
    }
    // If we've checked all cells and haven't returned false, the board is valid
    return true;
}

function countAndSay(n) {
    let result = '1'; // initialize the sequence with '1'
    for (let i = 1; i < n; i++) { // loop through the sequence
        let next = ''; // initialize the next sequence
        let count = 1; // initialize the count of consecutive characters
        for (let j = 1; j <= result.length; j++) { // loop through the current sequence
            // if the current character is the same as the previous one, increment the count
            if (j < result.length && result[j] === result[j - 1]) {
                count++;
            } else { // otherwise, append the count and character to the next sequence
                next += count + result[j - 1];
                count = 1; // reset the count
            }
        }
        result = next; // update the current sequence
    }
    return result; // return the nth sequence
}

function solveSudoku(board) {
  // Define the size of the Sudoku board
  const size = 9;
  const boxSize = 3;

  // Function to check if a number can be placed at a given position
  function isValid(row, col, num) {
    // Check the row
    for (let i = 0; i < size; i++) {
      // If the number already exists in the row, return false
      if (board[row][i] === num.toString()) return false;
    }

    // Check the column
    for (let i = 0; i < size; i++) {
      // If the number already exists in the column, return false
      if (board[i][col] === num.toString()) return false;
    }

    // Check the box
    const boxRow = Math.floor(row / boxSize) * boxSize;
    const boxCol = Math.floor(col / boxSize) * boxSize;
    for (let i = 0; i < boxSize; i++) {
      for (let j = 0; j < boxSize; j++) {
        // If the number already exists in the box, return false
        if (board[boxRow + i][boxCol + j] === num.toString()) return false;
      }
    }

    // If the number does not exist in the row, column, or box, return true
    return true;
  }

  // Function to solve the Sudoku puzzle using backtracking
  function solve() {
    // Iterate over the board
    for (let i = 0; i < size; i++) {
      for (let j = 0; j < size; j++) {
        // If the current cell is empty
        if (board[i][j] === ".") {
          // Try numbers from 1 to 9
          for (let num = 1; num <= size; num++) {
            // If the number can be placed at the current position
            if (isValid(i, j, num)) {
              // Place the number at the current position
              board[i][j] = num.toString();
              // Recursively try to fill the rest of the board
              if (solve()) return true;
              // If the recursive call returns false, reset the current cell
              board[i][j] = ".";
            }
          }
          // If no number can be placed at the current position, return false
          return false;
        }
      }
    }
    // If the entire board is filled, return true
    return true;
  }

  // Call the solve function
  solve();
}

// TIME: O(9^(n*n)) SPACE: O(n*n)

function combinationSum(candidates, target) {
  const result = []; // store the combinations that sum to target
  function backtrack(remain, comb, start) { // backtrack function to explore all combinations
    // if the remaining sum is 0, it means we have found a valid combination
    if (remain === 0) result.push([...comb]);
    // if the remaining sum is negative, it means the current combination exceeds the target
    else if (remain < 0) return;
    for (let i = start; i < candidates.length; i++) { // iterate over the candidates
      // add the current candidate to the current combination
      comb.push(candidates[i]);
      // recursively call the backtrack function with the updated remaining sum and combination
      backtrack(remain - candidates[i], comb, i); // allow the same number to be chosen from candidates an unlimited number of times
      // remove the last added candidate from the current combination for backtracking
      comb.pop();
    }
  }
  backtrack(target, [], 0); // start the backtracking process
  return result;
}

// TIME: O(N^(T/M + 1)) SPACE: O(T/M)

function combinationSum2(candidates, target) {
  // Sort the candidates array to handle duplicates
  candidates.sort((a, b) => a - b);
  var result = [];
  function backtrack(remain, comb, start) {
    // If the remaining target is zero, it means we have found a valid combination
    if (remain === 0) result.push([...comb]);
    // Iterate over the candidates array
    for (var i = start; i < candidates.length; i++) {
      // Skip duplicates to avoid duplicate combinations
      if (i > start && candidates[i] === candidates[i-1]) continue;
      // If the current candidate is greater than the remaining target, break the loop
      if (candidates[i] > remain) break;
      // Add the current candidate to the current combination
      comb.push(candidates[i]);
      // Recursively call the backtrack function with the updated remaining target and combination
      backtrack(remain - candidates[i], comb, i + 1);
      // Remove the last added candidate from the current combination for backtracking
      comb.pop();
    }
  }
  backtrack(target, [], 0);
  return result;
}

function firstMissingPositive(nums) {
    // Separate positive numbers to the left side of the array
    let j = 0;
    for (let i = 0; i < nums.length; i++) {
        // Check if the current number is positive
        if (nums[i] > 0) {
            // Swap the current number with the number at index j
            let temp = nums[j];
            nums[j] = nums[i];
            nums[i] = temp;
            j++;
        }
    }

    // Mark the presence of an element x by using the sign of the value at index x
    for (let i = 0; i < j; i++) {
        // Calculate the absolute value of the current number
        let num = Math.abs(nums[i]);
        // Check if the number is within the range of the array
        if (num - 1 < j) {
            // Mark the presence of the number
            nums[num - 1] = -Math.abs(nums[num - 1]);
        }
    }

    // Find the first missing positive number
    for (let i = 0; i < j; i++) {
        // Check if the number at index i is positive
        if (nums[i] > 0) {
            // Return the index plus one as the first missing positive number
            return i + 1;
        }
    }

    // If no missing positive number is found, return the length of the array plus one
    return j + 1;
}

function trap(height) {
    let left = 0, right = height.length - 1; // initialize two pointers
    let maxLeft = 0, maxRight = 0; // keep track of max height on both sides
    let result = 0;
    while (left <= right) { 
        // if height of left bar is less than right bar, update maxLeft and calculate trapped water
        if (height[left] < height[right]) {
            if (height[left] >= maxLeft) maxLeft = height[left]; 
            else result += maxLeft - height[left]; 
            left++; 
        } 
        // if height of right bar is less than or equal to left bar, update maxRight and calculate trapped water
        else {
            if (height[right] >= maxRight) maxRight = height[right]; 
            else result += maxRight - height[right]; 
            right--; 
        }
    }
    return result;
}

function multiply(num1, num2) {
    // Initialize result array with zeros
    let result = new Array(num1.length + num2.length).fill(0);
    // Multiply each digit of num1 with each digit of num2 and store in result array
    for (let i = num1.length - 1; i >= 0; i--) {
        for (let j = num2.length - 1; j >= 0; j--) {
            // Calculate the product and add it to the corresponding position in the result array
            let product = (num1.charCodeAt(i) - '0'.charCodeAt(0)) * (num2.charCodeAt(j) - '0'.charCodeAt(0));
            let p1 = i + j, p2 = i + j + 1;
            let sum = product + result[p2];
            result[p1] += Math.floor(sum / 10);
            result[p2] = sum % 10;
        }
    }
    // Remove leading zeros from the result array
    let start = 0;
    while (start < result.length - 1 && result[start] === 0) {
        start++;
    }
    // Convert the result array to a string
    return result.slice(start).join('');
}

function isMatch(s, p) {
    // Initialize a 2D array to store the dynamic programming table
    let dp = Array(s.length + 1).fill(0).map(() => Array(p.length + 1).fill(false));
    // Initialize the base case where both strings are empty
    dp[0][0] = true;
    // Fill the first row of the table where the pattern is empty
    for (let j = 1; j <= p.length; j++) {
        // If the current character in the pattern is '*', it can match an empty string
        if (p[j - 1] === '*') {
            dp[0][j] = dp[0][j - 1];
        }
    }
    // Fill the rest of the table
    for (let i = 1; i <= s.length; i++) {
        for (let j = 1; j <= p.length; j++) {
            // If the current character in the pattern is '?', it can match any character in the string
            if (p[j - 1] === '?') {
                dp[i][j] = dp[i - 1][j - 1];
            } 
            // If the current character in the pattern is '*', it can match any sequence of characters in the string
            else if (p[j - 1] === '*') {
                // If the '*' matches zero characters, the result is the same as the previous character in the pattern
                dp[i][j] = dp[i][j - 1] || dp[i - 1][j];
            } 
            // If the current character in the pattern is not '*' or '?', it must match the current character in the string
            else {
                dp[i][j] = dp[i - 1][j - 1] && s[i - 1] === p[j - 1];
            }
        }
    }
    // The result is stored in the bottom-right corner of the table
    return dp[s.length][p.length];
}

function jump(nums) {
  let maxReach = nums[0]; // keep track of the maximum reachable position
  let step = nums[0]; // keep track of the remaining steps before we need to make another jump
  let jumps = 1; // initialize the number of jumps
  // iterate through the array starting from the second element
  for (let i = 1; i < nums.length; i++) {
    // if we've reached the end of our current jump, we need to make another jump
    if (i === step) {
      jumps++; // increment the number of jumps
      step = maxReach; // update the remaining steps
    }
    // update the maximum reachable position
    maxReach = Math.max(maxReach, i + nums[i]);
    // if we've reached the end of the array, we can stop
    if (step >= nums.length - 1) {
      break;
    }
  }
  // if we've reached the end of the array, return the number of jumps
  return jumps;
}

function rotate(matrix) {
  // Transpose the matrix by swapping elements across the diagonal
  for (let i = 0; i < matrix.length; i++) {
    for (let j = i; j < matrix.length; j++) {
      // Swap elements across the diagonal
      let temp = matrix[i][j];
      matrix[i][j] = matrix[j][i];
      matrix[j][i] = temp;
    }
  }
  // Reverse each row to complete the rotation
  for (let i = 0; i < matrix.length; i++) {
    // Reverse the row using two pointers
    let left = 0;
    let right = matrix.length - 1;
    while (left < right) {
      let temp = matrix[i][left];
      matrix[i][left] = matrix[i][right];
      matrix[i][right] = temp;
      left++;
      right--;
    }
  }
}

function permute(nums) {
  // Initialize result array to store all permutations
  var result = [];
  // Define a helper function to generate permutations using backtracking
  function backtrack(current, remaining) {
    // If there are no more numbers to choose from, add the current permutation to the result
    if (remaining.length === 0) result.push([...current]);
    else {
      // For each number in the remaining array, add it to the current permutation and recurse
      for (var i = 0; i < remaining.length; i++) {
        // Add the current number to the current permutation
        current.push(remaining[i]);
        // Remove the current number from the remaining array
        var newRemaining = remaining.slice(0, i).concat(remaining.slice(i + 1));
        // Recurse with the updated current permutation and remaining array
        backtrack(current, newRemaining);
        // Remove the last added number from the current permutation (backtracking)
        current.pop();
      }
    }
  }
  // Start the backtracking process with an empty current permutation and the input array
  backtrack([], nums);
  // Return the result array containing all permutations
  return result;
}

function permuteUnique(nums) {
  // Sort the array to group duplicate numbers together
  nums.sort((a, b) => a - b);
  var result = [];
  var used = new Array(nums.length).fill(false);
  function backtrack(current) {
    // If the current permutation is complete, add it to the result
    if (current.length === nums.length) {
      result.push([...current]);
      return;
    }
    for (var i = 0; i < nums.length; i++) {
      // Skip the current number if it's already used or if it's the same as the previous number
      if (used[i] || (i > 0 && nums[i] === nums[i - 1] && !used[i - 1])) {
        continue;
      }
      // Mark the current number as used and add it to the current permutation
      used[i] = true;
      current.push(nums[i]);
      // Recursively generate permutations with the current number
      backtrack(current);
      // Backtrack by removing the current number from the permutation and marking it as unused
      current.pop();
      used[i] = false;
    }
  }
  backtrack([]);
  return result;
}

// TIME: O(N! / (K1! * K2! * ... * Km!)) SPACE: O(N)

function groupAnagrams(strs) {
  // Create a hash table to store the sorted characters as keys and the original strings as values
  var hashTable = {};
  for (var i = 0; i < strs.length; i++) {
    // Sort the characters in the current string and use it as a key in the hash table
    var sortedStr = strs[i].split('').sort().join('');
    if (!hashTable[sortedStr]) {
      hashTable[sortedStr] = [];
    }
    // Add the original string to the corresponding key in the hash table
    hashTable[sortedStr].push(strs[i]);
  }
  // Return the values in the hash table as the result
  return Object.values(hashTable);
}

// TIME: O(n*m*log(m)) SPACE: O(n*m)

function myPow(x, n) {
    // base case: anything to the power of 0 is 1
    if (n === 0) return 1;
    // if n is negative, calculate the reciprocal of x to the power of -n
    if (n < 0) return 1 / myPow(x, -n);
    // if n is even, calculate x to the power of n/2 and square the result
    if (n % 2 === 0) return myPow(x * x, n / 2);
    // if n is odd, calculate x to the power of (n-1)/2, square the result, and multiply by x
    return x * myPow(x * x, (n - 1) / 2);
}

function solveNQueens(n) {
  const result = [];
  const board = Array(n).fill('.').map(() => Array(n).fill('.'));
  function backtrack(row) {
    // check if all queens are placed
    if (row === n) {
      const solution = board.map(row => row.join(''));
      result.push(solution);
      return;
    }
    for (let col = 0; col < n; col++) {
      // check if it's safe to place a queen at (row, col)
      if (isSafe(row, col)) {
        board[row][col] = 'Q';
        backtrack(row + 1);
        // backtrack by removing the queen
        board[row][col] = '.';
      }
    }
  }
  function isSafe(row, col) {
    // check the column
    for (let i = 0; i < row; i++) {
      if (board[i][col] === 'Q') return false;
    }
    // check the main diagonal
    for (let i = row - 1, j = col - 1; i >= 0 && j >= 0; i--, j--) {
      if (board[i][j] === 'Q') return false;
    }
    // check the other diagonal
    for (let i = row - 1, j = col + 1; i >= 0 && j < n; i--, j++) {
      if (board[i][j] === 'Q') return false;
    }
    return true;
  }
  backtrack(0);
  return result;
}

function maxSubArray(nums) {
    // Initialize maximum sum and current sum to the first element of the array
    let maxSum = nums[0];
    let currentSum = nums[0];
    // Iterate through the array starting from the second element
    for (let i = 1; i < nums.length; i++) {
        // Update current sum to be the maximum of the current number and the sum of the current number and the previous current sum
        currentSum = Math.max(nums[i], currentSum + nums[i]);
        // Update maximum sum to be the maximum of the current maximum sum and the current sum
        maxSum = Math.max(maxSum, currentSum);
    }
    // Return the maximum sum found
    return maxSum;
}

function spiralOrder(matrix) {
    // Initialize result array and row/column boundaries
    var result = [];
    var rowStart = 0, rowEnd = matrix.length - 1;
    var colStart = 0, colEnd = matrix[0].length - 1;

    // Continue iterating until all elements are visited
    while (rowStart <= rowEnd && colStart <= colEnd) {
        // Traverse from left to right
        for (var i = colStart; i <= colEnd; i++) {
            // Add current element to result array
            result.push(matrix[rowStart][i]);
        }
        rowStart++;

        // Traverse from top to bottom
        for (var i = rowStart; i <= rowEnd; i++) {
            // Add current element to result array
            result.push(matrix[i][colEnd]);
        }
        colEnd--;

        // Traverse from right to left if rowStart is still within bounds
        if (rowStart <= rowEnd) {
            for (var i = colEnd; i >= colStart; i--) {
                // Add current element to result array
                result.push(matrix[rowEnd][i]);
            }
        }
        rowEnd--;

        // Traverse from bottom to top if colStart is still within bounds
        if (colStart <= colEnd) {
            for (var i = rowEnd; i >= rowStart; i--) {
                // Add current element to result array
                result.push(matrix[i][colStart]);
            }
        }
        colStart++;
    }

    return result;
}

function totalNQueens(n) {
    function isValid(board, row, col) {
        // Check this column on left side
        for (let i = 0; i < row; i++) {
            if (board[i] === col || 
                board[i] - i === col - row || 
                board[i] + i === col + row) {
                return false;
            }
        }
        return true;
    }

    function placeQueens(board, row) {
        // Base case: If all queens are placed then increment count
        if (row === n) {
            return 1;
        }
        let count = 0;
        // Consider this column and try placing this queen in all rows one by one
        for (let col = 0; col < n; col++) {
            // Check if the queen can be placed on board[row][col]
            if (isValid(board, row, col)) {
                // Place this queen in board[row][col]
                board[row] = col;
                // recur to place rest of the queens
                count += placeQueens(board, row + 1);
            }
        }
        return count;
    }

    let board = new Array(n).fill(-1);
    return placeQueens(board, 0);
}

function canJump(nums) {
  // keep track of the maximum reachable index
  let maxReachableIndex = 0;
  // iterate through the array
  for (let i = 0; i < nums.length; i++) {
    // if we can't reach this index, return false
    if (i > maxReachableIndex) return false;
    // update the maximum reachable index
    maxReachableIndex = Math.max(maxReachableIndex, i + nums[i]);
  }
  // if we can reach the last index, return true
  return true;
}

function merge(intervals) {
  // Sort the intervals based on their start value
  intervals.sort(function(a, b) { return a[0] - b[0]; });
  var merged = [intervals[0]];
  // Iterate through the intervals and merge overlapping ones
  for (var i = 1; i < intervals.length; i++) {
    // Check if the current interval overlaps with the last merged interval
    if (intervals[i][0] <= merged[merged.length - 1][1]) {
      // Merge the current interval with the last merged interval
      merged[merged.length - 1][1] = Math.max(merged[merged.length - 1][1], intervals[i][1]);
    } else {
      // Add the current interval to the merged list
      merged.push(intervals[i]);
    }
  }
  return merged;
}

function insert(intervals, newInterval) {
    // Initialize result array and index to track current position in intervals array
    let result = [], i = 0;
    // Add all intervals that come before the new interval
    while (i < intervals.length && intervals[i][1] < newInterval[0]) {
        // Add current interval to result array
        result.push(intervals[i]);
        i++;
    }
    // Merge all overlapping intervals to the new interval
    while (i < intervals.length && intervals[i][0] <= newInterval[1]) {
        // Update newInterval to be the merged interval
        newInterval[0] = Math.min(newInterval[0], intervals[i][0]);
        newInterval[1] = Math.max(newInterval[1], intervals[i][1]);
        i++;
    }
    // Add the new interval
    result.push(newInterval);
    // Add all remaining intervals to the result array
    while (i < intervals.length) {
        // Add current interval to result array
        result.push(intervals[i]);
        i++;
    }
    return result;
}

function lengthOfLastWord(s) {
    // remove trailing spaces and split the string into words
    var words = s.trim().split(' ');
    // return the length of the last word
    return words[words.length - 1].length;
}

function getPermutation(n, k) {
    // calculate the factorial of n
    let factorial = [1];
    for (let i = 1; i <= n; i++) {
        // calculate the factorial iteratively
        factorial[i] = factorial[i - 1] * i;
    }
    let numbers = [];
    for (let i = 1; i <= n; i++) {
        // initialize an array to store the available numbers
        numbers.push(i);
    }
    let result = '';
    k--; // adjust k to be 0-indexed
    for (let i = n; i >= 1; i--) {
        // calculate the index of the current number
        let index = Math.floor(k / factorial[i - 1]);
        k %= factorial[i - 1];
        // append the current number to the result
        result += numbers[index];
        // remove the current number from the available numbers
        numbers.splice(index, 1);
    }
    return result;
}

function generateMatrix(n) {
    // Initialize the matrix with zeros
    var matrix = new Array(n).fill(0).map(() => new Array(n).fill(0));
    var count = 1;
    var rowStart = 0, rowEnd = n - 1;
    var colStart = 0, colEnd = n - 1;
    // Continue the loop until all elements are filled
    while (rowStart <= rowEnd && colStart <= colEnd) {
        // Fill the first row from left to right
        for (var i = colStart; i <= colEnd; i++) matrix[rowStart][i] = count++;
        rowStart++;
        // Fill the last column from top to bottom
        for (var i = rowStart; i <= rowEnd; i++) matrix[i][colEnd] = count++;
        colEnd--;
        // Fill the last row from right to left
        if (rowStart <= rowEnd) {
            for (var i = colEnd; i >= colStart; i--) matrix[rowEnd][i] = count++;
            rowEnd--;
        }
        // Fill the first column from bottom to top
        if (colStart <= colEnd) {
            for (var i = rowEnd; i >= rowStart; i--) matrix[i][colStart] = count++;
            colStart++;
        }
    }
    return matrix;
}

function rotateRight(head, k) {
  // if the list is empty or only contains one node, return the head as it is
  if (!head || !head.next) return head;

  // initialize two pointers, one at the head and one at the end of the list
  let oldTail = head;
  let n = 1;
  // find the length of the list and the last node
  while (oldTail.next) {
    oldTail = oldTail.next;
    n += 1;
  }

  // connect the last node to the head to form a ring
  oldTail.next = head;

  // find the new tail, which is (n - k % n - 1) nodes from the head
  let newTail = head;
  for (let i = 0; i < n - k % n - 1; i++) {
    newTail = newTail.next;
  }

  // find the new head, which is the next node of the new tail
  let newHead = newTail.next;

  // break the ring at the new tail
  newTail.next = null;

  // return the new head
  return newHead;
}

function uniquePaths(m, n) {
    // Create a 2D array to store the number of unique paths to each cell
    let dp = Array(m).fill().map(() => Array(n).fill(1));
    // Fill the dp array in a bottom-up manner
    for (let i = 1; i < m; i++) {
        for (let j = 1; j < n; j++) {
            // The number of unique paths to a cell is the sum of the number of unique paths to the cell above it and the cell to its left
            dp[i][j] = dp[i - 1][j] + dp[i][j - 1];
        }
    }
    // The number of unique paths to the bottom-right corner is stored in the bottom-right cell of the dp array
    return dp[m - 1][n - 1];
}

function uniquePathsWithObstacles(obstacleGrid) {
    var m = obstacleGrid.length, n = obstacleGrid[0].length;
    // Create a 2D array to store the number of unique paths to each cell
    var dp = new Array(m).fill(0).map(() => new Array(n).fill(0));
    // Initialize the first cell
    dp[0][0] = obstacleGrid[0][0] === 0 ? 1 : 0;
    // Fill the first row
    for (var i = 1; i < n; i++) {
        // If the current cell is not an obstacle and the previous cell is reachable
        dp[0][i] = obstacleGrid[0][i] === 0 ? dp[0][i - 1] : 0;
    }
    // Fill the first column
    for (var i = 1; i < m; i++) {
        // If the current cell is not an obstacle and the cell above it is reachable
        dp[i][0] = obstacleGrid[i][0] === 0 ? dp[i - 1][0] : 0;
    }
    // Fill the rest of the grid
    for (var i = 1; i < m; i++) {
        for (var j = 1; j < n; j++) {
            // If the current cell is not an obstacle, the number of unique paths to it is the sum of the number of unique paths to the cell above it and the cell to its left
            dp[i][j] = obstacleGrid[i][j] === 0 ? dp[i - 1][j] + dp[i][j - 1] : 0;
        }
    }
    // The number of unique paths to the bottom-right corner is stored in the bottom-right cell of the dp array
    return dp[m - 1][n - 1];
}

function minPathSum(grid) {
  // Initialize the first element of the first row and column as the base case
  for (let i = 1; i < grid.length; i++) grid[i][0] += grid[i-1][0];
  for (let j = 1; j < grid[0].length; j++) grid[0][j] += grid[0][j-1];
  // Fill up the rest of the grid with the minimum sum from the top or left
  for (let i = 1; i < grid.length; i++) 
    for (let j = 1; j < grid[0].length; j++) 
      grid[i][j] += Math.min(grid[i-1][j], grid[i][j-1]);
  // The minimum path sum is stored in the bottom right corner of the grid
  return grid[grid.length-1][grid[0].length-1];
}

function isNumber(s) {
    let seenE = false, seenDot = false, seenDigit = false;
    for (let i = 0; i < s.length; i++) {
        // Check if the current character is a digit
        if (!isNaN(s[i])) seenDigit = true;
        // Check if the current character is a sign
        else if (s[i] === '+' || s[i] === '-') {
            // If the current character is a sign, it must be at the start or after 'e' or 'E'
            if (i !== 0 && s[i - 1].toLowerCase() !== 'e') return false;
        }
        // Check if the current character is 'e' or 'E'
