    while (low <= high) {
        // Calculate the mid value
        var mid = Math.floor((low + high) / 2);
        // If the square of mid is less than or equal to x, update the result and move the low pointer
        if (mid * mid <= x) {
            result = mid;
            low = mid + 1;
        } 
        // If the square of mid is greater than x, move the high pointer
        else {
            high = mid - 1;
