  let ways = new Array(n + 1);
  ways[1] = 1;
  ways[2] = 2;

  // For each step from 3 to n, calculate the number of ways to climb
  for (let i = 3; i <= n; i++) {
    // Number of ways to climb i steps is the sum of the number of ways to climb i-1 and i-2 steps
    ways[i] = ways[i - 1] + ways[i - 2];
