  // Initialize the base cases for the dynamic programming table
  for (var i = 0; i <= word1.length; i++) {
    // The minimum edit distance between a substring of word1 and an empty string is the length of the substring
    dp[i][0] = i;
  }
  for (var j = 0; j <= word2.length; j++) {
    // The minimum edit distance between an empty string and a substring of word2 is the length of the substring
    dp[0][j] = j;
  }

  // Fill in the rest of the dynamic programming table
  for (var i = 1; i <= word1.length; i++) {
    for (var j = 1; j <= word2.length; j++) {
      // If the current characters in word1 and word2 are the same, there is no edit cost
      if (word1[i - 1] === word2[j - 1]) {
