    let windowCounts = {};

    // Iterate over the string s
    for (let right = 0; right < s.length; right++) {
        // Add the current character to the window
        let character = s[right];
        windowCounts[character] = (windowCounts[character] || 0) + 1;

        // If the current character is in t and its frequency in the window is equal to its frequency in t
        if (tCount[character] && windowCounts[character] === tCount[character]) {
            // Increment the formed count
            formed++;
        }

        // While the window is valid and the left pointer is not at the beginning of the string
        while (left <= right && formed === count) {
