      currentCombination.push(i);

      // Recursively call the backtrack function with the next start number
      backtrack(i + 1);

      // Remove the last added number from the current combination (backtracking)
      currentCombination.pop();
    }
  }

  // Call the backtrack function with the initial start number
  backtrack(1);

  // Return the result
  return result;
