function exist(board, word) {
    // Define the directions for DFS
    const directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    // Get the number of rows and columns in the board
    const rows = board.length, cols = board[0].length;
    // Create a visited set to keep track of visited cells
    const visited = new Array(rows).fill(0).map(() => new Array(cols).fill(false));

    // Define the DFS function
    function dfs(row, col, index) {
        // If the current character does not match the character in the word, return false
        if (board[row][col] !== word[index]) return false;
        // If the current index is the last index in the word, return true
        if (index === word.length - 1) return true;
        // Mark the current cell as visited
        visited[row][col] = true;
        // Perform DFS in all four directions
        for (const [dr, dc] of directions) {
            const nr = row + dr, nc = col + dc;
            // Check if the new cell is within the board and not visited
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && !visited[nr][nc]) {
                // If DFS returns true, return true
                if (dfs(nr, nc, index + 1)) return true;
