        }
        // Unmark the current cell as visited
        visited[row][col] = false;
        // If DFS returns false in all directions, return false
        return false;
    }

    // Perform DFS from each cell in the board
    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            // If DFS returns true, return true
            if (dfs(i, j, 0)) return true;
        }
    }
