function generateTrees(n) {
    function generateTreesHelper(start, end) {
        // base case: if start is greater than end, return a list containing null
        if (start > end) return [null];
        const trees = [];
        // for each possible root node from start to end
        for (let i = start; i <= end; i++) {
            // generate all possible left subtrees
            const leftSubtrees = generateTreesHelper(start, i - 1);
            // generate all possible right subtrees
            const rightSubtrees = generateTreesHelper(i + 1, end);
            // for each possible left subtree and right subtree, create a new tree with i as the root
            for (const left of leftSubtrees) {
                for (const right of rightSubtrees) {
