function numTrees(n) {
    // Initialize an array to store the number of unique BST's for each number of nodes
    let dp = new Array(n + 1).fill(0);
    // Base case: there is only one way to construct an empty tree
    dp[0] = 1;
    // Base case: there is only one way to construct a tree with one node
    dp[1] = 1;
    // Calculate the number of unique BST's for each number of nodes from 2 to n
    for (let i = 2; i <= n; i++) {
        // For each number of nodes, calculate the number of unique BST's by considering each node as the root
        for (let j = 1; j <= i; j++) {
            // The number of unique BST's is the product of the number of unique left and right subtrees
            dp[i] += dp[j - 1] * dp[i - j];
        }
    }
    // Return the number of unique BST's for n nodes
    return dp[n];
}

function isValidBST(root) {
    function dfs(node, minVal, maxVal) {
