function isInterleave(s1, s2, s3) {
    // If lengths of s1, s2, and s3 do not match, s3 cannot be formed by interleaving s1 and s2
    if (s1.length + s2.length !== s3.length) return false;

    // Create a 2D array to store the dynamic programming table
    var dp = new Array(s1.length + 1);
    for (var i = 0; i <= s1.length; i++) {
        dp[i] = new Array(s2.length + 1);
    }

    // Initialize the base case where s1 and s2 are empty
    dp[0][0] = true;

    // Fill the first row of the table
    for (var i = 1; i <= s2.length; i++) {
        // If the current character in s2 matches the current character in s3, update the table
        dp[0][i] = dp[0][i - 1] && s2[i - 1] === s3[i - 1];
    }

    // Fill the first column of the table
    for (var i = 1; i <= s1.length; i++) {
        // If the current character in s1 matches the current character in s3, update the table
        dp[i][0] = dp[i - 1][0] && s1[i - 1] === s3[i - 1];
    }

    // Fill the rest of the table
    for (var i = 1; i <= s1.length; i++) {
        for (var j = 1; j <= s2.length; j++) {
            // If the current character in s1 or s2 matches the current character in s3, update the table
            dp[i][j] = (dp[i - 1][j] && s1[i - 1] === s3[i + j - 1]) || (dp[i][j - 1] && s2[j - 1] === s3[i + j - 1]);
