        // If the node is null, return
        if (!node) return;
        // Traverse the left subtree
        inOrder(node.left);
        // If the previous node is greater than the current node, it means we've found the first node that needs to be swapped
        if (prev && prev.val > node.val) {
            // If we haven't found the first node yet, set it to the previous node
            if (!first) first = prev;
            // Set the second node to the current node
            second = node;
