        if (t1 === null || t2 === null) return false;
        // If the values of the nodes are not equal, the trees are not mirror images
        // If the left subtree of t1 is a mirror image of the right subtree of t2 and the right subtree of t1 is a mirror image of the left subtree of t2, the trees are mirror images
        return (t1.val === t2.val) && isMirror(t1.right, t2.left) && isMirror(t1.left, t2.right);
