        if (preStart > preEnd) return null;
        let root = { val: preorder[preStart], left: null, right: null };
        let inIndex = inorderMap[preorder[preStart]];
        let leftSize = inIndex - inStart;
        root.left = recursiveBuild(preStart + 1, preStart + leftSize, inStart, inIndex - 1);
        root.right = recursiveBuild(preStart + leftSize + 1, preEnd, inIndex + 1, inEnd);
