function buildTree(inorder, postorder) {
  const inorderIndexMap = {};
  for (let i = 0; i < inorder.length; i++) {
    inorderIndexMap[inorder[i]] = i;
  }
  function recursiveBuildTree(inorderStart, inorderEnd, postorderStart, postorderEnd) {
    if (inorderStart > inorderEnd) return null;
    const root = { val: postorder[postorderEnd], left: null, right: null };
    const inorderRootIndex = inorderIndexMap[postorder[postorderEnd]];
    const leftSubtreeSize = inorderRootIndex - inorderStart;
    root.left = recursiveBuildTree(inorderStart, inorderRootIndex - 1, postorderStart, postorderStart + leftSubtreeSize - 1);
    root.right = recursiveBuildTree(inorderRootIndex + 1, inorderEnd, postorderStart + leftSubtreeSize, postorderEnd - 1);
