        currentSum += node.val;
        // If current node is a leaf and sum equals targetSum, add path to result
        if (!node.left && !node.right && currentSum === targetSum) result.push([...currentPath]);
        // Recursively explore left and right subtrees
        dfs(node.left, currentPath, currentSum); // Explore left subtree
        dfs(node.right, currentPath, currentSum); // Explore right subtree
