  for (var i = 1; i <= t.length; i++) {
    for (var j = 1; j <= s.length; j++) {
      // If the current characters in s and t are the same, we have two options: 
      // either include the current character in s or not
      if (s[j - 1] === t[i - 1]) {
        // Add the number of distinct subsequences without the current character in s
        // to the number of distinct subsequences without the current character in t
        dp[i][j] = dp[i][j - 1] + dp[i - 1][j - 1];
