}

function generate(numRows) {
    let result = [[1]]; // initialize the first row of Pascal's triangle
    for (let i = 1; i < numRows; i++) { // loop through each row
        let row = [1]; // start each row with 1
        for (let j = 1; j < i; j++) { // calculate the middle elements
            // calculate the sum of the two numbers directly above it
            row.push(result[i-1][j-1] + result[i-1][j]);
        }
        row.push(1); // end each row with 1
        result.push(row); // add the row to the result
    }
