function getRow(rowIndex) {
  // Initialize the first row of Pascal's triangle
  let row = [1];
  // Generate each row up to the desired row index
  for (let i = 1; i <= rowIndex; i++) {
    // Initialize the next row with the first element as 1
    let nextRow = [1];
    // Calculate the middle elements of the next row
    for (let j = 1; j < i; j++) {
      // Each element is the sum of the two elements directly above it
      nextRow.push(row[j - 1] + row[j]);
    }
    // Add the last element as 1
    nextRow.push(1);
    // Update the current row
    row = nextRow;
  }
  // Return the desired row
  return row;
}

function minimumTotal(triangle) {
  // start from the second last row and move upwards to fill up the dp table
  for (var i = triangle.length - 2; i >= 0; i--) {
    // for each element in the current row, add the minimum of the two elements directly below it
    for (var j = 0; j < triangle[i].length; j++) {
