  let maxProfit = 0; // keep track of the maximum profit that can be achieved
  for (let i = 0; i < prices.length; i++) { 
    // update minPrice if a lower price is found
    if (prices[i] < minPrice) minPrice = prices[i]; 
    // update maxProfit if a higher profit can be achieved by selling at the current price
    if (prices[i] - minPrice > maxProfit) maxProfit = prices[i] - minPrice; 
  }
  return maxProfit; // return the maximum profit that can be achieved
}

function maxProfit(prices) {
  // Initialize variables to store the maximum profit after the first buy, first sell, second buy, and second sell
  let firstBuy = -Infinity, firstSell = 0, secondBuy = -Infinity, secondSell = 0;
  // Iterate through the prices array to update the maximum profit variables
  for (let price of prices) {
    // Update the maximum profit after the first buy
