  maxPathSumHelper(root);

  // Return the maximum path sum
  return maxSum;
}

function isPalindrome(s) {
  // Initialize two pointers at the start and end of the string
  let left = 0, right = s.length - 1;
  // Continue the loop until the two pointers meet
  while (left < right) {
    // If the character at the left pointer is not alphanumeric, move the pointer to the right
    if (!isAlphanumeric(s[left])) left++;
    // If the character at the right pointer is not alphanumeric, move the pointer to the left
    else if (!isAlphanumeric(s[right])) right--;
    // If the characters at the two pointers are not equal (ignoring case), return false
    else if (s[left].toLowerCase() !== s[right].toLowerCase()) return false;
    // If the characters at the two pointers are equal, move both pointers
    else {
      left++;
      right--;
    }
  }
  // If the loop completes without returning false, the string is a palindrome
  return true;
}

// Helper function to check if a character is alphanumeric
function isAlphanumeric(char) {
  return (char >= 'a' && char <= 'z') || (char >= 'A' && char <= 'Z') || (char >= '0' && char <= '9');
}

function longestConsecutive(nums) {
  // Create a hash set to store the numbers for O(1) lookup
  var numSet = new Set(nums);
  var longestStreak = 0;

  // Iterate over each number in the set
  for (var num of numSet) {
    // Check if it's the start of a sequence
    if (!numSet.has(num - 1)) {
      // Initialize the current number and the current streak
      var currentNum = num;
      var currentStreak = 1;

      // Check numbers that are consecutive to currentNum
      while (numSet.has(currentNum + 1)) {
        // If it is, increment the current number and the current streak
        currentNum += 1;
        currentStreak += 1;
      }

      // Update the longest streak if the current streak is longer
      longestStreak = Math.max(longestStreak, currentStreak);
    }
  }

