function findLadders(beginWord, endWord, wordList) {
    let wordSet = new Set(wordList);
    if (!wordSet.has(endWord)) return [];

    let queue = [[beginWord]];
    let result = [];
    let shortest = Infinity;

    while (queue.length > 0) {
        // process one whole level at a time so multiple equal-length paths
        // to the same word aren't pruned by an early wordSet.delete()
        const levelSize = queue.length;
        const usedThisLevel = new Set();

        for (let k = 0; k < levelSize; k++) {
            let path = queue.shift();
            let word = path[path.length - 1];

            if (path.length > shortest) return result;

            if (word === endWord) {
                if (path.length === shortest) result.push(path);
                else if (path.length < shortest) {
                    result = [path];
                    shortest = path.length;
                }
                continue;
            }

            for (let i = 0; i < word.length; i++) {
                for (let j = 0; j < 26; j++) {
                    let nextWord = word.slice(0, i) + String.fromCharCode(97 + j) + word.slice(i + 1);
                    if (wordSet.has(nextWord)) {
                        queue.push([...path, nextWord]);
                        usedThisLevel.add(nextWord);
                    }
                }
            }
        }
        for (const w of usedThisLevel) wordSet.delete(w);
    }

    return result;
}
