function solve(board) {
    // Check if the board is empty
    if (!board || board.length === 0) return;

    // Get the number of rows and columns
    const rows = board.length;
    const cols = board[0].length;

    // Define a function to perform DFS
    function dfs(row, col) {
        // Check if the current cell is within the board and is an 'O'
        if (row < 0 || row >= rows || col < 0 || col >= cols || board[row][col] !== 'O') return;

        // Mark the current cell as visited by changing it to 'N'
        board[row][col] = 'N';

        // Perform DFS on the neighboring cells
        dfs(row - 1, col); // Top
        dfs(row + 1, col); // Bottom
        dfs(row, col - 1); // Left
        dfs(row, col + 1); // Right
    }

    // Perform DFS on the cells on the border
    for (let i = 0; i < rows; i++) {
        dfs(i, 0); // Left border
        dfs(i, cols - 1); // Right border
    }
    for (let i = 0; i < cols; i++) {
        dfs(0, i); // Top border
        dfs(rows - 1, i); // Bottom border
    }

    // Capture the surrounded regions
    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            // If the cell is an 'O', it is surrounded, so capture it
            if (board[i][j] === 'O') board[i][j] = 'X';
            // If the cell is an 'N', it is not surrounded, so change it back to 'O'
            else if (board[i][j] === 'N') board[i][j] = 'O';
        }
    }
}

function partition(s) {
    // Initialize result array to store all possible palindrome partitions
    var result = [];
    // Define a helper function to check if a string is a palindrome
    function isPalindrome(str) {
        // Compare the string with its reverse
        return str === str.split('').reverse().join('');
    }
    // Define a helper function to perform backtracking
    function backtrack(start, path) {
        // If the start index reaches the end of the string, add the current path to the result
        if (start === s.length) {
            // Create a copy of the current path to avoid modifying the original array
            result.push([...path]);
            return;
        }
        // Iterate over all possible substring lengths
        for (var i = 1; i <= s.length - start; i++) {
            // Extract the substring
            var substring = s.substring(start, start + i);
            // Check if the substring is a palindrome
            if (isPalindrome(substring)) {
                // If it's a palindrome, add it to the current path and continue backtracking
                path.push(substring);
                // Recursively call the backtrack function with the updated start index and path
                backtrack(start + i, path);
                // Remove the last added substring to backtrack and explore other possibilities
                path.pop();
            }
        }
    }
    // Start the backtracking process from the beginning of the string
    backtrack(0, []);
    // Return the result array containing all possible palindrome partitions
    return result;
}

function cloneGraph(node) {
    if (!node) return null;
    const visited = new Map();
    function dfs(node) {
        // Create a new node if it's not visited before
        if (!visited.has(node)) {
            const newNode = { val: node.val, neighbors: [] };
            visited.set(node, newNode);
            // Recursively clone all its neighbors
            for (const neighbor of node.neighbors) {
                // If the neighbor is not visited, clone it first
                if (!visited.has(neighbor)) dfs(neighbor);
                // Add the cloned neighbor to the new node's neighbors
                newNode.neighbors.push(visited.get(neighbor));
            }
        }
        // Return the cloned node
        return visited.get(node);
    }
    return dfs(node);
}

function canCompleteCircuit(gas, cost) {
    let totalGas = 0, totalCost = 0, tank = 0, start = 0;
    for (let i = 0; i < gas.length; i++) {
        // calculate the total gas and total cost to check if it's possible to complete the circuit
        totalGas += gas[i];
        totalCost += cost[i];
        tank += gas[i] - cost[i];
        // if the tank is empty, reset the start index and the tank
        if (tank < 0) {
            start = i + 1;
            tank = 0;
        }
    }
    // if the total gas is less than the total cost, it's impossible to complete the circuit
    if (totalGas < totalCost) return -1;
    // otherwise, return the start index
    return start;
}

function minCut(s) {
    // Create a 2D array to store whether each substring is a palindrome
    var isPalindrome = new Array(s.length);
    for (var i = 0; i < s.length; i++) {
        isPalindrome[i] = new Array(s.length);
    }
    // Initialize the diagonal of the 2D array to true since single characters are always palindromes
    for (var i = 0; i < s.length; i++) {
        isPalindrome[i][i] = true;
    }
    // Fill the 2D array in a bottom-up manner
    for (var length = 2; length <= s.length; length++) {
        for (var i = 0; i < s.length - length + 1; i++) {
            var j = i + length - 1;
            // If the substring has a length of 2, it's a palindrome if the characters are the same
            if (length == 2) {
                isPalindrome[i][j] = (s[i] == s[j]);
            } 
            // For longer substrings, it's a palindrome if the first and last characters are the same and the substring in between is a palindrome
            else {
                isPalindrome[i][j] = (s[i] == s[j] && isPalindrome[i + 1][j - 1]);
            }
        }
    }
    // Create a 1D array to store the minimum cuts needed for each substring
    var minCuts = new Array(s.length);
    // Initialize the first element to 0 since a single character needs no cuts
    minCuts[0] = 0;
    // Fill the 1D array in a bottom-up manner
    for (var i = 1; i < s.length; i++) {
        // Initialize the minimum cuts for the current substring to the maximum possible value
        var min = i;
        // Check all possible cuts
        for (var j = 0; j <= i; j++) {
            // If the substring from j to i is a palindrome, update the minimum cuts
            if (isPalindrome[j][i]) {
                // If this is the first cut, the minimum cuts is 0
                if (j == 0) {
                    min = 0;
                } 
                // Otherwise, update the minimum cuts
                else if (minCuts[j - 1] + 1 < min) {
                    min = minCuts[j - 1] + 1;
                }
            }
        }
        // Update the minimum cuts for the current substring
        minCuts[i] = min;
    }
    // Return the minimum cuts for the entire string
    return minCuts[s.length - 1];
}

function candy(ratings) {
  // Initialize an array to store the number of candies for each child
  let candies = new Array(ratings.length).fill(1);

  // Iterate through the ratings from left to right
  for (let i = 1; i < ratings.length; i++) {
    // If the current child has a higher rating than the previous child, give them one more candy
    if (ratings[i] > ratings[i - 1]) candies[i] = candies[i - 1] + 1;
  }

  // Iterate through the ratings from right to left
  for (let i = ratings.length - 2; i >= 0; i--) {
    // If the current child has a higher rating than the next child and they don't already have more candies, give them one more candy
    if (ratings[i] > ratings[i + 1] && candies[i] <= candies[i + 1]) candies[i] = candies[i + 1] + 1;
  }

  // Calculate the total number of candies
  let totalCandies = 0;
  for (let i = 0; i < candies.length; i++) {
    totalCandies += candies[i];
  }

  return totalCandies;
}

function singleNumber(nums) {
  // Initialize result variable to 0, and use XOR operation to find the single number
  let result = 0;
  for (let i = 0; i < nums.length; i++) {
    // XOR operation has the property that a ^ a = 0 and a ^ 0 = a, so all numbers that appear twice will cancel out
    result ^= nums[i];
  }
  return result;
}

function singleNumber(nums) {
  // Initialize variables to store the bits that appear once and twice
  let ones = 0, twos = 0;
  // Iterate over each number in the array
  for (let num of nums) {
    // Update the bits that appear twice
    twos |= ones & num; 
    // Update the bits that appear once
    ones ^= num; 
    // Remove the bits that appear three times
    let threes = ones & twos; 
    // Remove the bits that appear three times from ones and twos
    ones &= ~threes; 
    twos &= ~threes;
  }
  // Return the bits that appear once
  return ones;
}

function copyRandomList(head) {
    // Create a hash map to store the mapping between original nodes and their copies
    let map = new Map();
    let current = head;
    // First pass: create a copy of each node and store it in the hash map
    while (current) {
        map.set(current, { val: current.val, next: null, random: null });
        current = current.next;
    }
    current = head;
    // Second pass: set the next and random pointers of each copied node
    while (current) {
        // If current node's next is not null, set the next pointer of its copy
        if (current.next) map.get(current).next = map.get(current.next);
        // If current node's random is not null, set the random pointer of its copy
        if (current.random) map.get(current).random = map.get(current.random);
        current = current.next;
    }
    // Return the head of the copied linked list
    return head ? map.get(head) : null;
}

function wordBreak(s, wordDict) {
    // Create a set for faster lookup of words in the dictionary
    let wordSet = new Set(wordDict);
    // Initialize a dynamic programming array to store whether each substring can be segmented
    let dp = new Array(s.length + 1).fill(false);
    // The empty string can always be segmented
    dp[0] = true;
    // Iterate over each character in the string
    for (let i = 1; i <= s.length; i++) {
        // Check all substrings ending at the current character
        for (let j = 0; j < i; j++) {
            // If the substring from j to i is in the dictionary and the substring from 0 to j can be segmented
            if (wordSet.has(s.substring(j, i)) && dp[j]) {
                // Then the substring from 0 to i can be segmented
                dp[i] = true;
                // No need to continue checking other substrings
                break;
            }
        }
    }
    // Return whether the entire string can be segmented
    return dp[s.length];
}

function wordBreak(s, wordDict) {
    // Create a set for O(1) lookup of words in the dictionary
    let wordSet = new Set(wordDict);
    // Initialize a memoization table to store the results of subproblems
    let memo = new Map();
    function backtrack(start) {
        // If the start index is equal to the length of the string, return a list containing an empty string
        if (start === s.length) return [[]];
        // If the subproblem has already been solved, return the stored result
        if (memo.has(start)) return memo.get(start);
        // Initialize a list to store the results of the subproblem
        let result = [];
        // Iterate over the string from the start index to the end
        for (let end = start + 1; end <= s.length; end++) {
            // Get the substring from the start index to the current end index
            let word = s.substring(start, end);
            // If the word is in the dictionary, recursively call the backtrack function
            if (wordSet.has(word)) {
                // Get the results of the subproblem
                let nextWords = backtrack(end);
                // For each result, add the current word to the beginning of the result
                for (let nextWord of nextWords) {
                    // If the nextWord is empty, add the word to the result
                    if (nextWord.length === 0) result.push([word]);
                    // Otherwise, add the word to the beginning of the nextWord
                    else result.push([word].concat(nextWord));
                }
            }
        }
        // Store the result of the subproblem in the memoization table
        memo.set(start, result);
        // Return the result of the subproblem
        return result;
    }
    // Call the backtrack function with a start index of 0
    let result = backtrack(0);
    // For each result, join the words with a space and return the list of sentences
    return result.map(sentence => sentence.join(' '));
}

function hasCycle(head) {
    // Initialize two pointers, slow and fast, to the head of the linked list
    let slow = head;
    let fast = head;
    // Loop through the linked list, moving the slow pointer one step at a time and the fast pointer two steps at a time
    while (fast !== null && fast.next !== null) {
        // Move the slow pointer one step
        slow = slow.next;
        // Move the fast pointer two steps
        fast = fast.next.next;
        // If the slow and fast pointers meet, there is a cycle in the linked list
        if (slow === fast) return true;
    }
    // If the loop ends without the slow and fast pointers meeting, there is no cycle in the linked list
    return false;
}

function detectCycle(head) {
    // if the list is empty, return null
    if (!head || !head.next) return null;

    // initialize two pointers, slow and fast
    let slow = head;
    let fast = head;

    // move the fast pointer twice as fast as the slow pointer
    while (fast && fast.next) {
        // move the slow pointer one step at a time
        slow = slow.next;
        // move the fast pointer two steps at a time
        fast = fast.next.next;

        // if the fast pointer catches up to the slow pointer, there is a cycle
        if (slow === fast) {
            // reset the slow pointer to the head of the list
            slow = head;
            // move both pointers one step at a time
            while (slow !== fast) {
                // move both pointers one step at a time
                slow = slow.next;
                fast = fast.next;
            }
            // return the node where the cycle begins
            return slow;
        }
    }

    // if the fast pointer reaches the end of the list, there is no cycle
    return null;
}

function reorderList(head) {
