function preorderTraversal(root) {
    // Initialize result array and stack with root node
    var result = [], stack = [root];
    // Continue traversal until stack is empty
    while (stack.length) {
        // Pop top node from stack and add its value to result
        var node = stack.pop();
        if (node) {
            // Add node value to result
            result.push(node.val);
            // Push right and left child nodes to stack for next iteration
            stack.push(node.right);
            stack.push(node.left);
        }
    }
    return result;
}

function postorderTraversal(root) {
    // Initialize an empty array to store the result and a stack with the root node
    var result = [], stack = [root];
    // Continue the process until the stack is empty
    while (stack.length > 0) {
        // Pop the top node from the stack
        var node = stack.pop();
        // If the node is not null, push its value to the result array
        if (node !== null) {
            // Push the node's value to the result array
            result.push(node.val);
            // Push the node's left child to the stack
            stack.push(node.left);
            // Push the node's right child to the stack
            stack.push(node.right);
        }
    }
    // Return the result array in reverse order
    return result.reverse();
}

function LRUCache(capacity) {
    // Create a hash map to store the keys and their corresponding nodes in the linked list
    let cache = new Map();
    // Create a doubly linked list with a head and tail
    let head = { next: null, prev: null };
    let tail = { next: null, prev: null };
    head.next = tail;
    tail.prev = head;
    let size = 0;

    function remove(node) {
        // Remove a node from the linked list
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    function add(node) {
        // Add a node to the end of the linked list
        node.prev = tail.prev;
        node.next = tail;
        tail.prev.next = node;
        tail.prev = node;
    }

    return function(operation, key, value) {
        // If the operation is 'get', retrieve the value from the cache
        if (operation === 'get') {
            // Check if the key exists in the cache
            if (cache.has(key)) {
                // Get the node from the cache
                let node = cache.get(key);
                // Remove the node from its current position in the linked list
                remove(node);
                // Add the node to the end of the linked list
                add(node);
                // Return the value of the node
                return node.value;
            } else {
                // If the key does not exist, return -1
                return -1;
            }
        }
        // If the operation is 'put', add or update the value in the cache
        else if (operation === 'put') {
            // Check if the key already exists in the cache
            if (cache.has(key)) {
                // Get the node from the cache
                let node = cache.get(key);
                // Update the value of the node
                node.value = value;
                // Remove the node from its current position in the linked list
                remove(node);
                // Add the node to the end of the linked list
                add(node);
            } else {
                // If the key does not exist, create a new node
                let node = { key: key, value: value };
                // Add the node to the cache
                cache.set(key, node);
                // Add the node to the end of the linked list
                add(node);
                // Increment the size of the cache
                size++;
                // If the cache is full, remove the least recently used node
                if (size > capacity) {
                    // Get the least recently used node (the node at the head of the linked list)
                    let lruNode = head.next;
                    // Remove the node from the cache
                    cache.delete(lruNode.key);
                    // Remove the node from the linked list
                    remove(lruNode);
                    // Decrement the size of the cache
                    size--;
                }
            }
        }
    }
}

function insertionSortList(head) {
    // create a dummy node to simplify the insertion process
    let dummy = { next: head };
    let current = head;
    while (current && current.next) {
        // if the next node's value is smaller than the current node's value, we need to insert it into the sorted list
        if (current.next.val < current.val) {
            // find the position to insert the next node
            let pre = dummy;
            while (pre.next.val < current.next.val) {
                pre = pre.next;
            }
            // insert the next node into the sorted list
            let temp = current.next;
            current.next = temp.next;
            temp.next = pre.next;
            pre.next = temp;
        } else {
            // if the next node's value is not smaller than the current node's value, we can move to the next node
            current = current.next;
        }
    }
    // the sorted list's head is the next node of the dummy node
    return dummy.next;
}

function sortList(head) {
    // Base case: if the list has 0 or 1 nodes, it's already sorted
    if (!head || !head.next) return head;
    // Split the list into two halves
    let mid = getMiddle(head);
    let midNext = mid.next;
    mid.next = null;
    // Recursively sort the two halves
    let left = sortList(head);
    let right = sortList(midNext);
    // Merge the two sorted halves
    return merge(left, right);
}

function getMiddle(head) {
    // Use two pointers to find the middle of the list
    let slow = head;
    let fast = head;
    while (fast.next && fast.next.next) {
        slow = slow.next;
        fast = fast.next.next;
    }
    return slow;
}

function merge(l1, l2) {
    // Create a dummy node to simplify the merge process
    let dummy = new ListNode(0);
    let current = dummy;
    // Merge the two sorted lists
    while (l1 && l2) {
        // Compare the values of the two nodes and add the smaller one to the result
        if (l1.val < l2.val) {
            current.next = l1;
            l1 = l1.next;
        } else {
            current.next = l2;
            l2 = l2.next;
        }
        current = current.next;
    }
    // Add any remaining nodes to the result
    current.next = l1 || l2;
    return dummy.next;
}

function maxPoints(points) {
    // Calculate the slope of the line passing through two points
    function calculateSlope(point1, point2) {
        let xDiff = point2[0] - point1[0];
        let yDiff = point2[1] - point1[1];
        // If the x-coordinates are the same, the slope is infinity
        if (xDiff === 0) return Infinity;
        // Calculate the slope as a string to avoid floating point precision issues
        return (yDiff / xDiff).toString();
    }

    let maxPoints = 0;
    // Iterate over each point in the array
    for (let i = 0; i < points.length; i++) {
        // Initialize a hash map to store the slopes of lines passing through the current point
        let slopeMap = new Map();
        let samePoint = 1; // Count the current point itself
        // Iterate over the remaining points in the array
        for (let j = i + 1; j < points.length; j++) {
            // If the two points are the same, increment the samePoint count
            if (points[i][0] === points[j][0] && points[i][1] === points[j][1]) {
                samePoint++;
            } else {
                // Calculate the slope of the line passing through the two points
                let slope = calculateSlope(points[i], points[j]);
                // Increment the count of points with the same slope in the hash map
                slopeMap.set(slope, (slopeMap.get(slope) || 0) + 1);
            }
        }
        // Update the maximum number of points that lie on the same straight line
        maxPoints = Math.max(maxPoints, Math.max(...slopeMap.values(), 0) + samePoint);
    }
    return maxPoints;
}

function evalRPN(tokens) {
    var stack = []; // stack to store the intermediate results
    for (var i = 0; i < tokens.length; i++) {
        // check if the token is an operator
        if (tokens[i] === "+" || tokens[i] === "-" || tokens[i] === "*" || tokens[i] === "/") {
            // pop two numbers from the stack, perform the operation, and push the result back
            var num2 = stack.pop();
            var num1 = stack.pop();
            if (tokens[i] === "+") stack.push(num1 + num2);
            else if (tokens[i] === "-") stack.push(num1 - num2);
            else if (tokens[i] === "*") stack.push(num1 * num2);
            else stack.push(parseInt(num1 / num2)); // use parseInt to get integer division
        } else {
            // if the token is a number, push it to the stack
            stack.push(parseInt(tokens[i]));
        }
    }
    // the final result is the only element left in the stack
    return stack[0];
}

