function maxProduct(nums) {
    // Initialize variables to store maximum and minimum product ending at current position
    let maxSoFar = nums[0];
    let minSoFar = nums[0];
    // Initialize variable to store overall maximum product
    let result = nums[0];
    // Iterate over the array starting from the second element
    for (let i = 1; i < nums.length; i++) {
        // If current element is negative, swap maxSoFar and minSoFar
        if (nums[i] < 0) {
            // Swap maxSoFar and minSoFar because multiplying by a negative number swaps their order
            let temp = maxSoFar;
            maxSoFar = minSoFar;
            minSoFar = temp;
        }
        // Update maxSoFar and minSoFar
        maxSoFar = Math.max(nums[i], maxSoFar * nums[i]);
        minSoFar = Math.min(nums[i], minSoFar * nums[i]);
        // Update result
        result = Math.max(result, maxSoFar);
    }
    return result;
}

function findMin(nums) {
    // Initialize two pointers for binary search
    let left = 0;
    let right = nums.length - 1;

    // Continue searching while the two pointers haven't converged
    while (left < right) {
        // Calculate the middle index
        let mid = Math.floor((left + right) / 2);

        // If the middle element is greater than the rightmost element, the minimum must be in the right half
        if (nums[mid] > nums[right]) {
            // Move the left pointer to the right of the middle
            left = mid + 1;
        } 
        // If the middle element is less than or equal to the rightmost element, the minimum must be in the left half
        else {
            // Move the right pointer to the left of the middle
            right = mid;
        }
    }

    // At this point, left and right pointers have converged to the index of the minimum element
    return nums[left];
}

function findMin(nums) {
    let left = 0, right = nums.length - 1;
    while (left < right) { 
        // If the middle element is greater than the rightmost element, the minimum must be in the right half
        let mid = Math.floor((left + right) / 2);
        if (nums[mid] > nums[right]) {
            left = mid + 1;
        } 
        // If the middle element is less than the rightmost element, the minimum must be in the left half
        else if (nums[mid] < nums[right]) {
            right = mid;
        } 
        // If the middle element is equal to the rightmost element, we can't be sure which half the minimum is in, so we remove the rightmost element
        else {
            right--;
        }
    }
    return nums[left];
}

function MinStack() {
    this.stack = [];
    this.minStack = [];
}

MinStack.prototype.push = function(val) {
    this.stack.push(val);
    if (this.minStack.length === 0 || val <= this.minStack[this.minStack.length - 1]) {
        this.minStack.push(val);
    }
};

MinStack.prototype.pop = function() {
    const poppedVal = this.stack.pop();
    if (poppedVal === this.minStack[this.minStack.length - 1]) {
        this.minStack.pop();
    }
    return poppedVal;
};

MinStack.prototype.top = function() {
    return this.stack[this.stack.length - 1];
};

MinStack.prototype.getMin = function() {
    return this.minStack[this.minStack.length - 1];
};

function getIntersectionNode(headA, headB) {
    // calculate the length of the first linked list
    let lengthA = 0;
    let tempA = headA;
    while (tempA !== null) {
        lengthA++;
        tempA = tempA.next;
    }

    // calculate the length of the second linked list
    let lengthB = 0;
    let tempB = headB;
    while (tempB !== null) {
        lengthB++;
        tempB = tempB.next;
    }

    // move the longer list forward by the difference in lengths
    let diff = Math.abs(lengthA - lengthB);
    if (lengthA > lengthB) {
        // move the first list forward
        for (let i = 0; i < diff; i++) {
            headA = headA.next;
        }
    } else {
        // move the second list forward
        for (let i = 0; i < diff; i++) {
            headB = headB.next;
        }
    }

    // move both lists forward and check for intersection
    while (headA !== null && headB !== null) {
        // if the current nodes are the same, return the intersection node
        if (headA === headB) {
            return headA;
        }
        headA = headA.next;
        headB = headB.next;
    }

    // if no intersection is found, return null
    return null;
}

function maximumGap(nums) {
    // If the array contains less than two elements, return 0
    if (nums.length < 2) return 0;

    // Find the minimum and maximum values in the array
    let minVal = Math.min(...nums);
    let maxVal = Math.max(...nums);

    // If all numbers are the same, return 0
    if (minVal === maxVal) return 0;

    // Calculate the bucket size
    let bucketSize = Math.max(1, Math.floor((maxVal - minVal) / (nums.length - 1)));

    // Initialize the buckets
    let bucketCount = Math.floor((maxVal - minVal) / bucketSize) + 1;
    let buckets = new Array(bucketCount).fill(0).map(() => ({ min: Infinity, max: -Infinity }));

    // Distribute the numbers into the buckets
    for (let num of nums) {
        // Find the bucket index for the current number
        let index = Math.floor((num - minVal) / bucketSize);
        // Update the minimum and maximum values of the bucket
        buckets[index].min = Math.min(buckets[index].min, num);
        buckets[index].max = Math.max(buckets[index].max, num);
    }

    // Initialize the maximum gap
    let maxGap = 0;

    // Find the maximum gap between two successive non-empty buckets
    let prevMax = buckets[0].max;
    for (let i = 1; i < bucketCount; i++) {
        // If the current bucket is not empty
        if (buckets[i].min !== Infinity) {
            // Update the maximum gap
            maxGap = Math.max(maxGap, buckets[i].min - prevMax);
            // Update the previous maximum value
            prevMax = buckets[i].max;
        }
    }

    return maxGap;
}

function compareVersion(version1, version2) {
    // Split version strings into revision arrays
    var revisions1 = version1.split('.').map(Number);
    var revisions2 = version2.split('.').map(Number);

    // Find the maximum number of revisions
    var maxRevisions = Math.max(revisions1.length, revisions2.length);

    // Compare revisions in left-to-right order
    for (var i = 0; i < maxRevisions; i++) {
        // If a revision is missing, treat it as 0
        var revision1 = i < revisions1.length ? revisions1[i] : 0;
        var revision2 = i < revisions2.length ? revisions2[i] : 0;

        // If revisions are not equal, return the comparison result
        if (revision1 !== revision2) {
            // This algorithm is already optimal, with a time complexity of O(n) where n is the maximum number of revisions
            return revision1 < revision2 ? -1 : 1;
        }
    }

    // If all revisions are equal, return 0
    return 0;
}

function twoSum(numbers, target) {
  // Initialize two pointers, one at the start and one at the end of the array
  let left = 0;
  let right = numbers.length - 1;
  // Continue the loop until the two pointers meet
  while (left < right) {
    // Calculate the sum of the values at the two pointers
    let sum = numbers[left] + numbers[right];
    // If the sum is equal to the target, return the indices
    if (sum === target) return [left + 1, right + 1];
    // If the sum is less than the target, move the left pointer to the right
    else if (sum < target) left++;
    // If the sum is greater than the target, move the right pointer to the left
    else right--;
  }
}

function trailingZeroes(n) {
    // calculate the number of trailing zeroes by counting the factors of 5 in n!
    let count = 0;
    let i = 5;
    while (Math.floor(n / i) >= 1) {
        // add the number of factors of 5 to the count
        count += Math.floor(n / i);
        i *= 5;
    }
    return count;
}

