function BSTIterator(root) {
    this.stack = [];
    this.pushLeft(root); // push all left nodes to the stack
}

BSTIterator.prototype.next = function() {
    let topmostNode = this.stack.pop(); // get the topmost node
    if (topmostNode.right) this.pushLeft(topmostNode.right); // push all left nodes of the right child to the stack
    return topmostNode.val; // return the value of the topmost node
}

BSTIterator.prototype.hasNext = function() {
    return this.stack.length > 0;
}

BSTIterator.prototype.pushLeft = function(node) {
    while (node) { // keep pushing nodes to the stack until we reach the leftmost node
        this.stack.push(node);
        node = node.left; // move to the left child
    }
}

function calculateMinimumHP(dungeon) {
    // Get the number of rows and columns in the dungeon
    var rows = dungeon.length;
    var cols = dungeon[0].length;

    // Create a 2D array to store the minimum health required to reach each cell
    var dp = new Array(rows);
    for (var i = 0; i < rows; i++) {
        dp[i] = new Array(cols);
    }

    // Initialize the minimum health required to reach the bottom-right cell
    dp[rows - 1][cols - 1] = Math.max(1, 1 - dungeon[rows - 1][cols - 1]);

    // Calculate the minimum health required to reach each cell in the last row
    for (var j = cols - 2; j >= 0; j--) {
        // The minimum health required to reach a cell is the maximum of 1 and the minimum health required to reach the next cell minus the health change of the current cell
        dp[rows - 1][j] = Math.max(1, dp[rows - 1][j + 1] - dungeon[rows - 1][j]);
    }

    // Calculate the minimum health required to reach each cell in the last column
    for (var i = rows - 2; i >= 0; i--) {
        // The minimum health required to reach a cell is the maximum of 1 and the minimum health required to reach the cell below minus the health change of the current cell
        dp[i][cols - 1] = Math.max(1, dp[i + 1][cols - 1] - dungeon[i][cols - 1]);
    }

    // Calculate the minimum health required to reach each cell in the rest of the dungeon
    for (var i = rows - 2; i >= 0; i--) {
        for (var j = cols - 2; j >= 0; j--) {
            // The minimum health required to reach a cell is the maximum of 1 and the minimum of the minimum health required to reach the cell to the right and the cell below minus the health change of the current cell
            dp[i][j] = Math.max(1, Math.min(dp[i + 1][j], dp[i][j + 1]) - dungeon[i][j]);
        }
    }

    // The minimum initial health required is the minimum health required to reach the top-left cell
    return dp[0][0];
}

function largestNumber(nums) {
    // Convert each number to a string to easily concatenate and compare them
    let strNums = nums.map(num => num.toString());

    // Sort the string numbers in descending order based on a custom comparison function
    strNums.sort((a, b) => (b + a) - (a + b));

    // Join the sorted string numbers into a single string
    let result = strNums.join('');

    // If the result starts with '0', return '0' because the largest number would be 0
    return result[0] === '0' ? '0' : result;
}

function findRepeatedDnaSequences(s) {
    // Create a hash map to store the frequency of each 10-letter-long sequence
    var sequenceCount = {};
    var result = [];
    for (var i = 0; i <= s.length - 10; i++) {
        // Extract the 10-letter-long sequence
        var sequence = s.substring(i, i + 10);
        // Increment the count of the sequence in the hash map
        sequenceCount[sequence] = (sequenceCount[sequence] || 0) + 1;
        // If the count is 2, it means we've found a repeated sequence
        if (sequenceCount[sequence] === 2) {
            // Add the repeated sequence to the result
            result.push(sequence);
        }
    }
    return result;
}

function maxProfit(k, prices) {
  // if k is greater than or equal to prices length divided by 2, we can simply consider every peak and valley
  if (k >= prices.length / 2) {
    let maxProfit = 0;
    for (let i = 1; i < prices.length; i++) {
      if (prices[i] > prices[i - 1]) {
        maxProfit += prices[i] - prices[i - 1];
      }
    }
    return maxProfit;
  }

  const n = prices.length;
  if (n === 0) return 0;

  // buy[j] = best profit after buying into the j-th transaction (still holding)
  // sell[j] = best profit after completing the j-th transaction (sold)
  const buy = new Array(k + 1).fill(-Infinity);
  const sell = new Array(k + 1).fill(0);

  for (let i = 0; i < n; i++) {
    for (let j = 1; j <= k; j++) {
      buy[j] = Math.max(buy[j], sell[j - 1] - prices[i]);
      sell[j] = Math.max(sell[j], buy[j] + prices[i]);
    }
  }

  return sell[k];
}

function rotateArray(nums, k) {
    // calculate the effective number of steps to rotate, considering cases where k is greater than the length of the array
    k = k % nums.length;
    // use the splice method to rotate the array to the right by k steps
    nums.splice(0, nums.length, ...nums.slice(-k), ...nums.slice(0, -k));
    return nums;
}

function reverseBits(n) {
    let result = 0; 
    // shift the bits of n to the right and append the least significant bit to result
    for (let i = 0; i < 32; i++) {
        result = (result << 1) | (n & 1); 
        // right shift n by 1 to move to the next bit
        n >>>= 1; 
    }
    return result >>> 0; 
}

function hammingWeight(n) {
    let count = 0; 
    // use bit manipulation to check each bit in the binary representation
    while (n) { 
        // use bitwise AND operation to check if the least significant bit is 1
        count += n & 1; 
        // use bitwise right shift operation to move to the next bit
        n >>>= 1; 
    }
    return count;
}

function majorityElement(nums) {
  // Initialize the count and candidate variables
  let count = 0;
  let candidate = null;
  // Iterate over the array, updating the count and candidate as we go
  for (let i = 0; i < nums.length; i++) {
    // If the count is zero, set the current element as the candidate
    if (count === 0) candidate = nums[i];
    // Increment the count if the current element matches the candidate, otherwise decrement it
    count += (nums[i] === candidate) ? 1 : -1;
  }
  // The candidate is the majority element
  return candidate;
}

function findPeakElement(nums) {
  // Initialize two pointers, one at the start and one at the end of the array
  let left = 0;
  let right = nums.length - 1;
  // Continue the loop until the two pointers meet
  while (left < right) {
    // Calculate the middle index
    let mid = Math.floor((left + right) / 2);
    // If the middle element is smaller than the next one, move the left pointer to the right
    if (nums[mid] < nums[mid + 1]) {
      left = mid + 1;
    } 
    // If the middle element is greater than or equal to the next one, move the right pointer to the left
    else {
      right = mid;
    }
  }
  // The peak element is at the index where the two pointers meet
  return left;
}

function convertToTitle(columnNumber) {
    let result = ''; // initialize result string
    while (columnNumber > 0) { 
        // calculate remainder and update columnNumber for next iteration
        columnNumber--; 
        let remainder = columnNumber % 26; 
        // convert remainder to corresponding character and prepend to result
        result = String.fromCharCode(65 + remainder) + result; 
        columnNumber = Math.floor(columnNumber / 26); 
    }
    return result;
}

function titleToNumber(columnTitle) {
    let result = 0; 
    // calculate the column number by treating the title as a base-26 number
    for (let i = 0; i < columnTitle.length; i++) {
        // convert character to its corresponding number (A = 1, B = 2, etc.)
        let digit = columnTitle.charCodeAt(i) - 'A'.charCodeAt(0) + 1;
        // update the result by shifting the current digits to the left and adding the new digit
        result = result * 26 + digit;
    }
    return result;
}

function fractionToDecimal(numerator, denominator) {
    // Check for division by zero
    if (denominator === 0) return "";

    let result = "";
    // Check for negative sign
    if ((numerator < 0) ^ (denominator < 0)) result += "-";

    // Convert to positive
    numerator = Math.abs(numerator);
    denominator = Math.abs(denominator);

    // Calculate integer part
    result += Math.floor(numerator / denominator);

    // Calculate fractional part
    let remainder = numerator % denominator;
    if (remainder === 0) return result;

    result += ".";
    let map = {};
    let fractionalPart = "";
    while (remainder !== 0) {
        // Check for repeating remainder
        if (map[remainder] !== undefined) {
            // Insert parentheses around repeating part
            fractionalPart = fractionalPart.substring(0, map[remainder]) + "(" + fractionalPart.substring(map[remainder]) + ")";
            break;
        }
        // Store remainder and its index
        map[remainder] = fractionalPart.length;
        // Calculate next digit
        remainder *= 10;
        fractionalPart += Math.floor(remainder / denominator);
        remainder %= denominator;
    }
    result += fractionalPart;
    return result;
}

