function rangeBitwiseAnd(left, right) {
    // shift both numbers to the right until they are equal, effectively removing the last differing bit
    let shift = 0;
    while (left < right) {
        // shift both numbers to the right
        left >>= 1;
        right >>= 1;
        // increment the shift counter
        shift++;
    }
    // shift the result to the left to restore the original position of the common prefix
    return left << shift;
}

function rightSideView(root) {
    // Perform BFS level by level and store the last node's value at each level
    let result = [];
    if (!root) return result;
    let queue = [root];
    while (queue.length > 0) {
        // Store the size of the current level
        let levelSize = queue.length;
        // Process all nodes at the current level
        for (let i = 0; i < levelSize; i++) {
            // Remove the next node from the queue
            let currentNode = queue.shift();
            // If this is the last node at the current level, add its value to the result
            if (i === levelSize - 1) result.push(currentNode.val);
            // Add the left and right children of the current node to the queue if they exist
            if (currentNode.left) queue.push(currentNode.left);
            if (currentNode.right) queue.push(currentNode.right);
        }
    }
    return result;
}

function isHappy(n) {
    // Create a hash set to store seen numbers to detect cycles
    var seen = new Set();
    while (n !== 1 && !seen.has(n)) {
        // Add current number to the set
        seen.add(n);
        // Calculate the sum of squares of digits
        n = Array.from(String(n), Number).reduce((sum, digit) => sum + digit * digit, 0);
    }
    // Return true if n is 1, false otherwise
    return n === 1;
}

function numIslands(grid) {
  // Check if grid is empty
  if (!grid || grid.length === 0) return 0;

  let count = 0;
  for (let i = 0; i < grid.length; i++) {
    for (let j = 0; j < grid[0].length; j++) {
      // If land is found, increment island count and mark all connected lands as visited
      if (grid[i][j] === '1') {
        count++;
        dfs(grid, i, j); // Mark all connected lands as visited
      }
    }
  }
  return count;
}

function dfs(grid, i, j) {
  // Check if current position is out of bounds or is water
  if (i < 0 || j < 0 || i >= grid.length || j >= grid[0].length || grid[i][j] !== '1') return;

  // Mark current land as visited
  grid[i][j] = '0';

  // Recursively visit all adjacent lands
  dfs(grid, i - 1, j); // Up
  dfs(grid, i + 1, j); // Down
  dfs(grid, i, j - 1); // Left
  dfs(grid, i, j + 1); // Right
}

function rob(nums) {
  // if the array is empty, return 0
  if (nums.length === 0) return 0;
  // if the array has only one element, return that element
  if (nums.length === 1) return nums[0];
  // initialize an array to store the maximum amount of money that can be robbed up to each house
  let maxAmount = new Array(nums.length);
  // the maximum amount of money that can be robbed up to the first house is the money in the first house
  maxAmount[0] = nums[0];
  // the maximum amount of money that can be robbed up to the second house is the maximum of the money in the first house and the money in the second house
  maxAmount[1] = Math.max(nums[0], nums[1]);
  // for each house from the third house onwards
  for (let i = 2; i < nums.length; i++) {
    // the maximum amount of money that can be robbed up to this house is the maximum of the maximum amount of money that can be robbed up to the previous house and the sum of the money in this house and the maximum amount of money that can be robbed up to the house two houses ago
    maxAmount[i] = Math.max(maxAmount[i-1], maxAmount[i-2] + nums[i]);
  }
  // the maximum amount of money that can be robbed is the maximum amount of money that can be robbed up to the last house
  return maxAmount[nums.length - 1];
}

function removeElements(head, val) {
  // if head is null, return null as there are no elements to remove
  if (head === null) return null;
  // recursively remove elements from the rest of the list
  head.next = removeElements(head.next, val);
  // if the current node's value matches the target value, return the next node
  return head.val === val ? head.next : head;
}

function reverseList(head) {
    // Initialize previous node as null
    let previous = null;
    // Initialize current node as head
    let current = head;
    // Traverse the list until current node is not null
    while (current !== null) {
        // Store the next node in a temporary variable
        let nextNode = current.next;
        // Reverse the link of current node
        current.next = previous;
        // Move previous and current one step forward
        previous = current;
        current = nextNode;
    }
    // At the end of the loop, previous will be the new head
    return previous;
}

function canFinish(numCourses, prerequisites) {
  // Create an adjacency list to represent the graph
  const graph = Array.from({ length: numCourses }, () => []);
  const visited = Array.from({ length: numCourses }, () => 0);

  // Build the graph
  for (const [course, prerequisite] of prerequisites) {
    // Add an edge from the prerequisite to the course
    graph[prerequisite].push(course);
  }

  // Define a helper function to perform DFS
  function dfs(course) {
    // If the course is marked as visiting, it means a cycle is detected
    if (visited[course] === 1) return false;
    // If the course is marked as visited, it means it's already been checked
    if (visited[course] === 2) return true;

    // Mark the course as visiting
    visited[course] = 1;
    // Perform DFS on all neighboring courses
    for (const neighbor of graph[course]) {
      // If any neighboring course has a cycle, return false
      if (!dfs(neighbor)) return false;
    }
    // Mark the course as visited
    visited[course] = 2;
    return true;
  }

  // Perform DFS on all courses
  for (let i = 0; i < numCourses; i++) {
    // If any course has a cycle, return false
    if (!dfs(i)) return false;
  }
  return true;
}

function countPrimes(n) {
  // Create a boolean array, prime, of size n and initialize all entries as true
  var prime = new Array(n).fill(true);
  // 0 and 1 are not prime numbers
  prime[0] = prime[1] = false;
  // Iterate from 2 to sqrt(n)
  for (var p = 2; p * p < n; p++) {
    // If p is a prime, mark as composite all the multiples of p
    if (prime[p]) {
      // Start from p*p because all the multiples of p less than p*p have already been marked
      for (var i = p * p; i < n; i += p) {
        // Mark i as composite
        prime[i] = false;
      }
    }
  }
  // Count all prime numbers in the boolean array
  var count = 0;
  for (var i = 0; i < n; i++) {
    // If i is a prime number, increment the count
    if (prime[i]) {
      count++;
    }
  }
  return count;
}

function isIsomorphic(s, t) {
  // Create two hash maps to store character mappings from s to t and t to s
  var sToTMap = {};
  var tToSMap = {};

  // Iterate over the characters in the strings
  for (var i = 0; i < s.length; i++) {
    // If the character in s is not in the sToTMap, add it and its corresponding character in t
    if (!(s[i] in sToTMap)) {
      // Check if the character in t is already in the tToSMap
      if (t[i] in tToSMap) {
        return false;
      }
      sToTMap[s[i]] = t[i];
      tToSMap[t[i]] = s[i];
    } 
    // If the character in s is already in the sToTMap, check if its corresponding character in t matches
    else if (sToTMap[s[i]] !== t[i]) {
      return false;
    }
  }

  // If we have iterated over all characters and haven't returned false, the strings are isomorphic
  return true;
}

function Trie() {
    this.children = {};
    this.isEndOfWord = false;
}

Trie.prototype.insert = function(word) {
    let node = this;
    for (let i = 0; i < word.length; i++) {
        if (!node.children[word[i]]) node.children[word[i]] = new Trie();
        node = node.children[word[i]];
    }
    node.isEndOfWord = true;
};

Trie.prototype.search = function(word) {
    let node = this;
    for (let i = 0; i < word.length; i++) {
        if (!node.children[word[i]]) return false;
        node = node.children[word[i]];
    }
    return node.isEndOfWord;
};

Trie.prototype.startsWith = function(prefix) {
    let node = this;
    for (let i = 0; i < prefix.length; i++) {
        if (!node.children[prefix[i]]) return false;
        node = node.children[prefix[i]];
    }
    return true;
};

function shortestPalindrome(s) {
    // Reverse the string to compare it with the original string
    var reversed = s.split('').reverse().join('');
    // Create a new string by concatenating the original string and the reversed string
    var combined = s + '#' + reversed;
    // Initialize an array to store the longest prefix that is also a suffix for each substring
    var prefixSuffixLengths = new Array(combined.length).fill(0);
    // Initialize variables to keep track of the current prefix and suffix
    var prefixLength = 0;
    // Iterate over the combined string to fill the prefixSuffixLengths array
    for (var i = 1; i < combined.length; i++) {
        // If the current character does not match the character at the prefix index, update the prefix index
        while (prefixLength > 0 && combined[i] !== combined[prefixLength]) {
            // Update the prefix index to the value at the previous prefix index - 1
            prefixLength = prefixSuffixLengths[prefixLength - 1];
        }
        // If the current character matches the character at the prefix index, increment the prefix index
        if (combined[i] === combined[prefixLength]) {
            prefixLength++;
        }
        // Update the prefixSuffixLengths array
        prefixSuffixLengths[i] = prefixLength;
    }
    // Find the length of the longest prefix that is also a suffix
    var maxLength = prefixSuffixLengths[combined.length - 1];
    // Return the shortest palindrome by adding the reversed string to the original string
    return reversed.substring(0, s.length - maxLength) + s;
}

function findOrder(numCourses, prerequisites) {
    // Create a graph and initialize the in-degree array
    let graph = Array.from({length: numCourses}, () => []);
    let inDegree = new Array(numCourses).fill(0);

    // Populate the graph and update the in-degree array
    for (let [course, prerequisite] of prerequisites) {
        // Add an edge from the prerequisite to the course
        graph[prerequisite].push(course);
        // Increment the in-degree of the course
        inDegree[course]++;
    }

    // Initialize a queue with courses that have no prerequisites
    let queue = [];
    for (let i = 0; i < numCourses; i++) {
        if (inDegree[i] === 0) {
            queue.push(i);
        }
    }

    // Initialize the result array
    let result = [];

    // Perform topological sorting using BFS
    while (queue.length > 0) {
        // Dequeue a course with no prerequisites
        let course = queue.shift();
        // Add the course to the result array
        result.push(course);
        // For each neighbor of the course
        for (let neighbor of graph[course]) {
            // Decrement the in-degree of the neighbor
            inDegree[neighbor]--;
            // If the neighbor has no more prerequisites, add it to the queue
            if (inDegree[neighbor] === 0) {
                queue.push(neighbor);
            }
        }
    }

    // If there are still courses with prerequisites, it's impossible to finish all courses
    if (result.length !== numCourses) {
        return [];
    }

    return result;
}

function rob(nums) {
    // this problem is already optimal with dynamic programming solution
    if (nums.length === 1) return nums[0];
    if (nums.length === 2) return Math.max(nums[0], nums[1]);

    // calculate max amount for nums[0] to nums[nums.length - 2]
    let maxAmount1 = new Array(nums.length).fill(0);
    maxAmount1[0] = nums[0];
    maxAmount1[1] = Math.max(nums[0], nums[1]);
    for (let i = 2; i < nums.length - 1; i++) 
        // for each house, max amount is max of (amount of current house + max amount of house 2 steps back) and max amount of previous house
        maxAmount1[i] = Math.max(maxAmount1[i - 1], maxAmount1[i - 2] + nums[i]);

    // calculate max amount for nums[1] to nums[nums.length - 1]
    let maxAmount2 = new Array(nums.length).fill(0);
    maxAmount2[0] = 0;
    maxAmount2[1] = nums[1];
    for (let i = 2; i < nums.length; i++) 
        // for each house, max amount is max of (amount of current house + max amount of house 2 steps back) and max amount of previous house
        maxAmount2[i] = Math.max(maxAmount2[i - 1], maxAmount2[i - 2] + nums[i]);

    return Math.max(maxAmount1[nums.length - 2], maxAmount2[nums.length - 1]);
}

