function partition(nums, left, right) {
  // Lomuto partition: choose the rightmost element as pivot so the returned
  // index is guaranteed to be the pivot's final sorted position.
  let pivot = nums[right];
  let i = left;
  for (let j = left; j < right; j++) {
    if (nums[j] < pivot) {
      [nums[i], nums[j]] = [nums[j], nums[i]];
      i++;
    }
  }
  [nums[i], nums[right]] = [nums[right], nums[i]];
  return i;
}

