        board[row][col] = '#';

        // Explore all possible directions
        for (let [dr, dc] of directions) {
            const nr = row + dr;
            const nc = col + dc;
            if (nr >= 0 && nr < board.length && nc >= 0 && nc < board[0].length && board[nr][nc] in node) {
                // Recursively call the backtrack function for the next cell
                backtrack(nr, nc, node[board[nr][nc]], word + board[nr][nc]);
