function containsNearbyAlmostDuplicate(nums, indexDiff, valueDiff) {
  // Create a bucket for each possible value, with a size of valueDiff + 1 to handle edge cases
  const buckets = new Map();
  for (let i = 0; i < nums.length; i++) {
    // Calculate the bucket index for the current number
    const bucketIndex = Math.floor(nums[i] / (valueDiff + 1));
    // Check if the current bucket or the adjacent buckets contain a number that satisfies the conditions
    if (buckets.has(bucketIndex)) // Check the current bucket
      return true;
    if (buckets.has(bucketIndex - 1) && Math.abs(nums[i] - buckets.get(bucketIndex - 1)) <= valueDiff) // Check the previous bucket
      return true;
    if (buckets.has(bucketIndex + 1) && Math.abs(nums[i] - buckets.get(bucketIndex + 1)) <= valueDiff) // Check the next bucket
      return true;
    // Add the current number to the bucket
    buckets.set(bucketIndex, nums[i]);
    // Remove the number that is out of the window
    if (i >= indexDiff) {
      const oldBucketIndex = Math.floor(nums[i - indexDiff] / (valueDiff + 1));
      buckets.delete(oldBucketIndex);
    }
