                dp[i][j] = Math.min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1;
                maxSize = Math.max(maxSize, dp[i][j]);
            }
        }
    }
    return maxSize * maxSize;
}

function getSkyline(buildings) {
    // Create an array of all critical points
    let criticalPoints = [];
    for (let building of buildings) {
        // Add the left and right points of each building to the critical points array
        criticalPoints.push([building[0], -building[2]]);
        criticalPoints.push([building[1], building[2]]);
    }

    // Sort the critical points by their x-coordinate
    criticalPoints.sort((a, b) => a[0] - b[0] || a[1] - b[1]);

    // Initialize the result array and the current height
    let result = [];
    let currentHeight = 0;
    let heights = [0];

    // Iterate over the critical points
    for (let point of criticalPoints) {
        // If the point is a start point, add its height to the heights array
        if (point[1] < 0) {
            heights.push(-point[1]);
        } 
        // If the point is an end point, remove its height from the heights array
        else {
            let index = heights.indexOf(point[1]);
            heights.splice(index, 1);
        }

        // Update the current height
        let newHeight = Math.max(...heights);
        // If the new height is different from the current height, add a new point to the result array
        if (newHeight !== currentHeight) {
            result.push([point[0], newHeight]);
            currentHeight = newHeight;
        }
    }

    return result;
}

function countNodes(root) {
    let height = 0;
    let node = root;
    while (node) {
        height++;
        node = node.left;
    }
    if (height == 0) return 0;
    if (height == 1) return 1;
    let left = 0, right = Math.pow(2, height - 1) - 1;
    while (left <= right) {
        let mid = Math.floor((left + right) / 2);
        let node = root;
        let path = mid;
        for (let i = height - 2; i >= 0; i--) {
            node = path & (1 << i) ? node.right : node.left;
        }
        if (node) left = mid + 1;
        else right = mid - 1;
    }
    return Math.pow(2, height - 1) - 1 + left;
}

