function productExceptSelf(nums) {
    // calculate prefix product for each element
    var length = nums.length;
    var answer = new Array(length).fill(1);
    var prefixProduct = 1;
    for (var i = 0; i < length; i++) {
        // update answer array with prefix product
        answer[i] *= prefixProduct;
        // update prefix product
        prefixProduct *= nums[i];
    }
    // calculate suffix product for each element
    var suffixProduct = 1;
    for (var i = length - 1; i >= 0; i--) {
        // update answer array with suffix product
        answer[i] *= suffixProduct;
        // update suffix product
        suffixProduct *= nums[i];
    }
    return answer;
}

function maxSlidingWindow(nums, k) {
    // Create a deque to store indices of elements in the current window
    let deque = [];
    let result = [];

    // Iterate over the array
    for (let i = 0; i < nums.length; i++) {
        // Remove elements from the back of the deque that are out of the current window
        while (deque.length > 0 && deque[0] < i - k + 1) deque.shift();

        // Remove elements from the front of the deque that are smaller than the current element
        while (deque.length > 0 && nums[deque[deque.length - 1]] < nums[i]) deque.pop();

        // Add the current element to the deque
        deque.push(i);

        // Add the maximum element in the current window to the result
        if (i >= k - 1) result.push(nums[deque[0]]);
    }

    return result;
}

function searchMatrix(matrix, target) {
    // Start from the top right corner of the matrix
    let row = 0, col = matrix[0].length - 1;
    // Continue the search until we are within the matrix bounds
    while (row < matrix.length && col >= 0) {
        // If the target is found, return true
        if (matrix[row][col] === target) return true;
        // If the target is smaller, move left
        else if (matrix[row][col] > target) col--;
        // If the target is larger, move down
        else row++;
    }
    // If the target is not found after the search, return false
    return false;
}

function diffWaysToCompute(expression) {
    // Create a memoization map to store the results of subproblems
    let memo = new Map();
    function compute(expression) {
        // If the expression is already in the memoization map, return the stored result
        if (memo.has(expression)) return memo.get(expression);

        // If the expression is a number, return a list containing the number
        if (!isNaN(expression)) return [parseInt(expression)];

        // Initialize an empty list to store the results
        let results = [];

        // Iterate over each character in the expression
        for (let i = 0; i < expression.length; i++) {
            // If the character is an operator
            if (expression[i] === '+' || expression[i] === '-' || expression[i] === '*') {
                // Recursively compute the results of the left and right subexpressions
                let leftResults = compute(expression.substring(0, i));
                let rightResults = compute(expression.substring(i + 1));

                // For each result in the left and right subexpressions
                for (let left of leftResults) {
                    for (let right of rightResults) {
                        // Compute the result of the current operator and add it to the results list
                        if (expression[i] === '+') results.push(left + right);
                        else if (expression[i] === '-') results.push(left - right);
                        else if (expression[i] === '*') results.push(left * right);
                    }
                }
            }
        }

        // Store the results in the memoization map and return them
        memo.set(expression, results);
        return results;
    }

    // Call the compute function and return the results
    return compute(expression);
}

function isAnagram(s, t) {
    // If the two strings are not of the same length, they cannot be anagrams
    if (s.length !== t.length) return false;
    // Create a hash table to store the frequency of each character in string s
    let charFrequency = {};
    // Populate the hash table with character frequencies from string s
    for (let char of s) charFrequency[char] = (charFrequency[char] || 0) + 1;
    // Iterate through string t and decrement the corresponding character frequencies in the hash table
    for (let char of t) {
        // If a character in string t is not found in the hash table or its frequency is 0, return false
        if (!charFrequency[char] || charFrequency[char] === 0) return false;
        charFrequency[char]--;
    }
    // If we have iterated through both strings without returning false, they are anagrams
    return true;
}

function binaryTreePaths(root) {
    // Initialize result array to store all root-to-leaf paths
    let result = [];
    // Define a helper function for DFS
    function dfs(node, path) {
        // If the current node is a leaf, add the current path to the result array
        if (!node.left && !node.right) result.push(path);
        // Recursively traverse the left subtree if it exists
        if (node.left) dfs(node.left, path + "->" + node.left.val);
        // Recursively traverse the right subtree if it exists
        if (node.right) dfs(node.right, path + "->" + node.right.val);
    }
    // Start DFS from the root node
    if (root) dfs(root, root.val.toString());
    // Return the result array
    return result;
}

function addDigits(num) {
  // The algorithm solution is already optimal, using mathematical properties to avoid loops
  // We use the property that the digital root of a number is equal to the remainder of the number when divided by 9, unless the number is divisible by 9, in which case the digital root is 9
  if (num === 0) return 0;
  return (num - 1) % 9 + 1;
}

function singleNumber(nums) {
  // Calculate the XOR of all numbers to find the XOR of the two single numbers
  let xorResult = 0;
  for (let num of nums) {
    xorResult ^= num;
  }

  // Find the rightmost set bit in the XOR result
  let rightmostSetBit = xorResult & -xorResult;

  // Divide the numbers into two groups based on the rightmost set bit
  let singleNumber1 = 0, singleNumber2 = 0;
  for (let num of nums) {
    // If the rightmost set bit is set, put the number in the first group
    if (num & rightmostSetBit) {
      singleNumber1 ^= num;
    } 
    // Otherwise, put the number in the second group
    else {
      singleNumber2 ^= num;
    }
  }

  return [singleNumber1, singleNumber2];
}

function isUgly(n) {
  if (n <= 0) return false;
  for (const p of [2, 3, 5]) {
    while (n % p === 0) n /= p;
  }
  return n === 1;
}

function nthUglyNumber(n) {
  // Initialize an array to store the ugly numbers, starting with the first one
  let uglyNumbers = [1];
  // Initialize three pointers to track the next multiples of 2, 3, and 5
  let i2 = 0, i3 = 0, i5 = 0;
  // Loop until we have found the nth ugly number
  while (uglyNumbers.length < n) {
    // Calculate the next possible ugly numbers by multiplying the current ones with 2, 3, and 5
    let next2 = uglyNumbers[i2] * 2, next3 = uglyNumbers[i3] * 3, next5 = uglyNumbers[i5] * 5;
    // Find the smallest of the three next possible ugly numbers
    let nextUgly = Math.min(next2, next3, next5);
    // Add the smallest one to the array of ugly numbers
    uglyNumbers.push(nextUgly);
    // Move the corresponding pointer(s) forward
    if (nextUgly === next2) i2++;
    if (nextUgly === next3) i3++;
    if (nextUgly === next5) i5++;
  }
  // Return the nth ugly number
  return uglyNumbers[n - 1];
}

function findMissingNumber(nums) {
    let n = nums.length; // calculate the length of the array
    let expectedSum = (n * (n + 1)) / 2; // calculate the expected sum of numbers from 0 to n
    let actualSum = 0; // initialize the actual sum
    for (let i = 0; i < n; i++) { // iterate over the array to calculate the actual sum
        actualSum += nums[i]; // add each number to the actual sum
    }
    return expectedSum - actualSum; // return the difference between the expected and actual sums
}

function numberToWords(num) {
    // Define the English words for numbers 0-19
    const ones = ['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten', 'Eleven', 'Twelve', 'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen', 'Seventeen', 'Eighteen', 'Nineteen'];
    // Define the English words for tens
    const tens = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];
    // Define the English words for thousands
    const thousands = ['', 'Thousand', 'Million', 'Billion'];

    // Handle the case where num is 0
    if (num === 0) return 'Zero';

    let result = '';
    let i = 0;
    // Loop through the number in groups of three digits
    while (num > 0) {
        // If the current group of three digits is not zero, add it to the result
        if (num % 1000 !== 0) {
            result = helper(num % 1000, ones, tens) + ' ' + thousands[i] + ' ' + result;
        }
        // Move to the next group of three digits
        num = Math.floor(num / 1000);
        i++;
    }
    // Remove trailing spaces
    return result.trim();

    // Helper function to convert a number less than 1000 to English words
    function helper(num, ones, tens) {
        let result = '';
        // If the number is 100 or more, add the hundreds place to the result
        if (num >= 100) {
            // Add the hundreds place to the result
            result += ones[Math.floor(num / 100)] + ' Hundred ';
            // Remove the hundreds place from the number
            num %= 100;
        }
        // If the number is 20 or more, add the tens place to the result
        if (num >= 20) {
            // Add the tens place to the result
            result += tens[Math.floor(num / 10)] + ' ';
            // Remove the tens place from the number
            num %= 10;
        }
        // If the number is less than 20, add it to the result
        if (num > 0) {
            // Add the number to the result
            result += ones[num];
        }
        // Remove trailing spaces
        return result.trim();
    }
}

function hIndex(citations) {
    // sort the citations array in descending order to prioritize papers with more citations
    citations.sort((a, b) => b - a);
    for (let i = 0; i < citations.length; i++) {
        // calculate the h-index for each paper and return the maximum h-index found
        if (citations[i] < i + 1) return i;
    }
    // if no paper has an h-index less than its index, return the total number of papers
    return citations.length;
}

function hIndex(citations) {
  let left = 0, right = citations.length - 1;
  // perform binary search to find the h-index
  while (left <= right) {
    let mid = Math.floor((left + right) / 2);
    // calculate the h-index for the current mid index
    let h = Math.min(citations[mid], citations.length - mid);
    // if the h-index is equal to the number of papers with at least h citations, return h
    if (h === citations[mid]) return h;
    // if the h-index is less than the number of papers with at least h citations, move to the right half
    else if (h < citations[mid]) left = mid + 1;
    // if the h-index is greater than the number of papers with at least h citations, move to the left half
    else right = mid - 1;
  }
  // if no h-index is found, return the number of papers with at least 0 citations
  return citations.length - left;
}

function firstBadVersion(n, bad) {
  function isBadVersion(version) {
    return version >= bad;
  }
  let left = 1;
  let right = n;
  while (left < right) {
    let mid = Math.floor((left + right) / 2);
    if (isBadVersion(mid)) {
      right = mid;
    } else {
      left = mid + 1;
    }
  }
  return left;
}

function numSquares(n) {
  // Create a dynamic programming array to store the least number of perfect squares for each number up to n
  var dp = new Array(n + 1).fill(Infinity);
  dp[0] = 0; // Base case: 0 can be represented as the sum of 0 perfect squares
  // Iterate over each number up to n
  for (var i = 1; i <= n; i++) {
    // For each number i, iterate over all perfect squares less than or equal to i
    for (var j = 1; j * j <= i; j++) {
      // Update dp[i] with the minimum of its current value and dp[i - j * j] + 1
      dp[i] = Math.min(dp[i], dp[i - j * j] + 1); // Update dp[i] with the least number of perfect squares
    }
  }
  return dp[n]; // Return the least number of perfect squares for n
}

