function removeInvalidParentheses(s) {
    // Check if a string is valid
    function isValid(str) {
        let count = 0;
        for (let i = 0; i < str.length; i++) {
            if (str[i] === '(') count++;
            if (str[i] === ')') count--;
            if (count < 0) return false;
        }
        return count === 0;
    }

    // Perform BFS to find the minimum number of removals
    let level = { [s]: true };
    while (true) {
        let valid = Object.keys(level).filter(isValid);
        if (valid.length > 0) return valid;
        // Generate the next level by removing one parenthesis at a time
        let nextLevel = {};
        for (let str in level) {
            for (let i = 0; i < str.length; i++) {
                if (str[i] === '(' || str[i] === ')') {
                    let nextStr = str.slice(0, i) + str.slice(i + 1);
                    nextLevel[nextStr] = true;
                }
            }
        }
        level = nextLevel;
    }
}

function NumArray(nums) {
    this.prefixSum = [0];
    for (let i = 0; i < nums.length; i++) {
        this.prefixSum.push(this.prefixSum[i] + nums[i]);
