}

NumArray.prototype.sumRange = function(i, j) {
    return this.prefixSum[j + 1] - this.prefixSum[i];
};

function NumMatrix(matrix) {
    this.prefixSum = new Array(matrix.length + 1).fill(0).map(() => new Array(matrix[0].length + 1).fill(0));
    for (let i = 1; i <= matrix.length; i++) {
        for (let j = 1; j <= matrix[0].length; j++) {
            this.prefixSum[i][j] = matrix[i - 1][j - 1] + this.prefixSum[i - 1][j] + this.prefixSum[i][j - 1] - this.prefixSum[i - 1][j - 1];
        }
    }
}

NumMatrix.prototype.sumRegion = function(row1, col1, row2, col2) {
    return this.prefixSum[row2 + 1][col2 + 1] - this.prefixSum[row2 + 1][col1] - this.prefixSum[row1][col2 + 1] + this.prefixSum[row1][col1];
};

function isAdditiveNumber(num) {
    function isValid(num) {
        // check if the number has leading zeros
        return !(num.length > 1 && num[0] === '0');
    }

    function backtrack(start, path) {
        // if we have reached the end of the string and have at least three numbers in the path
        if (start === num.length && path.length >= 3) {
            return true;
        }
        for (let i = start; i < num.length; i++) {
            // get the current number
            let currNum = num.substring(start, i + 1);
            // if the current number is valid
            if (isValid(currNum)) {
                // if the path has less than two numbers or the current number is the sum of the last two numbers in the path
                if (path.length < 2 || parseInt(currNum) === parseInt(path[path.length - 1]) + parseInt(path[path.length - 2])) {
                    // add the current number to the path and continue the backtracking
                    if (backtrack(i + 1, path.concat([currNum]))) {
                        return true;
                    }
                }
            }
        }
        // if we have tried all possible numbers and haven't found a valid sequence
        return false;
    }
    // start the backtracking with an empty path
    return backtrack(0, []);
}

function NumArray(nums) {
    // Initialize the segment tree with the given array
    this.tree = new Array(4 * nums.length).fill(0);
    this.n = nums.length;
    this.buildTree(nums, 0, 0, nums.length - 1);
}

function buildTree(nums, node, start, end) {
    // Base case: if the segment contains only one element, store the element in the tree
    if (start === end) {
        this.tree[node] = nums[start];
    } else {
        // Calculate the mid point of the segment
        const mid = Math.floor((start + end) / 2);
        // Recursively build the left and right subtrees
        buildTree.call(this, nums, 2 * node + 1, start, mid);
        buildTree.call(this, nums, 2 * node + 2, mid + 1, end);
        // Store the sum of the left and right subtrees in the current node
        this.tree[node] = this.tree[2 * node + 1] + this.tree[2 * node + 2];
    }
}

NumArray.prototype.buildTree = buildTree;

NumArray.prototype.update = function(i, val) {
    // Update the value at index i in the segment tree
    this.updateTree(0, 0, this.n - 1, i, val);
}

function updateTree(node, start, end, i, val) {
    // Base case: if the segment contains only one element, update the value
    if (start === end) {
        this.tree[node] = val;
    } else {
        // Calculate the mid point of the segment
        const mid = Math.floor((start + end) / 2);
        // Recursively update the left or right subtree
        if (i <= mid) {
            updateTree.call(this, 2 * node + 1, start, mid, i, val);
        } else {
            updateTree.call(this, 2 * node + 2, mid + 1, end, i, val);
        }
        // Update the sum of the left and right subtrees in the current node
        this.tree[node] = this.tree[2 * node + 1] + this.tree[2 * node + 2];
    }
}

NumArray.prototype.updateTree = updateTree;

NumArray.prototype.sumRange = function(i, j) {
    // Calculate the sum of the range [i, j] using the segment tree
    return this.queryTree(0, 0, this.n - 1, i, j);
}

function queryTree(node, start, end, i, j) {
    // Base case: if the segment is completely inside the query range, return the sum
    if (i <= start && j >= end) {
        return this.tree[node];
    } else if (i > end || j < start) {
        // Base case: if the segment is completely outside the query range, return 0
        return 0;
    } else {
        // Calculate the mid point of the segment
        const mid = Math.floor((start + end) / 2);
        // Recursively query the left and right subtrees
        const leftSum = queryTree.call(this, 2 * node + 1, start, mid, i, j);
        const rightSum = queryTree.call(this, 2 * node + 2, mid + 1, end, i, j);
        // Return the sum of the left and right subtrees
        return leftSum + rightSum;
    }
}

NumArray.prototype.queryTree = queryTree;

function findMinHeightTrees(n, edges) {
    if (n === 1) return [0]; // base case: if there's only one node, return it
    let graph = new Array(n).fill(0).map(() => []); // create adjacency list
    let degree = new Array(n).fill(0); // keep track of node degrees
    for (let edge of edges) {
        graph[edge[0]].push(edge[1]); // add edge to adjacency list
        graph[edge[1]].push(edge[0]);
        degree[edge[0]]++; // increment degree of node
        degree[edge[1]]++;
    }
    let queue = []; // initialize queue for BFS
    for (let i = 0; i < n; i++) {
        if (degree[i] === 1) queue.push(i); // add leaf nodes to queue
    }
    while (n > 2) { // continue until only 2 nodes are left
        let size = queue.length; // get current queue size
        n -= size; // decrement node count
        for (let i = 0; i < size; i++) {
            let node = queue.shift(); // dequeue a node
            for (let neighbor of graph[node]) {
                degree[neighbor]--; // decrement degree of neighbor
                if (degree[neighbor] === 1) queue.push(neighbor); // add neighbor to queue if it's a leaf
            }
        }
    }
    return queue; // return remaining nodes as MHT roots
}

function removeDuplicateLetters(s) {
    // Create a count map to store the frequency of each character
    var countMap = {};
    for (var i = 0; i < s.length; i++) {
        // If the character is already in the map, increment its count
        if (countMap[s[i]]) {
            countMap[s[i]]++;
        } else {
            countMap[s[i]] = 1;
        }
    }

    // Create a set to store the characters in the result
    var resultSet = new Set();
    var result = '';

    // Iterate over the string
    for (var i = 0; i < s.length; i++) {
        // Decrement the count of the current character
        countMap[s[i]]--;

        // If the character is already in the result set, skip it
        if (resultSet.has(s[i])) {
            continue;
        }

        // While the result is not empty and the last character is greater than the current character
        // and the last character appears later in the string, remove the last character from the result
        while (result.length > 0 && result[result.length - 1] > s[i] && countMap[result[result.length - 1]] > 0) {
            // Remove the last character from the result set
            resultSet.delete(result[result.length - 1]);
            // Remove the last character from the result
            result = result.slice(0, -1);
        }

        // Add the current character to the result set
        resultSet.add(s[i]);
        // Add the current character to the result
        result += s[i];
    }

    return result;
}

function countSmaller(nums) {
  // Create a copy of the input array and sort it in ascending order
  var sortedNums = nums.slice().sort((a, b) => a - b);
  var result = [];
  for (var i = 0; i < nums.length; i++) {
    // Use binary search to find the index of the current element in the sorted array
    var index = binarySearch(sortedNums, nums[i]);
    // The number of smaller elements is the index of the current element in the sorted array
    result.push(index);
    // Remove the current element from the sorted array to avoid counting duplicates
    sortedNums.splice(index, 1);
  }
  return result;
}

function binarySearch(arr, target) {
  var left = 0;
  var right = arr.length - 1;
  while (left <= right) {
    var mid = Math.floor((left + right) / 2);
    if (arr[mid] < target) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }
  return left;
}

function nthSuperUglyNumber(n, primes) {
  let uglyNumbers = [1]; // initialize with the first ugly number
  let indices = new Array(primes.length).fill(0); // keep track of the current index for each prime
  // iterate until we find the nth super ugly number
  while (uglyNumbers.length < n) {
    // find the next super ugly number by multiplying each prime with its current index
    let nextUgly = Infinity;
    for (let i = 0; i < primes.length; i++) {
      // calculate the next possible super ugly number for this prime
      let candidate = uglyNumbers[indices[i]] * primes[i];
      // update the next super ugly number if this candidate is smaller
      nextUgly = Math.min(nextUgly, candidate);
    }
    // add the next super ugly number to the list
    uglyNumbers.push(nextUgly);
    // update the indices for the primes that produced the next super ugly number
    for (let i = 0; i < primes.length; i++) {
      // if this prime produced the next super ugly number, increment its index
      if (uglyNumbers[indices[i]] * primes[i] === nextUgly) {
        indices[i]++;
      }
    }
  }
  // the nth super ugly number is the last one in the list
  return uglyNumbers[n - 1];
}

function bulbSwitch(n) {
    // The bulb will be toggled an odd number of times if it has an odd number of factors, which is the case for perfect squares
    return Math.floor(Math.sqrt(n));
}

function coinChange(coins, amount) {
    // Create a dynamic programming table to store the minimum number of coins needed for each amount
    let dp = new Array(amount + 1).fill(Infinity);
    dp[0] = 0; // Base case: 0 coins are needed to make 0 amount
    // Iterate over each coin and update the dp table
    for (let coin of coins) {
        // Update the dp table for each amount that can be made with the current coin
        for (let i = coin; i <= amount; i++) {
            // Update the minimum number of coins needed for the current amount
            dp[i] = Math.min(dp[i], dp[i - coin] + 1);
        }
    }
    // Return the minimum number of coins needed for the given amount, or -1 if it's not possible
    return dp[amount] === Infinity ? -1 : dp[amount];
}

function wiggleSort(nums) {
  const n = nums.length;
  const sorted = nums.slice().sort((a, b) => a - b);
  const mid = Math.floor((n - 1) / 2);
  const result = new Array(n);
  let j = mid, k = n - 1;
  for (let i = 0; i < n; i++) {
    if (i % 2 === 0) result[i] = sorted[j--];
    else result[i] = sorted[k--];
  }
  for (let i = 0; i < n; i++) nums[i] = result[i];
}

function isPowerOfThree(n) {
  // main logic: keep dividing n by 3 until it's no longer divisible, if n becomes 1 then it's a power of 3
  if (n <= 0) return false;
  while (n % 3 === 0) n /= 3;
  return n === 1;
}

function countRangeSum(nums, lower, upper) {
    let count = 0;
    let prefixSums = [0];
    for (let num of nums) {
        prefixSums.push(prefixSums[prefixSums.length - 1] + num);
    }
    let sortedPrefixSums = [];
    for (let i = 0; i < prefixSums.length; i++) {
        let leftIndex = binarySearch(sortedPrefixSums, prefixSums[i] - upper);
        let rightIndex = binarySearch(sortedPrefixSums, prefixSums[i] - lower, true);
        count += rightIndex - leftIndex;
        insertSorted(sortedPrefixSums, prefixSums[i]);
    }
    return count;
}
function insertSorted(arr, val) {
    let idx = binarySearch(arr, val, true);
    arr.splice(idx, 0, val);
}
function binarySearch(arr, target, upperBound) {
    let left = 0;
    let right = arr.length;
    while (left < right) {
        let mid = Math.floor((left + right) / 2);
        if (upperBound ? arr[mid] <= target : arr[mid] < target) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return left;
}

function oddEvenList(head) {
    // Algorithm solution is already optimal, using two pointers to separate odd and even nodes
    if (!head) return head;
    let odd = head;
    let even = head.next;
    let evenHead = even;
    while (even && even.next) {
        // Reconnect odd nodes to the next odd node
        odd.next = even.next;
        odd = odd.next;
        // Reconnect even nodes to the next even node
        even.next = odd.next;
        even = even.next;
    }
    // Connect the last odd node to the first even node
    odd.next = evenHead;
    return head;
}

function longestIncreasingPath(matrix) {
    // If the matrix is empty, return 0
    if (!matrix.length) return 0;

    const directions = [[0, 1], [0, -1], [1, 0], [-1, 0]];
    const memo = Array(matrix.length).fill(0).map(() => Array(matrix[0].length).fill(0));

    function dfs(row, col) {
        // If the result is already memoized, return it
        if (memo[row][col] !== 0) return memo[row][col];

        let longest = 1;
        // Explore all four directions
        for (const [dr, dc] of directions) {
            const nr = row + dr;
            const nc = col + dc;
            // Check if the new position is within the matrix and has a greater value
            if (nr >= 0 && nr < matrix.length && nc >= 0 && nc < matrix[0].length && matrix[nr][nc] > matrix[row][col]) {
                // Recursively find the longest path from the new position
                longest = Math.max(longest, 1 + dfs(nr, nc));
            }
        }
        // Memoize the result
        memo[row][col] = longest;
        return longest;
    }

    let maxLength = 0;
    // Perform DFS from each cell
    for (let i = 0; i < matrix.length; i++) {
        for (let j = 0; j < matrix[0].length; j++) {
            // Find the longest path starting from the current cell
            maxLength = Math.max(maxLength, dfs(i, j));
        }
    }
    return maxLength;
}

function minPatches(nums, n) {
    let patchCount = 0, i = 0, miss = 1;
    // calculate the minimum number of patches required to cover the range [1, n]
    while (miss <= n) {
        // if the current number in the array is less than or equal to the current miss value, use it to update the miss value
        if (i < nums.length && nums[i] <= miss) {
            miss += nums[i];
            i++;
        } else {
            // otherwise, add the current miss value to the array and update the miss value
            miss *= 2;
            patchCount++;
        }
    }
    return patchCount;
}

function isValidSerialization(preorder) {
    let nodes = preorder.split(','); // split the string into nodes
    let degree = 1; // initialize the degree of the tree
    for (let node of nodes) { 
        // if the degree becomes zero or negative, return false
        if (--degree < 0) return false; 
        // if the node is not '#', increase the degree by 2 (for left and right children)
        if (node !== '#') degree += 2; 
    }
    // return true if the degree is zero (all nodes have been used), otherwise return false
    return degree === 0; 
}

function findItinerary(tickets) {
    // Create a graph from the tickets
    const graph = {};
    for (let i = 0; i < tickets.length; i++) {
        if (!graph[tickets[i][0]]) graph[tickets[i][0]] = [];
        graph[tickets[i][0]].push(tickets[i][1]);
    }
    // Sort the destinations for each airport
    for (let airport in graph) {
        graph[airport].sort();
    }
    // Initialize the result
    const result = [];
    // Perform DFS
    function dfs(airport) {
        // While there are still destinations from the current airport
        while (graph[airport] && graph[airport].length > 0) {
            // Get the next destination
            const nextAirport = graph[airport].shift();
            // Recursively visit the next destination
            dfs(nextAirport);
        }
        // Add the current airport to the result
        result.unshift(airport);
    }
    // Start the DFS from JFK
    dfs('JFK');
    return result;
}

function increasingTriplet(nums) {
  let first = Infinity; // initialize first element as infinity
  let second = Infinity; // initialize second element as infinity
  for (let i = 0; i < nums.length; i++) { 
    // if current number is smaller than first, update first
    if (nums[i] <= first) first = nums[i]; 
    // if current number is greater than first but smaller than second, update second
    else if (nums[i] <= second) second = nums[i]; 
    // if current number is greater than second, we have found a triplet
    else return true; 
  }
  // if no triplet is found, return false
  return false;
}

function isSelfCrossing(x) {
  const n = x.length;
  for (let i = 3; i < n; i++) {
    if (x[i] >= x[i - 2] && x[i - 1] <= x[i - 3]) return true;
    if (i === 4 && x[i - 1] === x[i - 3] && x[i] + x[i - 4] >= x[i - 2]) return true;
    if (i >= 5 && x[i - 2] >= x[i - 4] && x[i] + x[i - 4] >= x[i - 2] &&
        x[i - 1] <= x[i - 3] && x[i - 1] + x[i - 5] >= x[i - 3]) return true;
  }
  return false;
}

function maxCoins(nums) {
  // add 1 at the beginning and the end of the array to handle edge cases
  nums = [1].concat(nums).concat([1]);
  var n = nums.length;
  var dp = new Array(n).fill(0).map(function() { return new Array(n).fill(0); });
  // fill the dp table in a bottom-up manner
  for (var length = 1; length < n - 1; length++) {
    // consider all possible subarrays of the current length
    for (var left = 0; left < n - length - 1; left++) {
      var right = left + length + 1;
      // consider all possible balloons to burst in the current subarray
      for (var i = left + 1; i < right; i++) {
        // calculate the maximum coins that can be collected by bursting the ith balloon
        dp[left][right] = Math.max(dp[left][right], nums[left] * nums[i] * nums[right] + dp[left][i] + dp[i][right]);
      }
    }
  }
  // the maximum coins that can be collected is stored in dp[0][n - 1]
  return dp[0][n - 1];
}

function palindromePairs(words) {
    const indexMap = new Map();
    for (let i = 0; i < words.length; i++) indexMap.set(words[i], i);

    const isPalindrome = (s, l, r) => {
        while (l < r) { if (s[l] !== s[r]) return false; l++; r--; }
        return true;
    };

    const result = [];
    for (let i = 0; i < words.length; i++) {
        const w = words[i];
        const n = w.length;
        for (let cut = 0; cut <= n; cut++) {
            if (isPalindrome(w, cut, n - 1)) {
                const leftRev = w.substring(0, cut).split('').reverse().join('');
                if (indexMap.has(leftRev) && indexMap.get(leftRev) !== i) {
                    result.push([i, indexMap.get(leftRev)]);
                }
            }
            if (cut > 0 && isPalindrome(w, 0, cut - 1)) {
                const rightRev = w.substring(cut).split('').reverse().join('');
                if (indexMap.has(rightRev) && indexMap.get(rightRev) !== i) {
                    result.push([indexMap.get(rightRev), i]);
                }
            }
        }
    }
    return result;
}

function rob(root) {
    function dfs(node) {
        if (!node) return [0, 0];
        const left = dfs(node.left);
        const right = dfs(node.right);
        const without = Math.max(left[0], left[1]) + Math.max(right[0], right[1]);
        // if we rob this node, its children CANNOT be robbed -- use their "without" values
        const withNode = node.val + left[1] + right[1];
        return [withNode, without];
    }
    return Math.max(dfs(root)[0], dfs(root)[1]);
}

class NestedIterator {
  constructor(nestedList) {
    let stack = [...nestedList].reverse();
    let result = [];
    while (stack.length > 0) {
      let current = stack.pop();
      if (Array.isArray(current)) {
        stack.push(...current.reverse());
      } else {
        result.push(current);
      }
    }
    this.flatList = result;
    this.index = 0;
  }
  hasNext() { return this.index < this.flatList.length; }
  next() { return this.flatList[this.index++]; }
}

function isPowerOfFour(n) {
    // check if n is greater than 0 and its binary representation has only one '1' bit and the number of zeros after the '1' bit is even
    return n > 0 && (n & (n - 1)) === 0 && (n & 0xAAAAAAAA) === 0;
}

function integerBreak(n) {
    // the optimal solution is to divide n into as many 3's as possible, with a remainder of 2 or 1 if n is not divisible by 3
    if (n === 2) return 1; // base case: 2 = 1 + 1
    if (n === 3) return 2; // base case: 3 = 1 + 2
    let result = 1;
    while (n > 4) { // divide n into as many 3's as possible
        result *= 3;
        n -= 3;
    }
    result *= n; // multiply the remaining value
    return result;
}

function reverseString(s) {
  // Initialize two pointers, one at the start and one at the end of the string
  let left = 0;
  let right = s.length - 1;
  // Continue swapping characters until the two pointers meet in the middle
  while (left < right) {
    // Swap the characters at the left and right pointers
    let temp = s[left];
    s[left] = s[right];
    s[right] = temp;
    // Move the pointers towards the center of the string
    left++;
    right--;
  }
}

function reverseVowels(s) {
  // Define the vowels in both lower and upper cases
  const vowels = 'aeiouAEIOU';
  // Convert the string to an array for easier manipulation
  const chars = s.split('');
  // Initialize two pointers, one at the start and one at the end of the string
  let left = 0, right = chars.length - 1;
  // Continue the loop until the two pointers meet
  while (left < right) {
    // If the character at the left pointer is not a vowel, move the pointer to the right
    if (!vowels.includes(chars[left])) left++;
    // If the character at the right pointer is not a vowel, move the pointer to the left
    else if (!vowels.includes(chars[right])) right--;
    // If both characters are vowels, swap them and move both pointers
    else {
      // Swap the vowels
      [chars[left], chars[right]] = [chars[right], chars[left]];
      // Move both pointers
      left++; right--;
    }
  }
  // Join the characters back into a string and return the result
  return chars.join('');
}

function topKFrequent(nums, k) {
    var frequencyMap = {};
    for (var i = 0; i < nums.length; i++) {
        if (frequencyMap[nums[i]]) frequencyMap[nums[i]]++;
        else frequencyMap[nums[i]] = 1;
    }
    var bucket = new Array(nums.length + 1).fill(0).map(() => new Array());
    for (var key in frequencyMap) {
        bucket[frequencyMap[key]].push(Number(key));
    }
    var result = new Array();
    for (var i = bucket.length - 1; i >= 0; i--) {
        for (var j = 0; j < bucket[i].length; j++) {
            result.push(bucket[i][j]);
        }
        if (result.length >= k) break;
    }
    return result.slice(0, k);
}

function intersection(nums1, nums2) {
  // Create a set from the first array to remove duplicates and have O(1) lookup time
  const set1 = new Set(nums1);
  // Create a set to store the intersection
  const intersectionSet = new Set();
  // Iterate over the second array and add elements to the intersection set if they exist in the first set
  for (const num of nums2) {
    // Check if the current number exists in the first set
    if (set1.has(num)) {
      // Add the current number to the intersection set
      intersectionSet.add(num);
    }
  }
  // Convert the intersection set to an array and return it
  return Array.from(intersectionSet);
}

function intersect(nums1, nums2) {
    // Create a hash map to store the frequency of elements in nums1
    var map = {};
    for (var i = 0; i < nums1.length; i++) {
        // If the element is already in the map, increment its count
        if (map[nums1[i]]) map[nums1[i]]++;
        // If the element is not in the map, add it with a count of 1
        else map[nums1[i]] = 1;
    }
    var result = [];
    for (var i = 0; i < nums2.length; i++) {
        // If the element is in the map and its count is greater than 0, add it to the result and decrement its count
        if (map[nums2[i]] > 0) {
            result.push(nums2[i]);
            map[nums2[i]]--;
        }
    }
    return result;
}

function SummaryRanges() {
    this.intervals = []; // sorted array of [start, end] pairs, always kept merged
}

SummaryRanges.prototype.addNum = function(value) {
    const intervals = this.intervals;
    let lo = 0, hi = intervals.length;
    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (intervals[mid][0] < value) lo = mid + 1; else hi = mid;
    }
    const before = lo - 1 >= 0 ? intervals[lo - 1] : null;
    const after = lo < intervals.length ? intervals[lo] : null;

    if (before && before[1] >= value) return; // already covered by an existing interval

    const mergeBefore = before && before[1] + 1 === value;
    const mergeAfter = after && after[0] - 1 === value;

    if (mergeBefore && mergeAfter) {
        before[1] = after[1];
        intervals.splice(lo, 1);
    } else if (mergeBefore) {
        before[1] = value;
    } else if (mergeAfter) {
        after[0] = value;
    } else {
        intervals.splice(lo, 0, [value, value]);
    }
};

SummaryRanges.prototype.getIntervals = function() {
    return this.intervals.map(iv => [...iv]);
};

function maxEnvelopes(envelopes) {
  // Sort envelopes by width and then by height in descending order
  envelopes.sort((a, b) => a[0] === b[0] ? b[1] - a[1] : a[0] - b[0]);
  let dp = new Array(envelopes.length).fill(1);
  for (let i = 0; i < envelopes.length; i++) {
    // For each envelope, find the maximum number of envelopes that can fit inside it
    for (let j = 0; j < i; j++) {
      if (envelopes[i][0] > envelopes[j][0] && envelopes[i][1] > envelopes[j][1]) {
        // Update the maximum number of envelopes that can fit inside the current envelope
        dp[i] = Math.max(dp[i], dp[j] + 1);
      }
    }
  }
  // Return the maximum number of envelopes that can fit inside each other
  return Math.max(...dp);
}

