Twitter.prototype.getNewsFeed = function(userId) {
    // Get the 10 most recent tweets from the user and their followings
    let tweets = [];
    if (this.tweets[userId]) tweets = tweets.concat(this.tweets[userId]);
    if (this.userFollowings[userId]) {
        for (let followId of this.userFollowings[userId]) {
            if (this.tweets[followId]) tweets = tweets.concat(this.tweets[followId]);
        }
    }
    // Sort the tweets by time in descending order and return the top 10
    return tweets.sort((a, b) => b.time - a.time).slice(0, 10).map(tweet => tweet.id);
}

Twitter.prototype.follow = function(followerId, followeeId) {
    // Add the followee to the follower's followings
    if (!this.userFollowings[followerId]) this.userFollowings[followerId] = new Set();
    this.userFollowings[followerId].add(followeeId);
}

Twitter.prototype.unfollow = function(followerId, followeeId) {
    // Remove the followee from the follower's followings
    if (this.userFollowings[followerId]) this.userFollowings[followerId].delete(followeeId);
}

