function countNumbersWithUniqueDigits(n) {
    if (n === 0) return 1;
    let count = 10;
    let unique = 9;
    let available = 9;
    for (let i = 2; i <= n && i <= 10; i++) {
        unique *= available;
        count += unique;
        available--;
    }
    return count;
}

function maxSumSubmatrix(matrix, k) {
    let maxSum = -Infinity;
    let rows = matrix.length;
    let cols = matrix[0].length;
    for (let left = 0; left < cols; left++) {
        let temp = new Array(rows).fill(0);
        for (let right = left; right < cols; right++) {
            for (let i = 0; i < rows; i++) {
                temp[i] += matrix[i][right];
            }
            maxSum = Math.max(maxSum, maxSumSubarray(temp, k));
        }
    }
    return maxSum;
}
function maxSumSubarray(arr, k) {
    let maxSum = -Infinity;
    let sum = 0;
    let sorted = [0];
    function insertSorted(x) {
        let lo = 0, hi = sorted.length;
        while (lo < hi) { const mid = (lo + hi) >> 1; if (sorted[mid] < x) lo = mid + 1; else hi = mid; }
        sorted.splice(lo, 0, x);
    }
    function ceilingIndex(target) {
        // smallest value >= target
        let lo = 0, hi = sorted.length;
        while (lo < hi) { const mid = (lo + hi) >> 1; if (sorted[mid] < target) lo = mid + 1; else hi = mid; }
        return lo < sorted.length ? lo : -1;
    }
    for (const num of arr) {
        sum += num;
        const target = sum - k;
        const idx = ceilingIndex(target);
        if (idx !== -1) maxSum = Math.max(maxSum, sum - sorted[idx]);
        insertSorted(sum);
    }
    return maxSum;
}

function canMeasureWater(x, y, target) {
    // If the target is greater than the sum of the capacities, it's impossible to reach
    if (target > x + y) return false;
    // If the target is 0, we can always reach it by not filling either jug
    if (target === 0) return true;
    // Use the Euclidean algorithm to find the GCD of x and y
    function gcd(a, b) {
        if (b === 0) return a;
        return gcd(b, a % b);
    }
    // If the target is a multiple of the GCD, we can reach it
    return target % gcd(x, y) === 0;
}

