function isPerfectSquare(num) {
  // Initialize the low and high pointers for binary search
  var low = 1, high = num;
  // Continue the binary search until the low pointer is less than or equal to the high pointer
  while (low <= high) {
    // Calculate the mid value
    var mid = Math.floor((low + high) / 2);
    // Calculate the square of the mid value
    var square = mid * mid;
    // If the square is equal to the input number, return true
    if (square === num) return true;
    // If the square is greater than the input number, update the high pointer
    else if (square > num) high = mid - 1;
    // If the square is less than the input number, update the low pointer
    else low = mid + 1;
  }
  // If no perfect square is found, return false
  return false;
}

function largestDivisibleSubset(nums) {
    if (nums.length === 0) return [];
    nums.sort((a, b) => a - b); // sorting the array to apply dynamic programming
    let dp = new Array(nums.length).fill(1); // initializing dp array with 1
    let prev = new Array(nums.length).fill(-1); // storing previous index for backtracking
    let maxIndex = 0; // storing index of maximum length subset
    for (let i = 1; i < nums.length; i++) {
        for (let j = 0; j < i; j++) {
            if (nums[i] % nums[j] === 0 && dp[i] < dp[j] + 1) { // checking divisibility and updating dp array
                dp[i] = dp[j] + 1;
                prev[i] = j; // updating previous index
            }
        }
        if (dp[i] > dp[maxIndex]) maxIndex = i; // updating maxIndex
    }
    let result = []; // storing result
    while (maxIndex !== -1) {
        result.push(nums[maxIndex]); // backtracking to find subset
        maxIndex = prev[maxIndex];
    }
    return result.reverse(); // returning result in correct order
}

function getSum(a, b) {
  // use bitwise XOR to get the sum without considering the carry
  // use bitwise AND and left shift to get the carry
  // repeat the process until there's no carry
  while (b !== 0) {
    // calculate the carry
    var carry = a & b;
    // calculate the sum without considering the carry
    a = a ^ b;
    // left shift the carry to prepare for the next iteration
    b = carry << 1;
  }
  return a;
}

