function superPow(a, b) {
    // using the property of modular arithmetic to avoid large numbers
    let result = 1;
    for (let i = 0; i < b.length; i++) {
        // using the property of exponentiation to divide the problem into smaller sub-problems
        result = powMod(result, 10, 1337) * powMod(a, b[i], 1337) % 1337;
    }
    return result;
}

function powMod(base, exponent, mod) {
    // using the property of exponentiation to divide the problem into smaller sub-problems
    let result = 1;
    base = base % mod;
    while (exponent > 0) {
        // using the property of exponentiation to divide the problem into smaller sub-problems
        if (exponent % 2 === 1) result = (result * base) % mod;
        exponent = exponent >> 1;
        base = (base * base) % mod;
    }
    return result;
}

