function kSmallestPairs(nums1, nums2, k) {
    // Create a min-heap to store the pairs, with the sum of each pair as the key
    let minHeap = [];
    for (let i = 0; i < nums1.length; i++) {
        // Push the pair (nums1[i], nums2[0]) into the min-heap
        minHeap.push([nums1[i], nums2[0], i, 0]);
    }
    // Initialize the result array
    let result = [];
    // While the min-heap is not empty and we have not found k pairs
    while (minHeap.length > 0 && result.length < k) {
        // Extract the pair with the smallest sum from the min-heap
        minHeap.sort((a, b) => (a[0] + a[1]) - (b[0] + b[1]));
        let [u, v, i, j] = minHeap.shift();
        // Add the extracted pair to the result array
        result.push([u, v]);
        // If we have not reached the end of the second array
        if (j + 1 < nums2.length) {
            // Push the next pair (nums1[i], nums2[j + 1]) into the min-heap
            minHeap.push([nums1[i], nums2[j + 1], i, j + 1]);
        }
    }
    // Return the result array
    return result;
}

