function guessNumber(n, pick) {
    function guess(num) {
        if (num === pick) return 0;
        return num < pick ? 1 : -1;
    }
    let left = 1, right = n;
    while (left <= right) {
        let mid = Math.floor((left + right) / 2);
        let result = guess(mid);
        if (result === 0) return mid;
        else if (result === -1) right = mid - 1;
        else left = mid + 1;
    }
}

function getMoneyAmount(n) {
    let dp = Array.from({length: n + 2}, () => Array.from({length: n + 2}, () => 0));
    for (let length = 2; length <= n; length++) {
        for (let i = 1; i <= n - length + 1; i++) {
            let j = i + length - 1;
            dp[i][j] = Infinity;
            for (let k = i; k <= j; k++) {
                let cost = k + Math.max(dp[i][k - 1] || 0, dp[k + 1][j] || 0);
                dp[i][j] = Math.min(dp[i][j], cost);
            }
        }
    }
    return dp[1][n];
}

function wiggleMaxLength(nums) {
    // Initialize variables to store the length of the longest wiggle subsequence with the last difference being positive or negative
    let up = 1, down = 1;
    for (let i = 1; i < nums.length; i++) {
        // If the current difference is positive, update the length of the longest wiggle subsequence with the last difference being positive
        if (nums[i] > nums[i - 1]) up = down + 1;
        // If the current difference is negative, update the length of the longest wiggle subsequence with the last difference being negative
        else if (nums[i] < nums[i - 1]) down = up + 1;
    }
    // Return the maximum length of the longest wiggle subsequence with the last difference being positive or negative
    return Math.max(up, down);
}

function combinationSum4(nums, target) {
  // Create a dynamic programming array to store the number of combinations for each sum from 0 to target
  let dp = new Array(target + 1).fill(0);
  // Base case: there is one way to get a sum of 0 (by not choosing any numbers)
  dp[0] = 1;
  // Iterate over each possible sum from 1 to target
  for (let i = 1; i <= target; i++) {
    // For each sum, iterate over each number in the input array
    for (let num of nums) {
      // If the current number is less than or equal to the current sum, add the number of combinations for the remaining sum to the current sum's combinations
      if (i - num >= 0) dp[i] += dp[i - num];
    }
  }
  // The number of combinations for the target sum is stored in the last index of the dynamic programming array
  return dp[target];
}

function kthSmallest(matrix, k) {
    // Initialize the min-heap with the first element of each row
    let minHeap = [];
    for (let i = 0; i < matrix.length; i++) {
        // Store the value, row, and column in the heap
        minHeap.push([matrix[i][0], i, 0]);
    }
    // Heapify the min-heap
    minHeap.sort((a, b) => a[0] - b[0]);

    // Remove the smallest element from the heap k times
    let count = 0;
    while (count < k) {
        // Get the smallest element from the heap
        let [val, row, col] = minHeap.shift();
        count++;
        // If this is the kth smallest element, return it
        if (count === k) {
            return val;
        }
        // If there are more elements in the row, add the next one to the heap
        if (col + 1 < matrix[row].length) {
            // Add the next element in the row to the heap
            minHeap.push([matrix[row][col + 1], row, col + 1]);
            // Heapify the min-heap
            minHeap.sort((a, b) => a[0] - b[0]);
        }
    }
}

function RandomizedSet() {
    // Initialize an object to store the indices of elements in the array for O(1) lookup
    this.indexMap = {};
    // Initialize an array to store the elements
    this.elements = [];
}

RandomizedSet.prototype.insert = function(val) {
    // Check if the element is already in the set
    if (!(val in this.indexMap)) {
        // If not, add it to the array and update the index map
        this.indexMap[val] = this.elements.length;
        this.elements.push(val);
        return true;
    }
    // If the element is already in the set, return false
    return false;
}

RandomizedSet.prototype.remove = function(val) {
    // Check if the element is in the set
    if (val in this.indexMap) {
        // Get the index of the element to be removed
        var index = this.indexMap[val];
        // Get the last element in the array
        var lastElement = this.elements[this.elements.length - 1];
        // Swap the element to be removed with the last element
        this.elements[index] = lastElement;
        // Update the index map for the last element
        this.indexMap[lastElement] = index;
        // Remove the last element from the array
        this.elements.pop();
        // Remove the element from the index map
        delete this.indexMap[val];
        return true;
    }
    // If the element is not in the set, return false
    return false;
}

RandomizedSet.prototype.getRandom = function() {
    // Return a random element from the array
    return this.elements[Math.floor(Math.random() * this.elements.length)];
}

