function RandomizedCollection() {
    // Initialize an empty array to store the elements
    this.nums = [];
    // Initialize an empty hash map to store the indices of each element
    this.indexMap = {};
}

RandomizedCollection.prototype.insert = function(val) {
    // Add the element to the end of the array
    this.nums.push(val);
    // If the element is already in the hash map, add the new index to its set of indices
    if (this.indexMap[val]) {
        this.indexMap[val].add(this.nums.length - 1);
    } 
    // If the element is not in the hash map, create a new set with the new index
    else {
        this.indexMap[val] = new Set([this.nums.length - 1]);
    }
    // Return true to indicate that the element was inserted
    return this.indexMap[val].size === 1;
}

RandomizedCollection.prototype.remove = function(val) {
    // If the element is not in the hash map, return false
    if (!this.indexMap[val] || this.indexMap[val].size === 0) {
        return false;
    }
    // Get the index of the element to be removed
    let removeIndex = this.indexMap[val].values().next().value;
    // Get the last element in the array
    let lastVal = this.nums[this.nums.length - 1];
    // Replace the element to be removed with the last element
    this.nums[removeIndex] = lastVal;
    // Update the index of the last element in the hash map
    this.indexMap[lastVal].delete(this.nums.length - 1);
    this.indexMap[lastVal].add(removeIndex);
    // Remove the last element from the array
    this.nums.pop();
    // Remove the index of the removed element from the hash map
    this.indexMap[val].delete(removeIndex);
    // If the element is no longer in the hash map, delete it
    if (this.indexMap[val].size === 0) {
        delete this.indexMap[val];
    }
    // Return true to indicate that the element was removed
    return true;
}

RandomizedCollection.prototype.getRandom = function() {
    // Return a random element from the array
    return this.nums[Math.floor(Math.random() * this.nums.length)];
}

function canConstruct(ransomNote, magazine) {
  // Create a hash table to store the frequency of each character in the magazine
  var magazineFrequency = {};
  for (var i = 0; i < magazine.length; i++) {
    // If the character is already in the hash table, increment its count; otherwise, add it to the hash table with a count of 1
    magazineFrequency[magazine[i]] = (magazineFrequency[magazine[i]] || 0) + 1;
  }

  // Iterate over each character in the ransom note
  for (var i = 0; i < ransomNote.length; i++) {
    // If the character is not in the hash table or its count is 0, return false
    if (!magazineFrequency[ransomNote[i]] || magazineFrequency[ransomNote[i]] === 0) {
      return false;
    }
    // Decrement the count of the character in the hash table
    magazineFrequency[ransomNote[i]]--;
  }

  // If we've iterated over the entire ransom note without returning false, return true
  return true;
}

class Solution {
    constructor(nums) {
        this.original = [...nums];
        this.array = [...nums];
    }
    reset() {
        this.array = [...this.original];
        return this.array;
    }
    shuffle() {
        this.array = [...this.original];
        for (let i = this.array.length - 1; i > 0; i--) {
            let j = Math.floor(Math.random() * (i + 1));
            let temp = this.array[i];
            this.array[i] = this.array[j];
            this.array[j] = temp;
        }
        return this.array;
    }
}

function lexicalOrder(n) {
    var result = [];
    // start from 1 and perform DFS to generate numbers in lexicographical order
    for (var i = 1; i < 10; i++) {
        dfs(i, n, result);
    }
    return result;
}

function dfs(num, n, result) {
    // if the current number is within the range, add it to the result
    if (num <= n) {
        result.push(num);
        // for each digit from 0 to 9, perform DFS to generate the next numbers
        for (var i = 0; i < 10; i++) {
            dfs(num * 10 + i, n, result);
        }
    }
}

function deserialize(s) {
