}

function firstUniqChar(s) {
    // Create a hash map to store the frequency of each character
    var charFrequency = {};
    for (var i = 0; i < s.length; i++) {
        // If the character is already in the hash map, increment its frequency
        if (charFrequency[s[i]]) {
            charFrequency[s[i]]++;
        } 
        // If the character is not in the hash map, add it with a frequency of 1
        else {
            charFrequency[s[i]] = 1;
        }
    }
    // Iterate through the string again to find the first character with a frequency of 1
    for (var i = 0; i < s.length; i++) {
        // If the character has a frequency of 1, return its index
        if (charFrequency[s[i]] === 1) {
            return i;
        }
    }
    // If no unique character is found, return -1
    return -1;
}

function lengthLongestPath(input) {
    // Split the input string into an array of file/directory names
    let paths = input.split('\n');
    let stack = [];
    let maxLen = 0;
    // Iterate over each path in the array
    for (let path of paths) {
        // Count the number of tabs to determine the depth of the current path
        let depth = path.lastIndexOf('\t') + 1;
        // Remove the tabs from the path to get the actual name
        let name = path.replace(/\t/g, '');
        // If the path is a file, calculate its absolute path length
        if (name.includes('.')) {
            // Calculate the absolute path length by adding the current path name to the path of its parent directory
            let absPathLen = name.length + stack.slice(0, depth).reduce((sum, dir) => sum + dir.length + 1, 0);
            // Update the maximum length if the current path is longer
            maxLen = Math.max(maxLen, absPathLen);
        }
        // If the path is a directory, add its name to the stack
        else {
            // Remove directories from the stack that are at a greater depth than the current directory
            stack = stack.slice(0, depth);
            // Add the current directory to the stack
            stack.push(name);
        }
    }
    // Return the maximum length found
    return maxLen;
}

function findTheDifference(s, t) {
    let result = 0; 
    // calculate the XOR of all characters in string s
    for (let i = 0; i < s.length; i++) {
        result ^= s.charCodeAt(i);
    }
    // calculate the XOR of all characters in string t and the result
    for (let i = 0; i < t.length; i++) {
        result ^= t.charCodeAt(i);
    }
    // the result will be the ASCII value of the character that was added to t
    return String.fromCharCode(result);
}

function lastRemaining(n) {
  return n === 1 ? 1 : 2 * (1 + Math.floor(n / 2) - lastRemaining(Math.floor(n / 2)));
}

function isRectangleCover(rectangles) {
    let area = 0, x1 = Infinity, y1 = Infinity, x2 = -Infinity, y2 = -Infinity;
    let corners = {};
    // Calculate total area and find the bounding box of all rectangles
    for (let rectangle of rectangles) {
        let [x, y, a, b] = rectangle;
        area += (a - x) * (b - y);
        x1 = Math.min(x1, x);
        y1 = Math.min(y1, y);
        x2 = Math.max(x2, a);
        y2 = Math.max(y2, b);
        // Mark the corners of each rectangle
        let points = [[x, y], [x, b], [a, y], [a, b]];
        for (let point of points) {
            let key = point.join(',');
            // If a corner is marked twice, it's not a perfect rectangle
            if (corners[key]) {
                delete corners[key];
            } else {
                corners[key] = true;
            }
        }
    }
    // Check if the total area is equal to the area of the bounding box
    if (area !== (x2 - x1) * (y2 - y1)) return false;
    // Check if only the four corners of the bounding box are marked
    let expectedCorners = [[x1, y1], [x1, y2], [x2, y1], [x2, y2]];
    for (let corner of expectedCorners) {
        let key = corner.join(',');
        if (!corners[key]) return false;
    }
    return Object.keys(corners).length === 4;
}

function longestSubstring(s, k) {
  // base case: if string length is less than k, return 0
  if (s.length < k) return 0;

  // find the character with frequency less than k
  for (let char of new Set(s)) {
    // if the character's frequency is less than k, divide the string
    if (countChar(s, char) < k) {
      // divide the string into substrings separated by the character
      let maxLen = 0;
      for (let substring of s.split(char)) {
        // recursively find the longest substring in each substring
        maxLen = Math.max(maxLen, longestSubstring(substring, k));
      }
      return maxLen;
    }
  }

  // if no character's frequency is less than k, return the string length
  return s.length;
}

// helper function to count the frequency of a character in a string
function countChar(s, char) {
  let count = 0;
  for (let c of s) {
    if (c === char) count++;
  }
  return count;
}

