function integerReplacement(n) {
    let operations = 0;
    while (n !== 1) {
        if (n % 2 === 0) {
            n = n / 2;
        } else if (n % 4 === 1 || n === 3) {
            n = n - 1;
        } else {
            n = n + 1;
        }
        operations++;
    }
    return operations;
}

function rotateFunction(nums) {
  const n = nums.length;
  const sum = nums.reduce((a,b)=>a+b,0);
  let f = 0;
  for (let i = 0; i < n; i++) f += i * nums[i];
  let maxF = f;
  for (let k = 1; k < n; k++) {
    f = f + sum - n * nums[n - k];
    maxF = Math.max(maxF, f);
  }
  return maxF;
}

function decodeString(s) {
    // Initialize an empty stack to store the characters and counts
    let stack = [];
    let curNum = 0;
    let curString = '';
    // Iterate over each character in the string
    for (let i = 0; i < s.length; i++) {
        // If the character is a digit, update the current number
        if (!isNaN(s[i])) {
            // If the current number is already greater than 0, multiply it by 10 to handle multi-digit numbers
            curNum = curNum * 10 + parseInt(s[i]);
        } 
        // If the character is a letter, add it to the current string
        else if (s[i] >= 'a' && s[i] <= 'z') {
            curString += s[i];
        } 
        // If the character is an opening bracket, push the current number and string to the stack and reset them
        else if (s[i] === '[') {
            stack.push(curString);
            stack.push(curNum);
            curString = '';
            curNum = 0;
        } 
        // If the character is a closing bracket, pop the number and previous string from the stack, repeat the current string that many times, and append it to the previous string
        else if (s[i] === ']') {
            let num = stack.pop();
            let prevString = stack.pop();
            curString = prevString + curString.repeat(num);
        }
    }
    // Return the decoded string
    return curString;
}

function calcEquation(equations, values, queries) {
    // Create a graph to store the equations
    const graph = {};
    for (let i = 0; i < equations.length; i++) {
        const [dividend, divisor] = equations[i];
        const value = values[i];
        // If dividend is not in the graph, add it
        if (!(dividend in graph)) graph[dividend] = {};
        // If divisor is not in the graph, add it
        if (!(divisor in graph)) graph[divisor] = {};
        // Add the equation to the graph
        graph[dividend][divisor] = value;
        // Add the inverse equation to the graph
        graph[divisor][dividend] = 1 / value;
    }

    // Function to perform DFS
    function dfs(start, end, visited) {
        // If start is not in the graph, return -1
        if (!(start in graph)) return -1;
        // If start is the same as end, return 1
        if (start === end) return 1;
        // Mark start as visited
        visited.add(start);
        // Initialize result to -1
        let result = -1;
        // Iterate over the neighbors of start
        for (const neighbor in graph[start]) {
            // If neighbor is not visited, perform DFS
            if (!visited.has(neighbor)) {
                // Calculate the result
                const tempResult = dfs(neighbor, end, visited);
                // If result is not -1, update result
                if (tempResult !== -1) {
                    result = graph[start][neighbor] * tempResult;
                    break;
                }
            }
        }
        // Remove start from visited
        visited.delete(start);
        // Return result
        return result;
    }

    // Initialize result array
    const result = [];
    // Iterate over the queries
    for (const query of queries) {
        const [dividend, divisor] = query;
        // Perform DFS
        const tempResult = dfs(dividend, divisor, new Set());
        // Add result to the result array
        result.push(tempResult);
    }
    // Return result
    return result;
}

function findNthDigit(n) {
    // calculate the length of the numbers that we need to check
    let length = 1;
    let count = 9;
    let start = 1;
    // loop through the lengths of numbers until we find the one that contains the nth digit
    while (n > length * count) {
        // update the variables for the next iteration
        n -= length * count;
        length += 1;
        count *= 10;
        start *= 10;
    }
    // calculate the actual number that contains the nth digit
    start += Math.floor((n - 1) / length);
    // convert the number to a string to easily access the nth digit
    let str = start.toString();
    // return the nth digit
    return parseInt(str[(n - 1) % length]);
}
