function canCross(stones) {
  let n = stones.length;
  let stoneSet = new Set(stones);
  let memo = new Map();
  function dfs(stone, k) {
    // use memoization to store the results of subproblems
    let key = stone + ',' + k;
    if (memo.has(key)) return memo.get(key);
    // base case: if we reach the last stone, return true
    if (stone === stones[n - 1]) return true;
    // try all possible jumps
    for (let jump = k - 1; jump <= k + 1; jump++) {
      // skip invalid jumps
      if (jump <= 0) continue;
      // check if the next stone exists
      if (stoneSet.has(stone + jump)) {
        // recursively try to cross the river from the next stone
        if (dfs(stone + jump, jump)) {
          memo.set(key, true);
          return true;
        }
      }
    }
    // if we can't cross the river from the current stone, return false
    memo.set(key, false);
    return false;
  }
  // start the dfs from the first stone with a jump of 1
  return dfs(stones[0], 1);
}

function sumOfLeftLeaves(root) {
    function dfs(node, isLeft) { 
        // if node is null, return 0
        if (!node) return 0; 
        // if node is a leaf and is left, return its value
        if (!node.left && !node.right && isLeft) return node.val; 
        // recursively call dfs on left and right children
        return dfs(node.left, true) + dfs(node.right, false);
    }
    return dfs(root, false);
}

function toHex(num) {
    // handle negative numbers using two's complement method
    if (num < 0) num += Math.pow(2, 32);
    let result = '';
    // convert number to hexadecimal representation
    while (num > 0) {
        let remainder = num % 16;
        // convert remainder to hexadecimal digit
        if (remainder < 10) result = remainder.toString() + result;
        else result = String.fromCharCode(97 + remainder - 10) + result;
        num = Math.floor(num / 16);
    }
    // if result is empty, return '0'
    if (result === '') return '0';
    return result;
}

function removeKdigits(num, k) {
    let stack = []; // initialize an empty stack to store the digits
    // iterate over each character in the input string
    for (let i = 0; i < num.length; i++) {
        // while the stack is not empty, the top of the stack is greater than the current digit, and we can still remove digits
        while (stack.length > 0 && stack[stack.length - 1] > num[i] && k > 0) {
            // remove the top of the stack
            stack.pop();
            // decrement the count of digits to remove
            k--;
        }
        // push the current digit onto the stack
        stack.push(num[i]);
    }
    // if we still have digits to remove, remove them from the end of the stack
    while (k > 0) {
        stack.pop();
        k--;
    }
    // join the stack into a string and remove leading zeros
    let result = stack.join('').replace(/^0+/, '') || '0';
    return result;
}

