function longestPalindrome(s) {
    var charCount = {};
    for (var i = 0; i < s.length; i++) {
        // Count the occurrence of each character in the string
        charCount[s[i]] = (charCount[s[i]] || 0) + 1;
    }
    var length = 0;
    var oddCounted = false;
    for (var char in charCount) {
        // If the count of a character is even, add it to the length
        if (charCount[char] % 2 === 0) {
            length += charCount[char];
        } 
        // If the count of a character is odd, add the largest even number less than or equal to it to the length
        else {
            length += charCount[char] - 1;
            // If we haven't counted an odd character yet, add 1 to the length
            if (!oddCounted) {
                length += 1;
                oddCounted = true;
            }
        }
    }
    return length;
}

function trapRainWater(heightMap) {
  // Create a min-heap to store the cells with the lowest height
  let minHeap = [];
  let visited = new Array(heightMap.length).fill(0).map(() => new Array(heightMap[0].length).fill(false));
  let directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
  let water = 0;

  // Push all the boundary cells into the min-heap
  for (let i = 0; i < heightMap.length; i++) {
    // Add the cells in the first and last row
    minHeap.push([heightMap[i][0], i, 0]);
    minHeap.push([heightMap[i][heightMap[0].length - 1], i, heightMap[0].length - 1]);
    visited[i][0] = true;
    visited[i][heightMap[0].length - 1] = true;
  }
  for (let j = 1; j < heightMap[0].length - 1; j++) {
    // Add the cells in the first and last column
    minHeap.push([heightMap[0][j], 0, j]);
    minHeap.push([heightMap[heightMap.length - 1][j], heightMap.length - 1, j]);
    visited[0][j] = true;
    visited[heightMap.length - 1][j] = true;
  }

  // Heapify the min-heap
  minHeap.sort((a, b) => a[0] - b[0]);

  // Perform BFS
  while (minHeap.length > 0) {
    // Get the cell with the lowest height
    let [height, x, y] = minHeap.shift();
    // Explore the neighbors
    for (let [dx, dy] of directions) {
      let nx = x + dx;
      let ny = y + dy;
      // Check if the neighbor is within the boundary and not visited
      if (nx >= 0 && nx < heightMap.length && ny >= 0 && ny < heightMap[0].length && !visited[nx][ny]) {
        // Calculate the water trapped
        water += Math.max(0, height - heightMap[nx][ny]);
        // Mark the neighbor as visited and push it into the min-heap
        minHeap.push([Math.max(height, heightMap[nx][ny]), nx, ny]);
        visited[nx][ny] = true;
      }
    }
    // Heapify the min-heap
    minHeap.sort((a, b) => a[0] - b[0]);
  }

  return water;
}

