function thirdMax(nums) {
  // Remove duplicates by converting to a set and then back to an array
  let uniqueNums = [...new Set(nums)];

  // If there are less than 3 unique numbers, return the maximum
  if (uniqueNums.length < 3) {
    // Return the maximum number
    return Math.max(...uniqueNums);
  } else {
    // Remove the maximum and second maximum numbers
    uniqueNums.splice(uniqueNums.indexOf(Math.max(...uniqueNums)), 1);
    uniqueNums.splice(uniqueNums.indexOf(Math.max(...uniqueNums)), 1);

    // Return the maximum of the remaining numbers (third maximum)
    return Math.max(...uniqueNums);
  }
}

function numberOfArithmeticSlices(nums) {
    let count = 0; // initialize count of arithmetic slices
    let currentLength = 0; // initialize length of current arithmetic slice
    let lastDifference = null; // initialize last difference between consecutive elements
    for (let i = 0; i < nums.length - 1; i++) {
        let difference = nums[i + 1] - nums[i]; // calculate difference between current and next element
        if (lastDifference === null || lastDifference === difference) { // if this is the first element or the difference is the same as the last one
            currentLength++; // increase the length of the current arithmetic slice
            lastDifference = difference; // update the last difference
        } else {
            // if the current arithmetic slice has at least 3 elements, calculate the number of arithmetic slices it contains
            count += (currentLength - 1) * currentLength / 2;
            currentLength = 1; // reset the length of the current arithmetic slice
            lastDifference = difference; // update the last difference
        }
    }
    // if the last arithmetic slice has at least 3 elements, calculate the number of arithmetic slices it contains
    count += (currentLength - 1) * currentLength / 2; // this is the optimal algorithm solution
    return count;
}

function addStrings(num1, num2) {
    // Initialize variables to store the result and the carry
    let result = '';
    let carry = 0;
    // Initialize two pointers at the end of both strings
    let i = num1.length - 1;
    let j = num2.length - 1;
    // Loop through both strings from right to left
    while (i >= 0 || j >= 0 || carry) {
        // Calculate the sum of the current digits and the carry
        let sum = carry;
        if (i >= 0) sum += num1[i--] - '0';
        if (j >= 0) sum += num2[j--] - '0';
        // Update the result and the carry
        result = (sum % 10) + result;
        carry = Math.floor(sum / 10);
    }
    return result;
}

