function splitArray(nums, k) {
    // Calculate the total sum of the array and the maximum value in the array
    let left = Math.max(...nums), right = nums.reduce((a, b) => a + b, 0);
    // Perform binary search to find the minimum largest sum
    while (left < right) {
        // Calculate the mid value
        let mid = Math.floor((left + right) / 2);
        // Calculate the number of subarrays needed for the current mid value
        let count = 1, sum = 0;
        for (let num of nums) {
            // If the current sum plus the current number exceeds the mid value, start a new subarray
            if (sum + num > mid) {
                count++;
                sum = num;
            } else {
                // Otherwise, add the current number to the current sum
                sum += num;
            }
        }
        // If the number of subarrays needed is less than or equal to k, update the right boundary
        if (count <= k) {
            right = mid;
        } else {
            // Otherwise, update the left boundary
            left = mid + 1;
        }
    }
    // The minimum largest sum is the left boundary
    return left;
}

function canPartition(nums) {
    // calculate the total sum of the array
    let totalSum = nums.reduce((a, b) => a + b, 0);
    // if the total sum is odd, it's impossible to partition the array into two subsets with equal sum
    if (totalSum % 2 !== 0) return false;
    // calculate the target sum for each subset
    let targetSum = totalSum / 2;
    // create a dynamic programming array to store the possible sums
    let dp = new Array(targetSum + 1).fill(false);
    // base case: it's possible to get a sum of 0
    dp[0] = true;
    // iterate over the array and update the dynamic programming array
    for (let num of nums) {
        // iterate over the possible sums in reverse order to avoid overwriting previous results
        for (let i = targetSum; i >= num; i--) {
            // if it's possible to get a sum of i - num, then it's also possible to get a sum of i
            dp[i] = dp[i] || dp[i - num];
        }
    }
    // return whether it's possible to get a sum of targetSum
    return dp[targetSum];
}

function strongPasswordChecker(password) {
    // Calculate the missing types of characters
    let missingTypes = 3;
    if (/[a-z]/.test(password)) missingTypes--;
    if (/[A-Z]/.test(password)) missingTypes--;
    if (/[0-9]/.test(password)) missingTypes--;

    // Calculate the number of replacements needed for repeated characters
    let replacements = 0;
    let i = 2;
    while (i < password.length) {
        // Count the length of the current sequence
        let seqLength = 1;
        while (i < password.length && password[i] === password[i-1] && password[i] === password[i-2]) {
            i++;
            seqLength++;
        }
        // Calculate the number of replacements needed for the current sequence
        if (seqLength > 2) {
            replacements += Math.floor((seqLength - 2) / 3);
        }
        i++;
    }

    // Calculate the minimum number of steps required
    if (password.length < 6) {
        // Inserting characters can simultaneously satisfy missing-type requirements,
        // so it's the max of the two needs, not their sum.
        return Math.max(missingTypes, 6 - password.length);
    }

    let steps = Math.max(missingTypes, replacements);
    if (password.length > 20) {
        // If the password is too long, add the excess length
        steps += password.length - 20;
    }
    return steps;
}

function pacificAtlantic(heights) {
    // Get the number of rows and columns in the grid
    const rows = heights.length;
    const cols = heights[0].length;

    // Create sets to store the cells that can flow to the Pacific and Atlantic oceans
    const pacific = new Set();
    const atlantic = new Set();

    // Function to perform DFS from a given cell
    function dfs(row, col, ocean) {
        // Check if the cell is within the grid boundaries and has not been visited before
        if (row < 0 || row >= rows || col < 0 || col >= cols || ocean.has(`${row},${col}`)) return;

        // Add the cell to the set of cells that can flow to the ocean
        ocean.add(`${row},${col}`);

        // Perform DFS on the neighboring cells
        // Check if the neighboring cell's height is greater than or equal to the current cell's height
        if (row > 0 && heights[row - 1][col] >= heights[row][col]) dfs(row - 1, col, ocean);
        if (row < rows - 1 && heights[row + 1][col] >= heights[row][col]) dfs(row + 1, col, ocean);
        if (col > 0 && heights[row][col - 1] >= heights[row][col]) dfs(row, col - 1, ocean);
        if (col < cols - 1 && heights[row][col + 1] >= heights[row][col]) dfs(row, col + 1, ocean);
    }

    // Perform DFS from the cells on the Pacific Ocean's border
    for (let i = 0; i < rows; i++) dfs(i, 0, pacific);
    for (let j = 0; j < cols; j++) dfs(0, j, pacific);

    // Perform DFS from the cells on the Atlantic Ocean's border
    for (let i = 0; i < rows; i++) dfs(i, cols - 1, atlantic);
    for (let j = 0; j < cols; j++) dfs(rows - 1, j, atlantic);

    // Find the cells that can flow to both oceans
    const result = [];
    for (let cell of pacific) {
        if (atlantic.has(cell)) {
            // Convert the cell string back to an array of coordinates
            const [row, col] = cell.split(',').map(Number);
            result.push([row, col]);
        }
    }

    return result;
}

function findMaximumXOR(nums) {
  // Create a Trie to store the binary representation of numbers
  let trie = {};
  // Iterate over each number in the array
  for (let num of nums) {
    // Initialize the current node to the root of the Trie
    let node = trie;
    // Iterate over each bit in the binary representation of the number
    for (let i = 31; i >= 0; i--) {
      // Calculate the current bit
      let bit = (num >> i) & 1;
      // If the bit is not in the current node, add it
      if (!(bit in node)) node[bit] = {};
      // Move to the next node
      node = node[bit];
    }
  }
  // Initialize the maximum XOR result
  let maxResult = 0;
  // Iterate over each number in the array
  for (let num of nums) {
    // Initialize the current node to the root of the Trie
    let node = trie;
    // Initialize the current XOR result
    let currResult = 0;
    // Iterate over each bit in the binary representation of the number
    for (let i = 31; i >= 0; i--) {
      // Calculate the current bit
      let bit = (num >> i) & 1;
      // If the opposite bit is in the current node, use it to maximize the XOR result
      if (1 - bit in node) {
        // Update the current XOR result
        currResult |= (1 << i);
        // Move to the next node
        node = node[1 - bit];
      } else {
        // Move to the next node
        node = node[bit];
      }
    }
    // Update the maximum XOR result
    maxResult = Math.max(maxResult, currResult);
  }
  // Return the maximum XOR result
  return maxResult;
}

function characterReplacement(s, k) {
    let maxFrequency = 0, maxLength = 0, windowStart = 0;
    let frequencyMap = {};
    // iterate over the string and update frequency map
    for (let windowEnd = 0; windowEnd < s.length; windowEnd++) {
        let rightChar = s[windowEnd];
        if (!(rightChar in frequencyMap)) {
            frequencyMap[rightChar] = 0;
        }
        frequencyMap[rightChar]++;
        // update max frequency
        maxFrequency = Math.max(maxFrequency, frequencyMap[rightChar]);
        // if window size is greater than max frequency plus k, shrink the window
        if (windowEnd - windowStart + 1 > maxFrequency + k) {
            let leftChar = s[windowStart];
            frequencyMap[leftChar]--;
            windowStart++;
        }
        // update max length
        maxLength = Math.max(maxLength, windowEnd - windowStart + 1);
    }
    return maxLength;
}

function originalDigits(s) {
    // Create a frequency map of characters in the input string
    let charFrequency = {};
    for (let char of s) {
        if (!charFrequency[char]) charFrequency[char] = 0;
        charFrequency[char]++;
    }

    // Initialize the result string
    let result = '';

    // Determine the count of each digit based on unique characters
    // 'z' is unique to 'zero', 'w' is unique to 'two', 'u' is unique to 'four', 'x' is unique to 'six', 'g' is unique to 'eight'
    let zeroCount = charFrequency['z'] || 0; // 
    let twoCount = charFrequency['w'] || 0; // 
    let fourCount = charFrequency['u'] || 0; // 
    let sixCount = charFrequency['x'] || 0; // 
    let eightCount = charFrequency['g'] || 0; // 

    // 'h' can be in 'three' or 'eight', but we've already counted 'eight'
    let threeCount = (charFrequency['h'] || 0) - eightCount; // 
    threeCount = Math.max(threeCount, 0);

    // 'f' can be in 'four' or 'five', but we've already counted 'four'
    let fiveCount = (charFrequency['f'] || 0) - fourCount; // 
    fiveCount = Math.max(fiveCount, 0);

    // 's' can be in 'six' or 'seven', but we've already counted 'six'
    let sevenCount = (charFrequency['s'] || 0) - sixCount; // 
    sevenCount = Math.max(sevenCount, 0);

    // 'n' can be in 'one' or 'nine', but we've already counted 'nine' (indirectly through 'seven')
    let oneCount = (charFrequency['n'] || 0) - (sevenCount * 2); // 
    oneCount = Math.max(oneCount, 0);

    // 'i' can be in 'five', 'six', 'eight', or 'nine', but we've already counted 'five', 'six', and 'eight'
    let nineCount = (charFrequency['i'] || 0) - fiveCount - sixCount - eightCount; // 
    nineCount = Math.max(nineCount, 0);

    // Append the digits to the result string
    result += '0'.repeat(zeroCount);
    result += '1'.repeat(oneCount);
    result += '2'.repeat(twoCount);
    result += '3'.repeat(threeCount);
    result += '4'.repeat(fourCount);
    result += '5'.repeat(fiveCount);
    result += '6'.repeat(sixCount);
    result += '7'.repeat(sevenCount);
    result += '8'.repeat(eightCount);
    result += '9'.repeat(nineCount);

    return result;
}

function construct(grid) {
    function constructQuadTree(grid, x, y, n) {
        // Check if all elements in the grid are the same
        let isLeaf = true;
        let val = grid[x][y];
        for (let i = x; i < x + n; i++) {
            for (let j = y; j < y + n; j++) {
                if (grid[i][j] !== val) {
                    isLeaf = false;
                    break;
                }
            }
            if (!isLeaf) break;
        }
        if (isLeaf) {
            return [1, val];
        } else {
            // Divide the grid into four sub-grids
            let node = [0, 0];
            node.push(constructQuadTree(grid, x, y, n / 2));
            node.push(constructQuadTree(grid, x, y + n / 2, n / 2));
            node.push(constructQuadTree(grid, x + n / 2, y, n / 2));
            node.push(constructQuadTree(grid, x + n / 2, y + n / 2, n / 2));
            return node;
        }
    }
    return constructQuadTree(grid, 0, 0, grid.length);
}

function levelOrder(root) {
    // Initialize result array and queue with root node
    var result = [];
    if (!root) return result;
    var queue = [root];

    // Continue BFS traversal until queue is empty
    while (queue.length > 0) {
        // Store node values at current level
        var levelValues = [];
        // Store nodes at next level
        var nextLevelNodes = [];

        // Process all nodes at current level
        for (var i = 0; i < queue.length; i++) {
            // Add current node's value to level values
            levelValues.push(queue[i].val);
            // Add current node's children to next level nodes
            if (queue[i].children) {
                nextLevelNodes = nextLevelNodes.concat(queue[i].children);
            }
        }

        // Add current level values to result
        result.push(levelValues);
        // Update queue with next level nodes
        queue = nextLevelNodes;
    }

    return result;
}

function countBattleships(board) {
    let count = 0;
    for (let i = 0; i < board.length; i++) {
        for (let j = 0; j < board[0].length; j++) {
            // If the current cell is 'X' and it's not part of a previously counted battleship
            if (board[i][j] === 'X' && (i === 0 || board[i-1][j] === '.') && (j === 0 || board[i][j-1] === '.')) {
                count++; // Increment the count of battleships
            }
        }
    }
    return count;
}

function flatten(head) {
    if (!head) return head;
    const stack = [head];
    let prev = null;
    while (stack.length) {
        const cur = stack.pop();
        if (prev) {
            prev.next = cur;
            cur.prev = prev;
        }
        if (cur.next) stack.push(cur.next);
        if (cur.child) {
            stack.push(cur.child);
            cur.child = null;
        }
        prev = cur;
    }
    return head;
}

class Node {
    constructor(val, prev = null, next = null, child = null) {
        this.val = val;
        this.prev = prev;
        this.next = next;
        this.child = child;
    }
}

function toList(head) {
    const res = [];
    while (head) {
        res.push(head.val);
        head = head.next;
    }
    return res;
}

function link(...nodes) {
    for (let i = 0; i < nodes.length - 1; i++) {
        nodes[i].next = nodes[i + 1];
        nodes[i + 1].prev = nodes[i];
    }
    return nodes[0];
}

