function minMutation(startGene, endGene, bank) {
    // Create a set of valid genes for efficient lookups
    let validGenes = new Set(bank);
    // Initialize a queue with the starting gene and its distance
    let queue = [[startGene, 0]];
    // Create a set to keep track of visited genes
    let visited = new Set([startGene]);
    while (queue.length > 0) {
        // Dequeue the next gene and its distance
        let [currentGene, distance] = queue.shift();
        // If the current gene is the end gene, return the distance
        if (currentGene === endGene) return distance;
        // Generate all possible mutations of the current gene
        for (let i = 0; i < 8; i++) {
            // For each position, try all possible nucleotides
            for (let nucleotide of ['A', 'C', 'G', 'T']) {
                // Create a new gene by replacing the nucleotide at the current position
                let newGene = currentGene.substring(0, i) + nucleotide + currentGene.substring(i + 1);
                // If the new gene is valid and has not been visited, mark it as visited and enqueue it
                if (validGenes.has(newGene) && !visited.has(newGene)) {
                    queue.push([newGene, distance + 1]);
                    visited.add(newGene);
                }
            }
        }
    }
    // If there is no mutation from startGene to endGene, return -1
    return -1;
}

