function AllOne() {
    this.countMap = {};
    this.bucketMap = {};
    this.minCount = 1;
    this.maxCount = 1;
}

AllOne.prototype.inc = function(key) {
    if (this.countMap[key] !== undefined) {
        this.bucketMap[this.countMap[key]].delete(key);
        if (this.bucketMap[this.countMap[key]].size === 0 && this.minCount === this.countMap[key]) this.minCount++;
        this.countMap[key]++;
        if (this.bucketMap[this.countMap[key]] === undefined) this.bucketMap[this.countMap[key]] = new Set();
        this.bucketMap[this.countMap[key]].add(key);
        this.maxCount = Math.max(this.maxCount, this.countMap[key]);
    } else {
        this.countMap[key] = 1;
        if (this.bucketMap[1] === undefined) this.bucketMap[1] = new Set();
        this.bucketMap[1].add(key);
        this.minCount = 1;
        this.maxCount = Math.max(this.maxCount, 1);
    }
};

AllOne.prototype.dec = function(key) {
    if (this.countMap[key] !== undefined) {
        this.bucketMap[this.countMap[key]].delete(key);
        if (this.bucketMap[this.countMap[key]].size === 0 && this.maxCount === this.countMap[key]) this.maxCount--;
        this.countMap[key]--;
        if (this.countMap[key] > 0) {
            if (this.bucketMap[this.countMap[key]] === undefined) this.bucketMap[this.countMap[key]] = new Set();
            this.bucketMap[this.countMap[key]].add(key);
            this.minCount = Math.min(this.minCount, this.countMap[key]);
        } else {
            delete this.countMap[key];
            if (Object.keys(this.countMap).length === 0) {
                this.minCount = 1;
                this.maxCount = 1;
            } else {
                this.minCount = Math.min(...Object.keys(this.bucketMap).filter(k => this.bucketMap[k].size > 0).map(Number));
            }
        }
    }
};

AllOne.prototype.getMinKey = function() {
    // FIXED: must check the bucket actually has members, not just that the Set object exists
    if (this.bucketMap[this.minCount] !== undefined && this.bucketMap[this.minCount].size > 0) {
        return this.bucketMap[this.minCount].values().next().value;
    }
