};

function findRightInterval(intervals) {
    // Create a copy of the intervals array with their original indices
    var indexedIntervals = intervals.map(function(interval, index) { return [interval[0], interval[1], index]; });
    // Sort the intervals based on their start time
    indexedIntervals.sort(function(a, b) { return a[0] - b[0]; });
    var result = new Array(intervals.length);
    // Iterate over each interval in the original array
    for (var i = 0; i < intervals.length; i++) {
        // Use binary search to find the first interval in the sorted array that ends after the current interval starts
        var left = 0, right = indexedIntervals.length - 1;
        while (left <= right) {
            var mid = Math.floor((left + right) / 2);
            // If the middle interval's start time is greater than or equal to the current interval's end time, update the right pointer
            if (indexedIntervals[mid][0] >= intervals[i][1]) {
                right = mid - 1;
            } 
            // If the middle interval's start time is less than the current interval's end time, update the left pointer
            else {
                left = mid + 1;
            }
        }
        // If an interval is found that ends after the current interval starts, store its original index in the result array
        if (left < indexedIntervals.length) {
            result[i] = indexedIntervals[left][2];
        } 
        // If no such interval is found, store -1 in the result array
        else {
            result[i] = -1;
        }
    }
    return result;
}

function pathSum(root, targetSum) {
    // Initialize count of paths that sum to targetSum
    let count = 0;
    // Define a helper function to perform DFS
    function dfs(node, currentSum) {
        // Base case: if node is null, return
        if (node === null) return;
        // Update currentSum and check if it equals targetSum
        currentSum += node.val;
        // If currentSum equals targetSum, increment count
        if (currentSum === targetSum) count++;
        // Recursively call dfs on left and right subtrees
        dfs(node.left, currentSum);
        dfs(node.right, currentSum);
    }
    // Define another helper function to traverse the tree
    function traverse(node) {
        // Base case: if node is null, return
        if (node === null) return;
        // Call dfs on current node
        dfs(node, 0);
        // Recursively call traverse on left and right subtrees
        traverse(node.left);
        traverse(node.right);
    }
    // Call traverse on the root node
    traverse(root);
    // Return the count of paths that sum to targetSum
    return count;
}

function findAnagrams(s, p) {
    // Create a hash map to store the frequency of characters in string p
    var pCount = {};
    for (var i = 0; i < p.length; i++) {
        // Count the frequency of each character in string p
        if (pCount[p[i]]) pCount[p[i]]++;
        else pCount[p[i]] = 1;
    }

    // Initialize variables to store the result and the count of characters in the current window
    var result = [];
    var windowCount = {};
    var requiredChars = Object.keys(pCount).length;
    var formedChars = 0;

    // Initialize the window boundaries
    var left = 0;

    // Traverse the string s
    for (var right = 0; right < s.length; right++) {
        // Add the character at the right boundary to the window count
        var character = s[right];
        if (pCount[character]) {
            // If the character is in p, update the window count and the formed characters count
            if (windowCount[character]) windowCount[character]++;
            else windowCount[character] = 1;
            if (windowCount[character] === pCount[character]) formedChars++;
        }

        // If the window size is greater than the size of string p, remove characters from the left boundary
        while (right - left + 1 > p.length) {
            // Remove the character at the left boundary from the window count
            var character = s[left];
            if (pCount[character]) {
                // If the character is in p, update the window count and the formed characters count
                windowCount[character]--;
                if (windowCount[character] < pCount[character]) formedChars--;
            }
            left++;
        }

        // If the window size is equal to the size of string p and all characters are formed, add the left boundary to the result
        if (right - left + 1 === p.length && formedChars === requiredChars) {
            // Add the start index of the anagram to the result
            result.push(left);
        }
    }

    return result;
}

function findKthNumber(n, k) {
  let cur = 1; // start from the smallest number
  k--; // subtract 1 because we are 1-indexed
  while (k > 0) {
    // calculate the number of nodes in the current level
    let step = 0, first = cur, last = cur + 1;
    while (first <= n) {
      // calculate the number of nodes in the current level
      step += Math.min(n + 1, last) - first;
      first *= 10; // move to the next level
      last *= 10; // move to the next level
    }
    // if k is larger than the number of nodes in the current level, move to the next level
    if (k >= step) {
      // move to the next level
      k -= step;
      cur++;
    } else {
      // move to the next node in the current level
      k--;
      cur *= 10;
    }
  }
  return cur;
}

function arrangeCoins(n) {
    // Using binary search to find the number of complete rows
    let left = 1, right = n;
    while (left <= right) {
        // Calculating the middle value
        let mid = Math.floor((left + right) / 2);
        // Calculating the total coins required for mid rows
        let totalCoins = Math.floor(mid * (mid + 1) / 2);
        // If total coins is less than or equal to n, update left
        if (totalCoins <= n) {
            left = mid + 1;
        } 
        // If total coins is greater than n, update right
        else {
            right = mid - 1;
        }
    }
    // The number of complete rows is the value of right
    return right;
}

function compress(chars) {
  let writeIndex = 0; 
  let count = 1; 
  // iterate over the input array and count consecutive repeating characters
  for (let readIndex = 1; readIndex <= chars.length; readIndex++) {
    if (readIndex === chars.length || chars[readIndex] !== chars[readIndex - 1]) {
      // write the character to the input array
      chars[writeIndex++] = chars[readIndex - 1];
      // write the count to the input array, handling counts 10 or longer
      if (count > 1) {
        // convert the count to a string to handle counts 10 or longer
        let countStr = count.toString();
        for (let i = 0; i < countStr.length; i++) {
          chars[writeIndex++] = countStr[i];
        }
      }
      // reset the count for the next group of characters
      count = 1;
    } else {
      // increment the count for the current group of characters
      count++;
    }
  }
  // return the new length of the input array
  return writeIndex;
}

function eraseOverlapIntervals(intervals) {
  // If the input array is empty, return 0
  if (intervals.length === 0) return 0;

  // Sort the intervals based on their end points
  intervals.sort(function(a, b) { return a[1] - b[1]; });

  // Initialize the count of non-overlapping intervals and the end point of the last non-overlapping interval
  let count = 1, lastEnd = intervals[0][1];

  // Iterate over the intervals
  for (let i = 1; i < intervals.length; i++) {
    // If the current interval does not overlap with the last non-overlapping interval, increment the count and update the last end point
    if (intervals[i][0] >= lastEnd) { count++; lastEnd = intervals[i][1]; }
  }

  // The minimum number of intervals to remove is the total number of intervals minus the count of non-overlapping intervals
  return intervals.length - count;
}

function findDuplicates(nums) {
    // Initialize an empty array to store the duplicates
    var duplicates = [];
    // Iterate over the input array
    for (var i = 0; i < nums.length; i++) {
        // Use the absolute value of the current number as an index to mark it as visited
        var index = Math.abs(nums[i]) - 1;
        // If the number at the marked index is negative, it means we've seen this number before
        if (nums[index] < 0) {
            // Add the absolute value of the current number to the duplicates array
            duplicates.push(Math.abs(nums[i]));
        } else {
            // Mark the number at the marked index as negative to indicate it's been visited
            nums[index] = -nums[index];
        }
    }
    // Return the array of duplicates
    return duplicates;
}

function numberOfArithmeticSlices(nums) {
    var n = nums.length;
    var result = 0;
    // Initialize a map to store the difference and its count for each number
    var dp = new Array(n);
    for (var i = 0; i < n; i++) {
        dp[i] = new Map();
    }
    // Iterate over the array to find all possible arithmetic subsequences
    for (var i = 0; i < n; i++) {
        for (var j = 0; j < i; j++) {
            // Calculate the difference between the current and previous numbers
            var diff = nums[i] - nums[j];
            // Update the count of the difference in the map
            result += dp[j].get(diff) || 0;
            // Update the count of the difference in the map for the current number
            dp[i].set(diff, (dp[i].get(diff) || 0) + (dp[j].get(diff) || 0) + 1);
        }
    }
    return result;
}

function numberOfBoomerangs(points) {
  let totalBoomerangs = 0;
  // iterate over each point to calculate distances to other points
  for (let i = 0; i < points.length; i++) {
    let distanceMap = {};
    // calculate distance from current point to all other points
    for (let j = 0; j < points.length; j++) {
      if (i === j) continue;
      let distance = Math.pow(points[i][0] - points[j][0], 2) + Math.pow(points[i][1] - points[j][1], 2);
      // count occurrences of each distance
      distanceMap[distance] = (distanceMap[distance] || 0) + 1;
    }
    // calculate boomerangs for each distance
    for (let distance in distanceMap) {
      let count = distanceMap[distance];
      // for each distance, the number of boomerangs is the number of ways to choose 2 points from the count of points with that distance
      totalBoomerangs += count * (count - 1);
    }
  }
  return totalBoomerangs;
}

function findDisappearedNumbers(nums) {
