}

function addTwoNumbers(l1, l2) {
    let arr1 = [], arr2 = [];
    while (l1) { arr1.push(l1.val); l1 = l1.next; }
    while (l2) { arr2.push(l2.val); l2 = l2.next; }
    arr1 = arr1.reverse(); arr2 = arr2.reverse();
    let result = [], carry = 0;
    while (arr1.length > 0 || arr2.length > 0 || carry > 0) {
        let digit1 = arr1.length > 0 ? arr1.shift() : 0;
        let digit2 = arr2.length > 0 ? arr2.shift() : 0;
        let sum = digit1 + digit2 + carry;
        carry = Math.floor(sum / 10);
        result.push(sum % 10);
    }
    result = result.reverse(); // result was built least-significant-digit-first; flip to MSB-first
    let dummy = new ListNode(0);
    let current = dummy;
    for (let i = 0; i < result.length; i++) {
        current.next = new ListNode(result[i]);
        current = current.next;
    }
    return dummy.next;
}

function deleteNode(root, key) {
    // base case: if tree is empty, return null
    if (root === null) return null;
    // if key is less than current node's value, recursively call deleteNode on left subtree
    if (key < root.val) root.left = deleteNode(root.left, key);
    // if key is greater than current node's value, recursively call deleteNode on right subtree
    else if (key > root.val) root.right = deleteNode(root.right, key);
    // if key matches current node's value, handle deletion
    else {
        // case 1: no children, simply return null
        if (root.left === null && root.right === null) return null;
        // case 2: one child, return that child
        if (root.left === null) return root.right;
        if (root.right === null) return root.left;
        // case 3: two children, find in-order successor (smallest node in right subtree) and replace current node's value
        let minNode = root.right;
        while (minNode.left !== null) minNode = minNode.left;
        root.val = minNode.val;
        // delete in-order successor
        root.right = deleteNode(root.right, minNode.val);
    }
    return root;
}

function frequencySort(s) {
    // Create a hash map to store the frequency of each character
    var frequencyMap = {};
    for (var i = 0; i < s.length; i++) {
        // If the character is already in the map, increment its count
        if (frequencyMap[s[i]]) {
            frequencyMap[s[i]]++;
        } else {
            // Otherwise, add it to the map with a count of 1
            frequencyMap[s[i]] = 1;
        }
    }

    // Create an array of characters and their frequencies
    var frequencyArray = [];
    for (var key in frequencyMap) {
        // Add each character and its frequency to the array
        frequencyArray.push([key, frequencyMap[key]]);
    }

    // Sort the array in descending order based on the frequency
    frequencyArray.sort(function(a, b) {
        // Compare the frequencies of two characters
        return b[1] - a[1];
    });

    // Create the sorted string
    var sortedString = '';
    for (var i = 0; i < frequencyArray.length; i++) {
        // Append each character to the string a number of times equal to its frequency
        for (var j = 0; j < frequencyArray[i][1]; j++) {
            sortedString += frequencyArray[i][0];
        }
    }

    return sortedString;
}

function minMoves(nums) {
  // find the minimum element in the array as the target value
  var minVal = Math.min.apply(Math, nums);
  // calculate the total difference between each element and the minimum element
  var totalDiff = 0;
  for (var i = 0; i < nums.length; i++) {
    // add the difference between the current element and the minimum element to the total difference
    totalDiff += nums[i] - minVal;
  }
  // return the total difference as the minimum number of moves required
  return totalDiff;
}

function findMinArrowShots(points) {
