  points.sort(function(a, b) { return a[1] - b[1]; });
  var arrows = 1;
  var currentEnd = points[0][1];
  // Iterate through the sorted balloons and count the number of arrows needed
  for (var i = 1; i < points.length; i++) {
    // If the current balloon's start point is greater than the current end point, a new arrow is needed
    if (points[i][0] > currentEnd) {
      arrows++;
      currentEnd = points[i][1];
    }
  }
  return arrows;
}

function find132pattern(nums) {
    let n = nums.length;
    let stack = [];
    let s3 = -Infinity; // the largest value seen so far
    for (let i = n - 1; i >= 0; i--) { // iterate through the array from right to left
        // if current element is less than s3, we found a 132 pattern
        if (nums[i] < s3) return true;
        // while the stack is not empty and the top of the stack is less than the current element
        while (stack.length > 0 && stack[stack.length - 1] < nums[i]) { 
            // update s3 to be the top of the stack
            s3 = stack.pop();
        }
        // push the current element onto the stack
        stack.push(nums[i]);
    }
    // if we reach this point, no 132 pattern was found
    return false;
}

function serialize(root) {
    // Preorder traversal to serialize the tree
    if (!root) return 'X,';
    return root.val + ',' + serialize(root.left) + serialize(root.right);
}

function deserialize(data) {
    // Split the serialized string into an array
    let nodes = data.split(',');
    let index = 0;
    // Recursive function to deserialize the tree
    function buildTree() {
        // If the current node is 'X', return null
        if (nodes[index] === 'X') {
            index++;
            return null;
        }
        // Create a new node with the current value
        let node = { val: parseInt(nodes[index]), left: null, right: null };
        index++;
        // Recursively build the left and right subtrees
        node.left = buildTree();
        node.right = buildTree();
        return node;
    }
    return buildTree();
}

function findContentChildren(g, s) {
    // Sort the greed factors and cookie sizes in ascending order
    g.sort((a, b) => a - b);
    s.sort((a, b) => a - b);
    let childIndex = 0, cookieIndex = 0;
    // Iterate through the sorted arrays and assign cookies to children
    while (childIndex < g.length && cookieIndex < s.length) {
        // If the current cookie can satisfy the current child's greed factor, move to the next child
        if (s[cookieIndex] >= g[childIndex]) childIndex++;
        // Move to the next cookie
        cookieIndex++;
    }
    // The number of content children is the number of children that were assigned a cookie
    return childIndex;
}

function poorPigs(buckets, minutesToDie, minutesToTest) {
    // calculate the number of states a pig can be in
    let states = Math.floor(minutesToTest / minutesToDie) + 1;
    // calculate the minimum number of pigs needed using the formula for the minimum number of pigs
    let pigs = Math.ceil(Math.log(buckets) / Math.log(states));
    return pigs;
}

function circularArrayLoop(nums) {
  for (let i = 0; i < nums.length; i++) {
    let slow = i, fast = i;
    let direction = nums[i] > 0;
    do {
      slow = findNextIndex(nums, slow, direction);
      if (slow === -1) break;
      fast = findNextIndex(nums, fast, direction);
      if (fast === -1) break;
      fast = findNextIndex(nums, fast, direction);
      if (fast === -1) break;
    } while (slow !== fast);
    if (slow !== -1 && slow === fast) {
      if (hasCycle(nums, slow, direction)) return true;
    }
  }
  return false;
}
function findNextIndex(nums, currentIndex, direction) {
  let nextIndex = (currentIndex + nums[currentIndex]) % nums.length;
  if (nextIndex < 0) nextIndex += nums.length;
  if ((nums[currentIndex] > 0) === direction) return nextIndex;
  return -1;
}
function hasCycle(nums, start, direction) {
  let current = start, next = findNextIndex(nums, start, direction);
  // a cycle that loops back to its own start in one step is a length-1 self-loop, not valid
  if (next === -1 || next === start) return false;
  while (next !== start) {
    if (next === -1) return false;
    current = next;
    next = findNextIndex(nums, current, direction);
  }
  return true;
}

function fourSumCount(nums1, nums2, nums3, nums4) {
    let count = 0;
    let n = nums1.length;
    let map = {};
    // Create a hash map to store the sum of elements from nums1 and nums2
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            let sum = nums1[i] + nums2[j];
            if (map[sum] === undefined) {
                map[sum] = 1;
            } else {
                map[sum]++;
            }
        }
    }
    // Use the hash map to count the number of tuples with sum equal to 0
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            let sum = nums3[i] + nums4[j];
            if (map[-sum] !== undefined) {
                // If the negative sum is in the map, increment the count
                count += map[-sum];
            }
        }
    }
    return count;
}

function repeatedSubstringPattern(s) {
  // check if the string can be constructed by taking a substring and appending multiple copies of it
  for (let i = 1; i <= s.length / 2; i++) {
    if (s.length % i === 0) {
      let substring = s.substring(0, i);
      let repeatedSubstring = '';
      for (let j = 0; j < s.length / i; j++) {
        repeatedSubstring += substring;
      }
      if (repeatedSubstring === s) {
        return true;
      }
    }
  }
  return false;
}

function hammingDistance(x, y) {
  // calculate the XOR of x and y to get the bits that are different
  let diff = x ^ y;
  // initialize a counter for the number of different bits
  let count = 0;
  // loop until there are no more different bits
  while (diff) {
    // count the least significant bit
    count += diff & 1;
    // shift the bits to the right
    diff >>= 1;
  }
  return count;
}

