function DoublyLinkedList() {
    this.head = new Node(0, 0, 0);
    this.tail = new Node(0, 0, 0);
    this.head.next = this.tail;
    this.tail.prev = this.head;
    this.size = 0;
}
DoublyLinkedList.prototype.add = function(node) {
    node.prev = this.tail.prev;
    node.next = this.tail;
    this.tail.prev.next = node;
    this.tail.prev = node;
    this.size++;
};
DoublyLinkedList.prototype.remove = function(node) {
    node.prev.next = node.next;
    node.next.prev = node.prev;
    this.size--;
};
DoublyLinkedList.prototype.delete = function(node) {
    node.prev.next = node.next;
    node.next.prev = node.prev;
    this.size--;
};

function LFUCache(capacity) {
    this.capacity = capacity;
    this.keyMap = new Map();
    this.freqMap = new Map();
    this.minFreq = 1;
}

LFUCache.prototype.get = function(key) {
    if (!this.keyMap.has(key)) return -1;
    let node = this.keyMap.get(key);
    this.freqMap.get(node.freq).delete(node);
    if (this.freqMap.get(node.freq).size === 0) {
        this.freqMap.delete(node.freq);
        if (this.minFreq === node.freq) this.minFreq++;
    }
    node.freq++;
    if (!this.freqMap.has(node.freq)) this.freqMap.set(node.freq, new DoublyLinkedList());
    this.freqMap.get(node.freq).add(node);
    this.keyMap.set(key, node);
    return node.val;
};

LFUCache.prototype.put = function(key, value) {
    if (this.capacity === 0) return;
    if (this.keyMap.has(key)) {
        let node = this.keyMap.get(key);
        node.val = value;
        this.get(key);
        return;
    }
    if (this.keyMap.size === this.capacity) {
        let minFreqList = this.freqMap.get(this.minFreq);
        // FIXED: was minFreqList.tail (the dummy sentinel, crashes); head.next
        // is the true least-recently-used real node in this frequency bucket
        let node = minFreqList.head.next;
        this.keyMap.delete(node.key);
        minFreqList.remove(node);
        if (minFreqList.size === 0) this.freqMap.delete(this.minFreq);
    }
    let newNode = new Node(key, value, 1);
    if (!this.freqMap.has(1)) this.freqMap.set(1, new DoublyLinkedList());
    this.freqMap.get(1).add(newNode);
    this.keyMap.set(key, newNode);
    this.minFreq = 1;
};

function minMoves2(nums) {
  // Sort the array to easily find the median
  nums.sort((a, b) => a - b);
  // Find the median of the array, which is the optimal target value
  var median = nums[Math.floor(nums.length / 2)];
  // Initialize the count of moves
  var moves = 0;
  // Calculate the total moves required to make all elements equal to the median
  for (var i = 0; i < nums.length; i++) {
