    moves += Math.abs(nums[i] - median);
  }
  return moves;
}

function islandPerimeter(grid) {
    let perimeter = 0;
    // iterate over each cell in the grid to check for land cells
    for (let i = 0; i < grid.length; i++) {
        for (let j = 0; j < grid[0].length; j++) {
            // if the current cell is a land cell
            if (grid[i][j] === 1) {
                // check the top edge of the cell
                if (i === 0 || grid[i - 1][j] === 0) {
                    perimeter++; // increment perimeter if the top edge is adjacent to water or the grid boundary
                }
                // check the bottom edge of the cell
                if (i === grid.length - 1 || grid[i + 1][j] === 0) {
                    perimeter++; // increment perimeter if the bottom edge is adjacent to water or the grid boundary
                }
                // check the left edge of the cell
                if (j === 0 || grid[i][j - 1] === 0) {
                    perimeter++; // increment perimeter if the left edge is adjacent to water or the grid boundary
                }
                // check the right edge of the cell
                if (j === grid[0].length - 1 || grid[i][j + 1] === 0) {
                    perimeter++; // increment perimeter if the right edge is adjacent to water or the grid boundary
                }
            }
        }
    }
    return perimeter;
}

function getMaxRepetitions(s1, n1, s2, n2) {
  // Create a 2D array to store the dynamic programming table
  let dp = Array(s2.length + 1).fill(0).map(() => Array(s1.length + 1).fill(0));

  // Initialize the base case
  for (let i = 0; i <= s1.length; i++) {
    dp[0][i] = 0;
  }

  // Fill the dynamic programming table
  for (let i = 1; i <= s2.length; i++) {
    for (let j = 1; j <= s1.length; j++) {
      // If the current character in s2 matches the current character in s1
      if (s2[i - 1] === s1[j - 1]) {
        // Update the dynamic programming table
        dp[i][j] = dp[i - 1][j - 1] + 1;
      } else {
        // If the characters do not match, use the previous value
        dp[i][j] = dp[i][j - 1];
      }
    }
  }

  // Calculate the maximum number of repetitions
  let maxRepetitions = 0;
  for (let i = 1; i <= s1.length; i++) {
    // If the entire string s2 can be obtained from the current substring of s1
    if (dp[s2.length][i] === s2.length) {
      // Update the maximum number of repetitions
      maxRepetitions = Math.max(maxRepetitions, Math.floor((n1 * i) / s1.length));
    }
  }

  // Return the maximum number of repetitions
  return Math.floor(maxRepetitions / n2);
}

function validIPAddress(queryIP) {
    // Check if the IP address is IPv4
    if (queryIP.includes('.')) {
        // Split the IP address into its parts
        let parts = queryIP.split('.');
        // Check if the IP address has 4 parts
        if (parts.length !== 4) return "Neither";
        // Check each part of the IP address
        for (let part of parts) {
            // Check if the part is a number and is between 0 and 255
            if (isNaN(part) || part < 0 || part > 255 || (part.length > 1 && part[0] === '0')) return "Neither";
        }
        // If all checks pass, return "IPv4"
        return "IPv4";
    }
    // Check if the IP address is IPv6
    else if (queryIP.includes(':')) {
        // Split the IP address into its parts
        let parts = queryIP.split(':');
        // Check if the IP address has 8 parts
        if (parts.length !== 8) return "Neither";
        // Check each part of the IP address
        for (let part of parts) {
            // Check if the part is a hexadecimal number and is between 0 and FFFF
            if (part.length > 4 || !/^[0-9a-fA-F]+$/.test(part)) return "Neither";
        }
        // If all checks pass, return "IPv6"
        return "IPv6";
    }
    // If the IP address is neither IPv4 nor IPv6, return "Neither"
    else return "Neither";
}

function findSubstringInWraproundString(s) {
    // Initialize a set to store unique substrings
    let uniqueSubstrings = new Set();
    // Initialize a variable to store the current substring
    let currentSubstring = '';
    // Iterate over the string
    for (let i = 0; i < s.length; i++) {
        // If the current character is the next character in the alphabet or it's the first character, add it to the current substring
        if (i === 0 || (s.charCodeAt(i) - s.charCodeAt(i - 1) === 1) || (s.charCodeAt(i) - s.charCodeAt(i - 1) === -25)) {
            currentSubstring += s[i];
        } else {
            // If the current character is not the next character in the alphabet, add all substrings of the current substring to the set
            for (let j = 0; j < currentSubstring.length; j++) {
                for (let k = j + 1; k <= currentSubstring.length; k++) {
                    uniqueSubstrings.add(currentSubstring.substring(j, k));
                }
            }
            // Reset the current substring
            currentSubstring = s[i];
        }
    }
    // Add all substrings of the last current substring to the set
    for (let j = 0; j < currentSubstring.length; j++) {
        for (let k = j + 1; k <= currentSubstring.length; k++) {
            uniqueSubstrings.add(currentSubstring.substring(j, k));
        }
    }
    // Return the number of unique substrings
    return uniqueSubstrings.size;
}

function findAllConcatenatedWordsInADict(words) {
  let wordSet = new Set(words);
  function isConcatenated(word) {
    const n = word.length;
    let dp = new Array(n + 1).fill(false);
    dp[0] = true;
    for (let i = 1; i <= n; i++) {
      for (let j = 0; j < i; j++) {
        if (!dp[j]) continue;
        if (j === 0 && i === n) continue; // disallow matching the whole word as a single piece
        if (wordSet.has(word.substring(j, i))) {
          dp[i] = true;
          break;
        }
      }
    }
    return dp[n];
  }
  return words.filter(word => word.length > 0 && isConcatenated(word));
}

function makesquare(matchsticks) {
    let totalLength = 0;
    for (let i = 0; i < matchsticks.length; i++) {
        totalLength += matchsticks[i];
    }
    if (totalLength % 4 !== 0) return false;
    let sideLength = totalLength / 4;
    let sides = new Array(4).fill(0);
    matchsticks.sort((a, b) => b - a);
    function backtrack(index) {
        // if we've used all matchsticks and formed a square, return true
        if (index === matchsticks.length) return sides[0] === sideLength && sides[1] === sideLength && sides[2] === sideLength && sides[3] === sideLength;
        for (let i = 0; i < 4; i++) {
            // if adding the current matchstick to the current side would exceed the side length, skip it
            if (sides[i] + matchsticks[index] > sideLength) continue;
            sides[i] += matchsticks[index];
            // recursively try adding the next matchstick to each side
            if (backtrack(index + 1)) return true;
            sides[i] -= matchsticks[index];
        }
        return false;
    }
    return backtrack(0);
}

function canIWin(maxChoosableInteger, desiredTotal) {
    if (desiredTotal <= 0) return true;
    let sum = (maxChoosableInteger * (maxChoosableInteger + 1)) / 2;
    if (sum < desiredTotal) return false;
    if (sum == desiredTotal && maxChoosableInteger % 2 == 1) return true;
    let memo = new Map();
    function dp(mask, remainingTotal) {
        if (memo.has(mask)) return memo.get(mask);
        for (let i = 1; i <= maxChoosableInteger; i++) {
            let bitMask = 1 << (i - 1);
            if ((mask & bitMask) == 0 && remainingTotal >= i) {
                if (!dp(mask | bitMask, remainingTotal - i)) {
                    memo.set(mask, true);
                    return true;
                }
            }
        }
        memo.set(mask, false);
        return false;
    }
    return dp(0, desiredTotal);
}

function findMaxForm(strs, m, n) {
    // Initialize a 3D DP array to store the maximum subset size for each possible count of 0's and 1's
    let dp = Array(m + 1).fill(0).map(() => Array(n + 1).fill(0));

    // Iterate over each binary string
    for (let str of strs) {
        // Count the number of 0's and 1's in the current string
        let zeros = 0, ones = 0;
        for (let char of str) {
            if (char === '0') zeros++;
            else ones++;
        }

        // Iterate over the DP array in reverse order to avoid overwriting previously computed values
        for (let i = m; i >= zeros; i--) {
            for (let j = n; j >= ones; j--) {
                // Update the maximum subset size for the current count of 0's and 1's
                dp[i][j] = Math.max(dp[i][j], dp[i - zeros][j - ones] + 1);
            }
        }
    }

    // The maximum subset size is stored in the last cell of the DP array
    return dp[m][n];
}

