function findComplement(num) {
    // calculate the number of bits in num
    let bits = Math.floor(Math.log2(num)) + 1;
    // create a mask with all bits set to 1, with the same number of bits as num
    let mask = (1 << bits) - 1;
    // flip all the bits in num using the XOR operator
    return num ^ mask;
}

