function totalHammingDistance(nums) {
  let totalDistance = 0;
  // calculate the number of bits to consider
  let maxNum = Math.max(...nums);
  let maxBits = Math.floor(Math.log2(maxNum)) + 1;

  // for each bit position
  for (let bit = 0; bit < maxBits; bit++) {
    // count the number of ones and zeros at this bit position
    let ones = 0, zeros = 0;
    for (let num of nums) {
      // check if the bit is set
      if ((num >> bit) & 1) ones++;
      else zeros++;
    }
    // add the product of ones and zeros to the total distance
    totalDistance += ones * zeros;
  }
  return totalDistance;
}

function medianSlidingWindow(nums, k) {
    // Create a min-heap and a max-heap to store the larger and smaller halves of the window
    let minHeap = [], maxHeap = [];
    let result = [];

    // Iterate over the array
    for (let i = 0; i < nums.length; i++) {
        // Add the current number to the heaps
        if (maxHeap.length === 0 || nums[i] < -maxHeap[0]) {
            // Add to max-heap
            maxHeap.push(-nums[i]);
            maxHeap.sort((a, b) => a - b);
        } else {
            // Add to min-heap
            minHeap.push(nums[i]);
            minHeap.sort((a, b) => a - b);
        }

        // Balance the heaps
        if (maxHeap.length > minHeap.length + 1) {
            // Move the largest number from max-heap to min-heap
            minHeap.push(-maxHeap.shift());
            minHeap.sort((a, b) => a - b);
        } else if (minHeap.length > maxHeap.length) {
            // Move the smallest number from min-heap to max-heap
            maxHeap.push(-minHeap.shift());
            maxHeap.sort((a, b) => a - b);
        }

        // If the window is full, calculate the median
        if (i >= k - 1) {
            // Calculate the median
            if (k % 2 === 0) {
                // If the window size is even, the median is the average of the two middle numbers
                result.push((-maxHeap[0] + minHeap[0]) / 2);
            } else {
                // If the window size is odd, the median is the middle number
                result.push(-maxHeap[0]);
            }

            // Remove the number that is out of the window from the heaps
            if (nums[i - k + 1] <= -maxHeap[0]) {
                // Remove from max-heap
                maxHeap.splice(maxHeap.indexOf(-nums[i - k + 1]), 1);
                maxHeap.sort((a, b) => a - b);
            } else {
                // Remove from min-heap
                minHeap.splice(minHeap.indexOf(nums[i - k + 1]), 1);
                minHeap.sort((a, b) => a - b);
            }

            // Balance the heaps again
            if (maxHeap.length > minHeap.length + 1) {
                // Move the largest number from max-heap to min-heap
                minHeap.push(-maxHeap.shift());
                minHeap.sort((a, b) => a - b);
            } else if (minHeap.length > maxHeap.length) {
                // Move the smallest number from min-heap to max-heap
                maxHeap.push(-minHeap.shift());
                maxHeap.sort((a, b) => a - b);
            }
        }
    }

    return result;
}

function largestPalindromeProduct(n) {
    // Calculate the minimum and maximum n-digit numbers
    let min = Math.pow(10, n - 1);
    let max = Math.pow(10, n) - 1;

    // Initialize the result
    let result = 0;

    // Iterate over all possible pairs of n-digit numbers in descending order
    for (let i = max; i >= min; i--) {
        // For each number i, start from i and go down to min
        for (let j = i; j >= min; j--) {
            // Calculate the product of i and j
            let product = i * j;

            // Check if the product is a palindrome and is larger than the current result
            if (isPalindrome(product) && product > result) {
                // Update the result
                result = product;
            }

            // If the product is less than the current result, break the loop
            if (product < result) {
                break;
            }
        }
    }

    // Return the result modulo 1337
    return result % 1337;
}

