function magicalString(n) {
    // Initialize the magical string with the first three elements
    let magicalString = [1, 2, 2];
    // Initialize the index for the next group size
    let nextGroupSizeIndex = 2;
    // Continue generating the magical string until it has n elements
    while (magicalString.length < n) {
        // Get the next group size from the magical string
        let nextGroupSize = magicalString[nextGroupSizeIndex];
        // Get the next group value (1 if the last group was 2, and vice versa)
        let nextGroupValue = magicalString[magicalString.length - 1] === 1 ? 2 : 1;
        // Add the next group to the magical string
        for (let i = 0; i < nextGroupSize; i++) {
            magicalString.push(nextGroupValue);
        }
        // Move to the next group size index
        nextGroupSizeIndex++;
    }
    // Count the number of 1's in the first n elements of the magical string
    let count = 0;
    for (let i = 0; i < n; i++) {
        // If the current element is 1, increment the count
        if (magicalString[i] === 1) count++;
    }
    return count;
}

function licenseKeyFormatting(s, k) {
