    var str = s.replace(/-/g, '').toUpperCase();
    // Calculate the length of the first group
    var firstGroupLength = str.length % k;
    // If the first group length is 0, set it to k
    if (firstGroupLength === 0) firstGroupLength = k;
    // Initialize the result string with the first group
    var result = str.substring(0, firstGroupLength);
    // Loop through the rest of the string and add groups of k characters
    for (var i = firstGroupLength; i < str.length; i += k) {
