}

function smallestGoodBase(n) {
    const num = BigInt(n);
    const maxLen = Math.floor(Math.log(Number(num)) / Math.log(2)) + 1;
    for (let len = maxLen; len >= 2; len--) {
        let left = 2n, right = num - 1n;
        while (left <= right) {
            const mid = (left + right) / 2n;
            let sum = 0n;
            for (let i = 0; i < len; i++) {
                sum = sum * mid + 1n;
            }
            if (sum === num) {
                return mid.toString();
            } else if (sum < num) {
                left = mid + 1n;
            } else {
                right = mid - 1n;
            }
        }
    }
    return (num - 1n).toString();
}

function findRadius(houses, heaters) {
    // Sort houses and heaters arrays in ascending order
    houses.sort((a, b) => a - b);
    heaters.sort((a, b) => a - b);

    // Initialize variables to store the result and the index of the current heater
    let result = 0;
    let heaterIndex = 0;

    // Iterate over each house
    for (let i = 0; i < houses.length; i++) {
        // While the current heater is not the closest one to the current house, move to the next heater
        while (heaterIndex < heaters.length - 1 && Math.abs(heaters[heaterIndex + 1] - houses[i]) <= Math.abs(heaters[heaterIndex] - houses[i])) {
            heaterIndex++;
        }
        // Update the result with the maximum distance between the current house and the closest heater
        result = Math.max(result, Math.abs(heaters[heaterIndex] - houses[i]));
    }

    // Return the minimum radius standard of heaters
    return result;
}

function PredictTheWinner(nums) {
    // The algorithm solution is already optimal, using dynamic programming to store the maximum score difference
    let n = nums.length;
    let dp = new Array(n).fill(0).map(() => new Array(n).fill(0));
    for (let i = 0; i < n; i++) {
        dp[i][i] = nums[i];
    }
    for (let length = 1; length < n; length++) {
        for (let i = 0; i < n - length; i++) {
            let j = i + length;
            // Calculate the maximum score difference by considering the two possible moves
            dp[i][j] = Math.max(nums[i] - dp[i + 1][j], nums[j] - dp[i][j - 1]);
        }
    }
    // Return true if the maximum score difference is non-negative
    return dp[0][n - 1] >= 0;
}

function findMaxConsecutiveOnes(nums) {
