  // iterate through the array and update maxConsecutiveOnes whenever we encounter a sequence of 1s
  for (let i = 0; i < nums.length; i++) {
    // if current element is 1, increment currentConsecutiveOnes
    if (nums[i] === 1) currentConsecutiveOnes++;
    // if current element is not 1, update maxConsecutiveOnes and reset currentConsecutiveOnes
    else {
      maxConsecutiveOnes = Math.max(maxConsecutiveOnes, currentConsecutiveOnes);
      currentConsecutiveOnes = 0;
    }
  }
  // update maxConsecutiveOnes one last time after the loop ends
  maxConsecutiveOnes = Math.max(maxConsecutiveOnes, currentConsecutiveOnes);
  return maxConsecutiveOnes;
}

function findMinStep(board, hand) {
    let handMap = {};
    for (let i = 0; i < hand.length; i++) {
        handMap[hand[i]] = (handMap[hand[i]] || 0) + 1;
    }
    let queue = [[board, handMap]];
    let visited = new Set([board + JSON.stringify(handMap)]);
    let step = 0;
    while (queue.length > 0) {
        let size = queue.length;
        for (let i = 0; i < size; i++) {
            let [currBoard, currHand] = queue.shift();
            if (currBoard.length === 0) return step;
            for (let color in currHand) {
                if (currHand[color] === 0) continue;
                for (let j = 0; j <= currBoard.length; j++) {
                    let newBoard = currBoard.slice(0, j) + color + currBoard.slice(j);
                    newBoard = reduceBoard(newBoard);
                    let newHand = Object.assign({}, currHand);
                    newHand[color]--;
                    const stateKey = newBoard + JSON.stringify(newHand);
                    if (!visited.has(stateKey)) {
                        visited.add(stateKey);
                        queue.push([newBoard, newHand]);
                    }
                }
            }
        }
        step++;
    }
    return -1;
}
function reduceBoard(board) {
    let changed = true;
    while (changed) {
        changed = false;
        let i = 0;
        while (i < board.length) {
            let j = i;
            while (j < board.length && board[j] === board[i]) j++;
            if (j - i >= 3) { board = board.slice(0, i) + board.slice(j); changed = true; break; }
            i = j;
        }
    }
    return board;
}
