function findSubsequences(nums) {
  // generate all possible subsequences and filter non-decreasing ones
  let result = new Set();
  function backtrack(start, current) {
    // if current subsequence has at least two elements, add it to the result
    if (current.length >= 2) result.add(JSON.stringify(current));
    for (let i = start; i < nums.length; i++) {
      // if current subsequence is empty or current number is not less than the last number in the subsequence, add it to the subsequence
      if (current.length === 0 || nums[i] >= current[current.length - 1]) {
        current.push(nums[i]);
        backtrack(i + 1, current);
        current.pop();
      }
    }
  }
  backtrack(0, []);
  return Array.from(result).map(JSON.parse);
}

function findTargetSumWays(nums, target) {
  // Initialize a hashmap to store the intermediate results for dynamic programming
  let dp = {0: 1};
  // Iterate over the array
  for (let num of nums) {
    // Initialize a temporary hashmap to store the new intermediate results
    let temp = {};
    // For each existing intermediate result
    for (let sum in dp) {
      // Calculate the new sum by adding the current number
      let newSum = parseInt(sum) + num;
      // If the new sum is not in the temporary hashmap, add it with the count of the current sum
      if (!(newSum in temp)) temp[newSum] = dp[sum];
      // Otherwise, add the count of the current sum to the new sum
      else temp[newSum] += dp[sum];
      // Calculate the new sum by subtracting the current number
      newSum = parseInt(sum) - num;
      // If the new sum is not in the temporary hashmap, add it with the count of the current sum
      if (!(newSum in temp)) temp[newSum] = dp[sum];
      // Otherwise, add the count of the current sum to the new sum
      else temp[newSum] += dp[sum];
    }
    // Update the hashmap with the new intermediate results
    dp = temp;
  }
  // Return the count of the target sum, or 0 if it does not exist
  return dp[target] || 0;
}

function reversePairs(nums) {
    let count = 0;
    function mergeSort(arr) {
        if (arr.length <= 1) return arr;
        const mid = Math.floor(arr.length / 2);
        const left = mergeSort(arr.slice(0, mid));
        const right = mergeSort(arr.slice(mid));
        // count pairs first, using a separate two-pointer pass over the two
        // already-sorted halves (the doubled-value comparison is unrelated to merge order)
        let j = 0;
        for (let i = 0; i < left.length; i++) {
            while (j < right.length && left[i] > 2 * right[j]) j++;
            count += j;
        }
        return merge(left, right);
    }
    function merge(left, right) {
        const result = [];
        let i = 0, j = 0;
        while (i < left.length && j < right.length) {
            if (left[i] <= right[j]) {
                result.push(left[i]);
                i++;
            } else {
                result.push(right[j]);
                j++;
            }
        }
        return result.concat(left.slice(i)).concat(right.slice(j));
    }
    mergeSort(nums);
    return count;
}

function nextGreaterElement(nums1, nums2) {
  // Create a hash map to store the next greater element for each element in nums2
  const nextGreaterMap = {};
  const stack = [];
  for (let i = 0; i < nums2.length; i++) {
    // While the stack is not empty and the current element is greater than the top of the stack
    while (stack.length > 0 && nums2[i] > stack[stack.length - 1]) {
      // Update the next greater element for the top of the stack
      nextGreaterMap[stack.pop()] = nums2[i];
    }
    // Push the current element to the stack
    stack.push(nums2[i]);
  }
  // For the remaining elements in the stack, there is no next greater element
  while (stack.length > 0) {
    nextGreaterMap[stack.pop()] = -1;
  }
  // Create the result array using the next greater map
  const result = [];
  for (let i = 0; i < nums1.length; i++) {
    // Get the next greater element for the current element in nums1
    result.push(nextGreaterMap[nums1[i]]);
  }
  return result;
}

class Solution {
    constructor(rects) {
        this.rects = rects;
        this.prefixAreas = [];
        let totalPoints = 0;
        for (let i = 0; i < rects.length; i++) {
            totalPoints += (rects[i][2] - rects[i][0] + 1) * (rects[i][3] - rects[i][1] + 1);
            this.prefixAreas.push(totalPoints);
        }
        this.totalPoints = totalPoints;
    }
    pick() {
        let randomIndex = Math.floor(Math.random() * this.totalPoints);
        for (let i = 0; i < this.rects.length; i++) {
            if (randomIndex < this.prefixAreas[i]) {
                const rect = this.rects[i];
                const x = rect[0] + Math.floor(Math.random() * (rect[2] - rect[0] + 1));
                const y = rect[1] + Math.floor(Math.random() * (rect[3] - rect[1] + 1));
                return [x, y];
            }
        }
    }
}

function findDiagonalOrder(mat) {
    // Initialize variables to store the result and the number of rows and columns in the matrix
    var result = [];
    var rows = mat.length;
    var cols = mat[0].length;
    // Initialize variables to store the current diagonal and the direction of the diagonal
    var diagonal = 0;
    var direction = 1;
    // Create a map to store the elements of each diagonal
    var map = {};
    // Iterate over each element in the matrix
    for (var i = 0; i < rows; i++) {
        for (var j = 0; j < cols; j++) {
            // Calculate the diagonal of the current element
            diagonal = i + j;
            // If the diagonal is not in the map, add it
            if (!(diagonal in map)) {
                map[diagonal] = [];
            }
            // Add the current element to the diagonal in the map
            map[diagonal].push(mat[i][j]);
        }
    }
    // Iterate over each diagonal in the map
    for (var i = 0; i < rows + cols - 1; i++) {
        // If the diagonal is even, reverse the elements in the diagonal
        if (i % 2 === 0) {
            // Add the elements of the diagonal to the result in reverse order
            result = result.concat(map[i].reverse());
        } else {
            // Add the elements of the diagonal to the result
            result = result.concat(map[i]);
        }
    }
    // Return the result
    return result;
}

function findWords(words) {
  const rows = ["qwertyuiop", "asdfghjkl", "zxcvbnm"];
  const result = [];
  for (let originalWord of words) {
    let word = originalWord.toLowerCase();
    let canBeTyped = true;
    if (rows[0].includes(word[0])) {
      for (let char of word) { if (!rows[0].includes(char)) { canBeTyped = false; break; } }
    } else if (rows[1].includes(word[0])) {
      for (let char of word) { if (!rows[1].includes(char)) { canBeTyped = false; break; } }
    } else {
      for (let char of word) { if (!rows[2].includes(char)) { canBeTyped = false; break; } }
    }
    if (canBeTyped) result.push(originalWord);
  }
  return result;
}

function findMode(root) {
    // Initialize variables to store the frequency of each node value and the maximum frequency
    let frequency = {}, maxFrequency = 0, modes = [];

    // Define a helper function to perform DFS on the tree and update the frequency of each node value
    function dfs(node) {
        // If the node is null, return immediately
        if (!node) return;

        // Update the frequency of the current node value
        frequency[node.val] = (frequency[node.val] || 0) + 1;

        // Recursively traverse the left and right subtrees
        dfs(node.left); dfs(node.right);
    }

    // Perform DFS on the tree
    dfs(root);

    // Update the maximum frequency
    maxFrequency = Math.max(...Object.values(frequency));

    // Find all node values with the maximum frequency
    for (let val in frequency) {
        // If the frequency of the current node value is equal to the maximum frequency, add it to the modes array
        if (frequency[val] === maxFrequency) modes.push(parseInt(val));
    }

    return modes;
}

function findMaximizedCapital(k, w, profits, capital) {
    // Create a list of projects with their profits and capital requirements
    let projects = [];
    for (let i = 0; i < profits.length; i++) {
        projects.push([profits[i], capital[i]]);
    }

    // Sort the projects by their capital requirements
    projects.sort((a, b) => a[1] - b[1]);

    // Initialize a priority queue to store the projects that can be started
    let pq = [];

    // Initialize the index of the current project
    let i = 0;

    // Repeat k times
    while (k > 0) {
        // Add all projects that can be started to the priority queue
        while (i < projects.length && projects[i][1] <= w) {
            // Add the project to the priority queue
            pq.push(projects[i][0]);
            // Move to the next project
            i++;
        }

        // If no projects can be started, break the loop
        if (pq.length === 0) {
            break;
        }

        // Start the project with the highest profit
        w += Math.max(...pq);
        // Remove the project from the priority queue
        pq.splice(pq.indexOf(Math.max(...pq)), 1);

        // Decrement k
        k--;
    }

    // Return the final maximized capital
    return w;
}

function nextGreaterElements(nums) {
    var result = new Array(nums.length).fill(-1);
    var stack = [];
    // iterate over the array twice to simulate circular behavior
    for (var i = 0; i < nums.length * 2; i++) {
        // use modulus operator to wrap around to the start of the array
        var current = i % nums.length;
        // while the stack is not empty and the current number is greater than the number at the top of the stack
        while (stack.length > 0 && nums[current] > nums[stack[stack.length - 1]]) {
            // update the result array with the next greater number
            result[stack.pop()] = nums[current];
        }
        // push the current index onto the stack
        stack.push(current);
    }
    return result;
}

function convertToBase7(num) {
  // If the number is 0, return '0' immediately
  if (num === 0) return '0';
  let result = '';
  let isNegative = num < 0;
  // Take the absolute value of the number to simplify calculations
  num = Math.abs(num);
  // Repeatedly divide the number by 7 and append the remainder to the result
  while (num > 0) {
    result = num % 7 + result;
    num = Math.floor(num / 7);
  }
  // If the original number was negative, add a negative sign to the result
  return isNegative ? '-' + result : result;
}

function findRelativeRanks(score) {
    // Create a copy of the score array and sort it in descending order to determine the rank of each athlete
    var sortedScore = score.slice().sort(function(a, b) { return b - a; });
    var result = new Array(score.length);
    for (var i = 0; i < score.length; i++) {
        // Find the index of the current score in the sorted array to determine its rank
        var rank = sortedScore.indexOf(score[i]) + 1;
        // Assign the rank to the result array, using the appropriate medal name for the top 3 ranks
        if (rank === 1) result[i] = "Gold Medal";
        else if (rank === 2) result[i] = "Silver Medal";
        else if (rank === 3) result[i] = "Bronze Medal";
        else result[i] = rank.toString();
    }
    return result;
}

function checkPerfectNumber(num) {
    // calculate sum of divisors from 1 to sqrt(num) and multiply by 2, excluding num itself
    let sum = 1;
    for (let i = 2; i * i <= num; i++) {
        // check if i is a divisor of num
        if (num % i === 0) {
            sum += i;
            // if i is not the square root of num, add its corresponding divisor
            if (i * i !== num) sum += num / i;
        }
    }
    return sum === num;
}

