function complexNumberMultiply(num1, num2) {
    // split the complex numbers into real and imaginary parts
    var real1 = parseInt(num1.substring(0, num1.indexOf('+')));
    var imag1 = parseInt(num1.substring(num1.indexOf('+') + 1, num1.length - 1));
    var real2 = parseInt(num2.substring(0, num2.indexOf('+')));
    var imag2 = parseInt(num2.substring(num2.indexOf('+') + 1, num2.length - 1));
    // calculate the real and imaginary parts of the product
    var real = real1 * real2 - imag1 * imag2;
    var imag = real1 * imag2 + real2 * imag1;
    // return the result as a string
    return real + '+' + imag + 'i';
}

function convertBST(root) {
    // Initialize a variable to store the sum of all keys greater than the current node
    let sum = 0;
    // Define a helper function to perform reverse in-order traversal
    function reverseInOrder(node) {
        // If the node is null, return immediately
        if (!node) return;
        // Recursively traverse the right subtree
        reverseInOrder(node.right);
        // Update the node's value by adding the sum of all keys greater than the current node
        node.val += sum;
        // Update the sum by adding the current node's value
        sum = node.val;
        // Recursively traverse the left subtree
        reverseInOrder(node.left);
    }
    // Perform reverse in-order traversal starting from the root node
    reverseInOrder(root);
    // Return the modified root node
    return root;
}

function singleNonDuplicate(nums) {
  // Initialize the result variable to 0
  let result = 0;
  // Iterate over the array using bitwise XOR operation to find the single element
  for (let i = 0; i < nums.length; i++) {
    // XOR operation has the property that a ^ a = 0 and a ^ 0 = a, so all pairs will cancel out
    result ^= nums[i];
  }
  // The result will be the single element that appears only once
  return result;
}

function reverseStr(s, k) {
    s = s.split(''); // convert string to array for easier manipulation
    for (let i = 0; i < s.length; i += 2 * k) { // loop through the string in steps of 2k
        // reverse the first k characters of the current 2k block
        let left = i, right = Math.min(i + k - 1, s.length - 1);
        while (left < right) {
            let temp = s[left];
            s[left] = s[right];
            s[right] = temp;
            left++;
            right--;
        }
    }
    return s.join(''); // convert array back to string
}

function updateMatrix(mat) {
  // Initialize the result matrix with the same dimensions as the input matrix
  var result = new Array(mat.length);
  for (var i = 0; i < mat.length; i++) {
    result[i] = new Array(mat[0].length);
  }

  // Initialize a queue for BFS with all cells containing 0
  var queue = [];
  for (var i = 0; i < mat.length; i++) {
    for (var j = 0; j < mat[0].length; j++) {
      if (mat[i][j] === 0) {
        // Mark cells with 0 as visited and add them to the queue
        result[i][j] = 0;
        queue.push([i, j]);
      } else {
        // Mark cells with 1 as unvisited
        result[i][j] = -1;
      }
    }
  }

  // Perform BFS
  var directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
  while (queue.length > 0) {
    var current = queue.shift();
    // Explore all neighboring cells
    for (var i = 0; i < directions.length; i++) {
      var x = current[0] + directions[i][0];
      var y = current[1] + directions[i][1];
      // Check if the neighboring cell is within the matrix bounds and unvisited
      if (x >= 0 && x < mat.length && y >= 0 && y < mat[0].length && result[x][y] === -1) {
        // Mark the neighboring cell as visited and update its distance
        result[x][y] = result[current[0]][current[1]] + 1;
        // Add the neighboring cell to the queue
        queue.push([x, y]);
      }
    }
  }

  return result;
}

function diameterOfBinaryTree(root) {
  let maxDiameter = 0;
  function dfs(node) {
    // calculate the depth of the left and right subtrees
    if (!node) return 0;
    let leftDepth = dfs(node.left);
    let rightDepth = dfs(node.right);
    // update the maximum diameter if the current path is longer
    maxDiameter = Math.max(maxDiameter, leftDepth + rightDepth);
    // return the depth of the current node
    return Math.max(leftDepth, rightDepth) + 1;
  }
  dfs(root);
  return maxDiameter;
}

function findMinDifference(timePoints) {
    // Convert time points to minutes and sort them
    var minutes = timePoints.map(function(time) {
        var parts = time.split(':');
        return parseInt(parts[0]) * 60 + parseInt(parts[1]);
    }).sort(function(a, b) {
        return a - b;
    });

    // Calculate the minimum time difference
    var minDiff = Infinity;
    for (var i = 0; i < minutes.length - 1; i++) {
        // Calculate the time difference between two consecutive time points
        minDiff = Math.min(minDiff, minutes[i + 1] - minutes[i]);
    }

    // Calculate the time difference between the first and last time points
    minDiff = Math.min(minDiff, 24 * 60 - minutes[minutes.length - 1] + minutes[0]);

    return minDiff;
}

function removeBoxes(boxes) {
  let memo = new Map();
  function dp(left, right, k) {
    if (left > right) return 0;
    let key = left + ',' + right + ',' + k;
    if (memo.has(key)) return memo.get(key);
    let maxPoints = 0;
    if (left === right) return (k + 1) * (k + 1);
    for (let i = left + 1; i <= right; i++) {
      if (boxes[i] === boxes[left]) {
        let points = dp(left + 1, i - 1, 0) + dp(i, right, k + 1);
        maxPoints = Math.max(maxPoints, points);
      }
    }
    maxPoints = Math.max(maxPoints, (k + 1) * (k + 1) + dp(left + 1, right, 0));
    memo.set(key, maxPoints);
    return maxPoints;
  }
  return dp(0, boxes.length - 1, 0);
}

function findCircleNum(isConnected) {
    // Initialize the number of cities
    var n = isConnected.length;

    // Initialize the visited array
    var visited = new Array(n).fill(false);

    // Initialize the count of provinces
    var count = 0;

    // Iterate over each city
    for (var i = 0; i < n; i++) {
        // If the city is not visited, it's a new province
        if (!visited[i]) {
            // Mark all connected cities as visited
            dfs(isConnected, visited, i); 
            // Increment the count of provinces
            count++;
        }
    }

    // Return the total number of provinces
    return count;
}

// Depth-First Search function to mark all connected cities as visited
function dfs(isConnected, visited, i) {
    // Mark the current city as visited
    visited[i] = true;
    // Iterate over each city
    for (var j = 0; j < isConnected.length; j++) {
        // If the cities are connected and the city is not visited, perform DFS
        if (isConnected[i][j] === 1 && !visited[j]) {
            dfs(isConnected, visited, j); // Perform DFS on the connected city
        }
    }
}

