function optimalDivision(nums) {
  // base case: if there is only one number, return it as a string
  if (nums.length === 1) return nums[0].toString();
  // if there are only two numbers, return the division expression
  if (nums.length === 2) return nums[0] + '/' + nums[1];
  // for more than two numbers, add parentheses around the division of the rest of the numbers
