}

function checkRecord(n) {
    const MOD = 1000000007;
    // dp[a][l]: number of valid records so far with a absences and l trailing lates
    let dp = new Array(2).fill(0).map(() => new Array(3).fill(0));
    dp[0][0] = 1;
    for (let day = 0; day < n; day++) {
        let newDp = new Array(2).fill(0).map(() => new Array(3).fill(0));
        for (let a = 0; a < 2; a++) {
            for (let l = 0; l < 3; l++) {
                const prev = dp[a][l];
                if (prev === 0) continue;
                newDp[a][0] = (newDp[a][0] + prev) % MOD;
                if (l < 2) newDp[a][l + 1] = (newDp[a][l + 1] + prev) % MOD;
                if (a === 0) newDp[1][0] = (newDp[1][0] + prev) % MOD;
            }
        }
        dp = newDp;
    }
    let ans = 0;
    for (let a = 0; a < 2; a++) for (let l = 0; l < 3; l++) ans = (ans + dp[a][l]) % MOD;
    return ans;
}

function leastBricks(wall) {
    // Initialize an object to store the frequency of each edge position
    var edges = {};
    for (var i = 0; i < wall.length; i++) {
        var sum = 0;
        for (var j = 0; j < wall[i].length - 1; j++) {
            // Calculate the edge position and update its frequency
            sum += wall[i][j];
            if (edges[sum] === undefined) edges[sum] = 1;
            else edges[sum]++;
        }
    }
    // Find the maximum frequency of edge positions
    var maxEdges = 0;
    for (var key in edges) {
        // Update the maximum frequency
        maxEdges = Math.max(maxEdges, edges[key]);
    }
    // Return the minimum number of crossed bricks
    return wall.length - maxEdges;
}

function reverseWords(s) {
