}

function nextGreaterElement(n) {
    // Convert the integer into an array of digits for easier manipulation
    let digits = n.toString().split('').map(Number);

    // Find the first decreasing digit from the right
    let i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        // Keep moving left until we find a digit that is smaller than the one to its right
        i--;
    }

    // If we couldn't find a decreasing digit, the number is already the largest possible
    if (i < 0) {
        return -1;
    }

    // Find the smallest digit to the right of the decreasing digit that is greater than it
    let j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        // Keep moving left until we find a digit that is greater than the decreasing digit
        j--;
    }

    // Swap the decreasing digit with the smallest greater digit to its right
    [digits[i], digits[j]] = [digits[j], digits[i]];

    // Sort the digits to the right of the decreasing digit in ascending order
    let right = digits.slice(i + 1);
    right.sort((a, b) => a - b);
    digits = digits.slice(0, i + 1).concat(right);

    // Convert the array of digits back into an integer
    let result = parseInt(digits.join(''));

    // Check if the result fits in a 32-bit integer
    if (result > 2**31 - 1) {
        return -1;
    }

    return result;
}

function maxDepth(root) {
    if (!root) return 0; // base case: if root is null, return 0
    let max = 0; // initialize max depth
    for (let child of root.children) { // iterate over children
        max = Math.max(max, maxDepth(child)); // recursively calculate max depth for each child
    }
    return max + 1; // return max depth plus 1 for the current node
}

function intersect(quadTree1, quadTree2) {
    // If both trees are leaf nodes, return a new leaf node with the OR of their values
    if (quadTree1[0] && quadTree2[0]) return [1, quadTree1[1] || quadTree2[1]];
    // If one tree is a leaf node and the other is not, return the non-leaf node
    if (quadTree1[0]) return quadTree2;
    if (quadTree2[0]) return quadTree1;
    // If neither tree is a leaf node, recursively intersect their children
    return [0, 
        intersect(quadTree1[1], quadTree2[1]), 
        intersect(quadTree1[2], quadTree2[2]), 
        intersect(quadTree1[3], quadTree2[3]), 
        intersect(quadTree1[4], quadTree2[4])
    ];
}

function matrixReshape(mat, r, c) {
    // Check if the total number of elements in the original matrix is equal to the total number of elements in the reshaped matrix
    if (mat.length * mat[0].length !== r * c) return mat;

    // Initialize an empty array to store the reshaped matrix
    let reshapedMatrix = [];

    // Initialize an empty array to store the current row of the reshaped matrix
    let currentRow = [];

    // Initialize a counter to keep track of the current column index
    let columnIndex = 0;

    // Iterate over each element in the original matrix
    for (let i = 0; i < mat.length; i++) {
        for (let j = 0; j < mat[0].length; j++) {
            // Add the current element to the current row of the reshaped matrix
            currentRow.push(mat[i][j]);

            // If the current row is full, add it to the reshaped matrix and reset the current row
            if (++columnIndex === c) {
                reshapedMatrix.push(currentRow);
                currentRow = [];
                columnIndex = 0;
            }
        }
    }

    return reshapedMatrix;
}

function arrayNesting(nums) {
  let maxLength = 0;
  let visited = new Array(nums.length).fill(false);
  // Iterate over each element in the array to find the longest set
  for (let i = 0; i < nums.length; i++) {
    if (!visited[i]) {
      let currentLength = 0;
      let currentIndex = i;
      // Perform DFS to find the length of the current set
      while (!visited[currentIndex]) {
        visited[currentIndex] = true;
        currentLength++;
        currentIndex = nums[currentIndex];
      }
      // Update the maximum length found so far
      maxLength = Math.max(maxLength, currentLength);
    }
  }
  return maxLength;
}

function checkInclusion(s1, s2) {
    // Create a hash map to store the frequency of characters in s1
    var s1Map = {};
    for (var i = 0; i < s1.length; i++) {
        // Count the frequency of each character in s1
        s1Map[s1[i]] = (s1Map[s1[i]] || 0) + 1;
    }

    // Initialize the window boundaries
    var left = 0;
    var right = 0;
    var matched = 0;
    var windowCounts = {};

    // Traverse the string s2
    while (right < s2.length) {
        // Add the character on the right to the window
        var character = s2[right];
        // If the character is in s1, update the window counts
        if (character in s1Map) {
            windowCounts[character] = (windowCounts[character] || 0) + 1;
            // If the count of the character in the window is equal to the count in s1, increment the matched count
            if (windowCounts[character] === s1Map[character]) {
                matched++;
            }
        }

        // If the window size is equal to the length of s1, check if we have a permutation
        if (right - left + 1 === s1.length) {
            // If all characters in the window match the characters in s1, return true
            if (matched === Object.keys(s1Map).length) {
                return true;
            }

            // Remove the character on the left from the window
            var character = s2[left];
            // If the character is in s1, update the window counts
            if (character in s1Map) {
                // If the count of the character in the window is equal to the count in s1, decrement the matched count
                if (windowCounts[character] === s1Map[character]) {
                    matched--;
                }
                // Decrement the count of the character in the window
                windowCounts[character]--;
            }
            // Move the window to the right
            left++;
        }
        // Move the window to the right
        right++;
    }
    // If no permutation is found, return false
    return false;
}

function isSubtree(root, subRoot) {
    // check if the current tree matches the subtree
    function isMatch(node1, node2) {
        // base case: both trees are empty
        if (!node1 && !node2) return true;
        // base case: one tree is empty, the other is not
        if (!node1 || !node2) return false;
        // check if the current nodes match and recursively check the children
        return node1.val === node2.val && isMatch(node1.left, node2.left) && isMatch(node1.right, node2.right);
    }
    // perform DFS on the main tree and check if the subtree matches at each node
    function dfs(node) {
        // base case: the tree is empty
        if (!node) return false;
        // check if the current tree matches the subtree
        if (isMatch(node, subRoot)) return true;
        // recursively check the left and right subtrees
        return dfs(node.left) || dfs(node.right);
    }
    // start the DFS from the root of the main tree
    return dfs(root);
}

function distributeCandies(candyType) {
    // Create a set to store unique candy types
    var uniqueCandies = new Set(candyType);
    // Return the minimum of the number of unique candies and half of the total candies
    return Math.min(uniqueCandies.size, candyType.length / 2);
}

function findPaths(m, n, maxMove, startRow, startColumn) {
    const MOD = 1e9 + 7;
    const directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    const memo = new Map();
    function dfs(row, col, moves) {
        // If the ball is out of the grid boundary, return 1
        if (row < 0 || row >= m || col < 0 || col >= n) return 1;
        // If the number of moves is 0, return 0
        if (moves === 0) return 0;
        const key = [row, col, moves].join(',');
        // If the result is already in the memo, return it
        if (memo.has(key)) return memo.get(key);
        let res = 0;
        // For each possible direction, recursively call the dfs function
        for (const [dr, dc] of directions) {
            // Add the result of the recursive call to the current result
            res = (res + dfs(row + dr, col + dc, moves - 1)) % MOD;
        }
        // Store the result in the memo
        memo.set(key, res);
        return res;
    }
    // Call the dfs function with the initial position and number of moves
    return dfs(startRow, startColumn, maxMove);
}

function findUnsortedSubarray(nums) {
    // Create a copy of the input array and sort it
    var sortedNums = nums.slice().sort((a, b) => a - b);
    var left = 0, right = nums.length - 1;
    // Find the first element from the left that is different in the two arrays
    while (left < nums.length && nums[left] === sortedNums[left]) left++;
    // If the array is already sorted, return 0
    if (left === nums.length) return 0;
    // Find the first element from the right that is different in the two arrays
    while (right >= 0 && nums[right] === sortedNums[right]) right--;
    // Return the length of the subarray that needs to be sorted
    return right - left + 1;
}

function minDistance(word1, word2) {
    // Create a 2D array to store the lengths of the longest common subsequences
    var dp = Array(word1.length + 1).fill(0).map(() => Array(word2.length + 1).fill(0));
    // Initialize the base cases
    for (var i = 0; i <= word1.length; i++) {
        // If word1 is empty, the length of the longest common subsequence is 0
        dp[i][0] = 0;
    }
    for (var j = 0; j <= word2.length; j++) {
        // If word2 is empty, the length of the longest common subsequence is 0
        dp[0][j] = 0;
    }
    // Fill in the rest of the 2D array
    for (var i = 1; i <= word1.length; i++) {
        for (var j = 1; j <= word2.length; j++) {
            // If the current characters in word1 and word2 are the same, 
            // the length of the longest common subsequence is one more than the length of the longest common subsequence without these characters
            if (word1[i - 1] === word2[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
            } 
            // If the current characters are different, the length of the longest common subsequence is the maximum of the lengths of the longest common subsequences without the current character in word1 or word2
            else {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
    }
    // The minimum number of steps required to make word1 and word2 the same is the sum of the lengths of word1 and word2 minus twice the length of the longest common subsequence
    return word1.length + word2.length - 2 * dp[word1.length][word2.length];
}

function outerTrees(trees) {
    const n = trees.length;
    if (n < 4) return trees;
    trees = trees.slice().sort((a,b) => a[0]-b[0] || a[1]-b[1]);
    function cross(o,a,b){ return (a[0]-o[0])*(b[1]-o[1]) - (a[1]-o[1])*(b[0]-o[0]); }
    const lower = [];
    for (const p of trees) {
        while (lower.length>=2 && cross(lower[lower.length-2], lower[lower.length-1], p) < 0) lower.pop();
        lower.push(p);
    }
    const upper = [];
    for (let i=n-1;i>=0;i--) {
        const p = trees[i];
        while (upper.length>=2 && cross(upper[upper.length-2], upper[upper.length-1], p) < 0) upper.pop();
        upper.push(p);
    }
    const seen = new Set();
    const result = [];
    for (const p of [...lower, ...upper]) {
        const key = p[0]+','+p[1];
        if (!seen.has(key)) { seen.add(key); result.push(p); }
    }
    return result;
}

function preorder(root) {
    // Initialize result array and stack with root node
    var result = [], stack = root ? [root] : [];
    while (stack.length) {
        // Pop the last node from the stack and add its value to the result
        var node = stack.pop();
        result.push(node.val);
        // Add the children of the current node to the stack in reverse order
        for (var i = node.children.length - 1; i >= 0; i--) {
            stack.push(node.children[i]);
        }
    }
    return result;
}

function postorder(root) {
    // Initialize result array and stack with root node
    let result = [], stack = root ? [root] : [];
    while (stack.length) {
        // Pop the top node from the stack and push its value to the result array
        let node = stack.pop();
        result.push(node.val);
        // Push all children of the current node to the stack in reverse order
        if (node.children) for (let i = node.children.length - 1; i >= 0; i--) stack.push(node.children[i]);
    }
    // Return the result array in reverse order
    return result.reverse();
}

function isValid(code) {
    let stack = [];
    let insideCdata = false;
    for (let i = 0; i < code.length; i++) {
        // check for start of cdata
        if (code.substring(i, i + 9) === '<![CDATA[') {
            insideCdata = true;
            i += 8;
        }
        // check for end of cdata
        else if (insideCdata && code.substring(i, i + 3) === ']]>') {
            insideCdata = false;
            i += 2;
        }
        // check for start tag
        else if (code[i] === '<' && !insideCdata) {
            let j = i + 1;
            while (j < code.length && code[j] !== '>') {
                j++;
            }
            let tag = code.substring(i + 1, j);
            // check if tag is start tag
            if (tag[0] !== '/') {
                // check for valid tag name
                let tagName = '';
                for (let k = 0; k < tag.length; k++) {
                    if (tag[k] === ' ') {
                        break;
                    }
                    tagName += tag[k];
                }
                    // check if tag name is valid
                    if (!tagName.match(/^[A-Z]+$/)) {
                        return false;
                    }
                    stack.push(tagName);
                }
            // check if tag is end tag
            else {
                let tagName = tag.substring(1);
                // check if tag name is valid
                if (!tagName.match(/^[A-Z]+$/)) {
                    return false;
                }
                // check if stack is empty or top of stack does not match tag name
                if (stack.length === 0 || stack.pop() !== tagName) {
                    return false;
                }
            }
            i = j;
        }
    }
    // check if stack is empty
    return stack.length === 0;
}

function fractionAddition(expression) {
    const parts = expression.match(/[+-]?\d+\/\d+/g);
    let numerator = 0, denominator = 1;
    function gcd(a, b) {
        a = Math.abs(a); b = Math.abs(b);
        while (b) { [a, b] = [b, a % b]; }
        return a || 1;
    }
    for (const part of parts) {
        const [n, d] = part.split('/').map(Number);
        numerator = numerator * d + n * denominator;
        denominator *= d;
        const g = gcd(numerator, denominator);
        numerator /= g;
        denominator /= g;
    }
    if (denominator < 0) { numerator = -numerator; denominator = -denominator; }
    return numerator + '/' + denominator;
}

function validSquare(p1, p2, p3, p4) {
  // calculate distances between all pairs of points
  let distances = [];
  distances.push(distance(p1, p2));
  distances.push(distance(p1, p3));
  distances.push(distance(p1, p4));
  distances.push(distance(p2, p3));
  distances.push(distance(p2, p4));
  distances.push(distance(p3, p4));

  // sort the distances to easily identify the sides and diagonals
  distances.sort((a, b) => a - b);

  // check if the four sides have the same length and the two diagonals have the same length
  return distances[0] === distances[1] && distances[1] === distances[2] && distances[2] === distances[3] && distances[4] === distances[5] && distances[0] < distances[4];
}

// calculate the Euclidean distance between two points
function distance(p1, p2) {
  // calculate the difference in x and y coordinates
  return Math.sqrt(Math.pow(p1[0] - p2[0], 2) + Math.pow(p1[1] - p2[1], 2));
}

function findLHS(nums) {
    var countMap = {};
    for (var num of nums) {
        countMap[num] = (countMap[num] || 0) + 1;
    }
    var longestLength = 0;
    for (var num in countMap) {
        var n = parseInt(num);
        if (countMap[n + 1]) {
            longestLength = Math.max(longestLength, countMap[n] + countMap[n + 1]);
        }
    }
    return longestLength;
}

function maxCount(m, n, ops) {
  // find the minimum row and column to determine the overlap area
  let minRow = m;
  let minCol = n;
  for (let i = 0; i < ops.length; i++) {
    // update minRow and minCol if current operation has smaller row or column
    minRow = Math.min(minRow, ops[i][0]);
    minCol = Math.min(minCol, ops[i][1]);
  }
  // calculate the area of the overlap
  return minRow * minCol;
}

function findRestaurant(list1, list2) {
    // Create a hash map to store the index of each restaurant in list1
    var map = {};
    for (var i = 0; i < list1.length; i++) {
        // Store the index of each restaurant in the hash map
        map[list1[i]] = i;
    }
    var minSum = Infinity;
    var result = [];
    for (var i = 0; i < list2.length; i++) {
        // Check if the current restaurant is in the hash map
        if (map[list2[i]] !== undefined) {
            // Calculate the index sum
            var sum = i + map[list2[i]];
            // If the index sum is less than the current minimum sum, update the minimum sum and reset the result
            if (sum < minSum) {
                minSum = sum;
                result = [list2[i]];
            }
            // If the index sum is equal to the current minimum sum, add the restaurant to the result
            else if (sum === minSum) {
                result.push(list2[i]);
            }
        }
    }
    return result;
}

function findIntegers(n) {
    const fib = new Array(32).fill(0);
    fib[0] = 1; fib[1] = 2;
    for (let i = 2; i < 32; i++) fib[i] = fib[i - 1] + fib[i - 2];
    let result = 0, prevBit = 0, highest = 0;
    for (let b = 31; b >= 0; b--) { if ((n >> b) & 1) { highest = b; break; } }
    for (let i = highest; i >= 0; i--) {
        if ((n >> i) & 1) {
            result += fib[i];
            if (prevBit) return result;
            prevBit = 1;
        } else {
            prevBit = 0;
        }
    }
    return result + 1;
}

function canPlaceFlowers(flowerbed, n) {
    let count = 0;
    // check each plot to see if a flower can be planted
    for (let i = 0; i < flowerbed.length; i++) {
        // if the plot is empty and the adjacent plots are also empty, plant a flower
        if (flowerbed[i] === 0 && (i === 0 || flowerbed[i - 1] === 0) && (i === flowerbed.length - 1 || flowerbed[i + 1] === 0)) {
            flowerbed[i] = 1;
            count++;
        }
    }
    // return true if n new flowers can be planted, false otherwise
    return count >= n;
}

function tree2str(root) {
    // if the tree is empty, return an empty string
    if (!root) return "";

    // start with the root's value
    let result = root.val;

    // if the left subtree is not empty, recursively traverse it and add the result to the string
    if (root.left) {
        // add the left subtree's string representation enclosed in parentheses
        result += "(" + tree2str(root.left) + ")";
    }

    // if the right subtree is not empty, recursively traverse it and add the result to the string
    if (root.right) {
        // if the left subtree is empty, add an empty pair of parentheses to indicate the absence of a left child
        if (!root.left) result += "()";
        // add the right subtree's string representation enclosed in parentheses
        result += "(" + tree2str(root.right) + ")";
    }

    // return the final string representation of the tree
    return result;
}

function findDuplicateFiles(paths) {
    // Create a hash map to store the file contents and their corresponding paths
    let contentMap = {};
    for (let path of paths) {
        // Split the path into directory and files
        let [directory, ...files] = path.split(' ');
        for (let file of files) {
            // Extract the file name and content
            let [fileName, content] = file.split('(');
            content = content.slice(0, -1); // Remove the closing parenthesis
            // Add the file path to the content map
            if (!contentMap[content]) contentMap[content] = [];
            contentMap[content].push(directory + '/' + fileName);
        }
    }
    // Filter out the contents with less than two files
    let result = [];
    for (let content in contentMap) {
        // Only include contents with at least two files
        if (contentMap[content].length > 1) result.push(contentMap[content]);
    }
    return result;
}

function triangleNumber(nums) {
    // Sort the array to apply the two-pointer technique
    nums.sort((a, b) => a - b);
    let count = 0;
    // Iterate over the array to fix the largest side of the triangle
    for (let i = nums.length - 1; i >= 2; i--) {
        // Initialize two pointers for the remaining two sides
        let left = 0, right = i - 1;
        // Apply the two-pointer technique to find valid combinations
        while (left < right) {
            // Check if the current combination can form a triangle
            if (nums[left] + nums[right] > nums[i]) {
                // If it can, increment the count by the number of valid combinations
                count += right - left;
                // Move the right pointer to find more valid combinations
                right--;
            } else {
                // If it cannot, move the left pointer to increase the sum
                left++;
            }
        }
    }
    return count;
}

function mergeTrees(root1, root2) {
    // if both trees are empty, return null
    if (!root1 && !root2) return null;
    // if one tree is empty, return the other tree
    if (!root1) return root2;
    if (!root2) return root1;
    // merge the values of the current nodes
    root1.val += root2.val;
    // recursively merge the left and right subtrees
    root1.left = mergeTrees(root1.left, root2.left);
    root1.right = mergeTrees(root1.right, root2.right);
    return root1;
}

function leastInterval(tasks, n) {
  // Create a frequency map for tasks
  let frequencyMap = {};
  for (let task of tasks) {
    // Count the frequency of each task
    frequencyMap[task] = (frequencyMap[task] || 0) + 1;
  }

  // Find the maximum frequency
  let maxFrequency = 0;
  for (let task in frequencyMap) {
    // Update the maximum frequency
    maxFrequency = Math.max(maxFrequency, frequencyMap[task]);
  }

  // Count the number of tasks with the maximum frequency
  let maxFrequencyCount = 0;
  for (let task in frequencyMap) {
    // Check if the task has the maximum frequency
    if (frequencyMap[task] === maxFrequency) {
      // Increment the count
      maxFrequencyCount++;
    }
  }

  // Calculate the minimum number of intervals
  let intervals = (maxFrequency - 1) * (n + 1) + maxFrequencyCount;
  // Return the maximum of the calculated intervals and the total number of tasks
  return Math.max(intervals, tasks.length);
}

class MyCircularQueue {
    constructor(k) {
        this.queue = new Array(k);
        this.head = 0;
        this.tail = -1;
        this.size = 0;
    }
    enQueue(value) {
        if (this.size === this.queue.length) return false;
        this.tail = (this.tail + 1) % this.queue.length;
        this.queue[this.tail] = value;
        this.size++;
        return true;
    }
    deQueue() {
        if (this.size === 0) return false;
        this.head = (this.head + 1) % this.queue.length;
        this.size--;
        return true;
    }
    Front() { return this.size === 0 ? -1 : this.queue[this.head]; }
    Rear() { return this.size === 0 ? -1 : this.queue[this.tail]; }
    isEmpty() { return this.size === 0; }
    isFull() { return this.size === this.queue.length; }
}

function addOneRow(root, val, depth) {
    // if depth is 1, we need to create a new root node with the given value and the original root as its child
    if (depth === 1) {
        var newNode = { val: val, left: root, right: null };
        return newNode;
    }
    // perform a depth-first search to add the new row at the given depth
    function dfs(node, currentDepth) {
        // if the current node is null, return null
        if (node === null) return null;
        // if the current depth is one less than the target depth, add the new nodes
        if (currentDepth === depth - 1) {
            // create new nodes with the given value and the original children
            var newLeft = { val: val, left: node.left, right: null };
            var newRight = { val: val, left: null, right: node.right };
            // update the children of the current node
            node.left = newLeft;
            node.right = newRight;
        } else {
            // recursively search the left and right subtrees
            dfs(node.left, currentDepth + 1);
            dfs(node.right, currentDepth + 1);
        }
    }
    // start the depth-first search from the root node at depth 1
    dfs(root, 1);
    return root;
}

function maxDistance(arrays) {
  // Find the minimum and maximum values across all arrays
  let minVal = Infinity, maxVal = -Infinity;
  for (let array of arrays) {
    // Update minVal if the first element of the current array is smaller
    minVal = Math.min(minVal, array[0]);
    // Update maxVal if the last element of the current array is larger
    maxVal = Math.max(maxVal, array[array.length - 1]);
  }
  // The maximum distance is the difference between the maximum and minimum values
  return maxVal - minVal;
}

function maximumProduct(nums) {
  // Sort the array in ascending order to easily find the maximum and minimum numbers
  nums.sort((a, b) => a - b);
  // The maximum product can be either the product of the three largest numbers or the product of the two smallest (most negative) numbers and the largest number
  return Math.max(nums[nums.length - 1] * nums[nums.length - 2] * nums[nums.length - 3], nums[0] * nums[1] * nums[nums.length - 1]);
}

function kInversePairs(n, k) {
    const MOD = 1e9 + 7;
    const dp = Array(n + 1).fill(0).map(() => Array(k + 1).fill(0));
    // Initialize base case where there are no inverse pairs
    for (let i = 1; i <= n; i++) {
        dp[i][0] = 1;
    }
    // Calculate the number of arrays with exactly k inverse pairs
    for (let i = 2; i <= n; i++) {
        for (let j = 1; j <= k; j++) {
            // Calculate the number of arrays by considering the current number and the previous numbers
            for (let p = 0; p <= i - 1 && p <= j; p++) {
                dp[i][j] = (dp[i][j] + dp[i - 1][j - p]) % MOD;
            }
        }
    }
    // Return the number of arrays with exactly k inverse pairs
    return dp[n][k];
}

function scheduleCourse(courses) {
    // Sort the courses by their last day
    courses.sort((a, b) => a[1] - b[1]);
    let pq = [], time = 0;
    for (let i = 0; i < courses.length; i++) {
        // Add the course to the priority queue if it can be taken
        let duration = courses[i][0], lastDay = courses[i][1];
        if (time + duration <= lastDay) {
            time += duration;
            pq.push(-duration); // Use negative to simulate max heap
            pq.sort((a, b) => a - b);
        } else if (pq.length > 0 && -pq[0] > duration) {
            // Replace the longest course in the priority queue if it's longer than the current course
            time += duration - (-pq.shift());
            pq.push(-duration);
            pq.sort((a, b) => a - b);
        }
    }
    return pq.length;
}

function smallestRange(nums) {
  // Create a min-heap to store the current smallest element from each list
  let minHeap = [];
  for (let i = 0; i < nums.length; i++) {
    // Push the first element of each list into the min-heap along with its list index and element index
    minHeap.push([nums[i][0], i, 0]);
  }
  minHeap.sort((a, b) => a[0] - b[0]); // Sort the min-heap based on the element value

  let minRange = Infinity;
  let maxVal = Math.max(...minHeap.map(x => x[0])); // Find the maximum value in the min-heap
  let res = [-1, -1];

  // Continue the process until the min-heap is empty
  while (minHeap.length === nums.length) {
    // Get the smallest element from the min-heap
    let minVal = minHeap[0][0];
    // Update the range if the current range is smaller
    if (maxVal - minVal < minRange) {
      minRange = maxVal - minVal;
      res = [minVal, maxVal];
    }
    // Remove the smallest element from the min-heap
    let [val, listIndex, elementIndex] = minHeap.shift();
    // If there are more elements in the list, push the next element into the min-heap
    if (elementIndex + 1 < nums[listIndex].length) {
      let nextVal = nums[listIndex][elementIndex + 1];
      minHeap.push([nextVal, listIndex, elementIndex + 1]);
      minHeap.sort((a, b) => a[0] - b[0]); // Sort the min-heap based on the element value
      // Update the maximum value in the min-heap
      maxVal = Math.max(maxVal, nextVal);
    }
  }
  return res;
}

function judgeSquareSum(c) {
  // iterate through all possible values of a
  for (let a = 0; a * a <= c; a++) {
    // calculate the remaining value after subtracting a^2 from c
    let remaining = c - a * a;
    // check if the remaining value is a perfect square
    let b = Math.sqrt(remaining);
    // if the remaining value is a perfect square, return true
    if (b === Math.floor(b)) return true;
  }
  // if no such pair is found, return false
  return false;
}

