function findExclusiveTimes(n, logs) {
    var stack = [];
    var exclusiveTimes = new Array(n).fill(0);
    var prevTime = 0;
    // iterate through each log and update the exclusive time of the current function
    for (var log of logs) {
        var [functionId, eventType, timestamp] = log.split(":");
        functionId = parseInt(functionId);
        timestamp = parseInt(timestamp);
        // if the event is a start event, push the function id onto the stack and update the previous time
        if (eventType === "start") {
            if (stack.length > 0) {
                exclusiveTimes[stack[stack.length - 1]] += timestamp - prevTime;
            }
            stack.push(functionId);
            prevTime = timestamp;
        } 
        // if the event is an end event, pop the function id from the stack and update the exclusive time
        else {
            exclusiveTimes[stack.pop()] += timestamp - prevTime + 1;
            prevTime = timestamp + 1;
        }
    }
    return exclusiveTimes;
}

function averageOfLevels(root) {
    // Initialize result array and queue with root node
    let result = [], queue = [root];
    while (queue.length > 0) {
        // Calculate sum of current level nodes
        let sum = 0, levelSize = queue.length;
        for (let i = 0; i < levelSize; i++) {
            // Add node value to sum and enqueue its children
            let node = queue.shift();
            sum += node.val;
            if (node.left) queue.push(node.left);
            if (node.right) queue.push(node.right);
        }
        // Calculate average of current level nodes
        result.push(sum / levelSize);
    }
    return result;
}

function shoppingOffers(price, special, needs) {
    // Create a memoization table to store the results of subproblems
    let memo = new Map();

    function dfs(needs) {
        // If the current state is already in the memoization table, return the stored result
        let key = needs.join(',');
        if (memo.has(key)) return memo.get(key);

        // Initialize the minimum cost to the cost of buying all items at their original prices
        let minCost = 0;
        for (let i = 0; i < needs.length; i++) {
            // Calculate the cost of buying the current item at its original price
            minCost += needs[i] * price[i];
        }

        // Iterate over all special offers
        for (let offer of special) {
            // Create a copy of the current state
            let clone = needs.slice();

            // Apply the current special offer to the copy of the state
            let valid = true;
            for (let i = 0; i < needs.length; i++) {
                clone[i] -= offer[i];
                // If the special offer exceeds the number of items needed, skip it
                if (clone[i] < 0) {
                    valid = false;
                    break;
                }
            }

            // If the special offer is valid, recursively calculate the minimum cost
            if (valid) {
                minCost = Math.min(minCost, offer[offer.length - 1] + dfs(clone));
            }
        }

        // Store the result of the current state in the memoization table
        memo.set(key, minCost);
        return minCost;
    }

    // Call the dfs function with the initial state
    return dfs(needs);
}

function numDecodings(s) {
    const MOD = 1000000007;
    const n = s.length;
    let dp = new Array(n + 1).fill(0);
    dp[0] = 1;
    for (let i = 1; i <= n; i++) {
        if (s[i - 1] !== '*') {
            if (s[i - 1] !== '0') {
                dp[i] = dp[i - 1];
            }
        } else {
            dp[i] += dp[i - 1] * 9;
        }
        if (i >= 2) {
            if (s[i - 1] !== '*' && s[i - 2] !== '*') {
                if (parseInt(s.substring(i - 2, i)) <= 26 && parseInt(s.substring(i - 2, i)) >= 10) {
                    dp[i] += dp[i - 2];
                }
            } else if (s[i - 1] !== '*' && s[i - 2] === '*') {
                if (parseInt(s[i - 1]) <= 26) {
                    dp[i] += dp[i - 2] * 1;
                }
                if (parseInt(s[i - 1]) <= 6) {
                    dp[i] += dp[i - 2] * 1;
                }
            } else if (s[i - 1] === '*' && s[i - 2] !== '*') {
                if (s[i - 2] === '1') {
                    dp[i] += dp[i - 2] * 9;
                } else if (s[i - 2] === '2') {
                    dp[i] += dp[i - 2] * 6;
                }
            } else {
                dp[i] += dp[i - 2] * 15;
            }
        }
        dp[i] %= MOD;
    }
    return dp[n];
}

function solveEquation(equation) {
    const [left, right] = equation.split('=');
    function parseSide(side) {
        let xCoeff = 0, constant = 0;
        const terms = side.match(/[+-]?\d*x|[+-]?\d+/g) || [];
        for (const term of terms) {
            if (term.endsWith('x')) {
                let coeffStr = term.slice(0, -1);
                if (coeffStr === '' || coeffStr === '+') xCoeff += 1;
                else if (coeffStr === '-') xCoeff -= 1;
                else xCoeff += parseInt(coeffStr, 10);
            } else {
                constant += parseInt(term, 10);
            }
        }
        return [xCoeff, constant];
    }
    const [leftX, leftC] = parseSide(left);
    const [rightX, rightC] = parseSide(right);
    const xCoefficient = leftX - rightX;
    const constant = rightC - leftC;
    if (xCoefficient === 0) {
        return constant === 0 ? "Infinite solutions" : "No solution";
    }
    return "x=" + (constant / xCoefficient);
}

class MyCircularDeque {
    constructor(k) {
        this.capacity = k;
        this.size = 0;
        this.head = 0;
        this.tail = 0;
        this.deque = new Array(k);
    }
    insertFront(value) {
        if (this.size === this.capacity) return false;
        this.head = (this.head - 1 + this.capacity) % this.capacity;
        this.deque[this.head] = value;
        this.size++;
        return true;
    }
    insertLast(value) {
        if (this.size === this.capacity) return false;
        this.deque[this.tail] = value;
        this.tail = (this.tail + 1) % this.capacity;
        this.size++;
        return true;
    }
    deleteFront() {
        if (this.size === 0) return false;
        this.head = (this.head + 1) % this.capacity;
        this.size--;
        return true;
    }
    deleteLast() {
        if (this.size === 0) return false;
        this.tail = (this.tail - 1 + this.capacity) % this.capacity;
        this.size--;
        return true;
    }
    getFront() { return this.size === 0 ? -1 : this.deque[this.head]; }
    getRear() { return this.size === 0 ? -1 : this.deque[(this.tail - 1 + this.capacity) % this.capacity]; }
    isEmpty() { return this.size === 0; }
    isFull() { return this.size === this.capacity; }
}

function findMaxAverage(nums, k) {
  // calculate the sum of the first k elements
  let maxSum = 0;
  for (let i = 0; i < k; i++) {
    maxSum += nums[i];
  }
  let currentSum = maxSum;

  // slide the window to the right and update the sum
  for (let i = k; i < nums.length; i++) {
    // subtract the leftmost element and add the new element
    currentSum = currentSum - nums[i - k] + nums[i];
    // update the max sum if the current sum is larger
    maxSum = Math.max(maxSum, currentSum);
  }

  // return the max average
  return maxSum / k;
}

function findErrorNums(nums) {
    // Create a hash map to store the frequency of each number
    var count = {};
    var n = nums.length;
    var duplicate = -1, missing = -1;
    // Count the frequency of each number
    for (var i = 0; i < n; i++) {
        if (count[nums[i]]) {
            duplicate = nums[i];
        } else {
            count[nums[i]] = 1;
        }
    }
    // Find the missing number
    for (var i = 1; i <= n; i++) {
        if (!count[i]) {
            missing = i;
            break;
        }
    }
    return [duplicate, missing];
}

function findLongestChain(pairs) {
  // Sort the pairs based on the right value of each pair
  pairs.sort(function(a, b) { return a[1] - b[1]; });
  var count = 1;
  // Initialize the end of the current chain as the right value of the first pair
  var currentEnd = pairs[0][1];
  // Iterate through the pairs starting from the second pair
  for (var i = 1; i < pairs.length; i++) {
    // If the left value of the current pair is greater than the end of the current chain, 
    // it means we can extend the chain with this pair
    if (pairs[i][0] > currentEnd) {
      // Increment the count of pairs in the chain
      count++;
      // Update the end of the current chain
      currentEnd = pairs[i][1];
    }
  }
  return count;
}

function countSubstrings(s) {
    var count = 0;
    // iterate over the string to consider each character as the center of a potential palindrome
    for (var i = 0; i < s.length; i++) {
        // consider odd-length palindromes
        var left = i, right = i;
        while (left >= 0 && right < s.length && s[left] === s[right]) {
            // if the characters at the left and right pointers match, increment the count
            count++;
            left--;
            right++;
        }
        // consider even-length palindromes
        left = i, right = i + 1;
        while (left >= 0 && right < s.length && s[left] === s[right]) {
            // if the characters at the left and right pointers match, increment the count
            count++;
            left--;
            right++;
        }
    }
    return count;
}

function replaceWords(dictionary, sentence) {
    // Create a Trie and insert all roots into it
    let trie = {};
    for (let root of dictionary) {
        let node = trie;
        for (let char of root) {
            if (!node[char]) node[char] = {};
            node = node[char];
        }
        node.end = true;
    }

    // Split the sentence into words
    let words = sentence.split(' ');

    // For each word, check if it can be replaced by a root in the Trie
    for (let i = 0; i < words.length; i++) {
        let node = trie;
        let j = 0;
        // Check if the word can be replaced by a root
        while (j < words[i].length && node[words[i][j]]) {
            node = node[words[i][j]];
            j++;
            // If the word can be replaced, replace it with the root
            if (node.end) {
                words[i] = words[i].substring(0, j);
                break;
            }
        }
    }

    // Join the words back into a sentence and return
    return words.join(' ');
}

function predictPartyVictory(senate) {
    let radiantQueue = [], direQueue = [];
    // Initialize the queues with the initial senate order
    for (let i = 0; i < senate.length; i++) {
        if (senate[i] === 'R') radiantQueue.push(i);
        else direQueue.push(i);
    }
    // Continue the process until one party's queue is empty
    while (radiantQueue.length > 0 && direQueue.length > 0) {
        // Compare the order of the senators in the queues
        if (radiantQueue[0] < direQueue[0]) {
            // If the Radiant senator is first, they ban the next Dire senator
            radiantQueue.push(radiantQueue[0] + senate.length);
            radiantQueue.shift();
            direQueue.shift();
        } else {
            // If the Dire senator is first, they ban the next Radiant senator
            direQueue.push(direQueue[0] + senate.length);
            direQueue.shift();
            radiantQueue.shift();
        }
    }
    // Return the winning party
    return radiantQueue.length > 0 ? "Radiant" : "Dire";
}

function minSteps(n) {
  // this problem is already optimal with a dynamic programming solution, but we can use a mathematical approach to solve it in O(sqrt(n)) time complexity
  let result = 0;
  let current = 1;
  let buffer = 0;
  while (current < n) {
    // if n is divisible by current, we can copy and paste to reduce the number of operations
    if (n % current === 0) {
      buffer = current;
      result += 1;
    }
    // paste the buffer to increase the current number of 'A's
    current += buffer;
    result += 1;
  }
  return result;
}

