        var subtree = node.val + ',' + dfs(node.left) + ',' + dfs(node.right);

        // Increment the frequency of the subtree in the hashmap
        subtreeMap[subtree] = (subtreeMap[subtree] || 0) + 1;

        // If the frequency of the subtree is 2, add it to the result list
