}

function findTarget(root, k) {
    // Create a set to store the values we've seen so far
    let seen = new Set();
    // Define a helper function to perform DFS
    function dfs(node) {
        // If the node is null, return false
        if (!node) return false;
        // Check if the complement of the current node's value is in the set
        if (seen.has(k - node.val)) return true;
        // Add the current node's value to the set
        seen.add(node.val);
        // Recursively search the left and right subtrees
        return dfs(node.left) || dfs(node.right);
    }
    // Start the DFS from the root node
    return dfs(root);
}

function constructMaximumBinaryTree(nums) {
    // Base case: if the array is empty, return null
    if (nums.length === 0) return null;

    // Find the index of the maximum value in the array
    let maxIndex = 0;
    for (let i = 1; i < nums.length; i++) {
        // If the current value is greater than the max value, update maxIndex
        if (nums[i] > nums[maxIndex]) maxIndex = i;
    }

    // Create a new TreeNode with the maximum value
    let root = { val: nums[maxIndex], left: null, right: null };

    // Recursively construct the left and right subtrees
    root.left = constructMaximumBinaryTree(nums.slice(0, maxIndex));
    root.right = constructMaximumBinaryTree(nums.slice(maxIndex + 1));

    // Return the root of the constructed tree
    return root;
}

function printTree(root) {
