    let height = getHeight(root);
    let res = new Array(height).fill(0).map(() => new Array(Math.pow(2, height) - 1).fill(""));
    // perform a level order traversal to fill in the matrix
    let queue = [[root, 0, 0, Math.pow(2, height) - 1]];
    while (queue.length > 0) {
        let [node, level, start, end] = queue.shift();
        let mid = Math.floor((start + end) / 2);
        res[level][mid] = node.val.toString();
        // add the left and right children to the queue if they exist
        if (node.left) queue.push([node.left, level + 1, start, mid - 1]);
        if (node.right) queue.push([node.right, level + 1, mid + 1, end]);
    }
    return res;
}

function getHeight(node) {
