function findClosestElements(arr, k, x) {
    // Find the closest element to x in the array using binary search
    let left = 0, right = arr.length - k;
    while (left < right) {
        // Calculate the middle index
        let mid = Math.floor((left + right) / 2);
        // Compare the distance between arr[mid] and x, and arr[mid + k] and x
        if (x - arr[mid] > arr[mid + k] - x) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    // Return the k closest elements
    return arr.slice(left, left + k);
}

