        }
    }
    return true;
}

function imageSmoother(img) {
    // Initialize variables to store the number of rows and columns in the image
    var rows = img.length;
    var cols = img[0].length;

    // Initialize a new 2D array to store the smoothed image
    var smoothedImg = new Array(rows);
    for (var i = 0; i < rows; i++) {
        smoothedImg[i] = new Array(cols);
    }

    // Iterate over each cell in the image
    for (var i = 0; i < rows; i++) {
        for (var j = 0; j < cols; j++) {
            // Initialize variables to store the sum of neighboring cells and the count of neighboring cells
            var sum = 0;
            var count = 0;

            // Iterate over the neighboring cells
            for (var x = Math.max(0, i - 1); x <= Math.min(rows - 1, i + 1); x++) {
                for (var y = Math.max(0, j - 1); y <= Math.min(cols - 1, j + 1); y++) {
                    // Add the value of the neighboring cell to the sum and increment the count
                    sum += img[x][y];
                    count++;
                }
            }

            // Calculate the average of the neighboring cells and round it down to the nearest integer
            smoothedImg[i][j] = Math.floor(sum / count); // Calculate the average and round down
        }
    }

    // Return the smoothed image
    return smoothedImg;
}

function widthOfBinaryTree(root) {
    // Initialize the maximum width and the queue for BFS with the root node
    let maxWidth = 0;
    let queue = [[root, 0]];

    // Perform BFS
    while (queue.length > 0) {
        // Get the size of the current level
        let levelSize = queue.length;

        // Initialize the minimum and maximum indices for the current level
        let minIndex = queue[0][1];
        let maxIndex = queue[0][1];

        // Process each node in the current level
        for (let i = 0; i < levelSize; i++) {
            // Get the current node and its index
            let [node, index] = queue.shift();

            // Update the minimum and maximum indices
            minIndex = Math.min(minIndex, index);
            maxIndex = Math.max(maxIndex, index);

            // Add the children of the current node to the queue
            if (node.left) queue.push([node.left, 2 * index + 1]);
            if (node.right) queue.push([node.right, 2 * index + 2]);
        }

        // Update the maximum width
        maxWidth = Math.max(maxWidth, maxIndex - minIndex + 1);
    }

    // Return the maximum width
    return maxWidth;
}

function strangePrinter(s) {
  const n = s.length;
  if (n === 0) return 0;
  const dp = Array.from({length: n}, () => new Array(n).fill(0));
  for (let i = n - 1; i >= 0; i--) {
    dp[i][i] = 1;
    for (let j = i + 1; j < n; j++) {
      if (s[i] === s[j]) {
        dp[i][j] = dp[i][j - 1];
      } else {
        let best = Infinity;
        for (let k = i; k < j; k++) best = Math.min(best, dp[i][k] + dp[k + 1][j]);
        dp[i][j] = best;
      }
    }
  }
  return dp[0][n - 1];
}

