    // If the current element is greater than the next element, increment the modified count
    if (nums[i] > nums[i + 1]) {
      // If the modified count is already 1, return false as we can't modify more than one element
      if (modifiedCount === 1) return false;
      // Check if modifying the current or next element would make the array non-decreasing
      if (i > 0 && nums[i - 1] > nums[i + 1] && i < nums.length - 2 && nums[i] > nums[i + 2]) return false;
      // Increment the modified count
      modifiedCount++;
    }
  }
