    for (let j = 0; j < words[i].length; j++) {
      bitmasks[i] |= 1 << (words[i].charCodeAt(j) - 'a'.charCodeAt(0));
    }
  }
  // Iterate over each pair of words and check if they share common letters
  for (let i = 0; i < words.length; i++) {
    for (let j = i + 1; j < words.length; j++) {
      // Check if the two words do not share common letters by performing a bitwise AND operation
      if ((bitmasks[i] & bitmasks[j]) === 0) {
