    // Sort the priority queue based on the height of the trees
    pq.sort((a, b) => a[0] - b[0]);

    // Initialize the total steps and the current position
    let totalSteps = 0;
    let currX = 0;
    let currY = 0;

    // Iterate over the trees in the priority queue
    for (let i = 0; i < pq.length; i++) {
        // Get the position of the next tree to be cut off
