        // Calculate the minimum steps to reach the next tree
        const steps = bfs(forest, currX, currY, nextX, nextY);
        if (steps === -1) {
            // If it's impossible to reach the next tree, return -1
            return -1;
        }

        // Update the total steps and the current position
        totalSteps += steps;
        currX = nextX;
        currY = nextY;

        // Mark the current tree as cut off
        forest[currX][currY] = 1;
    }

