// Breadth-First Search function to calculate the minimum steps to reach a target position
function bfs(forest, startX, startY, targetX, targetY) {
    // Get the number of rows and columns in the forest
    const rows = forest.length;
    const cols = forest[0].length;

    // Create a queue to store the positions to be visited
    const queue = [[startX, startY, 0]];

    // Create a set to store the visited positions
    const visited = new Set();
    visited.add(`${startX},${startY}`);

    // Define the possible directions
    const directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];

    // Iterate over the queue
    while (queue.length > 0) {
        // Get the current position and the number of steps
        const [x, y, steps] = queue.shift();

        // If the current position is the target position, return the number of steps
        if (x === targetX && y === targetY) {
            return steps;
        }

        // Iterate over the possible directions
        for (const [dx, dy] of directions) {
            // Calculate the next position
            const nextX = x + dx;
            const nextY = y + dy;

            // Check if the next position is valid and not visited
            if (nextX >= 0 && nextX < rows && nextY >= 0 && nextY < cols && forest[nextX][nextY] !== 0 && !visited.has(`${nextX},${nextY}`)) {
                // Add the next position to the queue and mark it as visited
                queue.push([nextX, nextY, steps + 1]);
                visited.add(`${nextX},${nextY}`);
            }
        }
    }

    // If the target position is not reachable, return -1
    return -1;
}

