function validUtf8(data) {
    let bytesLeft = 0;
    // Check each byte in the data array
    for (let i = 0; i < data.length; i++) {
        // Convert the integer to binary and remove the '0b' prefix
        let binary = data[i].toString(2).padStart(8, '0');
        // If there are no bytes left to process, this byte should be a single-byte character
        if (bytesLeft === 0) {
            // Check if the byte is a single-byte character (0xxxxxxx)
            if (binary[0] === '0') {
                continue;
            }
            // Check if the byte is a multi-byte character (110xxxxx, 1110xxxx, 11110xxx)
            else if (binary[0] === '1' && binary[1] === '1' && binary[2] === '0') {
                bytesLeft = 1;
            }
            // Check if the byte is a 3-byte character (1110xxxx)
            else if (binary[0] === '1' && binary[1] === '1' && binary[2] === '1' && binary[3] === '0') {
                bytesLeft = 2;
            }
            // Check if the byte is a 4-byte character (11110xxx)
            else if (binary[0] === '1' && binary[1] === '1' && binary[2] === '1' && binary[3] === '1' && binary[4] === '0') {
                bytesLeft = 3;
            }
            // If none of the above conditions are met, the byte is invalid
            else {
                return false;
            }
        }
        // If there are bytes left to process, this byte should be a continuation byte (10xxxxxx)
        else {
            // Check if the byte is a continuation byte
            if (binary[0] === '1' && binary[1] === '0') {
                bytesLeft--;
            }
            // If the byte is not a continuation byte, the sequence is invalid
            else {
                return false;
            }
        }
    }
    // If there are still bytes left to process after checking all bytes, the sequence is invalid
    if (bytesLeft !== 0) {
        return false;
    }
    // If the function has not returned false by now, the sequence is valid
    return true;
}

function maxNumber(nums1, nums2, k) {
    function pickMax(nums, k) {
        // pick the maximum k digits from nums
        let drop = nums.length - k;
        let out = [];
        for (let i = 0; i < nums.length; i++) {
            // remove smaller digits from the back of out
            while (out.length && drop && out[out.length - 1] < nums[i]) {
                out.pop();
                drop--;
            }
            out.push(nums[i]);
        }
        out = out.slice(0, k);
        return out;
    }

    function greater(a, b, aIndex, bIndex, maxLen) {
        // compare a and b from aIndex and bIndex to the end
        while (aIndex < a.length && bIndex < b.length) {
            if (a[aIndex] !== b[bIndex]) {
                return a[aIndex] > b[bIndex];
            }
            aIndex++;
            bIndex++;
        }
        // if one array is longer, it's greater
        return aIndex < a.length;
    }

    function merge(a, b) {
        // merge a and b into a single array
        let out = [];
        let i = 0, j = 0;
        while (i < a.length || j < b.length) {
            // compare a and b from i and j to the end
            if (j === b.length || (i < a.length && greater(a, b, i, j, a.length - i))) {
                out.push(a[i]);
                i++;
            } else {
                out.push(b[j]);
                j++;
            }
        }
        return out;
    }

    let max = [];
    for (let i = Math.max(0, k - nums2.length); i <= Math.min(k, nums1.length); i++) {
        // pick the maximum i digits from nums1 and k - i digits from nums2
        let candidate = merge(pickMax(nums1, i), pickMax(nums2, k - i));
        // update max if candidate is greater
        if (greater(candidate, max, 0, 0, candidate.length)) {
            max = candidate;
        }
    }
    return max;
}

