function shortestPathLength(graph) {
    const n = graph.length;
    const allNodesVisited = (1 << n) - 1;
    const queue = [];
    const visited = new Array(n).fill(0).map(() => new Array(1 << n).fill(false));
    for (let i = 0; i < n; i++) {
        queue.push([i, 1 << i, 0]); // node, bitmask, distance
        visited[i][1 << i] = true; // mark current node as visited
    }
    while (queue.length > 0) {
        const [node, bitmask, distance] = queue.shift();
        // if all nodes are visited, return the current distance
        if (bitmask === allNodesVisited) return distance;
        for (const neighbor of graph[node]) {
            const newBitmask = bitmask | (1 << neighbor);
            // if the neighbor is not visited before, mark it as visited and add it to the queue
            if (!visited[neighbor][newBitmask]) {
                queue.push([neighbor, newBitmask, distance + 1]);
                visited[neighbor][newBitmask] = true;
            }
        }
    }
    // this solution is already optimal with a time complexity of O(n * 2^n) and space complexity of O(n * 2^n)
}

function isNStraightHand(hand, groupSize) {
    // Create a hash map to store the frequency of each card
    var map = {};
    for (var i = 0; i < hand.length; i++) {
        // If the card is already in the map, increment its frequency
        if (map[hand[i]]) {
            map[hand[i]]++;
        } else {
            // If the card is not in the map, add it with a frequency of 1
            map[hand[i]] = 1;
        }
    }

    // Sort the keys of the map
    var keys = Object.keys(map).sort(function(a, b) {
        return a - b;
    });

    // Iterate over the sorted keys
    for (var i = 0; i < keys.length; i++) {
        // If the frequency of the current card is greater than 0
        while (map[keys[i]] > 0) {
            // Try to form a group of consecutive cards
            for (var j = 0; j < groupSize; j++) {
                // If the next consecutive card is not in the map or its frequency is 0
                if (!map[parseInt(keys[i]) + j] || map[parseInt(keys[i]) + j] === 0) {
                    // Return false because we cannot form a group of consecutive cards
                    return false;
                }
                // Decrement the frequency of the current card
                map[parseInt(keys[i]) + j]--;
            }
        }
    }

    // If we can form groups of consecutive cards for all cards, return true
    return true;
}

function scoreOfParentheses(s) {
