    for (let i = 0; i < s.length; i++) { // iterate over the string
        if (s[i] === '(') depth++; // if open parenthesis, increase depth
        else { // if close parenthesis
            depth--; // decrease depth
            if (s[i - 1] === '(') score += 1 << depth; // if previous is open, add score based on depth
        }
    }
