}

function possibleBipartition(n, dislikes) {
    // Create an adjacency list to represent the graph
    let graph = Array.from({ length: n + 1 }, () => []);
    for (let [u, v] of dislikes) {
        // Add edges to the graph
        graph[u].push(v);
        graph[v].push(u);
    }
    // Initialize the color array
    let color = Array.from({ length: n + 1 }, () => -1);
    for (let i = 1; i <= n; i++) {
        // If the node is not colored, perform DFS
        if (color[i] === -1) {
            // If DFS returns false, it's not possible to bipartite the graph
            if (!dfs(graph, color, i, 0)) return false;
        }
    }
    // If we can color all nodes, it's possible to bipartite the graph
    return true;
}

// Perform DFS to color the graph
function dfs(graph, color, node, currColor) {
    // Color the current node
    color[node] = currColor;
    for (let neighbor of graph[node]) {
        // If the neighbor is not colored, recursively color it with the opposite color
        if (color[neighbor] === -1) {
            // If DFS returns false, it's not possible to bipartite the graph
            if (!dfs(graph, color, neighbor, 1 - currColor)) return false;
        } else if (color[neighbor] === currColor) {
            // If the neighbor has the same color, it's not possible to bipartite the graph
            return false;
        }
    }
    // If we can color all neighbors, it's possible to bipartite the graph
    return true;
}

function kSimilarity(s1, s2) {
    // Create a queue for BFS, with the initial state being s1 and the number of swaps being 0
    let queue = [[s1, 0]];
    // Create a set to store visited states
    let visited = new Set([s1]);
    while (queue.length > 0) {
        // Dequeue the current state and the number of swaps
        let [curr, swaps] = queue.shift();
        // If the current state is equal to s2, return the number of swaps
        if (curr === s2) return swaps;
        // Iterate over the characters in the current state
        for (let i = 0; i < curr.length; i++) {
            // If the current character is not equal to the corresponding character in s2
            if (curr[i] !== s2[i]) {
                // Iterate over the remaining characters in the current state
                for (let j = i + 1; j < curr.length; j++) {
                    // If the current character in the current state is equal to the corresponding character in s2
                    if (curr[j] === s2[i]) {
                        // Create a new state by swapping the characters at indices i and j
                        let next = swap(curr, i, j);
                        // If the new state has not been visited
                        if (!visited.has(next)) {
                            // Mark the new state as visited
                            visited.add(next);
                            // Enqueue the new state and the updated number of swaps
                            queue.push([next, swaps + 1]);
                        }
                    }
                }
                // Break the loop as we have found a character that is not equal to the corresponding character in s2
                break;
            }
        }
    }
}

