function shortestPathAllKeys(grid) {
    // Get the number of rows and columns in the grid
    const rows = grid.length;
    const cols = grid[0].length;

    // Initialize variables to store the number of keys and locks
    let keys = 0;
    let locks = 0;

    // Initialize a queue for BFS, storing the current position, number of keys collected, and the number of steps taken
    const queue = [];

    // Initialize a set to store the visited positions
    const visited = new Set();

    // Iterate over the grid to find the starting position and count the number of keys and locks
    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            if (grid[i][j] === '@') {
                // Add the starting position to the queue
                queue.push([i, j, 0, 0]);
                // Mark the starting position as visited
                visited.add(`${i},${j},0`);
            } else if (grid[i][j] >= 'a' && grid[i][j] <= 'f') {
                // Increment the number of keys
                keys++;
            } else if (grid[i][j] >= 'A' && grid[i][j] <= 'F') {
                // Increment the number of locks
                locks++;
            }
        }
    }

    // Define the possible directions for movement
    const directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];

    // Perform BFS
    while (queue.length > 0) {
        // Dequeue the current position, number of keys collected, and the number of steps taken
        const [x, y, collectedKeys, steps] = queue.shift();

        // If all keys are collected, return the number of steps taken
        if (collectedKeys === (1 << keys) - 1) {
            return steps;
        }

        // Explore all possible directions
        for (const [dx, dy] of directions) {
            // Calculate the new position
            const nx = x + dx;
            const ny = y + dy;

            // Check if the new position is within the grid boundaries and is not a wall
            if (nx >= 0 && nx < rows && ny >= 0 && ny < cols && grid[nx][ny] !== '#') {
                // Get the new cell value
                const newCell = grid[nx][ny];

                // Check if the new cell is a key
                if (newCell >= 'a' && newCell <= 'f') {
                    // Calculate the new number of keys collected
                    const newCollectedKeys = collectedKeys | (1 << (newCell.charCodeAt(0) - 'a'.charCodeAt(0)));

                    // Check if the new position has not been visited before with the same number of keys collected
                    if (!visited.has(`${nx},${ny},${newCollectedKeys}`)) {
                        // Mark the new position as visited
                        visited.add(`${nx},${ny},${newCollectedKeys}`);
                        // Add the new position to the queue
                        queue.push([nx, ny, newCollectedKeys, steps + 1]);
                    }
                } 
                // Check if the new cell is a lock
                else if (newCell >= 'A' && newCell <= 'F') {
                    // Check if the corresponding key is collected
                    if (collectedKeys & (1 << (newCell.charCodeAt(0) - 'A'.charCodeAt(0)))) {
                        // Check if the new position has not been visited before with the same number of keys collected
                        if (!visited.has(`${nx},${ny},${collectedKeys}`)) {
                            // Mark the new position as visited
                            visited.add(`${nx},${ny},${collectedKeys}`);
                            // Add the new position to the queue
                            queue.push([nx, ny, collectedKeys, steps + 1]);
                        }
                    }
                } 
                // If the new cell is not a key or a lock, it's an empty space or the starting point
                else {
                    // Check if the new position has not been visited before with the same number of keys collected
                    if (!visited.has(`${nx},${ny},${collectedKeys}`)) {
                        // Mark the new position as visited
                        visited.add(`${nx},${ny},${collectedKeys}`);
                        // Add the new position to the queue
                        queue.push([nx, ny, collectedKeys, steps + 1]);
                    }
                }
            }
        }
    }

    // If all keys cannot be collected, return -1
    return -1;
}

class ExamRoom {
    constructor(n) {
        this.n = n;
        this.seats = [];
    }
    seat() {
        if (this.seats.length === 0) { this.seats.push(0); return 0; }
        let maxDistance = -1, seat = -1;
        let distance = this.seats[0];
        if (distance > maxDistance) { maxDistance = distance; seat = 0; }
        for (let i = 0; i < this.seats.length - 1; i++) {
            distance = Math.floor((this.seats[i + 1] - this.seats[i]) / 2);
            if (distance > maxDistance) { maxDistance = distance; seat = this.seats[i] + distance; }
        }
        distance = (this.n - 1) - this.seats[this.seats.length - 1];
        if (distance > maxDistance) { maxDistance = distance; seat = this.n - 1; }
        this.seats.push(seat);
        this.seats.sort((a, b) => a - b);
        return seat;
    }
    leave(p) {
        let index = this.seats.indexOf(p);
        if (index !== -1) this.seats.splice(index, 1);
    }
}

function mincostToHireWorkers(quality, wage, k) {
    let workers = quality.map((q, i) => [q, wage[i]]).map(([q, w]) => [w / q, q]);
    workers.sort((a, b) => a[0] - b[0]);
    let res = Infinity, qsum = 0, heap = [];
    for (let i = 0; i < workers.length; i++) {
        qsum += workers[i][1];
        heap.push(workers[i][1]);
        heap.sort((a, b) => a - b); // ascending, so pop() removes the largest quality
        if (heap.length > k) {
            qsum -= heap.pop();
        }
        if (i >= k - 1) {
            res = Math.min(res, qsum * workers[i][0]);
        }
    }
    return res;
}

