function increasingBST(root) {
    // Initialize a new root and a stack to store nodes for in-order traversal
    let newRoot = new TreeNode(null);
    let curr = newRoot;
    let stack = [];
    let node = root;

    // Traverse the tree in-order and update the new root
    while (node || stack.length) {
        // Go as far left as possible and push nodes to the stack
        while (node) {
            stack.push(node);
            node = node.left;
        }
        // Pop the leftmost node from the stack and update the new root
        node = stack.pop();
        // Update the new root and move to the right subtree
        curr.right = new TreeNode(node.val);
        curr = curr.right;
        node = node.right;
    }
    return newRoot.right;
}

function orderlyQueue(s, k) {
    // If k is greater than 1, the problem reduces to sorting the string
    if (k > 1) {
        // Split the string into an array of characters, sort it, and join it back into a string
        return s.split('').sort().join('');
    } else {
        // Initialize the result with the input string
        let result = s;
        // Iterate over each character in the string
        for (let i = 0; i < s.length; i++) {
            // Rotate the string by one character to the right
            let rotated = s.slice(i) + s.slice(0, i);
            // If the rotated string is lexicographically smaller than the current result, update the result
            if (rotated < result) {
                result = rotated;
            }
        }
        // Return the lexicographically smallest string
        return result;
    }
}

