function dieSimulator(n, rollMax) {
  const MOD = 1e9 + 7;
  const dp = Array.from({ length: n + 1 }, () => Array(6).fill(0).map(() => Array(16).fill(0)));
  for (let i = 0; i < 6; i++) {
    dp[1][i][1] = 1; // initialize the base case for each number
  }
  for (let i = 2; i <= n; i++) {
    for (let j = 0; j < 6; j++) {
      for (let k = 1; k <= 15; k++) {
        for (let prev = 0; prev < 6; prev++) {
          if (prev !== j) {
            dp[i][j][1] = (dp[i][j][1] + dp[i - 1][prev][k]) % MOD; // update dp for each number and consecutive count
          } else if (k < rollMax[j]) {
            dp[i][j][k + 1] = (dp[i][j][k + 1] + dp[i - 1][prev][k]) % MOD; // update dp for each number and consecutive count
          }
        }
      }
    }
  }
  let res = 0;
  for (let i = 0; i < 6; i++) {
    for (let j = 1; j <= 15; j++) {
      res = (res + dp[n][i][j]) % MOD; // calculate the total number of distinct sequences
    }
  }
  return res;
}

function threeEqualParts(arr) {
