    if (ones === 0) return [0, n - 1];
    if (ones % 3 !== 0) return [-1, -1];
    const k = ones / 3;
    let i1 = -1, i2 = -1, i3 = -1, count = 0;
    for (let i = 0; i < n; i++) {
        if (arr[i] === 1) {
            count++;
            if (count === 1) i1 = i;
            else if (count === k + 1) i2 = i;
            else if (count === 2 * k + 1) i3 = i;
        }
    }
    const len = n - i3;
    if (i1 + len > i2 || i2 + len > i3) return [-1, -1];
    for (let i = 0; i < len; i++) {
        if (arr[i1 + i] !== arr[i2 + i] || arr[i2 + i] !== arr[i3 + i]) return [-1, -1];
    }
    return [i1 + len - 1, i2 + len];
}

