function longestSubarray(nums) {
  let maxLength = 0;
  let left = 0, zeros = 0; 
  // Initialize two pointers and a counter for zeros in the current window
  for (let right = 0; right < nums.length; right++) {
    // If the current element is 0, increment the zeros counter
    if (nums[right] === 0) zeros++;
    // While there are more than one zeros in the window, move the left pointer to the right
    while (zeros > 1) {
      // If the element at the left pointer is 0, decrement the zeros counter
      if (nums[left] === 0) zeros--;
      // Move the left pointer to the right
      left++;
    }
    // Update the maximum length if the current window has more ones
    maxLength = Math.max(maxLength, right - left + 1 - zeros);
  }
  // If the maximum length is equal to the length of the array, decrement it by 1
  if (maxLength === nums.length) maxLength--;
  return maxLength;
}

function minimumInteger(num, k) {
    let digits = num.split(''); // convert string to array of characters
    let n = digits.length;
    for (let i = 0; i < n; i++) { 
        // find the minimum digit in the next k positions
        let minIndex = i;
        for (let j = i + 1; j <= i + k && j < n; j++) {
            if (digits[j] < digits[minIndex]) {
                minIndex = j;
            }
        }
        // swap the minimum digit with the current digit
        for (let j = minIndex; j > i; j--) {
            // swap digits[j] and digits[j - 1]
            [digits[j], digits[j - 1]] = [digits[j - 1], digits[j]];
            k--; // decrement k after each swap
        }
        if (k === 0) break; // stop if no more swaps are allowed
    }
    return digits.join(''); // convert array of characters back to string
}

function minNumberOfSemesters(n, relations, k) {
    // Create an adjacency list to represent the graph
    let graph = Array.from({length: n + 1}, () => []);
    let inDegree = Array(n + 1).fill(0);
    for (let [prev, next] of relations) {
        graph[prev].push(next);
        inDegree[next]++;
    }

    // Initialize the queue with nodes having in-degree 0
    let queue = [];
    for (let i = 1; i <= n; i++) {
        if (inDegree[i] === 0) {
            queue.push(i);
        }
    }

    // Initialize the count of visited nodes and the result (number of semesters)
    let visited = 0;
    let result = 0;

    // Perform BFS
    while (queue.length > 0) {
        // Dequeue at most k nodes in the current semester
        let size = queue.length;
        let dequeueCount = 0;
        for (let i = 0; i < size && dequeueCount < k; i++) {
            let node = queue.shift();
            visited++;
            dequeueCount++;
            // Decrease in-degree of neighboring nodes
            for (let neighbor of graph[node]) {
                inDegree[neighbor]--;
                // Enqueue neighboring nodes if their in-degree becomes 0
                if (inDegree[neighbor] === 0) {
                    queue.push(neighbor);
                }
            }
        }
        // Increment the result (number of semesters) if any nodes were dequeued
        if (dequeueCount > 0) {
            result++;
        }
    }

    return result;
}

function numSubmat(mat) {
    let m = mat.length, n = mat[0].length;
    let height = new Array(n).fill(0);
    let count = 0;
    // Calculate the height of each column and update the count of submatrices
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            height[j] = mat[i][j] === 1 ? height[j] + 1 : 0;
        }
        // Use a monotonic stack to calculate the count of submatrices
        let stack = [];
        for (let j = 0; j <= n; j++) {
            // Pop elements from the stack if the current height is less than the height at the top of the stack
            while (stack.length > 0 && (j === n || height[j] < height[stack[stack.length - 1]])) {
                let h = height[stack.pop()];
                let w = stack.length === 0 ? j : j - stack[stack.length - 1] - 1;
                count += h * w;
            }
            stack.push(j);
        }
    }
    return count;
}

