function maxProbability(n, edges, succProb, start, end) {
    // Create an adjacency list to represent the graph
    let graph = new Array(n).fill(0).map(() => new Array());
    for (let i = 0; i < edges.length; i++) {
        // Add edges to the graph with their corresponding probabilities
        graph[edges[i][0]].push([edges[i][1], succProb[i]]);
        graph[edges[i][1]].push([edges[i][0], succProb[i]]);
    }

    // Initialize the max probability for each node to 0
    let maxProb = new Array(n).fill(0);
    maxProb[start] = 1;

    // Use a priority queue to store nodes to be processed
    let pq = [[start, 1]];
    while (pq.length > 0) {
        // Get the node with the highest probability from the priority queue
        let [node, prob] = pq.shift();
        // If the current node is the end node, return its probability
        if (node === end) return prob;
        // If the current probability is less than the max probability, skip this node
        if (prob < maxProb[node]) continue;
        // Update the max probability for each neighbor of the current node
        for (let [neighbor, edgeProb] of graph[node]) {
            // Calculate the new probability for the neighbor
            let newProb = prob * edgeProb;
            // If the new probability is greater than the max probability, update it
            if (newProb > maxProb[neighbor]) {
                maxProb[neighbor] = newProb;
                // Add the neighbor to the priority queue
                pq.push([neighbor, newProb]);
                // Sort the priority queue in descending order of probability
                pq.sort((a, b) => b[1] - a[1]);
            }
        }
    }
    // If there is no path from start to end, return 0
    return 0;
}

