function maximumScore(a, b, c) {
    // The optimal strategy is to always remove stones from the two largest piles
    let score = 0;
    while (a > 0 && b > 0 || a > 0 && c > 0 || b > 0 && c > 0) {
        // Sort the piles in descending order
        let max = Math.max(a, b, c);
        let min = Math.min(a, b, c);
        let mid = a + b + c - max - min;
        // Remove one stone from the two largest piles
        if (max === a) {
            a--;
        } else if (max === b) {
            b--;
        } else {
