        score++;
    }
    return score;
}

function maxValue(events, k) {
    events.sort((a, b) => a[0] - b[0]);
    const n = events.length;
    const starts = events.map(e => e[0]);
    function bisectLeft(target) {
        let lo = 0, hi = n;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (starts[mid] < target) lo = mid + 1; else hi = mid;
        }
        return lo;
    }
    const memo = new Map();
    function dp(i, remaining) {
        if (remaining === 0 || i === n) return 0;
        const key = i + ',' + remaining;
        if (memo.has(key)) return memo.get(key);
        const skip = dp(i + 1, remaining);
        const nextIdx = bisectLeft(events[i][1] + 1);
        const take = events[i][2] + dp(nextIdx, remaining - 1);
        const result = Math.max(skip, take);
        memo.set(key, result);
        return result;
    }
    return dp(0, k);
}

