    for (let i = m - 1; i >= 0; i--) {
        for (let left = i; left >= 0; left--) {
            // Choose the maximum score between choosing from the start and choosing from the end
            dp[i][left] = Math.max(nums[left] * multipliers[i] + dp[i + 1][left + 1], nums[n - 1 - (i - left)] * multipliers[i] + dp[i + 1][left]);
