        const key = Math.min(u, v) + ',' + Math.max(u, v);
        sharedEdges.set(key, (sharedEdges.get(key) || 0) + 1);
    }
    let answers = new Array(queries.length).fill(0);
    for (let i = 0; i < queries.length; i++) {
