function findRedundantConnection(edges) {
    let parent = Array(edges.length + 1).fill(0).map((_, i) => i);
    // Iterate over each edge and check if the two nodes are already connected
    for (let edge of edges) {
        let node1 = edge[0], node2 = edge[1];
        // If the two nodes are already connected, return this edge as the redundant connection
        if (!union(parent, node1, node2)) return edge;
    }
    // Helper function to find the parent of a node
    function find(node) {
        if (parent[node] !== node) parent[node] = find(parent[node]);
        return parent[node];
    }
    // Helper function to union two nodes
    function union(parent, node1, node2) {
        let root1 = find(node1), root2 = find(node2);
        // If the two nodes are already connected, return false
        if (root1 === root2) return false;
        // Otherwise, union the two nodes
        parent[root1] = root2;
        return true;
    }
}

