function findRedundantDirectedConnection(edges) {
    const n = edges.length;
    const parent = new Array(n + 1).fill(0);
    let first = null, second = null, candidate = null;
    for (let i = 0; i < n; i++) {
        const [u, v] = edges[i];
        if (parent[v] !== 0) {
            first = [parent[v], v];
            second = [u, v];
            candidate = i;
        } else {
            parent[v] = u;
        }
    }
    const ufParent = Array.from({length: n + 1}, (_, i) => i);
    function find(x) {
        while (ufParent[x] !== x) { ufParent[x] = ufParent[ufParent[x]]; x = ufParent[x]; }
        return x;
    }
    for (let i = 0; i < n; i++) {
        if (i === candidate) continue; // skip the 'second' edge - try removing it first
        const [u, v] = edges[i];
        const ru = find(u), rv = find(v);
        if (ru === rv) {
            // a cycle exists even without 'second' - so 'second' wasn't the true problem
            return candidate !== null ? first : edges[i];
        }
        ufParent[rv] = ru;
    }
    // no cycle found once 'second' was removed (or there was no candidate at all)
    return candidate !== null ? second : null;
}

