    }
    dfs(root, null);
    return maxLength;
}

function knightProbability(n, k, row, column) {
  // Define the possible moves of a knight
  const moves = [[-2, -1], [-1, -2], [1, -2], [2, -1], [-2, 1], [-1, 2], [1, 2], [2, 1]];

  // Create a memoization table to store the probabilities
  const memo = Array.from({ length: n }, () => Array.from({ length: n }, () => Array.from({ length: k + 1 }, () => -1)));

  // Function to calculate the probability recursively
  function calculateProbability(x, y, movesLeft) {
    // If the knight is out of the board, return 0
    if (x < 0 || x >= n || y < 0 || y >= n) return 0;

    // If the knight has made all the moves, return 1
    if (movesLeft === 0) return 1;

    // If the probability is already calculated, return it
    if (memo[x][y][movesLeft] !== -1) return memo[x][y][movesLeft];

    // Calculate the probability recursively
    let probability = 0;
    for (const move of moves) {
      // Calculate the probability of the knight staying on the board after the move
      probability += calculateProbability(x + move[0], y + move[1], movesLeft - 1) / 8;
    }

    // Store the calculated probability in the memoization table
    memo[x][y][movesLeft] = probability;

    return probability;
  }

  // Calculate and return the probability
  return calculateProbability(row, column, k);
}

function maxSumOfThreeSubarrays(nums, k) {
