    for (let i = 0; i < n; i++) {
        prefixSum[i + 1] = prefixSum[i] + nums[i];
    }
    let sum1 = new Array(n - k + 1).fill(0);
    for (let i = 0; i <= n - k; i++) {
        // calculate sum of subarray of length k starting at index i
        sum1[i] = prefixSum[i + k] - prefixSum[i];
    }
    let sum2 = new Array(n - 2 * k + 1).fill(0);
    for (let i = 0; i <= n - 2 * k; i++) {
        // calculate sum of two non-overlapping subarrays of length k starting at index i
        let maxSum = -Infinity;
        for (let j = i + k; j <= n - k; j++) {
            maxSum = Math.max(maxSum, sum1[i] + sum1[j]);
        }
        sum2[i] = maxSum;
    }
    let maxSum = -Infinity;
    let result = [];
    for (let i = 0; i <= n - 3 * k; i++) {
        // calculate sum of three non-overlapping subarrays of length k starting at index i
        for (let j = i + k; j <= n - 2 * k; j++) {
            for (let m = j + k; m <= n - k; m++) {
                let currentSum = sum1[i] + sum1[j] + sum1[m];
                if (currentSum > maxSum) {
                    maxSum = currentSum;
                    result = [i, j, m];
                } else if (currentSum === maxSum) {
                    // if sums are equal, choose the lexicographically smaller one
                    if (i < result[0] || (i === result[0] && j < result[1]) || (i === result[0] && j === result[1] && m < result[2])) {
                        result = [i, j, m];
