  // Define a recursive function to calculate the total importance value
  function dfs(employeeId) {
    // Get the current employee's information from the hash table
    const employee = employeeMap.get(employeeId);
    // Calculate the total importance value by adding the current employee's importance and their subordinates' importance
    let totalImportance = employee[1];
