function topKFrequent(words, k) {
    // Create a hash map to store the frequency of each word
    var frequencyMap = {};
    for (var word of words) {
        // If the word is already in the map, increment its frequency
        if (word in frequencyMap) {
            frequencyMap[word]++;
        } else {
            // Otherwise, add it to the map with a frequency of 1
            frequencyMap[word] = 1;
        }
    }

    // Create an array of words and their frequencies
    var wordFrequencies = [];
    for (var word in frequencyMap) {
        // Push each word and its frequency into the array
        wordFrequencies.push([word, frequencyMap[word]]);
    }

    // Sort the array based on the frequency and lexicographical order
    wordFrequencies.sort(function(a, b) {
        // If the frequencies are different, sort by frequency in descending order
        if (a[1] !== b[1]) {
            return b[1] - a[1];
        } else {
            // If the frequencies are the same, sort by lexicographical order
            return a[0].localeCompare(b[0]);
        }
    });

    // Return the top k words
    var result = [];
    for (var i = 0; i < k; i++) {
        // Push each word into the result array
        result.push(wordFrequencies[i][0]);
    }
    return result;
}

