  const memo = new Map();
  function dfs(remaining) {
    if (remaining === '') return 0;
    if (memo.has(remaining)) return memo.get(remaining);
    let best = Infinity;
    const firstIdx = remaining.charCodeAt(0) - 97;
    for (let i = 0; i < n; i++) {
      if (stickerCounts[i][firstIdx] === 0) continue;
      const used = stickerCounts[i].slice();
      let next = '';
      for (const c of remaining) {
        const idx = c.charCodeAt(0) - 97;
        if (used[idx] > 0) used[idx]--;
        else next += c;
      }
      if (next.length < remaining.length) {
        const res = dfs(next);
        if (res !== -1) best = Math.min(best, res + 1);
      }
    }
    const result = best === Infinity ? -1 : best;
    memo.set(remaining, result);
    return result;
  }
  return dfs(target);
}

function hasAlternatingBits(n) {
