  // Iterate over the binary string to check for alternating bits
  for (var i = 0; i < binary.length - 1; i++) 
    // If two adjacent bits are the same, return false
    if (binary[i] === binary[i + 1]) return false;
  // If no adjacent bits are the same, return true
  return true;
}

function maxAreaOfIsland(grid) {
    // Algorithm solution is already optimal, using DFS to explore all connected land cells
    if (!grid || grid.length === 0) return 0;
    let maxArea = 0;
    for (let i = 0; i < grid.length; i++) {
        for (let j = 0; j < grid[0].length; j++) {
            if (grid[i][j] === 1) {
                let area = dfs(grid, i, j);
                maxArea = Math.max(maxArea, area);
            }
        }
    }
    return maxArea;
}

function dfs(grid, i, j) {
    // If the current cell is out of bounds or is water, return 0
    if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length || grid[i][j] === 0) return 0;
    // Mark the current cell as visited by setting it to 0
    grid[i][j] = 0;
    // Recursively explore all neighboring land cells and sum their areas
    return 1 + dfs(grid, i - 1, j) + dfs(grid, i + 1, j) + dfs(grid, i, j - 1) + dfs(grid, i, j + 1);
}

function countBinarySubstrings(s) {
  let count = 0;
  let prev = 0, curr = 1; // initialize previous and current counts
  // iterate through the string and update counts when encountering different characters
  for (let i = 1; i < s.length; i++) {
    // if current character is different from previous one, update counts
    if (s[i] !== s[i - 1]) {
      count += Math.min(prev, curr); // add minimum of previous and current counts
      prev = curr; // update previous count
      curr = 1; // reset current count
    } else {
      // if current character is the same as previous one, increment current count
      curr++;
    }
  }
  // add minimum of previous and current counts one last time
  count += Math.min(prev, curr);
  return count;
}

function findShortestSubArray(nums) {
    // Create a hash map to store the frequency, first index, and last index of each element
    var map = {};
    for (var i = 0; i < nums.length; i++) {
        if (!map[nums[i]]) {
            map[nums[i]] = { frequency: 0, firstIndex: i, lastIndex: i };
        }
        map[nums[i]].frequency++;
        map[nums[i]].lastIndex = i;
    }

    // Find the maximum frequency
    var maxFrequency = 0;
    for (var key in map) {
        maxFrequency = Math.max(maxFrequency, map[key].frequency);
    }

    // Find the minimum length of the subarray with the maximum frequency
    var minLength = Infinity;
    for (var key in map) {
        if (map[key].frequency === maxFrequency) {
            minLength = Math.min(minLength, map[key].lastIndex - map[key].firstIndex + 1);
        }
    }

    return minLength;
}

function canPartitionKSubsets(nums, k) {
    // calculate the total sum of the array
    let totalSum = nums.reduce((a, b) => a + b, 0);
    // if the total sum is not divisible by k, it's impossible to divide the array into k subsets with equal sums
    if (totalSum % k !== 0) return false;
    // calculate the target sum for each subset
    let targetSum = totalSum / k;
    // sort the array in descending order
    nums.sort((a, b) => b - a);
    // create an array to store the current sums of each subset
    let subsetSums = new Array(k).fill(0);
    // use a recursive function to try to assign each number to a subset
    function backtrack(index) {
        // if we've assigned all numbers to subsets, check if all subsets have the target sum
        if (index === nums.length) return subsetSums.every(sum => sum === targetSum);
        // try to assign the current number to each subset
        for (let i = 0; i < k; i++) {
            // if adding the current number to the current subset would exceed the target sum, skip this subset
            if (subsetSums[i] + nums[index] > targetSum) continue;
            // add the current number to the current subset
            subsetSums[i] += nums[index];
            // recursively try to assign the remaining numbers to subsets
            if (backtrack(index + 1)) return true;
            // if we couldn't assign the remaining numbers to subsets, remove the current number from the current subset
            subsetSums[i] -= nums[index];
        }
        // if we couldn't assign the current number to any subset, return false
        return false;
    }
    // start the backtracking process
    return backtrack(0);
}

function fallingSquares(positions) {
    let ans = [], heights = [], max = 0;
    for (let i = 0; i < positions.length; i++) {
        let left = positions[i][0], side = positions[i][1];
        let right = left + side;
        let height = 0;
        // calculate the height of the current square by checking the heights of the squares it overlaps with
        for (let j = 0; j < heights.length; j++) {
            if (heights[j][0] < right && heights[j][1] > left) {
                height = Math.max(height, heights[j][2]);
            }
        }
        height += side;
        // update the heights array with the new square's height
        heights.push([left, right, height]);
        // update the max height
        max = Math.max(max, height);
        ans.push(max);
    }
    return ans;
}

function searchBST(root, val) {
    // if the tree is empty, return null
    if (root === null) return null;
    // if the current node's value matches the target, return the subtree rooted at this node
    if (root.val === val) return root;
    // if the target value is less than the current node's value, search in the left subtree
    if (val < root.val) return searchBST(root.left, val);
    // if the target value is greater than the current node's value, search in the right subtree
    return searchBST(root.right, val);
}

function insertIntoBST(root, val) {
    // if the tree is empty, create a new node
    if (!root) return { val, left: null, right: null };
    // if the value is less than the current node, insert into the left subtree
    if (val < root.val) root.left = insertIntoBST(root.left, val);
    // if the value is greater than the current node, insert into the right subtree
    else root.right = insertIntoBST(root.right, val);
    return root;
}

class KthLargest {
    constructor(k, nums) {
        this.k = k;
        this.minHeap = [];
        for (const n of nums) this.add(n);
    }
    add(val) {
        this._push(val);
        if (this.minHeap.length > this.k) this._pop();
        return this.minHeap[0];
    }
    _push(val) {
        this.minHeap.push(val);
        let i = this.minHeap.length - 1;
        while (i > 0) {
            const parent = (i - 1) >> 1;
            if (this.minHeap[parent] <= this.minHeap[i]) break;
            [this.minHeap[parent], this.minHeap[i]] = [this.minHeap[i], this.minHeap[parent]];
            i = parent;
        }
    }
    _pop() {
        const n = this.minHeap.length;
        this.minHeap[0] = this.minHeap[n - 1];
        this.minHeap.pop();
        let i = 0;
        const m = this.minHeap.length;
        while (true) {
            let left = 2*i+1, right = 2*i+2, smallest = i;
            if (left < m && this.minHeap[left] < this.minHeap[smallest]) smallest = left;
            if (right < m && this.minHeap[right] < this.minHeap[smallest]) smallest = right;
            if (smallest === i) break;
            [this.minHeap[i], this.minHeap[smallest]] = [this.minHeap[smallest], this.minHeap[i]];
            i = smallest;
        }
    }
}

function search(nums, target) {
  // Initialize two pointers, low and high, to the start and end of the array
  let low = 0;
  let high = nums.length - 1;
  // Continue the search until the two pointers meet
  while (low <= high) {
    // Calculate the middle index
    let mid = Math.floor((low + high) / 2);
    // If the target is found at the middle index, return the index
    if (nums[mid] === target) return mid;
    // If the target is less than the middle element, move the high pointer to the left
    else if (nums[mid] > target) high = mid - 1;
    // If the target is greater than the middle element, move the low pointer to the right
    else low = mid + 1;
  }
  // If the target is not found, return -1
  return -1;
}

