function MyHashMap() {
    // Initialize an empty array to store key-value pairs
    this.map = new Array(1000);
}

MyHashMap.prototype.put = function(key, value) {
    // Calculate the index using the modulo operator to handle collisions
    const index = key % 1000;
    // If the index is empty, create a new array to store key-value pairs
    if (!this.map[index]) this.map[index] = [];
    // Iterate through the array at the calculated index to find the key
    for (let i = 0; i < this.map[index].length; i++) {
        // If the key is found, update its value
        if (this.map[index][i][0] === key) { this.map[index][i][1] = value; return; }
    }
    // If the key is not found, add a new key-value pair to the array
    this.map[index].push([key, value]);
}

MyHashMap.prototype.get = function(key) {
    // Calculate the index using the modulo operator to handle collisions
    const index = key % 1000;
    // If the index is empty, return -1 as the key is not found
    if (!this.map[index]) return -1;
    // Iterate through the array at the calculated index to find the key
    for (let i = 0; i < this.map[index].length; i++) {
        // If the key is found, return its value
        if (this.map[index][i][0] === key) return this.map[index][i][1];
    }
    // If the key is not found, return -1
    return -1;
}

MyHashMap.prototype.remove = function(key) {
    // Calculate the index using the modulo operator to handle collisions
    const index = key % 1000;
    // If the index is empty, do nothing as the key is not found
    if (!this.map[index]) return;
    // Iterate through the array at the calculated index to find the key
    for (let i = 0; i < this.map[index].length; i++) {
        // If the key is found, remove it from the array
        if (this.map[index][i][0] === key) { this.map[index].splice(i, 1); return; }
    }
}

function MyLinkedList() {
    // Initialize the head of the linked list as null
    let head = null;
    // Initialize the tail of the linked list as null
    let tail = null;
    // Initialize the size of the linked list as 0
    let size = 0;

    function getNode(index) {
        // If the index is less than or equal to half of the size, start from the head
        if (index <= size / 2) {
            let node = head;
            // Traverse the linked list from the head to the index
            for (let i = 0; i < index; i++) {
                node = node.next;
            }
            return node;
        } else {
            // If the index is greater than half of the size, start from the tail
            let node = tail;
            // Traverse the linked list from the tail to the index
            for (let i = 0; i < size - index - 1; i++) {
                node = node.prev;
            }
            return node;
        }
    }

    this.addAtHead = function(val) {
        // Create a new node with the given value
        let newNode = { val: val, next: null, prev: null };
        // If the linked list is empty, set the head and tail to the new node
        if (head === null) {
            head = newNode;
            tail = newNode;
        } else {
            // Otherwise, set the next of the new node to the head and the prev of the head to the new node
            newNode.next = head;
            head.prev = newNode;
            // Update the head to the new node
            head = newNode;
        }
        // Increment the size of the linked list
        size++;
    };

    this.addAtTail = function(val) {
        // Create a new node with the given value
        let newNode = { val: val, next: null, prev: null };
        // If the linked list is empty, set the head and tail to the new node
        if (tail === null) {
            head = newNode;
            tail = newNode;
        } else {
            // Otherwise, set the prev of the new node to the tail and the next of the tail to the new node
            newNode.prev = tail;
            tail.next = newNode;
            // Update the tail to the new node
            tail = newNode;
        }
        // Increment the size of the linked list
        size++;
    };

    this.addAtIndex = function(index, val) {
        // If the index is 0, add at the head
        if (index === 0) {
            this.addAtHead(val);
        } else if (index === size) {
            // If the index is equal to the size, add at the tail
            this.addAtTail(val);
        } else if (index < 0 || index > size) {
            // If the index is out of range, do nothing
            return;
        } else {
            // Get the node at the index - 1
            let prevNode = getNode(index - 1);
            // Create a new node with the given value
            let newNode = { val: val, next: null, prev: null };
            // Set the next of the new node to the next of the previous node and the prev of the new node to the previous node
            newNode.next = prevNode.next;
            newNode.prev = prevNode;
            // Set the next of the previous node to the new node and the prev of the next node to the new node
            prevNode.next.prev = newNode;
            prevNode.next = newNode;
            // Increment the size of the linked list
            size++;
        }
    };

    this.deleteAtIndex = function(index) {
        // If the index is out of range, do nothing
        if (index < 0 || index >= size) {
            return;
        }
        // If the index is 0, remove the head
        if (index === 0) {
            // If the linked list has only one node, set the head and tail to null
            if (size === 1) {
                head = null;
                tail = null;
            } else {
                // Otherwise, set the head to the next of the head and the prev of the new head to null
                head = head.next;
                head.prev = null;
            }
        } else if (index === size - 1) {
            // If the index is equal to the size - 1, remove the tail
            // Set the tail to the previous of the tail and the next of the new tail to null
            tail = tail.prev;
            tail.next = null;
        } else {
            // Get the node at the index
            let node = getNode(index);
            // Set the next of the previous node to the next of the node and the prev of the next node to the previous node
            node.prev.next = node.next;
            node.next.prev = node.prev;
        }
        // Decrement the size of the linked list
        size--;
    };

    this.get = function(index) {
        // If the index is out of range, return -1
        if (index < 0 || index >= size) {
            return -1;
        }
        // Get the node at the index and return its value
        return getNode(index).val;
    };
}

