class Solution {
    constructor(n, blacklist) {
        this.blacklisted = new Set(blacklist);
        this.n = n;
    }
    pick() {
        const nonBlacklistedCount = this.n - this.blacklisted.size;
        const randomIndex = Math.floor(Math.random() * nonBlacklistedCount);
        let count = 0;
        for (let i = 0; i < this.n; i++) {
