    }
}

function minimumDeleteSum(s1, s2) {
    // Initialize a 2D array to store the minimum ASCII sum of deleted characters for subproblems
    let dp = Array(s1.length + 1).fill(0).map(() => Array(s2.length + 1).fill(0));

    // Fill the first row and first column of the 2D array
    for (let i = 1; i <= s1.length; i++) // Initialize the first column
        dp[i][0] = dp[i - 1][0] + s1.charCodeAt(i - 1);
    for (let j = 1; j <= s2.length; j++) // Initialize the first row
        dp[0][j] = dp[0][j - 1] + s2.charCodeAt(j - 1);

    // Fill the rest of the 2D array
    for (let i = 1; i <= s1.length; i++)
        for (let j = 1; j <= s2.length; j++)
            // If the current characters in s1 and s2 are the same, no deletion is needed
            if (s1[i - 1] === s2[j - 1])
                dp[i][j] = dp[i - 1][j - 1];
            // Otherwise, consider deleting the current character from s1 or s2
            else
                dp[i][j] = Math.min(dp[i - 1][j] + s1.charCodeAt(i - 1), dp[i][j - 1] + s2.charCodeAt(j - 1));

    // The minimum ASCII sum of deleted characters is stored in the bottom-right corner of the 2D array
    return dp[s1.length][s2.length];
}

function numSubarrayProductLessThanK(nums, k) {
    // Initialize the count of subarrays and the product of the current window
    let count = 0, product = 1;
    // Initialize the left pointer of the window
    let left = 0;
    // Iterate over the array with the right pointer of the window
    for (let right = 0; right < nums.length; right++) {
        // Update the product of the current window
        product *= nums[right];
        // Shrink the window from the left until the product is less than k
        while (product >= k && left <= right) {
            // Update the product of the current window
            product /= nums[left];
            // Move the left pointer to the right
            left++;
        }
        // Update the count of subarrays
        count += right - left + 1;
    }
    // This algorithm is already optimal with a time complexity of O(n)
    return count;
}

function maxProfit(prices, fee) {
    let hold = -prices[0]; // initialize hold as -price of first stock
    let sold = 0; // initialize sold as 0
    for (let i = 1; i < prices.length; i++) {
        // update hold and sold using dynamic programming
        let newHold = Math.max(hold, sold - prices[i]);
        let newSold = Math.max(sold, hold + prices[i] - fee);
        hold = newHold; // update hold for next iteration
        sold = newSold; // update sold for next iteration
    }
    return sold; // return maximum profit
}

class RangeModule {
    constructor() { this.intervals = []; }
    addRange(left, right) {
        let i = 0;
        while (i < this.intervals.length && this.intervals[i][1] < left) i++;
        let start = left;
        while (i < this.intervals.length && this.intervals[i][0] <= right) {
            start = Math.min(start, this.intervals[i][0]);
            right = Math.max(right, this.intervals[i][1]);
            this.intervals.splice(i, 1);
        }
        this.intervals.splice(i, 0, [start, right]);
    }
    queryRange(left, right) {
        let i = 0;
        while (i < this.intervals.length && this.intervals[i][1] < left) i++;
        return i < this.intervals.length && this.intervals[i][0] <= left && this.intervals[i][1] >= right;
    }
    removeRange(left, right) {
        let i = 0;
        while (i < this.intervals.length) {
            const [s, e] = this.intervals[i];
            if (s < right && e > left) {
                const pieces = [];
                if (s < left) pieces.push([s, left]);
                if (e > right) pieces.push([right, e]);
                this.intervals.splice(i, 1, ...pieces);
                i += pieces.length;
            } else {
                i++;
            }
        }
    }
}

function isOneBitCharacter(bits) {
    // iterate through the array and keep track of the index
    let i = 0;
    while (i < bits.length - 1) {
        // if the current bit is 1, it's a 2-bit character, so skip the next bit
        if (bits[i] === 1) {
            i += 2;
        } else {
            // if the current bit is 0, it's a 1-bit character, so move to the next bit
            i += 1;
        }
    }
    // if the last character is a 1-bit character, the index should be at the second last position
    return i === bits.length - 1;
}

function findLength(nums1, nums2) {
    // Initialize a 2D array to store the lengths of common subarrays
    let dp = Array(nums1.length + 1).fill(0).map(() => Array(nums2.length + 1).fill(0));
    let maxLength = 0;
    // Iterate over both arrays and update the dp array
    for (let i = 1; i <= nums1.length; i++) {
        for (let j = 1; j <= nums2.length; j++) {
            // If the current elements are equal, update the length of the common subarray
            if (nums1[i - 1] === nums2[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
                // Update the maximum length
                maxLength = Math.max(maxLength, dp[i][j]);
            }
        }
    }
    return maxLength;
}

function smallestDistancePair(nums, k) {
  // Sort the array in ascending order
  nums.sort((a, b) => a - b);
  let left = 0, right = nums[nums.length - 1] - nums[0];
  while (left < right) {
    // Calculate the mid distance
    let mid = Math.floor((left + right) / 2);
    // Count the number of pairs with distance less than or equal to mid
    let count = 0, j = 0;
    for (let i = 0; i < nums.length; i++) {
      // Move the j pointer to the right until the distance is greater than mid
      while (j < nums.length && nums[j] - nums[i] <= mid) {
        j++;
      }
      // Update the count
      count += j - i - 1;
    }
    // If the count is less than k, update the left pointer
    if (count < k) {
      left = mid + 1;
    } 
    // If the count is greater than or equal to k, update the right pointer
    else {
      right = mid;
    }
  }
  // The kth smallest distance is the left pointer
  return left;
}

function longestWord(words) {
    // Create a set to store all words for efficient lookups
    var wordSet = new Set(words);
    var longest = "";
    // Iterate over each word in the dictionary
    for (var word of words) {
        // Initialize a flag to check if the word can be built
        var canBeBuilt = true;
        // Check if the word can be built by removing one character at a time
        for (var i = 1; i < word.length; i++) {
            // If the word without the last character is not in the set, it cannot be built
            if (!wordSet.has(word.substring(0, i))) {
                canBeBuilt = false;
                break;
            }
        }
        // If the word can be built and it's longer than the current longest word, or it's the same length but lexicographically smaller, update the longest word
        if (canBeBuilt && (word.length > longest.length || (word.length === longest.length && word < longest))) {
            longest = word;
        }
    }
    return longest;
}

function removeComments(source) {
    let result = [];
    let blockComment = false;
    let currentLine = '';
    for (let i = 0; i < source.length; i++) {
        let line = source[i];
