                j++;
            }
        }
        // if not in block comment and current line is not empty, add it to result
        if (!blockComment && currentLine.trim() !== '') {
            result.push(currentLine.trim());
            currentLine = '';
        }
    }
    return result;
}

function accountsMerge(accounts) {
    // Create a parent array to store the parent of each email
    let parent = {};
    // Create a name array to store the name of each email
    let name = {};

    // Initialize the parent and name arrays
    for (let account of accounts) {
        for (let email of account.slice(1)) {
            // Initialize the parent of each email to itself
            parent[email] = email;
            // Store the name of each email
            name[email] = account[0];
        }
    }

    // Create a function to find the parent of an email
    function find(email) {
        // If the parent of the email is itself, return the email
        if (parent[email] === email) return email;
        // Otherwise, recursively find the parent of the email
        return parent[email] = find(parent[email]);
    }

    // Create a function to union two emails
    function union(email1, email2) {
        // Find the parents of the two emails
        let parent1 = find(email1);
        let parent2 = find(email2);
        // If the parents are different, union the two emails
        if (parent1 !== parent2) parent[parent1] = parent2;
    }

    // Union emails that belong to the same account
    for (let account of accounts) {
        for (let i = 1; i < account.length - 1; i++) {
            // Union the current email with the next email
            union(account[i], account[i + 1]);
        }
    }

    // Create a map to store the merged emails
    let merged = {};
    // Merge the emails
    for (let email in parent) {
        // Find the parent of the email
        let parentEmail = find(email);
        // If the parent email is not in the merged map, add it
        if (!merged[parentEmail]) merged[parentEmail] = [];
        // Add the email to the merged map
        merged[parentEmail].push(email);
    }

    // Create the result array
    let result = [];
    // Create the result accounts
    for (let parentEmail in merged) {
        // Sort the emails
        let emails = merged[parentEmail].sort();
        // Add the name and emails to the result array
        result.push([name[parentEmail]].concat(emails));
    }

    return result;
}

function pivotIndex(nums) {
    // calculate the total sum of the array
    let totalSum = 0;
    for (let i = 0; i < nums.length; i++) {
        totalSum += nums[i];
    }
    // initialize the left sum to 0
    let leftSum = 0;
    // iterate through the array to find the pivot index
    for (let i = 0; i < nums.length; i++) {
        // if the left sum is equal to the total sum minus the left sum and the current element, return the current index
        if (leftSum === totalSum - leftSum - nums[i]) {
            return i;
        }
        // update the left sum by adding the current element
        leftSum += nums[i];
    }
    // if no pivot index is found, return -1
    return -1;
}

function splitListToParts(head, k) {
    // calculate the length of the linked list
    let length = 0;
    let temp = head;
    while (temp) {
        length++;
        temp = temp.next;
    }

    // calculate the size of each part
    let size = Math.floor(length / k);
    let remainder = length % k;

    // initialize the result array
    let result = new Array(k);

    // initialize the current node and index
    temp = head;
    for (let i = 0; i < k; i++) {
        // calculate the size of the current part
        let partSize = size + (i < remainder ? 1 : 0);
        // initialize the current part
        let partHead = temp;
        // initialize the previous node
        let prev = null;
        // traverse the current part
        for (let j = 0; j < partSize; j++) {
            // update the previous node
            prev = temp;
            // move to the next node
            temp = temp.next;
        }
        // set the next of the last node in the current part to null
        if (prev) prev.next = null;
        // add the current part to the result array
        result[i] = partHead;
    }

    return result;
}

function countOfAtoms(formula) {
    let i = 0;
    const n = formula.length;

    function parseCount() {
        let start = i;
        while (i < n && formula[i] >= '0' && formula[i] <= '9') i++;
        return i > start ? parseInt(formula.slice(start, i)) : 1;
    }

    function parse() {
        const stack = [new Map()];
        while (i < n) {
            const ch = formula[i];
            if (ch === '(') {
                i++;
                stack.push(new Map());
            } else if (ch === ')') {
                i++;
                const count = parseCount();
                const top = stack.pop();
                const target = stack[stack.length - 1];
                for (const [name, c] of top) {
                    target.set(name, (target.get(name) || 0) + c * count);
                }
            } else {
                let start = i;
                i++;
                while (i < n && formula[i] >= 'a' && formula[i] <= 'z') i++;
                const name = formula.slice(start, i);
                const count = parseCount();
                const target = stack[stack.length - 1];
                target.set(name, (target.get(name) || 0) + count);
            }
        }
        return stack[0];
    }

    const counts = parse();
    const names = [...counts.keys()].sort();
    let result = '';
    for (const name of names) {
        result += name;
        const c = counts.get(name);
        if (c > 1) result += c;
    }
    return result;
}

function selfDividingNumbers(left, right) {
    function isSelfDividing(num) {
        // Check if the number is divisible by every digit it contains
        let temp = num;
        while (temp > 0) {
            let digit = temp % 10;
            // If the digit is zero or the number is not divisible by the digit, return false
            if (digit === 0 || num % digit !== 0) return false;
            temp = Math.floor(temp / 10);
        }
        return true;
    }

    let result = [];
    // Iterate over the range [left, right] and check if each number is self-dividing
    for (let i = left; i <= right; i++) {
        if (isSelfDividing(i)) result.push(i);
    }
    return result;
}

