    this.events.push([start, end]);
    this.events.sort(function(a, b) { return a[0] - b[0]; });

    // Main logic: initialize variables to track the maximum k-booking
    let maxK = 0;
    let currentK = 0;
    let endTimes = [];

    // Main logic: iterate over the sorted events to find the maximum k-booking
    for (let i = 0; i < this.events.length; i++) {
        // Main logic: remove end times that are earlier than the current event's start time
        while (endTimes.length > 0 && endTimes[0] <= this.events[i][0]) {
            endTimes.shift();
            currentK--;
        }

        // Main logic: add the current event's end time to the list and increment the current k-booking
        endTimes.push(this.events[i][1]);
        endTimes.sort(function(a, b) { return a - b; });
        currentK++;

        // Main logic: update the maximum k-booking
        maxK = Math.max(maxK, currentK);
    }

    return maxK;
}

function floodFill(image, sr, sc, color) {
    // Check if the target color is the same as the starting pixel's color
    if (image[sr][sc] === color) return image;

    // Define the directions for DFS
    const directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];

    // Store the original color of the starting pixel
    const originalColor = image[sr][sc];

    // Perform DFS from the starting pixel
    function dfs(row, col) {
        // Check if the current pixel is within the image boundaries and has the same color as the starting pixel
        if (row < 0 || row >= image.length || col < 0 || col >= image[0].length || image[row][col] !== originalColor) return;

        // Change the color of the current pixel to the target color
        image[row][col] = color;

        // Recursively perform DFS on the neighboring pixels
        for (const direction of directions) {
            dfs(row + direction[0], col + direction[1]);
        }
    }

    // Start the DFS from the starting pixel
    dfs(sr, sc);

    return image;
}

function asteroidCollision(asteroids) {
    var stack = [];
    for (var i = 0; i < asteroids.length; i++) {
        var alive = true;
        while (alive && asteroids[i] < 0 && stack.length > 0 && stack[stack.length - 1] > 0) {
            if (stack[stack.length - 1] < -asteroids[i]) {
                stack.pop();
            } else if (stack[stack.length - 1] === -asteroids[i]) {
                stack.pop();
                alive = false;
            } else {
                alive = false;
            }
        }
        if (alive) stack.push(asteroids[i]);
    }
    return stack;
}

function evalLisp(expression) {
    function tokenize(s) {
        const tokens = [];
        let depth = 0, start = 0;
        for (let i = 0; i < s.length; i++) {
            if (s[i] === '(') depth++;
            else if (s[i] === ')') depth--;
            else if (s[i] === ' ' && depth === 0) {
                tokens.push(s.slice(start, i));
                start = i + 1;
            }
        }
        tokens.push(s.slice(start));
        return tokens;
    }
    function helper(expr, scope) {
        if (expr[0] !== '(') {
            if (!isNaN(parseInt(expr[0])) || expr[0] === '-') return parseInt(expr);
            for (let i = scope.length - 1; i >= 0; i--) {
                if (scope[i].has(expr)) return scope[i].get(expr);
            }
        }
        const inner = expr.slice(1, -1);
        const tokens = tokenize(inner);
        if (tokens[0] === 'let') {
            const newScope = new Map();
            scope.push(newScope);
            let i = 1;
            while (i < tokens.length - 1) {
                newScope.set(tokens[i], helper(tokens[i + 1], scope));
                i += 2;
            }
            const result = helper(tokens[tokens.length - 1], scope);
            scope.pop();
            return result;
        } else if (tokens[0] === 'add') {
            return helper(tokens[1], scope) + helper(tokens[2], scope);
        } else {
            return helper(tokens[1], scope) * helper(tokens[2], scope);
        }
    }
    return helper(expression, []);
}

function monotoneIncreasingDigits(n) {
