        if (numStr[i] < numStr[i - 1]) {
            numStr = numStr.substring(0, i - 1) + (parseInt(numStr[i - 1]) - 1).toString() + numStr.substring(i);
            numStr = numStr.substring(0, i) + '9' + numStr.substring(i + 1);
        }
    }
    return parseInt(numStr);
}

function dailyTemperatures(temperatures) {
  const result = new Array(temperatures.length).fill(0); // initialize result array with zeros
  const stack = []; // initialize stack to store indices of temperatures
  for (let i = 0; i < temperatures.length; i++) { // iterate through temperatures array
    // while stack is not empty and current temperature is greater than temperature at top of stack
    while (stack.length > 0 && temperatures[i] > temperatures[stack[stack.length - 1]]) {
      const index = stack.pop(); // pop index from stack
      result[index] = i - index; // calculate and store result
    }
    stack.push(i); // push current index to stack
  }
  return result; // return result array
}

function deleteAndEarn(nums) {
  // Create a hash map to store the frequency of each number
  let frequencyMap = {};
  for (let num of nums) {
    // If the number is already in the map, increment its frequency
    if (num in frequencyMap) {
      frequencyMap[num] += 1;
    } else {
      // Otherwise, add it to the map with a frequency of 1
      frequencyMap[num] = 1;
    }
  }

  // Initialize the maximum number and the dynamic programming array
  let maxNum = Math.max(...Object.keys(frequencyMap));
  let dp = new Array(maxNum + 1).fill(0);

  // Initialize the base cases for the dynamic programming
  dp[1] = frequencyMap[1] ? frequencyMap[1] : 0;

  // Fill up the dynamic programming array
  for (let i = 2; i <= maxNum; i++) {
    // For each number, the maximum points we can earn is the maximum of the points we can earn by including the current number
    // and the points we can earn by excluding the current number
    dp[i] = Math.max(dp[i - 1], dp[i - 2] + frequencyMap[i] * i);
  }

  // The maximum points we can earn is stored in the last element of the dynamic programming array
  return dp[maxNum];
}

function cherryPickup(grid) {
  const n = grid.length;
  const memo = new Map();
  function dp(r1, c1, r2) {
    const c2 = r1 + c1 - r2;
    if (r1 >= n || c1 >= n || r2 >= n || c2 >= n || c2 < 0 || grid[r1][c1] === -1 || grid[r2][c2] === -1) return -Infinity;
    if (r1 === n - 1 && c1 === n - 1) return grid[r1][c1];
    const key = r1 + ',' + c1 + ',' + r2;
    if (memo.has(key)) return memo.get(key);
    let cherries = grid[r1][c1];
    if (r1 !== r2) cherries += grid[r2][c2];
    let best = Math.max(dp(r1 + 1, c1, r2 + 1), dp(r1 + 1, c1, r2), dp(r1, c1 + 1, r2 + 1), dp(r1, c1 + 1, r2));
    cherries += best;
    memo.set(key, cherries);
    return cherries;
  }
  return Math.max(dp(0, 0, 0), 0);
}

function nextGreatestLetter(letters, target) {
  // Perform binary search to find the smallest character greater than the target
  let left = 0, right = letters.length;
  while (left < right) {
    // Calculate the middle index and compare the character at this index with the target
    let mid = Math.floor((left + right) / 2);
    if (letters[mid] <= target) {
      // If the character at the middle index is less than or equal to the target, move the left pointer to the right
      left = mid + 1;
    } else {
      // If the character at the middle index is greater than the target, move the right pointer to the left
      right = mid;
    }
  }
  // Return the character at the left index, which is the smallest character greater than the target
  return letters[left % letters.length];
}

function networkDelayTime(times, n, k) {
    // Create an adjacency list to represent the graph
    const graph = new Array(n + 1).fill(null).map(() => []);
    for (const [u, v, w] of times) {
        // Add each edge to the graph with its corresponding weight
        graph[u].push([v, w]);
    }

    // Initialize the distance array with infinity for all nodes except the source node
    const distance = new Array(n + 1).fill(Infinity);
    distance[k] = 0;

    // Create a priority queue to store nodes to be processed
    const pq = [[k, 0]];

    // Process each node in the priority queue
    while (pq.length) {
        // Extract the node with the minimum distance from the priority queue
        const [node, dist] = pq.shift();
        // If the extracted distance is greater than the current distance, skip this node
        if (dist > distance[node]) continue;
        // Iterate over all neighbors of the current node
        for (const [neighbor, weight] of graph[node]) {
            // Calculate the new distance to the neighbor
            const newDist = dist + weight;
            // If the new distance is less than the current distance, update the distance and push the neighbor to the priority queue
            if (newDist < distance[neighbor]) {
                distance[neighbor] = newDist;
                pq.push([neighbor, newDist]);
                // Sort the priority queue to maintain the minimum distance at the top
                pq.sort((a, b) => a[1] - b[1]);
            }
        }
    }

    // Find the maximum distance in the distance array
    const maxDist = Math.max(...distance.slice(1));
    // If the maximum distance is infinity, return -1; otherwise, return the maximum distance
    return maxDist === Infinity ? -1 : maxDist;
}

class WordFilter {
