    }
  }
  return maxIndex;
}

function minCostClimbingStairs(cost) {
  // Initialize variables to store the minimum cost to reach each step
  let minCostToReachPreviousStep = cost[0];
  let minCostToReachCurrentStep = cost[1];

  // Iterate through the cost array starting from the third step
  for (let i = 2; i < cost.length; i++) {
    // Calculate the minimum cost to reach the current step by taking the minimum of the cost to reach the previous step and the step before that, and add the cost of the current step
    let temp = minCostToReachCurrentStep;
    minCostToReachCurrentStep = Math.min(minCostToReachPreviousStep, minCostToReachCurrentStep) + cost[i];
    minCostToReachPreviousStep = temp;
  }

  // Return the minimum cost to reach the top of the floor by taking the minimum of the cost to reach the last step and the step before that
  return Math.min(minCostToReachPreviousStep, minCostToReachCurrentStep);
}

function openLock(deadends, target) {
    // Create a set of deadends for efficient lookups
    var dead = new Set(deadends);
    // If the initial state is a deadend, return -1
    if (dead.has('0000')) return -1;
    // Create a queue for BFS, with the initial state and 0 turns
    var queue = [['0000', 0]];
    // Create a set to keep track of visited states
    var visited = new Set(['0000']);
    while (queue.length > 0) {
        // Dequeue the next state and number of turns
        var [state, turns] = queue.shift();
        // If the current state is the target, return the number of turns
        if (state === target) return turns;
        // Generate all possible next states
        for (var i = 0; i < 4; i++) {
            // Generate the next state by incrementing the current digit
            var nextState = state.substring(0, i) + ((parseInt(state[i]) + 1) % 10) + state.substring(i + 1);
            // If the next state is not a deadend and has not been visited, add it to the queue
            if (!dead.has(nextState) && !visited.has(nextState)) {
                queue.push([nextState, turns + 1]);
                visited.add(nextState);
            }
            // Generate the next state by decrementing the current digit
            var nextState = state.substring(0, i) + ((parseInt(state[i]) - 1 + 10) % 10) + state.substring(i + 1);
            // If the next state is not a deadend and has not been visited, add it to the queue
            if (!dead.has(nextState) && !visited.has(nextState)) {
                queue.push([nextState, turns + 1]);
                visited.add(nextState);
            }
        }
    }
    // If the target state is not reachable, return -1
    return -1;
}

function crackSafe(n, k) {
    const visited = new Set();
    const result = [];
    const start = '0'.repeat(n - 1);
    function dfs(node) {
        for (let x = 0; x < k; x++) {
            const next = node + x;
            if (!visited.has(next)) {
                visited.add(next);
                dfs(next.slice(1));
                result.push(x.toString());
            }
        }
    }
    dfs(start);
    return result.join('') + start;
}

function containVirus(isInfected) {
    const m = isInfected.length;
    const n = isInfected[0].length;
    let walls = 0;
    while (true) {
        const regions = [];
        const boundaryEdgeCounts = [];
        const fronts = [];
        const visited = Array.from({ length: m }, () => Array(n).fill(false));
        for (let i = 0; i < m; i++) {
            for (let j = 0; j < n; j++) {
                if (isInfected[i][j] === 1 && !visited[i][j]) {
                    const region = [];
                    let boundaryEdges = 0;
                    const front = new Set();
                    const queue = [[i, j]];
                    visited[i][j] = true;
                    while (queue.length > 0) {
                        const [x, y] = queue.shift();
                        region.push([x, y]);
                        for (const [dx, dy] of [[-1, 0], [1, 0], [0, -1], [0, 1]]) {
                            const nx = x + dx;
                            const ny = y + dy;
                            if (nx >= 0 && nx < m && ny >= 0 && ny < n) {
                                if (isInfected[nx][ny] === 1 && !visited[nx][ny]) {
                                    queue.push([nx, ny]);
                                    visited[nx][ny] = true;
                                } else if (isInfected[nx][ny] === 0) {
                                    boundaryEdges++;
                                    front.add(`${nx},${ny}`);
                                }
                            }
                        }
                    }
                    regions.push(region);
                    boundaryEdgeCounts.push(boundaryEdges);
                    fronts.push(front);
                }
            }
        }
        if (regions.length === 0) break;
        let maxThreat = 0;
        let maxThreatIndex = 0;
        for (let i = 0; i < regions.length; i++) {
            if (fronts[i].size > maxThreat) {
                maxThreat = fronts[i].size;
                maxThreatIndex = i;
            }
        }
        walls += boundaryEdgeCounts[maxThreatIndex];
        for (let i = 0; i < regions.length; i++) {
            if (i !== maxThreatIndex) {
                for (const [x, y] of regions[i]) {
                    for (const [dx, dy] of [[-1, 0], [1, 0], [0, -1], [0, 1]]) {
                        const nx = x + dx;
                        const ny = y + dy;
                        if (nx >= 0 && nx < m && ny >= 0 && ny < n && isInfected[nx][ny] === 0) {
                            isInfected[nx][ny] = 1;
                        }
                    }
                }
            }
        }
        for (const [x, y] of regions[maxThreatIndex]) {
            isInfected[x][y] = -1;
        }
    }
    return walls;
}

function validPalindrome(s) {
    let left = 0, right = s.length - 1;
    while (left < right) { 
        // if characters at left and right pointers do not match, try deleting one of them
        if (s[left] !== s[right]) {
            return isPalindrome(s, left + 1, right) || isPalindrome(s, left, right - 1);
        }
        left++;
        right--;
    }
    return true;
}

function isPalindrome(s, left, right) {
    while (left < right) { 
        // check if substring is palindrome
        if (s[left] !== s[right]) {
            return false;
        }
        left++;
        right--;
    }
