        if (!node) return 0;

        // Recursively calculate the sum of the left and right subtrees
        let leftSum = dfs(node.left);
        let rightSum = dfs(node.right);

        // Calculate the tilt of the current node and update the total tilt
        totalTilt += Math.abs(leftSum - rightSum);

        // Return the sum of the current node and its subtrees
        return node.val + leftSum + rightSum;
    }

    // Call the helper function to start the DFS traversal
    dfs(root);

    // Return the total tilt
    return totalTilt;
}

