function findKthNumber(m, n, k) {
  // The algorithm solution is already optimal, using binary search to find the kth smallest number
  let left = 1, right = m * n;
  while (left < right) {
    // Calculate the middle value and count the numbers less than or equal to mid
    let mid = Math.floor((left + right) / 2);
    let count = 0;
    let j = n;
    for (let i = 1; i <= m; i++) {
      // Count the numbers less than or equal to mid in the current row
      while (j >= 1 && i * j > mid) j--;
      count += j;
    }
    // Update the left or right pointer based on the count
    if (count < k) left = mid + 1;
    else right = mid;
  }
  return left;
}

