    if (nums.length === 1) return Math.abs(nums[0] - 24) < 1e-6;
    for (let i = 0; i < nums.length; i++) {
      for (let j = i + 1; j < nums.length; j++) {
        // Generate all possible combinations of two numbers and operators
        const a = nums[i], b = nums[j];
        const rest = nums.slice(0, i).concat(nums.slice(i + 1, j)).concat(nums.slice(j + 1));
        // Try all four operators and recursively call dfs
        if (dfs(rest.concat([a + b]))) return true;
        if (dfs(rest.concat([a - b]))) return true;
        if (dfs(rest.concat([b - a]))) return true;
        if (a * b !== 0 && dfs(rest.concat([a * b]))) return true;
        if (b !== 0 && dfs(rest.concat([a / b]))) return true;
        if (a !== 0 && dfs(rest.concat([b / a]))) return true;
      }
    }
    return false;
  }
  // Start the backtracking process with the given cards
  return dfs(cards);
}

function reachNumber(target) {
    // calculate the absolute value of target to handle negative targets
    target = Math.abs(target);
    let step = 0;
    let sum = 0;
    // keep increasing the step and sum until the sum is greater than or equal to the target
    while (sum < target) {
        step++;
        sum += step;
    }
    // if the sum is equal to the target, return the step
    if (sum === target) {
        return step;
    }
    // if the sum is greater than the target, check if the difference is even or odd
    while ((sum - target) % 2 !== 0) {
        step++;
        sum += step;
    }
    // return the step
    return step;
}

