            let lowerCaseChar = char.toLowerCase();
            // Increment the count of the character in the hash map
            wordMap[lowerCaseChar] = (wordMap[lowerCaseChar] || 0) + 1;
        }

        // Check if the word contains all the characters in the license plate
        let isCompletingWord = true;
        for (let char in licensePlateMap) {
            // If the word does not contain a character or contains it less times than the license plate, it is not a completing word
            if (!wordMap[char] || wordMap[char] < licensePlateMap[char]) {
                isCompletingWord = false;
                break;
            }
        }

        // If the word is a completing word and its length is less than the current shortest length, update the shortest word and length
        if (isCompletingWord && word.length < shortestLength) {
            shortestWord = word;
            shortestLength = word.length;
        }
    }

    // Return the shortest completing word
    return shortestWord;
}

