function orderOfLargestPlusSign(n, mines) {
    // Create a 2D grid with all values initially 1's
    let grid = Array(n).fill().map(() => Array(n).fill(1));

    // Mark the mines in the grid as 0's
    for (let [x, y] of mines) {
        grid[x][y] = 0;
    }

    // Initialize the maximum order of the plus sign
    let maxOrder = 0;

    // Iterate over each cell in the grid
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            // If the current cell is 1, try to find the largest plus sign with this cell as the center
            if (grid[i][j] === 1) {
                // Initialize the order of the plus sign
                let order = 1;

                // Try to extend the arms of the plus sign
                while (i - order >= 0 && i + order < n && j - order >= 0 && j + order < n) {
                    // Check if all cells in the arms are 1's
                    if (grid[i - order][j] === 1 && grid[i + order][j] === 1 && grid[i][j - order] === 1 && grid[i][j + order] === 1) {
