function reorganizeString(s) {
    // Create a hash map to store the frequency of each character
    let charFrequency = {};
    for (let char of s) {
        if (charFrequency[char]) {
            charFrequency[char]++;
        } else {
            charFrequency[char] = 1;
        }
    }

    // Create a max heap to store the characters and their frequencies
    let maxHeap = [];
    for (let char in charFrequency) {
        // Push the character and its frequency into the max heap
        maxHeap.push([char, charFrequency[char]]);
    }
    maxHeap.sort((a, b) => b[1] - a[1]);

    // Initialize the result string
    let result = '';

    // While the max heap is not empty
    while (maxHeap.length > 0) {
        // If the result string is not empty and the last character of the result string is the same as the character at the top of the max heap
        if (result.length > 0 && result[result.length - 1] === maxHeap[0][0]) {
            // If the max heap has only one character left, return an empty string
            if (maxHeap.length === 1) {
                return "";
            }
            // Otherwise, swap the top two characters in the max heap
            let temp = maxHeap[0];
            maxHeap[0] = maxHeap[1];
            maxHeap[1] = temp;
        }

        // Pop the character at the top of the max heap and append it to the result string
        let char = maxHeap[0][0];
        let frequency = maxHeap[0][1];
        result += char;
        maxHeap[0][1]--;
        // If the frequency of the character becomes zero, remove it from the max heap
        if (maxHeap[0][1] === 0) {
            maxHeap.shift();
        }
        // If the max heap is not empty, sort it again to maintain the max heap property
        if (maxHeap.length > 0) {
            maxHeap.sort((a, b) => b[1] - a[1]);
        }
    }

    // Return the result string
    return result;
}

function pyramidTransition(bottom, allowed) {
