    // Get the allowed patterns for the current pair of blocks
    var key = row.substring(index, index + 2);
    if (!map[key]) return;
    // Iterate over each allowed pattern
    for (var pattern of map[key]) {
        // Recursively generate the next rows
        generateNextRows(row, index + 1, current + pattern, set, map);
    }
}

