  }
  function mulPoly(a, b) {
    const result = new Map();
    for (const [, ta] of a) {
      for (const [, tb] of b) {
        let vars = [...ta.vars, ...tb.vars].filter(v => v !== '1').sort();
        if (vars.length === 0) vars = ['1'];
        const key = vars.join('*');
        const coeff = ta.coeff * tb.coeff;
        if (result.has(key)) result.get(key).coeff += coeff;
        else result.set(key, { coeff, vars });
