    let node = parseTerm();
    while (pos < tokens.length && (tokens[pos] === '+' || tokens[pos] === '-')) {
      const op = tokens[pos++];
      const rhs = parseTerm();
      node = op === '+' ? addPoly(node, rhs) : subPoly(node, rhs);
    }
    return node;
  }
  function parseTerm() {
    let node = parseFactor();
    while (pos < tokens.length && tokens[pos] === '*') {
      pos++;
      const rhs = parseFactor();
      node = mulPoly(node, rhs);
    }
    return node;
  }
  function parseFactor() {
    if (tokens[pos] === '(') {
      pos++;
