    const tok = tokens[pos++];
    if (/^\d+$/.test(tok)) return makeTerm(parseInt(tok), ['1']);
    if (varMap.has(tok)) return makeTerm(varMap.get(tok), ['1']);
    return makeTerm(1, [tok]);
