            const nx = x + dx;
            const ny = y + dy;
            if (nx >= 0 && nx < n && ny >= 0 && ny < n && !visited[nx][ny]) {
                pq.push([Math.max(elevation, grid[nx][ny]), nx, ny]);
                pq.sort((a, b) => a[0] - b[0]);
            }
        }
    }
}

function canTransform(start, result) {
  for (let i = 0, j = 0; i < start.length && j < result.length;) {
    while (i < start.length && start[i] === 'X') i++;
    while (j < result.length && result[j] === 'X') j++;
    if (i === start.length || j === result.length) return i === j;
    if (start[i] !== result[j]) return false;
    if (start[i] === 'L' && i < j) return false;
    if (start[i] === 'R' && i > j) return false;
    i++; j++;
  }
  return true;
}

function isIdealPermutation(nums) {
    // Check each pair (i, j) where i < j and nums[i] > nums[j] to count global inversions
    let globalInversions = 0;
    for (let i = 0; i < nums.length; i++) {
        for (let j = i + 1; j < nums.length; j++) {
            // If nums[i] > nums[j], it's a global inversion
            if (nums[i] > nums[j]) globalInversions++;
        }
    }
    // Count local inversions by checking each index i where i + 1 < nums.length and nums[i] > nums[i + 1]
    let localInversions = 0;
    for (let i = 0; i < nums.length - 1; i++) {
        // If nums[i] > nums[i + 1], it's a local inversion
        if (nums[i] > nums[i + 1]) localInversions++;
    }
    // Return true if the number of global inversions is equal to the number of local inversions
    return globalInversions === localInversions;
}

function slidingPuzzle(board) {
    // Define the target state of the board
    const target = [[1,2,3],[4,5,0]];
    // Convert the board to a one-dimensional array for easier comparison
    const start = board.flat();
    // Define the possible moves (up, down, left, right)
    const directions = [[1,3], [0,2,4], [1,5], [0,4], [1,3,5], [2,4]];
    // Create a queue for BFS and add the initial state
    const queue = [[start, 0]];
    // Create a set to store visited states
    const visited = new Set([start.join(',')]);
    while (queue.length) {
        // Dequeue the current state and the number of moves
        const [state, moves] = queue.shift();
        // If the current state is the target state, return the number of moves
        if (state.join(',') === target.flat().join(',')) return moves;
        // Find the index of the empty square (0)
        const zeroIndex = state.indexOf(0);
        // For each possible move
        for (const dir of directions[zeroIndex]) {
            // Create a copy of the current state
            const newState = state.slice();
            // Swap the empty square with the adjacent number
            [newState[zeroIndex], newState[dir]] = [newState[dir], newState[zeroIndex]];
            // If the new state has not been visited
            if (!visited.has(newState.join(','))) {
                // Mark the new state as visited and add it to the queue
                visited.add(newState.join(','));
                queue.push([newState, moves + 1]);
            }
        }
    }
    // If the target state is not reachable, return -1
    return -1;
}

function minDiffInBST(root) {
    let minDiff = Infinity, prevVal = null;
    function inOrderTraversal(node) { // perform in-order traversal to get sorted node values
        if (node) {
            inOrderTraversal(node.left);
            if (prevVal !== null) minDiff = Math.min(minDiff, node.val - prevVal); // calculate min diff between current and previous node values
            prevVal = node.val;
            inOrderTraversal(node.right);
        }
    }
    inOrderTraversal(root);
    return minDiff;
}

function numRabbits(answers) {
  var count = {};
  var total = 0;
  for (var i = 0; i < answers.length; i++) {
    if (count[answers[i]]) count[answers[i]]++;
    else count[answers[i]] = 1;
  }
  for (var key in count) {
    var k = Number(key);
    var groups = Math.ceil(count[key] / (k + 1));
    total += groups * (k + 1);
  }
  return total;
}

function movesToMakeBoard(board) {
    const n = board.length;
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if ((board[0][0] ^ board[i][0] ^ board[0][j] ^ board[i][j]) !== 0) return -1;
        }
    }

    let rowSum = 0, colSum = 0, rowSwap = 0, colSwap = 0;
    for (let i = 0; i < n; i++) {
        rowSum += board[0][i];
        colSum += board[i][0];
        if (board[i][0] === (i % 2)) rowSwap++;
        if (board[0][i] === (i % 2)) colSwap++;
    }
    if (rowSum < Math.floor(n / 2) || rowSum > Math.ceil(n / 2)) return -1;
    if (colSum < Math.floor(n / 2) || colSum > Math.ceil(n / 2)) return -1;

    if (n % 2 === 1) {
        if (rowSwap % 2 === 1) rowSwap = n - rowSwap;
        if (colSwap % 2 === 1) colSwap = n - colSwap;
    } else {
        rowSwap = Math.min(rowSwap, n - rowSwap);
        colSwap = Math.min(colSwap, n - colSwap);
    }
    return (rowSwap + colSwap) / 2;
}

function letterCasePermutation(s) {
    // generate all possible permutations using backtracking
    function backtrack(index, current) {
        if (index === s.length) {
            result.push(current.join(''));
            return;
        }
        // if character is a digit, only one possibility
        if (!isNaN(s[index])) {
            current.push(s[index]);
            backtrack(index + 1, current);
            current.pop();
        } else {
            // if character is a letter, two possibilities: lowercase and uppercase
            current.push(s[index].toLowerCase());
            backtrack(index + 1, current);
            current.pop();
            current.push(s[index].toUpperCase());
            backtrack(index + 1, current);
            current.pop();
        }
    }
    var result = [];
    backtrack(0, []);
    return result;
}

function isBipartite(graph) {
    // Initialize a color array to keep track of the color of each node
    const color = new Array(graph.length).fill(-1);

    // Iterate over each node in the graph
    for (let i = 0; i < graph.length; i++) {
        // If the node has not been colored yet
        if (color[i] === -1) {
            // Initialize a queue for BFS and add the current node to it
            const queue = [i];
            // Color the current node with 0
            color[i] = 0;

            // Perform BFS
            while (queue.length > 0) {
                // Dequeue a node
                const node = queue.shift();
                // For each neighbor of the node
                for (const neighbor of graph[node]) {
                    // If the neighbor has not been colored yet
                    if (color[neighbor] === -1) {
                        // Color the neighbor with the opposite color of the node
                        color[neighbor] = 1 - color[node];
                        // Add the neighbor to the queue
                        queue.push(neighbor);
                    } 
                    // If the neighbor has been colored and its color is the same as the node's color
                    else if (color[neighbor] === color[node]) {
                        // Return false because the graph is not bipartite
                        return false;
                    }
                }
            }
        }
    }

    // If we have checked all nodes and have not returned false, the graph is bipartite
    return true;
}

function rotateString(s, goal) {
