function customSortString(order, s) {
    // Create a hash map to store the frequency of each character in s
    var frequencyMap = {};
    for (var i = 0; i < s.length; i++) {
        // Count the frequency of each character in s
        frequencyMap[s[i]] = (frequencyMap[s[i]] || 0) + 1;
    }

    var result = '';
    // Iterate over the characters in the order string
    for (var i = 0; i < order.length; i++) {
        // If the character is present in s, append it to the result and decrement its frequency
        if (frequencyMap[order[i]]) {
            result += order[i].repeat(frequencyMap[order[i]]);
            frequencyMap[order[i]] = 0;
        }
    }

    // Append the remaining characters in s to the result
    for (var char in frequencyMap) {
        // If the character is not in the order string, append it to the result
        if (frequencyMap[char] > 0) {
            result += char.repeat(frequencyMap[char]);
        }
    }

    return result;
}

function kthSmallestPrimeFraction(arr, k) {
  let minHeap = [];
  for (let i = 1; i < arr.length; i++) {
    minHeap.push([arr[0], arr[i], 0, i]);
  }
  minHeap.sort((a, b) => a[0] / a[1] - b[0] / b[1]);
  for (let i = 0; i < k - 1; i++) {
    let [num, den, row, col] = minHeap.shift();
    if (row + 1 < col) {
      minHeap.push([arr[row + 1], den, row + 1, col]);
      minHeap.sort((a, b) => a[0] / a[1] - b[0] / b[1]);
    }
  }
  return [minHeap[0][0], minHeap[0][1]];
}

function escapeGhosts(ghosts, target) {
  // calculate the Manhattan distance from the player to the target
  const playerDistance = Math.abs(target[0]) + Math.abs(target[1]);
  // iterate over each ghost and calculate the Manhattan distance from the ghost to the target
  for (let i = 0; i < ghosts.length; i++) {
    // calculate the Manhattan distance from the ghost to the target
    const ghostDistance = Math.abs(ghosts[i][0] - target[0]) + Math.abs(ghosts[i][1] - target[1]);
    // if the ghost's distance is less than or equal to the player's distance, return false
    if (ghostDistance <= playerDistance) return false;
  }
  // if no ghost can catch the player, return true
  return true;
}

function numSubarrayBoundedMax(nums, left, right) {
    function countAtMost(bound) {
        let count = 0, cur = 0;
        for (const num of nums) {
            cur = num <= bound ? cur + 1 : 0;
            count += cur;
        }
        return count;
    }
    return countAtMost(right) - countAtMost(left - 1);
}

function numMatchingSubseq(s, words) {
  let count = 0;
  // iterate over each word in the words array
  for (let word of words) {
    let i = 0, j = 0;
    // use two pointers to check if word is a subsequence of s
    while (i < s.length && j < word.length) {
      if (s[i] === word[j]) j++;
      i++;
    }
    // if j is equal to the length of word, it means word is a subsequence of s
    if (j === word.length) count++;
  }
  return count;
}

function numTilings(n) {
    const mod = 1000000007;
    if (n === 0) return 1;
    if (n === 1) return 1;
    if (n === 2) return 2;
    const dp = new Array(n + 1).fill(0);
    dp[0] = 1; dp[1] = 1; dp[2] = 2;
    for (let i = 3; i <= n; i++) {
        dp[i] = (2 * dp[i - 1] % mod + dp[i - 3]) % mod;
    }
    return dp[n];
}

function preimageSizeFZF(k) {
  // calculate the number of trailing zeroes in x! using binary search
  function findTrailingZeroes(x) {
    let count = 0;
    let i = 5;
    while (Math.floor(x / i) >= 1) {
      count += Math.floor(x / i);
      i *= 5;
    }
    return count;
  }

  // perform binary search to find the range of x values that give k trailing zeroes
  let left = 0;
  let right = 5 * k;
  while (left < right) {
    let mid = Math.floor((left + right) / 2);
    // if mid! has less than k trailing zeroes, move the left pointer to mid + 1
    if (findTrailingZeroes(mid) < k) {
      left = mid + 1;
    } 
    // if mid! has more than k trailing zeroes, move the right pointer to mid
    else if (findTrailingZeroes(mid) > k) {
      right = mid;
    } 
    // if mid! has exactly k trailing zeroes, move the right pointer to mid
    else {
      right = mid;
    }
  }

  // check if left! has exactly k trailing zeroes
  if (findTrailingZeroes(left) === k) {
    // if left! has exactly k trailing zeroes, check if left + 4 also has exactly k trailing zeroes
    if (findTrailingZeroes(left + 4) === k) {
      return 5;
    } else {
      return 1;
    }
  } else {
    return 0;
  }
}

