function validTicTacToe(board) {
    let xCount = 0, oCount = 0;
    // Count the number of 'X' and 'O' on the board
    for (let i = 0; i < 3; i++) {
        for (let j = 0; j < 3; j++) {
            if (board[i][j] === 'X') xCount++;
            else if (board[i][j] === 'O') oCount++;
        }
    }
    // Check if the number of 'X' and 'O' is valid
    if (xCount < oCount || xCount > oCount + 1) return false;
    // Check if there is a winner
    let xWin = checkWin(board, 'X');
    let oWin = checkWin(board, 'O');
    // If 'X' wins, 'O' cannot win, and the number of 'X' must be one more than 'O'
    if (xWin && oWin) return false;
    if (xWin && xCount !== oCount + 1) return false;
    // If 'O' wins, the number of 'X' must be equal to 'O'
    if (oWin && xCount !== oCount) return false;
    return true;
}

function checkWin(board, player) {
    // Check rows and columns for a win
    for (let i = 0; i < 3; i++) {
        if (board[i][0] === player && board[i][1] === player && board[i][2] === player) return true;
        if (board[0][i] === player && board[1][i] === player && board[2][i] === player) return true;
    }
    // Check diagonals for a win
    if (board[0][0] === player && board[1][1] === player && board[2][2] === player) return true;
    if (board[0][2] === player && board[1][1] === player && board[2][0] === player) return true;
    return false;
}

function rotatedDigits(n) {
    let count = 0;
    // iterate over each number in the range [1, n]
    for (let i = 1; i <= n; i++) {
        let isGood = false;
        let isValid = true;
        let rotated = 0;
        let temp = i;
        let base = 1;
        // rotate each digit and check if it's valid and different from the original number
        while (temp > 0) {
            let digit = temp % 10;
            // check if the digit is valid after rotation
            if (digit === 3 || digit === 4 || digit === 7) {
                isValid = false;
                break;
            }
            // rotate the digit
            let rotatedDigit = (digit === 0) ? 0 : (digit === 1) ? 1 : (digit === 6) ? 9 : (digit === 8) ? 8 : (digit === 9) ? 6 : 9;
            // check if the rotated digit is different from the original digit
            if (rotatedDigit !== digit) {
                isGood = true;
            }
            // update the rotated number
            rotated += rotatedDigit * base;
            base *= 10;
            temp = Math.floor(temp / 10);
        }
        // if the number is valid and good, increment the count
        if (isValid && isGood) {
            count++;
        }
    }
    return count;
}

function findCheapestPrice(n, flights, src, dst, k) {
  let costs = new Array(n).fill(Infinity);
  costs[src] = 0;
  for (let i = 0; i <= k; i++) {
    const newCosts = costs.slice();
    for (const [from, to, price] of flights) {
      if (costs[from] !== Infinity && costs[from] + price < newCosts[to]) {
        newCosts[to] = costs[from] + price;
      }
    }
    costs = newCosts;
  }
  return costs[dst] === Infinity ? -1 : costs[dst];
}

function allPathsSourceTarget(graph) {
    // Initialize an empty array to store all possible paths
    let result = [];
    // Define a helper function for DFS
    function dfs(currentNode, path) {
        // Add the current node to the path
        path.push(currentNode);
        // If the current node is the target node, add the path to the result
        if (currentNode === graph.length - 1) result.push([...path]);
        // Otherwise, recursively explore all neighboring nodes
        else for (let neighbor of graph[currentNode]) dfs(neighbor, path);
        // Remove the current node from the path to backtrack
        path.pop();
    }
    // Start the DFS from the source node (0)
    dfs(0, []);
    // Return all possible paths
    return result;
}

function bestRotation(nums) {
    // Initialize variables to store the maximum score and the corresponding rotation index
    let maxScore = 0;
    let rotationIndex = 0;

    // Iterate over all possible rotations
    for (let k = 0; k < nums.length; k++) {
        // Initialize the score for the current rotation
        let score = 0;

        // Calculate the score for the current rotation
        for (let i = 0; i < nums.length; i++) {
            // Check if the current element is less than or equal to its index in the rotated array
            if (nums[(i + k) % nums.length] <= i) {
                // If it is, increment the score
                score++;
            }
        }

        // Update the maximum score and the corresponding rotation index if the current score is higher
        if (score > maxScore) {
            maxScore = score;
            rotationIndex = k;
        } else if (score === maxScore) {
            // If the current score is equal to the maximum score, update the rotation index if it is smaller
            rotationIndex = Math.min(rotationIndex, k);
        }
    }

    // Return the rotation index that corresponds to the highest score
    return rotationIndex;
}

function uniqueMorseRepresentations(words) {
    const morseCode = [".-","-...","-.-.","-..",".","..-.","--.","....","..",".---","-.-",".-..","--","-.","---",".--.","--.-",".-.","...","-","..-","...-",".--","-..-","-.--","--.."];
    const transformations = new Set();
    for (let word of words) {
        let transformation = '';
        for (let char of word) // loop through each character in the word
            transformation += morseCode[char.charCodeAt(0) - 97]; // convert character to morse code
        transformations.add(transformation); // add transformation to set
    }
    return transformations.size; // return number of unique transformations
}

function champagneTower(poured, query_row, query_glass) {
    // Initialize an array to store the amount of champagne in each glass
    let champagne = Array(query_row + 1).fill(0).map(() => Array(query_row + 1).fill(0));
    champagne[0][0] = poured; // Pour champagne into the top glass
    for (let row = 0; row < query_row; row++) { 
        // For each glass in the current row, calculate the excess champagne and pour it into the glasses below
        for (let glass = 0; glass <= row; glass++) { 
            if (champagne[row][glass] > 1) { 
                // Calculate the excess champagne
                let excess = (champagne[row][glass] - 1) / 2; 
                champagne[row + 1][glass] += excess; // Pour excess champagne into the glass to the left
                champagne[row + 1][glass + 1] += excess; // Pour excess champagne into the glass to the right
                champagne[row][glass] = 1; // The current glass is now full
            }
        }
    }
    // Return the amount of champagne in the query glass, or 0 if it's less than 1
    return Math.min(1, champagne[query_row][query_glass]);
}

function numberOfLines(widths, s) {
    let lines = 1; // initialize number of lines
    let width = 0; // initialize current line width
    for (let i = 0; i < s.length; i++) { // iterate over each character in the string
        // calculate the width of the current character
        let charWidth = widths[s.charCodeAt(i) - 97]; 
        // if adding the current character exceeds the line width, start a new line
        if (width + charWidth > 100) { 
            lines++; 
            width = 0; 
        }
        // add the current character to the current line
        width += charWidth; 
    }
    // return the number of lines and the width of the last line
    return [lines, width];
}

function maxIncreaseKeepingSkyline(grid) {
    var n = grid.length;
    var rowMax = new Array(n).fill(0);
    var colMax = new Array(n).fill(0);
    // find the maximum height in each row and column
    for (var i = 0; i < n; i++) {
        for (var j = 0; j < n; j++) {
            rowMax[i] = Math.max(rowMax[i], grid[i][j]);
            colMax[j] = Math.max(colMax[j], grid[i][j]);
        }
    }
    var sum = 0;
    // calculate the maximum increase for each building without changing the skyline
    for (var i = 0; i < n; i++) {
        for (var j = 0; j < n; j++) {
            // the maximum increase is the minimum of the row and column max minus the current height
            sum += Math.min(rowMax[i], colMax[j]) - grid[i][j];
        }
    }
    return sum;
}

function xorGame(nums) {
  // calculate the initial XOR of all elements in the array
  let xor = 0;
  for (let i = 0; i < nums.length; i++) {
    // update the XOR by performing a bitwise XOR operation with the current element
    xor ^= nums[i];
  }
  // if the initial XOR is 0, Alice wins
  if (xor === 0) return true;
  // if the length of the array is even, Alice wins
  // this is because no matter what Alice does, Bob will always be left with an odd number of elements
  // and since the XOR of an odd number of elements is always non-zero, Bob will never be able to make the XOR zero
  if (nums.length % 2 === 0) return true;
  // if the length of the array is odd, Alice loses
  // this is because Alice will always be left with an even number of elements
  // and since the XOR of an even number of elements is always zero, Alice will always be able to make the XOR zero
  // but since Alice starts first, she will be the one to make the XOR zero, which means she loses
  return false;
}

function splitArraySameAverage(nums) {
    // Calculate the total sum of the array
    let totalSum = 0;
    for (let i = 0; i < nums.length; i++) {
        totalSum += nums[i];
    }

    // Iterate over all possible subset sizes
    for (let size = 1; size < nums.length; size++) {
        // Check if the total sum can be divided into two parts with the same average
        if (totalSum * size % nums.length === 0) {
            // Calculate the target sum for the subset
            let targetSum = totalSum * size / nums.length;

            // Use bitmask to generate all possible subsets of the given size
            let bitmask = (1 << nums.length) - 1;
            for (let i = 0; i <= bitmask; i++) {
                // Check if the current bitmask represents a subset of the given size
                if (countBits(i) === size) {
                    // Calculate the sum of the current subset
                    let subsetSum = 0;
                    for (let j = 0; j < nums.length; j++) {
                        if ((i & (1 << j)) !== 0) {
                            subsetSum += nums[j];
                        }
                    }

                    // Check if the subset sum equals the target sum
                    if (subsetSum === targetSum) {
                        return true;
                    }
                }
            }
        }
    }

    // If no subset with the same average is found, return false
    return false;
}

// Helper function to count the number of bits set in a number
function countBits(n) {
    let count = 0;
    while (n !== 0) {
        count += n & 1;
        n >>= 1;
    }
    return count;
}

function minSwap(nums1, nums2) {
  const n = nums1.length;
  let swap = 1, notSwap = 0;
  for (let i = 1; i < n; i++) {
    let newSwap = Infinity, newNotSwap = Infinity;
    if (nums1[i] > nums1[i-1] && nums2[i] > nums2[i-1]) {
      newNotSwap = Math.min(newNotSwap, notSwap);
      newSwap = Math.min(newSwap, swap + 1);
    }
    if (nums1[i] > nums2[i-1] && nums2[i] > nums1[i-1]) {
      newSwap = Math.min(newSwap, notSwap + 1);
      newNotSwap = Math.min(newNotSwap, swap);
    }
    swap = newSwap;
    notSwap = newNotSwap;
  }
  return Math.min(swap, notSwap);
}

function eventualSafeNodes(graph) {
    // Create an array to store the color of each node, where 0 means not visited, 1 means visiting, and 2 means safe
    let color = new Array(graph.length).fill(0);
    let result = [];

    // Define a helper function to perform DFS
    function dfs(node) {
        // If the node is already marked as safe, return true
        if (color[node] === 2) return true;
        // If the node is being visited and not safe yet, return false
        if (color[node] === 1) return false;

        // Mark the node as being visited
        color[node] = 1;

        // Perform DFS on all adjacent nodes
        for (let neighbor of graph[node]) {
            // If any adjacent node is not safe, return false
            if (!dfs(neighbor)) return false;
        }

        // If all adjacent nodes are safe, mark the current node as safe
        color[node] = 2;
        return true;
    }

    // Perform DFS on all nodes
    for (let i = 0; i < graph.length; i++) {
        // If a node is safe, add it to the result array
        if (dfs(i)) result.push(i);
    }

    // Return the result array
    return result;
}

function hitBricks(grid, hits) {
  const R = grid.length, C = grid[0].length;
  const gridCopy = grid.map(row => row.slice());
  for (const [r, c] of hits) gridCopy[r][c] = 0;

  const size = R * C + 1;
  const parent = Array.from({length: size}, (_, i) => i);
  const rank = new Array(size).fill(0);
  const sz = new Array(size).fill(1);
  function find(x) { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; }
  function union(a, b) {
    const ra = find(a), rb = find(b);
    if (ra === rb) return;
    if (rank[ra] < rank[rb]) { parent[ra] = rb; sz[rb] += sz[ra]; }
    else if (rank[ra] > rank[rb]) { parent[rb] = ra; sz[ra] += sz[rb]; }
    else { parent[rb] = ra; sz[ra] += sz[rb]; rank[ra]++; }
  }
  const roof = R * C;
  const idx = (r, c) => r * C + c;
  for (let c = 0; c < C; c++) if (gridCopy[0][c] === 1) union(idx(0, c), roof);
  for (let r = 0; r < R; r++) {
    for (let c = 0; c < C; c++) {
      if (gridCopy[r][c] === 1) {
        if (r > 0 && gridCopy[r - 1][c] === 1) union(idx(r, c), idx(r - 1, c));
        if (c > 0 && gridCopy[r][c - 1] === 1) union(idx(r, c), idx(r, c - 1));
      }
    }
  }
  const result = new Array(hits.length).fill(0);
  for (let i = hits.length - 1; i >= 0; i--) {
    const [r, c] = hits[i];
    if (grid[r][c] === 0) continue;
    const before = sz[find(roof)];
    gridCopy[r][c] = 1;
    if (r === 0) union(idx(r, c), roof);
    if (r > 0 && gridCopy[r - 1][c] === 1) union(idx(r, c), idx(r - 1, c));
    if (r < R - 1 && gridCopy[r + 1][c] === 1) union(idx(r, c), idx(r + 1, c));
    if (c > 0 && gridCopy[r][c - 1] === 1) union(idx(r, c), idx(r, c - 1));
    if (c < C - 1 && gridCopy[r][c + 1] === 1) union(idx(r, c), idx(r, c + 1));
    const after = sz[find(roof)];
    result[i] = Math.max(0, after - before - 1);
  }
  return result;
}

function soupServings(n) {
    n = Math.ceil(n / 25); // scale down the problem size
    if (n >= 179) return 1; // if n is large enough, the probability is almost 1
    var memo = Array.from({length: n + 1}, () => new Array(n + 1).fill(0));
    function dfs(a, b) { // depth-first search with memoization
        if (a <= 0 && b <= 0) return 0.5; // both soups are used up
        if (a <= 0) return 1; // soup A is used up
        if (b <= 0) return 0; // soup B is used up
        if (memo[a][b] !== 0) return memo[a][b]; // return memoized result
        // calculate the probability based on the four serving operations
        memo[a][b] = 0.25 * (dfs(a - 4, b) + dfs(a - 3, b - 1) + dfs(a - 2, b - 2) + dfs(a - 1, b - 3));
        return memo[a][b];
    }
    return dfs(n, n); // start the depth-first search
}

function subdomainVisits(cpdomains) {
