                while (i + 1 < s.length && s[i] === s[i + 1]) { i++; countS++; }
                while (j + 1 < word.length && word[j] === word[j + 1]) { j++; countWord++; }
                if (countS < countWord || (countS !== 0 && countS < 2 && countS !== countWord)) return false;
                i++; j++;
