function largestTriangleArea(points) {
    let maxArea = 0;
    // calculate area for all possible triangles and keep track of the maximum area
    for (let i = 0; i < points.length; i++) {
        for (let j = i + 1; j < points.length; j++) {
            for (let k = j + 1; k < points.length; k++) {
                // calculate area using the shoelace formula
                let area = Math.abs((points[i][0] * (points[j][1] - points[k][1]) + points[j][0] * (points[k][1] - points[i][1]) + points[k][0] * (points[i][1] - points[j][1])) / 2);
                maxArea = Math.max(maxArea, area);
            }
        }
    }
    return maxArea;
}

function pruneTree(root) {
    // if the tree is empty, return null
    if (!root) return null;

    // recursively prune the left and right subtrees
    root.left = pruneTree(root.left);
    root.right = pruneTree(root.right);

    // if the current node is 0 and has no children, return null to prune it
    if (root.val === 0 && !root.left && !root.right) return null;

    // otherwise, return the current node
    return root;
}

function numComponents(head, nums) {
  // Create a set of nums for O(1) lookups
  const numSet = new Set(nums);
  let count = 0;
  // Traverse the linked list
  while (head) {
    // If the current node's value is in the set, it could be the start of a new component
    if (numSet.has(head.val)) {
      // Assume it's the start of a new component
      count++;
      // Move to the next node
      let nextNode = head.next;
      // While the next node's value is also in the set, move to the next node
      while (nextNode && numSet.has(nextNode.val)) {
        nextNode = nextNode.next;
      }
      // Update the head to the node after the current component
      head = nextNode;
    } else {
      // If the current node's value is not in the set, move to the next node
      head = head.next;
    }
  }
  return count;
}

function mostCommonWord(paragraph, banned) {
  // Convert paragraph to lowercase and replace non-alphanumeric characters with spaces
  let words = paragraph.toLowerCase().replace(/[^\w\s]/g, ' ').split(/\s+/);
  // Create a hash table to store the frequency of each word
  let wordCount = {};
  for (let word of words) {
    // If the word is not empty, increment its count in the hash table
    if (word) wordCount[word] = (wordCount[word] || 0) + 1;
  }
  // Create a set of banned words for efficient lookup
  let bannedSet = new Set(banned.map(word => word.toLowerCase()));
  // Initialize the most common word and its count
  let maxCount = 0, mostCommon = '';
  // Iterate over the hash table to find the most common non-banned word
  for (let word in wordCount) {
    // If the word is not banned and its count is greater than the current max count
    if (!bannedSet.has(word) && wordCount[word] > maxCount) {
      // Update the most common word and its count
      maxCount = wordCount[word];
      mostCommon = word;
    }
  }
  return mostCommon;
}

function numBusesToDestination(routes, source, target) {
    if (source === target) return 0;
    // Create a hash map to store bus stops for each route
    let routeMap = {};
    for (let i = 0; i < routes.length; i++) {
        for (let stop of routes[i]) {
            if (!routeMap[stop]) routeMap[stop] = [];
            routeMap[stop].push(i);
        }
    }
    // Initialize queue with source stop and visited set
    let queue = [[source, 0]];
    let visitedStops = new Set([source]);
    let visitedRoutes = new Set();
    while (queue.length) {
        let [stop, buses] = queue.shift();
        // Explore all possible routes from the current stop
        for (let route of routeMap[stop] || []) {
            if (!visitedRoutes.has(route)) {
                visitedRoutes.add(route);
                // Explore all stops in the current route
                for (let nextStop of routes[route]) {
                    if (nextStop === target) return buses + 1;
                    if (!visitedStops.has(nextStop)) {
                        visitedStops.add(nextStop);
                        queue.push([nextStop, buses + 1]);
                    }
                }
            }
        }
    }
    // If no path is found, return -1
    return -1;
}

