function largestSumOfAverages(nums, k) {
    // Calculate prefix sum to efficiently calculate subarray sums
    let prefixSum = new Array(nums.length + 1).fill(0);
    for (let i = 0; i < nums.length; i++) {
        prefixSum[i + 1] = prefixSum[i] + nums[i];
    }

    // Initialize dp table with -Infinity
    let dp = new Array(nums.length).fill(0).map(() => new Array(k + 1).fill(-Infinity));

    // Base case: one partition
    for (let i = 0; i < nums.length; i++) {
        // Calculate average of subarray from 0 to i
        dp[i][1] = (prefixSum[i + 1] / (i + 1));
    }

    // Fill dp table for each number of partitions
    for (let j = 2; j <= k; j++) {
        for (let i = j - 1; i < nums.length; i++) {
            // Try all possible previous partition ends
            for (let x = j - 2; x < i; x++) {
                // Calculate average of subarray from x + 1 to i
                let avg = (prefixSum[i + 1] - prefixSum[x + 1]) / (i - x);
                // Update dp table with maximum score
                dp[i][j] = Math.max(dp[i][j], dp[x][j - 1] + avg);
            }
        }
    }

    // Return maximum score for k partitions
    return dp[nums.length - 1][k];
}

function racecar(target) {
    let queue = [[0, 1, 0]]; // position, speed, steps
    let visited = new Set();
    while (queue.length > 0) {
        let [position, speed, steps] = queue.shift();
        // if we reached the target, return the steps
        if (position === target) return steps;
        // if we already visited this state, skip it
        if (visited.has(`${position},${speed}`)) continue;
        visited.add(`${position},${speed}`);
        // accelerate
        queue.push([position + speed, speed * 2, steps + 1]);
        // reverse
        if ((speed > 0 && position + speed > target) || (speed < 0 && position + speed < target)) {
            queue.push([position, -1, steps + 1]);
        }
    }
}

function flipgame(fronts, backs) {
    // Create a set to store the same numbers on both sides of a card
    let same = new Set();
    for (let i = 0; i < fronts.length; i++) {
        // If the front and back of a card are the same, add it to the set
        if (fronts[i] === backs[i]) same.add(fronts[i]);
    }
    let res = Infinity;
    // Iterate over all the numbers on the cards
    for (let i = 0; i < fronts.length; i++) {
        // If the current number is not in the set of same numbers and it's smaller than the current result
        if (!same.has(fronts[i]) && fronts[i] < res) {
            // Update the result
            res = fronts[i];
        }
        // If the current number is not in the set of same numbers and it's smaller than the current result
        if (!same.has(backs[i]) && backs[i] < res) {
            // Update the result
            res = backs[i];
        }
    }
    // If the result is still Infinity, return 0
    return res === Infinity ? 0 : res;
}

function minimumLengthEncoding(words) {
    // Create a Trie and add all words to it in reverse order
    let trie = {};
    for (let word of words) {
        let node = trie;
        for (let i = word.length - 1; i >= 0; i--) {
            // If the character is not in the Trie, add it
            if (!node[word[i]]) node[word[i]] = {};
            node = node[word[i]];
        }
    }

    // Perform DFS to find the length of the shortest reference string
    function dfs(node, depth) {
        // If the node has no children, it's a leaf node and we add its depth to the result
        if (Object.keys(node).length === 0) return depth + 1;
        let sum = 0;
        for (let child in node) {
            // Recursively traverse all children and add their depths to the result
            sum += dfs(node[child], depth + 1);
        }
        return sum;
    }

    // The length of the shortest reference string is the sum of all depths in the Trie
    return dfs(trie, 0);
}

