function numFactoredBinaryTrees(arr) {
    const MOD = 1e9 + 7;
    arr.sort((a, b) => a - b); // sort the array to make it easier to find factors
    const dp = new Map(); // use a map to store the number of trees for each number
    let result = 0;
    for (let i = 0; i < arr.length; i++) {
        // calculate the number of trees for the current number
        dp.set(arr[i], 1); // a single number is a tree
        for (let j = 0; j < i; j++) {
            // check if the current number can be factored into two smaller numbers
            if (arr[i] % arr[j] === 0) {
                const otherFactor = arr[i] / arr[j];
                if (dp.has(otherFactor)) {
                    // if the other factor is also in the array, update the number of trees
                    dp.set(arr[i], (dp.get(arr[i]) + dp.get(arr[j]) * dp.get(otherFactor)) % MOD);
                }
            }
        }
        // update the result
        result = (result + dp.get(arr[i])) % MOD;
    }
    return result;
}

