function shortestToChar(s, c) {
    // Initialize an array to store the distances
    var res = new Array(s.length).fill(Infinity);
    // Initialize a variable to store the previous occurrence of character c
    var prev = -Infinity;
    // Traverse the string from left to right
    for (var i = 0; i < s.length; i++) {
        // If the current character is c, update the previous occurrence and the distance
        if (s[i] === c) {
            prev = i;
            res[i] = 0;
        } else if (prev !== -Infinity) {
            // If the current character is not c, update the distance
            res[i] = Math.min(res[i], i - prev);
        }
    }
    // Initialize a variable to store the next occurrence of character c
    var next = Infinity;
    // Traverse the string from right to left
    for (var i = s.length - 1; i >= 0; i--) {
        // If the current character is c, update the next occurrence
        if (s[i] === c) {
            next = i;
        } else if (next !== Infinity) {
            // If the current character is not c, update the distance
            res[i] = Math.min(res[i], next - i);
        }
    }
    return res;
}

function maxProfitAssignment(difficulty, profit, worker) {
    // Create a 2D array to store the difficulty and profit of each job
    let jobs = difficulty.map((diff, i) => [diff, profit[i]]);
    // Sort the jobs based on their difficulty
    jobs.sort((a, b) => a[0] - b[0]);
    // Initialize the maximum profit that can be achieved for each job
    let maxProfit = new Array(jobs.length).fill(0);
    // Initialize the maximum profit that can be achieved for the first job
    maxProfit[0] = jobs[0][1];
    // Calculate the maximum profit that can be achieved for each job
    for (let i = 1; i < jobs.length; i++) {
        // Update the maximum profit for the current job
        maxProfit[i] = Math.max(maxProfit[i-1], jobs[i][1]);
    }
    // Initialize the total profit
    let totalProfit = 0;
    // Iterate over each worker
    for (let w of worker) {
        // Find the job with the highest difficulty that the worker can complete
        let left = 0, right = jobs.length - 1;
        while (left < right) {
            // Calculate the middle index
            let mid = Math.floor((left + right + 1) / 2);
            // If the worker can complete the job at the middle index, update the left pointer
            if (jobs[mid][0] <= w) {
                left = mid;
            } 
            // Otherwise, update the right pointer
            else {
                right = mid - 1;
            }
        }
        // If the worker can complete the job at the left index, add the maximum profit to the total profit
        if (jobs[left][0] <= w) {
            totalProfit += maxProfit[left];
        }
    }
    // Return the total profit
    return totalProfit;
}

