}

function flipAndInvertImage(image) {
  // iterate over each row in the image and reverse it
  for (let i = 0; i < image.length; i++) {
    // use two pointers to reverse the row in-place
    let left = 0, right = image[i].length - 1;
    while (left < right) {
      // swap the elements at the left and right pointers
      let temp = image[i][left];
      image[i][left] = image[i][right];
      image[i][right] = temp;
      left++;
      right--;
    }
    // invert the row by flipping each bit
    for (let j = 0; j < image[i].length; j++) {
      // use bitwise XOR to flip the bit
      image[i][j] = image[i][j] ^ 1;
    }
  }
  return image;
}

function largestIsland(grid) {
    const n = grid.length;
    const directions = [[0, 1], [0, -1], [1, 0], [-1, 0]];
    let islandIndex = 2;
    const islandSizes = {};

    // Perform DFS to mark and calculate the size of each island
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] === 1) {
                islandSizes[islandIndex] = dfs(grid, i, j, islandIndex, directions);
                islandIndex++;
            }
        }
    }

    let maxSize = 0;
    // Check each 0 cell to see if changing it to 1 can form a larger island
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] === 0) {
                const seen = new Set();
                let size = 1;
                // Check all four directions to see if there are any islands
                for (const [dx, dy] of directions) {
                    const x = i + dx;
                    const y = j + dy;
                    if (x >= 0 && x < n && y >= 0 && y < n && grid[x][y] > 1 && !seen.has(grid[x][y])) {
                        size += islandSizes[grid[x][y]];
                        seen.add(grid[x][y]);
                    }
                }
                maxSize = Math.max(maxSize, size);
            }
        }
    }

    // If no 0s are found, return the size of the largest island
    if (maxSize === 0) {
        return Math.max(...Object.values(islandSizes));
    }

    return maxSize;
}

// Helper function to perform DFS
function dfs(grid, x, y, index, directions) {
    const n = grid.length;
    if (x < 0 || x >= n || y < 0 || y >= n || grid[x][y] !== 1) {
        return 0;
    }
    grid[x][y] = index;
    let size = 1;
    // Perform DFS in all four directions
    for (const [dx, dy] of directions) {
        size += dfs(grid, x + dx, y + dy, index, directions);
    }
    return size;
}

