function findReplaceString(s, indices, sources, targets) {
    // Create a sorted array of indices to ensure we process replacements from right to left
    const sortedIndices = indices.map((index, i) => [index, sources[i], targets[i]]).sort((a, b) => b[0] - a[0]);
    let result = s;
    // Iterate over the sorted indices and perform replacements
    for (const [index, source, target] of sortedIndices) {
        // Check if the source string matches the substring at the current index
        if (result.substring(index, index + source.length) === source) {
