        } else if (digits.length === 11) {
            countryCode = '+*-';
            digits = digits.substring(1);
        }
        var maskedDigits = countryCode + '***-***-' + digits.substring(digits.length - 4);
        // Return the masked phone number
        return maskedDigits;
    }
}

function isRectangleOverlap(rec1, rec2) {
    // check if the x-coordinate of the top-right corner of rec1 is greater than the x-coordinate of the bottom-left corner of rec2
    // and the x-coordinate of the bottom-left corner of rec1 is less than the x-coordinate of the top-right corner of rec2
    // and the y-coordinate of the top-right corner of rec1 is greater than the y-coordinate of the bottom-left corner of rec2
    // and the y-coordinate of the bottom-left corner of rec1 is less than the y-coordinate of the top-right corner of rec2
    return rec1[2] > rec2[0] && rec1[0] < rec2[2] && rec1[3] > rec2[1] && rec1[1] < rec2[3];
