function pushDominoes(dominoes) {
    // Initialize the result array with the same length as dominoes
    let result = new Array(dominoes.length).fill('.');

    // Initialize the force array to keep track of the forces on each domino
    let force = new Array(dominoes.length).fill(0);

    // Calculate the forces from the left
    let f = 0;
    for (let i = 0; i < dominoes.length; i++) {
        // If the current domino is 'R', reset the force
        if (dominoes[i] === 'R') f = dominoes.length;
        // If the current domino is 'L', reset the force to 0
        else if (dominoes[i] === 'L') f = 0;
        // If the current domino is '.', decrease the force by 1
        else f = Math.max(f - 1, 0);
        // Update the force array
        force[i] += f;
    }

    // Calculate the forces from the right
    f = 0;
    for (let i = dominoes.length - 1; i >= 0; i--) {
        // If the current domino is 'L', reset the force
        if (dominoes[i] === 'L') f = dominoes.length;
        // If the current domino is 'R', reset the force to 0
        else if (dominoes[i] === 'R') f = 0;
        // If the current domino is '.', decrease the force by 1
        else f = Math.max(f - 1, 0);
        // Update the force array
        force[i] -= f;
    }

    // Update the result array based on the forces
    for (let i = 0; i < dominoes.length; i++) {
        // If the force is positive, the domino falls to the right
        if (force[i] > 0) result[i] = 'R';
        // If the force is negative, the domino falls to the left
        else if (force[i] < 0) result[i] = 'L';
    }

    // Return the result as a string
    return result.join('');
}

function new21Game(n, k, maxPts) {
  if (k === 0 || n >= k + maxPts - 1) return 1.0;
  const dp = new Array(n + 1).fill(0);
  dp[0] = 1;
  let wSum = 1, result = 0;
  for (let i = 1; i <= n; i++) {
    dp[i] = wSum / maxPts;
    if (i < k) wSum += dp[i]; else result += dp[i];
    if (i - maxPts >= 0) wSum -= dp[i - maxPts];
  }
  return result;
}

function sumOfDistancesInTree(n, edges) {
    let graph = Array.from({ length: n }, () => []);
    for (let [u, v] of edges) { graph[u].push(v); graph[v].push(u); }
    let count = Array(n).fill(1);
    let answer = Array(n).fill(0);
    function dfs(node, parent, depth) {
        answer[0] += depth;
        for (let child of graph[node]) {
            if (child !== parent) {
                dfs(child, node, depth + 1);
                count[node] += count[child];
            }
        }
    }
    function dfs2(node, parent) {
        for (let child of graph[node]) {
            if (child !== parent) {
                answer[child] = answer[node] + n - 2 * count[child];
                dfs2(child, node);
            }
        }
    }
    dfs(0, -1, 0);
    dfs2(0, -1);
    return answer;
}

function largestOverlap(img1, img2) {
    // Get the size of the images
    var n = img1.length;

    // Initialize the maximum overlap
    var maxOverlap = 0;

    // Iterate over all possible translations
    for (var dx = -n + 1; dx < n; dx++) {
        for (var dy = -n + 1; dy < n; dy++) {
            // Initialize the overlap for the current translation
            var overlap = 0;

            // Calculate the overlap for the current translation
            for (var x = 0; x < n; x++) {
                for (var y = 0; y < n; y++) {
                    // Check if the translated position is within the image boundaries
                    if (x + dx >= 0 && x + dx < n && y + dy >= 0 && y + dy < n) {
                        // Check if both images have a 1 at the translated position
                        if (img1[x][y] === 1 && img2[x + dx][y + dy] === 1) {
                            // Increment the overlap
                            overlap++;
                        }
                    }
                }
            }

            // Update the maximum overlap
            maxOverlap = Math.max(maxOverlap, overlap);
        }
    }

    // Return the maximum overlap
    return maxOverlap;
}

function numSimilarGroups(strs) {
    // Create a parent array to store the parent of each group
    let parent = new Array(strs.length).fill(0).map((_, i) => i);

    // Function to find the parent of a group
    function find(x) {
        // If the parent of x is not x, then find the parent of the parent of x
        if (parent[x] !== x) parent[x] = find(parent[x]);
        return parent[x];
    }

    // Function to union two groups
    function union(x, y) {
        // Find the parents of x and y
        let rootX = find(x);
        let rootY = find(y);

        // If the parents are different, then union the two groups
        if (rootX !== rootY) parent[rootX] = rootY;
    }

    // Function to check if two strings are similar
    function isSimilar(s1, s2) {
        // Initialize the count of different characters
        let count = 0;

        // Iterate over the characters of the strings
        for (let i = 0; i < s1.length; i++) {
            // If the characters are different, then increment the count
            if (s1[i] !== s2[i]) count++;

            // If the count is greater than 2, then return false
            if (count > 2) return false;
        }

        // If the count is 0 or 2, then return true
        return count === 0 || count === 2;
    }

    // Iterate over the strings
    for (let i = 0; i < strs.length; i++) {
        // Iterate over the strings that come after the current string
        for (let j = i + 1; j < strs.length; j++) {
            // If the strings are similar, then union the groups
            if (isSimilar(strs[i], strs[j])) union(i, j);
        }
    }

    // Initialize the count of groups
    let count = 0;

    // Iterate over the parent array
    for (let i = 0; i < parent.length; i++) {
        // If the parent of the current group is the current group, then increment the count
        if (parent[i] === i) count++;
    }

    // Return the count of groups
    return count;
}

function numMagicSquaresInside(grid) {
