    let count = 0;
    // Get number of rows and columns in the grid
    let rows = grid.length;
    let cols = grid[0].length;
    // Iterate over each possible 3x3 subgrid
    for (let i = 0; i <= rows - 3; i++) {
        for (let j = 0; j <= cols - 3; j++) {
            // Check if the current subgrid is a magic square
            if (isMagicSquare(grid, i, j)) {
                // If it is, increment the count
                count++;
            }
        }
    }
    // Return the total count of magic squares
    return count;
}

function isMagicSquare(grid, row, col) {
    // Get the numbers in the current 3x3 subgrid
    let nums = [];
    for (let i = row; i < row + 3; i++) {
        for (let j = col; j < col + 3; j++) {
            nums.push(grid[i][j]);
        }
    }
    // Check if the numbers are distinct and between 1 and 9
    if (new Set(nums).size !== 9 || nums.some(num => num < 1 || num > 9)) {
        return false;
    }
    // Calculate the target sum
    let targetSum = nums[0] + nums[1] + nums[2];
    // Check rows
    for (let i = 0; i < 3; i++) {
        // Check if the sum of the current row is equal to the target sum
        if (grid[row + i][col] + grid[row + i][col + 1] + grid[row + i][col + 2] !== targetSum) {
            return false;
        }
    }
    // Check columns
    for (let i = 0; i < 3; i++) {
        // Check if the sum of the current column is equal to the target sum
        if (grid[row][col + i] + grid[row + 1][col + i] + grid[row + 2][col + i] !== targetSum) {
            return false;
        }
    }
    // Check diagonals
    if (grid[row][col] + grid[row + 1][col + 1] + grid[row + 2][col + 2] !== targetSum) {
        return false;
    }
    if (grid[row][col + 2] + grid[row + 1][col + 1] + grid[row + 2][col] !== targetSum) {
        return false;
    }
    // If all checks pass, the subgrid is a magic square
    return true;
}

function canVisitAllRooms(rooms) {
    // Create a set to store visited rooms
    var visited = new Set();
    // Create a queue for BFS, starting with room 0
    var queue = [0];
    // Mark room 0 as visited
    visited.add(0);
    // Perform BFS
    while (queue.length > 0) {
        // Dequeue the next room
        var currentRoom = queue.shift();
        // For each key in the current room
        for (var key of rooms[currentRoom]) {
            // If the room corresponding to the key has not been visited
            if (!visited.has(key)) {
                // Mark the room as visited
                visited.add(key);
                // Enqueue the room
                queue.push(key);
            }
        }
    }
    // If all rooms have been visited, return true
    return visited.size === rooms.length;
}

function splitIntoFibonacci(num) {
    function isFibonacci(arr) {
        for (let i = 2; i < arr.length; i++) {
            if (BigInt(arr[i - 2]) + BigInt(arr[i - 1]) !== BigInt(arr[i])) return false;
        }
        return true;
    }
    function backtrack(start, path) {
        if (start === num.length && path.length >= 3 && isFibonacci(path)) return path;
        for (let i = start; i < num.length; i++) {
            if (i > start && num[start] === '0') break;
            let curr = num.substring(start, i + 1);
            if (BigInt(curr) > 2 ** 31 - 1) break;
            let result = backtrack(i + 1, [...path, curr]);
            if (result) return result;
        }
        return null;
    }
    let result = backtrack(0, []);
    return result ? result.map(Number) : [];
}

function peakIndexInMountainArray(arr) {
  let left = 0, right = arr.length - 1; 
  // using binary search to find the peak element
  while (left < right) {
    let mid = Math.floor((left + right) / 2);
    // if middle element is smaller than next one, peak must be on the right side
    if (arr[mid] < arr[mid + 1]) {
      left = mid + 1;
    } 
    // if middle element is larger than next one, peak must be on the left side
    else {
      right = mid;
    }
  }
  return left;
}

