function shiftingLetters(s, shifts) {
    // calculate the prefix sum of shifts to determine the total shift for each character
    for (let i = shifts.length - 2; i >= 0; i--) {
        shifts[i] += shifts[i + 1];
    }
    let result = '';
    for (let i = 0; i < s.length; i++) {
        // calculate the new character by shifting the current character by the total shift
        let newChar = String.fromCharCode(((s.charCodeAt(i) - 'a'.charCodeAt(0) + shifts[i]) % 26) + 'a'.charCodeAt(0));
        result += newChar;
    }
    return result;
}

function longestMountain(arr) {
    let maxLength = 0;
    // iterate over the array to find potential mountain peaks
    for (let i = 1; i < arr.length - 1; i++) {
        // check if current element is a potential mountain peak
        if (arr[i - 1] < arr[i] && arr[i] > arr[i + 1]) {
            // initialize left and right pointers
            let left = i - 1;
            let right = i + 1;
            // expand to the left
            while (left >= 0 && arr[left] < arr[left + 1]) {
                left--;
            }
            // expand to the right
            while (right < arr.length && arr[right] < arr[right - 1]) {
                right++;
            }
            // update maxLength if current mountain is longer
            maxLength = Math.max(maxLength, right - left - 1);
        }
    }
    // the algorithm solution is already optimal, with a time complexity of O(n) where n is the length of the array
    return maxLength;
}

function loudAndRich(richer, quiet) {
    var n = quiet.length;
    var graph = new Array(n).fill(0).map(() => new Array());
    var indegree = new Array(n).fill(0);
    for (var i = 0; i < richer.length; i++) {
        // Build the graph and calculate the indegree of each node
        graph[richer[i][0]].push(richer[i][1]);
        indegree[richer[i][1]]++;
    }
    var answer = new Array(n).fill(0).map((_, i) => i);
    var queue = [];
    for (var i = 0; i < n; i++) {
        if (indegree[i] === 0) {
            // Initialize the queue with nodes having indegree 0
            queue.push(i);
        }
    }
    while (queue.length > 0) {
        var u = queue.shift();
        for (var v of graph[u]) {
            // Update the answer for each neighbor of the current node
            if (quiet[answer[u]] < quiet[answer[v]]) {
                answer[v] = answer[u];
            }
            indegree[v]--;
            if (indegree[v] === 0) {
                // Add the neighbor to the queue if its indegree becomes 0
                queue.push(v);
            }
        }
    }
    return answer;
}

function backspaceCompare(s, t) {
    // Initialize two pointers at the end of each string
    let i = s.length - 1, j = t.length - 1;
    // Initialize counters for backspaces
    let backS = 0, backT = 0;
    // Loop through both strings from the end
    while (i >= 0 || j >= 0) {
        // Move pointer i until we find a character that is not backspaced
        while (i >= 0) {
            // If we encounter a '#', increment backspace counter
            if (s[i] === '#') {
                backS++;
                i--;
            } 
            // If we have backspaces, decrement counter and move pointer
            else if (backS > 0) {
                backS--;
                i--;
            } 
            // If we don't have backspaces, break the loop
            else {
                break;
            }
        }
        // Move pointer j until we find a character that is not backspaced
        while (j >= 0) {
            // If we encounter a '#', increment backspace counter
            if (t[j] === '#') {
                backT++;
                j--;
            } 
            // If we have backspaces, decrement counter and move pointer
            else if (backT > 0) {
                backT--;
                j--;
            } 
            // If we don't have backspaces, break the loop
            else {
                break;
            }
        }
        // If both pointers are out of bounds, strings are equal
        if (i < 0 && j < 0) {
            return true;
        }
        // If one pointer is out of bounds and the other is not, strings are not equal
        if (i < 0 || j < 0) {
            return false;
        }
        // If characters at current positions are different, strings are not equal
        if (s[i] !== t[j]) {
            return false;
        }
        // Move both pointers
        i--;
        j--;
    }
    // If we have reached this point, strings are equal
    return true;
}

function rectangleArea(rectangles) {
  const MOD = 1000000007n;
  const xs = new Set();
  for (const [x1, , x2] of rectangles) { xs.add(x1); xs.add(x2); }
  const sortedXs = [...xs].sort((a, b) => a - b);
  let area = 0n;
  for (let i = 0; i < sortedXs.length - 1; i++) {
    const x1 = sortedXs[i], x2 = sortedXs[i + 1];
    const width = x2 - x1;
    if (width <= 0) continue;
    const intervals = [];
    for (const [rx1, ry1, rx2, ry2] of rectangles) {
      if (rx1 <= x1 && rx2 >= x2) intervals.push([ry1, ry2]);
    }
    intervals.sort((a, b) => a[0] - b[0]);
    let totalHeight = 0n;
    let curStart = null, curEnd = null;
    for (const [y1, y2] of intervals) {
      if (curEnd === null || y1 > curEnd) {
        if (curEnd !== null) totalHeight += BigInt(curEnd - curStart);
        curStart = y1; curEnd = y2;
      } else {
        curEnd = Math.max(curEnd, y2);
      }
    }
    if (curEnd !== null) totalHeight += BigInt(curEnd - curStart);
    area = (area + BigInt(width) * totalHeight) % MOD;
  }
  return Number(area);
}

function findSecretWord(wordlist, master) {
    let possibleWords = wordlist.slice();
    let allowedGuesses = 10;
    for (let i = 0; i < allowedGuesses; i++) {
        // calculate the word with the most possible matches
        let wordToGuess = possibleWords[0];
        let maxMatches = 0;
        for (let j = 1; j < possibleWords.length; j++) {
            let matches = 0;
            for (let k = 0; k < possibleWords[j].length; k++) {
                // count the number of matches between the current word and the word to guess
                if (possibleWords[j][k] === possibleWords[0][k]) matches++;
            }
            if (matches > maxMatches) {
                maxMatches = matches;
                wordToGuess = possibleWords[j];
            }
        }
        let matches = master.guess(wordToGuess);
        if (matches === 6) return;
        // filter the possible words based on the number of matches
        possibleWords = possibleWords.filter(word => {
            let count = 0;
            for (let k = 0; k < word.length; k++) {
                // count the number of matches between the current word and the word to guess
                if (word[k] === wordToGuess[k]) count++;
            }
            return count === matches;
        });
    }
}

function mirrorReflection(p, q) {
    let gcd = function(a, b) { return b === 0 ? a : gcd(b, a % b); };
    let g = gcd(p, q);
    p /= g; q /= g;
    if (p % 2 === 0) return 2;
    if (q % 2 === 0) return 0;
    return 1;
}

function nextPrimePalindrome(n) {
    // check if a number is palindrome
    function isPalindrome(num) {
        // convert number to string and compare with its reverse
        return num.toString() === num.toString().split('').reverse().join('');
    }

    // check if a number is prime
    function isPrime(num) {
        // 0 and 1 are not prime numbers
        if (num < 2) return false;
        // check divisibility from 2 to sqrt(num)
        for (let i = 2, sqrt = Math.sqrt(num); i <= sqrt; i++) 
            // if num is divisible by any number, it's not prime
            if (num % i === 0) return false;
        // if num is not divisible by any number, it's prime
        return true;
    }

    // start checking from n
    while (true) {
        // check if current number is palindrome and prime
        if (isPalindrome(n) && isPrime(n)) return n;
        // if not, increment and check the next number
        n++;
    }
}

