function advantageCount(nums1, nums2) {
  // Sort nums1 in ascending order
  nums1.sort((a, b) => a - b);
  // Sort nums2 in descending order and store the index and value in an array
  let sortedNums2 = nums2.map((val, idx) => [val, idx]).sort((a, b) => b[0] - a[0]);
  let left = 0, right = nums1.length - 1;
  let result = new Array(nums1.length);
  // Iterate through sortedNums2 and assign the largest possible value from nums1
  for (let i = 0; i < sortedNums2.length; i++) {
    // If the current value in nums1 is greater than the current value in nums2, assign it
    if (nums1[right] > sortedNums2[i][0]) {
      result[sortedNums2[i][1]] = nums1[right];
      right--;
    } 
    // Otherwise, assign the smallest possible value from nums1
    else {
      result[sortedNums2[i][1]] = nums1[left];
      left++;
    }
  }
  return result;
}

