function subtreeWithAllDeepest(root) {
    function dfs(node) {
        // calculate the depth of the current node
        if (!node) return 0;
        return 1 + Math.max(dfs(node.left), dfs(node.right));
    }
    function findLCA(node, depth) {
        // find the LCA of the deepest nodes
        if (!node) return null;
        if (depth === 0) return node;
        const leftDepth = dfs(node.left);
        const rightDepth = dfs(node.right);
        if (leftDepth === rightDepth) return node;
        if (leftDepth > rightDepth) return findLCA(node.left, depth - 1);
        return findLCA(node.right, depth - 1);
    }
    const maxDepth = dfs(root);
    return findLCA(root, maxDepth - 1);
}

function binaryGap(n) {
