    let maxDistance = 0;
    let lastOneIndex = -1;
    for (let i = 0; i < binaryString.length; i++) { // iterate over binary string
        if (binaryString[i] === '1') { // check if current character is '1'
            if (lastOneIndex !== -1) { // if this is not the first '1'
                maxDistance = Math.max(maxDistance, i - lastOneIndex); // update max distance
            }
            lastOneIndex = i; // update last '1' index
        }
    }
    return maxDistance; // return max distance
}

function lenLongestFibSubseq(arr) {
    let numSet = new Set(arr); // create a set for O(1) lookup
    let maxLength = 0;
    for (let i = 0; i < arr.length; i++) {
        for (let j = i + 1; j < arr.length; j++) {
            let a = arr[i], b = arr[j]; // initialize the first two numbers
            let length = 2; // the length of the current subsequence
            // generate the next number in the sequence and check if it exists in the set
            while (numSet.has(a + b)) {
                let temp = a; // store the current a
                a = b; // update a to be the current b
                b = temp + b; // update b to be the sum of the previous two numbers
                length++; // increment the length of the subsequence
            }
            maxLength = Math.max(maxLength, length); // update the maximum length
        }
    }
    // if the maximum length is less than 3, return 0 because a Fibonacci-like sequence must have at least 3 numbers
    return maxLength < 3 ? 0 : maxLength;
}

function shortestSubarray(nums, k) {
  const n = nums.length;
  const prefixSum = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) prefixSum[i + 1] = prefixSum[i] + nums[i];
  let result = n + 1;
  const deque = [];
  for (let i = 0; i <= n; i++) {
    while (deque.length > 0 && prefixSum[i] - prefixSum[deque[0]] >= k) {
      result = Math.min(result, i - deque.shift());
    }
    while (deque.length > 0 && prefixSum[i] <= prefixSum[deque[deque.length - 1]]) {
      deque.pop();
    }
    deque.push(i);
  }
  return result <= n ? result : -1;
}

function buddyStrings(s, goal) {
