        // If the characters at the current index are different
        if (s[i] !== goal[i]) {
            // If this is the first different character, store its index
            if (firstDiff === -1) firstDiff = i;
            // If this is the second different character, store its index
            else if (secondDiff === -1) secondDiff = i;
            // If there are more than two different characters, return false
            else return false;
        }
    }
    // If there are exactly two different characters and they are a swap of each other, return true
    return firstDiff !== -1 && secondDiff !== -1 && s[firstDiff] === goal[secondDiff] && s[secondDiff] === goal[firstDiff];
}

function transpose(matrix) {
    // Initialize an empty array to store the transposed matrix
    let transposedMatrix = new Array(matrix[0].length).fill(0).map(() => new Array(matrix.length).fill(0));
    // Iterate over each element in the original matrix and assign it to its corresponding position in the transposed matrix
    for (let i = 0; i < matrix.length; i++) {
        for (let j = 0; j < matrix[0].length; j++) {
            // Swap row and column indices to transpose the matrix
            transposedMatrix[j][i] = matrix[i][j];
        }
    }
    return transposedMatrix;
}

function distanceK(root, target, k) {
  // Create a hash map to store the parent of each node
  const parentMap = {};
  function dfs(node, parent) {
    // If the node is null, return
    if (!node) return;
    // Store the parent of the current node
    parentMap[node.val] = parent;
    // Recursively call dfs on the left and right children
    dfs(node.left, node);
    dfs(node.right, node);
  }
  // Call dfs on the root node
  dfs(root, null);

  // Create a queue for BFS and add the target node
  const queue = [[target, 0]];
  // Create a set to store the visited nodes
  const visited = new Set([target.val]);
  // Create a result array to store the nodes at distance k
  const result = [];
  // Perform BFS
  while (queue.length) {
    // Dequeue the current node and its distance
    const [node, distance] = queue.shift();
    // If the distance is equal to k, add the node to the result array
    if (distance === k) result.push(node.val);
    // If the distance is greater than k, break the loop
    if (distance > k) break;
    // Get the neighbors of the current node (left, right, and parent)
    const neighbors = [node.left, node.right, parentMap[node.val]];
    // For each neighbor
    for (const neighbor of neighbors) {
      // If the neighbor is not null and has not been visited
      if (neighbor && !visited.has(neighbor.val)) {
        // Mark the neighbor as visited
        visited.add(neighbor.val);
        // Enqueue the neighbor and its distance
        queue.push([neighbor, distance + 1]);
      }
    }
  }
  // Return the result array
  return result;
}

function maxDistToClosest(seats) {
    let maxDistance = 0;
    let currentDistance = 0;
    let seenPerson = false;
    for (let i = 0; i < seats.length; i++) {
        if (seats[i] === 1) {
            if (!seenPerson) {
                maxDistance = Math.max(maxDistance, currentDistance);
            } else {
                maxDistance = Math.max(maxDistance, Math.ceil(currentDistance / 2));
            }
            seenPerson = true;
            currentDistance = 0;
        } else {
            currentDistance++;
        }
    }
    maxDistance = Math.max(maxDistance, currentDistance);
    return maxDistance;
}

function minRefuelStops(target, startFuel, stations) {
  let fuel = startFuel;
  let stops = 0;
  let i = 0;
  const n = stations.length;
  const heap = [];
  while (fuel < target) {
    while (i < n && stations[i][0] <= fuel) {
      heap.push(stations[i][1]);
      i++;
    }
    if (heap.length === 0) return -1;
    heap.sort((a, b) => b - a);
    fuel += heap.shift();
    stops++;
  }
  return stops;
}

function matrixScore(grid) {
    // Initialize the score to 0
    let score = 0;
    // Get the number of rows and columns in the grid
    let rows = grid.length;
    let cols = grid[0].length;

    // Iterate over each row in the grid
    for (let i = 0; i < rows; i++) {
        // If the first element of the row is 0, flip the row to maximize the score
        if (grid[i][0] === 0) {
            // Flip the row by toggling each value in the row
            for (let j = 0; j < cols; j++) {
                grid[i][j] = 1 - grid[i][j];
            }
        }
    }

    // Iterate over each column in the grid
    for (let j = 1; j < cols; j++) {
        // Count the number of 1's in the column
        let ones = 0;
        for (let i = 0; i < rows; i++) {
            if (grid[i][j] === 1) {
                ones++;
            }
        }
        // If the number of 1's in the column is less than half the number of rows, flip the column to maximize the score
        if (ones < rows / 2) {
            // Flip the column by toggling each value in the column
            for (let i = 0; i < rows; i++) {
                grid[i][j] = 1 - grid[i][j];
            }
        }
    }

    // Calculate the score by interpreting each row as a binary number and summing them up
    for (let i = 0; i < rows; i++) {
        let rowScore = 0;
        for (let j = 0; j < cols; j++) {
            // Calculate the binary value of the row
            rowScore += grid[i][j] * (1 << (cols - 1 - j));
        }
        score += rowScore;
    }

    return score;
}

function lemonadeChange(bills) {
  let fiveDollars = 0, tenDollars = 0; // initialize counters for $5 and $10 bills
  for (let i = 0; i < bills.length; i++) { // iterate over each customer's bill
    if (bills[i] === 5) fiveDollars++; // if bill is $5, increment $5 counter
    else if (bills[i] === 10) { // if bill is $10
      if (fiveDollars === 0) return false; // if no $5 bills, can't give change
      fiveDollars--; tenDollars++; // decrement $5 counter, increment $10 counter
    } else { // if bill is $20
      if (tenDollars > 0 && fiveDollars > 0) { // if have $10 and $5 bills, give change
        tenDollars--; fiveDollars--;
      } else if (fiveDollars >= 3) { // if have at least 3 $5 bills, give change
