  return true; // if all customers got correct change, return true
}

function carFleet(target, position, speed) {
    // Create a list of cars with their positions and speeds
    let cars = position.map((pos, i) => [pos, speed[i]]);
    // Sort the cars by their positions in descending order
    cars.sort((a, b) => b[0] - a[0]);
    // Initialize the count of car fleets and the time of the previous fleet
    let count = 0, prevTime = 0;
    // Iterate over the sorted cars
    for (let i = 0; i < cars.length; i++) {
        // Calculate the time it takes for the current car to reach the target
        let time = (target - cars[i][0]) / cars[i][1];
        // If the current car's time is greater than the previous fleet's time, it forms a new fleet
        if (time > prevTime) {
            count++;
            prevTime = time;
        }
    }
    return count;
}

function robotSim(commands, obstacles) {
    let x = 0, y = 0, dx = 0, dy = 1, maxDistance = 0;
    let obstacleSet = new Set(obstacles.map(([a, b]) => `${a},${b}`));
    for (let command of commands) {
        // if command is negative, change direction
        if (command < 0) {
            if (command === -1) {
                // turn right
                [dx, dy] = [dy, -dx];
            } else {
                // turn left
                [dx, dy] = [-dy, dx];
            }
        } else {
            // move forward
            for (let i = 0; i < command; i++) {
                let newX = x + dx, newY = y + dy;
                if (obstacleSet.has(`${newX},${newY}`)) break;
                x = newX; y = newY;
            }
        }
        // update max distance
        maxDistance = Math.max(maxDistance, x * x + y * y);
    }
    return maxDistance;
}

function middleNode(head) {
    // Initialize two pointers, slow and fast, both at the head of the list
    let slow = head;
    let fast = head;
    // Loop through the list, moving the fast pointer twice as fast as the slow pointer
    while (fast !== null && fast.next !== null) {
        // Move the slow pointer one step at a time
        slow = slow.next;
        // Move the fast pointer two steps at a time
        fast = fast.next.next;
    }
    // When the fast pointer reaches the end of the list, the slow pointer will be at the middle node
    return slow;
}

