function fairCandySwap(aliceSizes, bobSizes) {
    let aliceTotal = aliceSizes.reduce((a, b) => a + b);
    let bobTotal = bobSizes.reduce((a, b) => a + b);
    let diff = (aliceTotal - bobTotal) / 2;
    let bobSet = new Set(bobSizes);
    for (let aliceSize of aliceSizes) {
        if (bobSet.has(aliceSize - diff)) {
