        }
    }
}

function nthMagicalNumber(n, a, b) {
    const MOD = 1e9 + 7;
    let left = Math.min(a, b), right = n * Math.min(a, b);
    // using binary search to find the nth magical number
    while (left < right) {
        const mid = Math.floor((left + right) / 2);
        // calculating the number of magical numbers less than or equal to mid
        const count = Math.floor(mid / a) + Math.floor(mid / b) - Math.floor(mid / lcm(a, b));
        if (count < n) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return left % MOD;
}

// helper function to calculate the least common multiple
function lcm(a, b) {
    return a * b / gcd(a, b);
}

// helper function to calculate the greatest common divisor
function gcd(a, b) {
    if (b === 0) return a;
    return gcd(b, a % b);
}

