function projectionArea(grid) {
    let xyArea = 0, yzArea = 0, zxArea = 0;
    let maxRow = new Array(grid.length).fill(0), maxCol = new Array(grid[0].length).fill(0);
    // calculate xyArea by counting non-zero cells
    for (let i = 0; i < grid.length; i++) {
        for (let j = 0; j < grid[0].length; j++) {
            if (grid[i][j] > 0) xyArea++;
            // calculate maxRow and maxCol
            maxRow[i] = Math.max(maxRow[i], grid[i][j]);
            maxCol[j] = Math.max(maxCol[j], grid[i][j]);
        }
    }
    // calculate yzArea and zxArea by summing maxRow and maxCol
    yzArea = maxRow.reduce((a, b) => a + b, 0);
    zxArea = maxCol.reduce((a, b) => a + b, 0);
    // return total area
    return xyArea + yzArea + zxArea;
}

function decodeAtIndex(s, k) {
    let size = 0; 
    // calculate the total length of the decoded string
    for (let i = 0; i < s.length; i++) {
        if (!isNaN(s[i])) {
            size *= parseInt(s[i]);
        } else {
            size++;
        }
    }

    // start from the end of the string and work backwards
    for (let i = s.length - 1; i >= 0; i--) {
        // if the current character is a digit, divide k by the digit
        if (!isNaN(s[i])) {
            k %= size;
            size /= parseInt(s[i]);
        } 
        // if the current character is a letter, check if k is 0
        else {
            // if k is 0, return the current character
            if (k == size) {
                return s[i];
            }
            // if k is not 0, decrement size
            size--;
        }
    }
}

function superEggDrop(k, n) {
  // The problem can be solved using dynamic programming
  let dp = Array(k + 1).fill(0).map(() => Array(n + 1).fill(0));
  let m = 0;
  // Continue the process until we find the minimum number of moves
  while (dp[k][m] < n) {
    // Increment the number of moves
    m++;
    // For each number of eggs
    for (let i = 1; i <= k; i++) {
      // For each number of moves
      dp[i][m] = dp[i][m - 1] + dp[i - 1][m - 1] + 1;
    }
  }
  // The minimum number of moves is the current number of moves
  return m;
}

