function minEatingSpeed(piles, h) {
  function canEatAll(k) {
    // calculate the time it takes to eat all bananas at speed k
    let time = 0;
    for (let pile of piles) {
      time += Math.ceil(pile / k);
    }
    return time <= h;
  }

  // binary search for the minimum speed
  let left = 1;
  let right = Math.max(...piles);
  while (left < right) {
    // calculate the middle speed
    let mid = Math.floor((left + right) / 2);
    // if Koko can eat all bananas at speed mid, try a lower speed
    if (canEatAll(mid)) {
      right = mid;
    } 
    // if Koko cannot eat all bananas at speed mid, try a higher speed
    else {
      left = mid + 1;
    }
  }
  // the minimum speed is the left boundary
  return left;
}

function profitableSchemes(n, minProfit, group, profit) {
  const MOD = 1e9 + 7;
  const dp = Array.from({length: n + 1}, () => new Array(minProfit + 1).fill(0));
  dp[0][0] = 1;
  for (let i = 0; i < group.length; i++) {
    const g = group[i], p = profit[i];
    for (let j = n; j >= g; j--) {
      for (let k = minProfit; k >= 0; k--) {
        const newK = Math.min(minProfit, k + p);
        dp[j][newK] = (dp[j][newK] + dp[j - g][k]) % MOD;
      }
    }
  }
  let result = 0;
  for (let j = 0; j <= n; j++) result = (result + dp[j][minProfit]) % MOD;
  return result;
}

function reachableNodes(edges, maxMoves, n) {
  const graph = new Map();
  for (let i = 0; i < n; i++) graph.set(i, new Map());
  for (const [u, v, cnt] of edges) {
    graph.get(u).set(v, cnt);
    graph.get(v).set(u, cnt);
  }
  const dist = new Array(n).fill(Infinity);
  dist[0] = 0;
  const pq = [[0, 0]];
  const visited = new Set();
  while (pq.length) {
    pq.sort((a, b) => a[0] - b[0]);
    const [d, u] = pq.shift();
    if (visited.has(u)) continue;
    visited.add(u);
    for (const [v, cnt] of graph.get(u)) {
      const nd = d + cnt + 1;
      if (nd < dist[v]) { dist[v] = nd; pq.push([nd, v]); }
    }
  }
  let result = 0;
  for (let i = 0; i < n; i++) if (dist[i] <= maxMoves) result++;
  for (const [u, v, cnt] of edges) {
    const a = dist[u] < maxMoves ? Math.min(cnt, maxMoves - dist[u]) : 0;
    const b = dist[v] < maxMoves ? Math.min(cnt, maxMoves - dist[v]) : 0;
    result += Math.min(cnt, a + b);
  }
  return result;
}

function spiralMatrixIII(rows, cols, rStart, cStart) {
    // initialize the result array and the directions array
    var result = [];
    var directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
    var directionIndex = 0;
    var steps = 1;
    var stepCount = 0;
    var row = rStart;
    var col = cStart;
    result.push([row, col]);

    // continue the loop until we have visited all cells
    while (result.length < rows * cols) {
        // calculate the next position based on the current direction
        var nextRow = row + directions[directionIndex][0];
        var nextCol = col + directions[directionIndex][1];

        // check if the next position is within the grid
        if (nextRow >= 0 && nextRow < rows && nextCol >= 0 && nextCol < cols) {
            // if it is, add it to the result array and move to the next position
            result.push([nextRow, nextCol]);
        }

        // move to the next position
        row = nextRow;
        col = nextCol;

        // increment the step count
        stepCount++;

        // if we have taken the required number of steps in the current direction, change the direction
        if (stepCount === steps) {
            // reset the step count
            stepCount = 0;

            // change the direction
            directionIndex = (directionIndex + 1) % 4;

            // if we have changed the direction twice, increment the number of steps
            if (directionIndex % 2 === 0) {
                steps++;
            }
        }
    }

    return result;
}

function constructFromPrePost(preorder, postorder) {
    // Create a hashmap to store the indices of the postorder array for quick lookup
    let postIndexMap = {};
    for (let i = 0; i < postorder.length; i++) {
        postIndexMap[postorder[i]] = i;
    }

    function construct(preStart, preEnd, postStart, postEnd) {
        if (preStart > preEnd) return null;
        let root = new TreeNode(preorder[preStart]);
        // If the current node has no children, return it
        if (preStart + 1 > preEnd) return root;

        // Find the index of the left child in the postorder array
        let leftChildPostIndex = postIndexMap[preorder[preStart + 1]];
        // Calculate the number of nodes in the left subtree
        let leftSubtreeSize = leftChildPostIndex - postStart + 1;

        // Recursively construct the left and right subtrees
        root.left = construct(preStart + 1, preStart + leftSubtreeSize, postStart, leftChildPostIndex);
        root.right = construct(preStart + leftSubtreeSize + 1, preEnd, leftChildPostIndex + 1, postEnd - 1);

        return root;
    }

    return construct(0, preorder.length - 1, 0, postorder.length - 1);
}

function isMonotonic(nums) {
  // Check if array is increasing
  let isIncreasing = true;
  // Check if array is decreasing
  let isDecreasing = true;
  for (let i = 0; i < nums.length - 1; i++) {
    // If current element is greater than next element, array is not increasing
    if (nums[i] > nums[i + 1]) isIncreasing = false;
    // If current element is less than next element, array is not decreasing
    if (nums[i] < nums[i + 1]) isDecreasing = false;
  }
  // Return true if array is either increasing or decreasing
  return isIncreasing || isDecreasing;
}

function sortArrayByParity(nums) {
  let left = 0; 
  let right = nums.length - 1;
  // iterate through the array and swap even numbers to the left and odd numbers to the right
  while (left < right) {
    if (nums[left] % 2 === 0) {
      left++;
    } else if (nums[right] % 2 === 1) {
      right--;
    } else {
      let temp = nums[left];
      nums[left] = nums[right];
      nums[right] = temp;
      left++;
      right--;
    }
  }
  return nums;
}

function totalFruit(fruits) {
    let maxFruits = 0, left = 0, fruitCount = {};
    // Initialize the window boundaries and a hash table to store the frequency of each fruit type
    for (let right = 0; right < fruits.length; right++) {
        // Expand the window to the right
        fruitCount[fruits[right]] = (fruitCount[fruits[right]] || 0) + 1;
        // While there are more than 2 types of fruits in the window, shrink the window from the left
        while (Object.keys(fruitCount).length > 2) {
            // Remove the fruit at the left boundary from the hash table
            fruitCount[fruits[left]]--;
            if (fruitCount[fruits[left]] === 0) delete fruitCount[fruits[left]];
            left++;
        }
        // Update the maximum number of fruits that can be picked
        maxFruits = Math.max(maxFruits, right - left + 1);
    }
    return maxFruits;
}

function numSpecialEquivGroups(words) {
    // Create a set to store unique special-equivalent strings
    var set = new Set();
    for (var word of words) {
        // Create two arrays to store even and odd indexed characters
        var even = [], odd = [];
        for (var i = 0; i < word.length; i++) {
            // Separate even and odd indexed characters
            if (i % 2 === 0) even.push(word[i]); else odd.push(word[i]);
        }
        // Sort even and odd indexed characters and join them into a string
        var sortedEven = even.sort().join(''), sortedOdd = odd.sort().join('');
        // Create a special-equivalent string by concatenating sorted even and odd strings
        var specialEquivalent = sortedEven + sortedOdd;
        // Add the special-equivalent string to the set
        set.add(specialEquivalent);
    }
    // The number of groups is the size of the set
    return set.size;
}

