function numPermsDISequence(s) {
  const n = s.length;
  const MOD = 1e9 + 7;
  let prev = [1];
  for (let i = 1; i <= n; i++) {
    const cur = new Array(i + 1).fill(0);
    if (s[i - 1] === 'I') {
      let prefix = 0;
      for (let j = 0; j <= i; j++) {
        cur[j] = prefix % MOD;
        if (j < prev.length) prefix += prev[j];
      }
    } else {
      let suffix = 0;
      for (let j = i; j >= 0; j--) {
        if (j < prev.length) suffix += prev[j];
        cur[j] = suffix % MOD;
      }
    }
    prev = cur;
  }
  let res = 0;
  for (const v of prev) res = (res + v) % MOD;
  return res;
}

function findAndReplacePattern(words, pattern) {
    function match(word) {
        const pToW = {}, wToP = {};
        for (let i = 0; i < word.length; i++) {
            const p = pattern[i], w = word[i];
            if (pToW[p] === undefined && wToP[w] === undefined) {
                pToW[p] = w;
                wToP[w] = p;
            } else if (pToW[p] !== w || wToP[w] !== p) {
                return false;
            }
        }
        return true;
    }
    let result = [];
    for (let word of words) if (match(word)) result.push(word);
    return result;
}

class StockSpanner {
    constructor() { this.stack = []; }
    next(price) {
        let span = 1;
        while (this.stack.length > 0 && this.stack[this.stack.length - 1][0] <= price) {
            span += this.stack[this.stack.length - 1][1];
            this.stack.pop();
        }
        this.stack.push([price, span]);
        return span;
    }
}

function allPossibleFBT(n) {
    if (n % 2 === 0) return [];
    if (n === 1) return [new TreeNode(0)];

    let result = [];
    for (let i = 1; i < n; i += 2) {
        let leftTrees = allPossibleFBT(i);
        let rightTrees = allPossibleFBT(n - i - 1);
        for (let left of leftTrees) {
            for (let right of rightTrees) {
                let root = new TreeNode(0);
                root.left = left;
                root.right = right;
                result.push(root);
            }
        }
    }
    return result;
}

function TreeNode(val, left, right) {
    this.val = (val === undefined ? 0 : val);
    this.left = (left === undefined ? null : left);
    this.right = (right === undefined ? null : right);
}

function FreqStack() {
    // Initialize a hash map to store the frequency of each element
    let frequencyMap = {};
    // Initialize a hash map to store the stack of elements with the same frequency
    let frequencyStacks = {};
    // Initialize the maximum frequency
    let maxFrequency = 0;

    // Function to push an element to the stack
    this.push = function(x) {
        // Increment the frequency of the element
        frequencyMap[x] = (frequencyMap[x] || 0) + 1;
        // Update the maximum frequency
        maxFrequency = Math.max(maxFrequency, frequencyMap[x]);
        // Push the element to the stack with the corresponding frequency
        if (!frequencyStacks[frequencyMap[x]]) frequencyStacks[frequencyMap[x]] = [];
        frequencyStacks[frequencyMap[x]].push(x);
    };

    // Function to pop the most frequent element from the stack
    this.pop = function() {
        // Pop the most frequent element from the stack with the maximum frequency
        let result = frequencyStacks[maxFrequency].pop();
        // Decrement the frequency of the popped element
        frequencyMap[result]--;
        // If the stack with the maximum frequency is empty, decrement the maximum frequency
        if (frequencyStacks[maxFrequency].length === 0) maxFrequency--;
        // Return the popped element
        return result;
    };
}

function sumSubseqWidths(nums) {
  nums.sort((a, b) => a - b);
  const MOD = 1e9 + 7;
  const n = nums.length;
  const pow2 = new Array(n);
  pow2[0] = 1;
  for (let i = 1; i < n; i++) pow2[i] = (pow2[i - 1] * 2) % MOD;
  let res = 0;
  for (let i = 0; i < n; i++) {
    res = (res + nums[i] * (pow2[i] - pow2[n - 1 - i]) % MOD + MOD) % MOD;
  }
  return res;
}

function superpalindromesInRange(left, right) {
    function isPalindrome(num) {
        // check if the number is a palindrome
        return num.toString() === num.toString().split('').reverse().join('');
    }

    let count = 0;
    for (let i = 1; i <= 10000; i++) {
        // generate all possible palindrome numbers
        let palindromeNum = i;
        let square = palindromeNum * palindromeNum;
        // check if the square is within the given range and is a palindrome
        if (square >= parseInt(left) && square <= parseInt(right) && isPalindrome(square) && isPalindrome(palindromeNum)) {
            count++;
        }
    }
    return count;
}

function surfaceArea(grid) {
    let n = grid.length;
    let result = 0;
    // calculate the surface area of each cell
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] > 0) {
                // add the area of the top and bottom faces
                result += 2;
                // add the area of the four side faces
                result += 4 * grid[i][j];
                // subtract the area of the adjacent cells
                if (i > 0) result -= Math.min(grid[i][j], grid[i - 1][j]);
                if (i < n - 1) result -= Math.min(grid[i][j], grid[i + 1][j]);
                if (j > 0) result -= Math.min(grid[i][j], grid[i][j - 1]);
                if (j < n - 1) result -= Math.min(grid[i][j], grid[i][j + 1]);
            }
        }
    }
    return result;
}

function atMostNGivenDigitSet(digits, n) {
    // convert n to string to easily access its digits
    let nStr = n.toString();
    let res = 0;
    // calculate number of possible numbers for each length up to n's length
    for (let i = 1; i < nStr.length; i++) {
        // calculate number of possible numbers of length i
        res += Math.pow(digits.length, i);
    }
    // calculate number of possible numbers of length n's length
    let dp = new Array(nStr.length).fill(0);
    for (let i = 0; i < digits.length; i++) {
        // check if current digit is less than n's first digit
        if (digits[i] < nStr[0]) {
            dp[0]++;
        } else if (digits[i] === nStr[0]) {
            // if equal, move to next digit
            dp[0] = 1;
            break;
        }
    }
    for (let i = 1; i < nStr.length; i++) {
        for (let j = 0; j < digits.length; j++) {
            // check if current digit is less than n's current digit
            if (digits[j] < nStr[i]) {
                dp[i] += dp[i - 1] * digits.length;
            } else if (digits[j] === nStr[i]) {
                // if equal, add to dp[i]
                dp[i] += dp[i - 1];
            }
        }
    }
    // add number of possible numbers of length n's length to result
    res += dp[nStr.length - 1];
    return res;
}

