function sumSubarrayMins(arr) {
  const MOD = 1e9 + 7;
  const n = arr.length;
  const left = new Array(n).fill(-1);
  const right = new Array(n).fill(n);
  const stack = [];
  for (let i = 0; i < n; i++) {
    // find the first smaller element on the left
    while (stack.length > 0 && arr[stack[stack.length - 1]] >= arr[i]) {
      stack.pop();
    }
    if (stack.length > 0) {
      left[i] = stack[stack.length - 1];
    }
    stack.push(i);
  }
  stack.length = 0;
  for (let i = n - 1; i >= 0; i--) {
    // find the first smaller element on the right
    while (stack.length > 0 && arr[stack[stack.length - 1]] > arr[i]) {
      stack.pop();
    }
    if (stack.length > 0) {
      right[i] = stack[stack.length - 1];
    }
    stack.push(i);
  }
  let sum = 0;
  for (let i = 0; i < n; i++) {
    // calculate the sum of min(b) for each subarray
    sum = (sum + (i - left[i]) * (right[i] - i) * arr[i]) % MOD;
  }
  return sum;
}

function smallestRangeI(nums, k) {
  // Calculate the minimum and maximum values in the array
  let minVal = Math.min(...nums);
  let maxVal = Math.max(...nums);

  // Calculate the range after applying the operation
  let range = Math.max(0, maxVal - minVal - 2 * k);

  return range;
}

function partitionDisjoint(nums) {
  // initialize variables to store the maximum value in the left subarray and the result
  let maxLeft = nums[0], maxSoFar = nums[0], result = 1;
  // iterate through the array to find the partition point
  for (let i = 1; i < nums.length; i++) {
    // update the maximum value in the left subarray if a larger value is found
    if (nums[i] < maxLeft) {
      // if a smaller value is found, update the result and reset the maximum value in the left subarray
      result = i + 1;
      maxLeft = maxSoFar;
    } else {
      // update the maximum value seen so far
      maxSoFar = Math.max(maxSoFar, nums[i]);
    }
  }
  return result;
}

function reverseOnlyLetters(s) {
    // Initialize two pointers, one at the start and one at the end of the string
    let left = 0, right = s.length - 1;
    // Convert the string to an array for easier manipulation
    s = s.split('');
    // Loop through the string until the two pointers meet
    while (left < right) {
        // If the character at the left pointer is not a letter, move the left pointer to the right
        if (!isLetter(s[left])) left++;
        // If the character at the right pointer is not a letter, move the right pointer to the left
        else if (!isLetter(s[right])) right--;
        // If both characters are letters, swap them and move both pointers
        else {
            // Swap the characters at the left and right pointers
            let temp = s[left];
            s[left] = s[right];
            s[right] = temp;
            // Move both pointers
            left++;
            right--;
        }
    }
    // Join the array back into a string and return it
    return s.join('');
}

// Helper function to check if a character is a letter
function isLetter(char) {
    return char >= 'a' && char <= 'z' || char >= 'A' && char <= 'Z';
}

function snakesAndLadders(board) {
    const n = board.length;
    const cells = new Array(n * n);
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            const idx = i % 2 === 0 ? i * n + j : i * n + n - j - 1;
            cells[idx] = board[n - i - 1][j];
        }
    }
    const queue = [[0, 0]];
    const visited = new Set([0]);
    while (queue.length > 0) {
        const [curr, rolls] = queue.shift();
        if (curr === n * n - 1) return rolls;
        for (let i = 1; i <= 6; i++) {
            let next = curr + i;
            if (next >= n * n) continue;
            if (cells[next] !== -1) next = cells[next] - 1;
            if (!visited.has(next)) {
                queue.push([next, rolls + 1]);
                visited.add(next);
            }
        }
    }
    return -1;
}

function smallestRangeII(nums, k) {
  nums.sort((a, b) => a - b);
  const n = nums.length;
  let result = nums[n - 1] - nums[0];
  for (let i = 0; i < n - 1; i++) {
    const high = Math.max(nums[n - 1] - k, nums[i] + k);
    const low = Math.min(nums[0] + k, nums[i + 1] - k);
    result = Math.min(result, high - low);
  }
  return result;
}

function isNStraightHand(deck) {
    // Create a hash map to store the frequency of each card
    var countMap = {};
    for (var i = 0; i < deck.length; i++) {
        // Count the frequency of each card
        if (countMap[deck[i]]) {
            countMap[deck[i]]++;
        } else {
            countMap[deck[i]] = 1;
        }
    }

    // Sort the cards in ascending order
    var sortedCards = Object.keys(countMap).map(Number).sort(function(a, b) {
        return a - b;
    });

    // Iterate over the sorted cards
    for (var i = 0; i < sortedCards.length; i++) {
        // If the current card has a count greater than 0
        if (countMap[sortedCards[i]] > 0) {
            // Decrement the count of the current card and the next cards
            var count = countMap[sortedCards[i]];
            for (var j = sortedCards[i]; j < sortedCards[i] + count; j++) {
                // If the next card does not exist or its count is less than the current count
                if (!countMap[j] || countMap[j] < count) {
                    return false;
                }
                // Decrement the count of the next card
                countMap[j] -= count;
            }
        }
    }
    return true;
}

function sortArray(nums) {
  // The algorithm solution is already optimal, using merge sort
  function mergeSort(arr) {
    // If the array has only one element, it is already sorted
    if (arr.length <= 1) return arr;
    // Find the middle index of the array
    const mid = Math.floor(arr.length / 2);
    // Divide the array into two halves
    const left = arr.slice(0, mid);
    const right = arr.slice(mid);
    // Recursively sort the two halves
    return merge(mergeSort(left), mergeSort(right));
  }

  // Merge two sorted arrays into one sorted array
  function merge(left, right) {
    // Initialize an empty array to store the merged result
    const result = [];
    // Initialize two pointers, one for each array
    let i = 0, j = 0;
    // Merge the two arrays
    while (i < left.length && j < right.length) {
      // If the current element in the left array is smaller, push it to the result
      if (left[i] < right[j]) {
        result.push(left[i]);
        i++;
      } 
      // Otherwise, push the current element in the right array to the result
      else {
        result.push(right[j]);
        j++;
      }
    }
    // If there are remaining elements in the left array, push them to the result
    while (i < left.length) {
      result.push(left[i]);
      i++;
    }
    // If there are remaining elements in the right array, push them to the result
    while (j < right.length) {
      result.push(right[j]);
      j++;
    }
    // Return the merged result
    return result;
  }

  // Call the merge sort function and return the result
  return mergeSort(nums);
}

