function wordSubsets(words1, words2) {
    let maxFreq = {};
    for (let word of words2) {
        let freq = {};
        for (let char of word) freq[char] = (freq[char] || 0) + 1;
        for (let char in freq) maxFreq[char] = Math.max(maxFreq[char] || 0, freq[char]);
    }
    let result = [];
    for (let word of words1) {
        let freq = {};
        for (let char of word) freq[char] = (freq[char] || 0) + 1;
        let isUniversal = true;
        for (let char in maxFreq) {
            if ((freq[char] || 0) < maxFreq[char]) {
                isUniversal = false;
                break;
            }
        }
        if (isUniversal) result.push(word);
    }
    return result;
}

class TopVotedCandidate {
    constructor(persons, times) {
        this.times = times;
        this.leaders = [];
        const counts = {};
        let leader = -1, maxCount = 0;
        for (let i = 0; i < persons.length; i++) {
            counts[persons[i]] = (counts[persons[i]] || 0) + 1;
            if (counts[persons[i]] >= maxCount) {
                maxCount = counts[persons[i]];
                leader = persons[i];
            }
            this.leaders.push(leader);
        }
    }
    q(t) {
        let left = 0, right = this.times.length - 1;
        while (left < right) {
            const mid = Math.ceil((left + right) / 2);
            if (this.times[mid] <= t) left = mid; else right = mid - 1;
        }
        return this.leaders[left];
    }
}

function catMouseGame(graph) {
  const n = graph.length;
  const DRAW = 0, MOUSE_WIN = 1, CAT_WIN = 2;
  const MOUSE_TURN = 0, CAT_TURN = 1;

  const color = Array.from({length: n}, () => Array.from({length: n}, () => new Array(2).fill(DRAW)));
  const degree = Array.from({length: n}, () => Array.from({length: n}, () => new Array(2).fill(0)));
  for (let mouse = 0; mouse < n; mouse++) {
    for (let cat = 0; cat < n; cat++) {
      degree[mouse][cat][MOUSE_TURN] = graph[mouse].length;
      degree[mouse][cat][CAT_TURN] = graph[cat].length - (graph[cat].includes(0) ? 1 : 0);
    }
  }

  const queue = [];
  for (let cat = 1; cat < n; cat++) {
    for (let turn = 0; turn < 2; turn++) {
      if (color[0][cat][turn] === DRAW) { color[0][cat][turn] = MOUSE_WIN; queue.push([0, cat, turn]); }
      if (color[cat][cat][turn] === DRAW) { color[cat][cat][turn] = CAT_WIN; queue.push([cat, cat, turn]); }
    }
  }

  function parents(mouse, cat, turn) {
    const result = [];
    if (turn === CAT_TURN) {
      for (const m of graph[mouse]) result.push([m, cat, MOUSE_TURN]);
    } else {
      for (const c of graph[cat]) {
        if (c !== 0) result.push([mouse, c, CAT_TURN]);
      }
    }
    return result;
  }

  let qi = 0;
  while (qi < queue.length) {
    const [mouse, cat, turn] = queue[qi++];
    const result = color[mouse][cat][turn];
    for (const [pMouse, pCat, pTurn] of parents(mouse, cat, turn)) {
      if (color[pMouse][pCat][pTurn] !== DRAW) continue;
      let win;
      if (pTurn === MOUSE_TURN) win = (result === MOUSE_WIN);
      else win = (result === CAT_WIN);
      if (win) {
        color[pMouse][pCat][pTurn] = result;
        queue.push([pMouse, pCat, pTurn]);
      } else {
        degree[pMouse][pCat][pTurn]--;
        if (degree[pMouse][pCat][pTurn] === 0) {
          color[pMouse][pCat][pTurn] = (pTurn === MOUSE_TURN) ? CAT_WIN : MOUSE_WIN;
          queue.push([pMouse, pCat, pTurn]);
        }
      }
    }
  }

  return color[1][2][MOUSE_TURN];
}

function minAddToMakeValid(s) {
  let count = 0; // initialize count of moves needed
  let balance = 0; // initialize balance of parentheses
  for (let i = 0; i < s.length; i++) { 
    // if opening parenthesis, increase balance
    if (s[i] === '(') balance++; 
    // if closing parenthesis, decrease balance and if negative, increment count and reset balance
    else if (s[i] === ')') { balance--; if (balance < 0) { count++; balance = 0; } }
  }
  // add remaining balance to count, as each opening parenthesis without a closing one needs a move
  return count + balance; 
}

function maxSubarraySumCircular(nums) {
    // calculate total sum of the array
    let totalSum = 0;
    for (let i = 0; i < nums.length; i++) {
        totalSum += nums[i];
    }

    // calculate maximum sum of a subarray using Kadane's algorithm
    let maxSum = -Infinity;
    let currentMaxSum = 0;
    for (let i = 0; i < nums.length; i++) {
        // update current max sum by adding current number or starting a new subarray
        currentMaxSum = Math.max(nums[i], currentMaxSum + nums[i]);
        // update max sum if current max sum is greater
        maxSum = Math.max(maxSum, currentMaxSum);
    }

    // calculate minimum sum of a subarray using Kadane's algorithm
    let minSum = Infinity;
    let currentMinSum = 0;
    for (let i = 0; i < nums.length; i++) {
        // update current min sum by adding current number or starting a new subarray
        currentMinSum = Math.min(nums[i], currentMinSum + nums[i]);
        // update min sum if current min sum is smaller
        minSum = Math.min(minSum, currentMinSum);
    }

    // if total sum is equal to min sum, it means all numbers are negative, so return max sum
    if (totalSum === minSum) {
        return maxSum;
    }
    // otherwise, return the maximum of max sum and total sum minus min sum
    else {
        return Math.max(maxSum, totalSum - minSum);
    }
}

function numMusicPlaylists(n, goal, k) {
    const MOD = 1e9 + 7;
    const dp = Array(goal + 1).fill(0).map(() => Array(n + 1).fill(0));
    dp[0][0] = 1;
    for (let i = 1; i <= goal; i++) {
        for (let j = 1; j <= n; j++) {
            dp[i][j] = (dp[i][j] + dp[i - 1][j - 1] * (n - j + 1)) % MOD;
            if (j > k) dp[i][j] = (dp[i][j] + dp[i - 1][j] * (j - k)) % MOD;
        }
    }
    return dp[goal][n];
}

class CBTInserter {
    constructor(root) {
        this.root = root;
        this.queue = [];
        let q = [root];
        while (q.length) {
            let node = q.shift();
            if (!node.left || !node.right) this.queue.push(node);
            if (node.left) q.push(node.left);
            if (node.right) q.push(node.right);
        }
    }
    insert(val) {
        const node = new TreeNode(val);
        const parent = this.queue[0];
        if (!parent.left) parent.left = node;
        else { parent.right = node; this.queue.shift(); }
        this.queue.push(node);
        return parent.val;
    }
    get_root() { return this.root; }
}

function sortArrayByParityII(nums) {
    let evenIndex = 0, oddIndex = 1; // initialize two pointers for even and odd indices
    while (evenIndex < nums.length && oddIndex < nums.length) { 
        // if the current even index has an odd number, swap it with the current odd index
        if (nums[evenIndex] % 2 === 1) {
            // swap nums[evenIndex] and nums[oddIndex]
            let temp = nums[evenIndex];
            nums[evenIndex] = nums[oddIndex];
            nums[oddIndex] = temp;
            // move the odd index forward
            oddIndex += 2; 
        } else { 
            // if the current even index has an even number, move the even index forward
            evenIndex += 2; 
        }
    }
    return nums; // return the sorted array
}

function threeSumMulti(arr, target) {
  const MOD = 1e9 + 7;
  arr.sort((a, b) => a - b);
  let count = 0;
  for (let i = 0; i < arr.length - 2; i++) {
    let left = i + 1;
    let right = arr.length - 1;
    while (left < right) {
      const sum = arr[i] + arr[left] + arr[right];
      if (sum < target) {
        left++;
      } else if (sum > target) {
        right--;
      } else if (arr[left] === arr[right]) {
        const windowSize = right - left + 1;
        count = (count + windowSize * (windowSize - 1) / 2) % MOD;
        break;
      } else {
        let leftCount = 1;
        while (left + 1 < right && arr[left] === arr[left + 1]) { leftCount++; left++; }
        let rightCount = 1;
        while (right - 1 > left && arr[right] === arr[right - 1]) { rightCount++; right--; }
        count = (count + leftCount * rightCount) % MOD;
        left++;
        right--;
      }
    }
  }
  return count;
}

function minFlipsMonoIncr(s) {
    // Initialize variables to keep track of the number of flips for '0' and '1' respectively
    let flipsToZero = 0, flipsToOne = 0;
    // Iterate over the string
    for (let i = 0; i < s.length; i++) {
        // If the current character is '1', we need to flip all previous '1's to '0' if we want to flip this '1' to '0'
        if (s[i] === '1') {
            // So, we increment the flipsToZero counter by 1
            flipsToZero++;
        } else {
            // If the current character is '0', we need to flip all previous '0's to '1' if we want to flip this '0' to '1'
            // So, we increment the flipsToOne counter by the number of '1's we have seen so far
            flipsToOne = Math.min(flipsToOne + 1, flipsToZero);
        }
    }
    // Return the minimum number of flips
    return Math.min(flipsToZero, flipsToOne);
}

function numSubarraysWithSum(nums, goal) {
    // Initialize a hashmap to store the cumulative sum and its frequency
    var count = {0: 1};
    var sum = 0, res = 0;
    // Iterate over the array and calculate the cumulative sum
    for (var i = 0; i < nums.length; i++) {
        // Update the cumulative sum
        sum += nums[i];
        // Check if the difference between the current sum and the goal exists in the hashmap
        res += count[sum - goal] || 0;
        // Update the frequency of the current sum in the hashmap
        count[sum] = (count[sum] || 0) + 1;
    }
    return res;
}

function isLongPressedName(name, typed) {
  let nameIndex = 0, typedIndex = 0; 
  // iterate through typed string and check if characters match with name string, allowing for long presses
  while (typedIndex < typed.length) {
    if (nameIndex < name.length && name[nameIndex] === typed[typedIndex]) {
      nameIndex++;
    } else if (typedIndex === 0 || typed[typedIndex] !== typed[typedIndex - 1]) {
      return false;
    }
    typedIndex++;
  }
  // check if all characters in name string were matched
  return nameIndex === name.length;
}

function numUniqueEmails(emails) {
    // Create a set to store unique email addresses
    let uniqueEmails = new Set();
    // Iterate over each email in the input array
    for (let email of emails) {
        // Split the email into local name and domain name
        let [localName, domainName] = email.split('@');
        // Find the index of the first '+' in the local name
        let plusIndex = localName.indexOf('+');
        // If '+' is found, ignore everything after it
        if (plusIndex !== -1) localName = localName.substring(0, plusIndex);
        // Remove all '.' from the local name
        localName = localName.replace(/\./g, '');
        // Combine the modified local name and domain name to form the normalized email address
        let normalizedEmail = localName + '@' + domainName;
        // Add the normalized email address to the set
        uniqueEmails.add(normalizedEmail);
    }
    // Return the number of unique email addresses
    return uniqueEmails.size;
}

function beautifulArray(n) {
    if (n <= 0) return [];
    const mid = Math.floor((n + 1) / 2);
    const left = [];
    for (let i = 1; i < mid; i++) left.push(i);
    const right = [];
    for (let i = n; i > mid; i--) right.push(i);
    return [mid, ...left, ...right];
}

function minFallingPathSum(matrix) {
    let n = matrix.length;
    // create a copy of the first row to store the minimum sum at each position
    let dp = matrix[0].slice();
    // iterate over each row starting from the second row
    for (let i = 1; i < n; i++) {
        // create a temporary array to store the minimum sum at each position in the current row
        let temp = new Array(n).fill(Infinity);
        // iterate over each column in the current row
        for (let j = 0; j < n; j++) {
            // if it's the first column, consider the top and top-right elements
            if (j === 0) {
                // update the minimum sum at the current position
                temp[j] = Math.min(dp[j], dp[j + 1]) + matrix[i][j];
            } 
            // if it's the last column, consider the top and top-left elements
            else if (j === n - 1) {
                // update the minimum sum at the current position
                temp[j] = Math.min(dp[j - 1], dp[j]) + matrix[i][j];
            } 
            // for other columns, consider the top, top-left, and top-right elements
            else {
                // update the minimum sum at the current position
                temp[j] = Math.min(dp[j - 1], dp[j], dp[j + 1]) + matrix[i][j];
            }
        }
        // update the dp array with the minimum sum at each position in the current row
        dp = temp;
    }
    // return the minimum sum of any falling path
    return Math.min(...dp);
}

