            else if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } 
            // If the ranks are the same, then make rootX the parent of rootY and increment the rank of rootX
            else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }

    // Union the nodes that are connected
    for (let i = 0; i < graph.length; i++) {
        for (let j = 0; j < graph.length; j++) {
            // If the nodes are connected, then union them
            if (graph[i][j] === 1) {
                union(i, j);
            }
        }
    }

    // Create a map to store the size of each group
    let groupSize = {};
    for (let i = 0; i < graph.length; i++) {
        // Find the parent of the node
        let root = find(i);
        // Increment the size of the group
        groupSize[root] = (groupSize[root] || 0) + 1;
    }

    // Create a map to store the number of infected nodes in each group
    let infectedCount = {};
    for (let node of initial) {
