        // If the group has only one infected node, then remove this node
        if (infectedCount[root] === 1) {
            // If the size of the group is smaller than the minimum size, then update the minimum size and the node to remove
            if (groupSize[root] < minSize) {
                minSize = groupSize[root];
                nodeToRemove = node;
            } 
            // If the size of the group is equal to the minimum size, then update the node to remove if it has a smaller index
            else if (groupSize[root] === minSize && node < nodeToRemove) {
                nodeToRemove = node;
            }
        }
    }

    // If no node can be removed to minimize the malware spread, then return the node with the smallest index
    if (minSize === Infinity) {
