function minMalwareSpread(graph, initial) {
  const n = graph.length;
  const parent = Array.from({length: n}, (_, i) => i);
  function find(x) { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; }
  function union(x, y) { const rx = find(x), ry = find(y); if (rx !== ry) parent[rx] = ry; }
  const initialSet = new Set(initial);
  for (let i = 0; i < n; i++) {
    if (initialSet.has(i)) continue;
    for (let j = i + 1; j < n; j++) {
      if (initialSet.has(j)) continue;
      if (graph[i][j] === 1) union(i, j);
    }
  }
  const count = new Map();
  for (const node of initial) {
    for (let j = 0; j < n; j++) {
      if (!initialSet.has(j) && graph[node][j] === 1) {
        const root = find(j);
        if (!count.has(root)) count.set(root, new Set());
        count.get(root).add(node);
      }
    }
  }
  const size = new Map();
  for (let i = 0; i < n; i++) {
    if (!initialSet.has(i)) {
      const root = find(i);
      size.set(root, (size.get(root) || 0) + 1);
    }
  }
  const contribution = new Map();
  for (const [root, sources] of count) {
    if (sources.size === 1) {
      const node = [...sources][0];
      contribution.set(node, (contribution.get(node) || 0) + size.get(root));
    }
  }
  let best = Math.min(...initial);
  let bestVal = contribution.get(best) || 0;
  for (const node of initial) {
    const val = contribution.get(node) || 0;
    if (val > bestVal || (val === bestVal && node < best)) {
      bestVal = val;
      best = node;
    }
  }
  return best;
}

function knightDialer(n) {
    const MOD = 1e9 + 7;
    const moves = [[4, 6], [6, 8], [7, 9], [4, 8], [3, 9, 0], [], [1, 7, 0], [2, 6], [1, 3], [2, 4]];
    let dp = new Array(10).fill(1);
    // for each jump, update dp array based on possible moves from each cell
    for (let i = 2; i <= n; i++) {
        let next = new Array(10).fill(0);
        // for each cell, calculate the number of ways to reach it
        for (let j = 0; j < 10; j++) {
            // for each possible move from the current cell
            for (let move of moves[j]) {
                // update the number of ways to reach the next cell
                next[j] = (next[j] + dp[move]) % MOD;
            }
        }
        dp = next;
    }
    // calculate the total number of distinct phone numbers
    let total = 0;
    for (let count of dp) {
        total = (total + count) % MOD;
    }
    return total;
}

function shortestBridge(grid) {
    // find the first island using DFS
    function findIsland(grid, island) {
        for (let i = 0; i < grid.length; i++) {
            for (let j = 0; j < grid[0].length; j++) {
                if (grid[i][j] === 1) {
                    dfs(grid, i, j, island);
                    return;
                }
            }
        }
    }

    // perform DFS to mark the first island
    function dfs(grid, i, j, island) {
        if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length || grid[i][j] !== 1) {
            return;
        }
        grid[i][j] = -1; // mark as visited
        island.push([i, j]);
        dfs(grid, i - 1, j, island);
        dfs(grid, i + 1, j, island);
        dfs(grid, i, j - 1, island);
        dfs(grid, i, j + 1, island);
    }

    // perform BFS to find the shortest bridge
    function bfs(grid, island) {
        let queue = island.slice();
        let distance = 0;
        while (queue.length > 0) {
            let size = queue.length;
            for (let i = 0; i < size; i++) {
                let [x, y] = queue.shift();
                // check all four directions
                for (let [dx, dy] of [[-1, 0], [1, 0], [0, -1], [0, 1]]) {
                    let nx = x + dx;
                    let ny = y + dy;
                    if (nx < 0 || nx >= grid.length || ny < 0 || ny >= grid[0].length) {
                        continue;
                    }
                    if (grid[nx][ny] === 1) {
                        return distance;
                    }
                    if (grid[nx][ny] === 0) {
                        grid[nx][ny] = -1; // mark as visited
                        queue.push([nx, ny]);
                    }
                }
            }
            distance++;
        }
        return distance;
    }

    let island = [];
    findIsland(grid, island);
    return bfs(grid, island);
}

function reorderLogFiles(logs) {
    // separate logs into letter and digit logs
    let letterLogs = [], digitLogs = [];
    for (let log of logs) {
        // check if the log is a letter log or a digit log
        if (isNaN(log.split(' ')[1])) letterLogs.push(log); 
        else digitLogs.push(log);
    }

    // sort letter logs based on their contents
    letterLogs.sort((a, b) => {
        // compare the contents of the logs (excluding the identifier)
        let contentA = a.substring(a.indexOf(' ') + 1), contentB = b.substring(b.indexOf(' ') + 1);
        if (contentA < contentB) return -1; 
        else if (contentA > contentB) return 1; 
        // if the contents are the same, compare the identifiers
        else return a.localeCompare(b);
    });

    // combine the sorted letter logs and the original digit logs
    return letterLogs.concat(digitLogs);
}

