function movesToStamp(stamp, target) {
  const M = stamp.length, N = target.length;
  const result = [];
  const s = target.split('');
  const stamped = new Array(N).fill(false);
  let stampedCount = 0;
  function canStampAt(i) {
    let changed = false;
    for (let j = 0; j < M; j++) {
      if (s[i + j] === '?') continue;
      if (s[i + j] !== stamp[j]) return null;
      changed = true;
    }
    return changed;
  }
  let madeProgress = true;
  while (stampedCount < N && madeProgress) {
    madeProgress = false;
    for (let i = 0; i <= N - M; i++) {
      if (stamped[i]) continue;
      const canApply = canStampAt(i);
      if (canApply) {
        for (let j = 0; j < M; j++) {
          if (s[i + j] !== '?') { s[i + j] = '?'; stampedCount++; }
        }
        stamped[i] = true;
        result.push(i);
        madeProgress = true;
      }
    }
  }
  if (stampedCount < N) return [];
  return result.reverse();
}

function rangeSumBST(root, low, high) {
  // Initialize sum variable to store the sum of node values in the range
  let sum = 0;
  // Define a helper function for DFS
  function dfs(node) {
    // If the node is null, return immediately
    if (!node) return;
    // Recursively traverse the left subtree
    dfs(node.left);
    // Check if the node's value is within the range and add it to the sum
    if (node.val >= low && node.val <= high) sum += node.val;
    // Recursively traverse the right subtree
    dfs(node.right);
  }
  // Perform DFS from the root node
  dfs(root);
  // Return the calculated sum
  return sum;
}

function minAreaRect(points) {
    // Create a set to store the points for efficient lookups
    let pointSet = new Set();
    for (let point of points) {
        pointSet.add(point.join(','));
    }

    let minArea = Infinity;
    for (let i = 0; i < points.length; i++) {
        for (let j = i + 1; j < points.length; j++) {
            // Check if the points form a diagonal of a rectangle
            let [x1, y1] = points[i];
            let [x2, y2] = points[j];
            if (x1 === x2 || y1 === y2) continue;
            // Check if the other two points of the rectangle exist
            if (pointSet.has([x1, y2].join(',')) && pointSet.has([x2, y1].join(','))) {
                // Calculate the area of the rectangle
                let area = Math.abs(x2 - x1) * Math.abs(y2 - y1);
                // Update the minimum area
                minArea = Math.min(minArea, area);
            }
        }
    }
    // Return the minimum area or 0 if no rectangle is found
    return minArea === Infinity ? 0 : minArea;
}

function validMountainArray(arr) {
  // check if array has less than 3 elements, it cannot be a mountain array
  if (arr.length < 3) return false;
  let i = 0;
  // find the first element that is greater than the previous one
  while (i < arr.length - 1 && arr[i] < arr[i + 1]) i++;
  // if we are at the end or at the beginning, it's not a mountain array
  if (i === 0 || i === arr.length - 1) return false;
  // check if the rest of the array is decreasing
  while (i < arr.length - 1) {
    // if we find an element that is not less than the previous one, it's not a mountain array
    if (arr[i] <= arr[i + 1]) return false;
    i++;
  }
  // if we passed all checks, it's a mountain array
  return true;
}

