    result.push(left); 
    return result;
}

function distinctSubseqII(s) {
    const MOD = 1e9 + 7;
    const n = s.length;
    let dp = new Array(n + 1).fill(0);
    dp[0] = 1;
    let last = {};
    for (let i = 1; i <= n; i++) {
        // calculate the total number of subsequences ending at i
        dp[i] = (dp[i - 1] * 2) % MOD;
        // subtract the number of subsequences that end with the same character as the current character
        if (last[s[i - 1]]) {
            // if the character has been seen before, subtract the number of subsequences ending at the previous occurrence
            dp[i] = (dp[i] - dp[last[s[i - 1]] - 1] + MOD) % MOD;
        }
        // update the last occurrence of the current character
        last[s[i - 1]] = i;
    }
    // the total number of distinct non-empty subsequences is dp[n] - 1 (excluding the empty string)
    return (dp[n] - 1 + MOD) % MOD;
}

function minIncrementForUnique(nums) {
