}

function validateStackSequences(pushed, popped) {
  // Initialize an empty stack to simulate the push and pop operations
  let stack = [];
  let popIndex = 0;
  // Iterate through the pushed array
  for (let i = 0; i < pushed.length; i++) {
    // Push the current element onto the stack
    stack.push(pushed[i]);
    // While the stack is not empty and the top of the stack matches the next expected popped element
    while (stack.length > 0 && stack[stack.length - 1] === popped[popIndex]) {
      // Pop the top element from the stack
      stack.pop();
      // Move to the next expected popped element
      popIndex++;
    }
  }
  // If the stack is empty, it means we have successfully simulated the push and pop operations
  return stack.length === 0;
}

function shortestSuperstring(words) {
  const n = words.length;
  const overlap = Array(n).fill(0).map(() => Array(n).fill(0));
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (i === j) continue;
      for (let k = Math.min(words[i].length, words[j].length); k > 0; k--) {
        // check if the suffix of words[i] matches the prefix of words[j]
        if (words[i].slice(-k) === words[j].slice(0, k)) {
          overlap[i][j] = k;
          break;
        }
      }
    }
  }

  const dp = Array(1 << n).fill(null).map(() => Array(n).fill(null));
  const parent = Array(1 << n).fill(null).map(() => Array(n).fill(null));
  for (let i = 0; i < n; i++) {
    dp[1 << i][i] = words[i];
  }

  for (let mask = 1; mask < (1 << n); mask++) {
    for (let i = 0; i < n; i++) {
      if (((mask >> i) & 1) === 0) continue;
      const prevMask = mask ^ (1 << i);
      for (let j = 0; j < n; j++) {
        if (((prevMask >> j) & 1) === 0) continue;
        if (dp[prevMask][j] === null) continue;
        const newStr = dp[prevMask][j] + words[i].slice(overlap[j][i]);
        if (dp[mask][i] === null || newStr.length < dp[mask][i].length) {
          // update dp[mask][i] with the shorter string
          dp[mask][i] = newStr;
          parent[mask][i] = j;
        }
      }
    }
  }

  let minLen = Infinity;
  let minStr = null;
  let minMask = (1 << n) - 1;
  for (let i = 0; i < n; i++) {
    if (dp[minMask][i] !== null && dp[minMask][i].length < minLen) {
      minLen = dp[minMask][i].length;
      minStr = dp[minMask][i];
    }
  }
  return minStr;
}

