    tokens.sort((a, b) => a - b);
    let score = 0, maxScore = 0, left = 0, right = tokens.length - 1;
    // Use two pointers to consider the smallest and largest tokens
    while (left <= right) {
        // If the power is sufficient to play the smallest token face-up, play it
        if (tokens[left] <= power) {
            power -= tokens[left];
            score++;
            left++;
            // Update the maximum score
            maxScore = Math.max(maxScore, score);
        } 
        // If the power is not sufficient, play the largest token face-down to gain power
        else if (score > 0) {
            power += tokens[right];
            score--;
            right--;
        } 
        // If neither of the above conditions is met, break the loop
        else {
            break;
        }
    }
    return maxScore;
}

