function permute(arr, left, right, callback) {
    if (left === right) {
        callback(arr.slice());
    } else {
        for (let i = left; i <= right; i++) {
            // Swap elements at left and i indices
            swap(arr, left, i);
            // Recursively generate permutations for the remaining elements
            permute(arr, left + 1, right, callback);
            // Backtrack by swapping the elements back
            swap(arr, left, i);
        }
    }
}

