      temp[parseInt(diff) + rod] = Math.max(temp[parseInt(diff) + rod] || -Infinity, dp[diff]);
      temp[Math.abs(parseInt(diff) - rod)] = Math.max(temp[Math.abs(parseInt(diff) - rod)] || -Infinity, dp[diff] + Math.min(parseInt(diff), rod));
