    if (!root) return true;

    let queue = [root];
    let hasNull = false;

    // Perform BFS traversal
    while (queue.length) {
        let node = queue.shift();
        // If we've seen a null node before, all subsequent nodes must be null
        if (node === null) {
            hasNull = true; 
        } else {
            // If we've seen a null node before and encounter a non-null node, return false
            if (hasNull) return false;
            // Add children to the queue
            queue.push(node.left);
            queue.push(node.right);
        }
    }

    return true;
}

function maxWidthRamp(nums) {
