  let stack = [];
  for (let i = 0; i < nums.length; i++) {
    // If stack is empty or current element is smaller than the top of the stack, push the index to the stack
    if (stack.length === 0 || nums[i] < nums[stack[stack.length - 1]]) {
      stack.push(i);
    }
  }
  let maxWidth = 0;
  for (let j = nums.length - 1; j >= 0; j--) {
    // While stack is not empty and current element is greater than or equal to the top of the stack, update the maximum width
    while (stack.length > 0 && nums[j] >= nums[stack[stack.length - 1]]) {
      // Calculate the width of the current ramp and update the maximum width
      maxWidth = Math.max(maxWidth, j - stack.pop());
    }
  }
  return maxWidth;
}

function leastOpsExpressTarget(x, target) {
