          if (smallest === i) break;
          [this.a[i], this.a[smallest]] = [this.a[smallest], this.a[i]];
          i = smallest;
        }
      }
      return top;
    }
    get size() { return this.a.length; }
  }

  const heap = new MinHeap();
  heap.push([0, target]);
  const visited = new Set();
  while (heap.size > 0) {
    const [c, t] = heap.pop();
    if (t === 0) return c - 1;
    if (visited.has(t)) continue;
