        // If the node's value is different from the expected value, return false
        if (node.val !== value) return false;
        // Recursively check the left and right children
        return dfs(node.left, value) && dfs(node.right, value);
    }
    // Start the DFS from the root node with its own value
    return dfs(root, root.val);
}

function spellchecker(wordlist, queries) {
    var wordSet = new Set(wordlist); // store original words
    var lowerCaseMap = {}; // store lower case words
    var vowelMap = {}; // store vowel ignored words
    for (var word of wordlist) {
        var lowerCaseWord = word.toLowerCase(); // convert to lower case
        if (!(lowerCaseWord in lowerCaseMap)) {
            lowerCaseMap[lowerCaseWord] = word; // store lower case word
        }
        var vowelIgnoredWord = lowerCaseWord.replace(/a/g, '*').replace(/e/g, '*').replace(/i/g, '*').replace(/o/g, '*').replace(/u/g, '*'); // ignore vowels
        if (!(vowelIgnoredWord in vowelMap)) {
            vowelMap[vowelIgnoredWord] = word; // store vowel ignored word
        }
    }
    var result = [];
    for (var query of queries) {
        if (wordSet.has(query)) { // exact match
            result.push(query);
        } else {
            var lowerCaseQuery = query.toLowerCase(); // convert to lower case
            if (lowerCaseQuery in lowerCaseMap) { // lower case match
                result.push(lowerCaseMap[lowerCaseQuery]);
            } else {
                var vowelIgnoredQuery = lowerCaseQuery.replace(/a/g, '*').replace(/e/g, '*').replace(/i/g, '*').replace(/o/g, '*').replace(/u/g, '*'); // ignore vowels
                if (vowelIgnoredQuery in vowelMap) { // vowel ignored match
                    result.push(vowelMap[vowelIgnoredQuery]);
                } else {
                    result.push(""); // no match
                }
            }
        }
    }
    return result;
}

function numsSameConsecDiff(n, k) {
