}

function backtrack(result, currentNumber, lastDigit, n, k) {
  // if the current number has the required length, add it to the result
  if (n === 1) {
    result.push(currentNumber);
    return;
  }
  // calculate the next possible digits
  var nextDigit1 = lastDigit + k;
  var nextDigit2 = lastDigit - k;
  // check if the next possible digits are valid (0-9)
  if (nextDigit1 >= 0 && nextDigit1 <= 9) {
    // recursively call the backtrack function with the next possible digit
    backtrack(result, currentNumber * 10 + nextDigit1, nextDigit1, n - 1, k);
  }
  // only consider the second possible digit if it's different from the first one
  if (k !== 0 && nextDigit2 >= 0 && nextDigit2 <= 9) {
    // recursively call the backtrack function with the next possible digit
    backtrack(result, currentNumber * 10 + nextDigit2, nextDigit2, n - 1, k);
  }
}

function minCameraCover(root) {
    let result = 0;
    // MAIN LOGIC: if a node is null, it's covered, if it's not null but has no children, it's not covered, if it's not null and has children, it's covered if any of its children are covered
    function dfs(node) {
        if (!node) return 0; // 0: covered, no camera
        let left = dfs(node.left);
        let right = dfs(node.right);
        if (left === -1 || right === -1) { // if any child is not covered, install a camera
            result++;
            return 1; // 1: has camera
        }
        if (left === 1 || right === 1) return 0; // if any child has a camera, it's covered
        return -1; // if no child has a camera and it's not null, it's not covered
    }
    // if the root is not covered, install a camera
    if (dfs(root) === -1) result++;
    return result;
}

function flipMatchVoyage(root, voyage) {
