function pancakeSort(arr) {
    var result = [];
    for (var currSize = arr.length; currSize > 0; currSize--) {
        // find the index of the maximum element in the unsorted part of the array
        var maxIndex = 0;
        var maxValue = arr[0];
        for (var i = 1; i < currSize; i++) {
            if (arr[i] > maxValue) {
                maxIndex = i;
                maxValue = arr[i];
            }
        }
        // if the maximum element is not at the end of the unsorted part, flip it to the beginning
        if (maxIndex !== currSize - 1) {
            if (maxIndex !== 0) {
                // flip the maximum element to the beginning
                result.push(maxIndex + 1);
                arr = arr.slice(0, maxIndex + 1).reverse().concat(arr.slice(maxIndex + 1));
            }
            // flip the maximum element to the end of the unsorted part
            result.push(currSize);
            arr = arr.slice(0, currSize).reverse().concat(arr.slice(currSize));
        }
    }
    return result;
}

function kClosest(points, k) {
