            stack.push(i);
        }
        return result;
    }
    const idx = arr.map((v, i) => i);
    const ascIndices = idx.slice().sort((a, b) => arr[a] - arr[b] || a - b);
    const descIndices = idx.slice().sort((a, b) => arr[b] - arr[a] || a - b);
    const nextHigher = makeJumps(ascIndices);
    const nextLower = makeJumps(descIndices);
    const higher = new Array(n).fill(false);
    const lower = new Array(n).fill(false);
    higher[n - 1] = true;
    lower[n - 1] = true;
    let count = 1;
    for (let i = n - 2; i >= 0; i--) {
        if (nextHigher[i] !== -1) higher[i] = lower[nextHigher[i]];
