    let left = 0, right = this.map[key].length - 1;
    while (left <= right) {
        let mid = Math.floor((left + right) / 2);
        if (this.map[key][mid][1] <= timestamp) {
            // if the current value's timestamp is less than or equal to the given timestamp, move to the right half
            left = mid + 1;
        } else {
            // if the current value's timestamp is greater than the given timestamp, move to the left half
            right = mid - 1;
        }
    }
    // return the most recent value at or before the given timestamp
    return left > 0 ? this.map[key][left - 1][0] : "";
}

