function uniquePathsIII(grid) {
    let rows = grid.length, cols = grid[0].length;
    let nonObstacles = 0, startRow = 0, startCol = 0;
    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            if (grid[i][j] !== -1) nonObstacles++;
            if (grid[i][j] === 1) { startRow = i; startCol = j; }
        }
    }
    let directions = [[0, 1], [0, -1], [1, 0], [-1, 0]];
    let result = 0;
    function backtrack(row, col, steps) {
        for (let i = 0; i < 4; i++) {
            let newRow = row + directions[i][0], newCol = col + directions[i][1];
            if (newRow >= 0 && newRow < rows && newCol >= 0 && newCol < cols && grid[newRow][newCol] !== -1 && grid[newRow][newCol] !== -2) {
                if (grid[newRow][newCol] === 2) {
                    if (steps + 1 === nonObstacles) result++;
                    continue;
                }
                let temp = grid[newRow][newCol];
                grid[newRow][newCol] = -2;
                backtrack(newRow, newCol, steps + 1);
                grid[newRow][newCol] = temp;
            }
        }
    }
    const startTemp = grid[startRow][startCol];
    grid[startRow][startCol] = -2;
    backtrack(startRow, startCol, 1);
    grid[startRow][startCol] = startTemp;
    return result;
}

function countAndTriples(nums) {
  let count = 0; // Initialize count variable to store the number of AND triples
  // The algorithm solution is already optimal with a time complexity of O(n^3) as we need to check all possible triples
  for (let i = 0; i < nums.length; i++) { // Iterate over the array for the first index
    for (let j = 0; j < nums.length; j++) { // Iterate over the array for the second index
      for (let k = 0; k < nums.length; k++) { // Iterate over the array for the third index
        if ((nums[i] & nums[j] & nums[k]) === 0) { // Check if the bitwise AND of the three numbers is equal to zero
          count++; // If the condition is met, increment the count
        }
      }
    }
  }
  return count; // Return the total count of AND triples
}

function sumEvenAfterQueries(nums, queries) {
    // initialize the sum of even numbers
    let evenSum = 0;
    // calculate the initial sum of even numbers
    for (let num of nums) {
        // check if the number is even
        if (num % 2 === 0) {
            // add the number to the sum
            evenSum += num;
        }
    }
    let result = [];
    // iterate over each query
    for (let query of queries) {
        // get the value and index of the query
        let val = query[0], index = query[1];
        // check if the number at the index is even
        if (nums[index] % 2 === 0) {
            // subtract the number from the sum
            evenSum -= nums[index];
        }
        // update the number at the index
        nums[index] += val;
        // check if the updated number is even
        if (nums[index] % 2 === 0) {
            // add the updated number to the sum
            evenSum += nums[index];
        }
        // add the current sum to the result
        result.push(evenSum);
    }
    return result;
}

function strWithout3a3b(a, b) {
