function mincostTickets(days, costs) {
    let lastDay = days[days.length - 1];
    let travelDays = new Set(days);
    let dp = new Array(lastDay + 1).fill(0);
    // Initialize dp array with infinity for all days that require travel
    for (let day of travelDays) {
        dp[day] = Infinity;
    }
    // Fill dp array using dynamic programming
    for (let day = 1; day <= lastDay; day++) {
        // If the current day does not require travel, the cost is the same as the previous day
        if (!travelDays.has(day)) {
            dp[day] = dp[day - 1];
        } else {
            // Calculate the minimum cost for the current day by considering all possible passes
            dp[day] = Math.min(
                // 1-day pass
                dp[day - 1] + costs[0],
                // 7-day pass
                dp[Math.max(0, day - 7)] + costs[1],
                // 30-day pass
                dp[Math.max(0, day - 30)] + costs[2]
            );
        }
    }
    // The minimum cost for the entire travel plan is stored in the last element of the dp array
    return dp[lastDay];
}

function intervalIntersection(firstList, secondList) {
    let result = [];
    let i = 0, j = 0;
    // Loop through both lists until one of them is exhausted
    while (i < firstList.length && j < secondList.length) {
        // Calculate the intersection of the current intervals
        let start = Math.max(firstList[i][0], secondList[j][0]);
        let end = Math.min(firstList[i][1], secondList[j][1]);
        // If the intersection is valid, add it to the result
        if (start <= end) result.push([start, end]);
        // Move the pointer of the interval with the smaller end
        if (firstList[i][1] < secondList[j][1]) i++;
        else j++;
    }
    return result;
}

function brokenCalc(startValue, target) {
    let operations = 0;
    // Continue the process until target is less than or equal to startValue
    while (target > startValue) {
        // If target is odd, we need to add 1 to make it even for division by 2
        if (target % 2 === 1) {
            target++;
            operations++;
        }
        // Divide target by 2 to reduce the difference between startValue and target
        target = target / 2;
        operations++;
    }
    // Add the difference between startValue and target to the operations count
    operations += startValue - target;
    return operations;
}

function smallestFromLeaf(root) {
    // define the result variable to store the lexicographically smallest string
    let result = "~";

    // define a helper function for depth-first search
    function dfs(node, path) {
        // if the node is null, return immediately
        if (!node) return;

        // append the current node's value to the path
        path = String.fromCharCode('a'.charCodeAt(0) + node.val) + path;

        // if the node is a leaf, update the result if the current path is lexicographically smaller
        if (!node.left && !node.right) result = result < path ? result : path;

        // recursively search the left and right subtrees
        dfs(node.left, path); // explore left subtree
        dfs(node.right, path); // explore right subtree
    }

    // start the depth-first search from the root
    dfs(root, "");

    // return the lexicographically smallest string
    return result;
}

function subarraysWithKDistinct(nums, k) {
    function atMostK(k) {
        let left = 0, count = 0;
        let map = {};
        // Initialize a hashmap to store the frequency of each number in the current window
        for (let right = 0; right < nums.length; right++) {
            // Increase the frequency of the current number
            map[nums[right]] = (map[nums[right]] || 0) + 1;
            // While there are more than k distinct numbers in the window, shrink the window
            while (Object.keys(map).length > k) {
                // Decrease the frequency of the number at the left of the window
                map[nums[left]]--;
                // If the frequency of the number at the left of the window is 0, remove it from the hashmap
                if (map[nums[left]] === 0) delete map[nums[left]];
                // Move the left pointer to the right
                left++;
            }
            // Increase the count of subarrays with at most k distinct numbers
            count += right - left + 1;
        }
        return count;
    }
    // The number of subarrays with exactly k distinct numbers is the number of subarrays with at most k distinct numbers minus the number of subarrays with at most k-1 distinct numbers
    return atMostK(k) - atMostK(k - 1);
}

function addToArrayForm(num, k) {
