function isCousins(root, x, y) {
    // Perform a level order traversal to find the depth and parent of each node
    let queue = [{ node: root, depth: 0, parent: null }];
    let xInfo = null, yInfo = null;
    while (queue.length > 0) {
        // Dequeue the next node
        let { node, depth, parent } = queue.shift();
        // Check if this is the node we're looking for
        if (node.val === x) xInfo = { depth, parent };
        if (node.val === y) yInfo = { depth, parent };
        // If we've found both nodes, break out of the loop
        if (xInfo && yInfo) break;
        // Enqueue the children of the current node
        if (node.left) queue.push({ node: node.left, depth: depth + 1, parent: node.val });
        if (node.right) queue.push({ node: node.right, depth: depth + 1, parent: node.val });
    }
    // Check if the nodes are cousins
    return xInfo.depth === yInfo.depth && xInfo.parent !== yInfo.parent;
}

function verticalTraversal(root) {
    if (!root) return [];
    // Initialize a hash map to store the nodes at each column index
    let columnTable = {};
    let minColumn = 0, maxColumn = 0;
    let queue = [[root, 0]];

    while (queue.length > 0) {
        let size = queue.length;
        let temp = {};
        // Process all nodes at the current level
        for (let i = 0; i < size; i++) {
            let [node, column] = queue.shift();
            // Update the min and max column indices
            minColumn = Math.min(minColumn, column);
            maxColumn = Math.max(maxColumn, column);
            // Add the node to the temporary hash map
            if (!temp[column]) temp[column] = [];
            temp[column].push(node.val);
            // Add the children to the queue
            if (node.left) queue.push([node.left, column - 1]);
            if (node.right) queue.push([node.right, column + 1]);
        }
        // Add the nodes from the temporary hash map to the column table
        for (let column in temp) {
            if (!columnTable[column]) columnTable[column] = [];
            columnTable[column].push(...temp[column].sort((a, b) => a - b));
        }
    }
    // Create the result array
    let result = [];
    for (let i = minColumn; i <= maxColumn; i++) {
        result.push(columnTable[i]);
    }
    return result;
}

function equationsPossible(equations) {
    // Create a parent array for union-find
    let parent = new Array(26);
    for (let i = 0; i < 26; i++) {
        parent[i] = i;
    }

    // Union the variables that are equal
    for (let equation of equations) {
        // Check if the equation is of the form "xi==yi"
        if (equation[1] === '=') {
            // Find the parent of xi and yi
            let x = equation[0].charCodeAt(0) - 'a'.charCodeAt(0);
            let y = equation[3].charCodeAt(0) - 'a'.charCodeAt(0);
            // Union xi and yi
            parent[find(parent, x)] = find(parent, y);
        }
    }

    // Check if the variables that are not equal are in the same set
    for (let equation of equations) {
        // Check if the equation is of the form "xi!=yi"
        if (equation[1] === '!') {
            // Find the parent of xi and yi
            let x = equation[0].charCodeAt(0) - 'a'.charCodeAt(0);
            let y = equation[3].charCodeAt(0) - 'a'.charCodeAt(0);
            // If xi and yi are in the same set, return false
            if (find(parent, x) === find(parent, y)) {
                return false;
            }
        }
    }

    // If we have not returned false, then it is possible to assign integers to variable names
    return true;
}

// Helper function to find the parent of a variable
function find(parent, x) {
    // If x is the parent of itself, return x
    if (parent[x] === x) {
        return x;
    }
    // Otherwise, recursively find the parent of x
    return parent[x] = find(parent, parent[x]);
}

