function minKBitFlips(nums, k) {
    let n = nums.length;
    let flipTracker = new Array(n + 1).fill(0);
    let flips = 0;
    let currentFlips = 0;
    for (let i = 0; i < n; i++) {
        currentFlips += flipTracker[i];
        const isFlipped = currentFlips % 2 === 1;
        const currentBit = isFlipped ? 1 - nums[i] : nums[i];
        if (currentBit === 0) {
            if (i + k > n) return -1;
            flips++;
            currentFlips++;
            flipTracker[i + k] -= 1;
        }
    }
    return flips;
}

function numSquarefulPerms(nums) {
  nums.sort((a, b) => a - b);
  const n = nums.length;
  const used = new Array(n).fill(false);
  let count = 0;
  function isPerfectSquare(num) {
    const sqrt = Math.sqrt(num);
    return sqrt === Math.floor(sqrt);
  }
  function backtrack(perm) {
    if (perm.length === n) { count++; return; }
    for (let i = 0; i < n; i++) {
      if (used[i]) continue;
      if (i > 0 && nums[i] === nums[i - 1] && !used[i - 1]) continue;
      if (perm.length > 0 && !isPerfectSquare(perm[perm.length - 1] + nums[i])) continue;
      used[i] = true;
      perm.push(nums[i]);
      backtrack(perm);
      perm.pop();
      used[i] = false;
    }
  }
  backtrack([]);
  return count;
}

function findJudge(n, trust) {
    // Initialize an array to store the trust score for each person
    let trustScore = new Array(n + 1).fill(0);
    // Iterate over each trust relationship
    for (let i = 0; i < trust.length; i++) {
        // Decrease the trust score of the person who trusts
        trustScore[trust[i][0]]--;
        // Increase the trust score of the person who is trusted
        trustScore[trust[i][1]]++;
    }
    // Iterate over each person to find the town judge
    for (let i = 1; i <= n; i++) {
        // If a person has a trust score of n - 1, they are the town judge
        if (trustScore[i] === n - 1) {
            return i;
        }
    }
    // If no town judge is found, return -1
    return -1;
}

function insertIntoMaxTree(root, val) {
    if (!root) return { val: val, left: null, right: null };
    if (val > root.val) {
        return { val: val, left: root, right: null };
    }
    if (root.right && val > root.right.val) {
        root.right = { val: val, left: root.right, right: null };
    } else {
        root.right = insertIntoMaxTree(root.right, val);
    }
    return root;
}

function numRookCaptures(board) {
