function orangesRotting(grid) {
    // Get the number of rows and columns in the grid
    var rows = grid.length;
    var cols = grid[0].length;

    // Initialize variables to store the number of fresh oranges and the queue for BFS
    var freshOranges = 0;
    var queue = [];

    // Count the number of fresh oranges and add rotten oranges to the queue
    for (var i = 0; i < rows; i++) {
        for (var j = 0; j < cols; j++) {
            if (grid[i][j] === 1) {
                freshOranges++;
            } else if (grid[i][j] === 2) {
                queue.push([i, j]);
            }
        }
    }

    // Initialize the directions for 4-directional adjacency
    var directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];

    // Initialize the minutes counter
    var minutes = 0;

    // Perform BFS
    while (queue.length > 0 && freshOranges > 0) {
        // Increase the minutes counter
        minutes++;

        // Store the size of the current queue
        var size = queue.length;

        // Process all oranges in the current queue
        for (var i = 0; i < size; i++) {
            var current = queue.shift();

            // Check all adjacent cells
            for (var j = 0; j < 4; j++) {
                var x = current[0] + directions[j][0];
                var y = current[1] + directions[j][1];

                // Check if the adjacent cell is within the grid and is a fresh orange
                if (x >= 0 && x < rows && y >= 0 && y < cols && grid[x][y] === 1) {
                    // Mark the fresh orange as rotten
                    grid[x][y] = 2;

                    // Decrease the fresh oranges counter
                    freshOranges--;

                    // Add the newly rotten orange to the queue
                    queue.push([x, y]);
                }
            }
        }
    }

    // If there are still fresh oranges left, return -1
    if (freshOranges > 0) {
        return -1;
    }

    // Return the minimum number of minutes
    return minutes;
}

function isValid(s) {
    let stack = []; // initialize an empty stack
    for (let i = 0; i < s.length; i++) { // iterate over the string
        // if the current character is 'c' and the stack has at least two elements, and the top two elements are 'a' and 'b', pop them
        if (s[i] === 'c' && stack.length >= 2 && stack[stack.length - 1] === 'b' && stack[stack.length - 2] === 'a') {
            stack.pop(); stack.pop();
        } else { // otherwise, push the current character to the stack
            stack.push(s[i]);
        }
    }
    // if the stack is empty after processing the entire string, it is valid
    return stack.length === 0;
}

function findCommonCharacters(words) {
    // Initialize a hash map with the character frequencies of the first word
    let commonChars = {};
    for (let char of words[0]) {
        // Count the frequency of each character in the first word
        commonChars[char] = (commonChars[char] || 0) + 1;
    }

    // Iterate over the rest of the words
    for (let i = 1; i < words.length; i++) {
        let wordChars = {};
        for (let char of words[i]) {
            // Count the frequency of each character in the current word
            wordChars[char] = (wordChars[char] || 0) + 1;
        }

        // Update the commonChars hash map with the minimum frequency of each character
        for (let char in commonChars) {
            // Update the frequency of each character to be the minimum of the current frequency and the frequency in the current word
            commonChars[char] = Math.min(commonChars[char], wordChars[char] || 0);
        }
    }

    // Create the result array with the common characters and their frequencies
    let result = [];
    for (let char in commonChars) {
        // Add each common character to the result array as many times as its frequency
        for (let i = 0; i < commonChars[char]; i++) {
            result.push(char);
        }
    }

    return result;
}

function mergeStones(stones, k) {
    const n = stones.length;
    if ((n - 1) % (k - 1) !== 0) return -1;
    const prefixSum = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) prefixSum[i + 1] = prefixSum[i] + stones[i];
    const dp = new Array(n).fill(0).map(() => new Array(n).fill(Infinity));
    for (let i = 0; i < n; i++) dp[i][i] = 0;
    for (let length = 2; length <= n; length++) {
        for (let i = 0; i <= n - length; i++) {
            const j = i + length - 1;
            for (let x = i; x < j; x += k - 1) {
                dp[i][j] = Math.min(dp[i][j], dp[i][x] + dp[x + 1][j]);
            }
            if ((j - i) % (k - 1) === 0) {
                dp[i][j] += prefixSum[j + 1] - prefixSum[i];
            }
        }
    }
    return dp[0][n - 1];
}

function gridIllumination(n, lamps, queries) {
    // Create a set to store the lamp positions for efficient lookups
    let lampSet = new Set();
    for (let lamp of lamps) {
        lampSet.add(lamp.join(','));
    }

    // Create hash maps to store the count of lamps in each row, column, and diagonal
    let rowMap = new Array(n).fill(0);
    let colMap = new Array(n).fill(0);
    let diagMap1 = new Array(2 * n - 1).fill(0);
    let diagMap2 = new Array(2 * n - 1).fill(0);

    // Initialize the hash maps
    for (let lamp of lamps) {
        let row = lamp[0];
        let col = lamp[1];
        rowMap[row]++;
        colMap[col]++;
        diagMap1[row + col]++;
        diagMap2[row - col + n - 1]++;
    }

    // Create a result array to store the answers
    let result = new Array(queries.length).fill(0);

    // Iterate over the queries
    for (let i = 0; i < queries.length; i++) {
        let row = queries[i][0];
        let col = queries[i][1];

        // Check if the cell is illuminated
        if (rowMap[row] > 0 || colMap[col] > 0 || diagMap1[row + col] > 0 || diagMap2[row - col + n - 1] > 0) {
            result[i] = 1;
        }

        // Turn off the lamp at the query position and its adjacent lamps
        for (let r = Math.max(0, row - 1); r <= Math.min(n - 1, row + 1); r++) {
            for (let c = Math.max(0, col - 1); c <= Math.min(n - 1, col + 1); c++) {
                // Check if the lamp is turned on
                if (lampSet.has([r, c].join(','))) {
                    // Decrement the count of lamps in the corresponding row, column, and diagonals
                    rowMap[r]--;
                    colMap[c]--;
                    diagMap1[r + c]--;
                    diagMap2[r - c + n - 1]--;
                    // Remove the lamp from the set
                    lampSet.delete([r, c].join(','));
                }
            }
        }
    }

    return result;
}

function longestOnes(nums, k) {
    let maxConsecutiveOnes = 0;
    let left = 0; // left pointer of the sliding window
    let zerosInWindow = 0; // count of zeros in the current window
    for (let right = 0; right < nums.length; right++) { // right pointer of the sliding window
        // if the current element is 0, increment the count of zeros in the window
        if (nums[right] === 0) zerosInWindow++;
        // while the number of zeros in the window exceeds k, move the left pointer to the right
        while (zerosInWindow > k) {
            // if the leftmost element is 0, decrement the count of zeros in the window
            if (nums[left] === 0) zerosInWindow--;
            left++; // move the left pointer to the right
        }
        // update the maximum number of consecutive ones
        maxConsecutiveOnes = Math.max(maxConsecutiveOnes, right - left + 1);
    }
    return maxConsecutiveOnes;
}

function largestSumAfterKNegations(nums, k) {
  // sort the array in ascending order to prioritize negating smaller numbers
  nums.sort((a, b) => a - b);
  for (let i = 0; i < k; i++) {
    // negate the smallest number in the array
    nums[0] = -nums[0];
    // re-sort the array to maintain the smallest number at the front
    nums.sort((a, b) => a - b);
  }
  // calculate the sum of the modified array
  let sum = 0;
  for (let i = 0; i < nums.length; i++) {
    sum += nums[i];
  }
  return sum;
}

function clumsy(n) {
  const stack = [n];
  n--;
  let index = 0;
  while (n > 0) {
    if (index % 4 === 0) { stack.push(stack.pop() * n); }
    else if (index % 4 === 1) { stack.push(Math.trunc(stack.pop() / n)); }
    else if (index % 4 === 2) { stack.push(n); }
    else { stack.push(-n); }
    n--; index++;
  }
  return stack.reduce((a, b) => a + b, 0);
}

function minDominoRotations(tops, bottoms) {
    // Check if all dominoes can be made to have the same value on top or bottom
    function check(x) {
        // Count the number of rotations needed to make all dominoes have the same value on top
        let rotationsA = 0;
        // Count the number of rotations needed to make all dominoes have the same value on bottom
        let rotationsB = 0;
        for (let i = 0; i < tops.length; i++) {
            // If the current domino does not have the target value on top or bottom, increment the rotation count
            if (tops[i] !== x && bottoms[i] !== x) return -1;
            // If the current domino has the target value on bottom, increment the rotation count for top
            if (tops[i] !== x) rotationsA++;
            // If the current domino has the target value on top, increment the rotation count for bottom
            if (bottoms[i] !== x) rotationsB++;
        }
        // Return the minimum number of rotations needed
        return Math.min(rotationsA, rotationsB);
    }

    // Check for the first domino's values
    let rotations = check(tops[0]);
    // If the first domino's values do not work, check the second domino's values
    if (rotations === -1 || rotations === tops.length) rotations = check(bottoms[0]);
    return rotations;
}

function numDupDigitsAtMostN(n) {
    // calculate total numbers without repeated digits
    let count = 0;
    let i = 1;
    while (i <= n) {
        // check if number has repeated digits
        let num = i;
        let seen = new Set();
        let hasRepeated = false;
        while (num > 0) {
            let digit = num % 10;
            if (seen.has(digit)) {
                hasRepeated = true;
                break;
            }
            seen.add(digit);
            num = Math.floor(num / 10);
        }
        if (!hasRepeated) {
            count++;
        }
        i++;
    }
    // return total numbers minus numbers without repeated digits
    return n - count;
}

function findComplement(n) {
    // calculate the number of bits in n
    let numBits = Math.floor(Math.log2(n)) + 1;
    // create a mask with all bits set to 1, with the same number of bits as n
    let mask = (1 << numBits) - 1;
    // flip all the bits in n using the mask
    return ~n & mask;
}

function canThreePartsEqualSum(arr) {
  let totalSum = 0; // calculate the total sum of the array
  for (let i = 0; i < arr.length; i++) {
    totalSum += arr[i]; // add each element to the total sum
  }
  if (totalSum % 3 !== 0) return false; // if the total sum is not divisible by 3, return false
  let targetSum = totalSum / 3; // calculate the target sum for each part
  let count = 0; // count the number of parts with the target sum
  let currentSum = 0; // current sum of the part
  for (let i = 0; i < arr.length; i++) {
    currentSum += arr[i]; // add each element to the current sum
    if (currentSum === targetSum) { // if the current sum equals the target sum
      count++; // increment the count
      currentSum = 0; // reset the current sum
    }
  }
  return count >= 3; // return true if we have at least 3 parts with the target sum
}

function numPairsDivisibleBy60(time) {
