  }
  return count;
}

function shipWithinDays(weights, days) {
    // define the search range for the ship capacity
    let left = Math.max(...weights), right = weights.reduce((a, b) => a + b);

    // perform binary search to find the minimum capacity
    while (left < right) {
        // calculate the mid capacity
        let mid = Math.floor((left + right) / 2);

        // calculate the number of days required for the mid capacity
        let need = 1, cur = 0;
        for (let weight of weights) {
            // if the current weight exceeds the mid capacity, start a new day
            if (cur + weight > mid) {
                need++;
                cur = 0;
            }
            // add the current weight to the current day
            cur += weight;
        }

        // if the number of days required is less than or equal to the given days, update the right boundary
        if (need <= days) {
            right = mid;
        } 
        // otherwise, update the left boundary
        else {
            left = mid + 1;
        }
    }

    // the minimum capacity is the left boundary
    return left;
}

function bstFromPreorder(preorder) {
    function TreeNode(val, left, right) {
        this.val = (val === undefined ? 0 : val);
        this.left = (left === undefined ? null : left);
        this.right = (right === undefined ? null : right);
    }

    if (preorder.length === 0) return null;
    let root = new TreeNode(preorder[0]);
    let stack = [root];
    for (let i = 1; i < preorder.length; i++) {
        // if current node's value is less than the top of the stack, create a left child
        if (preorder[i] < stack[stack.length - 1].val) {
            stack[stack.length - 1].left = new TreeNode(preorder[i]);
            stack.push(stack[stack.length - 1].left);
        } else {
            // backtrack to the correct parent node
            let last = null;
            while (stack.length > 0 && stack[stack.length - 1].val < preorder[i]) {
                last = stack.pop();
            }
            // create a right child
            last.right = new TreeNode(preorder[i]);
            stack.push(last.right);
        }
    }
    return root;
}

