  for (let j = 1; j < values.length; j++) {
    // Update the maximum score if the current score plus the value of the current spot minus the distance is greater
    maxScore = Math.max(maxScore, currentScore + values[j] - j);
    // Update the current score by subtracting the distance and adding the value of the current spot
    currentScore = Math.max(currentScore, values[j] + j);
  }
  // Return the maximum score found
  return maxScore;
}

function nextLargerNodes(head) {
    let result = [];
    let stack = [];
    let index = 0;
    while (head) {
        while (stack.length > 0 && head.val > stack[stack.length - 1].val) {
            let popped = stack.pop();
            while (result.length <= popped.index) result.push(0);
            result[popped.index] = head.val;
        }
        stack.push({ index: index, val: head.val });
        head = head.next;
        index++;
    }
    while (result.length < index) result.push(0);
    return result;
}

function numEnclaves(grid) {
  // Define the directions for DFS
  const directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
  // Get the number of rows and columns in the grid
  const rows = grid.length, cols = grid[0].length;
  // Function to perform DFS from a given cell
  function dfs(row, col) {
    // Check if the cell is within the grid boundaries and is a land cell
    if (row < 0 || row >= rows || col < 0 || col >= cols || grid[row][col] === 0) return;
    // Mark the cell as visited by setting it to 0
    grid[row][col] = 0;
    // Perform DFS on the adjacent cells
    for (const [dr, dc] of directions) dfs(row + dr, col + dc);
  }
  // Perform DFS on the land cells on the boundary
  for (let i = 0; i < rows; i++) {
    // Check the cells on the left and right boundaries
    dfs(i, 0); dfs(i, cols - 1);
  }
  for (let j = 0; j < cols; j++) {
    // Check the cells on the top and bottom boundaries
    dfs(0, j); dfs(rows - 1, j);
  }
  // Count the number of land cells that are not reachable from the boundary
  let count = 0;
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      // If the cell is a land cell, increment the count
      if (grid[i][j] === 1) count++;
    }
  }
  return count;
}

function removeOuterParentheses(s) {
  let result = '', temp = '', count = 0; 
  // iterate over the string and count the parentheses to identify primitive strings
  for (let i = 0; i < s.length; i++) {
    temp += s[i];
    // if the current character is an opening parenthesis, increment the count
    if (s[i] === '(') count++;
    // if the current character is a closing parenthesis, decrement the count
    else count--;
    // if the count is zero, it means we have found a primitive string
    if (count === 0) {
      // remove the outermost parentheses and add the primitive string to the result
      result += temp.slice(1, temp.length - 1);
      temp = '';
    }
  }
  return result;
}

function videoStitching(clips, time) {
    // Sort the clips based on their start time
    clips.sort((a, b) => a[0] - b[0]);
    let count = 0, currEnd = 0, farEnd = 0, i = 0;
    // Traverse through the sorted clips and update the current end and far end
    while (i < clips.length && clips[i][0] <= currEnd) {
        // Update the far end to be the maximum of the current far end and the end of the current clip
        while (i < clips.length && clips[i][0] <= currEnd) {
            farEnd = Math.max(farEnd, clips[i][1]);
            i++;
        }
        // If the current end is equal to the time, return the count
        if (currEnd == time) return count;
        // Update the current end to be the far end and increment the count
        currEnd = farEnd;
        count++;
    }
    // If the current end is less than the time, return -1
    return currEnd < time ? -1 : count;
}

function divisorGame(n) {
