function sumRootToLeaf(root) {
    function dfs(node, currentNumber) {
        // if the node is null, return 0
        if (!node) return 0;
        // update the current number by shifting the bits to the left and adding the node's value
        currentNumber = (currentNumber << 1) | node.val;
        // if the node is a leaf, return the current number
        if (!node.left && !node.right) return currentNumber;
        // recursively call dfs on the left and right children
        return dfs(node.left, currentNumber) + dfs(node.right, currentNumber);
    }
    // call dfs on the root node with an initial current number of 0
    return dfs(root, 0);
}

function maxAncestorDiff(root) {
    let maxDiff = 0;
    // Traverse the tree and for each node, calculate the difference with its ancestors
    function dfs(node, minVal, maxVal) {
        if (!node) return;
        // Update maxDiff with the maximum difference between the current node's value and its ancestors
        maxDiff = Math.max(maxDiff, Math.abs(maxVal - node.val), Math.abs(node.val - minVal));
        // Recursively traverse the left and right subtrees, updating minVal and maxVal
        dfs(node.left, Math.min(minVal, node.val), Math.max(maxVal, node.val));
        dfs(node.right, Math.min(minVal, node.val), Math.max(maxVal, node.val));
    }
    dfs(root, root.val, root.val);
    return maxDiff;
}

function camelMatch(queries, pattern) {
    function match(query) {
        let i = 0, j = 0; // two pointers for query and pattern
        while (i < query.length) {
            if (j < pattern.length && query[i] === pattern[j]) { // if current characters in query and pattern match
                j++; // move to the next character in pattern
            } else if (query[i] >= 'A' && query[i] <= 'Z') { // if current character in query is uppercase and does not match the current character in pattern
                return false; // query does not match pattern
            }
            i++; // move to the next character in query
        }
        return j === pattern.length; // query matches pattern if all characters in pattern have been matched
    }
    return queries.map(match); // apply match function to each query
}

function longestArithmeticSubsequence(nums) {
    let maxLength = 0;
    let sequenceLengths = {};
    // Create a hash table to store the length of the longest arithmetic subsequence ending at each position
    for (let i = 0; i < nums.length; i++) {
        for (let j = 0; j < i; j++) {
            // Calculate the difference between the current and previous numbers
            let difference = nums[i] - nums[j];
            // If the difference is already in the hash table, update the length of the subsequence
            if (difference in sequenceLengths && j in sequenceLengths[difference]) {
                sequenceLengths[difference][i] = sequenceLengths[difference][j] + 1;
            } else {
                // If the difference is not in the hash table, add it with a length of 2
                if (!(difference in sequenceLengths)) {
                    sequenceLengths[difference] = {};
                }
                sequenceLengths[difference][i] = 2;
            }
            // Update the maximum length found so far
            maxLength = Math.max(maxLength, sequenceLengths[difference][i]);
        }
    }
    // The longest arithmetic subsequence has a length of at least 2, so return the maximum length found
    return maxLength;
}

function recoverFromPreorder(traversal) {
