        let dashes = 0;
        while (index < traversal.length && traversal[index] === '-') { dashes++; index++; }
        if (dashes !== depth) { index = start; return null; }
        let value = 0;
        while (index < traversal.length && traversal[index] !== '-') {
            value = value * 10 + (traversal[index++] - '0');
        }
        let node = { val: value, left: null, right: null };
        node.left = dfs(depth + 1);
        node.right = dfs(depth + 1);
        return node;
    }
    return dfs(0);
}

function twoCitySchedCost(costs) {
