function numMovesStones(a, b, c) {
  // Sort the stones in ascending order to determine the positions
  let stones = [a, b, c].sort((x, y) => x - y);
  let left = stones[0], middle = stones[1], right = stones[2];

  // Check if the stones are already consecutive
  if (right - left == 2) return [0, 0];

  // Check if we can move the left or right stone to make the stones consecutive
  let minMoves = 1;
  let maxMoves = right - left - 2;

  // Check if we can move the middle stone to make the stones consecutive
  if (middle - left > 2 && right - middle > 2) minMoves = 2;

  return [minMoves, maxMoves];
}

function maxSumTwoNoOverlap(nums, firstLen, secondLen) {
    // Calculate prefix sum to efficiently calculate subarray sums
    let prefixSum = new Array(nums.length + 1).fill(0);
    for (let i = 0; i < nums.length; i++) {
        prefixSum[i + 1] = prefixSum[i] + nums[i];
    }

    // Initialize maximum sum
    let maxSum = -Infinity;

    // Iterate over all possible subarrays of length firstLen
    for (let i = 0; i <= nums.length - firstLen; i++) {
        // Calculate sum of current subarray
        let sum1 = prefixSum[i + firstLen] - prefixSum[i];

        // Iterate over all possible subarrays of length secondLen that do not overlap with the current subarray
        for (let j = 0; j <= nums.length - secondLen; j++) {
            // Check if subarrays do not overlap
            if (j + secondLen <= i || j >= i + firstLen) {
                // Calculate sum of current subarray
                let sum2 = prefixSum[j + secondLen] - prefixSum[j];

                // Update maximum sum
                maxSum = Math.max(maxSum, sum1 + sum2);
            }
        }
    }

    // The algorithm solution is already optimal, with a time complexity of O(n^2) due to the nested loops
    return maxSum;
}

function StreamChecker(words) {
    // Create a Trie data structure to store the given words
    this.trie = {};
    for (let word of words) {
        let node = this.trie;
        // Insert each word into the Trie in reverse order
        for (let i = word.length - 1; i >= 0; i--) {
            if (!node[word[i]]) node[word[i]] = {};
            node = node[word[i]];
        }
        // Mark the end of each word in the Trie
        node.end = true;
    }
    // Initialize the stream of characters
    this.stream = '';
}

StreamChecker.prototype.query = function(letter) {
    // Append the new character to the stream
    this.stream += letter;
    // Initialize a pointer to the root of the Trie
    let node = this.trie;
    // Iterate over the stream from the end to the beginning
    for (let i = this.stream.length - 1; i >= 0; i--) {
        // If the current character is not in the Trie, return false
        if (!node[this.stream[i]]) return false;
        // Move to the next node in the Trie
        node = node[this.stream[i]];
        // If we reach the end of a word in the Trie, return true
        if (node.end) return true;
    }
    // If we don't find a match, return false
    return false;
}

function colorBorder(grid, row, col, color) {
    // Get the number of rows and columns in the grid
    const rows = grid.length;
    const cols = grid[0].length;

    // Get the original color of the connected component
    const originalColor = grid[row][col];

    // Create a visited set to keep track of visited cells
    const visited = new Set();

    // Create a set to store the border cells
    const borderCells = new Set();

    // Define the directions for DFS
    const directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];

    // Perform DFS to find the border cells
    function dfs(r, c) {
        // If the cell is out of bounds or has a different color, return
        if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] !== originalColor) {
            return;
        }

        // If the cell is on the border, add it to the border cells set
        if (r === 0 || r === rows - 1 || c === 0 || c === cols - 1 || 
            grid[r - 1][c] !== originalColor || grid[r + 1][c] !== originalColor || 
            grid[r][c - 1] !== originalColor || grid[r][c + 1] !== originalColor) {
            borderCells.add(`${r},${c}`);
        }

        // Mark the cell as visited
        visited.add(`${r},${c}`);

        // Perform DFS on the neighboring cells
        for (const [dr, dc] of directions) {
            const nr = r + dr;
            const nc = c + dc;
            if (!visited.has(`${nr},${nc}`)) {
                dfs(nr, nc);
            }
        }
    }

    // Perform DFS from the given cell
    dfs(row, col);

    // Color the border cells
    for (const cell of borderCells) {
        const [r, c] = cell.split(',').map(Number);
        grid[r][c] = color;
    }

    return grid;
}

function maxUncrossedLines(nums1, nums2) {
    // Initialize a 2D array to store the lengths of the longest common subsequences
    var dp = Array(nums1.length + 1).fill(0).map(() => Array(nums2.length + 1).fill(0));

    // Iterate over the two arrays to fill the dp array
    for (var i = 1; i <= nums1.length; i++) {
        for (var j = 1; j <= nums2.length; j++) {
            // If the current elements are equal, the length of the longest common subsequence increases by 1
            if (nums1[i - 1] === nums2[j - 1]) dp[i][j] = dp[i - 1][j - 1] + 1;
            // Otherwise, the length of the longest common subsequence is the maximum of the lengths without the current elements
            else dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
        }
    }

    // The maximum number of uncrossed lines is the length of the longest common subsequence
    return dp[nums1.length][nums2.length];
}

function convertBST(root) {
    // Initialize the sum of all keys greater than the current node
    let sum = 0;
    function dfs(node) {
        // If the node is null, return
        if (!node) return;
        // Recursively traverse the right subtree
        dfs(node.right);
        // Update the sum and the node's value
        sum += node.val;
        node.val = sum;
        // Recursively traverse the left subtree
        dfs(node.left);
    }
    dfs(root);
    return root;
}

function isBoomerang(points) {
