    let x1 = points[0][0], y1 = points[0][1];
    let x2 = points[1][0], y2 = points[1][1];
    let x3 = points[2][0], y3 = points[2][1];
    return (y2 - y1) * (x3 - x2) !== (y3 - y2) * (x2 - x1);
}

function minScoreTriangulation(values) {
  // Initialize a 2D array to store the minimum score for each sub-polygon
  var n = values.length;
  var dp = new Array(n).fill(0).map(() => new Array(n).fill(0));

  // Fill the dp array in a bottom-up manner
  for (var length = 2; length < n; length++) {
    // Calculate the minimum score for each sub-polygon of the current length
    for (var i = 0; i < n - length; i++) {
      var j = i + length;
      // Initialize the minimum score for the current sub-polygon
      dp[i][j] = Infinity;
      // Try all possible triangulations of the current sub-polygon
      for (var k = i + 1; k < j; k++) {
        // Calculate the score of the current triangulation
        var score = values[i] * values[k] * values[j] + dp[i][k] + dp[k][j];
        // Update the minimum score for the current sub-polygon
        dp[i][j] = Math.min(dp[i][j], score); // Calculate the minimum score for the current sub-polygon
      }
    }
  }

  // The minimum score for the entire polygon is stored in dp[0][n-1]
  return dp[0][n-1];
}

function numMovesStonesII(stones) {
