    // BFS loop
    while (queue.length > 0) {
        var current = queue.shift();
        // If we've reached the target, return true
        if (current[0] === target[0] && current[1] === target[1]) {
            return true;
        }

        // Explore all possible moves from the current position
        for (var i = 0; i < moves.length; i++) {
            var newX = current[0] + moves[i][0];
            var newY = current[1] + moves[i][1];

            // Check if the new position is within the grid and not blocked
            if (newX >= 0 && newX < 1000000 && newY >= 0 && newY < 1000000 && !blockedSet.has([newX, newY].join(',')) && !visited.has([newX, newY].join(','))) {
                queue.push([newX, newY]);
                visited.add([newX, newY].join(','));
            }
        }

        // If we've explored 200 steps without finding the target, we can stop
        if (queue.length > 200) {
            return true;
        }
    }

    // If we've reached this point, it means we couldn't find the target
    return false;
}

function gardenNoAdj(n, paths) {
    // Create an adjacency list to represent the graph
    let graph = Array.from({length: n}, () => []);
    for (let [x, y] of paths) {
        // Add edges to the graph
        graph[x - 1].push(y - 1);
        graph[y - 1].push(x - 1);
    }

    // Initialize the answer array with zeros
    let answer = new Array(n).fill(0);

    // Iterate over each garden
    for (let i = 0; i < n; i++) {
        // Initialize a set to store the flower types of adjacent gardens
        let used = new Set();
        for (let j of graph[i]) {
            // Add the flower type of each adjacent garden to the set
            used.add(answer[j]);
        }
        // Find the first available flower type
        for (let j = 1; j <= 4; j++) {
            // If the flower type is not used by any adjacent garden, use it
            if (!used.has(j)) {
                answer[i] = j;
                break;
            }
        }
    }

    return answer;
}

function isRobotBounded(instructions) {
    // initialize position and direction
    let x = 0, y = 0, dx = 0, dy = 1;
    // simulate the robot's movement for 4 cycles
    for (let i = 0; i < 4; i++) {
        // iterate over each instruction
        for (let j = 0; j < instructions.length; j++) {
            // if the instruction is 'G', move the robot
            if (instructions[j] === 'G') {
                // update the position based on the current direction
                x += dx; y += dy;
            }
            // if the instruction is 'L', turn the robot left
            else if (instructions[j] === 'L') {
                // update the direction
                let temp = dx; dx = -dy; dy = temp;
            }
            // if the instruction is 'R', turn the robot right
            else if (instructions[j] === 'R') {
                // update the direction
                let temp = dx; dx = dy; dy = -temp;
            }
        }
    }
    // if the robot is back at the origin after 4 cycles, it is bounded
    return x === 0 && y === 0;
}

function maxSumAfterPartitioning(arr, k) {
  const n = arr.length;
  const dp = new Array(n + 1).fill(0);
  for (let i = 1; i <= n; i++) {
    let maxVal = 0;
    // calculate the maximum sum for each possible subarray length from 1 to k
    for (let j = 1; j <= Math.min(i, k); j++) {
      maxVal = Math.max(maxVal, arr[i - j]);
      // update dp array with the maximum sum
      dp[i] = Math.max(dp[i], dp[i - j] + maxVal * j);
    }
  }
  // return the maximum sum after partitioning
  return dp[n];
}

function lastStoneWeight(stones) {
  // The algorithm solution is already optimal, using a max heap to store the stones
  while (stones.length > 1) {
    // Sort the stones in descending order to get the heaviest two stones
    stones.sort((a, b) => b - a);
    // Smash the heaviest two stones together
    let x = stones.shift();
    let y = stones.shift();
    // If x is not equal to y, add the difference back to the stones array
    if (x !== y) {
      // Add the difference back to the stones array
      stones.push(Math.abs(x - y));
    }
  }
  // Return the weight of the last stone, or 0 if there are no stones left
  return stones.length === 0 ? 0 : stones[0];
}

function removeDuplicates(s) {
