    if (stack.length > 0 && stack[stack.length - 1] === s[i]) {
      stack.pop();
    } 
    // Otherwise, push the current character onto the stack
    else {
      stack.push(s[i]);
    }
  }
  // Join the characters in the stack into a string and return the result
  return stack.join('');
}

function lastStoneWeightII(stones) {
  let totalSum = 0;
  for (let i = 0; i < stones.length; i++) totalSum += stones[i];
  const half = Math.floor(totalSum / 2);
  let dp = new Array(half + 1).fill(0);
  for (let i = 0; i < stones.length; i++) {
    for (let j = half; j >= stones[i]; j--) {
      dp[j] = Math.max(dp[j], dp[j - stones[i]] + stones[i]);
    }
  }
  return totalSum - 2 * dp[half];
}

function longestStrChain(words) {
    // Sort the words array by the length of each word
    words.sort((a, b) => a.length - b.length);

    // Initialize a hashmap to store the longest chain length for each word
    let dp = {};

    // Initialize the maximum chain length
    let maxChainLength = 1;

    // Iterate over each word in the sorted array
    for (let word of words) {
        // Initialize the chain length for the current word to 1
        dp[word] = 1;

        // Iterate over each possible predecessor of the current word
        for (let i = 0; i < word.length; i++) {
            // Create the predecessor by removing the character at the current index
            let predecessor = word.substring(0, i) + word.substring(i + 1);

            // If the predecessor is in the hashmap, update the chain length for the current word
            if (predecessor in dp) {
                // Update the chain length for the current word
                dp[word] = Math.max(dp[word], dp[predecessor] + 1);
            }
        }

        // Update the maximum chain length
        maxChainLength = Math.max(maxChainLength, dp[word]);
    }

    // Return the maximum chain length
    return maxChainLength;
}

function longestDuplicateSubstring(s) {
    const n = s.length;
    for (let length = n - 1; length > 0; length--) {
        const seen = new Map();
        for (let i = 0; i <= n - length; i++) {
            let hash = 0;
            for (let j = 0; j < length; j++) hash = hash * 31 + s.charCodeAt(i + j);
            if (seen.has(hash)) {
                const prevIndex = seen.get(hash);
                if (s.substring(prevIndex, prevIndex + length) === s.substring(i, i + length)) {
                    return s.substring(i, i + length);
                }
            }
            seen.set(hash, i);
        }
    }
    return "";
}

function heightChecker(heights) {
