}

function prevPermOpt1(arr) {
    // Find the first pair of elements from the right where the first element is greater than the second
    for (var i = arr.length - 2; i >= 0; i--) {
        // Check if the current element is greater than the next one
        if (arr[i] > arr[i + 1]) {
            // Find the largest element to the right of the current element that is smaller than it
            var maxSmaller = -Infinity;
            var maxSmallerIndex = -1;
            for (var j = i + 1; j < arr.length; j++) {
                // Update the maximum smaller element and its index
                if (arr[j] < arr[i] && arr[j] > maxSmaller) {
                    maxSmaller = arr[j];
                    maxSmallerIndex = j;
                }
            }
            // Swap the current element with the maximum smaller element
            var temp = arr[i];
            arr[i] = arr[maxSmallerIndex];
            arr[maxSmallerIndex] = temp;
            // The lexicographically largest permutation that is smaller than arr has been found
            return arr;
        }
    }
    // If no such pair is found, return the original array
    return arr;
}

function maxSatisfied(customers, grumpy, minutes) {
    let totalSatisfied = 0; // calculate the total number of satisfied customers without using the technique
    for (let i = 0; i < customers.length; i++) {
