        if (grumpy[i] === 0) totalSatisfied += customers[i];
    }

    let maxAdditionalSatisfied = 0; // find the maximum number of additional satisfied customers using the technique
    let currentAdditionalSatisfied = 0; // calculate the current number of additional satisfied customers
    for (let i = 0; i < customers.length; i++) {
        // add the customers to the current additional satisfied
        currentAdditionalSatisfied += customers[i] * grumpy[i];
        // if the window size exceeds the minutes, subtract the customers at the start of the window
        if (i >= minutes) currentAdditionalSatisfied -= customers[i - minutes] * grumpy[i - minutes];
        // update the maximum additional satisfied
        maxAdditionalSatisfied = Math.max(maxAdditionalSatisfied, currentAdditionalSatisfied);
    }

    // return the total satisfied plus the maximum additional satisfied
    return totalSatisfied + maxAdditionalSatisfied;
}

function rearrangeBarcodes(barcodes) {
    // Create a hash map to store the frequency of each barcode
    var frequencyMap = {};
    for (var i = 0; i < barcodes.length; i++) {
        // Count the frequency of each barcode
        frequencyMap[barcodes[i]] = (frequencyMap[barcodes[i]] || 0) + 1;
    }

    // Create a max heap to store the barcodes and their frequencies
    var maxHeap = [];
    for (var key in frequencyMap) {
        // Push the barcode and its frequency into the max heap
        maxHeap.push([key, frequencyMap[key]]);
    }
    maxHeap.sort(function(a, b) {
        // Sort the max heap in descending order based on the frequency
        return b[1] - a[1];
    });

    var result = [];
    while (maxHeap.length > 0) {
        // Dequeue the two barcodes with the highest frequency
        var first = maxHeap.shift();
        if (maxHeap.length > 0) {
            var second = maxHeap.shift();
            // Add the two barcodes to the result
            result.push(parseInt(first[0]));
            result.push(parseInt(second[0]));
            // Decrement the frequency of the two barcodes
            first[1]--;
            second[1]--;
            // If the frequency is greater than 0, push the barcodes back into the max heap
            if (first[1] > 0) {
                maxHeap.push(first);
            }
            if (second[1] > 0) {
                maxHeap.push(second);
            }
            // Sort the max heap in descending order based on the frequency
            maxHeap.sort(function(a, b) {
                return b[1] - a[1];
            });
        } else {
            // If there is only one barcode left, add it to the result
            result.push(parseInt(first[0]));
        }
    }
    return result;
}

function smallestEquivalentString(s1, s2, baseStr) {
    // Create a parent array to store the parent of each character
    let parent = new Array(26).fill(0).map((_, i) => String.fromCharCode('a'.charCodeAt(0) + i));

    // Function to find the parent of a character
    function find(x) {
        // If the parent of x is not x, then update the parent of x
        if (parent[x.charCodeAt(0) - 'a'.charCodeAt(0)] !== x) {
            parent[x.charCodeAt(0) - 'a'.charCodeAt(0)] = find(parent[x.charCodeAt(0) - 'a'.charCodeAt(0)]);
        }
        return parent[x.charCodeAt(0) - 'a'.charCodeAt(0)];
    }

    // Function to union two characters
    function union(x, y) {
        // Find the parents of x and y
        let rootX = find(x);
        let rootY = find(y);
        // If rootX is greater than rootY, then update the parent of rootX to rootY
        if (rootX > rootY) {
            parent[rootX.charCodeAt(0) - 'a'.charCodeAt(0)] = rootY;
        } else {
            // Otherwise, update the parent of rootY to rootX
            parent[rootY.charCodeAt(0) - 'a'.charCodeAt(0)] = rootX;
        }
    }

    // Union the characters in s1 and s2
    for (let i = 0; i < s1.length; i++) {
        union(s1[i], s2[i]);
    }

    // Initialize an empty result string
    let result = '';
    // For each character in baseStr, find its parent and add it to the result string
    for (let i = 0; i < baseStr.length; i++) {
        result += find(baseStr[i]);
    }
    return result;
}

function gcdOfStrings(str1, str2) {
  if (str1 + str2 !== str2 + str1) return "";
  function gcd(a, b) { return b === 0 ? a : gcd(b, a % b); }
  const g = gcd(str1.length, str2.length);
  return str1.substring(0, g);
}

function maxEqualRowsAfterFlips(matrix) {
    // Create a hashmap to store the frequency of each row
    var rowFrequency = {};
    // Initialize the maximum count of equal rows
    var maxCount = 0;
    // Iterate over each row in the matrix
    for (var i = 0; i < matrix.length; i++) {
        // Create a copy of the current row
        var row = matrix[i].slice();
        // Calculate the hash of the row and its flipped version
        var hash = row.join('');
        var flippedHash = row.map(x => 1 - x).join('');
        // Increment the frequency of the row or its flipped version
        rowFrequency[hash] = (rowFrequency[hash] || 0) + 1;
        rowFrequency[flippedHash] = (rowFrequency[flippedHash] || 0) + 1;
        // Update the maximum count of equal rows
        maxCount = Math.max(maxCount, rowFrequency[hash], rowFrequency[flippedHash]);
    }
    // This algorithm is already optimal with a time complexity of O(m * n) and space complexity of O(m * n)
    return maxCount;
}

function addNegabinary(arr1, arr2) {
    let num1 = 0, num2 = 0;
    for (let i = 0; i < arr1.length; i++) num1 += arr1[i] * Math.pow(-2, arr1.length - 1 - i);
    for (let i = 0; i < arr2.length; i++) num2 += arr2[i] * Math.pow(-2, arr2.length - 1 - i);
    let sum = num1 + num2;
    if (sum === 0) return [0];
    let result = [];
    while (sum !== 0) {
        const remainder = ((sum % 2) + 2) % 2;
        result.push(remainder);
        sum = (sum - remainder) / -2;
    }
    result.reverse();
    return result;
}

function sufficientSubset(root, limit) {
    if (!root) return null;
    if (!root.left && !root.right) return root.val < limit ? null : root;
    root.left = sufficientSubset(root.left, limit - root.val);
    root.right = sufficientSubset(root.right, limit - root.val);
    if (!root.left && !root.right) return null;
    return root;
}

function numSubmatrixSumTarget(matrix, target) {
  let count = 0; // initialize count of submatrices that sum to target
  let rows = matrix.length, cols = matrix[0].length; // get number of rows and columns
  let prefixSum = Array(rows + 1).fill(0).map(() => Array(cols + 1).fill(0)); // initialize prefix sum matrix
  for (let i = 1; i <= rows; i++) { // calculate prefix sum
    for (let j = 1; j <= cols; j++) {
      prefixSum[i][j] = prefixSum[i - 1][j] + prefixSum[i][j - 1] - prefixSum[i - 1][j - 1] + matrix[i - 1][j - 1];
    }
  }
  for (let x1 = 0; x1 < rows; x1++) { // iterate over all possible submatrices
    for (let y1 = 0; y1 < cols; y1++) {
      for (let x2 = x1; x2 < rows; x2++) {
        for (let y2 = y1; y2 < cols; y2++) {
          let sum = prefixSum[x2 + 1][y2 + 1] - prefixSum[x2 + 1][y1] - prefixSum[x1][y2 + 1] + prefixSum[x1][y1]; // calculate sum of submatrix using prefix sum
          if (sum === target) count++; // increment count if sum equals target
        }
      }
    }
  }
  return count; // return count of submatrices that sum to target
}

function numTilePossibilities(tiles) {
    let count = 0;
    let frequency = {};
    // Create a frequency map of the tiles
    for (let i = 0; i < tiles.length; i++) {
        if (frequency[tiles[i]]) {
            frequency[tiles[i]]++;
        } else {
            frequency[tiles[i]] = 1;
        }
    }
    function backtrack() {
        // For each unique tile, recursively generate all possible sequences
        for (let tile in frequency) {
            if (frequency[tile] > 0) {
                count++;
                frequency[tile]--;
                backtrack();
                frequency[tile]++;
            }
        }
    }
    backtrack();
    return count;
}

function smallestSubsequence(s) {
    // Create a set to store the characters we've seen so far
    let seen = new Set();
    // Create a stack to store the characters of the subsequence
    let stack = [];
    // Create a map to store the last occurrence of each character
    let lastOccurrence = {};
    for (let i = 0; i < s.length; i++) {
        // Store the last occurrence of each character
        lastOccurrence[s[i]] = i;
    }
    for (let i = 0; i < s.length; i++) {
        // If we've already seen this character, skip it
        if (seen.has(s[i])) {
            continue;
        }
        // While the stack is not empty and the top of the stack is greater than the current character
        // and the top of the stack appears again in the string after the current position
        while (stack.length > 0 && stack[stack.length - 1] > s[i] && lastOccurrence[stack[stack.length - 1]] > i) {
            // Remove the top of the stack from the seen set
            seen.delete(stack.pop());
        }
        // Add the current character to the stack and the seen set
        stack.push(s[i]);
        seen.add(s[i]);
    }
    // Join the characters in the stack to form the subsequence
    return stack.join('');
}

function largestValuesFromLabels(values, labels, numWanted, useLimit) {
