function parseBoolExpr(expression) {
    // Base case: if the expression is a single character, return its boolean value
    if (expression.length === 1) return expression === 't';

    // Extract the operator and the operands
    var operator = expression[0];
    var operands = [];
    var count = 0;
    var temp = '';
    for (var i = 2; i < expression.length - 1; i++) {
        // If the character is an opening parenthesis, increment the count
        if (expression[i] === '(') count++;
        // If the character is a closing parenthesis, decrement the count
        else if (expression[i] === ')') count--;
        // If the character is a comma and the count is 0, it's a separator
        else if (expression[i] === ',' && count === 0) {
            // Add the current operand to the list and reset the temp string
            operands.push(temp);
            temp = '';
        } else {
            // Add the character to the current operand
            temp += expression[i];
        }
    }
    // Add the last operand to the list
    operands.push(temp);

    // Evaluate the expression based on the operator
    if (operator === '!') {
        // NOT operator: return the opposite of the first operand
        return !parseBoolExpr(operands[0]);
    } else if (operator === '&') {
        // AND operator: return true if all operands are true
        for (var i = 0; i < operands.length; i++) {
            // If any operand is false, return false
            if (!parseBoolExpr(operands[i])) return false;
        }
        // If all operands are true, return true
        return true;
    } else if (operator === '|') {
        // OR operator: return true if any operand is true
        for (var i = 0; i < operands.length; i++) {
            // If any operand is true, return true
            if (parseBoolExpr(operands[i])) return true;
        }
        // If all operands are false, return false
        return false;
    }
}

function delNodes(root, to_delete) {
    // Create a set for efficient lookups of nodes to delete
    const deleteSet = new Set(to_delete);
    const result = [];

    function dfs(node) {
        // If the node is null, return null
        if (!node) return null;

        // Recursively traverse the left and right subtrees
        node.left = dfs(node.left);
        node.right = dfs(node.right);

        // If the current node's value is in the delete set
        if (deleteSet.has(node.val)) {
            // If the left child is not null, add it to the result
            if (node.left) result.push(node.left);
            // If the right child is not null, add it to the result
            if (node.right) result.push(node.right);
            // Return null to remove the current node
            return null;
        }

        // If the current node's value is not in the delete set, return the node
        return node;
    }

    // If the root node is not null after the DFS traversal
    if (dfs(root)) {
        // Add the root node to the result
        result.push(root);
    }

    // Return the result
    return result;
}

function maxDepthAfterSplit(seq) {
    const result = [];
    let depth = 0;
    for (const ch of seq) {
        if (ch === '(') {
            result.push(depth % 2);
            depth++;
        } else {
            depth--;
            result.push(depth % 2);
        }
    }
    return result;
}

function relativeSortArray(arr1, arr2) {
  // Create a hash map to store the frequency of elements in arr1
  var frequencyMap = {};
  for (var i = 0; i < arr1.length; i++) {
    // Count the frequency of each element in arr1
    frequencyMap[arr1[i]] = (frequencyMap[arr1[i]] || 0) + 1;
  }

  var result = [];
  // Iterate through arr2 to maintain the relative ordering
  for (var i = 0; i < arr2.length; i++) {
    // Append elements from arr2 to the result array
    while (frequencyMap[arr2[i]] > 0) {
      result.push(arr2[i]);
      frequencyMap[arr2[i]]--;
    }
  }

  // Append the remaining elements from arr1 in ascending order
  for (var key in frequencyMap) {
    // Check if the key exists in the frequency map
    if (frequencyMap[key] > 0) {
      // Append the remaining elements to the result array
      for (var i = 0; i < frequencyMap[key]; i++) {
        result.push(parseInt(key));
      }
    }
  }

  return result;
}

function lcaDeepestLeaves(root) {
    // Perform DFS to find the deepest leaves and their LCA
    function dfs(node) {
        if (!node) return [0, null]; // Base case: empty tree
        // Recursively find the depth and LCA of the left and right subtrees
        let [leftDepth, leftLca] = dfs(node.left);
        let [rightDepth, rightLca] = dfs(node.right);

        // If the left and right subtrees have the same depth, the current node is the LCA
        if (leftDepth === rightDepth) return [leftDepth + 1, node];
        // If the left subtree is deeper, its LCA is the LCA of the entire tree
        else if (leftDepth > rightDepth) return [leftDepth + 1, leftLca];
        // If the right subtree is deeper, its LCA is the LCA of the entire tree
        else return [rightDepth + 1, rightLca];
    }
    // This algorithm is already optimal, with a time complexity of O(n) and space complexity of O(h)
    let result = dfs(root);
    return result[1];
}

function longestWPI(hours) {
  let score = 0, maxLength = 0, seen = {};
  // Initialize a hash map to store the score and its corresponding index
  for (let i = 0; i < hours.length; i++) {
    // Update the score based on whether the current day is tiring or not
    score += hours[i] > 8 ? 1 : -1;
    // If the score is positive, it means we have a well-performing interval
    if (score > 0) {
      // Update the maximum length of the well-performing interval
      maxLength = Math.max(maxLength, i + 1);
    } else {
      // If the score is not in the hash map, add it
      if (!(score in seen)) {
        seen[score] = i;
      }
      // If the score - 1 is in the hash map, it means we have a well-performing interval
      if ((score - 1) in seen) {
        // Update the maximum length of the well-performing interval
        maxLength = Math.max(maxLength, i - seen[score - 1]);
      }
    }
  }
  // This algorithm is already optimal with a time complexity of O(n)
  return maxLength;
}

function smallestSufficientTeam(req_skills, people) {
    // Create a bitmask for each required skill
    let skillToBit = {};
    for (let i = 0; i < req_skills.length; i++) {
        skillToBit[req_skills[i]] = 1 << i;
    }

    // Create a bitmask for each person's skills
    let personSkills = [];
    for (let person of people) {
        let skillBitmask = 0;
        for (let skill of person) {
            skillBitmask |= skillToBit[skill];
        }
        personSkills.push(skillBitmask);
    }

    // Initialize the dp array with an empty team
    let dp = new Array(1 << req_skills.length).fill(null);
    dp[0] = [];

    // Iterate over each person
    for (let i = 0; i < people.length; i++) {
        // Iterate over the dp array in reverse order
        for (let j = (1 << req_skills.length) - 1; j >= 0; j--) {
            // If the current team is not null and the person's skills can cover new skills
            if (dp[j] !== null && (dp[j].length + 1 < (dp[j | personSkills[i]] === null ? Infinity : dp[j | personSkills[i]].length))) {
                // Update the dp array with the new team
                dp[j | personSkills[i]] = [...dp[j], i];
            }
        }
    }

    // Return the smallest sufficient team
    return dp[(1 << req_skills.length) - 1];
}

function maxAbsValExpr(arr1, arr2) {
  let maxVal = 0;
  // calculate all possible combinations of i and j
  for (let i = 0; i < arr1.length; i++) {
    for (let j = i + 1; j < arr1.length; j++) {
      // calculate the absolute value expression for current i and j
      let val = Math.abs(arr1[i] - arr1[j]) + Math.abs(arr2[i] - arr2[j]) + Math.abs(i - j);
      // update maxVal if current val is greater
      maxVal = Math.max(maxVal, val);
    }
  }
  return maxVal;
}

function numEquivDominoPairs(dominoes) {
  // Create a hash map to store the frequency of each domino
  var map = {};
  var count = 0;
  for (var i = 0; i < dominoes.length; i++) {
    // Sort the domino to ensure [a, b] and [b, a] are treated as the same
    var domino = dominoes[i].sort((a, b) => a - b);
    var key = domino.join(',');
    // If the domino is already in the map, calculate the number of pairs
    if (map[key] !== undefined) {
      // Calculate the number of pairs for the current domino
      count += map[key];
      // Increment the frequency of the domino
      map[key]++;
    } else {
      // If the domino is not in the map, add it with a frequency of 1
      map[key] = 1;
    }
  }
  return count;
}

function mctFromLeafValues(arr) {
    let result = 0; // initialize result variable
    let stack = [Infinity]; // initialize stack with infinity
    for (let num of arr) { // iterate through the array
        // while the top of the stack is smaller than the current number, calculate the result and pop the stack
        while (stack[stack.length - 1] < num) {
            let mid = stack.pop(); // pop the top of the stack
            result += mid * Math.min(stack[stack.length - 1], num); // calculate the result
        }
        stack.push(num); // push the current number to the stack
    }
    // calculate the result for the remaining numbers in the stack
    while (stack.length > 2) {
        let mid = stack.pop(); // pop the top of the stack
        result += mid * stack[stack.length - 1]; // calculate the result
    }
    return result; // return the result
}

function shortestAlternatingPaths(n, redEdges, blueEdges) {
    // Create adjacency list for red and blue edges
    let redGraph = Array.from({length: n}, () => []), blueGraph = Array.from({length: n}, () => []);
    for (let [u, v] of redEdges) redGraph[u].push(v);
    for (let [u, v] of blueEdges) blueGraph[u].push(v);

    // Initialize result array and queue for BFS
    let result = Array(n).fill(-1), queue = [[0, 0, true], [0, 0, false]];
    result[0] = 0;

    // Perform BFS
    while (queue.length) {
        let [node, length, isRed] = queue.shift();
        // Explore neighbors of the current node
        if (isRed) {
            for (let neighbor of blueGraph[node]) {
                if (result[neighbor] === -1) {
                    result[neighbor] = length + 1;
                    queue.push([neighbor, length + 1, false]);
                }
            }
        } else {
            for (let neighbor of redGraph[node]) {
                if (result[neighbor] === -1) {
                    result[neighbor] = length + 1;
                    queue.push([neighbor, length + 1, true]);
                }
            }
        }
    }
    return result;
}

function alphabetBoardPath(target) {
    var board = ["abcde", "fghij", "klmno", "pqrst", "uvwxy", "z"];
    var result = "", currX = 0, currY = 0;
    for (var i = 0; i < target.length; i++) {
        for (var j = 0; j < board.length; j++) {
            if (board[j].indexOf(target[i]) !== -1) {
                var newX = j, newY = board[j].indexOf(target[i]);
                // Up and Left must happen before Down and Right for the same
                // reason as above: avoids stepping into an invalid (row, col) pair
                while (currX > newX) { result += "U"; currX--; }
                while (currY > newY) { result += "L"; currY--; }
                while (currX < newX) { result += "D"; currX++; }
                while (currY < newY) { result += "R"; currY++; }
                result += "!";
                break;
            }
        }
    }
    return result;
}

function stoneGameII(piles) {
  let n = piles.length;
  let suffixSum = new Array(n + 1).fill(0);
  for (let i = n - 1; i >= 0; i--) {
    // calculate the suffix sum for each pile
    suffixSum[i] = suffixSum[i + 1] + piles[i];
  }
  let memo = new Array(n).fill(0).map(() => new Array(n + 1).fill(-1));
  function dp(i, m) {
    if (i + 2 * m >= n) {
      // base case: if we can take all remaining piles, return the sum
      return suffixSum[i];
    }
    if (memo[i][m] !== -1) {
      // if we've already computed this subproblem, return the result
      return memo[i][m];
    }
    let maxScore = -Infinity;
    for (let x = 1; x <= 2 * m; x++) {
      // try taking x piles and recursively compute the score for the remaining piles
      let score = suffixSum[i] - dp(i + x, Math.max(x, m));
      maxScore = Math.max(maxScore, score);
    }
    // store the result in the memoization table
    memo[i][m] = maxScore;
    return maxScore;
  }
  return dp(0, 1);
}

function movesToMakeZigzag(nums) {
    const n = nums.length;
    function cost(parity) {
        // decrease every index with i % 2 === parity so it's strictly less than both neighbors
        let total = 0;
        for (let i = 0; i < n; i++) {
            if (i % 2 !== parity) continue;
            let neighborMin = Infinity;
            if (i > 0) neighborMin = Math.min(neighborMin, nums[i - 1]);
            if (i < n - 1) neighborMin = Math.min(neighborMin, nums[i + 1]);
            if (neighborMin === Infinity) continue;
            total += Math.max(0, nums[i] - neighborMin + 1);
        }
        return total;
    }
    return Math.min(cost(0), cost(1));
}

function longestCommonSubsequence(text1, text2) {
  // Create a 2D array to store the lengths of common subsequences
  var dp = Array(text1.length + 1).fill(0).map(() => Array(text2.length + 1).fill(0));

  // Iterate over both strings to fill the dp array
  for (var i = 1; i <= text1.length; i++) {
    for (var j = 1; j <= text2.length; j++) {
      // If the current characters match, increase the length of the common subsequence
      if (text1[i - 1] === text2[j - 1]) dp[i][j] = dp[i - 1][j - 1] + 1;
      // Otherwise, take the maximum length from the previous characters
      else dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
    }
  }

  // The length of the longest common subsequence is stored in the last cell of the dp array
  return dp[text1.length][text2.length];
}

function longestDecomposition(text) {
  const n = text.length;
  if (n === 0) return 0;
  for (let len = 1; len <= Math.floor(n / 2); len++) {
    if (text.slice(0, len) === text.slice(n - len)) {
      return 2 + longestDecomposition(text.slice(len, n - len));
    }
  }
  return 1;
}

function btreeGameWinningMove(root, n, x) {
    let parentMap = new Map();
    function dfs(node, parent) {
        if (node) parentMap.set(node.val, parent);
        if (node.left) dfs(node.left, node);
        if (node.right) dfs(node.right, node);
    }
    dfs(root, null);

    let targetNode = null;
    function findNode(node) {
        if (node && node.val === x) targetNode = node;
        if (node && node.left) findNode(node.left);
        if (node && node.right) findNode(node.right);
    }
    findNode(root);

    function countSize(node) {
        if (!node) return 0;
        return 1 + countSize(node.left) + countSize(node.right);
    }
    const leftCount = countSize(targetNode.left);
    const rightCount = countSize(targetNode.right);

    return leftCount > n / 2 || rightCount > n / 2 || n - leftCount - rightCount - 1 > n / 2;
}

class SnapshotArray {
    constructor(length) {
        this.snapshots = Array(length).fill(0).map(() => ({}));
        this.snapId = 0;
    }
    set(index, val) { this.snapshots[index][this.snapId] = val; }
    snap() { this.snapId++; return this.snapId - 1; }
    get(index, snapId) {
        if (snapId >= this.snapId) return 0;
        const record = this.snapshots[index];
        let best = 0, bestId = -1;
        for (const id in record) {
            const idNum = Number(id);
            if (idNum <= snapId && idNum > bestId) { bestId = idNum; best = record[id]; }
        }
        return best;
    }
}

function numRollsToTarget(n, k, target) {
    const MOD = 1e9 + 7;
    const dp = Array(n + 1).fill(0).map(() => Array(target + 1).fill(0));
    dp[0][0] = 1; // base case: one way to get sum 0 with 0 dice
    for (let i = 1; i <= n; i++) { // for each die
        for (let j = 1; j <= target; j++) { // for each possible sum
            for (let x = 1; x <= Math.min(j, k); x++) { // for each face of the current die
                dp[i][j] = (dp[i][j] + dp[i - 1][j - x]) % MOD; // update the number of ways to get sum j with i dice
            }
        }
    }
    return dp[n][target]; // return the number of ways to get the target sum with n dice
}

function maxRepOpt1(text) {
    const n = text.length;
    const counts = {};
    for (const c of text) counts[c] = (counts[c] || 0) + 1;
    const groups = [];
    let i = 0;
    while (i < n) {
        let j = i + 1;
        while (j < n && text[j] === text[i]) j++;
        groups.push([text[i], j - i]);
        i = j;
    }
    let maxLen = 0;
    for (let idx = 0; idx < groups.length; idx++) {
        const [ch, len] = groups[idx];
        // extend this run by 1 if there's a spare same char elsewhere to swap in
        let cand = len + (counts[ch] > len ? 1 : 0);
        maxLen = Math.max(maxLen, Math.min(cand, counts[ch]));
        // merge two same-char runs separated by exactly one different char
        if (idx + 2 < groups.length && groups[idx + 1][1] === 1 && groups[idx][0] === groups[idx + 2][0]) {
            let merged = groups[idx][1] + groups[idx + 2][1];
            merged += (counts[ch] > merged) ? 1 : 0;
            maxLen = Math.max(maxLen, Math.min(merged, counts[ch]));
        }
    }
    return maxLen;
}

class MajorityChecker {
    constructor(arr) {
        this.indexMap = {};
        for (let i = 0; i < arr.length; i++) {
            if (!this.indexMap[arr[i]]) this.indexMap[arr[i]] = [];
            this.indexMap[arr[i]].push(i);
        }
    }
    query(left, right, threshold) {
        for (const num in this.indexMap) {
            const indices = this.indexMap[num];
            let count = 0;
            for (let i = 0; i < indices.length; i++) {
                if (indices[i] >= left && indices[i] <= right) count++;
            }
            if (count >= threshold) return parseInt(num);
        }
        return -1;
    }
}

function countCharacters(words, chars) {
  // Create a hash map to store the frequency of characters in 'chars'
  var charFrequency = {};
  for (var i = 0; i < chars.length; i++) {
    // If the character is already in the hash map, increment its count
    if (charFrequency[chars[i]]) charFrequency[chars[i]]++;
    // If the character is not in the hash map, add it with a count of 1
    else charFrequency[chars[i]] = 1;
  }

  var totalLength = 0;
  // Iterate over each word in the 'words' array
  for (var i = 0; i < words.length; i++) {
    // Create a copy of the 'charFrequency' hash map for the current word
    var wordFrequency = Object.assign({}, charFrequency);
    var isValidWord = true;
    // Iterate over each character in the current word
    for (var j = 0; j < words[i].length; j++) {
      // If the character is not in the 'wordFrequency' hash map or its count is 0, the word is not valid
      if (!wordFrequency[words[i][j]] || wordFrequency[words[i][j]] === 0) {
        isValidWord = false;
        break;
      }
      // Decrement the count of the character in the 'wordFrequency' hash map
      wordFrequency[words[i][j]]--;
    }
    // If the word is valid, add its length to the 'totalLength'
    if (isValidWord) totalLength += words[i].length;
  }
  return totalLength;
}

function lastSubstring(s) {
  let maxLength = 0, maxSubstring = '';
  // iterate over all possible substrings and compare them lexicographically
  for (let i = 0; i < s.length; i++) {
    for (let j = i + 1; j <= s.length; j++) {
      let substring = s.substring(i, j);
      // compare the current substring with the max substring found so far
      if (substring > maxSubstring) {
        maxSubstring = substring;
      }
    }
  }
  return maxSubstring;
}

function largest1BorderedSquare(grid) {
    // Get the number of rows and columns in the grid
    var rows = grid.length;
    if (rows === 0) return 0;
    var cols = grid[0].length;

    // Initialize variables to store the maximum size of the square and the result
    var maxSize = Math.min(rows, cols);
    var result = 0;

    // Iterate over all possible sizes of the square
    for (var size = 1; size <= maxSize; size++) {
        // Iterate over all possible positions of the top-left corner of the square
        for (var i = 0; i <= rows - size; i++) {
            for (var j = 0; j <= cols - size; j++) {
                // Check if the current square has all 1s on its border
                if (hasBorder(grid, i, j, size)) {
                    // Update the result if the current square is larger than the previous largest square
                    result = Math.max(result, size * size);
                }
            }
        }
    }

    // Return the result
    return result;
}

// Helper function to check if a square has all 1s on its border
function hasBorder(grid, row, col, size) {
    // Check the top and bottom borders
    for (var i = col; i <= col + size - 1; i++) {
        // If the top or bottom border has a 0, return false
        if (grid[row][i] === 0 || grid[row + size - 1][i] === 0) return false;
    }

    // Check the left and right borders
    for (var i = row; i <= row + size - 1; i++) {
        // If the left or right border has a 0, return false
        if (grid[i][col] === 0 || grid[i][col + size - 1] === 0) return false;
    }

    // If all borders have 1s, return true
    return true;
}

function maxLevelSum(root) {
    if (!root) return 0;
    let maxSum = -Infinity, maxLevel = 0, level = 0;
    let queue = [root];
    // perform BFS and calculate the sum of each level
    while (queue.length > 0) {
        level++;
        let levelSize = queue.length, sum = 0;
        for (let i = 0; i < levelSize; i++) {
            let node = queue.shift();
            sum += node.val;
            if (node.left) queue.push(node.left);
            if (node.right) queue.push(node.right);
        }
        // update maxSum and maxLevel if current level sum is greater
        if (sum > maxSum) {
            maxSum = sum;
            maxLevel = level;
        }
    }
    return maxLevel;
}

function dayOfYear(date) {
  // calculate the day of the year by first splitting the date string into year, month, and day components
  var year = parseInt(date.substring(0, 4));
  var month = parseInt(date.substring(5, 7));
  var day = parseInt(date.substring(8, 10));

  // initialize the total days to the day of the month
  var totalDays = day;

  // add the days for each month that has passed
  var monthDays = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if ((year % 4 === 0 && year % 100 !== 0) || year % 400 === 0) monthDays[1] = 29; // account for leap year
  for (var i = 0; i < month - 1; i++) totalDays += monthDays[i];

  // return the total days
  return totalDays;
}

function numSmallerByFrequency(queries, words) {
  // calculate frequency of smallest character in each word
  var wordFreqs = words.map(function(word) {
    var minChar = word.split('').sort()[0];
    // count frequency of smallest character
    return word.split(minChar).length - 1;
  });

  // sort word frequencies
  wordFreqs.sort(function(a, b) { return a - b; });

  // for each query, calculate frequency of smallest character
  return queries.map(function(query) {
    var minChar = query.split('').sort()[0];
    // count frequency of smallest character
    var queryFreq = query.split(minChar).length - 1;

    // use binary search to find number of words with higher frequency
    var left = 0, right = wordFreqs.length;
    while (left < right) {
      // find middle index
      var mid = Math.floor((left + right) / 2);
      // if middle frequency is greater than query frequency, update right
      if (wordFreqs[mid] > queryFreq) {
        right = mid;
      } 
      // otherwise, update left
      else {
        left = mid + 1;
      }
    }
    // return number of words with higher frequency
    return wordFreqs.length - left;
  });
}

function invalidTransactions(transactions) {
