}

function maxDistance(grid) {
    var n = grid.length;
    var queue = [];
    var distance = 0;
    var visited = new Array(n).fill(0).map(() => new Array(n).fill(false));
    // add all land cells to the queue
    for (var i = 0; i < n; i++) {
        for (var j = 0; j < n; j++) {
            if (grid[i][j] === 1) {
                queue.push([i, j]);
                visited[i][j] = true;
            }
        }
    }
    // if no land or water exists in the grid, return -1
    if (queue.length === 0 || queue.length === n * n) return -1;
    // perform BFS
    var directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    while (queue.length > 0) {
        var size = queue.length;
        // process each cell at the current distance level
        for (var k = 0; k < size; k++) {
            var cell = queue.shift();
            // explore all neighboring cells
            for (var i = 0; i < 4; i++) {
                var x = cell[0] + directions[i][0];
                var y = cell[1] + directions[i][1];
                // if the neighboring cell is within bounds and is a water cell, add it to the queue
                if (x >= 0 && x < n && y >= 0 && y < n && !visited[x][y]) {
                    queue.push([x, y]);
                    visited[x][y] = true;
                }
            }
        }
        // increment the distance after processing all cells at the current distance level
        distance++;
    }
    // the maximum distance is the last distance level processed
    return distance - 1;
}

function canMakePali(s, queries) {
    var result = [];
    for (var i = 0; i < queries.length; i++) {
        var left = queries[i][0];
        var right = queries[i][1];
        var k = queries[i][2];
        var count = {};
        for (var j = left; j <= right; j++) {
            if (count[s[j]]) { count[s[j]]++; } else { count[s[j]] = 1; }
        }
        var oddCount = 0;
        for (var key in count) {
            if (count[key] % 2 !== 0) { oddCount++; }
        }
        // minimum replacements needed = floor(oddCount / 2)
        result.push(Math.floor(oddCount / 2) <= k);
    }
    return result;
}

function removeZeroSumSublists(head) {
    // Create a dummy node to simplify the process of removing the head node
    let dummy = { next: head };
    let prefix = 0;
    let seen = { 0: dummy };
    while (head) {
        // Update the prefix sum
        prefix += head.val;
        // If the prefix sum is seen before, remove the nodes between the seen prefix sum and the current node
        if (prefix in seen) {
            let node = seen[prefix];
            let tmp = node.next;
            let tmpPrefix = prefix + tmp.val;
            // Remove the nodes between the seen prefix sum and the current node
            while (tmp !== head) {
                delete seen[tmpPrefix];
                tmp = tmp.next;
                tmpPrefix += tmp.val;
            }
            // Update the next pointer of the seen node
            node.next = head.next;
        } else {
            // If the prefix sum is not seen before, add it to the seen object
            seen[prefix] = head;
        }
        // Move to the next node
        head = head.next;
    }
    // Return the next node of the dummy node
    return dummy.next;
}

function numPrimeArrangements(n) {
    // Create a boolean array to store whether each number is prime
    var isPrime = new Array(n + 1).fill(true);
    isPrime[0] = isPrime[1] = false;
    for (var i = 2; i * i <= n; i++) {
        // If i is prime, mark its multiples as not prime
        if (isPrime[i]) {
            for (var j = i * i; j <= n; j += i) {
                isPrime[j] = false;
            }
        }
    }

    // Count the number of prime numbers and non-prime numbers
    var primeCount = 0, nonPrimeCount = 0;
    for (var i = 1; i <= n; i++) {
        // Count prime numbers
        if (isPrime[i]) primeCount++;
        // Count non-prime numbers
        else nonPrimeCount++;
    }

    // Calculate the number of permutations
    var result = 1;
    for (var i = 2; i <= primeCount; i++) {
        // Calculate the factorial of primeCount
        result = (result * i) % (1e9 + 7);
    }
    for (var i = 2; i <= nonPrimeCount; i++) {
        // Calculate the factorial of nonPrimeCount
        result = (result * i) % (1e9 + 7);
    }

    return result;
}

function findNumOfValidWords(words, puzzles) {
    let wordCount = {};
    for (let word of words) {
        let mask = 0; // create a bitmask for the word
        for (let char of word) {
            mask |= 1 << (char.charCodeAt(0) - 'a'.charCodeAt(0));
        }
        wordCount[mask] = (wordCount[mask] || 0) + 1; // count the number of words with the same bitmask
    }

    let result = [];
    for (let puzzle of puzzles) {
        let count = 0; // count the number of valid words for the current puzzle
        let mask = 0; // create a bitmask for the puzzle
        for (let char of puzzle) {
            mask |= 1 << (char.charCodeAt(0) - 'a'.charCodeAt(0));
        }
        for (let wordMask in wordCount) {
            let wordMaskInt = parseInt(wordMask); // convert the bitmask to an integer
            if ((wordMaskInt & mask) === wordMaskInt) { // check if the word is a subset of the puzzle
                if ((wordMaskInt & (1 << (puzzle[0].charCodeAt(0) - 'a'.charCodeAt(0)))) !== 0) { // check if the first letter of the puzzle is in the word
                    count += wordCount[wordMask]; // increment the count
                }
            }
        }
        result.push(count); // add the count to the result
    }
    return result;
}

function distanceBetweenBusStops(distance, start, destination) {
  // Calculate the total distance of the circular route
  let totalDistance = 0;
  for (let i = 0; i < distance.length; i++) {
    totalDistance += distance[i];
  }

  // Ensure start is less than destination
  if (start > destination) {
    let temp = start;
    start = destination;
    destination = temp;
  }

  // Calculate the distance between start and destination in the clockwise direction
  let clockwiseDistance = 0;
  for (let i = start; i < destination; i++) {
    // Add the distance between each pair of neighboring stops
    clockwiseDistance += distance[i];
  }

  // Calculate the distance between start and destination in the counterclockwise direction
  let counterclockwiseDistance = totalDistance - clockwiseDistance;

  // Return the minimum distance between the two directions
  return Math.min(clockwiseDistance, counterclockwiseDistance);
}

class DinnerPlates {
    constructor(capacity) {
        this.capacity = capacity;
        this.stacks = [];
        this.available = new MinHeap();
    }
    push(val) {
        while (this.available.size && (this.available.peek() >= this.stacks.length || this.stacks[this.available.peek()].length >= this.capacity)) {
            this.available.pop();
        }
        if (this.available.size === 0) {
            this.stacks.push([val]);
            if (this.capacity > 1) this.available.push(this.stacks.length - 1);
        } else {
            const idx = this.available.peek();
            this.stacks[idx].push(val);
            if (this.stacks[idx].length >= this.capacity) this.available.pop();
        }
    }
    pop() {
        while (this.stacks.length && this.stacks[this.stacks.length-1].length === 0) this.stacks.pop();
        if (!this.stacks.length) return -1;
        return this.popAtStack(this.stacks.length - 1);
    }
    popAtStack(index) {
        if (index >= this.stacks.length || this.stacks[index].length === 0) return -1;
        const wasFull = this.stacks[index].length === this.capacity;
        const val = this.stacks[index].pop();
        if (wasFull) this.available.push(index);
        while (this.stacks.length && this.stacks[this.stacks.length-1].length === 0) this.stacks.pop();
        return val;
    }
}
class MinHeap {
    constructor() { this.heap = []; }
    push(val) {
        this.heap.push(val);
        let i = this.heap.length - 1;
        while (i > 0) {
            const p = (i-1)>>1;
            if (this.heap[p] <= this.heap[i]) break;
            [this.heap[p], this.heap[i]] = [this.heap[i], this.heap[p]];
            i = p;
        }
    }
    pop() {
        const top = this.heap[0];
        const last = this.heap.pop();
        if (this.heap.length) {
            this.heap[0] = last;
            let i = 0, n = this.heap.length;
            while (true) {
                let l=2*i+1, r=2*i+2, smallest=i;
                if (l<n && this.heap[l]<this.heap[smallest]) smallest=l;
                if (r<n && this.heap[r]<this.heap[smallest]) smallest=r;
                if (smallest===i) break;
                [this.heap[i],this.heap[smallest]]=[this.heap[smallest],this.heap[i]];
                i=smallest;
            }
        }
        return top;
    }
    peek() { return this.heap[0]; }
    get size() { return this.heap.length; }
}

function dayOfTheWeek(day, month, year) {
    // Calculate the day of the week using Zeller's Congruence formula
    let t = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4];
    year -= month < 3;
    let result = (year + Math.floor(year/4) - Math.floor(year/100) + Math.floor(year/400) + t[month-1] + day) % 7;
    // Map the result to the corresponding day of the week
    let days = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
    return days[result];
}

function maxNumberOfBalloons(text) {
    // count the frequency of each character in the string
    let charCount = {};
    for (let char of text) {
        if (!charCount[char]) charCount[char] = 0;
        charCount[char]++;
    }
    // calculate the maximum number of instances that can be formed
    let b = charCount['b'] || 0;
    let a = charCount['a'] || 0;
    let l = Math.floor((charCount['l'] || 0) / 2);
    let o = Math.floor((charCount['o'] || 0) / 2);
    let n = charCount['n'] || 0;
    // the minimum of these counts is the maximum number of instances
    return Math.min(b, a, l, o, n);
}

function reverseParentheses(s) {
    // start with a base level so the outermost text always has somewhere to accumulate into
    let stack = [''];
    for (let i = 0; i < s.length; i++) {
        if (s[i] === '(') {
            stack.push('');
        } else if (s[i] === ')') {
            let reversed = stack.pop().split('').reverse().join('');
            stack[stack.length - 1] += reversed;
        } else {
            stack[stack.length - 1] += s[i];
        }
    }
    return stack[0];
}

function maximumSum(arr) {
  let n = arr.length;
  let forward = new Array(n).fill(0);
  let backward = new Array(n).fill(0);
  let maxSum = arr[0];
  // calculate the maximum sum of subarray ending at each position from left to right
  forward[0] = arr[0];
  for (let i = 1; i < n; i++) {
    forward[i] = Math.max(arr[i], forward[i - 1] + arr[i]);
    maxSum = Math.max(maxSum, forward[i]);
  }
  // calculate the maximum sum of subarray ending at each position from right to left
  backward[n - 1] = arr[n - 1];
  for (let i = n - 2; i >= 0; i--) {
    backward[i] = Math.max(arr[i], backward[i + 1] + arr[i]);
    maxSum = Math.max(maxSum, backward[i]);
  }
  // calculate the maximum sum of subarray with one deletion
  for (let i = 1; i < n - 1; i++) {
    // calculate the maximum sum of subarray with one deletion at the current position
    maxSum = Math.max(maxSum, forward[i - 1] + backward[i + 1]);
  }
  return maxSum;
}

function kConcatenationMaxSum(arr, k) {
    const MOD = 1e9 + 7;
    function kadaneNonNeg(a) {
        let cur = 0, best = 0;
        for (const x of a) {
            cur = Math.max(x, cur + x);
            best = Math.max(best, cur);
        }
        return best;
    }
    let total = 0;
    for (const x of arr) total += x;
    const best1 = kadaneNonNeg(arr);
    if (k === 1) return best1 % MOD;
    const best2 = kadaneNonNeg(arr.concat(arr));
    // beyond 2 copies, extra whole-array repeats only help if the array's total sum is positive
    let ans = total > 0 ? best2 + (k - 2) * total : best2;
    return ans % MOD;
}

function makeArrayIncreasing(arr1, arr2) {
    const sorted2 = Array.from(new Set(arr2)).sort((a, b) => a - b);
    function nextGreater(v) {
        // smallest value in sorted2 strictly greater than v
        let lo = 0, hi = sorted2.length;
        while (lo < hi) { let mid = (lo + hi) >> 1; if (sorted2[mid] > v) hi = mid; else lo = mid + 1; }
        return lo < sorted2.length ? sorted2[lo] : undefined;
    }
    // dp: map from "value the sequence currently ends on" -> min operations used so far
    let dp = new Map();
    dp.set(arr1[0], 0);
    if (sorted2.length > 0) dp.set(sorted2[0], Math.min(dp.get(sorted2[0]) ?? Infinity, 1));
    for (let i = 1; i < arr1.length; i++) {
        const newDp = new Map();
        for (const [prevVal, prevOps] of dp) {
            if (arr1[i] > prevVal) {
                const cur = newDp.get(arr1[i]) ?? Infinity;
                newDp.set(arr1[i], Math.min(cur, prevOps));
            }
            const ng = nextGreater(prevVal);
            if (ng !== undefined) {
                const cur = newDp.get(ng) ?? Infinity;
                newDp.set(ng, Math.min(cur, prevOps + 1));
            }
        }
        dp = newDp;
        if (dp.size === 0) return -1;
    }
    return Math.min(...dp.values());
}

function criticalConnections(n, connections) {
    // Create an adjacency list representation of the graph
    var graph = Array.from({ length: n }, () => []);
    for (var i = 0; i < connections.length; i++) {
        var u = connections[i][0];
        var v = connections[i][1];
        graph[u].push(v);
        graph[v].push(u);
    }

    var low = Array(n).fill(0);
    var disc = Array(n).fill(0);
    var visited = Array(n).fill(false);
    var parent = Array(n).fill(-1);
    var rank = 0;
    var result = [];

    function dfs(u) {
        // Initialize discovery time and low value for the current node
        disc[u] = rank;
        low[u] = rank;
        rank++;
        visited[u] = true;

        for (var i = 0; i < graph[u].length; i++) {
            var v = graph[u][i];
            if (!visited[v]) {
                // Update parent of the child node
                parent[v] = u;
                dfs(v);
                // Update low value of the current node
                low[u] = Math.min(low[u], low[v]);
                // Check if the edge between u and v is a critical connection
                if (low[v] > disc[u]) {
                    // If the edge is critical, add it to the result
                    result.push([u, v]);
                }
            } else if (v !== parent[u]) {
                // Update low value of the current node
                low[u] = Math.min(low[u], disc[v]);
            }
        }
    }

    dfs(0);
    return result;
}

function minimumAbsDifference(arr) {
  // Sort the array to find adjacent elements with minimum absolute difference
  arr.sort((a, b) => a - b);
  let minDiff = Infinity;
  let result = [];
  // Iterate through the sorted array to find the minimum absolute difference
  for (let i = 0; i < arr.length - 1; i++) {
    let diff = arr[i + 1] - arr[i];
    if (diff < minDiff) {
      // Update the minimum difference and reset the result array
      minDiff = diff;
      result = [[arr[i], arr[i + 1]]];
    } else if (diff === minDiff) {
      // Add pairs with the same minimum absolute difference to the result array
      result.push([arr[i], arr[i + 1]]);
    }
  }
  return result;
}

function uniqueOccurrences(arr) {
  var countMap = {}; // create a map to store the count of each number
  for (var i = 0; i < arr.length; i++) { // count occurrences of each number
    // increment count in map for each occurrence
    countMap[arr[i]] = (countMap[arr[i]] || 0) + 1;
  }
  var uniqueCounts = new Set(); // create a set to store unique counts
  for (var key in countMap) { // check if counts are unique
    // if count already exists in set, return false
    if (uniqueCounts.has(countMap[key])) return false;
    uniqueCounts.add(countMap[key]); // add count to set
  }
  return true; // if all counts are unique, return true
}

function equalSubstring(s, t, maxCost) {
    let maxLength = 0, left = 0, currentCost = 0;
    // calculate the cost of changing the substring and slide the window to the right
    for (let right = 0; right < s.length; right++) {
        currentCost += Math.abs(s.charCodeAt(right) - t.charCodeAt(right));
        // if the cost exceeds maxCost, slide the window to the right by moving the left pointer
        while (currentCost > maxCost) {
            currentCost -= Math.abs(s.charCodeAt(left) - t.charCodeAt(left));
            left++;
        }
        // update the maximum length of the substring
        maxLength = Math.max(maxLength, right - left + 1);
    }
    return maxLength;
}

function nthUglyNumber(n, a, b, c) {
    // calculate the least common multiple of a, b, and c
    function gcd(x, y) {
        return y === 0 ? x : gcd(y, x % y);
    }
    function lcm(x, y) {
        return x * y / gcd(x, y);
    }
    let lcm_ab = lcm(a, b);
    let lcm_bc = lcm(b, c);
    let lcm_ac = lcm(a, c);
    let lcm_abc = lcm(lcm_ab, c);

    // perform binary search to find the nth ugly number
    let left = 1;
    let right = 2 * 10 ** 9;
    while (left < right) {
        // calculate the number of ugly numbers less than or equal to mid
        let mid = Math.floor((left + right) / 2);
        let count = Math.floor(mid / a) + Math.floor(mid / b) + Math.floor(mid / c);
        count -= Math.floor(mid / lcm_ab) + Math.floor(mid / lcm_bc) + Math.floor(mid / lcm_ac);
        count += Math.floor(mid / lcm_abc);
        // adjust the search range based on the count
        if (count < n) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return left;
}

function removeDuplicates(s, k) {
  var stack = [];
  // iterate over the string and push characters and their counts to the stack
  for (var i = 0; i < s.length; i++) {
    // if the stack is not empty and the top character is the same as the current one, increment the count
    if (stack.length > 0 && stack[stack.length - 1][0] === s[i]) {
      stack[stack.length - 1][1]++;
      // if the count equals k, pop the character from the stack
      if (stack[stack.length - 1][1] === k) {
        stack.pop();
      }
    } else {
      // otherwise, push the character and its count to the stack
      stack.push([s[i], 1]);
    }
  }
  // build the result string from the stack
  var result = '';
  for (var i = 0; i < stack.length; i++) {
    // append the character to the result string, repeated by its count
    result += stack[i][0].repeat(stack[i][1]);
  }
  return result;
}

function smallestStringWithSwaps(s, pairs) {
    // Create a union-find data structure to group connected components
    let parent = Array(s.length).fill(0).map((_, i) => i);
    let rank = Array(s.length).fill(0);

    // Function to find the root of a node
    function find(x) {
        // If x is not the root, find its root and compress the path
        if (parent[x] !== x) parent[x] = find(parent[x]);
        return parent[x];
    }

    // Function to union two nodes
    function union(x, y) {
        // Find the roots of x and y
        let rootX = find(x);
        let rootY = find(y);

        // If x and y are already in the same group, return
        if (rootX === rootY) return;

        // Union the two groups by rank
        if (rank[rootX] < rank[rootY]) parent[rootX] = rootY;
        else if (rank[rootX] > rank[rootY]) parent[rootY] = rootX;
        else {
            parent[rootY] = rootX;
            rank[rootX]++;
        }
    }

    // Group connected components
    for (let [x, y] of pairs) union(x, y);

    // Create a map to store the characters in each group
    let map = {};
    for (let i = 0; i < s.length; i++) {
        let root = find(i);
        if (!map[root]) map[root] = [];
        map[root].push(s[i]);
    }

    // Sort the characters in each group
    for (let key in map) map[key].sort();

    // Create the result string
    let result = Array(s.length).fill(0);
    for (let i = 0; i < s.length; i++) {
        let root = find(i);
        // Get the smallest character from the group and remove it
        result[i] = map[root].shift();
    }

    // Join the result string
    return result.join('');
}

// TIME: O(n + m * alpha(n)) SPACE: O(n)

function Skiplist() {
    this.levels = 16;
    this.p = 0.5;
    this.head = new Node(0, this.levels);
}

function Node(val, level) {
    this.val = val;
    this.next = new Array(level).fill(null);
}

Skiplist.prototype.search = function(target) {
    let node = this.head;
    for (let i = this.levels - 1; i >= 0; i--) {
        // traverse to the right until we find a node with a value greater than or equal to the target
        while (node.next[i] && node.next[i].val < target) {
            node = node.next[i];
        }
    }
    // check if the node's value is equal to the target
    return node.next[0] && node.next[0].val === target;
}

Skiplist.prototype.add = function(num) {
    let update = new Array(this.levels).fill(null);
    let node = this.head;
    for (let i = this.levels - 1; i >= 0; i--) {
        // traverse to the right until we find a node with a value greater than or equal to the target
        while (node.next[i] && node.next[i].val < num) {
            node = node.next[i];
        }
        // update the node at the current level
        update[i] = node;
    }
    // create a new node with a random level
    let newNode = new Node(num, this.getRandomLevel());
    for (let i = 0; i < newNode.next.length; i++) {
        // update the next pointers of the new node
        newNode.next[i] = update[i].next[i];
        update[i].next[i] = newNode;
    }
}

Skiplist.prototype.erase = function(num) {
    let update = new Array(this.levels).fill(null);
    let node = this.head;
    for (let i = this.levels - 1; i >= 0; i--) {
        // traverse to the right until we find a node with a value greater than or equal to the target
        while (node.next[i] && node.next[i].val < num) {
            node = node.next[i];
        }
        // update the node at the current level
        update[i] = node;
    }
    // check if the node's value is equal to the target
    if (node.next[0] && node.next[0].val === num) {
        for (let i = 0; i < this.levels; i++) {
            // update the next pointers of the nodes at the current level
            if (update[i].next[i] && update[i].next[i].val === num) {
                update[i].next[i] = update[i].next[i].next[i];
            }
        }
        return true;
    }
    return false;
}

Skiplist.prototype.getRandomLevel = function() {
    let level = 1;
    while (Math.random() < this.p && level < this.levels) {
        level++;
    }
    return level;
}

// TIME: O(log(n)) SPACE: O(n)

function sortItems(n, m, group, beforeItems) {
    group = group.slice();
    let nextGroupId = m;
    for (let i = 0; i < n; i++) {
        if (group[i] === -1) group[i] = nextGroupId++;
    }
    const totalGroups = nextGroupId;

    const itemAdj = Array.from({length: n}, () => []);
    const itemIndeg = new Array(n).fill(0);
    const groupAdj = Array.from({length: totalGroups}, () => []);
    const groupIndeg = new Array(totalGroups).fill(0);

    for (let i = 0; i < n; i++) {
        for (const b of beforeItems[i]) {
            itemAdj[b].push(i);
            itemIndeg[i]++;
            if (group[b] !== group[i]) {
                groupAdj[group[b]].push(group[i]);
                groupIndeg[group[i]]++;
            }
        }
    }

    function topo(adj, indeg, count) {
        const deg = indeg.slice();
        const queue = [];
        for (let i = 0; i < count; i++) if (deg[i] === 0) queue.push(i);
        const order = [];
        let head = 0;
        while (head < queue.length) {
            const u = queue[head++];
            order.push(u);
            for (const v of adj[u]) {
                deg[v]--;
                if (deg[v] === 0) queue.push(v);
            }
        }
        return order.length === count ? order : null;
    }

    const itemOrder = topo(itemAdj, itemIndeg, n);
    if (itemOrder === null) return [];
    const groupOrder = topo(groupAdj, groupIndeg, totalGroups);
    if (groupOrder === null) return [];

    const itemsByGroup = new Map();
    for (let g = 0; g < totalGroups; g++) itemsByGroup.set(g, []);
    for (const item of itemOrder) itemsByGroup.get(group[item]).push(item);

    const result = [];
    for (const g of groupOrder) {
        for (const item of itemsByGroup.get(g)) result.push(item);
    }
    return result;
}

function isValid(n, group, beforeItems, order) {
    if (order.length !== n) return false;
    const pos = new Array(n);
    order.forEach((v, i) => pos[v] = i);
    for (let i = 0; i < n; i++) {
        for (const b of beforeItems[i]) {
            if (pos[b] > pos[i]) return false;
        }
    }
    const seen = new Map();
    order.forEach((item, idx) => {
        const g = group[item];
        if (g === -1) return;
        if (!seen.has(g)) seen.set(g, [idx, idx]);
        else seen.get(g)[1] = idx;
    });
    for (const [g, [lo, hi]] of seen) {
        for (let idx = lo; idx <= hi; idx++) {
            if (group[order[idx]] !== g) return false;
        }
    }
    return true;
}

