function minimumMoves(grid) {
    const n = grid.length;
    const visited = Array.from({length: n}, () => Array.from({length: n}, () => [false, false]));
    const queue = [[0, 0, 0, 0]]; // r, c, orientation (0=horizontal,1=vertical), steps
    visited[0][0][0] = true;
    while (queue.length) {
        const [r, c, ori, steps] = queue.shift();
        if (ori === 0 && r === n - 1 && c === n - 2) return steps;
        if (ori === 0) {
            if (c + 2 < n && grid[r][c + 2] === 0 && !visited[r][c + 1][0]) {
                visited[r][c + 1][0] = true;
                queue.push([r, c + 1, 0, steps + 1]);
            }
            if (r + 1 < n && grid[r + 1][c] === 0 && grid[r + 1][c + 1] === 0) {
                if (!visited[r + 1][c][0]) { visited[r + 1][c][0] = true; queue.push([r + 1, c, 0, steps + 1]); }
                if (!visited[r][c][1]) { visited[r][c][1] = true; queue.push([r, c, 1, steps + 1]); }
            }
        } else {
            if (r + 2 < n && grid[r + 2][c] === 0 && !visited[r + 1][c][1]) {
                visited[r + 1][c][1] = true;
                queue.push([r + 1, c, 1, steps + 1]);
            }
            if (c + 1 < n && grid[r][c + 1] === 0 && grid[r + 1][c + 1] === 0) {
                if (!visited[r][c + 1][1]) { visited[r][c + 1][1] = true; queue.push([r, c + 1, 1, steps + 1]); }
                if (!visited[r][c][0]) { visited[r][c][0] = true; queue.push([r, c, 0, steps + 1]); }
            }
        }
    }
    return -1;
}

function minCostToMoveChips(position) {
    let evenCount = 0;
    let oddCount = 0;
    // count the number of chips at even and odd positions
    for (let i = 0; i < position.length; i++) {
        if (position[i] % 2 === 0) {
            evenCount++;
        } else {
            oddCount++;
        }
    }
    // the minimum cost is the smaller count because we can move all chips to either even or odd position
    return Math.min(evenCount, oddCount);
}

function balancedStringSplit(s) {
  let count = 0, balance = 0; 
  // iterate through the string and balance the 'L' and 'R' counts
  for (let i = 0; i < s.length; i++) {
    // increment balance if 'L' is encountered, decrement if 'R' is encountered
    balance += (s[i] === 'L') ? 1 : -1;
    // if balance is zero, it means we have a balanced string, so increment count
    if (balance === 0) count++;
  }
  return count;
}

function longestSubsequence(arr, difference) {
  let maxLength = 0; // Initialize max length
  let dp = {}; // Create a hash map to store the length of the longest subsequence ending at each number
  for (let i = 0; i < arr.length; i++) { // Iterate through the array
    // Check if the number minus the difference exists in the hash map and update the length of the subsequence
    let currentLength = (dp[arr[i] - difference] || 0) + 1; 
    dp[arr[i]] = currentLength; // Update the length of the subsequence ending at the current number
    maxLength = Math.max(maxLength, currentLength); // Update the max length
  }
  return maxLength; // Return the max length
}

function countVowelPermutation(n) {
    const MOD = 1000000007;
    const dp = Array(5).fill(1); // indices: a,e,i,o,u
    for (let i = 2; i <= n; i++) {
        const temp = Array(5).fill(0);
        for (let j = 0; j < 5; j++) {
            if (j === 0) temp[1] = (temp[1] + dp[j]) % MOD; // a -> e
            else if (j === 1) { temp[0] = (temp[0] + dp[j]) % MOD; temp[2] = (temp[2] + dp[j]) % MOD; } // e -> a,i
            else if (j === 2) { // i -> a,e,o,u
                temp[0] = (temp[0] + dp[j]) % MOD;
                temp[1] = (temp[1] + dp[j]) % MOD;
                temp[3] = (temp[3] + dp[j]) % MOD;
                temp[4] = (temp[4] + dp[j]) % MOD;
            }
            else if (j === 3) { temp[2] = (temp[2] + dp[j]) % MOD; temp[4] = (temp[4] + dp[j]) % MOD; } // o -> i,u
            else if (j === 4) { temp[0] = (temp[0] + dp[j]) % MOD; } // u -> a only
        }
        for (let j = 0; j < 5; j++) dp[j] = temp[j];
    }
    let total = 0;
    for (let i = 0; i < 5; i++) total = (total + dp[i]) % MOD;
    return total;
}

function getMaximumGold(grid) {
    // Define the directions for backtracking
    const directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    let maxGold = 0;

    function backtrack(row, col, currentGold, visited) {
        // Update the maximum gold if the current gold is greater
        maxGold = Math.max(maxGold, currentGold);

        // Iterate over all possible directions
        for (let i = 0; i < 4; i++) {
            const newRow = row + directions[i][0];
            const newCol = col + directions[i][1];

            // Check if the new position is within the grid and not visited
            if (newRow >= 0 && newRow < grid.length && newCol >= 0 && newCol < grid[0].length && grid[newRow][newCol] !== 0 && !visited.has(`${newRow},${newCol}`)) {
                // Mark the new position as visited and recursively call backtrack
                visited.add(`${newRow},${newCol}`);
                backtrack(newRow, newCol, currentGold + grid[newRow][newCol], visited);
                // Backtrack by removing the new position from the visited set
                visited.delete(`${newRow},${newCol}`);
            }
        }
    }

    // Iterate over all cells in the grid and start backtracking from each cell
    for (let i = 0; i < grid.length; i++) {
        for (let j = 0; j < grid[0].length; j++) {
            // Check if the cell has gold
            if (grid[i][j] !== 0) {
                // Start backtracking from the current cell
                backtrack(i, j, grid[i][j], new Set([`${i},${j}`]));
            }
        }
    }

    return maxGold;
}

function checkStraightLine(coordinates) {
    // calculate the slope between the first two points
    let x0 = coordinates[0][0], y0 = coordinates[0][1];
    let x1 = coordinates[1][0], y1 = coordinates[1][1];
    // check if the line is vertical
    if (x1 - x0 === 0) {
        // check if all points have the same x-coordinate
        for (let i = 2; i < coordinates.length; i++) {
            if (coordinates[i][0] !== x0) return false;
        }
        return true;
    } else {
        // calculate the slope
        let slope = (y1 - y0) / (x1 - x0);
        // check if all points are on the same line
        for (let i = 2; i < coordinates.length; i++) {
            // calculate the slope between the first point and the current point
            let xi = coordinates[i][0], yi = coordinates[i][1];
            // check if the slope is the same
            if ((yi - y0) / (xi - x0) !== slope) return false;
        }
        return true;
    }
}

function circularPermutation(n, start) {
    const size = 1 << n;
    const result = new Array(size);
    for (let i = 0; i < size; i++) {
        // standard reflected binary Gray code, XORed with start so p[0] === start
        // and the sequence is still a valid circular Gray code (wraps with 1-bit change)
        result[i] = start ^ i ^ (i >> 1);
    }
    return result;
}

function f(x, y, function_id) {
