}

function maxLength(arr) {
  function backtrack(index, currentString) {
    // update maximum length if current string length is greater
    maxLengthResult = Math.max(maxLengthResult, currentString.length);
    for (let i = index; i < arr.length; i++) {
      // check if string has unique characters
      if (hasUniqueChars(currentString + arr[i])) {
        // recursively call backtrack with updated string and index
        backtrack(i + 1, currentString + arr[i]);
      }
    }
  }

  function hasUniqueChars(str) {
    // create a set to store unique characters
    let charSet = new Set();
    for (let char of str) {
      // if character is already in set, return false
      if (charSet.has(char)) return false;
      // add character to set
      charSet.add(char);
    }
    // if all characters are unique, return true
    return true;
  }

  let maxLengthResult = 0;
  backtrack(0, "");
  return maxLengthResult;
}

function numberOfSubarrays(nums, k) {
    // Initialize a hashmap to store the prefix sum of odd numbers and their frequencies
    let prefixSumCount = {0: 1};
    let currentSum = 0;
    let count = 0;
    // Iterate through the array and calculate the prefix sum of odd numbers
    for (let i = 0; i < nums.length; i++) {
        // If the current number is odd, increment the prefix sum
        if (nums[i] % 2 !== 0) currentSum++;
        // If the hashmap contains the prefix sum minus k, increment the count by the frequency of that prefix sum
        if (prefixSumCount[currentSum - k]) count += prefixSumCount[currentSum - k];
        // Increment the frequency of the current prefix sum
        prefixSumCount[currentSum] = (prefixSumCount[currentSum] || 0) + 1;
    }
    return count;
}

function balancedString(s) {
    const n = s.length;
    const target = n / 4;
    const count = { 'Q': 0, 'W': 0, 'E': 0, 'R': 0 };
    for (const ch of s) count[ch]++;
    function allBalanced() {
        return count.Q <= target && count.W <= target && count.E <= target && count.R <= target;
    }
    if (allBalanced()) return 0;
    let left = 0, minLen = n;
    for (let right = 0; right < n; right++) {
        count[s[right]]--; // char at `right` is now inside the window (candidate for replacement)
        while (left <= right && allBalanced()) {
            minLen = Math.min(minLen, right - left + 1);
            count[s[left]]++; // shrink window: char at `left` goes back outside
            left++;
        }
    }
    return minLen;
}

/**
 * Restores the contaminated binary tree and returns a finder function.
 * @param {TreeNode} root - root of the contaminated tree (all vals = -1)
 * @return {{find: function(number): boolean}} object with a find method
 */
function FindElements(root) {
    const values = new Set();                     // store all recovered values

    // DFS restores values and fills the set
    function dfs(node, val) {
        if (!node) return;
        node.val = val;                           // recover original value
        values.add(val);                          // remember it
        dfs(node.left, 2 * val + 1);              // left child rule
        dfs(node.right, 2 * val + 2);             // right child rule
    }
    dfs(root, 0);                                 // start from root = 0

    // returned object provides the required find method
    return {
        find: function(target) {
            return values.has(target);            // O(1) lookup
        }
    };
}

function maxSumDivisibleByThree(nums) {
    // dp[r] = maximum sum with remainder r when divided by 3
    const dp = [0, -Infinity, -Infinity];

    for (let i = 0; i < nums.length; i++) {
        const cur = nums[i];
        const next = dp.slice();                 // copy current state
        // update dp for each possible remainder
        for (let r = 0; r < 3; r++) {
            if (dp[r] !== -Infinity) {
                const newR = (r + cur) % 3;
                next[newR] = Math.max(next[newR], dp[r] + cur);
            }
        }
        dp[0] = next[0];
        dp[1] = next[1];
        dp[2] = next[2];
    }
    return dp[0]; // maximum sum divisible by 3
}

function shiftGrid(grid, k) {
    const m = grid.length;
    const n = grid[0].length;
    const total = m * n;
    k %= total;                         // effective shifts
    if (k === 0) return grid;           // nothing to do

    const result = Array.from({ length: m }, () => Array(n));

    // map each element to its new position after k shifts
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            const oldIdx = i * n + j;
            const newIdx = (oldIdx + k) % total;
            const newRow = Math.floor(newIdx / n);
            const newCol = newIdx % n;
            result[newRow][newCol] = grid[i][j];
        }
    }
    return result;
}

function countServers(grid) {
    var rows = grid.length;
    var cols = grid[0].length;
    var rowCount = new Array(rows).fill(0);
    var colCount = new Array(cols).fill(0);

    // count servers in each row and column
    for (var i = 0; i < rows; i++) {
        for (var j = 0; j < cols; j++) {
            if (grid[i][j] === 1) {
                rowCount[i]++;
                colCount[j]++;
            }
        }
    }

    var answer = 0;
    // count servers that share a row or column with another server
    for (var i = 0; i < rows; i++) {
        for (var j = 0; j < cols; j++) {
            if (grid[i][j] === 1 && (rowCount[i] > 1 || colCount[j] > 1)) {
                answer++;
            }
        }
    }
    return answer;
}

function suggestedProducts(products, searchWord) {
    // 1. sort products lexicographically
    products.sort();

    const result = [];
    const n = products.length;

    // 2. iterate over each prefix of searchWord
    for (let i = 1; i <= searchWord.length; i++) {
        const prefix = searchWord.slice(0, i);

        // binary search: first index >= prefix
        let left = 0, right = n;
        while (left < right) {
            const mid = (left + right) >> 1;
            if (products[mid] < prefix) left = mid + 1;
            else right = mid;
        }

        const suggestions = [];
        // collect up to three products that start with the prefix
        for (let j = left; j < Math.min(left + 3, n); j++) {
            if (products[j].startsWith(prefix)) suggestions.push(products[j]);
            else break; // further strings cannot match the prefix
        }
        result.push(suggestions);
    }
    return result;
}

function minTimeVisitAllPoints(points) {
    let total = 0;                                   // accumulator
    for (let i = 1; i < points.length; i++) {       // iterate over consecutive pairs
        const dx = Math.abs(points[i][0] - points[i - 1][0]);
        const dy = Math.abs(points[i][1] - points[i - 1][1]);
        total += Math.max(dx, dy);                   // time for this segment
    }
    return total;
}

function numWays(steps, arrLen) {
    const MOD = 1_000_000_007;
    // reachable positions are limited by array size and by steps/2
    const maxPos = Math.min(arrLen - 1, Math.floor(steps / 2));

    let cur = new Array(maxPos + 1).fill(0);
    cur[0] = 1;                     // start at position 0

    for (let step = 1; step <= steps; step++) {
        const next = new Array(maxPos + 1).fill(0);
        for (let pos = 0; pos <= maxPos; pos++) {
            let ways = cur[pos];                     // stay
            if (pos > 0) ways += cur[pos - 1];       // from left
            if (pos < maxPos) ways += cur[pos + 1];  // from right
            next[pos] = ways % MOD;                  // store modulo
        }
        cur = next; // move to next step
    }
    return cur[0]; // ways to be back at index 0
}


// TIME: O(steps · min(arrLen, steps)) SPACE: O(min(arrLen, steps))

function minPushBox2(grid) {
    const m = grid.length, n = grid[0].length;
    const dirs = [[-1,0],[1,0],[0,-1],[0,1]];
    let startPlayer, startBox, target;
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] === 'S') startPlayer = [i,j];
            else if (grid[i][j] === 'B') startBox = [i,j];
            else if (grid[i][j] === 'T') target = [i,j];
        }
    }
    function reachable(px, py, tx, ty, bx, by) {
        if (px === tx && py === ty) return true;
        const q = [[px,py]];
        const seen = new Set([px+','+py]);
        let head = 0;
        while (head < q.length) {
            const [x,y] = q[head++];
            for (const [dx,dy] of dirs) {
                const nx = x+dx, ny = y+dy;
                const key = nx+','+ny;
                if (nx>=0 && nx<m && ny>=0 && ny<n && !seen.has(key)) {
                    if (grid[nx][ny] !== '#' && !(nx===bx && ny===by)) {
                        if (nx===tx && ny===ty) return true;
                        seen.add(key);
                        q.push([nx,ny]);
                    }
                }
            }
        }
        return false;
    }
    const startState = [startBox[0], startBox[1], startPlayer[0], startPlayer[1]];
    const q = [[0, startState]];
