            visited[backward] = true;
            queue.push(backward);
        }
    }
    return false;
}

function findZeroSumArray(n) {
    const result = [];
    if (n % 2 === 0) {
        for (let i = 1; i <= n / 2; i++) {
            result.push(i);
            result.push(-i);
        }
    } else {
        if (n === 1) {
            result.push(0);
        } else if (n === 3) {
            result.push(-1, 0, 1);
        } else {
            result.push(-1, 1);
            let sumPos = 0;
            for (let i = 3; i <= n - 1; i++) {
                result.push(i);
                sumPos += i;
            }
            result.push(-sumPos);
        }
    }
    result.sort((a, b) => a - b);
    return result;
}

function verbalArithmeticPuzzle(words, result) {
    const letters = new Set();
    for (const w of words) for (const ch of w) letters.add(ch);
    for (const ch of result) letters.add(ch);
    if (letters.size > 10) return false;

    const leading = new Set();
    for (const w of words) if (w.length > 1) leading.add(w[0]);
    if (result.length > 1) leading.add(result[0]);

    const assign = new Map();
    const used = new Set();
    const maxLen = Math.max(result.length, ...words.map(w => w.length));

    const dfs = (col, carry) => {
        if (col === maxLen) return carry === 0;

        const assignAdd = (i, curSum) => {
            if (i === words.length) {
                const resCh = col < result.length ? result[result.length - 1 - col] : null;
                const total = curSum + carry;
                const neededDigit = total % 10;
                const nextCarry = Math.floor(total / 10);

                if (resCh === null) {
                    if (neededDigit !== 0) return false;
                    return dfs(col + 1, nextCarry);
                }
                if (assign.has(resCh)) {
                    if (assign.get(resCh) !== neededDigit) return false;
                    return dfs(col + 1, nextCarry);
                }
                if (used.has(neededDigit)) return false;
                if (neededDigit === 0 && leading.has(resCh)) return false;

                assign.set(resCh, neededDigit);
                used.add(neededDigit);
                if (dfs(col + 1, nextCarry)) return true;
                assign.delete(resCh);
                used.delete(neededDigit);
                return false;
            }

            const w = words[i];
            if (col >= w.length) return assignAdd(i + 1, curSum);

            const ch = w[w.length - 1 - col];
            if (assign.has(ch)) return assignAdd(i + 1, curSum + assign.get(ch));

            for (let d = 0; d <= 9; d++) {
                if (used.has(d)) continue;
                if (d === 0 && leading.has(ch)) continue;
                assign.set(ch, d);
                used.add(d);
                if (assignAdd(i + 1, curSum + d)) return true;
                assign.delete(ch);
                used.delete(d);
            }
            return false;
        };

        return assignAdd(0, 0);
    };

    return dfs(0, 0);
}

function xorQueries(arr, queries) {
    const n = arr.length;
    const prefix = new Array(n + 1);
    prefix[0] = 0;                                   // build prefix xor
    for (let i = 0; i < n; i++) {
        prefix[i + 1] = prefix[i] ^ arr[i];
    }

    const answers = new Array(queries.length);
    for (let i = 0; i < queries.length; i++) {
        const [l, r] = queries[i];
        answers[i] = prefix[r + 1] ^ prefix[l];      // xor of subarray [l, r]
    }
    return answers;
}

function decompressRLElist(nums) {
    const result = [];                              // output array
    for (let i = 0; i < nums.length; i += 2) {
        const freq = nums[i];
        const val = nums[i + 1];
        for (let j = 0; j < freq; j++) {            // repeat each value freq times
            result.push(val);
        }
    }
    return result;
}

function getWatchedVideosByFriends(watchedVideos, friends, id, level) {
    // BFS to find friends at the exact distance 'level'
    const n = friends.length;
    const visited = new Array(n).fill(false);
    const queue = [id];
    visited[id] = true;
    let depth = 0;

    while (queue.length && depth < level) {
        const size = queue.length;
        for (let i = 0; i < size; i++) {
            const cur = queue.shift();
            for (const nb of friends[cur]) {
                if (!visited[nb]) {
                    visited[nb] = true;
                    queue.push(nb);
                }
            }
        }
        depth++;
    }

    // count videos of people in the queue (they are exactly at distance 'level')
    const freq = Object.create(null);
    for (const person of queue) {
        for (const video of watchedVideos[person]) {
            freq[video] = (freq[video] || 0) + 1;
        }
    }

    // sort by frequency then alphabetically
    const result = Object.entries(freq)
        .sort((a, b) => a[1] === b[1] ? a[0].localeCompare(b[0]) : a[1] - b[1])
        .map(pair => pair[0]);

    return result;
}

function minInsertions(s) {
    var n = s.length;
    var rev = s.split('').reverse().join('');
    var prev = new Uint16Array(n + 1);
    var curr = new Uint16Array(n + 1);
    // DP for LCS using O(n) space
    for (var i = 1; i <= n; i++) {
        for (var j = 1; j <= n; j++) {
            if (s[i - 1] === rev[j - 1]) {
                curr[j] = prev[j - 1] + 1;
            } else {
                curr[j] = Math.max(prev[j], curr[j - 1]);
            }
        }
        var tmp = prev; prev = curr; curr = tmp; // swap rows
    }
    var lps = prev[n];               // longest palindromic subsequence length
    return n - lps;                  // min insertions = n - LPS
}

function sumEvenGrandparent(root) {
    let total = 0;                                   // accumulator

    function dfs(node, parent, grandparent) {
        if (!node) return;
        if (grandparent && grandparent.val % 2 === 0) // main logic: add if grandparent is even
            total += node.val;
        dfs(node.left, node, parent);
        dfs(node.right, node, parent);
    }

    dfs(root, null, null);
    return total;
}

function distinctEchoSubstrings(text) {
    const n = text.length;
    const result = new Set();
    for (let len = 2; len <= n; len += 2) {
        const half = len / 2;
        for (let i = 0; i + len <= n; i++) {
            const a = text.substring(i, i+half);
            const b = text.substring(i+half, i+len);
            if (a === b) result.add(a+b);
        }
    }
    return result.size;
}

function matrixBlockSum(mat, k) {
    const m = mat.length;
    const n = mat[0].length;

    // build prefix sum (m+1)×(n+1)
    const pref = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            pref[i + 1][j + 1] = mat[i][j] + pref[i][j + 1] + pref[i + 1][j] - pref[i][j];
        }
    }

    const answer = Array.from({ length: m }, () => new Array(n));
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            const top = Math.max(0, i - k);
            const bottom = Math.min(m - 1, i + k);
            const left = Math.max(0, j - k);
            const right = Math.min(n - 1, j + k);
            // rectangle sum via prefix sums
            answer[i][j] = pref[bottom + 1][right + 1] - pref[top][right + 1] - pref[bottom + 1][left] + pref[top][left];
        }
    }
    return answer;
}

function minFlips(a, b, c) {
    let flips = 0;
    for (let i = 0; i < 32; i++) {                     // iterate over all bit positions
        const mask = 1 << i;
        const bitA = (a & mask) >>> i;                 // current bits of a, b, c
        const bitB = (b & mask) >>> i;
        const bitC = (c & mask) >>> i;
        if (bitC === 1) {                              // target bit is 1
            if (bitA === 0 && bitB === 0) flips += 1; // need one 1 among a or b
        } else {                                       // target bit is 0
            flips += bitA + bitB;                      // each 1 must be flipped to 0
        }
    }
    return flips;
}

function sumNoZeroIntegers(n) {
    // helper: returns true if x contains a zero digit
    function hasZero(x) {
        while (x > 0) {
            if (x % 10 === 0) return true;
            x = Math.floor(x / 10);
        }
        return false;
    }

    // main logic: try every possible a until both a and b are no‑zero
    for (let a = 1; a < n; ++a) {
        const b = n - a;
        if (!hasZero(a) && !hasZero(b)) {
            return [a, b];
        }
    }
    // According to the problem statement this line is never reached
    return [];
}

function minimumDistanceToTypeAWordUsingTwoFingers(word) {
    if (!word) return 0;
    const INF = 1e9;
    const COLS = 6;
    const NONE = 26;

    const manhattan = (a, b) => {
        const ra = Math.floor(a / COLS), ca = a % COLS;
        const rb = Math.floor(b / COLS), cb = b % COLS;
        return Math.abs(ra - rb) + Math.abs(ca - cb);
    };

    let dp = Array.from({length: 27}, () => new Array(27).fill(INF));
    dp[NONE][NONE] = 0;

    for (const ch of word) {
        const cur = ch.charCodeAt(0) - 65;
        const ndp = Array.from({length: 27}, () => new Array(27).fill(INF));
        for (let p1 = 0; p1 < 27; p1++) {
            const row = dp[p1];
            for (let p2 = 0; p2 < 27; p2++) {
                const curCost = row[p2];
                if (curCost === INF) continue;
                let add = p1 === NONE ? 0 : manhattan(p1, cur);
                let newCost = curCost + add;
                if (newCost < ndp[cur][p2]) ndp[cur][p2] = newCost;
                add = p2 === NONE ? 0 : manhattan(p2, cur);
                newCost = curCost + add;
                if (newCost < ndp[p1][cur]) ndp[p1][cur] = newCost;
            }
        }
        dp = ndp;
    }

    let answer = INF;
    for (const row of dp) for (const val of row) if (val < answer) answer = val;
    return answer;
}

function makeConnected(n, connections) {
    // If there are not enough cables, impossible to connect all computers
    if (connections.length < n - 1) return -1;

    const parent = new Array(n);
    const rank = new Array(n).fill(0);
    for (let i = 0; i < n; i++) parent[i] = i;

    function find(x) {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]]; // path compression
            x = parent[x];
        }
        return x;
    }

    function union(a, b) {
        const rootA = find(a);
        const rootB = find(b);
        if (rootA === rootB) return false; // already in same set
        if (rank[rootA] < rank[rootB]) parent[rootA] = rootB;
        else if (rank[rootA] > rank[rootB]) parent[rootB] = rootA;
        else {
            parent[rootB] = rootA;
            rank[rootA]++;
        }
        return true;
    }

    let extraEdges = 0;
    for (const [u, v] of connections) {
        if (!union(u, v)) extraEdges++; // count redundant cables
    }

    // count distinct components
    const components = new Set();
    for (let i = 0; i < n; i++) components.add(find(i));

    const needed = components.size - 1;
    return extraEdges >= needed ? needed : -1;
}
