function maximum69Number(num) {
    var n = num;
    var place = 1;               // current digit place (1,10,100,...)
    var mostSignificantSix = -1; // place of the leftmost 6

    // find the most significant digit equal to 6
    while (n > 0) {
        var digit = n % 10;
        if (digit === 6) {
            mostSignificantSix = place; // overwrite to keep the highest place
        }
        n = Math.floor(n / 10);
        place *= 10;
    }

    if (mostSignificantSix === -1) return num; // no 6 found
    return num + 3 * mostSignificantSix;       // change that 6 to 9 (9‑6 = 3)
}

function printVertically(s) {
    const words = s.split(' ');
    let maxLen = 0;
    for (let w of words) if (w.length > maxLen) maxLen = w.length; // find longest word

    const result = [];
    for (let i = 0; i < maxLen; i++) {               // iterate over columns
        let col = '';
        for (let w of words) {                       // build column string
            col += i < w.length ? w[i] : ' ';
        }
        col = col.replace(/\s+$/g, '');               // trim trailing spaces
        result.push(col);
    }
    return result;
}

function maxValueAfterReverse(nums) {
    const n = nums.length;
    if (n < 2) return 0;
    let base = 0;
    for (let i = 0; i < n - 1; ++i) {
        base += Math.abs(nums[i] - nums[i + 1]);
    }
    let bestGain = 0;
    // Gains from moving an element to the start or end
    for (let i = 0; i < n - 1; ++i) {
        const cur = Math.abs(nums[i] - nums[i + 1]);
        const gainFront = Math.abs(nums[i] - nums[0]) - cur;
        const gainBack = Math.abs(nums[i + 1] - nums[n - 1]) - cur;
        if (gainFront > bestGain) bestGain = gainFront;
        if (gainBack > bestGain) bestGain = gainBack;
    }
    // Gains from internal reversal
    let maxOfMins = -Infinity; // max of min(a[i], a[i+1])
    let minOfMaxs = Infinity;  // min of max(a[i], a[i+1])
    for (let i = 0; i < n - 1; ++i) {
        const a = nums[i];
        const b = nums[i + 1];
        const mn = Math.min(a, b);
        const mx = Math.max(a, b);
        if (mn > maxOfMins) maxOfMins = mn;
        if (mx < minOfMaxs) minOfMaxs = mx;
        const internalGain = 2 * (maxOfMins - minOfMaxs);
        if (internalGain > bestGain) bestGain = internalGain;
    }
    return base + bestGain;
}

/**
 * Deletes all leaf nodes with value `target` from the binary tree.
 * @param {TreeNode|null} root - root of the binary tree
 * @param {number} target - value to delete
 * @return {TreeNode|null} - new root after deletions
 */
function deleteLeaves(root, target) {
    // post‑order recursion: prune children before deciding about the current node
    function prune(node) {
        if (node === null) return null;                     // base case
        node.left  = prune(node.left);                      // process left subtree
        node.right = prune(node.right);                     // process right subtree
        // if node is now a leaf and matches target, delete it
        if (node.left === null && node.right === null && node.val === target) {
            return null;
        }
        return node;                                        // keep node
    }
    return prune(root);
}

function minTaps(n, ranges) {
    // build maxReach[s] = farthest right end of any tap covering s
    const maxReach = new Array(n + 1).fill(0);
    for (let i = 0; i <= n; i++) {
        const left = Math.max(0, i - ranges[i]);
        const right = Math.min(n, i + ranges[i]);
        if (right > maxReach[left]) maxReach[left] = right;
    }

    let taps = 0;          // number of opened taps
    let curEnd = 0;        // rightmost point already covered
    let farthest = 0;      // farthest point we can reach from positions ≤ i

    // MAIN LOGIC: greedy expansion of the covered interval
    for (let i = 0; i <= n; i++) {
        farthest = Math.max(farthest, maxReach[i]);   // best we can reach from i
        if (i === curEnd) {                           // need a new tap
            taps++;
            curEnd = farthest;                         // extend coverage
            if (curEnd <= i) return -1;                // cannot move forward
        }
        if (curEnd >= n) break;                       // whole garden covered
    }
    return curEnd >= n ? taps : -1;
}

function breakPalindrome(palindrome) {
    const n = palindrome.length;
    if (n === 1) return "";                         // length 1 cannot be broken

    const chars = palindrome.split('');
    // replace first non-'a' in the left half with 'a'
    for (let i = 0; i < Math.floor(n / 2); i++) {
        if (chars[i] !== 'a') {
            chars[i] = 'a';
            return chars.join('');
        }
    }
    // all left half are 'a' → change the last character to 'b'
    chars[n - 1] = 'b';
    return chars.join('');
}

function diagonalSort(mat) {
    const rows = mat.length;
    if (rows === 0) return mat;
    const cols = mat[0].length;

    // process diagonals that start in the first row
    for (let startCol = 0; startCol < cols; startCol++) {
        let r = 0, c = startCol;
        const diag = [];

        // collect diagonal elements
        while (r < rows && c < cols) {
            diag.push(mat[r][c]);
            r++; c++;
        }

        diag.sort((a, b) => a - b);   // sort the collected values

        // write them back
        r = 0; c = startCol;
        let idx = 0;
        while (r < rows && c < cols) {
            mat[r][c] = diag[idx++];
            r++; c++;
        }
    }

    // process diagonals that start in the first column (skip the top‑left cell)
    for (let startRow = 1; startRow < rows; startRow++) {
        let r = startRow, c = 0;
        const diag = [];

        // collect diagonal elements
        while (r < rows && c < cols) {
            diag.push(mat[r][c]);
            r++; c++;
        }

        diag.sort((a, b) => a - b);   // sort the collected values

        // write them back
        r = startRow; c = 0;
        let idx = 0;
        while (r < rows && c < cols) {
            mat[r][c] = diag[idx++];
            r++; c++;
        }
    }

    return mat;
}


