function removePalindromeSub(s) {
    // if the string is empty no steps are needed
    if (s.length === 0) return 0;

    // check whether the whole string is a palindrome
    let left = 0, right = s.length - 1;
    while (left < right) {
        if (s[left] !== s[right]) break;   // not a palindrome
        left++;
        right--;
    }

    // if we never broke out, the string is a palindrome
    return (left >= right) ? 1 : 2;        // otherwise at most two steps are enough
}

function filterRestaurants(restaurants, veganFriendly, maxPrice, maxDistance) {
    // filter according to the three criteria
    const filtered = [];
    for (let i = 0; i < restaurants.length; i++) {
        const [id, rating, vegan, price, distance] = restaurants[i];
        if ((veganFriendly === 0 || vegan === 1) && price <= maxPrice && distance <= maxDistance) {
            filtered.push([id, rating]);          // keep only id and rating for sorting
        }
    }
    // sort by rating descending, then id descending
    filtered.sort((a, b) => {
        if (b[1] !== a[1]) return b[1] - a[1];
        return b[0] - a[0];
    });
    // extract the ids in the required order
    const result = new Array(filtered.length);
    for (let i = 0; i < filtered.length; i++) result[i] = filtered[i][0];
    return result;
}

function findTheCity(n, edges, distanceThreshold) {
    // initialise distance matrix
    const dist = Array.from({ length: n }, () => Array(n).fill(Infinity));
    for (let i = 0; i < n; ++i) dist[i][i] = 0;
    for (const [u, v, w] of edges) {
        dist[u][v] = w;
        dist[v][u] = w;
    }

    // Floyd‑Warshall: compute shortest paths between all pairs
    for (let k = 0; k < n; ++k) {
        for (let i = 0; i < n; ++i) {
            const dik = dist[i][k];
            if (dik === Infinity) continue;               // skip unreachable intermediate
            for (let j = 0; j < n; ++j) {
                const newDist = dik + dist[k][j];
                if (newDist < dist[i][j]) dist[i][j] = newDist;
            }
        }
    }

    // count reachable neighbours for each city and keep the best answer
    let bestCity = -1;
    let bestCount = Infinity;
    for (let i = 0; i < n; ++i) {
        let cnt = 0;
        for (let j = 0; j < n; ++j) {
            if (i !== j && dist[i][j] <= distanceThreshold) ++cnt;
        }
        if (cnt < bestCount || (cnt === bestCount && i > bestCity)) {
            bestCount = cnt;
            bestCity = i;
        }
    }
    return bestCity;
}

function minDifficulty(jobDifficulty, d) {
    const n = jobDifficulty.length;
    if (n < d) return -1;
    const INF = Number.MAX_SAFE_INTEGER;
    const dp = Array.from({ length: n + 1 }, () => Array(d + 1).fill(INF));
    dp[0][0] = 0;
    for (let day = 1; day <= d; day++) {
        for (let i = day; i <= n; i++) {
            let max = 0;
            for (let j = i - 1; j >= day - 1; j--) {
                if (jobDifficulty[j] > max) max = jobDifficulty[j];
                const cand = dp[j][day - 1] + max;
                if (cand < dp[i][day]) dp[i][day] = cand;
            }
        }
    }
    const ans = dp[n][d];
    return ans === INF ? -1 : ans;
}

function rankTransform(arr) {
  // keep only distinct values and sort them
  const sortedUnique = [...new Set(arr)].sort((a, b) => a - b);
  const rankMap = new Map();                     // value → rank
  for (let i = 0; i < sortedUnique.length; i++) {
    rankMap.set(sortedUnique[i], i + 1);         // smallest gets rank 1
  }
  // replace each element by its rank
  return arr.map(v => rankMap.get(v));
}

function kWeakestRows(mat, k) {
  // count soldiers in a row using binary search
  function countOnes(row) {
    let lo = 0, hi = row.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (row[mid] === 1) lo = mid + 1;
      else hi = mid;
    }
    return lo;
  }

  // max‑heap comparator (greater soldier count or larger index)
  function greater(a, b) {
    if (a[0] !== b[0]) return a[0] > b[0];
    return a[1] > b[1];
  }

  // push into max‑heap
  function heapPush(heap, node) {
    heap.push(node);
    let i = heap.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (greater(heap[p], heap[i])) break;
      [heap[p], heap[i]] = [heap[i], heap[p]];
      i = p;
    }
  }

  // pop max from heap
  function heapPop(heap) {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length) {
      heap[0] = last;
      let i = 0;
      while (true) {
        const l = i * 2 + 1,
          r = i * 2 + 2;
        let largest = i;
        if (l < heap.length && !greater(heap[largest], heap[l])) largest = l;
        if (r < heap.length && !greater(heap[largest], heap[r])) largest = r;
        if (largest === i) break;
        [heap[i], heap[largest]] = [heap[largest], heap[i]];
        i = largest;
      }
    }
    return top;
  }

  const heap = []; // maintain max‑heap of size k
  for (let i = 0; i < mat.length; i++) {
    const soldiers = countOnes(mat[i]); // main logic: count soldiers
    heapPush(heap, [soldiers, i]);      // main logic: push row info
    if (heap.length > k) heapPop(heap); // main logic: keep only k weakest
  }

  // extract, sort by soldiers then index, and return indices
  return heap
    .sort((a, b) => (a[0] - b[0]) || (a[1] - b[1]))
    .map(pair => pair[1]);
}

function maxProduct(root) {
    const MOD = 1000000007n;
    // first DFS: compute the sum of the WHOLE tree only (root's subtree sum)
    function sumSub(node) {
        if (!node) return 0n;
        return BigInt(node.val) + sumSub(node.left) + sumSub(node.right);
    }
    const total = sumSub(root);

    let best = 0n;
    function dfs(node) {
        if (!node) return 0n;
        const left = dfs(node.left);
        const right = dfs(node.right);
