    const n = arr.length;
    const memo = new Array(n).fill(0);          // dp[i] = 0 means not computed yet

    function dfs(i) {
        if (memo[i] !== 0) return memo[i];      // already known

        let best = 1;                           // sequence containing only i

        // explore reachable positions within distance d while respecting height condition
        for (let step = 1; step <= d && i - step >= 0; step++) {
            if (arr[i] > arr[i - step]) {
