function isPossible(target) {
    // ---------- heap implementation ----------
    const heap = [];
    const swap = (i, j) => { const t = heap[i]; heap[i] = heap[j]; heap[j] = t; };
    const push = (val) => {
        heap.push(val);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p] >= heap[i]) break;
            swap(i, p);
            i = p;
        }
    };
    const pop = () => {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            let i = 0;
            while (true) {
                let l = i * 2 + 1, r = i * 2 + 2, largest = i;
                if (l < heap.length && heap[l] > heap[largest]) largest = l;
                if (r < heap.length && heap[r] > heap[largest]) largest = r;
                if (largest === i) break;
                swap(i, largest);
                i = largest;
            }
        }
        return top;
    };
    // -----------------------------------------

    // trivial case
    if (target.length === 1) return target[0] === 1;

    let total = 0;
    for (const v of target) { push(v); total += v; }

    while (true) {
        const max = pop();                 // get current largest element
        const rest = total - max;          // sum of the remaining elements

        // if the array is already all ones
        if (max === 1 || rest === 1) return true;

        // previous value of the max element
        const prev = max % rest || rest;   // handle exact multiples

        // impossible situations
        if (prev === 0 || prev === max) return false;

        // update structures for next iteration
        push(prev);
        total = rest + prev;
    }
}

