}

function maxEvents(events) {
    events.sort((a, b) => a[0] - b[0]);               // sort by start day

    const heap = [];                                 // min‑heap of end days
    const push = (x) => {                           // heap insert
        heap.push(x);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p] <= heap[i]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]];
            i = p;
        }
    };
    const pop = () => {                             // heap extract‑min
        if (!heap.length) return null;
        const min = heap[0];
        const last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            let i = 0;
            while (true) {
                let l = i * 2 + 1,
                    r = i * 2 + 2,
                    s = i;
                if (l < heap.length && heap[l] < heap[s]) s = l;
                if (r < heap.length && heap[r] < heap[s]) s = r;
                if (s === i) break;
                [heap[i], heap[s]] = [heap[s], heap[i]];
                i = s;
            }
        }
        return min;
    };

    let day = 0, i = 0, attended = 0;
    while (i < events.length || heap.length) {
        if (!heap.length) day = events[i][0];       // jump to next start day if idle

        while (i < events.length && events[i][0] <= day) {
            push(events[i][1]);                      // add all events starting today
            i++;
        }
        while (heap.length && heap[0] < day) {
            pop();                                    // discard already expired events
        }
        if (heap.length) {
            pop();                                    // attend event with earliest end
            attended++;
            day++;                                    // move to next day
        }
    }
    return attended;
}

