function countOrders(n) {
    const MOD = 1000000007n;                     // prime modulus as BigInt

    // compute (2n)! % MOD
    let fact = 1n;
    for (let i = 2n; i <= 2n * BigInt(n); i++) { // i runs from 2 to 2n
        fact = (fact * i) % MOD;
    }

    // fast exponentiation: returns (base^exp) % MOD
    function modPow(base, exp) {
        let result = 1n;
        let b = base % MOD;
        let e = BigInt(exp);
        while (e > 0) {
            if (e & 1n) result = (result * b) % MOD; // multiply when bit is 1
            b = (b * b) % MOD;
            e >>= 1n;
        }
        return result;
    }

    const pow2 = modPow(2n, n);                  // 2^n % MOD
    const invPow2 = modPow(pow2, MOD - 2n);      // (2^n)^{-1} % MOD using Fermat

    return Number((fact * invPow2) % MOD);       // result fits into 32‑bit integer
}

