function validateBinaryTreeNodes(n, leftChild, rightChild) {
    // compute indegree of each node
    var indegree = new Array(n).fill(0);
    for (var i = 0; i < n; i++) {
        var l = leftChild[i];
        var r = rightChild[i];
        if (l !== -1) indegree[l]++;
        if (r !== -1) indegree[r]++;
    }

    // find the unique root (indegree 0) and ensure no node has >1 parent
    var root = -1;
    for (var i = 0; i < n; i++) {
        if (indegree[i] === 0) {
            if (root !== -1) return false; // more than one root
            root = i;
        } else if (indegree[i] > 1) {
            return false; // node has multiple parents
        }
    }
    if (root === -1) return false; // no root found

    // traverse from the root and count visited nodes
    var stack = [root];
    var visited = new Array(n).fill(false);
    visited[root] = true;
    var visitedCount = 0;

    while (stack.length) {
        var node = stack.pop();
        visitedCount++;

        var l = leftChild[node];
        var r = rightChild[node];

        if (l !== -1) {
            if (visited[l]) return false; // cycle or duplicate edge
            visited[l] = true;
            stack.push(l);
        }
        if (r !== -1) {
            if (visited[r]) return false;
            visited[r] = true;
            stack.push(r);
        }
    }

    return visitedCount === n; // all nodes must be reachable
}

