function largestMultipleOfThree(digits) {
    // count occurrences of each digit
    const cnt = Array(10).fill(0);
    let sum = 0;
    for (let d of digits) {
        cnt[d]++;               // O(1) per digit
        sum += d;
    }

    const rem = sum % 3;        // current remainder of the whole set

    // helper: try to remove `need` smallest digits whose value % 3 == target
    function tryRemove(target, need) {
        for (let d = 0; d <= 9 && need > 0; d++) {
            if (d % 3 === target) {
                const take = Math.min(cnt[d], need);
                cnt[d] -= take;
                need -= take;
            }
