        return need === 0;      // true if we succeeded
    }

    // fix the remainder using the greedy removal described above
    if (rem === 1) {
        if (!tryRemove(1, 1)) {          // try to drop one digit %3==1
            if (!tryRemove(2, 2)) {      // otherwise drop two digits %3==2
                return "";                // impossible
            }
        }
    } else if (rem === 2) {
        if (!tryRemove(2, 1)) {          // try to drop one digit %3==2
            if (!tryRemove(1, 2)) {      // otherwise drop two digits %3==1
                return "";
            }
        }
    }

    // build the largest number by outputting digits from 9 down to 0
    let result = "";
    for (let d = 9; d >= 0; d--) {
        if (cnt[d] > 0) result += String(d).repeat(cnt[d]);
