        if (!list) return true;               // all list nodes matched
        if (!node) return false;              // tree path ended early
        if (node.val !== list.val) return false; // values differ
        // continue matching down either left or right child
        return match(node.left, list.next) || match(node.right, list.next);
    }

    if (!root) return false;                  // empty tree can't contain the list
    // if current node starts a matching path, return true
    if (match(root, head)) return true;
    // otherwise search in left and right subtrees
    return isSubPath(head, root.left) || isSubPath(head, root.right);
}

function minCost(grid) {
    const m = grid.length, n = grid[0].length;
    const INF = 1 << 30;
    const dist = Array.from({ length: m }, () => Array(n).fill(INF));

    const dirs = [
        [0, 1, 1],   // right
        [0, -1, 2],  // left
        [1, 0, 3],   // down
        [-1, 0, 4]   // up
    ];

    // proper unbounded deque (see explanation for why the fixed-size buffer was broken)
    let deque = [];
    dist[0][0] = 0;
    deque.push([0, 0]);

    while (deque.length) {
        const [x, y] = deque.shift();
        const curCost = dist[x][y];

        for (const [dx, dy, dirVal] of dirs) {
            const nx = x + dx, ny = y + dy;
            if (nx < 0 || nx >= m || ny < 0 || ny >= n) continue;
            const w = (grid[x][y] === dirVal) ? 0 : 1;
            const newCost = curCost + w;
            if (newCost < dist[nx][ny]) {
                dist[nx][ny] = newCost;
                if (w === 0) deque.unshift([nx, ny]);
                else deque.push([nx, ny]);
