        const leftChild = dfs(node.left);   // [leftZig, rightZig] of left child
        const rightChild = dfs(node.right); // [leftZig, rightZig] of right child

        const leftZig = 1 + leftChild[1];   // go left then must go right
        const rightZig = 1 + rightChild[0]; // go right then must go left

        if (leftZig > maxLen) maxLen = leftZig;   // update global answer
        if (rightZig > maxLen) maxLen = rightZig; // update global answer

        return [leftZig, rightZig];          // propagate to parent
    }

    dfs(root);
    return maxLen;
}

function longestEvenVowelSubstring(s) {
    // mask bits: 0‑a, 1‑e, 2‑i, 3‑o, 4‑u
    const firstIdx = new Array(32).fill(Infinity);
    firstIdx[0] = -1;                     // empty prefix has mask 0
    let mask = 0;
    let best = 0;

    for (let i = 0; i < s.length; i++) { // update mask and check earliest occurrence
        const ch = s.charCodeAt(i);
        // toggle the corresponding bit if current char is a vowel
        if (ch === 97) mask ^= 1 << 0;          // 'a'
        else if (ch === 101) mask ^= 1 << 1;    // 'e'
        else if (ch === 105) mask ^= 1 << 2;    // 'i'
        else if (ch === 111) mask ^= 1 << 3;    // 'o'
        else if (ch === 117) mask ^= 1 << 4;    // 'u'

        if (firstIdx[mask] !== Infinity) {
            const length = i - firstIdx[mask];
            if (length > best) best = length;
        } else {
            firstIdx[mask] = i;                  // store first occurrence of this mask
        }
    }
    return best;
}

function generateString(n) {
    // Build a string where each character appears an odd number of times
    if (n % 2 === 1) {                 // n is odd → one character with odd count
        return 'a'.repeat(n);
    } else {                           // n is even → two characters, each odd count
        return 'a'.repeat(n - 1) + 'b'; // (n‑1) is odd, plus one occurrence of 'b'
    }
}

function numberOfPrefixAligned(flips) {
    let maxSeen = 0;      // track the farthest flipped position so far
    let alignedCount = 0;

    for (let i = 0; i < flips.length; i++) {
        if (flips[i] > maxSeen) maxSeen = flips[i];   // update max
        if (maxSeen === i + 1) alignedCount++;        // check prefix‑aligned condition
    }

    return alignedCount;
}

function maxSumBST(root) {
    let maxSum = 0;                                   // best sum found so far

    function dfs(node) {
        if (!node) return {isBST: true, sum: 0, min: Infinity, max: -Infinity};

        const left  = dfs(node.left);                // process left child
        const right = dfs(node.right);               // process right child

        // main logic: check BST property and compute sum if valid
        const isBST = left.isBST && right.isBST &&
                      node.val > left.max && node.val < right.min;

        const sum = isBST ? left.sum + right.sum + node.val : 0;
        if (isBST) maxSum = Math.max(maxSum, sum);

        return {
            isBST,
            sum,
            min: Math.min(node.val, left.min),
            max: Math.max(node.val, right.max)
        };
    }

    dfs(root);
    return maxSum;
}

function numOfMinutes(n, headID, manager, informTime) {
    // Build adjacency list of subordinates for each manager
    var subordinates = Array.from({ length: n }, () => []);
    for (var i = 0; i < n; i++) {
        var mgr = manager[i];
        if (mgr !== -1) subordinates[mgr].push(i);
    }

    // DFS returns the longest time needed to inform the subtree of `emp`
    function dfs(emp) {
        var longest = 0;
        for (var sub of subordinates[emp]) {
            var subTime = dfs(sub);
            if (subTime > longest) longest = subTime;
        }
        return longest + informTime[emp];
    }

    return dfs(headID);
}

function frogPosition(n, edges, t, target) {
    // build adjacency list
    const adj = Array.from({ length: n + 1 }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }

    const queue = [[1, 1, 0]];          // [node, probability, elapsed time]
    const visited = new Array(n + 1).fill(false);
    visited[1] = true;

    while (queue.length) {
        const [node, prob, time] = queue.shift();

        // count neighbours that are still unvisited
        const unvisited = adj[node].filter(v => !visited[v]);

        // MAIN LOGIC: decide if this state gives the final answer
        if (node === target) {
            if (time === t || (time < t && unvisited.length === 0)) {
                return prob;
            }
        }

        if (time === t) continue;       // cannot move further

        const cnt = unvisited.length;
        if (cnt === 0) continue;        // dead end, frog stays here

        const nextProb = prob / cnt;    // split probability equally
        for (const nb of unvisited) {
            visited[nb] = true;
            queue.push([nb, nextProb, time + 1]);
        }
    }
    return 0;                           // target never reached with required conditions
}

function CustomStack(maxSize) {
    const stack = [];                     // holds the real values
    const inc   = new Array(maxSize).fill(0); // lazy increments

    return {
        push: function(x) {               // O(1)
            if (stack.length < maxSize) stack.push(x);
        },

        pop: function() {                // O(1)
            if (stack.length === 0) return -1;
            const i   = stack.length - 1;
            const val = stack.pop() + inc[i]; // apply pending increment
            if (i > 0) inc[i - 1] += inc[i];   // propagate to next element
            inc[i] = 0;                         // clear used slot
            return val;
        },

        increment: function(k, val) {    // O(1)
            const i = Math.min(k, stack.length) - 1;
            if (i >= 0) inc[i] += val;    // lazy add to bottom k elements
        }
    };
}

function getTargetCopy(original, cloned, target) {
    // DFS simultaneously traversing original and cloned trees
    if (original === null) return null;
    if (original === target) return cloned;
    const leftResult = getTargetCopy(original.left, cloned.left, target);
    if (leftResult !== null) return leftResult;
    return getTargetCopy(original.right, cloned.right, target);
}

function balanceBST(root) {
    // collect values in sorted order
    const sorted = [];
    function inorder(node) {
        if (!node) return;
        inorder(node.left);
        sorted.push(node.val);
        inorder(node.right);
    }
    inorder(root);

    // build a balanced BST from the sorted array
    function build(l, r) {
        if (l > r) return null;
        const m = (l + r) >> 1;               // middle index
        const node = { val: sorted[m] };      // create new node
        node.left = build(l, m - 1);
        node.right = build(m + 1, r);
        return node;
    }
    return build(0, sorted.length - 1);
}

function luckyNumbers(matrix) {
    var rowCount = matrix.length;
    var colCount = matrix[0].length;
    var rowMins = new Array(rowCount);          // store min value and its column for each row
    var colMaxes = new Array(colCount).fill(-Infinity); // store max value for each column

    // compute row minima and column maxima in one pass
    for (var i = 0; i < rowCount; i++) {
        var minVal = Infinity, minCol = -1;
        for (var j = 0; j < colCount; j++) {
            var cur = matrix[i][j];
            if (cur < minVal) { minVal = cur; minCol = j; }
            if (cur > colMaxes[j]) colMaxes[j] = cur;
        }
        rowMins[i] = { value: minVal, col: minCol };
    }

    var lucky = [];
    // collect numbers that are row‑min and column‑max
    for (var i = 0; i < rowCount; i++) {
        var info = rowMins[i];
        if (info.value === colMaxes[info.col]) lucky.push(info.value);
    }
    return lucky;
}

function maxPerformance(n, speed, efficiency, k) {
    const MOD = 1_000_000_007;

    // pair each engineer as [efficiency, speed] and sort descending by efficiency
    const engineers = new Array(n);
    for (let i = 0; i < n; i++) engineers[i] = [efficiency[i], speed[i]];
    engineers.sort((a, b) => b[0] - a[0]); // main logic

    // ----- min‑heap implementation for speeds -----
    const heap = [];
    const heapPush = (val) => {
        heap.push(val);
        let idx = heap.length - 1;
        while (idx > 0) {
            const parent = (idx - 1) >> 1;
            if (heap[parent] <= heap[idx]) break;
            [heap[parent], heap[idx]] = [heap[idx], heap[parent]];
            idx = parent;
        }
    };
    const heapPop = () => {
        const min = heap[0];
        const last = heap.pop();
        if (heap.length === 0) return min;
        heap[0] = last;
        let idx = 0;
        while (true) {
            let left = idx * 2 + 1;
            let right = left + 1;
            let smallest = idx;
            if (left < heap.length && heap[left] < heap[smallest]) smallest = left;
            if (right < heap.length && heap[right] < heap[smallest]) smallest = right;
            if (smallest === idx) break;
            [heap[smallest], heap[idx]] = [heap[idx], heap[smallest]];
            idx = smallest;
        }
        return min;
    };
    const heapSize = () => heap.length;
    // ----------------------------------------------

    let sumSpeeds = 0;
    let best = 0;

    for (const [eff, spd] of engineers) {
        heapPush(spd);
        sumSpeeds += spd;
        if (heapSize() > k) {
            sumSpeeds -= heapPop(); // keep only k largest speeds
        }
        const perf = (sumSpeeds * eff) % MOD; // candidate performance
        if (perf > best) best = perf;
    }
    return best;
}

function maxFourPersonGroups(n, reservedSeats) {
  const rowMask = new Map();
  for (let i = 0; i < reservedSeats.length; i++) {
    const row = reservedSeats[i][0];
    const seat = reservedSeats[i][1];
    if (seat >= 2 && seat <= 9) {
      const bit = 1 << (seat - 2);
      rowMask.set(row, (rowMask.get(row) || 0) | bit);
    }
  }
  let result = (n - rowMask.size) * 2;
  for (const mask of rowMask.values()) {
    const leftFree = (mask & 0b1111) === 0;          // seats 2-5
    const middleFree = (mask & 0b111100) === 0;     // seats 4-7
    const rightFree = (mask & 0b11110000) === 0;    // seats 6-9
    if (leftFree && rightFree) {
      result += 2;
    } else if (leftFree || rightFree || middleFree) {
      result += 1;
    }
  }
  return result;
}

function getKth(lo, hi, k) {
    const memo = new Map();          // stores power values already computed
    memo.set(1, 0);

    // recursively compute power with memoisation
    function power(x) {
        if (memo.has(x)) return memo.get(x);
        const next = (x % 2 === 0) ? x / 2 : 3 * x + 1;
        const val = 1 + power(next);
        memo.set(x, val);
        return val;
    }

    const pairs = [];                 // [number, power] for every x in [lo,hi]
    for (let n = lo; n <= hi; n++) {
        pairs.push([n, power(n)]);
    }

    // sort by power, then by number
    pairs.sort((a, b) => a[1] === b[1] ? a[0] - b[0] : a[1] - b[1]); // MAIN LOGIC

    return pairs[k - 1][0];
}

function distanceValue(arr1, arr2, d) {
    // sort arr2 once for binary searching
    arr2.sort((a, b) => a - b);
    let count = 0;

    for (let i = 0; i < arr1.length; i++) {
        const x = arr1[i];
        // binary search: first index with value >= x
        let lo = 0, hi = arr2.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (arr2[mid] < x) lo = mid + 1;
            else hi = mid;
        }
        let ok = true;
        // check element at lo (first >= x)
        if (lo < arr2.length && Math.abs(arr2[lo] - x) <= d) ok = false;
        // check element just before lo (largest < x)
        if (lo > 0 && Math.abs(arr2[lo - 1] - x) <= d) ok = false;
        if (ok) count++;
    }
    return count;
}


