function processQueries(queries, m) {
    var n = queries.length;
    var size = n + m + 2;                 // +2 for 1‑based BIT safety
    var bit = new Array(size).fill(0);

    function add(i, delta) {              // BIT point update
        for (; i < size; i += i & -i) bit[i] += delta;
    }
    function sum(i) {                     // BIT prefix sum
        var res = 0;
        for (; i > 0; i -= i & -i) res += bit[i];
        return res;
    }

    var pos = new Array(m + 1);            // current index of each value
    for (var v = 1; v <= m; v++) {         // place initial permutation
        var idx = n + v;
        pos[v] = idx;
        add(idx, 1);
    }

    var result = new Array(n);
    var front = n;                         // next free front index (decreasing)

    for (var i = 0; i < n; i++) {          // MAIN LOGIC: handle each query
        var x = queries[i];
        var idx = pos[x];
        result[i] = sum(idx) - 1;          // 0‑based position of x
        add(idx, -1);                      // remove from old spot
        add(front, 1);                     // insert at front
        pos[x] = front;                    // update stored index
        front--;                           // move front pointer leftwards
    }
    return result;
}

