function numSteps(s) {
    let steps = 0;          // total steps performed
    let carry = 0;          // 0 or 1, result of previous add‑1

    // process from rightmost bit down to the second bit
    for (let i = s.length - 1; i > 0; i--) {
        const bit = s.charCodeAt(i) - 48;   // 0 or 1
        const sum = bit + carry;            // effective bit after previous carry

        // main logic: decide how many operations this bit contributes
        if (sum === 1) {          // odd → add 1 (creates carry) then divide
            steps += 2;
            carry = 1;
        } else {                  // even (sum 0 or 2) → only divide
            steps += 1;
            // carry stays unchanged (0 stays 0, 1 stays 1)
        }
    }

    steps += carry;   // possible final step for the leading '1'
    return steps;
}

function longestDiverseString(a, b, c) {
    let result = '';
    const pool = [['a', a], ['b', b], ['c', c]];   // remaining counts

    while (true) {
        // sort letters by remaining count (largest first)
        pool.sort((x, y) => y[1] - x[1]);

        // no letters left → finished
        if (pool[0][1] === 0) break;

        // if the two last chars are the same as the most frequent letter,
        // we must try the second most frequent one
        if (result.length >= 2 &&
            result[result.length - 1] === pool[0][0] &&
            result[result.length - 2] === pool[0][0]) {

            if (pool[1][1] === 0) break;          // nothing else to use
            result += pool[1][0];
            pool[1][1]--;                         // use one of the second letter
            continue;
        }

        // we can use the most frequent letter, but at most 2 and
        // at most 1 if the previous char is the same
        const maxAdd = result.endsWith(pool[0][0]) ? 1 : 2;
        const use = Math.min(pool[0][1], maxAdd);
        result += pool[0][0].repeat(use);
        pool[0][1] -= use;
    }

    return result;
}

