function minFibonacciNumbers(k) {
    // build all Fibonacci numbers ≤ k (starting with 1, 2)
    const fib = [1, 2];
    while (fib[fib.length - 1] + fib[fib.length - 2] <= k) {
        fib.push(fib[fib.length - 1] + fib[fib.length - 2]);
    }

    let count = 0;
    while (k > 0) {
        // binary search the greatest Fibonacci ≤ k
        let lo = 0, hi = fib.length - 1;
        while (lo < hi) {
            const mid = Math.floor((lo + hi + 1) / 2);
            if (fib[mid] <= k) lo = mid; else hi = mid - 1;
        }
        k -= fib[lo];   // use that Fibonacci number
        count++;        // one number added to the sum
    }
    return count;
}

function restoreArray(s, k) {
    const MOD = 1000000007;
    const n = s.length;
    const maxLen = k.toString().length;          // digits of k

    const dp = new Array(n + 1).fill(0);
    dp[0] = 1;

    for (let i = 1; i <= n; i++) {
        // try all possible starts of the last number
        for (let j = i - 1; j >= 0 && i - j <= maxLen; j--) {
            if (s[j] === '0') continue;           // no leading zero
            const num = Number(s.slice(j, i));    // length ≤ maxLen
            if (num > k) continue;                // exceeds k
            dp[i] = (dp[i] + dp[j]) % MOD;         // main DP transition
        }
    }
    return dp[n];
}



