function getHappyString(n, k) {
    const total = 3 * (1 << (n - 1));          // total happy strings
    if (k > total) return "";                  // not enough strings

    const letters = ['a', 'b', 'c'];
    let result = '';
    let prev = '';                             // previous character

    for (let i = 0; i < n; i++) {
        const remaining = n - i - 1;           // positions left after this one
        const blockSize = 1 << remaining;      // 2^remaining

        for (let ch of letters) {
            if (ch === prev) continue;         // cannot repeat previous char
            if (k > blockSize) {               // skip whole block
                k -= blockSize;
            } else {                           // this char is the next one
                result += ch;
                prev = ch;
                break;
            }
        }
    }
    return result;
}

