function buildArrayWhereYouCanFindTheMaximumExactlyKComparisons(n, m, k) {
    const MOD = 1000000007n;
    if (k === 0 || k > n || k > m) return 0;

    let dp = Array.from({length: k + 1}, () => new Array(m + 1).fill(0n));
    for (let mx = 1; mx <= m; mx++) dp[1][mx] = 1n;

    for (let step = 1; step < n; step++) {
        const ndp = Array.from({length: k + 1}, () => new Array(m + 1).fill(0n));
        for (let cnt = 1; cnt <= k; cnt++) {
            const cur = dp[cnt];
            for (let mx = 1; mx <= m; mx++) {
                if (cur[mx]) ndp[cnt][mx] = (ndp[cnt][mx] + cur[mx] * BigInt(mx)) % MOD;
            }
            if (cnt + 1 <= k) {
                let prefix = 0n;
                for (let newMx = 1; newMx <= m; newMx++) {
                    ndp[cnt + 1][newMx] = (ndp[cnt + 1][newMx] + prefix) % MOD;
                    prefix = (prefix + cur[newMx]) % MOD;
                }
            }
        }
        dp = ndp;
    }

    let sum = 0n;
    for (let mx = 1; mx <= m; mx++) sum = (sum + dp[k][mx]) % MOD;
