function maxScore(s) {
    // total number of '1' in the whole string
    let totalOnes = 0;
    for (let ch of s) if (ch === '1') totalOnes++;

    let zerosLeft = 0;   // zeros in the current left part
    let onesSeen = 0;    // ones in the current left part
    let best = 0;        // best score found so far

    // iterate over all possible split positions (cannot split after last char)
    for (let i = 0; i < s.length - 1; i++) {
        if (s[i] === '0') zerosLeft++; else onesSeen++;   // update counters
        const onesRight = totalOnes - onesSeen;           // ones in the right part
        const score = zerosLeft + onesRight;              // current split score
        if (score > best) best = score;                   // keep the maximum
    }
    return best;
}

function diagonalTraverse(nums) {
    const buckets = [];                     // bucket[d] holds elements of diagonal d
    for (let i = 0; i < nums.length; i++) { // scan rows
        const row = nums[i];
        for (let j = 0; j < row.length; j++) { // scan columns
            const d = i + j;                // diagonal index
            if (!buckets[d]) buckets[d] = []; // create bucket if needed
            buckets[d].push(row[j]);        // store element (row order ↑)
        }
    }

    const result = [];                      // final order
    for (let d = 0; d < buckets.length; d++) { // traverse diagonals ↑
        const bucket = buckets[d];
        if (!bucket) continue;
        for (let k = bucket.length - 1; k >= 0; k--) { // output ↓ row order
            result.push(bucket[k]);
        }
    }
    return result;
}

function constrainedSubsequenceSum(nums, k) {
    const n = nums.length;
    const dp = new Array(n);
    const deque = [];               // stores indices, dp values decreasing
    let best = -Infinity;           // overall answer

    for (let i = 0; i < n; i++) {
        // remove indices that are out of the window [i‑k, i‑1]
        while (deque.length && deque[0] < i - k) deque.shift();

        // maxPrev = dp of the best index in the window, or 0 if window empty
        const maxPrev = deque.length ? dp[deque[0]] : 0;

        dp[i] = nums[i] + Math.max(0, maxPrev);   // compute dp[i]

        // maintain decreasing order of dp values in deque
        while (deque.length && dp[deque[deque.length - 1]] <= dp[i]) {
            deque.pop();
        }
        deque.push(i);               // add current index as a candidate

        if (dp[i] > best) best = dp[i]; // update global maximum
    }
    return best;
}

function maxScore(cardPoints, k) {
    const n = cardPoints.length;
    const windowSize = n - k;                     // size of the subarray we will keep

    if (windowSize === 0) {                       // take all cards
        return cardPoints.reduce((s, v) => s + v, 0);
    }

    let total = 0;
    for (let v of cardPoints) total += v;         // total sum of all cards

    // sliding window to find the minimum sum of any subarray of length windowSize
    let current = 0;
    for (let i = 0; i < windowSize; i++) current += cardPoints[i];
    let minSum = current;
    for (let i = windowSize; i < n; i++) {
        current += cardPoints[i] - cardPoints[i - windowSize];
        if (current < minSum) minSum = current;
    }

    return total - minSum;                         // max score = total - min removed sum
}

