}

function numberOfWays(hats) {
    const MOD = 1_000_000_007;
    const n = hats.length;
    const fullMask = (1 << n) - 1;

    // hatToPeople[h] = list of people that like hat h (1‑based hats)
    const hatToPeople = Array.from({ length: 41 }, () => []);
    for (let person = 0; person < n; person++) {
        for (const h of hats[person]) {
            hatToPeople[h].push(person);
        }
    }

    let dp = new Array(1 << n).fill(0);
    dp[0] = 1;                                   // empty assignment

    for (let h = 1; h <= 40; h++) {
        const next = dp.slice();                 // keep ways that skip this hat
        // DP over masks: assign current hat to an eligible person
        for (let mask = 0; mask <= fullMask; mask++) {
            const ways = dp[mask];
            if (!ways) continue;
            for (const p of hatToPeople[h]) {
                if ((mask & (1 << p)) === 0) {    // person p not yet assigned
                    const newMask = mask | (1 << p);
                    next[newMask] = (next[newMask] + ways) % MOD;
                }
            }
        }
        dp = next;
    }
    return dp[fullMask];
}

function kthSmallestSum(mat, k) {
    class MinHeap {
        constructor() { this.a = []; }
        push(x) {
            const a = this.a; a.push(x);
            let i = a.length - 1;
            while (i > 0) {
                const p = (i - 1) >> 1;
                if (a[p][0] <= a[i][0]) break;
                [a[p], a[i]] = [a[i], a[p]];
                i = p;
            }
        }
        pop() {
            const a = this.a;
            const top = a[0];
            const last = a.pop();
            if (a.length) {
                a[0] = last;
                let i = 0;
                while (true) {
                    let l = 2*i+1, r = 2*i+2, s = i;
                    if (l < a.length && a[l][0] < a[s][0]) s = l;
                    if (r < a.length && a[r][0] < a[s][0]) s = r;
                    if (s === i) break;
                    [a[s], a[i]] = [a[i], a[s]];
                    i = s;
                }
            }
            return top;
        }
        get size() { return this.a.length; }
    }

    let prev = mat[0].slice(0, Math.min(k, mat[0].length));

    for (let r = 1; r < mat.length; r++) {
        const row = mat[r];
        const heap = new MinHeap();
        const seen = new Set();
        heap.push([prev[0] + row[0], 0, 0]);
        seen.add('0,0');
        const cur = [];
        while (cur.length < k && heap.size > 0) {
            const [s, i, j] = heap.pop();
            cur.push(s);
            if (i + 1 < prev.length) {
                const key1 = `${i+1},${j}`;
                if (!seen.has(key1)) { seen.add(key1); heap.push([prev[i+1] + row[j], i+1, j]); }
            }
            if (j + 1 < row.length) {
                const key2 = `${i},${j+1}`;
                if (!seen.has(key2)) { seen.add(key2); heap.push([prev[i] + row[j+1], i, j+1]); }
            }
        }
        prev = cur;
    }
    return prev[k - 1];
}

