function longestSubarray(nums, limit) {
    let maxDeque = [];               // stores indices of candidates for max, decreasing values
    let minDeque = [];               // stores indices of candidates for min, increasing values
    let left = 0, best = 0;

    for (let right = 0; right < nums.length; right++) {
        // keep maxDeque decreasing
        while (maxDeque.length && nums[maxDeque[maxDeque.length - 1]] < nums[right]) {
            maxDeque.pop();
        }
        maxDeque.push(right);

        // keep minDeque increasing
        while (minDeque.length && nums[minDeque[minDeque.length - 1]] > nums[right]) {
            minDeque.pop();
        }
        minDeque.push(right);

        // shrink window until diff <= limit
        while (nums[maxDeque[0]] - nums[minDeque[0]] > limit) {
            if (maxDeque[0] === left) maxDeque.shift();
            if (minDeque[0] === left) minDeque.shift();
            left++;
        }

        // update answer
        best = Math.max(best, right - left + 1);
    }
    return best;
}

