    for (let idx = 0; idx <= n; idx++) {
        if (idx) pref ^= arr[idx - 1];
        if (count.has(pref) && count.get(pref)) {
            ans += count.get(pref) * (idx - 1) - (sumIdx.get(pref) || 0);
        }
        count.set(pref, (count.get(pref) || 0) + 1);
        sumIdx.set(pref, (sumIdx.get(pref) || 0) + idx);
    }
    return ans;
}

function minTime(n, edges, hasApple) {
    // build adjacency list
    const graph = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        graph[u].push(v);
        graph[v].push(u);
    }

    // DFS returns time needed for the subtree rooted at `node`
    function dfs(node, parent) {
        let total = 0;
        for (const nxt of graph[node]) {
            if (nxt === parent) continue;               // avoid going back
            const childTime = dfs(nxt, node);
            if (childTime > 0 || hasApple[nxt]) {       // subtree has an apple
                total += childTime + 2;                 // go there and back
            }
        }
        return total;
    }

    return dfs(0, -1);
}

function numberOfWaysOfCuttingAPizza(pizza, k) {
    const MOD = 1000000007n;
    const rows = pizza.length, cols = pizza[0].length;
    const apples = Array.from({length: rows + 1}, () => new Array(cols + 1).fill(0));
    for (let i = rows - 1; i >= 0; i--) {
        const row = pizza[i];
        for (let j = cols - 1; j >= 0; j--) {
            apples[i][j] = (row[j] === 'A' ? 1 : 0) + apples[i + 1][j] + apples[i][j + 1] - apples[i + 1][j + 1];
        }
    }

    let dpCur = Array.from({length: rows}, () => new Array(cols).fill(0n));
    for (let i = 0; i < rows; i++) for (let j = 0; j < cols; j++) dpCur[i][j] = apples[i][j] > 0 ? 1n : 0n;

    for (let cut = 1; cut < k; cut++) {
        const dpNext = Array.from({length: rows}, () => new Array(cols).fill(0n));
        for (let i = 0; i < rows; i++) {
            for (let j = 0; j < cols; j++) {
                if (apples[i][j] === 0) continue;
                for (let ni = i + 1; ni < rows; ni++) {
                    if (apples[i][j] - apples[ni][j] > 0) {
                        dpNext[i][j] = (dpNext[i][j] + dpCur[ni][j]) % MOD;
                    }
                }
                for (let nj = j + 1; nj < cols; nj++) {
                    if (apples[i][j] - apples[i][nj] > 0) {
                        dpNext[i][j] = (dpNext[i][j] + dpCur[i][nj]) % MOD;
                    }
                }
            }
        }
        dpCur = dpNext;
    }
    return Number(dpCur[0][0] % MOD);
}

function buildArray(target, n) {
    const ops = [];               // result list
    let ti = 0;                   // index in target

    for (let num = 1; num <= n && ti < target.length; num++) {
        if (target[ti] === num) { // needed element
            ops.push("Push");
            ti++;                 // move to next target element
        } else {                  // not needed
            ops.push("Push");
            ops.push("Pop");
        }
    }
    return ops;
}

function numberOfStudents(startTime, endTime, queryTime) {
    var count = 0;
    for (var i = 0; i < startTime.length; i++) {
        // check if queryTime lies within the student's interval
        if (startTime[i] <= queryTime && queryTime <= endTime[i]) {
            count++;
        }
    }
    return count;
}

function rearrangeWords(text) {
    // split sentence into words
    var words = text.split(' ');
    // lower‑case all words (final sentence must be lower‑case except first word)
    var lower = words.map(function (w) { return w.toLowerCase(); });

    // create objects that keep the word, its length and original position
    var items = lower.map(function (w, i) {
        return { word: w, len: w.length, idx: i };
    });

    // sort by length, stable by original index
    items.sort(function (a, b) {
        if (a.len !== b.len) return a.len - b.len;   // main logic
        return a.idx - b.idx;                        // tie‑breaker keeps original order
    });

    // rebuild the sentence: first word capitalized, others unchanged
    var result = items.map(function (obj, i) {
        return i === 0
            ? obj.word.charAt(0).toUpperCase() + obj.word.slice(1)
            : obj.word;
    }).join(' ');

    return result;
}

function maxPower(s) {
    let maxLen = 0;          // longest run found
    let curLen = 0;          // length of the current run
    let prevChar = '';       // previous character in the scan

    for (let i = 0; i < s.length; i++) {
        // extend current run if same char, otherwise start new run
        if (s[i] === prevChar) {
            curLen++;
        } else {
            curLen = 1;
            prevChar = s[i];
        }
        if (curLen > maxLen) maxLen = curLen;   // keep the maximum
    }
    return maxLen;
}

function simplifiedFractions(n) {
    var result = [];
    for (var d = 2; d <= n; d++) {
        for (var num = 1; num < d; num++) {
            if (gcd(num, d) === 1) // main logic: keep only coprime numerator/denominator
                result.push(num + '/' + d);
        }
    }
    return result;

    // Euclidean algorithm for GCD
    function gcd(a, b) {
        while (b !== 0) {
            var t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

function goodNodes(root) {
    var goodCount = 0;                                   // count of good nodes

    function dfs(node, maxSoFar) {
        if (!node) return;
        if (node.val >= maxSoFar) goodCount++;          // node is good
        var newMax = Math.max(maxSoFar, node.val);      // update max on this path
        dfs(node.left, newMax);
        dfs(node.right, newMax);
    }

    dfs(root, -Infinity);
    return goodCount;
}

function largestNumber(cost, target) {
    const dp = new Array(target + 1).fill(-Infinity); // dp[t] = max digits for cost t
    dp[0] = 0;

    // fill dp with maximum possible digit count for each total cost
    for (let t = 1; t <= target; t++) {
        for (let d = 1; d <= 9; d++) {
            const c = cost[d - 1];
            if (t >= c && dp[t - c] !== -Infinity) {
                dp[t] = Math.max(dp[t], dp[t - c] + 1);
            }
        }
    }

    if (dp[target] <= 0) return "0"; // no solution

    let remaining = dp[target];
    let result = "";
    // greedily pick the largest possible digit for each position
    while (remaining > 0) {
        for (let d = 9; d >= 1; d--) {
            const c = cost[d - 1];
            if (target >= c && dp[target - c] === remaining - 1) {
                result += d;
                target -= c;
                remaining--;
                break;
            }
        }
    }
    return result;
}

function maxVowels(s, k) {
    const vowels = new Set(['a', 'e', 'i', 'o', 'u']);
    let windowCount = 0;

    // initialize first window
    for (let i = 0; i < k; i++) {
        if (vowels.has(s[i])) windowCount++;
    }
    let maxCount = windowCount;

    // slide the window across the string
    for (let i = k; i < s.length; i++) {
        if (vowels.has(s[i])) windowCount++;               // add right char
        if (vowels.has(s[i - k])) windowCount--;           // remove left char
        if (windowCount > maxCount) maxCount = windowCount;
    }
    return maxCount;
}

function peopleIndexes(favoriteCompanies) {
    const n = favoriteCompanies.length;

    // convert each list to a Set for O(1) look‑ups
    const sets = favoriteCompanies.map(arr => new Set(arr));

    // store index, set and size; sort by size descending
    const info = sets.map((s, i) => ({ idx: i, set: s, size: s.size }));
    info.sort((a, b) => b.size - a.size);               // main logic: ordering

    const keep = new Array(n).fill(true);               // assume all are kept

    // for each list (shorter to longer) check only against earlier (longer) lists
    for (let i = 0; i < n; i++) {
        const { idx: curIdx, set: curSet } = info[i];
        for (let j = 0; j < i; j++) {                  // main logic: subset test
            const { set: largerSet } = info[j];
            let isSubset = true;
            for (const val of curSet) {
                if (!largerSet.has(val)) { isSubset = false; break; }
            }
            if (isSubset) { keep[curIdx] = false; break; }
        }
    }

    // collect indices that were never found to be a subset
    const result = [];
    for (let i = 0; i < n; i++) {
        if (keep[i]) result.push(i);
    }
    return result;                                      // already in increasing order
}

function maxDarts(darts, r) {
    const n = darts.length;
    if (n <= 1) return n;
    const R2 = (2 * r) * (2 * r);
    const TWO_PI = 2 * Math.PI;
    let bestOverall = 1;

    for (let i = 0; i < n; ++i) {
        const events = [];
        const [xi, yi] = darts[i];

        for (let j = 0; j < n; ++j) {
            if (i === j) continue;
            const dx = darts[j][0] - xi;
            const dy = darts[j][1] - yi;
            const d2 = dx * dx + dy * dy;
            if (d2 > R2) continue;

            const d = Math.sqrt(d2);
            const base = Math.atan2(dy, dx);
            const delta = Math.acos(Math.min(1, d / (2 * r)));

            // keep start/end as a consistent pair - do NOT independently clamp
            // each one into [0, 2*PI), that desyncs them whenever they straddle
            // the 0 boundary differently
            const start = base - delta;
            const end = base + delta;

            events.push([start, 1]);
            events.push([end, -1]);
            events.push([start + TWO_PI, 1]);
            events.push([end + TWO_PI, -1]);
        }

        // starts before ends at equal angles, so boundary-touching points still count
        events.sort((a, b) => a[0] - b[0] || b[1] - a[1]);

        let cur = 0, best = 0;
        for (const [, type] of events) {
            cur += type;
            if (cur > best) best = cur;
        }

        if (best + 1 > bestOverall) bestOverall = best + 1;
    }
    return bestOverall;
}

function isPrefixOfWord(sentence, searchWord) {
    // two‑pointer scan of the sentence
    let i = 0;                 // current index in sentence
    let wordIdx = 1;           // 1‑based word counter

    while (i < sentence.length) {
        // start of the current word
        let start = i;

        // compare characters of the word with searchWord
        while (i < sentence.length &&
               sentence[i] !== ' ' &&               // still inside the word
               i - start < searchWord.length &&      // characters left in searchWord
               sentence[i] === searchWord[i - start]) {
            i++;
        }

        // if we consumed the whole searchWord → it is a prefix
        if (i - start === searchWord.length) {
            return wordIdx;
        }

        // skip the rest of the current word (if any)
        while (i < sentence.length && sentence[i] !== ' ') {
            i++;
        }

        // move past the separating space, if present
        if (i < sentence.length && sentence[i] === ' ') {
            i++;
        }

        wordIdx++;
    }

    return -1;   // no word has the given prefix
}

function canMakeEqual(target, arr) {
    // build frequency map from target
    const freq = Object.create(null);
    for (let i = 0; i < target.length; i++) {
        const v = target[i];
        freq[v] = (freq[v] || 0) + 1;
    }

    // decrement with elements of arr, fail early on mismatch
    for (let i = 0; i < arr.length; i++) {
        const v = arr[i];
        if (!freq[v]) return false;          // main logic: mismatch detection
        freq[v]--;
    }
    return true;
}

function pseudoPalindromicPaths(root) {
    let result = 0;
    const stack = [[root, 0]];                 // node + current parity mask

    while (stack.length) {
        const [node, mask] = stack.pop();
        if (!node) continue;

        const newMask = mask ^ (1 << node.val);   // flip parity of current value

        // leaf → check if at most one bit is set (pseudo‑palindrome)
        if (!node.left && !node.right) {
            if ((newMask & (newMask - 1)) === 0) result++;
        } else {
            if (node.right) stack.push([node.right, newMask]);
            if (node.left)  stack.push([node.left,  newMask]);
        }
    }
    return result;
}

function checkIfPrerequisite(numCourses, prerequisites, queries) {
    // initialise reachability matrix
    const reach = Array.from({ length: numCourses }, () => Array(numCourses).fill(false));
    for (const [a, b] of prerequisites) reach[a][b] = true;

    // Floyd‑Warshall: compute transitive closure
    for (let k = 0; k < numCourses; k++) {
        for (let i = 0; i < numCourses; i++) {
            if (reach[i][k]) {                     // only continue if i can reach k
                for (let j = 0; j < numCourses; j++) {
                    if (reach[k][j]) reach[i][j] = true; // i can also reach j through k
                }
            }
        }
    }

    // answer queries
    const answer = [];
    for (const [u, v] of queries) answer.push(reach[u][v] === true);
    return answer;
}

function maxDotProduct(nums1, nums2) {
    const m = nums1.length, n = nums2.length;
    // dp[j] holds the result for the previous row (i‑1, j)
    const dp = new Array(n + 1).fill(-Infinity);
    for (let i = 1; i <= m; i++) {
        const newRow = new Array(n + 1).fill(-Infinity);
        let prevDiag = -Infinity;               // dp[i‑1][j‑1]
        for (let j = 1; j <= n; j++) {
            const prod = nums1[i - 1] * nums2[j - 1];
            // main logic: choose best among four possibilities
            const best = Math.max(
                prevDiag + prod,   // extend previous subsequence
                prod,              // start new subsequence
                dp[j],             // skip nums1[i‑1]
                newRow[j - 1]      // skip nums2[j‑1]
            );
            newRow[j] = best;
            prevDiag = dp[j];    // store old dp[j] for next diagonal
        }
        // move to next row
        for (let j = 0; j <= n; j++) dp[j] = newRow[j];
    }
    return dp[n];
}

function maxArea(h, w, horizontalCuts, verticalCuts) {
    const MOD = 1_000_000_007;

    // sort cuts to be able to compute consecutive gaps
    horizontalCuts.sort((a, b) => a - b);
    verticalCuts.sort((a, b) => a - b);

    // find maximal vertical gap (height of the biggest piece)
    let maxHeight = horizontalCuts[0];                     // gap from top edge
    for (let i = 1; i < horizontalCuts.length; i++) {
        const gap = horizontalCuts[i] - horizontalCuts[i - 1];
        if (gap > maxHeight) maxHeight = gap;               // keep the largest gap
    }
    const lastHeightGap = h - horizontalCuts[horizontalCuts.length - 1];
    if (lastHeightGap > maxHeight) maxHeight = lastHeightGap;

    // find maximal horizontal gap (width of the biggest piece)
    let maxWidth = verticalCuts[0];                         // gap from left edge
    for (let i = 1; i < verticalCuts.length; i++) {
        const gap = verticalCuts[i] - verticalCuts[i - 1];
        if (gap > maxWidth) maxWidth = gap;                 // keep the largest gap
    }
    const lastWidthGap = w - verticalCuts[verticalCuts.length - 1];
    if (lastWidthGap > maxWidth) maxWidth = lastWidthGap;

    // area modulo MOD (use BigInt to avoid overflow)
    const area = (BigInt(maxHeight) * BigInt(maxWidth)) % BigInt(MOD);
    return Number(area);
}

function cherryPickup(grid) {
    const rows = grid.length;
    const cols = grid[0].length;

    // dp[c1][c2] = best cherries up to the current row with robots at c1 and c2
    let dp = Array.from({ length: cols }, () => Array(cols).fill(-Infinity));
    dp[0][cols - 1] = grid[0][0] + (cols === 1 ? 0 : grid[0][cols - 1]); // start

    for (let r = 1; r < rows; r++) {
        const next = Array.from({ length: cols }, () => Array(cols).fill(-Infinity));

        for (let c1 = 0; c1 < cols; c1++) {
            for (let c2 = 0; c2 < cols; c2++) {
                if (dp[c1][c2] === -Infinity) continue;

                // try all 3 moves for each robot
                for (let d1 = -1; d1 <= 1; d1++) {
                    const nc1 = c1 + d1;
                    if (nc1 < 0 || nc1 >= cols) continue;

                    for (let d2 = -1; d2 <= 1; d2++) {
                        const nc2 = c2 + d2;
                        if (nc2 < 0 || nc2 >= cols) continue;

                        // collect cherries of the new cells (once if they coincide)
                        let add = grid[r][nc1];
                        if (nc1 !== nc2) add += grid[r][nc2];

                        // update DP value for the new positions
                        next[nc1][nc2] = Math.max(next[nc1][nc2], dp[c1][c2] + add);
                    }
                }
            }
        }
        dp = next; // roll to the next row
    }

    // answer = maximum over all possible final positions
    let ans = 0;
    for (let c1 = 0; c1 < cols; c1++) {
        for (let c2 = 0; c2 < cols; c2++) {
            ans = Math.max(ans, dp[c1][c2]);
        }
    }
    return ans;
}

function probabilityOfATwoBoxesHavingTheSameNumberOfDistinctBalls(balls) {
    const comb = (() => {
        const cache = new Map();
        const fact = (n) => {
            let r = 1;
            for (let i = 2; i <= n; i++) r *= i;
            return r;
        };
        return (n, r) => {
            if (r < 0 || r > n) return 0;
            const key = n + ',' + r;
            if (cache.has(key)) return cache.get(key);
            let result = 1;
            for (let i = 0; i < r; i++) result = result * (n - i) / (i + 1);
            const rounded = Math.round(result);
            cache.set(key, rounded);
            return rounded;
        };
    })();

    const total = balls.reduce((a, b) => a + b, 0);
    if (total % 2 !== 0) return 0.0;
    const half = total / 2;

    let dp = Array.from({length: half + 1}, () => new Map());
    dp[0].set(0, 1);

    for (const c of balls) {
        const newdp = Array.from({length: half + 1}, () => new Map());
        const combs = [];
        for (let x = 0; x <= c; x++) combs.push(comb(c, x));
        for (let sel = 0; sel <= half; sel++) {
            if (dp[sel].size === 0) continue;
            for (const [diff, ways] of dp[sel]) {
                for (let x = 0; x <= c; x++) {
                    const ns = sel + x;
                    if (ns > half) break;
                    const nd = diff + (x > 0 ? 1 : 0) - (x < c ? 1 : 0);
                    newdp[ns].set(nd, (newdp[ns].get(nd) || 0) + ways * combs[x]);
                }
            }
        }
        dp = newdp;
    }

    const favorable = dp[half].get(0) || 0;
    const totalWays = comb(total, half);
    return Math.round((favorable / totalWays) * 100000) / 100000;
}

function hasAllCodes(s, k) {
    const totalCodes = 1 << k;                 // total possible binary codes
    if (s.length < k) return false;

    const seen = new Uint8Array(totalCodes);   // record which codes appear
    let hash = 0;

    // build hash for the first window
    for (let i = 0; i < k; i++) {
        hash = (hash << 1) | (s.charCodeAt(i) - 48);
    }
    seen[hash] = 1;
    let found = 1;

    const mask = totalCodes - 1;                // keep only k bits

    for (let i = k; i < s.length; i++) {
        // slide window: drop leftmost bit, add new bit
        hash = ((hash << 1) & mask) | (s.charCodeAt(i) - 48);
        if (!seen[hash]) {
            seen[hash] = 1;
            if (++found === totalCodes) return true;
        }
    }
    return found === totalCodes;
}

function maxProduct(nums) {
    // Find the two largest numbers in a single pass
    let max1 = 0, max2 = 0;
    for (let i = 0; i < nums.length; i++) {
        const v = nums[i];
        if (v > max1) {
            max2 = max1;
            max1 = v;
        } else if (v > max2) {
            max2 = v;
        }
    }
    return (max1 - 1) * (max2 - 1);
}

function minReorder(n, connections) {
    const adj = Array.from({ length: n }, () => []);
    for (const [a, b] of connections) {
        // traversing a->b outward from the root means the original a->b edge
        // points AWAY from the root (parent to child) - that's backwards, needs reversal
        adj[a].push([b, 1]);
        // traversing b->a outward means the original a->b edge points child-to-parent,
        // which is already the direction we want - no reversal needed
        adj[b].push([a, 0]);
    }

    const visited = new Array(n).fill(false);
    let changes = 0;
    const stack = [0];
    visited[0] = true;

    while (stack.length) {
        const node = stack.pop();
        for (const [next, needReverse] of adj[node]) {
            if (!visited[next]) {
                changes += needReverse;
                visited[next] = true;
                stack.push(next);
            }
        }
    }
    return changes;
}

function BrowserHistory(homepage) {
    this.history = [homepage];   // store visited pages
    this.current = 0;            // index of the current page
}

// visit a new url, discarding any forward history
BrowserHistory.prototype.visit = function (url) {
    this.history.length = this.current + 1; // truncate forward part
    this.history.push(url);
    this.current++;                         // move to the new page
};

// move back up to 'steps' pages and return the current url
BrowserHistory.prototype.back = function (steps) {
    this.current = Math.max(0, this.current - steps);
    return this.history[this.current];
};

// move forward up to 'steps' pages and return the current url
BrowserHistory.prototype.forward = function (steps) {
    this.current = Math.min(this.history.length - 1, this.current + steps);
    return this.history[this.current];
};

// TIME: O(1) per operation SPACE: O(N) where N is the number of visited pages.

var minCost = function(houses, cost, m, n, target) {
    const INF = 1e15;
    let dp = Array.from({length: target+1}, () => new Array(n+1).fill(INF));
    if (houses[0] !== 0) {
        dp[1][houses[0]] = 0;
    } else {
        for (let c=1;c<=n;c++) dp[1][c] = cost[0][c-1];
    }
    for (let i=1;i<m;i++) {
        const best1 = new Array(target+1).fill(INF);
        const best2 = new Array(target+1).fill(INF);
        const bestColor = new Array(target+1).fill(0);
        for (let t=1;t<=target;t++) {
            let b1=INF,b2=INF,bc=0;
            for (let c=1;c<=n;c++) {
                const val = dp[t][c];
                if (val < b1) { b2 = b1; b1 = val; bc = c; }
                else if (val < b2) { b2 = val; }
            }
            best1[t]=b1; best2[t]=b2; bestColor[t]=bc;
        }
        const newDp = Array.from({length: target+1}, () => new Array(n+1).fill(INF));
        const possibleColors = houses[i] !== 0 ? [houses[i]] : Array.from({length:n}, (_,k)=>k+1);
        for (let t=1;t<=target;t++) {
            for (const curC of possibleColors) {
                const add = houses[i] !== 0 ? 0 : cost[i][curC-1];
                const same = dp[t][curC] + add;
                let diff;
                if (t > 1) {
                    diff = (bestColor[t-1] !== curC) ? best1[t-1]+add : best2[t-1]+add;
                } else {
                    diff = INF;
                }
                newDp[t][curC] = same < diff ? same : diff;
            }
        }
        dp = newDp;
    }
    let ans = INF;
    for (let c=1;c<=n;c++) ans = Math.min(ans, dp[target][c]);
    return ans >= INF ? -1 : ans;
};

function shuffle(nums, n) {
    const shuffled = new Array(2 * n);               // allocate result array
    for (let i = 0; i < n; i++) {
        // interleave elements from the first half (x_i) and second half (y_i)
        shuffled[2 * i] = nums[i];
        shuffled[2 * i + 1] = nums[i + n];
    }
    return shuffled;
}

function finalPrices(prices) {
    const n = prices.length;
    const result = prices.slice();               // copy to modify in-place
    const stack = [];                            // store indices waiting for discount

    for (let i = 0; i < n; i++) {
        // resolve pending items whose next smaller-or-equal price is prices[i]
        while (stack.length && prices[i] <= prices[stack[stack.length - 1]]) {
            const idx = stack.pop();
            result[idx] = prices[idx] - prices[i];
        }
        stack.push(i);                            // current index may get discount later
    }
    // remaining indices have no discount; result already contains original prices
    return result;
}

function SubrectangleQueries(rectangle) {
    // keep a mutable copy of the matrix
    const grid = rectangle.map(row => row.slice());

    return {
        // O((row2-row1+1)*(col2-col1+1)) - overwrite every cell in the sub-rectangle
        updateSubrectangle: function(row1, col1, row2, col2, newValue) {
            for (let r = row1; r <= row2; r++) {
                for (let c = col1; c <= col2; c++) {
                    grid[r][c] = newValue;
                }
            }
        },

        // O(1) - direct access
        getValue: function(row, col) {
            return grid[row][col];
        }
    };
}

function strongestValues(arr, k) {
    const n = arr.length;
    const sorted = arr.slice().sort((a, b) => a - b);          // sort ascending
    const centre = sorted[Math.floor((n - 1) / 2)];           // median element

    const result = [];
    let l = 0, r = n - 1;                                    // two pointers

    // main logic: pick the stronger side until k elements are taken
    while (result.length < k) {
        const leftDist  = Math.abs(sorted[l] - centre);
        const rightDist = Math.abs(sorted[r] - centre);

        if (rightDist > leftDist) {               // right side farther
            result.push(sorted[r--]);
        } else if (leftDist > rightDist) {        // left side farther
            result.push(sorted[l++]);
        } else {                                   // equal distance → larger value wins
            if (sorted[r] > sorted[l]) result.push(sorted[r--]);
            else result.push(sorted[l++]);
        }
    }
    return result;
}

function leastUniqueIntegers(arr, k) {
    // 1. build frequency map
    const freq = {};
    for (let i = 0; i < arr.length; i++) {
        const v = arr[i];
        freq[v] = (freq[v] || 0) + 1;
    }

    // 2. collect and sort frequencies (ascending)
    const counts = Object.values(freq).sort((a, b) => a - b);

    // 3. greedily delete whole groups while we have deletions left
    let unique = counts.length;
    for (let i = 0; i < counts.length && k > 0; i++) {
        if (k >= counts[i]) {          // can erase this whole integer
            k -= counts[i];
            unique--;                  // one less distinct value
        } else {
            break;                     // not enough deletions to remove another group
        }
    }
    return unique;
}

function minSumOfLengths(arr, target) {
    const n = arr.length;
    const INF = Number.MAX_SAFE_INTEGER;

    // lengths of sub‑arrays that end at / start at each position
    const minLenEndingAt = new Array(n).fill(INF);
    const minLenStartingAt = new Array(n).fill(INF);

    // ---- sliding window to find all target‑sum sub‑arrays ----
    let left = 0, sum = 0;
    for (let right = 0; right < n; right++) {
        sum += arr[right];
        while (sum > target && left <= right) {
            sum -= arr[left++];
        }
        if (sum === target) {
            const len = right - left + 1;
            minLenEndingAt[right] = len;          // ends at right
            minLenStartingAt[left] = len;         // starts at left
        }
    }

    // ---- prefix minima (best sub‑array up to each index) ----
    const bestPrefix = new Array(n).fill(INF);
    for (let i = 0; i < n; i++) {
        bestPrefix[i] = i === 0 ? minLenEndingAt[i]
                                 : Math.min(bestPrefix[i - 1], minLenEndingAt[i]);
    }

    // ---- suffix minima (best sub‑array from each index to the end) ----
    const bestSuffix = new Array(n).fill(INF);
    for (let i = n - 1; i >= 0; i--) {
        bestSuffix[i] = i === n - 1 ? minLenStartingAt[i]
                                    : Math.min(bestSuffix[i + 1], minLenStartingAt[i]);
    }

    // ---- combine prefix and suffix to obtain answer ----
    let answer = INF;
    for (let i = 0; i < n - 1; i++) {
        if (bestPrefix[i] < INF && bestSuffix[i + 1] < INF) {
            answer = Math.min(answer, bestPrefix[i] + bestSuffix[i + 1]);
        }
    }
    return answer === INF ? -1 : answer;
}

function minDistance(houses, k) {
    houses.sort((a,b) => a-b);
    const n = houses.length;
    const cost = Array.from({length:n}, () => new Array(n).fill(0));
    for (let i = 0; i < n; i++) {
        for (let j = i+1; j < n; j++) {
            const mid = Math.floor((i+j)/2);
            let sum = 0;
            for (let x = i; x <= j; x++) sum += Math.abs(houses[x] - houses[mid]);
            cost[i][j] = sum;
        }
    }
    const INF = Infinity;
    const dp = Array.from({length:n+1}, () => new Array(k+1).fill(INF));
    dp[0][0] = 0;
    for (let i = 1; i <= n; i++) {
        for (let m = 1; m <= k; m++) {
            for (let j = 0; j < i; j++) {
                if (dp[j][m-1] === INF) continue;
                dp[i][m] = Math.min(dp[i][m], dp[j][m-1] + cost[j][i-1]);
            }
        }
    }
    return dp[n][k];
}

function runningSum(nums) {
  // accumulate each element with the sum of all previous elements
  for (let i = 1; i < nums.length; i++) {
    nums[i] += nums[i - 1];
  }
  return nums;
}

function xorOperation(n, start) {
    // split start into higher bits (a) and LSB (b)
    var a = start >> 1;               // higher part
    var b = start & 1;                // LSB (0 or 1)

    // xor of consecutive numbers a … a+n-1
    function xor0To(k) {              // xor of 0 … k
        switch (k & 3) {              // k % 4
            case 0: return k;
            case 1: return 1;
            case 2: return k + 1;
            default: return 0;        // case 3
        }
    }
    var highXor = xor0To(a + n - 1) ^ xor0To(a - 1); // xorRange(a, a+n-1)

    // combine higher bits (shifted left) with LSB contribution
    return (highXor << 1) | (b & (n & 1));
}

function getFolderNames(names) {
    var result = new Array(names.length);
    var next = Object.create(null);               // hash table: name → next suffix to try

    for (var i = 0; i < names.length; i++) {
        var name = names[i];

        if (next[name] === undefined) {           // name never used before
            result[i] = name;
            next[name] = 1;                        // next suffix would be (1)
        } else {
            var k = next[name];
            var candidate;
            while (next[candidate = name + '(' + k + ')'] !== undefined) {
                k++;                                 // try the next suffix
            }
            result[i] = candidate;                  // first free name found
            next[name] = k + 1;                      // update base name's next suffix
            next[candidate] = 1;                     // reserve the new name
        }
    }
    return result;
}

function minDays(bloomDay, m, k) {
    // impossible if not enough flowers
    if (m * k > bloomDay.length) return -1;

    // helper to test if we can form m bouquets by given day
    function canMake(day) {
        let bouquets = 0, consecutive = 0;
        for (let i = 0; i < bloomDay.length; i++) {
            if (bloomDay[i] <= day) {
                consecutive++;                     // flower has bloomed
                if (consecutive === k) {           // enough for one bouquet
                    bouquets++;
                    consecutive = 0;               // reset for next bouquet
                    if (bouquets >= m) return true;
                }
            } else {
                consecutive = 0;                   // break the adjacency
            }
        }
        return false;
    }

    let low = Math.min(...bloomDay);               // earliest possible day
    let high = Math.max(...bloomDay);              // latest possible day

    // binary search for the minimal day that satisfies canMake
    while (low < high) {
        const mid = Math.floor((low + high) / 2);
        if (canMake(mid)) high = mid;               // try earlier days
        else low = mid + 1;                         // need more days
    }
    return low;
}

function pathCrossing(path) {
    const visited = new Set();          // store visited coordinates
    let x = 0, y = 0;
    visited.add('0,0');                 // origin is visited first

    // iterate through the path, move one step, and check for repeats
    for (let i = 0; i < path.length; i++) {
        const dir = path[i];
        if (dir === 'N') y++;
        else if (dir === 'S') y--;
        else if (dir === 'E') x++;
        else if (dir === 'W') x--;

        const pos = x + ',' + y;
        if (visited.has(pos)) return true; // crossing detected
        visited.add(pos);
    }
    return false;
}

class TreeAncestor {
    constructor(n, parent) {
        this.LOG = Math.ceil(Math.log2(Math.max(n,2))) + 1;
        this.up = Array.from({length: this.LOG}, () => new Int32Array(n));
        for (let i = 0; i < n; i++) this.up[0][i] = parent[i];
        for (let j = 1; j < this.LOG; j++) {
            for (let i = 0; i < n; i++) {
                const mid = this.up[j-1][i];
                this.up[j][i] = mid === -1 ? -1 : this.up[j-1][mid];
            }
        }
    }
    getKthAncestor(node, k) {
        for (let j = 0; j < this.LOG && node !== -1; j++) {
            if (k & (1 << j)) node = this.up[j][node];
        }
        return node;
    }
}

function numSubseq(nums, target) {
    const MOD = 1_000_000_007;
    nums.sort((a, b) => a - b);                     // sort to enable two‑pointer scan
    const n = nums.length;
    const pow2 = new Array(n);
    pow2[0] = 1;
    for (let i = 1; i < n; i++) {                  // pre‑compute 2^i mod MOD
        pow2[i] = (pow2[i - 1] * 2) % MOD;
    }

    let left = 0, right = n - 1, ans = 0;
    while (left <= right) {                        // two‑pointer traversal
        if (nums[left] + nums[right] <= target) {
            ans = (ans + pow2[right - left]) % MOD; // all subsets between left and right
            left++;
        } else {
            right--;
        }
    }
    return ans;
}

function avoidFloodInTheCity(rains) {
    const n = rains.length;
    const INF = Infinity;
    const nextRain = new Array(n).fill(INF);
    const lastOccurrence = new Map();
    for (let i = n - 1; i >= 0; i--) {
        const lake = rains[i];
        if (lake > 0) {
            if (lastOccurrence.has(lake)) nextRain[i] = lastOccurrence.get(lake);
            lastOccurrence.set(lake, i);
        }
    }

    const ans = new Array(n).fill(0);
    const full = new Set();
    // min-heap by [nextRainDay, lake] - simple array + sort-on-demand (n is small enough) via binary insert
    const heap = [];
    const heapPush = (item) => {
        heap.push(item);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p][0] > heap[i][0] || (heap[p][0] === heap[i][0] && heap[p][1] > heap[i][1])) {
                [heap[p], heap[i]] = [heap[i], heap[p]];
                i = p;
            } else break;
        }
    };
    const heapPop = () => {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            let i = 0;
            while (true) {
                let l = 2 * i + 1, r = 2 * i + 2, smallest = i;
                if (l < heap.length && (heap[l][0] < heap[smallest][0] || (heap[l][0] === heap[smallest][0] && heap[l][1] < heap[smallest][1]))) smallest = l;
                if (r < heap.length && (heap[r][0] < heap[smallest][0] || (heap[r][0] === heap[smallest][0] && heap[r][1] < heap[smallest][1]))) smallest = r;
                if (smallest === i) break;
                [heap[i], heap[smallest]] = [heap[smallest], heap[i]];
                i = smallest;
            }
        }
        return top;
    };

    for (let i = 0; i < n; i++) {
        const lake = rains[i];
        if (lake > 0) {
            if (full.has(lake)) return [];
            ans[i] = -1;
            full.add(lake);
            if (nextRain[i] !== INF) heapPush([nextRain[i], lake]);
        } else {
            while (heap.length && !full.has(heap[0][1])) heapPop();
            if (heap.length) {
                const [, lakeToDry] = heapPop();
                ans[i] = lakeToDry;
                full.delete(lakeToDry);
            } else {
                ans[i] = 1;
            }
        }
    }
    return ans;
}

function findCriticalAndPseudoCriticalEdges(n, edges) {
    class DSU {
        constructor(n) {
            this.parent = Array.from({length: n}, (_, i) => i);
            this.rank = new Array(n).fill(0);
            this.components = n;
        }
        find(x) {
            while (this.parent[x] !== x) {
                this.parent[x] = this.parent[this.parent[x]];
                x = this.parent[x];
            }
            return x;
        }
        union(x, y) {
            let xr = this.find(x), yr = this.find(y);
            if (xr === yr) return false;
            if (this.rank[xr] < this.rank[yr]) [xr, yr] = [yr, xr];
            this.parent[yr] = xr;
            if (this.rank[xr] === this.rank[yr]) this.rank[xr]++;
            this.components--;
            return true;
        }
    }

    const indexed = edges.map((e, i) => [e[0], e[1], e[2], i]);
    indexed.sort((a, b) => a[2] - b[2]);
    const INF = 1e15;

    const mst = (skip = -1, force = -1) => {
        const dsu = new DSU(n);
        let total = 0;
        if (force !== -1) {
            const [u, v, w] = indexed[force];
            if (dsu.union(u, v)) total += w;
        }
        for (let idx = 0; idx < indexed.length; idx++) {
            if (idx === skip || idx === force) continue;
            const [u, v, w] = indexed[idx];
            if (dsu.union(u, v)) {
                total += w;
                if (dsu.components === 1) break;
            }
        }
        return dsu.components === 1 ? total : INF;
    };

    const original = mst();
    const critical = [];
    const pseudo = [];

    for (let i = 0; i < indexed.length; i++) {
        if (mst(i, -1) > original) {
            critical.push(indexed[i][3]);
        } else if (mst(-1, i) === original) {
            pseudo.push(indexed[i][3]);
        }
    }
    return [critical, pseudo];
}

function reformatDate(date) {
    const monthMap = {
        Jan: '01', Feb: '02', Mar: '03', Apr: '04',
        May: '05', Jun: '06', Jul: '07', Aug: '08',
        Sep: '09', Oct: '10', Nov: '11', Dec: '12'
    };                                   // map month abbreviation to two‑digit number

    const parts = date.split(' ');      // ["20th", "Oct", "2052"]
    const day = parts[0].slice(0, -2).padStart(2, '0'); // remove suffix, pad if needed
    const month = monthMap[parts[1]];   // convert month abbreviation
    const year = parts[2];              // year stays unchanged

    return `${year}-${month}-${day}`;   // assemble final format
}

function canArrange(arr, k) {
    const freq = new Map();                              // count remainders
    for (let i = 0; i < arr.length; i++) {
        const rem = ((arr[i] % k) + k) % k;               // normalize to [0, k-1]
        freq.set(rem, (freq.get(rem) || 0) + 1);
    }
    if ((freq.get(0) || 0) % 2 !== 0) return false;      // remainder 0 must pair within itself
    if (k % 2 === 0 && (freq.get(k / 2) || 0) % 2 !== 0) return false; // k/2 case when k even
    for (let [rem, cnt] of freq) {                       // compare each remainder with its complement
        if (rem === 0 || (k % 2 === 0 && rem === k / 2)) continue;
        const complement = k - rem;
        if ((freq.get(complement) || 0) !== cnt) return false;
    }
    return true;
}

function maxValueOfEquation(points, k) {
    let deque = [];                 // stores {x, val = y - x} in decreasing val order
    let best = -Infinity;           // answer

    for (let i = 0; i < points.length; i++) {
        const [xj, yj] = points[i];

        // remove points that are farther than k from the current x
        while (deque.length && deque[0].x < xj - k) deque.shift();

        // use the maximum (yi - xi) from the deque to form a candidate answer
        if (deque.length) {
            const candidate = deque[0].val + yj + xj;
            if (candidate > best) best = candidate;
        }

        const curVal = yj - xj;     // (yi - xi) for the current point

        // maintain decreasing order of val in the deque
        while (deque.length && deque[deque.length - 1].val <= curVal) deque.pop();

        deque.push({ x: xj, val: curVal });
    }

    return best;
}

function stoneGameIV(n) {
    const win = new Array(n + 1).fill(false); // win[0] = false by default

    for (let i = 1; i <= n; i++) {
        // try every square k*k that can be removed from i
        for (let k = 1; k * k <= i; k++) {
            if (!win[i - k * k]) { // opponent loses from the resulting pile
                win[i] = true;      // current player can win
                break;               // no need to check larger squares
            }
        }
    }
    return win[n];
}

function minDifference(nums) {
    if (nums.length <= 4) return 0;                     // trivial case

    nums.sort((a, b) => a - b);                         // sort to access extremes easily

    let n = nums.length;
    let best = Infinity;
    for (let i = 0; i <= 3; i++) {                      // try removing i smallest & (3‑i) largest
        let diff = nums[n - 1 - (3 - i)] - nums[i];
        if (diff < best) best = diff;
    }
    return best;
}

function rangeSumSortedSubarraySums(nums, n, left, right) {
    const pref = new Array(n + 1);
    pref[0] = 0;
    for (let i = 0; i < n; i++) pref[i + 1] = pref[i] + nums[i];
    const prefPref = new Array(n + 2);
    prefPref[0] = 0;
    for (let i = 0; i <= n; i++) prefPref[i + 1] = prefPref[i] + pref[i];
    const MOD = 1000000007;

    function countAndSum(limit) {
        let cnt = 0;
        let tot = 0;
        let r = 0;
        for (let l = 0; l < n; l++) {
            if (r < l) r = l;
            while (r < n && pref[r + 1] - pref[l] <= limit) r++;
            const num = r - l;
            cnt += num;
            const sumPref = prefPref[r + 1] - prefPref[l + 1];
            const subTot = sumPref - num * pref[l];
            tot += subTot;
        }
        return { cnt, tot };
    }

    function prefixSumK(k) {
        if (k === 0) return 0;
        let low = 0;
        let high = pref[n];
        while (low < high) {
            const mid = (low + high) >> 1;
            if (countAndSum(mid).cnt >= k) high = mid;
            else low = mid + 1;
        }
        const X = low;
        const { cnt, tot } = countAndSum(X);
        const excess = cnt - k;
        const res = tot - excess * X;
        return ((res % MOD) + MOD) % MOD;
    }

    const ans = (prefixSumK(right) - prefixSumK(left - 1) + MOD) % MOD;
    return ans;
}

function maxWaterBottles(numBottles, numExchange) {
    // total drinks = initial bottles + extra bottles obtained by repeatedly exchanging empties
    return numBottles + Math.floor((numBottles - 1) / (numExchange - 1));
}

function countOdds(low, high) {
    // odds up to high minus odds before low
    return Math.floor((high + 1) / 2) - Math.floor(low / 2);
}

function countSubTrees(n, edges, labels) {
    // build adjacency list
    const g = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        g[u].push(v);
        g[v].push(u);
    }

    const ans = new Array(n).fill(0);
    const visited = new Array(n).fill(false);

    // DFS post‑order to aggregate label frequencies
    function dfs(u) {
        visited[u] = true;
        const cnt = new Array(26).fill(0);
        const idx = labels.charCodeAt(u) - 97;   // 0‑based index of label
        cnt[idx] = 1;                            // count the node itself

        for (const v of g[u]) {
            if (!visited[v]) {
                const childCnt = dfs(v);         // child's frequency array
                for (let i = 0; i < 26; ++i) {
                    cnt[i] += childCnt[i];        // merge child frequencies
                }
            }
        }
        ans[u] = cnt[idx];                       // answer for node u
        return cnt;
    }

    dfs(0);
    return ans;
}

function bestPosition(positions) {
    const eps = 1e-7;                     // convergence tolerance
    // initial guess: centroid
    let x = 0, y = 0;
    for (const p of positions) {
        x += p[0];
        y += p[1];
    }
    x /= positions.length;
    y /= positions.length;

    while (true) {
        let numX = 0, numY = 0, den = 0;
        let moved = 0;

        // Weiszfeld iteration
        for (const p of positions) {
            const dx = x - p[0];
            const dy = y - p[1];
            const dist = Math.hypot(dx, dy);
            if (dist < eps) {               // current estimate coincides with a point
                x = p[0];
                y = p[1];
                moved = 0;
                break;
            }
            const w = 1 / dist;
            numX += p[0] * w;
            numY += p[1] * w;
            den += w;
        }
        const newX = numX / den;
        const newY = numY / den;
        moved = Math.hypot(newX - x, newY - y);
        if (moved < eps) break;             // stop when change is negligible
        x = newX;
        y = newY;
    }

    // compute the minimal sum of distances
    let total = 0;
    for (const p of positions) {
        total += Math.hypot(x - p[0], y - p[1]);
    }
    return total;
}

function maxNumOfSubstrings(s) {
    const n = s.length;
    const left = new Array(26).fill(-1);
    const right = new Array(26).fill(-1);
    for (let i = 0; i < n; i++) {
        const c = s.charCodeAt(i) - 97;
        if (left[c] === -1) left[c] = i;
        right[c] = i;
    }
    const intervals = [];
    for (let c = 0; c < 26; c++) {
        if (left[c] === -1) continue;
        let l = left[c], r = right[c];
        let changed = true;
        while (changed) {
            changed = false;
            for (let i = l; i <= r; i++) {
                const cc = s.charCodeAt(i) - 97;
                if (left[cc] < l) { l = left[cc]; changed = true; }
                if (right[cc] > r) { r = right[cc]; changed = true; }
            }
        }
        if (l === left[c]) intervals.push([l, r]);
    }
    intervals.sort((a,b) => a[1]-b[1]);
    const result = [];
    let lastEnd = -1;
    for (const [l, r] of intervals) {
        if (l > lastEnd) { result.push(s.substring(l, r+1)); lastEnd = r; }
    }
    return result;
}

function numberOfSubarrays(arr) {
    const MOD = 1e9 + 7;          // modulo as required
    let evenCnt = 1;              // empty prefix has even sum
    let oddCnt = 0;
    let parity = 0;               // 0 = even, 1 = odd
    let ans = 0;

    for (let i = 0; i < arr.length; i++) {
        parity ^= (arr[i] & 1);    // update parity of current prefix sum

        if (parity === 1) {        // prefix sum is odd
            ans = (ans + evenCnt) % MOD; // odd sub‑arrays end here
            oddCnt++;                     // store this odd prefix
        } else {                   // prefix sum is even
            ans = (ans + oddCnt) % MOD;  // odd sub‑arrays end here
            evenCnt++;                    // store this even prefix
        }
    }
    return ans;
}

function shuffleString(s, indices) {
  const n = s.length;
  const shuffled = new Array(n);
  for (let i = 0; i < n; i++) {
    shuffled[indices[i]] = s[i]; // place each character at its target index
  }
  return shuffled.join('');
}

function numSplits(s) {
  const n = s.length;
  const leftDistinct = new Array(n).fill(0);
  const rightDistinct = new Array(n).fill(0);
  let seen = new Set();
  for (let i = 0; i < n; i++) { seen.add(s[i]); leftDistinct[i] = seen.size; }
  seen = new Set();
  for (let i = n - 1; i >= 0; i--) { seen.add(s[i]); rightDistinct[i] = seen.size; }
  let count = 0;
  for (let i = 0; i < n - 1; i++) if (leftDistinct[i] === rightDistinct[i+1]) count++;
  return count;
}

function minSuffixFlips(target) {
    let flips = 0;
    let parity = 0; // current parity of suffix flips
    for (let i = 0; i < target.length; i++) {
        const bit = target.charCodeAt(i) - 48; // convert '0'/'1' to 0/1
        if ((bit ^ parity) === 1) { // effective bit is 1 → need a flip here
            flips++;
            parity ^= 1; // toggle parity for the remaining suffix
        }
    }
    return flips;
}

function minNumberOperations(target) {
    let ops = target[0];                         // operations for the first element
    for (let i = 1; i < target.length; i++) {
        const diff = target[i] - target[i - 1];
        if (diff > 0) ops += diff;               // add only positive increases
    }
    return ops;
}

function minSwaps(grid) {
    const n = grid.length;
    const rightmostOne = new Array(n);
    // compute rightmost 1 for each row
    for (let i = 0; i < n; i++) {
        let pos = -1;
        for (let j = n - 1; j >= 0; j--) {
            if (grid[i][j] === 1) { pos = j; break; }
        }
        rightmostOne[i] = pos;
    }

    let swaps = 0;
    // place rows one by one from top to bottom
    for (let i = 0; i < n; i++) {
        let j = i;
        // find the first row that can stay at position i
        while (j < n && rightmostOne[j] > i) j++;
        if (j === n) return -1;               // no suitable row → impossible
        // bring row j up to i by adjacent swaps
        while (j > i) {
            const tmp = rightmostOne[j];
            rightmostOne[j] = rightmostOne[j - 1];
            rightmostOne[j - 1] = tmp;
            swaps++;
            j--;
        }
    }
    return swaps;
}

function countPairs(root, distance) {
    let goodPairs = 0;                     // total answer

    // post‑order DFS returning an array of distances from this node to its leaves
    function dfs(node) {
        if (!node) return [];              // empty subtree

        // leaf node: distance 1 to itself (the edge to its parent)
        if (!node.left && !node.right) return [1];

        const leftDist  = dfs(node.left);
        const rightDist = dfs(node.right);

        // count good pairs formed by one leaf in left subtree and one in right subtree
        for (let l of leftDist) {
            for (let r of rightDist) {
                if (l + r <= distance) goodPairs++;
            }
        }

        // build distance list for the current node
        const curDist = [];
        for (let d of leftDist) {
            if (d + 1 <= distance) curDist.push(d + 1);
        }
        for (let d of rightDist) {
            if (d + 1 <= distance) curDist.push(d + 1);
        }
        return curDist;
    }

    dfs(root);
    return goodPairs;
}

function stringCompressionII(s, k) {
    const n = s.length;
    const memo = new Map();
    const dp = (i, kLeft) => {
        if (i === n) return 0;
        const key = i + ',' + kLeft;
        if (memo.has(key)) return memo.get(key);
        let best = kLeft > 0 ? dp(i + 1, kLeft - 1) : n;
        let cnt = 0, delCnt = 0;
        for (let j = i; j < n; j++) {
            if (s[j] === s[i]) cnt++; else delCnt++;
            if (delCnt > kLeft) break;
            let add = 1;
            if (cnt > 1) add += String(cnt).length;
            const cand = add + dp(j + 1, kLeft - delCnt);
            if (cand < best) best = cand;
        }
        memo.set(key, best);
        return best;
    };
    return dp(0, k);
}

function countGoodTriplets(arr, a, b, c) {
    var n = arr.length;
    var good = 0;
    // enumerate all triples i < j < k and test the three conditions
    for (var i = 0; i < n - 2; i++) {
        for (var j = i + 1; j < n - 1; j++) {
            if (Math.abs(arr[i] - arr[j]) > a) continue;          // prune early
            for (var k = j + 1; k < n; k++) {
                if (Math.abs(arr[j] - arr[k]) <= b &&
                    Math.abs(arr[i] - arr[k]) <= c) {
                    good++;
                }
            }
        }
    }
    return good;
}

function canConvertString(s, t, k) {
    if (s.length !== t.length) return false;               // lengths must match
    const need = new Array(26).fill(0);                    // count of each required shift

    for (let i = 0; i < s.length; i++) {                   // compute needed shifts
        const diff = (t.charCodeAt(i) - s.charCodeAt(i) + 26) % 26;
        if (diff !== 0) need[diff]++;                      // ignore already equal chars
    }

    for (let r = 1; r < 26; r++) {                         // check availability of moves
        if (need[r] === 0) continue;
        if (k < r) return false;                           // smallest move with this remainder is larger than k
        const maxMoves = Math.floor((k - r) / 26) + 1;     // how many moves ≤ k have remainder r
        if (need[r] > maxMoves) return false;              // not enough moves for this remainder
    }
    return true;                                            // all required shifts can be assigned
}

function findWinner(arr, k) {
    let champion = arr[0];      // current element at position 0
    let winCnt = 0;             // consecutive wins of champion

    // If k is large enough, the global maximum will win for sure
    if (k >= arr.length - 1) {
        for (let v of arr) if (v > champion) champion = v;
        return champion;
    }

    for (let i = 1; i < arr.length; i++) {
        if (champion > arr[i]) {          // champion stays, wins this round
            winCnt++;
        } else {                          // arr[i] becomes new champion
            champion = arr[i];
            winCnt = 1;                   // first win for the new champion
        }
        if (winCnt === k) return champion; // k consecutive wins achieved
    }
    // If loop finishes, champion is the maximum element
    return champion;
}

function minInsertions(s) {
    var insertions = 0, need = 0;                 // insertions = answer, need = how many ')' are required
    for (var i = 0; i < s.length; i++) {
        var ch = s[i];
        if (ch === '(') {
            if (need % 2 === 1) { insertions++; need--; } // fix odd pending ')'
            need += 2;                                   // '(' needs two ')'
        } else { // ch === ')'
            need--;                                      // use one required ')'
            if (need < 0) { insertions++; need = 1; }   // extra ')', insert '(' before it
        }
    }
    insertions += need;                               // add remaining needed ')'
    return insertions;
}

function maxScore(nums1, nums2) {
    const MOD = 1e9 + 7;
    let i = 0, j = 0;
    let sum1 = 0, sum2 = 0, ans = 0;

    while (i < nums1.length && j < nums2.length) {
        if (nums1[i] < nums2[j]) {
            sum1 += nums1[i++];
        } else if (nums1[i] > nums2[j]) {
            sum2 += nums2[j++];
        } else {
            // accumulate into the running total - each common point closes off
            // an independent segment whose contribution must be added, not overwrite
            // the answer from previous segments
            ans += Math.max(sum1, sum2) + nums1[i];
            sum1 = 0; sum2 = 0;
            i++; j++;
        }
    }

    while (i < nums1.length) sum1 += nums1[i++];
    while (j < nums2.length) sum2 += nums2[j++];

    ans = (ans + Math.max(sum1, sum2)) % MOD;
    return ans;
}

function findKthMissingPositive(arr, k) {
    // binary search for the first index where missing count >= k
    let left = 0, right = arr.length - 1;
    while (left <= right) {
        const mid = Math.floor((left + right) / 2);
        const missing = arr[mid] - (mid + 1); // how many positives are missing up to arr[mid]
        if (missing < k) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    // if k is larger than all missing numbers inside the array
    if (left === arr.length) {
        const totalMissing = arr[arr.length - 1] - arr.length;
        return arr[arr.length - 1] + (k - totalMissing);
    }

    // compute the kth missing using the element at index left
    const missingAtLeft = arr[left] - (left + 1);
    return arr[left] - (missingAtLeft - k + 1);
}

function makeGoodString(s) {
  const stack = [];                         // stack to build the good string
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    const top = stack[stack.length - 1];
    // if current char and stack top are same letter with opposite case, remove the top
    if (stack.length && ch !== top && ch.toLowerCase() === top.toLowerCase()) {
      stack.pop();
    } else {
      stack.push(ch);
    }
  }
  return stack.join('');
}

function longestAwesome(s) {
    var earliest = new Array(1 << 10).fill(-1); // store first index of each mask
    earliest[0] = 0;                            // empty prefix
    var mask = 0;
    var maxLen = 0;

    for (var i = 0; i < s.length; i++) {
        mask ^= 1 << (s.charCodeAt(i) - 48);    // toggle parity of current digit

        // case 1: same mask → all even counts
        if (earliest[mask] !== -1) {
            maxLen = Math.max(maxLen, i + 1 - earliest[mask]);
        } else {
            earliest[mask] = i + 1;             // store earliest occurrence
        }

        // case 2: mask differs by one bit → exactly one odd count
        for (var b = 0; b < 10; b++) {
            var toggled = mask ^ (1 << b);
            if (earliest[toggled] !== -1) {
                maxLen = Math.max(maxLen, i + 1 - earliest[toggled]);
            }
        }
    }
    return maxLen;
}

function minCost(n, cuts) {
    const points = [0, ...cuts, n].sort((a,b) => a-b);
    const m = points.length;
    const dp = Array.from({length:m}, () => new Array(m).fill(0));
    for (let len = 2; len < m; len++) {
        for (let i = 0; i + len < m; i++) {
            const j = i + len;
            let best = Infinity;
            for (let k = i+1; k < j; k++) {
                best = Math.min(best, dp[i][k] + dp[k][j]);
            }
            dp[i][j] = best + (points[j] - points[i]);
        }
    }
    return dp[0][m-1];
}

function findKthBit(n, k) {
    if (n === 1) return '0';                     // base case S1 = "0"
    const mid = 1 << (n - 1);                    // middle position = 2^(n-1)
    if (k === mid) return '1';                   // the central bit is always '1'
    if (k < mid) return findKthBit(n - 1, k);    // left part: same as S_{n-1}
    const mirrored = (1 << n) - k;               // right part maps to left via reverse
    const bit = findKthBit(n - 1, mirrored);     // recurse on mirrored index
    return bit === '0' ? '1' : '0';               // invert the bit from left part
}

function minimumOperationsToMakeArrayEqual(n) {
    const a = Math.floor(n / 2);
    const b = n - a;
    return a * b;
}

function maxNonOverlappingSubarrays(nums, target) {
  let pref = 0;
  let count = 0;
  const reachable = new Set();
  reachable.add(0);

  for (let i = 0; i < nums.length; i++) {
    pref += nums[i];
    if (reachable.has(pref - target)) {
      count++;
      reachable.clear();
      reachable.add(pref);
    } else {
      // this branch was missing entirely - without recording every intermediate
      // prefix sum, only a subarray starting at index 0 (or right after a
      // previous match) could ever be detected
      reachable.add(pref);
    }
  }
  return count;
}

function threeConsecutiveOdds(arr) {
  let consecutive = 0;                       // count of current consecutive odds
  for (let i = 0; i < arr.length; i++) {
    if (arr[i] % 2 !== 0) {                  // odd element
      consecutive++;                         // extend streak
      if (consecutive === 3) return true;    // found three odds in a row
    } else {
      consecutive = 0;                       // reset on even
    }
  }
  return false;
}

function minDays(n) {
    const memo = new Map();
    function f(n) {
        if (n <= 1) return n;
        if (memo.has(n)) return memo.get(n);
        const res = 1 + Math.min(n % 2 + f(Math.floor(n/2)), n % 3 + f(Math.floor(n/3)));
        memo.set(n, res);
        return res;
    }
    return f(n);
}

function maxMagneticForce(position, m) {
    // sort positions to enable greedy placement
    position.sort((a, b) => a - b);

    // helper: can we place m balls with at least 'dist' between them?
    function canPlace(dist) {
        let count = 1;                     // first ball at the leftmost basket
        let last = position[0];
        for (let i = 1; i < position.length; i++) {
            if (position[i] - last >= dist) {
                count++;
                last = position[i];
                if (count >= m) return true; // early exit
            }
        }
        return false;
    }

    let low = 0;
    let high = position[position.length - 1] - position[0];

    // binary search on the answer (maximising the minimum distance)
    while (low < high) {
        const mid = Math.floor((low + high + 1) / 2); // try larger half
        if (canPlace(mid)) low = mid;                 // feasible → keep it
        else high = mid - 1;                          // infeasible → shrink
    }
    return low;
}

function minimumNumbersOfFunctionCallsToMakeTargetArray(target) {
    if (!target.length) return 0;
    let totalPop = 0;
    let maxVal = 0;
    const popcount = (x) => { let c = 0; while (x) { c += x & 1; x >>>= 1; } return c; };
    for (const x of target) {
        if (x > maxVal) maxVal = x;
        totalPop += popcount(x);
    }
    if (maxVal === 0) return 0;
    const doubles = maxVal.toString(2).length - 1;
    return totalPop + doubles;
}

function thousandSeparator(n) {
    var s = String(Math.abs(n));          // convert number to string without sign
    var result = '';
    var count = 0;
    for (var i = s.length - 1; i >= 0; i--) {
        result = s[i] + result;           // build result from right to left
        count++;
        if (count % 3 === 0 && i !== 0)   // insert dot after every three digits
            result = '.' + result;
    }
    if (n < 0) result = '-' + result;     // restore negative sign if needed
    return result;
}

function minimumVertexSet(n, edges) {
    const indegree = new Array(n).fill(0);               // count incoming edges for each vertex
    for (let i = 0; i < edges.length; i++) {
        indegree[edges[i][1]]++;                         // increase indegree of destination
    }
    const result = [];                                   // vertices that must be chosen
    for (let v = 0; v < n; v++) {
        if (indegree[v] === 0) result.push(v);           // vertices with no incoming edges
    }
    return result;
}

function maxCoins(piles) {
    // sort ascending; Bob (smallest each round) always ends up with the smallest
    // n piles overall (indices 0..n-1), Alice always takes the current largest,
    // and "you" get every second pile among the remaining top 2n piles
    piles.sort((a, b) => a - b);
    const n = piles.length / 3;
    let total = 0;
    for (let i = n; i < piles.length; i += 2) {
        total += piles[i];
    }
    return total;
}

function stoneGameV(stoneValue) {
    const n = stoneValue.length;
    if (n < 2) return 0;
    const prefix = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) prefix[i + 1] = prefix[i] + stoneValue[i];
    const dp = Array.from({length: n}, () => new Array(n).fill(0));

    for (let length = 2; length <= n; length++) {
        for (let i = 0; i <= n - length; i++) {
            const j = i + length - 1;
            const total = prefix[j + 1] - prefix[i];
            let lo = i, hi = j - 1;
            while (lo < hi) {
                const mid = Math.floor((lo + hi + 1) / 2);
                const left = prefix[mid + 1] - prefix[i];
                if (left * 2 <= total) lo = mid; else hi = mid - 1;
            }
            let best = 0;
            for (const k of [lo, lo + 1]) {
                if (k < i || k >= j) continue;
                const left = prefix[k + 1] - prefix[i];
                const right = total - left;
                let val;
                if (left < right) val = left + dp[i][k];
                else if (left > right) val = right + dp[k + 1][j];
                else val = left + Math.max(dp[i][k], dp[k + 1][j]);
                if (val > best) best = val;
            }
            dp[i][j] = best;
        }
    }
    return dp[0][n - 1];
}

function detectCycle(grid) {
    const rows = grid.length;
    if (rows === 0) return false;
    const cols = grid[0].length;
    const visited = Array.from({ length: rows }, () => Array(cols).fill(false));
    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];   // four directions

    // depth‑first search, returns true if a cycle is found
    function dfs(r, c, pr, pc, ch) {
        visited[r][c] = true;
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;   // out of bounds
            if (grid[nr][nc] !== ch) continue;                           // different character
            if (nr === pr && nc === pc) continue;                        // don't go back to previous cell
            if (visited[nr][nc]) return true;                            // cycle detected
            if (dfs(nr, nc, r, c, ch)) return true;                      // continue deeper
        }
        return false;
    }

    for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
            if (!visited[r][c]) {
                if (dfs(r, c, -1, -1, grid[r][c])) return true; // start new component
            }
        }
    }
    return false;
}

function mostVisited(n, rounds) {
    const start = rounds[0];
    const end   = rounds[rounds.length - 1];
    const result = [];

    // build the sectors that lie on the final path (most visited)
    if (start <= end) {
        for (let i = start; i <= end; i++) result.push(i);
    } else {
        for (let i = 1; i <= end; i++) result.push(i);
        for (let i = start; i <= n; i++) result.push(i);
    }
    return result;
}

function minDays(grid) {
    const rows = grid.length, cols = grid[0].length;
    function countIslands(g) {
        const vis = Array.from({length:rows}, () => new Array(cols).fill(false));
        let count = 0;
        for (let r = 0; r < rows; r++) {
            for (let c = 0; c < cols; c++) {
                if (g[r][c] === 1 && !vis[r][c]) {
                    count++;
                    const stack = [[r,c]];
                    vis[r][c] = true;
                    while (stack.length) {
                        const [cr,cc] = stack.pop();
                        for (const [dr,dc] of [[1,0],[-1,0],[0,1],[0,-1]]) {
                            const nr=cr+dr, nc=cc+dc;
                            if (nr>=0&&nr<rows&&nc>=0&&nc<cols&&g[nr][nc]===1&&!vis[nr][nc]) {
                                vis[nr][nc]=true; stack.push([nr,nc]);
                            }
                        }
                    }
                }
            }
        }
        return count;
    }
    if (countIslands(grid) !== 1) return 0;
    for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
            if (grid[r][c] === 1) {
                grid[r][c] = 0;
                const cnt = countIslands(grid);
                grid[r][c] = 1;
                if (cnt !== 1) return 1;
            }
        }
    }
    return 2;
}

function findLatestGroupOfSizeM(arr, m) {
    const n = arr.length;
    if (m > n) return -1;
    if (m === n) return n;
    const size = new Array(n + 2).fill(0);
    const cnt = new Array(n + 1).fill(0);
    let ans = -1;
    for (let step = 1; step <= arr.length; step++) {
        const p = arr[step - 1];
        const leftLen = size[p - 1] || 0;
        const rightLen = size[p + 1] || 0;
        const total = leftLen + 1 + rightLen;
        if (leftLen) cnt[leftLen]--;
        if (rightLen) cnt[rightLen]--;
        cnt[total]++;
        size[p - leftLen] = total;
        size[p + rightLen] = total;
        if (cnt[m] > 0) ans = step;
    }
    return ans;
}

function numberOfWaysToReorderArrayToGetSameBST(nums) {
    const MOD = 1000000007n;
    const n = nums.length;
    if (n <= 1) return 0;

    const fact = new Array(n + 1).fill(1n);
    for (let i = 1; i <= n; i++) fact[i] = (fact[i - 1] * BigInt(i)) % MOD;
    const modpow = (base, exp, mod) => {
        base %= mod;
        let result = 1n;
        while (exp > 0n) {
            if (exp & 1n) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1n;
        }
        return result;
    };
    const invFact = new Array(n + 1).fill(1n);
    invFact[n] = modpow(fact[n], MOD - 2n, MOD);
    for (let i = n; i >= 1; i--) invFact[i - 1] = (invFact[i] * BigInt(i)) % MOD;

    const comb = (a, b) => {
        if (b < 0 || b > a) return 0n;
        return (fact[a] * invFact[b] % MOD) * invFact[a - b] % MOD;
    };

    const dfs = (sub) => {
        if (sub.length === 0) return [0, 1n];
        const root = sub[0];
        const left = sub.slice(1).filter(x => x < root);
        const right = sub.slice(1).filter(x => x > root);
        const [lsz, lways] = dfs(left);
        const [rsz, rways] = dfs(right);
        const total = lsz + rsz + 1;
        let ways = comb(lsz + rsz, lsz);
        ways = (ways * lways) % MOD;
        ways = (ways * rways) % MOD;
        return [total, ways];
    };

    const [, totalWays] = dfs(nums);
    let result = (totalWays - 1n) % MOD;
    if (result < 0n) result += MOD;
    return Number(result);
}

function detectPattern(arr, m, k) {
    const n = arr.length;
    if (m * k > n) return false;                     // quick reject

    const MOD = 1000000007;                          // prime modulus
    const BASE = 1000003;                            // base for rolling hash

    // prefix[i] = hash of arr[0..i-1]
    const prefix = new Array(n + 1).fill(0);
    const power = new Array(n + 1).fill(1);
    for (let i = 0; i < n; i++) {
        prefix[i + 1] = (prefix[i] * BASE + arr[i]) % MOD;
        power[i + 1] = (power[i] * BASE) % MOD;
    }

    // O(1) hash of sub‑array [l, r)
    function getHash(l, r) {
        const val = (prefix[r] - (prefix[l] * power[r - l]) % MOD + MOD) % MOD;
        return val;
    }

    const repeat = new Array(n).fill(0);             // repeat[i] = #identical blocks starting at i
    for (let i = n - m; i >= 0; i--) {
        // MAIN LOGIC: compare current block with the next block of length m
        if (i + 2 * m <= n && getHash(i, i + m) === getHash(i + m, i + 2 * m)) {
            repeat[i] = repeat[i + m] + 1;
        } else {
            repeat[i] = 1;
        }
        if (repeat[i] >= k) return true;            // found a pattern
    }
    return false;
}

function getMaxLen(nums) {
    let pos = 0;          // longest positive‑product subarray ending here
    let neg = 0;          // longest negative‑product subarray ending here
    let best = 0;         // answer

    for (let i = 0; i < nums.length; i++) {
        const x = nums[i];
        if (x > 0) {                     // positive number
            pos = pos + 1;
            neg = (neg > 0) ? neg + 1 : 0;
        } else if (x < 0) {              // negative number
            const newPos = (neg > 0) ? neg + 1 : 0;
            const newNeg = pos + 1;
            pos = newPos;
            neg = newNeg;
        } else {                         // zero resets everything
            pos = 0;
            neg = 0;
        }
        if (pos > best) best = pos;      // update answer
    }
    return best;
}

function countRoutes(locations, start, finish, fuel) {
    const MOD = 1_000_000_007;
    const n = locations.length;
    const memo = Array.from({ length: n }, () => Array(fuel + 1).fill(-1));

    function dfs(city, remaining) {                     // main recursion
        if (memo[city][remaining] !== -1) return memo[city][remaining];
        let ways = (city === finish) ? 1 : 0;           // count staying at finish
