function rearrangeSpaces(text) {
    // count total spaces
    let totalSpaces = 0;
    for (let ch of text) if (ch === ' ') totalSpaces++;

    // extract words
    const words = text.trim().split(/\s+/);
    const wordCount = words.length;

    // only one word → all spaces go to the end
    if (wordCount === 1) {
        return words[0] + ' '.repeat(totalSpaces);
    }

    // compute spaces per gap and remaining spaces
    const gapSpaces = Math.floor(totalSpaces / (wordCount - 1));
    const extraSpaces = totalSpaces % (wordCount - 1);

    // build result
    const between = ' '.repeat(gapSpaces);
    return words.join(between) + ' '.repeat(extraSpaces);
}

function maxUniqueSplit(s) {
    const n = s.length;
    let best = 0;                     // best answer found so far
    const used = new Set();           // substrings already taken in current path

    function dfs(pos, cnt) {
        if (pos === n) {              // reached the end → a complete split
            if (cnt > best) best = cnt;
            return;
        }
        // prune: even if we split every remaining character separately,
        // we cannot beat the current best
        if (cnt + (n - pos) <= best) return;

        for (let i = pos + 1; i <= n; i++) {   // try every possible next cut
            const sub = s.slice(pos, i);
            if (!used.has(sub)) {               // keep uniqueness
                used.add(sub);
                dfs(i, cnt + 1);                // recurse on the suffix
                used.delete(sub);               // backtrack
            }
        }
    }

    dfs(0, 0);
    return best;
}

function isPrintable(targetGrid) {
    const rows = targetGrid.length, cols = targetGrid[0].length;
    const bounds = new Map(); // color -> [minR,maxR,minC,maxC]
    for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
            const color = targetGrid[r][c];
            if (!bounds.has(color)) bounds.set(color, [r,r,c,c]);
            else {
                const b = bounds.get(color);
                b[0] = Math.min(b[0], r); b[1] = Math.max(b[1], r);
                b[2] = Math.min(b[2], c); b[3] = Math.max(b[3], c);
            }
        }
    }
    const colors = [...bounds.keys()];
    const removed = new Set();
    for (let iter = 0; iter < colors.length; iter++) {
        let progressed = false;
        for (const color of colors) {
            if (removed.has(color)) continue;
            const [minR,maxR,minC,maxC] = bounds.get(color);
            let ok = true;
            for (let r = minR; r <= maxR && ok; r++) {
                for (let c = minC; c <= maxC && ok; c++) {
                    const cell = targetGrid[r][c];
                    if (cell !== color && !removed.has(cell)) ok = false;
                }
            }
            if (ok) { removed.add(color); progressed = true; }
        }
        if (removed.size === colors.length) return true;
        if (!progressed) return false;
    }
    return removed.size === colors.length;
}

var maxProductPath = function(grid) {
