            const cur = ndp[mask];
            if (cur === INF) continue;
            for (let j = 0; j < m; j++) {
                const newMask = mask | (1 << j);
                const val = cur + row[j];
                if (val < ndp[newMask]) ndp[newMask] = val;
            }
        }
