            const mid = (lo + hi) >> 1;
            if (arr[mid] < val) lo = mid + 1; else hi = mid;
        }
        arr.splice(lo, 0, val);
    };
    const bisectLeft = (arr, val) => {
        let lo = 0, hi = arr.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (arr[mid] < val) lo = mid + 1; else hi = mid;
        }
        return lo;
    };

    for (let i = 0; i < n; i++) {
        const t = arrival[i];
        while (busy.length && busy[0][0] <= t) {
            const [, sid] = heapPop();
            insort(free, sid);
        }
        if (!free.length) continue;

        const start = i % k;
        let idx = bisectLeft(free, start);
        if (idx === free.length) idx = 0;

        const sid = free[idx];
        free.splice(idx, 1);
        handled[sid]++;
        heapPush([t + load[i], sid]);
    }

    const maxHandled = Math.max(...handled);
    const result = [];
    for (let i = 0; i < k; i++) if (handled[i] === maxHandled) result.push(i);
    return result;
}

function alertNames(keyName, keyTime) {
    const minutesMap = new Map();                     // name → list of minutes

    // build the map
    for (let i = 0; i < keyName.length; i++) {
        const name = keyName[i];
        const [h, m] = keyTime[i].split(':');
        const mins = Number(h) * 60 + Number(m);
        if (!minutesMap.has(name)) minutesMap.set(name, []);
        minutesMap.get(name).push(mins);
    }

    const alerted = [];

    for (const [name, times] of minutesMap) {
        times.sort((a, b) => a - b);                  // sort times for this employee
        // check three consecutive times within 60 minutes
        for (let i = 0; i + 2 < times.length; i++) {
            if (times[i + 2] - times[i] <= 60) {      // main logic
                alerted.push(name);
                break;                                 // one alert per employee is enough
            }
        }
    }

    alerted.sort();                                   // alphabetical order
    return alerted;
}

function restoreMatrix(rowSum, colSum) {
    var rows = rowSum.length,
        cols = colSum.length,
        matrix = Array.from({ length: rows }, () => Array(cols).fill(0));

    var i = 0, j = 0;
    while (i < rows && j < cols) {
        var val = Math.min(rowSum[i], colSum[j]); // main logic
        matrix[i][j] = val;
        rowSum[i] -= val;
        colSum[j] -= val;
        if (rowSum[i] === 0) i++;   // move to next row when its sum is satisfied
        if (colSum[j] === 0) j++;   // move to next column when its sum is satisfied
    }
    return matrix;
}

function specialArray(nums) {
    // sort descending so that the first k elements are the k largest numbers
    nums.sort((a, b) => b - a);
    const n = nums.length;
    for (let i = 0; i < n; i++) {
        const x = i + 1;                     // candidate: exactly i+1 numbers should be ≥ x
        // main logic: check that the i‑th element is ≥ x and the next one (if any) is < x
        if (nums[i] >= x && (i === n - 1 || nums[i + 1] < x)) {
