        }
    }
    return -1;                               // no suitable x found
}

function isEvenOddTree(root) {
    if (!root) return true;                     // empty tree is trivially valid
    const q = [root];
    let level = 0;

    while (q.length) {
        const sz = q.length;
        let prev = level % 2 === 0 ? -Infinity : Infinity; // init comparison bound

        for (let i = 0; i < sz; i++) {
            const node = q.shift();               // dequeue current node

            // ---- main logic ----
            if (level % 2 === 0) {                // even level: odd values, increasing
                if (node.val % 2 === 0 || node.val <= prev) return false;
            } else {                               // odd level: even values, decreasing
                if (node.val % 2 === 1 || node.val >= prev) return false;
            }
            // --------------------
            prev = node.val;                       // update previous value for this level

            if (node.left) q.push(node.left);      // enqueue children for next level
            if (node.right) q.push(node.right);
        }
        level++;                                   // move to next depth
    }
    return true;
}

function visiblePoints(points, angle, location) {
    const [locX, locY] = location;
    let samePlace = 0;                     // points at the observer location
    const angles = [];

    // compute angles for all points except those coinciding with location
    for (const [x, y] of points) {
        const dx = x - locX, dy = y - locY;
        if (dx === 0 && dy === 0) { samePlace++; continue; }
        let deg = Math.atan2(dy, dx) * 180 / Math.PI;
        if (deg < 0) deg += 360;           // map to [0, 360)
        angles.push(deg);
    }

    if (angles.length === 0) return samePlace;   // only coincident points

    // if the field of view covers the whole circle, all points are visible
    if (angle >= 360) return points.length;

    angles.sort((a, b) => a - b);                // O(N log N)

    // duplicate angles to handle wrap‑around intervals
    const extended = angles.concat(angles.map(v => v + 360));

    let maxInWindow = 0, left = 0;
    // sliding window: expand right, shrink left while window too wide
    for (let right = 0; right < extended.length; right++) {
        while (extended[right] - extended[left] > angle + 1e-9) left++;
        const windowSize = right - left + 1;
        if (windowSize > maxInWindow) maxInWindow = windowSize;
    }

    return maxInWindow + samePlace;
}

function maxDepth(s) {
  let current = 0;          // current nesting level
  let best = 0;             // maximum nesting found

  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (ch === '(') {       // entering a deeper level
      current++;
      if (current > best) best = current; // update max depth
    } else if (ch === ')') { // leaving a level
      current--;
    }
  }
  return best;
}

function minimumOneBitOperations(n) {
    if (n === 0) return 0;
    let highest = 31 - Math.clz32(n);
    let mask = 1 << highest;
    return ((mask << 1) - 1) - minimumOneBitOperations(n ^ mask);
