function countSubtreesWithMaxDistanceBetweenCities(n, edges) {
    const adj = Array.from({length: n}, () => []);
    for (const [u0, v0] of edges) {
        const u = u0 - 1, v = v0 - 1;
        adj[u].push(v);
        adj[v].push(u);
    }

    const bfs = (start, mask) => {
        const q = [start];
        let head = 0;
        let visitedMask = 1 << start;
        const dist = new Array(n).fill(-1);
        dist[start] = 0;
        let far = start;
        while (head < q.length) {
            const u = q[head++];
            const du = dist[u];
            for (const v of adj[u]) {
                if (((mask >> v) & 1) && !((visitedMask >> v) & 1)) {
                    visitedMask |= (1 << v);
                    dist[v] = du + 1;
                    q.push(v);
                    if (dist[v] > dist[far]) far = v;
                }
            }
        }
        return [far, dist[far], visitedMask];
    };

    const ans = new Array(n - 1).fill(0);
    const totalMasks = 1 << n;
    for (let mask = 1; mask < totalMasks; mask++) {
        if ((mask & (mask - 1)) === 0) continue; // single node
        const start = Math.log2(mask & -mask) | 0;
        const [far1, , visited] = bfs(start, mask);
        if (visited !== mask) continue;
        const [, diameter] = bfs(far1, mask);
        if (diameter >= 1) ans[diameter - 1]++;
    }
    return ans;
}

function meanAfterRemoving(arr) {
    const n = arr.length;
    const k = Math.floor(n * 0.05);          // number of elements to drop from each end
    if (k === 0) {                           // nothing to remove
        const total = arr.reduce((s, v) => s + v, 0);
        return parseFloat((total / n).toFixed(5));
    }
    arr.sort((a, b) => a - b);               // sort ascending
    let sum = 0;
    for (let i = k; i < n - k; ++i) {        // sum the middle part
        sum += arr[i];
    }
    const mean = sum / (n - 2 * k);
    return parseFloat(mean.toFixed(5));      // keep 5 decimal digits
}

function maximalNetworkRank(n, roads) {
  // degree[i] = number of roads incident to city i
  const degree = new Array(n).fill(0);
  // adjacency[i] = set of cities directly connected to i
  const adjacency = Array.from({ length: n }, () => new Set());

  for (const [a, b] of roads) {
    degree[a]++; degree[b]++;
    adjacency[a].add(b);
    adjacency[b].add(a);
  }

  let best = 0;
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      // rank = sum of degrees minus 1 if i and j share a road
      const rank = degree[i] + degree[j] - (adjacency[i].has(j) ? 1 : 0);
      if (rank > best) best = rank;
    }
  }
  return best;
}

function coordinateWithMaxNetworkQuality(towers, radius) {
    // 1. overall bounds of towers
    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
    for (let i = 0; i < towers.length; i++) {
        const [x, y] = towers[i];
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
        if (y < minY) minY = y;
        if (y > maxY) maxY = y;
    }

    let bestQuality = -1, bestX = 0, bestY = 0;

    // 2. scan every integer point in the extended bounding box
    for (let x = minX - radius; x <= maxX + radius; x++) {
        for (let y = minY - radius; y <= maxY + radius; y++) {
            let total = 0;
            // main logic: sum contributions of reachable towers
            for (let i = 0; i < towers.length; i++) {
                const [tx, ty, q] = towers[i];
                const dx = x - tx;
                const dy = y - ty;
                const dist = Math.sqrt(dx * dx + dy * dy);
                if (dist <= radius) {
                    total += Math.floor(q / (1 + dist));
                }
            }
            // keep best (lexicographically smallest on tie)
            if (total > bestQuality ||
                (total === bestQuality && (x < bestX || (x === bestX && y < bestY)))) {
                bestQuality = total;
                bestX = x;
                bestY = y;
            }
        }
    }
    return [bestX, bestY];
}

function longestSubstringBetweenEqualChars(s) {
    // store the first index of each character
    const firstPos = Object.create(null);
    let best = -1;                                   // longest length found

    for (let i = 0; i < s.length; i++) {
        const ch = s[i];
        if (firstPos[ch] === undefined) {           // first time we see ch
            firstPos[ch] = i;
        } else {                                     // ch seen before
            const len = i - firstPos[ch] - 1;        // length between the pair
            if (len > best) best = len;              // update maximum
        }
    }
    return best;
}

function numberOfSetsOfKNonOverlappingLineSegments(n, k) {
    const MOD = 1000000007n;
    if (k === 0) return 1;
    if (k > n - 1) return 0;

    const total = n + k - 1;
    const choose = 2 * k;

    const fact = new Array(total + 1).fill(1n);
    for (let i = 2; i <= total; i++) fact[i] = (fact[i - 1] * BigInt(i)) % MOD;

    const modpow = (base, exp, mod) => {
        base %= mod;
        let result = 1n;
        while (exp > 0n) {
            if (exp & 1n) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1n;
        }
        return result;
    };
    const invFact = new Array(total + 1).fill(1n);
    invFact[total] = modpow(fact[total], MOD - 2n, MOD);
    for (let i = total; i >= 1; i--) invFact[i - 1] = (invFact[i] * BigInt(i)) % MOD;

    const result = (fact[total] * invFact[choose] % MOD) * invFact[total - choose] % MOD;
    return Number(result);
}

function bestTeamScore(scores, ages) {
  const n = scores.length;
  const players = ages.map((a, i) => [a, scores[i]]);
  players.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const dp = new Array(n).fill(0);
  let best = 0;
  for (let i = 0; i < n; i++) {
    dp[i] = players[i][1];
    for (let j = 0; j < i; j++) {
      if (players[j][1] <= players[i][1]) dp[i] = Math.max(dp[i], dp[j] + players[i][1]);
    }
    best = Math.max(best, dp[i]);
  }
  return best;
}

class Fancy {
    constructor() {
        this.mod = 1000000007n;
        this.vals = [];
        this.mulAt = [];
        this.addAt = [];
        this.curMul = 1n;
        this.curAdd = 0n;
    }
    append(val) {
        this.vals.push(BigInt(val) % this.mod);
        this.mulAt.push(this.curMul);
        this.addAt.push(this.curAdd);
    }
    addAll(inc) { this.curAdd = (this.curAdd + BigInt(inc)) % this.mod; }
    multAll(m) {
        this.curMul = this.curMul * BigInt(m) % this.mod;
        this.curAdd = this.curAdd * BigInt(m) % this.mod;
    }
    getIndex(idx) {
        const mod = this.mod;
        if (idx < 0 || idx >= this.vals.length) return -1;
        const factor = this.curMul * modInv(this.mulAt[idx], mod) % mod;
        const addPart = (this.curAdd - this.addAt[idx] * factor % mod + mod) % mod;
        return Number((this.vals[idx] * factor % mod + addPart) % mod);
    }
}
function modPow(base, exp, mod) {
    let result = 1n; base %= mod;
    while (exp > 0n) { if (exp & 1n) result = result * base % mod; base = base * base % mod; exp >>= 1n; }
    return result;
}
