function slowestKey(releaseTimes, keysPressed) {
    let longestDuration = releaseTimes[0];          // duration of first key
    let resultKey = keysPressed[0];                // current answer

    for (let i = 1; i < releaseTimes.length; i++) { // iterate through remaining keys
        const duration = releaseTimes[i] - releaseTimes[i - 1];
        if (duration > longestDuration || (duration === longestDuration && keysPressed[i] > resultKey)) {
            longestDuration = duration;
            resultKey = keysPressed[i];
        }
    }
    return resultKey;
}

function minimumEffortPath(heights) {
    const rows = heights.length;
    const cols = heights[0].length;
    const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
    const INF = Number.MAX_SAFE_INTEGER;

    // distance[r][c] = minimal possible maximum edge weight to reach (r,c)
    const distance = Array.from({length: rows}, () => Array(cols).fill(INF));
    distance[0][0] = 0;

    // ----- binary min‑heap implementation -----
    const heap = [];
    function heapPush(node) { // node = [effort, r, c]
        heap.push(node);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p][0] <= heap[i][0]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]];
            i = p;
        }
    }
    function heapPop() {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            let i = 0;
            while (true) {
                let l = i * 2 + 1, r = i * 2 + 2, smallest = i;
                if (l < heap.length && heap[l][0] < heap[smallest][0]) smallest = l;
                if (r < heap.length && heap[r][0] < heap[smallest][0]) smallest = r;
                if (smallest === i) break;
                [heap[i], heap[smallest]] = [heap[smallest], heap[i]];
                i = smallest;
            }
        }
        return top;
    }
    // -----------------------------------------

    heapPush([0, 0, 0]); // start with effort 0 at (0,0)

    while (heap.length) {
        const [curEffort, r, c] = heapPop();
        if (r === rows - 1 && c === cols - 1) return curEffort; // reached target
        if (curEffort !== distance[r][c]) continue; // stale entry

        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
            const edge = Math.abs(heights[nr][nc] - heights[r][c]);
            const newEffort = Math.max(curEffort, edge); // main logic
            if (newEffort < distance[nr][nc]) {
                distance[nr][nc] = newEffort;
                heapPush([newEffort, nr, nc]);
            }
        }
    }
    return -1; // never reached (input guarantees a path)
}

// TIME: O(R·C·log(R·C)) SPACE: O(R·C)

function areConnected(n, threshold, queries) {
    // ---------- Union‑Find ----------
    const parent = new Int32Array(n + 1);
    const rank   = new Int8Array(n + 1);
    for (let i = 1; i <= n; ++i) parent[i] = i;

    function find(x) {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]]; // path compression
            x = parent[x];
        }
        return x;
    }
    function union(a, b) {
        let ra = find(a), rb = find(b);
        if (ra === rb) return;
        if (rank[ra] < rank[rb]) [ra, rb] = [rb, ra];
        parent[rb] = ra;
        if (rank[ra] === rank[rb]) ++rank[ra];
    }

    // ---------- unite numbers that share a divisor > threshold ----------
    for (let d = threshold + 1; d <= n; ++d) {
        // first multiple is d itself, start from 2*d to avoid self‑union
        for (let multiple = d * 2; multiple <= n; multiple += d) {
            union(d, multiple);
        }
    }

    // ---------- answer queries ----------
    const ans = new Array(queries.length);
    for (let i = 0; i < queries.length; ++i) {
        const [a, b] = queries[i];
        ans[i] = find(a) === find(b);
    }
    return ans;
}


