function lexicographicallySmallestStringAfterApplyingOperations(s, a, b) {
    const n = s.length;
    const visited = new Set([s]);
    const q = [s];
    let head = 0;
    let best = s;

    while (head < q.length) {
        const cur = q[head++];
        if (cur < best) best = cur;

        const lst = cur.split('');
        for (let i = 1; i < n; i += 2) {
            lst[i] = String((parseInt(lst[i], 10) + a) % 10);
        }
        let nxt = lst.join('');
        if (!visited.has(nxt)) { visited.add(nxt); q.push(nxt); }

        nxt = cur.slice(n - b) + cur.slice(0, n - b);
        if (!visited.has(nxt)) { visited.add(nxt); q.push(nxt); }
    }
    return best;
}

var checkArithmeticSubarrays = function(nums, l, r) {
    const m = l.length;
    const answer = new Array(m).fill(false);
    for (let i=0;i<m;i++) {
        const start=l[i], end=r[i];
        const length = end-start+1;
        if (length <= 2) { answer[i]=true; continue; }
        let minVal = nums[start], maxVal = nums[start];
        for (let j=start+1;j<=end;j++) {
            const v = nums[j];
            if (v<minVal) minVal=v;
            if (v>maxVal) maxVal=v;
        }
        if (maxVal===minVal) { answer[i]=true; continue; }
        if ((maxVal-minVal) % (length-1) !== 0) { answer[i]=false; continue; }
        const diff = (maxVal-minVal)/(length-1);
        const seen = new Array(length).fill(false);
        let ok = true;
        for (let j=start;j<=end;j++) {
            const v = nums[j];
            if ((v-minVal) % diff !== 0) { ok=false; break; }
            const idx = (v-minVal)/diff;
            if (idx<0 || idx>=length || seen[idx]) { ok=false; break; }
            seen[idx]=true;
        }
        answer[i]=ok;
    }
    return answer;
};

var matrixRankTransform = function(matrix) {
    const m = matrix.length, n = matrix[0].length;
    const valPos = new Map();
    for (let i=0;i<m;i++) for (let j=0;j<n;j++) {
        const v = matrix[i][j];
        if (!valPos.has(v)) valPos.set(v, []);
        valPos.get(v).push([i,j]);
    }
    const rowMax = new Array(m).fill(0);
    const colMax = new Array(n).fill(0);
    const answer = Array.from({length:m}, () => new Array(n).fill(0));
    const parent = Array.from({length:m*n}, (_,i)=>i);
    const rnk = new Array(m*n).fill(0);
    function find(x) {
        while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; }
        return x;
    }
    function union(x,y) {
        let rx=find(x), ry=find(y);
        if (rx===ry) return;
        if (rnk[rx] < rnk[ry]) parent[rx]=ry;
        else if (rnk[rx] > rnk[ry]) parent[ry]=rx;
        else { parent[ry]=rx; rnk[rx]++; }
    }
    const values = Array.from(valPos.keys()).sort((a,b)=>a-b);
    for (const value of values) {
        const positions = valPos.get(value);
        for (const [i,j] of positions) {
            const idx = i*n+j;
            parent[idx] = idx;
            rnk[idx] = 0;
        }
        const rowRep = new Map(), colRep = new Map();
        for (const [i,j] of positions) {
            const idx = i*n+j;
            if (!rowRep.has(i)) rowRep.set(i, idx); else union(idx, rowRep.get(i));
            if (!colRep.has(j)) colRep.set(j, idx); else union(idx, colRep.get(j));
        }
        const compRank = new Map();
        for (const [i,j] of positions) {
            const idx = i*n+j;
            const root = find(idx);
            const needed = 1 + Math.max(rowMax[i], colMax[j]);
            if (!compRank.has(root) || needed > compRank.get(root)) compRank.set(root, needed);
        }
        for (const [i,j] of positions) {
            const idx = i*n+j;
            const root = find(idx);
            const r = compRank.get(root);
            answer[i][j] = r;
            rowMax[i] = r;
            colMax[j] = r;
        }
    }
    return answer;
};

function countVowelStrings(n) {
    // compute C(n+4,4) = (n+4)*(n+3)*(n+2)*(n+1) / 24
    var a = n + 1;
