  // sort by (frequency asc, value desc)
  return nums.sort((a, b) => {
    const fa = freq.get(a), fb = freq.get(b);
    if (fa !== fb) return fa - fb;      // lower frequency first
    return b - a;                       // same frequency → higher value first
