function kthSmallestInstruction(destination, k) {
    const row = destination[0];          // number of 'V'
    const col = destination[1];          // number of 'H'
    let v = row, h = col;
    let kk = BigInt(k);                  // work with BigInt
    let result = '';

    // compute nCr as BigInt (r ≤ n)
    function nCr(n, r) {
        if (r < 0 || r > n) return 0n;
        if (r > n - r) r = n - r;        // use smaller r
        let res = 1n;
        for (let i = 1; i <= r; i++) {
            res = res * BigInt(n - r + i) / BigInt(i);
        }
        return res;
    }

    while (v > 0 || h > 0) {
