        const countH = h > 0 ? nCr(v + h - 1, v) : 0n;   // MAIN LOGIC
        if (h > 0 && kk <= countH) {                     // choose 'H'
            result += 'H';
            h--;
        } else {                                         // choose 'V'
            if (h > 0) kk -= countH;                     // skip those starting with 'H'
            result += 'V';
            v--;
        }
    }
    return result;
}

