function furthestBuilding(heights, bricks, ladders) {
    // ---------- min‑heap implementation ----------
    const heap = [];
    const heapPush = (val) => {
        heap.push(val);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p] <= heap[i]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]];
            i = p;
        }
    };
    const heapPop = () => {
        if (heap.length === 1) return heap.pop();
        const min = heap[0];
        heap[0] = heap.pop();
        let i = 0;
        while (true) {
            let l = i * 2 + 1,
                r = i * 2 + 2,
                smallest = i;
            if (l < heap.length && heap[l] < heap[smallest]) smallest = l;
            if (r < heap.length && heap[r] < heap[smallest]) smallest = r;
            if (smallest === i) break;
            [heap[i], heap[smallest]] = [heap[smallest], heap[i]];
            i = smallest;
        }
        return min;
    };
    // ----------------------------------------------

    for (let i = 0; i < heights.length - 1; i++) {
        const diff = heights[i + 1] - heights[i];
        if (diff <= 0) continue;                 // no resources needed
        heapPush(diff);                           // assume we use a ladder for this jump
        if (heap.length > ladders) {              // too many ladders → replace smallest with bricks
            bricks -= heapPop();                  // pay bricks for the smallest jump
            if (bricks < 0) return i;             // cannot afford this step
        }
    }
    return heights.length - 1;                    // reached the last building
}

function getMaximumGenerated(n) {
    if (n === 0) return 0;                     // handle smallest case
    var nums = new Array(n + 1);
