    for (var i = 2; i <= n; i++) {
        if ((i & 1) === 0) {                   // i is even
            nums[i] = nums[i >> 1];            // nums[2*k] = nums[k]
        } else {                               // i is odd
            var k = i >> 1;                    // k = floor(i/2)
            nums[i] = nums[k] + nums[k + 1];   // nums[2*k+1] = nums[k] + nums[k+1]
        }
        if (nums[i] > maxVal) maxVal = nums[i]; // update maximum
    }
    return maxVal;
}

function createSortedArray(instructions) {
    const MOD = 1_000_000_007;
    const n = instructions.length;
    const maxVal = Math.max(...instructions);
    const bit = new Array(maxVal + 2).fill(0);

    function add(i, delta) {
        for (i += 1; i < bit.length; i += i & -i) bit[i] += delta;
    }
    function sum(i) {
        let res = 0;
        for (i += 1; i > 0; i -= i & -i) res += bit[i];
        return res;
    }

    let total = 0;
    for (let i = 0; i < n; i++) {
        const x = instructions[i];
        const less = sum(x - 1);
        const lessOrEqual = sum(x);
        const greater = i - lessOrEqual;
        total = (total + Math.min(less, greater)) % MOD;
        add(x, 1);
    }
    return total;
}

function maxProfit(inventory, orders) {
    const MOD = 1000000007n;                     // modulo constant
    // sort descending
    inventory.sort((a, b) => b - a);
    inventory.push(0);                           // sentinel for the last level
    let profit = 0n;
    let remaining = BigInt(orders);
    const n = inventory.length;

    for (let i = 0; i < n - 1; i++) {
        const cur = BigInt(inventory[i]);         // current level value
        const next = BigInt(inventory[i + 1]);    // next lower level value
        const diff = cur - next;                  // height of this level
        const cnt = BigInt(i + 1);                // how many colours share this level
        const balls = diff * cnt;                 // balls we could sell in this whole level

        if (remaining >= balls) {                 // ----- sell whole level -----
            // sum of arithmetic series: (cur + next + 1) * diff / 2
            const levelSum = (cur + next + 1n) * diff / 2n;
            profit += levelSum * cnt;
            remaining -= balls;
        } else {                                   // ----- sell partial level -----
            const fullRounds = remaining / cnt;   // full decrements for each colour
            const remainder = remaining % cnt;    // extra balls of the same final value
            const low = cur - fullRounds;         // final value after fullRounds

            // sum for the full rounds
            const sumFull = (cur + low + 1n) * fullRounds / 2n;
            profit += sumFull * cnt;

            // add the remainder balls (each worth 'low')
            profit += remainder * low;
            remaining = 0n;
            break;
        }
    }
    return Number(profit % MOD);
}

function canDistribute(nums, quantity) {
    // count frequencies of each distinct integer
    const freqMap = new Map();
    for (const v of nums) {
        freqMap.set(v, (freqMap.get(v) || 0) + 1);
    }
    const counts = Array.from(freqMap.values());          // u ≤ 50

    const m = quantity.length;
    const fullMask = (1 << m) - 1;

    // pre‑compute total quantity for every subset of customers
    const need = new Array(1 << m).fill(0);
    for (let mask = 1; mask <= fullMask; ++mask) {
        const lsb = mask & -mask;                         // lowest set bit
        const idx = Math.clz32(lsb) - (32 - m);           // position of that bit (0‑based)
        need[mask] = need[mask ^ lsb] + quantity[idx];
    }

    // dp[mask] = reachable?
    const dp = new Array(1 << m).fill(false);
    dp[0] = true;

    // main DP over frequencies
    for (const c of counts) {
        const next = dp.slice();                          // copy current reachable states
        for (let mask = 0; mask <= fullMask; ++mask) {
            if (!dp[mask]) continue;                       // skip unreachable states
            const remaining = fullMask ^ mask;            // customers not yet satisfied
            // iterate over all sub‑masks of 'remaining'
            for (let sub = remaining; sub; sub = (sub - 1) & remaining) {
                if (need[sub] <= c) {                     // this frequency can cover 'sub'
                    next[mask | sub] = true;
                }
            }
        }
        // replace dp with the newly reachable states
        for (let i = 0; i <= fullMask; ++i) dp[i] = next[i];
    }

    return dp[fullMask];
}

function decrypt(code, k) {
    const n = code.length;
    const result = new Array(n);
    if (k === 0) {                     // all zeros when k is zero
        result.fill(0);
        return result;
    }
    if (k > 0) {
        let windowSum = 0;
        for (let i = 1; i <= k; i++)               // initial sum of next k elements for i = 0
            windowSum += code[i % n];
        for (let i = 0; i < n; i++) {
            result[i] = windowSum;                  // assign current window sum
            windowSum -= code[(i + 1) % n];         // remove element leaving the window
            windowSum += code[(i + k + 1) % n];     // add new element entering the window
        }
    } else {
        const m = -k;                               // number of previous elements to sum
        let windowSum = 0;
        for (let i = 0; i < m; i++)                // initial sum of previous m elements for i = 0
            windowSum += code[(n - 1 - i + n) % n];
        for (let i = 0; i < n; i++) {
            result[i] = windowSum;                  // assign current window sum
            windowSum -= code[(i - m + n) % n];     // remove element leaving the window
            windowSum += code[i];                   // add new element entering the window
        }
    }
    return result;
}

function minDeletion(s) {
