function minOperations(nums, x) {
    const n = nums.length;
    let total = 0;
    for (let i = 0; i < n; i++) total += nums[i];   // compute total sum

    const target = total - x;                       // sum we need to keep
    if (target === 0) return n;                    // remove all elements

    let left = 0, windowSum = 0, maxLen = -1;
    for (let right = 0; right < n; right++) {
        windowSum += nums[right];                   // expand window

        while (windowSum > target && left <= right) {
            windowSum -= nums[left++];              // shrink from left
        }

        if (windowSum === target) {                 // found a valid window
            const curLen = right - left + 1;
            if (curLen > maxLen) maxLen = curLen;   // keep longest
        }
    }

    return maxLen === -1 ? -1 : n - maxLen;         // minimal operations
}

function minimumJumps(forbidden, a, b, x) {
    const forbiddenSet = new Set(forbidden);
    const maxForbidden = Math.max(...forbidden, 0);
    const limit = Math.max(maxForbidden, x) + a + b;          // upper bound for positions

    const queue = [[0, 0, false]];                           // [position, steps, lastWasBackward]
    const visited = new Set(['0,false']);

    let head = 0;
    while (head < queue.length) {
        const [pos, steps, lastBack] = queue[head++];
        if (pos === x) return steps;                         // reached home

        // forward jump
        const forward = pos + a;
        const fKey = `${forward},false`;
        if (forward <= limit && !forbiddenSet.has(forward) && !visited.has(fKey)) {
            visited.add(fKey);
            queue.push([forward, steps + 1, false]);
        }

        // backward jump (only if previous jump wasn't backward)
        if (!lastBack) {
            const backward = pos - b;
            const bKey = `${backward},true`;
            if (backward >= 0 && !forbiddenSet.has(backward) && !visited.has(bKey)) {
                visited.add(bKey);
                queue.push([backward, steps + 1, true]);
            }
        }
    }
    return -1;                                                // impossible
}

function OrderedStream(n) {
