function waysToMakeFair(nums) {
    let totalEven = 0, totalOdd = 0;
    // compute total sums for original even / odd positions
    for (let i = 0; i < nums.length; i++) {
        if (i % 2 === 0) totalEven += nums[i];
        else totalOdd += nums[i];
    }

    let leftEven = 0, leftOdd = 0, answer = 0;
    for (let i = 0; i < nums.length; i++) {
        // sums of the right side after removing i
        let rightEven = totalEven - leftEven - (i % 2 === 0 ? nums[i] : 0);
        let rightOdd  = totalOdd  - leftOdd  - (i % 2 === 1 ? nums[i] : 0);
        // new even / odd sums after removal
        if (leftEven + rightOdd === leftOdd + rightEven) answer++; // main logic
        // update left sums for next iteration
        if (i % 2 === 0) leftEven += nums[i];
        else leftOdd += nums[i];
    }
    return answer;
}

function maxGridHappiness(m, n, introvertsCount, extrovertsCount) {
    const pow3 = new Array(n);
    pow3[0] = 1;
    for (let i = 1; i < n; i++) pow3[i] = pow3[i - 1] * 3;
    const maskCount = Math.pow(3, n);
    const introCnt = new Array(maskCount);
    const extroCnt = new Array(maskCount);
    const rowBase = new Array(maskCount);
    const cellTypes = new Array(maskCount);
    function edge(a, b) {
        if (a === 0 || b === 0) return 0;
        if (a === 1 && b === 1) return -60;
        if (a === 2 && b === 2) return 40;
        return -10;
    }
    for (let mask = 0; mask < maskCount; mask++) {
        const types = new Array(n);
        let tmp = mask;
        let intro = 0, extro = 0, base = 0;
        for (let col = 0; col < n; col++) {
            const t = tmp % 3;
            types[col] = t;
            tmp = (tmp / 3) | 0;
            if (t === 1) { intro++; base += 120; }
            else if (t === 2) { extro++; base += 40; }
        }
        for (let col = 1; col < n; col++) {
            base += edge(types[col], types[col - 1]);
        }
        introCnt[mask] = intro;
        extroCnt[mask] = extro;
        rowBase[mask] = base;
        cellTypes[mask] = types;
    }
    const upContribution = Array.from({ length: maskCount }, () => new Int32Array(maskCount));
    for (let prev = 0; prev < maskCount; prev++) {
        const up = cellTypes[prev];
        for (let cur = 0; cur < maskCount; cur++) {
            const curT = cellTypes[cur];
            let sum = 0;
            for (let col = 0; col < n; col++) {
                sum += edge(curT[col], up[col]);
            }
            upContribution[prev][cur] = sum;
        }
    }
    const Imax = introvertsCount, Emax = extrovertsCount;
    const size = (Imax + 1) * (Emax + 1) * maskCount;
    const idx = (i, e, mask) => ((i * (Emax + 1) + e) * maskCount + mask);
    let dpPrev = new Float64Array(size);
    dpPrev.fill(-Infinity);
    dpPrev[idx(0, 0, 0)] = 0;
    for (let row = 0; row < m; row++) {
        const dpCurr = new Float64Array(size);
        dpCurr.fill(-Infinity);
        for (let i = 0; i <= Imax; i++) {
            for (let e = 0; e <= Emax; e++) {
                for (let prevMask = 0; prevMask < maskCount; prevMask++) {
                    const curVal = dpPrev[idx(i, e, prevMask)];
                    if (curVal === -Infinity) continue;
                    for (let curMask = 0; curMask < maskCount; curMask++) {
                        const intro = introCnt[curMask];
                        const extro = extroCnt[curMask];
                        const ni = i + intro;
                        const ne = e + extro;
                        if (ni > Imax || ne > Emax) continue;
                        const newVal = curVal + rowBase[curMask] + upContribution[prevMask][curMask];
                        const index = idx(ni, ne, curMask);
                        if (newVal > dpCurr[index]) dpCurr[index] = newVal;
                    }
                }
            }
        }
        dpPrev = dpCurr;
    }
    let ans = 0;
    for (let i = 0; i <= Imax; i++) {
        for (let e = 0; e <= Emax; e++) {
            for (let mask = 0; mask < maskCount; mask++) {
                const val = dpPrev[idx(i, e, mask)];
                if (val > ans) ans = val;
            }
        }
    }
    return ans;
}
