function minEnergy(tasks) {
    // sort by (minimum - actual) descending
    tasks.sort(function (a, b) {
        return (b[1] - b[0]) - (a[1] - a[0]);
    });

    let cumulativeActual = 0;   // sum of actual values of processed tasks
    let required = 0;           // maximal (minimum + cumulativeActual) seen so far

    for (let i = 0; i < tasks.length; i++) {
        const actual = tasks[i][0];
        const minimum = tasks[i][1];
        // update required energy for the current task
        required = Math.max(required, minimum + cumulativeActual);
