function minimumMountainRemovals(nums) {
    const n = nums.length;
    const inc = new Array(n);
    const dec = new Array(n);

    // ---------- compute inc[i] (LIS ending at i) ----------
    let tails = [];
    for (let i = 0; i < n; i++) {
        const x = nums[i];
        // binary search first index >= x
        let l = 0, r = tails.length;
        while (l < r) {
            const m = (l + r) >> 1;
            if (tails[m] < x) l = m + 1;
            else r = m;
        }
        const pos = l;
        if (pos === tails.length) tails.push(x);
        else tails[pos] = x;
        inc[i] = pos + 1;               // length of LIS ending at i
    }

    // ---------- compute dec[i] (LDS starting at i) ----------
    tails = [];
    for (let i = n - 1; i >= 0; i--) {
        const x = nums[i];
        let l = 0, r = tails.length;
        while (l < r) {
            const m = (l + r) >> 1;
            if (tails[m] < x) l = m + 1;
            else r = m;
        }
        const pos = l;
        if (pos === tails.length) tails.push(x);
        else tails[pos] = x;
        dec[i] = pos + 1;               // length of LDS starting at i
    }

    // ---------- find best mountain ----------
    let best = 0;
    for (let i = 1; i < n - 1; i++) {
        if (inc[i] > 1 && dec[i] > 1) { // need both sides non‑trivial
            const cur = inc[i] + dec[i] - 1;
            if (cur > best) best = cur;
        }
    }
    return n - best;                    // elements to remove
}

function mergeInBetween(list1, a, b, list2) {
    // locate node before a and node after b in list1
    let prevA = null, cur = list1, idx = 0;
    while (idx < a) {               // stop right before a
        prevA = cur;
        cur = cur.next;
        idx++;
    }
    // cur is now at position a; advance to b
    while (idx <= b) {              // stop after b
        cur = cur.next;
        idx++;
    }
    const postB = cur;              // node after the removed segment

    // splice list2 in place of the removed segment
    if (prevA) prevA.next = list2;  // connect left part to list2
    else list1 = list2;             // a == 0, new head is list2

    // find tail of list2
    let tail2 = list2;
    while (tail2.next) tail2 = tail2.next;

    // connect tail of list2 to the right part
    tail2.next = postB;

    return list1;                   // head of the merged list
}

function smallestString(n, k) {
