        this.right = [];
    }
    pushFront(val) {
        this.left.unshift(val);
        if (this.left.length > this.right.length + 1) this.right.unshift(this.left.pop());
    }
    pushMiddle(val) {
        if (this.left.length > this.right.length) this.right.unshift(this.left.pop());
        this.left.push(val);
    }
    pushBack(val) {
        this.right.push(val);
        if (this.left.length < this.right.length) this.left.push(this.right.shift());
    }
    popFront() {
        if (this.left.length === 0 && this.right.length === 0) return -1;
        let val = this.left.length > 0 ? this.left.shift() : this.right.shift();
        if (this.left.length < this.right.length) this.left.push(this.right.shift());
        return val;
    }
    popMiddle() {
        if (this.left.length === 0 && this.right.length === 0) return -1;
        let val = this.left.pop();
        if (this.left.length < this.right.length) this.left.push(this.right.shift());
        return val;
    }
    popBack() {
        if (this.left.length === 0 && this.right.length === 0) return -1;
        let val = this.right.length > 0 ? this.right.pop() : this.left.pop();
        if (this.left.length > this.right.length + 1) this.right.unshift(this.left.pop());
        return val;
    }
}

function minimumDeviation(nums) {
    // ---------- max‑heap implementation ----------
    function MaxHeap() {
        this.data = [];
    }
    MaxHeap.prototype.peek = function () { return this.data[0]; };
    MaxHeap.prototype.push = function (val) {
        const a = this.data;
        a.push(val);
        let i = a.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (a[p] >= a[i]) break;
            [a[p], a[i]] = [a[i], a[p]];
            i = p;
        }
    };
    MaxHeap.prototype.pop = function () {
        const a = this.data;
        const top = a[0];
        const last = a.pop();
        if (a.length === 0) return top;
        a[0] = last;
        let i = 0;
        while (true) {
            let l = i * 2 + 1,
                r = i * 2 + 2,
                largest = i;
            if (l < a.length && a[l] > a[largest]) largest = l;
            if (r < a.length && a[r] > a[largest]) largest = r;
            if (largest === i) break;
            [a[i], a[largest]] = [a[largest], a[i]];
            i = largest;
        }
        return top;
    };
    // ----------------------------------------------

    const heap = new MaxHeap();
    let minVal = Infinity;

    // make every number even and fill the heap
    for (let x of nums) {
        if (x % 2 === 1) x *= 2;          // turn odd into even
        heap.push(x);
        if (x < minVal) minVal = x;
    }

    let answer = heap.peek() - minVal;

    // repeatedly lower the current maximum while it is even
    while (heap.peek() % 2 === 0) {
        const max = heap.pop();
        const newVal = max / 2;
        heap.push(newVal);
        if (newVal < minVal) minVal = newVal;
        const curDev = heap.peek() - minVal;
        if (curDev < answer) answer = curDev;
    }

    return answer;
}

function maximumWealth(accounts) {
    let richest = 0;                                   // track max wealth
    for (let i = 0; i < accounts.length; i++) {
        let sum = 0;
        for (let j = 0; j < accounts[i].length; j++) {
            sum += accounts[i][j];                    // accumulate wealth of customer i
        }
        if (sum > richest) richest = sum;              // update richest if needed
    }
    return richest;
}

function mostCompetitive(nums, k) {
    const stack = [];
    const n = nums.length;
    for (let i = 0; i < n; i++) {
        const cur = nums[i];
        // pop larger elements if we still have enough remaining numbers to fill k
        while (
            stack.length &&
            stack[stack.length - 1] > cur &&
            stack.length - 1 + (n - i) >= k
        ) {
            stack.pop();
        }
        // push current number if we haven't reached size k yet
        if (stack.length < k) {
            stack.push(cur);
        }
    }
    return stack;
}

function maxOperations(nums, k) {
    const freq = {};          // frequency map
    let pairs = 0;            // count of successful operations

    for (let i = 0; i < nums.length; i++) {
        const cur = nums[i];
        const need = k - cur;
        if (freq[need] > 0) { // if complement exists, form a pair
            freq[need]--;
            pairs++;
        } else {
            freq[cur] = (freq[cur] || 0) + 1;
        }
    }
    return pairs;
}

function concatenatedBinary(n) {
    const MOD = 1000000007;
    let result = 0;
    let bits = 0;                     // current bit‑length of i

    for (let i = 1; i <= n; i++) {
        // increase bit count when i is a power of two
        if ((i & (i - 1)) === 0) bits++;

        // main logic: shift left by bits and add i, keep modulo
        result = ( (result * Math.pow(2, bits)) % MOD + i ) % MOD;
    }
    return result;
}

function minMoves(nums, limit) {
    const n = nums.length;
    const maxSum = 2 * limit;
    const diff = new Array(maxSum + 2).fill(0); // difference array

    for (let i = 0; i < n / 2; ++i) {
        const a = nums[i];
        const b = nums[n - 1 - i];
        const sum = a + b;

        diff[2] += 2;                 // default: 2 moves for every sum
        diff[sum] -= 1;               // exact sum needs one less move
        diff[sum + 1] += 1;           // restore after sum

        const low = Math.min(a, b) + 1;
        const high = Math.max(a, b) + limit;
        diff[low] -= 1;               // interval where only 1 move is enough
        diff[high + 1] += 1;          // restore after high
    }

    let cur = 0;
    let answer = Infinity;
    for (let s = 2; s <= maxSum; ++s) {
        cur += diff[s];               // prefix sum → total moves for sum s
        if (cur < answer) answer = cur;
    }
    return answer;
}

function interpret(command) {
    let i = 0;                     // index in the input string
    const result = [];             // collect parsed parts

    while (i < command.length) {   // iterate through the whole string
        if (command[i] === 'G') {          // direct 'G'
            result.push('G');
            i += 1;
        } else if (command[i] === '(' && command[i + 1] === ')') { // "()"
            result.push('o');
            i += 2;
        } else {                            // "(al)"
            result.push('al');
            i += 4; // skip "(al)"
        }
    }
    return result.join('');        // concatenate all pieces
}

function sumAbsDifferences(nums) {
    const n = nums.length;
    const result = new Array(n);
    let totalSum = 0;
    for (let v of nums) totalSum += v;          // total sum of all elements

    let leftSum = 0;                             // sum of elements before i
    for (let i = 0; i < n; i++) {
        const cur = nums[i];
        const left = i * cur - leftSum;          // contribution from left side
        const right = (totalSum - leftSum - cur) - (n - i - 1) * cur; // right side
        result[i] = left + right;                // total absolute difference
        leftSum += cur;                           // update left sum for next i
    }
    return result;
}

function stoneGameVI(aliceValues, bobValues) {
    const n = aliceValues.length;
    const combined = new Array(n);
    for (let i = 0; i < n; i++) {
        combined[i] = aliceValues[i] + bobValues[i];
    }

    const indices = Array.from({ length: n }, (_, i) => i);
    indices.sort((i, j) => combined[j] - combined[i]); // sort by total value descending

    let aliceScore = 0, bobScore = 0;
    for (let turn = 0; turn < n; turn++) {
        const idx = indices[turn];
        if (turn % 2 === 0) {
            aliceScore += aliceValues[idx];   // Alice's turn
        } else {
            bobScore += bobValues[idx];       // Bob's turn
        }
    }

    if (aliceScore > bobScore) return 1;
    if (aliceScore < bobScore) return -1;
    return 0;
}

function minTrips(boxes, portsCount, maxBoxes, maxWeight) {
    const n = boxes.length;
    const pre = new Array(n + 1);
    pre[0] = 0;
    for (let i = 1; i <= n; i++) {
        if (i === 1 || boxes[i - 1][0] !== boxes[i - 2][0]) pre[i] = pre[i - 1] + 1;
        else pre[i] = pre[i - 1];
    }
    const dp = new Array(n + 1);
    dp[0] = 0;
    const dq = new Array(n + 1);
    let head = 0, tail = 0;
    dq[tail++] = 0;
    let left = 0, curWeight = 0, curBoxes = 0;
    for (let i = 1; i <= n; i++) {
        curWeight += boxes[i - 1][1];
        curBoxes++;
        while (curWeight > maxWeight || curBoxes > maxBoxes) {
            curWeight -= boxes[left][1];
            curBoxes--;
            left++;
        }
        while (head < tail && dq[head] < left) head++;
        const bestIdx = dq[head];
        dp[i] = pre[i] + 2 + (dp[bestIdx] - pre[bestIdx + 1]);
        if (i === n) break;
        const curVal = dp[i] - pre[i + 1];
        while (head < tail && (dp[dq[tail - 1]] - pre[dq[tail - 1] + 1]) >= curVal) tail--;
        dq[tail++] = i;
    }
    return dp[n];
}

function minIncompatibility(nums, k) {
    const n = nums.length;
    const g = n / k;                     // size of each group

    // ---------- impossible case ----------
    const freq = new Map();
    for (const v of nums) {
        freq.set(v, (freq.get(v) || 0) + 1);
        if (freq.get(v) > k) return -1; // a value appears too many times
    }

    const totalMask = 1 << n;
    const inc = new Int32Array(totalMask).fill(-1); // incompatibility of a mask

    // ---------- pre‑compute incompatibility of every valid group ----------
    const popcnt = (x) => {
        let c = 0;
        while (x) { x &= x - 1; c++; }
        return c;
    };
    for (let mask = 0; mask < totalMask; mask++) {
        if (popcnt(mask) !== g) continue;
        let min = Infinity, max = -Infinity;
        const seen = new Set();
        let ok = true;
        for (let i = 0; i < n; i++) if (mask & (1 << i)) {
            const v = nums[i];
            if (seen.has(v)) { ok = false; break; }
            seen.add(v);
            if (v < min) min = v;
            if (v > max) max = v;
        }
        if (ok) inc[mask] = max - min;   // valid group
    }

    // ---------- DP over masks ----------
    const INF = 1e9;
    const dp = new Int32Array(totalMask).fill(INF);
    dp[0] = 0;
    for (let mask = 1; mask < totalMask; mask++) {
        if (popcnt(mask) % g !== 0) continue; // cannot be formed by whole groups
        // iterate sub‑masks of size g that are valid
        for (let sub = mask; sub; sub = (sub - 1) & mask) {
            const cost = inc[sub];
            if (cost === -1) continue; // not a valid group
            const prev = dp[mask ^ sub];
            if (prev + cost < dp[mask]) dp[mask] = prev + cost;
        }
    }

    const ans = dp[totalMask - 1];
    return ans >= INF ? -1 : ans;
}

function maxHeight(cuboids) {
  // normalize each cuboid (allow any rotation)
  for (let i = 0; i < cuboids.length; i++) {
    cuboids[i].sort((a, b) => a - b);
  }

  // global ordering so that a possible lower cuboid appears earlier
  cuboids.sort((a, b) => {
    if (a[0] !== b[0]) return a[0] - b[0];
    if (a[1] !== b[1]) return a[1] - b[1];
    return a[2] - b[2];
  });

  const n = cuboids.length;
  const dp = new Array(n);
  let answer = 0;

  for (let i = 0; i < n; i++) {
    dp[i] = cuboids[i][2];               // height of the stack consisting only of i
    for (let j = 0; j < i; j++) {
      // main logic: can j be placed below i ?
      if (cuboids[j][0] <= cuboids[i][0] &&
          cuboids[j][1] <= cuboids[i][1] &&
          cuboids[j][2] <= cuboids[i][2]) {
        dp[i] = Math.max(dp[i], dp[j] + cuboids[i][2]);
      }
    }
    answer = Math.max(answer, dp[i]);
  }
  return answer;
}

function countConsistentStrings(allowed, words) {
    var allowedMask = 0;
    for (var i = 0; i < allowed.length; i++) {               // build bitmask of allowed chars
        allowedMask |= 1 << (allowed.charCodeAt(i) - 97);
    }

    var consistentCount = 0;
    for (var w = 0; w < words.length; w++) {
        var word = words[w];
        var isConsistent = true;
        for (var j = 0; j < word.length; j++) {               // check each char against mask
            if ((allowedMask & (1 << (word.charCodeAt(j) - 97))) === 0) {
                isConsistent = false;
                break;
            }
        }
        if (isConsistent) consistentCount++;
    }
    return consistentCount;
}

function reformatNumber(number) {
    // 1. keep only digits
    const digits = number.replace(/[^\d]/g, '');
    const groups = [];
    let i = 0;
    let remaining = digits.length;

    // 2. take groups of three while >4 digits remain
    while (remaining > 4) {
        groups.push(digits.slice(i, i + 3));
        i += 3;
        remaining -= 3;
    }

    // 3. handle the final 2‑4 digits
    if (remaining === 4) {
        groups.push(digits.slice(i, i + 2));
        groups.push(digits.slice(i + 2, i + 4));
    } else {
        groups.push(digits.slice(i));
    }

    // 4. join with dashes
    return groups.join('-');
}

function countMatches(n) {
