    return n - 1;
}

function minPartitions(n) {
    let maxDigit = 0;
    for (let i = 0; i < n.length; i++) {
        const digit = n.charCodeAt(i) - 48;          // convert char to integer
        if (digit > maxDigit) maxDigit = digit;     // keep track of largest digit
    }
