}

function stoneGameVII(stones) {
    const n = stones.length;
    const prefix = new Array(n + 1).fill(0);
    for (let i = 0; i < n; ++i) prefix[i + 1] = prefix[i] + stones[i]; // prefix sums

    const dp = Array.from({ length: n }, () => new Array(n).fill(0));

    for (let len = 2; len <= n; ++len) {               // length of interval
        for (let i = 0; i + len - 1 < n; ++i) {
            const j = i + len - 1;
            const sumLeft  = prefix[j + 1] - prefix[i + 1]; // sum(i+1, j)
            const sumRight = prefix[j] - prefix[i];       // sum(i, j-1)
            // choose the move that maximizes the current player's advantage
            dp[i][j] = Math.max(sumLeft - dp[i + 1][j],
                                sumRight - dp[i][j - 1]);
        }
    }
    return dp[0][n - 1]; // optimal difference Alice - Bob
}

function maximumErasureValue(nums) {
    const cnt = new Map();          // frequency of values inside the window
    let left = 0, curSum = 0, maxSum = 0;

    for (let right = 0; right < nums.length; right++) {
        const val = nums[right];
        // shrink window while val is already inside
        while (cnt.get(val) > 0) {
            const leftVal = nums[left];
            curSum -= leftVal;
            cnt.set(leftVal, cnt.get(leftVal) - 1);
            left++;
        }
        // add the new distinct element
        curSum += val;
        cnt.set(val, (cnt.get(val) || 0) + 1);
        if (curSum > maxSum) maxSum = curSum;
    }
    return maxSum;
}

function checkEdgeLimitedPaths(n, edgeList, queries) {
  // ---------- Union‑Find ----------
  const parent = new Array(n);
  const rank = new Array(n).fill(0);
  for (let i = 0; i < n; i++) parent[i] = i;

  function find(x) {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]]; // path compression
      x = parent[x];
    }
    return x;
  }

  function union(a, b) {
    let ra = find(a), rb = find(b);
    if (ra === rb) return;
    if (rank[ra] < rank[rb]) parent[ra] = rb;
    else if (rank[ra] > rank[rb]) parent[rb] = ra;
    else {
      parent[rb] = ra;
      rank[ra]++;
    }
  }

  // ---------- Sort edges and queries ----------
  edgeList.sort((e1, e2) => e1[2] - e2[2]); // by distance
  const queriesWithIdx = queries.map((q, i) => ({p: q[0], q: q[1], limit: q[2], idx: i}));
  queriesWithIdx.sort((a, b) => a.limit - b.limit); // by limit

  const answer = new Array(queries.length);
  let eIdx = 0;

  // ---------- Process queries ----------
  for (const {p, q, limit, idx} of queriesWithIdx) {
    // add all edges whose distance is strictly less than current limit
    while (eIdx < edgeList.length && edgeList[eIdx][2] < limit) {
      union(edgeList[eIdx][0], edgeList[eIdx][1]);
      eIdx++;
    }
    // check connectivity
    answer[idx] = find(p) === find(q);
  }

  return answer;
}
// TIME: O((E + Q) log (E + Q)) SPACE: O(n + E + Q)

function maximumBinaryString(binary) {
    const n = binary.length;
    const firstZero = binary.indexOf('0');
    if (firstZero === -1) return binary;
    const zeroCount = (binary.match(/0/g) || []).length;
    return '1'.repeat(firstZero + zeroCount - 1) + '0' + '1'.repeat(n - firstZero - zeroCount);
}

function maxResult(nums, k) {
    var n = nums.length;
    var dp = new Array(n);
    dp[0] = nums[0];
    var deque = [];               // stores indices with decreasing dp values
    deque.push(0);

    for (var i = 1; i < n; i++) {
        // discard indices that are farther than k steps behind i
        while (deque.length && deque[0] < i - k) deque.shift();

        dp[i] = nums[i] + dp[deque[0]];   // best reachable score for i

        // keep deque monotonic: remove smaller dp values from the back
        while (deque.length && dp[i] >= dp[deque[deque.length - 1]]) deque.pop();

        deque.push(i);
    }
    return dp[n - 1];
}

function averageWaitingTime(customers) {
    let totalWaiting = 0;          // sum of waiting times
    let currentTime = 0;           // when the chef becomes free

    for (let i = 0; i < customers.length; i++) {
        const arrival = customers[i][0];
        const cook = customers[i][1];

        if (currentTime < arrival) {          // chef waits for the next arrival
            currentTime = arrival;
        }

        const finish = currentTime + cook;    // order completion time
        totalWaiting += finish - arrival;     // waiting time for this customer
        currentTime = finish;                 // chef is free after finishing
    }

    return totalWaiting / customers.length;   // average waiting time
}

function findBall(grid) {
    const rows = grid.length;
    const cols = grid[0].length;
    const result = new Array(cols).fill(-1);          // answer array

    for (let start = 0; start < cols; start++) {     // try each ball
        let col = start;
        let stuck = false;

        for (let r = 0; r < rows; r++) {             // walk down the rows
            const dir = grid[r][col];                // direction of current board
            const nextCol = col + dir;               // where the ball wants to go

            // check wall hit or V‑shaped trap
            if (nextCol < 0 || nextCol >= cols || grid[r][nextCol] !== dir) {
                stuck = true;
                break;
            }

            col = nextCol;                           // move to next cell
        }

        if (!stuck) result[start] = col;             // ball exits here
    }

    return result;
}

function countStudents(students, sandwiches) {
    // simulate using counts instead of queue
    let cnt0 = 0, cnt1 = 0;
    for (let s of students) {
        if (s === 0) cnt0++;
        else cnt1++;
