    for (let sand of sandwiches) {
        if (sand === 0) {
            if (cnt0 > 0) cnt0--;
            else break;               // no student wants this sandwich
        } else {
            if (cnt1 > 0) cnt1--;
            else break;
        }
    }
    return cnt0 + cnt1;               // students left unable to eat
}

function minMoves(nums, k) {
    const pos = [];
    for (let i = 0; i < nums.length; i++) if (nums[i] === 1) pos.push(i);
    const n = pos.length;
    if (k <= 1) return 0;

    const adjusted = pos.map((p, i) => p - i);
    const pref = [0];
    for (const v of adjusted) pref.push(pref[pref.length - 1] + v);

    let answer = Infinity;
    for (let left = 0; left + k <= n; left++) {
        const right = left + k - 1;
        const medianIdx = left + Math.floor((k - 1) / 2);
        const median = adjusted[medianIdx];

        const leftDist = median * (medianIdx - left) - (pref[medianIdx] - pref[left]);
        const rightDist = (pref[right + 1] - pref[medianIdx + 1]) - median * (right - medianIdx);

        const moves = leftDist + rightDist; // no extra correction needed - the "adjusted" positions already account for it
        if (moves < answer) answer = moves;
    }
    return answer;
}

function halvesAreAlike(s) {
    var half = s.length >> 1;                 // length of each half
    var diff = 0;                             // vowel count difference (first - second)
    var vowels = "aeiouAEIOU";

    for (var i = 0; i < half; i++) {          // iterate over both halves simultaneously
        if (vowels.indexOf(s[i]) !== -1) diff++;          // vowel in first half
        if (vowels.indexOf(s[i + half]) !== -1) diff--;   // vowel in second half
    }

    return diff === 0;                        // true if counts are equal
}

function maxEatenApples(apples, days) {
    // ---------- min‑heap implementation ----------
    const heap = [];                     // stores objects {expire, count}
    const swap = (i, j) => { const t = heap[i]; heap[i] = heap[j]; heap[j] = t; };
    const up = (i) => {
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p].expire <= heap[i].expire) break;
            swap(i, p);
            i = p;
        }
    };
    const down = (i) => {
        const n = heap.length;
        while (true) {
            let l = i * 2 + 1, r = l + 1, smallest = i;
            if (l < n && heap[l].expire < heap[smallest].expire) smallest = l;
            if (r < n && heap[r].expire < heap[smallest].expire) smallest = r;
            if (smallest === i) break;
            swap(i, smallest);
            i = smallest;
        }
    };
    const push = (node) => { heap.push(node); up(heap.length - 1); };
    const pop = () => { if (heap.length === 1) return heap.pop(); const top = heap[0]; heap[0] = heap.pop(); down(0); return top; };
    const peek = () => heap[0];

    // ---------- main greedy loop ----------
    let day = 0, eaten = 0;
    while (day < apples.length || heap.length) {
        // add today's apples
        if (day < apples.length && apples[day] > 0) {
            push({expire: day + days[day], count: apples[day]});
        }
        // discard rotten batches
        while (heap.length && peek().expire <= day) pop();
        // eat one apple from the batch that expires soonest
        if (heap.length) {
            const top = peek();
            top.count--;
            eaten++;
            if (top.count === 0) pop();   // remove empty batch
        }
        day++;
    }
    return eaten;
}

function maximumXORWithAnElementFromArray(nums, queries) {
    nums = [...nums].sort((a, b) => a - b);
    const indexed = queries.map(([xi, mi], idx) => [mi, xi, idx]);
    indexed.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
    const ans = new Array(queries.length).fill(-1);

    const children = [[-1, -1]];
    const insert = (val) => {
