            let nxt = children[node][b];
            if (nxt === -1) {
                children.push([-1, -1]);
                nxt = children.length - 1;
                children[node][b] = nxt;
            }
            node = nxt;
        }
    };
    const queryMaxXor = (val) => {
        let node = 0, res = 0;
        for (let bit = 30; bit >= 0; bit--) {
            const b = (val >> bit) & 1;
            const toggled = b ^ 1;
            if (children[node][toggled] !== -1) {
                res |= (1 << bit);
                node = children[node][toggled];
            } else {
                node = children[node][b];
            }
        }
        return res;
    };

    let i = 0;
    const n = nums.length;
    for (const [mi, xi, idx] of indexed) {
        while (i < n && nums[i] <= mi) { insert(nums[i]); i++; }
        ans[idx] = i === 0 ? -1 : queryMaxXor(xi);
    }
