function countGoodMeals(deliciousness) {
    const MOD = 1_000_000_007;
    const freq = new Map();          // stores counts of values seen so far
    let ans = 0;

    // pre‑compute all powers of two that could be a possible sum
    const maxVal = Math.max(...deliciousness);
    const limit = maxVal * 2;
    const powers = [];
    for (let p = 1; p <= limit; p <<= 1) powers.push(p);

    for (let i = 0; i < deliciousness.length; i++) {
        const cur = deliciousness[i];
        // main logic: for each power, look for a complement already seen
        for (let j = 0; j < powers.length; j++) {
            const need = powers[j] - cur;
            if (freq.has(need)) {
                ans = (ans + freq.get(need)) % MOD;
            }
        }
        // record current value for future pairs
        freq.set(cur, (freq.get(cur) || 0) + 1);
    }
    return ans;
}

function waysToSplitArrayIntoThreeSubarrays(nums) {
    const MOD = 1000000007n;
    const n = nums.length;
    if (n < 3) return 0;
    const prefix = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];
    const total = prefix[n];
    let ans = 0n;
    let low = 1, high = 1;
    for (let i = 1; i < n - 1; i++) {
        const leftSum = prefix[i];
        if (low < i) low = i;
        if (high < low) high = low;
        while (low < n - 1 && prefix[low + 1] - prefix[i] < leftSum) low++;
        while (high < n - 1 && prefix[high + 1] - prefix[i] <= total - prefix[high + 1]) high++;
        if (low <= high - 1) ans = (ans + BigInt(high - low)) % MOD;
    }
    return Number(ans);
}

function maximumUnits(boxTypes, truckSize) {
    // sort by units per box descending
    boxTypes.sort(function(a, b) { return b[1] - a[1]; });

