function maximumScore(s, x, y) {
    // decide which substring is more valuable
    const first = x > y ? 'ab' : 'ba';      // higher‑value substring
    const firstScore = Math.max(x, y);
    const second = x > y ? 'ba' : 'ab';     // lower‑value substring
    const secondScore = Math.min(x, y);

    let total = 0;
    let stack = [];

    // first pass – remove all high‑value substrings
    for (const ch of s) {
        if (stack.length && stack[stack.length - 1] === first[0] && ch === first[1]) {
            stack.pop();                     // erase the matching pair
            total += firstScore;
        } else {
            stack.push(ch);
        }
    }

    // second pass – remove all low‑value substrings from the remaining string
    let stack2 = [];
    for (const ch of stack) {
        if (stack2.length && stack2[stack2.length - 1] === second[0] && ch === second[1]) {
            stack2.pop();
            total += secondScore;
        } else {
            stack2.push(ch);
        }
    }

    return total;
}

function minOperations(target, arr) {
    // map each value of target to its index
    const pos = {};
    for (let i = 0; i < target.length; i++) pos[target[i]] = i;

    // build the sequence of indices that appear in arr
    const seq = [];
    for (let v of arr) {
        if (pos.hasOwnProperty(v)) seq.push(pos[v]);   // keep only values that exist in target
    }

    // patience sorting to compute LIS length
    const tails = [];                                   // tails[i] = smallest possible tail of an increasing subsequence of length i+1
    for (let idx of seq) {
        // binary search for the first element >= idx
        let lo = 0, hi = tails.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (tails[mid] < idx) lo = mid + 1;
            else hi = mid;
        }
        if (lo === tails.length) tails.push(idx);      // extend LIS
        else tails[lo] = idx;                           // replace to keep tails minimal
    }

    return target.length - tails.length;               // missing elements = operations needed
}

function constructLargestValidSequence(n) {
    const len = 2 * n - 1;
    const res = new Array(len).fill(0);
    const used = new Array(n + 1).fill(false);

    function backtrack(pos) {
        if (pos === len) return true;
        if (res[pos] !== 0) return backtrack(pos + 1);
        for (let num = n; num >= 1; num--) {
            if (used[num]) continue;
            if (num === 1) {
                res[pos] = 1;
                used[1] = true;
                if (backtrack(pos + 1)) return true;
                res[pos] = 0;
                used[1] = false;
            } else {
                const second = pos + num;
                if (second < len && res[second] === 0) {
                    res[pos] = num; res[second] = num; used[num] = true;
                    if (backtrack(pos + 1)) return true;
                    res[pos] = 0; res[second] = 0; used[num] = false;
                }
            }
        }
        return false;
    }
    backtrack(0);
    return res;
}

function minimumHammingDistance(source, target, allowedSwaps) {
    const n = source.length;

    // Union‑Find initialization
    const parent = new Array(n);
    const rank = new Array(n).fill(0);
    for (let i = 0; i < n; i++) parent[i] = i;

    function find(x) {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    function union(x, y) {
        const rx = find(x), ry = find(y);
        if (rx === ry) return;
        if (rank[rx] < rank[ry]) parent[rx] = ry;
        else if (rank[rx] > rank[ry]) parent[ry] = rx;
        else { parent[ry] = rx; rank[rx]++; }
    }

    // build connected components from allowed swaps
    for (const [a, b] of allowedSwaps) union(a, b);   // main logic

    // group indices by root
    const groups = new Map();                         // main logic
    for (let i = 0; i < n; i++) {
        const root = find(i);
        if (!groups.has(root)) groups.set(root, []);
        groups.get(root).push(i);
    }

    let mismatches = 0;

    // for each component, count unmatched target values
    for (const indices of groups.values()) {
        const freq = new Map();                        // main logic
        for (const idx of indices) {
            const val = source[idx];
            freq.set(val, (freq.get(val) || 0) + 1);
        }
        for (const idx of indices) {
            const val = target[idx];
            if (freq.has(val) && freq.get(val) > 0) {
                freq.set(val, freq.get(val) - 1);
            } else {
                mismatches++;                          // main logic
            }
        }
    }
    return mismatches;
}

