function calculateMoney(n) {
    const fullWeeks = Math.floor(n / 7);          // number of complete weeks
    const extraDays = n % 7;                       // remaining days after full weeks

    // sum of all complete weeks: 28 per week + 7 * (0 + 1 + … + (fullWeeks‑1))
    const totalFullWeeks = 28 * fullWeeks + 7 * fullWeeks * (fullWeeks - 1) / 2;

    // sum of the remaining days in the next week
    const totalExtra = extraDays * (fullWeeks + 1) + extraDays * (extraDays - 1) / 2;

    return totalFullWeeks + totalExtra;
}

