function tupleSameProduct(nums) {
    const freq = Object.create(null);          // product → count of unordered pairs
    const n = nums.length;
    for (let i = 0; i < n; i++) {               // enumerate all unordered pairs
        for (let j = i + 1; j < n; j++) {
