function checkWays(pairs) {
  const MAX = 510;
  const relations = Array.from({length: MAX}, () => new Array(MAX).fill(false));
  const lists = Array.from({length: MAX}, () => []);
  for (const [x, y] of pairs) {
    relations[x][y] = true; relations[y][x] = true;
    lists[x].push(y); lists[y].push(x);
  }
  const indices = [];
  for (let i = 1; i < MAX; i++) {
    if (lists[i].length > 0) { indices.push(i); relations[i][i] = true; }
  }
  indices.sort((a, b) => lists[a].length - lists[b].length);
  let equal = false, rootCount = 0;
  const size = indices.length;
  for (let i = 0; i < size; i++) {
    let j = i + 1;
    while (j < size && !relations[indices[i]][indices[j]]) j++;
    if (j < size) {
      if (lists[indices[i]].length === lists[indices[j]].length) equal = true;
      for (const val of lists[indices[i]]) {
        if (!relations[val][indices[j]]) return 0;
      }
    } else {
      rootCount++;
    }
  }
  if (rootCount > 1) return 0;
  if (equal) return 2;
  return 1;
}

function swapNodes(head, k) {
    // locate kth node from start and kth node from end using two pointers
    let first = head;
    for (let i = 1; i < k; i++) first = first.next;   // kth from start

    let second = head;
    let fast = first;                                 // start fast pointer at kth node
    while (fast.next) {                               // move fast to end, second follows
        fast = fast.next;
        second = second.next;
    }

    // swap their values
    let tmp = first.val;
    first.val = second.val;
    second.val = tmp;

    return head;
}

function minimumTimeRequired(jobs, k) {
    jobs.sort((a, b) => b - a);

    let low = Math.max(...jobs);
    let high = jobs.reduce((s, v) => s + v, 0);

    while (low < high) {
        const mid = Math.floor((low + high) / 2);
        // feasible at `mid` -> the true minimum might be smaller, search left
        // infeasible -> need a larger limit, search right
        if (canFinish(mid)) high = mid; else low = mid + 1;
    }
    return low;

    function canFinish(limit) {
        const loads = new Array(k).fill(0);
        function dfs(idx) {
            if (idx === jobs.length) return true;
            const cur = jobs[idx];
            const seen = new Set();
            for (let i = 0; i < k; i++) {
                if (loads[i] + cur > limit) continue;
                if (seen.has(loads[i])) continue;
                seen.add(loads[i]);
                loads[i] += cur;
                if (dfs(idx + 1)) return true;
                loads[i] -= cur;
                if (loads[i] === 0) break;
            }
            return false;
        }
        return dfs(0);
    }
}

function minimumTeachings(n, languages, friendships) {
    // 1. store languages of each user as a Set for O(1) look‑ups
    const userLang = languages.map(arr => new Set(arr));

    const badUsers = new Set();                     // users that appear in a bad pair

    // 2. find all bad friendships
    for (const [u, v] of friendships) {
        const a = u - 1, b = v - 1;                 // convert to 0‑based indices
        let share = false;
        for (const lang of userLang[a]) {           // check intersection
            if (userLang[b].has(lang)) { share = true; break; }
        }
        if (!share) {                               // pair cannot communicate yet
            badUsers.add(a);
            badUsers.add(b);
        }
    }

    if (badUsers.size === 0) return 0;              // everyone already communicates

    // 3. try every language as the teaching language and keep the best
    let answer = Infinity;
    for (let L = 1; L <= n; ++L) {
        let teach = 0;
        for (const u of badUsers) {
            if (!userLang[u].has(L)) ++teach;       // user needs to learn L
        }
        if (teach < answer) answer = teach;
    }
    return answer;
}

function decodeXorPermutation(encoded) {
    const n = encoded.length + 1;               // original permutation length
    let totalXor = 0;
    // xor of 1..n
    for (let i = 1; i <= n; i++) totalXor ^= i;

    let oddXor = 0;
    // xor of encoded at odd indices (1,3,5,...)
    for (let i = 1; i < encoded.length; i += 2) oddXor ^= encoded[i];

    const perm = new Array(n);
    perm[0] = totalXor ^ oddXor;                // first element

    // reconstruct the rest using encoded
    for (let i = 1; i < n; i++) perm[i] = perm[i - 1] ^ encoded[i - 1];

    return perm;
}

function largestSubmatrix(matrix) {
    const m = matrix.length;
    const n = matrix[0].length;
    const heights = new Array(n).fill(0);   // vertical 1‑streaks
    let maxArea = 0;

    for (let i = 0; i < m; i++) {
        // update heights for current row
        for (let j = 0; j < n; j++) {
            heights[j] = matrix[i][j] === 1 ? heights[j] + 1 : 0;
        }

        // counting sort of heights (range 0..m)
        const cnt = new Array(m + 1).fill(0);
        for (let h of heights) cnt[h]++;

        // scan heights from large to small, accumulating columns
        let colsAtLeast = 0;
        for (let h = m; h >= 1; h--) {
            colsAtLeast += cnt[h];                 // columns with height ≥ h
            const area = h * colsAtLeast;          // rectangle using those columns
            if (area > maxArea) maxArea = area;
        }
    }
    return maxArea;
}

function canMouseWin(grid, catJump, mouseJump) {
  const rows = grid.length, cols = grid[0].length;
  const N = rows * cols;
  let mouseStart, catStart, foodIdx;
  const wall = new Array(N).fill(false);
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const idx = r * cols + c;
      const ch = grid[r][c];
      if (ch === '#') wall[idx] = true;
      else if (ch === 'M') mouseStart = idx;
      else if (ch === 'C') catStart = idx;
      else if (ch === 'F') foodIdx = idx;
    }
  }
  const dirs = [[0,1],[0,-1],[1,0],[-1,0]];
  function movesFrom(idx, jump) {
    const r0 = Math.floor(idx / cols), c0 = idx % cols;
    const res = [idx];
    for (const [dr, dc] of dirs) {
      for (let step = 1; step <= jump; step++) {
        const r = r0 + dr * step, c = c0 + dc * step;
        if (r < 0 || r >= rows || c < 0 || c >= cols) break;
        const idx2 = r * cols + c;
        if (wall[idx2]) break;
        res.push(idx2);
      }
    }
    return res;
  }
  const movesMouse = [], movesCat = [];
  for (let i = 0; i < N; i++) {
    if (wall[i]) { movesMouse.push([]); movesCat.push([]); continue; }
    movesMouse.push(movesFrom(i, mouseJump));
    movesCat.push(movesFrom(i, catJump));
  }

  // state: (mouse, cat, turn) turn 0 = mouse to move, 1 = cat to move
  const DRAW = 0, MOUSE_WIN = 1, CAT_WIN = 2;
  const stateIndex = (m, c, t) => (m * N + c) * 2 + t;
  const color = new Int8Array(N * N * 2).fill(DRAW);
  const degree = new Int32Array(N * N * 2);
  for (let m = 0; m < N; m++) {
    for (let c = 0; c < N; c++) {
      degree[stateIndex(m, c, 0)] = movesMouse[m].length;
      degree[stateIndex(m, c, 1)] = movesCat[c].length;
    }
  }

  const queue = [];
  for (let m = 0; m < N; m++) {
    for (let c = 0; c < N; c++) {
      for (let t = 0; t < 2; t++) {
        const s = stateIndex(m, c, t);
        if (wall[m] || wall[c]) continue;
        if (m === foodIdx) { color[s] = MOUSE_WIN; queue.push(s); }
        else if (c === foodIdx || c === m) { color[s] = CAT_WIN; queue.push(s); }
      }
    }
  }

  // reverse adjacency: for a given "prev" state (m,c,t), what states lead into it
  function neighbors(m, c, t) {
    // states that could have moved INTO (m,c,t) are states with turn = 1-t
    const res = [];
    if (t === 0) {
      // now it's mouse's turn; previous mover was cat: prev state (m, c', 1) where c in movesCat[c']
      // We need reverse: which c' have c in movesCat[c']? Since movement is symmetric in this grid (jump straight line, no wrap), moves are NOT necessarily symmetric due to jump length but reachability via straight line steps IS symmetric (if c2 reachable from c1 stepping in dir, then c1 reachable from c2 stepping back) because it's just walking along same line with no walls between. So movesCat is symmetric: c in movesCat[c2] iff c2 in movesCat[c].
      for (const cprev of movesCat[c]) {
        res.push(stateIndex(m, cprev, 1));
      }
    } else {
      // now cat's turn; previous mover was mouse: prev state (m', c, 0), m in movesMouse[m']
      for (const mprev of movesMouse[m]) {
        res.push(stateIndex(mprev, c, 0));
      }
    }
    return res;
  }

  let head = 0;
  while (head < queue.length) {
    const s = queue[head++];
    const t = s % 2;
    const c = Math.floor(s / 2) % N;
    const m = Math.floor(s / 2 / N);
    const result = color[s];
    const prevTurn = 1 - t;
    for (const ps of neighbors(m, c, t)) {
      if (color[ps] !== DRAW) continue;
      // ps has turn prevTurn; mover at ps is prevTurn player
      // if mover's own win result matches: mouse wins for mover=0 result 1, cat wins for mover=1 result 2
      const moverIsMouse = (prevTurn === 0);
      const moverWinsByThisMove = (moverIsMouse && result === MOUSE_WIN) || (!moverIsMouse && result === CAT_WIN);
      if (moverWinsByThisMove) {
        color[ps] = result;
        queue.push(ps);
      } else {
        degree[ps]--;
        if (degree[ps] === 0) {
          // all moves lead to opponent's win => mover loses
          color[ps] = moverIsMouse ? CAT_WIN : MOUSE_WIN;
          queue.push(ps);
        }
      }
    }
  }

  return color[stateIndex(mouseStart, catStart, 0)] === MOUSE_WIN;
}

function changeMinimumCharactersToSatisfyOneOfThreeConditions(a, b) {
    if (!a || !b) return 0;
    const cntA = new Array(26).fill(0);
    const cntB = new Array(26).fill(0);
    for (const ch of a) cntA[ch.charCodeAt(0) - 97]++;
    for (const ch of b) cntB[ch.charCodeAt(0) - 97]++;

    const nA = a.length, nB = b.length;
    const prefA = new Array(26).fill(0);
    const prefB = new Array(26).fill(0);
    let cur = 0;
    for (let i = 0; i < 26; i++) { cur += cntA[i]; prefA[i] = cur; }
    cur = 0;
    for (let i = 0; i < 26; i++) { cur += cntB[i]; prefB[i] = cur; }

    let bestSame = 0;
    for (let i = 0; i < 26; i++) bestSame = Math.max(bestSame, cntA[i] + cntB[i]);
    let ans = nA + nB - bestSame;

    for (let s = 0; s < 25; s++) {
        const changes1 = (nA - prefA[s]) + prefB[s];
        if (changes1 < ans) ans = changes1;
        const changes2 = (nB - prefB[s]) + prefA[s];
        if (changes2 < ans) ans = changes2;
    }
    return ans;
}

var kthLargestXorCoordinate = function(matrix, k) {
    if (!matrix.length || !matrix[0].length) return 0;
    const m = matrix.length, n = matrix[0].length;
    let prev = new Array(n).fill(0);
    let heap = [];
    for (let i=0;i<m;i++) {
        const cur = new Array(n).fill(0);
        for (let j=0;j<n;j++) {
            const top = i>0 ? prev[j] : 0;
            const left = j>0 ? cur[j-1] : 0;
            const diag = (i>0 && j>0) ? prev[j-1] : 0;
            cur[j] = top ^ left ^ diag ^ matrix[i][j];
            const val = cur[j];
            if (heap.length < k) {
                heap.push(val);
                heap.sort((a,b)=>a-b);
            } else if (val > heap[0]) {
                heap[0] = val;
                heap.sort((a,b)=>a-b);
            }
        }
        prev = cur;
    }
    return heap[0];
};

