function maxAverageRatio(classes, extraStudents) {
    // compute gain of adding one student to a class
    function gain(p, t) {
        return (p + 1) / (t + 1) - p / t;
    }

    // ---------- max‑heap implementation ----------
    const heap = [];

    function heapSwap(i, j) {
        const tmp = heap[i];
        heap[i] = heap[j];
        heap[j] = tmp;
    }

    function heapPush(node) {
        heap.push(node);
        let idx = heap.length - 1;
        while (idx > 0) {
            const parent = (idx - 1) >> 1;
            if (heap[parent].gain >= heap[idx].gain) break;
            heapSwap(parent, idx);
            idx = parent;
        }
    }

    function heapPop() {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            let idx = 0;
            while (true) {
                let left = idx * 2 + 1;
                let right = left + 1;
                let largest = idx;

                if (left < heap.length && heap[left].gain > heap[largest].gain) {
                    largest = left;
                }
                if (right < heap.length && heap[right].gain > heap[largest].gain) {
                    largest = right;
                }
                if (largest === idx) break;
                heapSwap(idx, largest);
                idx = largest;
            }
        }
        return top;
    }
    // ----------------------------------------------

    // initialise heap with each class' current gain
    for (const [p, t] of classes) {
        heapPush({ p, t, gain: gain(p, t) });
    }

    // assign each extra student to the class with maximal gain
    for (let i = 0; i < extraStudents; i++) {
        const best = heapPop();               // pop class with largest gain
        best.p += 1;                          // give it an extra passing student
        best.t += 1;
        best.gain = gain(best.p, best.t);     // recompute its gain
        heapPush(best);                       // push back for next iteration
    }

    // compute final average ratio
    let sum = 0;
    for (const node of heap) {
        sum += node.p / node.t;
    }
    return sum / classes.length;
}



