function canMakeEqualWithOneSwap(s1, s2) {
    // main logic: collect mismatching indices and evaluate the possible swap
    if (s1.length !== s2.length) return false; // lengths must match

    let first = -1, second = -1; // store up to two mismatching positions

    for (let i = 0; i < s1.length; i++) {
        if (s1[i] !== s2[i]) {
            if (first === -1) {
                first = i;                 // first mismatch
            } else if (second === -1) {
                second = i;                // second mismatch
            } else {
                return false;             // more than two mismatches
            }
        }
    }

    if (first === -1) return true;          // strings already equal
    if (second === -1) return false;        // exactly one mismatch

    // check the swap condition for the two mismatches
    return s1[first] === s2[second] && s1[second] === s2[first];
