function maximumScoreOfAGoodSubarray(nums, k) {
    const n = nums.length;
    let left = k, right = k;
    let curMin = nums[k];
    let ans = curMin;
    while (left > 0 || right < n - 1) {
        if (left === 0) {
            right++;
            curMin = Math.min(curMin, nums[right]);
        } else if (right === n - 1) {
            left--;
            curMin = Math.min(curMin, nums[left]);
        } else if (nums[left - 1] >= nums[right + 1]) {
            left--;
            curMin = Math.min(curMin, nums[left]);
        } else {
            right++;
            curMin = Math.min(curMin, nums[right]);
        }
        const length = right - left + 1;
        const score = curMin * length;
        if (score > ans) ans = score;
    }
    return ans;
}

function maxScore(nums) {
    const m = nums.length;                 // m = 2 * n
    const fullMask = (1 << m) - 1;

    // pre‑compute gcd for every pair
    const gcd = Array.from({ length: m }, () => Array(m).fill(0));
    function computeGcd(a, b) {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
    for (let i = 0; i < m; i++) {
        for (let j = i + 1; j < m; j++) {
            gcd[i][j] = computeGcd(nums[i], nums[j]);
        }
    }

    const dp = new Array(1 << m).fill(0);   // dp[mask] = best score for this mask

    // iterate over all masks
    for (let mask = 0; mask <= fullMask; mask++) {
        const used = popcount(mask);
        if (used % 2 !== 0) continue;       // only even‑bit masks are reachable
        const op = used / 2 + 1;            // next operation index (1‑based)

        // find first unused element i
        let i = 0;
        while (i < m && (mask & (1 << i))) i++;
        if (i === m) continue;              // all used

        // pair i with any later unused j
        for (let j = i + 1; j < m; j++) {
            if (mask & (1 << j)) continue;
            const newMask = mask | (1 << i) | (1 << j);
            const candidate = dp[mask] + op * gcd[i][j];
            if (candidate > dp[newMask]) dp[newMask] = candidate;
        }
    }
    return dp[fullMask];
}

