function getNumberOfBacklogOrders(orders) {
  const MOD = 1_000_000_007;
  const buyHeap = [];   // max‑heap by price
  const sellHeap = [];  // min‑heap by price

  // generic heap push
  function heapPush(heap, node, compare) {
    heap.push(node);
    let i = heap.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (compare(heap[p], heap[i])) break;
      [heap[p], heap[i]] = [heap[i], heap[p]];
      i = p;
    }
  }

  // generic heap pop (removes top)
  function heapPop(heap, compare) {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length) {
      heap[0] = last;
      let i = 0;
      while (true) {
        let l = i * 2 + 1,
            r = l + 1,
            best = i;
        if (l < heap.length && !compare(heap[best], heap[l])) best = l;
        if (r < heap.length && !compare(heap[best], heap[r])) best = r;
        if (best === i) break;
        [heap[i], heap[best]] = [heap[best], heap[i]];
        i = best;
      }
    }
    return top;
  }

  const compareBuy  = (a, b) => a.price >= b.price; // max‑heap
  const compareSell = (a, b) => a.price <= b.price; // min‑heap

  for (let [price, amount, type] of orders) {
    if (type === 0) { // BUY order
      // match with cheapest sell orders while possible
      while (amount > 0 && sellHeap.length && sellHeap[0].price <= price) {
        const sell = sellHeap[0];
        const matched = Math.min(amount, sell.amount);
        amount -= matched;
        sell.amount -= matched;
        if (sell.amount === 0) heapPop(sellHeap, compareSell);
      }
      if (amount > 0) heapPush(buyHeap, {price, amount}, compareBuy); // add remaining buy to backlog
    } else { // SELL order
      // match with highest buy orders while possible
      while (amount > 0 && buyHeap.length && buyHeap[0].price >= price) {
        const buy = buyHeap[0];
        const matched = Math.min(amount, buy.amount);
        amount -= matched;
        buy.amount -= matched;
        if (buy.amount === 0) heapPop(buyHeap, compareBuy);
      }
      if (amount > 0) heapPush(sellHeap, {price, amount}, compareSell); // add remaining sell to backlog
    }
  }

  // sum remaining amounts
  let total = 0;
  for (const node of buyHeap)  total = (total + node.amount) % MOD;
  for (const node of sellHeap) total = (total + node.amount) % MOD;
