function maximumValueAtAGivenIndexInABoundedArray(n, index, maxSum) {
    const sideSum = (val, length) => {
        if (length === 0) return 0;
        if (val > length) {
            return length * (2 * val - length - 1) / 2;
        }
        const descending = (val - 1) * val / 2;
        return descending + (length - (val - 1));
    };

    const canAchieve = (x) => {
        const left = sideSum(x, index);
        const right = sideSum(x, n - index - 1);
        return left + right + x <= maxSum;
    };

    let low = 1, high = maxSum;
    while (low < high) {
        const mid = Math.floor((low + high + 1) / 2);
        if (canAchieve(mid)) low = mid; else high = mid - 1;
    }
    return low;
