function countPairs(nums, low, high) {
    function countLE(limit) {
        if (limit < 0) return 0;
        const root = { child: [null, null], cnt: 0 };
        let total = 0;
        for (const x of nums) {
            let node = root, cnt = 0;
            for (let bit = 31; bit >= 0; bit--) {
                if (!node) break;
                const bX = (x >> bit) & 1;
