            }
            if (node) cnt += node.cnt; // exact-match path: xor == limit exactly, still <= limit
            total += cnt;
            node = root;
            for (let bit = 31; bit >= 0; bit--) {
                const bX = (x >> bit) & 1;
                if (!node.child[bX]) node.child[bX] = { child: [null, null], cnt: 0 };
