function minAbsoluteSumDiff(nums1, nums2) {
    const MOD = 1_000_000_007;
    const n = nums1.length;

    // ----- sorted copy of nums1 for binary search -----
    const sorted = nums1.slice().sort((a, b) => a - b);

    // ----- binary search: first index with value >= target -----
    function lowerBound(arr, target) {
        let lo = 0, hi = arr.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (arr[mid] < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    let totalDiff = 0;          // sum of original absolute differences
    let bestGain = 0;           // maximal reduction achievable with one replacement

    for (let i = 0; i < n; ++i) {
        const a = nums1[i];
        const b = nums2[i];
        const curDiff = Math.abs(a - b);
        totalDiff = (totalDiff + curDiff) % MOD;   // keep modulo to avoid overflow

        // ----- find closest value to b in sorted nums1 -----
        const pos = lowerBound(sorted, b);
        let minDiff = curDiff;                     // worst case: keep original a

        if (pos < n) {                             // candidate on the right
            const cand = Math.abs(sorted[pos] - b);
            if (cand < minDiff) minDiff = cand;
        }
        if (pos > 0) {                             // candidate on the left
            const cand = Math.abs(sorted[pos - 1] - b);
            if (cand < minDiff) minDiff = cand;
        }

        const gain = curDiff - minDiff;            // improvement if we replace a
        if (gain > bestGain) bestGain = gain;
    }

    // ----- apply the best possible gain -----
    const answer = (totalDiff - bestGain + MOD) % MOD;
    return answer;
}

