        remaining--;
    }
    return Number(((ans % MOD) + MOD) % MOD);
}

class MKAverage {
    constructor(m, k) {
        this.m = m; this.k = k; this.window = []; this.sorted = [];
    }
    addElement(num) {
        this.window.push(num);
        this._insertSorted(num);
        if (this.window.length > this.m) {
            const removed = this.window.shift();
            this._removeSorted(removed);
        }
    }
    _insertSorted(num) {
        let lo = 0, hi = this.sorted.length;
        while (lo < hi) { const mid = (lo+hi)>>1; if (this.sorted[mid] < num) lo = mid+1; else hi = mid; }
        this.sorted.splice(lo, 0, num);
    }
    _removeSorted(num) {
        let lo = 0, hi = this.sorted.length;
        while (lo < hi) { const mid = (lo+hi)>>1; if (this.sorted[mid] < num) lo = mid+1; else hi = mid; }
        this.sorted.splice(lo, 1);
    }
    calculateMKAverage() {
        if (this.window.length < this.m) return -1;
        const mid = this.sorted.slice(this.k, this.m - this.k);
        const sum = mid.reduce((a,b) => a+b, 0);
        return Math.floor(sum / mid.length);
    }
