function maxIceCream(costs, coins) {
    // find the maximum price to size the counting array
    let maxCost = 0;
    for (let i = 0; i < costs.length; i++) {
        if (costs[i] > maxCost) maxCost = costs[i];
    }

    // count how many bars have each price
    const freq = new Array(maxCost + 1).fill(0);
    for (let i = 0; i < costs.length; i++) {
        freq[costs[i]]++;
    }

    let bought = 0;
    // buy cheapest bars first using the frequency table
    for (let price = 1; price <= maxCost && coins >= price; price++) {
        if (freq[price] === 0) continue;
        const canBuy = Math.min(freq[price], Math.floor(coins / price));
        bought += canBuy;
        coins -= canBuy * price;
    }
    return bought;
}

function xorAndSum(arr1, arr2) {
    let ans = 0;
    // for each bit position, decide if it appears odd number of times in all pairwise ANDs
    for (let bit = 0; bit < 31; bit++) {          // 31 bits are enough for non‑negative 32‑bit ints
        const mask = 1 << bit;
        let cnt1 = 0, cnt2 = 0;
        for (const v of arr1) if (v & mask) cnt1++;   // count set bits in arr1
        for (const v of arr2) if (v & mask) cnt2++;   // count set bits in arr2
        if ((cnt1 * cnt2) & 1) ans |= mask;           // set bit if product is odd
    }
    return ans;
}

function getOrder(tasks) {
    const n = tasks.length;
    // attach original indices
    const tasksWithIdx = tasks.map((t, idx) => [t[0], t[1], idx]);
    // sort by enqueue time
    tasksWithIdx.sort((a, b) => a[0] - b[0]);

    // ---------- min‑heap implementation ----------
    const heap = [];
    const less = (a, b) => {
        if (a[1] !== b[1]) return a[1] < b[1];          // smaller processing time first
        return a[2] < b[2];                             // tie‑break by original index
    };
    const heapPush = (node) => {
        heap.push(node);
        let cur = heap.length - 1;
        while (cur > 0) {
            const parent = (cur - 1) >> 1;
            if (less(heap[parent], heap[cur])) break;
            [heap[parent], heap[cur]] = [heap[cur], heap[parent]];
            cur = parent;
        }
    };
    const heapPop = () => {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            let cur = 0;
            while (true) {
                let left = cur * 2 + 1;
                let right = left + 1;
                let smallest = cur;
                if (left < heap.length && less(heap[left], heap[smallest])) smallest = left;
                if (right < heap.length && less(heap[right], heap[smallest])) smallest = right;
                if (smallest === cur) break;
                [heap[cur], heap[smallest]] = [heap[smallest], heap[cur]];
                cur = smallest;
            }
        }
        return top;
    };
    // ----------------------------------------------

    const order = [];
    let time = 0, i = 0;

    while (order.length < n) {
        // add all tasks that have arrived by current time
        while (i < n && tasksWithIdx[i][0] <= time) {
            heapPush(tasksWithIdx[i]);
            i++;
        }
        if (heap.length === 0) {               // CPU idle, jump to next arrival
            time = tasksWithIdx[i][0];
            continue;
        }
        const [_, proc, idx] = heapPop();      // process best available task
        order.push(idx);
        time += proc;
    }
    return order;
}

function maxFrequency(nums, k) {
    nums.sort((a, b) => a - b);               // sort to enable sliding window
    let left = 0;
