    for (let right = 0; right < nums.length; right++) {
        windowSum += nums[right];               // add new element to window sum
        // while increments needed exceed k, shrink window from the left
        while (nums[right] * (right - left + 1) - windowSum > k) {
            windowSum -= nums[left];
            left++;
