    }
    return best;
}

function maxBuilding(n, restrictions) {
    // add implicit restrictions for building 1 and building n
    restrictions.push([1, 0]);
    restrictions.push([n, n - 1]);

    // sort by building index
    restrictions.sort((a, b) => a[0] - b[0]);

    // forward pass: enforce left‑to‑right height limits
    for (let i = 1; i < restrictions.length; i++) {
        const dist = restrictions[i][0] - restrictions[i - 1][0];
        restrictions[i][1] = Math.min(restrictions[i][1], restrictions[i - 1][1] + dist);
    }

    // backward pass: enforce right‑to‑left height limits
    for (let i = restrictions.length - 2; i >= 0; i--) {
        const dist = restrictions[i + 1][0] - restrictions[i][0];
        restrictions[i][1] = Math.min(restrictions[i][1], restrictions[i + 1][1] + dist);
    }

    let answer = 0;
    // evaluate maximum height inside each interval
    for (let i = 0; i < restrictions.length - 1; i++) {
        const leftPos = restrictions[i][0];
        const rightPos = restrictions[i + 1][0];
        const leftH = restrictions[i][1];
        const rightH = restrictions[i + 1][1];
        const distance = rightPos - leftPos;

        // peak height between the two restrictions
        const peak = Math.floor((leftH + rightH + distance) / 2);
        answer = Math.max(answer, peak, leftH, rightH);
    }
    return answer;
}

function sumBaseDigits(n, k) {
