function SeatManager(n) {
    this.heap = [];

    const swap = (i, j) => {
        const tmp = this.heap[i];
        this.heap[i] = this.heap[j];
        this.heap[j] = tmp;
    };

    const siftUp = (idx) => {
        while (idx > 0) {
            const parent = (idx - 1) >> 1;
            if (this.heap[parent] <= this.heap[idx]) break;
            swap(parent, idx);
            idx = parent;
        }
    };

    const siftDown = (idx) => {
        const size = this.heap.length;
        while (true) {
            let left = idx * 2 + 1;
            let right = left + 1;
            let smallest = idx;

            if (left < size && this.heap[left] < this.heap[smallest]) smallest = left;
            if (right < size && this.heap[right] < this.heap[smallest]) smallest = right;
            if (smallest === idx) break;
            swap(idx, smallest);
            idx = smallest;
        }
    };

    const push = (val) => {
        this.heap.push(val);
        siftUp(this.heap.length - 1);
    };

    const pop = () => {
        const top = this.heap[0];
        const last = this.heap.pop();
        if (this.heap.length) {
            this.heap[0] = last;
            siftDown(0);
        }
        return top;
    };

    for (let i = 1; i <= n; ++i) push(i);
}

