function closestRoom(rooms, queries) {
    const n = rooms.length;
    const roomsSorted = [...rooms].sort((a, b) => b[1] - a[1]);
    const queriesWithIdx = queries.map(([pref, minSz], idx) => [pref, minSz, idx]);
    queriesWithIdx.sort((a, b) => b[1] - a[1]);

    const eligibleIds = [];
    const insort = (arr, val) => {
        let lo = 0, hi = arr.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (arr[mid] < val) lo = mid + 1; else hi = mid;
        }
        arr.splice(lo, 0, val);
    };
    const bisectLeft = (arr, val) => {
        let lo = 0, hi = arr.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (arr[mid] < val) lo = mid + 1; else hi = mid;
        }
        return lo;
    };

    const ans = new Array(queries.length).fill(-1);
    let rPtr = 0;

    for (const [pref, minSz, qIdx] of queriesWithIdx) {
        while (rPtr < n && roomsSorted[rPtr][1] >= minSz) {
            insort(eligibleIds, roomsSorted[rPtr][0]);
            rPtr++;
        }
        if (!eligibleIds.length) { ans[qIdx] = -1; continue; }

        const pos = bisectLeft(eligibleIds, pref);
        let bestId = null, bestDiff = null;

        if (pos < eligibleIds.length) {
            const cand = eligibleIds[pos];
            bestId = cand; bestDiff = Math.abs(cand - pref);
        }
        if (pos > 0) {
            const cand = eligibleIds[pos - 1];
            const diff = Math.abs(cand - pref);
            if (bestId === null || diff < bestDiff || (diff === bestDiff && cand < bestId)) {
                bestId = cand; bestDiff = diff;
            }
        }
        ans[qIdx] = bestId !== null ? bestId : -1;
    }
    return ans;
}

function replaceDigits(s) {
