    // apply difference array: +1 at birth, -1 at death
    for (let i = 0; i < logs.length; i++) {
        const birth = logs[i][0] - OFFSET;
        const death = logs[i][1] - OFFSET;
        diff[birth] += 1;
        diff[death] -= 1;                     // death year is excluded
    }

    // prefix sum to obtain populations and track the earliest max year
    let cur = 0, best = -1, answer = OFFSET;
    for (let y = 0; y < RANGE; y++) {        // iterate years 1950 … 2050
        cur += diff[y];
        if (cur > best) {                    // found a higher population
            best = cur;
