}

function splittingAStringIntoDescendingConsecutiveValues(s) {
    const n = s.length;
    if (n < 2) return false;
    const memo = new Map();

    const match = (idx, expected) => {
        if (idx === n) return true;
        if (expected < 0) return false;
        const key = idx + ',' + expected;
        if (memo.has(key)) return memo.get(key);

        let result = false;
        for (let end = idx + 1; end <= n; end++) {
            const val = parseInt(s.slice(idx, end), 10);
            if (val === expected) {
                if (match(end, expected - 1)) { result = true; break; }
            } else if (val > expected) {
