function largestPathValue(colors, edges) {
    const n = colors.length;
    const adj = Array.from({ length: n }, () => []);
    const indeg = new Uint32Array(n);
    for (const [a, b] of edges) {          // build graph
        adj[a].push(b);
        indeg[b]++;
    }

    const dp = Array.from({ length: n }, () => new Uint16Array(26));
    for (let i = 0; i < n; i++) {          // initialise DP with own colour
        dp[i][colors.charCodeAt(i) - 97] = 1;
    }

    const queue = [];
    for (let i = 0; i < n; i++) if (indeg[i] === 0) queue.push(i);
    let processed = 0;
    let answer = 0;

    while (queue.length) {
        const u = queue.shift();            // pop next topological node
        processed++;
        // update global answer using dp of u
        for (let c = 0; c < 26; c++) {
            if (dp[u][c] > answer) answer = dp[u][c];
        }
        for (const v of adj[u]) {           // relax outgoing edges
            for (let c = 0; c < 26; c++) {
                const cand = dp[u][c] + (colors.charCodeAt(v) - 97 === c ? 1 : 0);
                if (cand > dp[v][c]) dp[v][c] = cand;
            }
            if (--indeg[v] === 0) queue.push(v);
        }
    }

    return processed === n ? answer : -1;   // cycle detection
}

