function maxSumMinProduct(nums) {
    const n = nums.length;
    const MOD = 1000000007n;

    // prefix sums (BigInt)
    const pref = new Array(n + 1).fill(0n);
    for (let i = 0; i < n; i++) pref[i + 1] = pref[i] + BigInt(nums[i]);

    const left = new Array(n);
    const right = new Array(n);
