        } else {                                 // second stick is larger
            if (memory2 >= t) {                  // can allocate on stick 2
                memory2 -= t;
                t++;
            } else {                             // not enough memory → crash
                break;
            }
        }
    }
    return [t, memory1, memory2];                // crash time and remaining memories
