            if (oldCount === 1) freq.delete(oldVal);
            else freq.set(oldVal, oldCount - 1);

            freq.set(newVal, (freq.get(newVal) || 0) + 1);
        },

        // count pairs (i, j) with nums1[i] + nums2[j] == tot
        count: function (tot) {
            let pairs = 0;
            for (const x of nums1) {
                pairs += freq.get(tot - x) || 0; // look‑up complementary value in nums2
            }
            return pairs;
        }
    };
}

// TIME: O(1) per add, O(n1) per count  SPACE: O(n2)

function rotateTheBox(boxGrid) {
    var m = boxGrid.length;               // rows
    var n = boxGrid[0].length;            // columns

    // ---- apply gravity to each row (stones fall to the right) ----
    for (var i = 0; i < m; i++) {
        var empty = 0;                     // empty cells to the right of current position
        for (var j = n - 1; j >= 0; j--) {
            var cell = boxGrid[i][j];
            if (cell === '.') {
                empty++;                   // count empty space
            } else if (cell === '*') {
                empty = 0;                // obstacle blocks falling stones
            } else if (cell === '#') {
                if (empty > 0) {           // move stone to the farthest empty spot
                    boxGrid[i][j] = '.';
                    boxGrid[i][j + empty] = '#';
                }
            }
        }
    }

    // ---- rotate the settled box 90° clockwise ----
    var result = Array.from({ length: n }, () => Array(m));
    for (var i = 0; i < m; i++) {
        for (var j = 0; j < n; j++) {
            result[j][m - 1 - i] = boxGrid[i][j];
        }
    }
    return result;
}

function sumOfFlooredPairs(nums) {
  const MOD = 1000000007n;
  const maxVal = Math.max(...nums);
  const cnt = new Array(maxVal + 1).fill(0);
  for (const x of nums) cnt[x]++;
  const prefix = new Array(maxVal + 1).fill(0);
  for (let i = 1; i <= maxVal; i++) prefix[i] = prefix[i-1] + cnt[i];
  let total = 0n;
  for (let x = 1; x <= maxVal; x++) {
    if (cnt[x] === 0) continue;
    let k = 1;
    let sum = 0;
    for (let low = x; low <= maxVal; low += x, k++) {
      const high = Math.min(low + x - 1, maxVal);
      sum += k * (prefix[high] - prefix[low - 1]);
    }
    total = (total + BigInt(cnt[x]) * BigInt(sum)) % MOD;
  }
  return Number(total);
}

function sumXorTotals(nums) {
    const n = nums.length;
    if (n === 0) return 0;                         // empty array case
    let allOr = 0;
    for (let i = 0; i < n; i++) allOr |= nums[i]; // compute bitwise OR of all numbers
    const subsetsHalf = Math.pow(2, n - 1);        // 2^(n‑1)
    return subsetsHalf * allOr;                    // each set bit contributes 2^(n‑1)
}

function minSwaps(s) {
    const n = s.length;
    let zeros = 0, ones = 0;
    for (let ch of s) {               // count characters
        if (ch === '0') zeros++;
        else ones++;
    }

    // helper: swaps needed for a pattern that starts with startChar
    function swapsIfPossible(startChar) {
        const needZeros = startChar === '0' ? Math.ceil(n / 2) : Math.floor(n / 2);
        const needOnes  = n - needZeros;
        if (zeros !== needZeros || ones !== needOnes) return Infinity; // impossible

        let zeroToOne = 0; // positions where we have '0' but need '1'
        for (let i = 0; i < n; i++) {
            const expected = (i % 2 === 0) ? startChar : (startChar === '0' ? '1' : '0');
            if (s[i] !== expected) {
                if (s[i] === '0') zeroToOne++; // mismatch type 0→1
            }
        }
        return zeroToOne; // each swap fixes one 0→1 and one 1→0
    }

    const ans = Math.min(swapsIfPossible('0'), swapsIfPossible('1'));
    return ans === Infinity ? -1 : ans;
}

function longerOnesThanZeros(s) {
    let maxOnes = 0, maxZeros = 0;          // best lengths found
    let currChar = s[0];                    // character of the current run
    let currLen = 0;                        // length of the current run

    for (let i = 0; i < s.length; i++) {    // iterate through the string
        if (s[i] === currChar) {            // same character as current run
            currLen++;                      // extend the run
        } else {                            // run ends, start a new one
            if (currChar === '1') maxOnes = Math.max(maxOnes, currLen);
            else                 maxZeros = Math.max(maxZeros, currLen);
            currChar = s[i];                // new character
            currLen = 1;                    // start its length at 1
        }
    }

    // update the maximum for the last run
    if (currChar === '1') maxOnes = Math.max(maxOnes, currLen);
    else                 maxZeros = Math.max(maxZeros, currLen);

    return maxOnes > maxZeros;              // true iff 1‑run is strictly longer
}

function rearrangeSticks(n, k) {
    const MOD = 1000000007;
    const dp = Array.from({length:n+1}, () => new Array(k+1).fill(0));
    dp[0][0] = 1;
    for (let i = 1; i <= n; i++) {
        for (let j = 1; j <= k; j++) {
            dp[i][j] = (dp[i-1][j-1] + (i-1) * dp[i-1][j]) % MOD;
        }
    }
    return dp[n][k];
}

function minSpeedOnTime(dist, hour) {
    const n = dist.length;

    // check whether a given speed is enough
    function can(speed) {
        let total = 0;
        for (let i = 0; i < n - 1; ++i) {
            total += Math.ceil(dist[i] / speed);   // integer departure constraint
        }
        total += dist[n - 1] / speed;               // last ride exact time
        return total <= hour + 1e-9;                // tolerance for floating errors
    }

    // quick impossibility test: even with infinite speed the first n‑1 rides need n‑1 hours
    if (hour < n - 1) return -1;

    let lo = 1, hi = 1e7;               // search interval [lo, hi]
    while (lo < hi) {                   // binary search for minimal feasible speed
        const mid = Math.floor((lo + hi) / 2);
        if (can(mid)) hi = mid;         // mid works → look left
        else lo = mid + 1;              // mid too slow → look right
    }
    return can(lo) ? lo : -1;           // verify the found candidate
}

var canReach = function(s, minJump, maxJump) {
    const n = s.length;
    if (n === 0 || s[0] !== '0' || s[n-1] !== '0') return false;
    const reachable = new Array(n).fill(false);
    reachable[0] = true;
    const q = [0];
    let head = 0;
    for (let i=1;i<n;i++) {
        while (head < q.length && q[head] < i - maxJump) head++;
        if (head < q.length && q[head] <= i - minJump && s[i] === '0') {
            reachable[i] = true;
            q.push(i);
        }
    }
    return reachable[n-1];
};

function countGoodSubstrings(s) {
    var n = s.length;
    var goodCount = 0;
    for (var i = 0; i + 2 < n; i++) {
        // count window [i, i+2] if all three chars differ
        if (s[i] !== s[i + 1] && s[i] !== s[i + 2] && s[i + 1] !== s[i + 2]) {
            goodCount++;
        }
    }
    return goodCount;
}

function getBiggestThreeRhombusSumsInAGrid(grid) {
    const m = grid.length, n = grid[0].length;
    const diag1 = Array.from({length: m}, () => new Array(n).fill(0));
    const diag2 = Array.from({length: m}, () => new Array(n).fill(0));

    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            diag1[i][j] = grid[i][j] + (i > 0 && j > 0 ? diag1[i - 1][j - 1] : 0);
            diag2[i][j] = grid[i][j] + (i > 0 && j + 1 < n ? diag2[i - 1][j + 1] : 0);
        }
    }

    const diag1Sum = (x1, y1, x2, y2) => {
        let res = diag1[x2][y2];
        if (x1 > 0 && y1 > 0) res -= diag1[x1 - 1][y1 - 1];
        return res;
    };
    const diag2Sum = (x1, y1, x2, y2) => {
        let res = diag2[x2][y2];
        if (x1 > 0 && y1 + 1 < n) res -= diag2[x1 - 1][y1 + 1];
        return res;
    };

    const sums = new Set();
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            sums.add(grid[i][j]);
            const maxK = Math.min(Math.floor((m - i - 1) / 2), j, n - j - 1);
            for (let k = 1; k <= maxK; k++) {
                const top = [i, j];
                const left = [i + k, j - k];
                const bottom = [i + 2 * k, j];
                const right = [i + k, j + k];

                const edge1 = diag2Sum(top[0], top[1], left[0], left[1]);
                const edge2 = diag1Sum(left[0], left[1], bottom[0], bottom[1]);
                const edge3 = diag2Sum(right[0], right[1], bottom[0], bottom[1]);
                const edge4 = diag1Sum(top[0], top[1], right[0], right[1]);

                let borderSum = edge1 + edge2 + edge3 + edge4;
                borderSum -= (grid[top[0]][top[1]] + grid[left[0]][left[1]] +
                              grid[bottom[0]][bottom[1]] + grid[right[0]][right[1]]);
                sums.add(borderSum);
            }
        }
    }

    return [...sums].sort((a, b) => b - a).slice(0, 3);
}

function stoneGameVIII(stones) {
    const n = stones.length;
    const prefix = new Array(n).fill(0);
    prefix[0] = stones[0];
    for (let i = 1; i < n; i++) prefix[i] = prefix[i-1] + stones[i];
    let best = prefix[n-1];
    for (let i = n-2; i >= 1; i--) {
        best = Math.max(best, prefix[i] - best);
    }
    return best;
}

function maxValueAfterInsertion(n, x) {
    var xs = x.toString();                     // digit as string
    var isNeg = n[0] === '-';
    var i = isNeg ? 1 : 0;                      // start after possible '-'

    // find insertion point
    while (i < n.length) {
        var cur = n[i];
        if (!isNeg && cur < xs) break;          // positive: first smaller digit
        if (isNeg && cur > xs) break;           // negative: first larger digit
        i++;
    }

    return n.slice(0, i) + xs + n.slice(i);     // insert x at position i
}

function minPairSum(nums) {
    // sort the array to enable greedy pairing of smallest with largest
    nums.sort((a, b) => a - b);

    let left = 0;                     // start pointer
    let right = nums.length - 1;      // end pointer
    let maxSum = 0;                   // answer holder

    while (left < right) {            // main logic: two‑pointer pairing
        const pairSum = nums[left] + nums[right];
        if (pairSum > maxSum) maxSum = pairSum;
        left++;
        right--;
    }
    return maxSum;
}

function assignTasks(servers, tasks) {
  // ---------- heap implementation ----------
  class MinHeap {
    constructor(cmp) {
      this.cmp = cmp;
      this.arr = [];
    }
    size() { return this.arr.length; }
    peek() { return this.arr[0]; }
    push(x) {
      const a = this.arr;
      a.push(x);
      let i = a.length - 1;
      while (i > 0) {
        const p = (i - 1) >> 1;
        if (this.cmp(a[p], a[i]) <= 0) break;
        [a[p], a[i]] = [a[i], a[p]];
        i = p;
      }
    }
    pop() {
      const a = this.arr;
      if (a.length === 0) return undefined;
      const top = a[0];
      const last = a.pop();
      if (a.length) {
        a[0] = last;
        this._heapify(0);
      }
      return top;
    }
    _heapify(i) {
      const a = this.arr, cmp = this.cmp;
      const n = a.length;
      while (true) {
        let l = i * 2 + 1, r = l + 1, smallest = i;
        if (l < n && cmp(a[l], a[smallest]) < 0) smallest = l;
        if (r < n && cmp(a[r], a[smallest]) < 0) smallest = r;
        if (smallest === i) break;
        [a[i], a[smallest]] = [a[smallest], a[i]];
        i = smallest;
      }
    }
  }

  const n = servers.length, m = tasks.length;
  const free = new MinHeap((a, b) => a.w !== b.w ? a.w - b.w : a.i - b.i);
  const busy = new MinHeap((a, b) => a.time !== b.time ? a.time - b.time
                     : a.w !== b.w ? a.w - b.w : a.i - b.i);

  // initially all servers are idle
  for (let i = 0; i < n; ++i) free.push({ w: servers[i], i });

  const ans = new Array(m);
  let curTime = 0;

  for (let j = 0; j < m; ++j) {
    curTime = Math.max(curTime, j);               // task j arrives at second j

    // release servers that have finished by curTime
    while (busy.size() && busy.peek().time <= curTime) {
      const s = busy.pop();
      free.push({ w: s.w, i: s.i });
    }

    // if no server is free, jump to the next finishing time
    if (free.size() === 0) {
      curTime = busy.peek().time;
      while (busy.size() && busy.peek().time <= curTime) {
        const s = busy.pop();
        free.push({ w: s.w, i: s.i });
      }
    }

    const srv = free.pop();                       // assign the task
    ans[j] = srv.i;
    busy.push({ time: curTime + tasks[j], w: srv.w, i: srv.i });
  }

  return ans;
}


// TIME: O((n+m)·log n) SPACE: O(n+m)

function minSkips(dist, speed, hoursBefore) {
    const n = dist.length;

    // check if we can finish with at most maxSkips skips
    function canFinish(maxSkips) {
        const INF = 1e30;
        let dp = new Array(maxSkips + 1).fill(INF);
        dp[0] = 0;                                   // start at time 0

        for (let i = 0; i < n; ++i) {
            const ndp = new Array(maxSkips + 1).fill(INF);
            const travel = dist[i] / speed;          // time to drive this road

            for (let used = 0; used <= maxSkips; ++used) {
                if (dp[used] === INF) continue;

                const arrive = dp[used] + travel;    // time right after this road

                if (i === n - 1) {                    // last road, no rest needed
                    ndp[used] = Math.min(ndp[used], arrive);
                } else {
                    // 1) do NOT skip the rest → wait for next integer hour
                    const wait = Math.ceil(arrive);
                    ndp[used] = Math.min(ndp[used], wait);

                    // 2) skip the rest (if we still have a skip left)
                    if (used < maxSkips) {
                        ndp[used + 1] = Math.min(ndp[used + 1], arrive);
                    }
                }
            }
            dp = ndp;                                 // move to next road
        }

        // any feasible number of used skips gives a total time ≤ hoursBefore ?
        for (let used = 0; used <= maxSkips; ++used) {
            if (dp[used] <= hoursBefore + 1e-9) return true;
        }
        return false;
    }

    // quick check: maybe no skip is enough
    if (canFinish(0)) return 0;

    // binary search the minimal required skips
    let lo = 1, hi = n - 1, answer = -1;
    while (lo <= hi) {
        const mid = (lo + hi) >> 1;
        if (canFinish(mid)) {
            answer = mid;
            hi = mid - 1;          // try to use fewer skips
        } else {
            lo = mid + 1;
        }
    }
    return answer;
}

function minimumXORSum(nums1, nums2) {
    const n = nums1.length;
    const fullMask = (1 << n) - 1;
    const INF = 1e15;
    const dp = new Array(1 << n).fill(INF);
    dp[0] = 0;                                   // base: no elements matched yet

    for (let mask = 0; mask <= fullMask; ++mask) {
        const k = popcount(mask);               // how many nums1 elements are already paired
        if (k >= n) continue;                   // all paired, nothing to do
        const cur = dp[mask];
        // try to pair nums1[k] with every still free element of nums2
        for (let j = 0; j < n; ++j) {
            if ((mask & (1 << j)) === 0) {      // j is free
                const newMask = mask | (1 << j);
                const cand = cur + (nums1[k] ^ nums2[j]);
                if (cand < dp[newMask]) dp[newMask] = cand; // update best for newMask
            }
        }
    }
    return dp[fullMask];
}

// helper: count set bits (popcount)
function popcount(x) {
    let cnt = 0;
    while (x) { x &= x - 1; ++cnt; }
    return cnt;
}

function checkWordSum(firstWord, secondWord, targetWord) {
    // convert a word to its numeric BigInt value
    function toBigInt(word) {
        let digits = '';
        for (let i = 0; i < word.length; i++) {
            digits += (word.charCodeAt(i) - 97); // map 'a'‑'j' to 0‑9
        }
        return BigInt(digits);                     // turn the digit string into a BigInt
    }

    const val1 = toBigInt(firstWord);   // numeric value of firstWord
    const val2 = toBigInt(secondWord);  // numeric value of secondWord
    const target = toBigInt(targetWord); // numeric value of targetWord

    return val1 + val2 === target;      // check if the sum equals the target
}

function minFlips(s) {
    const n = s.length;
    const doubled = s + s;                     // consider all rotations
    let diffA = 0, diffB = 0;                   // mismatches for the two patterns
    let best = Infinity;

    for (let i = 0; i < doubled.length; i++) {
        const ch = doubled[i];
        const expectedA = (i % 2 === 0) ? '0' : '1';
        const expectedB = (i % 2 === 0) ? '1' : '0';
        if (ch !== expectedA) diffA++;          // count mismatches for pattern A
        if (ch !== expectedB) diffB++;          // count mismatches for pattern B

        // slide window: remove the character that leaves the window
        if (i >= n) {
            const j = i - n;
            const left = doubled[j];
            const leftExpA = (j % 2 === 0) ? '0' : '1';
            const leftExpB = (j % 2 === 0) ? '1' : '0';
            if (left !== leftExpA) diffA--;
            if (left !== leftExpB) diffB--;
        }

        // when the window is full, update the answer
        if (i >= n - 1) {
            best = Math.min(best, diffA, diffB);
        }
    }
    return best;
}

function minWastedSpace(packages, boxes) {
    const MOD = 1000000007n;
    packages = [...packages].sort((a,b)=>a-b);
    const n = packages.length;
    const prefix = new Array(n+1).fill(0n);
    for (let i = 0; i < n; i++) prefix[i+1] = prefix[i] + BigInt(packages[i]);
    let best = null;
    for (const supplier of boxes) {
        const sorted = [...supplier].sort((a,b)=>a-b);
        if (sorted[sorted.length-1] < packages[n-1]) continue;
        let total = 0n;
        let idx = 0;
        for (const boxSize of sorted) {
            let lo = idx, hi = n;
            while (lo < hi) { const mid=(lo+hi)>>1; if (packages[mid] <= boxSize) lo=mid+1; else hi=mid; }
            const cnt = lo - idx;
            if (cnt > 0) total += BigInt(boxSize) * BigInt(cnt) - (prefix[lo]-prefix[idx]);
            idx = lo;
            if (idx >= n) break;
        }
        if (idx < n) continue;
        if (best === null || total < best) best = total;
    }
    if (best === null) return -1;
    return Number(best % MOD);
}

function twoEggDrop(n) {
    // main logic: compute minimal m with m(m+1)/2 >= n using the quadratic formula
    if (n <= 0) return 0;
    return Math.ceil((Math.sqrt(1 + 8 * n) - 1) / 2);
}

function canBeRotated(mat, target) {
    const n = mat.length;

    // check if two matrices are identical
    function same() {
        for (let i = 0; i < n; i++) {
            for (let j = 0; j < n; j++) {
                if (mat[i][j] !== target[i][j]) return false;
            }
        }
        return true;
    }

    // rotate mat 90° clockwise in place
    function rotate() {
        for (let layer = 0; layer < Math.floor(n / 2); layer++) {
            const first = layer;
            const last = n - 1 - layer;
            for (let i = first; i < last; i++) {
                const offset = i - first;
                const top = mat[first][i];                     // save top
                // left → top
                mat[first][i] = mat[last - offset][first];
                // bottom → left
                mat[last - offset][first] = mat[last][last - offset];
                // right → bottom
                mat[last][last - offset] = mat[i][last];
                // top (saved) → right
                mat[i][last] = top;
            }
        }
    }

    // MAIN LOGIC: try all four orientations
    for (let k = 0; k < 4; k++) {
        if (same()) return true;   // found a matching rotation
        rotate();                  // prepare next orientation
    }
    return false;
}

function reductionOperations(nums) {
    nums.sort((a, b) => a - b);
    let ops = 0;
    let level = 0;
    for (let i = 1; i < nums.length; i++) {
        if (nums[i] !== nums[i - 1]) level++; // one more reduction step needed to bring everything down to this new value
        ops += level;
    }
    return ops;
}

function isCovered(ranges, left, right) {
    // find the maximum coordinate we have to consider
    let maxCoord = right;
    for (let i = 0; i < ranges.length; i++) {
        if (ranges[i][1] > maxCoord) maxCoord = ranges[i][1];
    }

    // difference array, one extra cell for the sentinel at maxCoord+1
    const diff = new Array(maxCoord + 2).fill(0);

    // mark each interval in the difference array
    for (let i = 0; i < ranges.length; i++) {
        const start = ranges[i][0];
        const end   = ranges[i][1];
        diff[start] += 1;          // interval starts
        diff[end + 1] -= 1;        // interval ends (exclusive)
    }

    // compute prefix sums and check coverage for [left, right]
    let cur = 0;
    for (let x = 0; x <= maxCoord; x++) {
        cur += diff[x];            // current number of covering intervals
        if (x >= left && x <= right && cur === 0) return false;
    }
    return true;
}

function findStudent(chalk, k) {
    // compute total chalk needed for one full round
    var total = 0;
    for (var i = 0; i < chalk.length; i++) total += chalk[i];

    k %= total;                     // reduce k to the remaining chalk in the current round

    // build prefix sums for binary search
    var prefix = 0;
    var prefixSum = new Array(chalk.length);
    for (var i = 0; i < chalk.length; i++) {
        prefix += chalk[i];
        prefixSum[i] = prefix;
    }

    // binary search the first prefix > k
    var left = 0, right = chalk.length - 1;
    while (left <= right) {
        var mid = (left + right) >> 1;
        if (prefixSum[mid] <= k) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return left;                    // index of the student who cannot get enough chalk
}

function largestMagicSquare(grid) {
    const m = grid.length, n = grid[0].length;
    const rowPref = Array.from({length: m}, () => new Array(n + 1).fill(0));
    for (let i = 0; i < m; i++) {
        let s = 0;
        for (let j = 0; j < n; j++) { s += grid[i][j]; rowPref[i][j + 1] = s; }
    }
    const colPref = Array.from({length: n}, () => new Array(m + 1).fill(0));
    for (let j = 0; j < n; j++) {
        let s = 0;
        for (let i = 0; i < m; i++) { s += grid[i][j]; colPref[j][i + 1] = s; }
    }
    const diag1 = Array.from({length: m + 1}, () => new Array(n + 1).fill(0));
    for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) diag1[i + 1][j + 1] = grid[i][j] + diag1[i][j];
    const diag2 = Array.from({length: m + 1}, () => new Array(n + 1).fill(0));
    for (let i = 0; i < m; i++) for (let j = n - 1; j >= 0; j--) diag2[i + 1][j] = grid[i][j] + diag2[i][j + 1];

    let maxK = 1;
    const limit = Math.min(m, n);
    for (let k = 2; k <= limit; k++) {
        let found = false;
        for (let i = 0; i <= m - k && !found; i++) {
            for (let j = 0; j <= n - k; j++) {
                const target = rowPref[i][j + k] - rowPref[i][j];
                let ok = true;
                for (let r = i; r < i + k; r++) {
                    if (rowPref[r][j + k] - rowPref[r][j] !== target) { ok = false; break; }
                }
                if (!ok) continue;
                for (let c = j; c < j + k; c++) {
                    if (colPref[c][i + k] - colPref[c][i] !== target) { ok = false; break; }
                }
                if (!ok) continue;
                if (diag1[i + k][j + k] - diag1[i][j] !== target) continue;
                if (diag2[i + k][j] - diag2[i][j + k] !== target) continue;
                found = true;
                break;
            }
        }
        if (found) maxK = k;
    }
    return maxK;
}

function mergeTriplets(triplets, target) {
    var needA = target[0], needB = target[1], needC = target[2];
    var curA = 0, curB = 0, curC = 0;
    for (var i = 0; i < triplets.length; i++) {
        var a = triplets[i][0], b = triplets[i][1], c = triplets[i][2];
        if (a <= needA && b <= needB && c <= needC) { // only triplets that don't exceed target
            if (a > curA) curA = a;
            if (b > curB) curB = b;
            if (c > curC) curC = c;
        }
    }
    return curA === needA && curB === needB && curC === needC;
}

function makeEqual(words) {
    const n = words.length;                     // number of strings
    const cnt = new Array(26).fill(0);          // frequency of each letter

    for (const w of words) {                    // count all characters
        for (const ch of w) {
            cnt[ch.charCodeAt(0) - 97]++;       // 'a' -> 0, ..., 'z' -> 25
        }
    }

    for (const c of cnt) {                      // check divisibility by n
        if (c % n !== 0) return false;
    }
    return true;
}

function maximumRemovals(s, p, removable) {
    const n = s.length;
    const order = new Array(n).fill(Infinity);          // removal step for each index
    for (let i = 0; i < removable.length; i++) {
        order[removable[i]] = i;                         // store order
    }

    // check if p is subsequence after removing first k characters
    function can(k) {
        let j = 0;
        for (let i = 0; i < n && j < p.length; i++) {
            if (order[i] < k) continue;                  // character removed
            if (s[i] === p[j]) j++;                      // match next char of p
        }
        return j === p.length;
    }

    let lo = 0, hi = removable.length;                  // binary search on k
    while (lo < hi) {
        const mid = Math.floor((lo + hi + 1) / 2);       // try larger half
        if (can(mid)) lo = mid;                          // feasible, keep it
        else hi = mid - 1;                               // not feasible
    }
    return lo;
}

function minCostToChangeExpression(expression) {
    const valStack = [];
    const opStack = [];

    function compute(l, r, op) {
        if (op === '&') {
            const c1 = l.c1 + r.c1;
            const c0 = Math.min(
                l.c0 + r.c0,
                l.c0 + r.c1,
                l.c1 + r.c0
            );
            return { c0, c1 };
        } else { // '|'
            const c0 = l.c0 + r.c0;
            const c1 = Math.min(
                l.c1 + r.c1,
                l.c0 + r.c1,
                l.c1 + r.c0
            );
            return { c0, c1 };
        }
    }

    function combine(l, r, op) {
        const keep = compute(l, r, op);
        const flippedOp = op === '&' ? '|' : '&';
        const flip = compute(l, r, flippedOp);
        flip.c0 += 1;
        flip.c1 += 1;
        return {
            c0: Math.min(keep.c0, flip.c0),
            c1: Math.min(keep.c1, flip.c1)
        };
    }

    function apply() {
        const op = opStack.pop();
        const right = valStack.pop();
        const left = valStack.pop();
        valStack.push(combine(left, right, op));
    }

    for (let i = 0; i < expression.length; i++) {
        const ch = expression[i];
        if (ch === '0' || ch === '1') {
            const isOne = ch === '1';
            valStack.push({
                c0: isOne ? 1 : 0,
                c1: isOne ? 0 : 1
            });
        } else if (ch === '(') {
            opStack.push(ch);
        } else if (ch === '&' || ch === '|') {
            while (opStack.length && opStack[opStack.length - 1] !== '(') {
                apply();
            }
            opStack.push(ch);
        } else if (ch === ')') {
            while (opStack.length && opStack[opStack.length - 1] !== '(') {
                apply();
            }
            opStack.pop(); // remove '('
        }
    }

    while (opStack.length) {
        apply();
    }

    const finalPair = valStack.pop();
    const originalValue = finalPair.c0 === 0 ? 0 : 1;
    const answer = originalValue === 0 ? finalPair.c1 : finalPair.c0;
    return answer;
}

function largestOddNumber(num) {
    // find the last odd digit
    for (let i = num.length - 1; i >= 0; i--) {
        const d = num.charCodeAt(i) - 48;          // digit value 0‑9
        if (d % 2 === 1) {                         // odd?
            return num.slice(0, i + 1);            // longest prefix ending at i
        }
    }
    return "";                                     // no odd digit found
}

function numberOfFullRounds(loginTime, logoutTime) {
    // parse HH:MM into minutes since midnight
    const toMin = t => Number(t.slice(0, 2)) * 60 + Number(t.slice(3, 5));
    let login = toMin(loginTime);
    let logout = toMin(logoutTime);
    // handle crossing midnight
    if (logout < login) logout += 24 * 60;
    // first round start not earlier than login
    const firstStart = Math.ceil(login / 15) * 15;
    // last round start whose end is not after logout
    const lastStart = Math.floor((logout - 15) / 15) * 15;
    // count full rounds
    return firstStart > lastStart ? 0 : (lastStart - firstStart) / 15 + 1;
}

function minDifference(nums, queries) {
    const n = nums.length;
    const MAXV = 100;
    // prefix[i][v] = count of value v in nums[0..i-1]
    const prefix = Array.from({length:n+1}, () => new Array(MAXV+1).fill(0));
    for (let i = 0; i < n; i++) {
        for (let v = 1; v <= MAXV; v++) prefix[i+1][v] = prefix[i][v];
        prefix[i+1][nums[i]]++;
    }
    const ans = [];
    for (const [l, r] of queries) {
        let last = -1, best = Infinity;
        for (let v = 1; v <= MAXV; v++) {
            if (prefix[r+1][v] - prefix[l][v] > 0) {
                if (last !== -1) best = Math.min(best, v - last);
                last = v;
            }
        }
        ans.push(best === Infinity ? -1 : best);
    }
    return ans;
}

function findPeakGrid(mat) {
    const rows = mat.length;
    const cols = mat[0].length;
    let left = 0, right = cols - 1;

    while (left <= right) {                         // binary search on columns
        const mid = Math.floor((left + right) / 2);

        // find row index of the maximum element in column 'mid'
        let maxRow = 0;
        for (let r = 1; r < rows; r++) {
            if (mat[r][mid] > mat[maxRow][mid]) maxRow = r;
        }

        const leftVal  = (mid > 0)     ? mat[maxRow][mid - 1] : -1;
        const rightVal = (mid < cols-1)? mat[maxRow][mid + 1] : -1;
        const curVal   = mat[maxRow][mid];

        // peak found
        if (curVal > leftVal && curVal > rightVal) {
            return [maxRow, mid];
        }
        // move to the side that has a larger neighbour
        if (leftVal > curVal) {
            right = mid - 1;
        } else {
            left = mid + 1;
        }
    }
}

function maxAlternatingSum(nums) {
    // E: best sum for a subsequence with an EVEN chosen-count so far (or empty) - ends on a SUBTRACT (or nothing)
    // O: best sum for a subsequence with an ODD chosen-count so far - ends on an ADD
    let E = 0, O = -Infinity;
    for (let i = 0; i < nums.length; i++) {
        const x = nums[i];
        // extending an even-count subsequence by one element makes it odd-count,
        // and that new element is at an ODD position (1st, 3rd, ...) - it gets ADDED
        const newO = Math.max(O, E + x);
        // extending an odd-count subsequence by one makes it even-count,
        // and that new element is at an EVEN position (2nd, 4th, ...) - it gets SUBTRACTED
        const newE = Math.max(E, O - x);
        O = newO;
        E = newE;
    }
    // the optimal subsequence can end on either parity
    return Math.max(E, O);
}

function countSubIslands(grid1, grid2) {
    const m = grid1.length, n = grid1[0].length;
    let subCount = 0;
    const dirs = [[1,0],[-1,0],[0,1],[0,-1]];   // 4‑direction moves

    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (grid2[i][j] === 1) {
                // explore one island of grid2
                let stack = [[i, j]];
                let isSub = true;
                grid2[i][j] = 0;                 // mark visited

                while (stack.length) {
                    const [x, y] = stack.pop();
                    if (grid1[x][y] === 0) isSub = false;   // not contained

                    for (const [dx, dy] of dirs) {
                        const nx = x + dx, ny = y + dy;
                        if (nx >= 0 && nx < m && ny >= 0 && ny < n && grid2[nx][ny] === 1) {
                            grid2[nx][ny] = 0;               // mark visited
                            stack.push([nx, ny]);
                        }
                    }
                }

                if (isSub) subCount++;   // whole island fits inside grid1
            }
        }
    }
    return subCount;
}

function maxProductDifference(nums) {
    // initialise extremes
    let max1 = -Infinity, max2 = -Infinity;
    let min1 = Infinity,  min2 = Infinity;

    for (let i = 0; i < nums.length; i++) {
        const v = nums[i];

        // update two largest values
        if (v > max1) { max2 = max1; max1 = v; }
        else if (v > max2) { max2 = v; }

        // update two smallest values
        if (v < min1) { min2 = min1; min1 = v; }
        else if (v < min2) { min2 = v; }
    }

    return max1 * max2 - min1 * min2;   // compute maximal product difference
}

function removeOccurrences(s, part) {
    const m = part.length;

    // build LPS (longest proper prefix which is also suffix) for KMP
    const lps = new Array(m).fill(0);
    for (let i = 1, len = 0; i < m; ) {
        if (part[i] === part[len]) {
            lps[i++] = ++len;
        } else if (len) {
            len = lps[len - 1];
        } else {
            lps[i++] = 0;
        }
    }

    const stack = [];        // characters kept so far
    const matchStack = [];   // length of current prefix match after each char

    for (let i = 0; i < s.length; i++) {
        const ch = s[i];
        stack.push(ch);                                   // add current char
        let k = matchStack.length ? matchStack[matchStack.length - 1] : 0;
        while (k > 0 && ch !== part[k]) k = lps[k - 1];   // adjust using LPS
        if (ch === part[k]) k++;                          // extend match
        matchStack.push(k);                               // store match length
        if (k === m) {                                    // full part found
            for (let j = 0; j < m; j++) {                // remove it
                stack.pop();
                matchStack.pop();
            }
        }
    }
    return stack.join('');
}

function canBeIncreasing(nums) {
    let violations = 0;                     // count of non‑increasing pairs
    for (let i = 1; i < nums.length; i++) {
        if (nums[i] <= nums[i - 1]) {       // found a violation
            violations++;
            if (violations > 1) return false; // more than one removal needed
            // decide which element to "remove"
            if (i > 1 && nums[i] <= nums[i - 2]) {
                // cannot remove nums[i‑1]; check if removing nums[i] works
                if (i + 1 < nums.length && nums[i + 1] <= nums[i - 1]) {
                    return false;           // both removals fail
                }
            }
        }
    }
    return true;                            // zero or one violation handled
}

function rotateGrid(grid, k) {
    const rows = grid.length;
    const cols = grid[0].length;
    const layers = Math.min(rows, cols) >> 1;          // number of concentric layers

    for (let layer = 0; layer < layers; layer++) {
        const top = layer, left = layer;
        const bottom = rows - 1 - layer, right = cols - 1 - layer;
        const vals = [];

        // collect border clockwise
        for (let c = left; c <= right; c++) vals.push(grid[top][c]);               // top row
        for (let r = top + 1; r < bottom; r++) vals.push(grid[r][right]);          // right column
        for (let c = right; c >= left; c--) vals.push(grid[bottom][c]);            // bottom row
        for (let r = bottom - 1; r > top; r--) vals.push(grid[r][left]);           // left column

        const len = vals.length;
        const shift = k % len;                         // effective rotation

        // write back shifted left by 'shift'
        let idx = 0;
        for (let c = left; c <= right; c++) grid[top][c] = vals[(idx + shift) % len], idx++;
        for (let r = top + 1; r < bottom; r++) grid[r][right] = vals[(idx + shift) % len], idx++;
        for (let c = right; c >= left; c--) grid[bottom][c] = vals[(idx + shift) % len], idx++;
        for (let r = bottom - 1; r > top; r--) grid[r][left] = vals[(idx + shift) % len], idx++;
    }
    return grid;
}

function Heap(compare) { this.data = []; this.cmp = compare; }
Heap.prototype.peek = function () { return this.data[0]; };
Heap.prototype.push = function (x) {
    const a = this.data, cmp = this.cmp;
    a.push(x);
    let i = a.length - 1;
    while (i > 0) {
        const p = (i - 1) >> 1;
        if (cmp(a[p], a[i]) <= 0) break;
        [a[p], a[i]] = [a[i], a[p]];
        i = p;
    }
};
Heap.prototype.pop = function () {
    const a = this.data, cmp = this.cmp;
    if (a.length === 0) return undefined;
    const root = a[0];
    const last = a.pop();
    if (a.length) {
        a[0] = last;
        let i = 0;
        while (true) {
            let l = i * 2 + 1, r = l + 1, smallest = i;
            if (l < a.length && cmp(a[l], a[smallest]) < 0) smallest = l;
            if (r < a.length && cmp(a[r], a[smallest]) < 0) smallest = r;
            if (smallest === i) break;
            [a[i], a[smallest]] = [a[smallest], a[i]];
            i = smallest;
        }
    }
    return root;
};
class MovieRentingSystem {
    constructor(n, entries) {
        this.priceMap = new Map();
        this.available = new Map();
        this.rentedHeap = new Heap((a,b) => a[0]!==b[0] ? a[0]-b[0] : a[1]!==b[1] ? a[1]-b[1] : a[2]-b[2]);
        this.rentedSet = new Set();
        for (const [shop, movie, price] of entries) {
            const key = shop + ',' + movie;
            this.priceMap.set(key, price);
            if (!this.available.has(movie)) this.available.set(movie, new Heap((a,b) => a[0]!==b[0] ? a[0]-b[0] : a[1]-b[1]));
            this.available.get(movie).push([price, shop]);
        }
    }
    search(movie) {
        const heap = this.available.get(movie);
        if (!heap) return [];
        const result = [], temp = [];
        while (result.length < 5 && heap.data.length) {
            const top = heap.peek();
            const key = top[1] + ',' + movie;
            if (this.rentedSet.has(key)) { heap.pop(); continue; }
            result.push(top[1]);
            temp.push(heap.pop());
        }
        for (const e of temp) heap.push(e);
        return result;
    }
    rent(shop, movie) {
        const key = shop + ',' + movie;
        this.rentedSet.add(key);
        const price = this.priceMap.get(key);
        this.rentedHeap.push([price, shop, movie]);
    }
    drop(shop, movie) {
        const key = shop + ',' + movie;
        this.rentedSet.delete(key);
    }
    report() {
        const result = [], temp = [];
        while (result.length < 5 && this.rentedHeap.data.length) {
            const top = this.rentedHeap.peek();
            const key = top[1] + ',' + top[2];
            if (!this.rentedSet.has(key)) { this.rentedHeap.pop(); continue; }
            result.push([top[1], top[2]]);
            temp.push(this.rentedHeap.pop());
        }
        for (const e of temp) this.rentedHeap.push(e);
        return result;
    }
}

function eliminateMaximum(dist, speed) {
    const n = dist.length;
    const arrival = dist.map((d, i) => d / speed[i]).sort((a, b) => a - b);
    let time = 0;
    for (let i = 0; i < n; i++) {
        if (arrival[i] <= time) return i;
        time++;
    }
    return n;
}

function countWaysToBuildRoomsInAnAntColony(prevRoom) {
    const MOD = 1000000007n;
    const n = prevRoom.length;
    const children = Array.from({length: n}, () => []);
    for (let i = 1; i < n; i++) children[prevRoom[i]].push(i);

    const fact = new Array(n + 1).fill(1n);
    for (let i = 1; i <= n; i++) fact[i] = (fact[i - 1] * BigInt(i)) % MOD;
    const modpow = (base, exp, mod) => {
        base %= mod;
        let result = 1n;
        while (exp > 0n) {
            if (exp & 1n) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1n;
        }
        return result;
    };
    const invFact = new Array(n + 1).fill(1n);
    invFact[n] = modpow(fact[n], MOD - 2n, MOD);
    for (let i = n; i >= 1; i--) invFact[i - 1] = (invFact[i] * BigInt(i)) % MOD;

    const subtreeWays = new Array(n).fill(0n);

    const dfs = (u) => {
        let total = 0;
        let ways = 1n;
        for (const v of children[u]) {
            const sz = dfs(v);
            total += sz;
            ways = (ways * invFact[sz]) % MOD;
            ways = (ways * subtreeWays[v]) % MOD;
        }
        ways = (ways * fact[total]) % MOD;
        subtreeWays[u] = ways;
        return total + 1;
    };

    dfs(0);
    return Number(subtreeWays[0] % MOD);
}

function wonderfulSubstrings(word) {
    const cnt = new Map();          // mask → occurrences
    cnt.set(0, 1);                  // empty prefix
    let cur = 0;
    let ans = 0;

    for (let i = 0; i < word.length; i++) {
        const bit = word.charCodeAt(i) - 97;   // 'a' → 0, …, 'j' → 9
        cur ^= (1 << bit);                     // flip parity of this letter

        ans += (cnt.get(cur) || 0);             // same mask → 0 odd letters
        for (let k = 0; k < 10; k++) {         // masks differing by one bit
            const other = cur ^ (1 << k);
            ans += (cnt.get(other) || 0);
        }

        cnt.set(cur, (cnt.get(cur) || 0) + 1); // store current prefix
    }
    return ans;
}

function buildArray(nums) {
    const n = nums.length;
    const ans = new Array(n);
    // compute ans[i] = nums[nums[i]]
    for (let i = 0; i < n; i++) {
        ans[i] = nums[nums[i]];
    }
    return ans;
}

function longestCommonSubpath(n, paths) {
    if (!paths.length) return 0;
    const minLen = Math.min(...paths.map(p => p.length));
    const maxLen = Math.max(...paths.map(p => p.length));

    const MOD1 = 1000000007n, MOD2 = 1000000009n, BASE = 100007n;

    const pow1 = new Array(maxLen + 1).fill(1n);
    const pow2 = new Array(maxLen + 1).fill(1n);
    for (let i = 1; i <= maxLen; i++) {
        pow1[i] = (pow1[i - 1] * BASE) % MOD1;
        pow2[i] = (pow2[i - 1] * BASE) % MOD2;
    }

    const prefixes = [];
    for (const p of paths) {
        const pref1 = new Array(p.length + 1).fill(0n);
        const pref2 = new Array(p.length + 1).fill(0n);
        for (let i = 0; i < p.length; i++) {
            const x = BigInt(p[i] + 1);
            pref1[i + 1] = (pref1[i] * BASE + x) % MOD1;
            pref2[i + 1] = (pref2[i] * BASE + x) % MOD2;
        }
        prefixes.push([pref1, pref2]);
    }

    const mmod = (x, m) => ((x % m) + m) % m;

    const check = (L) => {
        if (L === 0) return true;
        let common = null;
        for (let idx = 0; idx < paths.length; idx++) {
            const [pref1, pref2] = prefixes[idx];
            const curSet = new Set();
            const plen = paths[idx].length;
            const mul1 = pow1[L], mul2 = pow2[L];
            for (let start = 0; start <= plen - L; start++) {
                const h1 = mmod(pref1[start + L] - pref1[start] * mul1, MOD1);
                const h2 = mmod(pref2[start + L] - pref2[start] * mul2, MOD2);
                curSet.add(h1 + ',' + h2);
            }
            if (idx === 0) {
                common = curSet;
                if (common.size === 0) return false;
            } else {
                const next = new Set();
                for (const v of common) if (curSet.has(v)) next.add(v);
                common = next;
                if (common.size === 0) return false;
            }
        }
        return common.size > 0;
    };

    let low = 0, high = minLen;
    while (low < high) {
        const mid = Math.floor((low + high + 1) / 2);
        if (check(mid)) low = mid; else high = mid - 1;
    }
    return low;
}

function countTriples(n) {
    let count = 0;
    for (let a = 1; a <= n; a++) {
        for (let b = 1; b <= n; b++) {
            const c2 = a*a + b*b;
            const c = Math.round(Math.sqrt(c2));
            if (c <= n && c*c === c2) count++;
        }
    }
    return count;
}

function sumGame(num) {
    var n = num.length, half = n / 2;
    var sumFirst = 0, sumSecond = 0, qFirst = 0, qSecond = 0;

    for (var i = 0; i < half; i++) {
        var ch = num[i];
        if (ch === '?') qFirst++; else sumFirst += ch.charCodeAt(0) - 48;
    }
    for (var i = half; i < n; i++) {
        var ch = num[i];
        if (ch === '?') qSecond++; else sumSecond += ch.charCodeAt(0) - 48;
    }

    var totalQ = qFirst + qSecond;
    if (totalQ % 2 === 1) return true; // Alice gets the extra move, guaranteed win

    var diff = sumFirst - sumSecond;
    // Bob wins iff diff == 4.5 * (qSecond - qFirst)
    return !(diff === 4.5 * (qSecond - qFirst));
}

function countGoodNumbers(n) {
    const MOD = 1000000007n;                     // modulus as BigInt

    // number of even / odd indices (0‑based)
    const evenCnt = Math.floor((n + 1) / 2);     // ceil(n/2)
    const oddCnt  = Math.floor(n / 2);           // floor(n/2)

    // fast exponentiation (binary exponentiation)
    function modPow(base, exp) {
        let result = 1n;
        let b = BigInt(base) % MOD;
        let e = BigInt(exp);
        while (e > 0n) {                         // MAIN LOGIC: binary exponentiation
            if (e & 1n) result = (result * b) % MOD;
            b = (b * b) % MOD;
            e >>= 1n;
        }
        return result;
    }

    const pow5 = modPow(5, evenCnt);             // 5^evenCnt mod MOD
    const pow4 = modPow(4, oddCnt);              // 4^oddCnt  mod MOD

    const ans = (pow5 * pow4) % MOD;             // combine the two independent counts
    return Number(ans);                          // fits into 32‑bit integer
}

function nearestExit(maze, entrance) {
    const rows = maze.length;
    const cols = maze[0].length;
    const [startR, startC] = entrance;

    const queue = [];
    let head = 0;
    queue.push([startR, startC, 0]);          // row, col, distance
    maze[startR][startC] = '+';               // mark entrance as visited

    const dirs = [
        [-1, 0], // up
        [1, 0],  // down
        [0, -1], // left
        [0, 1]   // right
    ];

    while (head < queue.length) {
        const [r, c, dist] = queue[head++];
        // check if current cell is an exit (border but not the entrance)
        if ((r === 0 || r === rows - 1 || c === 0 || c === cols - 1) &&
            !(r === startR && c === startC)) {
            return dist;
        }
        // explore neighbours
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && maze[nr][nc] === '.') {
                maze[nr][nc] = '+';           // mark visited
                queue.push([nr, nc, dist + 1]);
            }
        }
    }
    return -1; // no exit reachable
}

function concatenationOfArray(nums) {
