}

function minimumOperations(nums, start, goal) {
    if (start === goal) return 0;                     // trivial case

    const MAX = 1000;
    const visited = new Array(MAX + 1).fill(false);
    const queue = [];                                 // stores [value, steps]
    let head = 0;

    if (0 <= start && start <= MAX) {                // start must be inside range to expand
        visited[start] = true;
        queue.push([start, 0]);
    }

    while (head < queue.length) {
        const [x, steps] = queue[head++];             // dequeue

        for (let i = 0; i < nums.length; i++) {       // try both + and – with each num
            const add = x + nums[i];
            const sub = x - nums[i];

            // if we reach goal (even out of bounds) return answer
            if (add === goal || sub === goal) return steps + 1;

            // enqueue only values that stay inside [0,1000] and are unvisited
            if (0 <= add && add <= MAX && !visited[add]) {
                visited[add] = true;
                queue.push([add, steps + 1]);
            }
            if (0 <= sub && sub <= MAX && !visited[sub]) {
                visited[sub] = true;
                queue.push([sub, steps + 1]);
            }
        }
    }
    return -1;                                        // goal unreachable
}

function areAlmostEquivalent(word1, word2) {
    var diff = new Array(26).fill(0);
    // count frequencies: +1 for word1, -1 for word2
    for (var i = 0; i < word1.length; i++) diff[word1.charCodeAt(i) - 97]++;
    for (var i = 0; i < word2.length; i++) diff[word2.charCodeAt(i) - 97]--;
    // verify each letter's difference does not exceed 3
    for (var i = 0; i < 26; i++) if (Math.abs(diff[i]) > 3) return false;
    return true;
}

function countVowelSubstrings(word) {
    const vowelIdx = { a: 0, e: 1, i: 2, o: 3, u: 4 };
    const isVowel = ch => ch in vowelIdx;
    const n = word.length;
    let ans = 0;
    let blockStart = 0;
    let shrinkLeft = 0;
    const cnt = [0, 0, 0, 0, 0];
    let distinct = 0;
    for (let right = 0; right < n; right++) {
        const ch = word[right];
        if (!isVowel(ch)) {
            blockStart = right + 1;
            shrinkLeft = right + 1;
            cnt.fill(0);
            distinct = 0;
            continue;
        }
        const idx = vowelIdx[ch];
        if (cnt[idx] === 0) distinct++;
        cnt[idx]++;
        if (distinct === 5) {
            while (shrinkLeft <= right) {
                const leftIdx = vowelIdx[word[shrinkLeft]];
                if (cnt[leftIdx] > 1) {
                    cnt[leftIdx]--;
                    shrinkLeft++;
                } else break;
            }
            ans += (shrinkLeft - blockStart + 1);
        }
    }
    return ans;
}

var maxTaskAssign = function(tasks, workers, pills, strength) {
    tasks = tasks.slice().sort((a,b)=>a-b);
    workers = workers.slice().sort((a,b)=>a-b);
    const n = tasks.length, m = workers.length;
    function bisectLeft(arr, x) {
        let lo=0, hi=arr.length;
        while (lo<hi) {
            const mid=(lo+hi)>>1;
            if (arr[mid] < x) lo=mid+1; else hi=mid;
        }
        return lo;
    }
    function canAssign(k) {
        const available = workers.slice();
        let remainingPills = pills;
        for (let idx=k-1; idx>=0; idx--) {
            const task = tasks[idx];
            let pos = bisectLeft(available, task);
            if (pos < available.length) {
                available.splice(pos,1);
                continue;
            }
            if (remainingPills === 0) return false;
            let need = task - strength;
            if (need < 0) need = 0;
            pos = bisectLeft(available, need);
            if (pos === available.length) return false;
            available.splice(pos,1);
            remainingPills--;
        }
        return true;
    }
    let low=0, high=Math.min(n,m);
    while (low < high) {
        const mid = Math.floor((low+high+1)/2);
        if (canAssign(mid)) low=mid; else high=mid-1;
    }
    return low;
};

class Robot {
    constructor(width, height) {
        this.width = width;
        this.height = height;
        this.x = 0;
        this.y = 0;
        this.dirIdx = 0;
        this.dx = [1, 0, -1, 0];
        this.dy = [0, 1, 0, -1];
    }
    move(num) {
        for (let i = 0; i < num; i++) {
            let nx = this.x + this.dx[this.dirIdx], ny = this.y + this.dy[this.dirIdx];
            if (nx < 0 || nx >= this.width || ny < 0 || ny >= this.height) {
                this.dirIdx = (this.dirIdx + 1) % 4;
                nx = this.x + this.dx[this.dirIdx]; ny = this.y + this.dy[this.dirIdx];
            }
            this.x = nx; this.y = ny;
        }
    }
    getPos() { return [this.x, this.y]; }
    getDir() { return ["East","North","West","South"][this.dirIdx]; }
}

function mostBeautifulItem(items, queries) {
    // sort items by price
    const sorted = items.slice().sort((a, b) => a[0] - b[0]);

    const priceList = [];
    const bestList = [];
    let curMax = 0;

    // build prefix‑maximum beauty array
    for (const [price, beauty] of sorted) {
        curMax = Math.max(curMax, beauty);
        priceList.push(price);
        bestList.push(curMax);
    }

    const answers = new Array(queries.length);

    // binary search for each query
    for (let i = 0; i < queries.length; i++) {
        const q = queries[i];
        let lo = 0, hi = priceList.length - 1, idx = -1;
        while (lo <= hi) {
            const mid = (lo + hi) >> 1;
            if (priceList[mid] <= q) {        // price fits the query
                idx = mid;
                lo = mid + 1;                 // try to find a larger price
            } else {
                hi = mid - 1;
            }
        }
        answers[i] = idx === -1 ? 0 : bestList[idx];
    }

    return answers;
}

function minimizedMaximum(n, quantities) {
    // binary search on the answer
    let low = 1;
    let high = Math.max(...quantities);
    while (low < high) {
        const mid = Math.floor((low + high) / 2);
        // check if mid is feasible
        let needed = 0;
        for (let i = 0; i < quantities.length; i++) {
            needed += Math.ceil(quantities[i] / mid);
            if (needed > n) break;               // early exit
        }
        if (needed <= n) high = mid;             // try smaller maximum
        else low = mid + 1;                       // need larger maximum
    }
    return low;
}

function timeNeededToBuy(tickets, k) {
    var target = tickets[k];                 // tickets needed by person k
    var time = 0;
    for (var i = 0; i < tickets.length; i++) {
        // people before or at k can buy at most 'target' tickets,
        // people after k can buy at most 'target-1' tickets
        time += i <= k ? Math.min(tickets[i], target)
                       : Math.min(tickets[i], target - 1);
    }
    return time;
}

function reverseEvenLengthGroups(head) {
    // dummy node simplifies handling of the first group
    const dummy = { val: 0, next: head };
    let prevGroupTail = dummy;   // tail of the already processed part
    let current = head;          // first node of the next group
    let groupSize = 1;           // expected size of the current group

    while (current !== null) {
        // ---- count nodes of the current group ----
        let groupHead = current;
        let count = 0;
        let prev = null;         // will end up as the last node of the group
        while (count < groupSize && current !== null) {
            prev = current;
            current = current.next;
            count++;
        }
        let groupTail = prev;          // last node of this group
        let nextGroupHead = current;   // first node of the following group

        if (count % 2 === 0) {         // ---- reverse even‑length group ----
            // reverse nodes from groupHead to groupTail inclusive
            let prevNode = null;
            let node = groupHead;
            while (node !== nextGroupHead) {
                const nxt = node.next;
                node.next = prevNode;
                prevNode = node;
                node = nxt;
            }
            // connect reversed segment with the rest of the list
            prevGroupTail.next = groupTail;   // groupTail is new head after reversal
            groupHead.next = nextGroupHead;   // groupHead became the tail
            prevGroupTail = groupHead;        // move tail pointer forward
        } else {
            // ---- keep odd‑length group unchanged ----
            prevGroupTail = groupTail;
        }

        groupSize++;   // next group should be one node larger
    }

    return dummy.next;
}

function decodeSlantedCipher(encodedText, rows) {
    if (rows === 1) return encodedText;
    const n = encodedText.length;
    const cols = Math.floor(n / rows);
    let res = "";
    for (let c = 0; c < cols; c++) {
        let r = 0, j = c;
        while (r < rows && j < cols) {
            res += encodedText[r * cols + j];
            r++;
            j++;
        }
    }
    return res.replace(/ +$/, '');
}

