function wateringPlants(plants, capacity) {
    let steps = 0;
    let water = capacity;
    let pos = -1; // start at the river
    for (let i = 0; i < plants.length; i++) {
        if (water < plants[i]) {
            // return to river and refill
            steps += pos + 1;
            water = capacity;
            // walk from river to current plant
            steps += i + 1;
            pos = i;
            water -= plants[i];
        } else {
            // walk directly to current plant
            steps += i - pos;
            pos = i;
            water -= plants[i];
        }
    }
    return steps;
}

function processRestrictedFriendRequests(n, restrictions, requests) {
    // ----- Union‑Find -----
    const parent = new Array(n).fill(0).map((_, i) => i);
    const rank   = new Array(n).fill(0);

    function find(x) {                     // path compression
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    function union(a, b) {                 // union by rank
        let ra = find(a), rb = find(b);
        if (ra === rb) return;
        if (rank[ra] < rank[rb]) parent[ra] = rb;
        else if (rank[ra] > rank[rb]) parent[rb] = ra;
        else { parent[rb] = ra; rank[ra]++; }
    }

    const answer = [];

    for (const [u, v] of requests) {
        const ru = find(u), rv = find(v);
        if (ru === rv) {                    // already friends
            answer.push(true);
            continue;
        }

        // check every restriction for a conflict with the prospective merge
        let conflict = false;
        for (const [x, y] of restrictions) {
            const rx = find(x), ry = find(y);
            if ((rx === ru && ry === rv) || (rx === rv && ry === ru)) {
                conflict = true;
                break;
            }
        }

        if (conflict) answer.push(false);   // request denied
        else {
            answer.push(true);               // request accepted
            union(ru, rv);                   // merge the two components
        }
    }

    return answer;
}


