function isPalinBaseK(num, k) {
  const digits = [];
  let x = num;
  while (x > 0) { digits.push(x % k); x = Math.floor(x / k); }
  let l = 0, r = digits.length - 1;
  while (l < r) { if (digits[l] !== digits[r]) return false; l++; r--; }
  return true;
}

function kMirror(k, n) {
  let sum = 0n, found = 0;
  for (let len = 1; found < n; len++) {
    const halfLen = Math.ceil(len / 2);
    const start = Math.pow(10, halfLen - 1);
    const end = Math.pow(10, halfLen) - 1;
    for (let half = start; half <= end && found < n; half++) {
      const s = String(half);
      const rev = s.split('').reverse().join('');
      const palStr = (len % 2 === 0) ? s + rev : s + rev.slice(1);
      const pal = Number(palStr);
      if (isPalinBaseK(pal, k)) {
        sum += BigInt(pal);
        found++;
      }
    }
  }
  return Number(sum); // convert back from BigInt - the accumulator needs BigInt precision
                       // internally, but the function must return a plain Number
}

function maxDistance(colors) {
    const n = colors.length;
    // if the two ends already differ, we have the maximum possible distance
    if (colors[0] !== colors[n - 1]) return n - 1;

    let leftDiff = -1;   // index of first house from left that differs from rightmost color
    const rightColor = colors[n - 1];
    for (let i = 0; i < n; i++) {          // scan from left
        if (colors[i] !== rightColor) {    // found a different color
            leftDiff = i;
            break;
        }
    }

    let rightDiff = -1;  // index of first house from right that differs from leftmost color
    const leftColor = colors[0];
    for (let i = n - 1; i >= 0; i--) {     // scan from right
        if (colors[i] !== leftColor) {
            rightDiff = i;
            break;
        }
    }

    // compute distances using the two candidate houses
    const distFromLeft = leftDiff === -1 ? 0 : n - 1 - leftDiff;
    const distFromRight = rightDiff === -1 ? 0 : rightDiff;

    return Math.max(distFromLeft, distFromRight);
}

function RangeFreqQuery(nums) {
    const posMap = new Map();                     // value -> sorted list of indices
    for (let i = 0; i < nums.length; i++) {       // build the map
        const v = nums[i];
        if (!posMap.has(v)) posMap.set(v, []);
        posMap.get(v).push(i);
    }

    // binary search: first index >= target
    function lowerBound(arr, target) {
        let lo = 0, hi = arr.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (arr[mid] < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    // binary search: first index > target
    function upperBound(arr, target) {
        let lo = 0, hi = arr.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (arr[mid] <= target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    return {
        query: function (left, right, value) {
            const list = posMap.get(value);
            if (!list) return 0;                    // value never appears
            const l = lowerBound(list, left);       // first occurrence inside interval
            const r = upperBound(list, right);      // first occurrence after interval
            return r - l;                           // count inside [left, right]
        }
    };
}

function minimumNumberOfFoodBucketsToFeedTheHamsters(hamsters) {
    const n = hamsters.length;
    const bucket = new Array(n).fill(false);
    let count = 0;
    for (let i = 0; i < n; i++) {
        const ch = hamsters[i];
        if (ch !== 'H') continue;
        if ((i > 0 && bucket[i - 1]) || (i + 1 < n && bucket[i + 1])) continue;
        if (i + 1 < n && hamsters[i + 1] === '.' && !bucket[i + 1]) {
            bucket[i + 1] = true;
            count++;
        } else if (i > 0 && hamsters[i - 1] === '.' && !bucket[i - 1]) {
            bucket[i - 1] = true;
            count++;
        } else {
            return -1;
        }
    }
    return count;
}

function countFertilePyramidsInALand(grid) {
    if (!grid.length) return 0;
    const m = grid.length, n = grid[0].length;
    let ans = 0;

    let nextRow = new Array(n).fill(0);
    for (let i = m - 1; i >= 0; i--) {
        const cur = new Array(n).fill(0);
        for (let j = 0; j < n; j++) {
            if (grid[i][j] === 1) {
                if (i === m - 1 || j === 0 || j === n - 1) cur[j] = 1;
                else cur[j] = 1 + Math.min(nextRow[j - 1], nextRow[j], nextRow[j + 1]);
                ans += cur[j] - 1;
            }
        }
        nextRow = cur;
    }

    let prevRow = new Array(n).fill(0);
    for (let i = 0; i < m; i++) {
        const cur = new Array(n).fill(0);
        for (let j = 0; j < n; j++) {
            if (grid[i][j] === 1) {
                if (i === 0 || j === 0 || j === n - 1) cur[j] = 1;
                else cur[j] = 1 + Math.min(prevRow[j - 1], prevRow[j], prevRow[j + 1]);
                ans += cur[j] - 1;
            }
        }
        prevRow = cur;
    }
    return ans;
}

function kRadiusAverages(nums, k) {
    const n = nums.length;
    const result = Array(n).fill(-1);
    const windowSize = 2 * k + 1;
    if (windowSize > n) return result;               // not enough elements for any window

    let sum = 0;
    for (let i = 0; i < windowSize; i++) sum += nums[i]; // initial window sum

    for (let i = k; i <= n - k - 1; i++) {
        if (i > k) sum += nums[i + k] - nums[i - k - 1]; // slide window: add right, remove left
        result[i] = Math.trunc(sum / windowSize);       // integer division truncates toward zero
    }
    return result;
}

function countCommonWords(words1, words2) {
    const freq1 = Object.create(null);
    for (const w of words1) {
        freq1[w] = (freq1[w] || 0) + 1;
