function maxScoreDivisions(nums) {
    var n = nums.length;
    var totalOnes = 0;
    for (var i = 0; i < n; i++) {
        if (nums[i] === 1) totalOnes++;
    }

    var zerosLeft = 0, onesSeen = 0;
    var maxScore = -1;
    var answer = [];

    for (var i = 0; i <= n; i++) {
        var onesRight = totalOnes - onesSeen;               // main logic
        var score = zerosLeft + onesRight;

        if (score > maxScore) {
            maxScore = score;
            answer = [i];
        } else if (score === maxScore) {
            answer.push(i);
        }

        if (i < n) {                     // update counters for next division
            if (nums[i] === 0) zerosLeft++;
            else                onesSeen++;
        }
    }
    return answer;
}

function partitionArray(nums, pivot) {
