    for (let i = 0; i < nums.length; i++) {
        const v = nums[i];
        if (v < pivot) less.push(v);
        else if (v === pivot) equal.push(v);
        else greater.push(v);
    }

    // concatenate the three stable groups
    return less.concat(equal, greater);
}

function minCostSetTime(startAt, moveCost, pushCost, targetSeconds) {
  function cost(minutes, seconds) {
