function minimumDifferenceInSumsAfterRemovalOfElements(nums) {
    const n = Math.floor(nums.length / 3);

    class MinHeap {
        constructor() { this.a = []; }
        push(v) { this.a.push(v); let i = this.a.length - 1; while (i > 0) { const p = (i - 1) >> 1; if (this.a[p] > this.a[i]) { [this.a[p], this.a[i]] = [this.a[i], this.a[p]]; i = p; } else break; } }
        pop() { const top = this.a[0]; const last = this.a.pop(); if (this.a.length) { this.a[0] = last; let i = 0; while (true) { let l = 2*i+1, r = 2*i+2, s = i; if (l < this.a.length && this.a[l] < this.a[s]) s = l; if (r < this.a.length && this.a[r] < this.a[s]) s = r; if (s === i) break; [this.a[i], this.a[s]] = [this.a[s], this.a[i]]; i = s; } } return top; }
        get length() { return this.a.length; }
    }
    class MaxHeap {
        constructor() { this.a = []; }
        push(v) { this.a.push(v); let i = this.a.length - 1; while (i > 0) { const p = (i - 1) >> 1; if (this.a[p] < this.a[i]) { [this.a[p], this.a[i]] = [this.a[i], this.a[p]]; i = p; } else break; } }
        pop() { const top = this.a[0]; const last = this.a.pop(); if (this.a.length) { this.a[0] = last; let i = 0; while (true) { let l = 2*i+1, r = 2*i+2, s = i; if (l < this.a.length && this.a[l] > this.a[s]) s = l; if (r < this.a.length && this.a[r] > this.a[s]) s = r; if (s === i) break; [this.a[i], this.a[s]] = [this.a[s], this.a[i]]; i = s; } } return top; }
        get length() { return this.a.length; }
    }

    const leftMin = new Array(3 * n + 1).fill(0);
    let curSum = nums.slice(0, n).reduce((a, b) => a + b, 0);
    const leftHeap = new MaxHeap(); // stores actual values, pop() gives max
    for (const x of nums.slice(0, n)) leftHeap.push(x);
    leftMin[n] = curSum;
    for (let i = n; i < 2 * n; i++) {
        const x = nums[i];
        leftHeap.push(x);
        curSum += x;
        if (leftHeap.length > n) {
            const largest = leftHeap.pop();
            curSum -= largest;
        }
        leftMin[i + 1] = curSum;
    }

    const rightMax = new Array(3 * n + 1).fill(0);
    curSum = nums.slice(2 * n).reduce((a, b) => a + b, 0);
    const rightHeap = new MinHeap();
    for (const x of nums.slice(2 * n)) rightHeap.push(x);
    rightMax[2 * n] = curSum;
    for (let i = 2 * n - 1; i >= n; i--) {
        const x = nums[i];
        rightHeap.push(x);
        curSum += x;
        if (rightHeap.length > n) {
            const smallest = rightHeap.pop();
            curSum -= smallest;
        }
        rightMax[i] = curSum;
    }

    let ans = Infinity;
    for (let i = n; i <= 2 * n; i++) {
        const diff = leftMin[i] - rightMax[i];
        if (diff < ans) ans = diff;
    }
    return ans;
}

