function Bitset(size){
    this.n = size;
    this.bits = new Uint8Array(size);
    this.flipped = false;
    this.cnt = 0;
}
Bitset.prototype.fix = function(idx){
    if (!this.flipped){
        if (this.bits[idx] === 0){
            this.bits[idx] = 1;
            this.cnt++;
        }
    } else {
        if (this.bits[idx] === 1){
            this.bits[idx] = 0;
            this.cnt++;
        }
    }
};
Bitset.prototype.unfix = function(idx){
    if (!this.flipped){
        if (this.bits[idx] === 1){
            this.bits[idx] = 0;
            this.cnt--;
        }
    } else {
        if (this.bits[idx] === 0){
            this.bits[idx] = 1;
            this.cnt--;
        }
    }
};
Bitset.prototype.flip = function(){
    this.flipped = !this.flipped;
    this.cnt = this.n - this.cnt;
};
Bitset.prototype.all = function(){
    return this.cnt === this.n;
};
Bitset.prototype.one = function(){
    return this.cnt > 0;
};
Bitset.prototype.count = function(){
    return this.cnt;
};
Bitset.prototype.toString = function(){
    const res = new Array(this.n);
    if (!this.flipped){
        for (let i = 0; i < this.n; i++) res[i] = this.bits[i] ? '1' : '0';
    } else {
        for (let i = 0; i < this.n; i++) res[i] = this.bits[i] ? '0' : '1';
    }
    return res.join('');
};

function minOperations(nums) {
    const evenFreq = new Map();   // frequencies of numbers at even indices
    const oddFreq  = new Map();   // frequencies of numbers at odd indices

    // count frequencies
    for (let i = 0; i < nums.length; i++) {
        const map = (i & 1) === 0 ? evenFreq : oddFreq;
        map.set(nums[i], (map.get(nums[i]) || 0) + 1);
    }

    // helper: return two most frequent [value, count] pairs (or count 0 if missing)
    function topTwo(freqMap) {
        let first = [-1, 0], second = [-1, 0];
        for (const [val, cnt] of freqMap) {
            if (cnt > first[1]) {
                second = first;
                first = [val, cnt];
            } else if (cnt > second[1]) {
                second = [val, cnt];
            }
        }
        return [first, second];
    }

    const [evenBest, evenSecond] = topTwo(evenFreq);
    const [oddBest,  oddSecond]  = topTwo(oddFreq);

    // decide which values to keep
    let keep;
    if (evenBest[0] !== oddBest[0]) {               // best values are different
        keep = evenBest[1] + oddBest[1];
    } else {                                        // same value, need a second choice
        keep = Math.max(evenBest[1] + oddSecond[1],
                        evenSecond[1] + oddBest[1]);
    }

    return nums.length - keep;
}

