function maximumANDSum(nums, numSlots) {
    const n = nums.length;
    const memo = new Map();
    // mask1: which slots currently hold exactly 1 number; mask2: which slots hold 2 (full)
    function dp(i, mask1, mask2) {
        if (i === n) return 0;
        const key = i + ',' + mask1 + ',' + mask2;
        if (memo.has(key)) return memo.get(key);
        let res = 0;
        for (let j = 0; j < numSlots; j++) {
            if (mask2 & (1 << j)) continue; // slot j is already full
            let newMask1 = mask1, newMask2 = mask2;
            if (!(mask1 & (1 << j))) {
                newMask1 = mask1 | (1 << j); // slot goes from empty to 1 number
            } else {
                newMask1 = mask1 ^ (1 << j); // slot goes from 1 to 2 numbers (full)
                newMask2 = mask2 | (1 << j);
            }
            const cand = dp(i + 1, newMask1, newMask2) + (nums[i] & (j + 1));
            if (cand > res) res = cand;
        }
        memo.set(key, res);
        return res;
    }
    return dp(0, 0, 0);
}

function maximumSplit(finalSum) {
    if (finalSum % 2 !== 0) return [];
    const result = [];
    let next = 2;
    let remaining = finalSum;
    while (remaining >= next) {
        result.push(next);
        remaining -= next;
        next += 2;
    }
    if (remaining > 0) result[result.length - 1] += remaining;
    return result;
}

function mergeNodes(head) {
