  return result;
}

function goodTriplets(nums1, nums2) {
    const n = nums1.length;
    const posInNums2 = new Array(Math.max(...nums2) + 1).fill(0);
    for (let idx = 0; idx < nums2.length; idx++) posInNums2[nums2[idx]] = idx;
    const p = nums1.map(val => posInNums2[val]);

    class Fenwick {
        constructor(size) { this.n = size; this.bit = new Array(size+1).fill(0); }
        add(idx, delta=1) {
            let i = idx+1;
            while (i <= this.n) { this.bit[i] += delta; i += i & (-i); }
        }
        sum(idx) {
            if (idx < 0) return 0;
            let i = idx+1, res = 0;
            while (i) { res += this.bit[i]; i -= i & (-i); }
            return res;
        }
    }
    const fenwickLeft = new Fenwick(n);
    const leftCounts = new Array(n).fill(0);
    for (let i = 0; i < n; i++) {
        const pi = p[i];
        leftCounts[i] = fenwickLeft.sum(pi-1);
        fenwickLeft.add(pi, 1);
    }
    const fenwickRight = new Fenwick(n);
    const rightCounts = new Array(n).fill(0);
    let seen = 0;
    for (let i = n-1; i >= 0; i--) {
        const pi = p[i];
        const lessOrEqual = fenwickRight.sum(pi);
        const greater = seen - lessOrEqual;
        rightCounts[i] = greater;
        fenwickRight.add(pi, 1);
        seen++;
    }
    let ans = 0;
    for (let i = 0; i < n; i++) ans += leftCounts[i] * rightCounts[i];
    return ans;
}

function countEvenDigitSum(num) {
  const s = String(num);               // string representation of num
  const n = s.length;
  const memo = Array.from({ length: n }, () => Array(2).fill(-1));

  // dfs(pos, parity, tight) returns count of numbers for suffix [pos..)
  function dfs(pos, parity, tight) {
    if (pos === n) return parity === 0 ? 1 : 0;               // main logic: leaf
    if (!tight && memo[pos][parity] !== -1) return memo[pos][parity]; // reuse

    const limit = tight ? s.charCodeAt(pos) - 48 : 9;        // main logic: bound
    let res = 0;
    for (let d = 0; d <= limit; d++) {                       // main logic: iterate
      const nextParity = (parity + d) & 1;                   // parity update
      const nextTight = tight && d === limit;
      res += dfs(pos + 1, nextParity, nextTight);
    }

    if (!tight) memo[pos][parity] = res;                     // store for reuse
    return res;
  }

  // subtract 1 to exclude the number 0 (its digit sum is 0, even)
  return dfs(0, 0, true) - 1;
}

function countPairs(nums, k) {
    // helper: Euclidean algorithm
    function gcd(a, b) {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    const cnt = new Map();                 // divisor → frequency
    for (let i = 0; i < nums.length; ++i) {
        const g = gcd(nums[i], k);          // main logic: map each number to its gcd with k
        cnt.set(g, (cnt.get(g) || 0) + 1);
    }

    const divisors = Array.from(cnt.keys()); // only divisors that actually appear
    let ans = 0;
    for (let i = 0; i < divisors.length; ++i) {
        const d1 = divisors[i];
        const c1 = cnt.get(d1);
        for (let j = i; j < divisors.length; ++j) {
            const d2 = divisors[j];
            if ((d1 * d2) % k !== 0) continue; // check product divisibility
            const c2 = cnt.get(d2);
            if (i === j) {
                ans += c1 * (c1 - 1) / 2;      // pairs inside the same bucket
            } else {
                ans += c1 * c2;                // cross‑bucket pairs
            }
        }
    }
    return ans;
