function getAncestors(n, edges) {
    // build adjacency list and indegree array
    const adj = Array.from({ length: n }, () => []);
    const indeg = new Array(n).fill(0);
    for (const [a, b] of edges) {
        adj[a].push(b);
        indeg[b]++;
    }

    // ancestors[i] will be a Set of all ancestors of i
    const ancestors = Array.from({ length: n }, () => new Set());

    // Kahn's algorithm for topological order
    const queue = [];
    for (let i = 0; i < n; i++) if (indeg[i] === 0) queue.push(i);

    while (queue.length) {
        const u = queue.shift();                     // current vertex
        for (const v of adj[u]) {
            ancestors[v].add(u);                     // u is a direct ancestor
            for (const anc of ancestors[u]) {        // propagate indirect ancestors
                ancestors[v].add(anc);
            }
            if (--indeg[v] === 0) queue.push(v);     // ready for processing
        }
    }

    // convert each Set to a sorted array
    const answer = ancestors.map(set => Array.from(set).sort((a, b) => a - b));
    return answer;
}

function minimumTime(time, totalTrips) {
    // binary search on time
    let low = 1;
    let high = Math.min(...time) * totalTrips; // upper bound

    while (low < high) {
        const mid = Math.floor((low + high) / 2);
        let trips = 0;
        for (let i = 0; i < time.length; i++) {
            trips += Math.floor(mid / time[i]); // trips each bus can finish by mid
            if (trips >= totalTrips) break; // early stop
        }
        if (trips >= totalTrips) {
            high = mid; // enough trips, try smaller time
        } else {
            low = mid + 1; // not enough, need more time
        }
    }
    return low;
}

// TIME: O(N log (minTime * totalTrips)) SPACE: O(1)

function minimumTimeToFinishTheRace(tires, changeTime, numLaps) {
    const INF = 1e18;
    const best = new Array(numLaps + 1).fill(INF);
    for (const [f, r] of tires) {
        let lap = 1, cur = f, total = f;
        while (lap <= numLaps) {
            if (total < best[lap]) best[lap] = total;
            const nextTime = cur * r;
            if (nextTime > changeTime + f) break;
            cur = nextTime;
            total += cur;
            lap++;
        }
    }
    const dp = new Array(numLaps + 1).fill(INF);
    dp[0] = 0;
    for (let i = 1; i <= numLaps; i++) {
        dp[i] = best[i];
        for (let k = 1; k < i; k++) {
            if (best[k] !== INF) {
                const cand = dp[i - k] + changeTime + best[k];
                if (cand < dp[i]) dp[i] = cand;
            }
        }
    }
    return dp[numLaps];
}

function createBinaryTree(descriptions) {
    // map value → TreeNode instance
    const nodes = new Map();
    // set of values that are children
    const children = new Set();

    // helper to obtain (or create) a node for a given value
    function getNode(val) {
        if (!nodes.has(val)) nodes.set(val, { val: val, left: null, right: null });
        return nodes.get(val);
    }

    // build the tree from the descriptions
    for (const [parentVal, childVal, isLeft] of descriptions) {
        const parentNode = getNode(parentVal);
        const childNode  = getNode(childVal);
        if (isLeft) parentNode.left = childNode;   // attach as left child
        else       parentNode.right = childNode;  // attach as right child
        children.add(childVal);                    // remember that this node has a parent
    }

    // the root is the only node that never appeared as a child
    for (const val of nodes.keys()) {
        if (!children.has(val)) return nodes.get(val);
    }
    return null; // should never happen for valid input
}

function replaceNonCoprime(nums) {
    // Euclidean algorithm for GCD
    function gcd(a, b) {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    const stack = [];

    for (let i = 0; i < nums.length; i++) {
        stack.push(nums[i]);                         // add next number
        // MAIN LOGIC: merge while the last two numbers are non‑coprime
        while (stack.length >= 2) {
            const b = stack[stack.length - 1];
            const a = stack[stack.length - 2];
            const g = gcd(a, b);
            if (g === 1) break;                     // coprime → stop merging
            stack.pop();                             // remove b
            stack.pop();                             // remove a
            const lcm = (a / g) * b;                 // a/g * b is safe from overflow
            stack.push(lcm);                         // push merged value
        }
    }
    return stack;
}

function mostFrequentFollowing(nums, key) {
    const followCount = {};               // map: target -> how many times it follows key

    // count occurrences of each target that follows the key
    for (let i = 0; i < nums.length - 1; i++) {
        if (nums[i] === key) {
            const target = nums[i + 1];
            followCount[target] = (followCount[target] || 0) + 1;
        }
    }

    // find the target with the maximum count
    let bestTarget = null;
    let maxCount = -1;
    for (const t in followCount) {
        const cnt = followCount[t];
        if (cnt > maxCount) {
            maxCount = cnt;
            bestTarget = Number(t); // keys of an object are strings
        }
    }
    return bestTarget;
}

function cellsInRange(s) {
  const parts = s.split(':');                     // split range
  const startCol = parts[0].charCodeAt(0);
  const endCol   = parts[1].charCodeAt(0);
  const startRow = parseInt(parts[0].slice(1), 10);
  const endRow   = parseInt(parts[1].slice(1), 10);

  const result = [];

  for (let c = startCol; c <= endCol; c++) {      // iterate columns
    for (let r = startRow; r <= endRow; r++) {    // iterate rows
      result.push(String.fromCharCode(c) + r);
    }
  }
  return result;
}

function minMovesToMakePalindrome(s) {
    const n = s.length;
    // collect positions of each character
    const posMap = {};
    for (let i = 0; i < n; i++) {
        const ch = s[i];
        if (!posMap[ch]) posMap[ch] = [];
        posMap[ch].push(i);
    }

    const target = new Array(n);
    let left = 0, right = n - 1;

    // build the target order: pair outermost positions, middle stays in centre
    for (const ch in posMap) {
        const arr = posMap[ch];
        while (arr.length > 1) {
            const lPos = arr.shift();   // smallest index
            const rPos = arr.pop();     // largest index
            target[left++] = lPos;
            target[right--] = rPos;
        }
        if (arr.length === 1) {          // middle character (odd length)
            target[Math.floor(n / 2)] = arr[0];
        }
    }

    // Fenwick Tree for counting already placed indices
    class Fenwick {
        constructor(size) {
            this.n = size;
            this.bit = new Array(size + 1).fill(0);
        }
        add(idx, delta) {
            for (let i = idx; i <= this.n; i += i & -i) this.bit[i] += delta;
        }
        sum(idx) {
            let res = 0;
            for (let i = idx; i > 0; i -= i & -i) res += this.bit[i];
            return res;
        }
    }

    const ft = new Fenwick(n);
    let moves = 0;

    // count inversions of target order
    for (let i = 0; i < n; i++) {
        const pos = target[i];          // original index that should go to i
        const placedBefore = ft.sum(pos + 1); // how many of the earlier elements are ≤ pos
        moves += i - placedBefore;      // elements already placed that are > pos
        ft.add(pos + 1, 1);              // mark this index as placed
    }
    return moves;
}

var minimalKSum = function(nums, k) {
    const uniq = Array.from(new Set(nums)).sort((a,b)=>a-b);
    let added = 0, total = 0, prev = 0;
    for (const val of uniq) {
        if (added >= k) break;
        const gap = val - prev - 1;
        if (gap > 0) {
            const take = Math.min(gap, k - added);
            const first = prev+1, last = prev+take;
            total += (first+last)*take/2;
            added += take;
        }
        prev = val;
    }
    if (added < k) {
        const take = k - added;
        const first = prev+1, last = prev+take;
        total += (first+last)*take/2;
    }
    return total;
};

function findKDistantIndices(nums, key, k) {
    const n = nums.length;
    const diff = new Array(n + 1).fill(0);          // difference array

    // MAIN LOGIC: for each key position, mark its k‑range in diff
    for (let i = 0; i < n; i++) {
        if (nums[i] === key) {
            const l = Math.max(0, i - k);
            const r = Math.min(n - 1, i + k);
            diff[l] += 1;
            diff[r + 1] -= 1;
        }
    }

    const result = [];
    let cur = 0;
    for (let i = 0; i < n; i++) {
        cur += diff[i];               // prefix sum = number of covering intervals
        if (cur > 0) result.push(i); // index i is k‑distant
    }
    return result;
}

function maximizeTheTopmostElementAfterKMoves(nums, k) {
    const n = nums.length;
    if (k === 0) return nums[0];
    if (n === 1) return k % 2 === 1 ? -1 : nums[0];
    if (k === 1) return n > 1 ? nums[1] : -1;

    const limit = Math.min(k - 1, n);
    let maxCandidate = nums[0];
    for (let i = 1; i < limit; i++) if (nums[i] > maxCandidate) maxCandidate = nums[i];

    if (k < n && nums[k] > maxCandidate) maxCandidate = nums[k];
    return maxCandidate;
}

function countArtifacts(n, artifacts, dig) {
    // map each occupied cell to the index of its artifact
    const cellToArtifact = Object.create(null);
    const remaining = new Array(artifacts.length);

    for (let i = 0; i < artifacts.length; ++i) {
        const [r1, c1, r2, c2] = artifacts[i];
        const area = (r2 - r1 + 1) * (c2 - c1 + 1);
        remaining[i] = area;                         // cells still covered
        for (let r = r1; r <= r2; ++r) {
            for (let c = c1; c <= c2; ++c) {
                cellToArtifact[r + ',' + c] = i;     // store owner artifact
            }
        }
    }

    // process each dig
    for (const [r, c] of dig) {
        const key = r + ',' + c;
        const idx = cellToArtifact[key];
        if (idx !== undefined) {                     // cell belongs to an artifact
            remaining[idx]--;                        // uncover one part
            delete cellToArtifact[key];              // avoid double counting
        }
    }

    // count artifacts whose all parts are uncovered
    let extracted = 0;
    for (let i = 0; i < remaining.length; ++i) {
        if (remaining[i] === 0) ++extracted;
    }
    return extracted;
}

function minimumWeight(n, edges, src1, src2, dest) {
    class MinHeap {
        constructor() { this.heap = []; }
        isEmpty() { return this.heap.length === 0; }
        push(item) {
            const h = this.heap;
            h.push(item);
            let i = h.length - 1;
            while (i > 0) {
                const p = (i - 1) >> 1;
                if (h[p][0] <= h[i][0]) break;
                [h[p], h[i]] = [h[i], h[p]];
                i = p;
            }
        }
        pop() {
            const h = this.heap;
            const top = h[0];
            const last = h.pop();
            if (h.length) {
                h[0] = last;
                let i = 0;
                while (true) {
                    let l = i * 2 + 1, r = i * 2 + 2, smallest = i;
                    if (l < h.length && h[l][0] < h[smallest][0]) smallest = l;
                    if (r < h.length && h[r][0] < h[smallest][0]) smallest = r;
                    if (smallest === i) break;
                    [h[i], h[smallest]] = [h[smallest], h[i]];
                    i = smallest;
                }
            }
            return top;
        }
    }

    const adj = Array.from({ length: n }, () => []);
    const rev = Array.from({ length: n }, () => []);
    for (const [u, v, w] of edges) {
        adj[u].push([v, w]);
        rev[v].push([u, w]);
    }

    function dijkstra(start, graph) {
        const INF = Number.MAX_SAFE_INTEGER;
        const dist = new Array(n).fill(INF);
        dist[start] = 0;
        const heap = new MinHeap();
        heap.push([0, start]);
        while (!heap.isEmpty()) {
            const [d, u] = heap.pop();
            if (d !== dist[u]) continue;
            for (const [v, w] of graph[u]) {
                const nd = d + w;
                if (nd < dist[v]) { dist[v] = nd; heap.push([nd, v]); }
            }
        }
        return dist;
    }

    const dist1 = dijkstra(src1, adj);
    const dist2 = dijkstra(src2, adj);
    const distDest = dijkstra(dest, rev);

    let ans = Number.MAX_SAFE_INTEGER;
    for (let v = 0; v < n; ++v) {
        const total = dist1[v] + dist2[v] + distDest[v];
        if (total < ans) ans = total;
    }
    return ans === Number.MAX_SAFE_INTEGER ? -1 : ans;
}

function minOperations(nums) {
    // ---------- max‑heap implementation ----------
    function MaxHeap(arr) {
        this.heap = arr.slice();               // copy
        this.size = this.heap.length;
        // heapify
        for (let i = Math.floor(this.size / 2) - 1; i >= 0; i--) this.bubbleDown(i);
    }
    MaxHeap.prototype.bubbleUp = function (idx) {
        while (idx > 0) {
            const parent = (idx - 1) >> 1;
            if (this.heap[parent] >= this.heap[idx]) break;
            [this.heap[parent], this.heap[idx]] = [this.heap[idx], this.heap[parent]];
            idx = parent;
        }
    };
    MaxHeap.prototype.bubbleDown = function (idx) {
        const n = this.size;
        while (true) {
            let largest = idx;
            const left = idx * 2 + 1;
            const right = left + 1;
            if (left < n && this.heap[left] > this.heap[largest]) largest = left;
            if (right < n && this.heap[right] > this.heap[largest]) largest = right;
            if (largest === idx) break;
            [this.heap[largest], this.heap[idx]] = [this.heap[idx], this.heap[largest]];
            idx = largest;
        }
    };
    MaxHeap.prototype.pop = function () {
        const top = this.heap[0];
        const last = this.heap[--this.size];
        if (this.size > 0) {
            this.heap[0] = last;
            this.bubbleDown(0);
        }
        this.heap.pop(); // shrink array
        return top;
    };
    MaxHeap.prototype.push = function (val) {
        this.heap[this.size++] = val;
        this.bubbleUp(this.size - 1);
    };
    // ------------------------------------------------

    let total = 0;
    for (const v of nums) total += v;
    const target = total / 2;          // needed reduction
    let reduced = 0;
    const heap = new MaxHeap(nums.map(v => v * 1.0)); // store as doubles
    let ops = 0;

    while (reduced < target) {         // main loop
        const maxVal = heap.pop();     // largest element
        const half = maxVal / 2;
        reduced += half;               // reduction gained this step
        heap.push(half);               // new value can be used later
        ops++;
    }
    return ops;
}

function maximizeNumberOfSubsequencesInAString(text, pattern) {
    const a = pattern[0], b = pattern[1];
    let seenA = 0, baseline = 0, countA = 0, countB = 0;
    for (const ch of text) {
        if (ch === a) { seenA++; countA++; }
        if (ch === b) { baseline += seenA; countB++; }
    }
    if (a === b) return baseline + countA;
    return baseline + Math.max(countA, countB);
}

function minimumWhiteTiles(floor, numCarpets, carpetLen) {
    const n = floor.length;
    const pref = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++)               // build prefix sum of white tiles
        pref[i + 1] = pref[i] + (floor[i] === '1' ? 1 : 0);

    // dpPrev holds dp for k‑1 carpets; initialise for k = 0 (no carpet)
    let dpPrev = pref.slice();                // dpPrev[i] = pref[i]

    for (let k = 1; k <= numCarpets; k++) {
        const dpCurr = new Array(n + 1).fill(0);
        dpCurr[0] = 0;                         // empty prefix needs no white tiles
        for (let i = 1; i <= n; i++) {
            const notCover = dpCurr[i - 1] + (floor[i - 1] === '1' ? 1 : 0);
            const j = i - carpetLen >= 0 ? i - carpetLen : 0;
            const cover = dpPrev[j];           // carpet hides all whites in [j, i)
            dpCurr[i] = Math.min(notCover, cover);
        }
        dpPrev = dpCurr;                       // roll to next carpet count
    }
    return dpPrev[n];
}

function divideArray(nums) {
  const freq = new Map();                     // count occurrences
  for (const v of nums) {                     // O(n)
    freq.set(v, (freq.get(v) || 0) + 1);
  }
  for (const cnt of freq.values()) {          // O(k)
    if (cnt % 2 !== 0) return false;          // any odd count makes pairing impossible
  }
  return true;
}

function countHillValley(nums) {
    if (nums.length < 3) return 0;                     // no possible hill/valley

    // compress consecutive equal values
    const comp = [];
    for (let v of nums) {
        if (comp.length === 0 || comp[comp.length - 1] !== v) comp.push(v);
    }

    let ans = 0;
    // check each interior element of the compressed array
    for (let i = 1; i < comp.length - 1; ++i) {
        if (comp[i] > comp[i - 1] && comp[i] > comp[i + 1]) ans++;   // hill
        else if (comp[i] < comp[i - 1] && comp[i] < comp[i + 1]) ans++; // valley
    }
    return ans;
}

function maximumBobArrows(numArrows, aliceArrows) {
    const n = 12;
    let bestScore = -1;
    let bestMask = 0;

    // enumerate all subsets (bitmask) to find best score
    for (let mask = 0; mask < (1 << n); mask++) {
        let arrowsNeeded = 0;
        let score = 0;
        for (let i = 0; i < n; i++) {
            if (mask & (1 << i)) {
                arrowsNeeded += aliceArrows[i] + 1; // need one more than Alice
                score += i;                         // points earned for this section
            }
        }
        if (arrowsNeeded > numArrows) continue;   // cannot afford this subset
        if (score > bestScore) {
            bestScore = score;
            bestMask = mask;
        }
    }

    // build Bob's arrow distribution based on bestMask
    const bobArrows = new Array(n).fill(0);
    let used = 0;
    for (let i = 0; i < n; i++) {
        if (bestMask & (1 << i)) {
            bobArrows[i] = aliceArrows[i] + 1;
            used += bobArrows[i];
        }
    }
    // put any remaining arrows into section 0 (any section works)
    bobArrows[0] += numArrows - used;
    return bobArrows;
}

