function countCollisions(directions) {
    const n = directions.length;
    let left = 0;
    while (left < n && directions[left] === 'L') left++;   // discard left‑moving cars at the left edge
    let right = n - 1;
    while (right >= 0 && directions[right] === 'R') right--; // discard right‑moving cars at the right edge

    let collisions = 0;
    for (let k = left; k <= right; k++) {
        if (directions[k] !== 'S') collisions++;           // each moving car in the remaining segment will collide once
    }
    return collisions;
}

function longestRepeatingSubstring(s, queryCharacters, queryIndices) {
    const n = s.length;
    const size = 4 * n;                     // segment‑tree array
    const tree = new Array(size);

    // build leaf node
    function makeNode(ch) {
        return {
            len: 1,
            leftChar: ch,
            leftLen: 1,
            rightChar: ch,
            rightLen: 1,
            best: 1
        };
    }

    // merge two child nodes
    function merge(a, b) {
        const node = {
            len: a.len + b.len,
            leftChar: a.leftChar,
            leftLen: a.leftLen,
            rightChar: b.rightChar,
            rightLen: b.rightLen,
            best: Math.max(a.best, b.best)
        };

        if (a.rightChar === b.leftChar) {
            const cross = a.rightLen + b.leftLen;
            if (cross > node.best) node.best = cross;
        }

        // longest prefix
        if (a.leftLen === a.len && a.rightChar === b.leftChar) {
            node.leftLen = a.len + b.leftLen;
        }

        // longest suffix
        if (b.rightLen === b.len && a.rightChar === b.leftChar) {
            node.rightLen = b.len + a.rightLen;
        }

        return node;
    }

    // build tree recursively
    function build(idx, l, r) {
        if (l === r) {
            tree[idx] = makeNode(s[l]);
            return;
        }
        const mid = (l + r) >> 1;
        build(idx << 1, l, mid);
        build(idx << 1 | 1, mid + 1, r);
        tree[idx] = merge(tree[idx << 1], tree[idx << 1 | 1]);
    }

    // point update
    function update(idx, l, r, pos, ch) {
        if (l === r) {
            tree[idx] = makeNode(ch);
            return;
        }
        const mid = (l + r) >> 1;
        if (pos <= mid) update(idx << 1, l, mid, pos, ch);
        else update(idx << 1 | 1, mid + 1, r, pos, ch);
        tree[idx] = merge(tree[idx << 1], tree[idx << 1 | 1]);
    }

    build(1, 0, n - 1);
    const ans = [];

    for (let i = 0; i < queryIndices.length; ++i) {
        const pos = queryIndices[i];
        const ch = queryCharacters[i];
        if (s[pos] !== ch) {                 // avoid unnecessary work
            s = s.substring(0, pos) + ch + s.substring(pos + 1);
            update(1, 0, n - 1, pos, ch);
        }
        ans.push(tree[1].best);               // longest run after this query
    }
    return ans;
}



