function findDifference(nums1, nums2) {
    const set1 = new Set(nums1);               // build hash set for nums1
    const set2 = new Set(nums2);               // build hash set for nums2
    const onlyInFirst = [];
    const onlyInSecond = [];

    for (const v of set1) {                    // elements only in nums1
        if (!set2.has(v)) onlyInFirst.push(v);
    }

    for (const v of set2) {                    // elements only in nums2
        if (!set1.has(v)) onlyInSecond.push(v);
    }

    return [onlyInFirst, onlyInSecond];
}

var minDeletion = function(nums) {
    let pairs = 0, waiting = false, first = 0;
    for (const x of nums) {
        if (!waiting) { first = x; waiting = true; }
        else {
            if (x > first) { pairs++; waiting = false; }
            else { first = x; }
        }
    }
    return nums.length - 2*pairs;
};

function maxValueOfCoins(piles, k) {
    // dp[j] = best value using processed piles and taking exactly j coins
    const dp = new Array(k + 1).fill(0);

    for (let pileIdx = 0; pileIdx < piles.length; pileIdx++) {
        const pile = piles[pileIdx];
        const maxTake = Math.min(pile.length, k);

        // prefix sums of the current pile
        const pref = new Array(maxTake + 1).fill(0);
        for (let t = 1; t <= maxTake; t++) {
            pref[t] = pref[t - 1] + pile[t - 1];
        }

        const next = dp.slice();                     // copy current dp
        // MAIN LOGIC: try every possible number of taken coins from this pile
        for (let j = 0; j <= k; j++) {
            for (let t = 1; t <= Math.min(maxTake, j); t++) {
                const candidate = dp[j - t] + pref[t];
                if (candidate > next[j]) next[j] = candidate;
            }
        }
        // replace dp with the updated values for the next iteration
        for (let j = 0; j <= k; j++) dp[j] = next[j];
    }

    return dp[k];
}



