function findPalindromes(queries, intLength) {
    const halfLen = Math.ceil(intLength / 2);                     // length of the defining half
    const start = Math.pow(10, halfLen - 1);                      // smallest possible half (no leading zero)
    const maxCount = 9 * Math.pow(10, halfLen - 1);               // total palindromes of this length
    const res = [];

    for (let i = 0; i < queries.length; i++) {
        const k = queries[i];
        if (k > maxCount) {                                        // query exceeds available palindromes
            res.push(-1);
            continue;
        }
        const halfNum = start + k - 1;                             // k‑th half value
        const halfStr = String(halfNum);
        const rev = halfStr.split('').reverse().join('');         // reverse of the half
        const palStr = intLength % 2 === 0
            ? halfStr + rev                                          // even length: mirror whole half
            : halfStr + rev.slice(1);                               // odd length: skip middle digit when mirroring
        res.push(Number(palStr));                                  // convert to number (fits into JS safe integer)
    }
    return res;
}

function numberOfWays(s) {
  const n = s.length;
  const prefix0 = new Array(n).fill(0), prefix1 = new Array(n).fill(0);
  for (let i = 0; i < n; i++) {
    prefix0[i] = (i>0?prefix0[i-1]:0) + (s[i]==='0'?1:0);
    prefix1[i] = (i>0?prefix1[i-1]:0) + (s[i]==='1'?1:0);
  }
  const total0 = prefix0[n-1], total1 = prefix1[n-1];
  let ways = 0n;
  for (let j = 0; j < n; j++) {
    const before0 = j>0?prefix0[j-1]:0, before1 = j>0?prefix1[j-1]:0;
    const after0 = total0 - prefix0[j], after1 = total1 - prefix1[j];
    if (s[j] === '1') ways += BigInt(before0) * BigInt(after0);
    else ways += BigInt(before1) * BigInt(after1);
  }
  return Number(ways);
}

function minBitFlips(start, goal) {
    // XOR reveals differing bits; count the set bits
    let xor = start ^ goal;
    let flips = 0;
    while (xor) {          // remove the lowest set bit each iteration
        flips++;
        xor &= xor - 1;
    }
    return flips;
}

function triangularSum(nums) {
    let arr = nums.slice();
    while (arr.length > 1) {
        const next = [];
        for (let i = 0; i < arr.length-1; i++) next.push((arr[i]+arr[i+1]) % 10);
        arr = next;
    }
    return arr[0];
}

function minOperations(current, correct) {
    // parse "HH:MM" → total minutes
    const cur = parseInt(current.slice(0, 2)) * 60 + parseInt(current.slice(3));
    const cor = parseInt(correct.slice(0, 2)) * 60 + parseInt(correct.slice(3));

    let diff = cor - cur;               // minutes we need to add
    let ops = 0;

    // greedy use of the largest possible increments
    ops += Math.floor(diff / 60); diff %= 60;   // 60‑minute steps
    ops += Math.floor(diff / 15); diff %= 15;   // 15‑minute steps
    ops += Math.floor(diff / 5);  diff %= 5;    // 5‑minute steps
    ops += diff;                               // remaining 1‑minute steps

    return ops;
}

function findWinners(matches) {
    const lossCount = {};          // map player -> number of losses
    const players = new Set();     // all distinct players

    // main logic: count losses and collect all players
    for (let i = 0; i < matches.length; i++) {
        const [winner, loser] = matches[i];
        players.add(winner);
        players.add(loser);
        lossCount[loser] = (lossCount[loser] || 0) + 1;
    }

    const zeroLosses = [];
    const oneLoss = [];

    // separate players based on loss count
    for (const p of players) {
        const cnt = lossCount[p];
        if (cnt === undefined) zeroLosses.push(p);
        else if (cnt === 1) oneLoss.push(p);
    }

    zeroLosses.sort((a, b) => a - b); // required increasing order
    oneLoss.sort((a, b) => a - b);

    return [zeroLosses, oneLoss];
}

function maximumCandies(candies, k) {
    // edge case: no children
    if (k === 0) return 0;

    let low = 1;
    let high = 0;
    for (let v of candies) if (v > high) high = v;   // find max pile size

    let best = 0;
    // binary search on the answer
    while (low <= high) {
        const mid = Math.floor((low + high) / 2);
        let pieces = 0;
        for (let v of candies) pieces += Math.floor(v / mid);
        if (pieces >= k) {          // feasible → try larger value
            best = mid;
            low = mid + 1;
        } else {                    // not feasible → try smaller value
            high = mid - 1;
        }
    }
    return best;
}

function sumScores(s) {
    const n = s.length;
    const Z = new Array(n).fill(0);
    Z[0] = n;                                   // whole string matches itself

    let l = 0, r = 0;                           // current Z-box [l, r]

    for (let i = 1; i < n; i++) {
        if (i <= r) {
            Z[i] = Math.min(r - i + 1, Z[i - l]); // reuse previous value
        }
        while (i + Z[i] < n && s[Z[i]] === s[i + Z[i]]) {
            Z[i]++;                               // extend the match
        }
        if (i + Z[i] - 1 > r) {
            l = i;
            r = i + Z[i] - 1;                     // update Z-box
        }
    }

    let total = 0;
    for (const v of Z) total += v;               // sum of all scores
    return total;
}

function Encrypter(keys, values, dictionary) {
    var charToVal = {};
    for (var i = 0; i < keys.length; i++) {
        charToVal[keys[i]] = values[i];
    }

    var encCount = {};
    for (var i = 0; i < dictionary.length; i++) {
        var word = dictionary[i];
        var enc = "";
        var ok = true;
        for (var j = 0; j < word.length; j++) {
            var v = charToVal[word[j]];
            if (v === undefined) { ok = false; break; }
            enc += v;
        }
        if (ok) {
            encCount[enc] = (encCount[enc] || 0) + 1;
        }
    }

    return {
        encrypt: function(word) {
            var enc = "";
            for (var i = 0; i < word.length; i++) {
                var v = charToVal[word[i]];
                if (v === undefined) return "";
                enc += v;
            }
            return enc;
        },
        decrypt: function(encryptedWord) {
            return encCount[encryptedWord] || 0;
        }
    };
}

function largestNumberAfterParitySwaps(num) {
    const s = String(num);
    const evenCnt = Array(10).fill(0);
    const oddCnt = Array(10).fill(0);
    for (let i = 0; i < s.length; i++) {
        const d = s.charCodeAt(i) - 48;
        if ((d & 1) === 0) evenCnt[d]++; else oddCnt[d]++;
    }
    let evenPtr = 8, oddPtr = 9;
    const res = [];
    for (let i = 0; i < s.length; i++) {
        const d = s.charCodeAt(i) - 48;
        if ((d & 1) === 0) {
            while (evenPtr >= 0 && evenCnt[evenPtr] === 0) evenPtr -= 2;
            res.push(String.fromCharCode(evenPtr + 48));
            evenCnt[evenPtr]--;
        } else {
            while (oddPtr >= 1 && oddCnt[oddPtr] === 0) oddPtr -= 2;
            res.push(String.fromCharCode(oddPtr + 48));
            oddCnt[oddPtr]--;
        }
    }
    return Number(res.join('')); // convert back to a number - the expected return type
}

var maximumProduct = function(nums, k) {
    const MOD = 1000000007;
    const n = nums.length;
    if (n === 0) return 0;
    nums = nums.slice().sort((a,b)=>a-b);
    let cur = nums[0];
    let i = 0;
    while (i < n-1) {
        const diff = nums[i+1] - cur;
        if (diff === 0) { i++; continue; }
        const need = diff*(i+1);
        if (k >= need) {
            cur = nums[i+1];
            k -= need;
            i++;
        } else {
            const inc = Math.floor(k/(i+1));
            cur += inc;
            k -= inc*(i+1);
            const remainder = k;
            let prod = 1;
            for (let idx=0; idx<=i; idx++) {
                const val = cur + (idx < remainder ? 1 : 0);
                prod = (prod * (val % MOD)) % MOD;
            }
            for (let idx=i+1; idx<n; idx++) {
                prod = (prod * (nums[idx] % MOD)) % MOD;
            }
            return prod;
        }
    }
    const inc = Math.floor(k/n);
    cur += inc;
    const remainder = k % n;
    let prod = 1;
    for (let idx=0; idx<n; idx++) {
        const val = cur + (idx < remainder ? 1 : 0);
        prod = (prod*(val % MOD)) % MOD;
    }
    return prod;
};

function minimizeResultByAddingParenthesesToExpression(expression) {
    const plusIdx = expression.indexOf('+');
    const left = expression.slice(0, plusIdx);
    const right = expression.slice(plusIdx + 1);

    let bestVal = null;
    let bestExpr = "";

    for (let i = 0; i < left.length; i++) {
        const leftOutStr = left.slice(0, i);
        const insideLeftStr = left.slice(i);
        const leftOut = leftOutStr ? parseInt(leftOutStr, 10) : 1;

        for (let j = 1; j <= right.length; j++) {
            const insideRightStr = right.slice(0, j);
            const rightOutStr = right.slice(j);
            const insideRight = parseInt(insideRightStr, 10);
            const rightOut = rightOutStr ? parseInt(rightOutStr, 10) : 1;

            const val = leftOut * (parseInt(insideLeftStr, 10) + insideRight) * rightOut;
            if (bestVal === null || val < bestVal) {
                bestVal = val;
                bestExpr = leftOutStr + '(' + insideLeftStr + '+' + insideRightStr + ')' + rightOutStr;
            }
        }
    }
    return bestExpr;
}

function maximumTotalBeautyOfTheGardens(flowers, newFlowers, target, full, partial) {
    const n = flowers.length;
    flowers = [...flowers].sort((a, b) => a - b);
    const prefix = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) prefix[i + 1] = prefix[i] + flowers[i];

    const suffixNeed = new Array(n + 1).fill(0);
    for (let k = 1; k <= n; k++) {
        const idx = n - k;
        const need = Math.max(0, target - flowers[idx]);
        suffixNeed[k] = suffixNeed[k - 1] + need;
    }

    const bisectLeft = (arr, val, hiLimit) => {
        let lo = 0, hi = hiLimit;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (arr[mid] < val) lo = mid + 1; else hi = mid;
        }
        return lo;
    };

    let ans = 0;
    for (let k = 0; k <= n; k++) {
        const costFull = suffixNeed[k];
        if (costFull > newFlowers) break;
        const remaining = newFlowers - costFull;
        const m = n - k;
        if (m === 0) {
            ans = Math.max(ans, full * n);
            continue;
        }
        let low = 0, high = target - 1, best = 0;
        while (low <= high) {
            const mid = Math.floor((low + high) / 2);
            const pos = bisectLeft(flowers, mid, m);
            const cost = mid * pos - prefix[pos];
            if (cost <= remaining) { best = mid; low = mid + 1; }
            else high = mid - 1;
        }
        ans = Math.max(ans, full * k + partial * best);
    }
    return ans;
}

function addTwoIntegers(num1, num2) {
    // return the sum of the two integers
    return num1 + num2;
}

function rootEqualsSumChildren(root) {
    // compare root value with sum of its two children
    return root.val === root.left.val + root.right.val;
}

function closestToZero(nums) {
  let best = nums[0];                         // start with first element as candidate
  for (let i = 1; i < nums.length; i++) {
    const cur = nums[i];
    // update if cur is closer to 0, or equally close but larger
    if (Math.abs(cur) < Math.abs(best) || (Math.abs(cur) === Math.abs(best) && cur > best)) {
      best = cur;
    }
  }
  return best;
}

function waysToBuyPensPencils(total, cost1, cost2) {
    let ways = 0n;
    const T = BigInt(total), C1 = BigInt(cost1), C2 = BigInt(cost2);
    let p = 0n;
    while (p * C1 <= T) {
        const remaining = T - p * C1;
        ways += remaining / C2 + 1n;
        p++;
    }
    return Number(ways);
}

function ATM() {
    const values = [20, 50, 100, 200, 500];   // fixed denominations
    const stock = [0, 0, 0, 0, 0];            // current notes in the machine

    return {
        deposit: function (banknotes) {
            for (let i = 0; i < 5; i++) stock[i] += banknotes[i];
        },

        withdraw: function (amount) {
            const used = [0, 0, 0, 0, 0];

            for (let i = 4; i >= 0; i--) {
                const maxTake = Math.min(Math.floor(amount / values[i]), stock[i]);
                if (maxTake > 0) {
                    used[i] = maxTake;
                    amount -= maxTake * values[i];
                }
            }

            if (amount !== 0) return [-1];

            for (let i = 0; i < 5; i++) stock[i] -= used[i];
            return used;
        }
    };
}

function maximumScoreOfANodeSequence(scores, edges) {
    const n = scores.length;
    const adj = Array.from({length: n}, () => []);
    for (const [u, v] of edges) { adj[u].push(v); adj[v].push(u); }

    const topNeighbors = Array.from({length: n}, () => []);
    for (let i = 0; i < n; i++) {
        if (adj[i].length) {
            const neigh = [...adj[i]].sort((a, b) => scores[b] - scores[a]);
            topNeighbors[i] = neigh.slice(0, 3);
        }
    }

    let best = -1;
    for (const [b, c] of edges) {
        const candA = topNeighbors[b].filter(nbr => nbr !== c);
        const candD = topNeighbors[c].filter(nbr => nbr !== b);
        if (!candA.length || !candD.length) continue;
        for (const a of candA) {
            for (const d of candD) {
                if (a === d) continue;
                const total = scores[a] + scores[b] + scores[c] + scores[d];
                if (total > best) best = total;
            }
        }
    }
    return best;
}

function minimumRounds(tasks) {
    const freq = {};                     // count each difficulty
    for (let i = 0; i < tasks.length; i++) {
        const d = tasks[i];
        freq[d] = (freq[d] || 0) + 1;
    }

    let rounds = 0;
    for (const key in freq) {
        const cnt = freq[key];
        if (cnt === 1) return -1;        // impossible to finish a single task
        // use as many groups of 3 as possible, add one extra group if remainder exists
        rounds += Math.floor(cnt / 3) + (cnt % 3 === 0 ? 0 : 1);
    }
    return rounds;
}

function digitSumString(s, k) {
    while (s.length > k) {                     // repeat until length ≤ k
        let next = '';
        for (let i = 0; i < s.length; i += k) {   // process blocks of size k
            let sum = 0;
            const end = Math.min(i + k, s.length);
            for (let j = i; j < end; ++j) {        // sum digits of the block
                sum += s.charCodeAt(j) - 48;       // '0' → 48
            }
            next += sum.toString();                // replace block by its sum
        }
        s = next;                                   // prepare for next round
    }
    return s;
}

function maximumTrailingZerosInACorneredPath(grid) {
    const m = grid.length, n = grid[0].length;
    const cnt2 = Array.from({length: m}, () => new Array(n).fill(0));
    const cnt5 = Array.from({length: m}, () => new Array(n).fill(0));

    const factorCounts = (x) => {
        let c2 = 0, c5 = 0;
        while (x % 2 === 0) { c2++; x = Math.floor(x / 2); }
        while (x % 5 === 0) { c5++; x = Math.floor(x / 5); }
        return [c2, c5];
    };

    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            const [c2, c5] = factorCounts(grid[i][j]);
            cnt2[i][j] = c2;
            cnt5[i][j] = c5;
        }
    }

    const rowPre2 = Array.from({length: m}, () => new Array(n + 1).fill(0));
    const rowPre5 = Array.from({length: m}, () => new Array(n + 1).fill(0));
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            rowPre2[i][j + 1] = rowPre2[i][j] + cnt2[i][j];
            rowPre5[i][j + 1] = rowPre5[i][j] + cnt5[i][j];
        }
    }

    const colPre2 = Array.from({length: m + 1}, () => new Array(n).fill(0));
    const colPre5 = Array.from({length: m + 1}, () => new Array(n).fill(0));
    for (let j = 0; j < n; j++) {
        for (let i = 0; i < m; i++) {
            colPre2[i + 1][j] = colPre2[i][j] + cnt2[i][j];
            colPre5[i + 1][j] = colPre5[i][j] + cnt5[i][j];
        }
    }

    let ans = 0;
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            const cell2 = cnt2[i][j], cell5 = cnt5[i][j];
            const up2 = colPre2[i + 1][j], up5 = colPre5[i + 1][j];
            const down2 = colPre2[m][j] - colPre2[i][j], down5 = colPre5[m][j] - colPre5[i][j];
            const left2 = rowPre2[i][j + 1], left5 = rowPre5[i][j + 1];
            const right2 = rowPre2[i][n] - rowPre2[i][j], right5 = rowPre5[i][n] - rowPre5[i][j];

            let t2 = up2 + down2 - cell2, t5 = up5 + down5 - cell5;
            ans = Math.max(ans, Math.min(t2, t5));
            t2 = left2 + right2 - cell2; t5 = left5 + right5 - cell5;
            ans = Math.max(ans, Math.min(t2, t5));
            t2 = up2 + left2 - cell2; t5 = up5 + left5 - cell5;
            ans = Math.max(ans, Math.min(t2, t5));
            t2 = up2 + right2 - cell2; t5 = up5 + right5 - cell5;
            ans = Math.max(ans, Math.min(t2, t5));
            t2 = down2 + left2 - cell2; t5 = down5 + left5 - cell5;
            ans = Math.max(ans, Math.min(t2, t5));
            t2 = down2 + right2 - cell2; t5 = down5 + right5 - cell5;
            ans = Math.max(ans, Math.min(t2, t5));
        }
    }
    return ans;
}

function intersectionMultiple(nums) {
    if (!Array.isArray(nums) || nums.length === 0) return [];

    const arrayCount = nums.length;               // total number of inner arrays
    const freq = new Map();                       // element -> how many arrays contain it

    for (let i = 0; i < arrayCount; i++) {
        const uniqueInCurrent = new Set(nums[i]); // deduplicate current array
        // count each distinct element once per array
        for (const val of uniqueInCurrent) {
            freq.set(val, (freq.get(val) || 0) + 1);
        }
    }

    const result = [];                             // collect elements present in all arrays
    for (const [val, cnt] of freq.entries()) {
        if (cnt === arrayCount) result.push(val);
    }

    result.sort((a, b) => a - b);                  // optional: return sorted order
    return result;
}

function countRectangles(rectangles, points) {
    // sort rectangles by length descending
    rectangles.sort((a, b) => b[0] - a[0]);

    // keep points with original index and sort by x descending
    const pts = points.map((p, i) => [p[0], p[1], i]);
    pts.sort((a, b) => b[0] - a[0]);

    // coordinate‑compress all heights (rectangles + points)
    const allHeights = [];
    for (const [, h] of rectangles) allHeights.push(h);
    for (const [, y] of points) allHeights.push(y);
    const uniq = Array.from(new Set(allHeights)).sort((a, b) => a - b);
    const idx = new Map();
    uniq.forEach((v, i) => idx.set(v, i + 1));          // 1‑based indices
    const size = uniq.length;

    // Fenwick Tree
    const bit = new Array(size + 2).fill(0);
    const add = (i, delta) => { for (let x = i; x <= size; x += x & -x) bit[x] += delta; };
    const sum = (i) => { let s = 0; for (let x = i; x > 0; x -= x & -x) s += bit[x]; return s; };

    const ans = new Array(points.length);
    let r = 0;                       // index in rectangles

    for (const [x, y, orig] of pts) {
        // insert every rectangle whose length ≥ current point's x
        while (r < rectangles.length && rectangles[r][0] >= x) {
            add(idx.get(rectangles[r][1]), 1);
            r++;
        }
        const total = r;                                 // rectangles inserted so far
        const belowY = sum(idx.get(y) - 1);              // heights < y
        ans[orig] = total - belowY;                      // heights ≥ y
    }
    return ans;
}



