function longestPath(parent, s) {
    const n = parent.length;
    const children = Array.from({length:n}, () => []);
    for (let i = 1; i < n; i++) children[parent[i]].push(i);
    let best = 1;
    function dfs(u) {
        let top1 = 0, top2 = 0;
        for (const c of children[u]) {
            const clen = dfs(c);
            if (s[c] === s[u]) continue;
            if (clen > top1) { top2 = top1; top1 = clen; }
            else if (clen > top2) top2 = clen;
        }
        best = Math.max(best, top1 + top2 + 1);
        return top1 + 1;
    }
    dfs(0);
    return best;
}

function countLatticePoints(circles) {
    const visited = new Set();                     // store unique points
    for (let i = 0; i < circles.length; i++) {    // iterate over each circle
        const [cx, cy, r] = circles[i];
        const r2 = r * r;
        for (let x = cx - r; x <= cx + r; x++) {  // enumerate possible x
            const dx = x - cx;
            const maxDy = Math.floor(Math.sqrt(r2 - dx * dx));
            for (let y = cy - maxDy; y <= cy + maxDy; y++) { // enumerate y
                visited.add(x + ',' + y);          // add point to set
            }
        }
    }
    return visited.size;
}

function fullBloomFlowers(flowers, people) {
    const starts = [];
    const ends = [];

    for (let i = 0; i < flowers.length; i++) {
        starts.push(flowers[i][0]);   // collect start times
        ends.push(flowers[i][1]);     // collect end times
    }

    starts.sort((a, b) => a - b);      // sort ascending
    ends.sort((a, b) => a - b);        // sort ascending

    const ans = new Array(people.length);

    for (let i = 0; i < people.length; i++) {
        const t = people[i];
        const started = upperBound(starts, t);   // count of starts ≤ t
        const ended   = lowerBound(ends, t);     // count of ends < t
        ans[i] = started - ended;                // blooming flowers at t
    }

    return ans;
}

/* binary search: first index with value > target */
function upperBound(arr, target) {
    let lo = 0, hi = arr.length;
    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (arr[mid] <= target) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

/* binary search: first index with value >= target */
function lowerBound(arr, target) {
    let lo = 0, hi = arr.length;
    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (arr[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}


// TIME: O((f + p) log f) SPACE: O(f)

function minimumAverageDifference(nums) {
    const n = nums.length;
    let totalSum = 0;
    for (let v of nums) totalSum += v;               // total sum of the array

    let prefixSum = 0;
    let bestIdx = 0;
    let bestDiff = Number.MAX_SAFE_INTEGER;

    for (let i = 0; i < n; i++) {
        prefixSum += nums[i];                         // update prefix sum
        const leftAvg = Math.floor(prefixSum / (i + 1));

        const rightCount = n - i - 1;
        const rightAvg = rightCount > 0
            ? Math.floor((totalSum - prefixSum) / rightCount)
            : 0;                                      // empty suffix

        const diff = Math.abs(leftAvg - rightAvg);
        if (diff < bestDiff) {                        // keep smallest diff & index
            bestDiff = diff;
            bestIdx = i;
        }
    }
    return bestIdx;
}

function countPrefixes(words, s) {
    let count = 0;
    for (let i = 0; i < words.length; i++) {
        // check if each word is a prefix of s
        if (s.startsWith(words[i])) {
            count++;
        }
    }
    return count;
}

var countUnguarded = function(m, n, guards, walls) {
    const GUARD=1, WALL=2, GUARDED=3;
    const grid = Array.from({length:m}, () => new Array(n).fill(0));
    for (const [r,c] of guards) grid[r][c] = GUARD;
    for (const [r,c] of walls) grid[r][c] = WALL;
    const directions = [[-1,0],[1,0],[0,-1],[0,1]];
    for (const [gr,gc] of guards) {
        for (const [dr,dc] of directions) {
            let r = gr+dr, c = gc+dc;
            while (r>=0 && r<m && c>=0 && c<n && grid[r][c]!==WALL && grid[r][c]!==GUARD) {
                if (grid[r][c]===0) grid[r][c] = GUARDED;
                r += dr; c += dc;
            }
        }
    }
    let unguarded = 0;
    for (const row of grid) for (const cell of row) if (cell===0) unguarded++;
    return unguarded;
};

function maximumMinutes(grid) {
  const m = grid.length, n = grid[0].length;
  const INF = Infinity;
  const dirs = [[1,0],[-1,0],[0,1],[0,-1]];

  // BFS from all fire cells
  function bfs(sources) {
    const dist = Array.from({length: m}, () => new Array(n).fill(INF));
    const q = [];
    for (const [r,c] of sources) { dist[r][c] = 0; q.push([r,c]); }
    let head = 0;
    while (head < q.length) {
      const [r,c] = q[head++];
      for (const [dr,dc] of dirs) {
        const nr = r+dr, nc = c+dc;
        if (nr<0||nr>=m||nc<0||nc>=n) continue;
        if (grid[nr][nc] === 2) continue; // wall
        if (dist[nr][nc] !== INF) continue;
        dist[nr][nc] = dist[r][c] + 1;
        q.push([nr,nc]);
      }
    }
    return dist;
  }

  const fireSources = [];
  for (let r=0;r<m;r++) for (let c=0;c<n;c++) if (grid[r][c]===1) fireSources.push([r,c]);
  const fireDist = bfs(fireSources);
  const personDist = bfs([[0,0]]);

  const destFire = fireDist[m-1][n-1];
  const destPerson = personDist[m-1][n-1];

  if (destPerson === INF) return -1; // can't reach at all
  if (destFire === INF) return 1000000000; // fire never reaches destination

  // feasibility check for waiting time t
  function feasible(t) {
    // person can wait t minutes then move; fire spreads simultaneously with person's moves.
    // BFS for person where person's arrival time to (r,c) is personDist[r][c] + t (if not INF)
    // must have: personArrival < fireDist at every step along the path, with special handling at destination (== is safe there)
    const dist = Array.from({length: m}, () => new Array(n).fill(INF));
    if (t < 0) return false;
    // check start cell isn't already on fire at time t (if fire reaches (0,0) at or before t, can't even wait there safely... actually if fireDist[0][0] <= t, start burns before/at move time)
    if (fireDist[0][0] <= t) return false;
    dist[0][0] = t;
    const q = [[0,0]];
    let head = 0;
    while (head < q.length) {
      const [r,c] = q[head++];
      for (const [dr,dc] of dirs) {
        const nr = r+dr, nc = c+dc;
        if (nr<0||nr>=m||nc<0||nc>=n) continue;
        if (grid[nr][nc] === 2) continue;
        if (dist[nr][nc] !== INF) continue;
        const arrival = dist[r][c] + 1;
        const isDest = (nr===m-1 && nc===n-1);
        if (isDest) {
          if (arrival > fireDist[nr][nc]) continue; // fire strictly before person -> blocked; equal is OK at destination
        } else {
          if (arrival >= fireDist[nr][nc]) continue; // fire arrives same time or before -> blocked elsewhere
        }
        dist[nr][nc] = arrival;
        q.push([nr,nc]);
      }
    }
    return dist[m-1][n-1] !== INF;
  }

  let lo = 0, hi = 1000000000;
  if (!feasible(0)) return -1;
  while (lo < hi) {
    const mid = lo + Math.ceil((hi-lo)/2);
    if (feasible(mid)) lo = mid; else hi = mid - 1;
  }
  return lo;
}

function removeDigit(number, digit) {
    const n = number.length;
    // find the first digit that is smaller than its next character
    for (let i = 0; i < n - 1; i++) {
        if (number[i] === digit && number[i] < number[i + 1]) {
            return number.slice(0, i) + number.slice(i + 1);
        }
    }
    // no such position → remove the last occurrence of digit
    const last = number.lastIndexOf(digit);
    return number.slice(0, last) + number.slice(last + 1);
}

function countDistinctSubarrays(nums, k, p) {
    const n = nums.length;
    const MOD1 = 1000000007n;
    const MOD2 = 1000000009n;
    const BASE = 91138233n;

    const pref1 = new Array(n + 1).fill(0n);
    const pref2 = new Array(n + 1).fill(0n);
    const pow1 = new Array(n + 1).fill(1n);
    const pow2 = new Array(n + 1).fill(1n);
    for (let i = 0; i < n; ++i) {
        pref1[i + 1] = (pref1[i] * BASE + BigInt(nums[i])) % MOD1;
        pref2[i + 1] = (pref2[i] * BASE + BigInt(nums[i])) % MOD2;
        pow1[i + 1] = (pow1[i] * BASE) % MOD1;
        pow2[i + 1] = (pow2[i] * BASE) % MOD2;
    }

    const seen = new Set();
    for (let i = 0; i < n; ++i) {
        let divCnt = 0;
        for (let j = i; j < n; ++j) {
            if (nums[j] % p === 0) ++divCnt;
            if (divCnt > k) break;
            const len = j - i + 1;
            let h1 = (pref1[j + 1] - pref1[i] * pow1[len]) % MOD1;
            let h2 = (pref2[j + 1] - pref2[i] * pow2[len]) % MOD2;
            if (h1 < 0n) h1 += MOD1;
            if (h2 < 0n) h2 += MOD2;
            seen.add(h1 + ',' + h2);
        }
    }
    return seen.size;
}

function totalAppeal(s) {
    const last = new Map();   // last occurrence of each character
    let cur = 0;               // sum for substrings ending at current index
    let total = 0;

    for (let i = 0; i < s.length; i++) {
        const ch = s[i];
        const prev = last.has(ch) ? last.get(ch) : -1;
        cur += i - prev;       // contribution of s[i] to substrings ending at i
        total += cur;
        last.set(ch, i);       // update last occurrence
    }
    return total;
}

function minimumCardPickup(cards) {
  const lastIndex = new Map();          // store most recent position of each card value
  let minLen = Infinity;

  for (let i = 0; i < cards.length; i++) {
    const val = cards[i];
    if (lastIndex.has(val)) {           // main logic: found a previous same value
      const curLen = i - lastIndex.get(val) + 1;
      if (curLen < minLen) minLen = curLen;
    }
    lastIndex.set(val, i);              // update last seen position
  }

  return minLen === Infinity ? -1 : minLen;
}

function largestGoodInteger(num) {
    // keep the best triple found so far
    let best = "";
    for (let i = 0; i + 2 < num.length; i++) {
        // check three consecutive equal digits
        if (num[i] === num[i + 1] && num[i] === num[i + 2]) {
            // if this digit is larger than the current best, update best
            if (best === "" || num[i] > best[0]) {
                best = num[i] + num[i] + num[i];
            }
        }
    }
    return best;
}

function countNodesEqualToAverage(root) {
    var answer = 0;

    // Perform post-order DFS returning [sum, count] and counting matching nodes
    function dfs(node) {
        if (!node) return [0, 0];
        var left = dfs(node.left);
        var right = dfs(node.right);
        var subtreeSum = node.val + left[0] + right[0];
        var subtreeSize = 1 + left[1] + right[1];
        if (node.val === Math.floor(subtreeSum / subtreeSize)) answer++;
        return [subtreeSum, subtreeSize];
    }

    dfs(root);
    return answer;
}

function countNumberOfTexts(pressedKeys) {
    const MOD = 1000000007n;
    const n = pressedKeys.length;
    if (n === 0) return 0;

    let maxLen = 0;
    let i = 0;
    while (i < n) {
        let j = i;
        while (j < n && pressedKeys[j] === pressedKeys[i]) j++;
        const runLen = j - i;
        if (runLen > maxLen) maxLen = runLen;
        i = j;
    }

    const dp3 = new Array(maxLen + 1).fill(0n);
    const dp4 = new Array(maxLen + 1).fill(0n);
    dp3[0] = 1n; dp4[0] = 1n;
    for (let k = 1; k <= maxLen; k++) {
        let v3 = dp3[k - 1];
        if (k >= 2) v3 = (v3 + dp3[k - 2]) % MOD;
        if (k >= 3) v3 = (v3 + dp3[k - 3]) % MOD;
        dp3[k] = v3;

        let v4 = dp4[k - 1];
        if (k >= 2) v4 = (v4 + dp4[k - 2]) % MOD;
        if (k >= 3) v4 = (v4 + dp4[k - 3]) % MOD;
        if (k >= 4) v4 = (v4 + dp4[k - 4]) % MOD;
        dp4[k] = v4;
    }

    let ans = 1n;
    i = 0;
    while (i < n) {
        let j = i;
        while (j < n && pressedKeys[j] === pressedKeys[i]) j++;
        const length = j - i;
        const digit = pressedKeys[i];
        const ways = (digit === '7' || digit === '9') ? dp4[length] : dp3[length];
        ans = (ans * ways) % MOD;
        i = j;
    }
    return Number(ans);
}

function hasValidPath(grid) {
    const m = grid.length;
    const n = grid[0].length;
    const maxBal = m + n;                     // > possible balances

    // dpPrev[j] holds the balance table for column j of the previous row
    let dpPrev = new Array(n);
    // dpCurr[j] holds the balance table for column j of the current row
    let dpCurr = new Array(n);

    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            const curBal = new Uint8Array(maxBal + 1); // all false
            const ch = grid[i][j];

            if (i === 0 && j === 0) {                     // start cell
                if (ch === '(') curBal[1] = 1;            // balance 1 reachable
            } else {
                // combine reachable balances from top and left
                const fromTop = i > 0 ? dpPrev[j] : null;
                const fromLeft = j > 0 ? dpCurr[j - 1] : null;

                for (let b = 0; b <= maxBal; b++) {
                    if ((fromTop && fromTop[b]) || (fromLeft && fromLeft[b])) {
                        if (ch === '(' && b + 1 <= maxBal) curBal[b + 1] = 1;
                        else if (ch === ')' && b > 0) curBal[b - 1] = 1;
                    }
                }
            }
            dpCurr[j] = curBal;
        }
        // move current row to previous row for next iteration
        dpPrev = dpCurr;
        dpCurr = new Array(n);
    }
    // valid path exists iff balance 0 is reachable at bottom‑right cell
    return dpPrev[n - 1][0] === 1;
}


// TIME: O(m * n * (m + n)) SPACE: O(n * (m + n))

function divisorSubstrings(num, k) {
    const s = String(num);
    let count = 0;
    for (let i = 0; i + k <= s.length; i++) {
        const val = Number(s.slice(i, i+k));
        if (val !== 0 && num % val === 0) count++;
    }
    return count;
}

function countValidSplits(nums) {
    const n = nums.length;
    if (n < 2) return 0;                     // need two non‑empty parts

    // compute total sum of the array
    let total = 0;
    for (let i = 0; i < n; i++) total += nums[i];

    let prefix = 0;
    let valid = 0;
    // iterate up to n‑2, updating prefix and checking the split condition
    for (let i = 0; i < n - 1; i++) {
        prefix += nums[i];
        if (prefix >= total - prefix) valid++;   // main logic
    }
    return valid;
}

function maximumWhiteTiles(tiles, carpetLen) {
    // sort intervals by their start coordinate
    tiles.sort((a, b) => a[0] - b[0]);

    const n = tiles.length;
    let left = 0;               // left side of the sliding window
    let curLen = 0;             // total length of intervals inside the window (full)
    let best = 0;               // best answer found so far

    for (let right = 0; right < n; right++) {
        // add the whole length of the new interval
        curLen += tiles[right][1] - tiles[right][0] + 1;

        // position of the carpet's left edge when its right edge touches tiles[right][1]
        const carpetStart = tiles[right][1] - carpetLen + 1;

        // discard intervals that end before the carpet starts
        while (left <= right && tiles[left][1] < carpetStart) {
            curLen -= tiles[left][1] - tiles[left][0] + 1;
            left++;
        }

        // now tiles[left] is the first interval that intersects the carpet
        let covered = curLen;
        // if the left interval starts before carpetStart, subtract the uncovered prefix
        if (tiles[left][0] < carpetStart) {
            covered -= carpetStart - tiles[left][0];
        }

        if (covered > best) best = covered;
    }

    return best;
}

function findResultantArray(words) {
    var result = [];
    var prevSignature = "";                     // signature of the last kept word

    for (var i = 0; i < words.length; i++) {
        var w = words[i];
        var cnt = new Array(26).fill(0);        // count letters (a‑z)

        for (var j = 0; j < w.length; j++) {
            cnt[w.charCodeAt(j) - 97]++;        // build frequency array
        }
        var signature = cnt.join('#');          // unique key for anagram groups

        if (i === 0 || signature !== prevSignature) { // keep if not an anagram of previous kept word
            result.push(w);
            prevSignature = signature;
        }
    }
    return result;
}

function largestVariance(s) {
    const alphabet = Array.from({ length: 26 }, (_, i) =>
        String.fromCharCode(97 + i)
    );
    let best = 0;

    for (let hi = 0; hi < 26; hi++) {
        for (let lo = 0; lo < 26; lo++) {
            if (hi === lo) continue;                 // distinct characters only
            const high = alphabet[hi];
            const low = alphabet[lo];

            let cur = 0;          // current transformed sum
            let hasLow = false;  // does the current segment contain at least one low?

            // Kadane‑like scan for the pair (high, low)
            for (const ch of s) {
                if (ch === high) cur++;          // +1 for high
                if (ch === low) { cur--; hasLow = true; } // -1 for low

                if (hasLow) best = Math.max(best, cur);   // update answer only if low is present

                if (cur < 0) {                 // discard negative prefix
                    cur = 0;
                    hasLow = false;
                }
            }
        }
    }
    return best;
}

function maximumBags(capacity, rocks, additionalRocks) {
    // compute how many rocks each bag still needs
    var need = new Array(capacity.length);
    for (var i = 0; i < capacity.length; i++) {
        need[i] = capacity[i] - rocks[i];
    }

    need.sort((a, b) => a - b);               // sort needs ascending

    var fullBags = 0;
    for (var i = 0; i < need.length; i++) {
        if (additionalRocks >= need[i]) {      // can fill this bag
            additionalRocks -= need[i];
            fullBags++;
        } else {
            break;                              // not enough rocks for any larger need
        }
    }
    return fullBags;
}

function largestCombination(candidates) {
    let best = 0;                                   // best size found
    for (let bit = 0; bit < 31; bit++) {           // iterate over possible bits
        let cnt = 0;
        const mask = 1 << bit;
        for (const num of candidates) {            // count numbers with this bit set
            if (num & mask) cnt++;
        }
        if (cnt > best) best = cnt;                // update maximum
    }
    return best;
}

function maxConsecutiveFloors(bottom, top, special) {
    // sort the special floors
    special.sort((a, b) => a - b);               // O(n log n)

    let prev = bottom - 1;                       // floor before the first possible floor
    let maxGap = 0;                               // best length found so far

    for (let i = 0; i < special.length; i++) {   // O(n)
        const cur = special[i];
        // ignore specials outside the rented range (if any)
        if (cur < bottom || cur > top) continue;

        const gap = cur - prev - 1;               // length of free segment before cur
        if (gap > maxGap) maxGap = gap;           // update answer
        prev = cur;                               // move forward
    }

    // handle the segment after the last special floor
    const lastGap = top - prev;
    if (lastGap > maxGap) maxGap = lastGap;

    return maxGap;
}

function CountIntervals() {
    const intervals = [];          // sorted, non‑overlapping [l, r]
    let total = 0;                 // total number of covered integers

    function add(left, right) {
        // binary search for first interval with start >= left
        let lo = 0, hi = intervals.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (intervals[mid][0] < left) lo = mid + 1;
            else hi = mid;
        }
        let idx = lo;

        // the previous interval may still overlap
        if (idx > 0 && intervals[idx - 1][1] + 1 >= left) idx--;

        let newL = left, newR = right;

        // merge all overlapping / touching intervals
        while (idx < intervals.length && intervals[idx][0] <= right + 1) {
            const [l, r] = intervals[idx];
            newL = Math.min(newL, l);
            newR = Math.max(newR, r);
            total -= r - l + 1;            // remove its contribution
            intervals.splice(idx, 1);      // delete it
        }

        intervals.splice(idx, 0, [newL, newR]); // insert merged interval
        total += newR - newL + 1;               // add its contribution
    }

    function count() {
        return total;
    }

    return { add, count };
}

function percentageLetter(s, letter) {
    var count = 0;
    // count occurrences of the target letter
    for (var i = 0; i < s.length; i++) {
        if (s[i] === letter) count++;
    }
    return s.length === 0 ? 0 : Math.floor(count * 100 / s.length);
}

function sumTotalStrength(strength) {
  const MOD = 1000000007n;
  const n = strength.length;
  const s = strength.map(v => BigInt(v));

  const pref = new Array(n + 1);
  pref[0] = 0n;
  for (let i = 0; i < n; i++) {
    pref[i + 1] = (pref[i] + s[i]) % MOD;
  }

  const pref2 = new Array(n + 2);
  pref2[0] = 0n;
  for (let i = 0; i <= n; i++) {
    pref2[i + 1] = (pref2[i] + pref[i]) % MOD;
  }

  const left = new Array(n);
  const stackL = [];
  for (let i = 0; i < n; i++) {
    while (stackL.length && s[stackL[stackL.length - 1]] >= s[i]) stackL.pop();
    left[i] = stackL.length ? stackL[stackL.length - 1] : -1;
    stackL.push(i);
  }

  const right = new Array(n);
  const stackR = [];
  for (let i = n - 1; i >= 0; i--) {
    while (stackR.length && s[stackR[stackR.length - 1]] > s[i]) stackR.pop();
    right[i] = stackR.length ? stackR[stackR.length - 1] : n;
    stackR.push(i);
  }

  let ans = 0n;
  for (let i = 0; i < n; i++) {
    const L = left[i];
    const R = right[i];
    const leftCount = BigInt(i - L);
    const rightCount = BigInt(R - i);

    const sumRight = (pref2[R + 1] - pref2[i + 1] + MOD) % MOD;
    const sumLeft = (pref2[i + 1] - pref2[L + 1] + MOD) % MOD;

    const term = (leftCount * sumRight - rightCount * sumLeft) % MOD;
    const contrib = (s[i] * term) % MOD;
    ans = (ans + contrib) % MOD;
  }

  return Number((ans + MOD) % MOD);
}

function digitCount(num) {
    // count occurrences of each digit (0‑9)
    const freq = new Array(10).fill(0);
    for (let i = 0; i < num.length; i++) {
        const d = num.charCodeAt(i) - 48; // numeric value of current char
        freq[d]++;                         // increment its frequency
    }

    // verify the condition for every index
    for (let i = 0; i < num.length; i++) {
        const expected = num.charCodeAt(i) - 48;          // value of num[i]
        const actual = i < 10 ? freq[i] : 0;              // count of digit i
        if (actual !== expected) return false;           // mismatch → false
    }
    return true;                                         // all matched
}

function largestWordCount(messages, senders) {
    const counts = Object.create(null);               // hash table: sender → total words

    for (let i = 0; i < messages.length; i++) {       // MAIN LOGIC: accumulate word counts
        const msg = messages[i];
        const sender = senders[i];
        // word count = 1 + number of spaces (no leading/trailing spaces)
        const wordCount = 1 + (msg.split(' ').length - 1);
        counts[sender] = (counts[sender] || 0) + wordCount;
    }

    let bestSender = '';
    let bestCount = -1;
    for (const sender in counts) {                     // MAIN LOGIC: find max (lexicographically larger on tie)
        const cnt = counts[sender];
        if (cnt > bestCount || (cnt === bestCount && sender > bestSender)) {
            bestCount = cnt;
            bestSender = sender;
        }
    }
    return bestSender;
}

function minLines(stockPrices) {
    // ---------- helper ----------
    function gcd(a, b) {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    const n = stockPrices.length;
    if (n <= 1) return 0;                     // no line needed

    // sort by day
    stockPrices.sort((p, q) => p[0] - q[0]);

    // initialise first slope
    let dy = stockPrices[1][1] - stockPrices[0][1];
    let dx = stockPrices[1][0] - stockPrices[0][0];
    let g = gcd(Math.abs(dy), Math.abs(dx));
    dy /= g; dx /= g;
    if (dx < 0) { dx = -dx; dy = -dy; }        // keep dx non‑negative
    if (dx === 0) dy = 1;                      // vertical line normalisation

    let lines = 1;                             // at least one segment

    // main logic: compare slopes and start a new line when they differ
    for (let i = 2; i < n; ++i) {
        let ndy = stockPrices[i][1] - stockPrices[i - 1][1];
        let ndx = stockPrices[i][0] - stockPrices[i - 1][0];
        let ng = gcd(Math.abs(ndy), Math.abs(ndx));
        ndy /= ng; ndx /= ng;
        if (ndx < 0) { ndx = -ndx; ndy = -ndy; }
        if (ndx === 0) ndy = 1;

        if (ndy !== dy || ndx !== dx) {        // slope changed → new line
            ++lines;
            dy = ndy;
            dx = ndx;
        }
    }
    return lines;
}

function maximumImportance(n, roads) {
    // count degrees
    const degree = new Array(n).fill(0);
    for (let i = 0; i < roads.length; i++) {
        const [a, b] = roads[i];
        degree[a]++; degree[b]++;
    }

    // sort degrees descending
    degree.sort((x, y) => y - x); // MAIN LOGIC

    // assign biggest values to biggest degrees
    let curVal = n, ans = 0;
    for (const d of degree) {
        ans += d * curVal;
        curVal--;
    }
    return ans;
}

function minimumObstacleRemovalToReachCorner(grid) {
    const m = grid.length, n = grid[0].length;
    const INF = 1e9;
    const dist = Array.from({length: m}, () => new Array(n).fill(INF));
    const dq = [];
    dist[0][0] = 0;
    dq.push([0, 0]);
    let head = 0;
    const dirs = [[1,0],[-1,0],[0,1],[0,-1]];

    while (head < dq.length) {
        const [x, y] = dq[head++];
        const d = dist[x][y];
        if (x === m - 1 && y === n - 1) break;
        for (const [dx, dy] of dirs) {
            const nx = x + dx, ny = y + dy;
            if (nx >= 0 && nx < m && ny >= 0 && ny < n) {
                const nd = d + grid[nx][ny];
                if (nd < dist[nx][ny]) {
                    dist[nx][ny] = nd;
                    if (grid[nx][ny] === 0) {
                        dq.splice(head, 0, [nx, ny]); // push front (relative to remaining)
                    } else {
                        dq.push([nx, ny]);
                    }
                }
            }
        }
    }
    return dist[m - 1][n - 1];
}

function rearrange(s, target) {
    const sCount = {};
    const tCount = {};

    // count characters in s
    for (let i = 0; i < s.length; i++) {
        const ch = s[i];
        sCount[ch] = (sCount[ch] || 0) + 1;
    }

    // count characters in target
    for (let i = 0; i < target.length; i++) {
        const ch = target[i];
        tCount[ch] = (tCount[ch] || 0) + 1;
    }

    // main logic: find the limiting character ratio
    let copies = Infinity;
    for (const ch in tCount) {
        const available = sCount[ch] || 0;
        copies = Math.min(copies, Math.floor(available / tCount[ch]));
    }
    return copies === Infinity ? 0 : copies;
}

function discountPrices(sentence, discount) {
    // split the sentence into words
    var words = sentence.split(' ');
    // process each word
    for (var i = 0; i < words.length; i++) {
        var w = words[i];
        // MAIN LOGIC: check if word is a price and apply discount
        if (w.charAt(0) === '$' && w.length > 1) {
            var isNumber = true;
            for (var j = 1; j < w.length; j++) {
                var c = w.charCodeAt(j);
                if (c < 48 || c > 57) { // not '0'‑'9'
                    isNumber = false;
                    break;
                }
            }
            if (isNumber) {
                var price = parseInt(w.slice(1), 10);
                var discounted = price * (100 - discount) / 100;
                words[i] = '$' + discounted.toFixed(2);
            }
        }
    }
    // re‑assemble the sentence
    return words.join(' ');
}

function stepsToMakeNonDecreasing(nums) {
    let maxSteps = 0;
    const stack = []; // [value, removalStep] pairs
    for (let i = 0; i < nums.length; i++) {
        let curSteps = 0;
        // pop elements smaller-or-equal to the current one - they can never act as a
        // "blocker" for it (or for anything even bigger that comes later); track how
        // long it takes for them to clear out of the way
        while (stack.length && stack[stack.length - 1][0] <= nums[i]) {
            curSteps = Math.max(curSteps, stack[stack.length - 1][1]);
            stack.pop();
        }
        if (stack.length) curSteps += 1;
        maxSteps = Math.max(maxSteps, curSteps);
        stack.push([nums[i], curSteps]);
    }
    return maxSteps;
}

function BookMyShow(n, m) {
    this.n = n;
    this.m = m;
    this.rem = new Float64Array(n);
    this.rem.fill(m);
    const size = 4 * n;
    this.maxTree = new Float64Array(size);
    this.sumTree = new Float64Array(size);

    const build = (node, l, r) => {
        if (l === r) {
            this.maxTree[node] = m;
            this.sumTree[node] = m;
            return;
        }
        const mid = (l + r) >> 1;
        build(node << 1, l, mid);
        build((node << 1) | 1, mid + 1, r);
        this.maxTree[node] = Math.max(this.maxTree[node << 1], this.maxTree[(node << 1) | 1]);
        this.sumTree[node] = this.sumTree[node << 1] + this.sumTree[(node << 1) | 1];
    };
    build(1, 0, n - 1);

    this._update = (node, l, r, idx, val) => {
        if (l === r) {
            this.maxTree[node] = val;
            this.sumTree[node] = val;
            return;
        }
        const mid = (l + r) >> 1;
        if (idx <= mid) this._update(node << 1, l, mid, idx, val);
        else this._update((node << 1) | 1, mid + 1, r, idx, val);
        this.maxTree[node] = Math.max(this.maxTree[node << 1], this.maxTree[(node << 1) | 1]);
        this.sumTree[node] = this.sumTree[node << 1] + this.sumTree[(node << 1) | 1];
    };

    this._findGather = (node, l, r, maxRow, k) => {
        if (l > maxRow || this.maxTree[node] < k) return -1;
        if (l === r) return l;
        const mid = (l + r) >> 1;
        const left = this._findGather(node << 1, l, mid, maxRow, k);
        if (left !== -1) return left;
        return this._findGather((node << 1) | 1, mid + 1, r, maxRow, k);
    };

    this._querySum = (node, l, r, ql, qr) => {
        if (ql > r || qr < l) return 0;
        if (ql <= l && r <= qr) return this.sumTree[node];
        const mid = (l + r) >> 1;
        return this._querySum(node << 1, l, mid, ql, qr) + this._querySum((node << 1) | 1, mid + 1, r, ql, qr);
    };

    this._findFirstPositive = (node, l, r, maxRow) => {
        if (l > maxRow || this.maxTree[node] === 0) return -1;
        if (l === r) return l;
        const mid = (l + r) >> 1;
        const left = this._findFirstPositive(node << 1, l, mid, maxRow);
        if (left !== -1) return left;
        return this._findFirstPositive((node << 1) | 1, mid + 1, r, maxRow);
    };

    this.gather = (k, maxRow) => {
        const row = this._findGather(1, 0, this.n - 1, maxRow, k);
        if (row === -1) return [];
        const startSeat = this.m - this.rem[row];
        this.rem[row] -= k;
        this._update(1, 0, this.n - 1, row, this.rem[row]);
        return [row, startSeat];
    };

    this.scatter = (k, maxRow) => {
        const total = this._querySum(1, 0, this.n - 1, 0, maxRow);
        if (total < k) return false;
        while (k > 0) {
            const row = this._findFirstPositive(1, 0, this.n - 1, maxRow);
            const take = Math.min(this.rem[row], k);
            this.rem[row] -= take;
            this._update(1, 0, this.n - 1, row, this.rem[row]);
            k -= take;
        }
        return true;
    };
}
