function TextEditor() {
    const left = [];   // characters left of cursor
    const right = [];  // characters right of cursor

    return {
        // insert text at cursor
        addText: function(txt) {
            for (let i = 0; i < txt.length; i++) left.push(txt[i]);   // O(|txt|)
        },

        // delete up to k characters left of cursor, return number actually deleted
        deleteText: function(k) {
            let removed = 0;
            while (removed < k && left.length) { left.pop(); removed++; } // O(k)
            return removed;
        },

        // move cursor left k positions, return last up to 10 chars left of cursor
        cursorLeft: function(k) {
            let moved = 0;
            while (moved < k && left.length) { right.push(left.pop()); moved++; } // O(k)
            return left.slice(-10).join('');   // O(10)
        },

        // move cursor right k positions, return last up to 10 chars left of cursor
        cursorRight: function(k) {
            let moved = 0;
            while (moved < k && right.length) { left.push(right.pop()); moved++; } // O(k)
            return left.slice(-10).join('');   // O(10)
        }
    };
}

function minMaxGame(nums) {
  let n = nums.length;
  while (n > 1) {
    // compute min or max for each pair based on index parity
    for (let i = 0; i < n / 2; i++) {
      if (i % 2 === 0) {
        nums[i] = Math.min(nums[2 * i], nums[2 * i + 1]);
      } else {
        nums[i] = Math.max(nums[2 * i], nums[2 * i + 1]);
      }
    }
    n = n / 2;
  }
  return nums[0];
}

function minSubsequences(nums, k) {
    if (nums.length === 0) return 0;

    // sort first! partitioning into subsequences with bounded max-min doesn't
    // require preserving original order - grouping the smallest available values
    // together greedily (after sorting) is what actually minimizes group count
    const sorted = nums.slice().sort((a, b) => a - b);

    let groups = 1;
    let base = sorted[0];

    for (let i = 1; i < sorted.length; i++) {
        if (sorted[i] - base > k) {
            groups++;
            base = sorted[i];
        }
    }
    return groups;
}

function replaceElements(nums, operations) {
    // map current value -> its index in nums
    const pos = new Map();
    for (let i = 0; i < nums.length; i++) pos.set(nums[i], i);

    for (let i = 0; i < operations.length; i++) {
        const [oldVal, newVal] = operations[i];
        const idx = pos.get(oldVal);          // find where oldVal lives
        if (idx !== undefined) {
            nums[idx] = newVal;               // replace it
            pos.delete(oldVal);               // remove old mapping
            pos.set(newVal, idx);             // insert new mapping
        }
    }
    return nums;
}

function successfulPairs(spells, potions, success) {
    potions.sort((a, b) => a - b);               // sort potions for binary search
    const m = potions.length;
    const answer = new Array(spells.length);

    for (let i = 0; i < spells.length; i++) {
        const spell = spells[i];
        const need = Math.ceil(success / spell); // smallest potion that works

        // binary search first index with value >= need
        let lo = 0, hi = m;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (potions[mid] < need) lo = mid + 1;
            else hi = mid;
        }
        answer[i] = m - lo;                       // all potions from lo to end are successful
    }
    return answer;
}

function strongPasswordCheckerII(password) {
    // password must be at least 8 characters
    if (password.length < 8) return false;

    const specials = "!@#$%^&*()-+";
    let hasLower = false, hasUpper = false, hasDigit = false, hasSpecial = false;

    // Check each character and update criteria
    for (let i = 0; i < password.length; i++) {
        const ch = password[i];
        if (ch >= 'a' && ch <= 'z') hasLower = true;
        else if (ch >= 'A' && ch <= 'Z') hasUpper = true;
        else if (ch >= '0' && ch <= '9') hasDigit = true;
        else if (specials.indexOf(ch) !== -1) hasSpecial = true;

        // adjacent identical characters are not allowed
        if (i > 0 && password[i] === password[i - 1]) return false;
    }

    // Return true only if all criteria are satisfied
    return hasLower && hasUpper && hasDigit && hasSpecial;
}

var matchReplacement = function(s, sub, mappings) {
    const replaceMap = new Map();
    for (const [old,neu] of mappings) {
        if (!replaceMap.has(old)) replaceMap.set(old, new Set());
        replaceMap.get(old).add(neu);
    }
    const allowed = new Map();
    for (const ch of new Set(sub)) {
        const chars = new Set([ch]);
        if (replaceMap.has(ch)) for (const c of replaceMap.get(ch)) chars.add(c);
        allowed.set(ch, chars);
    }
    const n = s.length, m = sub.length;
    if (m > n) return false;
    for (let i=0;i<=n-m;i++) {
        let ok = true;
        for (let j=0;j<m;j++) {
            const ch = sub[j];
            if (!allowed.get(ch).has(s[i+j])) { ok=false; break; }
        }
        if (ok) return true;
    }
    return false;
};

function calculateTax(brackets, income) {
    let tax = 0;
    let lower = 0;
    for (let i = 0; i < brackets.length; i++) {
        const [upper, percent] = brackets[i];
        if (income <= lower) break;
        const portion = Math.min(income, upper) - lower;
        tax += portion * percent / 100;
        lower = upper;
    }
    return Number(tax.toFixed(5)); // convert back from string to a number
}

function countSubarrays(nums, k) {
    const n = nums.length;
    let left = 0, sum = 0, count = 0;
    for (let right = 0; right < n; right++) {
        sum += nums[right];
        while (sum * (right - left + 1) >= k) {
            sum -= nums[left];
            left++;
        }
        count += right - left + 1;
    }
    return count;
}

function minimumPathCost(grid, moveCost) {
    const m = grid.length;
    const n = grid[0].length;

    // dpPrev[j] = cheapest total cost to reach column j of the previous row
    let dpPrev = new Array(n);
    for (let j = 0; j < n; ++j) dpPrev[j] = grid[0][j];   // first row has no move cost

    for (let i = 1; i < m; ++i) {
        const dpCur = new Array(n);
        for (let j = 0; j < n; ++j) {
            let best = Infinity;
            // DP transition: try every column k of the previous row
            for (let k = 0; k < n; ++k) {
                const cand = dpPrev[k] + moveCost[grid[i - 1][k]][j];
                if (cand < best) best = cand;
            }
            dpCur[j] = grid[i][j] + best;   // add value of current cell
        }
        dpPrev = dpCur;   // move to next row
    }

    // answer = cheapest cost among cells of the last row
    let answer = Infinity;
    for (let v of dpPrev) if (v < answer) answer = v;
    return answer;
}

function distributeCookies(cookies, k) {
    // sort descending – large bags first for better pruning
    cookies.sort((a, b) => b - a);
    const n = cookies.length;
    if (k >= n) return Math.max(...cookies);          // each child can get ≤1 bag

    const total = cookies.reduce((s, v) => s + v, 0);
    let low = Math.max(...cookies), high = total;    // binary search bounds

    // ---------- main logic: binary search + DFS feasibility test ----------
    while (low < high) {
        const mid = Math.floor((low + high) / 2);
        const load = new Array(k).fill(0);
        let possible = false;

        function dfs(idx) {
            if (idx === n) return true;               // all bags placed
            const cur = cookies[idx];
            for (let i = 0; i < k; i++) {
                if (load[i] + cur > mid) continue;    // would exceed limit
                load[i] += cur;
                if (dfs(idx + 1)) return true;
                load[i] -= cur;
                if (load[i] === 0) break;             // avoid symmetric empty children
            }
            return false;
        }

        possible = dfs(0);
        if (possible) high = mid;                     // can do better
        else low = mid + 1;
    }
    return low;
}

function maxProfit(m, n, prices) {
    // store the best price for each exact shape
    const priceMap = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));
    for (const [h, w, p] of prices) {
        if (h <= m && w <= n && p > priceMap[h][w]) priceMap[h][w] = p;
    }

    // dp[h][w] = best profit for an h×w piece
    const dp = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));

    for (let h = 1; h <= m; ++h) {
        for (let w = 1; w <= n; ++w) {
            let best = priceMap[h][w];                     // sell as‑is
            // try all horizontal cuts
            for (let cut = 1; cut < h; ++cut) {
                const cur = dp[cut][w] + dp[h - cut][w];
                if (cur > best) best = cur;
            }
            // try all vertical cuts
            for (let cut = 1; cut < w; ++cut) {
                const cur = dp[h][cut] + dp[h][w - cut];
                if (cur > best) best = cur;
            }
            dp[h][w] = best;
        }
    }
    return dp[m][n];
}



