function longestBinarySubsequence(s, k) {
    let sum = 0;
    let cnt = 0;
    let ans = 0;
    for (let i = s.length - 1; i >= 0; i--) {
        if (s[i] === '0') {
            cnt++;
            ans++;
        } else {
            if (cnt >= 31) continue;
            const weight = 1 << cnt;
            if (sum + weight <= k) {
                sum += weight;
                cnt++;
                ans++;
            }
        }
    }
    return ans;
}

function greatestLetter(s) {
  // Record which letters appear in lower‑case and upper‑case, then find the greatest common one
  const lowerSeen = new Array(26).fill(false);
  const upperSeen = new Array(26).fill(false);

  for (let i = 0; i < s.length; i++) {
    const code = s.charCodeAt(i);
    if (code >= 97 && code <= 122) lowerSeen[code - 97] = true;   // 'a'‑'z'
    else if (code >= 65 && code <= 90) upperSeen[code - 65] = true; // 'A'‑'Z'
  }

  for (let i = 25; i >= 0; i--) {               // check from 'Z' down to 'A'
    if (lowerSeen[i] && upperSeen[i]) {
