}

function distinctNames(ideas) {
    // group suffixes by their first letter
    const groups = Array.from({ length: 26 }, () => new Set());
    for (let w of ideas) {
        const first = w.charCodeAt(0) - 97;          // 0 … 25
        const suffix = w.slice(1);
        groups[first].add(suffix);
    }

    let answer = 0;

    // iterate over all unordered pairs of different first letters
    for (let i = 0; i < 26; i++) {
        if (groups[i].size === 0) continue;
        for (let j = i + 1; j < 26; j++) {
            if (groups[j].size === 0) continue;

            // count common suffixes (intersection size)
            let common = 0;
            const smaller = groups[i].size < groups[j].size ? groups[i] : groups[j];
            const larger  = groups[i].size < groups[j].size ? groups[j] : groups[i];
            for (let s of smaller) if (larger.has(s)) common++;

            const uniqueI = groups[i].size - common;
            const uniqueJ = groups[j].size - common;

            // each ordered pair (i→j and j→i) is counted
            answer += uniqueI * uniqueJ * 2;
        }
    }
    return answer;
}

function countPairs(n, edges) {
    // initialise DSU
    var parent = new Array(n);
    var size = new Array(n);
    for (var i = 0; i < n; i++) {
        parent[i] = i;
        size[i] = 1;
    }

    function find(x) {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]]; // path compression
            x = parent[x];
        }
        return x;
    }

    function union(a, b) {
        var ra = find(a), rb = find(b);
        if (ra === rb) return;
        // union by size
        if (size[ra] < size[rb]) {
            var tmp = ra; ra = rb; rb = tmp;
        }
        parent[rb] = ra;
        size[ra] += size[rb];
    }

    // union all edges
    for (var i = 0; i < edges.length; i++) {
        union(edges[i][0], edges[i][1]);
    }

    // count nodes per component
    var compCount = new Map();
    for (var i = 0; i < n; i++) {
        var root = find(i);
        compCount.set(root, (compCount.get(root) || 0) + 1);
    }

    // total pairs minus pairs inside each component
    var totalPairs = n * (n - 1) / 2;
    var intraPairs = 0;
    compCount.forEach(function(c) {
        intraPairs += c * (c - 1) / 2;
    });

    return totalPairs - intraPairs;
}

