function countWays(n) {
    const MOD = 1000000007;

    // fast‑doubling: returns F_k (mod MOD)
    function fib(k) {
        if (k === 0) return [0, 1];                 // (F_k, F_{k+1})
        const [a, b] = fib(Math.floor(k / 2));      // a = F_m, b = F_{m+1}
        const twoBminusA = (2 * b % MOD - a + MOD) % MOD;
        const c = (a * twoBminusA) % MOD;            // F_{2m}
        const d = (a * a % MOD + b * b % MOD) % MOD; // F_{2m+1}
        if (k % 2 === 0) return [c, d];              // even
        return [d, (c + d) % MOD];                   // odd
    }

    const f = fib(n + 2)[0];                         // F_{n+2}
    return (f * f) % MOD;                            // (F_{n+2})² mod MOD
}

function spiralMatrix(m, n, head) {
    // create matrix filled with -1
    const matrix = Array.from({ length: m }, () => Array(n).fill(-1));

    let top = 0, bottom = m - 1, left = 0, right = n - 1;
    let cur = head, filled = 0, total = m * n;

    // fill matrix in spiral order using boundaries
    while (filled < total && cur) {
        for (let col = left; col <= right && cur; col++) {   // top row
            matrix[top][col] = cur.val;
            cur = cur.next;
            filled++;
        }
        top++;

        for (let row = top; row <= bottom && cur; row++) { // right column
            matrix[row][right] = cur.val;
            cur = cur.next;
            filled++;
        }
        right--;

        for (let col = right; col >= left && cur; col--) { // bottom row
            matrix[bottom][col] = cur.val;
            cur = cur.next;
            filled++;
        }
        bottom--;

        for (let row = bottom; row >= top && cur; row--) { // left column
            matrix[row][left] = cur.val;
            cur = cur.next;
            filled++;
        }
        left++;
    }

    return matrix;
}

function peopleAwareOfSecret(n, delay, forget) {
  const MOD = 1000000007n;
  const share = new Array(n + 1).fill(0n);
