    for (let i = 0; i < n; ++i) {          // compute original sums
        sum1 += nums1[i];
        sum2 += nums2[i];
    }

    let maxDiff = -Infinity, curMax = 0;   // Kadane for maximum sub‑array sum
    let minDiff = Infinity, curMin = 0;    // Kadane for minimum sub‑array sum

    for (let i = 0; i < n; ++i) {
        const d = nums2[i] - nums1[i];      // diff[i]

        // update max sub‑array sum
        curMax = Math.max(d, curMax + d);
        maxDiff = Math.max(maxDiff, curMax);

        // update min sub‑array sum
        curMin = Math.min(d, curMin + d);
        minDiff = Math.min(minDiff, curMin);
    }

    // best possible score
    return Math.max(
        sum1,                     // no swap, keep nums1
        sum2,                     // no swap, keep nums2
        sum1 + maxDiff,           // maximise sum of nums1
        sum2 - minDiff            // maximise sum of nums2
    );
}

