        tin[u] = timer++;
        let cur = nums[u];
        for (const v of adj[u]) {
            if (v === p) continue;
            dfs(v, u);
            cur ^= subXor[v];
        }
        subXor[u] = cur;
        tout[u] = timer++;
    }
    dfs(0, -1);
    const totalXor = subXor[0];
    const candidates = [];
    for (let i = 1; i < n; i++) candidates.push(i);
    function isAncestor(a, b) {
        return tin[a] <= tin[b] && tout[b] <= tout[a];
    }
    let ans = Number.MAX_SAFE_INTEGER;
    const m = candidates.length;
    for (let i = 0; i < m; i++) {
        const a = candidates[i];
        for (let j = i + 1; j < m; j++) {
            const b = candidates[j];
            let c1, c2, c3;
            if (isAncestor(a, b)) {
                c1 = subXor[b];
                c2 = subXor[a] ^ subXor[b];
                c3 = totalXor ^ subXor[a];
            } else if (isAncestor(b, a)) {
                c1 = subXor[a];
                c2 = subXor[b] ^ subXor[a];
                c3 = totalXor ^ subXor[b];
            } else {
                c1 = subXor[a];
                c2 = subXor[b];
                c3 = totalXor ^ subXor[a] ^ subXor[b];
            }
            const mx = Math.max(c1, c2, c3);
            const mn = Math.min(c1, c2, c3);
            const diff = mx - mn;
            if (diff < ans) ans = diff;
        }
    }
    return ans;
}

function decodeMessage(key, message) {
    const map = {};                     // cipher → plain
    let nextCharCode = 97;              // code for 'a'

    // Build the substitution table from the key
    for (let i = 0; i < key.length; i++) {
        const ch = key[i];
        if (ch === ' ') continue;       // skip spaces
        if (!(ch in map)) {             // first appearance
            map[ch] = String.fromCharCode(nextCharCode++);
        }
    }

    // Decode the message using the table
    let result = '';
    for (let i = 0; i < message.length; i++) {
        const ch = message[i];
        result += ch === ' ' ? ' ' : map[ch];
    }
    return result;
}

function latestTimeCatchTheBus(buses, passengers, capacity) {
    buses.sort((a, b) => a - b);
    passengers.sort((a, b) => a - b);
    const passengerSet = new Set(passengers);

    let pIdx = 0;
    let lastBoarded = -1;
    let lastBusHasRoom = false;

    for (let b = 0; b < buses.length; b++) {
        let cnt = 0;
        while (pIdx < passengers.length && passengers[pIdx] <= buses[b] && cnt < capacity) {
            lastBoarded = passengers[pIdx];
            pIdx++;
            cnt++;
        }
        // only the LAST bus's remaining capacity matters for "arrive right at bus time"
        if (b === buses.length - 1) lastBusHasRoom = cnt < capacity;
    }

    let answer = lastBusHasRoom ? buses[buses.length - 1] : lastBoarded - 1;
    while (answer >= 0 && passengerSet.has(answer)) answer--;
    return answer;
}

function countIncreasingPaths(grid) {
  const MOD = 1000000007;
  const m = grid.length, n = grid[0].length;
  const dp = Array.from({ length: m }, () => Array(n).fill(0));
  const dirs = [[1,0],[-1,0],[0,1],[0,-1]];          // 4 directions

  function dfs(i, j) {                               // memoised DFS
    if (dp[i][j]) return dp[i][j];                  // already computed
    let total = 1;                                   // path consisting only of (i,j)
    for (const [dx, dy] of dirs) {
      const x = i + dx, y = j + dy;
      if (x < 0 || x >= m || y < 0 || y >= n) continue;
      if (grid[x][y] <= grid[i][j]) continue;       // not strictly larger
      total = (total + dfs(x, y)) % MOD;            // extend neighbour paths
    }
    dp[i][j] = total;
    return total;
  }

  let answer = 0;
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      answer = (answer + dfs(i, j)) % MOD;          // sum over all start cells
    }
  }
  return answer;
}

function evaluateTree(root) {
