        while (j < n && target[j] === '_') j++;  // skip empties in target

        if (i === n || j === n) break;           // reached end of one string

        if (start[i] !== target[j]) return false;          // different piece
        if (start[i] === 'L' && i < j) return false;       // L would need to move right
