function SmallestInfiniteSet() {
    var next = 1;
    var heap = [];
    var inHeap = new Set();

    function heapPush(val) {
        heap.push(val);
        var i = heap.length - 1;
        while (i > 0) {
            var p = (i - 1) >> 1;
            if (heap[p] <= heap[i]) break;
            var tmp = heap[p]; heap[p] = heap[i]; heap[i] = tmp;
            i = p;
        }
    }
    function heapPop() {
        var top = heap[0];
        var last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            var i = 0, n = heap.length;
            while (true) {
                var l = i * 2 + 1, r = l + 1, smallest = i;
                if (l < n && heap[l] < heap[smallest]) smallest = l;
                if (r < n && heap[r] < heap[smallest]) smallest = r;
                if (smallest === i) break;
                var tmp = heap[i]; heap[i] = heap[smallest]; heap[smallest] = tmp;
                i = smallest;
            }
        }
        return top;
    }

    return {
        popSmallest: function () {
            if (heap.length) {
                var val = heapPop();
                inHeap.delete(val);
                return val;
            }
            return next++;
        },

        addBack: function (num) {
            if (num < next && !inHeap.has(num)) {
                heapPush(num);
                inHeap.add(num);
            }
        }
    };
}

function countTheNumberOfIdealArrays(n, maxValue) {
    const MOD = 1000000007n;
    const spf = Array.from({length: maxValue + 1}, (_, i) => i);
    const limitI = Math.floor(Math.sqrt(maxValue)) + 1;
    for (let i = 2; i < limitI; i++) {
        if (spf[i] === i) {
            for (let j = i * i; j <= maxValue; j += i) {
                if (spf[j] === j) spf[j] = i;
            }
        }
    }

    const totalExp = new Array(maxValue + 1).fill(0);
    let maxExp = 0;
    for (let i = 2; i <= maxValue; i++) {
        const p = spf[i];
        totalExp[i] = totalExp[Math.floor(i / p)] + 1;
        if (totalExp[i] > maxExp) maxExp = totalExp[i];
    }

    const limit = n - 1 + maxExp;
    const fact = new Array(limit + 1).fill(1n);
    for (let i = 1; i <= limit; i++) fact[i] = (fact[i - 1] * BigInt(i)) % MOD;

    const modpow = (base, exp, mod) => {
        base %= mod;
        let result = 1n;
        while (exp > 0n) {
            if (exp & 1n) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1n;
        }
        return result;
    };
    const invFact = new Array(limit + 1).fill(1n);
    invFact[limit] = modpow(fact[limit], MOD - 2n, MOD);
    for (let i = limit; i >= 1; i--) invFact[i - 1] = (invFact[i] * BigInt(i)) % MOD;

    const comb = (a, b) => {
        if (b < 0 || b > a) return 0n;
        return (fact[a] * invFact[b] % MOD) * invFact[a - b] % MOD;
    };

    let ans = 0n;
    for (let i = 1; i <= maxValue; i++) {
        ans = (ans + comb(n - 1 + totalExp[i], totalExp[i])) % MOD;
    }
    return Number(ans);
}

function findSubarrayLength(nums, threshold) {
    const n = nums.length;
    const left = new Int32Array(n);
    const right = new Int32Array(n);
    const stack = [];
    for (let i = 0; i < n; i++) {
        while (stack.length && nums[stack[stack.length - 1]] >= nums[i]) stack.pop();
        left[i] = stack.length ? stack[stack.length - 1] : -1;
        stack.push(i);
    }
    stack.length = 0;
    for (let i = n - 1; i >= 0; i--) {
        while (stack.length && nums[stack[stack.length - 1]] >= nums[i]) stack.pop();
        right[i] = stack.length ? stack[stack.length - 1] : n;
        stack.push(i);
    }
    // must check every index and keep the GLOBAL minimum valid length, not
    // just return on the first index that happens to work
    let best = -1;
    for (let i = 0; i < n; i++) {
        const maxLen = right[i] - left[i] - 1;
        const need = Math.floor(threshold / nums[i]) + 1;
        if (need <= maxLen) {
            if (best === -1 || need < best) best = need;
        }
    }
    return best;
}

function minSumSquareDiff(nums1, nums2, k1, k2) {
    const MOD = 1_000_000_007;
    const n = nums1.length;
    const heap = [];                     // max‑heap of differences

    // build heap
    for (let i = 0; i < n; ++i) {
        const diff = Math.abs(nums1[i] - nums2[i]);
        heapPush(heap, diff);
    }

    let ops = k1 + k2;
    // main loop: always reduce the largest difference
    while (ops-- > 0 && heap.length) {
        let top = heapPop(heap);          // largest diff
        if (top === 0) {                  // all diffs are zero, stop early
            heapPush(heap, 0);
            break;
        }
        heapPush(heap, top - 1);          // reduce by one
    }

    // compute the sum of squares
    let ans = 0;
    for (const v of heap) {
        ans = (ans + (v * v) % MOD) % MOD;
    }
    return ans;
}

