function maxSum(nums) {
    const best = {};                     // ds -> [largest, secondLargest]

    for (let i = 0; i < nums.length; i++) {
        const num = nums[i];
        let ds = 0, x = num;             // compute digit sum
        while (x > 0) { ds += x % 10; x = (x / 10) | 0; }

        if (best[ds] === undefined) {    // first occurrence of this ds
            best[ds] = [num, -1];
        } else {
            if (num > best[ds][0]) {     // new largest
                best[ds][1] = best[ds][0];
                best[ds][0] = num;
            } else if (num > best[ds][1]) { // new second largest
                best[ds][1] = num;
            }
        }
    }

    let answer = -1;
    for (const key in best) {            // evaluate each digit‑sum group
        const [first, second] = best[key];
        if (second !== -1) {
            const cur = first + second;
            if (cur > answer) answer = cur;
        }
    }
    return answer;
}

function maxPairs(nums) {
