    total += consecutive * (consecutive + 1) / 2;
    return total;
}

var shortestSequence = function(rolls, k) {
    const n = rolls.length;
    const pos = Array.from({length:k+1}, () => []);
    for (let i=0;i<n;i++) {
        const v = rolls[i];
        if (v>=1 && v<=k) pos[v].push(i);
    }
    for (let v=1; v<=k; v++) if (pos[v].length===0) return 1;
    function bisectRight(arr, x) {
        let lo=0, hi=arr.length;
        while (lo<hi) {
            const mid=(lo+hi)>>1;
            if (arr[mid] <= x) lo=mid+1; else hi=mid;
        }
        return lo;
    }
    let L = 2;
    while (true) {
        if (L > n) return L;
        const stack = [[0,-1]];
        while (stack.length) {
            const top = stack.pop();
            const depth = top[0], cur = top[1];
            if (depth === L) continue;
            for (let v=1; v<=k; v++) {
                const lst = pos[v];
                const idx = bisectRight(lst, cur);
                if (idx === lst.length) return L;
                stack.push([depth+1, lst[idx]]);
            }
        }
        L++;
    }
};

