        a.push(x);
        let i = a.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (this.cmp(a[p], a[i])) break;
            [a[p], a[i]] = [a[i], a[p]];
            i = p;
        }
    };
    Heap.prototype.pop = function () {
        const a = this.data;
        if (a.length === 0) return undefined;
        const top = a[0];
        const last = a.pop();
        if (a.length) {
            a[0] = last;
            let i = 0;
            while (true) {
                let l = i * 2 + 1,
                    r = i * 2 + 2,
                    best = i;
                if (l < a.length && !this.cmp(a[best], a[l])) best = l;
                if (r < a.length && !this.cmp(a[best], a[r])) best = r;
                if (best === i) break;
                [a[i], a[best]] = [a[best], a[i]];
                i = best;
            }
        }
        return top;
    };
    // comparator: higher rating first, then smaller name
    const cmp = (a, b) => a[0] > b[0] || (a[0] === b[0] && a[1] < b[1]);

    // ----- initialise structures -----
    for (let i = 0; i < foods.length; ++i) {
        const f = foods[i], r = ratings[i], c = cuisines[i];
        this.foodToCuisine[f] = c;
        this.foodToRating[f] = r;
        if (!this.cuisineHeap[c]) this.cuisineHeap[c] = new Heap(cmp);
        this.cuisineHeap[c].push([r, f]);          // push initial entry
    }
}

