    const dist2 = new Array(n).fill(Infinity);

    // compute distances from node1
    let cur = node1, d = 0;
    while (cur !== -1 && dist1[cur] === Infinity) {
        dist1[cur] = d++;
        cur = edges[cur];
    }

    // compute distances from node2
    cur = node2; d = 0;
    while (cur !== -1 && dist2[cur] === Infinity) {
        dist2[cur] = d++;
        cur = edges[cur];
    }

    // select node minimizing max(dist1, dist2) with tie‑break on smallest index
    let bestNode = -1;
    let bestDist = Infinity;
    for (let i = 0; i < n; i++) {
        if (dist1[i] !== Infinity && dist2[i] !== Infinity) {
            const curMax = Math.max(dist1[i], dist2[i]);
            if (curMax < bestDist || (curMax === bestDist && i < bestNode)) {
                bestDist = curMax;
                bestNode = i;
            }
        }
    }
    return bestNode;
}

function maxGroups(grades) {
    // the actual grade VALUES don't matter at all - grades can be freely sorted
    // and assigned, so this reduces purely to: what's the max k such that
    // group sizes 1,2,3,...,k (summing to k*(k+1)/2) fit within n students?
    const n = grades.length;
    let k = 0, total = 0;
    while (total + k + 1 <= n) {
        k++;
        total += k;
    }
    return k;
}

function taskSchedulerII(tasks, space) {
    const last = Object.create(null);   // stores last day a type was done
    let day = 1;                         // next day we can act

    for (let i = 0; i < tasks.length; i++) {
        const t = tasks[i];
        // compute earliest day we may execute this task
        if (last[t] !== undefined) {
            const earliest = last[t] + space + 1;
            if (day < earliest) day = earliest;
        }
        last[t] = day;   // perform task on current day
        day++;           // move to the following day
    }
    return day - 1;      // last performed day
}

function longestCycle(edges) {
    const n = edges.length;
    const visited = new Array(n).fill(false);
    let best = -1;

    for (let i = 0; i < n; i++) {
        if (visited[i]) continue;

        let cur = i;
        let step = 0;
        const localStep = new Map();               // node → step inside this walk

        while (cur !== -1 && !visited[cur]) {
            visited[cur] = true;                    // MAIN LOGIC
            localStep.set(cur, step);               // MAIN LOGIC
            cur = edges[cur];
            step++;
        }

        if (cur !== -1 && localStep.has(cur)) {     // MAIN LOGIC
            const cycleLen = step - localStep.get(cur);
            if (cycleLen > best) best = cycleLen;
        }
    }
    return best;
}

function minimumReplacement(nums) {
    let ops = 0n;
    let maxAllowed = BigInt(nums[nums.length-1]);
    for (let i = nums.length-2; i >= 0; i--) {
        const v = BigInt(nums[i]);
        if (v <= maxAllowed) { maxAllowed = v; continue; }
        const parts = (v + maxAllowed - 1n) / maxAllowed;
        ops += parts - 1n;
        maxAllowed = v / parts;
    }
    return Number(ops);
}

function validPartition(nums) {
    const n = nums.length;
    const dp = new Array(n + 1).fill(false);
    dp[0] = true;                                   // empty prefix is valid

    for (let i = 2; i <= n; i++) {
        // try a block of length 2: [x, x]
        if (nums[i - 2] === nums[i - 1] && dp[i - 2]) {
            dp[i] = true;
        }
        // try a block of length 3: [x, x, x] or [x, x+1, x+2]
        if (!dp[i] && i >= 3) {
            const a = nums[i - 3], b = nums[i - 2], c = nums[i - 1];
            if ((a === b && b === c && dp[i - 3]) ||          // all equal
                (a + 1 === b && b + 1 === c && dp[i - 3])) { // consecutive
                dp[i] = true;
            }
        }
    }
    return dp[n];
}

function numberOfArithmeticTriplets(nums, diff) {
    const numSet = new Set(nums);          // store all values for O(1) lookup
    let count = 0;
    for (let i = 0; i < nums.length; i++) {
        const x = nums[i];
        // if x+diff and x+2*diff both exist, (i, j, k) forms a valid triplet
        if (numSet.has(x + diff) && numSet.has(x + 2 * diff)) {
            count++;
        }
    }
    return count;
}

function countBadPairs(nums) {
    const n = nums.length;
    const totalPairs = n * (n - 1) / 2;          // total possible pairs
    const freq = new Map();                      // stores occurrences of (i - nums[i])
    let goodPairs = 0;

    for (let i = 0; i < n; i++) {
        const key = i - nums[i];                 // same key ⇒ good pair
        const prev = freq.get(key) || 0;         // how many earlier indices share this key
        goodPairs += prev;                       // each previous index forms a good pair with i
        freq.set(key, prev + 1);                 // update frequency
    }

    return totalPairs - goodPairs;                // bad pairs = total - good
}

function mergeSimilarItems(items1, items2) {
    const weightMap = new Map();                     // collect total weight per value
    for (const [value, weight] of items1) {
        weightMap.set(value, (weightMap.get(value) || 0) + weight);
    }
    for (const [value, weight] of items2) {
        weightMap.set(value, (weightMap.get(value) || 0) + weight);
    }
    const merged = [];                               // convert map to array
    for (const [value, totalWeight] of weightMap.entries()) {
        merged.push([value, totalWeight]);
    }
    merged.sort((a, b) => a[0] - b[0]);              // sort by value ascending
    return merged;
}

function largestLocal(grid) {
    const n = grid.length;                     // matrix dimension
    const result = new Array(n - 2);           // allocate answer rows
    for (let i = 0; i < n - 2; i++) {
        result[i] = new Array(n - 2);          // allocate answer columns
        for (let j = 0; j < n - 2; j++) {
            let maxVal = -Infinity;            // start with smallest possible
            // examine the 3×3 block whose top‑left corner is (i, j)
            for (let di = 0; di < 3; di++) {
                for (let dj = 0; dj < 3; dj++) {
                    const cur = grid[i + di][j + dj];
                    if (cur > maxVal) maxVal = cur;
                }
            }
            result[i][j] = maxVal;             // store the block maximum
        }
    }
    return result;
}

function reachableNodes(n, edges, restricted) {
    // build adjacency list
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }

    const restrictedSet = new Set(restricted);
    const visited = new Array(n).fill(false);
    const stack = [0];
    visited[0] = true;
    let reachableCount = 0;

    while (stack.length) {                     // explore reachable part of the tree
        const node = stack.pop();
        reachableCount++;
        for (const nb of adj[node]) {
            if (!visited[nb] && !restrictedSet.has(nb)) {
                visited[nb] = true;
                stack.push(nb);
            }
        }
    }
    return reachableCount;
}

function nodeWithHighestEdgeScore(edges) {
    const n = edges.length;
    const score = new Array(n).fill(0);          // accumulate edge scores

    for (let i = 0; i < n; i++) {                // each node contributes its label to its target
        score[edges[i]] += i;
    }

    let bestNode = 0;
    let bestScore = score[0];
    for (let i = 1; i < n; i++) {                // find max score, prefer smaller index on ties
        if (score[i] > bestScore) {
            bestScore = score[i];
            bestNode = i;
        }
    }
    return bestNode;
}

function longestIdealString(s, k) {
    const dp = new Array(26).fill(0);               // dp[i] = longest ideal subsequence ending with char i ('a'+i)

    for (let i = 0; i < s.length; i++) {
        const cur = s.charCodeAt(i) - 97;            // index of current character
        let best = 1;                                // subsequence consisting of only this character

        // try to extend any previous character within distance k
        for (let j = 0; j < 26; j++) {
            if (Math.abs(j - cur) <= k) {
                if (dp[j] + 1 > best) best = dp[j] + 1;
            }
        }
        if (best > dp[cur]) dp[cur] = best;          // keep the maximum for this ending character
    }

    // answer is the longest among all possible ending characters
    let ans = 0;
    for (let v of dp) if (v > ans) ans = v;
    return ans;
}

function countSpecialIntegers(n) {
    const fact = [1];
    for (let i = 1; i <= 10; i++) fact.push(fact[i - 1] * i);
    const perm = (m, k) => {
        if (k <= 0) return 1;
        if (k > m) return 0;
        return fact[m] / fact[m - k];
    };

    if (n <= 0) return 0;
    const s = String(n);
    const L = s.length;
    let total = 0;
    for (let l = 1; l < L; l++) total += 9 * perm(9, l - 1);

    const used = new Set();
    let brokeEarly = false;
    for (let i = 0; i < L; i++) {
        const cur = parseInt(s[i], 10);
        const start = i === 0 ? 1 : 0;
        for (let d = start; d < cur; d++) {
            if (used.has(d)) continue;
            const remaining = L - i - 1;
            const available = 10 - (i + 1);
            total += perm(available, remaining);
        }
        if (used.has(cur)) { brokeEarly = true; break; }
        used.add(cur);
    }
    if (!brokeEarly) total += 1;
    return total;
}

function shiftingLettersII(s, shifts) {
    const n = s.length;
    const diff = new Array(n + 1).fill(0);          // difference array

    // apply each operation to diff
    for (let i = 0; i < shifts.length; i++) {
        const [l, r, dir] = shifts[i];
        const val = dir === 1 ? 1 : -1;             // +1 forward, -1 backward
        diff[l] += val;
        diff[r + 1] -= val;                         // safe because diff has length n+1
    }

    // compute prefix sums and build result
    let cur = 0;
    const result = new Array(n);
    for (let i = 0; i < n; i++) {
        cur += diff[i];                              // current total shift
        const shift = ((cur % 26) + 26) % 26;        // normalize to [0,25]
        const code = s.charCodeAt(i) - 97;          // 0‑based alphabet index
        const newCode = (code + shift) % 26;
        result[i] = String.fromCharCode(newCode + 97);
    }
    return result.join('');
}

function constructSmallestNumber(pattern) {
    const n = pattern.length;
    const result = [];
    const stack = [];

    for (let i = 0; i <= n; i++) {
        stack.push(i + 1);                         // push next smallest number
        if (i === n || pattern[i] === 'I') {      // end of a decreasing block
            while (stack.length) {
                result.push(stack.pop());          // empty the stack
            }
        }
    }
    return result.join('');
}

function largestPalindromic(num) {
    const cnt = new Array(10).fill(0);
    for (let ch of num) cnt[ch.charCodeAt(0) - 48]++;

    let left = "";
    for (let d = 9; d >= 0; d--) {
        const pairs = Math.floor(cnt[d] / 2);
        if (pairs > 0) left += String(d).repeat(pairs);
        cnt[d] -= pairs * 2;
    }

    let middle = "";
    for (let d = 9; d >= 0; d--) {
        if (cnt[d] > 0) { middle = String(d); break; }
    }

    // if left is empty OR made up entirely of zeros (any non-zero digit pair would
    // always appear before zero-pairs in "left", since we build descending from 9),
    // a leading zero would result - fall back to just the middle digit (or "0")
    if (left === "" || left[0] === '0') {
        return middle === "0" || middle === "" ? "0" : middle;
    }

    const right = left.split('').reverse().join('');
    return left + middle + right;
}

function minRecolors(blocks, k) {
    var n = blocks.length;
    if (k === 0) return 0;                 // edge case
    if (k > n) return 0;                    // not possible, treat as 0

    var whiteInWindow = 0;
    // count whites in the first window
    for (var i = 0; i < k; i++) {
        if (blocks[i] === 'W') whiteInWindow++;
    }
    var minWhite = whiteInWindow;           // best window so far

    // slide the window across the string
    for (var i = k; i < n; i++) {
        if (blocks[i - k] === 'W') whiteInWindow--; // remove left char
        if (blocks[i] === 'W') whiteInWindow++;    // add right char
        if (whiteInWindow < minWhite) minWhite = whiteInWindow; // update answer
    }
    return minWhite;
}

function kSumArray(nums, k) {
  const n = nums.length;
  let base = 0;
  const absVals = new Array(n);
  for (let i = 0; i < n; i++) {
    const v = nums[i];
    if (v > 0) base += v;
    absVals[i] = Math.abs(v);
  }
  absVals.sort((a, b) => a - b);
  // min-heap implementation
  class MinHeap {
    constructor() {
      this.heap = [];
    }
    push(node) {
      const h = this.heap;
      h.push(node);
      let i = h.length - 1;
      while (i > 0) {
        const p = (i - 1) >> 1;
        if (h[p].sum <= h[i].sum) break;
        [h[p], h[i]] = [h[i], h[p]];
        i = p;
      }
    }
    pop() {
      const h = this.heap;
      const top = h[0];
      const last = h.pop();
      if (h.length) {
        h[0] = last;
        let i = 0;
        while (true) {
          let l = i * 2 + 1;
          let r = l + 1;
          if (l >= h.length) break;
          let smallest = l;
          if (r < h.length && h[r].sum < h[l].sum) smallest = r;
          if (h[i].sum <= h[smallest].sum) break;
          [h[i], h[smallest]] = [h[smallest], h[i]];
          i = smallest;
        }
      }
      return top;
    }
    get size() {
      return this.heap.length;
    }
  }
  const heap = new MinHeap();
  const results = [0]; // smallest reduction sums
  if (k === 1) return base;
  if (absVals.length > 0) heap.push({ sum: absVals[0], idx: 0 });
  while (results.length < k) {
    const node = heap.pop();
    const s = node.sum;
    const i = node.idx;
    results.push(s);
    if (i + 1 < n) {
      heap.push({ sum: s + absVals[i + 1], idx: i + 1 });
      heap.push({ sum: s - absVals[i] + absVals[i + 1], idx: i + 1 });
    }
  }
  const reduction = results[k - 1];
  return base - reduction;
}

function amountOfTime(root, start) {
    const adj = new Map();                     // adjacency list

    // ---------- build adjacency list (DFS) ----------
    function dfs(node) {
        if (!node) return;
        if (!adj.has(node.val)) adj.set(node.val, []);
        if (node.left) {
            if (!adj.has(node.left.val)) adj.set(node.left.val, []);
            adj.get(node.val).push(node.left.val);
            adj.get(node.left.val).push(node.val);
            dfs(node.left);
        }
        if (node.right) {
            if (!adj.has(node.right.val)) adj.set(node.right.val, []);
            adj.get(node.val).push(node.right.val);
            adj.get(node.right.val).push(node.val);
            dfs(node.right);
        }
    }
    dfs(root);

    // ---------- BFS from start, counting minutes ----------
    const queue = [start];
    const visited = new Set([start]);
    let minutes = -1;
    while (queue.length) {
        const size = queue.length;
        minutes++;
        for (let i = 0; i < size; i++) {
            const cur = queue.shift();
            for (const nb of (adj.get(cur) || [])) {
                if (!visited.has(nb)) {
                    visited.add(nb);
                    queue.push(nb);
                }
            }
        }
    }
    return minutes;
}

function removeStars(s) {
  const result = [];                     // stack to build the answer
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '*') {                  // main logic: handle star
      result.pop();                      // remove previous character
    } else {
      result.push(s[i]);                 // keep current character
    }
  }
  return result.join('');                // convert stack back to string
}

function longestSubsequenceWithLimitedSum(nums, queries) {
    // sort numbers to be able to take the smallest ones first
    const sorted = nums.slice().sort((a, b) => a - b);

    // build prefix sums of the sorted array
    const pref = new Array(sorted.length);
    for (let i = 0; i < sorted.length; i++) {
        pref[i] = (i ? pref[i - 1] : 0) + sorted[i];
    }

    const answer = [];

    // binary‑search the largest prefix sum ≤ query for each query
    for (const q of queries) {
        let lo = 0, hi = sorted.length - 1, best = -1;
        while (lo <= hi) {
            const mid = (lo + hi) >> 1;
            if (pref[mid] <= q) {
                best = mid;          // this size works, try to increase it
                lo = mid + 1;
            } else {
                hi = mid - 1;        // sum too large, shrink the size
            }
        }
        answer.push(best + 1);        // best = -1 → 0 elements
    }

    return answer;
}

function buildMatrix(k, rowConditions, colConditions) {
    // ---------- topological sort helper ----------
    function topoSort(edges) {
        const adj = Array.from({ length: k + 1 }, () => []);
        const indeg = new Array(k + 1).fill(0);
        for (const [u, v] of edges) {
            adj[u].push(v);
            indeg[v]++;                     // count incoming edges
        }
        const queue = [];
        for (let i = 1; i <= k; i++) if (indeg[i] === 0) queue.push(i);
        const order = [];
        while (queue.length) {
            const cur = queue.shift();
            order.push(cur);
            for (const nxt of adj[cur]) {
                if (--indeg[nxt] === 0) queue.push(nxt);
            }
        }
        return order.length === k ? order : null; // null → cycle
    }

    const rowOrder = topoSort(rowConditions);   // O(k + |rowConditions|)
    const colOrder = topoSort(colConditions);   // O(k + |colConditions|)
    if (!rowOrder || !colOrder) return [];       // cycle detected

    // ---------- map number → row / column ----------
    const rowPos = new Array(k + 1);
    const colPos = new Array(k + 1);
    for (let i = 0; i < k; i++) rowPos[rowOrder[i]] = i;
    for (let i = 0; i < k; i++) colPos[colOrder[i]] = i;

    // ---------- build answer matrix ----------
    const ans = Array.from({ length: k }, () => new Array(k).fill(0));
    for (let v = 1; v <= k; v++) {
        ans[rowPos[v]][colPos[v]] = v;
    }
    return ans;
}

function haveEqualSumSubarrays(nums) {
    if (nums.length < 2) return false;               // need at least one subarray of length 2
    const seenSums = new Set();                     // store sums of already‑seen subarrays
    for (let i = 0; i < nums.length - 1; i++) {
        const sum = nums[i] + nums[i + 1];           // sum of the current length‑2 subarray
        if (seenSums.has(sum)) return true;          // duplicate sum → answer is true
        seenSums.add(sum);
    }
    return false;
}

function isStrictlyPalindromic(n) {
  // All n ≥ 4 fail (base n‑2 gives "12"), and n < 4 has no valid bases → always false
  return false;
}

function maximumRows(mat, numSelect) {
    const m = mat.length, n = mat[0].length;
    const rowMasks = mat.map(row => row.reduce((acc,v,i)=>acc | (v<<i), 0));
    let best = 0;
    for (let mask = 0; mask < (1<<n); mask++) {
        let cnt=0, mm=mask; while(mm){cnt+=mm&1;mm>>=1;}
        if (cnt !== numSelect) continue;
        let covered = 0;
        for (const rm of rowMasks) if ((rm & mask) === rm) covered++;
        best = Math.max(best, covered);
    }
    return best;
}

function maxRobots(chargeTimes, runningCosts, budget) {
    const n = chargeTimes.length;
    let left = 0, sumRun = 0, best = 0;
    const deque = [];                     // stores indices, decreasing chargeTimes

    for (let right = 0; right < n; right++) {
        sumRun += runningCosts[right];                     // add new running cost

        // maintain decreasing deque for max chargeTime
        while (deque.length && chargeTimes[right] >= chargeTimes[deque[deque.length - 1]]) {
            deque.pop();
        }
        deque.push(right);

        // shrink window while cost exceeds budget
        while (left <= right) {
            const maxCharge = chargeTimes[deque[0]];
            const windowSize = right - left + 1;
            const cost = maxCharge + windowSize * sumRun;
            if (cost <= budget) break;                     // window fits, stop shrinking

            // remove leftmost element
            if (deque[0] === left) deque.shift();          // pop max if it leaves window
            sumRun -= runningCosts[left];
            left++;
        }

        best = Math.max(best, right - left + 1);           // update answer
    }
    return best;
}

function numberOfWaysToReachAPositionAfterExactlyKSteps(startPos, endPos, k) {
    const MOD = 1000000007n;
    const d = Math.abs(endPos - startPos);
    if (d > k || ((k - d) & 1)) return 0;

    const r = Math.floor((k + d) / 2);

    let factK = 1n, factR = 1n, factKR = 1n;
    for (let i = 1; i <= k; i++) {
        factK = (factK * BigInt(i)) % MOD;
        if (i === r) factR = factK;
        if (i === k - r) factKR = factK;
    }

    const modpow = (a, b) => {
        let res = 1n;
        a %= MOD;
        while (b > 0n) {
            if (b & 1n) res = (res * a) % MOD;
            a = (a * a) % MOD;
            b >>= 1n;
        }
        return res;
    };

    const invR = modpow(factR, MOD - 2n);
    const invKR = modpow(factKR, MOD - 2n);

    let ans = (factK * invR) % MOD;
    ans = (ans * invKR) % MOD;
    return Number(ans);
}

function longestNiceSubarray(nums) {
    let left = 0;           // left border of the sliding window
    let curMask = 0;        // bits currently occupied inside the window
    let best = 0;

    for (let right = 0; right < nums.length; right++) {
        // shrink window while the new element shares a bit with the window
        while ((curMask & nums[right]) !== 0) {
            curMask ^= nums[left]; // remove bits of the leftmost element
            left++;
        }
        curMask |= nums[right];    // add current element to the window
        if (right - left + 1 > best) best = right - left + 1;
    }
    return best;
}

function mostBooked(n, meetings) {
    function MinHeap(comp) { this.comp = comp; this.arr = []; }
    MinHeap.prototype.size = function () { return this.arr.length; };
    MinHeap.prototype.peek = function () { return this.arr[0]; };
    MinHeap.prototype.push = function (val) {
        const a = this.arr;
        a.push(val);
        let i = a.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (this.comp(a[p], a[i]) <= 0) break;
            [a[p], a[i]] = [a[i], a[p]];
            i = p;
        }
    };
    MinHeap.prototype.pop = function () {
        const a = this.arr;
        if (!a.length) return undefined;
        const top = a[0];
        const last = a.pop();
        if (a.length) {
            a[0] = last;
            let i = 0;
            while (true) {
                let l = i * 2 + 1, r = i * 2 + 2, smallest = i;
                if (l < a.length && this.comp(a[l], a[smallest]) < 0) smallest = l;
                if (r < a.length && this.comp(a[r], a[smallest]) < 0) smallest = r;
                if (smallest === i) break;
                [a[i], a[smallest]] = [a[smallest], a[i]];
                i = smallest;
            }
        }
        return top;
    };

    meetings.sort((a, b) => a[0] - b[0]);

    var free = new MinHeap((a, b) => a - b);
    for (let i = 0; i < n; i++) free.push(i);

    // tie-break by room index when finish times match - required by the problem's
    // own rule that ties always go to the lowest-numbered room
    var busy = new MinHeap((a, b) => a[0] - b[0] || a[1] - b[1]);

    var cnt = new Array(n).fill(0);

    for (let [start, end] of meetings) {
        while (busy.size() && busy.peek()[0] <= start) {
            const [, room] = busy.pop();
            free.push(room);
        }

        if (free.size()) {
            const room = free.pop();
            cnt[room]++;
            busy.push([end, room]);
        } else {
            const [finish, room] = busy.pop();
            cnt[room]++;
            const duration = end - start;
            busy.push([finish + duration, room]);
        }
    }

    let best = 0;
    for (let i = 1; i < n; i++) if (cnt[i] > cnt[best]) best = i;
    return best;
}

function isGoodArray(nums) {
  // Calculate the greatest common divisor of all numbers in the array
  function gcd(a, b) {
    if (b === 0) return a;
    return gcd(b, a % b);
  }
  let result = nums[0];
  for (let i = 1; i < nums.length; i++) {
    // Update the result with the gcd of the current result and the next number
    result = gcd(result, nums[i]);
  }
  // If the gcd is 1, the array is good
  return result === 1;
}

function removeSubfolders(folder) {
    // Sort the folders to ensure parent folders come before sub-folders
    folder.sort();
    let result = [];
    for (let i = 0; i < folder.length; i++) {
        // Check if the current folder is a sub-folder of the last folder in the result
        if (result.length === 0 || !folder[i].startsWith(result[result.length - 1] + '/')) {
            result.push(folder[i]);
        }
    }
    return result;
}

function minimumSwap(s1, s2) {
    let xy = 0, yx = 0; // xy: positions where s1='x' and s2='y'; yx: the reverse
    for (let i = 0; i < s1.length; i++) {
        if (s1[i] !== s2[i]) {
            if (s1[i] === 'x') xy++; else yx++;
        }
    }
    if ((xy + yx) % 2 === 1) return -1;
    // each matched "xy & xy" pair takes 1 swap, each "yx & yx" pair takes 1 swap;
    // one leftover xy plus one leftover yx (when both counts are odd) takes 2 swaps
    return Math.floor(xy / 2) + Math.floor(yx / 2) + (xy % 2) * 2;
}

function minRemoveToMakeValid(s) {
    // Initialize a stack to store indices of opening parentheses
    var stack = [];
    // Initialize a set to store indices of parentheses to be removed
    var removeSet = new Set();
    // Iterate over the string to find matching parentheses
    for (var i = 0; i < s.length; i++) {
        // If an opening parenthesis is found, push its index onto the stack
        if (s[i] === '(') {
            stack.push(i);
        } 
        // If a closing parenthesis is found
        else if (s[i] === ')') {
            // If the stack is empty, it means there's no matching opening parenthesis, so add the index to the remove set
            if (stack.length === 0) {
                removeSet.add(i);
            } 
            // If the stack is not empty, pop the index of the matching opening parenthesis from the stack
            else {
                stack.pop();
            }
        }
    }
    // Add the indices of the remaining opening parentheses in the stack to the remove set
    while (stack.length > 0) {
        removeSet.add(stack.pop());
    }
    // Initialize an empty result string
    var result = '';
    // Iterate over the string again to build the result string
    for (var i = 0; i < s.length; i++) {
        // If the current index is not in the remove set, add the character to the result string
        if (!removeSet.has(i)) {
            result += s[i];
        }
    }
    // Return the result string
    return result;
}

function oddCells(m, n, indices) {
    // Initialize a matrix with all 0's
    var matrix = Array(m).fill(0).map(() => Array(n).fill(0));

    // For each location in indices, increment the corresponding row and column in the matrix
    for (var i = 0; i < indices.length; i++) {
        var row = indices[i][0];
        var col = indices[i][1];
        // Increment the row
        for (var j = 0; j < n; j++) {
            matrix[row][j]++;
        }
        // Increment the column
        for (var j = 0; j < m; j++) {
            matrix[j][col]++;
        }
    }

    // Count the number of odd-valued cells in the matrix
    var count = 0;
    for (var i = 0; i < m; i++) {
        for (var j = 0; j < n; j++) {
            // Check if the cell value is odd
            if (matrix[i][j] % 2 !== 0) {
                count++;
            }
        }
    }

    return count;
}

