function secondsToRemoveOccurrences(s) {
  let zeros = 0;
  let seconds = 0;
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '0') {
      zeros++;
    } else if (zeros > 0) {
      seconds = Math.max(seconds + 1, zeros);
    }
  }
  return seconds;
}

function sortPeople(names, heights) {
  // Create a 2D array to store names and heights, then sort it in descending order by height
  var people = names.map((name, index) => [name, heights[index]]);
  people.sort((a, b) => b[1] - a[1]);
  // Return the sorted names
  return people.map(person => person[0]);
}

function countCommonFactors(a, b) {
  function gcd(a, b) {
    if (b === 0) return a;
    return gcd(b, a % b);
  }
  const g = gcd(a, b);
  let count = 0;
  for (let i = 1; i <= g; i++) {
    if (a % i === 0 && b % i === 0) count++;
  }
  return count;
}

