function maximumSum(grid) {
    let maxSum = -Infinity; // initialize maxSum as negative infinity
    let rows = grid.length; 
    let cols = grid[0].length;
    // calculate the sum for each possible hourglass in the grid
    for (let i = 0; i < rows - 2; i++) {
        for (let j = 0; j < cols - 2; j++) {
            // calculate the sum of the current hourglass
            let sum = grid[i][j] + grid[i][j + 1] + grid[i][j + 2] + grid[i + 1][j + 1] + grid[i + 2][j] + grid[i + 2][j + 1] + grid[i + 2][j + 2];
            // update maxSum if the current sum is larger
            maxSum = Math.max(maxSum, sum);
        }
    }
    return maxSum;
}

function numberOfPairsSatisfyingInequality(nums1, nums2, diff) {
    let count = 0; // Initialize count of pairs
    for (let i = 0; i < nums1.length; i++) { // Iterate over each element in nums1
        for (let j = i + 1; j < nums1.length; j++) { // Iterate over each element in nums1 starting from i + 1
            // Check if the condition is satisfied: nums1[i] - nums1[j] <= nums2[i] - nums2[j] + diff
            if (nums1[i] - nums1[j] <= nums2[i] - nums2[j] + diff) {
                count++; // Increment count if condition is satisfied
            }
        }
    }
    return count; // Return the total count of pairs
}

function longestSubarray(nums) {
  let maxLength = 0;
  let maxAnd = 0;
  // calculate the maximum possible bitwise AND
  for (let i = 0; i < nums.length; i++) {
    let and = nums[i];
    for (let j = i; j < nums.length; j++) {
      and = and & nums[j];
      // update maxAnd if a larger bitwise AND is found
      if (and > maxAnd) {
        maxAnd = and;
      }
    }
  }
  // find the longest subarray with the maximum bitwise AND
  for (let i = 0; i < nums.length; i++) {
    let and = nums[i];
    for (let j = i; j < nums.length; j++) {
      and = and & nums[j];
      // check if the running AND of the subarray equals maxAnd
      if (and === maxAnd) {
        // update maxLength if a longer subarray is found
        maxLength = Math.max(maxLength, j - i + 1);
      }
    }
  }
  return maxLength;
}

function goodIndices(nums, k) {
    let n = nums.length;
    let result = [];
    // Calculate prefix sum for non-increasing order
    let left = new Array(n).fill(1);
    for (let i = 1; i < n; i++) {
        // If current element is less than or equal to previous element, increase count
        if (nums[i] <= nums[i - 1]) left[i] = left[i - 1] + 1;
    }
    // Calculate prefix sum for non-decreasing order
    let right = new Array(n).fill(1);
    for (let i = n - 2; i >= 0; i--) {
        // If current element is less than or equal to next element, increase count
        if (nums[i] <= nums[i + 1]) right[i] = right[i + 1] + 1;
    }
    // Check each index for good indices
    for (let i = k; i < n - k; i++) {
        // If left and right prefix sums are greater than or equal to k, add index to result
        if (left[i] >= k && right[i] >= k) result.push(i);
    }
    return result;
}

function canEqualizeWord(word) {
  // Create a frequency map of the word
  var frequencyMap = {};
  for (var i = 0; i < word.length; i++) {
    // Count the frequency of each character
    frequencyMap[word[i]] = (frequencyMap[word[i]] || 0) + 1;
  }

  var counts = Object.values(frequencyMap);
  // Find the unique frequencies in the word
  var uniqueFrequencies = new Set(counts);

  // If there's only one unique frequency, we can equalize only if removing
  // one letter makes it vanish (count === 1) or there's only one letter type
  if (uniqueFrequencies.size === 1) {
    var c = [...uniqueFrequencies][0];
    return c === 1 || Object.keys(frequencyMap).length === 1;
  }

  // If there are more than 2 unique frequencies, we can't equalize the word
  if (uniqueFrequencies.size > 2) return false;

  // Get the two unique frequencies, sorted ascending
  var frequencies = Array.from(uniqueFrequencies).sort((a, b) => a - b);

  // If the larger frequency is one more than the smaller frequency, and only
  // one letter has the larger frequency
  if (frequencies[1] - frequencies[0] === 1 && counts.filter(c => c === frequencies[1]).length === 1) return true;

  // If the smaller frequency is one, and only one letter has that frequency
  if (frequencies[0] === 1 && counts.filter(c => c === frequencies[0]).length === 1) return true;

  // If none of the above conditions are met, we can't equalize the word
  return false;
}

function numberOfGoodPaths(vals, edges) {
    let n = vals.length;
    let uf = Array(n).fill(0).map((_, i) => i);
    let sz = Array(n).fill(1);
    let count = Array(n).fill(0).map((_, i) => ({ [vals[i]]: 1 }));
    let ans = n;

    edges = edges.slice();
    edges.sort((a, b) => Math.max(vals[a[0]], vals[a[1]]) - Math.max(vals[b[0]], vals[b[1]]));

    // Iterate over the sorted edges and union the nodes
    for (let [u, v] of edges) {
        let p1 = find(uf, u), p2 = find(uf, v);
        if (p1 !== p2) {
            // A good path completed exactly at this merge must have BOTH
            // endpoints equal to this edge's max value - that is the
            // threshold at which these two components first became
            // connected, so only nodes at that exact value are valid
            let maxVal = Math.max(vals[u], vals[v]);
            let c1 = count[p1], c2 = count[p2];
            ans += (c1[maxVal] || 0) * (c2[maxVal] || 0);
            // Union the two sets
            uf[p2] = p1;
            sz[p1] += sz[p2];
            for (let k in c2) {
                count[p1][k] = (count[p1][k] || 0) + (c2[k] || 0);
            }
        }
    }

    return ans;

    // Helper function to find the parent of a node
    function find(uf, x) {
        if (uf[x] !== x) uf[x] = find(uf, uf[x]);
        return uf[x];
    }
}

function xorAllPairings(nums1, nums2) {
    // calculate the XOR of all elements in nums1
    let xorNums1 = 0;
    for (let num of nums1) {
        xorNums1 ^= num; // XOR of all elements in nums1
    }

    // calculate the XOR of all elements in nums2
    let xorNums2 = 0;
    for (let num of nums2) {
        xorNums2 ^= num; // XOR of all elements in nums2
    }

    // each element of nums1 is paired with every element of nums2, so it
    // contributes to the final XOR only if it's XORed an odd number of
    // times overall (i.e. nums2.length is odd), and vice versa
    let result = 0;
    if (nums2.length % 2 === 1) result ^= xorNums1;
    if (nums1.length % 2 === 1) result ^= xorNums2;
    return result;
}

function minimizeXor(num1, num2) {
    // calculate the number of set bits in num2
    let setBitsInNum2 = countSetBits(num2);
    // calculate the number of set bits in num1
    let setBitsInNum1 = countSetBits(num1);
    // if the number of set bits in num1 is equal to the number of set bits in num2, return num1
    if (setBitsInNum1 === setBitsInNum2) return num1;
    // otherwise, return the smallest number with the same number of set bits as num2
    return smallestNumberWithSetBits(setBitsInNum2);
}

// helper function to count the number of set bits in a number
function countSetBits(num) {
    let count = 0;
    while (num > 0) {
        // if the least significant bit is 1, increment the count
        count += num & 1;
        // right shift the number by 1 bit
        num >>= 1;
    }
    return count;
}

// helper function to find the smallest number with a given number of set bits
function smallestNumberWithSetBits(setBits) {
    let result = 0;
    for (let i = 0; i < setBits; i++) {
        // left shift 1 by i bits and add it to the result
        result += 1 << i;
    }
    return result;
}

function maximumDeletions(s) {
    const n = s.length;
    // lcp[i][j] = length of the longest common prefix of s[i:] and s[j:]
    const lcp = Array.from({length: n + 1}, () => new Array(n + 1).fill(0));
    for (let i = n - 1; i >= 0; i--) {
        for (let j = n - 1; j >= 0; j--) {
            if (s[i] === s[j]) lcp[i][j] = lcp[i + 1][j + 1] + 1;
        }
    }
    // dp[i] = max operations to fully delete s starting from index i
    const dp = new Array(n + 1).fill(0);
    for (let i = n - 1; i >= 0; i--) {
        // fallback: delete the entire remaining suffix in one operation
        let best = 1;
        const maxL = Math.floor((n - i) / 2);
        for (let L = 1; L <= maxL; L++) {
            // s[i:i+L] === s[i+L:i+2L] iff their common prefix reaches at least L
            if (lcp[i][i + L] >= L) best = Math.max(best, 1 + dp[i + L]);
        }
        dp[i] = best;
    }
    return dp[0];
}

function countTime(time) {
    // initialize count of valid times to 0
    let count = 0;
    // loop through all possible hours (0-23)
    for (let hour = 0; hour < 24; hour++) {
        // convert hour to string and pad with leading zero if necessary
        let hourStr = hour.toString().padStart(2, '0');
        // loop through all possible minutes (0-59)
        for (let minute = 0; minute < 60; minute++) {
            // convert minute to string and pad with leading zero if necessary
            let minuteStr = minute.toString().padStart(2, '0');
            // create time string
            let currentTime = hourStr + ":" + minuteStr;
            // initialize flag to true
            let isValid = true;
            // loop through each character in time string
            for (let i = 0; i < 5; i++) {
                // if character is '?' it's valid, otherwise it must match the current time
                if (time[i] !== '?' && time[i] !== currentTime[i]) {
                    // if it doesn't match, set flag to false and break loop
                    isValid = false;
                    break;
                }
            }
            // if time is valid, increment count
            if (isValid) {
                count++;
            }
        }
    }
    // return count of valid times
    return count;
}

function findMaxK(nums) {
  // Create a set for O(1) lookup time
  let numSet = new Set(nums);
  let maxK = -1;
  // Iterate over the array to find the largest positive integer k
  for (let num of nums) {
    // Check if the negative of the current number exists in the set
    if (num > 0 && numSet.has(-num)) {
      // Update maxK if the current number is larger
      maxK = Math.max(maxK, num);
    }
  }
  return maxK;
}

function countDistinctIntegers(nums) {
  // Create a set to store unique integers
  let uniqueIntegers = new Set(nums);
  // Iterate over each integer in the input array
  for (let num of nums) {
    // Reverse the digits of the current integer
    let reversedNum = parseInt(num.toString().split('').reverse().join(''));
    // Add the reversed integer to the set
    uniqueIntegers.add(reversedNum);
  }
  // Return the number of distinct integers
  return uniqueIntegers.size;
}

function sumOfNumberAndItsReverse(num) {
  // iterate through all possible non-negative integers
  for (let i = 0; i <= num; i++) {
    // calculate the reverse of the current integer
    let reverse = 0, temp = i;
    while (temp > 0) {
      // append the last digit of temp to reverse
      reverse = reverse * 10 + temp % 10;
      temp = Math.floor(temp / 10);
    }
    // check if the sum of the current integer and its reverse equals num
    if (i + reverse === num) return true;
  }
  // if no such integer is found, return false
  return false;
}

function rangeProductQueriesOfPowers(n, queries) {
    // Decompose n into its binary representation from the least significant
    // bit upward, so powers ends up sorted ascending as the problem expects
    let powers = [];
    let temp = n;
    for (let i = 0; temp > 0; i++) {
        if (temp & 1) powers.push(1 << i);
        temp = temp >> 1;
    }

    // Calculate the product of all powers[j] with lefti <= j <= righti for each query
    let results = [];
    for (let query of queries) {
        let left = query[0];
        let right = query[1];
        let product = 1;
        for (let i = left; i <= right; i++) {
            product *= powers[i];
        }
        results.push(product);
    }

    return results;
}

function countSubarrays(nums, minK, maxK) {
    let result = 0;
    // left = index of the most recent out-of-range element (subarrays must
    // start strictly after it); minIndex/maxIndex = most recent occurrence
    // of minK/maxK seen so far
    let left = -1;
    let minIndex = -1, maxIndex = -1;
    for (let right = 0; right < nums.length; right++) {
        if (nums[right] < minK || nums[right] > maxK) {
            left = right;
        } else {
            if (nums[right] === minK) minIndex = right;
            if (nums[right] === maxK) maxIndex = right;
        }
        // every start position strictly between left and min(minIndex,maxIndex)
        // (inclusive) gives a valid fixed-bound subarray ending at right
        result += Math.max(0, Math.min(minIndex, maxIndex) - left);
    }
    return result;
}

function haveConflict(event1, event2) {
  // Convert time to minutes and compare the start and end times of both events to check for conflict
  function timeToMinutes(time) {
    var parts = time.split(':');
    return parseInt(parts[0]) * 60 + parseInt(parts[1]);
  }
  var start1 = timeToMinutes(event1[0]), end1 = timeToMinutes(event1[1]);
  var start2 = timeToMinutes(event2[0]), end2 = timeToMinutes(event2[1]);
  return Math.max(start1, start2) <= Math.min(end1, end2);
}

function subarrayGCD(nums, k) {
  function gcd(a, b) {
    // calculate the greatest common divisor of two numbers using Euclidean algorithm
    if (b === 0) return a;
    return gcd(b, a % b);
  }

  let count = 0;
  for (let i = 0; i < nums.length; i++) {
    let currentGcd = nums[i];
    for (let j = i; j < nums.length; j++) {
      // update the gcd of the current subarray
      currentGcd = gcd(currentGcd, nums[j]);
      if (currentGcd === k) {
        // if the gcd of the current subarray is k, increment the count
        count++;
      }
    }
  }
  return count;
}

function componentValue(nums, edges) {
    // Create an adjacency list to represent the tree
    let tree = Array(nums.length).fill(0).map(() => []);
    for (let edge of edges) {
        tree[edge[0]].push(edge[1]);
        tree[edge[1]].push(edge[0]);
    }

    // Calculate the total sum of all node values
    let totalSum = nums.reduce((a, b) => a + b, 0);
    const maxVal = Math.max(...nums);

    // Try candidate target sums smallest-first, starting from the largest
    // single node's value (a smaller target can never work); the first
    // target that yields a valid partition gives the most components
    let maxEdges = 0;
    for (let target = maxVal; target <= totalSum; target++) {
        if (totalSum % target !== 0) continue;
        const res = dfs(0, -1, target);
        if (res === 0) {
            maxEdges = Math.max(maxEdges, totalSum / target - 1);
            break;
        }
    }
    return maxEdges;

    // Walk the tree with a parent pointer so a completed subtree (sum ===
    // target) can be CUT OFF - it contributes 0 to its parent instead of
    // merging into one ever-growing total
    function dfs(node, parent, target) {
        let sum = nums[node];
        for (let child of tree[node]) {
            if (child === parent) continue;
            const s = dfs(child, node, target);
            if (s === -1) return -1;
            sum += s;
        }
        if (sum > target) return -1;
        if (sum === target) return 0; // cut this edge off from its parent
        return sum;
    }
}

function minimizeArray(nums) {
    // The allowed operation only moves value from a LATER index to an
    // EARLIER one (pick i where nums[i] <= nums[i+1], shift 1 unit from
    // i+1 down to i) - value never flows rightward. So the achievable
    // minimum maximum isn't bounded by the whole array's average; it's
    // bounded by the average of every PREFIX (since a prefix can never pull
    // value in from later elements), and we must satisfy the worst one.
    let prefixSum = 0;
    let ans = 0;
    for (let i = 0; i < nums.length; i++) {
        prefixSum += nums[i];
        ans = Math.max(ans, Math.ceil(prefixSum / (i + 1)));
    }
    return ans;
}

function minOperations(nums, target) {
    let numsCopy = nums.slice();
    let targetCopy = target.slice();

    // Split into odd/even groups first: each operation changes one element
    // by +2 and another by -2, so every element's parity never changes
    // across any number of operations, meaning a nums value can only ever
    // end up matching a target value that shares its parity.
    const numsOdd = numsCopy.filter(x => x % 2 !== 0).sort((a, b) => a - b);
    const numsEven = numsCopy.filter(x => x % 2 === 0).sort((a, b) => a - b);
    const targetOdd = targetCopy.filter(x => x % 2 !== 0).sort((a, b) => a - b);
    const targetEven = targetCopy.filter(x => x % 2 === 0).sort((a, b) => a - b);

    let increase = 0;
    for (let i = 0; i < numsOdd.length; i++) {
        if (targetOdd[i] > numsOdd[i]) increase += targetOdd[i] - numsOdd[i];
    }
    for (let i = 0; i < numsEven.length; i++) {
        if (targetEven[i] > numsEven[i]) increase += targetEven[i] - numsEven[i];
    }

    // Total operations = total increase needed / 2 (each op supplies one
    // unit of increase and one unit of decrease, and total increase always
    // equals total decrease since overall array sum is invariant)
    return increase / 2;
}

function minCost(nums, cost) {
  // Sort (nums,cost) pairs TOGETHER - sorting nums alone desyncs it from
  // cost, so cost[i] would no longer refer to the same element as nums[i].
  // The optimal target isn't the plain median but the WEIGHTED median: the
  // nums value at which cumulative cost first reaches half of total cost.
  const pairs = nums.map((v, i) => [v, cost[i]]).sort((a, b) => a[0] - b[0]);
  const totalCost = cost.reduce((a, b) => a + b, 0);
  let acc = 0;
  let median = pairs[0][0];
  for (const [v, c] of pairs) {
    acc += c;
    if (acc * 2 >= totalCost) { median = v; break; }
  }

  let totalMinCost = 0;
  for (let i = 0; i < nums.length; i++) {
    totalMinCost += Math.abs(nums[i] - median) * cost[i];
  }
  return totalMinCost;
}

function pathsDivisible(grid, k) {
    const MOD = 1_000_000_007;
    const m = grid.length, n = grid[0].length;

    // dpPrev[j][r] – counts for the previous row (initially all zeros)
    let dpPrev = Array.from({ length: n }, () => new Array(k).fill(0));

    for (let i = 0; i < m; i++) {
        // dpCurr[j][r] – counts for the current row
        const dpCurr = Array.from({ length: n }, () => new Array(k).fill(0));

        for (let j = 0; j < n; j++) {
            const valMod = grid[i][j] % k;          // value of the cell modulo k
            const cur = dpCurr[j];                  // reference for speed

            if (i === 0 && j === 0) {               // start cell
                cur[valMod] = 1;
                continue;
            }

            // from the cell above (i‑1, j)
            if (i > 0) {
                const top = dpPrev[j];
                for (let r = 0; r < k; r++) {
                    const cnt = top[r];
                    if (cnt) {
                        const nr = (r + valMod) % k;
                        cur[nr] = (cur[nr] + cnt) % MOD;
                    }
                }
            }

            // from the cell on the left (i, j‑1)
            if (j > 0) {
                const left = dpCurr[j - 1];
                for (let r = 0; r < k; r++) {
                    const cnt = left[r];
                    if (cnt) {
                        const nr = (r + valMod) % k;
                        cur[nr] = (cur[nr] + cnt) % MOD;
                    }
                }
            }
        }

        dpPrev = dpCurr; // move to next row
    }

    return dpPrev[n - 1][0]; // remainder 0 at destination
}

function robotPrint(s) {
    const n = s.length;
    const minSuffix = new Array(n);
    // compute smallest character for every suffix of s
    for (let i = n - 1; i >= 0; i--) {
        if (i === n - 1) minSuffix[i] = s[i];
        else minSuffix[i] = s[i] < minSuffix[i + 1] ? s[i] : minSuffix[i + 1];
    }

    const stack = [];
    let result = '';

    for (let i = 0; i < n; i++) {
        stack.push(s[i]);                     // move char from s to t
        // pop while top of t is not larger than the smallest remaining char in s
        while (stack.length && (i === n - 1 || stack[stack.length - 1] <= minSuffix[i + 1])) {
            result += stack.pop();
        }
    }

    // empty the remaining stack
    while (stack.length) result += stack.pop();

    return result;
}

function checkDistances(s, distance) {
    // store first index of each letter; -1 means not seen yet
    const firstIdx = new Array(26).fill(-1);
    for (let i = 0; i < s.length; i++) {
        const code = s.charCodeAt(i) - 97;          // letter index 0‑25
        if (firstIdx[code] === -1) {
            firstIdx[code] = i;                     // first occurrence
        } else {
            const between = i - firstIdx[code] - 1; // letters between the two occurrences
            if (between !== distance[code]) return false; // mismatch → not well‑spaced
        }
    }
    return true;
}

function oddStringDifference(words) {
  // Create a hash map to store the difference arrays as keys and their corresponding strings as values
  var differenceMap = {};
  for (var i = 0; i < words.length; i++) {
    var difference = [];
    for (var j = 0; j < words[i].length - 1; j++) {
      // Calculate the difference between each pair of adjacent characters
      difference.push(words[i].charCodeAt(j + 1) - words[i].charCodeAt(j));
    }
    // Convert the difference array to a string to use as a key in the hash map
    var key = difference.join(',');
    if (key in differenceMap) {
      differenceMap[key].push(words[i]);
    } else {
      differenceMap[key] = [words[i]];
    }
  }
  // Find the key with only one string in its value array
  for (var key in differenceMap) {
    // If a key has only one string, it is the odd string out
    if (differenceMap[key].length === 1) {
      return differenceMap[key][0];
    }
  }
}

function averageOfEvenNumbersDivisibleByThree(nums) {
  let sum = 0, count = 0; // initialize sum and count variables
  for (let num of nums) { // iterate over the input array
    if (num % 2 === 0 && num % 3 === 0) { // check if the number is even and divisible by 3
      sum += num; // add the number to the sum
      count++; // increment the count
    }
  }
  return count === 0 ? 0 : Math.floor(sum / count); // return the average, or 0 if no numbers satisfy the condition
}

function makeIntegerBeautiful(n, target) {
    // calculate the sum of digits of n
    let digitSum = getDigitSum(n);
    // if the sum of digits is already less than or equal to target, return 0
    if (digitSum <= target) return 0;
    // initialize the minimum non-negative integer x
    let x = 0;
    // keep adding 1 to x until n + x is beautiful
    while (true) {
        // calculate the sum of digits of n + x
        let newDigitSum = getDigitSum(n + x);
        // if the sum of digits is less than or equal to target, return x
        if (newDigitSum <= target) return x;
        // otherwise, increment x by 1
        x++;
    }
}

// helper function to calculate the sum of digits of a number
function getDigitSum(num) {
    // initialize the sum of digits
    let sum = 0;
    // keep adding the last digit to the sum and removing the last digit from the number
    while (num > 0) {
        // add the last digit to the sum
        sum += num % 10;
        // remove the last digit from the number
        num = Math.floor(num / 10);
    }
    // return the sum of digits
    return sum;
}

function mostPopularCreator(creators, ids, views) {
    // Create a hash table to store the total views for each creator
    let creatorViews = {};
    for (let i = 0; i < creators.length; i++) {
        if (!creatorViews[creators[i]]) creatorViews[creators[i]] = 0;
        creatorViews[creators[i]] += views[i];
    }

    // Find the maximum total views
    let maxViews = Math.max(...Object.values(creatorViews));

    // Create a hash table to store the most viewed video for each creator
    let mostViewedVideos = {};
    for (let i = 0; i < creators.length; i++) {
        // If the creator's video has the maximum views, update the most viewed video
        if (creatorViews[creators[i]] === maxViews) {
            if (!mostViewedVideos[creators[i]]) mostViewedVideos[creators[i]] = { id: ids[i], views: views[i] };
            else if (views[i] > mostViewedVideos[creators[i]].views) mostViewedVideos[creators[i]] = { id: ids[i], views: views[i] };
            else if (views[i] === mostViewedVideos[creators[i]].views && ids[i] < mostViewedVideos[creators[i]].id) mostViewedVideos[creators[i]] = { id: ids[i], views: views[i] };
        }
    }

    // Create the result array
    let result = [];
    for (let creator in mostViewedVideos) {
        result.push([creator, mostViewedVideos[creator].id]);
    }

    return result;
}

function secondGreaterElement(nums) {
    const n = nums.length;
    const result = new Array(n).fill(-1);
    const stack = [];       // indices waiting for a FIRST greater element
    const secondStack = []; // indices that already found their first greater, waiting for a second

    for (let i = 0; i < n; i++) {
        while (secondStack.length > 0 && nums[i] > nums[secondStack[secondStack.length - 1]]) {
            result[secondStack.pop()] = nums[i];
        }
        const temp = [];
        while (stack.length > 0 && nums[i] > nums[stack[stack.length - 1]]) {
            temp.push(stack.pop());
        }
        // preserve the correct (still-decreasing) order when moving into secondStack
        while (temp.length > 0) {
            secondStack.push(temp.pop());
        }
        stack.push(i);
    }
    return result;
}

function twoEditWords(queries, dictionary) {
    function isWithinTwoEdits(word1, word2) {
        // count the number of different characters between two words
        let diffCount = 0;
        for (let i = 0; i < word1.length; i++) {
            if (word1[i] !== word2[i]) diffCount++;
            if (diffCount > 2) return false;
        }
        return true;
    }

    let result = [];
    for (let query of queries) {
        // check if any word in dictionary is within two edits of the current query
        for (let dictWord of dictionary) {
            if (isWithinTwoEdits(query, dictWord)) {
                result.push(query);
                break;
            }
        }
    }
    return result;
}

function maximumSum(nums, k) {
    let maxSum = 0; 
    for (let i = 0; i <= nums.length - k; i++) {
        let set = new Set(); // create a set to store unique elements in the current subarray
        let sum = 0;
        for (let j = i; j < i + k; j++) {
            set.add(nums[j]); // add each element to the set
            sum += nums[j]; // calculate the sum of the current subarray
        }
        if (set.size === k) { // if the set size is equal to k, it means all elements are unique
            maxSum = Math.max(maxSum, sum); // update the maxSum
        }
    }
    return maxSum; // return the maxSum
}

function applyOperations(nums) {
  // iterate through the array and apply operations
  for (let i = 0; i < nums.length - 1; i++) {
    // check if the current element is equal to the next one
    if (nums[i] === nums[i + 1]) {
      // if they are equal, multiply the current element by 2 and set the next one to 0
      nums[i] *= 2;
      nums[i + 1] = 0;
    }
  }
  // use two pointers to shift all the 0's to the end of the array
  let left = 0;
  for (let right = 0; right < nums.length; right++) {
    // if the right pointer points to a non-zero element, swap it with the left pointer
    if (nums[right] !== 0) {
      // swap the elements
      let temp = nums[left];
      nums[left] = nums[right];
      nums[right] = temp;
      // move the left pointer to the next position
      left++;
    }
  }
  return nums;
}

function destroyTargets(nums, space) {
    // Create a hash map to store the count of targets for each possible seed value
    let countMap = {};
    for (let num of nums) {
        let seed = num % space;
        countMap[seed] = (countMap[seed] || 0) + 1;
    }

    let maxCount = 0;
    let minSeed = Infinity;
    for (let seed in countMap) {
        if (countMap[seed] > maxCount) {
            maxCount = countMap[seed];
            minSeed = Infinity;
            for (let num of nums) {
                if (num % space == seed) {
                    minSeed = Math.min(minSeed, num);
                }
            }
        } else if (countMap[seed] === maxCount) {
            // TIE in count: this seed group destroys just as many targets,
            // so it's still a candidate - must check whether it contains a
            // smaller minimum value than the current best
            for (let num of nums) {
                if (num % space == seed) {
                    minSeed = Math.min(minSeed, num);
                }
            }
        }
    }
    return minSeed;
}

function treeQueries(root, queries) {
    // depth[v] = depth of node with value v; maxDepthBelow[v] = max depth reachable
    // within the subtree rooted at v (including v itself)
    const depth = {};
    const maxDepthBelow = {};
    function dfs(node, d) {
        if (!node) return d - 1;
        depth[node.val] = d;
        const left = dfs(node.left, d + 1);
        const right = dfs(node.right, d + 1);
        maxDepthBelow[node.val] = Math.max(d, left, right);
        return maxDepthBelow[node.val];
    }
    dfs(root, 0);

    // second pass: for each node, track the best depth achievable using only
    // nodes OUTSIDE its own subtree (ancestors + sibling subtrees), passed down
    // from the parent and updated with the sibling's subtree depth at each step
    const ans = {};
    function solve(node, d, maxAbove) {
        if (!node) return;
        ans[node.val] = maxAbove;
        const effective = Math.max(maxAbove, d); // node itself remains if a descendant is removed
        const leftVal = node.left ? maxDepthBelow[node.left.val] : -1;
        const rightVal = node.right ? maxDepthBelow[node.right.val] : -1;
        solve(node.left, d + 1, Math.max(effective, rightVal));
        solve(node.right, d + 1, Math.max(effective, leftVal));
    }
    solve(root, 0, -1);
    return queries.map(q => ans[q]);
}

function minimumTotalDistance(robot, factory) {
    // Sort robots and factories by their positions
    robot.sort((a, b) => a - b);
    factory.sort((a, b) => a[0] - b[0]);

    // Initialize variables to store the total distance and the current factory index
    let totalDistance = 0;
    let factoryIndex = 0;

    // Iterate over the robots
    for (let i = 0; i < robot.length; i++) {
        // If the current robot can be repaired by the current factory, calculate the distance
        if (factoryIndex < factory.length && factory[factoryIndex][1] > 0) {
            // Calculate the distance between the robot and the factory
            totalDistance += Math.abs(robot[i] - factory[factoryIndex][0]);
            // Decrement the limit of the current factory
            factory[factoryIndex][1]--;
            // If the limit of the current factory is 0, move to the next factory
            if (factory[factoryIndex][1] === 0) {
                factoryIndex++;
            }
        } else {
            // If the current robot cannot be repaired by the current factory, move to the next factory
            factoryIndex++;
            // Calculate the distance between the robot and the next factory
            totalDistance += Math.abs(robot[i] - factory[factoryIndex][0]);
            // Decrement the limit of the next factory
            factory[factoryIndex][1]--;
        }
    }

    return totalDistance;
}

function convertTemperature(celsius) {
    // calculate Kelvin by adding 273.15 to Celsius
    var kelvin = celsius + 273.15;
    // calculate Fahrenheit by multiplying Celsius by 9/5 and adding 32
    var fahrenheit = celsius * 9 / 5 + 32;
    return [kelvin, fahrenheit];
}

function findOriginalArray(pref) {
    var n = pref.length;
    var arr = new Array(n);
    // each element is the xor of current and previous prefix values
    for (var i = 0; i < n; i++) {
        arr[i] = i === 0 ? pref[i] : pref[i] ^ pref[i - 1];
    }
    return arr;
}

function longestTaskEmployee(n, logs) {
    let prevLeave = 0;               // time when the previous task ended
    let maxDuration = -1;            // longest duration found so far
    let bestId = 0;                  // employee id for the longest task

    for (let i = 0; i < logs.length; i++) {
        const [empId, leaveTime] = logs[i];
        const duration = leaveTime - prevLeave;   // compute current task length
        if (duration > maxDuration || (duration === maxDuration && empId < bestId)) {
            maxDuration = duration;
            bestId = empId;
        }
        prevLeave = leaveTime;        // move to the next task start
    }
    return bestId;
}

function findPivotInteger(n) {
    // calculate the total sum of numbers from 1 to n
    let totalSum = Math.floor(n * (n + 1) / 2);
    let leftSum = 0;
    for (let x = 1; x <= n; x++) {
        // check if the sum of numbers from 1 to x equals the sum of numbers from x + 1 to n
        if (leftSum + x === totalSum - leftSum - x + x) return x;
        leftSum += x;
    }
    return -1;
}

function mostProfitablePath(edges, bob, amount) {
    const n = amount.length;
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }
    const depth = new Int32Array(n);
    const parent = new Int32Array(n);
    parent.fill(-1);
    const queue = [0];
    for (let qi = 0; qi < queue.length; qi++) {
        const u = queue[qi];
        for (const v of adj[u]) {
            if (v === parent[u]) continue;
            parent[v] = u;
            depth[v] = depth[u] + 1;
            queue.push(v);
        }
    }
    const bobDist = new Int32Array(n);
    bobDist.fill(-1);
    let cur = bob;
    let d = 0;
    while (cur !== -1) {
        bobDist[cur] = d;
        cur = parent[cur];
        d++;
    }
    const contrib = new Int32Array(n);
    for (let i = 0; i < n; i++) {
        const bd = bobDist[i];
        if (bd === -1) {
            contrib[i] = amount[i];
        } else if (depth[i] < bd) {
            contrib[i] = amount[i];
        } else if (depth[i] === bd) {
            contrib[i] = amount[i] / 2;
        } else {
            contrib[i] = 0;
        }
    }
    let maxIncome = -Infinity;
    const stack = [[0, -1, contrib[0]]];
    while (stack.length) {
        const [u, p, sum] = stack.pop();
        const isLeaf = u !== 0 && adj[u].length === 1;
        if (isLeaf) {
            if (sum > maxIncome) maxIncome = sum;
        }
        for (const v of adj[u]) {
            if (v === p) continue;
            stack.push([v, u, sum + contrib[v]]);
        }
    }
    return maxIncome;
}

function numberOfSubarrays(nums, k) {
  let count = 0;
  // iterate over all possible subarrays
  for (let i = 0; i < nums.length; i++) {
    for (let j = i; j < nums.length; j++) {
      let subarray = nums.slice(i, j + 1);
      // sort the subarray to find the median
      subarray.sort((a, b) => a - b);
      let medianIndex = Math.floor((subarray.length - 1) / 2);
      // check if the median is equal to k
      if (subarray[medianIndex] === k) {
        count++;
      }
    }
  }
  return count;
}

function removeNodes(head) {
    let prev = null, cur = head;
    while (cur) {
        const nxt = cur.next;
        cur.next = prev;
        prev = cur;
        cur = nxt;
    }
    let maxSoFar = -Infinity;
    let newHead = null;
    cur = prev;
    while (cur) {
        const nxt = cur.next; // save BEFORE overwriting cur.next below
        if (cur.val >= maxSoFar) {
            maxSoFar = cur.val;
            cur.next = newHead;
            newHead = cur;
        }
        cur = nxt;
    }
    return newHead;
}

function minAppend(s, t) {
  let i = 0, j = 0;
  // advance both pointers, moving j only when characters match
  while (i < s.length && j < t.length) {
    if (s[i] === t[j]) j++;
    i++;
  }
  return t.length - j; // characters of t that couldn't be matched must be appended
}

function countGoodStrings(low, high, zero, one) {
    const MOD = 1000000007;
    const dp = new Array(high + 1).fill(0);
    dp[0] = 1;                     // empty string

    let answer = 0;
    for (let i = 1; i <= high; i++) {
        // dp[i] = number of ways to obtain length i
        let ways = 0;
        if (i >= zero) ways = (ways + dp[i - zero]) % MOD;
        if (i >= one)  ways = (ways + dp[i - one]) % MOD;
        dp[i] = ways;

        if (i >= low) answer = (answer + dp[i]) % MOD;
    }
    return answer;
}

function subarrayLCM(nums, k) {
    function gcd(a, b) { // calculate greatest common divisor
        if (b === 0) return a;
        return gcd(b, a % b);
    }
    function lcm(a, b) { // calculate least common multiple
        return Math.floor(a * b / gcd(a, b));
    }
    let count = 0;
    for (let i = 0; i < nums.length; i++) { // generate all possible subarrays
        let currentLcm = nums[i]; // initialize current lcm with the first element
        for (let j = i; j < nums.length; j++) { // expand the subarray to the right
            currentLcm = lcm(currentLcm, nums[j]); // update the current lcm
            if (currentLcm === k) count++; // if the current lcm equals k, increment the count
            if (currentLcm > k) break; // if the current lcm exceeds k, stop expanding the subarray
        }
    }
    return count;
}

function distinctAverages(nums) {
    // sort to enable pairing smallest with largest
    nums.sort((a, b) => a - b);
    const seen = new Set();

    const n = nums.length;
    for (let i = 0; i < n / 2; i++) {               // pair min with max using two pointers
        const avg = (nums[i] + nums[n - 1 - i]) / 2;
        seen.add(avg);
    }
    return seen.size;
}

function minCuts(n) {
    // if n is even we can use diameters, otherwise we need one cut per slice
    return n % 2 === 0 ? n / 2 : n;
}

function minimumPenalty(customers) {
    let minPenalty = Infinity;
    let minIndex = -1;
    for (let i = 0; i <= customers.length; i++) {
        let penalty = 0;
        for (let j = 0; j < customers.length; j++) {
            if (j >= i) {
                // shop closed at hour j but a customer came - missed customer
                if (customers[j] === 'Y') penalty++;
            } else {
                // shop open at hour j but no customer came - wasted hour
                if (customers[j] === 'N') penalty++;
            }
        }
        if (penalty < minPenalty) {
            minPenalty = penalty;
            minIndex = i;
        }
    }
    return minIndex;
}

function magnificentSets(n, edges) {
    const adj = Array.from({ length: n + 1 }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }

    const visited = new Array(n + 1).fill(false);
    const color = new Array(n + 1).fill(-1);
    let answer = 0;

    for (let start = 1; start <= n; start++) {
        if (visited[start]) continue;

        // gather component and check bipartiteness
        const queue = [start];
        visited[start] = true;
        color[start] = 0;
        const component = [start];
        let isBipartite = true;

        for (let qIdx = 0; qIdx < queue.length; qIdx++) {
            const u = queue[qIdx];
            for (const v of adj[u]) {
                if (color[v] === -1) {
                    color[v] = color[u] ^ 1;
                    visited[v] = true;
                    queue.push(v);
                    component.push(v);
                } else if (color[v] === color[u]) {
                    isBipartite = false;
                }
            }
        }

        if (!isBipartite) return -1;

        // compute diameter of this component
        let diam = 0;
        for (const node of component) {
            const dist = new Array(n + 1).fill(-1);
            const q = [node];
            dist[node] = 0;
            for (let i = 0; i < q.length; i++) {
                const cur = q[i];
                for (const nb of adj[cur]) {
                    if (dist[nb] === -1) {
                        dist[nb] = dist[cur] + 1;
                        q.push(nb);
                    }
                }
            }
            for (const v of component) {
                if (dist[v] > diam) diam = dist[v];
            }
        }

        answer += diam + 1;
    }

    return answer;
}
// TIME: O(n * (n + m))  SPACE: O(n + m)

function dividePlayers(skill) {
    const n = skill.length;
    const total = skill.reduce((s, v) => s + v, 0);
    const target = (2 * total) / n;                     // each team must sum to this value
    if (!Number.isInteger(target)) return -1;

    const cnt = new Map();                               // frequency of each skill
    for (const v of skill) cnt.set(v, (cnt.get(v) || 0) + 1);

    let chemistrySum = 0;
    for (const [val, _] of cnt) {                        // iterate over distinct skills
        while (cnt.get(val) > 0) {                       // process all remaining players with this skill
            const partner = target - val;                // required partner skill
            if (!cnt.has(partner) || cnt.get(partner) === 0) return -1;
            if (partner === val && cnt.get(val) < 2) return -1; // need two of the same skill
            cnt.set(val, cnt.get(val) - 1);
            cnt.set(partner, cnt.get(partner) - 1);
            chemistrySum += val * partner;               // add chemistry of this team
        }
    }
    return chemistrySum;
}

function longestSquareStreak(nums) {
    const present = new Set(nums);          // O(1) look‑ups
    const memo = new Map();                 // stores len(x) for each x

    function chainLen(x) {                  // DP with memoisation
        if (!present.has(x)) return 0;
        if (memo.has(x)) return memo.get(x);
        const next = x * x;
        let len = 1;
        if (present.has(next)) len = 1 + chainLen(next); // main logic
        memo.set(x, len);
        return len;
    }

    let best = 0;
    for (const v of present) best = Math.max(best, chainLen(v));
    return best >= 2 ? best : -1;
}

class MinHeap {
    constructor() { this.data = []; }
    push(item) { // item = [cost, index]
        this.data.push(item);
        let i = this.data.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (this.data[p][0] > this.data[i][0]) { [this.data[p], this.data[i]] = [this.data[i], this.data[p]]; i = p; }
            else break;
        }
    }
    pop() {
        const top = this.data[0];
        const last = this.data.pop();
        if (this.data.length > 0) {
            this.data[0] = last;
            let i = 0;
            while (true) {
                let l = 2 * i + 1, r = 2 * i + 2, smallest = i;
                if (l < this.data.length && this.data[l][0] < this.data[smallest][0]) smallest = l;
                if (r < this.data.length && this.data[r][0] < this.data[smallest][0]) smallest = r;
                if (smallest === i) break;
                [this.data[i], this.data[smallest]] = [this.data[smallest], this.data[i]];
                i = smallest;
            }
        }
        return top;
    }
    get size() { return this.data.length; }
    get topCost() { return this.data.length ? this.data[0][0] : Infinity; }
}

function totalCost(costs, k, candidates) {
    const n = costs.length;
    const frontHeap = new MinHeap();
    const backHeap = new MinHeap();
    let left = 0, right = n - 1;
    for (let i = 0; i < candidates && left <= right; i++) { frontHeap.push([costs[left], left]); left++; }
    for (let i = 0; i < candidates && left <= right; i++) { backHeap.push([costs[right], right]); right--; }
    let total = 0;
    for (let count = 0; count < k; count++) {
        let chosen;
        if (backHeap.size === 0 || (frontHeap.size > 0 && frontHeap.topCost <= backHeap.topCost)) {
            chosen = frontHeap.pop();
            if (left <= right) { frontHeap.push([costs[left], left]); left++; }
        } else {
            chosen = backHeap.pop();
            if (left <= right) { backHeap.push([costs[right], right]); right--; }
        }
        total += chosen[0];
    }
    return total;
}

function minScore(n, roads) {
    // build adjacency list
    const adj = Array.from({ length: n + 1 }, () => []);
    for (const [a, b, w] of roads) {
        adj[a].push([b, w]);
        adj[b].push([a, w]);
    }

    const visited = new Array(n + 1).fill(false);
    const stack = [1];
    visited[1] = true;
    let best = Infinity;

    while (stack.length) {
        const v = stack.pop();
        for (const [to, w] of adj[v]) {
            best = Math.min(best, w);               // main logic
            if (!visited[to]) {
                visited[to] = true;
                stack.push(to);
            }
        }
    }
    return best;
}

var minimumTotalCost = function(nums1, nums2) {
    const n = nums1.length;
    let ans = 0n;
    let same = 0;
    const cnt = new Map();
    for (let i = 0; i < n; i++) {
        if (nums1[i] === nums2[i]) {
            ans += BigInt(i);
            same++;
            cnt.set(nums1[i], (cnt.get(nums1[i]) || 0) + 1);
        }
    }
    let m = 0, lead = -1;
    for (const [val, c] of cnt.entries()) {
        const t = c * 2 - same;
        if (t > m) { m = t; lead = val; }
    }
    for (let i = 0; i < n && m > 0; i++) {
        if (nums1[i] !== nums2[i] && nums1[i] !== lead && nums2[i] !== lead) {
            ans += BigInt(i);
            m--;
        }
    }
    return m > 0 ? -1 : Number(ans);
};

function frogJumpII(stones) {
    const n = stones.length;
    if (n <= 2) return stones[n - 1] - stones[0];
    let maxGap = 0;
    for (let i = 0; i < n - 2; i++) {
        const gap = stones[i + 2] - stones[i];
        if (gap > maxGap) maxGap = gap;
    }
    return maxGap;
}

function deleteGreatestValue(grid) {
    const m = grid.length;
    const n = grid[0].length;

    // sort each row in descending order so that the j‑th element is the j‑th greatest in that row
    for (let i = 0; i < m; i++) {
        grid[i].sort((a, b) => b - a);
    }

    let answer = 0;
    // for each column (i.e., each operation) take the maximum among rows and add it to the answer
    for (let col = 0; col < n; col++) {
        let colMax = 0;
        for (let row = 0; row < m; row++) {
            if (grid[row][col] > colMax) colMax = grid[row][col];
        }
        answer += colMax;
    }
    return answer;
}

function maxValue(strs) {
  let max = 0;
  for (let s of strs) {                     // iterate each string
    let onlyDigits = true;
    for (let i = 0; i < s.length; i++) {    // check if all chars are 0‑9
      const code = s.charCodeAt(i);
      if (code < 48 || code > 57) { onlyDigits = false; break; }
    }
    const val = onlyDigits ? Number(s) : s.length; // value rule
    if (val > max) max = val;
  }
  return max;
}

class MemoryAllocator {
    constructor(n) {
        this.n = n;
        const size = 4 * n;
        this.pref = new Int32Array(size);
        this.suff = new Int32Array(size);
        this.best = new Int32Array(size);
        this.len = new Int32Array(size);
        this.lazy = new Int8Array(size).fill(-1);
        this.allocations = new Map();
        const build = (idx, l, r) => {
            this.len[idx] = r - l + 1;
            this.pref[idx] = this.suff[idx] = this.best[idx] = this.len[idx];
            if (l === r) return;
            const m = (l + r) >> 1;
            build(idx << 1, l, m);
            build((idx << 1) | 1, m + 1, r);
        };
        build(1, 0, n - 1);
    }
    _apply(idx, val) {
        this.lazy[idx] = val;
        this.pref[idx] = this.suff[idx] = this.best[idx] = (val === 1 ? this.len[idx] : 0);
    }
    _push(idx) {
        if (this.lazy[idx] !== -1) {
            this._apply(idx << 1, this.lazy[idx]);
            this._apply((idx << 1) | 1, this.lazy[idx]);
            this.lazy[idx] = -1;
        }
    }
    _pull(idx) {
        const L = idx << 1, R = (idx << 1) | 1;
        this.pref[idx] = this.pref[L] === this.len[L] ? this.len[L] + this.pref[R] : this.pref[L];
        this.suff[idx] = this.suff[R] === this.len[R] ? this.len[R] + this.suff[L] : this.suff[R];
        this.best[idx] = Math.max(this.best[L], this.best[R], this.suff[L] + this.pref[R]);
    }
    _update(idx, l, r, ql, qr, val) {
        if (ql > r || qr < l) return;
        if (ql <= l && r <= qr) { this._apply(idx, val); return; }
        this._push(idx);
        const m = (l + r) >> 1;
        this._update(idx << 1, l, m, ql, qr, val);
        this._update((idx << 1) | 1, m + 1, r, ql, qr, val);
        this._pull(idx);
    }
    _find(idx, l, r, k) {
        if (this.best[idx] < k) return -1;
        if (l === r) return l;
        this._push(idx);
        const m = (l + r) >> 1;
        const L = idx << 1, R = (idx << 1) | 1;
        if (this.best[L] >= k) return this._find(L, l, m, k);
        if (this.suff[L] + this.pref[R] >= k) return m - this.suff[L] + 1;
        return this._find(R, m + 1, r, k);
    }
    allocate(size, mID) {
        const start = this._find(1, 0, this.n - 1, size);
        if (start === -1) return -1;
        this._update(1, 0, this.n - 1, start, start + size - 1, 0);
        if (!this.allocations.has(mID)) this.allocations.set(mID, []);
        this.allocations.get(mID).push([start, start + size - 1]);
        return start;
    }
    freeMemory(mID) {
        const blocks = this.allocations.get(mID);
        if (!blocks) return 0;
        let freed = 0;
        for (const [s, e] of blocks) {
            this._update(1, 0, this.n - 1, s, e, 1);
            freed += e - s + 1;
        }
        this.allocations.delete(mID);
        return freed;
    }
}

function addEdgesToMakeDegreesOfAllNodesEven(n, edges) {
    const edgeSet = new Set();
    const degreeParity = new Array(n + 1).fill(0);
    for (let [u, v] of edges) {
        if (u > v) [u, v] = [v, u];
        edgeSet.add(u + ',' + v);
        degreeParity[u] ^= 1;
        degreeParity[v] ^= 1;
    }

    const oddNodes = [];
    for (let i = 1; i <= n; i++) if (degreeParity[i]) oddNodes.push(i);
    const oddCnt = oddNodes.length;

    if (oddCnt === 0) return true;
    if (oddCnt > 4) return false;

    const hasEdge = (a, b) => edgeSet.has(Math.min(a, b) + ',' + Math.max(a, b));

    if (oddCnt === 2) {
        const [a, b] = oddNodes;
        if (!hasEdge(a, b)) return true;
        for (let c = 1; c <= n; c++) {
            if (c === a || c === b) continue;
            if (hasEdge(a, c)) continue;
            if (hasEdge(b, c)) continue;
            return true;
        }
        return false;
    }

    const o = oddNodes;
    const pairings = [
        [[o[0], o[1]], [o[2], o[3]]],
        [[o[0], o[2]], [o[1], o[3]]],
        [[o[0], o[3]], [o[1], o[2]]],
    ];
    for (const [[x1, y1], [x2, y2]] of pairings) {
        if (!hasEdge(x1, y1) && !hasEdge(x2, y2)) return true;
    }
    return false;
}

function countSimilarPairs(words) {
    var maskCount = Object.create(null);               // hashmap: mask → frequency

    for (var i = 0; i < words.length; i++) {           // build mask for each word
        var mask = 0;
        var w = words[i];
        for (var j = 0; j < w.length; j++) {
            mask |= 1 << (w.charCodeAt(j) - 97);       // set bit for the character
        }
        maskCount[mask] = (maskCount[mask] || 0) + 1;   // count this mask
    }

    var pairs = 0;
    for (var key in maskCount) {                       // compute pairs from frequencies
        var cnt = maskCount[key];
        pairs += cnt * (cnt - 1) / 2;
    }
    return pairs;
}

function smallestValue(n) {
    // helper: returns true if x is prime
    function isPrime(x) {
        if (x < 2) return false;
        if (x % 2 === 0) return x === 2;
        for (let d = 3; d * d <= x; d += 2) {
            if (x % d === 0) return false;
        }
        return true;
    }

    // helper: sum of prime factors of x (with multiplicity)
    function sumPrimeFactors(x) {
        let sum = 0;
        // factor out 2s
        while (x % 2 === 0) {
            sum += 2;
            x /= 2;
        }
        // odd factors
        for (let d = 3; d * d <= x; d += 2) {
            while (x % d === 0) {
                sum += d;
                x /= d;
            }
        }
        // remaining prime > 1
        if (x > 1) sum += x;
        return sum;
    }

    // main loop: keep replacing until n becomes prime (or 1)
    while (n > 1 && !isPrime(n)) {
        n = sumPrimeFactors(n);
    }
    return n;
}

function captureForts(forts) {
    const n = forts.length;
    let best = 0;
    let last = -1, lastVal = 0;
    for (let i = 0; i < n; i++) {
        if (forts[i] !== 0) {
            if (lastVal !== 0 && forts[i] !== lastVal && last !== -1) {
                best = Math.max(best, i - last - 1);
            }
            last = i;
            lastVal = forts[i];
        }
    }
    return best;
}

function topStudents(positive_feedback, negative_feedback, report, student_id, k) {
    // build fast lookup sets for feedback words
    const posSet = new Set(positive_feedback);
    const negSet = new Set(negative_feedback);

    // accumulate points per student
    const points = new Map();                     // id -> total points
    for (let i = 0; i < report.length; ++i) {
        const words = report[i].split(' ');
        let cur = 0;
        for (const w of words) {                  // count points for this report
            if (posSet.has(w)) cur += 3;
            else if (negSet.has(w)) cur -= 1;
        }
        const id = student_id[i];
        points.set(id, (points.get(id) || 0) + cur);
    }

    // ---------- min‑heap of size k ----------
    const heap = [];                              // stores {id, pts}
    const less = (a, b) => a.pts < b.pts || (a.pts === b.pts && a.id > b.id); // a is worse than b

    const swap = (i, j) => { const t = heap[i]; heap[i] = heap[j]; heap[j] = t; };

    const heapifyUp = (idx) => {
        while (idx > 0) {
            const p = (idx - 1) >> 1;
            if (!less(heap[idx], heap[p])) break;
            swap(idx, p);
            idx = p;
        }
    };
    const heapifyDown = (idx) => {
        const n = heap.length;
        while (true) {
            let left = idx * 2 + 1, right = left + 1, smallest = idx;
            if (left < n && less(heap[left], heap[smallest])) smallest = left;
            if (right < n && less(heap[right], heap[smallest])) smallest = right;
            if (smallest === idx) break;
            swap(idx, smallest);
            idx = smallest;
        }
    };
    const push = (node) => {
        heap.push(node);
        heapifyUp(heap.length - 1);
        if (heap.length > k) {               // keep only k best
            heap[0] = heap.pop();
            heapifyDown(0);
        }
    };
    // -----------------------------------------

    for (const [id, pts] of points.entries()) push({id, pts});

    // sort the k elements: higher points first, lower id on tie
    heap.sort((a, b) => b.pts - a.pts || a.id - b.id);
    return heap.map(x => x.id);
}

function maximumTastiness(price, k) {
    price.sort((a, b) => a - b);                     // sort prices

    const canPlace = (dist) => {                     // greedy feasibility test
        let count = 1;                               // first candy always taken
        let last = price[0];
        for (let i = 1; i < price.length; i++) {
            if (price[i] - last >= dist) {
                count++;
                last = price[i];
                if (count === k) return true;       // enough candies selected
            }
        }
        return false;
    };

    let low = 0, high = price[price.length - 1] - price[0];
    while (low < high) {                             // binary search on answer
        const mid = Math.floor((low + high + 1) / 2);
        if (canPlace(mid)) low = mid;                // mid works → try larger
        else high = mid - 1;                         // mid too large
    }
    return low;                                      // maximum feasible distance
}

function takeKOfEachCharacterFromLeftAndRight(s, k) {
    const n = s.length;
    const count = (ch) => s.split('').filter(c => c === ch).length;
    const totalA = count('a'), totalB = count('b'), totalC = count('c');
    if (totalA < k || totalB < k || totalC < k) return -1;

    const limitA = totalA - k, limitB = totalB - k, limitC = totalC - k;
    let cntA = 0, cntB = 0, cntC = 0;
    let left = 0, maxLen = 0;

    for (let right = 0; right < n; right++) {
        const ch = s[right];
        if (ch === 'a') cntA++; else if (ch === 'b') cntB++; else cntC++;
        while (cntA > limitA || cntB > limitB || cntC > limitC) {
            const chLeft = s[left];
            if (chLeft === 'a') cntA--; else if (chLeft === 'b') cntB--; else cntC--;
            left++;
        }
        const curLen = right - left + 1;
        if (curLen > maxLen) maxLen = curLen;
    }
    return n - maxLen;
}

function countAnagrams(s) {
    const MOD = 1000000007n;

    // split into words
    const words = s.split(' ');
    let maxLen = 0;
    for (const w of words) if (w.length > maxLen) maxLen = w.length;

    // pre‑compute factorials and inverse factorials up to maxLen
    const fact = new Array(maxLen + 1);
    const invFact = new Array(maxLen + 1);
    fact[0] = 1n;
    for (let i = 1; i <= maxLen; ++i) fact[i] = (fact[i - 1] * BigInt(i)) % MOD;

    // fast exponentiation
    function modPow(base, exp) {
        let res = 1n;
        let b = base % MOD;
        let e = exp;
        while (e > 0n) {
            if (e & 1n) res = (res * b) % MOD;
            b = (b * b) % MOD;
            e >>= 1n;
        }
        return res;
    }

    invFact[maxLen] = modPow(fact[maxLen], MOD - 2n);
    for (let i = maxLen; i > 0; --i) {
        invFact[i - 1] = (invFact[i] * BigInt(i)) % MOD;
    }

    let answer = 1n;

    for (const w of words) {
        // compute permutations for this word
        let ways = fact[w.length];
        const freq = {};
        for (const ch of w) freq[ch] = (freq[ch] || 0) + 1;
        for (const cnt of Object.values(freq)) {
            ways = (ways * invFact[cnt]) % MOD;
        }
        answer = (answer * ways) % MOD;   // multiply into global product
    }

    return Number(answer);
}

function distinctPrimeFactors(nums) {
    const primes = new Set();                     // store distinct primes

    for (let i = 0; i < nums.length; i++) {       // iterate over array
        let x = nums[i];
        if (x < 2) continue;                     // 0 or 1 add no primes

        // factor out 2
        if (x % 2 === 0) {
            primes.add(2);
            while (x % 2 === 0) x /= 2;
        }

        // factor out odd numbers up to sqrt(x)
        for (let d = 3; d * d <= x; d += 2) {     // MAIN LOGIC: trial division
            if (x % d === 0) {
                primes.add(d);
                while (x % d === 0) x /= d;
            }
        }

        // if remainder > 1 it is a prime larger than sqrt(original)
        if (x > 1) primes.add(x);
    }

    return primes.size;
}

function countDigits(num) {
  let count = 0;
  const n = Math.abs(num);          // work with positive value
  let temp = n;
  // iterate through each digit and check divisibility
  while (temp > 0) {
    const digit = temp % 10;
    if (digit !== 0 && n % digit === 0) count++;
    temp = Math.floor(temp / 10);
  }
  return count;
}

function shortestDistance(words, target, startIndex) {
    const n = words.length;
    let minDist = Infinity;

    // Scan array once and compute distance for each occurrence of target
    for (let i = 0; i < n; i++) {
        if (words[i] === target) {
            const forward = (i - startIndex + n) % n;   // steps moving right
            const backward = (startIndex - i + n) % n; // steps moving left
            const dist = Math.min(forward, backward);
            if (dist < minDist) minDist = dist;
        }
    }
    return minDist === Infinity ? -1 : minDist;
}

function minimumPartition(s, k) {
    let count = 1;
    let cur = 0n;
    const K = BigInt(k);
    for (const ch of s) {
        const d = BigInt(ch);
        if (d > K) return -1;
        const cand = cur*10n + d;
        if (cand > K) { count++; cur = d; }
        else cur = cand;
    }
    return count;
}

function minimizeTheMaximumOfTwoArrays(divisor1, divisor2, uniqueCnt1, uniqueCnt2) {
    const gcd = (a, b) => b === 0 ? a : gcd(b, a % b);
    const lcm = (a, b) => Math.floor(a / gcd(a, b)) * b;
    const l = lcm(divisor1, divisor2);

    const feasible = (m) => {
        const a = Math.floor(m / divisor1);
        const b = Math.floor(m / divisor2);
        const c = Math.floor(m / l);

        const exclusive1 = b - c;
        const exclusive2 = a - c;
        const overlap = m - (a + b - c);

        const need1 = Math.max(0, uniqueCnt1 - exclusive1);
        const need2 = Math.max(0, uniqueCnt2 - exclusive2);

        return need1 + need2 <= overlap;
    };

    let hi = 1;
    while (!feasible(hi)) hi <<= 1;

    let lo = 1;
    while (lo < hi) {
        const mid = Math.floor((lo + hi) / 2);
        if (feasible(mid)) hi = mid; else lo = mid + 1;
    }
    return lo;
}

function numberOfGreatPartitions(nums, k) {
    const MOD = 1_000_000_007;
    const n = nums.length;
    let total = 0;
    for (let v of nums) total += v;          // total sum S

    if (k > total) return 0;                  // impossible

    const dp = new Uint32Array(total + 1);    // dp[t] fits in 32‑bit modulo
    dp[0] = 1;

    let curMax = 0;
    for (let v of nums) {
        // update dp backwards to avoid reuse of the same element
        for (let t = curMax; t >= 0; --t) {
            const nxt = t + v;
            const add = dp[t];
            if (add) {
                let val = dp[nxt] + add;
                if (val >= MOD) val -= MOD;
                dp[nxt] = val;
            }
        }
        curMax += v;
    }

    let ans = 0;
    const upper = total - k;
    for (let t = k; t <= upper; ++t) {        // sum over valid x
        ans += dp[t];
        if (ans >= MOD) ans -= MOD;
    }
    return ans;
}

function xorBeauty(nums) {
    let ans = 0;                         // main logic: XOR all elements
    for (let i = 0; i < nums.length; i++) {
        ans ^= nums[i];
    }
    return ans;
}

function maxMinPower(stations, r, k) {
  const n = stations.length;
  const pref = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) pref[i + 1] = pref[i] + stations[i];

  const windowSum = (i) => {
    const left = i - r > 0 ? i - r : 0;
    const right = i + r < n ? i + r : n - 1;
    return pref[right + 1] - pref[left];
  };

  let maxWindow = 0;
  for (let i = 0; i < n; i++) {
    const w = windowSum(i);
    if (w > maxWindow) maxWindow = w;
  }

  const canAchieve = (target) => {
    const diff = new Array(n + 1).fill(0);
    let added = 0;
    let remaining = k;
    for (let i = 0; i < n; i++) {
      added += diff[i];
      const cur = windowSum(i) + added;
      if (cur < target) {
        const need = target - cur;
        remaining -= need;
        if (remaining < 0) return false;
        const pos = i + r < n ? i + r : n - 1;
        const start = pos - r > 0 ? pos - r : 0;
        const end = pos + r < n ? pos + r : n - 1;
        diff[start] += need;
        if (end + 1 < n) diff[end + 1] -= need;
        added += need;
      }
    }
    return true;
  };

  let low = 0;
  let high = maxWindow + k;
  while (low < high) {
    const mid = Math.floor((low + high + 1) / 2);
    if (canAchieve(mid)) low = mid;
    else high = mid - 1;
  }
  return low;
}

function DataStream() {
    // keep only the last value and its consecutive length
    let lastVal = null;
    let runLen = 0;

    return {
        // adds `val` to the stream and checks the last k values
        consec: function (k, val) {
            if (val === lastVal) {          // same as previous → extend run
                runLen++;
            } else {                        // different → start new run
                lastVal = val;
                runLen = 1;
            }
            return lastVal === val && runLen >= k; // main logic
        }
    };
}

function closestPrimes(left, right) {
    // ---------- Sieve of Eratosthenes ----------
    const limit = right;
    const isPrime = new Uint8Array(limit + 1); // 0 = unknown, 1 = prime, 2 = composite
    isPrime.fill(1, 2);                         // assume 2..limit are prime
    for (let p = 2; p * p <= limit; ++p) {
        if (isPrime[p] === 1) {
            for (let mult = p * p; mult <= limit; mult += p) {
                isPrime[mult] = 2;              // mark composite
            }
        }
    }

    // ---------- Collect primes inside [left, right] ----------
    const primesInRange = [];
    for (let i = Math.max(2, left); i <= right; ++i) {
        if (isPrime[i] === 1) primesInRange.push(i);
    }

    // ---------- Find closest pair ----------
    if (primesInRange.length < 2) return [-1, -1];
    let bestGap = Infinity, bestPair = [-1, -1];
    for (let i = 1; i < primesInRange.length; ++i) {
        const gap = primesInRange[i] - primesInRange[i - 1];
        if (gap < bestGap) {                     // smaller gap found
            bestGap = gap;
            bestPair = [primesInRange[i - 1], primesInRange[i]];
        }
    }
    return bestPair;
}

function categorizeBox(length, width, height, mass) {
    // check bulky criteria
    var isBulky = length >= 1e4 || width >= 1e4 || height >= 1e4 || length * width * height >= 1e9;
    // check heavy criteria
    var isHeavy = mass >= 100;

    if (isBulky && isHeavy) return "Both";
    if (isBulky) return "Bulky";
    if (isHeavy) return "Heavy";
    return "Neither";
}

function maximumCount(nums) {
  // binary search for first index where value > target
  function firstGreater(arr, target) {
    let lo = 0, hi = arr.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (arr[mid] > target) hi = mid;
      else lo = mid + 1;
    }
    return lo;
  }

  // binary search for first index where value >= target
  function firstGE(arr, target) {
    let lo = 0, hi = arr.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (arr[mid] >= target) hi = mid;
      else lo = mid + 1;
    }
    return lo;
  }

  const n = nums.length;
  const firstNonNeg = firstGE(nums, 0);   // count of negatives = firstNonNeg
  const firstPos = firstGreater(nums, 0); // count of positives = n - firstPos
  const negCount = firstNonNeg;
  const posCount = n - firstPos;
  return negCount > posCount ? negCount : posCount; // return the larger count
}

function maximalScore(nums, k) {
    // ---------- heap implementation ----------
    const heap = [];
    // heapify (max‑heap)
    for (let i = 0; i < nums.length; i++) heapPush(nums[i]);
    function heapPush(val) {
        heap.push(val);
        let idx = heap.length - 1;
        while (idx > 0) {
            const parent = (idx - 1) >> 1;
            if (heap[parent] >= heap[idx]) break;
            [heap[parent], heap[idx]] = [heap[idx], heap[parent]];
            idx = parent;
        }
    }
    function heapPop() {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            let idx = 0;
            while (true) {
                let left = idx * 2 + 1;
                let right = left + 1;
                let largest = idx;
                if (left < heap.length && heap[left] > heap[largest]) largest = left;
                if (right < heap.length && heap[right] > heap[largest]) largest = right;
                if (largest === idx) break;
                [heap[idx], heap[largest]] = [heap[largest], heap[idx]];
                idx = largest;
            }
        }
        return top;
    }
    // ---------- main logic ----------
    let answer = 0;
    for (let i = 0; i < k; i++) {
        const cur = heapPop();          // take current maximum
        answer += cur;                  // add its value to the score
        const next = Math.floor((cur + 2) / 3); // ceil(cur/3) without floating point
        heapPush(next);                 // insert the updated value
    }
    return answer;
}

function makeNumberOfDistinctCharactersEqual(word1, word2) {
    const freq1 = new Array(26).fill(0);
    const freq2 = new Array(26).fill(0);
    for (const ch of word1) { const idx = ch.charCodeAt(0) - 97; if (idx >= 0 && idx < 26) freq1[idx]++; }
    for (const ch of word2) { const idx = ch.charCodeAt(0) - 97; if (idx >= 0 && idx < 26) freq2[idx]++; }

    const d1 = freq1.filter(v => v > 0).length;
    const d2 = freq2.filter(v => v > 0).length;

    if (d1 === d2) return true;

    for (let a = 0; a < 26; a++) {
        if (!freq1[a]) continue;
        for (let b = 0; b < 26; b++) {
            if (!freq2[b]) continue;
            const delta1 = (freq1[b] === 0 ? 1 : 0) - (freq1[a] === 1 ? 1 : 0);
            const delta2 = (freq2[a] === 0 ? 1 : 0) - (freq2[b] === 1 ? 1 : 0);
            if (d1 + delta1 === d2 + delta2) return true;
        }
    }
    return false;
}

function timeToCrossBridge(n, k, time) {
    class Heap {
        constructor(cmp) { this.a = []; this.cmp = cmp; }
        get size() { return this.a.length; }
        peek() { return this.a[0]; }
        push(x) {
            const a = this.a; a.push(x);
            let i = a.length - 1;
            while (i > 0) {
                const p = (i - 1) >> 1;
                if (this.cmp(a[p], a[i]) <= 0) break;
                [a[p], a[i]] = [a[i], a[p]];
                i = p;
            }
        }
        pop() {
            const a = this.a;
            const top = a[0];
            const last = a.pop();
            if (a.length) {
                a[0] = last;
                let i = 0;
                while (true) {
                    let l = 2*i+1, r = 2*i+2, s = i;
                    if (l < a.length && this.cmp(a[l], a[s]) < 0) s = l;
                    if (r < a.length && this.cmp(a[r], a[s]) < 0) s = r;
                    if (s === i) break;
                    [a[s], a[i]] = [a[i], a[s]];
                    i = s;
                }
            }
            return top;
        }
    }

    const right = time.map(t => t[0]);
    const pick = time.map(t => t[1]);
    const left = time.map(t => t[2]);
    const put = time.map(t => t[3]);
    const crossSum = time.map((t, i) => right[i] + left[i]);

    // "least efficient first" = highest crossSum, tie -> highest index
    const effCmp = (a, b) => {
        // a, b are worker indices
        if (crossSum[a] !== crossSum[b]) return crossSum[b] - crossSum[a]; // higher crossSum first
        return b - a; // higher index first
    };

    const waitingLeft = new Heap(effCmp);
    const waitingRight = new Heap(effCmp);
    for (let i = 0; i < k; i++) waitingLeft.push(i);

    const workingRight = new Heap((a, b) => a[0] - b[0]); // [finishTime, idx] picking on right
    const workingLeft = new Heap((a, b) => a[0] - b[0]);  // [finishTime, idx] putting on left

    let currentTime = 0;
    let boxesLeftToPick = n;
    let boxesPut = 0;

    function releaseUpTo(t) {
        while (workingRight.size && workingRight.peek()[0] <= t) {
            const [, idx] = workingRight.pop();
            waitingRight.push(idx);
        }
        while (workingLeft.size && workingLeft.peek()[0] <= t) {
            const [, idx] = workingLeft.pop();
            waitingLeft.push(idx);
        }
    }

    while (boxesPut < n) {
        releaseUpTo(currentTime);

        if (waitingRight.size > 0) {
            const idx = waitingRight.pop();
            currentTime += left[idx];
            boxesPut++;
            if (boxesPut === n) return currentTime;
            workingLeft.push([currentTime + put[idx], idx]);
        } else if (waitingLeft.size > 0 && boxesLeftToPick > 0) {
            const idx = waitingLeft.pop();
            boxesLeftToPick--;
            currentTime += right[idx];
            workingRight.push([currentTime + pick[idx], idx]);
        } else {
            // bridge idle - jump to next event
            let next = Infinity;
            if (workingRight.size) next = Math.min(next, workingRight.peek()[0]);
            if (workingLeft.size) next = Math.min(next, workingLeft.peek()[0]);
            currentTime = next;
        }
    }
    return currentTime;
}

function differenceOfSums(nums) {
    var elementSum = 0;
    var digitSum = 0;
    for (var i = 0; i < nums.length; i++) {
        var num = nums[i];
        elementSum += num;                     // add whole number to element sum
        while (num > 0) {                      // extract each digit
            digitSum += num % 10;
            num = Math.trunc(num / 10);
        }
    }
    return Math.abs(elementSum - digitSum);
}

function countGoodSubarrays(nums, k) {
    if (k <= 0) return (nums.length * (nums.length + 1)) >> 1; // all subarrays are good

    const freq = new Map();          // occurrences inside current window
    let pairCnt = 0;                 // number of equal pairs in window
    let left = 0;                    // left border of sliding window
    let answer = 0;

    for (let right = 0; right < nums.length; right++) {
        const val = nums[right];
        const cur = freq.get(val) || 0;
        pairCnt += cur;               // new element forms `cur` new pairs
        freq.set(val, cur + 1);

        // shrink to the smallest left that still keeps at least k pairs
        while (pairCnt >= k) {
            // if we can remove nums[left] and still have ≥k pairs, do it
            const leftVal = nums[left];
            const leftCnt = freq.get(leftVal);
            const pairsLost = leftCnt - 1; // pairs contributed by this element
            if (pairCnt - pairsLost < k) break; // cannot shrink further

            pairCnt -= pairsLost;
            if (leftCnt === 1) freq.delete(leftVal);
            else freq.set(leftVal, leftCnt - 1);
            left++;
        }

        // now window [left … right] is the minimal one with ≥k pairs
        if (pairCnt >= k) answer += left + 1; // all starts ≤ left are good
    }
    return answer;
}

function isCircularSentence(sentence) {
    // Split the sentence into words
    var words = sentence.split(' ');
    // Check if the last character of each word is equal to the first character of the next word
    for (var i = 0; i < words.length; i++) {
        // If this is the last word, check if its last character is equal to the first character of the first word
        if (i === words.length - 1) {
            // Check if the last character of the last word is equal to the first character of the first word
            if (words[i][words[i].length - 1] !== words[0][0]) {
                return false;
            }
        } else {
            // Check if the last character of the current word is equal to the first character of the next word
            if (words[i][words[i].length - 1] !== words[i + 1][0]) {
                return false;
            }
        }
    }
    // If all checks pass, the sentence is circular
    return true;
}

function closestNodes(root, queries) {
    // Perform in-order traversal to get the sorted array of node values
    let values = [];
    function inOrder(node) {
        if (node) {
            inOrder(node.left);
            values.push(node.val);
            inOrder(node.right);
        }
    }
    inOrder(root);

    let result = [];
    for (let query of queries) {
        // Find the largest number that is smaller or equal to the query
        let mini = -1;
        for (let value of values) {
            if (value <= query) {
                mini = value;
            } else {
                break;
            }
        }

        // Find the smallest number that is greater or equal to the query
        let maxi = -1;
        for (let value of values) {
            if (value >= query) {
                maxi = value;
                break;
            }
        }

        result.push([mini, maxi]);
    }
    return result;
}

function countUnequalTriplets(nums) {
  let count = 0; 
  // iterate over all possible triplets in the array
  for (let i = 0; i < nums.length; i++) {
    for (let j = i + 1; j < nums.length; j++) {
      for (let k = j + 1; k < nums.length; k++) {
        // check if the current triplet meets the conditions
        if (nums[i] !== nums[j] && nums[j] !== nums[k] && nums[i] !== nums[k]) {
          count++; // increment the count if the conditions are met
        }
      }
    }
  }
  return count;
}

function maxNonOverlappingPalindromeSubstrings(s, k) {
    let count = 0; // count of non-overlapping palindrome substrings
    let left = 0; // left pointer for the sliding window
    while (left < s.length) { 
        // check if there is a palindrome substring of length at least k starting at left
        let found = false;
        for (let right = left + k; right <= s.length; right++) { 
            // check if the substring from left to right is a palindrome
            let substring = s.substring(left, right);
            if (isPalindrome(substring)) { 
                // if it is a palindrome, increment the count and move the left pointer to the right of the palindrome
                count++;
                left = right;
                found = true;
                break;
            }
        }
        if (!found) { 
            // if no palindrome substring is found, move the left pointer to the right
            left++;
        }
    }
    return count;
}

function isPalindrome(s) { 
    // helper function to check if a string is a palindrome
    let left = 0;
    let right = s.length - 1;
    while (left < right) { 
        if (s[left] !== s[right]) { 
            return false;
        }
        left++;
        right--;
    }
    return true;
}

function minimumFuelCost(roads, seats) {
    // Create an adjacency list to represent the tree structure
    let graph = Array(roads.length + 1).fill(0).map(() => []);
    for (let [u, v] of roads) {
        graph[u].push(v);
        graph[v].push(u);
    }

    // Initialize the result variable to store the minimum fuel cost
    let result = 0;

    // Define a helper function to perform DFS
    function dfs(node, parent) {
        // Initialize the count of representatives in the subtree rooted at the current node
        let count = 1;

        // Iterate over the neighbors of the current node
        for (let child of graph[node]) {
            // Skip the parent node to avoid counting it twice
            if (child === parent) continue;
            // Recursively perform DFS on the child node and update the count
            count += dfs(child, node);
        }

        // If the current node is not the capital city, update the result with the minimum fuel cost
        if (node > 0) result += Math.ceil(count / seats);
        // Return the count of representatives in the subtree rooted at the current node
        return count;
    }

    // Perform DFS from the capital city
    dfs(0, -1);
    // Return the minimum fuel cost
    return result;
}

function countPalindromicSubsequence(s) {
    const MOD = 1e9 + 7;
    const n = s.length;
    const D = 10; // digits 0-9

    // prefPairForJ[j][a][b] = # pairs (p0<p1<j) with s[p0]=a, s[p1]=b
    const prefPairForJ = new Array(n);
    {
        const pairCount = Array.from({length: D}, () => new Array(D).fill(0));
        const leftCount = new Array(D).fill(0);
        for (let j = 0; j < n; j++) {
            prefPairForJ[j] = pairCount.map(row => row.slice());
            const d = +s[j];
            for (let a = 0; a < D; a++) pairCount[a][d] += leftCount[a];
            leftCount[d]++;
        }
    }

    // suffPairForJ[j][b][a] = # pairs (p3<p4), both > j, with s[p3]=b, s[p4]=a
    const suffPairForJ = new Array(n);
    {
        const pairCount = Array.from({length: D}, () => new Array(D).fill(0));
        const rightCount = new Array(D).fill(0);
        for (let m = n - 1; m >= 0; m--) {
            suffPairForJ[m] = pairCount.map(row => row.slice());
            const d = +s[m];
            for (let a = 0; a < D; a++) pairCount[d][a] += rightCount[a];
            rightCount[d]++;
        }
    }

    // A length-5 palindromic subsequence is p0<p1<p2<p3<p4 with s[p0]=s[p4]
    // and s[p1]=s[p3] (p2 is any digit in between). Fix p2 = j and multiply
    // the number of matching (p0,p1) pairs before j by the number of
    // matching (p3,p4) pairs after j, for every digit combination.
    let total = 0;
    for (let j = 0; j < n; j++) {
        const pre = prefPairForJ[j], suf = suffPairForJ[j];
        for (let a = 0; a < D; a++) {
            for (let b = 0; b < D; b++) {
                total = (total + pre[a][b] * suf[b][a]) % MOD;
            }
        }
    }
    return total;
}

function splitMessage(message, limit) {
    const n = message.length;
    function digits(x) { return String(x).length; }

    // find smallest totalParts b such that capacity >= n
    let totalParts = -1;
    let b = 1;
    while (b <= n) {
        let capacity = 0;
        let feasible = true;
        const bDigits = digits(b);
        for (let i = 1; i <= b; i++) {
            const avail = limit - (3 + digits(i) + bDigits);
            if (avail <= 0) { feasible = false; break; }
            capacity += avail;
            if (capacity >= n) break;
        }
        if (feasible && capacity >= n) { totalParts = b; break; }
        b++;
    }
    if (totalParts === -1) return [];

    let result = [];
    let index = 0;
    while (index < message.length) {
        const suffix = '<' + (result.length + 1) + '/' + totalParts + '>';
        let partLength = Math.min(limit - suffix.length, message.length - index);
        result.push(message.substring(index, index + partLength) + suffix);
        index += partLength;
    }
    return result;
}

function maxPoints(grid, queries) {
    const m = grid.length;
    const n = grid[0].length;
    const result = [];
    for (let query of queries) {
        let count = 0;
        const visited = Array.from({length: m}, () => Array(n).fill(false));
        const queue = [[0, 0]];
        if (grid[0][0] < query) {
            visited[0][0] = true;
            let head = 0;
            while (head < queue.length) {
                const [x, y] = queue[head++];
                count++; // points earned = number of cells reachable, not their sum
                for (const [dx, dy] of [[-1, 0], [1, 0], [0, -1], [0, 1]]) {
                    const nx = x + dx;
                    const ny = y + dy;
                    // only expand into (and mark visited) a neighbor whose
                    // value is also strictly less than the query - visiting
                    // an unvisited-but-blocked cell here would incorrectly
                    // stop it from ever being explored via a valid path
                    if (nx >= 0 && nx < m && ny >= 0 && ny < n && !visited[nx][ny] && grid[nx][ny] < query) {
                        queue.push([nx, ny]);
                        visited[nx][ny] = true;
                    }
                }
            }
        }
        result.push(count);
    }
    return result;
}

function minimumOperations(root) {
    let result = 0;
    let queue = [root];
    while (queue.length > 0) {
        let levelSize = queue.length;
        let levelValues = [];
        for (let i = 0; i < levelSize; i++) {
            let node = queue.shift();
            levelValues.push(node.val);
            if (node.left !== null) queue.push(node.left);
            if (node.right !== null) queue.push(node.right);
        }
        let sortedLevelValues = [...levelValues].sort((a, b) => a - b);
        // map value -> its original index, then decompose the permutation into
        // cycles: a cycle of length L needs (L-1) swaps to sort
        let indexMapping = {};
        for (let i = 0; i < levelSize; i++) indexMapping[levelValues[i]] = i;
        let visited = new Array(levelSize).fill(false);
        for (let i = 0; i < levelSize; i++) {
            if (visited[i] || levelValues[i] === sortedLevelValues[i]) continue;
            let cycleSize = 0, j = i;
            while (!visited[j]) {
                visited[j] = true;
                j = indexMapping[sortedLevelValues[j]];
                cycleSize++;
            }
            result += cycleSize - 1;
        }
    }
    return result;
}

function numberOfBeautifulPartitions(s, k, minLength) {
    const MOD = 1e9 + 7;
    const n = s.length;
    const isPrimeDigit = d => d === '2' || d === '3' || d === '5' || d === '7';
    const dp = new Array(n + 1).fill(0).map(() => new Array(k + 1).fill(0));
    dp[0][0] = 1;
    for (let i = 1; i <= n; i++) {
        for (let j = 1; j <= k; j++) {
            for (let m = minLength; m <= i; m++) {
                const start = i - m;
                // a beautiful substring starts with a prime digit and ends
                // with a non-prime digit
                if (isPrimeDigit(s[start]) && !isPrimeDigit(s[i - 1])) {
                    dp[i][j] = (dp[i][j] + dp[start][j - 1]) % MOD;
                }
            }
        }
    }
    return dp[n][k];
}

function cycleLengthQueries(n, queries) {
    function findDepth(node) {
        return Math.floor(Math.log2(node)) + 1;
    }

    function findLCA(a, b) {
        let depthA = findDepth(a);
        let depthB = findDepth(b);
        let aParent = a;
        let bParent = b;
        while (depthA > depthB) {
            // parent of node x is floor(x/2), not floor((x-1)/2)+1
            aParent = Math.floor(aParent / 2);
            depthA--;
        }
        while (depthB > depthA) {
            bParent = Math.floor(bParent / 2);
            depthB--;
        }
        while (aParent !== bParent) {
            aParent = Math.floor(aParent / 2);
            bParent = Math.floor(bParent / 2);
        }
        return aParent;
    }

    let answer = [];
    for (let i = 0; i < queries.length; i++) {
        let a = queries[i][0];
        let b = queries[i][1];
        let lca = findLCA(a, b);
        let depthA = findDepth(a);
        let depthB = findDepth(b);
        let depthLCA = findDepth(lca);
        let cycleLength = (depthA - depthLCA) + (depthB - depthLCA) + 1;
        answer.push(cycleLength);
    }
    return answer;
}

function maxStarSum(vals, edges, k) {
    // Create an adjacency list to represent the graph
    const graph = Array.from({ length: vals.length }, () => []);
    for (const [a, b] of edges) {
        graph[a].push(b);
        graph[b].push(a);
    }

    let maxSum = -Infinity;
    // Iterate over each node in the graph
    for (let i = 0; i < vals.length; i++) {
        // Sort the neighbors of the current node in descending order of their values
        const sortedNeighbors = graph[i].sort((a, b) => vals[b] - vals[a]);
        // Calculate the sum of the current node and its k largest neighbors
        let sum = vals[i];
        for (let j = 0; j < Math.min(k, sortedNeighbors.length); j++) {
            // Add the value of the current neighbor to the sum
            sum += vals[sortedNeighbors[j]];
        }
        // Update the maximum sum if the current sum is larger
        maxSum = Math.max(maxSum, sum);
    }
    return maxSum;
}

// TIME: O(n * m * log(m)) SPACE: O(n + m)

function minCommonValue(nums1, nums2) {
    let i = 0, j = 0;                       // two pointers for each array
    while (i < nums1.length && j < nums2.length) {
        if (nums1[i] === nums2[j]) return nums1[i]; // found the smallest common value
        if (nums1[i] < nums2[j]) i++;                // advance the smaller element
        else j++;                                     // advance the larger element
    }
    return -1;                                       // no common element
}

function minOperations(nums1, nums2, k) {
    let totalPos = 0;
    let sumDiff = 0;
    for (let i = 0; i < nums1.length; i++) {
        const diff = nums1[i] - nums2[i];
        if (k === 0) {
            if (diff !== 0) return -1; // k=0 can never change any difference
            continue;
        }
        if (diff % k !== 0) return -1;
        sumDiff += diff;
        if (diff > 0) totalPos += diff / k;
    }
    // operations always move +k to one index and -k to another, so the sum
    // of all differences is invariant - it must already be 0, or no
    // sequence of operations can equalize every index
    if (sumDiff !== 0) return -1;
    return totalPos;
}

function maxCost(n, edges, price) {
    const adj = Array.from({ length: n }, () => []);
    for (const [a, b] of edges) {
        adj[a].push(b);
        adj[b].push(a);
    }

    const parent = new Int32Array(n);
    parent.fill(-1);
    const order = [];
    const stack = [0];
    parent[0] = -2;
    while (stack.length) {
        const u = stack.pop();
        order.push(u);
        for (const v of adj[u]) {
            if (parent[v] === -1) {
                parent[v] = u;
                stack.push(v);
            }
        }
    }

    const down = new Array(n);
    const best1 = new Array(n).fill(0);
    const best2 = new Array(n).fill(0);
    for (let i = order.length - 1; i >= 0; i--) {
        const u = order[i];
        let maxChild = 0;
        for (const v of adj[u]) {
            if (v === parent[u]) continue;
            const val = down[v];
            if (val > maxChild) maxChild = val;
            if (val > best1[u]) {
                best2[u] = best1[u];
                best1[u] = val;
            } else if (val > best2[u]) {
                best2[u] = val;
            }
        }
        down[u] = price[u] + maxChild;
    }

    const up = new Array(n);
    up[0] = price[0];
    for (const u of order) {
        for (const v of adj[u]) {
            if (v === parent[u]) continue;
            const siblingBest = down[v] === best1[u] ? best2[u] : best1[u];
            const bestFromParent = Math.max(up[u], siblingBest);
            up[v] = price[v] + bestFromParent;
        }
    }

    let ans = 0;
    for (let i = 0; i < n; i++) {
        const maxPath = Math.max(down[i], up[i]);
        const cost = maxPath - price[i];
        if (cost > ans) ans = cost;
    }
    return ans;
}

function sortTheStudents(score, k) {
  // Sort the students based on their scores in the kth exam from highest to lowest
  return score.sort((a, b) => b[k] - a[k]);
}

function isReachable(targetX, targetY) {
    // Calculate the greatest common divisor of targetX and targetY
    function gcd(a, b) {
        if (b === 0) return a;
        return gcd(b, a % b);
    }
    // Check if the greatest common divisor of targetX and targetY is 1
    return gcd(targetX, targetY) === 1;
}

// TIME: O(log min(targetX, targetY)) SPACE: O(1)

function countQuadruplets(nums) {
    let count = 0;
    // iterate over all possible quadruplets and check if they are increasing
    for (let i = 0; i < nums.length; i++) {
        for (let j = 0; j < nums.length; j++) {
            for (let k = 0; k < nums.length; k++) {
                for (let l = 0; l < nums.length; l++) {
                    // check if the indices are distinct and the quadruplet is increasing
                    if (i < j && j < k && k < l && nums[i] < nums[k] && nums[k] < nums[j] && nums[j] < nums[l]) {
                        count++;
                    }
                }
            }
        }
    }
    return count;
}

function alternateDigitSum(n) {
    let sum = 0, sign = 1; // initialize sum and sign
    while (n > 0) { // loop through each digit
        let digit = n % 10; // get the last digit
        sum += sign * digit; // add the digit to the sum with the current sign
        n = Math.floor(n / 10); // remove the last digit
        sign *= -1; // alternate the sign
    }
    return sum; // return the final sum
}

function distinctNumbersOnBoard(n) {
    // Every number x>=2 that ends up on the board also causes x-1 to be
    // added (since x % (x-1) === 1 for any x>=2), so the process cascades
    // all the way down and every integer from 2 to n eventually appears -
    // giving n-1 distinct numbers total (or just 1 if n===1, since no i in
    // [1,1] satisfies 1 % i === 1, so nothing is ever added to {1}).
    return Math.max(1, n - 1);
}

function separateDigits(nums) {
  // Initialize an empty array to store the result
  let result = [];
  // Iterate over each number in the input array
  for (let num of nums) {
    // Convert the number to a string to easily separate its digits
    let strNum = num.toString();
    // Iterate over each character (digit) in the string
    for (let digit of strNum) {
      // Convert the character back to an integer and add it to the result array
      result.push(parseInt(digit));
    }
  }
  // Return the result array
  return result;
}

function countCollisions(n) {
    const MOD = 1000000007n;
    function powMod(base, exp, mod) {
        base %= mod;
        let result = 1n;
        while (exp > 0n) {
            if (exp & 1n) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1n;
        }
        return result;
    }
    // No-collision configurations: all monkeys move clockwise, or all move
    // counter-clockwise - always exactly 2, whether n is even or odd (there
    // is no additional even-n case)
    const total = powMod(2n, BigInt(n), MOD);
    const noCollisions = 2n;
    let result = (total - noCollisions) % MOD;
    if (result < 0n) result += MOD;
    return Number(result);
}

function maxScore(nums1, nums2, k) {
    const n = nums1.length;
    const order = Array.from({ length: n }, (_, i) => i);
    order.sort((a, b) => nums2[b] - nums2[a]); // sort by nums2 descending

    const heap = [];          // min‑heap of selected nums1 values
    let sum = 0;              // sum of values currently in the heap
    let best = 0;             // best score found

    for (let i = 0; i < n; i++) {
        const idx = order[i];
        const v = nums1[idx];
        heapPush(heap, v);    // add current nums1 value
        sum += v;

        if (heap.length > k) {            // keep only the k largest nums1 values
            sum -= heapPop(heap);          // remove smallest
        }

        if (heap.length === k) {          // we have a full candidate subsequence
            const score = sum * nums2[idx]; // current nums2 is the minimum
            if (score > best) best = score;
        }
    }
    return best;
}

/* min‑heap helpers */
function heapPush(heap, val) {
    heap.push(val);
    let i = heap.length - 1;
    while (i > 0) {
        const p = (i - 1) >> 1;
        if (heap[p] <= heap[i]) break;
        [heap[p], heap[i]] = [heap[i], heap[p]];
        i = p;
    }
}
function heapPop(heap) {
    const min = heap[0];
    const last = heap.pop();
    if (heap.length) {
        heap[0] = last;
        let i = 0;
        while (true) {
            let l = i * 2 + 1,
                r = i * 2 + 2,
                smallest = i;
            if (l < heap.length && heap[l] < heap[smallest]) smallest = l;
            if (r < heap.length && heap[r] < heap[smallest]) smallest = r;
            if (smallest === i) break;
            [heap[i], heap[smallest]] = [heap[smallest], heap[i]];
            i = smallest;
        }
    }
    return min;
}

function incrementSubmatrices(n, queries) {
    // difference array (size n+1 to avoid boundary checks)
    const diff = Array.from({ length: n + 1 }, () => Array(n + 1).fill(0));

    // apply each query to the difference array
    for (let i = 0; i < queries.length; i++) {
        const [r1, c1, r2, c2] = queries[i];
        diff[r1][c1] += 1;
        diff[r1][c2 + 1] -= 1;
        diff[r2 + 1][c1] -= 1;
        diff[r2 + 1][c2 + 1] += 1;
    }

    // compute 2‑D prefix sums to obtain the final matrix values
    for (let i = 0; i <= n; i++) {
        for (let j = 0; j <= n; j++) {
            if (i > 0) diff[i][j] += diff[i - 1][j];
            if (j > 0) diff[i][j] += diff[i][j - 1];
            if (i > 0 && j > 0) diff[i][j] -= diff[i - 1][j - 1];
        }
    }

    // extract the n×n result matrix
    const result = Array.from({ length: n }, () => Array(n));
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            result[i][j] = diff[i][j];
        }
    }
    return result;
}

function disconnectPathInABinaryMatrixByAtMostOneFlip(grid) {
    const m = grid.length, n = grid[0].length;
    const f = Array.from({length: m}, () => new Array(n).fill(false));
    if (grid[0][0] === 1) f[0][0] = true;
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] !== 1) continue;
            if (i > 0 && f[i - 1][j]) f[i][j] = true;
            if (j > 0 && f[i][j - 1]) f[i][j] = true;
            if (i === 0 && j === 0) f[i][j] = true;
        }
    }
    if (!f[m - 1][n - 1]) return true;

    const totalDiagonals = m + n - 1;
    const cnt = new Array(totalDiagonals).fill(0);
    const cellI = new Array(totalDiagonals).fill(-1);
    const cellJ = new Array(totalDiagonals).fill(-1);

    let bNext = new Array(n).fill(false);
    for (let i = m - 1; i >= 0; i--) {
        const bCurr = new Array(n).fill(false);
        for (let j = n - 1; j >= 0; j--) {
            if (grid[i][j] !== 1) continue;
            if (i === m - 1 && j === n - 1) {
                bCurr[j] = true;
            } else {
                if (i < m - 1 && bNext[j]) bCurr[j] = true;
                if (j < n - 1 && bCurr[j + 1]) bCurr[j] = true;
            }
            if (bCurr[j] && f[i][j]) {
                const k = i + j;
                if (cnt[k] === 0) { cellI[k] = i; cellJ[k] = j; }
                cnt[k]++;
            }
        }
        bNext = bCurr;
    }

    for (let k = 0; k < totalDiagonals; k++) {
        if (cnt[k] === 1) {
            const i = cellI[k], j = cellJ[k];
            if (!(i === 0 && j === 0) && !(i === m - 1 && j === n - 1)) return true;
        }
    }
    return false;
}

function minimumImpossibleOR(nums) {
