}

function minTime(grid) {
    const m = grid.length, n = grid[0].length;
    const INF = Infinity;
    const dist = Array.from({length: m}, () => new Array(n).fill(INF));
    const dirs = [[1,0],[-1,0],[0,1],[0,-1]];

    const startTime = Math.max(0, grid[0][0]);
    dist[0][0] = startTime;
    // min-heap via simple array (small enough with lazy deletion pattern)
    const heap = [[startTime, 0, 0]];
    const heapPush = (item) => {
        heap.push(item);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p][0] <= heap[i][0]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]];
            i = p;
        }
    };
    const heapPop = () => {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            let i = 0;
            while (true) {
                let l = 2*i+1, r = 2*i+2, smallest = i;
                if (l < heap.length && heap[l][0] < heap[smallest][0]) smallest = l;
                if (r < heap.length && heap[r][0] < heap[smallest][0]) smallest = r;
                if (smallest === i) break;
                [heap[i], heap[smallest]] = [heap[smallest], heap[i]];
                i = smallest;
            }
        }
        return top;
    };

    while (heap.length) {
        const [time, r, c] = heapPop();
        if (time !== dist[r][c]) continue;
        if (r === m - 1 && c === n - 1) return time;
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                let arrival = time + 1;
                if (arrival >= grid[nr][nc]) {
                    if (arrival < dist[nr][nc]) {
                        dist[nr][nc] = arrival;
                        heapPush([arrival, nr, nc]);
                    }
                }
            }
        }
    }
    return -1;
}

