function onesMinusZeros(grid) {
    var m = grid.length, n = grid[0].length;
    var rowOnes = new Array(m).fill(0);
    var colOnes = new Array(n).fill(0);

    // Calculate the number of ones in each row and column
    for (var i = 0; i < m; i++) {
        for (var j = 0; j < n; j++) {
            if (grid[i][j] === 1) {
                rowOnes[i]++;
                colOnes[j]++;
            }
        }
    }

    var diff = new Array(m);
    for (var i = 0; i < m; i++) {
        diff[i] = new Array(n);
        for (var j = 0; j < n; j++) {
