            diff[i][j] = rowOnes[i] + colOnes[j] - (m - rowOnes[i]) - (n - colOnes[j]);
        }
    }

    return diff;
}

function countWays(ranges) {
    const MOD = 1000000007;                     // 1e9+7

    // sort by start, then by end
    ranges.sort((a, b) => a[0] - b[0] || a[1] - b[1]);

    let components = 0;
    let curEnd = -Infinity;                     // end of current component

    // MAIN LOGIC: count disjoint merged intervals
    for (let i = 0; i < ranges.length; i++) {
        const [s, e] = ranges[i];
        if (s > curEnd) {                       // starts a new component
            components++;
            curEnd = e;
        } else {
            if (e > curEnd) curEnd = e;         // extend current component
        }
    }

    // compute 2^components modulo MOD
    let ans = 1;
    for (let i = 0; i < components; i++) {
        ans = (ans * 2) % MOD;
    }
    return ans;
}

function findTheString(lcp) {
    const n = lcp.length;
    // basic validation: square matrix
    for (let i = 0; i < n; i++) {
        if (!Array.isArray(lcp[i]) || lcp[i].length !== n) return "";
    }
    // diagonal and symmetry checks
    for (let i = 0; i < n; i++) {
        if (lcp[i][i] !== n - i) return "";
        for (let j = i + 1; j < n; j++) {
            if (lcp[i][j] !== lcp[j][i]) return "";
        }
    }

    // Disjoint Set Union
    class DSU {
        constructor(size) {
            this.parent = new Array(size);
            this.rank = new Array(size).fill(0);
            for (let i = 0; i < size; i++) this.parent[i] = i;
        }
        find(x) {
            if (this.parent[x] !== x) this.parent[x] = this.find(this.parent[x]);
            return this.parent[x];
        }
        union(a, b) {
            let ra = this.find(a), rb = this.find(b);
            if (ra === rb) return;
            if (this.rank[ra] < this.rank[rb]) {
                this.parent[ra] = rb;
            } else if (this.rank[ra] > this.rank[rb]) {
                this.parent[rb] = ra;
            } else {
                this.parent[rb] = ra;
                this.rank[ra]++;
            }
        }
    }

    const dsu = new DSU(n);

    // Validate recurrence and union equality constraints
    for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
            const v = lcp[i][j];
            if (v > 0) {
                if (i + 1 < n && j + 1 < n) {
                    if (v !== 1 + lcp[i + 1][j + 1]) return "";
                } else {
                    // one of the suffixes length is 1
                    if (v !== 1) return "";
                }
                dsu.union(i, j);
            }
        }
    }

    // Build inequality graph
    const adj = Array.from({ length: n }, () => new Set());
    for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
            const maxCommon = Math.min(n - i, n - j);
            const v = lcp[i][j];
            if (v < maxCommon) {
                const a = i + v;
                const b = j + v;
                const ra = dsu.find(a);
                const rb = dsu.find(b);
                if (ra === rb) return ""; // need different letters within same component
                adj[ra].add(rb);
                adj[rb].add(ra);
            }
        }
    }

    // Assign letters greedily to components
    const compChar = new Array(n);
    const result = new Array(n);
    for (let i = 0; i < n; i++) {
        const root = dsu.find(i);
        if (compChar[root] === undefined) {
            const used = new Array(26).fill(false);
            for (const nb of adj[root]) {
                const ch = compChar[nb];
                if (ch !== undefined) used[ch.charCodeAt(0) - 97] = true;
            }
            let letter = null;
            for (let c = 0; c < 26; c++) {
                if (!used[c]) {
                    letter = String.fromCharCode(97 + c);
                    break;
                }
            }
            if (letter === null) return ""; // more than 26 colors needed
            compChar[root] = letter;
        }
        result[i] = compChar[root];
    }

    return result.join('');
}

function countNumberOfPossibleRootNodes(edges, guesses, k) {
    const n = edges.length + 1;
    const adj = Array.from({length: n}, () => []);
    for (const [a, b] of edges) { adj[a].push(b); adj[b].push(a); }

    const guessSet = new Set(guesses.map(([u, v]) => u + ',' + v));

    const parent = new Array(n).fill(-1);
    let stack = [[0, -1]];
    let initialCorrect = 0;
    while (stack.length) {
        const [node, par] = stack.pop();
        parent[node] = par;
        for (const nb of adj[node]) {
            if (nb === par) continue;
            stack.push([nb, node]);
            if (guessSet.has(node + ',' + nb)) initialCorrect++;
        }
    }

    let answer = 0;
    stack = [[0, -1, initialCorrect]];
    while (stack.length) {
        const [node, par, correct] = stack.pop();
        if (correct >= k) answer++;
        for (const nb of adj[node]) {
            if (nb === par) continue;
            let newCorrect = correct;
            if (guessSet.has(node + ',' + nb)) newCorrect--;
            if (guessSet.has(nb + ',' + node)) newCorrect++;
            stack.push([nb, node, newCorrect]);
        }
    }
    return answer;
}

function numberOfWaysToEarnPoints(target, types) {
    const MOD = 1000000007n;
    let dp = new Array(target + 1).fill(0n);
    dp[0] = 1n;
    for (const [count, marks] of types) {
        const newDp = new Array(target + 1).fill(0n);
        for (let curSum = 0; curSum <= target; curSum++) {
            const ways = dp[curSum];
            if (!ways) continue;
            const maxK = Math.min(count, Math.floor((target - curSum) / marks));
            for (let k = 0; k <= maxK; k++) {
                const nxt = curSum + k * marks;
                newDp[nxt] = (newDp[nxt] + ways) % MOD;
            }
        }
        dp = newDp;
    }
    return Number(dp[target]);
}

function splitWithMinimumSum(num) {
    // Convert number to array of its digits
    var digits = String(num).split('').map(Number);
    // Sort digits ascending
    digits.sort((a, b) => a - b);
    var a = '', b = '';
    // Distribute sorted digits alternately to form two numbers with minimal sum
    for (var i = 0; i < digits.length; i++) {
        if (i % 2 === 0) a += digits[i];
        else b += digits[i];
    }
    // Empty strings become 0 when converted to Number
    return Number(a) + Number(b);
}

function minTime(tasks) {
    tasks.sort((a, b) => a[1] - b[1] || a[0] - b[0]);

    const on = new Set();
    let total = 0;

    for (let i = 0; i < tasks.length; ++i) {
        const [l, r, d] = tasks[i];

        // FIRST count seconds already on within this task's range - those
        // are free, since the computer can run multiple tasks at once and
        // an already-on second satisfies every task whose range includes it
        let alreadyOn = 0;
        for (let t = l; t <= r; ++t) if (on.has(t)) alreadyOn++;
        let need = d - alreadyOn;
        if (need <= 0) continue;

        // only now add the REMAINING needed seconds, placed as far right
        // as possible so they stay useful for later tasks (equal/larger r)
        for (let t = r; t >= l && need > 0; --t) {
            if (!on.has(t)) {
                on.add(t);
                ++total;
                --need;
            }
        }
    }
    return total;
}

function countVowelStrings(words, left, right) {
