function countBeautifulSubarrays(nums) {
    // prefix xor while scanning
    let xor = 0;
    // map: xor value -> how many times it has appeared
    const freq = new Map();
    freq.set(0, 1);               // empty prefix
    let answer = 0;

    for (let i = 0; i < nums.length; ++i) {
        xor ^= nums[i];            // update prefix xor
        const seen = freq.get(xor) || 0;
        answer += seen;            // each previous same xor forms a beautiful subarray
        freq.set(xor, seen + 1);   // record current prefix xor
    }
    return answer;
}

function maxScore(nums) {
    // 1. sort descending – largest numbers first
    nums.sort(function(a, b) { return b - a; });

    let pref = 0;          // current prefix sum
    let answer = 0;        // number of positive prefixes

    // 2. scan the sorted array
    for (let i = 0; i < nums.length; ++i) {
        pref += nums[i];               // update prefix sum
        if (pref > 0) answer++;        // count if positive
    }
    return answer;
}

function distMoney(money, children) {
    if (money < children) return -1;
    let extra = money - children;
    let eights = Math.min(Math.floor(extra/7), children);
    let leftover = extra - eights*7;
    let remainingChildren = children - eights;
    if (remainingChildren === 0) {
        if (leftover > 0) eights -= 1;
    } else if (remainingChildren === 1) {
        if (leftover === 3) eights -= 1;
    }
    return eights;
}

function minRepairTime(ranks, cars) {
    // lower bound (impossible) and upper bound (fastest mechanic alone)
    let low = 0;
    let minRank = Math.min(...ranks);
    let high = minRank * cars * cars; // MAIN LOGIC: binary search interval

    while (low < high) {
        const mid = Math.floor((low + high) / 2);

        // MAIN LOGIC: check if 'mid' minutes are enough
        let total = 0;
        for (let i = 0; i < ranks.length; i++) {
            total += Math.floor(Math.sqrt(mid / ranks[i]));
            if (total >= cars) break; // early exit
        }

        if (total >= cars) {
            high = mid;          // feasible → try smaller time
        } else {
            low = mid + 1;       // infeasible → need more time
        }
    }
    return low;
}

function countEvenOddBits(n) {
    let even = 0, odd = 0, i = 0;
    while (n > 0) {
        if (n & 1) {                     // main logic: check current bit
            if ((i & 1) === 0) even++;   // even index
            else odd++;                  // odd index
        }
        n >>= 1;   // drop the processed bit
        i++;       // move to next index
    }
    return [even, odd];
