function findScore(nums) {
    const n = nums.length;
    const pos = Array.from({ length: n }, (_, i) => i);
    // sort indices by value, then by index to break ties left‑most first
    pos.sort((a, b) => nums[a] === nums[b] ? a - b : nums[a] - nums[b]);

    const marked = new Array(n).fill(false);
    let score = 0;

    for (let i = 0; i < n; i++) {
        const p = pos[i];
        if (marked[p]) continue;               // already taken by a previous step
        score += nums[p];                       // take this element
        marked[p] = true;                       // mark itself
        if (p > 0) marked[p - 1] = true;        // mark left neighbour
        if (p < n - 1) marked[p + 1] = true;    // mark right neighbour
    }
    return score;
}

function maximizeGreatness(nums) {
    const n = nums.length;
    const sortedOrig = [...nums].sort((a, b) => a - b);   // original values sorted
    const sortedPerm = [...nums].sort((a, b) => a - b);   // same values, will be used as perm

    let i = 0, j = 0, greatness = 0;
    // main greedy loop: try to beat each original element with the smallest possible larger element
    while (i < n && j < n) {
        if (sortedPerm[j] > sortedOrig[i]) { // win this position
            greatness++;
            i++;
            j++;
        } else { // too small, discard this perm element
            j++;
        }
    }
    return greatness;
}

function countBeautifulSubsets(nums, k) {
    const cnt = new Map();
    for (const x of nums) {
        cnt.set(x, (cnt.get(x) || 0) + 1);
    }
    const values = Array.from(cnt.keys()).sort((a, b) => a - b);
    let totalWays = 1;
    let i = 0;
    while (i < values.length) {
        const chain = [];
        while (i < values.length && (chain.length === 0 || values[i] - chain[chain.length - 1] === k)) {
            chain.push(values[i]);
            i++;
        }
        const w = chain.map(v => (1 << cnt.get(v)) - 1);
        let dpPrev2 = 1; // dp[-1]
        let dpPrev1 = 1 + w[0]; // dp[0]
        for (let j = 1; j < w.length; j++) {
            const cur = dpPrev1 + dpPrev2 * w[j];
            dpPrev2 = dpPrev1;
            dpPrev1 = cur;
        }
        totalWays *= dpPrev1;
    }
    return totalWays - 1;
}

function smallestMissingNonNegativeIntegerAfterOperations(nums, value) {
