function kthLargestLevelSum(root, k) {
    if (!root) return -1;                     // empty tree

    // ---------- BFS to compute level sums ----------
    const queue = [root];
    let head = 0;                             // index of current element
    const minHeap = [];                       // stores up to k largest sums

    // heap helpers (min‑heap)
    function heapPush(val) {
        minHeap.push(val);
        let i = minHeap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (minHeap[p] <= minHeap[i]) break;
            [minHeap[p], minHeap[i]] = [minHeap[i], minHeap[p]];
            i = p;
        }
    }
    function heapReplaceRoot(val) {           // pop min and push new value
        minHeap[0] = val;
        let i = 0;
        while (true) {
            let l = i * 2 + 1, r = i * 2 + 2, smallest = i;
            if (l < minHeap.length && minHeap[l] < minHeap[smallest]) smallest = l;
            if (r < minHeap.length && minHeap[r] < minHeap[smallest]) smallest = r;
            if (smallest === i) break;
            [minHeap[i], minHeap[smallest]] = [minHeap[smallest], minHeap[i]];
            i = smallest;
        }
    }

    while (head < queue.length) {
        const levelSize = queue.length - head;   // nodes on current level
        let levelSum = 0;
        for (let i = 0; i < levelSize; i++) {
            const node = queue[head++];
            levelSum += node.val;
            if (node.left) queue.push(node.left);
            if (node.right) queue.push(node.right);
        }
        // ---------- keep only k largest sums ----------
        if (minHeap.length < k) {
            heapPush(levelSum);                   // fill heap
        } else if (levelSum > minHeap[0]) {
            heapReplaceRoot(levelSum);            // replace smallest
        }
    }

    return minHeap.length === k ? minHeap[0] : -1;
}

function primeSubOperation(nums) {
  const LIMIT = 1000;
  const isComposite = new Array(LIMIT + 1).fill(false);
  const primes = [];
  for (let i = 2; i <= LIMIT; i++) {
    if (!isComposite[i]) { primes.push(i); for (let j = i*i; j <= LIMIT; j += i) isComposite[j] = true; }
  }
  let prevMax = 0;
  for (let i = 0; i < nums.length; i++) {
    const upperBound = nums[i] - prevMax - 1; // largest prime p allowed such that nums[i]-p > prevMax
    if (upperBound < 0) { 
      if (nums[i] <= prevMax) return false;
      prevMax = nums[i];
      continue;
    }
    // find largest prime <= upperBound
    let lo = 0, hi = primes.length;
    while (lo < hi) { const mid=(lo+hi)>>1; if (primes[mid] <= upperBound) lo=mid+1; else hi=mid; }
    const best = lo > 0 ? primes[lo-1] : 0;
    const newVal = nums[i] - best;
    if (newVal <= prevMax) return false;
    prevMax = newVal;
  }
  return true;
}

function checkValidKnightTour(grid) {
    const n = grid.length;
    const total = n * n;
    const pos = new Array(total);               // store (row,col) for each step number

    // fill positions array
    for (let r = 0; r < n; r++) {
        for (let c = 0; c < n; c++) {
            const v = grid[r][c];
            if (v < 0 || v >= total) return false; // out‑of‑range value
            pos[v] = [r, c];
        }
    }

    // start must be top‑left
    if (grid[0][0] !== 0) return false;

    // verify every consecutive move
    for (let k = 0; k < total - 1; k++) {
        const [r1, c1] = pos[k];
        const [r2, c2] = pos[k + 1];
        const dr = Math.abs(r1 - r2);
        const dc = Math.abs(c1 - c2);
        const ok = (dr === 1 && dc === 2) || (dr === 2 && dc === 1);
        if (!ok) return false;
    }
    return true;
}

function smallestNumber(nums1, nums2) {
    // find the smallest common digit, if any
    const present = new Array(10).fill(false);
    for (const d of nums1) present[d] = true;

    let bestCommon = 10;
    for (const d of nums2) {
        if (present[d] && d < bestCommon) bestCommon = d;
    }
    if (bestCommon < 10) return bestCommon; // return a number, not a string

    // no common digit -> use two different digits
    let min1 = 10, min2 = 10;
    for (const d of nums1) if (d < min1) min1 = d;
    for (const d of nums2) if (d < min2) min2 = d;

    const cand1 = min1 * 10 + min2;
    const cand2 = min2 * 10 + min1;
    return Math.min(cand1, cand2);
}

function minOperations(nums, queries) {
    // ----- preprocessing -----
    const n = nums.length;
    const sorted = nums.slice().sort((a, b) => a - b);   // O(n log n)
    const pref = new Array(n);
    let sum = 0;
    for (let i = 0; i < n; i++) {
        sum += sorted[i];
        pref[i] = sum;                                    // prefix sums
    }
    const total = sum;

    // ----- answer each query -----
    const res = new Array(queries.length);
    for (let qi = 0; qi < queries.length; qi++) {
        const t = queries[qi];

        // binary search: first index > t (upper bound)
        let lo = 0, hi = n;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (sorted[mid] <= t) lo = mid + 1;
            else hi = mid;
        }
        const k = lo;                     // count of elements ≤ t

        // left side contribution
        const left = k === 0 ? 0 : t * k - pref[k - 1];
        // right side contribution
        const right = k === n ? 0 : (total - (k === 0 ? 0 : pref[k - 1])) - t * (n - k);

        res[qi] = left + right;           // total operations for this query
    }
    return res;
}

function maxCostSubstring(s, chars, vals) {
    // build a map from character to its custom value
    const valueMap = {};
    for (let i = 0; i < chars.length; i++) {
        valueMap[chars[i]] = vals[i];
    }

    let cur = 0;   // current subarray sum (never negative)
    let best = 0;  // best sum seen so far

    for (let i = 0; i < s.length; i++) {
        // get cost of s[i]: custom value if present, otherwise 1
        const cost = (s[i] in valueMap) ? valueMap[s[i]] : 1;
        // Kadane's step: extend or restart the subarray
        cur = Math.max(0, cur + cost);
        // update global maximum
        if (cur > best) best = cur;
    }
    return best;
}

function collectCoins(coins, edges) {
    const n = coins.length;
    const adj = Array.from({ length: n }, () => []);
    const degree = new Array(n).fill(0);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
        degree[u]++;
        degree[v]++;
    }
    const removed = new Array(n).fill(false);
    const queue = [];
    let qh = 0;
    for (let i = 0; i < n; i++) {
        if (degree[i] === 1 && coins[i] === 0) queue.push(i);
    }
    while (qh < queue.length) {
        const node = queue[qh++];
        removed[node] = true;
        for (const nb of adj[node]) {
            if (removed[nb]) continue;
            degree[nb]--;
            if (degree[nb] === 1 && coins[nb] === 0) queue.push(nb);
        }
    }

    // After trimming all non-coin leaves, we're left with the minimal
    // subtree spanning every coin. But a walk never needs to travel all
    // the way to a node exactly 1 or 2 hops past the last required branch
    // point and back for nothing - trim 2 MORE layers of leaves (this
    // time regardless of coin) to find the true minimal walk-worthy core.
    for (let round = 0; round < 2; round++) {
        const next = [];
        for (let i = 0; i < n; i++) {
            if (!removed[i] && degree[i] === 1) next.push(i);
        }
        for (const node of next) {
            removed[node] = true;
            for (const nb of adj[node]) {
                if (removed[nb]) continue;
                degree[nb]--;
            }
        }
    }

    let edgeCount = 0;
    for (const [u, v] of edges) {
        if (!removed[u] && !removed[v]) edgeCount++;
    }
    return edgeCount * 2;
}

function convertArray(nums) {
    const freq = {};
    let maxFreq = 0;
    for (let i = 0; i < nums.length; i++) {
        const v = nums[i];
        freq[v] = (freq[v] || 0) + 1;
        if (freq[v] > maxFreq) maxFreq = freq[v];
    }

    // order distinct values by frequency descending, then by value
    // descending, matching the expected row layout
    const entries = Object.entries(freq)
        .map(([k, v]) => [Number(k), v])
        .sort((a, b) => b[1] - a[1] || b[0] - a[0]);

    const rows = Array.from({ length: maxFreq }, () => []);
    for (const [num, count] of entries) {
        for (let i = 0; i < count; i++) {
            rows[i].push(num);
        }
    }
    return rows;
}

function makeKSubarraySumsEqual(arr, k) {
    const n = arr.length;
    if (n === 0) return 0;
    const gcd = (a, b) => b === 0 ? a : gcd(b, a % b);
    const g = gcd(n, k);
    const cycleLen = n / g;
    let totalOps = 0;

    for (let start = 0; start < g; start++) {
        const vals = [];
        let idx = start;
        for (let i = 0; i < cycleLen; i++) {
            vals.push(arr[idx]);
            idx = (idx + k) % n;
        }
        vals.sort((a, b) => a - b);
        const median = vals[Math.floor(cycleLen / 2)];
        for (const v of vals) totalOps += Math.abs(v - median);
    }
    return totalOps;
}

function longestBalancedSubstring(s) {
    let maxLen = 0;
    let i = 0;
    const n = s.length;
    // process the string as consecutive (zero-run, one-run) pairs directly
    while (i < n) {
        let zeros = 0, ones = 0;
        while (i < n && s[i] === '0') { zeros++; i++; }
        while (i < n && s[i] === '1') { ones++; i++; }
        maxLen = Math.max(maxLen, 2 * Math.min(zeros, ones));
    }
    return maxLen;
}

function minimumReverseOperations(n, p, banned, k) {
    const dist = new Array(n).fill(-1);
    const visited = new Array(n).fill(false);
    const parent = new Array(n + 2);
    for (let i = 0; i <= n + 1; i++) parent[i] = i;

    function find(x) {
        if (x > n) return n;
        if (parent[x] !== x) parent[x] = find(parent[x]);
        return parent[x];
    }
    function remove(x) {
        parent[x] = find(x + 2);
    }

    for (const b of banned) {
        visited[b] = true;
        remove(b);
    }
    visited[p] = true;
    dist[p] = 0;
    remove(p);

    const queue = new Array(n);
    let head = 0, tail = 0;
    queue[tail++] = p;

    while (head < tail) {
        const x = queue[head++];
        const low = Math.max(0, x - (k - 1));
        const high = Math.min(n - 1, x + (k - 1));
        const needParity = (x + k - 1) & 1;
        let start = low;
        if ((start & 1) !== needParity) start++;
        for (let idx = find(start); idx <= high; idx = find(idx + 2)) {
            visited[idx] = true;
            dist[idx] = dist[x] + 1;
            queue[tail++] = idx;
            remove(idx);
        }
    }
    return dist;
}

function shortestCycle(n, edges) {
    // build adjacency list
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }

    let best = Infinity;

    // run BFS from every vertex
    for (let start = 0; start < n; start++) {
        const dist = new Int32Array(n).fill(-1);
        const parent = new Int32Array(n).fill(-1);
        const queue = [];
        let qHead = 0;

        dist[start] = 0;
        queue.push(start);

        while (qHead < queue.length) {
            const u = queue[qHead++];
            for (const v of adj[u]) {
                if (dist[v] === -1) {               // first time we see v
                    dist[v] = dist[u] + 1;
                    parent[v] = u;
                    queue.push(v);
                } else if (parent[u] !== v) {       // visited via a different edge → cycle
                    const cycleLen = dist[u] + dist[v] + 1;
                    if (cycleLen < best) best = cycleLen;
                }
            }
        }
    }

    return best === Infinity ? -1 : best;
}



// TIME: O(n·(n+m)) SPACE: O(n+m)

function maxSum(numOnes, numZeros, numNegOnes, k) {
    // take as many 1's as possible
    var onesTaken = Math.min(numOnes, k);
    var remaining = k - onesTaken;

    // then take as many 0's as needed
    var zerosTaken = Math.min(numZeros, remaining);
    remaining -= zerosTaken;

    // whatever is still needed must be -1's
    var negOnesTaken = remaining; // remaining ≤ numNegOnes by problem guarantee

    // zeros add 0, -1's subtract 1 each
    return onesTaken - negOnesTaken;
}

function minimumNumberOfVisitedCellsInAGrid(grid) {
    const m = grid.length, n = grid[0].length;
    if (m === 1 && n === 1) return 1;

    const rowParent = Array.from({length: m}, () => Array.from({length: n + 1}, (_, i) => i));
    const colParent = Array.from({length: n}, () => Array.from({length: m + 1}, (_, i) => i));

    const findRow = (r, c) => {
        while (rowParent[r][c] !== c) {
            rowParent[r][c] = rowParent[r][rowParent[r][c]];
            c = rowParent[r][c];
        }
        return c;
    };
    const findCol = (c, r) => {
        while (colParent[c][r] !== r) {
            colParent[c][r] = colParent[c][colParent[c][r]];
            r = colParent[c][r];
        }
        return r;
    };

    const q = [[0, 0, 1]];
    let head = 0;
    rowParent[0][0] = 1;
    colParent[0][0] = 1;

    while (head < q.length) {
        const [i, j, dist] = q[head++];
        if (i === m - 1 && j === n - 1) return dist;
        const jump = grid[i][j];
        if (jump === 0) continue;

        let limit = Math.min(n - 1, j + jump);
        let col = findRow(i, j + 1);
        while (col <= limit) {
            q.push([i, col, dist + 1]);
            rowParent[i][col] = col + 1;
            colParent[col][i] = i + 1;
            col = findRow(i, col + 1);
        }

        limit = Math.min(m - 1, i + jump);
        let row = findCol(j, i + 1);
        while (row <= limit) {
            q.push([row, j, dist + 1]);
            rowParent[row][j] = j + 1;
            colParent[j][row] = row + 1;
            row = findCol(j, row + 1);
        }
    }
    return -1;
}

function maxPoints(reward1, reward2, k) {
    var n = reward1.length;
    var base = 0;
    var diffs = new Array(n);
    for (var i = 0; i < n; i++) {
        base += reward2[i];                 // base points if second mouse eats all
        diffs[i] = reward1[i] - reward2[i]; // extra gain if first mouse eats this cheese
    }
    diffs.sort(function(a, b) { return b - a; }); // sort diffs descending to pick largest gains
    var add = 0;
    for (var i = 0; i < k; i++) {
        add += diffs[i];                    // sum the k largest differences
    }
    return base + add;
}

function largestPrimeDiagonal(nums) {
    const rows = nums.length;
    const cols = nums[0].length;
    let maxPrime = 0;

    // iterate over each row, checking main and anti‑diagonal elements
    for (let i = 0; i < rows; i++) {
        // main diagonal
        if (i < cols) {
            const v = nums[i][i];
            if (v > maxPrime && isPrime(v)) maxPrime = v;
        }

        // anti‑diagonal
        const j = cols - 1 - i;
        if (j >= 0 && j < cols && j !== i) { // avoid double‑counting centre
            const v = nums[i][j];
            if (v > maxPrime && isPrime(v)) maxPrime = v;
        }
    }
    return maxPrime;
}

// trial division primality test
function isPrime(x) {
    if (x <= 1) return false;
    if (x <= 3) return true;
    if (x % 2 === 0) return false;
    const limit = Math.floor(Math.sqrt(x));
    for (let d = 3; d <= limit; d += 2) {
        if (x % d === 0) return false;
    }
    return true;
}

function minimizeMaxDifference(nums, p) {
    if (p === 0) return 0;                     // no pairs needed
    const a = nums.slice().sort((x, y) => x - y); // sort the values

    // binary search on the answer
    let low = 0, high = a[a.length - 1] - a[0];
    while (low < high) {
        const mid = Math.floor((low + high) / 2);
        // can we make at least p pairs with diff ≤ mid ?
        let cnt = 0;
        for (let i = 0; i + 1 < a.length; ) {
            if (a[i + 1] - a[i] <= mid) { // take this pair
                cnt++;
                i += 2;
            } else {
                i++;                       // skip left element
            }
        }
        if (cnt >= p) high = mid;          // mid is feasible
        else low = mid + 1;                // need larger limit
    }
    return low;
}

function checkIfInstanceOf(value, cls) {
    if (typeof cls !== 'function') return false;
    if (value === null || value === undefined) return false;
    // box primitives (numbers, strings, booleans) so they get a real prototype chain
    const obj = Object(value);
    let proto = Object.getPrototypeOf(obj);
    while (proto !== null) {
        if (proto === cls.prototype) return true;
        proto = Object.getPrototypeOf(proto);
    }
    return false;
}

function TimeLimitedCache() {
