    if (existed) clearTimeout(prev.timeout);    // cancel old expiration
    else active++;                               // new active entry

    const timeout = setTimeout(() => {           // schedule removal
      store.delete(key);
      active--;
    }, duration);

    store.set(key, { value, expire: now + duration, timeout });
    return existed;
  }

  function get(key) {
    const now = Date.now();
    const entry = store.get(key);
    if (entry && entry.expire > now) return entry.value; // still valid

    if (entry) {                     // expired – clean up
      clearTimeout(entry.timeout);
      store.delete(key);
      active--;
    }
    return -1;
  }

  function count() {
    return active;                  // current number of un‑expired keys
  }

  return { set, get, count };
}

function sumOfDistances(nums) {
    const n = nums.length;
    const answer = new Array(n).fill(0);
    const groups = new Map();                     // value → list of indices

    // collect indices for each distinct value
    for (let i = 0; i < n; i++) {
        const v = nums[i];
        if (!groups.has(v)) groups.set(v, []);
        groups.get(v).push(i);
    }

    // process each group independently
    for (const positions of groups.values()) {
        const m = positions.length;
        if (m === 1) continue;                    // only one occurrence → answer stays 0

        const prefix = new Array(m).fill(0);
        // prefix sums of positions
        for (let i = 0; i < m; i++) {
            prefix[i] = positions[i] + (i ? prefix[i - 1] : 0);
        }
        const total = prefix[m - 1];

        // compute answer for every index in the group
        for (let i = 0; i < m; i++) {
            const pos = positions[i];
            const leftSum  = i ? prefix[i - 1] : 0;
            const rightSum = total - prefix[i];
            const leftCnt  = i;
            const rightCnt = m - i - 1;

            // sum of distances to all other equal elements
            answer[pos] = pos * leftCnt - leftSum + rightSum - pos * rightCnt;
        }
    }
    return answer;
}

function counter(n) {
    let value = n;                     // initial value
    return function () {
        const result = value;          // return current value
        value++;                       // advance for next call
        return result;
    };
}

function memoize(fn) {
    const cache = new Map();          // stores results for each argument list
    let callCount = 0;                // how many times fn was actually executed

    function memoized(...args) {
        const key = args.join('|');   // create a simple deterministic key
        if (cache.has(key)) {         // main logic: return cached value if present
            return cache.get(key);
        }
        const result = fn(...args);   // call original function
        cache.set(key, result);       // store result for future calls
        callCount++;                  // count the real invocation
        return result;
    }

    memoized.getCallCount = function () {   // expose call count
        return callCount;
    };

    return memoized;
}

function snail(nums, rowsCount, colsCount) {
  // validate input
  if (!Number.isInteger(rowsCount) || !Number.isInteger(colsCount) ||
      rowsCount <= 0 || colsCount <= 0 ||
      rowsCount * colsCount !== nums.length) {
    return [];
  }

  // create empty matrix
  const matrix = Array.from({ length: rowsCount }, () => Array(colsCount));

  let idx = 0; // index in the original 1-D array

  for (let col = 0; col < colsCount; col++) {
    // even column -> top-to-bottom, odd column -> bottom-to-top
    if (col % 2 === 0) {
      for (let row = 0; row < rowsCount; row++) {
        matrix[row][col] = nums[idx++];
      }
    } else {
      for (let row = rowsCount - 1; row >= 0; row--) {
        matrix[row][col] = nums[idx++];
      }
    }
  }

  return matrix;
}

function debounce(fn, wait) {
  let timerId;                         // timer reference
  return function (...args) {
    clearTimeout(timerId);             // cancel previous pending execution
    timerId = setTimeout(() => fn.apply(this, args), wait); // schedule new execution
  };
}

function flattenDepth(arr, n) {
    const result = [];

    function dfs(subArr, depth) {
        for (let i = 0; i < subArr.length; i++) {
            const v = subArr[i];
            if (Array.isArray(v) && depth < n) {   // flatten while depth < n
                dfs(v, depth + 1);
            } else {
                result.push(v);
            }
        }
    }

    dfs(arr, 0);
    return result;
}

function sleep(millis) {
  // resolve after the specified delay using the native timer
  return new Promise(resolve => setTimeout(resolve, millis));
}

function last(arr) {
    return arr.length ? arr[arr.length - 1] : -1;
}

function arrayReduce(nums, fn, init) {
  // iterate through array and apply reducer
  let acc = init;
  for (let i = 0; i < nums.length; i++) {
    acc = fn(acc, nums[i]);
  }
  return acc;
}

function enableGroupBy() {
  // add groupBy to every array if it doesn't exist yet
  if (typeof Array.prototype.groupBy !== 'function') {
    Array.prototype.groupBy = function (selector) {
      var groups = {};                         // result object
      for (var i = 0; i < this.length; i++) { // iterate once over the array
        var item = this[i];
        var key = selector(item, i, this);   // compute grouping key
        if (!groups[key]) groups[key] = [];   // create bucket if needed
        groups[key].push(item);               // preserve original order
      }
      return groups;
    };
  }
}

function memoize(fn) {
    const cache = new Map();                     // root cache
    const RESULT = Symbol('result');             // key for stored result
    return function(...args) {
        let node = cache;
        for (let i = 0; i < args.length; i++) {  // traverse/create path for arguments
            const arg = args[i];
            if (!node.has(arg)) node.set(arg, new Map());
            node = node.get(arg);
        }
        if (node.has(RESULT)) return node.get(RESULT); // return cached value
        const result = fn(...args);                     // compute and cache
        node.set(RESULT, result);
        return result;
    };
}

function compose(functions) {
    // return identity when no functions are provided
    if (functions.length === 0) return function(x) { return x; };

    // the composed function
    return function(x) {
        // apply functions from rightmost to leftmost
        for (let i = functions.length - 1; i >= 0; i--) {
            x = functions[i](x);
        }
        return x;
    };
}

function timeLimit(fn, t) {
  // return a wrapper that races the original promise against a timeout
  return function (...args) {
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => reject("Time Limit Exceeded"), t);
      fn(...args)
        .then((value) => {
          clearTimeout(timer);      // clear timeout on success
          resolve(value);
        })
        .catch((err) => {
          clearTimeout(timer);      // clear timeout on error
          reject(err);
        });
    });
  };
}

function filter(arr, fn) {
  const filteredArr = [];                     // result array
  for (let i = 0; i < arr.length; i++) {      // iterate through all elements
    if (fn(arr[i], i))                         // apply predicate (truthy check)
      filteredArr.push(arr[i]);               // keep element if predicate is true
  }
  return filteredArr;
}

function map(arr, fn) {
  const result = [];                     // create result array
  for (let i = 0; i < arr.length; i++) { // iterate over each element
    result.push(fn(arr[i], i));           // apply fn and store the value
  }
  return result;
}

class Graph {
    constructor(n, edges) {
        this.n = n;
        const INF = Number.MAX_SAFE_INTEGER;
        this.dist = Array.from({ length: n }, () => Array(n).fill(INF));
        for (let i = 0; i < n; ++i) this.dist[i][i] = 0;
        for (const [a, b, w] of edges) {
            if (w < this.dist[a][b]) this.dist[a][b] = w;
        }
        for (let k = 0; k < n; ++k) {
            const dk = this.dist[k];
            for (let i = 0; i < n; ++i) {
                const dik = this.dist[i][k];
                if (dik === INF) continue;
                const di = this.dist[i];
                for (let j = 0; j < n; ++j) {
                    const nd = dik + dk[j];
                    if (nd < di[j]) di[j] = nd;
                }
            }
        }
    }
    addEdge(edge) {
        const [u, v, w] = edge;
        if (w >= this.dist[u][v]) return;
        this.dist[u][v] = w;
        const n = this.n;
        for (let i = 0; i < n; ++i) {
            const diu = this.dist[i][u];
            if (diu === Number.MAX_SAFE_INTEGER) continue;
            const di = this.dist[i];
            for (let j = 0; j < n; ++j) {
                const dvj = this.dist[v][j];
                if (dvj === Number.MAX_SAFE_INTEGER) continue;
                const nd = diu + w + dvj;
                if (nd < di[j]) di[j] = nd;
            }
        }
    }
    shortestPath(node1, node2) {
        const d = this.dist[node1][node2];
        return d === Number.MAX_SAFE_INTEGER ? -1 : d;
    }
}

function findColumnWidth(grid) {
  const m = grid.length, n = grid[0].length;
  const ans = Array(n).fill(0);
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      const len = String(grid[i][j]).length;
      if (len > ans[j]) ans[j] = len;
    }
  }
  return ans;
}

function replaceValueInTree(root) {
    if (!root) return null;
    let queue = [[root, root.val]];
    while (queue.length) {
        const levelSize = queue.length;
        const levelTotal = queue.reduce((s, [node]) => s + node.val, 0);
        const next = [];
        for (let i = 0; i < levelSize; i++) {
            const [node, parentSum] = queue[i];
            node.val = levelTotal - parentSum;
            let childSum = 0;
            if (node.left) childSum += node.left.val;
            if (node.right) childSum += node.right.val;
            if (node.left) next.push([node.left, childSum]);
            if (node.right) next.push([node.right, childSum]);
        }
        queue = next;
    }
    return root;
}

function maxDivScore(nums, divisors) {
    let bestDiv = null;      // divisor with best score found so far
    let bestScore = -1;      // its score

    for (let i = 0; i < divisors.length; i++) {
        const d = divisors[i];
        let score = 0;
        for (let j = 0; j < nums.length; j++) {
            if (nums[j] % d === 0) score++;   // count numbers divisible by d
        }
        // update answer if we have a higher score or same score with smaller divisor
        if (score > bestScore || (score === bestScore && d < bestDiv)) {
            bestScore = score;
            bestDiv = d;
        }
    }
    return bestDiv;
}

function minimizeTheTotalPriceOfTheTrips(n, edges, price, trips) {
    const adj = Array.from({length: n}, () => []);
    for (const [a, b] of edges) { adj[a].push(b); adj[b].push(a); }

    const LOG = Math.max(1, Math.ceil(Math.log2(n + 1)));
    const up = Array.from({length: LOG}, () => new Array(n).fill(-1));
    const depth = new Array(n).fill(0);
    const parentOf = new Array(n).fill(-1);

    // iterative DFS to avoid recursion depth issues
    let stack = [[0, -1]];
    const order = [];
    const visited = new Array(n).fill(false);
    while (stack.length) {
        const [u, p] = stack.pop();
        if (visited[u]) continue;
        visited[u] = true;
        parentOf[u] = p;
        order.push(u);
        for (const v of adj[u]) {
            if (v === p) continue;
            depth[v] = depth[u] + 1;
            stack.push([v, u]);
        }
    }
    for (const u of order) up[0][u] = parentOf[u];

    for (let k = 1; k < LOG; k++) {
        for (let i = 0; i < n; i++) {
            if (up[k - 1][i] !== -1) up[k][i] = up[k - 1][up[k - 1][i]];
        }
    }

    const lca = (u, v) => {
        if (depth[u] < depth[v]) [u, v] = [v, u];
        let diff = depth[u] - depth[v];
        let bit = 0;
        while (diff) {
            if (diff & 1) u = up[bit][u];
            diff >>= 1;
            bit++;
        }
        if (u === v) return u;
        for (let k = LOG - 1; k >= 0; k--) {
            if (up[k][u] !== up[k][v]) { u = up[k][u]; v = up[k][v]; }
        }
        return up[0][u];
    };

    const cnt = new Array(n).fill(0);
    for (const [s, e] of trips) {
        const l = lca(s, e);
        cnt[s]++;
        cnt[e]++;
        cnt[l]--;
        const pl = up[0][l];
        if (pl !== -1) cnt[pl]--;
    }

    // accumulate bottom-up (reverse of DFS pre-order gives a valid post-order-ish sequence)
    for (let idx = order.length - 1; idx >= 0; idx--) {
        const u = order[idx];
        const p = parentOf[u];
        if (p !== -1) cnt[p] += cnt[u];
    }

    let totalOriginal = 0;
    for (let i = 0; i < n; i++) totalOriginal += price[i] * cnt[i];
    const savedWeight = new Array(n).fill(0);
    for (let i = 0; i < n; i++) savedWeight[i] = Math.floor(price[i] * cnt[i] / 2);

    const memoNotSel = new Array(n).fill(null);
    const memoSel = new Array(n).fill(null);
    const dfsDp = (u) => {
        if (memoSel[u] !== null) return [memoNotSel[u], memoSel[u]];
        let sel = savedWeight[u];
        let notSel = 0;
        for (const v of adj[u]) {
            if (v === parentOf[u]) continue;
            const [childNot, childSel] = dfsDp(v);
            sel += childNot;
            notSel += Math.max(childNot, childSel);
        }
        memoNotSel[u] = notSel;
        memoSel[u] = sel;
        return [notSel, sel];
    };

    // process children before parents using reverse DFS order (order is pre-order from stack DFS)
    for (let idx = order.length - 1; idx >= 0; idx--) {
        dfsDp(order[idx]);
    }
    const notRoot = memoNotSel[0], selRoot = memoSel[0];
    const saved = Math.max(notRoot, selRoot);
    return totalOriginal - saved;
}

function findConcatenationValue(nums) {
    let concatenationValue = 0; // initialize the concatenation value
    while (nums.length > 0) { 
        // if there's only one element left, concatenate it with the current value
        if (nums.length === 1) {
            concatenationValue += nums[0]; 
            nums.shift(); 
        } else {
            // concatenate the first and last elements and add to the concatenation value
            concatenationValue += parseInt(nums[0].toString() + nums[nums.length - 1].toString()); 
            // remove the first and last elements from the array
            nums.shift(); 
            nums.pop(); 
        }
    }
    return concatenationValue;
}

function maximumNumbers(banned, n, maxSum) {
    let currentSum = 0; 
    let count = 0; 
    let bannedSet = new Set(banned); 
    // iterate over the range and check if the number is banned or exceeds maxSum
    for (let i = 1; i <= n; i++) {
        if (!bannedSet.has(i) && currentSum + i <= maxSum) {
            currentSum += i; 
            count++;
        }
    }
    return count;
}

function minCapability(nums, k) {
    // The algorithm solution is already optimal, using binary search to find the minimum capability
    let left = Math.min(...nums), right = Math.max(...nums);
    while (left < right) {
        // Calculate the mid value as the potential capability
        let mid = Math.floor((left + right) / 2);
        // Initialize the count of houses robbed and the previous house index
        let count = 0, prev = -2;
        for (let i = 0; i < nums.length; i++) {
            // If the current house has more money than the mid capability and it's not adjacent to the previous house
            if (nums[i] <= mid && i - prev > 1) {
                // Rob the current house and update the count and previous house index
                count++, prev = i;
            }
        }
        // If the count of houses robbed is less than k, update the left boundary
        if (count < k) {
            left = mid + 1;
        } else {
            // Otherwise, update the right boundary
            right = mid;
        }
    }
    return left;
}

function findValidSplit(nums) {
  let totalProduct = 1n;
  for (let i = 0; i < nums.length; i++) totalProduct *= BigInt(nums[i]);

  let leftProduct = 1n;
  for (let i = 0; i < nums.length - 1; i++) {
    // include nums[i] in the left partition first - split at i means
    // left = nums[0..i], right = nums[i+1..], and the right side must be
    // non-empty (so i can never be the last index)
    leftProduct *= BigInt(nums[i]);
    if (gcd(leftProduct, totalProduct / leftProduct) === 1n) {
      return i;
    }
  }

  return -1;
}

function gcd(a, b) {
  if (b === 0n) {
    return a;
  } else {
    return gcd(b, a % b);
  }
}

function minimumScore(s, t) {
    const n = s.length, m = t.length;
    const INF = n + 1;
    const suf = new Array(m + 1).fill(INF);
    suf[m] = n;
    let si = n - 1;
    for (let tj = m - 1; tj >= 0; tj--) {
        while (si >= 0 && s[si] !== t[tj]) si--;
        if (si < 0) break;
        suf[tj] = si;
        si--;
    }

    let best = m;
    let sPos = -1;
    let j = 0;
    for (let i = 0; i <= m; i++) {
        if (j < i) j = i;
        while (j <= m && (suf[j] === INF || suf[j] <= sPos)) j++;
        if (j <= m) best = Math.min(best, j - i);
        if (i < m) {
            let p = sPos + 1;
            while (p < n && s[p] !== t[i]) p++;
            if (p >= n) break;
            sPos = p;
        }
    }
    return best;
}

function maxDiff(num) {
    // Convert the number to a string to easily access and replace digits
    let numStr = num.toString();

    // Initialize variables to store the maximum and minimum possible values
    let maxVal = -Infinity;
    let minVal = Infinity;

    // Iterate over all possible digits (0-9)
    for (let i = 0; i <= 9; i++) {
        // Iterate over all possible replacement digits (0-9)
        for (let j = 0; j <= 9; j++) {
            // Create a copy of the original string
            let newStr = numStr;

            // Replace all occurrences of the current digit with the replacement digit
            newStr = newStr.split(i.toString()).join(j.toString());

            // Update the maximum and minimum possible values
            maxVal = Math.max(maxVal, parseInt(newStr));
            minVal = Math.min(minVal, parseInt(newStr));
        }
    }

    // Return the difference between the maximum and minimum possible values
    return maxVal - minVal;
}

function substringXorQueries(s, queries) {
    let map = {};
    for (let i = 0; i < s.length; i++) {
        let val = 0;
        for (let j = i; j < s.length; j++) {
            val = (val << 1) | (s[j] - '0');
            // only keep the SHORTEST substring for each value; ties broken
            // by smallest start index (naturally satisfied since i only
            // increases and we only overwrite on a strictly shorter match)
            if (!(val in map)) {
                map[val] = [i, j];
            } else {
                const [curStart, curEnd] = map[val];
                const curLen = curEnd - curStart + 1;
                const newLen = j - i + 1;
                if (newLen < curLen) map[val] = [i, j];
            }
        }
    }
    let ans = [];
    for (let query of queries) {
        let val = query[0] ^ query[1];
        ans.push(map[val] ? map[val] : [-1, -1]);
    }
    return ans;
}

function minCost(basket1, basket2) {
    const cnt = {};
    for (const x of basket1) cnt[x] = (cnt[x] || 0) + 1;
    for (const x of basket2) cnt[x] = (cnt[x] || 0) - 1;

    let globalMin = Infinity;
    for (const x of basket1) if (x < globalMin) globalMin = x;
    for (const x of basket2) if (x < globalMin) globalMin = x;

    const excess = [];
    for (const key in cnt) {
        const c = cnt[key];
        if (c % 2 !== 0) return -1;
        const v = Number(key);
        for (let i = 0; i < Math.abs(c) / 2; i++) excess.push(v);
    }
    excess.sort((a, b) => a - b);

    let total = 0;
    const half = excess.length / 2;
    for (let i = 0; i < half; i++) {
        total += Math.min(excess[i], 2 * globalMin);
    }
    return total;
}

function maximizeWinFromTwoSegments(prizePositions, k) {
    const n = prizePositions.length;
    if (n === 0) return 0;

    // count[i] = number of prizes covered by a window ending exactly at
    // prizePositions[i], i.e. [prizePositions[i]-k, prizePositions[i]]
    const count = new Array(n).fill(0);
    let left = 0;
    for (let i = 0; i < n; i++) {
        while (prizePositions[i] - prizePositions[left] > k) left++;
        count[i] = i - left + 1;
    }

    // bestLeft[i] = best single-segment count using only prizes up to index i
    const bestLeft = new Array(n).fill(0);
    bestLeft[0] = count[0];
    for (let i = 1; i < n; i++) bestLeft[i] = Math.max(bestLeft[i - 1], count[i]);

    let ans = bestLeft[n - 1]; // fallback: only one effective segment needed
    left = 0;
    for (let i = 0; i < n; i++) {
        while (prizePositions[i] - prizePositions[left] > k) left++;
        // pair this window with the best NON-OVERLAPPING window entirely
        // to its left (ending before index `left`), so nothing is
        // double-counted
        if (left > 0) {
            ans = Math.max(ans, count[i] + bestLeft[left - 1]);
        }
    }
    return ans;
}

function countFairPairs(nums, lower, upper) {
    nums.sort((a, b) => a - b);
    let count = 0;
    for (let i = 0; i < nums.length; i++) {
        // binary search for the leftmost and rightmost valid j (j > i)
        count += upperBound(nums, i, upper - nums[i]) - lowerBound(nums, i, lower - nums[i]);
    }
    return count;

    function lowerBound(arr, from, target) {
        let lo = from + 1, hi = arr.length;
        while (lo < hi) {
            let mid = (lo + hi) >> 1;
            if (arr[mid] < target) lo = mid + 1; else hi = mid;
        }
        return lo;
    }
    function upperBound(arr, from, target) {
        let lo = from + 1, hi = arr.length;
        while (lo < hi) {
            let mid = (lo + hi) >> 1;
            if (arr[mid] <= target) lo = mid + 1; else hi = mid;
        }
        return lo;
    }
}

function minCost(nums, k) {
  let dp = new Array(nums.length + 1).fill(Infinity);
  dp[0] = 0;
  for (let i = 1; i <= nums.length; i++) {
    let trimmedLength = 0;
    let countMapForSubarray = {};
    for (let j = i - 1; j >= 0; j--) {
      countMapForSubarray[nums[j]] = (countMapForSubarray[nums[j]] || 0) + 1;
      // when a value repeats for the FIRST time (count reaches 2), BOTH
      // occurrences now belong in the trimmed length - the earlier
      // occurrence was skipped while it still looked like a singleton
      if (countMapForSubarray[nums[j]] === 2) trimmedLength += 2;
      else if (countMapForSubarray[nums[j]] > 2) trimmedLength += 1;
      dp[i] = Math.min(dp[i], dp[j] + k + trimmedLength);
    }
  }
  return dp[nums.length];
}

function vowelStrings(words, queries) {
    // Create a prefix sum array to store the count of strings that start and end with a vowel
    let prefixSum = new Array(words.length).fill(0);
    let vowels = 'aeiou';
    for (let i = 0; i < words.length; i++) {
        // Check if the string starts and ends with a vowel
        if (vowels.includes(words[i][0]) && vowels.includes(words[i][words[i].length - 1])) {
            prefixSum[i] = (i > 0 ? prefixSum[i - 1] : 0) + 1;
        } else {
            prefixSum[i] = i > 0 ? prefixSum[i - 1] : 0;
        }
    }
    let ans = new Array(queries.length).fill(0);
    for (let i = 0; i < queries.length; i++) {
        // Calculate the count of strings that start and end with a vowel in the given range
        let left = queries[i][0];
        let right = queries[i][1];
        ans[i] = prefixSum[right] - (left > 0 ? prefixSum[left - 1] : 0);
    }
    return ans;
}

function putMarblesInBags(weights, k) {
    const n = weights.length;
    if (k === 1 || k === n) return 0;
    const pairSums = [];
    for (let i = 0; i < n - 1; i++) pairSums.push(weights[i] + weights[i + 1]);
    pairSums.sort((a, b) => a - b);

    let minScore = 0, maxScore = 0;
    for (let i = 0; i < k - 1; i++) minScore += pairSums[i];
    for (let i = 0; i < k - 1; i++) maxScore += pairSums[pairSums.length - 1 - i];

    return maxScore - minScore;
}

function makeEqual(s, target) {
    // The operation lets '1's be freely moved/duplicated across positions
    // as long as at least one '1' exists to work with. s can be
    // transformed into target iff they agree on whether ANY '1' is present
    // at all - the exact COUNT of ones doesn't need to match, since a
    // single '1' can be spread to produce any configuration that also has
    // at least one '1' (an all-zero string can only ever stay all-zero).
    return s.includes('1') === target.includes('1');
}

