}

function minOperations(nums) {
    const n = nums.length;
    const order = Array.from({length: n}, (_, i) => i).sort((a, b) => nums[a] - nums[b]);
    const tree = new Array(n + 1).fill(0);
    function update(i, delta) {
        i++;
        while (i <= n) { tree[i] += delta; i += i & (-i); }
    }
    function query(i) {
        i++;
        let s = 0;
        while (i > 0) { s += tree[i]; i -= i & (-i); }
        return s;
    }
    for (let i = 0; i < n; i++) update(i, 1);

    let cur = 0, total = 0;
    for (const idx of order) {
        let activeBefore;
        if (idx >= cur) {
            activeBefore = query(idx) - query(cur - 1) - 1;
        } else {
            activeBefore = (query(n - 1) - query(cur - 1)) + query(idx) - 1;
        }
        total += activeBefore + 1;
        update(idx, -1);
        cur = idx + 1;
        if (cur === n) cur = 0;
    }
    return total;
}

function findPrefixCommonArray(A, B) {
    let n = A.length;
    let prefixCommonArray = new Array(n).fill(0);
    let setA = new Set();
    let setB = new Set();
    for (let i = 0; i < n; i++) {
        setA.add(A[i]); // adding current element of A to setA
        setB.add(B[i]); // adding current element of B to setB
        let intersectionCount = 0;
        for (let j = 1; j <= n; j++) {
            if (setA.has(j) && setB.has(j)) intersectionCount++; // counting common elements
        }
        prefixCommonArray[i] = intersectionCount; // storing the count of common elements
    }
    return prefixCommonArray; // this algorithm is already optimal
}

function maxFish(grid) {
    if (!grid.length) return 0;
    const m = grid.length, n = grid[0].length;
    const directions = [[0, 1], [0, -1], [1, 0], [-1, 0]];
    let maxFishCount = 0;

    function dfs(r, c) {
        if (r < 0 || r >= m || c < 0 || c >= n || grid[r][c] === 0) return 0;
        let fishCount = grid[r][c]; // must be `let` - it gets reassigned below
        grid[r][c] = 0;
        for (const [dr, dc] of directions) {
            fishCount += dfs(r + dr, c + dc);
        }
        return fishCount;
    }

    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (grid[r][c] > 0) {
                maxFishCount = Math.max(maxFishCount, dfs(r, c));
            }
        }
    }
    return maxFishCount;
}

function firstCompletelyPaintedRowOrColumn(arr, mat) {
    // Create a set to store the painted cells
    let painted = new Set();
