    let rows = Array(m).fill(0).map(() => new Set());
    let cols = Array(n).fill(0).map(() => new Set());

    // Iterate through the array and paint the cells
    for (let i = 0; i < arr.length; i++) {
        // Find the position of the current cell in the matrix
        for (let j = 0; j < m; j++) {
            for (let k = 0; k < n; k++) {
                if (mat[j][k] === arr[i]) {
                    // Add the cell to the set of painted cells
                    painted.add(arr[i]);
                    // Add the cell to the set of painted cells in the current row
                    rows[j].add(arr[i]);
                    // Add the cell to the set of painted cells in the current column
                    cols[k].add(arr[i]);
                    // Check if the current row or column is completely painted
                    if (rows[j].size === n || cols[k].size === m) {
                        return i;
                    }
                }
            }
        }
    }
    // If no row or column is completely painted, return -1
    return -1;
}

function getSubarrayBeauty(nums, k, x) {
    let result = [];
    for (let i = 0; i <= nums.length - k; i++) {
        // filter the subarray to get only negative numbers
        let negatives = nums.slice(i, i + k).filter(num => num < 0);
        // sort the negative numbers in ascending order
        let sortedNegatives = negatives.sort((a, b) => a - b);
        // if there are at least x negative numbers, get the xth smallest one, otherwise get 0
        let beauty = sortedNegatives.length >= x ? sortedNegatives[x - 1] : 0;
        result.push(beauty);
    }
    return result;
}

