function minOperations(nums) {
    const n = nums.length;
    const ones = nums.filter(x => x === 1).length;
    if (ones > 0) return n - ones;

    let minLen = Infinity;
    for (let i = 0; i < n; i++) {
        let g = nums[i];
        for (let j = i + 1; j < n; j++) {
            g = getGcd(g, nums[j]);
            if (g === 1) { minLen = Math.min(minLen, j - i + 1); break; }
        }
    }
    if (minLen === Infinity) return -1;
    return (minLen - 1) + (n - 1);
}

