function cancellable(generator) {
  let cancelled = false;
  let resolve, reject;
  const promise = new Promise((res, rej) => { resolve = res; reject = rej; });
  const cancel = () => {
    cancelled = true;
    try { generator.throw("Cancelled"); } catch (e) { /* generator may already be done */ }
  };
  function step(next) {
    // `next` is a thunk (function) that advances the generator when called --
    // NOT an already-computed {value, done} result
    if (cancelled) { reject("Cancelled"); return; }
    try {
      const result = next();
      if (result.done) {
        resolve(result.value);
      } else {
        result.value.then(val => {
          if (cancelled) reject("Cancelled");
          else step(() => generator.next(val));
        }).catch(err => { step(() => generator.throw(err)); });
      }
    } catch (err) { reject(err); }
  }
  step(() => generator.next());
  return [cancel, promise];
}

function determineWinner(player1, player2) {
    function calculateScore(player) {
        let score = 0;
        for (let i = 0; i < player.length; i++) {
            let roll = player[i];
            if ((i >= 1 && player[i - 1] === 10) || (i >= 2 && player[i - 2] === 10)) {
                roll *= 2;
            }
            score += roll;
        }
        return score;
    }
    const score1 = calculateScore(player1);
    const score2 = calculateScore(player2);
    if (score1 > score2) return 1;
    else if (score2 > score1) return 2;
    else return 0;
}

function minimumCost(start, target, specialRoads) {
    const key = (p) => p[0] + ',' + p[1];

    let points = [start, target];
    for (let road of specialRoads) {
        points.push([road[0], road[1]]);
        points.push([road[2], road[3]]);
    }
    const uniqueMap = new Map();
    for (const p of points) uniqueMap.set(key(p), p);
    points = [...uniqueMap.values()];

    // use a CONSISTENT key format ("x,y") throughout - the original mixed
    // the default array-toString key (used in the init loop, e.g. "1,1")
    // with JSON.stringify elsewhere (e.g. "[1,1]"), so the start point's
    // distance was set under a DIFFERENT key than the one everything else
    // looked it up by, leaving the "real" entry permanently at Infinity
    let distances = {};
    for (let point of points) distances[key(point)] = Infinity;
    distances[key(start)] = 0;

    let queue = [[0, start]];

    while (queue.length > 0) {
        let [dist, point] = queue.shift();
        const pk = key(point);

        if (dist > distances[pk]) continue;

        for (let road of specialRoads) {
            if (point[0] === road[0] && point[1] === road[1]) {
                let newDist = dist + road[4];
                let newPoint = [road[2], road[3]];
                const nk = key(newPoint);
                if (newDist < distances[nk]) {
                    distances[nk] = newDist;
                    queue.push([newDist, newPoint]);
                    queue.sort((a, b) => a[0] - b[0]);
                }
            }
        }

        for (let otherPoint of points) {
            let newDist = dist + Math.abs(otherPoint[0] - point[0]) + Math.abs(otherPoint[1] - point[1]);
            const ok = key(otherPoint);
            if (newDist < distances[ok]) {
                distances[ok] = newDist;
                queue.push([newDist, otherPoint]);
                queue.sort((a, b) => a[0] - b[0]);
            }
        }
    }

    return distances[key(target)];
}

function smallestBeautifulString(s, k) {
    const n = s.length;
    const arr = s.split('').map(c => c.charCodeAt(0) - 97);

    for (let i = n - 1; i >= 0; i--) {
        const forbidden = i > 0 ? arr[i - 1] : -1;
        let c = arr[i] + 1;
        while (c < k && c === forbidden) c++;
        if (c < k) {
            arr[i] = c;
            // fill everything after with the smallest valid beautiful sequence
            for (let j = i + 1; j < n; j++) {
                let c2 = 0;
                while (c2 === arr[j - 1]) c2++;
                arr[j] = c2;
            }
            return arr.map(x => String.fromCharCode(x + 97)).join('');
        }
        // no valid increment at position i within the first k letters that
        // also avoids matching the left neighbor - carry over to position i-1
    }
    return '';
}

