}

function minAdditions(word) {
    // pos = length of the prefix of the infinite "abc" pattern already used
    let pos = 0;
    const pattern = ['a', 'b', 'c'];          // the repeating block

    for (let i = 0; i < word.length; i++) {
        const ch = word[i];
        // advance until the current pattern character matches ch
        while (pattern[pos % 3] !== ch) {
            pos++;                              // these are inserted chars
        }
        pos++;                                  // consume the matching char
    }

    // round up to the next complete "abc" block
    const finalLen = Math.ceil(pos / 3) * 3;
    return finalLen - word.length;              // inserted characters
}

