function distinctDifferenceArray(nums) {
    var result = new Array(nums.length);
    for (var i = 0; i < nums.length; i++) {
        // calculate the number of distinct elements in the prefix
        var prefixSet = new Set();
        for (var j = 0; j <= i; j++) {
            prefixSet.add(nums[j]);
        }
        var prefixCount = prefixSet.size;

        // calculate the number of distinct elements in the suffix
        var suffixSet = new Set();
        for (var j = i + 1; j < nums.length; j++) {
            suffixSet.add(nums[j]);
        }
        var suffixCount = suffixSet.size;

        // calculate the difference and store it in the result array
        result[i] = prefixCount - suffixCount;
    }
    return result;
}

function minIncrements(n, cost) {
    const c = cost.slice();
    let increments = 0;
    for (let i = Math.floor((n - 2) / 2); i >= 0; i--) {
        const left = 2 * i + 1, right = 2 * i + 2;
        if (left >= n) continue;
        if (right >= n) {
            c[i] += c[left];
            continue;
        }
        if (c[left] !== c[right]) {
            increments += Math.abs(c[left] - c[right]);
            if (c[left] < c[right]) c[left] = c[right];
            else c[right] = c[left];
        }
        c[i] += c[left];
    }
    return increments;
}

