function maximumOr(nums, k) {
    let maxOr = 0;
    // Initialize maxOr as 0 to store the maximum possible OR value
    for (let i = 0; i < nums.length; i++) {
        // Iterate over each element in the array
        let temp = nums.slice(); // Create a copy of the array
        let remainingK = k; // Initialize remaining operations
        let j = i; // Initialize the index to start operations
        while (remainingK > 0 && temp[j] < (1 << 30)) {
            // Continue operations until k becomes 0 or the number exceeds 2^30
            temp[j] *= 2; // Double the current number
            remainingK--; // Decrement the remaining operations
        }
        let orValue = 0; // Initialize OR value for the current array
        for (let num of temp) {
            // Calculate the OR value of the modified array
            orValue |= num; // Update the OR value
        }
        maxOr = Math.max(maxOr, orValue); // Update the maximum OR value
    }
    return maxOr; // Return the maximum possible OR value
}

function powerOfHeroes(nums) {
    const MOD = 1000000007n;
    const sorted = nums.slice().sort((a, b) => a - b).map(BigInt);
    const n = sorted.length;
    let g = 0n;
    let result = 0n;
    for (let i = 0; i < n; i++) {
        const sumOfMins = (g + sorted[i]) % MOD;
        const contribution = (((sorted[i] * sorted[i]) % MOD) * sumOfMins) % MOD;
        result = (result + contribution) % MOD;
        g = (2n * g + sorted[i]) % MOD;
    }
    return Number(result);
}

function doesValidArrayExist(derived) {
    // a valid original array exists iff the XOR of every element in
