    // original[i] away in pairs, leaving 0 exactly when a consistent
    // assignment exists
    return derived.reduce((a, b) => a ^ b, 0) === 0;
}

function countCompleteComponents(n, edges) {
    // Create an adjacency list representation of the graph
    let graph = Array.from({length: n}, () => []);
    for (let [u, v] of edges) {
        graph[u].push(v);
        graph[v].push(u);
    }

    // Initialize visited array and count of complete components
    let visited = Array(n).fill(false);
    let count = 0;

    // Iterate over all vertices
    for (let i = 0; i < n; i++) {
        // If vertex is not visited, perform DFS
        if (!visited[i]) {
            let component = [];
            dfs(graph, visited, i, component);

            // Check if the component is complete
            let isComplete = true;
            for (let u of component) {
                for (let v of component) {
                    // If there is no edge between two vertices, the component is not complete
                    if (u !== v && !graph[u].includes(v)) {
                        isComplete = false;
                        break;
                    }
                }
                if (!isComplete) break;
            }

            // If the component is complete, increment the count
            if (isComplete) count++;
        }
    }

    return count;
}

function dfs(graph, visited, vertex, component) {
    // Mark the vertex as visited and add it to the component
    visited[vertex] = true;
    component.push(vertex);

    // Recur for all adjacent vertices
    for (let adjacent of graph[vertex]) {
        if (!visited[adjacent]) {
            dfs(graph, visited, adjacent, component);
        }
    }
}

function findLosers(n, k) {
    const visited = new Array(n + 1).fill(false);
    let current = 1;
    let i = 1;
    while (!visited[current]) {
        visited[current] = true;
        current = ((current - 1 + i * k) % n) + 1;
        i++;
    }
    const result = [];
    for (let f = 1; f <= n; f++) if (!visited[f]) result.push(f);
    return result;
}

