}

function callPolyfill(fn) {
  // create a new function that will be bound to the given context
  return function boundFn(obj, ...args) {
    // create a new function that will be called with the given context
    const bound = function() {
      // call the original function with the given context and arguments
      return fn.apply(obj, args);
    };
    // return the result of the bound function
    return bound();
  };
}

// add the callPolyfill method to all functions
Function.prototype.callPolyfill = function(obj, ...args) {
  // call the callPolyfill function with the current function and the given context and arguments
  return callPolyfill(this)(obj, ...args);
};

