function compactObject(obj) {
  // If obj is an array, filter out falsy values and recursively compact each element
  if (Array.isArray(obj)) {
    return obj.filter(val => val).map(val => compactObject(val));
  }
  // If obj is an object, filter out falsy values and recursively compact each value
  else if (typeof obj === 'object' && obj !== null) {
    const compacted = {};
    for (const key in obj) {
      // If the value is truthy, add it to the compacted object and recursively compact it
      if (obj[key]) {
        compacted[key] = compactObject(obj[key]);
      }
    }
    return compacted;
  }
  // If obj is not an array or object, return it as is
  else {
    return obj;
  }
}

