            if (currentSum > target) return false;
            let num = 0;
            for (let end = start; end < s.length; end++) {
                num = num * 10 + (s.charCodeAt(end) - 48);
                if (helper(end + 1, currentSum + num)) return true;
            }
            return false;
        }
        return helper(0, 0);
    }

    let result = 0;
    for (let i = 1; i <= n; i++) {
        const square = i * i;
        if (canPartition(square.toString(), i)) result += square;
    }
    return result;
}

function minExtraChars(s, dictionary) {
    let dp = new Array(s.length + 1).fill(0);
    // Initialize dp array to store minimum extra characters for each substring
    for (let i = 1; i <= s.length; i++) {
        dp[i] = dp[i - 1] + 1; // Assume all characters are extra
        for (let word of dictionary) {
            // Check if current substring ends with a word from dictionary
            if (i >= word.length && s.substring(i - word.length, i) === word) {
                dp[i] = Math.min(dp[i], dp[i - word.length]); // Update dp if a valid word is found
            }
        }
    }
    return dp[s.length]; // Return minimum extra characters for the entire string
}

function removeTrailingZeros(num) {
  // start from the end of the string and remove trailing zeros
  let endIndex = num.length - 1;
  while (endIndex >= 0 && num[endIndex] === '0') {
    endIndex--;
  }
  return num.substring(0, endIndex + 1);
}

function maximumStrength(nums) {
    // Generate all possible subsets of the given array
    let maxStrength = 0;
    for (let mask = 0; mask < (1 << nums.length); mask++) {
        let subsetProduct = 1;
        // Calculate the product of the current subset
        for (let i = 0; i < nums.length; i++) {
            if ((mask & (1 << i)) !== 0) {
                subsetProduct *= nums[i];
            }
        }
        // Update the maximum strength if the current subset's product is larger
        maxStrength = Math.max(maxStrength, subsetProduct);
    }
    return maxStrength;
}

function modifyGraphEdgeWeights(n, edges, source, destination, target) {
  const INF = 2000000000;

  function dijkstra(edgeList) {
    const g = Array.from({ length: n }, () => Array(n).fill(Infinity));
    for (const [a, b, w] of edgeList) {
      if (w === -1) continue;
      if (w < g[a][b]) { g[a][b] = w; g[b][a] = w; }
    }
    const dist = Array(n).fill(Infinity);
    dist[source] = 0;
    const vis = Array(n).fill(false);
    for (let iter = 0; iter < n; iter++) {
      let k = -1;
      for (let j = 0; j < n; j++) {
        if (!vis[j] && (k === -1 || dist[j] < dist[k])) k = j;
      }
      vis[k] = true;
      for (let j = 0; j < n; j++) {
        if (dist[k] + g[k][j] < dist[j]) dist[j] = dist[k] + g[k][j];
      }
    }
    return dist[destination];
  }

  let d = dijkstra(edges);
  if (d < target) return [];
  if (d === target) {
    for (const e of edges) if (e[2] === -1) e[2] = INF;
    return edges;
  }

  let ok = false;
  for (const e of edges) {
    if (e[2] !== -1) continue;
    if (ok) { e[2] = INF; continue; }
    e[2] = 1;
    d = dijkstra(edges);
    if (d <= target) {
      ok = true;
      e[2] += (target - d);
    }
  }
  return ok ? edges : [];
}

function gcdTraversal(nums) {
    // Create a parent array for union-find
    var parent = new Array(nums.length).fill(0).map((val, index) => index);

    // Function to find the parent of a node
    function find(x) {
        // If the parent of x is not x, then find the parent of x
        if (parent[x] !== x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    // Function to union two nodes
    function union(x, y) {
        // Find the parents of x and y
        var rootX = find(x);
        var rootY = find(y);

        // If the parents are different, then union them
        if (rootX !== rootY) {
            parent[rootX] = rootY;
        }
    }

    // Iterate over all pairs of indices
    for (var i = 0; i < nums.length; i++) {
        for (var j = i + 1; j < nums.length; j++) {
            // If the gcd of nums[i] and nums[j] is greater than 1, then union them
            if (gcd(nums[i], nums[j]) > 1) {
                union(i, j);
            }
        }
    }

    // Function to calculate the gcd of two numbers
    function gcd(a, b) {
        // If b is 0, then return a
        if (b === 0) {
            return a;
        }
        // Otherwise, return the gcd of b and the remainder of a divided by b
        return gcd(b, a % b);
    }

    // Check if all nodes have the same parent
    var root = find(0);
    for (var i = 1; i < nums.length; i++) {
        // If the parent of i is not the same as the root, then return false
        if (find(i) !== root) {
            return false;
        }
    }

    // If all nodes have the same parent, then return true
    return true;
}

function diffOfDiagonals(grid) {
    const m = grid.length;
    const n = grid[0].length;
    const answer = Array(m).fill(0).map(() => Array(n).fill(0));
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            const topLeft = new Set();
            let i = r - 1, j = c - 1;
            while (i >= 0 && j >= 0) { topLeft.add(grid[i][j]); i--; j--; }
            const bottomRight = new Set();
            i = r + 1; j = c + 1;
            while (i < m && j < n) { bottomRight.add(grid[i][j]); i++; j++; }
            answer[r][c] = Math.abs(topLeft.size - bottomRight.size);
        }
    }
    return answer;
}

class EventEmitter {
    constructor() { this.events = new Map(); }
    subscribe(eventName, callback) {
        if (!this.events.has(eventName)) this.events.set(eventName, []);
        this.events.get(eventName).push(callback);
        const events = this.events;
        return {
            unsubscribe: function() {
                const arr = events.get(eventName);
                const idx = arr.indexOf(callback);
                if (idx !== -1) arr.splice(idx, 1);
            }
        };
    }
    emit(eventName, args = []) {
        const callbacks = this.events.get(eventName) || [];
        return callbacks.map(cb => cb(...args));
    }
}

function sumInMatrix(nums) {
  if (!nums || nums.length === 0) return 0;
  let rows = nums.length;
  let cols = nums[0].length;
  let score = 0;
  for (let c = 0; c < cols; c++) {               // compute column‑wise maximum and accumulate
    let colMax = -Infinity;
    for (let r = 0; r < rows; r++) {
      if (nums[r][c] > colMax) colMax = nums[r][c];
    }
    score += colMax;
  }
  return score;
}

function minimizeStringLength(s) {
    // reachable minimum is the number of distinct characters
    return new Set(s).size;
}

function cancellable(fn, args, t) {
    let timeoutId = setTimeout(function() { // delay the execution of fn by t milliseconds
        fn(...args);
    }, t);
    return function cancelFn() { // return a cancel function
        clearTimeout(timeoutId); // cancel the delayed execution of fn
    }
}

function minSwaps(nums) {
    const n = nums.length;
    const pos1 = nums.indexOf(1);
    const posn = nums.indexOf(n);
    // adjacent swaps needed to walk 1 to front and n to back; subtract 1 if their paths would cross
    let ans = pos1 + (n - 1 - posn);
    if (pos1 > posn) ans -= 1;
    return ans;
}

var maxIncreasingCells = function(mat) {
    if (!mat.length || !mat[0].length) return 0;
    const rows = mat.length, cols = mat[0].length;
    const dp = Array.from({length:rows}, () => new Array(cols).fill(1));
    const cells = [];
    for (let i=0;i<rows;i++) for (let j=0;j<cols;j++) cells.push([mat[i][j], i, j]);
    cells.sort((a,b)=>a[0]-b[0]);
    const rowBest = new Array(rows).fill(0);
    const colBest = new Array(cols).fill(0);
    let idx = 0;
    const n = cells.length;
    while (idx < n) {
        const curVal = cells[idx][0];
        const group = [];
        while (idx < n && cells[idx][0] === curVal) {
            group.push([cells[idx][1], cells[idx][2]]);
            idx++;
        }
        for (const [r,c] of group) dp[r][c] = Math.max(rowBest[r], colBest[c]) + 1;
        for (const [r,c] of group) {
            if (dp[r][c] > rowBest[r]) rowBest[r] = dp[r][c];
            if (dp[r][c] > colBest[c]) colBest[c] = dp[r][c];
        }
    }
    let mx = 0;
    for (const row of dp) for (const v of row) if (v>mx) mx=v;
    return mx;
};

function addTwoPromises(promise1, promise2) {
    // Using Promise.all to wait for both promises to resolve and then add their values
    return Promise.all([promise1, promise2]).then(values => values[0] + values[1]);
}

function sumOfMatrixAfterQueries(n, queries) {
    const rowDone = new Array(n).fill(false);
    const colDone = new Array(n).fill(false);
    let rowsDoneCount = 0, colsDoneCount = 0;
    let total = 0;
    for (let i = queries.length - 1; i >= 0; i--) {
        const [type, index, val] = queries[i];
        if (type === 0) {
            if (!rowDone[index]) { rowDone[index] = true; rowsDoneCount++; total += val * (n - colsDoneCount); }
        } else {
            if (!colDone[index]) { colDone[index] = true; colsDoneCount++; total += val * (n - rowsDoneCount); }
        }
    }
    return total;
}

function countGoodIntegers(num1, num2, minSum, maxSum) {
  const MOD = 1000000007n;

  function decrementStr(s) {
    const arr = s.split('');
    let i = arr.length - 1;
    while (i >= 0 && arr[i] === '0') { arr[i] = '9'; i--; }
    if (i < 0) return null;
    arr[i] = String(Number(arr[i]) - 1);
    let res = arr.join('').replace(/^0+/, '');
    if (res === '') res = '0';
    return res;
  }

  function countUpTo(numStr) {
    if (numStr === null) return 0n;
    const digits = numStr.split('').map(Number);
    const n = digits.length;
    const memo = new Map();
    function dfs(pos, sum, tight) {
      if (sum > maxSum) return 0n;
      if (pos === n) return (sum >= minSum && sum <= maxSum) ? 1n : 0n;
      const key = pos + ',' + sum;
      if (!tight && memo.has(key)) return memo.get(key);
      const upper = tight ? digits[pos] : 9;
      let res = 0n;
      for (let d = 0; d <= upper; d++) {
        res = (res + dfs(pos + 1, sum + d, tight && d === upper)) % MOD;
      }
      if (!tight) memo.set(key, res);
      return res;
    }
    return dfs(0, 0, true);
  }

  const upper = countUpTo(num2);
  const lower = countUpTo(decrementStr(num1));
  const ans = (upper - lower + MOD) % MOD;
  return Number(ans);
}

function sortBy(arr, fn) {
  // use the built-in sort function with a compare function that uses fn to determine the sort order
  return arr.sort((a, b) => fn(a) - fn(b));
}

function promiseAll(functions) {
    let resolvedCount = 0;
    let results = new Array(functions.length);
    let startTime = Date.now();
    return new Promise((resolve, reject) => {
        if (functions.length === 0) resolve([]);
        functions.forEach((func, index) => {
            func().then((result) => {
                results[index] = result;
                resolvedCount++;
                if (resolvedCount === functions.length) resolve(results);
            }).catch((error) => {
                reject(error);
            });
        });
    }).then((results) => {
        let timeTaken = Date.now() - startTime;
        return { t: timeTaken, resolved: results };
    }).catch((error) => {
        let timeTaken = Date.now() - startTime;
        return Promise.reject({ t: timeTaken, rejected: error });
    });
}

class Calculator {
    constructor(initialValue) { this.result = initialValue; }
    add(value) { this.result += value; return this; }
    subtract(value) { this.result -= value; return this; }
    multiply(value) { this.result *= value; return this; }
    divide(value) {
        if (value === 0) throw new Error("Division by zero is not allowed");
        this.result /= value;
        return this;
    }
    power(value) { this.result = Math.pow(this.result, value); return this; }
    getResult() { return this.result; }
}

function isFascinating(n) {
    // Create a hash set to store unique digits
    let digitSet = new Set();
    // Concatenate the numbers n, 2n, and 3n
    let concatenated = n + '' + (2 * n) + '' + (3 * n);
    // Iterate over each character in the concatenated string
    for (let i = 0; i < concatenated.length; i++) {
        // Convert the character to an integer
        let digit = parseInt(concatenated[i]);
        // Check if the digit is between 1 and 9 (inclusive)
        if (digit >= 1 && digit <= 9) {
            // Add the digit to the set
            digitSet.add(digit);
        } else {
            // If the digit is not between 1 and 9, return false
            return false;
        }
    }
    // Check if the set contains all digits from 1 to 9
    return digitSet.size === 9;
}

function findNumber(nums) {
  // find the minimum and maximum values in the array
  let minVal = Math.min(...nums);
  let maxVal = Math.max(...nums);
  // iterate through the array to find a number that is neither the minimum nor the maximum
  for (let num of nums) {
    // check if the current number is neither the minimum nor the maximum
    if (num !== minVal && num !== maxVal) {
      return num;
    }
  }
  // if no such number is found, return -1
  return -1;
}

function robotDistances(nums, s, d) {
    const MOD = 1000000007n;
    const n = nums.length;
    // colliding robots swap directions, which is equivalent (for the multiset of final
    // positions) to each robot simply passing through as if it never collided at all -
    // so we can move every robot independently by its own original direction
    const positions = nums.map((num, i) => BigInt(num) + (s[i] === 'R' ? BigInt(d) : -BigInt(d)));
    positions.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
    let total = 0n;
    let prefixSum = 0n;
    for (let i = 0; i < n; i++) {
        total = (total + BigInt(i) * positions[i] - prefixSum) % MOD;
        prefixSum += positions[i];
    }
    total = ((total % MOD) + MOD) % MOD;
    return Number(total);
}

function longestSemiRepetitiveSubstring(s) {
    let maxLength = 0;
    for (let i = 0; i < s.length; i++) {
        for (let j = i + 1; j <= s.length; j++) {
            let substring = s.substring(i, j);
            // Check if the substring has at most one adjacent pair of the same digit
            let count = 0, prev = '';
            for (let k = 0; k < substring.length; k++) {
                if (substring[k] === prev) count++;
                prev = substring[k];
            }
            if (count <= 1) maxLength = Math.max(maxLength, substring.length);
        }
    }
    return maxLength;
}

function lexicographicallySmallestString(s) {
    const arr = s.split('');
    const n = arr.length;
    let i = 0;
    while (i < n && arr[i] === 'a') i++;
    if (i === n) {
        arr[n - 1] = 'z';
        return arr.join('');
    }
    while (i < n && arr[i] !== 'a') {
        arr[i] = String.fromCharCode(arr[i].charCodeAt(0) - 1);
        i++;
    }
    return arr.join('');
}

function minCostToCollectChocolates(nums, x) {
    const n = nums.length;
    let best = Infinity;
    const minSoFar = nums.slice();
    for (let k = 0; k < n; k++) {
        if (k > 0) { for (let i = 0; i < n; i++) minSoFar[i] = Math.min(minSoFar[i], nums[(i + k) % n]); }
        const sum = minSoFar.reduce((a, b) => a + b, 0) + k * x;
        best = Math.min(best, sum);
    }
    return best;
}

function maxSum(nums1, nums2, queries) {
    // Create a 2D array to store the sums of nums1 and nums2 at each index
    let sums = nums1.map((num, index) => num + nums2[index]);

    // Initialize an empty array to store the results of the queries
    let result = [];

    // Iterate over each query
    for (let query of queries) {
        // Initialize the maximum sum to -1
        let maxSum = -1;

        // Iterate over each index in the sums array
        for (let i = 0; i < sums.length; i++) {
            // Check if the current index satisfies the constraints of the query
            if (nums1[i] >= query[0] && nums2[i] >= query[1]) {
                // Update the maximum sum if the current sum is greater
                maxSum = Math.max(maxSum, sums[i]);
            }
        }

        // Add the maximum sum for the current query to the result array
        result.push(maxSum);
    }

    // Return the result array
    return result;
}

function totalDistanceTraveled(mainTank, additionalTank) {
    let dist = 0;
    while (mainTank >= 5) {
        mainTank -= 5;
        dist += 50;
        // every full 5 liters used triggers a 1-liter transfer, even if the tank is now empty
        if (additionalTank > 0) {
            additionalTank--;
            mainTank++;
        }
    }
    dist += mainTank * 10; // remaining partial fuel, no transfer triggered
    return dist;
}

function minimumPartitionValue(nums) {
    nums = nums.slice().sort((a, b) => a - b);
    let minDiff = Infinity;
    for (let i = 0; i < nums.length - 1; i++) {
        minDiff = Math.min(minDiff, nums[i + 1] - nums[i]);
    }
    return minDiff;
}

function countSpecialPermutations(nums) {
    const MOD = 1000000007;
    const n = nums.length;
    const dp = Array.from({ length: 1 << n }, () => new Array(n).fill(-1));
    function solve(mask, last) {
        if (mask === (1 << n) - 1) return 1;
        if (dp[mask][last] !== -1) return dp[mask][last];
        let ways = 0;
        for (let next = 0; next < n; next++) {
            if (mask & (1 << next)) continue;
            if (nums[last] % nums[next] === 0 || nums[next] % nums[last] === 0) {
                ways = (ways + solve(mask | (1 << next), next)) % MOD;
            }
        }
        return dp[mask][last] = ways;
    }
    let total = 0;
    for (let i = 0; i < n; i++) total = (total + solve(1 << i, i)) % MOD;
    return total;
}

function paintWalls(cost, time) {
    const n = cost.length;
    const INF = Infinity;
    // dp[j] = min cost so that "progress" (walls painted by paid painter, plus
    // free-painter walls painted during that time) reaches at least j (capped at n).
    const dp = new Array(n + 1).fill(INF);
    dp[0] = 0;
    for (let i = 0; i < n; i++) {
        for (let j = n; j >= 0; j--) {
            if (dp[j] === INF) continue;
            const nj = Math.min(n, j + time[i] + 1);
            const cand = dp[j] + cost[i];
            if (cand < dp[nj]) dp[nj] = cand;
        }
    }
    return dp[n];
}

function minLength(s) {
  const stack = [];
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    // if top of stack together with current char forms "AB" or "CD", delete them
    if (stack.length && ((stack[stack.length - 1] === 'A' && ch === 'B') ||
                         (stack[stack.length - 1] === 'C' && ch === 'D'))) {
      stack.pop();               // remove the matching previous character
    } else {
      stack.push(ch);            // keep current character for possible future matches
    }
  }
  return stack.length;
}

function makeSmallestPalindrome(s) {
    const a = s.split('');                 // work on mutable array
    let i = 0, j = a.length - 1;
    while (i < j) {
        if (a[i] !== a[j]) {               // main logic: mismatched pair
            const smaller = a[i] < a[j] ? a[i] : a[j];
            a[i] = a[j] = smaller;         // change the larger one to smaller
        }
        i++; j--;
    }
    return a.join('');
}

function minCostToEqualize(s) {
  const n = s.length;
  let ans = 0;
  // whenever consecutive characters differ, a cut must be made there: either flip
  // the whole prefix up to i (cost i) or the whole suffix from i onward (cost n-i)
  for (let i = 1; i < n; i++) {
    if (s[i] !== s[i - 1]) ans += Math.min(i, n - i);
  }
  return ans;
}

function ArrayWrapper(arr, op) {
    if (op === 'Add') {
        let sum = 0;
        for (const sub of arr) for (const v of sub) sum += v;
        return sum;
    }
    if (op === 'String') {
        return '[' + arr[0].join(',') + ']';
    }
    throw new Error('Unsupported operation: ' + op);
}

function isEmpty(obj) {
  // handle arrays quickly
  if (Array.isArray(obj)) return obj.length === 0;
  // check object for any own enumerable property
  for (var key in obj) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) return false;
  }
  return true;
}

function longestEvenOddSubarrayWithThreshold(nums, threshold) {
    let best = 0, curLen = 0, prevParity = null;
    for (const x of nums) {
        if (x > threshold) { curLen = 0; prevParity = null; continue; }
        const parity = x & 1;
        if (curLen === 0) {
            if (parity === 0) { curLen = 1; prevParity = 0; best = Math.max(best, curLen); }
            else { curLen = 0; prevParity = null; }
        } else {
            if (parity !== prevParity) { curLen++; prevParity = parity; best = Math.max(best, curLen); }
            else {
                if (parity === 0) { curLen = 1; prevParity = 0; best = Math.max(best, curLen); }
                else { curLen = 0; prevParity = null; }
            }
        }
    }
    return best;
}

function relocateMarbles(nums, moveFrom, moveTo) {
    // build a set of currently occupied positions
    const occupied = new Set(nums);               // O(nums.length)

    // simulate each move
    for (let i = 0; i < moveFrom.length; i++) {   // O(moveFrom.length)
        const src = moveFrom[i];
        const dst = moveTo[i];
        if (occupied.has(src)) {                  // check if there is a pile to move
            occupied.delete(src);                 // remove the source position
            occupied.add(dst);                    // occupy the destination
        }
    }

    // collect and sort the final positions
    return Array.from(occupied).sort((a, b) => a - b);
}

function countContinuousSubarrays(nums) {
    const n = nums.length;
    let maxDeque = [];
    let minDeque = [];
    let left = 0;
    let total = 0;
    for (let right = 0; right < n; right++) {
        const val = nums[right];
        while (maxDeque.length && nums[maxDeque[maxDeque.length - 1]] < val) {
            maxDeque.pop();
        }
        maxDeque.push(right);
        while (minDeque.length && nums[minDeque[minDeque.length - 1]] > val) {
            minDeque.pop();
        }
        minDeque.push(right);
        while (nums[maxDeque[0]] - nums[minDeque[0]] > 2) {
            if (maxDeque[0] === left) maxDeque.shift();
            if (minDeque[0] === left) minDeque.shift();
            left++;
        }
        total += right - left + 1;
    }
    return total;
}

function longestAlternatingSubarray(nums) {
    if (nums.length < 2) return -1;          // need at least two elements

    let maxLen = 0;
    let curLen = 1;                         // length of current segment
    let prevSign = 0;                       // sign of previous difference

    for (let i = 1; i < nums.length; i++) {
        const diff = nums[i] - nums[i - 1];
        if (diff === 0) {                   // equal neighbours break alternation
            curLen = 1;
            prevSign = 0;
            continue;
        }
        const sign = diff > 0 ? 1 : -1;      // sign of current difference

        // main logic: extend if sign alternates, otherwise restart from i‑1
        if (prevSign !== 0 && sign !== prevSign) {
            curLen++;
