    let leftCnt = 0;
    const n = nums.length;
    for (let i = 0; i < n - 1; i++) {        // both sides must be non‑empty
        if (nums[i] === d) leftCnt++;

        const leftLen = i + 1;
        const rightLen = n - leftLen;

        // main condition: d dominates both sides
        if (leftCnt * 2 > leftLen && (total - leftCnt) * 2 > rightLen) {
