function sortVowels(s) {
    const vowels = ['A','E','I','O','U','a','e','i','o','u'];   // ordered by ASCII
    const isVowel = new Set(vowels);
    const cnt = new Array(10).fill(0);                         // frequency of each vowel

    // count frequencies of vowels
    for (let ch of s) {
        if (isVowel.has(ch)) cnt[vowels.indexOf(ch)]++;
    }

    let idx = 0;                     // points to the next vowel with cnt > 0
    const res = [];

    // rebuild the string with sorted vowels
    for (let ch of s) {
