    // ---------- helper: merge two strings with maximal overlap ----------
    function merge(s, t) {
        if (isSub(s, t)) return s;               // t already inside s
        let max = 0;
        const limit = Math.min(s.length, t.length);
        for (let k = limit; k > 0; k--) {
            if (s.slice(s.length - k) === t.slice(0, k)) {
                max = k;
                break;
            }
        }
        return s + t.slice(max);
    }

    // ---------- remove strings that are substrings of another ----------
    const arr = [a, b, c];
    const filtered = [];
    for (let i = 0; i < 3; i++) {
        let keep = true;
        for (let j = 0; j < 3; j++) {
            if (i !== j && isSub(arr[j], arr[i])) { keep = false; break; }
        }
        if (keep) filtered.push(arr[i]);
    }

    // ---------- generate all permutations ----------
    const perms = [];
    const n = filtered.length;
    if (n === 0) return "";
    if (n === 1) return filtered[0];
    const used = Array(n).fill(false);
    const cur = [];

    function dfs() {
        if (cur.length === n) {
            perms.push(cur.slice());
            return;
        }
        for (let i = 0; i < n; i++) {
            if (!used[i]) {
                used[i] = true;
                cur.push(filtered[i]);
                dfs();
                cur.pop();
                used[i] = false;
            }
        }
    }
    dfs();

    // ---------- evaluate each permutation ----------
    let best = null;
    for (const p of perms) {
        let merged = p[0];
