        }
    }
    return best;
}

function insertGreatestCommonDivisors(head) {
    // handle empty or single‑node list
    if (!head || !head.next) return head;

    // helper: Euclidean algorithm
    function gcd(a, b) {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    let cur = head;
    while (cur && cur.next) {
        const g = gcd(cur.val, cur.next.val);   // compute GCD of the pair
        const gNode = { val: g, next: cur.next }; // new node
        cur.next = gNode;                         // insert it
        cur = gNode.next;                         // move to the next original node
    }
    return head;
}

function countSteppingNumbers(low, high) {
  const MOD = 1000000007n;

  function decStr(s) {
