function minimumTime(nums1, nums2, x) {
    const n = nums1.length;
    let total1 = nums1.reduce((a, b) => a + b, 0);
    const total2 = nums2.reduce((a, b) => a + b, 0);
    if (total1 <= x) return 0;

    const idx = Array.from({ length: n }, (_, i) => i).sort((a, b) => nums2[a] - nums2[b]);
    const NEG = -Infinity;
    const dp = new Array(n + 1).fill(NEG);
    dp[0] = 0;
    for (const i of idx) {
        for (let j = n; j >= 1; j--) {
            if (dp[j - 1] === NEG) continue;
            const candidate = dp[j - 1] + nums1[i] + nums2[i] * j;
