function maxElegance(items, k) {
    // sort by profit descending
    items.sort((a, b) => b[0] - a[0]);

    const seen = new Set();               // categories already taken
    const dupHeap = [];                    // min‑heap of profits that are duplicates
    let profitSum = 0;
    let distinct = 0;

    // helper: push into min‑heap
    function heapPush(val) {
        dupHeap.push(val);
        let i = dupHeap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (dupHeap[p] <= dupHeap[i]) break;
            [dupHeap[p], dupHeap[i]] = [dupHeap[i], dupHeap[p]];
            i = p;
        }
    }
    // helper: pop min from heap
    function heapPop() {
        const min = dupHeap[0];
        const last = dupHeap.pop();
        if (dupHeap.length) {
            dupHeap[0] = last;
            let i = 0;
            while (true) {
                let l = i * 2 + 1, r = i * 2 + 2, smallest = i;
                if (l < dupHeap.length && dupHeap[l] < dupHeap[smallest]) smallest = l;
                if (r < dupHeap.length && dupHeap[r] < dupHeap[smallest]) smallest = r;
                if (smallest === i) break;
                [dupHeap[i], dupHeap[smallest]] = [dupHeap[smallest], dupHeap[i]];
                i = smallest;
            }
        }
        return min;
    }

    // pick first k items (largest profits)
    for (let i = 0; i < k; ++i) {
        const [p, c] = items[i];
        profitSum += p;
        if (seen.has(c)) {
            heapPush(p);                     // duplicate category → candidate for replacement
        } else {
            seen.add(c);
            ++distinct;
        }
    }

    let best = profitSum + distinct * distinct;   // initial elegance

    // try to introduce new categories by swapping out cheapest duplicates
    for (let i = k; i < items.length; ++i) {
        const [p, c] = items[i];
        if (seen.has(c)) continue;                // only new categories can improve distinct count
        if (dupHeap.length === 0) break;          // no duplicate to replace
        const removed = heapPop();                 // remove cheapest duplicate profit
        profitSum = profitSum - removed + p;
        seen.add(c);
        ++distinct;
        const cur = profitSum + distinct * distinct;
        if (cur > best) best = cur;
    }

    return best;
}

function minimumSecondsToEqualizeACircularArray(nums) {
    const n = nums.length;
    if (n <= 1) return 0;
    const info = new Map();
    for (let i = 0; i < n; i++) {
        const v = nums[i];
        if (!info.has(v)) info.set(v, [i, i, 0]);
        else {
            const [first, prev, maxGap] = info.get(v);
            const gap = i - prev - 1;
            info.set(v, [first, i, Math.max(maxGap, gap)]);
        }
    }

    let answer = Infinity;
    for (const [first, prev, maxGap0] of info.values()) {
        let maxGap = maxGap0;
        let wrapGap;
        if (maxGap === n - 1) wrapGap = n - 1;
        else wrapGap = ((first + n - prev - 1) % n + n) % n;
        if (wrapGap > maxGap) maxGap = wrapGap;
        if (maxGap === n - 1 && info.size === 1) return 0;
        const seconds = Math.floor((maxGap + 1) / 2);
