function canSplitArray(nums, m) {
  const n = nums.length;
  const prefix = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];

  const memo = Array.from({ length: n }, () => Array(n).fill(undefined));

  function sum(l, r) {
    return prefix[r + 1] - prefix[l];
  }

  function dfs(l, r) {
    if (l === r) return true;
    if (memo[l][r] !== undefined) return memo[l][r];
    if (sum(l, r) < m) return (memo[l][r] = false);
    for (let k = l; k < r; k++) {
      if (dfs(l, k) && dfs(k + 1, r)) return (memo[l][r] = true);
    }
    return (memo[l][r] = false);
  }

  return dfs(0, n - 1);
}

function faultyKeyboard(s) {
