function doubleLinkedList(head) {
    // reverse the list so we can process from least‑significant digit
    let prev = null, cur = head;
    while (cur) {
        const nxt = cur.next;
        cur.next = prev;
        prev = cur;
        cur = nxt;
    }
    // prev is now the head of the reversed list
    let node = prev, carry = 0, last = null;
    while (node) {
        const sum = node.val * 2 + carry;   // double current digit + carry
        node.val = sum % 10;                // store new digit
        carry = Math.floor(sum / 10);       // new carry (0 or 1)
        last = node;                        // remember last processed node
        node = node.next;
    }
    // if a carry remains, create a new most‑significant digit
    if (carry) {
        last.next = { val: carry, next: null };
    }
    // reverse again to restore original order (now doubled)
    cur = prev;
    prev = null;
    while (cur) {
        const nxt = cur.next;
        cur.next = prev;
        prev = cur;
        cur = nxt;
    }
    return prev;   // new head of the doubled number
