    let best = Infinity;
    for (let i=0;i<nums.length;i++) {
        if (i - x >= 0) {
            const insertVal = nums[i-x];
            const pos = bisectLeft(sortedArr, insertVal);
            sortedArr.splice(pos, 0, insertVal);
        }
        if (sortedArr.length) {
            const val = nums[i];
            const pos = bisectLeft(sortedArr, val);
            if (pos < sortedArr.length) {
                const diff = Math.abs(sortedArr[pos]-val);
                if (diff < best) best = diff;
            }
            if (pos > 0) {
                const diff = Math.abs(sortedArr[pos-1]-val);
                if (diff < best) best = diff;
            }
        }
    }
    return best === Infinity ? 0 : best;
