function findTheSafestPathInAGrid(grid) {
    if (!grid.length || !grid[0].length) return 0;
    const rows = grid.length, cols = grid[0].length;
    const dist = Array.from({length: rows}, () => new Array(cols).fill(-1));
    const q = [];
    for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) if (grid[r][c] === 1) { dist[r][c] = 0; q.push([r, c]); }

    let head = 0;
    const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
    while (head < q.length) {
        const [r, c] = q[head++];
        const nd = dist[r][c] + 1;
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && dist[nr][nc] === -1) {
                dist[nr][nc] = nd;
                q.push([nr, nc]);
            }
        }
    }

    const best = Array.from({length: rows}, () => new Array(cols).fill(-1));
    const startSafety = dist[0][0];
    best[0][0] = startSafety;

    const heap = [[-startSafety, 0, 0]];
    const less = (a, b) => a[0] !== b[0] ? a[0] < b[0] : (a[1] !== b[1] ? a[1] < b[1] : a[2] < b[2]);
    const push = (item) => {
        heap.push(item);
        let i = heap.length - 1;
        while (i > 0) { const p = (i - 1) >> 1; if (less(heap[i], heap[p])) { [heap[i], heap[p]] = [heap[p], heap[i]]; i = p; } else break; }
    };
    const pop = () => {
        const top = heap[0]; const last = heap.pop();
        if (heap.length) {
            heap[0] = last; let i = 0;
            while (true) { let l = 2*i+1, r = 2*i+2, s = i; if (l < heap.length && less(heap[l], heap[s])) s = l; if (r < heap.length && less(heap[r], heap[s])) s = r; if (s === i) break; [heap[i], heap[s]] = [heap[s], heap[i]]; i = s; }
        }
        return top;
    };

    while (heap.length) {
        const [negSafety, r, c] = pop();
        const safety = -negSafety;
        if (r === rows - 1 && c === cols - 1) return safety;
        if (safety < best[r][c]) continue;
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                const newSafety = Math.min(safety, dist[nr][nc]);
                if (newSafety > best[nr][nc]) {
                    best[nr][nc] = newSafety;
                    push([-newSafety, nr, nc]);
                }
            }
        }
    }
    return 0;
}

