function maxProfit(n, offers) {
    // sort offers by their end coordinate
    offers.sort((a, b) => a[1] - b[1]);

    const m = offers.length;
    const ends = new Array(m);
    for (let i = 0; i < m; ++i) ends[i] = offers[i][1];

    const dp = new Array(m + 1).fill(0); // dp[0] = 0

    for (let i = 1; i <= m; ++i) {
        const [start, end, gold] = offers[i - 1];

        // binary search for the last offer ending before 'start'
        let lo = 0, hi = i - 2, pos = 0; // pos = number of offers that fit, i.e., dp index
        while (lo <= hi) {
