function numberOfBeautifulIntegersInTheRange(low, high, k) {
    const countUpto = (n) => {
        if (n < 0) return 0;
        const digits = String(n).split('').map(Number);
        const m = digits.length;
        const memo = new Map();

        const dfs = (pos, diff, rem, tight, started) => {
            if (pos === m) return (started && diff === 0 && rem === 0) ? 1 : 0;
            const key = pos + ',' + diff + ',' + rem + ',' + (tight?1:0) + ',' + (started?1:0);
            if (memo.has(key)) return memo.get(key);
