    const even1 = [s1[0], s1[2]].sort().join('');
    const odd1 = [s1[1], s1[3]].sort().join('');
    const even2 = [s2[0], s2[2]].sort().join('');
    const odd2 = [s2[1], s2[3]].sort().join('');
    return even1 === even2 && odd1 === odd2;
}

function minOperations(num) {
    const s = num;
    const n = s.length;
    let best = n;
    const targets = [['0','0'], ['2','5'], ['5','0'], ['7','5']];
    for (const [a, b] of targets) {
        let i = n - 1;
        while (i >= 0 && s[i] !== b) i--;
        if (i < 0) continue;
        let j = i - 1;
        while (j >= 0 && s[j] !== a) j--;
        if (j < 0) continue;
        best = Math.min(best, n - j - 2);
    }
    // a lone '0' digit is itself divisible by 25
    for (let i = n - 1; i >= 0; i--) {
        if (s[i] === '0') { best = Math.min(best, n - 1); break; }
    }
    return best;
}

function minimumEdgeWeightEquilibriumQueries(n, edges, queries) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v, w] of edges) {
        adj[u].push([v, w]);
        adj[v].push([u, w]);
    }
    const LOG = Math.ceil(Math.log2(n)) + 1;
    const up = Array.from({ length: n }, () => Array(LOG).fill(-1));
    const depth = new Int32Array(n);
    const cum = Array.from({ length: n }, () => new Uint16Array(27)); // 1..26

    const stack = [0];
    const visited = new Uint8Array(n);
    visited[0] = 1;
    while (stack.length) {
        const node = stack.pop();
        for (const [nei, w] of adj[node]) {
            if (!visited[nei]) {
                visited[nei] = 1;
                depth[nei] = depth[node] + 1;
                up[nei][0] = node;
                const cur = cum[nei];
                const prev = cum[node];
                cur.set(prev);
                cur[w] = cur[w] + 1;
                stack.push(nei);
            }
        }
    }

    for (let k = 1; k < LOG; k++) {
        for (let v = 0; v < n; v++) {
            const mid = up[v][k - 1];
            up[v][k] = mid === -1 ? -1 : up[mid][k - 1];
        }
    }

    function lca(u, v) {
        if (depth[u] < depth[v]) [u, v] = [v, u];
        for (let k = LOG - 1; k >= 0; k--) {
            if (up[u][k] !== -1 && depth[up[u][k]] >= depth[v]) {
                u = up[u][k];
            }
        }
        if (u === v) return u;
        for (let k = LOG - 1; k >= 0; k--) {
            if (up[u][k] !== -1 && up[u][k] !== up[v][k]) {
                u = up[u][k];
                v = up[v][k];
            }
        }
        return up[u][0];
    }

    const ans = [];
    for (const [a, b] of queries) {
        const L = lca(a, b);
        const pathLen = depth[a] + depth[b] - 2 * depth[L];
        let maxFreq = 0;
        const ca = cum[a];
        const cb = cum[b];
        const cl = cum[L];
        for (let w = 1; w <= 26; w++) {
            const freq = ca[w] + cb[w] - 2 * cl[w];
            if (freq > maxFreq) maxFreq = freq;
        }
        ans.push(pathLen - maxFreq);
    }
    return ans;
}
// TIME: O((n + m) * 26) SPACE: O(n * (LOG + 26))

var countSymmetricIntegers = function(low, high) {
    let answer = 0;
    const pow10 = [1];
    for (let i=1;i<11;i++) pow10.push(pow10[i-1]*10);
    for (let x=low;x<=high;x++) {
        const len = (x===0) ? 1 : Math.floor(Math.log10(x))+1;
        if (len % 2 !== 0) continue;
        const half = Math.floor(len/2);
        let left = Math.floor(x / pow10[half]);
        let right = x % pow10[half];
        let leftSum = 0, rightSum = 0;
        while (left > 0) { leftSum += left%10; left = Math.floor(left/10); }
        for (let i=0;i<half;i++) { rightSum += right%10; right = Math.floor(right/10); }
        if (leftSum === rightSum) answer++;
    }
    return answer;
};

function canReach(sx, sy, fx, fy, t) {
    var dx = Math.abs(fx - sx);
    var dy = Math.abs(fy - sy);
    var minSteps = Math.max(dx, dy);               // minimum seconds needed (Chebyshev distance)

    if (t < minSteps) return false;                // not enough time
    if (minSteps === 0) return t % 2 === 0;        // must return to start, only even t works
    return true;                                   // extra seconds can be wasted arbitrarily
}

function countKSubsequencesOfAStringWithMaximumBeauty(s, k) {
    const MOD = 1000000007n;
    const freq = new Array(26).fill(0);
    for (const ch of s) freq[ch.charCodeAt(0) - 97]++;

    const freqs = freq.filter(c => c);
    const distinct = freqs.length;
    if (k > distinct) return 0;
    if (k === 0) return 1;

    freqs.sort((a, b) => b - a);
    const threshold = freqs[k - 1];

    const higher = freqs.filter(f => f > threshold).length;
    const cntTotal = freqs.filter(f => f === threshold).length;
    const cntNeeded = k - higher;

    const modpow = (base, exp, mod) => {
        base %= mod;
        let result = 1n;
        while (exp > 0n) { if (exp & 1n) result = (result * base) % mod; base = (base * base) % mod; exp >>= 1n; }
        return result;
    };

    let prod = 1n;
    for (const f of freqs) if (f > threshold) prod = (prod * BigInt(f)) % MOD;
    prod = (prod * modpow(BigInt(threshold), BigInt(cntNeeded), MOD)) % MOD;

    const comb = (n, r) => {
        if (r < 0 || r > n) return 0n;
        let num = 1n, den = 1n;
        for (let i = 0; i < r; i++) { num = (num * BigInt(n - i)) % MOD; den = (den * BigInt(i + 1)) % MOD; }
        return (num * modpow(den, MOD - 2n, MOD)) % MOD;
    };

    const combVal = comb(cntTotal, cntNeeded);
    return Number((prod * combVal) % MOD);
}

function popcount(x) {
    let cnt = 0;
    while (x) { x &= x - 1; cnt++; }
    return cnt;
}

function minMoves(grid) {
    const stones = [];
    for (let r = 0; r < 3; r++)
        for (let c = 0; c < 3; c++)
            for (let k = 0; k < grid[r][c]; k++)
                stones.push([r, c]);
    const targets = [];
    for (let r = 0; r < 3; r++) for (let c = 0; c < 3; c++) targets.push([r, c]);
    const n = 9;
    const dist = Array.from({ length: n }, () => new Array(n).fill(0));
    for (let i = 0; i < n; i++) {
        const [sr, sc] = stones[i];
        for (let j = 0; j < n; j++) {
            const [tr, tc] = targets[j];
            dist[i][j] = Math.abs(sr - tr) + Math.abs(sc - tc);
        }
    }
    const INF = 1e9;
    const size = 1 << n;
    const dp = new Array(size).fill(INF);
    dp[0] = 0;
    for (let mask = 0; mask < size; mask++) {
        const k = popcount(mask);
        if (k >= n) continue;
        const cur = dp[mask];
        if (cur === INF) continue;
        for (let j = 0; j < n; j++) {
            if (mask & (1 << j)) continue;
            const nextMask = mask | (1 << j);
            const cand = cur + dist[k][j];
            if (cand < dp[nextMask]) dp[nextMask] = cand;
        }
    }
    return dp[size - 1];
}

function numberOfWays(s, t, k) {
    const MOD = 1000000007n;
    const n = s.length;

    function matMul(a, b) {
        const r = [[0n,0n],[0n,0n]];
        for (let i=0;i<2;i++) for (let j=0;j<2;j++){
            let sum=0n;
            for (let x=0;x<2;x++) sum = (sum + a[i][x]*b[x][j]) % MOD;
            r[i][j]=sum;
        }
        return r;
    }
    function matPow(m, e) {
        let result = [[1n,0n],[0n,1n]];
        let base = m;
        let exp = BigInt(e);
        while (exp>0n) {
            if (exp & 1n) result = matMul(result, base);
            base = matMul(base, base);
            exp >>= 1n;
        }
        return result;
    }
    const trans = [[0n,1n],[BigInt(n-1), BigInt(n-2)]];
    const p = matPow(trans, k);
    const dp0 = p[0][0], dp1 = p[0][1];

    // Z-algorithm on s+t+t
    const combined = s + t + t;
    const m = combined.length;
    const z = new Array(m).fill(0);
    let left=0, right=0;
    for (let i=1;i<m;i++){
        let zi = 0;
        if (i<=right && z[i-left] <= right-i) {
            zi = z[i-left];
        } else {
            zi = Math.max(0, right-i+1);
            while (i+zi<m && combined[i+zi]===combined[zi]) zi++;
        }
        z[i]=zi;
        if (i+zi-1>right){ left=i; right=i+zi-1; }
    }

    let result = 0n;
    for (let i=n;i<2*n;i++){
        if (z[i]>=n) {
            const rot = i-n;
            result = (result + (rot===0?dp0:dp1)) % MOD;
        }
    }
    return Number(result);
}

function countCoveredPoints(nums) {
    if (nums.length === 0) return 0;                     // handle empty input

    // sort intervals by start coordinate
    nums.sort((a, b) => a[0] - b[0]);

    let total = 0;
    let curStart = nums[0][0];
    let curEnd   = nums[0][1];

    for (let i = 1; i < nums.length; i++) {
        const s = nums[i][0];
        const e = nums[i][1];

        // main logic: merge overlapping or adjacent intervals
        if (s <= curEnd + 1) {
            if (e > curEnd) curEnd = e;                  // extend current interval
        } else {
            total += curEnd - curStart + 1;              // add length of finished interval
            curStart = s;
            curEnd   = e;
        }
    }

    total += curEnd - curStart + 1;                       // add last interval
    return total;
}

function minimumRightShifts(nums) {
    const n = nums.length;
    let dropIdx = -1, drops = 0;
    for (let i = 0; i < n; i++) {
        if (nums[i] > nums[(i+1)%n]) { drops++; dropIdx = i; }
    }
    if (drops === 0) return 0;
    if (drops > 1) return -1;
    return n - dropIdx - 1;
}

function countPairs(coordinates, k) {
    const map = new Map();
    let ans = 0;
    for (const [x, y] of coordinates) {
        for (let a = 0; a <= k; a++) {
            const b = k - a;
            const xa = x ^ a, yb = y ^ b;
            const key = xa + ',' + yb;
            if (map.has(key)) ans += map.get(key);
        }
        const key = x + ',' + y;
        map.set(key, (map.get(key) || 0) + 1);
    }
    return ans;
}

function countInterestingSubarrays(nums, modulo, k) {
    // map remainder → frequency of that remainder among processed prefixes
    const freq = new Map();
    freq.set(0, 1);                     // empty prefix

    let prefix = 0;                     // total number of contributing elements seen
    let answer = 0;

    for (let i = 0; i < nums.length; i++) {
        // main logic: update prefix if current element satisfies the condition
        if (nums[i] % modulo === k) prefix++;

        const curMod = prefix % modulo;
        const need = (curMod - k + modulo) % modulo;   // required previous remainder

        // add all earlier prefixes that make the sub‑array interesting
        answer += freq.get(need) || 0;

        // store current remainder for future sub‑arrays
        freq.set(curMod, (freq.get(curMod) || 0) + 1);
    }
    return answer;
}

function minArrayLength(nums) {
    const n = nums.length;
    let maxFreq = 0;
    let i = 0;
    while (i < n) {
        let j = i;
        // count occurrences of the current value
        while (j < n && nums[j] === nums[i]) j++;
        const freq = j - i;               // MAIN LOGIC: frequency of this value
        if (freq > maxFreq) maxFreq = freq; // update maximal frequency
        i = j;                            // move to next distinct value
    }
    return Math.max(0, 2 * maxFreq - n);
}

function sumIndicesWithKSetBits(nums, k) {
    const n = nums.length;
    const pop = new Uint8Array(n);   // pop[i] = number of set bits in i
    let answer = 0;

    for (let i = 0; i < n; i++) {
        // pop‑count using previously computed value
        pop[i] = i === 0 ? 0 : pop[i & (i - 1)] + 1;   // main logic
        if (pop[i] === k) answer += nums[i];
    }
    return answer;
}

function maxCompleteSubsetSum(nums) {
    const n = nums.length;
    // build smallest prime factor array
    const spf = new Uint32Array(n + 1);
    for (let i = 2; i <= n; i++) if (!spf[i]) {
        for (let j = i; j <= n; j += i) if (!spf[j]) spf[j] = i;
    }

    const groupSum = Object.create(null);
    let best = -Infinity;

    // process each index (1‑based)
    for (let idx = 1; idx <= n; idx++) {
        // compute square‑free part of idx
        let x = idx, sqFree = 1;
        while (x > 1) {
            const p = spf[x];
            let cnt = 0;
            while (x % p === 0) { x /= p; cnt++; }
            if (cnt & 1) sqFree *= p;          // keep prime if exponent is odd
        }
        const key = sqFree;                     // square‑free part as group key
        const newSum = (groupSum[key] || 0) + nums[idx - 1];
        groupSum[key] = newSum;
        if (newSum > best) best = newSum;       // keep maximum group sum
    }
    return best;
}

function maxAlloys(n, k, budget, composition, stock, cost) {
    // pre‑compute total value of current stock (used for upper bounds)
    let stockValue = 0;
    for (let j = 0; j < n; ++j) stockValue += stock[j] * cost[j];

    let best = 0;

    for (let i = 0; i < k; ++i) {
        // base cost of one alloy when buying everything
        let baseCost = 0;
        for (let j = 0; j < n; ++j) baseCost += composition[i][j] * cost[j];

        // if baseCost is zero, the machine needs no metal → infinite alloys,
        // but constraints guarantee at least one positive requirement.
        let high = Math.floor((budget + stockValue) / baseCost);
        let low = 0;

        // binary search for the largest feasible number of alloys
        while (low < high) {
            const mid = Math.floor((low + high + 1) / 2);
            let needed = 0;
            for (let j = 0; j < n; ++j) {
                const required = mid * composition[i][j];
                if (required > stock[j]) {
                    needed += (required - stock[j]) * cost[j];
                    if (needed > budget) break; // early exit
                }
            }
            if (needed <= budget) low = mid;      // feasible → try larger
            else high = mid - 1;                  // not feasible → shrink
        }
        if (low > best) best = low;
    }
    return best;
}

function countWays(nums) {
    const n = nums.length;
    const freq = new Array(n + 1).fill(0);
    for (const v of nums) freq[v]++;

    let ans = 0;
    let pref = 0;
    for (let k = 0; k < n; k++) {
        if (pref === k && freq[k] === 0) ans++;
        pref += freq[k];
    }
    ans++;
    return ans;
}

function maxOddBinaryNumber(s) {
    // count how many '1's are present
    let ones = 0;
    for (let i = 0; i < s.length; ++i) {
        if (s[i] === '1') ++ones;
    }
    // remaining ones go to the front, then zeros, finally one '1'
    const frontOnes = ones - 1;                 // one '1' is reserved for the last position
    const zeros = s.length - ones;              // all other positions are zeros
    return '1'.repeat(frontOnes) + '0'.repeat(zeros) + '1';
}

function maxSumBeautifulTowers(maxHeights) {
    const n = maxHeights.length;
    const left = new Array(n);
    const right = new Array(n);
    let stack = [];

    for (let i = 0; i < n; i++) {
        while (stack.length && maxHeights[stack[stack.length - 1]] >= maxHeights[i]) {
            stack.pop();
        }
        if (stack.length === 0) {
            left[i] = maxHeights[i] * (i + 1);
        } else {
            const prev = stack[stack.length - 1];
            left[i] = left[prev] + maxHeights[i] * (i - prev);
        }
        stack.push(i);
    }

    stack = [];
    for (let i = n - 1; i >= 0; i--) {
        while (stack.length && maxHeights[stack[stack.length - 1]] >= maxHeights[i]) {
            stack.pop();
        }
        if (stack.length === 0) {
            right[i] = maxHeights[i] * (n - i);
        } else {
            const prev = stack[stack.length - 1];
            right[i] = right[prev] + maxHeights[i] * (prev - i);
        }
        stack.push(i);
    }

    let ans = 0;
    for (let i = 0; i < n; i++) {
        const total = left[i] + right[i] - maxHeights[i];
        if (total > ans) ans = total;
    }
    return ans;
}

function minimumOperations(nums) {
    const freq = new Map();                     // count occurrences
    for (let v of nums) {
        freq.set(v, (freq.get(v) || 0) + 1);
    }

    let ops = 0;
    for (let f of freq.values()) {
        if (f === 1) return -1;                 // impossible case
        // main logic: minimum groups of size 2 or 3 for frequency f
        ops += Math.floor(f / 3) + (f % 3 === 0 ? 0 : 1);
    }
    return ops;
}

function beautifulTowersI(heights) {
    const n = heights.length;
    const left = new Array(n).fill(0);
    let stack = [];
    for (let i = 0; i < n; i++) {
        const h = heights[i];
        while (stack.length && heights[stack[stack.length - 1]] >= h) stack.pop();
        if (stack.length) {
            const prev = stack[stack.length - 1];
            left[i] = left[prev] + h * (i - prev);
        } else {
            left[i] = h * (i + 1);
        }
        stack.push(i);
    }

    const right = new Array(n).fill(0);
    stack = [];
    for (let i = n - 1; i >= 0; i--) {
        const h = heights[i];
        while (stack.length && heights[stack[stack.length - 1]] >= h) stack.pop();
        if (stack.length) {
            const nxt = stack[stack.length - 1];
            right[i] = right[nxt] + h * (nxt - i);
        } else {
            right[i] = h * (n - i);
        }
        stack.push(i);
    }

    let best = 0;
    for (let i = 0; i < n; i++) {
        const total = left[i] + right[i] - heights[i];
        if (total > best) best = total;
    }
    return best;
}

var countPaths = function(n, edges) {
    const isPrime = new Array(n+1).fill(false);
    if (n >= 2) {
        for (let i=2;i<=n;i++) isPrime[i] = true;
        let i = 2;
        while (i*i <= n) {
            if (isPrime[i]) {
                for (let j=i*i;j<=n;j+=i) isPrime[j] = false;
            }
            i++;
        }
    }
    const adj = Array.from({length:n+1}, () => []);
    for (const [u,v] of edges) { adj[u].push(v); adj[v].push(u); }
    const compId = new Array(n+1).fill(0);
    const compSize = [0];
    let compCnt = 0;
    for (let node=1; node<=n; node++) {
        if (isPrime[node] || compId[node]) continue;
        compCnt++;
        let size = 0;
        const stack = [node];
        compId[node] = compCnt;
        while (stack.length) {
            const cur = stack.pop();
            size++;
            for (const nb of adj[cur]) {
                if (!isPrime[nb] && !compId[nb]) {
                    compId[nb] = compCnt;
                    stack.push(nb);
                }
            }
        }
        compSize.push(size);
    }
    let answer = 0;
    for (let p=1;p<=n;p++) {
        if (!isPrime[p]) continue;
        let total = 0, sumSq = 0;
        const seen = new Set();
        for (const nb of adj[p]) {
            if (isPrime[nb]) continue;
            const cid = compId[nb];
            if (seen.has(cid)) continue;
            seen.add(cid);
            const sz = compSize[cid];
            total += sz;
            sumSq += sz*sz;
        }
        if (total) {
            answer += total + Math.floor((total*total - sumSq)/2);
        }
    }
    return answer;
};

var maxKDivisibleComponents = function(n, edges, values, k) {
    const adj = Array.from({length:n}, () => []);
    for (const [u,v] of edges) { adj[u].push(v); adj[v].push(u); }
    function dfs(u, parent) {
        let sumMod = values[u] % k;
        let comps = 0;
        for (const v of adj[u]) {
            if (v === parent) continue;
            const r = dfs(v, u);
            const childMod = r[0], childComps = r[1];
            if (childMod === 0) comps += childComps + 1;
            else { comps += childComps; sumMod = (sumMod + childMod) % k; }
        }
        return [sumMod, comps];
    }
    const root = dfs(0, -1);
    return root[1] + (root[0] === 0 ? 1 : 0);
};

function maxTripletValue(nums) {
    const n = nums.length;
    if (n < 3) return 0;
    let maxPrefix = nums[0];
    let bestDiff = -Infinity;
    let answer = -Infinity;
    for (let idx = 1; idx < n; ++idx) {
        if (idx >= 2 && bestDiff > -Infinity) {
            answer = Math.max(answer, bestDiff * nums[idx]);
        }
        const diff = maxPrefix - nums[idx];
        if (diff > bestDiff) bestDiff = diff;
        if (nums[idx] > maxPrefix) maxPrefix = nums[idx];
    }
    // the problem defines the answer as 0 when every triplet's value is negative
    return Math.max(0, answer);
}

function minOperations(nums, k) {
    const missing = new Set();                     // numbers still not seen
    for (let v = 1; v <= k; ++v) missing.add(v);   // initialise with 1..k

    let ops = 0;
    for (let i = nums.length - 1; i >= 0; --i) {   // scan from the end
        if (missing.has(nums[i])) missing.delete(nums[i]); // main logic
        ++ops;
        if (missing.size === 0) return ops;       // all 1..k collected
    }
    return -1; // k numbers not all present (should not happen per problem)
}

function maxSubarraysWithMinScore(nums) {
    let totalAnd = nums[0];
    for (let i = 1; i < nums.length; i++) {
        totalAnd &= nums[i];
    }
    let count = 0;
    let cur = -1;
    for (const v of nums) {
        cur &= v;
        if (cur === totalAnd) {
            count++;
            cur = -1;
        }
    }
    return count;
}

function maximumValueOfAnOrderedTripletII(nums) {
    const n = nums.length;
    if (n < 3) return 0;
    const suffixMax = new Array(n).fill(0);
    suffixMax[n - 1] = nums[n - 1];
    for (let i = n - 2; i >= 0; i--) suffixMax[i] = Math.max(nums[i], suffixMax[i + 1]);

    let best = 0, leftMax = nums[0];
    for (let j = 1; j < n - 1; j++) {
        const diff = leftMax - nums[j];
        if (diff > 0) {
            const candidate = diff * suffixMax[j + 1];
            if (candidate > best) best = candidate;
        }
        if (nums[j] > leftMax) leftMax = nums[j];
    }
    return best;
}

function countVisitedNodes(edges) {
  const n = edges.length;
  const answer = new Array(n).fill(0);
  const visited = new Uint8Array(n); // 0 = unvisited, 1 = in current walk, 2 = done

  for (let start = 0; start < n; start++) {
    if (answer[start]) continue;               // already computed

    let cur = start;
    const stack = [];

    // walk forward until we hit a visited node
    while (visited[cur] === 0) {
      visited[cur] = 1;                         // mark as in current walk
      stack.push(cur);
      cur = edges[cur];
    }

    // if we met a node that is still in the current walk → a new cycle
    if (visited[cur] === 1) {
      let cycleLen = 1;
      let node = edges[cur];
      while (node !== cur) {                    // count cycle length
        cycleLen++;
        node = edges[node];
      }
      // assign the cycle length to every node of the cycle
      node = cur;
      do {
        answer[node] = cycleLen;
        visited[node] = 2;
        node = edges[node];
      } while (node !== cur);
    }

    // unwind the stored path, using already known answers
    while (stack.length) {
      const node = stack.pop();
      if (answer[node]) {                       // node belongs to a cycle
        visited[node] = 2;
        continue;
      }
      const nxt = edges[node];
      answer[node] = answer[nxt] + 1;           // DP relation
      visited[node] = 2;
    }
  }
  return answer;
}

function minSizeSubarrayInfinite(nums, target) {
    const n = nums.length;
    const pref = new Array(n + 1);
    pref[0] = 0;
    for (let i = 0; i < n; i++) {
        pref[i + 1] = pref[i] + nums[i];
    }
    const sumAll = pref[n];
    const map = new Map();
    for (let i = 0; i <= n; i++) {
        if (!map.has(pref[i])) {
            map.set(pref[i], i);
        }
    }
    let ans = Infinity;
    for (let i = 0; i < n; i++) {
        const suffix = sumAll - pref[i];
        if (target <= suffix) {
            const needed = pref[i] + target;
            const j = map.get(needed);
            if (j !== undefined) {
                const len = j - i;
                if (len < ans) ans = len;
            }
        } else {
            const remaining = target - suffix;
            const k = Math.floor(remaining / sumAll);
            const remaining2 = remaining - k * sumAll;
            if (remaining2 === 0) {
                const len = (n - i) + k * n;
                if (len < ans) ans = len;
            } else {
                const j = map.get(remaining2);
                if (j !== undefined) {
                    const len = (n - i) + k * n + j;
                    if (len < ans) ans = len;
                }
            }
        }
    }
    return ans === Infinity ? -1 : ans;
}

function minimumEdgeReversals(n, edges) {
  const adj = Array.from({ length: n }, () => []);
  for (const [u, v] of edges) {
    adj[u].push([v, 0]);
    adj[v].push([u, 1]);
  }
  const answer = new Array(n).fill(0);
  let total = 0;
  const stack1 = [[0, -1]];
  while (stack1.length) {
    const [node, parent] = stack1.pop();
    for (const [nei, cost] of adj[node]) {
      if (nei === parent) continue;
      total += cost;
      stack1.push([nei, node]);
    }
  }
  answer[0] = total;
  const stack2 = [[0, -1]];
  while (stack2.length) {
    const [node, parent] = stack2.pop();
    for (const [nei, cost] of adj[node]) {
      if (nei === parent) continue;
      answer[nei] = answer[node] + (cost === 0 ? 1 : -1);
      stack2.push([nei, node]);
    }
  }
  return answer;
}

function divisibleNonDivisibleDifference(n, m) {
    // total sum of 1..n
    const total = n * (n + 1) / 2;
    // count of multiples of m up to n
    const k = Math.floor(n / m);
    // sum of those multiples
    const divisible = m * k * (k + 1) / 2;
    // result = total - 2 * divisible
    return total - 2 * divisible;
}

function minCostToMakeEqual(s1, s2, x) {
    const n = s1.length;
    const positions = [];
    for (let i = 0; i < n; i++) if (s1[i] !== s2[i]) positions.push(i);
    const m = positions.length;
    if (m % 2 !== 0) return -1;
    if (m === 0) return 0;
    const dp = new Array(m + 1).fill(Infinity);
    dp[0] = 0;
    for (let i = 1; i <= m; i++) {
        dp[i] = dp[i - 1] + x;
        if (i >= 2) dp[i] = Math.min(dp[i], dp[i - 2] + Math.min(x, positions[i - 1] - positions[i - 2]));
    }
    return dp[m];
}

function maxSumOfSquares(nums, k) {
  const MOD = 1000000007n;
  const bitCount = new Array(32).fill(0);
  for (const num of nums) {
    for (let b = 0; b < 32; b++) {
      if (num & (1 << b)) bitCount[b]++;
    }
  }
  const result = new Array(k).fill(0);
  for (let b = 31; b >= 0; b--) {
    const cnt = Math.min(bitCount[b], k);
    for (let i = 0; i < cnt; i++) {
      result[i] |= (1 << b);
    }
  }
  let sum = 0n;
  for (const r of result) {
    const big = BigInt(r >>> 0);
    sum = (sum + big * big) % MOD;
  }
  return Number(sum);
}

function lastVisitedIntegers(nums) {
    const seen = [];
    const ans = [];
    let cur = -1;
    for (let i = 0; i < nums.length; i++) {
        const v = nums[i];
        if (v === -1) {
            if (cur >= 0) {
                ans.push(seen[cur]);
                cur--;
            } else {
                ans.push(-1);
            }
        } else {
            seen.push(v);
            cur = seen.length - 1;
        }
    }
    return ans;
}

function minProcessingTime(processorTime, tasks) {
    processorTime.sort((a,b) => a-b);
    tasks.sort((a,b) => b-a);
    let ans = 0;
    for (let i = 0; i < processorTime.length; i++) {
        ans = Math.max(ans, processorTime[i] + tasks[i*4]);
    }
    return ans;
}

var shortestBeautifulSubstring = function(s, k) {
    const n = s.length;
    if (k === 0) return s.includes('0') ? "0" : "";
    let left = 0, ones = 0;
    let minLen = Infinity, bestStart = -1;
    for (let right=0; right<n; right++) {
        if (s[right]==='1') ones++;
        while (ones > k) {
            if (s[left]==='1') ones--;
            left++;
        }
        while (ones === k && left <= right && s[left]==='0') left++;
        if (ones === k) {
            const curLen = right-left+1;
            if (curLen < minLen) { minLen = curLen; bestStart = left; }
            else if (curLen === minLen) {
                if (s.slice(left, left+curLen) < s.slice(bestStart, bestStart+curLen)) bestStart = left;
            }
        }
    }
    if (bestStart === -1) return "";
    return s.slice(bestStart, bestStart+minLen);
};

function longestUnequalAdjacentGroupsSubsequenceII(words, groups) {
    const n = words.length;
    function hamming(a, b) { let d = 0; for (let k = 0; k < a.length; k++) if (a[k] !== b[k]) d++; return d; }
    const dp = new Array(n).fill(1);
    const parent = new Array(n).fill(-1);
    let bestIdx = 0;
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < i; j++) {
            // must be a different group AND the words must be equal-length with Hamming distance exactly 1
            if (groups[j] !== groups[i] && words[j].length === words[i].length && hamming(words[j], words[i]) === 1) {
                if (dp[j] + 1 >= dp[i]) { dp[i] = dp[j] + 1; parent[i] = j; }
            }
        }
        if (dp[i] >= dp[bestIdx]) bestIdx = i;
    }
    const resIdx = [];
    let cur = bestIdx;
    while (cur !== -1) { resIdx.push(cur); cur = parent[cur]; }
    resIdx.reverse();
    return resIdx.map(i => words[i]);
}

function findIndices(nums, indexDifference, valueDifference) {
  const n = nums.length;
  let minIdx = 0, maxIdx = 0;
  for (let j = indexDifference; j < n; j++) {
    const i = j - indexDifference;
    if (nums[i] < nums[minIdx]) minIdx = i;
    if (nums[i] > nums[maxIdx]) maxIdx = i;
    if (Math.abs(nums[j] - nums[minIdx]) >= valueDifference) return [minIdx, j];
    if (Math.abs(nums[j] - nums[maxIdx]) >= valueDifference) return [maxIdx, j];
  }
  return [-1, -1];
}

function longestUnequalAdjacentGroupsSubsequenceI(words, groups) {
    const result = [];
    // MAIN LOGIC: add word i if result is empty or groups[i] differs from the last taken group
    for (let i = 0; i < groups.length; i++) {
        if (result.length === 0 || groups[i] !== groups[result.length - 1]) {
            result.push(words[i]);
        }
    }
    return result;
}

function minimumSumOfMountainTripletsI(nums) {
    const n = nums.length;
    if (n < 3) return -1;
    const INF = 1e18;

    const uniq = [...new Set(nums)].sort((a, b) => a - b);
    const comp = new Map(uniq.map((v, i) => [v, i + 1]));

    class FenwickMin {
        constructor(size) { this.n = size; this.bit = new Array(size + 1).fill(INF); }
        update(idx, value) { while (idx <= this.n) { if (value < this.bit[idx]) this.bit[idx] = value; idx += idx & -idx; } }
        query(idx) { let res = INF; while (idx > 0) { if (this.bit[idx] < res) res = this.bit[idx]; idx -= idx & -idx; } return res; }
    }

    const left = new Array(n).fill(INF);
    const ftLeft = new FenwickMin(uniq.length);
    for (let j = 0; j < n; j++) {
        const idx = comp.get(nums[j]);
        left[j] = ftLeft.query(idx - 1);
        ftLeft.update(idx, nums[j]);
    }

    const right = new Array(n).fill(INF);
    const ftRight = new FenwickMin(uniq.length);
    for (let j = n - 1; j >= 0; j--) {
        const idx = comp.get(nums[j]);
        right[j] = ftRight.query(idx - 1);
        ftRight.update(idx, nums[j]);
    }

    let ans = INF;
    for (let j = 0; j < n; j++) {
        if (left[j] !== INF && right[j] !== INF) {
            const total = left[j] + nums[j] + right[j];
            if (total < ans) ans = total;
        }
    }
    return ans === INF ? -1 : ans;
}

function constructProductMatrix(grid) {
    const MOD = 12345;
    const n = grid.length, m = grid[0].length;
    const p = Array.from({length: n}, () => new Array(m).fill(0));
    let suf = 1;
    for (let i = n - 1; i >= 0; i--) {
        for (let j = m - 1; j >= 0; j--) {
            p[i][j] = suf;
            suf = (suf * grid[i][j]) % MOD;
        }
    }
    let pre = 1;
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < m; j++) {
            p[i][j] = (p[i][j] * pre) % MOD;
            pre = (pre * grid[i][j]) % MOD;
        }
    }
    return p;
}

function minChanges(s, k) {
    const n = s.length;
    if (k >= n) return 0;                     // each character can be a piece

    // ---------- pre‑compute palindrome costs ----------
    const cost = Array.from({ length: n }, () => Array(n).fill(0));
    for (let len = 2; len <= n; ++len) {      // length of the substring
        for (let i = 0; i + len - 1 < n; ++i) {
            const j = i + len - 1;
            if (len === 2) {
                cost[i][j] = s[i] === s[j] ? 0 : 1;
            } else {
                cost[i][j] = cost[i + 1][j - 1] + (s[i] === s[j] ? 0 : 1);
            }
        }
    }

    // ---------- DP for k partitions ----------
    const INF = 1e9;
    let prev = new Array(n + 1).fill(INF);
    prev[0] = 0;
    // one partition (p = 1)
    for (let i = 1; i <= n; ++i) prev[i] = cost[0][i - 1];

    for (let p = 2; p <= k; ++p) {
        const cur = new Array(n + 1).fill(INF);
        // i = length of prefix we are filling
        for (let i = p; i <= n; ++i) {        // at least p chars for p pieces
            // try every possible split point t
            for (let t = p - 1; t < i; ++t) {
                const cand = prev[t] + cost[t][i - 1];
                if (cand < cur[i]) cur[i] = cand;   // keep the minimum
            }
        }
        prev = cur;
    }
    return prev[n];
}

function minChanges(s) {
    let changes = 0;
    for (let i = 0; i < s.length; i += 2) {
        // count mismatched pairs
        if (s[i] !== s[i + 1]) changes++;
    }
    return changes;
}

function subarrayDistinctElementSumSquares(nums) {
    const n = nums.length;
    let total = 0;
    for (let i = 0; i < n; i++) {
        const freq = new Map();
        let distinct = 0;
        for (let j = i; j < n; j++) {
            const val = nums[j];
            const cnt = freq.get(val) || 0;
            if (cnt === 0) distinct++;
            freq.set(val, cnt + 1);
            total += distinct * distinct;
        }
    }
    return total;
}

function sumCounts(nums) {
  const MOD = 1000000007n;
  const n = nums.length;
  let ans = 0n;
  for (let i = 0; i < n; i++) {
    const seen = new Set();
    let distinct = 0;
    for (let j = i; j < n; j++) {
      if (!seen.has(nums[j])) {
        seen.add(nums[j]);
        distinct++;
      }
      const sq = BigInt(distinct) * BigInt(distinct);
      ans = (ans + sq) % MOD;
    }
  }
  return Number(ans);
}

function maxNumberOfPairs(words) {
    const seen = new Set();
    let pairs = 0;
    for (const w of words) {
        const rev = w.split('').reverse().join('');
        if (rev !== w && seen.has(rev)) {
            pairs++;
            seen.delete(rev);
        } else {
            seen.add(w);
        }
    }
    return pairs;
}

function longestNewString(x, y, z) {
    // calculate the maximum possible length by adding the lengths of all strings
    let maxLength = 2 * x + 2 * y + 2 * z;
    // calculate the minimum number of strings to remove to avoid "AAA" or "BBB"
    let remove = Math.max(0, x - y - z) + Math.max(0, y - x - z);
    // subtract the length of the removed strings from the maximum length
    return maxLength - 2 * remove;
}

function cancellable(fn, args, t) {
    let id = null;
    let results = [];
    // Call the function immediately and store the result
    results.push({ time: 0, returned: fn(...args) });
    // Create an interval to call the function every t milliseconds
    id = setInterval(() => {
        // Call the function and store the result
        results.push({ time: results.length * t, returned: fn(...args) });
    }, t);
    // Return a function to cancel the interval
    return function cancelFn() {
        // Clear the interval
        clearInterval(id);
        // Return the results
        return results;
    }
}

function joinTwoArrays(arr1, arr2) {
  // Create a Map to store the merged objects with id as the key
  let map = new Map();
  // Iterate over arr1 and add its objects to the map
  for (let obj of arr1) {
    // Use the id as the key and the object as the value
    map.set(obj.id, obj);
  }
  // Iterate over arr2 and merge its objects with the existing objects in the map
  for (let obj of arr2) {
    // If the id already exists in the map, merge the properties
    if (map.has(obj.id)) {
      // Use the spread operator to merge the properties
      map.set(obj.id, { ...map.get(obj.id), ...obj });
    } else {
      // If the id does not exist, add the object to the map
      map.set(obj.id, obj);
    }
  }
  // Convert the map values to an array and sort it by id
  let result = Array.from(map.values()).sort((a, b) => a.id - b.id);
  return result;
}

function waysToSplit(nums) {
    const MOD = 1e9 + 7;
    const n = nums.length;
    let prefixSum = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) {
        prefixSum[i + 1] = prefixSum[i] + nums[i];
    }
    let dp = new Array(n).fill(0);
    // calculate the number of ways to split the array into good subarrays ending at each position
    for (let i = 0; i < n; i++) {
        // check if the subarray ending at the current position is good
        if (prefixSum[i + 1] - prefixSum[0] === 1) {
            dp[i] = 1;
        }
        for (let j = 0; j < i; j++) {
            // check if the subarray ending at the current position is good and the subarray before it is also good
            if (prefixSum[i + 1] - prefixSum[j + 1] === 1) {
                dp[i] = (dp[i] + dp[j]) % MOD;
            }
        }
    }
    // the number of ways to split the entire array into good subarrays is stored in the last position of dp
    return dp[n - 1];
}

function countZeroRequestServers(n, logs, x, queries) {
    logs = logs.slice().sort((a, b) => a[1] - b[1]);
    const qIdx = queries.map((q, i) => [q, i]).sort((a, b) => a[0] - b[0]);
    const freq = new Map();
    let active = 0;
    let l = 0, r = 0;
    const ans = new Array(queries.length);
    for (const [q, idx] of qIdx) {
        const L = q - x, R = q;
        while (r < logs.length && logs[r][1] <= R) {
            const id = logs[r][0];
            const c = (freq.get(id) || 0);
            if (c === 0) active++;
            freq.set(id, c + 1);
            r++;
        }
        while (l < r && logs[l][1] < L) {
            const id = logs[l][0];
            const c = freq.get(id) - 1;
            freq.set(id, c);
            if (c === 0) active--;
            l++;
        }
        ans[idx] = n - active;
    }
    return ans;
}

function findGoodSubset(grid) {
    // generate all possible subsets of rows
    let subsets = [];
    for (let i = 1; i < (1 << grid.length); i++) {
        let subset = [];
        for (let j = 0; j < grid.length; j++) {
            if ((i & (1 << j)) !== 0) {
                subset.push(j);
            }
        }
        subsets.push(subset);
    }

    // check each subset to see if it's good
    for (let subset of subsets) {
        let k = subset.length;
        let columnSums = new Array(grid[0].length).fill(0);
        for (let row of subset) {
            for (let j = 0; j < grid[0].length; j++) {
                columnSums[j] += grid[row][j];
            }
        }
        // check if the sum of each column is at most half of the length of the subset
        let isGood = true;
        for (let sum of columnSums) {
            if (sum > Math.floor(k / 2)) {
                isGood = false;
                break;
            }
        }
        if (isGood) {
            return subset;
        }
    }

    // if no good subset is found, return an empty array
    return [];
}

function gcd(a, b) {
  while (b !== 0) { [a, b] = [b, a % b]; }
  return a;
}

function countBeautifulPairs(nums) {
  let count = 0;
  for (let i = 0; i < nums.length; i++) {
    for (let j = i + 1; j < nums.length; j++) {
      let firstDigit = Math.floor(nums[i] / Math.pow(10, Math.floor(Math.log10(nums[i]))));
      let lastDigit = nums[j] % 10;
      if (gcd(firstDigit, lastDigit) == 1) {
        count++;
      }
    }
  }
  return count;
}

function robotCollisions(positions, healths, directions) {
    const n = positions.length;
    const idx = Array.from({length: n}, (_, i) => i);
    idx.sort((a, b) => positions[a] - positions[b]);
    const health = healths.slice();
    const stack = [];
    for (const i of idx) {
        if (directions[i] === 'R') {
            stack.push(i);
        } else {
            let alive = true;
            while (alive && stack.length > 0 && health[i] > 0) {
                const j = stack[stack.length - 1];
                if (health[j] > health[i]) {
                    health[j] -= 1;
                    health[i] = 0;
                    alive = false;
                } else if (health[j] < health[i]) {
                    health[i] -= 1;
                    health[j] = 0;
                    stack.pop();
                } else {
                    health[j] = 0;
                    health[i] = 0;
                    stack.pop();
                    alive = false;
                }
            }
        }
    }
    const result = [];
    for (let i = 0; i < n; i++) {
        if (health[i] > 0) result.push(health[i]);
    }
    return result;
}

function minOperations(num1, num2) {
    for (let k = 1; k <= 60; k++) {
        const target = num1 - k * num2;
        if (target < k) continue;
        let bits = 0n, t = BigInt(target);
        while (t > 0n) { bits += t & 1n; t >>= 1n; }
        if (bits <= BigInt(k)) return k;
    }
    return -1;
}

function longestSubsequenceSum(nums, target) {
    // dp maps a reachable sum to the longest length achieving it
    let dp = new Map();
    dp.set(0, 0);                     // empty subsequence

    for (let x of nums) {
        const next = new Map(dp);    // copy current states (skip x)

        // main logic: try to take x and update sums
        for (let [sum, len] of dp) {
            const newSum = sum + x;
            const newLen = len + 1;
            if (!next.has(newSum) || next.get(newSum) < newLen) {
                next.set(newSum, newLen);
            }
        }
        dp = next;                    // move to the next prefix
    }

    return dp.has(target) ? dp.get(target) : -1;
}

function kOr(nums, k) {
    let ans = 0;
    // count each bit position (0‑31) and set it if count ≥ k
    for (let b = 0; b < 32; b++) {
        const mask = 1 << b;
        let cnt = 0;
        for (let v of nums) {
            if (v & mask) cnt++;
            if (cnt >= k) break;          // early stop when threshold reached
        }
        if (cnt >= k) ans |= mask;
    }
    return ans >>> 0;   // ensure unsigned 32‑bit result
}

function countOfSubMultisetsWithBoundedSum(nums, l, r) {
    const MOD = 1000000007n;
    const zeroCnt = nums.filter(x => x === 0).length;
    const nonZero = nums.filter(x => x !== 0);
    const totalSum = nonZero.reduce((a, b) => a + b, 0);
    if (totalSum < l) return 0;
    const maxSum = Math.min(totalSum, r);

    let dp = new Array(maxSum + 1).fill(0n);
    dp[0] = 1n;

    const freq = new Map();
    for (const v of nonZero) freq.set(v, (freq.get(v) || 0) + 1);

    for (const [v, c] of freq) {
        const newDp = new Array(maxSum + 1).fill(0n);
        const step = v, limit = c;
        for (let rem = 0; rem < step; rem++) {
            let window = 0n, k = 0, idx = rem;
            while (idx <= maxSum) {
                window += dp[idx];
                if (k > limit) {
                    const subIdx = idx - (limit + 1) * step;
                    if (subIdx >= 0) window -= dp[subIdx];
                }
                window = ((window % MOD) + MOD) % MOD;
                newDp[idx] = window;
                k++;
                idx += step;
            }
        }
        dp = newDp;
    }

    let ans = 0n;
    if (l <= maxSum) {
        for (let i = l; i <= maxSum; i++) ans = (ans + dp[i]) % MOD;
    }
    if (zeroCnt) {
        const modpow = (base, exp, mod) => {
            base %= mod; let result = 1n;
            while (exp > 0n) { if (exp & 1n) result = (result * base) % mod; base = (base * base) % mod; exp >>= 1n; }
            return result;
        };
        ans = (ans * modpow(2n, BigInt(zeroCnt), MOD)) % MOD;
    }
    return Number(ans);
}

function findIndices(nums, indexDifference, valueDifference) {
    const n = nums.length;
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if (Math.abs(i-j) >= indexDifference && Math.abs(nums[i]-nums[j]) >= valueDifference) return [i, j];
        }
    }
    return [-1, -1];
}

function minimumSumOfMountainTripletsII(nums) {
    const n = nums.length;
    if (n < 3) return -1;
    const INF = Infinity;

    const leftMin = new Array(n).fill(INF);
    let cur = INF;
    for (let i = 1; i < n; i++) {
        cur = Math.min(cur, nums[i - 1]);
        leftMin[i] = cur;
    }

    const rightMin = new Array(n).fill(INF);
    cur = INF;
    for (let i = n - 2; i >= 0; i--) {
        cur = Math.min(cur, nums[i + 1]);
        rightMin[i] = cur;
    }

    let ans = INF;
    for (let j = 1; j < n - 1; j++) {
        if (leftMin[j] < nums[j] && rightMin[j] < nums[j]) {
            const total = leftMin[j] + nums[j] + rightMin[j];
            if (total < ans) ans = total;
        }
    }
    return ans === INF ? -1 : ans;
}

function minBoxes(balls) {
    const freqMap = new Map();
    let total = 0;
    for (const x of balls) {
        total++;
        freqMap.set(x, (freqMap.get(x) || 0) + 1);
    }
    const freqs = Array.from(freqMap.values());
    let low = 1, high = total, ans = total;
    while (low <= high) {
        const mid = (low + high) >> 1;
        const s = Math.floor(total / mid);
        if (s === 0) {
            low = mid + 1;
            continue;
        }
        let minSum = 0, maxSum = 0;
        let possible = true;
        for (const f of freqs) {
            const minK = Math.floor((f + (s + 1) - 1) / (s + 1));
            const maxK = Math.floor(f / s);
            if (minK > maxK) {
                possible = false;
                break;
            }
            minSum += minK;
            maxSum += maxK;
            if (minSum > mid) break;
        }
        if (!possible || minSum > mid) {
            low = mid + 1;
        } else if (maxSum < mid) {
            high = mid - 1;
        } else {
            ans = mid;
            high = mid - 1;
        }
    }
    return ans;
}

function findChampion(n, edges) {
    // Create an adjacency list to represent the graph
    let graph = Array.from({ length: n }, () => []);
    let inDegree = Array(n).fill(0);

    // Populate the adjacency list and calculate the in-degree of each node
    for (let [u, v] of edges) {
        // A directed edge from u to v means v is weaker than u
        graph[u].push(v);
        inDegree[v]++;
    }

    // Find all nodes with an in-degree of 0, these are the potential champions
    let champions = inDegree.reduce((acc, degree, index) => degree === 0 ? [...acc, index] : acc, []);

    // If there is exactly one champion, return it
    return champions.length === 1 ? champions[0] : -1;
}

function findChampion(grid) {
  let champion = 0; 
  // Loop through each team to find the champion
  for (let i = 1; i < grid.length; i++) {
    let isChampionStronger = true;
    // Check if the current champion is stronger than the current team
    for (let j = 0; j < grid.length; j++) {
      // If the current team is stronger than the current champion, update the champion
      if (grid[i][j] === 1 && grid[champion][j] === 0) {
        isChampionStronger = false;
        break;
      }
    }
    // If the current champion is not stronger than the current team, update the champion
    if (!isChampionStronger) {
      champion = i;
    }
  }
  return champion;
}

function makeArrayBeautiful(nums, k) {
    const n = nums.length;
    // it suffices to ensure every window of EXACTLY size 3 has an element raised to >= k
    // (any larger window automatically satisfies the condition once its size-3 sub-windows do)
    const cost = nums.map(v => Math.max(0, k - v));
    const dp = new Array(n).fill(0);
    const at = (i) => (i < 0 ? 0 : dp[i]);
    for (let i = 0; i < n; i++) {
        // dp[i] = cost to force position i up to k, given the nearest previously-forced
        // position is at i-1, i-2, or i-3 (any farther back would leave 3 unforced in a row)
        dp[i] = cost[i] + Math.min(at(i - 1), at(i - 2), at(i - 3));
    }
    return Math.min(at(n - 1), at(n - 2), at(n - 3));
}

function minimumSum(nums1, nums2) {
    let sum1 = 0, sum2 = 0, zeros1 = 0, zeros2 = 0;
    for (const v of nums1) { if (v === 0) zeros1++; else sum1 += v; }
    for (const v of nums2) { if (v === 0) zeros2++; else sum2 += v; }
    if (zeros1 === 0 && zeros2 === 0) return sum1 === sum2 ? sum1 : -1;
    if (zeros1 === 0) return sum1 >= sum2 + zeros2 ? sum1 : -1;
    if (zeros2 === 0) return sum2 >= sum1 + zeros1 ? sum2 : -1;
    return Math.max(sum1 + zeros1, sum2 + zeros2);
}

function maxScore(edges, values) {
    const n = values.length;
    const graph = Array.from({ length: n }, () => []);
    for (const [a, b] of edges) { graph[a].push(b); graph[b].push(a); }
    let total = 0;
    for (const v of values) total += v;
    function dfs(node, parent) {
        let sumChildren = 0, childrenCount = 0;
        for (const child of graph[node]) {
            if (child !== parent) { sumChildren += dfs(child, node); childrenCount++; }
        }
        if (childrenCount === 0) return values[node];
        return Math.min(values[node], sumChildren);
    }
    const minKeep = dfs(0, -1);
    return total - minKeep;
}

function maxPoints(edges, coins, k) {
    const n = coins.length;
    const tree = Array.from({length:n},()=>[]);
    for (const [u,v] of edges) { tree[u].push(v); tree[v].push(u); }
    const CAP = 14;
    const memo = Array.from({length:n},()=>new Array(CAP+1).fill(-1));

    function dfs(node, parent, halvings) {
        const h = Math.min(halvings, CAP);
        if (memo[node][h] !== -1) return memo[node][h];

        const baseVal = coins[node] >> h;
        let way1 = baseVal - k;
        let way2 = Math.floor(baseVal / 2);
        for (const child of tree[node]) {
            if (child === parent) continue;
            way1 += dfs(child, node, h);
            way2 += dfs(child, node, Math.min(h + 1, CAP));
        }
        const result = Math.max(way1, way2);
        memo[node][h] = result;
        return result;
    }

    return dfs(0, -1, 0);
}

function distributeCandies(n, limit) {
  let count = 0;
  // iterate over all possible combinations of candies for the first child
  for (let a = 0; a <= Math.min(n, limit); a++) {
    // iterate over all possible combinations of candies for the second child
    for (let b = 0; b <= Math.min(n - a, limit); b++) {
      // calculate the number of candies for the third child
      let c = n - a - b;
      // check if the third child gets more than the limit candies
      if (c >= 0 && c <= limit) {
        // increment the count if the combination is valid
        count++;
      }
    }
  }
  return count;
}

