var maxBalancedSubsequenceSum = function(nums) {
    if (!nums.length) return 0;
    const n = nums.length;
    const dp = new Array(n).fill(0);
    let maxSum = -Infinity;
    for (let i=0;i<n;i++) {
        dp[i] = nums[i];
        for (let j=0;j<i;j++) {
            if (nums[i]-nums[j] >= i-j) {
                dp[i] = Math.max(dp[i], dp[j]+nums[i]);
            }
        }
        maxSum = Math.max(maxSum, dp[i]);
    }
    return maxSum;
};

function numberOfGoodStrings(n) {
    const MOD = 1000000007n;
    function modpow(base, exp) {
        base = BigInt(base) % MOD;
        let result = 1n;
        let e = BigInt(exp);
        while (e > 0n) { if (e & 1n) result = (result * base) % MOD; base = (base * base) % MOD; e >>= 1n; }
        return result;
    }
    const N = BigInt(n);
    const total = modpow(26, n);
    const p25n = modpow(25, n), p25n1 = modpow(25, n - 1);
    const p24n = modpow(24, n), p24n1 = modpow(24, n - 1);
    const p23n = modpow(23, n), p23n1 = modpow(23, n - 1);
    const sumSingles = (3n * p25n + N * p25n1) % MOD;
    const sumPairwise = (3n * p24n + 2n * N * p24n1) % MOD;
    const triple = (p23n + N * p23n1) % MOD;
    let bad = ((sumSingles - sumPairwise + triple) % MOD + MOD) % MOD;
    let good = ((total - bad) % MOD + MOD) % MOD;
    return Number(good);
}

function maximumSpending(values) {
  const m = values.length;
  const n = values[0].length;
  // Every item across every shop is eventually bought, and since each row is
  // consumed smallest-first (rows are sorted non-increasing, so the smallest
  // is at the end), the achievable set of (value, day) pairings is exactly
  // "flatten all values, sort ascending" — by the rearrangement inequality the
  // sum of value*day is maximized by pairing the largest values with the
  // largest day numbers, i.e. sorting ascending and multiplying by 1..m*n.
  const flat = [];
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) flat.push(values[i][j]);
  }
  flat.sort((a, b) => a - b);
  let totalSpending = 0;
  for (let day = 1; day <= flat.length; day++) {
    totalSpending += flat[day - 1] * day;
  }
  return totalSpending;
}

function highAccessEmployees(access_times) {
    const empMap = new Map();                     // employee → list of minutes

    // build the map
    for (let i = 0; i < access_times.length; i++) {
        const [name, t] = access_times[i];
        const minutes = parseInt(t.slice(0, 2), 10) * 60 + parseInt(t.slice(2), 10);
        if (!empMap.has(name)) empMap.set(name, []);
        empMap.get(name).push(minutes);
    }

    const qualified = [];

    // check each employee
    for (const [name, times] of empMap) {
        times.sort((a, b) => a - b);               // O(k log k)

        // sliding window to find 3 accesses within 60 minutes
        let left = 0;
        for (let right = 0; right < times.length; right++) {
            while (times[right] - times[left] > 60) left++;   // shrink window
            if (right - left + 1 >= 3) {                      // window size ≥ 3
                qualified.push(name);
                break;                                        // no need to check further
            }
        }
    }

    qualified.sort();                               // lexicographic order
    return qualified;
}

function minOperationsToMakeIncreasing(nums1, nums2) {
    const n = nums1.length;

    const tryCase = (end1, end2) => {
        let ops = 0;
        for (let i = 0; i < n - 1; i++) {
            const a = nums1[i], b = nums2[i];
            const noSwapOk = a <= end1 && b <= end2;
            const swapOk = b <= end1 && a <= end2;
            if (noSwapOk && swapOk) continue;
            else if (noSwapOk) continue;
            else if (swapOk) ops++;
            else return -1;
        }
        return ops;
    };

    const n1 = nums1[n - 1], n2 = nums2[n - 1];
    const case1 = tryCase(n1, n2); // no swap at last index
    const case2 = tryCase(n2, n1); // swap at last index

    let best = Infinity;
    if (case1 !== -1) best = Math.min(best, case1);
    if (case2 !== -1) best = Math.min(best, case2 + 1);

    return best === Infinity ? -1 : best;
}

function findWordsContainingCharacter(words, x) {
