    return result;
  }, []);
}

function maxStrongPairXor(nums) {
  const MAX_BIT = 20;
  nums.sort((a, b) => a - b);
  const trie = [{ next: [-1, -1], cnt: 0 }];

  function insert(num) {
    let node = 0;
    for (let b = MAX_BIT; b >= 0; b--) {
      const bit = (num >> b) & 1;
      let child = trie[node].next[bit];
      if (child === -1) {
        child = trie.length;
        trie[node].next[bit] = child;
        trie.push({ next: [-1, -1], cnt: 0 });
      }
      node = child;
      trie[node].cnt++;
    }
  }

  function remove(num) {
    let node = 0;
    for (let b = MAX_BIT; b >= 0; b--) {
      const bit = (num >> b) & 1;
      node = trie[node].next[bit];
      trie[node].cnt--;
    }
  }

  function query(num) {
    let node = 0;
    let xor = 0;
    for (let b = MAX_BIT; b >= 0; b--) {
      const bit = (num >> b) & 1;
      const desired = bit ^ 1;
      const child = trie[node].next[desired];
      if (child !== -1 && trie[child].cnt > 0) {
        xor |= (1 << b);
        node = child;
      } else {
        node = trie[node].next[bit];
      }
    }
    return xor;
  }

  let left = 0;
  let ans = 0;
  for (let j = 0; j < nums.length; j++) {
    insert(nums[j]);
    const limit = (nums[j] + 1) >> 1;
    while (left <= j && nums[left] < limit) {
      remove(nums[left]);
      left++;
    }
    const cur = query(nums[j]);
    if (cur > ans) ans = cur;
  }
  return ans;
}

function maximumStrongPairXor(nums) {
    const arr = nums.slice().sort((a, b) => a - b);
    const MAX_BIT = 31;
    const root = { child: [null, null], cnt: 0 };
    function insert(val) {
        let node = root;
        node.cnt++;
        for (let b = MAX_BIT; b >= 0; b--) {
            const bit = (val >> b) & 1;
            if (!node.child[bit]) node.child[bit] = { child: [null, null], cnt: 0 };
            node = node.child[bit];
            node.cnt++;
        }
    }
    function remove(val) {
        let node = root;
        node.cnt--;
        for (let b = MAX_BIT; b >= 0; b--) {
            const bit = (val >> b) & 1;
            const nxt = node.child[bit];
            nxt.cnt--;
            if (nxt.cnt === 0) node.child[bit] = null;
            node = nxt;
            if (!node) break;
        }
    }
    function query(val) {
        let node = root;
        let xor = 0;
        for (let b = MAX_BIT; b >= 0; b--) {
            const bit = (val >> b) & 1;
            const prefer = bit ^ 1;
            if (node.child[prefer] && node.child[prefer].cnt > 0) {
                xor |= (1 << b);
                node = node.child[prefer];
            } else {
                node = node.child[bit];
            }
        }
        return xor;
    }
    let left = 0;
    let ans = 0;
    for (let right = 0; right < arr.length; right++) {
        while (left < right && arr[right] > 2 * arr[left]) {
            remove(arr[left]);
            left++;
        }
        if (root.cnt > 0) {
            const cand = query(arr[right]);
            if (cand > ans) ans = cand;
        }
        insert(arr[right]);
    }
    return ans;
}

function minCoins(prices) {
    const n = prices.length;
    const dp = new Array(n + 1).fill(Infinity);
    dp[0] = 0;
    for (let i = 1; i <= n; i++) {
        const lo = Math.ceil(i / 2);
        for (let j = lo; j <= i; j++) {
            const cost = dp[j - 1] + prices[j - 1];
            if (cost < dp[i]) dp[i] = cost;
        }
    }
    return dp[n];
}

function maximumXorProduct(a, b, n) {
    // Initialize the maximum product
    let maxProduct = 0;
    // Iterate over all possible values of x
    for (let x = 0; x < (1 << n); x++) {
        // Calculate the product of (a XOR x) and (b XOR x)
        let product = (a ^ x) * (b ^ x);
        // Update the maximum product if the current product is larger
        maxProduct = Math.max(maxProduct, product);
    }
    // Return the maximum product
    return maxProduct;
}

