function maxAreaOfSquareHole(n, m, hBars, vBars) {
    function longestRun(arr) {
        arr = arr.slice().sort((a, b) => a - b);
        let best = 1, cur = 1;
        for (let i = 1; i < arr.length; i++) {
            if (arr[i] === arr[i - 1] + 1) cur++; else cur = 1;
            best = Math.max(best, cur);
        }
        return best;
    }
    const height = longestRun(hBars) + 1;
    const width = longestRun(vBars) + 1;
