}

function findMeetingBuilding(heights, queries) {
    const result = [];
    for (let [alice, bob] of queries) {
        let a = Math.min(alice, bob), b = Math.max(alice, bob);
        if (a === b) { result.push(a); continue; }
        if (heights[b] > heights[a]) { result.push(b); continue; }
        let ans = -1;
        for (let i = b + 1; i < heights.length; i++) {
            if (heights[i] > heights[a] && heights[i] > heights[b]) { ans = i; break; }
        }
        result.push(ans);
    }
    return result;
}

function findMaximumNonDecreasingArrayLength(nums) {
    const n = nums.length;
    const prefix = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];

    function lowerBound(arr, target) {
        let lo = 0, hi = arr.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (arr[mid] >= target) hi = mid; else lo = mid + 1;
        }
        return lo;
    }

    const dp = new Array(n + 1).fill(0);
    const bestStart = new Array(n + 2).fill(0);

    for (let i = 1; i <= n; i++) {
        bestStart[i] = Math.max(bestStart[i], bestStart[i - 1]);
        dp[i] = dp[bestStart[i]] + 1;
        const segSum = prefix[i] - prefix[bestStart[i]];
        const target = prefix[i] + segSum;
        const nxt = lowerBound(prefix, target);
        bestStart[nxt] = i;
    }
    return dp[n];
}

function findRotation(mat, k) {
    const L = mat[0].length;
    // a length-L cyclic shift repeats every L shifts, not 2*(L-1)
    k = k % L;
    let originalMat = mat.map(row => row.slice());
    for (let i = 0; i < k; i++) {
        for (let j = 0; j < mat.length; j++) {
            if (j % 2 === 0) {
                mat[j].unshift(mat[j].pop());
            } else {
                mat[j].push(mat[j].shift());
            }
        }
    }
    for (let i = 0; i < mat.length; i++) {
        for (let j = 0; j < mat[0].length; j++) {
            if (mat[i][j] !== originalMat[i][j]) return false;
        }
    }
    return true;
}

function makeThreeStringsEqual(s1, s2, s3) {
    // find longest common prefix length among the three strings
    let i = 0;
    const limit = Math.min(s1.length, s2.length, s3.length);
    while (i < limit && s1[i] === s2[i] && s1[i] === s3[i]) i++;

    if (i === 0) return -1;                     // no common prefix → impossible
    return (s1.length - i) + (s2.length - i) + (s3.length - i);
}



