function smallestArray(nums, limit) {
    const n = nums.length;
    const idx = [...Array(n).keys()].sort((a, b) => nums[a] - nums[b]);
    const result = new Array(n);
    let i = 0;
    while (i < n) {
        let j = i;
        // extend the group while consecutive sorted values stay within `limit` of each other
        while (j + 1 < n && nums[idx[j + 1]] - nums[idx[j]] <= limit) j++;
        // within a group, only the ORIGINAL positions get reordered - assign sorted values
        // to the group's original indices in increasing order of index
        const groupOrigIndices = idx.slice(i, j + 1).sort((a, b) => a - b);
        for (let k = 0; k < groupOrigIndices.length; k++) result[groupOrigIndices[k]] = nums[idx[i + k]];
        i = j + 1;
    }
    return result;
}

