    while (i < n) {
        if (Math.abs(word.charCodeAt(i) - word.charCodeAt(i - 1)) <= 1) {
            ops++;
            i += 2;
        } else {
            i += 1;
        }
    }
    return ops;
}

var numberOfSequence = function(n, sick) {
    const MOD = 1000000007;
    sick = sick.slice().sort((a,b)=>a-b);
    const totalUninfected = n - sick.length;
    const fact = new Array(n+1).fill(1);
    for (let i=1;i<=n;i++) fact[i] = Number((BigInt(fact[i-1])*BigInt(i))%BigInt(MOD));
    function modpow(base, exp, mod) {
        let b=BigInt(base)%BigInt(mod), e=BigInt(exp), m=BigInt(mod), r=1n;
        while (e>0n) { if (e&1n) r=(r*b)%m; e>>=1n; b=(b*b)%m; }
        return Number(r);
    }
    const invFact = new Array(n+1).fill(1);
    invFact[n] = modpow(fact[n], MOD-2, MOD);
    for (let i=n;i>=1;i--) invFact[i-1] = Number((BigInt(invFact[i])*BigInt(i))%BigInt(MOD));
    let result = fact[totalUninfected];
    const leftGap = sick.length ? sick[0] : n;
    result = Number((BigInt(result)*BigInt(invFact[leftGap]))%BigInt(MOD));
    const rightGap = sick.length ? (n-1-sick[sick.length-1]) : 0;
    result = Number((BigInt(result)*BigInt(invFact[rightGap]))%BigInt(MOD));
    for (let i=1;i<sick.length;i++) {
        const gap = sick[i]-sick[i-1]-1;
        if (gap > 0) {
            result = Number((BigInt(result)*BigInt(invFact[gap]))%BigInt(MOD));
            result = Number((BigInt(result)*BigInt(modpow(2,gap-1,MOD)))%BigInt(MOD));
        }
    }
    return result;
};

function longestSubarray(nums, k) {
    let maxLength = 0;
    let frequencyMap = {};
    let left = 0;
    // slide the window to the right and update frequency map
    for (let right = 0; right < nums.length; right++) {
        frequencyMap[nums[right]] = (frequencyMap[nums[right]] || 0) + 1;
        // if any frequency exceeds k, slide the window to the left
        while (Object.values(frequencyMap).some(frequency => frequency > k)) {
            frequencyMap[nums[left]]--;
            if (frequencyMap[nums[left]] === 0) {
                delete frequencyMap[nums[left]];
            }
            left++;
        }
        // update max length
        maxLength = Math.max(maxLength, right - left + 1);
    }
    return maxLength;
}

function findErrorNums(grid) {
  var n = grid.length;
  var count = new Array(n * n + 1).fill(0);
  // Count the occurrence of each number in the grid
  for (var i = 0; i < n; i++) {
    for (var j = 0; j < n; j++) {
      count[grid[i][j]]++;
    }
  }
  var a = 0, b = 0;
  // Find the repeating and missing numbers
  for (var i = 1; i <= n * n; i++) {
    if (count[i] === 0) b = i;
    else if (count[i] === 2) a = i;
  }
  return [a, b];
}

function findGoodIndices(variables, target) {
    // Initialize an empty array to store good indices
    var goodIndices = [];
    // Iterate over each variable in the variables array
    for (var i = 0; i < variables.length; i++) {
        // Extract the values from the current variable
        var a = variables[i][0];
        var b = variables[i][1];
        var c = variables[i][2];
        var m = variables[i][3];
        // Calculate the result of the formula
        var result = Math.pow((Math.pow(a, b) % 10), c) % m;
        // Check if the result equals the target
        if (result === target) {
            // If it does, add the current index to the goodIndices array
            goodIndices.push(i);
        }
    }
    // Return the array of good indices
    return goodIndices;
}

function countTestedDevices(batteryPercentages) {
    let testedDevices = 0; // count of tested devices
    for (let i = 0; i < batteryPercentages.length; i++) { // iterate through each device
        if (batteryPercentages[i] > 0) { // if the device has battery percentage greater than 0
            testedDevices++; // increment the count of tested devices
            for (let j = i + 1; j < batteryPercentages.length; j++) { // reset the battery percentages of the next devices
                batteryPercentages[j]--; // decrement the battery percentage of the next device
                if (batteryPercentages[j] < 0) { // if the battery percentage is less than 0
                    batteryPercentages[j] = 0; // set it to 0
                }
            }
        }
    }
    return testedDevices; // return the count of tested devices
}

function numberOfSubarrays(nums, k) {
    const maxVal = Math.max(...nums);
    const positions = [];
    let total = 0n;
    // for each right endpoint, once we've seen >= k occurrences of maxVal, every left
    // boundary from 0 up through the k-th-most-recent occurrence keeps the count >= k
    for (let right = 0; right < nums.length; right++) {
        if (nums[right] === maxVal) positions.push(right);
        if (positions.length >= k) {
            total += BigInt(positions[positions.length - k] + 1);
        }
    }
    return Number(total);
}

function countGoodPartitions(nums) {
    const MOD = 1000000007n;
    const n = nums.length;
    const lastIndex = new Map();
    for (let i = 0; i < n; i++) lastIndex.set(nums[i], i);

    // Merge overlapping [firstOcc, lastOcc] ranges by sweeping left to right,
    // extending the current block's end whenever a value's last occurrence goes further.
    let blocks = 0;
    let i = 0;
    while (i < n) {
        let end = lastIndex.get(nums[i]);
        let j = i;
        while (j < end) {
            j++;
            if (lastIndex.get(nums[j]) > end) end = lastIndex.get(nums[j]);
        }
        blocks++;
        i = end + 1;
    }

    let ans = 1n;
    for (let k = 0; k < blocks - 1; k++) ans = (ans * 2n) % MOD;
    return Number(ans);
}

function numberOfSets(n, maxDistance, roads) {
  let count = 0;
  for (let mask = 0; mask < (1 << n); mask++) {
    const dist = Array.from({length:n}, () => Array(n).fill(Infinity));
    for (let i = 0; i < n; i++) if (mask & (1 << i)) dist[i][i] = 0;
    for (const [u, v, w] of roads) {
      if ((mask & (1 << u)) && (mask & (1 << v))) {
        if (w < dist[u][v]) { dist[u][v] = w; dist[v][u] = w; }
      }
    }
    for (let k = 0; k < n; k++) {
      if (!(mask & (1 << k))) continue;
      for (let i = 0; i < n; i++) {
        if (!(mask & (1 << i))) continue;
        for (let j = 0; j < n; j++) {
          if (!(mask & (1 << j))) continue;
          if (dist[i][k] + dist[k][j] < dist[i][j]) dist[i][j] = dist[i][k] + dist[k][j];
        }
      }
    }
    let valid = true;
    outer:
    for (let i = 0; i < n; i++) {
      if (!(mask & (1 << i))) continue;
      for (let j = 0; j < n; j++) {
        if (!(mask & (1 << j))) continue;
        if (dist[i][j] > maxDistance) { valid = false; break outer; }
      }
    }
    if (valid) count++;
  }
  return count;
}

function numberOfSubarrays(nums) {
