        }
    }
    return true;
}

function minCostToMakeEqualindromic(nums) {
    function isPalindrome(x) {
        const s = String(x);
        return s === s.split('').reverse().join('');
    }
    const sorted = nums.slice().sort((a, b) => a - b);
    const n = sorted.length;
    const median = sorted[Math.floor((n - 1) / 2)];
    function cost(y) { let c = 0n; for (const num of nums) c += BigInt(Math.abs(num - y)); return c; }
    let down = median;
    while (!isPalindrome(down)) down--;
    let up = median;
    while (!isPalindrome(up)) up++;
    const c1 = cost(down), c2 = cost(up);
    return Number(c1 < c2 ? c1 : c2);
}

function maxFrequencyScore(nums, k) {
    nums.sort((a, b) => a - b);
    const n = nums.length;
    const prefix = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];

    function cost(left, right) {
        const mid = (left + right) >> 1;
        const leftCost = nums[mid] * (mid - left + 1) - (prefix[mid + 1] - prefix[left]);
        const rightCost = (prefix[right + 1] - prefix[mid + 1]) - nums[mid] * (right - mid);
        return leftCost + rightCost;
    }

    let left = 0, maxScore = 0;
    for (let right = 0; right < n; right++) {
        while (cost(left, right) > k) left++;
        maxScore = Math.max(maxScore, right - left + 1);
    }
    return maxScore;
}

function largestPerimeter(nums) {
    nums = nums.slice().sort((a, b) => a - b);
    const n = nums.length;
    const prefix = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];
    for (let i = n - 1; i >= 2; i--) {
        if (nums[i] < prefix[i]) return prefix[i] + nums[i];
    }
    return -1;
}

function minimumNumberGame(nums) {
