}

var placedCoins = function(edges, cost) {
    const n = cost.length;
    const graph = Array.from({length:n}, () => []);
    for (const [a,b] of edges) { graph[a].push(b); graph[b].push(a); }
    const result = new Array(n).fill(0);
    function dfs(node, parent) {
        let topVals = [cost[node]];
        for (const nxt of graph[node]) {
            if (nxt === parent) continue;
            const childTop = dfs(nxt, node);
            topVals = topVals.concat(childTop);
        }
        topVals.sort((a,b)=>b-a);
        if (topVals.length > 3) topVals = topVals.slice(0,3);
        if (topVals.length < 3) result[node] = 1;
        else {
            const prod = topVals[0]*topVals[1]*topVals[2];
            result[node] = prod > 0 ? prod : 0;
        }
        return topVals;
    }
    dfs(0, -1);
    return result;
};

function numberOfSubarrays(nums) {
    let count = 0;
