            // check if the subarray is incremovable
            let isIncreasing = true;
            for (let k = 0; k < temp.length - 1; k++) {
                if (temp[k] >= temp[k + 1]) {
                    isIncreasing = false;
                    break;
                }
            }
            if (isIncreasing) {
                count++;
            }
        }
    }
    return count;
}

function maxSquareArea(m, n, hFences, vFences) {
    const MOD = 1000000007n;
    const fullH = [1, ...hFences, m].sort((a, b) => a - b);
    const fullV = [1, ...vFences, n].sort((a, b) => a - b);
    const setH = new Set();
    for (let i = 0; i < fullH.length; i++) for (let j = i + 1; j < fullH.length; j++) setH.add(fullH[j] - fullH[i]);
    let best = -1n;
    for (let i = 0; i < fullV.length; i++) for (let j = i + 1; j < fullV.length; j++) {
        const d = fullV[j] - fullV[i];
        if (setH.has(d)) {
            const area = (BigInt(d) * BigInt(d)) % MOD;
            if (best === -1n || area > best) best = area;
        }
    }
    return best === -1n ? -1 : Number(best);
}

function minimumCost(source, target, original, changed, cost) {
    const nodeId = new Map();
    function getId(s) {
        if (!nodeId.has(s)) nodeId.set(s, nodeId.size);
        return nodeId.get(s);
    }
    const edgesU = [], edgesV = [], edgesW = [];
    for (let i = 0; i < original.length; i++) {
        edgesU.push(getId(original[i]));
        edgesV.push(getId(changed[i]));
        edgesW.push(cost[i]);
    }
    const V = nodeId.size;
    const INF = Infinity;
    const dist = Array.from({ length: V }, () => new Array(V).fill(INF));
    for (let i = 0; i < V; i++) dist[i][i] = 0;
    for (let i = 0; i < edgesU.length; i++) {
        const u = edgesU[i], v = edgesV[i], w = edgesW[i];
        if (w < dist[u][v]) dist[u][v] = w;
    }
    for (let k = 0; k < V; k++) {
        const dk = dist[k];
        for (let i = 0; i < V; i++) {
            const dik = dist[i][k];
            if (dik === INF) continue;
            const di = dist[i];
            for (let j = 0; j < V; j++) {
                const cand = dik + dk[j];
                if (cand < di[j]) di[j] = cand;
            }
        }
    }

    const lengths = [...new Set(original.map(s => s.length))].sort((a, b) => a - b);
    const n = source.length;
    const dp = new Array(n + 1).fill(INF);
    dp[0] = 0;
    for (let i = 0; i < n; i++) {
        if (dp[i] === INF) continue;
        if (source[i] === target[i]) {
            if (dp[i] < dp[i + 1]) dp[i + 1] = dp[i];
        }
        for (const L of lengths) {
            if (i + L > n) continue;
            const subS = source.substr(i, L);
            const subT = target.substr(i, L);
            const uid = nodeId.get(subS);
            if (uid === undefined) continue;
            const vid = nodeId.get(subT);
            if (vid === undefined) continue;
            const w = dist[uid][vid];
            if (w === INF) continue;
            const cand = dp[i] + w;
            if (cand < dp[i + L]) dp[i + L] = cand;
        }
    }
    return dp[n] === INF ? -1 : dp[n];
}

function minimumCost(source, target, original, changed, cost) {
    const INF = Infinity;
    const dist = Array.from({ length: 26 }, () => new Array(26).fill(INF));
    for (let i = 0; i < 26; i++) dist[i][i] = 0;
    for (let i = 0; i < original.length; i++) {
        const a = original[i].charCodeAt(0) - 97, b = changed[i].charCodeAt(0) - 97;
        dist[a][b] = Math.min(dist[a][b], cost[i]);
    }
    for (let k = 0; k < 26; k++) for (let i = 0; i < 26; i++) for (let j = 0; j < 26; j++) {
        if (dist[i][k] + dist[k][j] < dist[i][j]) dist[i][j] = dist[i][k] + dist[k][j];
    }
    let total = 0;
    for (let i = 0; i < source.length; i++) {
        const a = source.charCodeAt(i) - 97, b = target.charCodeAt(i) - 97;
        if (dist[a][b] === INF) return -1;
        total += dist[a][b];
    }
    return total;
}

function longestSpecialSubstring(s) {
    let maxLength = -1;
    // Create a hashmap to store the frequency of each special substring
    let frequencyMap = {};
    for (let i = 0; i < s.length; i++) {
        for (let j = i + 1; j <= s.length; j++) {
            let substring = s.substring(i, j);
            // Check if the substring is special
            if (isSpecial(substring)) {
                // Increment the frequency of the special substring
                frequencyMap[substring] = (frequencyMap[substring] || 0) + 1;
                // Update the maximum length if the frequency is at least 3
                if (frequencyMap[substring] >= 3) {
                    maxLength = Math.max(maxLength, substring.length);
                }
            }
        }
    }
    return maxLength;
}

// Helper function to check if a string is special
function isSpecial(s) {
    // Check if all characters in the string are the same
    return s.split('').every(c => c === s[0]);
}

function longestSpecialSubstring(s) {
    let maxLength = -1;
    function isSpecial(str) { return str.split('').every(c => c === str[0]); }
    function countOccurrences(str, sub) {
        // must count OVERLAPPING occurrences (every starting index), not regex's
        // non-overlapping global matches
        let count = 0;
        for (let i = 0; i + sub.length <= str.length; i++) {
            if (str.substr(i, sub.length) === sub) count++;
        }
        return count;
    }
    for (let i = 0; i < s.length; i++) {
        for (let j = i + 1; j <= s.length; j++) {
            const substring = s.substring(i, j);
            if (isSpecial(substring)) {
                const count = countOccurrences(s, substring);
                if (count >= 3 && substring.length > maxLength) maxLength = substring.length;
            }
        }
    }
    return maxLength;
}

function canMakePalindrome(s, queries) {
  const n = s.length;

  function getMirroredDiffs(s) {
    const diffs = [0];
    let i = 0, j = s.length - 1;
    while (i < j) {
      diffs.push(diffs[diffs.length - 1] + (s[i] !== s[j] ? 1 : 0));
      i++; j--;
    }
    return diffs;
  }

  function getCounts(s) {
    const count = new Array(26).fill(0);
    const counts = [count.slice()];
    for (const ch of s) {
      count[ch.charCodeAt(0) - 97]++;
      counts.push(count.slice());
    }
    return counts;
  }

  function subtractArrays(a, b) {
    const res = new Array(a.length);
    for (let i = 0; i < a.length; i++) res[i] = a[i] - b[i];
    return res;
  }

  const mirroredDiffs = getMirroredDiffs(s);
  const counts = getCounts(s);
  const ans = [];

  for (const [a0, b0, c0, d0] of queries) {
    const a = a0, b = b0 + 1, c = c0, d = d0 + 1;
    const ra = n - a, rb = n - b, rc = n - c, rd = n - d;

    if (
      (Math.min(a, rd) > 0 && mirroredDiffs[Math.min(a, rd)] > 0) ||
      (Math.floor(n / 2) > Math.max(b, rc) && mirroredDiffs[Math.floor(n / 2)] - mirroredDiffs[Math.max(b, rc)] > 0) ||
      (rd > b && mirroredDiffs[rd] - mirroredDiffs[b] > 0) ||
      (a > rc && mirroredDiffs[a] - mirroredDiffs[rc] > 0)
    ) {
      ans.push(false);
      continue;
    }

    let leftRangeCount = subtractArrays(counts[b], counts[a]);
    let rightRangeCount = subtractArrays(counts[d], counts[c]);

    if (a > rd) {
      rightRangeCount = subtractArrays(rightRangeCount, subtractArrays(counts[Math.min(a, rc)], counts[rd]));
    }
    if (rc > b) {
      rightRangeCount = subtractArrays(rightRangeCount, subtractArrays(counts[rc], counts[Math.max(b, rd)]));
    }
    if (c > rb) {
      leftRangeCount = subtractArrays(leftRangeCount, subtractArrays(counts[Math.min(c, ra)], counts[rb]));
    }
    if (ra > d) {
      leftRangeCount = subtractArrays(leftRangeCount, subtractArrays(counts[ra], counts[Math.max(d, rb)]));
    }

    const allNonNeg = arr => arr.every(x => x >= 0);
    const arraysEqual = (x, y) => x.length === y.length && x.every((v, i) => v === y[i]);

    ans.push(allNonNeg(leftRangeCount) && allNonNeg(rightRangeCount) && arraysEqual(leftRangeCount, rightRangeCount));
  }

  return ans;
}

function minOperations(x, y) {
    if (x === y) return 0;
    const queue = [[x, 0]];
    const visited = new Set([x]);
    while (queue.length > 0) {
        const [current, steps] = queue.shift();
        if (current === y) return steps;
        const nextValues = [];
        if (current % 5 === 0) nextValues.push(current / 5);
        if (current % 11 === 0) nextValues.push(current / 11);
        nextValues.push(current + 1);
        nextValues.push(current - 1);
        for (const next of nextValues) {
            if (next <= 0 || visited.has(next)) continue;
            visited.add(next);
            queue.push([next, steps + 1]);
        }
    }
    return -1;
}

function maximumAreaOfLongestDiagonalRectangle(dimensions) {
  let maxDiagonal = 0, maxArea = 0;
  for (let i = 0; i < dimensions.length; i++) {
    // calculate the length of the diagonal for the current rectangle
    let diagonalLength = Math.sqrt(dimensions[i][0] * dimensions[i][0] + dimensions[i][1] * dimensions[i][1]);
    // update maxDiagonal and maxArea if the current diagonal is longer
    if (diagonalLength > maxDiagonal) {
      maxDiagonal = diagonalLength;
      maxArea = dimensions[i][0] * dimensions[i][1];
    }
  }
  return maxArea;
}

function minMovesToCaptureTheQueen(a, b, c, d, e, f) {
    function between(x, lo, hi) { return x > Math.min(lo, hi) && x < Math.max(lo, hi); }
    function rookCanCapture(rx, ry, tx, ty, ox, oy) {
        if (rx !== tx && ry !== ty) return false;
        if (rx === tx) { if (ox === rx && between(oy, ry, ty)) return false; return true; }
        else { if (oy === ry && between(ox, rx, tx)) return false; return true; }
    }
    function bishopCanCapture(bx, by, tx, ty, ox, oy) {
        if (Math.abs(bx - tx) !== Math.abs(by - ty)) return false;
        if (Math.abs(ox - bx) === Math.abs(oy - by) && Math.abs(ox - tx) === Math.abs(oy - ty) && between(ox, bx, tx) && between(oy, by, ty)) return false;
        return true;
    }
    if (rookCanCapture(a, b, e, f, c, d)) return 1;
    if (bishopCanCapture(c, d, e, f, a, b)) return 1;
    return 2;
}

function maxPartitions(s, k) {
    // The optimal way is to change at most one index to get the maximum number of distinct characters in the string
    let max = 0;
    for (let i = 0; i < s.length; i++) {
        let set = new Set();
        for (let j = 0; j < s.length; j++) {
            if (i === j) {
                // Try all possible lowercase English letters
                for (let c = 'a'.charCodeAt(0); c <= 'z'.charCodeAt(0); c++) {
                    let char = String.fromCharCode(c);
                    if (char !== s[j]) {
                        set.add(char);
                    } else {
                        set.add(s[j]);
                    }
                    if (set.size <= k) {
                        // If the number of distinct characters is within the limit, update the maximum number of partitions
                        let partitions = 1;
                        let distinct = new Set();
                        for (let x = 0; x < s.length; x++) {
                            if (x === j) {
                                distinct.add(char);
                            } else {
                                distinct.add(s[x]);
                            }
                            if (distinct.size > k) {
                                partitions++;
                                distinct.clear();
                                if (x === j) {
                                    distinct.add(char);
                                } else {
                                    distinct.add(s[x]);
                                }
                            }
                        }
                        max = Math.max(max, partitions);
                    }
                    set.clear();
                }
            } else {
                set.add(s[j]);
            }
        }
    }
    // If no changes are made, calculate the maximum number of partitions
    let set = new Set();
    let partitions = 1;
    for (let i = 0; i < s.length; i++) {
        set.add(s[i]);
        if (set.size > k) {
            partitions++;
            set.clear();
            set.add(s[i]);
        }
    }
    max = Math.max(max, partitions);
    return max;
}

function maxFrequencyElements(nums) {
  var frequencyMap = {}; // create a map to store the frequency of each element
  var maxFrequency = 0; // initialize max frequency
  var maxFrequencyCount = 0; // initialize count of elements with max frequency
  // iterate through the array to populate the frequency map and find the max frequency
  for (var i = 0; i < nums.length; i++) {
    frequencyMap[nums[i]] = (frequencyMap[nums[i]] || 0) + 1;
    if (frequencyMap[nums[i]] > maxFrequency) {
      maxFrequency = frequencyMap[nums[i]];
    }
  }
  // iterate through the frequency map to count the elements with max frequency
  for (var key in frequencyMap) {
    if (frequencyMap[key] === maxFrequency) {
      maxFrequencyCount += maxFrequency; // add the frequency to the count
    }
  }
  return maxFrequencyCount;
}

function minCoinsToAdd(coins, target) {
    // sort the existing coins
    coins.sort((a, b) => a - b);

    let maxReach = 0;   // we can form every sum in [1, maxReach]
    let added = 0;      // number of new coins inserted
    let i = 0;          // index in the sorted array

    while (maxReach < target) {
        if (i < coins.length && coins[i] <= maxReach + 1) {
            // existing coin extends the reachable range
            maxReach += coins[i];
            i++;
        } else {
            // need to patch with a coin of value maxReach+1
            added++;
            maxReach += maxReach + 1;
        }
    }
    return added;
}

function greatestCheapNumber(k, x) {
    function countPrice(num) {
        let total = 0n;
        const N = BigInt(num);
        for (let m = x; m <= 60; m += x) {
            const bit = m - 1;
            const cycle = 1n << BigInt(bit + 1);
            const half = 1n << BigInt(bit);
            const full = (N + 1n) / cycle;
            let count = full * half;
            const rem = (N + 1n) % cycle;
            if (rem > half) count += rem - half;
            total += count;
        }
        return total;
    }
    let lo = 1n, hi = 1n << 60n;
    let ans = 0n;
    const K = BigInt(k);
    while (lo <= hi) {
        const mid = (lo + hi) / 2n;
        if (countPrice(mid) <= K) { ans = mid; lo = mid + 1n; } else { hi = mid - 1n; }
    }
    return Number(ans);
}

function findCommon(nums1, nums2) {
    // build hash sets for fast O(1) look‑ups
    const set1 = new Set(nums1);
    const set2 = new Set(nums2);

    // count elements of nums1 that exist in nums2
    let answer1 = 0;
    for (const v of nums1) if (set2.has(v)) answer1++;

    // count elements of nums2 that exist in nums1
    let answer2 = 0;
    for (const v of nums2) if (set1.has(v)) answer2++;

    return [answer1, answer2]; // optimal linear solution
}

function divideArray(nums, k) {
    // sort the whole array
    nums.sort((a, b) => a - b);

    const groups = [];
    for (let i = 0; i < nums.length; i += 3) {
        // check the max‑min condition for the current triple
        if (nums[i + 2] - nums[i] > k) return [];   // impossible
        groups.push([nums[i], nums[i + 1], nums[i + 2]]);
    }
    return groups;
}

function countCompleteSubstrings(word, k) {
    const n = word.length;
    const base = 'a'.charCodeAt(0);
    let answer = 0;
    for (let d = 1; d <= 26; d++) {
        const size = k * d;
        if (size > n) break;
        const cnt = new Array(26).fill(0);
        let distinct = 0;
        let full = 0;
        // initial window
        for (let i = 0; i < size; i++) {
            const idx = word.charCodeAt(i) - base;
            if (cnt[idx] === 0) distinct++;
            cnt[idx]++;
            if (cnt[idx] === k) full++;
            else if (cnt[idx] === k + 1) full--;
        }
        if (distinct === d && full === d) answer++;
        // slide window
        for (let i = size; i < n; i++) {
            const leftIdx = word.charCodeAt(i - size) - base;
            if (cnt[leftIdx] === k) full--;
            cnt[leftIdx]--;
            if (cnt[leftIdx] === 0) distinct--;
            else if (cnt[leftIdx] === k - 1) {
                // nothing extra needed
            }
            const rightIdx = word.charCodeAt(i) - base;
            if (cnt[rightIdx] === 0) distinct++;
            cnt[rightIdx]++;
            if (cnt[rightIdx] === k) full++;
            else if (cnt[rightIdx] === k + 1) full--;
            if (distinct === d && full === d) answer++;
        }
    }
    return answer;
}

function minimumKeypresses(word) {
    let freqMap = {};
    for (let char of word) { if (!freqMap[char]) freqMap[char] = 0; freqMap[char]++; }
    let frequencies = Object.values(freqMap).sort((a, b) => b - a);
    let pushes = 0;
    for (let i = 0; i < frequencies.length; i++) {
        pushes += frequencies[i] * (Math.floor(i / 8) + 1);
    }
    return pushes;
}

function checkTrailingZeros(nums) {
    let evenCount = 0;                         // count how many numbers are even
    for (let i = 0; i < nums.length; i++) {
        if ((nums[i] & 1) === 0) evenCount++; // LSB 0 → even
        if (evenCount >= 2) return true;      // need at least two evens for OR to be even
    }
    return false;
}

function countChangingKeys(s) {
