}

function countPairs(n, m) {
  // convert to BigInt for safe arithmetic
  const N = BigInt(n);
  const M = BigInt(m);

  // oddX = ceil(N/2), evenX = floor(N/2)
  const oddX = (N + 1n) / 2n;   // ceil
  const evenX = N / 2n;         // floor

  // oddY = ceil(M/2), evenY = floor(M/2)
  const oddY = (M + 1n) / 2n;
  const evenY = M / 2n;

  // main logic: count pairs where sum is odd
  const ans = oddX * evenY + evenX * oddY;

  // return as Number if it fits safely, otherwise as string
  const MAX_SAFE = BigInt(Number.MAX_SAFE_INTEGER);
  return ans <= MAX_SAFE ? Number(ans) : ans.toString();
}

var minOrAfterOperations = function(nums, k) {
    const B = 30;
    const cnt = new Array(B).fill(0);
    for (let x of nums) {
        let b = 0;
        while (x) {
            if (x & 1) cnt[b]++;
            x = x >>> 1;
            b++;
        }
    }
    let ans = 0;
    for (let bit=0; bit<B; bit++) {
        if (cnt[bit] > k) ans |= (1<<bit);
    }
    return ans;
};

function maximumLength(nums) {
  const count = new Map();
  for (const x of nums) count.set(x, (count.get(x) || 0) + 1);
  let best = count.get(1) || 0;
  for (const [val, cnt] of count.entries()) {
    if (val === 1) continue;
    let length = 0, cur = val;
    while (count.has(cur) && count.get(cur) >= 2) {
      length += 2;
      const next = cur * cur;
      if (next === cur || next > 1e10) break;
      cur = next;
    }
    if (count.has(cur)) length += 1;
    best = Math.max(best, length);
  }
  return best;
}

function typeOfTriangle(nums) {
    // check triangle inequality and positive sides
    if (nums[0] <= 0 || nums[1] <= 0 || nums[2] <= 0 ||
        nums[0] + nums[1] <= nums[2] ||
        nums[0] + nums[2] <= nums[1] ||
        nums[1] + nums[2] <= nums[0]) {
        return "none";
    }
    if (nums[0] === nums[1] && nums[1] === nums[2]) return "equilateral";
    if (nums[0] === nums[1] || nums[0] === nums[2] || nums[1] === nums[2]) return "isosceles";
    return "scalene";
}

function countUpperLeftPairs(points) {
    const n = points.length;
    let count = 0;
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if (i === j) continue;
            const [xi, yi] = points[i];
            const [xj, yj] = points[j];
            if (!(yi > yj && xi <= xj)) continue;
            let blocked = false;
            for (let k = 0; k < n && !blocked; k++) {
                if (k === i || k === j) continue;
                const [xk, yk] = points[k];
                if (xi < xk && xk < xj && yi > yk && yk > yj) blocked = true;
            }
            if (!blocked) count++;
        }
    }
    return count;
}

function antBoundary(nums) {
  let position = 0;          // current distance from the boundary
  let returns = 0;           // number of times we are exactly at the boundary
  for (let i = 0; i < nums.length; i++) {
    position += nums[i];     // update position according to the current step
    if (position === 0) {    // check if we have returned to the boundary
      returns++;
    }
  }
  return returns;
}

function resultGrid(image, threshold) {
    const m = image.length, n = image[0].length;
    const sum = Array.from({length:m}, () => new Array(n).fill(0));
    const cnt = Array.from({length:m}, () => new Array(n).fill(0));
    for (let i = 0; i + 2 < m; i++) {
        for (let j = 0; j + 2 < n; j++) {
            let valid = true, total = 0;
            for (let di = 0; di < 3 && valid; di++) {
                for (let dj = 0; dj < 3 && valid; dj++) {
                    const r = i+di, c = j+dj;
                    total += image[r][c];
                    if (dj+1 < 3 && Math.abs(image[r][c]-image[r][c+1]) > threshold) valid = false;
                    if (di+1 < 3 && Math.abs(image[r][c]-image[r+1][c]) > threshold) valid = false;
                }
            }
            if (valid) {
                const avg = Math.floor(total/9);
                for (let di = 0; di < 3; di++) for (let dj = 0; dj < 3; dj++) {
                    sum[i+di][j+dj] += avg;
                    cnt[i+di][j+dj] += 1;
                }
            }
        }
    }
    const result = Array.from({length:m}, () => new Array(n).fill(0));
    for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) {
        result[i][j] = cnt[i][j] > 0 ? Math.floor(sum[i][j]/cnt[i][j]) : image[i][j];
    }
    return result;
}

function minimumTimeToRevertWord(word, k) {
    const n = word.length;
    for (let t = 1; ; t++) {
        const shift = t * k;
        if (shift >= n) return t;
        let ok = true;
        for (let i = 0; i < n - shift; i++) {
            if (word[i] !== word[i + shift]) {
                ok = false;
                break;
            }
        }
        if (ok) return t;
    }
}

function countValidPairs(points) {
    const n = points.length;
    const xs = [], ys = [];
    for (let i = 0; i < n; i++) {
        xs.push(points[i][0]);
        ys.push(points[i][1]);
    }
    const uniqX = Array.from(new Set(xs)).sort((a, b) => a - b);
    const uniqY = Array.from(new Set(ys)).sort((a, b) => a - b);
    const mapX = new Map();
    const mapY = new Map();
    for (let i = 0; i < uniqX.length; i++) mapX.set(uniqX[i], i + 1);
    for (let i = 0; i < uniqY.length; i++) mapY.set(uniqY[i], i + 1);
    const nx = uniqX.length;
    const ny = uniqY.length;
    const pref = Array.from({ length: nx + 1 }, () => new Uint32Array(ny + 1));
    const idxX = new Array(n);
    const idxY = new Array(n);
    for (let i = 0; i < n; i++) {
        const xi = points[i][0];
        const yi = points[i][1];
        const ix = mapX.get(xi);
        const iy = mapY.get(yi);
        idxX[i] = ix;
        idxY[i] = iy;
        pref[ix][iy] = 1; // store point
    }
    for (let i = 1; i <= nx; i++) {
        const row = pref[i];
        const prev = pref[i - 1];
        let sum = 0;
        for (let j = 1; j <= ny; j++) {
            sum += row[j];
            row[j] = sum + prev[j];
        }
    }
    function rectSum(x1, y1, x2, y2) {
        return pref[x2][y2] - pref[x1 - 1][y2] - pref[x2][y1 - 1] + pref[x1 - 1][y1 - 1];
    }
    let ans = 0;
    for (let i = 0; i < n; i++) {
        const xi = points[i][0];
        const yi = points[i][1];
        const ix = idxX[i];
        const iy = idxY[i];
        for (let j = 0; j < n; j++) {
            if (i === j) continue;
            const xj = points[j][0];
            const yj = points[j][1];
            if (xi <= xj && yi >= yj) {
                const jx = idxX[j];
                const jy = idxY[j];
                const cnt = rectSum(ix, jy, jx, iy);
                if (cnt === 2) ans++;
            }
        }
    }
    return ans;
}

function minimumTimeToRevertWordII(word, k) {
  const n = word.length;
  const pi = new Uint32Array(n);
  for (let i = 1; i < n; i++) {
    let j = pi[i - 1];
    while (j > 0 && word[i] !== word[j]) {
      j = pi[j - 1];
    }
    if (word[i] === word[j]) j++;
    pi[i] = j;
  }
  let L = pi[n - 1];
  while (L > 0 && ((n - L) % k !== 0)) {
    L = pi[L - 1];
  }
  if (L > 0 && ((n - L) % k === 0)) {
    return (n - L) / k;
  }
  return Math.ceil(n / k);
}

function countMatchingSubarrays(nums, pattern) {
  const n = nums.length, m = pattern.length;
  let count = 0;
  for (let i = 0; i + m < n; i++) {
    let ok = true;
    for (let k = 0; k < m; k++) {
      const diff = nums[i+k+1] - nums[i+k];
      if (pattern[k] === 1 && diff <= 0) { ok = false; break; }
      if (pattern[k] === 0 && diff !== 0) { ok = false; break; }
      if (pattern[k] === -1 && diff >= 0) { ok = false; break; }
    }
    if (ok) count++;
  }
  return count;
}

function maximumPalindromesAfterOperations(words) {
    const freq = new Array(26).fill(0);
    for (const w of words) for (const c of w) freq[c.charCodeAt(0) - 97]++;

    let totalPairs = 0, totalSingles = 0;
    for (const cnt of freq) {
        totalPairs += Math.floor(cnt / 2);
        totalSingles += cnt & 1;
    }

    const lengths = words.map(w => w.length).sort((a, b) => a - b);
    let count = 0;
    for (const length of lengths) {
        const needPairs = Math.floor(length / 2);
        if (length % 2 === 0) {
            if (totalPairs >= needPairs) { totalPairs -= needPairs; count++; }
        } else {
            const extra = totalSingles > 0 ? 0 : 1;
            if (totalPairs >= needPairs + extra) {
                totalPairs -= needPairs;
                if (totalSingles) totalSingles--; else totalPairs--;
                count++;
            }
        }
    }
    return count;
}

function numberOfSubarrays(nums, pattern) {
  const n = nums.length;
  const m = pattern.length;

  // empty pattern → every single element forms a matching subarray
  if (m === 0) return n;

  // build diff array: sign of consecutive differences
  const diff = new Array(n - 1);
  for (let i = 0; i < n - 1; ++i) {
    const d = nums[i + 1] - nums[i];
    diff[i] = d > 0 ? 1 : d < 0 ? -1 : 0;
  }

  // ---------- KMP preprocessing (LPS) ----------
  const lps = new Array(m).fill(0);
  for (let i = 1, len = 0; i < m; ) {
    if (pattern[i] === pattern[len]) {
      lps[i++] = ++len;
    } else if (len) {
      len = lps[len - 1];
    } else {
      lps[i++] = 0;
    }
  }

  // ---------- KMP scan ----------
  let count = 0;
  for (let i = 0, j = 0; i < diff.length; ) {
    if (diff[i] === pattern[j]) {
      ++i; ++j;
      if (j === m) {          // full match found
        ++count;
        j = lps[j - 1];       // continue searching for overlapping matches
      }
    } else if (j) {
      j = lps[j - 1];
    } else {
      ++i;
    }
  }
  return count;
}

function modifyMatrix(matrix) {
    const rows = matrix.length;
    if (rows === 0) return [];                     // handle empty matrix
    const cols = matrix[0].length;

    // Compute column maximums and later replace -1 with those maximums
    const colMax = new Array(cols).fill(-Infinity);
    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            const val = matrix[i][j];
            if (val > colMax[j]) colMax[j] = val; // update column max
        }
    }

    const answer = matrix.map(row => row.slice()); // deep copy
    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            if (answer[i][j] === -1) answer[i][j] = colMax[j];
        }
    }
    return answer;
}

function maxOperations(nums) {
    const arr = nums.slice();
    if (arr.length < 2) return 0;
    const score = arr[0] + arr[1];
    let ops = 0;
    let i = 0;
    while (i + 1 < arr.length) {
        if (arr[i] + arr[i + 1] === score) {
            ops++;
            i += 2;
        } else break;
    }
    return ops;
}

function reduceStringBeforeLastOperation(s) {
    const stack = [];
    for (let i = 0; i < s.length; i++) {
        const ch = s[i];
        if (stack.length && stack[stack.length - 1] === ch) {
            stack.pop();
        } else {
            stack.push(ch);
        }
    }
    return stack.join('');
}

function maxConsecutiveElements(nums) {
    const sorted = nums.slice().sort((a, b) => a - b);
    const dp = new Map();
    let ans = 1;
    for (const x of sorted) {
        const dpXplus1 = (dp.get(x) || 0) + 1;
        const dpX = (dp.get(x - 1) || 0) + 1;
        dp.set(x + 1, dpXplus1);
        dp.set(x, dpX);
        ans = Math.max(ans, dpXplus1, dpX);
    }
    return ans;
}

function maxOperations(nums) {
    const MAX_VAL = 1000;
    const cnt = new Array(MAX_VAL + 1).fill(0);
    for (const v of nums) cnt[v]++;

    let best = 0;
    for (let s = 2; s <= 2 * MAX_VAL; s++) {
        let ops = 0;
        const limit = Math.floor(s / 2);
        for (let x = 1; x <= limit; x++) {
            const y = s - x;
            if (y < 1 || y > MAX_VAL) continue;
            if (x === y) {
                ops += Math.floor(cnt[x] / 2);
            } else {
                ops += Math.min(cnt[x], cnt[y]);
            }
        }
        if (ops > best) best = ops;
    }
    return best;
}

function countPrefixAndSuffixPairsI(words) {
    let ans = 0;
    const seen = new Map();
    for (const w of words) {
        const n = w.length;
        const pi = new Array(n).fill(0);
        for (let i = 1; i < n; i++) {
            let j = pi[i - 1];
            while (j && w[i] !== w[j]) j = pi[j - 1];
            if (w[i] === w[j]) j++;
            pi[i] = j;
        }
        let l = n;
        while (l) {
            const prefix = w.slice(0, l);
            ans += seen.get(prefix) || 0;
            l = pi[l - 1];
        }
        seen.set(w, (seen.get(w) || 0) + 1);
    }
    return ans;
}

function longestCommonPrefixLength(arr1, arr2) {
    // collect every prefix of numbers from arr1
    const prefSet = new Set();
