                if (sum < best) best = sum;
            }
        }
    }

    // three horizontal strips
    for (let r1 = 0; r1 < n - 2; r1++) {
        for (let r2 = r1 + 1; r2 < n - 1; r2++) {
            const a1 = area(0, r1, 0, m - 1);
            const a2 = area(r1 + 1, r2, 0, m - 1);
            const a3 = area(r2 + 1, n - 1, 0, m - 1);
            if (a1 && a2 && a3) {
                const sum = a1 + a2 + a3;
                if (sum < best) best = sum;
            }
        }
    }

    // L-shaped (one horizontal and one vertical cut)
    for (let r = 0; r < n - 1; r++) {
        for (let c = 0; c < m - 1; c++) {
            const tl = area(0, r, 0, c);
            const tr = area(0, r, c + 1, m - 1);
            const bl = area(r + 1, n - 1, 0, c);
            const br = area(r + 1, n - 1, c + 1, m - 1);
            const parts = [tl, tr, bl, br];
            const cnt = parts.filter(v => v !== null).length;
