            if (grid[i][j] !== grid[m - 1 - i][j]) colFlips++;   // one flip fixes the pair
        }
    }

    return Math.min(rowFlips, colFlips);
}

function isPathPossible(xCorner, yCorner, circles) {
    const n = circles.length;
    const leftIdx = n, rightIdx = n+1, bottomIdx = n+2, topIdx = n+3;
    const parent = [...Array(n+4).keys()];
    const rank = new Array(n+4).fill(0);
    function find(v) { while (parent[v] !== v) { parent[v] = parent[parent[v]]; v = parent[v]; } return v; }
    function unite(a, b) {
        let ra = find(a), rb = find(b);
        if (ra === rb) return;
        if (rank[ra] < rank[rb]) [ra, rb] = [rb, ra];
        parent[rb] = ra;
        if (rank[ra] === rank[rb]) rank[ra]++;
    }
    function touchesSide(x, y, r, side) {
        let dx, dy;
        if (side === 'left') {
            dx = x; dy = 0;
            if (y < 0) dy = -y; else if (y > yCorner) dy = y - yCorner;
        } else if (side === 'right') {
            dx = x - xCorner; dy = 0;
            if (y < 0) dy = -y; else if (y > yCorner) dy = y - yCorner;
        } else if (side === 'bottom') {
            dy = y; dx = 0;
            if (x < 0) dx = -x; else if (x > xCorner) dx = x - xCorner;
        } else {
            dy = y - yCorner; dx = 0;
            if (x < 0) dx = -x; else if (x > xCorner) dx = x - xCorner;
        }
        return dx*dx + dy*dy <= r*r;
    }
    for (let i = 0; i < n; i++) {
        const [x, y, r] = circles[i];
        if (touchesSide(x, y, r, 'left')) unite(i, leftIdx);
        if (touchesSide(x, y, r, 'right')) unite(i, rightIdx);
        if (touchesSide(x, y, r, 'bottom')) unite(i, bottomIdx);
        if (touchesSide(x, y, r, 'top')) unite(i, topIdx);
    }
    for (let i = 0; i < n; i++) {
        const [xi, yi, ri] = circles[i];
        for (let j = i+1; j < n; j++) {
            const [xj, yj, rj] = circles[j];
            const dx = xi - xj, dy = yi - yj;
            if (dx*dx + dy*dy <= (ri+rj)*(ri+rj)) unite(i, j);
        }
    }
    if (find(leftIdx) === find(rightIdx)) return false;
    if (find(bottomIdx) === find(topIdx)) return false;
    if (find(leftIdx) === find(bottomIdx)) return false;
    if (find(rightIdx) === find(topIdx)) return false;
    return true;
}

function countWinningPlayers(n, pick) {
    let winningCount = 0;                     // number of players that win
    const winners = new Set();                // players already counted
    const playerMap = new Map();              // player -> Map(colour -> count)

    for (let i = 0; i < pick.length; i++) {
        const [player, colour] = pick[i];
        if (winners.has(player)) continue;    // main logic: skip already winning players

        let colourMap = playerMap.get(player);
        if (!colourMap) {
            colourMap = new Map();
            playerMap.set(player, colourMap);
        }

        const newCnt = (colourMap.get(colour) || 0) + 1;
        colourMap.set(colour, newCnt);        // main logic: update count

        if (newCnt > player) {                 // main logic: check winning condition
            winners.add(player);
            winningCount++;
        }
    }
    return winningCount;
}

function timeTaken(edges) {
    const n = edges.length + 1;
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }

    const result = new Array(n).fill(0);

    for (let src = 0; src < n; src++) {
        const dist = new Array(n).fill(-1);
        dist[src] = 0;
        const stack = [src];
        let maxDist = 0;
        while (stack.length) {
            const cur = stack.pop();
            for (const nb of adj[cur]) {
                if (dist[nb] === -1) {
                    const w = (nb % 2 === 0) ? 2 : 1;
                    dist[nb] = dist[cur] + w;
                    if (dist[nb] > maxDist) maxDist = dist[nb];
                    stack.push(nb);
                }
            }
        }
        result[src] = maxDist;
    }
    return result;
}

function minimumNumberOfFlipsToMakeBinaryGridPalindromicII(grid) {
    const m = grid.length, n = grid[0].length;
    const visited = Array.from({length: m}, () => new Array(n).fill(false));
    const sizes = [];
    const onesCount = [];
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (visited[i][j]) continue;
            const cells = [];
            const xs = [i, i, m - 1 - i, m - 1 - i];
            const ys = [j, n - 1 - j, j, n - 1 - j];
            for (let k = 0; k < 4; k++) {
                const x = xs[k], y = ys[k];
                if (!visited[x][y]) { visited[x][y] = true; cells.push([x, y]); }
            }
            const sz = cells.length;
            let ones = 0;
            for (const [x, y] of cells) ones += grid[x][y];
            sizes.push(sz);
            onesCount.push(ones);
        }
    }
    const INF = Number.MAX_SAFE_INTEGER;
    let dp = [0, INF, INF, INF];
    for (let idx = 0; idx < sizes.length; idx++) {
        const sz = sizes[idx], ones = onesCount[idx];
        const cost0 = ones, cost1 = sz - ones;
        const ndp = [INF, INF, INF, INF];
        for (let mod = 0; mod < 4; mod++) {
            if (dp[mod] === INF) continue;
            if (dp[mod] + cost0 < ndp[mod]) ndp[mod] = dp[mod] + cost0;
            const nmod = (mod + sz) % 4;
            if (dp[mod] + cost1 < ndp[nmod]) ndp[nmod] = dp[mod] + cost1;
        }
        dp = ndp;
    }
    return dp[0];
}

function shortestDistanceAfterRoadAdditionQueriesII(n, queries) {
    const nxt = Array.from({length: n - 1}, (_, i) => i + 1);
    let cnt = n - 1;
    const ans = [];
    for (const [u, v] of queries) {
        if (nxt[u] > 0 && nxt[u] < v) {
            let i = nxt[u];
            while (i < v) {
                cnt--;
                const ni = nxt[i];
                nxt[i] = 0;
                i = ni;
            }
            nxt[u] = v;
        }
        ans.push(cnt);
    }
    return ans;
}

function snakeInMatrix(n, commands) {
  let row = 0, col = 0;                     // start at cell 0
  for (let i = 0; i < commands.length; i++) {
    const cmd = commands[i];
    // update row and col based on command
    if (cmd === "UP") row--;
    else if (cmd === "DOWN") row++;
    else if (cmd === "LEFT") col--;
    else if (cmd === "RIGHT") col++;
  }
  return row * n + col;                     // convert (row,col) to index
}

function countGoodNodes(edges) {
    const n = edges.length + 1;                     // number of nodes
    const adj = Array.from({ length: n }, () => []); // adjacency list
    for (const [a, b] of edges) {                   // build graph
        adj[a].push(b);
        adj[b].push(a);
    }

    const parent = new Array(n).fill(-1);
    const order = [];                               // DFS order
    const stack = [0];
    parent[0] = 0;                                  // root's parent is itself

    // ---------- build parent array and preorder ----------
    while (stack.length) {
        const v = stack.pop();
        order.push(v);
        for (const nb of adj[v]) {
            if (parent[nb] === -1) {
                parent[nb] = v;
                stack.push(nb);
            }
        }
    }

    const subSize = new Array(n).fill(1);
    let goodCount = 0;

    // ---------- process nodes bottom‑up ----------
    for (let i = order.length - 1; i >= 0; i--) {
        const v = order[i];
        const childSizes = [];
        for (const nb of adj[v]) {
            if (nb !== parent[v]) {
                childSizes.push(subSize[nb]);        // sizes of all children
            }
        }

        // node is good if it has ≤1 child or all child sizes are equal
        let isGood = true;
        if (childSizes.length > 1) {
            const first = childSizes[0];
            for (let j = 1; j < childSizes.length; j++) {
                if (childSizes[j] !== first) { isGood = false; break; }
            }
        }
        if (isGood) goodCount++;

        // compute subtree size of v
        let sum = 1;
        for (const sz of childSizes) sum += sz;
        subSize[v] = sum;
    }
    return goodCount;
}

function findSmallestMissingInteger(nums) {
  let longestPrefixSum = 0, longestPrefixLength = 0;
  for (let i = 0; i < nums.length; i++) {
    // check if current prefix is sequential
    if (isSequential(nums, i)) {
      let currentPrefixSum = nums.slice(0, i + 1).reduce((a, b) => a + b, 0);
      if (i + 1 > longestPrefixLength) {
        longestPrefixSum = currentPrefixSum;
        longestPrefixLength = i + 1;
      }
    }
  }
  // find smallest missing integer greater than or equal to the sum of the longest sequential prefix
  let smallestMissingInteger = longestPrefixSum;
  while (nums.includes(smallestMissingInteger)) {
    smallestMissingInteger++;
  }
  return smallestMissingInteger;
}

function isSequential(nums, endIndex) {
  for (let i = 1; i <= endIndex; i++) {
    // check if current prefix is sequential
    if (nums[i] - nums[i - 1] !== 1) {
      return false;
    }
  }
  return true;
}

function NeighborSum(grid) {
    const n = grid.length;
    const pos = new Map();                     // map each value to its encoded coordinate

    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            pos.set(grid[i][j], i * n + j);
        }
    }

    // sum of 4‑directionally adjacent cells
    this.adjacentSum = function (val) {
        const idx = pos.get(val);
        if (idx === undefined) return 0;
        const i = Math.floor(idx / n);
        const j = idx % n;
        let sum = 0;
        if (i > 0) sum += grid[i - 1][j];
        if (i < n - 1) sum += grid[i + 1][j];
        if (j > 0) sum += grid[i][j - 1];
        if (j < n - 1) sum += grid[i][j + 1];
        return sum;
    };

    // sum of the 4 diagonal cells
    this.diagonalSum = function (val) {
        const idx = pos.get(val);
        if (idx === undefined) return 0;
        const i = Math.floor(idx / n);
        const j = idx % n;
        let sum = 0;
        if (i > 0 && j > 0) sum += grid[i - 1][j - 1];
        if (i > 0 && j < n - 1) sum += grid[i - 1][j + 1];
        if (i < n - 1 && j > 0) sum += grid[i + 1][j - 1];
        if (i < n - 1 && j < n - 1) sum += grid[i + 1][j + 1];
        return sum;
    };
}

