function countMonotonicPairs(nums) {
  const MOD = 1000000007;
  const n = nums.length;
  const maxVal = Math.max(...nums);
  let dpPrev = new Array(maxVal + 1).fill(0);
  for (let v = 0; v <= nums[0]; v++) dpPrev[v] = 1;
  for (let i = 1; i < n; i++) {
    const L = Math.max(0, nums[i] - nums[i - 1]);
    const dpCurr = new Array(maxVal + 1).fill(0);
    const pref = new Array(maxVal + 1).fill(0);
    pref[0] = dpPrev[0];
    for (let v = 1; v <= maxVal; v++) {
      pref[v] = (pref[v - 1] + dpPrev[v]) % MOD;
    }
    for (let v = 0; v <= nums[i]; v++) {
      const limit = v - L;
      if (limit >= 0) {
        dpCurr[v] = pref[limit];
      }
    }
    dpPrev = dpCurr;
  }
  let ans = 0;
  for (let v = 0; v <= nums[n - 1]; v++) {
    ans = (ans + dpPrev[v]) % MOD;
  }
  return ans;
}

function numberOfSubstrings(s) {
    const n = s.length;
    const zerosPos = [];
    for (let i = 0; i < n; i++) if (s[i] === '0') zerosPos.push(i);
    let ans = 0;
    for (let i = 0; i < n; i++) {
        // find first zero index (in zerosPos array) at or after i
        let lo = 0, hi = zerosPos.length;
        while (lo < hi) { const mid=(lo+hi)>>1; if (zerosPos[mid] >= i) hi=mid; else lo=mid+1; }
        const startIdx = lo; // index into zerosPos of first zero >= i
        // z = 0 case: all windows before first zero
        const firstZero = startIdx < zerosPos.length ? zerosPos[startIdx] : n;
        ans += firstZero - i;
        // z >= 1
        for (let z = 1; ; z++) {
            const zIdx = startIdx + z - 1;
            if (zIdx >= zerosPos.length) break;
            if (z*z > n) break;
            const posZ = zerosPos[zIdx];
            const nextZero = (zIdx+1 < zerosPos.length) ? zerosPos[zIdx+1] : n;
            const minR = Math.max(posZ, i + z*z + z - 1);
            const maxR = nextZero - 1;
            if (minR <= maxR) ans += maxR - minR + 1;
        }
    }
    return ans;
}

function shortestDistanceAfterRoadAdditionQueriesI(n, queries) {
    const adj = Array.from({ length: n }, () => []);
    for (let i = 0; i < n - 1; i++) {
        adj[i].push(i + 1);
    }
    const answer = [];
    for (const [u, v] of queries) {
        adj[u].push(v);
        const INF = 1 << 30;
        const dist = new Int32Array(n);
        dist.fill(INF);
        dist[0] = 0;
        const queue = new Int32Array(n);
        let head = 0, tail = 0;
        queue[tail++] = 0;
        while (head < tail) {
            const cur = queue[head++];
            const curDist = dist[cur] + 1;
            for (const nb of adj[cur]) {
                if (dist[nb] > curDist) {
                    dist[nb] = curDist;
                    queue[tail++] = nb;
                }
            }
        }
        answer.push(dist[n - 1]);
    }
    return answer;
}
