function minOperations(nums, target) {
    const n = nums.length;
    let prev = 0;
    let ops = 0;
    for (let i = 0; i < n; i++) {
        const d = target[i] - nums[i];
        const delta = d - prev;
        if (delta > 0) ops += delta;
        prev = d;
    }
    if (prev < 0) ops += -prev;
    return ops;
}

function maxRookValueSum(board) {
    const m = board.length;
    const n = board[0].length;
    const topVals = new Array(m);

    for (let i = 0; i < m; i++) {
        let best1 = -Infinity, col1 = -1;
        let best2 = -Infinity, col2 = -1;
        let best3 = -Infinity, col3 = -1;
        const row = board[i];
        for (let j = 0; j < n; j++) {
            const v = row[j];
            if (v > best1) {
                best3 = best2; col3 = col2;
                best2 = best1; col2 = col1;
                best1 = v; col1 = j;
            } else if (v > best2) {
                best3 = best2; col3 = col2;
                best2 = v; col2 = j;
            } else if (v > best3) {
                best3 = v; col3 = j;
            }
        }
        const arr = [];
        if (col1 !== -1) arr.push({ val: best1, col: col1 });
        if (col2 !== -1) arr.push({ val: best2, col: col2 });
        if (col3 !== -1) arr.push({ val: best3, col: col3 });
        topVals[i] = arr;
    }

    let globalMax = -Infinity;

    for (let i = 0; i < m - 2; i++) {
        const a = topVals[i];
        for (let j = i + 1; j < m - 1; j++) {
            const b = topVals[j];
            for (let k = j + 1; k < m; k++) {
                const c = topVals[k];
                for (let ai = 0; ai < a.length; ai++) {
                    const av = a[ai].val;
                    const ac = a[ai].col;
                    for (let bj = 0; bj < b.length; bj++) {
                        const bv = b[bj].val;
