                        if (bc === ac) continue;
                        for (let ck = 0; ck < c.length; ck++) {
                            const cv = c[ck].val;
                            const cc = c[ck].col;
                            if (cc === ac || cc === bc) continue;
                            const sum = av + bv + cv;
                            if (sum > globalMax) globalMax = sum;
                        }
                    }
                }
            }
        }
    }

    return globalMax;
}
