function countKConstraintSubstrings(s, k) {
    const n = s.length;
    let left = 0, zeros = 0, ones = 0, count = 0;
    for (let right = 0; right < n; right++) {
        if (s[right] === '0') zeros++; else ones++;
        while (zeros > k && ones > k) {
            if (s[left] === '0') zeros--; else ones--;
            left++;
        }
        count += right - left + 1;
    }
    return count;
}

function findPowerOfKSizeSubarrays(nums, k) {
    const n = nums.length;
    const result = new Array(n - k + 1);
    if (k === 1) {
        for (let i = 0; i < n; i++) result[i] = nums[i];
        return result;
    }
    const inc = new Array(n).fill(0);
    for (let i = 1; i < n; i++) {
        inc[i] = nums[i] > nums[i - 1] ? 1 : 0;
    }
    let sum = 0;
    for (let i = 1; i < k; i++) sum += inc[i];
    for (let start = 0; start <= n - k; start++) {
        if (sum === k - 1) {
            result[start] = nums[start + k - 1];
        } else {
            result[start] = -1;
        }
        if (start + k < n) {
            sum += inc[start + k];
            sum -= inc[start + 1];
        }
    }
    return result;
}

function maximumValueSum(board) {
    const m = board.length;
    const n = board[0].length;
    let bestOverall = -Infinity;

    for (let r1 = 0; r1 < m - 2; r1++) {
        for (let r2 = r1 + 1; r2 < m - 1; r2++) {
            for (let r3 = r2 + 1; r3 < m; r3++) {
                // dp[mask] = max sum using rows of mask (bits 0,1,2) with distinct columns processed so far
                let dp = [-Infinity, -Infinity, -Infinity, -Infinity, -Infinity, -Infinity, -Infinity, -Infinity];
                dp[0] = 0;

                for (let c = 0; c < n; c++) {
                    const v1 = board[r1][c];
                    const v2 = board[r2][c];
                    const v3 = board[r3][c];
                    const ndp = dp.slice(); // copy previous state

                    for (let mask = 0; mask < 8; mask++) {
                        const cur = dp[mask];
                        if (cur === -Infinity) continue;

                        if ((mask & 1) === 0) {
                            const m1 = mask | 1;
                            const val = cur + v1;
                            if (val > ndp[m1]) ndp[m1] = val;
                        }
                        if ((mask & 2) === 0) {
                            const m2 = mask | 2;
                            const val = cur + v2;
                            if (val > ndp[m2]) ndp[m2] = val;
                        }
                        if ((mask & 4) === 0) {
                            const m3 = mask | 4;
                            const val = cur + v3;
                            if (val > ndp[m3]) ndp[m3] = val;
                        }
                    }
                    dp = ndp;
                }

                if (dp[7] > bestOverall) bestOverall = dp[7];
            }
        }
    }

    return bestOverall;
}

function findPowerOfKSizeSubarraysII(nums, k) {
    const n = nums.length;
    const resultSize = n - k + 1;
    const results = new Array(resultSize);
    if (k === 1) {
        for (let i = 0; i < n; i++) results[i] = nums[i];
        return results;
    }
    const inc = new Array(n - 1);
    for (let i = 0; i < n - 1; i++) inc[i] = nums[i + 1] > nums[i] ? 1 : 0;
    let sum = 0;
    for (let i = 0; i < k - 1; i++) sum += inc[i];
    for (let i = 0; i <= n - k; i++) {
        results[i] = sum === k - 1 ? nums[i + k - 1] : -1;
        if (i + k - 1 < inc.length) sum += inc[i + k - 1] - inc[i];
    }
    return results;
}

function countKConstraintSubstrings(s, k, queries) {
  function countInRange(l, r) {
    let total = 0;
    let left = l;
    let cnt0 = 0, cnt1 = 0;
    for (let right = l; right <= r; right++) {
      if (s[right] === '0') cnt0++; else cnt1++;
      while (cnt0 > k && cnt1 > k) {
        if (s[left] === '0') cnt0--; else cnt1--;
        left++;
      }
      total += right - left + 1;
    }
    return total;
  }
  return queries.map(([l, r]) => countInRange(l, r));
}

function finalArrayState(nums, k, multiplier) {
    const heap = [];
    const cmp = (a, b) => a[0] !== b[0] ? a[0] - b[0] : a[1] - b[1]; // ties broken by smaller index
    function heapSwap(i, j) { const tmp = heap[i]; heap[i] = heap[j]; heap[j] = tmp; }
    function heapPush(node) {
        heap.push(node);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (cmp(heap[p], heap[i]) <= 0) break;
            heapSwap(i, p);
            i = p;
        }
    }
    function heapPop() {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            let i = 0;
            while (true) {
                let left = i * 2 + 1;
                let right = left + 1;
                let smallest = i;
                if (left < heap.length && cmp(heap[left], heap[smallest]) < 0) smallest = left;
                if (right < heap.length && cmp(heap[right], heap[smallest]) < 0) smallest = right;
                if (smallest === i) break;
                heapSwap(i, smallest);
                i = smallest;
            }
        }
        return top;
    }
    for (let i = 0; i < nums.length; i++) heapPush([nums[i], i]);
    for (let op = 0; op < k; op++) {
        const [val, idx] = heapPop();
        const newVal = val * multiplier;
        nums[idx] = newVal;
        heapPush([newVal, idx]);
    }
    return nums;
}

function maxEnergyBoost(energyDrinkA, energyDrinkB) {
    const n = energyDrinkA.length;
    if (n === 0) return 0;

    // initial states for hour 0
    let a = energyDrinkA[0];   // drink A
    let b = energyDrinkB[0];   // drink B
    let idle = 0;              // stay idle

    for (let i = 1; i < n; i++) {
        const prevA = a, prevB = b, prevIdle = idle;   // keep previous values

        // transition to drink A or B, or stay idle
        a = Math.max(prevA, prevIdle) + energyDrinkA[i];   // drink A now
        b = Math.max(prevB, prevIdle) + energyDrinkB[i];   // drink B now
        idle = Math.max(prevA, prevB, prevIdle);           // be idle now
    }

    // best possible total boost
    return Math.max(a, b, idle);
}

function findTheLargestPalindromeDivisibleByK(n, k) {
    if (k === 0 || n === 0) return "";
    const m = Math.floor((n + 1) / 2);
    const pow10Mod = new Array(n).fill(0);
    pow10Mod[0] = 1 % k;
    for (let i = 1; i < n; i++) pow10Mod[i] = (pow10Mod[i - 1] * 10) % k;

    const weight = new Array(m).fill(0);
    for (let i = 0; i < m; i++) {
        const j = n - 1 - i;
        if (i === j) weight[i] = pow10Mod[i] % k;
        else weight[i] = (pow10Mod[i] + pow10Mod[j]) % k;
    }

    const reachable = Array.from({length: m + 1}, () => new Uint8Array(k));
    reachable[m][0] = 1;
    for (let i = m - 1; i >= 0; i--) {
        const w = weight[i];
        const cur = reachable[i];
        const nxt = reachable[i + 1];
        for (let r = 0; r < k; r++) {
            if (!nxt[r]) continue;
            for (let d = 0; d <= 9; d++) {
                if (i === 0 && d === 0) continue;
                const nr = (d * w + r) % k;
                cur[nr] = 1;
            }
        }
    }
    if (!reachable[0][0]) return "";

    const firstHalf = new Array(m).fill('');
    let need = 0;
    for (let i = 0; i < m; i++) {
        const w = weight[i];
        for (let d = 9; d >= 0; d--) {
            if (i === 0 && d === 0) continue;
            const contrib = (d * w) % k;
            const suffix = ((need - contrib) % k + k) % k;
            if (reachable[i + 1][suffix]) {
                firstHalf[i] = String(d);
                need = suffix;
                break;
            }
        }
    }
    const res = [...firstHalf];
    const start = n % 2 === 0 ? m - 1 : m - 2;
    for (let i = start; i >= 0; i--) res.push(firstHalf[i]);
    return res.join('');
}

function findKey(num1, num2, num3) {
    var result = 0;          // final key
    var place = 1;           // 1,10,100,1000

    for (var i = 0; i < 4; i++) {
        var d1 = num1 % 10;               // current digit of num1
        var d2 = num2 % 10;               // current digit of num2
        var d3 = num3 % 10;               // current digit of num3

        var minDigit = d1;                // MAIN LOGIC: find minimum digit
        if (d2 < minDigit) minDigit = d2;
        if (d3 < minDigit) minDigit = d3;

        result += minDigit * place;       // MAIN LOGIC: build the key
        place *= 10;

        num1 = Math.floor(num1 / 10);     // shift to next higher digit
        num2 = Math.floor(num2 / 10);
        num3 = Math.floor(num3 / 10);
    }
    return result;   // leading zeros are automatically dropped
}

function countAlmostEqualPairs(nums) {
    function isAlmostEqual(a, b) {
        let sa = String(a), sb = String(b);
        const len = Math.max(sa.length, sb.length);
        sa = sa.padStart(len, '0'); sb = sb.padStart(len, '0');
        if (sa === sb) return true;
        const diffs = [];
        for (let i = 0; i < len; i++) if (sa[i] !== sb[i]) diffs.push(i);
        if (diffs.length !== 2) return false;
        const [p, q] = diffs;
        return sa[p] === sb[q] && sa[q] === sb[p];
    }
    let count = 0;
    for (let i = 0; i < nums.length; i++) {
        for (let j = i + 1; j < nums.length; j++) {
            if (isAlmostEqual(nums[i], nums[j])) count++;
        }
    }
    return count;
}

var countPairs = function(nums) {
    function generate(num) {
        const s = String(num);
        const L = s.length;
        const result = new Set([num]);
        const arr = s.split('');
        for (let i=0;i<L;i++) {
            for (let j=i+1;j<L;j++) {
                const t = arr[i]; arr[i]=arr[j]; arr[j]=t;
                let swapped = arr.join('').replace(/^0+/, '');
                const val = swapped === '' ? 0 : parseInt(swapped, 10);
                result.add(val);
                const t2 = arr[i]; arr[i]=arr[j]; arr[j]=t2;
            }
        }
        return result;
    }
    const n = nums.length;
    const reachable = nums.map(x => generate(x));
    const valueMap = new Map();
    for (let i=0;i<n;i++) {
        for (const v of reachable[i]) {
            if (!valueMap.has(v)) valueMap.set(v, []);
            valueMap.get(v).push(i);
        }
    }
    const seenPairs = new Set();
    let ans = 0;
    for (const idxList of valueMap.values()) {
        const m = idxList.length;
        for (let a=0;a<m;a++) {
            const i = idxList[a];
            for (let b=a+1;b<m;b++) {
                const j = idxList[b];
                const code = i*n+j;
                if (!seenPairs.has(code)) { seenPairs.add(code); ans++; }
            }
        }
    }
    return ans;
};

function finalArrayStateAfterKMultiplicationOperationsII(nums, k, multiplier) {
    const MOD = 1000000007n;
    const n = nums.length;
    const modf = (x) => ((x % Number(MOD)) + Number(MOD)) % Number(MOD);

    if (k === 0 || multiplier === 1) return nums.map(x => modf(x));

    if (multiplier === 0) {
        const key = (val) => {
            if (val === 0) return -Infinity;
            const mag = Math.log(Math.abs(val));
            return val < 0 ? -mag : mag;
        };
        let best = 0;
        for (let i = 1; i < n; i++) if (key(nums[i]) < key(nums[best])) best = i;
        return nums.map((v, i) => i === best ? 0 : modf(v));
    }

    const logM = Math.log(Math.abs(multiplier));
    const cnt = new Array(n).fill(0);

    const heap = [];
    const less = (a, b) => a[0] !== b[0] ? a[0] < b[0] : a[1] < b[1];
    const push = (item) => { heap.push(item); let i = heap.length - 1; while (i > 0) { const p = (i - 1) >> 1; if (less(heap[i], heap[p])) { [heap[i], heap[p]] = [heap[p], heap[i]]; i = p; } else break; } };
    const pop = () => { const top = heap[0]; const last = heap.pop(); if (heap.length) { heap[0] = last; let i = 0; while (true) { let l = 2*i+1, r = 2*i+2, s = i; if (l < heap.length && less(heap[l], heap[s])) s = l; if (r < heap.length && less(heap[r], heap[s])) s = r; if (s === i) break; [heap[i], heap[s]] = [heap[s], heap[i]]; i = s; } } return top; };

    for (let i = 0; i < n; i++) {
        const v = nums[i];
        let kVal;
        if (v === 0) kVal = -Infinity;
        else { const mag = Math.log(Math.abs(v)); kVal = v < 0 ? -mag : mag; }
        push([kVal, i]);
    }

    for (let step = 0; step < k; step++) {
        const [, i] = pop();
        cnt[i]++;
        let newKey;
        if (nums[i] === 0) newKey = -Infinity;
        else { const mag = Math.log(Math.abs(nums[i])) + cnt[i] * logM; newKey = nums[i] < 0 ? -mag : mag; }
        push([newKey, i]);
    }

    const modpow = (base, exp, mod) => {
        base %= mod; let result = 1n;
        while (exp > 0n) { if (exp & 1n) result = (result * base) % mod; base = (base * base) % mod; exp >>= 1n; }
        return result;
    };

    const result = [];
    for (let i = 0; i < n; i++) {
        const base = BigInt(modf(nums[i]));
        const mult = modpow(BigInt(multiplier), BigInt(cnt[i]), MOD);
        result.push(Number((base * mult) % MOD));
    }
    return result;
}

function haveSameColor(coordinate1, coordinate2) {
    // convert column letter to 1‑based index
    const col1 = coordinate1.charCodeAt(0) - 96;   // 'a'.charCodeAt(0) = 97
    const col2 = coordinate2.charCodeAt(0) - 96;
    // row digit to number
    const row1 = Number(coordinate1[1]);
    const row2 = Number(coordinate2[1]);
    // main logic: compare parity of (col + row)
    return (col1 + row1) % 2 === (col2 + row2) % 2;
}

function resultsArray(queries, k) {
  const dists = [];
  const result = [];
  for (const [x, y] of queries) {
    const d = Math.abs(x) + Math.abs(y);
    // insert into sorted position
    let lo = 0, hi = dists.length;
    while (lo < hi) { const mid = (lo+hi)>>1; if (dists[mid] < d) lo = mid+1; else hi = mid; }
    dists.splice(lo, 0, d);
    result.push(dists.length >= k ? dists[k-1] : -1);
  }
  return result;
}

function hashDividedString(s, k) {
    const n = s.length;
    let result = '';
    let blockSum = 0;                     // sum of indices inside current block

    for (let i = 0; i < n; i++) {
        blockSum += s.charCodeAt(i) - 97; // add current character (a → 0)
        if ((i + 1) % k === 0) {          // end of a block
            const ch = String.fromCharCode(97 + (blockSum % 26));
            result += ch;                 // store the hashed character
            blockSum = 0;                 // reset for next block
        }
    }
    return result;
}

function maxScoreGrid(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  const maxMask = 1 << cols;
  const NEG = -1e15;
  let dp = new Array(maxMask).fill(NEG);
  dp[0] = 0;
  for (let i = 0; i < rows; i++) {
    const newDp = dp.slice();
    for (let mask = 0; mask < maxMask; mask++) {
      const cur = dp[mask];
      if (cur === NEG) continue;
      for (let j = 0; j < cols; j++) {
        if ((mask & (1 << j)) === 0) {
          const nMask = mask | (1 << j);
          const val = cur + grid[i][j];
          if (val > newDp[nMask]) newDp[nMask] = val;
        }
      }
    }
    dp = newDp;
  }
  let ans = 0;
  for (let v of dp) if (v > ans) ans = v;
  return ans;
}

function maximumSubarrayXor(nums, queries) {
    const n = nums.length;
    const score = Array.from({ length: n }, () => new Array(n).fill(0));
    const best = Array.from({ length: n }, () => new Array(n).fill(0));
    for (let i = 0; i < n; i++) { score[i][i] = nums[i]; best[i][i] = nums[i]; }
    for (let len = 2; len <= n; len++) {
        for (let i = 0; i + len - 1 < n; i++) {
            const j = i + len - 1;
            score[i][j] = score[i][j - 1] ^ score[i + 1][j];
            best[i][j] = Math.max(score[i][j], best[i][j - 1], best[i + 1][j]);
        }
    }
    return queries.map(([l, r]) => best[l][r]);
}

function countGoodIntegers(n, k) {
    const fact = new Array(n + 1);
    fact[0] = 1;
    for (let i = 1; i <= n; i++) fact[i] = fact[i - 1] * i;

    const halfLen = Math.ceil(n / 2);
    const lo = Math.pow(10, halfLen - 1);
    const hi = Math.pow(10, halfLen) - 1;
    const seen = new Set();

    for (let half = lo; half <= hi; half++) {
        const halfStr = String(half);
        const mirrorPart = (n % 2 === 0) ? halfStr : halfStr.slice(0, -1);
        const rev = mirrorPart.split('').reverse().join('');
        const fullStr = halfStr + rev;
        const fullNum = Number(fullStr);
        if (fullNum % k !== 0) continue;
        const counts = new Array(10).fill(0);
        for (const ch of fullStr) counts[ch.charCodeAt(0) - 48]++;
        seen.add(counts.join(','));
    }

    let total = 0;
    for (const key of seen) {
        const counts = key.split(',').map(Number);
        let allPerm = fact[n];
        for (const c of counts) allPerm /= fact[c];
        let leadZeroPerm = 0;
        if (counts[0] > 0) {
            leadZeroPerm = fact[n - 1] / fact[counts[0] - 1];
            for (let d = 1; d <= 9; d++) leadZeroPerm /= fact[counts[d]];
        }
        total += (allPerm - leadZeroPerm);
    }
    return total;
}

function maxMoves(kx, ky, positions) {
    const N = positions.length;
    const allMask = (1 << N) - 1;
    const dirs = [
        [2, 1], [2, -1], [-2, 1], [-2, -1],
        [1, 2], [1, -2], [-1, 2], [-1, -2]
    ];

    // ---------- compute knight distances between all relevant squares ----------
    const points = [[kx, ky], ...positions];          // 0 = start, 1..N = pawns
    const M = N + 1;
    const dist = Array.from({ length: M }, () => Array(M).fill(0));

    function bfs(startIdx) {
        const [sx, sy] = points[startIdx];
        const dgrid = Array.from({ length: 50 }, () => Array(50).fill(-1));
        const qx = [], qy = [];
        dgrid[sx][sy] = 0;
        qx.push(sx); qy.push(sy);
        let head = 0;
        while (head < qx.length) {
            const x = qx[head];
            const y = qy[head++];
            for (const [dx, dy] of dirs) {
                const nx = x + dx, ny = y + dy;
                if (nx < 0 || ny < 0 || nx >= 50 || ny >= 50) continue;
                if (dgrid[nx][ny] !== -1) continue;
                dgrid[nx][ny] = dgrid[x][y] + 1;
                qx.push(nx); qy.push(ny);
            }
        }
        // fill distances from startIdx to every other point
        for (let j = 0; j < M; ++j) {
            const [tx, ty] = points[j];
            dist[startIdx][j] = dgrid[tx][ty];
        }
    }

    for (let i = 0; i < M; ++i) bfs(i);

    // ---------- memoised minimax DP ----------
    const memo = Array.from({ length: 1 << N }, () =>
        Array.from({ length: M }, () => Array(2).fill(undefined))
    );

    function solve(mask, cur, turn) {
        if (mask === allMask) return 0;                     // no pawn left
        const cached = memo[mask][cur][turn];
        if (cached !== undefined) return cached;

        let best;
        if (turn === 0) {                                   // Alice – maximise
            best = -Infinity;
            for (let i = 0; i < N; ++i) {
                if (mask & (1 << i)) continue;             // already taken
                const cost = dist[cur][i + 1];
                const val = cost + solve(mask | (1 << i), i + 1, 1);
                if (val > best) best = val;
            }
        } else {                                            // Bob – minimise
            best = Infinity;
            for (let i = 0; i < N; ++i) {
                if (mask & (1 << i)) continue;
                const cost = dist[cur][i + 1];
                const val = cost + solve(mask | (1 << i), i + 1, 0);
                if (val < best) best = val;
            }
        }
        memo[mask][cur][turn] = best;
        return best;
    }

    return solve(0, 0, 0);
}

function countMonotonicPairs(nums) {
    const MOD = 1000000007n;
    const n = nums.length;
    const m = Math.max(...nums);

    // f[j] = number of ways for prefix ending with arr1[i] = j
    let f = new Array(m + 1).fill(0n);
    for (let j = 0; j <= nums[0]; j++) f[j] = 1n;

    for (let i = 1; i < n; i++) {
        // prefix sums of f (previous row), S[j] = sum_{j'=0}^{j} f[j']
        const S = new Array(m + 1).fill(0n);
        S[0] = f[0];
        for (let j = 1; j <= m; j++) S[j] = (S[j - 1] + f[j]) % MOD;

        const next = new Array(m + 1).fill(0n);
        const diff = nums[i - 1] - nums[i];
        for (let j = 0; j <= nums[i]; j++) {
            let k = Math.min(j, j + diff);
            if (k >= 0) {
                next[j] = S[k];
            }
        }
        f = next;
    }

    let ans = 0n;
    for (let j = 0; j <= nums[n - 1]; j++) ans = (ans + f[j]) % MOD;
    return Number(ans);
}

function maximizeScoreOfNumbersInRanges(start, d) {
    const n = start.length;
    if (n <= 1) return 0;
    const intervals = start.map(s => [s, s + d]).sort((a, b) => a[0] - b[0]);
    const minL = intervals[0][0];
    const maxR = intervals[n - 1][1];
    let lo = 0, hi = maxR - minL + 1;

    const feasible = (dist) => {
        let prev = intervals[0][0];
        for (let i = 1; i < n; i++) {
            const need = prev + dist;
            const [loI, hiI] = intervals[i];
            prev = loI > need ? loI : need;
            if (prev > hiI) return false;
        }
        return true;
    };

    while (lo < hi) {
        const mid = Math.floor((lo + hi) / 2);
        if (feasible(mid)) lo = mid + 1; else hi = mid;
    }
    return lo - 1;
}

function convertDateToBinary(date) {
    // split the date, convert each part to binary without leading zeros
    const parts = date.split('-');                     // ["yyyy","mm","dd"]
    const yearBin = parseInt(parts[0], 10).toString(2);
    const monthBin = parseInt(parts[1], 10).toString(2);
    const dayBin = parseInt(parts[2], 10).toString(2);
    return yearBin + '-' + monthBin + '-' + dayBin;
}

function findMaximumScore(nums) {
    const n = nums.length;
    let score = 0, maxSoFar = nums[0];
    for (let i = 0; i < n - 1; i++) {
        maxSoFar = Math.max(maxSoFar, nums[i]);
        score += maxSoFar;
    }
    return score;
}

var maxValue = function(nums, k) {
    const m = 1 << 7;
    const n = nums.length;
    const f = Array.from({ length: n + 1 }, () => Array.from({ length: k + 2 }, () => Array(m).fill(false)));
    f[0][0][0] = true;
    for (let i = 0; i < n; i++) {
        for (let j = 0; j <= k; j++) {
            for (let x = 0; x < m; x++) {
                if (f[i][j][x]) {
                    f[i + 1][j][x] = true;
                    f[i + 1][j + 1][x | nums[i]] = true;
                }
            }
        }
    }
    const g = Array.from({ length: n + 1 }, () => Array.from({ length: k + 2 }, () => Array(m).fill(false)));
    g[n][0][0] = true;
    for (let i = n; i > 0; i--) {
        for (let j = 0; j <= k; j++) {
            for (let y = 0; y < m; y++) {
                if (g[i][j][y]) {
                    g[i - 1][j][y] = true;
                    g[i - 1][j + 1][y | nums[i - 1]] = true;
                }
            }
        }
    }
    let ans = 0;
    for (let i = k; i <= n - k; i++) {
        for (let x = 0; x < m; x++) {
            if (f[i][k][x]) {
                for (let y = 0; y < m; y++) {
                    if (g[i][k][y]) ans = Math.max(ans, x ^ y);
                }
            }
        }
    }
    return ans;
};

function findTwoSneaky(nums) {
    const n = nums.length - 2;                 // original range size

    // mark occurrences by adding n at the index of each value
    for (let i = 0; i < nums.length; i++) {
        const idx = nums[i] % n;                // original value
        nums[idx] += n;                         // increase count for idx
    }

    const result = [];
    // indices whose count became 2 are the duplicated numbers
    for (let i = 0; i < n; i++) {
        if (Math.floor(nums[i] / n) === 2) {
            result.push(i);
        }
    }
    return result;
}

var maxPathLength = function(coordinates, k) {
    const n = coordinates.length;
    const points = coordinates.map((c,i) => [c[0], c[1], i]);
    const ysSet = new Set(points.map(p=>p[1]));
    const ys = Array.from(ysSet).sort((a,b)=>a-b);
    const yToRank = new Map();
    ys.forEach((y,i)=>yToRank.set(y, i+1));
    const maxRank = ys.length;
    class FenwickMax {
        constructor(size) { this.n=size; this.bit=new Array(size+1).fill(0); }
        update(idx, value) { while (idx<=this.n) { if (value>this.bit[idx]) this.bit[idx]=value; idx += idx&(-idx); } }
        query(idx) { let res=0; while (idx>0) { if (this.bit[idx]>res) res=this.bit[idx]; idx -= idx&(-idx); } return res; }
    }
    const pointsForward = points.slice().sort((a,b)=> a[0]-b[0] || b[1]-a[1]);
    const forward = new Array(n).fill(1);
    const bitFwd = new FenwickMax(maxRank);
    for (const [x,y,idx] of pointsForward) {
        const r = yToRank.get(y);
        const best = bitFwd.query(r-1);
        const dp = best+1;
        forward[idx] = dp;
        bitFwd.update(r, dp);
    }
    const pointsBackward = points.slice().sort((a,b)=> b[0]-a[0] || a[1]-b[1]);
    const backward = new Array(n).fill(1);
    const bitBwd = new FenwickMax(maxRank);
    for (const [x,y,idx] of pointsBackward) {
        const r = yToRank.get(y);
        const rev = maxRank - r + 1;
        const best = bitBwd.query(rev-1);
        const dp = best+1;
        backward[idx] = dp;
        bitBwd.update(rev, dp);
    }
    return forward[k] + backward[k] - 1;
};

function findSafeWalk(grid, health) {
    var m = grid.length, n = grid[0].length;
    var INF = 1e9;
    var dist = Array.from({ length: m }, () => Array(n).fill(INF));
    var dq = [];                         // deque for 0‑1 BFS
    var startCost = grid[0][0];
    if (health - startCost < 1) return false; // cannot survive the start cell
    dist[0][0] = startCost;
    dq.unshift([0, 0]);                  // push front

    var dirs = [[1,0],[-1,0],[0,1],[0,-1]];
    while (dq.length) {
        var [r, c] = dq.shift();         // pop front
        var cur = dist[r][c];
        // 0‑1 BFS: weight 0 cells go to front, weight 1 cells go to back
        for (var i = 0; i < 4; i++) {
            var nr = r + dirs[i][0], nc = c + dirs[i][1];
            if (nr < 0 || nr >= m || nc < 0 || nc >= n) continue;
            var nxt = cur + grid[nr][nc];
            if (nxt < dist[nr][nc] && nxt < health) {
                dist[nr][nc] = nxt;
                if (grid[nr][nc] === 0) dq.unshift([nr, nc]);
                else dq.push([nr, nc]);
            }
        }
    }
    return dist[m - 1][n - 1] <= health - 1;
}

function maxMultiplicationScore(a, b) {
    // dp[k] = best score after processing some prefix of b and picking k elements
    const dp = new Array(5).fill(-Infinity);
    dp[0] = 0;                       // base case: pick nothing

    for (let idx = 0; idx < b.length; idx++) {
        // update states backwards so each b[idx] is used at most once
        for (let k = 4; k >= 1; k--) {
            if (dp[k - 1] !== -Infinity) {
                const cand = dp[k - 1] + a[k - 1] * b[idx];
                if (cand > dp[k]) dp[k] = cand;   // keep the larger score
            }
        }
    }
    return dp[4];
}

function minimumSecondsToMakeMountainZero(mountainHeight, workerTimes) {
  const n = workerTimes.length;
  let maxTime = 0;
  for (let i = 0; i < n; i++) {
    const t = workerTimes[i];
    const candidate = t * mountainHeight * (mountainHeight + 1) / 2;
    if (candidate > maxTime) maxTime = candidate;
  }
  let low = 0;
  let high = maxTime;
  function canFinish(time) {
    let total = 0;
    for (let i = 0; i < n; i++) {
      const t = workerTimes[i];
      // solve t * x * (x + 1) / 2 <= time
      const disc = 1 + (8 * time) / t;
      const sqrtDisc = Math.sqrt(disc);
      let x = Math.floor((-1 + sqrtDisc) / 2);
      // correct possible rounding errors
      while (x > 0 && t * x * (x + 1) / 2 > time) x--;
      while (t * (x + 1) * (x + 2) / 2 <= time) x++;
      total += x;
      if (total >= mountainHeight) return true;
    }
    return total >= mountainHeight;
  }
  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    if (canFinish(mid)) {
      high = mid;
    } else {
      low = mid + 1;
    }
  }
  return low;
}

function minValidStrings(words, target) {
    // ---------- build trie ----------
    const root = { next: {} };
    for (const w of words) {
        let node = root;
        for (const ch of w) {
            if (!node.next[ch]) node.next[ch] = { next: {} };
            node = node.next[ch];
        }
    }

    const n = target.length;
    const INF = 1e9;
    const dp = new Array(n + 1).fill(INF);
    dp[0] = 0;

    // ---------- DP over target ----------
    for (let i = 0; i < n; ++i) {
        if (dp[i] === INF) continue;               // unreachable start
        let node = root;
        for (let j = i; j < n; ++j) {
            const ch = target[j];
            if (!node.next[ch]) break;             // no longer a valid prefix
            node = node.next[ch];
            // we have a valid prefix target[i..j]
            if (dp[j + 1] > dp[i] + 1) dp[j + 1] = dp[i] + 1;
        }
    }

    return dp[n] === INF ? -1 : dp[n];
}

var minValidStrings = function(words, target) {
