        for (let j=i; j<Math.min(n, i+maxLen); j++) {
            const ch = target[j];
            if (!(ch in node)) break;
            node = node[ch];
            if (dp[j+1] > dp[i]+1) dp[j+1] = dp[i]+1;
        }
    }
    return dp[n] === INF ? -1 : dp[n];
};

function isSpam(message, bannedWords) {
