function minElementAfterReplacement(nums) {
    // initialise answer with a large value
    let minVal = Infinity;

    // iterate over the array
    for (let i = 0; i < nums.length; i++) {
        let x = nums[i];
        let sum = 0;

        // compute digit sum of x
        while (x > 0) {
            sum += x % 10;
            x = Math.floor(x / 10);
        }

        // update minimum with the replaced value
        if (sum < minVal) minVal = sum;
    }

    return minVal;
}

function countSubstringsThatCanBeRearrangedToContainAStringII(word1, word2) {
    const n = word1.length, m = word2.length;
    if (m === 0) return n * (n + 1) / 2;
    if (m > n) return 0;
    const need = new Array(26).fill(0);
    const have = new Array(26).fill(0);
    for (const c of word2) need[c.charCodeAt(0) - 97]++;
    let missing = need.reduce((a, b) => a + b, 0);
    let ans = 0, R = 0;
    const base = 97;
    for (let L = 0; L < n; L++) {
        while (R < n && missing) {
            const idx = word1.charCodeAt(R) - base;
            if (have[idx] < need[idx]) missing--;
            have[idx]++;
            R++;
        }
        if (!missing) ans += n - (R - 1);
        else break;
        const idxL = word1.charCodeAt(L) - base;
        if (have[idxL] <= need[idxL]) missing++;
        have[idxL]--;
    }
    return ans;
}

var validSequence = function(word1, word2) {
