    const last = new Array(m).fill(-1);
    let i = n - 1, j = m - 1;
    while (i >= 0 && j >= 0) {
        if (word1[i] === word2[j]) last[j--] = i;
        i--;
    }
    const ans = [];
    let canSkip = true;
    j = 0;
    for (i = 0; i < n; i++) {
        if (j === m) break;
        if (word1[i] === word2[j]) {
            ans.push(i); j++;
        } else if (canSkip && (j === m - 1 || i < last[j + 1])) {
            canSkip = false;
            ans.push(i); j++;
        }
    }
    return j === m ? ans : [];
};

function countSubstringsThatCanBeRearrangedToContainAStringI(word1, word2) {
    const n = word1.length, m = word2.length;
