    if (m > n) return 0;
    const need = new Array(26).fill(0);
    for (const c of word2) need[c.charCodeAt(0) - 97]++;
    const diff = need.map(v => -v);
    let deficit = diff.filter(v => v < 0).length;
    let ans = 0, r = 0;
    for (let l = 0; l < n; l++) {
        while (r < n && deficit > 0) {
            const idx = word1.charCodeAt(r) - 97;
            diff[idx]++;
            if (diff[idx] === 0) deficit--;
            r++;
        }
        if (deficit > 0) break;
        ans += n - r + 1;
