function countSubstrings(word, k) {
    function atMost(K) {
        if (K < 0) return 0;
        const n = word.length;
        const last = [-1, -1, -1, -1, -1]; // a, e, i, o, u
        let left = 0;
        let cons = 0;
        let total = 0;
        for (let r = 0; r < n; ++r) {
            const ch = word[r];
            if (ch === 'a') last[0] = r;
            else if (ch === 'e') last[1] = r;
            else if (ch === 'i') last[2] = r;
            else if (ch === 'o') last[3] = r;
            else if (ch === 'u') last[4] = r;
            else cons++;
            while (cons > K) {
                const cl = word[left];
                if (cl !== 'a' && cl !== 'e' && cl !== 'i' && cl !== 'o' && cl !== 'u') {
                    cons--;
                }
                left++;
            }
            const minLast = Math.min(...last);
            if (minLast >= left) {
                total += (minLast - left + 1);
            }
        }
        return total;
    }
    return atMost(k) - atMost(k - 1);
}

function removeMethods(n, k, invocations) {
    // build adjacency list for outgoing edges
    const adj = Array.from({ length: n }, () => []);
    for (const [a, b] of invocations) adj[a].push(b);

    // find all suspicious methods reachable from k
    const suspicious = new Array(n).fill(false);
    const stack = [k];
    suspicious[k] = true;                     // start from k
    while (stack.length) {
        const cur = stack.pop();
        for (const nxt of adj[cur]) {
            if (!suspicious[nxt]) {
                suspicious[nxt] = true;
                stack.push(nxt);
            }
        }
    }

    // check for any edge from outside into the suspicious set
    for (const [a, b] of invocations) {
        if (suspicious[b] && !suspicious[a]) {
            // removal impossible → return all methods
            const all = [];
            for (let i = 0; i < n; ++i) all.push(i);
            return all;
        }
    }

    // removal possible → return methods not in the suspicious set
    const remaining = [];
    for (let i = 0; i < n; ++i) {
        if (!suspicious[i]) remaining.push(i);
    }
    return remaining;
}

function constructMinimumBitwiseArray(nums) {
    const ans = [];
    for (let num of nums) {
        if ((num & 1) === 0) {
            ans.push(-1);
            continue;
        }
        let t = 0;
        while ((num >> t) & 1) {
            t++;
        }
        const high = num & (~((1 << t) - 1));
        const lowerMask = t > 1 ? ((1 << (t - 1)) - 1) : 0;
        ans.push(high | lowerMask);
    }
    return ans;
}

function maxBinaryConcat(nums) {
  // helper: number of bits of a non‑negative integer
  function bitLen(v) {
    return v === 0 ? 1 : Math.floor(Math.log2(v)) + 1;
  }

  const [a, b, c] = nums;
  const la = bitLen(a), lb = bitLen(b), lc = bitLen(c);

  // compute value for a given order (x,y,z)
  function value(x, lx, y, ly, z, lz) {
    return x * (2 ** (ly + lz)) + y * (2 ** lz) + z;
  }

  // evaluate the six permutations
  let best = 0;
  best = Math.max(best, value(a, la, b, lb, c, lc));
  best = Math.max(best, value(a, la, c, lc, b, lb));
  best = Math.max(best, value(b, lb, a, la, c, lc));
  best = Math.max(best, value(b, lb, c, lc, a, la));
  best = Math.max(best, value(c, lc, a, la, b, lb));
  best = Math.max(best, value(c, lc, b, lb, a, la));

  return best;
}

function constructGridLayout(n, edges) {
    const graph = Array.from({length: n}, () => []);
    for (const [u, v] of edges) {
        graph[u].push(v);
        graph[v].push(u);
    }

    let corner = 0;
    for (let i = 1; i < n; i++) if (graph[i].length < graph[corner].length) corner = i;

    const seen = new Set([corner]);
    const cornerDegree = graph[corner].length;
    const row = [corner];
    while (row.length === 1 || graph[row[row.length - 1]].length === cornerDegree + 1) {
        const last = row[row.length - 1];
        graph[last].sort((a, b) => graph[a].length - graph[b].length);
        let found = false;
        for (const v of graph[last]) {
            if (!seen.has(v) && (graph[v].length === cornerDegree || graph[v].length === cornerDegree + 1)) {
                row.push(v);
                seen.add(v);
                found = true;
                break;
            }
        }
        if (!found) break;
    }

    const cols = row.length;
    const rows = n / cols;
    const ans = Array.from({length: rows}, () => new Array(cols).fill(0));
    ans[0] = row;
    for (let i = 1; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            for (const v of graph[ans[i-1][j]]) {
                if (!seen.has(v)) {
                    ans[i][j] = v;
                    seen.add(v);
                    break;
                }
            }
        }
    }
    return ans;
}

function constructMinimumBitwiseArray(nums) {
  const ans = [];
