    if (num === 2) {
      ans.push(-1);
      continue;
    }
    let cnt = 0;
    while (((num >> cnt) & 1) === 1) cnt++;
    const bitPos = cnt - 1;
    const mask = 1 << bitPos;
    const x = num & ~mask;
    ans.push((x | (x + 1)) === num ? x : -1);
  }
  return ans;
}

function findXSumAllKLongSubarrays(nums, k, x) {
  const n = nums.length;
  const maxVal = 50;
  const freq = new Array(maxVal + 1).fill(0);
  const res = new Array(n - k + 1);
  for (let i = 0; i < k; i++) freq[nums[i]]++;
  res[0] = computeWindowSum(freq, x);
  for (let i = 1; i <= n - k; i++) {
    const outVal = nums[i - 1];
    const inVal = nums[i + k - 1];
    freq[outVal]--;
    freq[inVal]++;
    res[i] = computeWindowSum(freq, x);
  }
  return res;
}
function computeWindowSum(freq, x) {
  const entries = [];
  let total = 0;
  for (let v = 1; v < freq.length; v++) {
    const f = freq[v];
    if (f) {
      entries.push([f, v]);
      total += f * v;
    }
  }
  if (entries.length <= x) return total;
  entries.sort((a, b) => {
    if (b[0] !== a[0]) return b[0] - a[0];
    return b[1] - a[1];
  });
  let sum = 0;
  for (let i = 0; i < x; i++) sum += entries[i][0] * entries[i][1];
  return sum;
}

function kthLargestPerfectSubtreeSize(root, k) {
    if (k <= 0) return -1;               // invalid k

    const heap = [];                     // min‑heap of at most k sizes

    // push a value and keep min‑heap property
    function heapPush(val) {
        heap.push(val);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p] <= heap[i]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]];
            i = p;
        }
    }

    // pop the smallest element (root of min‑heap)
    function heapPop() {
        if (heap.length === 1) return heap.pop();
        const top = heap[0];
        heap[0] = heap.pop();
        let i = 0;
        while (true) {
            const l = i * 2 + 1,
                  r = i * 2 + 2;
            let smallest = i;
            if (l < heap.length && heap[l] < heap[smallest]) smallest = l;
            if (r < heap.length && heap[r] < heap[smallest]) smallest = r;
            if (smallest === i) break;
            [heap[i], heap[smallest]] = [heap[smallest], heap[i]];
            i = smallest;
        }
        return top;
    }

    // record a perfect subtree size, keep only k largest sizes
    function addSize(sz) {
        heapPush(sz);
        if (heap.length > k) heapPop();   // discard smallest when exceeding k
    }

    // post‑order DFS returning height, size and perfect‑flag
    function dfs(node) {
        if (!node) return { height: -1, size: 0, perfect: true }; // empty subtree
        const left = dfs(node.left);
        const right = dfs(node.right);
        // main logic: a node forms a perfect subtree iff both children are perfect and have equal height
        if (left.perfect && right.perfect && left.height === right.height) {
            const height = left.height + 1;
            const size = left.size + right.size + 1;
            addSize(size);                 // store this perfect subtree size
            return { height, size, perfect: true };
        }
        return { height: 0, size: 0, perfect: false };
    }

    dfs(root);
    return heap.length < k ? -1 : heap[0]; // heap[0] is the kth largest (smallest among top k)
}

function sortedGCDPairQueries(nums, queries) {
    if (!nums.length) return [];
    const maxVal = Math.max(...nums);
    const freq = new Array(maxVal + 1).fill(0);
    for (const v of nums) freq[v]++;

    const cnt = new Array(maxVal + 1).fill(0);
    for (let d = 1; d <= maxVal; d++) {
        let s = 0;
        for (let m = d; m <= maxVal; m += d) s += freq[m];
        cnt[d] = s;
    }

    const exact = cnt;
    for (let d = maxVal; d >= 1; d--) {
        let total = cnt[d] * (cnt[d] - 1) / 2;
        let md = d * 2;
        while (md <= maxVal) { total -= exact[md]; md += d; }
        exact[d] = total;
    }

    const prefix = new Array(maxVal + 1).fill(0);
    let cum = 0;
    for (let d = 1; d <= maxVal; d++) { cum += exact[d]; prefix[d] = cum; }

    const bisectLeft = (arr, val, lo0, hi0) => {
        let lo = lo0, hi = hi0;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (arr[mid] < val) lo = mid + 1; else hi = mid;
        }
        return lo;
    };

    const res = [];
    for (const q of queries) {
        const target = q + 1;
        const d = bisectLeft(prefix, target, 1, maxVal + 1);
        res.push(d);
    }
    return res;
}

function maxRemovals(source, pattern, targetIndices) {
    const n = source.length, m = pattern.length;
    const isTarget = new Array(n).fill(false);
    for (const t of targetIndices) isTarget[t] = true;
    const INF = Infinity;
    // dp[j] = minimum number of target-indices that MUST be kept (used) to match the
    // first j characters of pattern as a subsequence of source scanned so far
    let dp = new Array(m + 1).fill(INF);
    dp[0] = 0;
    for (let i = 0; i < n; i++) {
        for (let j = Math.min(i + 1, m); j >= 1; j--) {
            if (source[i] === pattern[j - 1]) {
                const cost = dp[j - 1] + (isTarget[i] ? 1 : 0);
                if (cost < dp[j]) dp[j] = cost;
            }
        }
    }
    return targetIndices.length - dp[m];
}

function countWinningSequences(s) {
    const MOD = 1000000007;
    const n = s.length;
    const offset = n;
    const map = { 'F': 0, 'W': 1, 'E': 2 };
    const alice = new Array(n);
    for (let i = 0; i < n; i++) alice[i] = map[s[i]];
    const beats = [2, 0, 1]; // 0(F) beats 2(E), 1(W) beats 0(F), 2(E) beats 1(W)

    const size = 2 * n + 1;
    let dpPrev = Array.from({ length: 3 }, () => new Uint32Array(size));
    // first round
    for (let cur = 0; cur < 3; cur++) {
        let contrib = 0;
        if (cur === alice[0]) contrib = 0;
        else if (beats[cur] === alice[0]) contrib = 1;
        else contrib = -1;
        const idx = contrib + offset;
        dpPrev[cur][idx] = (dpPrev[cur][idx] + 1) % MOD;
    }

    for (let i = 1; i < n; i++) {
        const dpCurr = Array.from({ length: 3 }, () => new Uint32Array(size));
        for (let prev = 0; prev < 3; prev++) {
            const row = dpPrev[prev];
            for (let idx = 0; idx < size; idx++) {
                const ways = row[idx];
                if (!ways) continue;
                const oldScore = idx - offset;
                for (let cur = 0; cur < 3; cur++) {
                    if (cur === prev) continue;
                    let contrib = 0;
                    if (cur === alice[i]) contrib = 0;
                    else if (beats[cur] === alice[i]) contrib = 1;
                    else contrib = -1;
                    const newScore = oldScore + contrib;
                    const newIdx = newScore + offset;
                    dpCurr[cur][newIdx] = (dpCurr[cur][newIdx] + ways) % MOD;
                }
            }
        }
        dpPrev = dpCurr;
    }

    let ans = 0;
    for (let prev = 0; prev < 3; prev++) {
        const row = dpPrev[prev];
        for (let idx = offset + 1; idx < size; idx++) {
            ans = (ans + row[idx]) % MOD;
        }
    }
    return ans;
}

function findXSumAllKLongSubarrays(nums, k, x) {
    const n = nums.length;
    const result = [];
    for (let i = 0; i <= n - k; i++) {
        const freq = new Map();
        let windowSum = 0;
        for (let idx = i; idx < i + k; idx++) {
            const v = nums[idx];
            windowSum += v;
            freq.set(v, (freq.get(v) || 0) + 1);
        }
        if (freq.size <= x) {
            result.push(windowSum);
        } else {
            const items = [...freq.entries()].sort((a, b) => (b[1] - a[1]) || (b[0] - a[0]));
            let xSum = 0;
            for (let idx = 0; idx < x; idx++) xSum += items[idx][0] * items[idx][1];
            result.push(xSum);
        }
    }
    return result;
}

function findTheNumberOfPossibleWaysForAnEvent(n, x, y) {
    const MOD = 1000000007n;
    const maxN = Math.max(n, x);
    const fact = new Array(maxN + 1).fill(1n);
    for (let i = 1; i <= maxN; i++) fact[i] = (fact[i - 1] * BigInt(i)) % MOD;
    const modpow = (base, exp, mod) => {
        base %= mod; let result = 1n;
        while (exp > 0n) { if (exp & 1n) result = (result * base) % mod; base = (base * base) % mod; exp >>= 1n; }
        return result;
    };
    const invFact = new Array(maxN + 1).fill(1n);
    invFact[maxN] = modpow(fact[maxN], MOD - 2n, MOD);
    for (let i = maxN; i >= 1; i--) invFact[i - 1] = (invFact[i] * BigInt(i)) % MOD;

    const C = (N, K) => {
        if (K < 0 || K > N) return 0n;
        return (fact[N] * invFact[K] % MOD) * invFact[N - K] % MOD;
    };

    let stir = new Array(n + 1).fill(0n);
    stir[0] = 1n;
    for (let i = 1; i <= n; i++) {
        const nxt = new Array(n + 1).fill(0n);
        for (let j = 1; j <= i; j++) nxt[j] = (BigInt(j) * stir[j] + stir[j - 1]) % MOD;
        stir = nxt;
    }

    const limit = Math.min(n, x);
    const powY = new Array(limit + 1).fill(1n);
    for (let k = 1; k <= limit; k++) powY[k] = (powY[k - 1] * BigInt(y)) % MOD;

    let ans = 0n;
    for (let k = 1; k <= limit; k++) {
        let ways = C(x, k);
        ways = (ways * fact[k]) % MOD;
        ways = (ways * stir[k]) % MOD;
        ways = (ways * powY[k]) % MOD;
        ans = (ans + ways) % MOD;
    }
    return Number(ans);
}

function stringSequence(target) {
    const result = [];
