        let c = 'a';
        while (c !== ch) {
            c = String.fromCharCode(c.charCodeAt(0)+1);
            cur = cur.slice(0,-1) + c;
            result.push(cur);
        }
    }
    return result;
}

function minimumDivisionOperationsToMakeArrayNonDecreasing(nums) {
    if (!nums.length) return 0;
    const maxVal = Math.max(...nums);
    const limit = maxVal;
    const spf = new Array(limit + 1).fill(0);
    spf[1] = 1;
    const primes = [];
    for (let i = 2; i <= limit; i++) {
        if (spf[i] === 0) { spf[i] = i; primes.push(i); }
        for (const p of primes) {
            if (p * i > limit) break;
            spf[p * i] = p;
            if (p === spf[i]) break;
        }
    }

    const INF = 1e9;
    let dp0 = 0;
    const first = nums[0];
    const firstSpf = first === 1 ? 1 : spf[first];
    let dp1 = firstSpf !== first ? 1 : INF;
    let prevOrig = first, prevSpf = firstSpf;

    for (let i = 1; i < nums.length; i++) {
        const cur = nums[i];
        const curSpf = cur === 1 ? 1 : spf[cur];
        const curHasSpf = curSpf !== cur;

        let ndp0 = INF, ndp1 = INF;

        if (dp0 < INF) {
            if (prevOrig <= cur) ndp0 = dp0;
            if (curHasSpf && prevOrig <= curSpf) ndp1 = dp0 + 1;
        }
        if (dp1 < INF) {
            if (prevSpf <= cur) ndp0 = Math.min(ndp0, dp1);
            if (curHasSpf && prevSpf <= curSpf) ndp1 = Math.min(ndp1, dp1 + 1);
        }

        dp0 = ndp0; dp1 = ndp1;
        prevOrig = cur; prevSpf = curSpf;
    }

    const ans = Math.min(dp0, dp1);
    return ans >= INF ? -1 : ans;
}

function countOriginalStrings(word) {
    let n = word.length;
    let groups = 0;                     // count blocks
    for (let i = 0; i < n; i++) {
        if (i === 0 || word[i] !== word[i - 1]) {
            groups++;                  // start of a new block
        }
    }
    return n - groups + 1;              // formula derived above
}

function numberOfSubstrings(s, k) {
    const n = s.length;
    // total substrings - substrings where every char has freq < k
    const total = n*(n+1)/2;
    const freq = new Array(26).fill(0);
    let left = 0, invalidCount = 0;
    for (let right = 0; right < n; right++) {
        freq[s.charCodeAt(right)-97]++;
        while (freq[s.charCodeAt(right)-97] >= k) {
            freq[s.charCodeAt(left)-97]--;
            left++;
        }
        invalidCount += right - left + 1;
    }
    return total - invalidCount;
}

var findAnswer = function(parent, s) {
    const n = parent.length;
    const children = Array.from({length:n}, () => []);
    for (let i=1;i<n;i++) children[parent[i]].push(i);
    const answer = new Array(n).fill(false);
    function dfs(u) {
        let mask = 1 << (s.charCodeAt(u) - 97);
        for (const v of children[u]) mask ^= dfs(v);
        answer[u] = mask === 0 || (mask & (mask-1)) === 0;
        return mask;
    }
    dfs(0);
    return answer;
};

function maxFactorScore(nums) {
    const n = nums.length;
    if (n === 0) return 0;

    // ---------- helper functions ----------
    function gcd(a, b) {                     // Euclidean algorithm for BigInt
        while (b !== 0n) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
    function lcm(a, b) {                     // lcm = a / gcd(a,b) * b
        if (a === 0n || b === 0n) return 0n;
        return (a / gcd(a, b)) * b;
    }

    // ---------- build prefix arrays ----------
    const prefG = new Array(n + 1);
    const prefL = new Array(n + 1);
    prefG[0] = 0n;            // neutral for gcd
    prefL[0] = 1n;            // neutral for lcm
    for (let i = 0; i < n; ++i) {
        const v = BigInt(nums[i]);
        prefG[i + 1] = gcd(prefG[i], v);
        prefL[i + 1] = lcm(prefL[i], v);
    }

    // ---------- build suffix arrays ----------
    const suffG = new Array(n + 1);
    const suffL = new Array(n + 1);
    suffG[n] = 0n;
    suffL[n] = 1n;
    for (let i = n - 1; i >= 0; --i) {
        const v = BigInt(nums[i]);
        suffG[i] = gcd(suffG[i + 1], v);
        suffL[i] = lcm(suffL[i + 1], v);
    }

    // ---------- evaluate all possibilities ----------
    let best = 0n;
    // case: delete nothing
    best = prefG[n] * prefL[n];

    for (let i = 0; i < n; ++i) {               // delete element i
        const g = gcd(prefG[i], suffG[i + 1]);   // GCD of remaining elements
        const l = lcm(prefL[i], suffL[i + 1]);   // LCM of remaining elements
        const score = g * l;
        if (score > best) best = score;
    }

    // convert back to Number when safe, otherwise keep BigInt
    return best <= Number.MAX_SAFE_INTEGER ? Number(best) : best;
}

function countPairsWithEqualGcd(nums) {
  const MOD = 1000000007;
  const MAXV = 200;
  const gcd = (a, b) => {
    while (b !== 0) {
      const t = a % b;
      a = b;
      b = t;
    }
    return a;
  };
  let dp = Array.from({ length: MAXV + 1 }, () => Array(MAXV + 1).fill(0));
  dp[0][0] = 1;
  for (const x of nums) {
    const ndp = Array.from({ length: MAXV + 1 }, () => Array(MAXV + 1).fill(0));
    for (let g1 = 0; g1 <= MAXV; ++g1) {
      const row = dp[g1];
      for (let g2 = 0; g2 <= MAXV; ++g2) {
        const val = row[g2];
        if (!val) continue;
        // ignore the element
        ndp[g1][g2] = (ndp[g1][g2] + val) % MOD;
        // assign to first subsequence
        const ng1 = g1 === 0 ? x : gcd(g1, x);
        ndp[ng1][g2] = (ndp[ng1][g2] + val) % MOD;
        // assign to second subsequence
        const ng2 = g2 === 0 ? x : gcd(g2, x);
        ndp[g1][ng2] = (ndp[g1][ng2] + val) % MOD;
      }
    }
    dp = ndp;
  }
  let ans = 0;
  for (let g = 1; g <= MAXV; ++g) {
    ans = (ans + dp[g][g]) % MOD;
  }
  return ans;
}

function findSubtreeSizes(parent, s) {
  const n = parent.length;
  const origChildren = Array.from({ length: n }, () => []);
  for (let i = 1; i < n; i++) {
    origChildren[parent[i]].push(i);
  }

  const newParent = new Array(n).fill(0);
  newParent[0] = -1;

  const last = new Int32Array(26);
  for (let i = 0; i < 26; i++) last[i] = -1;

  const charIdx = new Uint8Array(n);
  for (let i = 0; i < n; i++) charIdx[i] = s.charCodeAt(i) - 97;

  const stack = [{ node: 0, idx: 0, entered: false, prevLast: -1 }];
  while (stack.length) {
    const top = stack[stack.length - 1];
    if (!top.entered) {
      top.entered = true;
      const c = charIdx[top.node];
      top.prevLast = last[c];
      last[c] = top.node;
    } else if (top.idx < origChildren[top.node].length) {
      const child = origChildren[top.node][top.idx++];
      const c = charIdx[child];
      const anc = last[c];
      newParent[child] = anc !== -1 ? anc : top.node;
      stack.push({ node: child, idx: 0, entered: false, prevLast: -1 });
    } else {
      const c = charIdx[top.node];
      last[c] = top.prevLast;
      stack.pop();
    }
  }

  const newChildren = Array.from({ length: n }, () => []);
  for (let i = 1; i < n; i++) {
    newChildren[newParent[i]].push(i);
  }

  const answer = new Array(n).fill(1);
  const stack2 = [{ node: 0, visited: false }];
  while (stack2.length) {
    const cur = stack2.pop();
    if (!cur.visited) {
      stack2.push({ node: cur.node, visited: true });
      for (const child of newChildren[cur.node]) {
        stack2.push({ node: child, visited: false });
      }
    } else {
      for (const child of newChildren[cur.node]) {
        answer[cur.node] += answer[child];
      }
    }
  }
  return answer;
}

function originalStringCount(word, k) {
    const MOD = 1000000007;
    const n = word.length;
    const groups = [];
    let i = 0;
    while (i < n) {
        let j = i;
        while (j < n && word[j] === word[i]) j++;
        groups.push(j - i);
        i = j;
    }
    let totalWays = 1;
    for (const g of groups) totalWays = (totalWays * g) % MOD;

    let dp = new Array(k).fill(0);
    let ndp = new Array(k).fill(0);
    dp[0] = 1;

    for (const g of groups) {
        const limit = g < k ? g : k - 1;
        const pref = new Array(k).fill(0);
        pref[0] = dp[0];
        for (let idx = 1; idx < k; idx++) {
            let s = pref[idx-1] + dp[idx];
            if (s >= MOD) s -= MOD;
            pref[idx] = s;
        }
        ndp[0] = 0;
        for (let t = 1; t < k; t++) {
            let left = t - limit;
            if (left < 0) left = 0;
            let sum_ = pref[t-1];
            if (left > 0) {
                sum_ -= pref[left-1];
                if (sum_ < 0) sum_ += MOD;
            }
            ndp[t] = sum_;
        }
        [dp, ndp] = [ndp, dp];
    }

    let lessThanK = 0;
    for (const val of dp) {
        lessThanK += val;
        if (lessThanK >= MOD) lessThanK -= MOD;
    }
    let ans = (totalWays - lessThanK) % MOD;
    if (ans < 0) ans += MOD;
    return ans;
}

function maxScore(n, k, stayScore, travelScore) {
  let dp = new Array(n).fill(0);
  for (let day = 0; day < k; day++) {
    const ndp = new Array(n).fill(-Infinity);
    for (let city = 0; city < n; city++) {
      // stay
      ndp[city] = Math.max(ndp[city], dp[city] + stayScore[day][city]);
    }
    for (let from = 0; from < n; from++) {
      for (let to = 0; to < n; to++) {
        if (to === from) continue;
        ndp[to] = Math.max(ndp[to], dp[from] + travelScore[from][to]);
      }
    }
    dp = ndp;
  }
  return Math.max(...dp);
}

function totalCharactersAfterTransformations(s, t) {
    const MOD = 1000000007;
    let vowelCount = 0;
    for (let i = 0; i < s.length; i++) {
        const ch = s.charCodeAt(i);
        if (ch === 97 || ch === 101 || ch === 105 || ch === 111 || ch === 117) {
            vowelCount++;
        }
    }
    const result = (BigInt(s.length) + BigInt(vowelCount) * BigInt(t)) % BigInt(MOD);
    return Number(result);
}

function isBalanced(num) {
    let evenSum = 0, oddSum = 0;
    for (let i = 0; i < num.length; i++) {
        const digit = num.charCodeAt(i) - 48; // convert char to numeric value
        if (i % 2 === 0) evenSum += digit; else oddSum += digit; // main logic
    }
    return evenSum === oddSum;
}

function totalCharactersInStringAfterTransformationsII(s, t, nums) {
    const MOD = 1000000007n;
    const SIZE = 26;

    const multiplyMatrix = (A, B) => {
        const C = Array.from({length: SIZE}, () => new Array(SIZE).fill(0n));
        for (let i = 0; i < SIZE; i++) {
            for (let k = 0; k < SIZE; k++) {
                const aik = A[i][k];
                if (aik) {
                    for (let j = 0; j < SIZE; j++) C[i][j] = (C[i][j] + aik * B[k][j]) % MOD;
                }
            }
        }
        return C;
    };
    const multiplyMatrixVector = (A, v) => {
        const res = new Array(SIZE).fill(0n);
        for (let i = 0; i < SIZE; i++) {
            let s = 0n;
            for (let j = 0; j < SIZE; j++) s = (s + A[i][j] * v[j]) % MOD;
            res[i] = s;
        }
        return res;
    };

    const A = Array.from({length: SIZE}, () => new Array(SIZE).fill(0n));
    for (let c = 0; c < SIZE; c++) {
        const cnt = nums[c];
        for (let d = 1; d <= cnt; d++) {
            const nxt = (c + d) % SIZE;
            A[c][nxt] = (A[c][nxt] + 1n) % MOD;
        }
    }

    let vec = new Array(SIZE).fill(1n);
    let cur = A;
    let exp = t;
    while (exp) {
        if (exp & 1) vec = multiplyMatrixVector(cur, vec);
        cur = multiplyMatrix(cur, cur);
        exp >>= 1;
    }

    let ans = 0n;
    for (const ch of s) ans = (ans + vec[ch.charCodeAt(0) - 97]) % MOD;
    return Number(ans);
}

function findMinimumTimeToReachLastRoomII(moveTime) {
    const n = moveTime.length, m = moveTime[0].length;
    const INF = 1e18;
    const dist0 = Array.from({length: n}, () => new Array(m).fill(INF));
    const dist1 = Array.from({length: n}, () => new Array(m).fill(INF));
    dist0[0][0] = 0;

    const less = (a, b) => a[0] - b[0];
    const heap = [[0, 0, 0, 0]];
    const push = (item) => { heap.push(item); let i = heap.length - 1; while (i > 0) { const p = (i - 1) >> 1; if (heap[i][0] < heap[p][0]) { [heap[i], heap[p]] = [heap[p], heap[i]]; i = p; } else break; } };
    const pop = () => { const top = heap[0]; const last = heap.pop(); if (heap.length) { heap[0] = last; let i = 0; while (true) { let l=2*i+1,r=2*i+2,s=i; if (l<heap.length && heap[l][0]<heap[s][0]) s=l; if (r<heap.length && heap[r][0]<heap[s][0]) s=r; if (s===i) break; [heap[i],heap[s]]=[heap[s],heap[i]]; i=s; } } return top; };

    const di = [-1, 1, 0, 0], dj = [0, 0, -1, 1];

    while (heap.length) {
        const [cur, i, j, par] = pop();
        if (par === 0) { if (cur !== dist0[i][j]) continue; }
        else { if (cur !== dist1[i][j]) continue; }
        const moveCost = par === 0 ? 1 : 2;
        const npar = 1 - par;
        for (let d = 0; d < 4; d++) {
            const ni = i + di[d], nj = j + dj[d];
            if (!(ni >= 0 && ni < n && nj >= 0 && nj < m)) continue;
            const start = Math.max(cur, moveTime[ni][nj]);
            const arrival = start + moveCost;
            if (npar === 0) {
                if (arrival < dist0[ni][nj]) { dist0[ni][nj] = arrival; push([arrival, ni, nj, npar]); }
            } else {
                if (arrival < dist1[ni][nj]) { dist1[ni][nj] = arrival; push([arrival, ni, nj, npar]); }
            }
        }
    }
    return Math.min(dist0[n - 1][m - 1], dist1[n - 1][m - 1]);
}

function findMinimumTimeToReachLastRoomI(moveTime) {
    const n = moveTime.length, m = moveTime[0].length;
    const INF = 1e19;
    const dist = Array.from({length: n}, () => new Array(m).fill(INF));
    dist[0][0] = 0;

    const heap = [[0, 0, 0]];
    const push = (item) => { heap.push(item); let i = heap.length - 1; while (i > 0) { const p = (i - 1) >> 1; if (heap[i][0] < heap[p][0]) { [heap[i], heap[p]] = [heap[p], heap[i]]; i = p; } else break; } };
    const pop = () => { const top = heap[0]; const last = heap.pop(); if (heap.length) { heap[0] = last; let i = 0; while (true) { let l=2*i+1,r=2*i+2,s=i; if (l<heap.length && heap[l][0]<heap[s][0]) s=l; if (r<heap.length && heap[r][0]<heap[s][0]) s=r; if (s===i) break; [heap[i],heap[s]]=[heap[s],heap[i]]; i=s; } } return top; };

    const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
    while (heap.length) {
        const [t, x, y] = pop();
        if (t !== dist[x][y]) continue;
        if (x === n - 1 && y === m - 1) break;
        const nt = t + 1;
        for (const [dx, dy] of dirs) {
            const nx = x + dx, ny = y + dy;
            if (nx >= 0 && nx < n && ny >= 0 && ny < m) {
                const arrive = Math.max(nt, moveTime[nx][ny] + 1);
                if (arrive < dist[nx][ny]) { dist[nx][ny] = arrive; push([arrive, nx, ny]); }
            }
        }
    }
    return dist[n - 1][m - 1];
}

function smallestNumber(n, t) {
    for (let x = n; ; x++) {
        let prod = 1;
        for (const ch of String(x)) prod *= Number(ch);
        if (prod % t === 0) return x;
