function countKReducible(s, k) {
    const MOD = 1000000007;
    const L = s.length;

    // precompute popcount steps for values up to L
    const steps = new Array(L + 1).fill(0);
    const pop = (x) => {
        let cnt = 0;
        while (x) {
            cnt += x & 1;
            x >>>= 1;
        }
        return cnt;
    };
    steps[1] = 0;
    for (let i = 2; i <= L; i++) {
        steps[i] = 1 + steps[pop(i)];
    }

    // set of popcounts that need less than k total operations
    const good = [];
    for (let c = 1; c <= L; c++) {
        if (steps[c] < k) good.push(c);
    }

    // binomial coefficients C[n][r] modulo MOD
    const C = Array.from({ length: L + 1 }, () => new Array(L + 1).fill(0));
    for (let n = 0; n <= L; n++) {
        C[n][0] = C[n][n] = 1;
        for (let r = 1; r < n; r++) {
            C[n][r] = (C[n - 1][r - 1] + C[n - 1][r]) % MOD;
        }
    }

    // count numbers < n with exact popcount = target
    const countWithPop = (target) => {
        let ans = 0;
        let onesSoFar = 0;
        for (let i = 0; i < L; i++) {
            if (s[i] === '1') {
                const rem = L - i - 1;
                const need = target - onesSoFar;
                if (need >= 0 && need <= rem) {
                    ans = (ans + C[rem][need]) % MOD;
                }
                onesSoFar++;
                if (onesSoFar > target) break;
            }
        }
        // the number n itself is not counted (we need < n)
        return ans;
    };

    let result = 0;
    for (const c of good) {
        result = (result + countWithPop(c)) % MOD;
    }
    return result;
}

