function shiftDistanceBetweenTwoStrings(s, t, nextCost, previousCost) {
    const n = s.length;
    const prefNext = new Array(27).fill(0);
    const prefPrev = new Array(27).fill(0);
    for (let i = 0; i < 26; i++) {
        prefNext[i + 1] = prefNext[i] + nextCost[i];
        prefPrev[i + 1] = prefPrev[i] + previousCost[i];
    }

    let total = 0;
    const base = 'a'.charCodeAt(0);
    for (let i = 0; i < n; i++) {
        const a = s.charCodeAt(i) - base;
        const b = t.charCodeAt(i) - base;

        let forward;
        if (a <= b) forward = prefNext[b] - prefNext[a];
        else forward = (prefNext[26] - prefNext[a]) + prefNext[b];

        let backward;
        if (a >= b) backward = prefPrev[a + 1] - prefPrev[b + 1];
        else backward = prefPrev[a + 1] + (prefPrev[26] - prefPrev[b + 1]);

        total += Math.min(forward, backward);
    }
    return total;
}

function minimizeMaximumDifference(nums) {
