            if (d > maxKnown) maxKnown = d;
        }
        if (nums[i] === -1) {
            if (i > 0 && nums[i - 1] !== -1) {
                const v = nums[i - 1];
                if (v < low) low = v;
                if (v > high) high = v;
            }
            if (i + 1 < n && nums[i + 1] !== -1) {
                const v = nums[i + 1];
                if (v < low) low = v;
                if (v > high) high = v;
            }
        }
    }
    if (low === Infinity) return 0;
    const need = Math.ceil((high - low) / 2);
    return Math.max(maxKnown, need);
}

function zeroArrayTransformation(nums, queries) {
    const n = nums.length;
    const size = 4 * n;
    const maxTree = new Int32Array(size);
    const lazy = new Int32Array(size);

    function build(node, l, r) {
        if (l === r) {
            maxTree[node] = nums[l];
            return;
        }
        const mid = (l + r) >> 1;
        build(node << 1, l, mid);
        build((node << 1) | 1, mid + 1, r);
        maxTree[node] = Math.max(maxTree[node << 1], maxTree[(node << 1) | 1]);
    }

    function apply(node, dec) {
        if (maxTree[node] === 0) return;
        if (maxTree[node] <= dec) {
            maxTree[node] = 0;
            lazy[node] = 0;
        } else {
            maxTree[node] -= dec;
            lazy[node] += dec;
        }
    }

    function push(node) {
        const lz = lazy[node];
        if (lz !== 0) {
            apply(node << 1, lz);
            apply((node << 1) | 1, lz);
            lazy[node] = 0;
        }
    }

    function update(node, l, r, ql, qr, dec) {
        if (ql > r || qr < l || maxTree[node] === 0) return;
        if (ql <= l && r <= qr && maxTree[node] <= dec) {
            maxTree[node] = 0;
            lazy[node] = 0;
            return;
        }
        if (l === r) {
            apply(node, dec);
            return;
        }
        push(node);
        const mid = (l + r) >> 1;
        if (ql <= mid) update(node << 1, l, mid, ql, qr, dec);
        if (qr > mid) update((node << 1) | 1, mid + 1, r, ql, qr, dec);
        maxTree[node] = Math.max(maxTree[node << 1], maxTree[(node << 1) | 1]);
    }

    build(1, 0, n - 1);
    if (maxTree[1] === 0) return 0;

    for (let i = 0; i < queries.length; i++) {
        const [l, r, v] = queries[i];
        update(1, 0, n - 1, l, r, v);
        if (maxTree[1] === 0) return i + 1;
    }
    return -1;
}
