var maxCollectedFruits = function(fruits) {
    const n = fruits.length;
    const inf = -Infinity;
    const f = Array.from({length:n}, () => new Array(n).fill(inf));
    f[0][n-1] = fruits[0][n-1];
    for (let i = 1; i < n; i++) {
        for (let j = i+1; j < n; j++) {
            let best = Math.max(f[i-1][j], f[i-1][j-1]);
            if (j+1 < n) best = Math.max(best, f[i-1][j+1]);
            f[i][j] = best + fruits[i][j];
        }
    }
    const g = Array.from({length:n}, () => new Array(n).fill(inf));
    g[n-1][0] = fruits[n-1][0];
    for (let j = 1; j < n; j++) {
        for (let i = j+1; i < n; i++) {
            let best = Math.max(g[i][j-1], g[i-1][j-1]);
            if (i+1 < n) best = Math.max(best, g[i+1][j-1]);
            g[i][j] = best + fruits[i][j];
        }
    }
    let ans = f[n-2][n-1] + g[n-1][n-2];
    for (let i = 0; i < n; i++) ans += fruits[i][i];
    return ans;
};

function canRearrange(s, t, k) {
