    if (s.length !== t.length) return false;
    if (s.length % k !== 0) return false;

    const blockSize = s.length / k;
    const diff = new Map();               // map: block string → count difference

    // main logic: count blocks from s, then subtract blocks from t
    for (let i = 0; i < s.length; i += blockSize) {
        const block = s.slice(i, i + blockSize);
        diff.set(block, (diff.get(block) || 0) + 1);
    }
    for (let i = 0; i < t.length; i += blockSize) {
        const block = t.slice(i, i + blockSize);
        const newCount = (diff.get(block) || 0) - 1;
        if (newCount < 0) return false;   // t needs a block that s lacks
        diff.set(block, newCount);
