function maxRemovableQueries(nums, queries) {
  const n = nums.length;
  const q = queries.length;
  const sorted = queries.slice().sort((a, b) => a[0] - b[0]);

  class MinHeap {
    constructor() {
      this.arr = [];
    }
    size() {
      return this.arr.length;
    }
    peek() {
      return this.arr[0];
    }
    push(val) {
      const a = this.arr;
      a.push(val);
      let i = a.length - 1;
      while (i > 0) {
        const p = (i - 1) >> 1;
        if (a[p] <= a[i]) break;
        [a[p], a[i]] = [a[i], a[p]];
        i = p;
      }
    }
    pop() {
      const a = this.arr;
      if (a.length === 0) return undefined;
      const top = a[0];
      const last = a.pop();
      if (a.length > 0) {
        a[0] = last;
        let i = 0;
        while (true) {
          const l = i * 2 + 1;
          const r = l + 1;
          let smallest = i;
          if (l < a.length && a[l] < a[smallest]) smallest = l;
          if (r < a.length && a[r] < a[smallest]) smallest = r;
          if (smallest === i) break;
          [a[i], a[smallest]] = [a[smallest], a[i]];
          i = smallest;
        }
      }
      return top;
    }
  }

  const available = new MinHeap(); // intervals that have started but not selected
  const active = new MinHeap();    // right endpoints of selected intervals currently covering position i
  let ptr = 0;
  let selectedCount = 0;
  let covering = 0; // number of selected intervals that currently cover i

  for (let i = 0; i < n; i++) {
    while (ptr < q && sorted[ptr][0] === i) {
      available.push(sorted[ptr][1]);
      ptr++;
