var getLargestOutlier = function(nums) {
    const total = nums.reduce((a,b)=>a+b,0);
    const freq = new Map();
    for (const v of nums) freq.set(v, (freq.get(v)||0)+1);
    let best = -Infinity;
    for (const [a, cnt] of freq.entries()) {
        const outlier = total - 2*a;
        if (freq.has(outlier)) {
