function maxRemainingWeight(edges, k) {
    const n = edges.length + 1;
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v, w] of edges) {
        adj[u].push([v, w]);
        adj[v].push([u, w]);
    }

    const dpFull = new Array(n).fill(0);
    const dpReserved = new Array(n).fill(0);

    // iterative post-order DFS
    const parent = new Array(n).fill(-1);
    const order = [];
    const visited = new Array(n).fill(false);
    const stack = [0];
    visited[0] = true;
    while (stack.length) {
        const u = stack.pop();
        order.push(u);
        for (const [v] of adj[u]) {
            if (!visited[v]) {
                visited[v] = true;
                parent[v] = u;
                stack.push(v);
            }
        }
    }

    for (let idx = order.length - 1; idx >= 0; idx--) {
        const u = order[idx];
        let baseSum = 0;
        const gains = [];
        for (const [v, w] of adj[u]) {
            if (v === parent[u]) continue;
            baseSum += dpFull[v];
            const gain = (w + dpReserved[v]) - dpFull[v];
            if (gain > 0) gains.push(gain);
        }
        gains.sort((a, b) => b - a);

        const mFull = k; // if this node's edge to ITS parent is NOT kept, it can use full k for children
        const mReserved = Math.max(0, k - 1); // if edge to parent IS kept, one slot reserved

        let sumFull = 0;
        for (let i = 0; i < Math.min(mFull, gains.length); i++) sumFull += gains[i];
        let sumReserved = 0;
        for (let i = 0; i < Math.min(mReserved, gains.length); i++) sumReserved += gains[i];

        dpFull[u] = baseSum + sumFull;
        dpReserved[u] = baseSum + sumReserved;
    }

    return dpFull[0];
}

function maximizeTargets(edges1, edges2, k) {
    const n = edges1.length + 1;
    const m = edges2.length + 1;

    const adj1 = Array.from({ length: n }, () => []);
    for (const [a, b] of edges1) {
        adj1[a].push(b);
        adj1[b].push(a);
    }
    const adj2 = Array.from({ length: m }, () => []);
    for (const [u, v] of edges2) {
        adj2[u].push(v);
        adj2[v].push(u);
    }

    function bfs(start, adj, size) {
        const dist = new Int16Array(size);
        dist.fill(-1);
        const q = new Int32Array(size);
        let head = 0, tail = 0;
        dist[start] = 0;
        q[tail++] = start;
        while (head < tail) {
            const u = q[head++];
            const du = dist[u];
            const neigh = adj[u];
            for (let i = 0; i < neigh.length; i++) {
                const v = neigh[i];
                if (dist[v] === -1) {
                    dist[v] = du + 1;
                    q[tail++] = v;
                }
            }
        }
        return dist;
    }

    // all-pairs distances for first tree
    const dist1 = Array.from({ length: n }, () => new Int16Array(n));
    for (let i = 0; i < n; i++) {
        const d = bfs(i, adj1, n);
        dist1[i] = d;
    }

    // count of first-tree nodes within distance k for each i
    const cntFirst = new Int32Array(n);
    for (let i = 0; i < n; i++) {
        const d = dist1[i];
        let cnt = 0;
        for (let j = 0; j < n; j++) {
            if (d[j] !== -1 && d[j] <= k) cnt++;
        }
        cntFirst[i] = cnt;
    }

    // all-pairs distances for second tree
    const dist2 = Array.from({ length: m }, () => new Int16Array(m));
    for (let i = 0; i < m; i++) {
        const d = bfs(i, adj2, m);
        dist2[i] = d;
    }

    // f[r] = max number of second-tree nodes within distance r from some node
    const f = new Int32Array(k + 1);
    for (let b = 0; b < m; b++) {
        const d = dist2[b];
        const freq = new Int32Array(k + 1);
        for (let x = 0; x < m; x++) {
            const dd = d[x];
            if (dd !== -1 && dd <= k) freq[dd]++;
