    }
    for (let r = 1; r <= k; r++) {
        if (f[r] < f[r - 1]) f[r] = f[r - 1];
    }

    const answer = new Int32Array(n);
    for (let i = 0; i < n; i++) {
        let best = 0;
        const di = dist1[i];
        for (let a = 0; a < n; a++) {
            const R = k - di[a] - 1;
            if (R >= 0) {
                const cand = f[R];
                if (cand > best) best = cand;
            }
