        if (l < n && this.heap[l][0] < this.heap[s][0]) s = l;
        if (r < n && this.heap[r][0] < this.heap[s][0]) s = r;
        if (s === i) break;
        [this.heap[i], this.heap[s]] = [this.heap[s], this.heap[i]];
        i = s;
      }
    }
    isEmpty() { return this.heap.length === 0; }
  }

  const pq = new MinHeap();
  pq.push([dist[n], n]);

  while (!pq.isEmpty()) {
    const [curCost, u] = pq.pop();
    if (curCost !== dist[u]) continue;
    if (u === m) return curCost;

    const s = String(u).padStart(L, '0');
    for (let i = 0; i < L; i++) {
      const digit = s.charCodeAt(i) - 48;

      // decrement digit
      if (digit > 0) {
        const ns = s.slice(0, i) + String(digit - 1) + s.slice(i + 1);
        const v = parseInt(ns, 10);
        if (!isPrime[v] && dist[v] > curCost + v) {
          dist[v] = curCost + v;
          pq.push([dist[v], v]);
        }
      }

      // increment digit
      if (digit < 9) {
        const ns = s.slice(0, i) + String(digit + 1) + s.slice(i + 1);
        const v = parseInt(ns, 10);
        if (!isPrime[v] && dist[v] > curCost + v) {
          dist[v] = curCost + v;
          pq.push([dist[v], v]);
        }
      }
    }
  }

  return -1;
}
// TIME: O(10^L * L * log(10^L)) SPACE: O(10^L)

function countConnectedComponents(nums, threshold) {
    const n = nums.length;
    const parent = new Array(n);
    const rank = new Array(n).fill(0);
    for (let i = 0; i < n; i++) parent[i] = i;
    function find(x) {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
    function union(a, b) {
        let ra = find(a), rb = find(b);
        if (ra === rb) return;
        if (rank[ra] < rank[rb]) {
            [ra, rb] = [rb, ra];
        }
        parent[rb] = ra;
        if (rank[ra] === rank[rb]) rank[ra]++;
    }
    const valueToIndex = new Map();
    for (let i = 0; i < n; i++) {
        const v = nums[i];
        if (v <= threshold) valueToIndex.set(v, i);
    }
    const rep = new Int32Array(threshold + 1);
    rep.fill(-1);
    for (const [val, idx] of valueToIndex.entries()) {
        for (let m = val; m <= threshold; m += val) {
            const r = rep[m];
            if (r === -1) {
                rep[m] = idx;
            } else {
                union(idx, r);
            }
        }
    }
    const roots = new Set();
    for (let i = 0; i < n; i++) roots.add(find(i));
    return roots.size;
}
// TIME: O(threshold log threshold + n α(n)) SPACE: O(threshold + n)

function transformedArray(nums) {
