  const adj1 = Array.from({ length: n }, () => []);
  for (const [u, v] of edges1) {
    adj1[u].push(v);
    adj1[v].push(u);
  }
  const color1 = new Int8Array(n);
  const cntFirst = [0, 0];
  const stack1 = [0];
  const parent1 = new Int32Array(n).fill(-1);
  parent1[0] = 0;
  while (stack1.length) {
    const node = stack1.pop();
    const col = color1[node];
    cntFirst[col]++;
    for (const nb of adj1[node]) {
      if (parent1[nb] === -1) {
        parent1[nb] = node;
        color1[nb] = col ^ 1;
        stack1.push(nb);
      }
    }
  }

  const adj2 = Array.from({ length: m }, () => []);
  for (const [u, v] of edges2) {
    adj2[u].push(v);
    adj2[v].push(u);
  }
  const color2 = new Int8Array(m);
  const cntSecond = [0, 0];
  const stack2 = [0];
  const parent2 = new Int32Array(m).fill(-1);
  parent2[0] = 0;
  while (stack2.length) {
    const node = stack2.pop();
    const col = color2[node];
    cntSecond[col]++;
