}

function findMinimumTime(strength, k) {
  const n = strength.length;
  const indices = [...Array(n).keys()];
  let best = Infinity;
  function permute(arr, l) {
    if (l === arr.length) {
      let x = 1, time = 0;
      for (const idx of arr) {
        time += Math.ceil(strength[idx] / x);
        x += k;
      }
      best = Math.min(best, time);
      return;
    }
    for (let i = l; i < arr.length; i++) {
      [arr[l], arr[i]] = [arr[i], arr[l]];
      permute(arr, l+1);
      [arr[l], arr[i]] = [arr[i], arr[l]];
    }
  }
  permute(indices, 0);
  return best;
}

function maxSubarraySumDivisibleByK(nums, k) {
    const minPrefix = new Array(k).fill(Infinity);
    minPrefix[0] = 0;                 // prefix sum before the first element
    let prefix = 0;
    let best = -Infinity;

    for (let i = 0; i < nums.length; i++) {
        prefix += nums[i];
        const idx = i + 1;            // current prefix index
        const r = idx % k;            // remainder of this prefix index

        // main logic: use smallest earlier prefix with same remainder
        if (minPrefix[r] !== Infinity) {
            best = Math.max(best, prefix - minPrefix[r]);
        }

        minPrefix[r] = Math.min(minPrefix[r], prefix);
    }
    return best;
}

function maxRectangleArea(points) {
    const byX = new Map();
    for (const [x,y] of points) {
        if (!byX.has(x)) byX.set(x, []);
        byX.get(x).push(y);
    }
    for (const arr of byX.values()) arr.sort((a,b)=>a-b);
    const allSet = new Set(points.map(([x,y]) => x+','+y));
    const xs = [...byX.keys()].sort((a,b)=>a-b);
    let best = -1;
    for (let i = 0; i < xs.length; i++) {
        for (let j = i+1; j < xs.length; j++) {
            const x1 = xs[i], x2 = xs[j];
            const ys1 = byX.get(x1), ys2 = byX.get(x2);
            const set2 = new Set(ys2);
            for (let a = 0; a < ys1.length; a++) {
                if (!set2.has(ys1[a])) continue;
                for (let b = a+1; b < ys1.length; b++) {
                    if (!set2.has(ys1[b])) continue;
                    const yLow = ys1[a], yHigh = ys1[b];
                    // check no points strictly inside or on border other than the 4 corners
                    let valid = true;
                    for (const [px,py] of points) {
                        if (px >= x1 && px <= x2 && py >= yLow && py <= yHigh) {
                            const isCorner = (px===x1||px===x2) && (py===yLow||py===yHigh);
                            if (!isCorner) { valid = false; break; }
                        }
                    }
                    if (valid) {
                        const area = (x2-x1)*(yHigh-yLow);
                        if (area > best) best = area;
                    }
                }
            }
        }
    }
    return best;
}

function maxRectangleArea(xCoord, yCoord) {
  const n = xCoord.length;
  if (n < 4) return -1;
  const pointSet = new Set();
  for (let i = 0; i < n; i++) {
    pointSet.add(xCoord[i] + ',' + yCoord[i]);
  }
  let maxArea = -1;
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const x1 = xCoord[i];
      const y1 = yCoord[i];
      const x2 = xCoord[j];
      const y2 = yCoord[j];
      if (x1 === x2 || y1 === y2) continue; // not a rectangle
      const c1 = x1 + ',' + y2;
      const c2 = x2 + ',' + y1;
      if (!pointSet.has(c1) || !pointSet.has(c2)) continue; // missing corners
      const left = Math.min(x1, x2);
      const right = Math.max(x1, x2);
      const bottom = Math.min(y1, y2);
      const top = Math.max(y1, y2);
      let ok = true;
      for (let k = 0; k < n; k++) {
        const x = xCoord[k];
        const y = yCoord[k];
        // skip the four corner points
        if (
          (x === x1 && y === y1) ||
          (x === x1 && y === y2) ||
          (x === x2 && y === y1) ||
          (x === x2 && y === y2)
        ) continue;
        // check if point lies inside or on the border
        if (x >= left && x <= right && y >= bottom && y <= top) {
          ok = false;
          break;
        }
      }
      if (ok) {
        const area = (right - left) * (top - bottom);
        if (area > maxArea) maxArea = area;
      }
    }
  }
  return maxArea;
}

function minCostForTarget(freq, k) {
    let cost = 0;
    let prevExcess = 0;
    for (let i = 0; i < 26; i++) {
        if (freq[i] >= k) {
            const excess = freq[i] - k;
            cost += excess;
            prevExcess = excess;
        } else {
            const deficit = k - freq[i];
            const redirectUsed = Math.min(prevExcess, deficit);
            const includeCost = deficit - redirectUsed;
            const excludeCost = freq[i];
            cost += Math.min(includeCost, excludeCost);
            prevExcess = 0;
        }
    }
    return cost;
}
