function longestPush(events) {
    // map: button index -> {lastPress, totalTime}
    const info = new Map();
    let maxTime = 0;                     // latest timestamp in the log

    // first pass: accumulate intervals between consecutive presses of the same button
    for (let i = 0; i < events.length; i++) {
        const [idx, t] = events[i];
        if (t > maxTime) maxTime = t;    // keep the overall maximum time

        if (!info.has(idx)) {
            // first time we see this button
            info.set(idx, { lastPress: t, total: 0 });
        } else {
            const data = info.get(idx);
            data.total += t - data.lastPress; // time since previous press
            data.lastPress = t;                // update last press time
        }
    }

    // second pass: add the tail interval (last press → end of sequence)
    let bestIdx = null;
    let bestTotal = -1;

    for (const [idx, { lastPress, total }] of info.entries()) {
        const finalTotal = total + (maxTime - lastPress);
        // choose larger total, break ties by smaller index
        if (finalTotal > bestTotal || (finalTotal === bestTotal && idx < bestIdx)) {
            bestTotal = finalTotal;
            bestIdx = idx;
        }
    }

    return bestIdx;
}

function maximizeAmountAfterTwoDaysOfConversions(initialCurrency, pairs1, rates1, pairs2, rates2) {
    const idMap = new Map();
    const getId = (s) => {
