        return idMap.get(s);
    };
    getId(initialCurrency);
    for (const p of pairs1) { getId(p[0]); getId(p[1]); }
    for (const p of pairs2) { getId(p[0]); getId(p[1]); }

    const n = idMap.size;
    const adj1 = Array.from({length: n}, () => []);
    const adj2 = Array.from({length: n}, () => []);

    pairs1.forEach(([uStr, vStr], i) => {
        const u = idMap.get(uStr), v = idMap.get(vStr), r = rates1[i];
        adj1[u].push([v, r]);
        adj1[v].push([u, 1.0 / r]);
    });
    pairs2.forEach(([uStr, vStr], i) => {
        const u = idMap.get(uStr), v = idMap.get(vStr), r = rates2[i];
        adj2[u].push([v, r]);
        adj2[v].push([u, 1.0 / r]);
    });

