    const computeFactors = (adj) => {
        const factors = new Array(n).fill(0.0);
        const q = [start];
        let head = 0;
        factors[start] = 1.0;
        while (head < q.length) {
            const u = q[head++];
            const fu = factors[u];
            for (const [v, w] of adj[u]) {
                if (factors[v] === 0.0) { factors[v] = fu * w; q.push(v); }
            }
