        if (f1[i] && f2[i]) {
            const cand = f1[i] / f2[i];
            if (cand > best) best = cand;
        }
    }
    return best;
}

function countBeautifulSplits(nums) {
    const n = nums.length;
    if (n < 2) return 0;                     // no possible split

    const prefMax = new Array(n);
    const sufMin = new Array(n);

    // build prefix maximums
    prefMax[0] = nums[0];
    for (let i = 1; i < n; i++) {
        prefMax[i] = Math.max(prefMax[i - 1], nums[i]);
    }

    // build suffix minimums
    sufMin[n - 1] = nums[n - 1];
    for (let i = n - 2; i >= 0; i--) {
        sufMin[i] = Math.min(sufMin[i + 1], nums[i]);
    }

    // count positions where max(left) == min(right)
    let count = 0;
    for (let i = 0; i < n - 1; i++) {
        if (prefMax[i] === sufMin[i + 1]) count++;
    }
    return count;
}

function checkValidCuts(n, rectangles) {
