function countUniqueMiddleMode(nums) {
  const MOD = 1000000007n;
  const n = nums.length;

  function nC2(x) {
    const xb = BigInt(x);
    if (xb < 2n) return 0n;
    return (xb * (xb - 1n) / 2n) % MOD;
  }

  function calc(a, other1, other2, count1, count2) {
    const o1 = BigInt(other1), o2 = BigInt(other2);
    let res = (o1 * nC2(o2)) % MOD;
    for (const [bKey, b1] of count1.entries()) {
      if (Number(bKey) === a) continue;
      const b2 = BigInt(count2.get(bKey) || 0);
      const b1b = BigInt(b1);
      res = (res - b1b * nC2(b2) % MOD + MOD) % MOD;
      res = (res - b1b * b2 % MOD * (o2 - b2) % MOD + MOD) % MOD;
    }
    for (const [bKey, b2] of count2.entries()) {
      if (Number(bKey) === a) continue;
      const b1 = BigInt(count1.get(bKey) || 0);
      res = (res - (o1 - b1) * nC2(BigInt(b2)) % MOD + MOD) % MOD;
    }
    return ((res % MOD) + MOD) % MOD;
  }

  const left = new Map();
  const right = new Map();
  for (let i = 0; i < 2; i++) {
    const k = String(nums[i]);
    left.set(k, (left.get(k) || 0) + 1);
  }
  for (let i = 2; i < n; i++) {
    const k = String(nums[i]);
    right.set(k, (right.get(k) || 0) + 1);
  }

  let ans = 0n;
  for (let i = 2; i < n - 2; i++) {
    const num = nums[i];
    const key = String(num);
    right.set(key, (right.get(key) || 0) - 1);
    if (right.get(key) === 0) right.delete(key);

    const leftCount = left.get(key) || 0;
    const rightCount = right.get(key) || 0;
    const leftOther = i - leftCount;
    const rightOther = (n - 1 - i) - rightCount;

    // count[mode] = 5 -- [a a] a [a a]
    ans = (ans + nC2(leftCount) * nC2(rightCount)) % MOD;
    // count[mode] = 4 -- [a a] a [a ?]
    ans = (ans + nC2(leftCount) * BigInt(rightCount) % MOD * BigInt(rightOther) % MOD) % MOD;
    // count[mode] = 4 -- [a ?] a [a a]
    ans = (ans + BigInt(leftCount) * BigInt(leftOther) % MOD * nC2(rightCount) % MOD) % MOD;
    // count[mode] = 3 -- [a a] a [? ?]
    ans = (ans + nC2(leftCount) * nC2(rightOther) % MOD) % MOD;
    // count[mode] = 3 -- [? ?] a [a a]
    ans = (ans + nC2(leftOther) * nC2(rightCount) % MOD) % MOD;
    // count[mode] = 3 -- [a ?] a [a ?]
    ans = (ans + BigInt(leftCount) * BigInt(leftOther) % MOD * BigInt(rightCount) % MOD * BigInt(rightOther) % MOD) % MOD;
    // count[mode] = 2 -- [a ?] a [? ?]
    ans = (ans + BigInt(leftCount) * calc(num, leftOther, rightOther, left, right) % MOD) % MOD;
    // count[mode] = 2 -- [? ?] a [a ?]
    ans = (ans + BigInt(rightCount) * calc(num, rightOther, leftOther, right, left) % MOD) % MOD;

    left.set(key, (left.get(key) || 0) + 1);
  }

  return Number(((ans % MOD) + MOD) % MOD);
}

function countPaths(grid, k) {
    const MOD = 1_000_000_007;
    const m = grid.length, n = grid[0].length;
    const totalSteps = m + n - 2;
    const mid = Math.floor(totalSteps / 2);

    // special case: single cell grid
    if (totalSteps === 0) return (grid[0][0] === k) ? 1 : 0;

    // startMap[i][j] is a Map xor -> count for the middle cells
    const startMap = Array.from({ length: m }, () =>
        Array.from({ length: n }, () => new Map())
    );

    // ---------- first half (from top‑left) ----------
    const stackStart = [{ i: 0, j: 0, xor: grid[0][0] }];
    while (stackStart.length) {
        const { i, j, xor } = stackStart.pop();
        const layer = i + j;
        if (layer === mid) {
            const mp = startMap[i][j];
            mp.set(xor, (mp.get(xor) || 0) + 1);
            continue;
        }
        // move right
        if (j + 1 < n) stackStart.push({ i, j: j + 1, xor: xor ^ grid[i][j + 1] });
        // move down
        if (i + 1 < m) stackStart.push({ i: i + 1, j, xor: xor ^ grid[i + 1][j] });
    }

    // ---------- second half (from bottom‑right) ----------
    let answer = 0;
    const stackEnd = [{ i: m - 1, j: n - 1, xor: grid[m - 1][n - 1] }];
    while (stackEnd.length) {
        const { i, j, xor } = stackEnd.pop();
        const layer = i + j;
        if (layer === mid) {
            const mp = startMap[i][j];
            if (mp.size) {
                // xorStart ^ xor ^ grid[i][j] must equal k
                // => xorStart = xor ^ k ^ grid[i][j]
                const need = xor ^ k ^ grid[i][j];
                const cntStart = mp.get(need);
                if (cntStart !== undefined) {
                    answer = (answer + cntStart) % MOD;
                }
            }
            continue;
        }
        // move left
        if (j - 1 >= 0) stackEnd.push({ i, j: j - 1, xor: xor ^ grid[i][j - 1] });
        // move up
        if (i - 1 >= 0) stackEnd.push({ i: i - 1, j, xor: xor ^ grid[i - 1][j] });
    }

    return answer % MOD;
}



