        let dpPrev0 = new Array(L + 1).fill(INF);
        let dpPrev1 = new Array(L + 1).fill(INF);
        // initialize for first character
        dpPrev0[1] = chars[0] === 0 ? 0 : 1;
        dpPrev1[1] = chars[0] === 1 ? 0 : 1;

        for (let i = 1; i < n; i++) {
            let dpCurr0 = new Array(L + 1).fill(INF);
            let dpCurr1 = new Array(L + 1).fill(INF);
            const cur = chars[i];
            // transitions from previous state ending with 0
            for (let len = 1; len <= L; len++) {
                const prevCost = dpPrev0[len];
                if (prevCost >= INF) continue;
                // continue with 0 if len < L
                if (len < L) {
                    const cost = prevCost + (cur === 0 ? 0 : 1);
                    if (cost < dpCurr0[len + 1]) dpCurr0[len + 1] = cost;
                }
                // switch to 1
                const costSwitch = prevCost + (cur === 1 ? 0 : 1);
                if (costSwitch < dpCurr1[1]) dpCurr1[1] = costSwitch;
            }
            // transitions from previous state ending with 1
            for (let len = 1; len <= L; len++) {
                const prevCost = dpPrev1[len];
                if (prevCost >= INF) continue;
                // continue with 1 if len < L
                if (len < L) {
                    const cost = prevCost + (cur === 1 ? 0 : 1);
                    if (cost < dpCurr1[len + 1]) dpCurr1[len + 1] = cost;
                }
                // switch to 0
                const costSwitch = prevCost + (cur === 0 ? 0 : 1);
                if (costSwitch < dpCurr0[1]) dpCurr0[1] = costSwitch;
            }
            dpPrev0 = dpCurr0;
            dpPrev1 = dpCurr1;
        }

        let best = INF;
        for (let len = 1; len <= L; len++) {
            if (dpPrev0[len] < best) best = dpPrev0[len];
            if (dpPrev1[len] < best) best = dpPrev1[len];
        }
        return best <= numOps;
    }

    let low = 1, high = n;
    while (low < high) {
        const mid = Math.floor((low + high) / 2);
        if (canAchieve(mid)) high = mid;
        else low = mid + 1;
    }
    return low;
}

function minOperations(grid) {
    const m = grid.length;
    const n = grid[0].length;
    let total = 0;

    for (let col = 0; col < n; col++) {
        // start with the first element of this column
        let prev = grid[0][col];
        for (let row = 1; row < m; row++) {
            const cur = grid[row][col];
            if (cur <= prev) {                     // need to raise this cell
                const inc = prev + 1 - cur;        // minimal increment
                total += inc;
                prev = prev + 1;                    // new required minimum
            } else {
                prev = cur;                         // already strictly larger
            }
        }
    }
    return total;
}

function maximumNumberOfDistinctElementsAfterOperations(nums, k) {
    nums = [...nums].sort((a, b) => a - b);
    let cur = -1e18;
    let cnt = 0;
    for (const a of nums) {
        const left = a - k;
        const right = a + k;
        const cand = left > cur ? left : cur + 1;
        if (cand <= right) { cnt++; cur = cand; }
    }
    return cnt;
}

function smallestSubstringWithIdenticalCharsII(s, numOps) {
    const n = s.length;

    function check(m) {
        let cnt = 0;
        if (m === 1) {
            let mismatchStartWith0 = 0;
            for (let i = 0; i < n; i++) {
                const expected = (i % 2 === 0) ? '0' : '1';
                if (s[i] !== expected) mismatchStartWith0++;
            }
            cnt = Math.min(mismatchStartWith0, n - mismatchStartWith0);
        } else {
            let runLen = 0;
            for (let i = 0; i < n; i++) {
                runLen++;
                if (i === n - 1 || s[i] !== s[i + 1]) {
                    cnt += Math.floor(runLen / (m + 1));
                    runLen = 0;
                }
            }
        }
        return cnt <= numOps;
    }

    let low = 1, high = n;
    while (low < high) {
        const mid = (low + high) >> 1;
        if (check(mid)) high = mid; else low = mid + 1;
    }
    return low;
}

function answerString(word, numFriends) {
    const n = word.length;
    if (numFriends === 1) return word;
    const maxLen = n - numFriends + 1;
    let best = "";
    for (let i = 0; i < n; i++) {
        const sub = word.slice(i, i + maxLen);
        if (sub > best) best = sub;
    }
    return best;
}

function countSpecialSubsequences(nums) {
    function gcd(a, b) { while (b) { [a, b] = [b, a % b]; } return a; }
    const n = nums.length;
    const leftFreq = new Map();
    function key(a, b) { const g = gcd(a, b); return (a / g) + ',' + (b / g); }
    let ans = 0n;
    let qAdded = -1;
    for (let r = 0; r < n; r++) {
        const qMax = r - 2;
        while (qAdded < qMax) {
            qAdded++;
            const q = qAdded;
            if (q >= 2) {
                for (let p = 0; p <= q - 2; p++) {
                    const k = key(nums[p], nums[q]);
                    leftFreq.set(k, (leftFreq.get(k) || 0) + 1);
                }
            }
        }
        for (let s = r + 2; s < n; s++) {
            const k = key(nums[s], nums[r]);
            ans += BigInt(leftFreq.get(k) || 0);
        }
    }
    return Number(ans);
}

var hasMatch = function(s, p) {
    const starPos = p.indexOf('*');
    if (starPos === -1) return s.includes(p);
    const pre = p.slice(0, starPos);
    const suf = p.slice(starPos+1);
    if (!pre && !suf) return true;
    if (!pre) return s.includes(suf);
    if (!suf) return s.includes(pre);
    const preLen = pre.length;
    let start = s.indexOf(pre);
    while (start !== -1) {
        if (s.indexOf(suf, start+preLen) !== -1) return true;
        start = s.indexOf(pre, start+1);
    }
    return false;
};

function countTheNumberOfArraysWithKMatchingAdjacentElements(n, m, k) {
    const MOD = 1000000007n;
    if (k > n - 1) return 0;
    const total = n - 1;
    const kk = k <= total - k ? k : total - k;

    let comb = 1n;
    const modpow = (base, exp, mod) => {
        base %= mod; let result = 1n;
        while (exp > 0n) { if (exp & 1n) result = (result * base) % mod; base = (base * base) % mod; exp >>= 1n; }
        return result;
    };
    for (let i = 1; i <= kk; i++) {
        comb = (comb * BigInt(total - i + 1)) % MOD;
        comb = (comb * modpow(BigInt(i), MOD - 2n, MOD)) % MOD;
    }

    let ans = (comb * BigInt(m)) % MOD;
    ans = (ans * modpow(BigInt(m - 1), BigInt(n - k - 1), MOD)) % MOD;
    return Number(ans);
}

class TaskManager {
    constructor(tasks) {
        this.taskInfo = new Map();
        this.heap = [];
        for (const [userId, taskId, priority] of tasks) {
            this.taskInfo.set(taskId, { userId, priority });
            this._push([priority, taskId]);
        }
    }
    _less(a, b) { return a[0] !== b[0] ? a[0] > b[0] : a[1] > b[1]; }
    _push(item) {
        this.heap.push(item);
        let i = this.heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (this._less(this.heap[p], this.heap[i])) break;
            [this.heap[p], this.heap[i]] = [this.heap[i], this.heap[p]];
            i = p;
        }
    }
    _pop() {
        const top = this.heap[0];
        const last = this.heap.pop();
        if (this.heap.length) {
            this.heap[0] = last;
            let i = 0;
            while (true) {
                let l = i*2+1, r = i*2+2, best = i;
                if (l < this.heap.length && this._less(this.heap[l], this.heap[best])) best = l;
                if (r < this.heap.length && this._less(this.heap[r], this.heap[best])) best = r;
                if (best === i) break;
                [this.heap[i], this.heap[best]] = [this.heap[best], this.heap[i]];
                i = best;
            }
        }
        return top;
    }
    add(userId, taskId, priority) {
        this.taskInfo.set(taskId, { userId, priority });
        this._push([priority, taskId]);
    }
    edit(taskId, newPriority) {
        const info = this.taskInfo.get(taskId);
        info.priority = newPriority;
        this._push([newPriority, taskId]);
    }
    rmv(taskId) { this.taskInfo.delete(taskId); }
    execTop() {
        while (this.heap.length) {
            const [priority, taskId] = this._pop();
            const info = this.taskInfo.get(taskId);
            if (info && info.priority === priority) {
                const userId = info.userId;
                this.taskInfo.delete(taskId);
                return userId;
            }
        }
        return -1;
    }
}

function maxSubarraySumAfterOneDeletion(nums) {
    const n = nums.length;
    // Build segment tree
    const size = 1 << Math.ceil(Math.log2(n));
    const sum = new Float64Array(size * 2);
    const pref = new Float64Array(size * 2);
    const suff = new Float64Array(size * 2);
    const best = new Float64Array(size * 2);

    // Initialize leaves
    for (let i = 0; i < n; i++) {
        const v = nums[i];
        const idx = i + size;
        sum[idx] = v;
        pref[idx] = v;
        suff[idx] = v;
        best[idx] = v;
    }
    for (let i = n; i < size; i++) {
        const idx = i + size;
        sum[idx] = 0;
        pref[idx] = -Infinity;
        suff[idx] = -Infinity;
        best[idx] = -Infinity;
    }

    // Build internal nodes
    for (let i = size - 1; i > 0; i--) {
        const l = i << 1;
        const r = l | 1;
        sum[i] = sum[l] + sum[r];
        pref[i] = Math.max(pref[l], sum[l] + pref[r]);
        suff[i] = Math.max(suff[r], sum[r] + suff[l]);
        best[i] = Math.max(best[l], best[r], suff[l] + pref[r]);
    }

    function update(pos, value) {
        let idx = pos + size;
        sum[idx] = value;
        pref[idx] = value;
        suff[idx] = value;
        best[idx] = value;
        idx >>= 1;
        while (idx) {
            const l = idx << 1;
            const r = l | 1;
            sum[idx] = sum[l] + sum[r];
            pref[idx] = Math.max(pref[l], sum[l] + pref[r]);
            suff[idx] = Math.max(suff[r], sum[r] + suff[l]);
            best[idx] = Math.max(best[l], best[r], suff[l] + pref[r]);
            idx >>= 1;
        }
    }

    // Map each value to its indices
    const posMap = new Map();
    for (let i = 0; i < n; i++) {
        const v = nums[i];
        if (!posMap.has(v)) posMap.set(v, []);
        posMap.get(v).push(i);
    }

    let answer = best[1]; // no deletion

    for (const [val, idxList] of posMap.entries()) {
        // Zero out all occurrences of val
        for (const idx of idxList) update(idx, 0);
        // Evaluate current max subarray sum
        answer = Math.max(answer, best[1]);
        // Restore original values
        for (const idx of idxList) update(idx, nums[idx]);
    }

    return answer;
}

function maximumCoins(coins, k) {
    // Sort intervals by left coordinate
    coins.sort((a, b) => a[0] - b[0]);

    // Build compressed segments (including zero‑value gaps)
    const segs = [];
    let prevEnd = null;
    for (const [l, r, c] of coins) {
        if (prevEnd !== null && l > prevEnd + 1) {
            segs.push({ len: l - (prevEnd + 1), val: 0 });
        }
        segs.push({ len: r - l + 1, val: c });
        prevEnd = r;
    }

    // Total length and total coins of all real segments (including gaps)
    let totalLen = 0;
    let totalCoins = 0;
    for (const s of segs) {
        totalLen += s.len;
        totalCoins += s.len * s.val;
    }

    // If the whole covered part is shorter than k, the answer is totalCoins
    if (totalLen <= k) return totalCoins;

    let leftIdx = 0;
    let leftOffset = 0; // how many positions already removed from left segment
    let curLen = 0;
    let curSum = 0;
    let maxSum = 0;

    for (let rightIdx = 0; rightIdx < segs.length; rightIdx++) {
        const seg = segs[rightIdx];
        curLen += seg.len;
        curSum += seg.len * seg.val;

        // Shrink window until its length <= k
        while (curLen > k) {
            const leftSeg = segs[leftIdx];
            const leftRemain = leftSeg.len - leftOffset;
            const excess = curLen - k;
            if (leftRemain <= excess) {
                // Remove whole left segment
                curLen -= leftRemain;
                curSum -= leftRemain * leftSeg.val;
                leftIdx++;
                leftOffset = 0;
            } else {
                // Remove part of left segment
                curLen -= excess;
                curSum -= excess * leftSeg.val;
                leftOffset += excess;
            }
        }

        // When window length equals k, update answer
        if (curLen === k && curSum > maxSum) {
            maxSum = curSum;
        }
    }

    return maxSum;
}

function maximumSubarrayWithEqualProducts(nums) {
    const n = nums.length;
    if (nums.some(x => x === 0)) return n;
    const gcd = (a, b) => b === 0 ? a : gcd(b, a % b);
    let best = 0;
    for (let i = 0; i < n; i++) {
        let prod = 1, curLcm = 1, curGcd = 0;
        for (let j = i; j < n; j++) {
            const x = nums[j];
            prod *= x;
            curLcm = Math.floor(curLcm / gcd(curLcm, x)) * x;
            curGcd = curGcd === 0 ? x : gcd(curGcd, x);
            if (prod === curLcm * curGcd) {
                const length = j - i + 1;
                if (length > best) best = length;
            }
        }
    }
    return best;
}

function longestSubsequence95(nums) {
  const n = nums.length;
  const maxDiff = 1000;
  const dp = Array.from({length:n}, () => new Array(maxDiff+1).fill(1));
  const suffixMax = Array.from({length:n}, () => new Array(maxDiff+2).fill(0));
  let ans = 1;
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < i; j++) {
      const d = Math.abs(nums[i] - nums[j]);
      const cand = 1 + suffixMax[j][d];
      if (cand > dp[i][d]) dp[i][d] = cand;
    }
    for (let d = maxDiff; d >= 0; d--) {
      suffixMax[i][d] = Math.max(dp[i][d], suffixMax[i][d+1] || 0);
    }
    ans = Math.max(ans, suffixMax[i][0]);
  }
  return ans;
}

function findMirrorScoreOfAString(s) {
    const stacks = Array.from({length: 26}, () => []);
    let score = 0;
    const aOrd = 'a'.charCodeAt(0);
    for (let i = 0; i < s.length; i++) {
        const idx = s.charCodeAt(i) - aOrd;
        const mirIdx = 25 - idx;
        if (stacks[mirIdx].length) {
            const pos = stacks[mirIdx].pop();
            score += i - pos;
        } else {
            stacks[idx].push(i);
        }
    }
    return score;
}

function maximumScoreOfNonOverlappingIntervals(intervals) {
    const n = intervals.length;
    if (n === 0) return [];
    const arr = intervals.map(([l, r, w], i) => [l, r, w, i]);
    arr.sort((a, b) => a[0] - b[0] || a[3] - b[3]);
    const starts = arr.map(a => a[0]);

    const bisectRight = (val) => {
        let lo = 0, hi = starts.length;
        while (lo < hi) { const mid = (lo + hi) >> 1; if (starts[mid] <= val) lo = mid + 1; else hi = mid; }
        return lo;
    };
    const nxt = arr.map((a) => bisectRight(a[1]));

    const K = 4;
    const dpWeight = Array.from({length: n + 1}, () => new Array(K + 1).fill(0));
    const dpChoice = Array.from({length: n + 1}, () => Array.from({length: K + 1}, () => []));

    const tupleLess = (a, b) => {
        const len = Math.min(a.length, b.length);
        for (let i = 0; i < len; i++) { if (a[i] !== b[i]) return a[i] < b[i]; }
        return a.length < b.length;
    };

    for (let i = n - 1; i >= 0; i--) {
        const [l, r, w, idx] = arr[i];
        for (let k = 0; k <= K; k++) {
            let bestW = dpWeight[i + 1][k];
            let bestC = dpChoice[i + 1][k];
            if (k > 0) {
                const takeW = w + dpWeight[nxt[i]][k - 1];
                const takeC = [idx, ...dpChoice[nxt[i]][k - 1]].sort((a, b) => a - b);
                if (takeW > bestW || (takeW === bestW && tupleLess(takeC, bestC))) {
                    bestW = takeW;
                    bestC = takeC;
                }
            }
            dpWeight[i][k] = bestW;
            dpChoice[i][k] = bestC;
        }
    }

    return dpChoice[0][K];
}

function minMaxWeight(n, edges, threshold) {
  const outEdges = Array.from({length: n}, () => []);
  for (const [u, v, w] of edges) outEdges[u].push([v, w]);
  for (let u = 0; u < n; u++) {
    outEdges[u].sort((a, b) => a[1] - b[1]);
    if (outEdges[u].length > threshold) outEdges[u].length = threshold;
  }
  const revAdj = Array.from({length: n}, () => []);
  let maxW = 0;
  for (let u = 0; u < n; u++) {
    for (const [v, w] of outEdges[u]) {
      revAdj[v].push([u, w]);
      if (w > maxW) maxW = w;
    }
  }

  function reachableCount(m) {
    const visited = new Array(n).fill(false);
    visited[0] = true;
    const stack = [0];
    let cnt = 1;
    while (stack.length) {
      const u = stack.pop();
      for (const [v, w] of revAdj[u]) {
        if (w <= m && !visited[v]) {
          visited[v] = true;
          cnt++;
          stack.push(v);
        }
      }
    }
    return cnt;
  }

  if (reachableCount(maxW) < n) return -1;
  let lo = 1, hi = maxW;
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (reachableCount(mid) === n) hi = mid; else lo = mid + 1;
  }
  return lo;
}

function zigzagSkip(grid) {
    var result = [];               // store taken values
    var take = true;               // first cell must be taken
    var rows = grid.length;
    var cols = rows ? grid[0].length : 0;

    for (var i = 0; i < rows; i++) {
        if (i % 2 === 0) {          // left → right on even rows
            for (var j = 0; j < cols; j++) {
                if (take) result.push(grid[i][j]); // take this cell
                take = !take;                     // toggle for next cell
            }
        } else {                    // right → left on odd rows
            for (var j = cols - 1; j >= 0; j--) {
                if (take) result.push(grid[i][j]); // take this cell
                take = !take;                     // toggle for next cell
            }
        }
    }
    return result;
}

function countNonDecreasingSubarrays(nums, k) {
    const n = nums.length;
    let total = 0;
    for (let l = 0; l < n; l++) {
        let curMax = nums[l];
        let cost = 0;
        for (let r = l; r < n; r++) {
            if (r > l) {
                if (nums[r] < curMax) {
                    cost += curMax - nums[r];
                } else {
                    curMax = nums[r];
                }
            }
            if (cost <= k) {
                total++;
            } else {
                break; // further extension will only increase cost
            }
        }
    }
    return total;
}

function minimumCostToMakeArraysIdentical(arr, brr, k) {
    let total = 0;
    for (let i = 0; i < arr.length; i++) {
        const a = arr[i];
        const b = brr[i];
        const direct = Math.abs(a - b);
        const flip = k + Math.abs(-a - b);
        total += direct < flip ? direct : flip;
    }
    return total;
}

function maxProfit(coins) {
    const m = coins.length;
    const n = coins[0].length;
    // dp[j][k] – best profit for column j with k neutralizations in the current row
    let dp = Array.from({ length: n }, () => Array(3).fill(-Infinity));

    for (let i = 0; i < m; i++) {
        const newRow = Array(n);
        for (let j = 0; j < n; j++) {
            const cur = Array(3).fill(-Infinity);

            if (i === 0 && j === 0) {                     // start cell
                cur[0] = coins[0][0];                     // take value
                cur[1] = 0;                               // neutralize it
            } else {
                // ----- transition from the cell above -----
                if (i > 0) {
                    const top = dp[j];
                    for (let k = 0; k <= 2; k++) {
                        if (top[k] === -Infinity) continue;
                        // keep current cell's value
                        cur[k] = Math.max(cur[k], top[k] + coins[i][j]);
                        // neutralize current cell
                        if (k < 2) cur[k + 1] = Math.max(cur[k + 1], top[k]);
                    }
                }
                // ----- transition from the cell on the left -----
                if (j > 0) {
                    const left = newRow[j - 1];
                    for (let k = 0; k <= 2; k++) {
                        if (left[k] === -Infinity) continue;
                        cur[k] = Math.max(cur[k], left[k] + coins[i][j]);
                        if (k < 2) cur[k + 1] = Math.max(cur[k + 1], left[k]);
                    }
                }
            }
            newRow[j] = cur;        // store results for this column
        }
        dp = newRow;                // move to next row
    }

    // answer = best profit at bottom‑right with any number of neutralizations (0..2)
    return Math.max(...dp[n - 1]);
}

function maxCircularDiff(nums) {
    if (!nums || nums.length < 2) return 0;          // handle trivial cases
    let maxDiff = 0;
    for (let i = 0; i < nums.length; i++) {
        // compute absolute difference between current element and its circular neighbour
        const diff = Math.abs(nums[i] - nums[(i + 1) % nums.length]);
        if (diff > maxDiff) maxDiff = diff;
    }
    return maxDiff;
}

function maxMinSumAtMostK(nums, k) {
    const MOD = 1000000007n;
    const n = nums.length;
    const sorted = nums.slice().sort((a, b) => a - b);
    const K = k;
    const sumComb = new Array(n + 1);
    let prev = new Array(K).fill(0n);
    prev[0] = 1n;
    sumComb[0] = 1n;
    for (let i = 1; i <= n; i++) {
        const cur = new Array(K).fill(0n);
        cur[0] = 1n;
        let sum = 1n;
        for (let r = 1; r < K; r++) {
            cur[r] = (prev[r] + prev[r - 1]) % MOD;
            sum = (sum + cur[r]) % MOD;
        }
        sumComb[i] = sum;
        prev = cur;
    }
    let ans = 0n;
    for (let i = 0; i < n; i++) {
        const left = i;
        const right = n - 1 - i;
        const cntMax = sumComb[left];
        const cntMin = sumComb[right];
        const total = (cntMax + cntMin) % MOD;
        const contribution = (BigInt(sorted[i]) % MOD) * total % MOD;
        ans = (ans + contribution) % MOD;
    }
    return Number(ans);
}

function longestSpecialPath(edges, nums) {
    const n = nums.length;
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v, w] of edges) {
        adj[u].push([v, w]);
        adj[v].push([u, w]);
    }

    const prefix = [];                 // prefix[depth] = distance root -> node at depth
    let bestLen = 0;                   // longest length found
    let bestNodes = Infinity;          // minimal node count for that length
    const lastSeen = new Map();        // value -> deepest depth where it appears

    function dfs(node, parent, depth, left) {
        const val = nums[node];
        const prevDepth = lastSeen.has(val) ? lastSeen.get(val) : -1;
        const newLeft = Math.max(left, prevDepth + 1);   // keep values unique

        const curPref = depth === 0 ? 0 : prefix[depth];
        const leftPref = prefix[newLeft];
        const pathLen = curPref - leftPref;               // length of window
        const nodeCnt = depth - newLeft + 1;              // nodes in window

        if (pathLen > bestLen) {
            bestLen = pathLen;
            bestNodes = nodeCnt;
        } else if (pathLen === bestLen && nodeCnt < bestNodes) {
            bestNodes = nodeCnt;
        }

        const saved = lastSeen.has(val) ? lastSeen.get(val) : undefined;
        lastSeen.set(val, depth);                         // add current node

        for (const [nbr, w] of adj[node]) {
            if (nbr === parent) continue;
            prefix[depth + 1] = curPref + w;              // prefix for child
            dfs(nbr, node, depth + 1, newLeft);
        }

        if (saved === undefined) lastSeen.delete(val);   // restore state
        else lastSeen.set(val, saved);
    }

    prefix[0] = 0;
    dfs(0, -1, 0, 0);
    return [bestLen, bestNodes];
}

function manhattanDistancesOfAllArrangementsOfPieces(m, n, k) {
    const MOD = 1000000007n;
    const modpow = (base, exp, mod) => {
        base %= mod; let result = 1n;
        while (exp > 0n) { if (exp & 1n) result = (result * base) % mod; base = (base * base) % mod; exp >>= 1n; }
        return result;
    };
    const INV6 = modpow(6n, MOD - 2n, MOD);

    if (k < 2) return 0;
    const totalCells = m * n;
    if (k > totalCells) return 0;

    const N = totalCells - 2;
    let r = k - 2;
    if (r > N) return 0;
    r = Math.min(r, N - r);

    let arrangements;
    if (r === 0) {
        arrangements = 1n;
    } else {
        const inv = new Array(r + 1).fill(0n);
        inv[1] = 1n;
        for (let i = 2; i <= r; i++) {
            inv[i] = (MOD - (MOD / BigInt(i)) * inv[Number(MOD % BigInt(i))] % MOD) % MOD;
        }
        arrangements = 1n;
        const start = N - r;
        for (let i = 1; i <= r; i++) {
            arrangements = (arrangements * BigInt(start + i)) % MOD;
            arrangements = (arrangements * inv[i]) % MOD;
        }
    }

    const mMod = BigInt(m) % MOD;
    const nMod = BigInt(n) % MOD;
    const m3 = (mMod * mMod % MOD) * mMod % MOD;
    const n3 = (nMod * nMod % MOD) * nMod % MOD;

    const rowPart = (nMod * nMod % MOD) * (((m3 - mMod) % MOD + MOD) % MOD) % MOD;
    const colPart = (mMod * mMod % MOD) * (((n3 - nMod) % MOD + MOD) % MOD) % MOD;

    let sumDist = (rowPart + colPart) % MOD;
    sumDist = (sumDist * INV6) % MOD;

    return Number((arrangements * sumDist) % MOD);
}

function countPartitions(nums) {
    const total = nums.reduce((a,b) => a+b, 0);
    return total % 2 === 0 ? nums.length - 1 : 0;
}

function sumSubarrayMins(nums) {
    let total = 0;
    const n = nums.length;
    for (let i = 0; i < n; i++) {
        const cur = [];
        for (let j = i; j < n; j++) {
            // insert nums[j] into cur, keeping it sorted
            let lo = 0, hi = cur.length;
            while (lo < hi) {
                const mid = (lo + hi) >> 1;
                if (cur[mid] < nums[j]) lo = mid + 1; else hi = mid;
            }
            cur.splice(lo, 0, nums[j]);
            const median = cur[Math.floor((cur.length - 1) / 2)];
            total += median;
        }
    }
    return total;
}

function paintHouseIV(n, cost) {
    const half = n / 2;
    const INF = Infinity;
    const combos = [];
    for (let a = 0; a < 3; a++) for (let b = 0; b < 3; b++) if (a !== b) combos.push([a, b]);
    let dp = combos.map(([a, b]) => cost[0][a] + cost[n - 1][b]);
    for (let i = 1; i < half; i++) {
        const ndp = new Array(combos.length).fill(INF);
        for (let ci = 0; ci < combos.length; ci++) {
            const [a, b] = combos[ci];
            const c = cost[i][a] + cost[n - 1 - i][b];
            for (let pj = 0; pj < combos.length; pj++) {
                const [pa, pb] = combos[pj];
                if (pa !== a && pb !== b) {
                    const val = dp[pj] + c;
                    if (val < ndp[ci]) ndp[ci] = val;
                }
            }
        }
        dp = ndp;
    }
    return Math.min(...dp);
}

function maxMinSumAtMostK(nums, k) {
    const n = nums.length;
    const prevGreater = new Array(n);
    const nextGreater = new Array(n);
    const prevSmaller = new Array(n);
    const nextSmaller = new Array(n);
    const stack = [];

    // previous greater (strict)
    for (let i = 0; i < n; i++) {
        while (stack.length && nums[stack[stack.length - 1]] <= nums[i]) stack.pop();
        prevGreater[i] = stack.length ? stack[stack.length - 1] : -1;
        stack.push(i);
    }
    stack.length = 0;
    // next greater (greater or equal)
    for (let i = n - 1; i >= 0; i--) {
        while (stack.length && nums[stack[stack.length - 1]] < nums[i]) stack.pop();
        nextGreater[i] = stack.length ? stack[stack.length - 1] : n;
        stack.push(i);
    }
    stack.length = 0;
    // previous smaller (strict)
    for (let i = 0; i < n; i++) {
        while (stack.length && nums[stack[stack.length - 1]] >= nums[i]) stack.pop();
        prevSmaller[i] = stack.length ? stack[stack.length - 1] : -1;
        stack.push(i);
    }
    stack.length = 0;
    // next smaller (smaller or equal)
    for (let i = n - 1; i >= 0; i--) {
        while (stack.length && nums[stack[stack.length - 1]] > nums[i]) stack.pop();
        nextSmaller[i] = stack.length ? stack[stack.length - 1] : n;
        stack.push(i);
    }

    function countPairs(L, R, k) {
        const limit = k - 1;
        if (limit < 0) return 0;
        if (limit >= L + R - 2) return L * R;
        const aMax = Math.min(L - 1, limit);
        const a0 = limit - (R - 1);
        const a1 = Math.min(L - 1, Math.max(-1, a0));
        let total = 0;
        if (a1 >= 0) total += (a1 + 1) * R;
        const start = a1 + 1;
        if (start <= aMax) {
            const cnt = aMax - start + 1;
            const first = limit - start + 1;
            const last = limit - aMax + 1;
            total += cnt * (first + last) / 2;
        }
        return total;
    }

    let answer = 0;
    for (let i = 0; i < n; i++) {
        const left = i - prevGreater[i];
        const right = nextGreater[i] - i;
        const cntMax = countPairs(left, right, k);
        answer += nums[i] * cntMax;

        const leftS = i - prevSmaller[i];
        const rightS = nextSmaller[i] - i;
        const cntMin = countPairs(leftS, rightS, k);
        answer += nums[i] * cntMin;
    }
    return answer;
}

function maxFreeTime(eventTime, k, startTime, endTime) {
    const n = startTime.length;
    const dur = new Array(n);
    for (let i = 0; i < n; i++) dur[i] = endTime[i] - startTime[i];

    const prefSum = new Array(n);
    const prefCost = new Array(n);
    let sum = 0, cost = 0;
    for (let i = 0; i < n; i++) {
        const earliestStart = sum;
        if (startTime[i] !== earliestStart) cost++;
        prefCost[i] = cost;
        sum += dur[i];
        prefSum[i] = sum;
    }

    const sufSum = new Array(n);
    const latestStart = new Array(n);
    const sufCost = new Array(n);
    sum = 0;
    cost = 0;
    for (let i = n - 1; i >= 0; i--) {
        sum += dur[i];
        sufSum[i] = sum;
        const ls = eventTime - sum;
        latestStart[i] = ls;
        if (startTime[i] !== ls) cost++;
        sufCost[i] = cost;
    }

    let ans = 0;
    // gap before first meeting
    if (sufCost[0] <= k) ans = Math.max(ans, latestStart[0]);
    // gap after last meeting
    if (prefCost[n - 1] <= k) ans = Math.max(ans, eventTime - prefSum[n - 1]);
    // gaps between meetings
    for (let i = 0; i < n - 1; i++) {
        const moves = prefCost[i] + sufCost[i + 1];
        if (moves <= k) {
            const gap = latestStart[i + 1] - prefSum[i];
            if (gap > ans) ans = gap;
        }
    }
    return ans;
}

function countMentions(numberOfUsers, events) {
    const indexed = events.map((e, i) => ({e, i}));
    indexed.sort((a, b) => {
        const tsA = parseInt(a.e[1]), tsB = parseInt(b.e[1]);
        if (tsA !== tsB) return tsA - tsB;
        const prioA = a.e[0] === 'OFFLINE' ? 0 : 1;
        const prioB = b.e[0] === 'OFFLINE' ? 0 : 1;
        if (prioA !== prioB) return prioA - prioB;
        return a.i - b.i;
    });
    const sorted = indexed.map(x => x.e);
    const mentions = new Array(numberOfUsers).fill(0);
    const offlineUntil = new Array(numberOfUsers).fill(-1);

    for (const [etype, t, content] of sorted) {
        const ts = parseInt(t);
        if (etype === 'OFFLINE') {
            const uid = parseInt(content);
            offlineUntil[uid] = ts + 60;
        } else {
            if (content === 'ALL') {
                for (let i = 0; i < numberOfUsers; i++) mentions[i] += 1;
            } else if (content === 'HERE') {
                for (let i = 0; i < numberOfUsers; i++) {
                    if (offlineUntil[i] <= ts) mentions[i] += 1;
                }
            } else {
                for (const part of content.split(' ')) {
                    const uid = parseInt(part.slice(2));
                    mentions[uid] += 1;
                }
            }
        }
    }
    return mentions;
}

var maxFrequency = function(nums, k) {
    const n = nums.length;
    const originalCount = nums.filter(v=>v===k).length;
    if (originalCount === n) return n;
    const deltaSet = new Set([0]);
    for (const v of nums) deltaSet.add(k-v);
    let answer = originalCount;
    for (const delta of deltaSet) {
        if (delta === 0) continue;
        const target = k - delta;
        let cur = 0, best = 0;
        for (const v of nums) {
            if (v === k) cur -= 1;
            else if (v === target) cur += 1;
            if (cur < 0) cur = 0;
            if (cur > best) best = cur;
        }
        const candidate = originalCount + best;
        if (candidate > answer) answer = candidate;
    }
    return answer;
};

function getShortestSupersequenceFrequencies(words) {
    const letterSet = new Set();
    for (const w of words) for (const c of w) letterSet.add(c);
    const letters = [...letterSet].sort();
    const n = letters.length;
    const idx = {};
    letters.forEach((c, i) => { idx[c] = i; });

    const outMask = new Array(n).fill(0);
    const selfLoop = new Array(n).fill(0);
    for (const w of words) {
        const a = w[0], b = w[1];
        const i = idx[a], j = idx[b];
        if (i === j) selfLoop[i]++;
        else outMask[i] |= (1 << j);
    }

    const fullMask = (1 << n) - 1;
    const INF = Infinity;
    const dpCost = new Array(1 << n).fill(INF);
    dpCost[0] = 0;

    const popcount = (x) => { let c = 0; while (x) { c += x & 1; x >>= 1; } return c; };

    for (let mask = 1; mask <= fullMask; mask++) {
        let best = INF;
        for (let v = 0; v < n; v++) {
            if ((mask >> v) & 1) {
                const prev = mask ^ (1 << v);
                const costV = popcount(outMask[v] & prev);
                const cand = dpCost[prev] + costV;
                if (cand < best) best = cand;
            }
        }
        dpCost[mask] = best;
    }

    const dpVec = Array.from({ length: 1 << n }, () => new Set());
    dpVec[0].add(JSON.stringify(new Array(n).fill(0)));

    for (let mask = 1; mask <= fullMask; mask++) {
        for (let v = 0; v < n; v++) {
            if ((mask >> v) & 1) {
                const prev = mask ^ (1 << v);
                const costV = popcount(outMask[v] & prev);
                if (dpCost[mask] === dpCost[prev] + costV) {
                    for (const vecStr of dpVec[prev]) {
                        const lst = JSON.parse(vecStr);
                        lst[v] += costV;
                        dpVec[mask].add(JSON.stringify(lst));
                    }
                }
            }
        }
    }

    const result = [];
    for (const vecStr of dpVec[fullMask]) {
        const vec = JSON.parse(vecStr);
        const freq = new Array(26).fill(0);
        for (let i = 0; i < n; i++) {
            const cnt = 1 + selfLoop[i] + vec[i];
            freq[letters[i].charCodeAt(0) - 97] = cnt;
        }
        result.push(freq);
    }

    result.sort((a, b) => {
        for (let i = 0; i < 26; i++) if (a[i] !== b[i]) return a[i] - b[i];
        return 0;
    });
    return result;
}

function maxDiffEvenOdd(s) {
    const freq = new Array(26).fill(0);
    for (let i = 0; i < s.length; i++) {               // count frequencies
        freq[s.charCodeAt(i) - 97]++;
    }

    let oddMax = -Infinity;
    let evenMin = Infinity;

    for (let i = 0; i < 26; i++) {
        const f = freq[i];
        if (f === 0) continue;
        if (f % 2 === 1) {                              // odd frequency
            if (f > oddMax) oddMax = f;
        } else {                                        // even frequency
            if (f < evenMin) evenMin = f;
        }
    }

    if (oddMax === -Infinity || evenMin === Infinity) // no valid pair
        return 0;
    return oddMax - evenMin;
}

function findValidPair(s) {
    // count occurrences of each digit (0‑9)
    const freq = new Array(10).fill(0);
    for (let i = 0; i < s.length; i++) {
        freq[s.charCodeAt(i) - 48]++;          // 48 = '0'.charCodeAt(0)
    }

    // check each adjacent pair for the required property
    for (let i = 0; i < s.length - 1; i++) {
        const a = s[i];
        const b = s[i + 1];
        const aVal = a.charCodeAt(0) - 48;
        const bVal = b.charCodeAt(0) - 48;
        if (a !== b && freq[aVal] === aVal && freq[bVal] === bVal) {
            return a + b;                       // first valid pair found
        }
    }
    return "";                                 // no valid pair
}

function maxManhattanDistanceAfterKChanges(s, k) {
    let x = 0, y = 0;
    let dist = 0;
    let cnt2 = 0, cnt1 = 0;
    let best = 0;
    for (let i = 0; i < s.length; i++) {
        const ch = s[i];
        let delta;
        if (ch === 'N') {
            delta = Math.abs(y + 1) - Math.abs(y);
            y += 1;
        } else if (ch === 'S') {
            delta = Math.abs(y - 1) - Math.abs(y);
            y -= 1;
        } else if (ch === 'E') {
            delta = Math.abs(x + 1) - Math.abs(x);
            x += 1;
        } else { // 'W'
            delta = Math.abs(x - 1) - Math.abs(x);
            x -= 1;
        }
        dist += delta;
        const gain = 1 - delta; // delta ∈ {-1,0,1}
        if (gain === 2) cnt2++;
        else if (gain === 1) cnt1++;
        let remaining = k;
        const use2 = Math.min(cnt2, remaining);
        let add = use2 * 2;
        remaining -= use2;
        const use1 = Math.min(cnt1, remaining);
        add += use1;
        const cur = dist + add;
        if (cur > best) best = cur;
    }
    return best;
}

function minimumIncrementsForTargetMultiplesInAnArray(nums, target) {
    const m = target.length;
    if (m === 0) return 0;
    const fullMask = (1 << m) - 1;
    const INF = 1e18;
    const gcd = (a, b) => b === 0 ? a : gcd(b, a % b);

    const lcmMask = new Array(1 << m).fill(1);
    for (let mask = 1; mask <= fullMask; mask++) {
        const bit = 31 - Math.clz32(mask & -mask);
        const prev = mask ^ (1 << bit);
        const prevL = lcmMask[prev];
        const t = target[bit];
        const g = gcd(prevL, t);
        lcmMask[mask] = Math.floor(prevL / g) * t;
    }

    let dp = new Array(1 << m).fill(INF);
    dp[0] = 0;

    for (const cur of nums) {
        const costMask = new Array(1 << m).fill(0);
        for (let mask = 1; mask <= fullMask; mask++) {
            const L = lcmMask[mask];
            const mult = Math.ceil(cur / L);
            const nxt = mult * L;
            costMask[mask] = nxt - cur;
        }

        const ndp = [...dp];
        for (let sub = 1; sub <= fullMask; sub++) {
            const add = costMask[sub];
            const comp = fullMask ^ sub;
            let mask = comp;
            while (true) {
                const newmask = mask | sub;
                const cand = dp[mask] + add;
                if (cand < ndp[newmask]) ndp[newmask] = cand;
                if (mask === 0) break;
                mask = (mask - 1) & comp;
            }
        }
        dp = ndp;
    }

    return dp[fullMask];
}

var maxFreeTime = function(eventTime, startTime, endTime) {
    const n = startTime.length;
    const leftGaps = new Array(n).fill(0);
    leftGaps[0] = startTime[0];
    for (let i = 1; i < n; i++) {
        leftGaps[i] = Math.max(leftGaps[i-1], startTime[i] - endTime[i-1]);
    }
    const rightGaps = new Array(n).fill(0);
    rightGaps[n-1] = eventTime - endTime[n-1];
    for (let i = n-2; i >= 0; i--) {
        rightGaps[i] = Math.max(rightGaps[i+1], startTime[i+1] - endTime[i]);
    }
    let res = 0;
    for (let i = 0; i < n; i++) {
        const leftGap = i === 0 ? leftGaps[0] : startTime[i] - endTime[i-1];
        const rightGap = i === n-1 ? rightGaps[n-1] : startTime[i+1] - endTime[i];
        const duration = endTime[i] - startTime[i];
        let interval = 0;
        const canUseLeft = i !== 0 && leftGaps[i-1] >= duration;
        const canUseRight = i !== n-1 && rightGaps[i+1] >= duration;
        if (canUseLeft || canUseRight) interval = duration;
        res = Math.max(res, leftGap + interval + rightGap);
    }
    return res;
};

function sortMatrixDiagonals(grid) {
    const n = grid.length;
    const diag = new Map();                     // collect elements per diagonal

    // first pass – group values by i‑j
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            const key = i - j;
            if (!diag.has(key)) diag.set(key, []);
            diag.get(key).push(grid[i][j]);
        }
    }

    // second pass – sort each diagonal and write back
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            const key = i - j;
            const list = diag.get(key);
            // main logic: choose sorting direction based on diagonal position
            if (key < 0) {                       // above main diagonal → ascending
                list.sort((a, b) => a - b);
            } else {                             // on / below main diagonal → descending
                list.sort((a, b) => b - a);
            }
            grid[i][j] = list.shift();           // place the next element
        }
    }
    return grid;
}

function assignElements(groups, elements) {
    // map each element value to its smallest index
    const smallestIdx = {};
    for (let i = 0; i < elements.length; i++) {
        const v = elements[i];
        if (smallestIdx[v] === undefined) smallestIdx[v] = i; // store first occurrence
    }

    const result = new Array(groups.length);
    for (let gi = 0; gi < groups.length; gi++) {
        const g = groups[gi];
        let best = Infinity;                     // smallest index found so far

        // enumerate all divisors of g
        for (let d = 1; d * d <= g; d++) {
            if (g % d !== 0) continue;           // d is not a divisor
            const d1 = d;
            const d2 = g / d;

            if (smallestIdx[d1] !== undefined && smallestIdx[d1] < best) {
                best = smallestIdx[d1];           // candidate divisor d1
            }
            if (d2 !== d1 && smallestIdx[d2] !== undefined && smallestIdx[d2] < best) {
                best = smallestIdx[d2];           // candidate divisor d2
            }
        }

        result[gi] = best === Infinity ? -1 : best; // -1 if no divisor found
    }
    return result;
}

function maxDifferenceEvenOdd(s, k) {
    const n = s.length;
    const INF = Number.MAX_SAFE_INTEGER;
    let ans = -Infinity;
    for (let a = 0; a <= 4; a++) {
        for (let b = 0; b <= 4; b++) {
            if (a === b) continue;
            const aChar = String(a), bChar = String(b);
            let curA = 0, curB = 0, preA = 0, preB = 0;
            const t = [[INF, INF],[INF, INF]];
            let l = -1;
            for (let r = 0; r < n; r++) {
                if (s[r] === aChar) curA++;
                if (s[r] === bChar) curB++;
                while (r - l >= k && curB - preB >= 2) {
                    const pa = preA & 1, pb = preB & 1;
                    if (preA - preB < t[pa][pb]) t[pa][pb] = preA - preB;
                    l++;
                    if (s[l] === aChar) preA++;
                    if (s[l] === bChar) preB++;
                }
                const idxA = (curA & 1) ^ 1;
                const idxB = curB & 1;
                const cand = curA - curB - t[idxA][idxB];
                if (cand > ans) ans = cand;
            }
        }
    }
    return ans;
}

function maximizeTheMinimumGameScore(points, m) {
    const maxP = points.length ? Math.max(...points) : 0;
    let low = 0, high = maxP * m;
    while (low < high) {
        const mid = Math.floor((low + high + 1) / 2);
        let need = 0;
        for (const v of points) {
            need += Math.ceil(mid / v);
            if (need > m) break;
        }
        if (need <= m) low = mid; else high = mid - 1;
    }
    return low;
}

function countSubstringsDivisibleByLastDigit(s) {
    const cnt = Array.from({ length: 10 }, (_, d) => (d === 0 ? null : new Array(d).fill(0)));
    let ans = 0;
    for (let i = 0; i < s.length; i++) {
        const cur = s.charCodeAt(i) - 48;
        const next = Array.from({ length: 10 }, (_, d) => (d === 0 ? null : new Array(d).fill(0)));
        for (let d = 1; d <= 9; d++) {
            const oldArr = cnt[d];
            const newArr = next[d];
            for (let r = 0; r < d; r++) {
                const newR = (r * 10 + cur) % d;
                newArr[newR] += oldArr[r];
            }
            const r0 = cur % d;
            newArr[r0] += 1;
        }
        if (cur !== 0) {
            ans += next[cur][0];
        }
        for (let d = 1; d <= 9; d++) {
            cnt[d] = next[d];
        }
    }
    return ans;
}

function sumGoodNumbers(nums, k) {
    let total = 0;
    // iterate and add element if it is greater than its k‑distance neighbors
    for (let i = 0; i < nums.length; i++) {
        let leftIdx = i - k;
        let rightIdx = i + k;
        let isGood = true;
        if (leftIdx >= 0 && nums[i] <= nums[leftIdx]) isGood = false;
        if (rightIdx < nums.length && nums[i] <= nums[rightIdx]) isGood = false;
        if (isGood) total += nums[i];
    }
    return total;
}

function separateSquaresI(squares) {
    let totalArea = 0.0;
    let low = Infinity, high = -Infinity;
    const events = new Map();
    for (const [, y, l] of squares) {
        totalArea += l * l;
        low = Math.min(low, y);
        high = Math.max(high, y + l);
        events.set(y, (events.get(y) || 0.0) - l);
        events.set(y + l, (events.get(y + l) || 0.0) + l);
    }

    const half = totalArea / 2.0;
    let currentH = low, currentArea = totalArea, slope = 0.0;

    const sortedKeys = [...events.keys()].sort((a, b) => a - b);
    for (const h of sortedKeys) {
        if (h > currentH) {
            if (slope !== 0.0) {
                const nextArea = currentArea + slope * (h - currentH);
                if ((slope < 0 && currentArea >= half && half >= nextArea) || (slope > 0 && currentArea <= half && half <= nextArea)) {
                    return Math.round((currentH + (half - currentArea) / slope) * 100000) / 100000;
                }
            } else {
                if (currentArea === half) return Math.round(currentH * 100000) / 100000;
            }
            currentArea += slope * (h - currentH);
            currentH = h;
        }
        slope += events.get(h);
    }
    return Math.round(high * 100000) / 100000;
}

function findSpecialSubstring(s, k) {
  if (k <= 0) return false;                     // edge case
  let run = 1;                                   // length of current equal-char run
  for (let i = 1; i < s.length; i++) {
    if (s[i] === s[i - 1]) {                     // same as previous char
      run++;                                     // extend run
    } else {
      run = 1;                                   // reset run
    }
    if (run === k) return true;                  // found a run of length k
  }
  return false;
}

var shortestMatchingSubstring = function(s, p) {
    const first = p.indexOf('*');
    const second = p.indexOf('*', first+1);
    const A = p.slice(0, first);
    const B = p.slice(first+1, second);
    const C = p.slice(second+1);
    const n = s.length;
    function allOccurrences(sub) {
        if (!sub) {
            const res = [];
            for (let i=0;i<=n;i++) res.push(i);
            return res;
        }
        const res = [];
        let start = 0;
        while (true) {
            const idx = s.indexOf(sub, start);
            if (idx === -1) break;
            res.push(idx);
            start = idx+1;
        }
        return res;
    }
    const startsB = allOccurrences(B);
    const startsC = allOccurrences(C);
    const startsA = allOccurrences(A);
    const nextB = new Array(n+1).fill(-1);
    let idxB = 0;
    for (let pos=0; pos<=n; pos++) {
        while (idxB < startsB.length && startsB[idxB] < pos) idxB++;
        if (idxB < startsB.length) nextB[pos] = startsB[idxB];
    }
    const nextC = new Array(n+1).fill(-1);
    let idxC = 0;
    for (let pos=0; pos<=n; pos++) {
        while (idxC < startsC.length && startsC[idxC] < pos) idxC++;
        if (idxC < startsC.length) nextC[pos] = startsC[idxC];
    }
    let best = Infinity;
    const lenA=A.length, lenB=B.length, lenC=C.length;
    for (const i of startsA) {
        const posB = i+lenA;
        if (posB > n) continue;
        const j = nextB[posB];
        if (j === -1) continue;
        const posC = j+lenB;
        if (posC > n) continue;
        const k = nextC[posC];
        if (k === -1) continue;
        const length = (k+lenC) - i;
        if (length < best) best = length;
    }
    return best === Infinity ? -1 : best;
};

function separateSquaresII(squares) {
    const n = squares.length;
    const xs = [];
    const events = [];
    for (let i = 0; i < n; i++) {
        const [x, y, l] = squares[i];
        const x1 = x;
        const x2 = x + l;
        const y1 = y;
        const y2 = y + l;
        xs.push(x1, x2);
        events.push({ y: y1, delta: 1, x1, x2 });
        events.push({ y: y2, delta: -1, x1, x2 });
    }
    xs.sort((a, b) => a - b);
    const uniqXs = [];
    for (let i = 0; i < xs.length; i++) {
        if (i === 0 || xs[i] !== xs[i - 1]) uniqXs.push(xs[i]);
    }
    const m = uniqXs.length - 1; // number of elementary intervals
    const segCnt = new Int32Array(m * 4);
    const segLen = new Float64Array(m * 4);
    function update(node, l, r, ql, qr, delta) {
        if (qr <= l || r <= ql) return;
        if (ql <= l && r <= qr) {
            segCnt[node] += delta;
        } else {
            const mid = (l + r) >> 1;
            update(node << 1, l, mid, ql, qr, delta);
            update(node << 1 | 1, mid, r, ql, qr, delta);
        }
        if (segCnt[node] > 0) {
            segLen[node] = uniqXs[r] - uniqXs[l];
        } else {
            if (l + 1 === r) {
                segLen[node] = 0;
            } else {
                segLen[node] = segLen[node << 1] + segLen[node << 1 | 1];
            }
        }
    }
    // map x to index
    function indexOf(val) {
        // binary search in uniqXs
        let lo = 0, hi = uniqXs.length - 1;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (uniqXs[mid] < val) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
    // prepare events with indices
    for (let e of events) {
        e.l = indexOf(e.x1);
        e.r = indexOf(e.x2);
    }
    events.sort((a, b) => a.y - b.y);
    let totalArea = 0;
    let prevY = events[0].y;
    let i = 0;
    while (i < events.length) {
        const curY = events[i].y;
        const deltaY = curY - prevY;
        const width = segLen[1];
        totalArea += width * deltaY;
        // process all events at curY
        while (i < events.length && events[i].y === curY) {
            const e = events[i];
            update(1, 0, m, e.l, e.r, e.delta);
            i++;
        }
        prevY = curY;
    }
    const half = totalArea / 2;
    // second sweep to find answer
    // reset segment tree
    segCnt.fill(0);
    segLen.fill(0);
    prevY = events[0].y;
    let areaSoFar = 0;
    i = 0;
    while (i < events.length) {
        const curY = events[i].y;
        const deltaY = curY - prevY;
        const width = segLen[1];
        if (width > 0) {
            const possible = areaSoFar + width * deltaY;
            if (possible >= half) {
                const needed = half - areaSoFar;
                const ansY = prevY + needed / width;
                return ansY;
            }
            areaSoFar = possible;
        }
        // apply events at curY
        while (i < events.length && events[i].y === curY) {
            const e = events[i];
            update(1, 0, m, e.l, e.r, e.delta);
            i++;
        }
        prevY = curY;
    }
    // If not found within events (should not happen), return last y
    return prevY;
}

function maxSum(grid, limits, k) {
    const n = grid.length;
    const flat = [];                       // collect all values with row index
    for (let i = 0; i < n; i++) {
        const row = grid[i];
        for (let j = 0; j < row.length; j++) {
            flat.push([row[j], i]);        // [value, row]
        }
    }
    flat.sort((a, b) => b[0] - a[0]);      // descending by value

    const used = new Array(n).fill(0);     // how many taken from each row
    let taken = 0;
    let sum = 0;

    for (let idx = 0; idx < flat.length && taken < k; idx++) {
        const [val, row] = flat[idx];
        if (val <= 0) break;               // no benefit from non‑positive numbers
        if (used[row] < limits[row]) {     // row still has capacity
            sum += val;
            used[row]++;                    // record the pick
            taken++;
        }
    }
    return sum;
}

