function maxWeight(pizzas) {
    const n = pizzas.length;
    const days = n / 4;
    const odd = Math.ceil(days / 2);
    const even = days - odd;
    const sorted = pizzas.slice().sort((a, b) => a - b);
    let i = n - 1;
    let ans = 0n;
    for (let j = 0; j < odd; j++, i -= 1) ans += BigInt(sorted[i]);
    for (let j = 0; j < even; j++, i -= 2) ans += BigInt(sorted[i - 1]);
    return Number(ans);
}

function maxSubstringLength(s, k) {
    const n = s.length;
    const first = new Map(), last = new Map();
    for (let i = 0; i < n; i++) {
        if (!first.has(s[i])) first.set(s[i], i);
        last.set(s[i], i);
    }
    const intervals = [];
    for (const [ch, st] of first) {
        let l = st, r = last.get(ch);
        let changed = true;
        while (changed) {
            changed = false;
            for (let i = l; i <= r; i++) {
                const c = s[i];
                if (first.get(c) < l) { l = first.get(c); changed = true; }
                if (last.get(c) > r) { r = last.get(c); changed = true; }
            }
        }
        if (!(l === 0 && r === n-1)) intervals.push([l, r]);
    }
    intervals.sort((a,b)=>a[1]-b[1]);
    let count = 0, lastEnd = -1;
    for (const [l,r] of intervals) {
        if (l > lastEnd) { count++; lastEnd = r; }
    }
    return count >= k;
}

var lenOfVDiagonal = function(grid) {
    const m = grid.length, n = grid[0].length;
    const dirs = [1,1,-1,-1,1];
    const memo = new Array(m);
    for (let i=0;i<m;i++){
        memo[i]=new Array(n);
        for (let j=0;j<n;j++){
            memo[i][j]=[[null,null],[null,null],[null,null],[null,null]];
        }
    }
    function dfs(i,j,k,cnt){
        if (memo[i][j][k][cnt]!==null) return memo[i][j][k][cnt];
        const target = grid[i][j]===2?0:2;
        let best=0;
        const x=i+dirs[k], y=j+dirs[k+1];
        if (x>=0&&x<m&&y>=0&&y<n&&grid[x][y]===target){
            best = dfs(x,y,k,cnt)+1;
        }
        if (cnt===0){
            const k2=(k+1)%4;
            const x2=i+dirs[k2], y2=j+dirs[k2+1];
            if (x2>=0&&x2<m&&y2>=0&&y2<n&&grid[x2][y2]===target){
                best = Math.max(best, dfs(x2,y2,k2,1)+1);
            }
        }
        memo[i][j][k][cnt]=best;
        return best;
    }
    let ans=0;
    for (let i=0;i<m;i++){
        for (let j=0;j<n;j++){
            if (grid[i][j]===1){
                for (let k=0;k<4;k++){
                    ans = Math.max(ans, dfs(i,j,k,0)+1);
                }
            }
        }
    }
    return ans;
};

function areFinalDigitsEqual(s) {
    while (s.length > 2) {
        let next = '';
        for (let i = 0; i < s.length - 1; i++) {
            const sum = (s.charCodeAt(i) - 48) + (s.charCodeAt(i + 1) - 48);
            next += String.fromCharCode((sum % 10) + 48);
        }
        s = next;
    }
    return s[0] === s[1];
}

function maxDistance(side, points, k) {
  const n = points.length;
  function perimeterPos([x, y]) {
    if (y === 0) return x;
    if (x === side) return side + y;
    if (y === side) return 2 * side + (side - x);
    return 3 * side + (side - y);
  }
  const augmented = points.map(p => [p, perimeterPos(p)]);
  augmented.sort((a, b) => a[1] - b[1]);
  const sorted = augmented.map(a => a[0]);

  function dist(p1, p2) { return Math.abs(p1[0] - p2[0]) + Math.abs(p1[1] - p2[1]); }

  function feasible(d) {
    for (let start = 0; start < n; start++) {
      let count = 1;
      let last = sorted[start];
      const anchor = sorted[start];
      for (let step = 1; step < n; step++) {
        const cand = sorted[(start + step) % n];
        if (dist(last, cand) >= d) { count++; last = cand; }
      }
      if (count >= k && dist(last, anchor) >= d) return true;
    }
    return false;
  }

  let lo = 0, hi = 2 * side;
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2);
    if (feasible(mid)) lo = mid; else hi = mid - 1;
  }
  return lo;
}

function transformArrayByParity(nums) {
    // count how many numbers are even
    let evenCount = 0;
    for (let i = 0; i < nums.length; i++) {
        if (nums[i] % 2 === 0) evenCount++;
    }

    // build the sorted parity array: evens (0) first, then odds (1)
    const result = new Array(nums.length);
    for (let i = 0; i < evenCount; i++) result[i] = 0;
    for (let i = evenCount; i < nums.length; i++) result[i] = 1;

    return result;
}

function countCopyArrays(original, bounds) {
    let L = -Infinity;
    let R = Infinity;
    for (let i = 0; i < original.length; i++) {
        const lo = bounds[i][0] - original[i];
        const hi = bounds[i][1] - original[i];
        if (lo > L) L = lo;
        if (hi < R) R = hi;
    }
    return R >= L ? R - L + 1 : 0;
}

function checkIfDigitsEqualAfterOperationsII(s) {
    const n = s.length;
    let cur = s.charCodeAt(0) - 48;
    for (let i = 1; i < n - 1; i++) {
        cur = (cur + (s.charCodeAt(i) - 48)) % 10;
    }
    const last = s.charCodeAt(n - 1) - 48;
    return cur === last;
}

function generateString(str1, str2) {
    const n = str1.length;
    const m = str2.length;
    const L = n + m - 1;
    const w = new Array(L).fill(null);
    const posToF = Array.from({ length: L }, () => []);
    const fStarts = [];
    const fFixed = [];
    const fEqual = [];

    // First pass: handle 'T' constraints and record 'F' windows
    for (let i = 0; i < n; i++) {
        if (str1[i] === 'T') {
            for (let j = 0; j < m; j++) {
                const pos = i + j;
                const ch = str2[j];
                if (w[pos] === null) {
                    w[pos] = ch;
                } else if (w[pos] !== ch) {
                    return "";
                }
            }
        } else { // 'F'
            const id = fStarts.length;
            fStarts.push(i);
            fFixed.push(0);
            fEqual.push(0);
            for (let j = 0; j < m; j++) {
                const pos = i + j;
                posToF[pos].push(id);
            }
        }
    }

    // Update counts for forced positions
    for (let pos = 0; pos < L; pos++) {
        const ch = w[pos];
        if (ch === null) continue;
        const list = posToF[pos];
        for (let k = 0; k < list.length; k++) {
            const id = list[k];
            fFixed[id] += 1;
            const offset = pos - fStarts[id];
            if (ch === str2[offset]) fEqual[id] += 1;
        }
    }

    // Immediate violation check
    for (let id = 0; id < fStarts.length; id++) {
        if (fEqual[id] === m) return "";
    }

    // Greedy fill remaining positions with smallest possible letters
    const alphabet = 'abcdefghijklmnopqrstuvwxyz';
    for (let pos = 0; pos < L; pos++) {
        if (w[pos] !== null) continue; // already fixed by 'T'

        const covering = posToF[pos];
        let chosen = null;

        outer: for (let ci = 0; ci < alphabet.length; ci++) {
            const ch = alphabet[ci];
            // test against all covering F-windows
            for (let k = 0; k < covering.length; k++) {
                const id = covering[k];
                const offset = pos - fStarts[id];
                const wouldEqual = (ch === str2[offset]) ? 1 : 0;
                if (fEqual[id] + wouldEqual === m && fFixed[id] + 1 === m) {
                    // this would complete a forbidden window
                    continue outer;
                }
            }
            chosen = ch;
            break;
        }

        if (chosen === null) return ""; // no feasible character

        w[pos] = chosen;
        // update counts for covering windows
        for (let k = 0; k < covering.length; k++) {
            const id = covering[k];
            fFixed[id] += 1;
            const offset = pos - fStarts[id];
            if (chosen === str2[offset]) fEqual[id] += 1;
        }
    }

    return w.join('');
}
// TIME: O(L * (average covering windows) * 26) SPACE: O(L + number of F windows)

function minCostRemoveArray(nums) {
    const sorted = nums.slice().sort((a, b) => a - b);
    const n = sorted.length;
    const dp = new Array(n + 1).fill(Infinity);
    dp[0] = 0;
    if (n >= 1) dp[1] = sorted[0];
    for (let i = 2; i <= n; i++) {
        dp[i] = Math.min(dp[i - 1] + sorted[i - 1], dp[i - 2] + sorted[i - 1]);
    }
    return dp[n];
}

function permute(n, k) {
  k = BigInt(k);
  const fact = [1n];
  for (let i = 1; i <= n; i++) fact.push(fact[i-1] * BigInt(i));

  let oddCount = Math.ceil(n/2), evenCount = Math.floor(n/2);
  // total valid perms overall (for early exit if k too large)
  function totalCount() {
    if (n === 0) return 1n;
    if (n === 1) return 1n; // single element, trivially valid (no adjacent pair)
    if (Math.abs(oddCount - evenCount) > 1) return 0n;
    if (oddCount === evenCount) return 2n * fact[oddCount] * fact[evenCount];
    return fact[oddCount] * fact[evenCount];
  }
  if (k > totalCount()) return [];

  const used = new Array(n+1).fill(false);
  const result = [];
  let remOdd = oddCount, remEven = evenCount;
  let prevParity = null; // 0 = even, 1 = odd

  for (let pos = 0; pos < n; pos++) {
    let placed = false;
    for (let v = 1; v <= n; v++) {
      if (used[v]) continue;
      const parity = v % 2; // 1 odd, 0 even
      if (prevParity !== null && parity === prevParity) continue;
      const newRemOdd = remOdd - (parity === 1 ? 1 : 0);
      const newRemEven = remEven - (parity === 0 ? 1 : 0);
      const L = newRemOdd + newRemEven;
      let cnt;
      if (L === 0) {
        cnt = 1n;
      } else {
        const nextParityOdd = (parity === 0); // if current is even, next must be odd
        const neededOdd = nextParityOdd ? Math.ceil(L/2) : Math.floor(L/2);
        const neededEven = L - neededOdd;
        if (newRemOdd === neededOdd && newRemEven === neededEven) {
          cnt = fact[newRemOdd] * fact[newRemEven];
        } else {
          cnt = 0n;
        }
      }
      if (k <= cnt) {
        used[v] = true;
        result.push(v);
        remOdd = newRemOdd; remEven = newRemEven; prevParity = parity;
        placed = true;
        break;
      } else {
        k -= cnt;
      }
    }
    if (!placed) return []; // shouldn't happen if totalCount check passed
  }
  return result;
}

function longestPalindromicSubseqAfterKOps(s, k) {
    const n = s.length;
    const K = k;
    const codes = new Uint8Array(n);
    for (let i = 0; i < n; i++) codes[i] = s.charCodeAt(i) - 97;

    const dist = Array.from({ length: 26 }, () => new Uint8Array(26));
    for (let a = 0; a < 26; a++) {
        for (let b = 0; b < 26; b++) {
            const d = Math.abs(a - b);
            dist[a][b] = Math.min(d, 26 - d);
        }
    }

    const zeroArr = new Uint8Array(K + 1);
    const dp = Array.from({ length: n }, () => Array(n));

    for (let i = 0; i < n; i++) {
        const arr = new Uint8Array(K + 1);
        arr.fill(1);
        dp[i][i] = arr;
    }

    for (let len = 2; len <= n; len++) {
        for (let l = 0; l + len - 1 < n; l++) {
            const r = l + len - 1;
            const cur = new Uint8Array(K + 1);
            const left = dp[l + 1][r];
            const right = dp[l][r - 1];
            const inner = l + 1 <= r - 1 ? dp[l + 1][r - 1] : zeroArr;
            const cost = dist[codes[l]][codes[r]];
            for (let c = 0; c <= K; c++) {
                let best = left[c];
                if (right[c] > best) best = right[c];
                if (cost <= c) {
                    const cand = inner[c - cost] + 2;
                    if (cand > best) best = cand;
                }
                cur[c] = best;
            }
            dp[l][r] = cur;
        }
    }

    return dp[0][n - 1][K];
}

var maxSumKSubarrays = function(nums, k, m) {
    const n = nums.length;
    const NEG_INF = -1e18;
    const pref = new Array(n+1).fill(0);
    for (let i=1;i<=n;i++) pref[i] = pref[i-1] + nums[i-1];
    let dpPrev = new Array(n+1).fill(NEG_INF);
    dpPrev[0] = 0;
    for (let t=0; t<k; t++) {
        const dpCurr = new Array(n+1).fill(NEG_INF);
        let best = NEG_INF;
        for (let i=m; i<=n; i++) {
            const candidate = dpPrev[i-m] - pref[i-m];
            if (candidate > best) best = candidate;
            const cur = best + pref[i];
            dpCurr[i] = cur > dpCurr[i-1] ? cur : dpCurr[i-1];
        }
        dpPrev = dpCurr;
    }
    return dpPrev[n];
};

function largestInteger(nums, k) {
  const n = nums.length;
  const values = [...new Set(nums)];
  let best = -1;
  for (const x of values) {
    let windowCount = 0;
    for (let s = 0; s + k <= n; s++) {
      let found = false;
      for (let i = s; i < s + k; i++) if (nums[i] === x) { found = true; break; }
      if (found) windowCount++;
      if (windowCount > 1) break;
    }
    if (windowCount === 1 && x > best) best = x;
  }
  return best;
}

function fruitsIntoBasketsII(fruits, baskets) {
    const fruitsSorted = [...fruits].sort((a, b) => a - b);
    const basketsSorted = [...baskets].sort((a, b) => a - b);
    let i = 0, j = 0, placed = 0;
    while (i < fruitsSorted.length && j < basketsSorted.length) {
        if (basketsSorted[j] > fruitsSorted[i]) { placed++; i++; j++; }
        else j++;
    }
    return fruits.length - placed;
}

function numOfUnplacedFruits(fruits, baskets) {
    const n = baskets.length;
    const tree = new Array(4*n).fill(0);
    function build(node, l, r) {
        if (l === r) { tree[node] = baskets[l]; return; }
        const mid = (l+r)>>1;
        build(2*node, l, mid); build(2*node+1, mid+1, r);
        tree[node] = Math.max(tree[2*node], tree[2*node+1]);
    }
    function query(node, l, r, need) {
        if (tree[node] < need) return -1;
        if (l === r) { tree[node] = -1; return l; }
        const mid = (l+r)>>1;
        let res = query(2*node, l, mid, need);
        if (res === -1) res = query(2*node+1, mid+1, r, need);
        tree[node] = Math.max(tree[2*node], tree[2*node+1]);
        return res;
    }
    build(1, 0, n-1);
    let unplaced = 0;
    for (const f of fruits) {
        const pos = query(1, 0, n-1, f);
        if (pos === -1) unplaced++;
    }
    return unplaced;
}

function chooseKElementsWithMaximumSum(nums1, nums2, k) {
    const n = nums1.length;
    if (n === 0 || k <= 0) return new Array(n).fill(0);
    const order = Array.from({length: n}, (_, i) => i).sort((a, b) => nums1[a] - nums1[b]);
    const answer = new Array(n).fill(0);

    class MinHeap {
        constructor() { this.a = []; }
        push(v) { this.a.push(v); let i = this.a.length - 1; while (i > 0) { const p = (i-1)>>1; if (this.a[p] > this.a[i]) { [this.a[p],this.a[i]]=[this.a[i],this.a[p]]; i=p; } else break; } }
        replace(v) { this.a[0] = v; let i = 0; while (true) { let l=2*i+1,r=2*i+2,s=i; if (l<this.a.length && this.a[l]<this.a[s]) s=l; if (r<this.a.length && this.a[r]<this.a[s]) s=r; if (s===i) break; [this.a[i],this.a[s]]=[this.a[s],this.a[i]]; i=s; } }
        get length() { return this.a.length; }
        get top() { return this.a[0]; }
    }
    const heap = new MinHeap();
    let curSum = 0;
    let i = 0;
    while (i < n) {
        let j = i;
        const curVal = nums1[order[i]];
        while (j < n && nums1[order[j]] === curVal) j++;
        for (let p = i; p < j; p++) answer[order[p]] = curSum;
        for (let p = i; p < j; p++) {
            const v = nums2[order[p]];
            if (heap.length < k) { heap.push(v); curSum += v; }
            else if (v > heap.top) { curSum += v - heap.top; heap.replace(v); }
        }
        i = j;
    }
    return answer;
}

var longestSpecialPath = function(edges, nums) {
    const n = nums.length;
    const adj = Array.from({length:n}, () => []);
    for (const [u,v,w] of edges) { adj[u].push([v,w]); adj[v].push([u,w]); }
    const maxVal = Math.max(...nums);
    const last = new Array(maxVal+1).fill(-1);
    const path = [];
    const pref = [0];
    let left = 0;
    let bestSum = 0, bestLen = 0;
    const stack = [[0,-1,0,0,-1,0]];
    while (stack.length) {
        const top = stack.pop();
        const node=top[0], parent=top[1], weight=top[2], state=top[3], prevLastIn=top[4], prevLeftIn=top[5];
        if (state === 0) {
            const val = nums[node];
            const prevLast = last[val];
            const prevLeft = left;
            const idx = path.length;
            path.push(node);
            pref.push(pref[pref.length-1] + weight);
            left = Math.max(left, prevLast+1);
            last[val] = idx;
            const curSum = pref[pref.length-1] - (left>0 ? pref[left] : 0);
            const curLen = idx - left + 1;
            if (curSum > bestSum || (curSum === bestSum && curLen > bestLen)) {
                bestSum = curSum; bestLen = curLen;
            }
            stack.push([node, parent, weight, 1, prevLast, prevLeft]);
            for (const [nei, w] of adj[node]) {
                if (nei === parent) continue;
                stack.push([nei, node, w, 0, -1, 0]);
            }
        } else {
            const val = nums[node];
            last[val] = prevLastIn;
            left = prevLeftIn;
            path.pop();
            pref.pop();
        }
    }
    return [bestSum, bestLen];
};

function countEvenNumbers(digits) {
    // build frequency table
    const freq = new Array(10).fill(0);
    for (const d of digits) freq[d]++;

    let total = 0;

    // try every possible even last digit
    for (let last = 0; last <= 8; last += 2) {          // MAIN LOGIC: iterate over all even last digits
        if (freq[last] === 0) continue;                // not enough of this digit
        freq[last]--;                                   // reserve it

        // first digit cannot be zero
        for (let first = 1; first <= 9; ++first) {
            if (freq[first] === 0) continue;
            freq[first]--;                              // reserve it

            // middle digit can be any digit
            for (let mid = 0; mid <= 9; ++mid) {
                if (freq[mid] === 0) continue;
                total++;                                 // a distinct 3‑digit even number exists
            }

            freq[first]++;                               // release first digit
        }

        freq[last]++;                                   // release last digit
    }

    return total;
}

class Spreadsheet {
    constructor(rows) {
        this.rows = rows;
        this.cells = new Map();
    }
    setCell(cell, value) { this.cells.set(cell, value); }
    resetCell(cell) { this.cells.delete(cell); }
    getValue(formula) {
        if (formula[0] === '=') {
            const parts = formula.slice(1).split('+');
            let total = 0;
            for (const p of parts) {
                if (/^[A-Z][0-9]+$/.test(p)) total += this.cells.get(p) || 0;
                else total += parseInt(p, 10);
            }
            return total;
        }
        return this.cells.get(formula) || 0;
    }
}

function closestEqualElementQueries(nums, queries) {
    const n = nums.length;
    const positions = new Map();
    nums.forEach((v, i) => { if (!positions.has(v)) positions.set(v, []); positions.get(v).push(i); });

    const precomputed = new Array(n).fill(-1);
    for (const vec of positions.values()) {
        const sz = vec.length;
        if (sz === 1) continue;
        for (let i = 0; i < sz; i++) {
            const cur = vec[i];
            const nxt = vec[(i + 1) % sz];
            const prev = vec[((i - 1) % sz + sz) % sz];
            const forward = ((nxt - cur) % n + n) % n;
            const backward = ((cur - prev) % n + n) % n;
            precomputed[cur] = Math.min(forward, backward);
        }
    }
    return queries.map(idx => precomputed[idx]);
}

function minQueriesToZeroArray(nums, queries) {
    const n = nums.length;
    let zeroCount = 0;
    for (let i = 0; i < n; i++) {
        if (nums[i] === 0) zeroCount++;
    }
    if (zeroCount === n) return 0;
    for (let k = 0; k < queries.length; k++) {
        const [l, r, val] = queries[k];
        for (let i = l; i <= r; i++) {
            if (nums[i] > 0) {
                nums[i] = Math.max(0, nums[i] - val);
                if (nums[i] === 0) zeroCount++;
            }
        }
        if (zeroCount === n) return k + 1;
    }
    return -1;
}

function longestCommonPrefixAfterRemoval(words, k) {
    const n = words.length;
    if (n - 1 < k) return Array(n).fill(0);
    const nodes = [{ children: Object.create(null), count: 0, depth: 0 }];
    const paths = new Array(n);
    let maxDepth = 0;
    for (let i = 0; i < n; i++) {
        const w = words[i];
        let cur = 0;
        const path = [];
        for (const ch of w) {
            const node = nodes[cur];
            if (!node.children[ch]) {
                nodes.push({ children: Object.create(null), count: 0, depth: node.depth + 1 });
                node.children[ch] = nodes.length - 1;
            }
            cur = node.children[ch];
            nodes[cur].count++;
            path.push(cur);
        }
        paths[i] = path;
        if (w.length > maxDepth) maxDepth = w.length;
    }
    const totalGood = new Array(maxDepth + 1).fill(0);
    for (let i = 1; i < nodes.length; i++) {
        const node = nodes[i];
        if (node.count >= k) totalGood[node.depth]++;
        node.isCritical = node.count === k;
    }
    let globalMaxDepth = 0;
    for (let d = maxDepth; d >= 1; d--) {
        if (totalGood[d] > 0) {
            globalMaxDepth = d;
            break;
        }
    }
    const ans = new Array(n);
    for (let i = 0; i < n; i++) {
        const len = words[i].length;
        if (globalMaxDepth > len) {
            ans[i] = globalMaxDepth;
            continue;
        }
        const path = paths[i];
        let best = 0;
        for (let d = len; d >= 1; d--) {
            let good = totalGood[d];
            const nodeId = path[d - 1];
            if (nodes[nodeId].isCritical) good--;
            if (good > 0) {
                best = d;
                break;
            }
        }
        ans[i] = best;
    }
    return ans;
}

function countBeautifulNumbers(l, r) {
  function countUpTo(x) {
    if (x <= 0) return 0;
    const digits = Array.from(String(x), ch => ch.charCodeAt(0) - 48);
    const n = digits.length;
    const maxSum = 9 * n;
    let total = 0;
    for (let S = 1; S <= maxSum; S++) {
      const memo = new Map();
      function dfs(pos, sum, prodMod, tight, started) {
        if (pos === n) {
          return started && sum === S && prodMod === 0 ? 1 : 0;
        }
        const key = pos + '|' + sum + '|' + prodMod + '|' + (tight ? 1 : 0) + '|' + (started ? 1 : 0);
        if (!tight && memo.has(key)) return memo.get(key);
        const limit = tight ? digits[pos] : 9;
        let res = 0;
        for (let d = 0; d <= limit; d++) {
          const nextStarted = started || d !== 0;
          const nextSum = sum + (nextStarted ? d : 0);
          if (nextSum > S) continue;
          let nextProdMod;
          if (!nextStarted) {
            nextProdMod = prodMod;
          } else if (!started && d !== 0) {
            nextProdMod = d % S;
          } else if (started && d === 0) {
            nextProdMod = 0;
          } else {
            nextProdMod = (prodMod * d) % S;
          }
          const nextTight = tight && d === limit;
          res += dfs(pos + 1, nextSum, nextProdMod, nextTight, nextStarted);
        }
        if (!tight) memo.set(key, res);
        return res;
      }
      total += dfs(0, 0, 1 % S, true, false);
    }
    return total;
  }
  return countUpTo(r) - countUpTo(l - 1);
}

function minBrewTime(skill, mana) {
    const n = skill.length;
    const m = mana.length;
    let done = new Array(n).fill(0);

    for (let j = 0; j < m; j++) {
        const idealStart = new Array(n).fill(0);
        for (let i = 1; i < n; i++) {
            idealStart[i] = idealStart[i - 1] + skill[i - 1] * mana[j];
        }
        let shift = 0;
        for (let i = 0; i < n; i++) {
            shift = Math.max(shift, done[i] - idealStart[i]);
        }
        const finish = new Array(n);
        for (let i = 0; i < n; i++) {
            const start = idealStart[i] + shift;
            finish[i] = start + skill[i] * mana[j];
        }
        done = finish;
    }
    return done[n - 1];
}

function maximumUniqueSubarray(nums) {
    const lastPos = new Map();          // stores last index of each value
    let left = 0;
    let curSum = 0;
    let best = 0;

    for (let right = 0; right < nums.length; right++) {
        const val = nums[right];

        // if val already in window, move left past its previous occurrence
        if (lastPos.has(val) && lastPos.get(val) >= left) {
            const newLeft = lastPos.get(val) + 1;
            while (left < newLeft) {    // shrink window and update sum
                curSum -= nums[left];
                left++;
            }
        }

        curSum += val;                   // extend window to include val
        lastPos.set(val, right);         // remember its latest position
        if (curSum > best) best = curSum; // update answer
    }

    return best;
}

function reverseDegree(s) {
    let ans = 0;
    for (let i = 0; i < s.length; i++) {
        const rev = 122 - s.charCodeAt(i) + 1;
        ans += (i + 1) * rev;
    }
    return ans;
}

function maxContainers(n, w, maxWeight) {
    // compute max containers limited by deck size and weight capacity
    const cells = n * n;
    const byWeight = Math.floor(maxWeight / w);
    return Math.min(cells, byWeight);
}

function numberOfComponents(properties, k) {
    const n = properties.length;
    if (n === 0) return 0;
    const sets = properties.map(p => new Set(p));
    const parent = Array.from({length: n}, (_, i) => i);
    const rank = new Array(n).fill(0);

    function find(x) {
        while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; }
        return x;
    }
    function unite(a, b) {
        let ra = find(a), rb = find(b);
        if (ra === rb) return;
        if (rank[ra] < rank[rb]) [ra, rb] = [rb, ra];
        parent[rb] = ra;
        if (rank[ra] === rank[rb]) rank[ra]++;
    }

    for (let i = 0; i < n; i++) {
        for (let j = i+1; j < n; j++) {
            let a = sets[i], b = sets[j];
            let small, large;
            if (a.size > b.size) { small = b; large = a; } else { small = a; large = b; }
            let common = 0;
            for (const val of small) {
                if (large.has(val)) {
                    common++;
                    if (common >= k) break;
                }
            }
            if (common >= k) unite(i, j);
        }
    }
    const roots = new Set();
    for (let i = 0; i < n; i++) roots.add(find(i));
    return roots.size;
}

function sumMinimumOperations(queries) {
    let total = 0;
