}

function maxActiveSectionsAfterTrade(s, queries) {
    const n = s.length;
    const prefOne = new Array(n+1).fill(0);
    const prefZero = new Array(n+1).fill(0);
    for (let i = 0; i < n; i++) {
        prefOne[i+1] = prefOne[i] + (s[i] === '1' ? 1 : 0);
        prefZero[i+1] = prefZero[i] + (s[i] === '0' ? 1 : 0);
    }
    const totalOnes = prefOne[n];

    const nextZero = new Array(n).fill(n);
    let nxt = n;
    for (let i = n-1; i >= 0; i--) {
        if (s[i] === '0') nxt = i;
        nextZero[i] = nxt;
    }
    const prevZero = new Array(n).fill(-1);
    let prv = -1;
    for (let i = 0; i < n; i++) {
        if (s[i] === '0') prv = i;
        prevZero[i] = prv;
    }

    const ans = [];
    for (const [l, r] of queries) {
        const zerosInside = prefZero[r+1] - prefZero[l];
        const leftZ = nextZero[l];
        const rightZ = prevZero[r];
        let canTrade = false;
        if (leftZ < rightZ) {
            const onesBetween = prefOne[rightZ] - prefOne[leftZ+1];
            if (onesBetween > 0) canTrade = true;
        }
        ans.push(canTrade ? totalOnes + zerosInside : totalOnes);
    }
    return ans;
}

function longestPalindromeAfterConcat(s, t) {
  const n = s.length;
  const m = t.length;
  let best = 0;
  function isPal(str) {
    let i = 0, j = str.length - 1;
    while (i < j) {
      if (str[i] !== str[j]) return false;
      i++;
      j--;
    }
    return true;
  }
  for (let i = 0; i <= n; i++) {
    for (let j = i; j <= n; j++) {
      const subS = s.slice(i, j);
      for (let p = 0; p <= m; p++) {
        for (let q = p; q <= m; q++) {
          const subT = t.slice(p, q);
          const combined = subS + subT;
          if (combined.length > best && isPal(combined)) {
            best = combined.length;
          }
        }
      }
    }
  }
  return best;
}
