function minimumCostToReachPositions(cost) {
    const n = cost.length;
    const answer = new Array(n);
    let best = Infinity;
    for (let i = 0; i < n; i++) {
        if (cost[i] < best) best = cost[i];
        answer[i] = best;
    }
    return answer;
}

function minOperations(nums, x, k) {
    const n = nums.length;
    const cost = new Array(n - x + 1).fill(0);
    for (let i = 0; i <= n - x; i++) {
        const window = nums.slice(i, i+x).slice().sort((a,b) => a-b);
        const median = window[Math.floor(window.length/2)];
        cost[i] = window.reduce((s,v) => s + Math.abs(v - median), 0);
    }
    const INF = Infinity;
    const m = n - x + 1;
    const dp = Array.from({length: n+1}, () => new Array(k+1).fill(INF));
    dp[0][0] = 0;
    for (let pos = 0; pos < n; pos++) {
        for (let t = 0; t <= k; t++) {
            if (dp[pos][t] === INF) continue;
            if (dp[pos][t] < dp[pos+1][t]) dp[pos+1][t] = dp[pos][t];
            if (pos < m && t < k) {
                const npos = pos + x;
                const ncost = dp[pos][t] + cost[pos];
                if (ncost < dp[npos][t+1]) dp[npos][t+1] = ncost;
            }
        }
    }
    return dp[n][k];
}

function maxActiveSectionsAfterTrade(s) {
  const n = s.length;
  for (let i = 0; i + 2 < n; i++) {
    if (s[i] === '0' && s[i + 1] === '1' && s[i + 2] === '0') {
      return n;
    }
  }
  return n - 1;
}

function minimumCost(nums, cost, k) {
    const n = nums.length;
    const prefixNums = new Array(n + 1).fill(0);
    const prefixCost = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) {
        prefixNums[i + 1] = prefixNums[i] + nums[i];
        prefixCost[i + 1] = prefixCost[i] + cost[i];
    }
    // dp[i] = min cost to divide nums[i..n-1] into subarrays
    const dp = new Array(n + 1).fill(Infinity);
    dp[n] = 0;
    for (let i = n - 1; i >= 0; i--) {
        for (let j = i; j < n; j++) {
            // k*(subarray index) summed across all subarrays telescopes into k times the
            // remaining total cost-sum whenever a new subarray starts, avoiding explicit index tracking
            const val = prefixNums[j + 1] * (prefixCost[j + 1] - prefixCost[i]) +
                        k * (prefixCost[n] - prefixCost[i]) + dp[j + 1];
            dp[i] = Math.min(dp[i], val);
        }
    }
    return dp[0];
}

function maximumProductOfSubsequencesWithAnAlternatingSumEqualToK(nums, k, limit) {
    let dpEven = new Map([[0, 1]]);
    let dpOdd = new Map();

    for (const val of nums) {
        const nextEven = new Map(dpEven);
        const nextOdd = new Map(dpOdd);

        if (Math.abs(val) <= limit) {
            if (!nextOdd.has(val) || val > nextOdd.get(val)) nextOdd.set(val, val);
        }

        for (const [s, prod] of dpEven) {
            if (val === 0) {
                const newSum = s;
                if (!nextOdd.has(newSum) || 0 > nextOdd.get(newSum)) nextOdd.set(newSum, 0);
                continue;
            }
            if (Math.abs(prod) > Math.floor(limit / Math.abs(val))) continue;
            const newProd = prod * val;
            const newSum = s + val;
            if (!nextOdd.has(newSum) || newProd > nextOdd.get(newSum)) nextOdd.set(newSum, newProd);
        }

        for (const [s, prod] of dpOdd) {
            if (val === 0) {
                const newSum = s;
                if (!nextEven.has(newSum) || 0 > nextEven.get(newSum)) nextEven.set(newSum, 0);
                continue;
            }
            if (Math.abs(prod) > Math.floor(limit / Math.abs(val))) continue;
            const newProd = prod * val;
            const newSum = s - val;
            if (!nextEven.has(newSum) || newProd > nextEven.get(newSum)) nextEven.set(newSum, newProd);
        }

        dpEven = nextEven; dpOdd = nextOdd;
    }

    let ans = -1;
    if (dpEven.has(k)) ans = Math.max(ans, dpEven.get(k));
    if (dpOdd.has(k)) ans = Math.max(ans, dpOdd.get(k));
    return ans;
}

function minOperations(nums) {
    const tails = [];                     // tails[i] = min possible end of length i+1 subseq
    for (let i = 0; i < nums.length; i++) {
        const x = nums[i];
        // find first index where tails[idx] > x  (upper bound)
        let lo = 0, hi = tails.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (tails[mid] > x) hi = mid;
            else lo = mid + 1;
        }
        if (lo === tails.length) tails.push(x); // extend longest subsequence
        else tails[lo] = x;                     // improve existing subsequence
    }
    return nums.length - tails.length; // deletions needed
}

function longestPalindromeAfterSubstringConcatenationII(s, t) {
  function longestPalSub(str) {
    const n = str.length;
    let best = 0;
    for (let c = 0; c < n; ++c) {
      // odd length
      let l = c, r = c;
      while (l >= 0 && r < n && str[l] === str[r]) {
        best = Math.max(best, r - l + 1);
        l--;
        r++;
      }
      // even length
      l = c;
      r = c + 1;
      while (l >= 0 && r < n && str[l] === str[r]) {
        best = Math.max(best, r - l + 1);
        l--;
        r++;
      }
    }
    return best;
  }

  function longestCross(a, b) {
    const revB = b.split('').reverse().join('');
    const n = a.length, m = revB.length;
    let prev = new Array(m + 1).fill(0);
    let ans = 0;
    for (let i = 1; i <= n; ++i) {
      const cur = new Array(m + 1).fill(0);
      for (let j = 1; j <= m; ++j) {
        if (a[i - 1] === revB[j - 1]) {
          cur[j] = prev[j - 1] + 1;
          const L = cur[j];
          ans = Math.max(ans, 2 * L);
          if (i < n || j < m) {
            ans = Math.max(ans, 2 * L + 1);
          }
        }
      }
      prev = cur;
    }
    return ans;
  }

  const bestInS = longestPalSub(s);
  const bestInT = longestPalSub(t);
  const bestCross = longestCross(s, t);
  return Math.max(bestInS, bestInT, bestCross);
}

function minimumRemovalsToSort(nums) {
    const n = nums.length;
    if (n === 0) return 0;
    const dp = new Array(n).fill(1);
    let best = 1;
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < i; j++) {
            if (nums[j] <= nums[i] && dp[j] + 1 > dp[i]) {
                dp[i] = dp[j] + 1;
            }
        }
        if (dp[i] > best) best = dp[i];
    }
    return n - best;
}

function numberOfUniqueXorTriplets(nums) {
    const n = nums.length;
    let power = 1;
    while (power < n) {
        power <<= 1;
    }
    return power;
}

class Router {
    constructor(memoryLimit) {
        this.memoryLimit = memoryLimit;
        this.queue = [];
        this.seen = new Set();
        this.destMap = new Map();
    }
    _key(source, destination, timestamp) { return source + ',' + destination + ',' + timestamp; }
    addPacket(source, destination, timestamp) {
        const key = this._key(source, destination, timestamp);
        if (this.seen.has(key)) return false;
        if (this.queue.length >= this.memoryLimit) this._forwardInternal();
        this.seen.add(key);
        this.queue.push({ source, destination, timestamp });
        if (!this.destMap.has(destination)) this.destMap.set(destination, []);
        this.destMap.get(destination).push(timestamp);
        return true;
    }
    _forwardInternal() {
        const pkt = this.queue.shift();
        this.seen.delete(this._key(pkt.source, pkt.destination, pkt.timestamp));
        const arr = this.destMap.get(pkt.destination);
        arr.shift();
        return pkt;
    }
    forwardPacket() {
        if (this.queue.length === 0) return [];
        const pkt = this._forwardInternal();
        return [pkt.source, pkt.destination, pkt.timestamp];
    }
    getCount(destination, startTime, endTime) {
        const arr = this.destMap.get(destination);
        if (!arr) return 0;
        const lo = this._lowerBound(arr, startTime);
        const hi = this._upperBound(arr, endTime);
        return hi - lo;
    }
    _lowerBound(arr, target) {
        let lo = 0, hi = arr.length;
        while (lo < hi) { const mid = (lo+hi)>>1; if (arr[mid] < target) lo = mid+1; else hi = mid; }
        return lo;
    }
    _upperBound(arr, target) {
        let lo = 0, hi = arr.length;
        while (lo < hi) { const mid = (lo+hi)>>1; if (arr[mid] <= target) lo = mid+1; else hi = mid; }
        return lo;
    }
}

function countUniqueXorTriplets(nums) {
  const MAX_VAL = 2048; // 2^11, enough for values up to 1500 and their XORs
  const present = new Uint8Array(MAX_VAL);
  const uniq = [];
  for (let v of nums) {
    if (!present[v]) {
      present[v] = 1;
      uniq.push(v);
    }
  }
  const twoXor = new Uint8Array(MAX_VAL);
  const m = uniq.length;
  for (let i = 0; i < m; i++) {
    const a = uniq[i];
    for (let j = 0; j < m; j++) {
      const b = uniq[j];
      twoXor[a ^ b] = 1;
    }
  }
  const result = new Uint8Array(MAX_VAL);
  for (let v = 0; v < MAX_VAL; v++) {
    if (twoXor[v]) {
      for (let i = 0; i < m; i++) {
        result[v ^ uniq[i]] = 1;
      }
    }
  }
  let count = 0;
  for (let i = 0; i < MAX_VAL; i++) {
    if (result[i]) count++;
  }
  return count;
}

function smallestPalindromicPermutation(s) {
    const cnt = new Array(256).fill(0);               // count characters (ASCII)
    for (let i = 0; i < s.length; ++i) cnt[s.charCodeAt(i)]++; // O(n)

    let left = [];                                    // left half builder
    let middle = '';                                  // middle character (if any)

    // MAIN LOGIC: build left half in increasing character order and find middle
    for (let c = 0; c < 256; ++c) {
        if (cnt[c] % 2 === 1) middle = String.fromCharCode(c); // odd count char
        if (cnt[c] > 1) left.push(String.fromCharCode(c).repeat(cnt[c] >> 1));
    }

    const leftStr = left.join('');                    // left half string
    const rightStr = leftStr.split('').reverse().join(''); // mirror of left
    return leftStr + middle + rightStr;               // final palindrome
}

function minOperations(nums, k) {
    let total = 0;
    for (let i = 0; i < nums.length; i++) {
        total += nums[i];               // accumulate array sum
    }
    return total % k;                  // remainder = minimal operations
}

function findClosestPerson(x, y, z) {
    var dist1 = Math.abs(x - z);   // distance Person 1 -> Person 3
    var dist2 = Math.abs(y - z);   // distance Person 2 -> Person 3

    // compare distances and return the appropriate identifier
    if (dist1 < dist2) return 1;
    if (dist2 < dist1) return 2;
    return 0;                      // equal distance
}

class Fenwick {
    constructor(n) { this.n = n; this.bit = new Array(n+2).fill(0); }
    add(idx, val) { let i = idx; while (i <= this.n) { this.bit[i] += val; i += i & (-i); } }
    rangeAdd(l, r, val) { this.add(l, val); this.add(r+1, -val); }
    pointQuery(idx) { let res = 0, i = idx; while (i > 0) { res += this.bit[i]; i -= i & (-i); } return res; }
}

function shortestPathQueries(n, edges, queries) {
    const adj = Array.from({length: n+1}, () => []);
    for (const [u, v, w] of edges) {
        adj[u].push([v, w]);
        adj[v].push([u, w]);
    }
    const parent = new Array(n+1).fill(0);
    const tin = new Array(n+1).fill(0);
    const tout = new Array(n+1).fill(0);
    const dist = new Array(n+1).fill(0);
    const edgeWeight = new Array(n+1).fill(0);

    let timer = 0;
    const stack = [[1, 0]];
    parent[1] = 0;
    while (stack.length) {
        const [v, state] = stack.pop();
        if (state === 0) {
            timer += 1;
            tin[v] = timer;
            stack.push([v, 1]);
            for (const [to, w] of adj[v]) {
                if (to === parent[v]) continue;
                parent[to] = v;
                edgeWeight[to] = w;
                dist[to] = dist[v] + w;
                stack.push([to, 0]);
            }
        } else {
            tout[v] = timer;
        }
    }

    const fenwick = new Fenwick(n);
    const answer = [];
    for (const q of queries) {
        if (q[0] === 1) {
            const u = q[1], v = q[2], wnew = q[3];
            const child = parent[u] === v ? u : v;
            const delta = wnew - edgeWeight[child];
            edgeWeight[child] = wnew;
            fenwick.rangeAdd(tin[child], tout[child], delta);
        } else {
            const x = q[1];
            const cur = dist[x] + fenwick.pointQuery(tin[x]);
            answer.push(cur);
        }
    }
    return answer;
}

function smallestPalindromicRearrangementII(s, k) {
    const INF = 2000000000000000000n;
    const combCapped = (n, kk) => {
        if (kk < 0 || kk > n) return 0n;
        if (kk > n - kk) kk = n - kk;
        let res = 1n;
        for (let i = 1; i <= kk; i++) {
            res = res * BigInt(n - kk + i) / BigInt(i);
            if (res >= INF) return INF;
        }
        return res;
    };
    const mulCapped = (a, b) => {
        if (a >= INF || b >= INF) return INF;
        if (b !== 0n && a > INF / b) return INF;
        return a * b;
    };

    let kBig = BigInt(k);
    if (kBig <= 0n) return "";
    const freq = new Array(26).fill(0);
    for (const ch of s) freq[ch.charCodeAt(0) - 97]++;

    const middle = [];
    const halfCnt = new Array(26).fill(0);
    for (let i = 0; i < 26; i++) {
        if (freq[i] % 2 === 1) middle.push(String.fromCharCode(97 + i));
        halfCnt[i] = Math.floor(freq[i] / 2);
    }

    const halfLen = halfCnt.reduce((a, b) => a + b, 0);

    let totalPerms = 1n;
    let remaining = halfLen;
    for (const c of halfCnt) {
        if (c) {
            totalPerms = mulCapped(totalPerms, combCapped(remaining, c));
            if (totalPerms >= INF) { totalPerms = INF; break; }
            remaining -= c;
        }
    }

    if (kBig > totalPerms) return "";

    const left = [];
    for (let pos = 0; pos < halfLen; pos++) {
        const N = halfLen - pos;
        for (let i = 0; i < 26; i++) {
            const cntI = halfCnt[i];
            if (cntI === 0) continue;
            const cntPerm = totalPerms * BigInt(cntI) / BigInt(N);
            if (kBig > cntPerm) { kBig -= cntPerm; continue; }
            left.push(String.fromCharCode(97 + i));
            halfCnt[i]--;
            totalPerms = cntPerm;
            break;
        }
    }

    const right = [...left].reverse();
    return left.join('') + middle.join('') + right.join('');
}

function maxSize(nums) {
  const stack = [];
  for (let v of nums) {
    let cur = v;                              // start a new segment with max = v
    while (stack.length && stack[stack.length - 1] > cur) {
      cur = Math.max(cur, stack.pop());       // merge while decreasing would occur
    }
    stack.push(cur);                          // keep non‑decreasing stack of segment maxima
  }
  return stack.length;                        // number of segments = maximum possible size
}

function findXValueArrayII(nums, k, queries) {
    const n = nums.length;
    const size = 4 * n;
    const prodTree = new Array(size);
    const cntTree = new Array(size);
    const K = k;

    function build(node, l, r) {
        if (l === r) {
            const val = nums[l] % K;
            prodTree[node] = val;
            const cnt = new Array(K).fill(0);
            cnt[val] = 1;
            cntTree[node] = cnt;
            return;
        }
        const mid = (l + r) >> 1;
        build(node << 1, l, mid);
        build(node << 1 | 1, mid + 1, r);
        merge(node);
    }

    function merge(node) {
        const left = node << 1;
        const right = node << 1 | 1;
        const leftProd = prodTree[left];
        const rightProd = prodTree[right];
        const prod = (leftProd * rightProd) % K;
        const cnt = new Array(K).fill(0);
        const leftCnt = cntTree[left];
        const rightCnt = cntTree[right];
        for (let i = 0; i < K; i++) cnt[i] += leftCnt[i];
        for (let r = 0; r < K; r++) {
            const shifted = (leftProd * r) % K;
            cnt[shifted] += rightCnt[r];
        }
        prodTree[node] = prod;
        cntTree[node] = cnt;
    }

    function update(node, l, r, idx, valMod) {
        if (l === r) {
            prodTree[node] = valMod;
            const cnt = new Array(K).fill(0);
            cnt[valMod] = 1;
            cntTree[node] = cnt;
            return;
        }
        const mid = (l + r) >> 1;
        if (idx <= mid) update(node << 1, l, mid, idx, valMod);
        else update(node << 1 | 1, mid + 1, r, idx, valMod);
        merge(node);
    }

    const identity = {
        prod: 1 % K,
        cnt: new Array(K).fill(0)
    };

    function query(node, l, r, ql, qr) {
        if (ql > r || qr < l) return identity;
        if (ql <= l && r <= qr) return { prod: prodTree[node], cnt: cntTree[node] };
        const mid = (l + r) >> 1;
        const leftRes = query(node << 1, l, mid, ql, qr);
        const rightRes = query(node << 1 | 1, mid + 1, r, ql, qr);
        const prod = (leftRes.prod * rightRes.prod) % K;
        const cnt = new Array(K).fill(0);
        for (let i = 0; i < K; i++) cnt[i] += leftRes.cnt[i];
        for (let r0 = 0; r0 < K; r0++) {
            const shifted = (leftRes.prod * r0) % K;
            cnt[shifted] += rightRes.cnt[r0];
        }
        return { prod, cnt };
    }

    build(1, 0, n - 1);
    const res = [];
    for (const q of queries) {
        const [idx, val, start, xi] = q;
        const valMod = val % K;
        update(1, 0, n - 1, idx, valMod);
        const prefixProd = start === 0 ? (1 % K) : query(1, 0, n - 1, 0, start - 1).prod;
        const node = query(1, 0, n - 1, start, n - 1);
        let ans = 0;
        for (let r = 0; r < K; r++) {
            if ((prefixProd * r) % K === xi) ans += node.cnt[r];
        }
        res.push(ans);
    }
    return res;
}
// TIME: O((n+q)·log n) SPACE: O(n·k)

const MOD = 1000000007;

function decimalToBase(s, b) {
    if (s === "0") return [0];
    let cur = s;
    const rev = [];
    while (!(cur.length === 1 && cur[0] === '0')) {
        let nextChars = [];
        let carry = 0;
        for (const ch of cur) {
            const num = carry * 10 + (ch.charCodeAt(0) - 48);
            const q = Math.floor(num / b);
            carry = num % b;
            if (nextChars.length || q !== 0) nextChars.push(String.fromCharCode(48 + q));
        }
        rev.push(carry);
        cur = nextChars.length ? nextChars.join('') : "0";
    }
    rev.reverse();
    return rev;
}

function decrementString(s) {
    const res = s.split('');
    let i = res.length - 1;
    while (i >= 0 && res[i] === '0') { res[i] = '9'; i--; }
    if (i >= 0) res[i] = String.fromCharCode(res[i].charCodeAt(0) - 1);
    let pos = 0;
    while (pos < res.length && res[pos] === '0') pos++;
    if (pos === res.length) return "0";
    return res.slice(pos).join('');
}

function countUpTo(digits, b) {
    const n = digits.length;
    const memo = Array.from({length: n}, () => Array.from({length: b}, () => [-1, -1]));
    function dfs(idx, prev, tight, started) {
        if (idx === n) return 1;
        const st = started ? 1 : 0;
        if (!tight && memo[idx][prev][st] !== -1) return memo[idx][prev][st];
        const limit = tight ? digits[idx] : b - 1;
        let res = 0;
        for (let d = 0; d <= limit; d++) {
            const nstarted = started || d !== 0;
            const ntight = tight && (d === limit);
            if (!nstarted) {
                res += dfs(idx + 1, 0, ntight, false);
            } else {
                if (!started) {
                    res += dfs(idx + 1, d, ntight, true);
                } else {
                    if (d >= prev) res += dfs(idx + 1, d, ntight, true);
                }
            }
            if (res >= MOD) res -= MOD;
        }
        if (!tight) memo[idx][prev][st] = res % MOD;
        return res % MOD;
    }
    return dfs(0, 0, true, false) % MOD;
}

function countNumbersNonDecreasing(l, r, b) {
    const rDigits = decimalToBase(r, b);
    const cntR = countUpTo(rDigits, b);
    let cntLMinus = 0;
    if (l !== "0") {
        const lMinus = decrementString(l);
        const lDigits = decimalToBase(lMinus, b);
        cntLMinus = countUpTo(lDigits, b);
    }
    let ans = (cntR - cntLMinus) % MOD;
    if (ans < 0) ans += MOD;
    return ans;
}

function countCellsInOverlappingHorizontalAndVerticalSubstrings(grid, pattern) {
    const m = grid.length, n = m ? grid[0].length : 0;
    const M = m * n;
    const L = pattern.length;

    const rowStr = grid.map(row => row.join('')).join('');
    let colChars = [];
    for (let j = 0; j < n; j++) for (let i = 0; i < m; i++) colChars.push(grid[i][j]);
    const colStr = colChars.join('');

    const kmpOccurrences = (text, pat) => {
        const nT = text.length, nP = pat.length;
        if (nP === 0) return Array.from({length: nT + 1}, (_, i) => i);
        const lps = new Array(nP).fill(0);
        let length = 0, i = 1;
        while (i < nP) {
            if (pat[i] === pat[length]) { length++; lps[i] = length; i++; }
            else { if (length !== 0) length = lps[length - 1]; else { lps[i] = 0; i++; } }
        }
        const res = [];
        i = 0; let j = 0;
        while (i < nT) {
            if (text[i] === pat[j]) {
                i++; j++;
                if (j === nP) { res.push(i - j); j = lps[j - 1]; }
            } else {
                if (j !== 0) j = lps[j - 1]; else i++;
            }
        }
        return res;
    };

    const rowOcc = kmpOccurrences(rowStr, pattern);
    const colOcc = kmpOccurrences(colStr, pattern);

    const diffHor = new Array(M + 1).fill(0);
    for (const p of rowOcc) if (p + L <= M) { diffHor[p]++; diffHor[p + L]--; }
    const diffVer = new Array(M + 1).fill(0);
    for (const q of colOcc) if (q + L <= M) { diffVer[q]++; diffVer[q + L]--; }

    const horCov = new Array(M).fill(false);
    let cur = 0;
    for (let i = 0; i < M; i++) { cur += diffHor[i]; horCov[i] = cur > 0; }
    const verCov = new Array(M).fill(false);
    cur = 0;
    for (let i = 0; i < M; i++) { cur += diffVer[i]; verCov[i] = cur > 0; }

    let count = 0;
    for (let i = 0; i < m; i++) {
        const baseRow = i * n;
        for (let j = 0; j < n; j++) {
            const idxRow = baseRow + j;
            const idxCol = j * m + i;
            if (horCov[idxRow] && verCov[idxCol]) count++;
        }
    }
    return count;
}

function calculateScore(instructions, values) {
    const n = instructions.length;
    const visited = new Array(n).fill(false);
    let idx = 0;
    let score = 0;

    while (idx >= 0 && idx < n && !visited[idx]) {   // main simulation loop
        visited[idx] = true;
        if (instructions[idx] === "add") {
            score += values[idx];    // add value to score
            idx += 1;                // move to next instruction
        } else { // "jump"
            idx += values[idx];      // jump by the given offset
        }
    }
    return score;
}

function findXValues(nums, k) {
    const ans = new Array(k).fill(0);          // final counts for each remainder
    let cnt = new Array(k).fill(0);            // sub‑arrays ending at previous index

    for (let idx = 0; idx < nums.length; idx++) {
        const cur = nums[idx] % k;              // remainder of the single element
        const next = new Array(k).fill(0);      // sub‑arrays ending at current index

        // sub‑array consisting only of nums[idx]
        next[cur] += 1;                         // MAIN LOGIC: start new sub‑array

        // extend all sub‑arrays that ended at idx‑1
        for (let r = 0; r < k; r++) {           // MAIN LOGIC: extend previous sub‑arrays
            if (cnt[r] !== 0) {
                const newRem = (r * cur) % k;
                next[newRem] += cnt[r];
            }
        }

        // add counts of sub‑arrays ending at idx to the global answer
        for (let r = 0; r < k; r++) {           // MAIN LOGIC: accumulate to answer
            ans[r] += next[r];
        }

        cnt = next;                             // prepare for next iteration
    }

    return ans;
}

function pathExistence(n, nums, maxDiff, queries) {
    var comp = new Array(n);          // component id for each node
    var cur = 0;
    comp[0] = 0;
    for (var i = 1; i < n; i++) {     // assign ids while scanning the sorted array
        if (nums[i] - nums[i - 1] > maxDiff) cur++;
        comp[i] = cur;
    }
    var ans = new Array(queries.length);
    for (var i = 0; i < queries.length; i++) {   // answer each query in O(1)
        var a = queries[i][0];
        var b = queries[i][1];
        ans[i] = comp[a] === comp[b];
    }
    return ans;
}

function mostCommonResponse(responses) {
    const globalCount = new Map();               // answer → number of days it appears

    for (let i = 0; i < responses.length; i++) {
        const daySet = new Set();                // remove duplicates inside the day
        const day = responses[i];
        for (let j = 0; j < day.length; j++) {
            daySet.add(day[j]);                  // O(1) average
        }
        // count each distinct answer of this day once
        for (const ans of daySet) {
            globalCount.set(ans, (globalCount.get(ans) || 0) + 1);
        }
    }

    let bestAnswer = '';
    let bestCount = -1;
    for (const [ans, cnt] of globalCount) {
        // main logic: choose higher count, break ties by lexicographic order
        if (cnt > bestCount || (cnt === bestCount && ans < bestAnswer)) {
            bestCount = cnt;
            bestAnswer = ans;
        }
    }
    return bestAnswer;
}

function smallestDivisiblePermutation(nums, k) {
    const n = nums.length;
    const fullMask = (1 << n) - 1;
    const lengths = new Array(n).fill(0);
    const pow10mod = new Array(n).fill(0);
    for (let i = 0; i < n; i++) {
        let l = 0, tmp = nums[i];
        while (tmp > 0) { l++; tmp = Math.floor(tmp / 10); }
        lengths[i] = l;
        let p = 1 % k;
        for (let j = 0; j < l; j++) p = (p * 10) % k;
        pow10mod[i] = p;
    }
    const memo = Array.from({length: 1 << n}, () => new Array(k).fill(-1));
    function can(mask, rem) {
        if (mask === fullMask) return rem === 0 ? 1 : 0;
        if (memo[mask][rem] !== -1) return memo[mask][rem];
        let res = 0;
        for (let i = 0; i < n; i++) {
            if (mask & (1 << i)) continue;
            const newRem = ((rem * pow10mod[i]) % k + nums[i] % k) % k;
            if (can(mask | (1 << i), newRem)) { res = 1; break; }
        }
        memo[mask][rem] = res;
        return res;
    }
    if (!can(0, 0)) return [];
    const order = [...Array(n).keys()].sort((a, b2) => nums[a] - nums[b2]);
    const answer = [];
    let mask = 0, rem = 0;
    for (let step = 0; step < n; step++) {
        for (const idx of order) {
            if (mask & (1 << idx)) continue;
            const newRem = ((rem * pow10mod[idx]) % k + nums[idx] % k) % k;
            if (can(mask | (1 << idx), newRem)) {
                answer.push(nums[idx]);
                mask |= (1 << idx);
                rem = newRem;
                break;
            }
        }
    }
    return answer;
}

function baseUnitConversion(conversions) {
    const MOD2 = 1000000007;
    if (!conversions.length) return [];
    let maxIdx = 0;
    for (const [src, tgt] of conversions) {
        if (src > maxIdx) maxIdx = src;
        if (tgt > maxIdx) maxIdx = tgt;
    }
    const n = maxIdx + 1;
    const adj = Array.from({length: n}, () => []);
    for (const [src, tgt, factor] of conversions) adj[src].push([tgt, factor]);
    const result = new Array(n).fill(0);
    result[0] = 1;
    const stack = [0];
    while (stack.length) {
        const u = stack.pop();
        for (const [v, factor] of adj[u]) {
            result[v] = (result[u] * factor) % MOD2;
            stack.push(v);
        }
    }
    return result;
}

function maxProfit(n, edges, score) {
    // preMask[i] = bitmask of nodes that must appear before i
    const preMask = new Array(n).fill(0);
    for (const [u, v] of edges) preMask[v] |= 1 << u;

    const totalMask = 1 << n;
    const dp = new Array(totalMask).fill(-Infinity);
    dp[0] = 0;

    // popcnt[mask] = number of set bits in mask
    const popcnt = new Uint8Array(totalMask);
    for (let m = 1; m < totalMask; ++m) popcnt[m] = popcnt[m >> 1] + (m & 1);

    for (let mask = 0; mask < totalMask; ++mask) {
        const pos = popcnt[mask] + 1;               // position of the next node
        const cur = dp[mask];
        if (cur === -Infinity) continue;           // unreachable state
        // try to place every node whose predecessors are already in mask
        for (let v = 0; v < n; ++v) {
            const bit = 1 << v;
            if (mask & bit) continue;               // already placed
            if ((preMask[v] & mask) !== preMask[v]) continue; // deps missing
            const newMask = mask | bit;
            const cand = cur + score[v] * pos;
            if (cand > dp[newMask]) dp[newMask] = cand;
        }
    }
    return dp[totalMask - 1];
}

function specialGrid(n) {
  const size = 1 << n;
  const grid = Array.from({length: size}, () => new Array(size).fill(0));
  function fill(row, col, sz, start) {
    if (sz === 1) { grid[row][col] = start; return; }
    const half = sz / 2;
    const block = half * half;
    fill(row, col + half, half, start);
    fill(row + half, col + half, half, start + block);
    fill(row + half, col, half, start + 2*block);
    fill(row, col, half, start + 3*block);
  }
  fill(0, 0, size, 0);
  return grid;
}

function countCoveredBuildings(n, buildings) {
    // maps: row -> min/max x, column -> min/max y
    const rowMinX = {};
    const rowMaxX = {};
    const colMinY = {};
    const colMaxY = {};

    // build extreme values
    for (let i = 0; i < buildings.length; i++) {
        const x = buildings[i][0];
        const y = buildings[i][1];

        if (rowMinX[y] === undefined || x < rowMinX[y]) rowMinX[y] = x;
        if (rowMaxX[y] === undefined || x > rowMaxX[y]) rowMaxX[y] = x;

        if (colMinY[x] === undefined || y < colMinY[x]) colMinY[x] = y;
        if (colMaxY[x] === undefined || y > colMaxY[x]) colMaxY[x] = y;
    }

    // count covered buildings
    let covered = 0;
    for (let i = 0; i < buildings.length; i++) {
        const x = buildings[i][0];
        const y = buildings[i][1];

        if (rowMinX[y] < x && x < rowMaxX[y] &&   // left & right exist
            colMinY[x] < y && y < colMaxY[x]) {   // below & above exist
            covered++;
        }
    }
    return covered;
}

var minTravelTime = function(l, n, k, position, time) {
    const INF = Infinity;
    const prefix = new Array(n).fill(0);
    for (let i = 0; i < n - 1; i++) prefix[i + 1] = prefix[i] + time[i];
    const dp = Array.from({length: n + 1}, () => Array.from({length: n}, () => new Array(k + 1).fill(INF)));
    dp[0][0][0] = 0;
    for (let c = 0; c < n - 1; c++) {
        for (let pidx = 0; pidx <= n; pidx++) {
            for (let m = 0; m <= k; m++) {
                const cost0 = dp[pidx][c][m];
                if (cost0 === INF) continue;
                const p = pidx - 1;
                const rate = prefix[c + 1] - prefix[p + 1];
                for (let i2 = c + 1; i2 < n; i2++) {
                    const mergesAdd = i2 - c - 1;
                    const m2 = m + mergesAdd;
                    if (m2 > k) continue;
                    const newcost = cost0 + rate * (position[i2] - position[c]);
                    if (newcost < dp[c + 1][i2][m2]) dp[c + 1][i2][m2] = newcost;
                }
            }
        }
    }
    let ans = INF;
    for (let pidx = 0; pidx <= n; pidx++) ans = Math.min(ans, dp[pidx][n - 1][k]);
    return ans;
};

function shortestPathLengths(n, nums, maxDiff, queries) {
    const nodes = new Array(n);
    for (let i = 0; i < n; i++) nodes[i] = [nums[i], i];
    nodes.sort((a, b) => a[0] - b[0]);
    const sortedVals = new Array(n);
    const sortedIdx = new Array(n);
    const pos = new Array(n);
    for (let i = 0; i < n; i++) {
        sortedVals[i] = nodes[i][0];
        sortedIdx[i] = nodes[i][1];
        pos[sortedIdx[i]] = i;
    }
    const far = new Array(n);
    let right = 0;
    for (let left = 0; left < n; left++) {
        while (right < n && sortedVals[right] - sortedVals[left] <= maxDiff) right++;
        far[left] = right - 1;
    }
    const LOG = Math.ceil(Math.log2(n)) + 1;
    const up = new Array(LOG);
    up[0] = far.slice();
    for (let k = 1; k < LOG; k++) {
        const prev = up[k - 1];
        const cur = new Array(n);
        for (let i = 0; i < n; i++) {
            cur[i] = prev[prev[i]];
        }
        up[k] = cur;
    }
    const ans = new Array(queries.length);
    for (let qi = 0; qi < queries.length; qi++) {
        let u = queries[qi][0];
        let v = queries[qi][1];
        if (u === v) {
            ans[qi] = 0;
            continue;
        }
        let a = pos[u];
        let b = pos[v];
        if (a > b) {
            const tmp = a;
            a = b;
            b = tmp;
        }
        if (up[LOG - 1][a] < b) {
            ans[qi] = -1;
            continue;
        }
        let cur = a;
        let steps = 0;
        for (let k = LOG - 1; k >= 0; k--) {
            if (up[k][cur] < b) {
                cur = up[k][cur];
                steps += 1 << k;
            }
        }
        steps += 1;
        ans[qi] = steps;
    }
    return ans;
}
// TIME: O((n+q) log n) SPACE: O(n log n)

function maxProductTwoDigits(n) {
    // count occurrences of each digit (0‑9)
    const cnt = Array(10).fill(0);
    const s = n.toString();
    for (let i = 0; i < s.length; i++) {
        cnt[s.charCodeAt(i) - 48]++;   // digit = s[i] - '0'
    }

    // find the two largest distinct digits
    let first = -1, second = -1;
    let sameProduct = 0;               // product of a digit with itself (if possible)

    for (let d = 9; d >= 0; d--) {
        if (cnt[d] === 0) continue;
        if (first === -1) {
            first = d;
            if (cnt[d] >= 2) sameProduct = d * d;   // same digit can be used twice
        } else if (second === -1) {
            second = d;
            break;
        }
    }

    const diffProduct = (first !== -1 && second !== -1) ? first * second : 0;
    return Math.max(diffProduct, sameProduct);
}

function minOperations(nums) {
    const stack = [];
    let ops = 0;
    for (let v of nums) {
        while (stack.length && stack[stack.length - 1] > v) {
            stack.pop();
        }
        if (v === 0) continue;
        if (!stack.length || stack[stack.length - 1] < v) {
            stack.push(v);
            ops++;
        }
    }
    return ops;
}

function minDeletions(s, k) {
    // count frequencies of each lowercase letter
    const freq = new Array(26).fill(0);
    for (let i = 0; i < s.length; i++) {
        freq[s.charCodeAt(i) - 97]++;   // 'a' → 97
    }

    // collect non‑zero frequencies
    const nonZero = [];
    for (let i = 0; i < 26; i++) {
        if (freq[i] > 0) nonZero.push(freq[i]);
    }

    // already within limit?
    if (nonZero.length <= k) return 0;

    // delete characters from least frequent distinct letters
    nonZero.sort((a, b) => a - b);      // ascending
    let deletions = 0;
    let distinct = nonZero.length;
    for (let i = 0; distinct > k; i++) {
        deletions += nonZero[i];
        distinct--;
    }
    return deletions;
}

var maxSum = function(edges, nums, k) {
    const n = nums.length;
    const adj = Array.from({length: n}, () => []);
    for (const [u, v] of edges) { adj[u].push(v); adj[v].push(u); }

    const parent = new Array(n).fill(-1);
    const order = [];
    const visited = new Array(n).fill(false);
    const stack = [0];
    visited[0] = true;
    while (stack.length) {
        const u = stack.pop();
        order.push(u);
        for (const v of adj[u]) {
            if (!visited[v]) { visited[v] = true; parent[v] = u; stack.push(v); }
        }
    }

    const dp = new Array(n);
    for (let idx = order.length - 1; idx >= 0; idx--) {
        const v = order[idx];
        const children = adj[v].filter(c => c !== parent[v]);
        const table = [];
        for (let dist = 0; dist <= k; dist++) {
            const row = [0, 0];
            for (let sidx = 0; sidx < 2; sidx++) {
                const sign = sidx === 0 ? 1 : -1;
                let noInvert = sign * nums[v];
                const cdist = Math.min(dist+1, k);
                for (const c of children) noInvert += dp[c][cdist][sidx];
                let best = noInvert;
                if (dist >= k) {
                    let invert = -sign * nums[v];
                    for (const c of children) invert += dp[c][1][1-sidx];
                    best = Math.max(best, invert);
                }
                row[sidx] = best;
            }
            table.push(row);
        }
        dp[v] = table;
    }
    return dp[0][k][0];
};

function findSumOfArrayProduct(m, k, nums) {
  const MOD = 1000000007n;
  const n = nums.length;
  const memo = new Map();

  function comb(a, b) {
    // small a (<=30), compute directly with BigInt binomial mod MOD via factorial precompute
    return C[a][b];
  }

  // precompute pascal's triangle mod MOD up to m
  const C = Array.from({length: m + 1}, () => Array(m + 1).fill(0n));
  for (let i = 0; i <= m; i++) {
    C[i][0] = 1n;
    for (let j = 1; j <= i; j++) {
      C[i][j] = (C[i-1][j-1] + (j <= i-1 ? C[i-1][j] : 0n)) % MOD;
    }
  }

  function dfs(i, j, kk, carry) {
    if (kk < 0 || (i === n && j > 0)) return 0n;
    const key = i + ',' + j + ',' + kk + ',' + carry;
    if (memo.has(key)) return memo.get(key);
    if (i === n) {
      let c = carry, kRem = kk;
      while (c) {
        kRem -= c & 1;
        c >>= 1;
      }
      const res = kRem === 0 ? 1n : 0n;
      memo.set(key, res);
      return res;
    }
    let res = 0n;
    for (let t = 0; t <= j; t++) {
      const nt = t + carry;
      const p = modpow(BigInt(nums[i]), BigInt(t), MOD);
      const nk = kk - (nt & 1);
      res = (res + comb(j, t) * p % MOD * dfs(i + 1, j - t, nk, nt >> 1)) % MOD;
    }
    memo.set(key, res);
    return res;
  }

  function modpow(base, exp, mod) {
    base %= mod;
    let result = 1n;
    while (exp > 0n) {
      if (exp & 1n) result = (result * base) % mod;
      base = (base * base) % mod;
      exp >>= 1n;
    }
    return result;
  }

  const ans = dfs(0, m, k, 0);
  return Number(ans % MOD);
}

function mostFrequentVowelConsonant(s) {
    // Count frequencies and track max for vowels and consonants
    const vowelSet = new Set(['a', 'e', 'i', 'o', 'u']);
    const vowelCnt = new Array(26).fill(0);
    const consCnt  = new Array(26).fill(0);
    let maxVowel = 0, maxConsonant = 0;

    for (let i = 0; i < s.length; i++) {
        const ch = s.charCodeAt(i) - 97;          // index 0‑25
        if (vowelSet.has(s[i])) {
            const v = ++vowelCnt[ch];
            if (v > maxVowel) maxVowel = v;
        } else {
            const c = ++consCnt[ch];
            if (c > maxConsonant) maxConsonant = c;
        }
    }
    return maxVowel + maxConsonant;
}

function smallestIndex(nums) {
  for (let i = 0; i < nums.length; i++) {
    // compute digit sum of nums[i] and compare with index i
    let sum = 0;
    let x = Math.abs(nums[i]);          // handle possible negatives
    while (x > 0) {
      sum += x % 10;
      x = (x / 10) | 0;                 // integer division
    }
    if (sum === i) return i;
  }
  return -1;
}

function maximumWeightedKEdgePath(n, edges, k, t) {
    const NEG_INF = -1e18;
    let prev = new Array(n).fill(NEG_INF);
    prev[0] = 0;
    if (k === 0) return 0 < t ? 0 : -1;

    for (let step = 1; step <= k; step++) {
        const cur = new Array(n).fill(NEG_INF);
        for (const [u, v, w] of edges) {
            if (prev[u] !== NEG_INF) {
                const cand = prev[u] + w;
                if (cand < t && cand > cur[v]) cur[v] = cand;
            }
        }
        prev = cur;
    }
    const ans = Math.max(...prev);
    return ans === NEG_INF ? -1 : ans;
}

function equalSumGridPartition(grid) {
    const m = grid.length;
    const n = grid[0].length;
    let total = 0;

    // compute total sum of all cells
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            total += grid[i][j];
        }
    }

    // ----- horizontal cut check -----
    let rowPrefix = 0;
    for (let i = 0; i < m - 1; i++) {          // stop before last row to keep both parts non‑empty
        for (let j = 0; j < n; j++) rowPrefix += grid[i][j];
        if (rowPrefix * 2 === total) return true; // found equal‑sum horizontal cut
    }

    // ----- vertical cut check -----
    let colPrefix = 0;
    for (let j = 0; j < n - 1; j++) {          // stop before last column
        for (let i = 0; i < m; i++) colPrefix += grid[i][j];
        if (colPrefix * 2 === total) return true; // found equal‑sum vertical cut
    }

    return false;
}

function minimumWeightedSubgraphWithTheRequiredPathsII(edges, queries) {
    const n = edges.length + 1;
    const adj = Array.from({length: n}, () => []);
    for (const [u, v, w] of edges) { adj[u].push([v, w]); adj[v].push([u, w]); }

    const LOG = Math.max(1, Math.ceil(Math.log2(n + 1)));
    const parent = Array.from({length: LOG}, () => new Array(n).fill(-1));
    const depth = new Array(n).fill(0);
    const dist = new Array(n).fill(0);

    const stack = [[0, -1]];
    const visited = new Array(n).fill(false);
    while (stack.length) {
        const [u, p] = stack.pop();
        if (visited[u]) continue;
        visited[u] = true;
        for (const [v, w] of adj[u]) {
            if (v === p) continue;
            parent[0][v] = u;
            depth[v] = depth[u] + 1;
            dist[v] = dist[u] + w;
            stack.push([v, u]);
        }
    }

    for (let kk = 1; kk < LOG; kk++) {
        for (let v = 0; v < n; v++) {
            const anc = parent[kk - 1][v];
            parent[kk][v] = anc === -1 ? -1 : parent[kk - 1][anc];
        }
    }

    const lca = (u, v) => {
        if (depth[u] < depth[v]) [u, v] = [v, u];
        let diff = depth[u] - depth[v];
        let bit = 0;
        while (diff) { if (diff & 1) u = parent[bit][u]; diff >>= 1; bit++; }
        if (u === v) return u;
        for (let kk = LOG - 1; kk >= 0; kk--) {
            if (parent[kk][u] !== parent[kk][v]) { u = parent[kk][u]; v = parent[kk][v]; }
        }
        return parent[0][u];
    };

    const distance = (u, v) => {
        const w = lca(u, v);
        return dist[u] + dist[v] - 2 * dist[w];
    };

    const res = [];
    for (const [a, b, c] of queries) {
        const x = lca(a, b), y = lca(a, c), z = lca(b, c);
        let m = x;
        if (depth[y] > depth[m]) m = y;
        if (depth[z] > depth[m]) m = z;
        const total = distance(a, m) + distance(b, m) + distance(c, m);
        res.push(total);
    }
    return res;
}

function maxScore(n, edges) {
    const adj = Array.from({length: n}, () => []);
    for (const [a, b] of edges) {
        adj[a].push(b);
        adj[b].push(a);
    }
    const m = edges.length;
    const isCycle = (m === n);

    const order = [];
    const visited = new Array(n).fill(false);
    let start = 0;
    if (!isCycle) {
        for (let i = 0; i < n; i++) {
            if (adj[i].length <= 1) { start = i; break; }
        }
    }
    let prev = -1, cur = start;
    while (cur !== null && cur !== undefined) {
        order.push(cur);
        visited[cur] = true;
        let nxt = null;
        for (const nb of adj[cur]) {
            if (nb !== prev && !visited[nb]) { nxt = nb; break; }
        }
        prev = cur;
        cur = nxt;
        if (isCycle && cur === start) break;
    }

    const k = order.length;
    const vals = [];
    for (let i = k; i >= 1; i--) vals.push(i);
    const arrangement = [vals[0]];
    for (let i = 1; i < k; i++) {
        if (i % 2 === 1) arrangement.push(vals[i]);
        else arrangement.unshift(vals[i]);
    }

    const value = new Array(n).fill(0);
    order.forEach((node, idx) => value[node] = arrangement[idx]);

    let total = 0;
    for (let i = 0; i < k - 1; i++) total += value[order[i]] * value[order[i+1]];
    if (isCycle) total += value[order[k-1]] * value[order[0]];
    return total;
}

