        }
    }
    const usedPortal = new Uint8Array(26);
    const total = m * n;
    const q = new Int32Array(total * 2);
    let head = 0, tail = 0;
    const startPos = 0;
    visited[0][0] = 1;
    q[tail++] = startPos;
    q[tail++] = 0;
    while (head < tail) {
        const pos = q[head++];
        const dist = q[head++];
        const i = (pos / n) | 0;
        const j = pos % n;
        if (i === m - 1 && j === n - 1) return dist;
        const code = matrix[i].charCodeAt(j);
        if (code >= 65 && code <= 90) {
            const idx = code - 65;
            if (!usedPortal[idx]) {
                usedPortal[idx] = 1;
                const list = portals[idx];
                for (let k = 0; k < list.length; k++) {
                    const p = list[k];
                    const pi = (p / n) | 0;
                    const pj = p % n;
                    if (!visited[pi][pj]) {
                        visited[pi][pj] = 1;
                        q[tail++] = p;
                        q[tail++] = dist;
                    }
                }
            }
        }
        const nd = dist + 1;
        if (i > 0 && !visited[i - 1][j] && matrix[i - 1].charAt(j) !== '#') {
            visited[i - 1][j] = 1;
            q[tail++] = (i - 1) * n + j;
            q[tail++] = nd;
        }
        if (i + 1 < m && !visited[i + 1][j] && matrix[i + 1].charAt(j) !== '#') {
            visited[i + 1][j] = 1;
            q[tail++] = (i + 1) * n + j;
            q[tail++] = nd;
        }
        if (j > 0 && !visited[i][j - 1] && matrix[i].charAt(j - 1) !== '#') {
            visited[i][j - 1] = 1;
            q[tail++] = i * n + (j - 1);
            q[tail++] = nd;
        }
        if (j + 1 < n && !visited[i][j + 1] && matrix[i].charAt(j + 1) !== '#') {
            visited[i][j + 1] = 1;
            q[tail++] = i * n + (j + 1);
            q[tail++] = nd;
        }
    }
    return -1;
}

function numberOfWays(edges) {
    const MOD = 1_000_000_007;

    // build adjacency list
    const n = edges.length + 1;
    const adj = Array.from({ length: n + 1 }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }

    // DFS to find maximum depth from node 1
    const stack = [[1, 0, 0]];               // [node, parent, depth]
    let maxDepth = 0;
    while (stack.length) {
        const [node, parent, depth] = stack.pop();
        if (depth > maxDepth) maxDepth = depth;   // main logic
        for (const nb of adj[node]) {
            if (nb !== parent) stack.push([nb, node, depth + 1]);
        }
    }

    if (maxDepth === 0) return 0; // only the root exists

    // fast exponentiation: 2^(maxDepth-1) mod MOD
    let exp = maxDepth - 1;
    let base = 2;
    let res = 1;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

function numberOfWaysEdgeWeights(edges, queries) {
    const MOD2 = 1000000007n;
    const n = edges.length + 1;
    const adj = Array.from({length: n+1}, () => []);
    for (const [u, v] of edges) { adj[u].push(v); adj[v].push(u); }
    const LOG = Math.max(1, Math.ceil(Math.log2(n+1)) + 1);
    const parent = Array.from({length: LOG}, () => new Array(n+1).fill(0));
    const depth = new Array(n+1).fill(0);
    const visited = new Array(n+1).fill(false);
    const stack = [1];
    visited[1] = true;
    depth[1] = 0;
    parent[0][1] = 0;
    while (stack.length) {
        const u = stack.pop();
        for (const v of adj[u]) {
            if (!visited[v]) {
                visited[v] = true;
                depth[v] = depth[u] + 1;
                parent[0][v] = u;
                stack.push(v);
            }
        }
    }
    for (let k = 1; k < LOG; k++) {
        for (let v = 1; v <= n; v++) {
            const anc = parent[k-1][v];
            parent[k][v] = anc ? parent[k-1][anc] : 0;
        }
    }
    function lca(u, v) {
        if (depth[u] < depth[v]) [u, v] = [v, u];
        let diff = depth[u] - depth[v];
        let bit = 0;
        while (diff) {
            if (diff & 1) u = parent[bit][u];
            diff >>= 1;
            bit++;
        }
        if (u === v) return u;
        for (let k = LOG - 1; k >= 0; k--) {
            if (parent[k][u] !== parent[k][v]) { u = parent[k][u]; v = parent[k][v]; }
        }
        return parent[0][u];
    }
    function modpow(base, exp, mod) {
        base %= mod; let result = 1n;
        while (exp > 0n) {
            if (exp & 1n) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1n;
        }
        return result;
    }
    const res = [];
    for (const [u, v] of queries) {
        const w = lca(u, v);
        const length = depth[u] + depth[v] - 2 * depth[w];
        if (length === 0) res.push(0);
        else res.push(Number(modpow(2n, BigInt(length - 1), MOD2)));
    }
    return res;
}

