function partitionArrayIntoTwoEqualProductSubsets(nums, target) {
    const n = nums.length;
    if (n < 2) return false;

    let total = 1;
    for (const v of nums) total *= v;
    if (total !== target * target) return false;

    if (target === 0) {
        const zeroCnt = nums.filter(x => x === 0).length;
        return zeroCnt >= 2;
    }

    if (nums.includes(0)) return false;

    for (const v of nums) if (v > target) return false;

    const sorted = [...nums].sort((a, b) => b - a);
    const memo = new Map();

    const dfs = (i, prod, cnt) => {
        if (prod === target) return cnt > 0 && cnt < n;
        if (i === n || prod > target) return false;
        const key = i + ',' + prod + ',' + cnt;
        if (memo.has(key)) return memo.get(key);
        let result = false;
        if (dfs(i + 1, prod * sorted[i], cnt + 1)) result = true;
        else if (dfs(i + 1, prod, cnt)) result = true;
        memo.set(key, result);
        return result;
    };

    return dfs(0, 1, 0);
}

function minimumMovesToCleanTheClassroom(classroom, energy) {
    const m = classroom.length, n = classroom[0].length;
    const litterPositions = [];
    let start = null;
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            const ch = classroom[i][j];
            if (ch === 'S') start = [i, j];
            else if (ch === 'L') litterPositions.push([i, j]);
        }
    }
    if (!start) return -1;
    const L = litterPositions.length;
    const idxMap = new Map(litterPositions.map(([r, c], i) => [r + ',' + c, i]));
    const fullMask = (1 << L) - 1;
    if (fullMask === 0) return 0;

    const [sr, sc] = start;
    const q = [[sr, sc, energy, 0, 0]];
    let head = 0;
    const best = new Map();
    best.set(sr + ',' + sc + ',' + 0, energy);
    const dirs = [[1,0],[-1,0],[0,1],[0,-1]];

    while (head < q.length) {
        const [r, c, e, mask, steps] = q[head++];
        if (mask === fullMask) return steps;
        if (e === 0 && classroom[r][c] !== 'R') continue;
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (!(nr >= 0 && nr < m && nc >= 0 && nc < n)) continue;
            const cell = classroom[nr][nc];
            if (cell === 'X') continue;
            let ne = e - 1;
            if (ne < 0) continue;
            let nmask = mask;
            if (cell === 'L') nmask = mask | (1 << idxMap.get(nr + ',' + nc));
            if (cell === 'R') ne = energy;
            const key = nr + ',' + nc + ',' + nmask;
            if ((best.has(key) ? best.get(key) : -1) >= ne) continue;
            best.set(key, ne);
            q.push([nr, nc, ne, nmask, steps + 1]);
        }
    }
    return -1;
}

function maximumGoodSubtreeScore(vals, par) {
    const MOD = 1000000007;
    const n = vals.length;
    const children = Array.from({ length: n }, () => []);
    for (let i = 1; i < n; i++) {
        children[par[i]].push(i);
    }
    const masks = new Array(n);
    for (let i = 0; i < n; i++) {
        let v = vals[i];
        if (v === 0) {
            masks[i] = 1 << 0;
            continue;
        }
        let mask = 0;
        let ok = true;
        while (v > 0) {
            const d = v % 10;
            const bit = 1 << d;
            if (mask & bit) {
                ok = false;
                break;
            }
            mask |= bit;
            v = Math.floor(v / 10);
        }
        masks[i] = ok ? mask : -1;
    }
    const maxScore = new Array(n).fill(0);
    function dfs(u) {
        let dp = new Array(1024).fill(-Infinity);
        dp[0] = 0;
        for (const v of children[u]) {
            const childDp = dfs(v);
            const newDp = new Array(1024).fill(-Infinity);
            for (let m1 = 0; m1 < 1024; m1++) {
                if (dp[m1] === -Infinity) continue;
                for (let m2 = 0; m2 < 1024; m2++) {
                    if (childDp[m2] === -Infinity) continue;
                    if ((m1 & m2) !== 0) continue;
                    const nm = m1 | m2;
                    const sum = dp[m1] + childDp[m2];
                    if (sum > newDp[nm]) newDp[nm] = sum;
                }
            }
            dp = newDp;
        }
        const nodeMask = masks[u];
        if (nodeMask !== -1) {
            for (let m = 0; m < 1024; m++) {
                if (dp[m] === -Infinity) continue;
                if ((m & nodeMask) === 0) {
                    const nm = m | nodeMask;
                    const sum = dp[m] + vals[u];
                    if (sum > dp[nm]) dp[nm] = sum;
                }
            }
        }
        let best = 0;
        for (let m = 0; m < 1024; m++) {
            if (dp[m] > best) best = dp[m];
        }
        maxScore[u] = best;
        return dp;
    }
    dfs(0);
    let total = 0;
    for (let i = 0; i < n; i++) {
        total = (total + maxScore[i]) % MOD;
    }
    return total;
}

