    }
    for (let k = 1; k < LOG; k++) {
        const prev = up[k - 1];
        const cur = up[k];
        for (let i = 0; i < n; i++) {
            const mid = prev[i];
            cur[i] = mid === -1 ? -1 : prev[mid];
        }
    }

    function liftNode(node, diff) {
        for (let k = 0; diff > 0; k++) {
            if (diff & 1) node = up[k][node];
            diff >>= 1;
        }
        return node;
    }

    function lca(u, v) {
        if (depth[u] < depth[v]) [u, v] = [v, u];
        u = liftNode(u, depth[u] - depth[v]);
        if (u === v) return u;
        for (let k = LOG - 1; k >= 0; k--) {
            const pu = up[k][u];
            const pv = up[k][v];
            if (pu !== pv) {
                u = pu;
                v = pv;
            }
        }
        return parent[u];
    }

    const ans = new Array(queries.length);
    for (let idx = 0; idx < queries.length; idx++) {
        const [u0, v0] = queries[idx];
        const l = lca(u0, v0);
        const total = dist[u0] + dist[v0] - 2 * dist[l];
        const target = Math.floor((total + 1) / 2);
        const upDist = dist[u0] - dist[l];
        if (target <= upDist) {
            let cur = u0;
            for (let k = LOG - 1; k >= 0; k--) {
                const anc = up[k][cur];
                if (anc !== -1 && (dist[u0] - dist[anc]) < target) {
                    cur = anc;
                }
            }
            ans[idx] = up[0][cur];
        } else {
            const remaining = target - upDist;
            const downDist = dist[v0] - dist[l];
            const limit = downDist - remaining;
            let cur = v0;
            for (let k = LOG - 1; k >= 0; k--) {
                const anc = up[k][cur];
                if (anc !== -1 && (dist[v0] - dist[anc]) <= limit) {
                    cur = anc;
                }
            }
            ans[idx] = cur;
        }
    }
    return ans;
}

