function specialTriplets(nums) {
    const MOD = 1000000007n;
    const n = nums.length;
    const leftFreq = new Map();
    const rightFreq = new Map();
    for (const v of nums) rightFreq.set(v, (rightFreq.get(v) || 0) + 1);
    let ans = 0n;
    for (let j = 0; j < n; j++) {
        rightFreq.set(nums[j], rightFreq.get(nums[j]) - 1);
        const target = nums[j] * 2;
        const l = BigInt(leftFreq.get(target) || 0);
        const r = BigInt(rightFreq.get(target) || 0);
        ans = (ans + l * r) % MOD;
        leftFreq.set(nums[j], (leftFreq.get(nums[j]) || 0) + 1);
    }
    return Number(ans);
}

function minSwaps(nums) {
    function cost(startParity) {
        const arr = nums.slice();
        const n = arr.length;
        let swaps = 0;
        for (let i = 0; i < n; i++) {
            const wantEven = (i % 2 === 0) === (startParity === 0);
            const curEven = arr[i] % 2 === 0;
            if (curEven === wantEven) continue;
            let j = i + 1;
            while (j < n && (arr[j] % 2 === 0) !== wantEven) j++;
            // shift arr[j] to position i
            const val = arr[j];
            for (let x = j; x > i; x--) arr[x] = arr[x-1];
            arr[i] = val;
            swaps += j - i;
        }
        return swaps;
    }
    const n = nums.length;
    const evenCount = nums.filter(x => x%2===0).length;
    const oddCount = n - evenCount;
    let best = Infinity;
    if (Math.abs(evenCount - oddCount) <= 1) {
        if (evenCount >= oddCount) best = Math.min(best, cost(0));
        if (oddCount >= evenCount) best = Math.min(best, cost(1));
    }
    return best;
}

function findMaximumAreaOfATriangle(points) {
    if (!points.length) return -1;
    const xMinY = new Map(), xMaxY = new Map();
    const yMinX = new Map(), yMaxX = new Map();

    let minX = points[0][0], maxX = points[0][0];
    let minY = points[0][1], maxY = points[0][1];

    for (const [x, y] of points) {
        if (x < minX) minX = x; else if (x > maxX) maxX = x;
        if (y < minY) minY = y; else if (y > maxY) maxY = y;

        if (xMinY.has(x)) {
            if (y < xMinY.get(x)) xMinY.set(x, y);
            if (y > xMaxY.get(x)) xMaxY.set(x, y);
        } else { xMinY.set(x, y); xMaxY.set(x, y); }

        if (yMinX.has(y)) {
            if (x < yMinX.get(y)) yMinX.set(y, x);
            if (x > yMaxX.get(y)) yMaxX.set(y, x);
        } else { yMinX.set(y, x); yMaxX.set(y, x); }
    }

    let best = 0;
    for (const [x, miny] of xMinY) {
        const maxy = xMaxY.get(x);
        if (maxy > miny) {
            const base = maxy - miny;
            const height = Math.max(Math.abs(x - minX), Math.abs(x - maxX));
            const area2 = base * height;
            if (area2 > best) best = area2;
        }
    }
    for (const [y, minx] of yMinX) {
        const maxx = yMaxX.get(y);
        if (maxx > minx) {
            const base = maxx - minx;
            const height = Math.max(Math.abs(y - minY), Math.abs(y - maxY));
            const area2 = base * height;
            if (area2 > best) best = area2;
        }
    }
    return best > 0 ? best : -1;
}

function maxProduct(nums, m) {
    const n = nums.length;

    // m = 1 : product is element squared
    if (m === 1) {
        let best = -Infinity;
        for (let v of nums) {
            const sq = v * v;               // square of the element
            if (sq > best) best = sq;
        }
        return best;
    }

    let best = -Infinity;
    let maxLeft = -Infinity;   // maximum value among eligible left indices
    let minLeft = Infinity;    // minimum value among eligible left indices
    const gap = m - 1;         // required distance between first and last

    // j is the index of the last element of the subsequence
    for (let j = gap; j < n; j++) {
        const iIdx = j - gap;               // newest index that becomes eligible
        const val = nums[iIdx];
        if (val > maxLeft) maxLeft = val;   // update maximum of eligible left side
        if (val < minLeft) minLeft = val;   // update minimum of eligible left side

        const cand1 = maxLeft * nums[j];    // positive·positive or negative·positive
        const cand2 = minLeft * nums[j];    // negative·negative or positive·negative
        if (cand1 > best) best = cand1;
        if (cand2 > best) best = cand2;
    }
    return best;
}

function kthSmallest(par, vals, queries) {
    const n = par.length;
    const children = Array.from({length:n}, () => []);
    for (let i = 1; i < n; i++) children[par[i]].push(i);
    const pathXor = new Array(n).fill(0);
    pathXor[0] = vals[0];
    const stack = [0];
    while (stack.length) {
        const u = stack.pop();
        for (const c of children[u]) { pathXor[c] = pathXor[u] ^ vals[c]; stack.push(c); }
    }
    function subtreeSorted(root) {
        const res = new Set();
        const st = [root];
        while (st.length) { const u = st.pop(); res.add(pathXor[u]); for (const c of children[u]) st.push(c); }
        return [...res].sort((a,b)=>a-b);
    }
    return queries.map(([u,k]) => {
        const arr = subtreeSorted(u);
        return k <= arr.length ? arr[k-1] : -1;
    });
}

class MinHeap {
    constructor() { this.data = []; }
    push(item) {
        this.data.push(item);
        let i = this.data.length - 1;
        while (i > 0) {
            const p = (i-1)>>1;
            if (this.data[p][0] <= this.data[i][0]) break;
            [this.data[p], this.data[i]] = [this.data[i], this.data[p]];
            i = p;
        }
    }
    pop() {
        const top = this.data[0];
        const last = this.data.pop();
        if (this.data.length > 0) {
            this.data[0] = last;
            let i = 0;
            while (true) {
                let l = 2*i+1, r = 2*i+2, smallest = i;
                if (l < this.data.length && this.data[l][0] < this.data[smallest][0]) smallest = l;
                if (r < this.data.length && this.data[r][0] < this.data[smallest][0]) smallest = r;
                if (smallest === i) break;
                [this.data[i], this.data[smallest]] = [this.data[smallest], this.data[i]];
                i = smallest;
            }
        }
        return top;
    }
    get size() { return this.data.length; }
}

function combinations(arr, k) {
    const result = [];
    function backtrack(start, cur) {
        if (cur.length === k) { result.push(cur.slice()); return; }
        for (let i = start; i < arr.length; i++) {
            cur.push(arr[i]);
            backtrack(i+1, cur);
            cur.pop();
        }
    }
    backtrack(0, []);
    return result;
}

var minTime = function(n, k, m, time, mul) {
    const FULL = (1 << n) - 1;
    const dist = [];
    for (let mask = 0; mask <= FULL; mask++) {
        dist.push([new Array(m).fill(Infinity), new Array(m).fill(Infinity)]);
    }
    dist[FULL][0][0] = 0.0;
    const pq = new MinHeap();
    pq.push([0.0, FULL, 0, 0]);
    const EPS = 1e-9;
    while (pq.size > 0) {
        const [cost, remaining, direction, stage] = pq.pop();
        if (cost > dist[remaining][direction][stage] + EPS) continue;
        if (direction === 1 && remaining === 0) return cost;
        if (direction === 0) {
            const people = [];
            for (let i = 0; i < n; i++) if (remaining & (1<<i)) people.push(i);
            for (let sz = 1; sz <= Math.min(k, people.length); sz++) {
                for (const group of combinations(people, sz)) {
                    let gtime = 0;
                    for (const i of group) gtime = Math.max(gtime, time[i]);
                    gtime *= mul[stage];
                    let newRemaining = remaining;
                    for (const i of group) newRemaining &= ~(1<<i);
                    const newStage = (stage + Math.floor(gtime)) % m;
                    const newCost = cost + gtime;
                    if (newCost < dist[newRemaining][1][newStage] - EPS) {
                        dist[newRemaining][1][newStage] = newCost;
                        pq.push([newCost, newRemaining, 1, newStage]);
                    }
                }
            }
        } else {
            for (let i = 0; i < n; i++) {
                if (!(remaining & (1<<i))) {
                    const rtime = time[i] * mul[stage];
                    const newRemaining = remaining | (1<<i);
                    const newStage = (stage + Math.floor(rtime)) % m;
                    const newCost = cost + rtime;
                    if (newCost < dist[newRemaining][0][newStage] - EPS) {
                        dist[newRemaining][0][newStage] = newCost;
                        pq.push([newCost, newRemaining, 0, newStage]);
                    }
                }
            }
        }
    }
    return -1.0;
};

function countPrimeGapBalancedSubarrays(nums, k) {
    const n = nums.length;
    const marks = nums.map(x => (x <= _MAXV && _IS_PRIME[x]) ? x : 0);
    const counts = new Map();
