    let ans = 0;
    const curMin = () => { let m = Infinity; for (const v of counts.keys()) if (v < m) m = v; return m; };
    const curMax = () => { let m = -Infinity; for (const v of counts.keys()) if (v > m) m = v; return m; };
    for (let i = 0; i < n; i++) {
