function hasPrimeFrequency(nums) {
  // 1. count frequencies
  const freq = {};
  for (let i = 0; i < nums.length; i++) {
    const v = nums[i];
    freq[v] = (freq[v] || 0) + 1;
  }

  // 2. find the maximum frequency to size the sieve
  let maxCount = 0;
  for (const key in freq) {
    if (freq[key] > maxCount) maxCount = freq[key];
  }
  if (maxCount < 2) return false;               // no prime possible

  // 3. sieve of Eratosthenes up to maxCount
  const isPrime = new Array(maxCount + 1).fill(true);
  isPrime[0] = isPrime[1] = false;
  for (let p = 2; p * p <= maxCount; p++) {
    if (isPrime[p]) {
      for (let multiple = p * p; multiple <= maxCount; multiple += p) {
        isPrime[multiple] = false;
      }
    }
  }

  // 4. check if any frequency is prime
  for (const key in freq) {
    if (isPrime[freq[key]]) return true;
  }
  return false;
}

function inverseCoinChange(numWays) {
    const n = numWays.length;
    const target = [0, ...numWays];
    const cur = new Array(n + 1).fill(0);
    cur[0] = 1;
    const denominations = [];

    for (let i = 1; i <= n; i++) {
        if (cur[i] > target[i]) return [];
        if (cur[i] === target[i]) continue;
        if (target[i] - cur[i] !== 1) return [];
        denominations.push(i);
        for (let a = i; a <= n; a++) cur[a] += cur[a - i];
    }

    for (let i = 1; i <= n; i++) if (cur[i] !== target[i]) return [];
    return denominations;
}

function minNodesToIncrease(n, edges, cost) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }
    const parent = new Int32Array(n);
    parent.fill(-1);
    const order = [];
    const stack = [0];
    parent[0] = -2;
    while (stack.length) {
        const v = stack.pop();
        order.push(v);
        for (const nb of adj[v]) {
            if (parent[nb] === -1) {
                parent[nb] = v;
                stack.push(nb);
            }
        }
    }
    const maxSum = new Array(n);
    const incCount = new Array(n);
    for (let i = order.length - 1; i >= 0; i--) {
        const v = order[i];
        let maxChild = -Infinity;
        let total = 0;
        let extra = 0;
        for (const nb of adj[v]) {
            if (nb === parent[v]) continue;
            const childMax = maxSum[nb];
            if (childMax > maxChild) maxChild = childMax;
        }
        if (maxChild === -Infinity) { // leaf
            maxSum[v] = cost[v];
            incCount[v] = 0;
        } else {
            for (const nb of adj[v]) {
                if (nb === parent[v]) continue;
                total += incCount[nb];
                if (maxSum[nb] < maxChild) extra++;
            }
            incCount[v] = total + extra;
            maxSum[v] = cost[v] + maxChild;
        }
    }
    return incCount[0];
}

function partitionString(s) {
  const seen = new Set();
  const result = [];
  let cur = '';
  for (const ch of s) {
    cur += ch;
    if (!seen.has(cur)) { seen.add(cur); result.push(cur); cur = ''; }
  }
  return result;
}

function longestCommonPrefixBetweenAdjacentStringsAfterRemovals(words) {
    const n = words.length;
    if (n === 1) return [0];

    const lcpLen = (a, b) => {
        const m = Math.min(a.length, b.length);
        let i = 0;
        while (i < m && a[i] === b[i]) i++;
        return i;
    };

    const lcp = new Array(n - 1).fill(0);
    for (let i = 0; i < n - 1; i++) lcp[i] = lcpLen(words[i], words[i + 1]);

    const prefMax = new Array(n - 1).fill(0);
    let cur = 0;
    for (let i = 0; i < n - 1; i++) { cur = Math.max(cur, lcp[i]); prefMax[i] = cur; }

    const suffMax = new Array(n - 1).fill(0);
    cur = 0;
    for (let i = n - 2; i >= 0; i--) { cur = Math.max(cur, lcp[i]); suffMax[i] = cur; }

    const ans = new Array(n).fill(0);
    for (let i = 0; i < n; i++) {
        let maxExcl = 0;
        const leftPair = i - 1;
        const rightPair = i;
        if (leftPair - 1 >= 0) maxExcl = Math.max(maxExcl, prefMax[leftPair - 1]);
        if (rightPair + 1 <= n - 2) maxExcl = Math.max(maxExcl, suffMax[rightPair + 1]);

        let newPair = 0;
        if (i - 1 >= 0 && i + 1 < n) newPair = lcpLen(words[i - 1], words[i + 1]);

        ans[i] = Math.max(maxExcl, newPair);
    }
    return ans;
}

function maxStability(n, edges, k) {
  class DSU {
    constructor(n) { this.p = Array.from({length:n},(_,i)=>i); this.r = new Array(n).fill(0); }
    find(x) { while (this.p[x]!==x) { this.p[x]=this.p[this.p[x]]; x=this.p[x]; } return x; }
    union(a,b) { a=this.find(a); b=this.find(b); if (a===b) return false; if (this.r[a]<this.r[b]) [a,b]=[b,a]; this.p[b]=a; if (this.r[a]===this.r[b]) this.r[a]++; return true; }
  }

  // Step 1: check mandatory edges alone don't form a cycle / are consistent
  const mandatory = edges.filter(e => e[3] === 1);
  const eligible = edges.filter(e => e[3] === 0);
  {
    const dsu = new DSU(n);
    for (const [u,v] of mandatory) {
      if (!dsu.union(u,v)) return -1; // cycle among mandatory edges -> impossible
    }
  }

  let maxStrength = 0;
  for (const e of edges) maxStrength = Math.max(maxStrength, e[2]);

  function feasible(X) {
    const dsu = new DSU(n);
    let components = n;
    // mandatory edges must all individually satisfy strength >= X (can't upgrade)
    for (const [u,v,s] of mandatory) {
      if (s < X) return false;
      if (dsu.union(u,v)) components--;
    }
    // free eligible edges (strength already >= X)
    for (const [u,v,s] of eligible) {
      if (s >= X) {
        if (dsu.union(u,v)) components--;
      }
    }
    if (components === 1) return true;
    // need upgrades: eligible edges with s < X but 2*s >= X
    let used = 0;
    for (const [u,v,s] of eligible) {
      if (s < X && 2*s >= X) {
        if (dsu.find(u) !== dsu.find(v)) {
          if (used >= k) continue;
          if (dsu.union(u,v)) { components--; used++; }
        }
      }
      if (components === 1) break;
    }
    return components === 1;
  }

  // quick connectivity check ignoring X constraint (using ALL edges, upgraded or not) to see if -1 needed
  {
    const dsu = new DSU(n);
    let components = n;
    for (const [u,v] of edges) { if (dsu.union(u,v)) components--; }
    if (components > 1) return -1;
  }

  let lo = 1, hi = 2 * maxStrength;
  let ans = -1;
  while (lo <= hi) {
    const mid = Math.floor((lo+hi)/2);
    if (feasible(mid)) { ans = mid; lo = mid + 1; } else hi = mid - 1;
  }
  return ans;
}

var minXor = function(nums, k) {
    const n = nums.length;
    const pref = new Array(n+1).fill(0);
    for (let i=0;i<n;i++) pref[i+1] = pref[i]^nums[i];
    function can(limit) {
        const dp = new Array(n+1).fill(0);
        dp[0] = 1;
        for (let i=1;i<=n;i++) {
            let mask = 0;
            for (let j=0;j<i;j++) {
                if ((pref[i]^pref[j]) <= limit) mask |= dp[j] << 1;
            }
            dp[i] = mask;
        }
        return ((dp[n] >> k) & 1) === 1;
    }
    let lo=0, hi=(2**31)-1;
    while (lo<hi) {
        const mid = Math.floor((lo+hi)/2);
        if (can(mid)) hi=mid; else lo=mid+1;
    }
    return lo;
};

function minCost(m, n, waitCost) {
    const entry = (i, j) => (i + 1) * (j + 1);
    const wait = (i, j) => (i === 0 && j === 0) ? 0 : waitCost[i][j];
    let prev = new Float64Array(n);
    let cur = new Float64Array(n);
    prev[0] = entry(0, 0);
    for (let j = 1; j < n; j++) prev[j] = prev[j - 1] + wait(0, j - 1) + entry(0, j);
    for (let i = 1; i < m; i++) {
        cur[0] = prev[0] + wait(i - 1, 0) + entry(i, 0);
        for (let j = 1; j < n; j++) {
            const fromLeft = cur[j - 1] + wait(i, j - 1);
            const fromUp = prev[j] + wait(i - 1, j);
            cur[j] = Math.min(fromLeft, fromUp) + entry(i, j);
        }
        [prev, cur] = [cur, prev];
    }
    return prev[n - 1];
}

function convert(n) {
  const bigN = BigInt(n);                     // use BigInt for safe large powers
  const hex = (bigN * bigN).toString(16).toUpperCase();   // hex of n²
  const base36 = (bigN * bigN * bigN).toString(36).toUpperCase(); // base‑36 of n³
  return hex + base36;                        // concatenate results
}

function minimumTimeToReachDestinationInDirectedGraph(n, edges) {
    if (n === 1) return 0;
    const adj = Array.from({length: n}, () => []);
    for (const [u, v, start, end] of edges) adj[u].push([v, start, end]);
    const INF = 1e18;
    const dist = new Array(n).fill(INF);
    dist[0] = 0;
    const target = n - 1;

    const heap = [[0, 0]];
    const push = (item) => { heap.push(item); let i = heap.length - 1; while (i > 0) { const p = (i-1)>>1; if (heap[i][0] < heap[p][0]) { [heap[i],heap[p]]=[heap[p],heap[i]]; i=p; } else break; } };
    const pop = () => { const top = heap[0]; const last = heap.pop(); if (heap.length) { heap[0] = last; let i = 0; while (true) { let l=2*i+1,r=2*i+2,s=i; if (l<heap.length && heap[l][0]<heap[s][0]) s=l; if (r<heap.length && heap[r][0]<heap[s][0]) s=r; if (s===i) break; [heap[i],heap[s]]=[heap[s],heap[i]]; i=s; } } return top; };

    while (heap.length) {
        const [curTime, u] = pop();
        if (curTime !== dist[u]) continue;
        if (u === target) return curTime;
        for (const [v, start, end] of adj[u]) {
            if (curTime > end) continue;
            const depart = curTime < start ? start : curTime;
            const nextTime = depart + 1;
            if (nextTime < dist[v]) { dist[v] = nextTime; push([nextTime, v]); }
        }
    }
    return -1;
}

function couponCodeValidator(code, businessLine, isActive) {
    const order = { electronics: 0, grocery: 1, pharmacy: 2, restaurant: 3 }; // order map
    const valid = [];

    for (let i = 0; i < code.length; i++) {                     // main loop
        if (!isActive[i]) continue;                              // must be active
        if (!order.hasOwnProperty(businessLine[i])) continue;   // allowed line
        if (!/^[A-Z0-9_]+$/.test(code[i])) continue;             // proper code format
        valid.push({ code: code[i], line: businessLine[i] });
    }

    valid.sort((a, b) => {                                      // sorting according to rules
        const diff = order[a.line] - order[b.line];
        return diff !== 0 ? diff : (a.code < b.code ? -1 : a.code > b.code ? 1 : 0);
    });

    return valid.map(item => item.code);
}

function minimumStabilityFactor(nums, maxC) {
  const n = nums.length;
  function gcd(a, b) {
    while (b !== 0) {
      const t = a % b;
      a = b;
      b = t;
    }
    return a;
  }
  const log = new Int32Array(n + 1);
  for (let i = 2; i <= n; i++) log[i] = log[i >> 1] + 1;
  const K = log[n] + 1;
  const st = Array.from({ length: K }, () => new Int32Array(n));
  for (let i = 0; i < n; i++) st[0][i] = nums[i];
  for (let k = 1; k < K; k++) {
    const half = 1 << (k - 1);
    const cur = st[k];
    const prev = st[k - 1];
    for (let i = 0; i + (1 << k) <= n; i++) {
      cur[i] = gcd(prev[i], prev[i + half]);
    }
  }
  function rangeGcd(l, r) {
    const len = r - l + 1;
    const k = log[len];
    const a = st[k][l];
    const b = st[k][r - (1 << k) + 1];
    return gcd(a, b);
  }
  function can(L) {
    const w = L + 1;
    if (w > n) return true;
    let needed = 0;
    let lastChosen = -1;
    for (let i = 0; i + w <= n; i++) {
      if (rangeGcd(i, i + L) >= 2) {
        if (lastChosen < i) {
          needed++;
          if (needed > maxC) return false;
          lastChosen = i + L;
        }
      }
    }
    return true;
  }
  let low = 0, high = n;
  while (low < high) {
    const mid = (low + high) >> 1;
    if (can(mid)) high = mid;
    else low = mid + 1;
  }
  return low;
}

function minimumTime(n, edges, k) {
    const parent = [...Array(n).keys()];
    const size = new Array(n).fill(1);
    function find(x) { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; }
    function union(a, b) {
        let ra = find(a), rb = find(b);
        if (ra === rb) return false;
        if (size[ra] < size[rb]) [ra, rb] = [rb, ra];
        parent[rb] = ra; size[ra] += size[rb];
        return true;
    }
    const sorted = edges.slice().sort((a, b) => b[2] - a[2]);
    let comps = n;
    for (const [u, v, t] of sorted) {
        if (union(u, v)) {
            comps -= 1;
            if (comps < k) return t;
        }
    }
    return 0;
}

/**
 * @param {number} sx
 * @param {number} sy
 * @param {number} tx
 * @param {number} ty
 * @return {number}
 */
function minMoves(sx, sy, tx, ty) {
    if (sx === tx && sy === ty) return 0;
    // if start is already beyond target, impossible
    if (sx > tx || sy > ty) return -1;
    // queue for BFS: each element is [x, y, steps]
    const queue = [];
    let head = 0;
    queue.push([sx, sy, 0]);
    const visited = new Set();
    visited.add(sx + ',' + sy);
    while (head < queue.length) {
        const [x, y, steps] = queue[head++];
        const m = Math.max(x, y);
        if (m === 0) continue; // cannot move further
        // move in x direction
        const nx = x + m;
        if (nx === tx && y === ty) return steps + 1;
        if (nx <= tx && y <= ty) {
            const key = nx + ',' + y;
            if (!visited.has(key)) {
                visited.add(key);
                queue.push([nx, y, steps + 1]);
            }
        }
        // move in y direction
        const ny = y + m;
        if (x === tx && ny === ty) return steps + 1;
        if (x <= tx && ny <= ty) {
            const key = x + ',' + ny;
            if (!visited.has(key)) {
                visited.add(key);
                queue.push([x, ny, steps + 1]);
            }
        }
    }
    return -1;
}
// TIME: O(N) SPACE: O(N) where N is the number of reachable states within the target rectangle.

function powerGridMaintenance(c, connections, queries) {
  const parent = new Int32Array(c + 1);
  const rank = new Int8Array(c + 1);
  for (let i = 1; i <= c; i++) parent[i] = i;
  function find(x) {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  }
  function union(a, b) {
    let ra = find(a), rb = find(b);
    if (ra === rb) return;
    if (rank[ra] < rank[rb]) {
      const t = ra; ra = rb; rb = t;
    }
    parent[rb] = ra;
    if (rank[ra] === rank[rb]) rank[ra]++;
  }
  for (const [u, v] of connections) union(u, v);
  const compRoot = new Int32Array(c + 1);
  for (let i = 1; i <= c; i++) compRoot[i] = find(i);
  class MinHeap {
    constructor() { this.arr = []; }
    push(val) {
      const a = this.arr;
      a.push(val);
      let i = a.length - 1;
      while (i > 0) {
        const p = (i - 1) >> 1;
        if (a[p] <= a[i]) break;
        [a[p], a[i]] = [a[i], a[p]];
        i = p;
      }
    }
    peek() { return this.arr[0]; }
    pop() {
      const a = this.arr;
      if (a.length === 0) return undefined;
      const min = a[0];
      const last = a.pop();
      if (a.length) {
        a[0] = last;
        let i = 0;
        while (true) {
          let l = i * 2 + 1, r = l + 1, s = i;
          if (l < a.length && a[l] < a[s]) s = l;
          if (r < a.length && a[r] < a[s]) s = r;
          if (s === i) break;
          [a[i], a[s]] = [a[s], a[i]];
          i = s;
        }
      }
      return min;
    }
    size() { return this.arr.length; }
  }
  const heaps = new Array(c + 1);
  for (let i = 1; i <= c; i++) {
    const r = compRoot[i];
    if (!heaps[r]) heaps[r] = new MinHeap();
    heaps[r].push(i);
  }
  const online = new Uint8Array(c + 1);
  online.fill(1, 1);
  const ans = [];
  for (const [type, x] of queries) {
    if (type === 2) {
      online[x] = 0;
    } else {
      // A station that is itself online always resolves its own check,
      // regardless of whether a smaller-id station is online elsewhere in the grid.
      if (online[x]) {
        ans.push(x);
        continue;
      }
      const r = compRoot[x];
      const heap = heaps[r];
      while (heap && heap.size() && online[heap.peek()] === 0) heap.pop();
      ans.push(heap && heap.size() ? heap.peek() : -1);
    }
  }
  return ans;
}

function processStr(s) {
    const out = [];
    let deleted = [];
    for (let i = 0; i < s.length; i++) {
        const ch = s[i];
        if (ch >= 'a' && ch <= 'z') {
            out.push(ch);
        } else if (ch === '#') {
            if (out.length > 0) {
                deleted.push(out.pop());
            }
        } else if (ch === '%') {
            if (deleted.length > 0) {
                out.push(deleted.pop());
            }
        } else if (ch === '*') {
            deleted = [];
        }
    }
    return out.join('');
}

function getKthCharAfterProcessing(s, k) {
    const n = s.length;
    let len = 0;
    for (let i = 0; i < n; i++) {
        const c = s[i];
        if (c === '*') {
            if (len > 0) len--;
        } else if (c === '#') {
            len *= 2;
        } else if (c === '%') {
            // no-op for length
        } else {
            len++;
        }
    }
    if (k >= len) return '.';
    for (let i = n - 1; i >= 0; i--) {
        const c = s[i];
        if (c === '*') {
            len++;
        } else if (c === '#') {
            len = Math.floor(len / 2);
            if (k >= len) k -= len;
        } else if (c === '%') {
            k = len - 1 - k;
        } else {
            len--;
            if (k === len) return c;
        }
    }
    return '.';
}

function minimizeMaximumComponentCost(n, edges, k) {
    if (k >= n) return 0;
    const parent = [...Array(n).keys()];
    const size = new Array(n).fill(1);
    function find(x) { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; }
    function union(a, b) {
        let ra = find(a), rb = find(b);
        if (ra === rb) return false;
        if (size[ra] < size[rb]) [ra, rb] = [rb, ra];
        parent[rb] = ra; size[ra] += size[rb];
        return true;
    }
    const sorted = edges.slice().sort((a, b) => a[2] - b[2]);
    let components = n, answer = 0;
    for (const [u, v, w] of sorted) {
        if (union(u, v)) {
            answer = w;
            components -= 1;
            if (components === k) break;
        }
    }
    return answer;
}

function longestPalindromicPathInGraph(n, edges, label) {
    const adj = Array.from({length: n}, () => []);
    for (const [u, v] of edges) { adj[u].push(v); adj[v].push(u); }

    const maxMask = 1 << n;
    const pairsByMask = Array.from({length: maxMask}, () => new Set());

    for (let i = 0; i < n; i++) pairsByMask[1 << i].add(i + ',' + i);

    for (const [u, v] of edges) {
        if (label[u] === label[v]) {
            const m = (1 << u) | (1 << v);
            pairsByMask[m].add(u + ',' + v);
            pairsByMask[m].add(v + ',' + u);
        }
    }

    const popcount = (x) => { let c = 0; while (x) { c += x & 1; x >>>= 1; } return c; };

    let ans = 1;
    for (let mask = 0; mask < maxMask; mask++) {
        for (const pairStr of pairsByMask[mask]) {
            const [i, j] = pairStr.split(',').map(Number);
            const bits = popcount(mask);
            if (bits > ans) ans = bits;
            for (const u of adj[i]) {
                if ((mask >> u) & 1) continue;
                for (const v of adj[j]) {
                    if ((mask >> v) & 1) continue;
                    if (u === v) continue;
                    if (label[u] !== label[v]) continue;
                    const newMask = mask | (1 << u) | (1 << v);
                    pairsByMask[newMask].add(u + ',' + v);
                }
            }
        }
    }
    return ans;
}

function countIslands(grid, k) {
    const m = grid.length;
    const n = grid[0].length;
    const visited = Array.from({ length: m }, () => Array(n).fill(false));
    const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
    let answer = 0;

    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] > 0 && !visited[i][j]) {
                // explore one island (BFS)
                let sum = 0;
                const q = [[i, j]];
                visited[i][j] = true;
                while (q.length) {
                    const [x, y] = q.pop();
                    sum += grid[x][y];
                    for (const [dx, dy] of dirs) {
                        const nx = x + dx, ny = y + dy;
                        if (nx >= 0 && nx < m && ny >= 0 && ny < n &&
                            grid[nx][ny] > 0 && !visited[nx][ny]) {
                            visited[nx][ny] = true;
                            q.push([nx, ny]);
                        }
                    }
                }
                if (sum % k === 0) answer++;   // check divisibility
            }
        }
    }
    return answer;
}

function maxScore(edges, online, k, n) {
  n = n || online.length;
  const adj = Array.from({length: n}, () => []);
  const indeg = new Array(n).fill(0);
  for (const [u, v, c] of edges) {
    adj[u].push([v, c]);
    indeg[v]++;
  }
  // topo order (Kahn's)
  const topo = [];
  const indegCopy = indeg.slice();
  const queue = [];
  for (let i = 0; i < n; i++) if (indegCopy[i] === 0) queue.push(i);
  let head = 0;
  while (head < queue.length) {
    const u = queue[head++];
    topo.push(u);
    for (const [v] of adj[u]) {
      indegCopy[v]--;
      if (indegCopy[v] === 0) queue.push(v);
    }
  }

  let maxCost = 0;
  for (const [,,c] of edges) maxCost = Math.max(maxCost, c);

  function feasible(X) {
    const INF = Infinity;
    const dist = new Array(n).fill(INF);
    dist[0] = 0;
    for (const u of topo) {
      if (dist[u] === INF) continue;
      if (!online[u] && u !== 0 && u !== n - 1) continue;
      for (const [v, c] of adj[u]) {
        if (c < X) continue;
        if (!online[v]) continue;
        const nd = dist[u] + c;
        if (nd < dist[v]) dist[v] = nd;
      }
    }
    return dist[n-1] !== INF && dist[n-1] <= k;
  }

  if (!feasible(0)) return -1;
  let lo = 0, hi = maxCost, ans = 0;
  while (lo <= hi) {
    const mid = Math.floor((lo+hi)/2);
    if (feasible(mid)) { ans = mid; lo = mid + 1; } else hi = mid - 1;
  }
  return ans;
}

function numberOfIntegersWithPopcountDepthEqualToKI(n, k) {
    if (n < 1) return 0;
    if (k === 0) return 1;

    const maxBits = n === 0 ? 1 : (32 - Math.clz32(n));
    const maxC = maxBits;

    const popcount = (x) => { let c = 0; while (x) { c += x & 1; x >>>= 1; } return c; };

    const depth = new Array(maxC + 1).fill(0);
    depth[1] = 0;
    for (let c = 2; c <= maxC; c++) {
        let cur = c, d = 0;
        while (cur !== 1) { cur = popcount(cur); d++; }
        depth[c] = d;
    }

    const targetDepth = k - 1;
    const candidates = [];
    for (let c = 1; c <= maxC; c++) if (depth[c] === targetDepth) candidates.push(c);

    const factorial = [1];
    for (let i = 1; i <= maxBits; i++) factorial.push(factorial[i - 1] * i);
    const comb = (a, b) => {
        if (b < 0 || b > a) return 0;
        return Math.round(factorial[a] / (factorial[b] * factorial[a - b]));
    };

    const countLeq = (pop) => {
        if (pop < 0) return 0;
        const bits = maxBits;
        let ans = 0, ones = 0;
        let exhausted = true;
        for (let i = bits - 1; i >= 0; i--) {
            if ((n >> i) & 1) {
                const need = pop - ones;
                if (need >= 0 && need <= i) ans += comb(i, need);
                ones++;
                if (ones > pop) { exhausted = false; break; }
            }
        }
        if (exhausted && ones === pop) ans += 1;
        return ans;
    };

    let total = 0;
    for (const c of candidates) total += countLeq(c);
    if (candidates.includes(1)) total -= 1;
    return total;
}

function checkDivisible(n) {
    let sum = 0;          // sum of digits
    let prod = 1;         // product of digits
    let temp = n;

    while (temp > 0) {                // iterate over each digit
        let d = temp % 10;            // current digit
        sum += d;                     // update sum
        prod *= d;                    // update product
        temp = Math.floor(temp / 10); // drop last digit
    }

    const divisor = sum + prod;        // total to test divisibility
    return n % divisor === 0;          // true if divisible, else false
}

function splitArray(nums) {
  function isPrime(x) {
    if (x < 2) return false;
    for (let i = 2; i*i <= x; i++) if (x % i === 0) return false;
    return true;
  }
  let sumA = 0, sumB = 0;
  for (let i = 0; i < nums.length; i++) {
    if (isPrime(i)) sumA += nums[i]; else sumB += nums[i];
  }
  return Math.abs(sumA - sumB);
}

function countNumberOfTrapezoidsI(points) {
    const MOD = 1000000007n;
    const INV2 = (MOD + 1n) / 2n;

    const yCounts = new Map();
    for (const [, y] of points) yCounts.set(y, (yCounts.get(y) || 0) + 1);

    let sumA = 0n, sumASq = 0n;
    for (const c of yCounts.values()) {
        if (c > 1) {
            const a = BigInt(c) * BigInt(c - 1) / 2n;
            const aMod = a % MOD;
            sumA = (sumA + aMod) % MOD;
            sumASq = (sumASq + aMod * aMod) % MOD;
        }
    }

    let ans = ((sumA * sumA - sumASq) % MOD + MOD) % MOD;
    ans = (ans * INV2) % MOD;
    return Number(ans);
}

function numberOfIntegersWithPopcountDepthEqualToKII(nums, queries) {
    class Fenwick {
        constructor(n) { this.n = n; this.bit = new Array(n + 1).fill(0); }
        add(idx, delta) { let i = idx + 1; while (i <= this.n) { this.bit[i] += delta; i += i & -i; } }
        sum(idx) { let i = idx + 1, res = 0; while (i) { res += this.bit[i]; i -= i & -i; } return res; }
        rangeSum(l, r) { if (l > r) return 0; return this.sum(r) - (l ? this.sum(l - 1) : 0); }
    }

    const popcountDepth = (x) => {
        const popcount = (v) => { let c = 0; while (v) { c += v & 1; v >>>= 1; } return c; };
        let d = 0;
        while (x !== 1) { x = popcount(x); d++; }
        return d;
    };

    const n = nums.length;
    const maxDepth = 5;
    const fenwicks = Array.from({length: maxDepth + 1}, () => new Fenwick(n));

    const depths = nums.map(v => popcountDepth(v));
    depths.forEach((d, i) => fenwicks[d].add(i, 1));

    const ans = [];
    for (const q of queries) {
        if (q[0] === 1) {
            const [, l, r, k] = q;
            if (k >= 0 && k <= maxDepth) ans.push(fenwicks[k].rangeSum(l, r));
            else ans.push(0);
        } else {
            const [, idx, val] = q;
            const oldD = depths[idx];
            const newD = popcountDepth(val);
            if (oldD !== newD) {
                fenwicks[oldD].add(idx, -1);
                fenwicks[newD].add(idx, 1);
                depths[idx] = newD;
            }
            nums[idx] = val;
        }
    }
    return ans;
}

function countNumberOfTrapezoidsII(points) {
    const n = points.length;
    const slopeMap = new Map();

    function gcd(a, b) {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    for (let i = 0; i < n; i++) {
        const [x1, y1] = points[i];
        for (let j = i + 1; j < n; j++) {
            const [x2, y2] = points[j];
            let dx = x2 - x1;
            let dy = y2 - y1;
            const g = gcd(Math.abs(dx), Math.abs(dy));
            dx /= g;
            dy /= g;
            if (dx < 0 || (dx === 0 && dy < 0)) {
                dx = -dx;
                dy = -dy;
            }
            const slopeKey = dy + '/' + dx;
            const c = dy * x1 - dx * y1;
            const lineKey = slopeKey + '|' + c;

            let obj = slopeMap.get(slopeKey);
            if (!obj) {
                obj = { total: 0, lineMap: new Map() };
                slopeMap.set(slopeKey, obj);
            }
            obj.total++;
            obj.lineMap.set(lineKey, (obj.lineMap.get(lineKey) || 0) + 1);
        }
    }

    let ans = 0;
    for (const obj of slopeMap.values()) {
        const m = obj.total;
        const totalPairs = m * (m - 1) / 2;
        let collinearPairs = 0;
        for (const k of obj.lineMap.values()) {
            collinearPairs += k * (k - 1) / 2;
        }
        ans += totalPairs - collinearPairs;
    }
    return ans;
}

function maxMedianSum(nums) {
    // sort to be able to pick the optimal medians
    nums.sort((a, b) => a - b);
    const n = nums.length;
    const groups = n / 3;
    let sum = 0;
    // take every second element from the end, skipping the largest each time
    for (let i = n - 2, taken = 0; taken < groups; i -= 2, taken++) {
        sum += nums[i];
    }
    return sum;
}

function maxSubsequenceCount(text) {
    function countLCT(s) {
        let L = 0, LC = 0, LCT = 0;
        for (const ch of s) {
            if (ch === 'L') L++;
            else if (ch === 'C') LC += L;
            else if (ch === 'T') LCT += LC;
        }
        return LCT;
    }
    let best = countLCT(text);
    for (const ins of ['L','C','T']) {
        for (let pos = 0; pos <= text.length; pos++) {
            const candidate = text.slice(0,pos) + ins + text.slice(pos);
            best = Math.max(best, countLCT(candidate));
        }
    }
    return best;
}

var minJumps = function(nums) {
    const n = nums.length;
    if (n === 1) return 0;
    let mx = 1;
    for (const v of nums) mx = Math.max(mx, v);
    const isComposite = new Array(mx + 1).fill(false);
    for (let i = 2; i * i <= mx; i++) {
        if (!isComposite[i]) for (let j = i * i; j <= mx; j += i) isComposite[j] = true;
    }
    const spf = new Array(mx + 1).fill(0);
    for (let i = 2; i <= mx; i++) {
        if (spf[i] === 0) for (let j = i; j <= mx; j += i) if (spf[j] === 0) spf[j] = i;
    }
    const buckets = new Map();
    for (let j = 0; j < n; j++) {
        let v = nums[j];
        while (v > 1) {
            const p = spf[v];
            if (!buckets.has(p)) buckets.set(p, []);
            buckets.get(p).push(j);
            while (v % p === 0) v = Math.floor(v / p);
        }
    }
    const seen = new Array(n).fill(false);
    seen[0] = true;
    let queue = [0];
    let jumps = 0;
    while (queue.length > 0) {
        const next = [];
        for (const idx of queue) {
            if (idx === n - 1) return jumps;
            if (idx > 0 && !seen[idx - 1]) { seen[idx - 1] = true; next.push(idx - 1); }
            if (idx < n - 1 && !seen[idx + 1]) { seen[idx + 1] = true; next.push(idx + 1); }
            const val = nums[idx];
            // Teleport only when the CURRENT value itself is a prime p (not any prime factor of it) -
            // this is the mechanic it's easy to get subtly wrong.
            if (val >= 2 && !isComposite[val]) {
                const lst = buckets.get(val);
                if (lst) {
                    for (const j of lst) if (!seen[j]) { seen[j] = true; next.push(j); }
                    buckets.delete(val);
                }
            }
        }
        queue = next;
        jumps++;
    }
    return -1;
};

function maxXorAndPartition(nums) {
    const n = nums.length;
    const full = 1 << n;
    const BITS = 30;

    // basis[mask] = Int32Array(BITS) linear basis (echelon form) of elements at set-bit positions of mask
    const basis = new Array(full);
    const totalXor = new Int32Array(full);
    const andVal = new Int32Array(full); // AND of elements in mask (mask!=0); andVal[0] unused (empty => sentinel)
    basis[0] = new Int32Array(BITS);
    totalXor[0] = 0;
    andVal[0] = -1; // all bits set, identity for AND, empty set sentinel

    for (let mask = 1; mask < full; mask++) {
        const low = mask & (-mask);
        const idx = Math.log2(low) | 0;
        const prev = mask ^ low;
        totalXor[mask] = totalXor[prev] ^ nums[idx];
        andVal[mask] = andVal[prev] & nums[idx];
        // copy basis from prev, then insert nums[idx]
        const b = basis[prev].slice();
        let v = nums[idx];
        for (let bit = BITS - 1; bit >= 0 && v; bit--) {
            if (!((v >> bit) & 1)) continue;
            if (b[bit] === 0) { b[bit] = v; break; }
            v ^= b[bit];
        }
        basis[mask] = b;
    }

    function bestXorSum(mask) {
        if (mask === 0) return 0; // both A and C empty
        const X = totalXor[mask];
        const b = basis[mask];
        let a = 0;
        for (let bit = BITS - 1; bit >= 0; bit--) {
            if (b[bit] === 0) continue;
            const isXBitZero = ((X >> bit) & 1) === 0;
            if (isXBitZero && !((a >> bit) & 1)) {
                a ^= b[bit];
            }
        }
        return a + (a ^ X);
    }

    let answer = 0;
    for (let B = 0; B < full; B++) {
        const S = (full - 1) ^ B;
        const andB = (B === 0) ? 0 : andVal[B];
        const cand = andB + bestXorSum(S);
        if (cand > answer) answer = cand;
    }
    return answer;
}

function minRemovals(nums, k) {
    nums.sort((a, b) => a - b);               // sort ascending
    let left = 0;
    let best = 0;
    for (let right = 0; right < nums.length; right++) {
        while (nums[right] > k * nums[left]) // shrink window while invalid
            left++;
        const windowSize = right - left + 1; // current valid segment length
        if (windowSize > best) best = windowSize;
    }
    return nums.length - best;                // removals = total - kept
}

function earliestFinishTimeForLandAndWaterRidesII(landStartTime, landDuration, waterStartTime, waterDuration) {
    const INF = 1e18;

    const bisectLeft = (arr, val) => {
        let lo = 0, hi = arr.length;
        while (lo < hi) { const mid = (lo + hi) >> 1; if (arr[mid] < val) lo = mid + 1; else hi = mid; }
        return lo;
    };

    const helper = (firstStarts, firstDurs, secondStarts, secondDurs) => {
        if (!firstStarts.length || !secondStarts.length) return INF;

        const paired = secondStarts.map((s, i) => [s, secondDurs[i]]).sort((a, b) => a[0] - b[0]);
        const secStarts = paired.map(p => p[0]);
        const secEnds = paired.map(p => p[0] + p[1]);
        const secDurs = paired.map(p => p[1]);
        const n = secStarts.length;

        const suffixMinEnd = new Array(n).fill(INF);
        let cur = INF;
        for (let i = n - 1; i >= 0; i--) { cur = Math.min(cur, secEnds[i]); suffixMinEnd[i] = cur; }

        const prefixMinDur = new Array(n).fill(INF);
        cur = INF;
        for (let i = 0; i < n; i++) { cur = Math.min(cur, secDurs[i]); prefixMinDur[i] = cur; }

        let best = INF;
        for (let i = 0; i < firstStarts.length; i++) {
            const s = firstStarts[i], d = firstDurs[i];
            const finishFirst = s + d;
            const idx = bisectLeft(secStarts, finishFirst);
            if (idx < n) best = Math.min(best, suffixMinEnd[idx]);
            if (idx > 0) best = Math.min(best, finishFirst + prefixMinDur[idx - 1]);
        }
        return best;
    };

    const ans = Math.min(
        helper(landStartTime, landDuration, waterStartTime, waterDuration),
        helper(waterStartTime, waterDuration, landStartTime, landDuration)
    );
    return ans === INF ? -1 : ans;
}

function earliestFinishTimeForLandAndWaterRidesI(landStartTime, landDuration, waterStartTime, waterDuration) {
    if (!landStartTime.length || !waterStartTime.length) return -1;

    const land = landStartTime.map((s, i) => [s, landDuration[i]]).sort((a, b) => a[0] - b[0]);
    const water = waterStartTime.map((s, i) => [s, waterDuration[i]]).sort((a, b) => a[0] - b[0]);

    const landStarts = land.map(p => p[0]);
    const landDurs = land.map(p => p[1]);
    const landSum = land.map(p => p[0] + p[1]);

    const waterStarts = water.map(p => p[0]);
    const waterDurs = water.map(p => p[1]);
    const waterSum = water.map(p => p[0] + p[1]);

    const INF = 1e18;
    const bisectLeft = (arr, val) => {
        let lo = 0, hi = arr.length;
        while (lo < hi) { const mid = (lo + hi) >> 1; if (arr[mid] < val) lo = mid + 1; else hi = mid; }
        return lo;
    };

    const prefMinWaterDur = [];
    let cur = INF;
    for (const d of waterDurs) { cur = Math.min(cur, d); prefMinWaterDur.push(cur); }

    const suffixMinWaterSum = new Array(water.length).fill(INF);
    cur = INF;
    for (let i = water.length - 1; i >= 0; i--) { cur = Math.min(cur, waterSum[i]); suffixMinWaterSum[i] = cur; }

    const prefMinLandDur = [];
    cur = INF;
    for (const d of landDurs) { cur = Math.min(cur, d); prefMinLandDur.push(cur); }

    const suffixMinLandSum = new Array(land.length).fill(INF);
    cur = INF;
    for (let i = land.length - 1; i >= 0; i--) { cur = Math.min(cur, landSum[i]); suffixMinLandSum[i] = cur; }

    let best = INF;

    for (const [s, d] of land) {
        const landEnd = s + d;
        let idx = bisectLeft(waterStarts, landEnd) - 1;
        if (idx >= 0) best = Math.min(best, landEnd + prefMinWaterDur[idx]);
        idx = bisectLeft(waterStarts, landEnd);
        if (idx < water.length) best = Math.min(best, suffixMinWaterSum[idx]);
    }

    for (const [s, d] of water) {
        const waterEnd = s + d;
        let idx = bisectLeft(landStarts, waterEnd) - 1;
        if (idx >= 0) best = Math.min(best, waterEnd + prefMinLandDur[idx]);
        idx = bisectLeft(landStarts, waterEnd);
        if (idx < land.length) best = Math.min(best, suffixMinLandSum[idx]);
    }

    return best === INF ? -1 : best;
}

var isTrionic = function(nums) {
    const n = nums.length;
    if (n < 3) return false;
    let i = 0;
    while (i+1<n && nums[i]<nums[i+1]) i++;
    const peak = i;
    if (peak===0 || peak===n-1) return false;
    while (i+1<n && nums[i]>nums[i+1]) i++;
    const valley = i;
    if (valley===peak || valley===n-1) return false;
    while (i+1<n && nums[i]<nums[i+1]) i++;
    return i === n-1;
};

function thresholdMajorityQueries(nums, queries) {
    const n = nums.length;
    const pos = new Map();
    nums.forEach((v, i) => { if (!pos.has(v)) pos.set(v, []); pos.get(v).push(i); });

    let size = 1;
    while (size < n) size <<= 1;
    let tree = new Array(2 * size).fill(null).map(() => [0, 0]);

    function combine(a, b) {
        if (a[0] === b[0]) return [a[0], a[1] + b[1]];
        if (a[1] > b[1]) return [a[0], a[1] - b[1]];
        return [b[0], b[1] - a[1]];
    }
    for (let i = 0; i < n; i++) tree[size + i] = [nums[i], 1];
    for (let i = size - 1; i >= 1; i--) tree[i] = combine(tree[i << 1], tree[(i << 1) | 1]);

    function query(l, r) {
        l += size; r += size + 1;
        let leftRes = [0, 0], rightRes = [0, 0];
        while (l < r) {
            if (l & 1) { leftRes = combine(leftRes, tree[l]); l++; }
            if (r & 1) { r--; rightRes = combine(tree[r], rightRes); }
            l >>= 1; r >>= 1;
        }
        return combine(leftRes, rightRes);
    }
    function bisectLeft(arr, x) {
        let lo = 0, hi = arr.length;
        while (lo < hi) { const mid = (lo+hi)>>1; if (arr[mid] < x) lo = mid+1; else hi = mid; }
        return lo;
    }
    function bisectRight(arr, x) {
        let lo = 0, hi = arr.length;
        while (lo < hi) { const mid = (lo+hi)>>1; if (arr[mid] <= x) lo = mid+1; else hi = mid; }
        return lo;
    }

    const ans = [];
    for (const [l, r, threshold] of queries) {
        const [cand] = query(l, r);
        if (!pos.has(cand)) { ans.push(-1); continue; }
        const lst = pos.get(cand);
        const cnt = bisectRight(lst, r) - bisectLeft(lst, l);
        ans.push(cnt >= threshold ? cand : -1);
    }
    return ans;
}

function maxSumTrionic(nums) {
    const n = nums.length;
    let i = 0;
    let ans = -Infinity;
    while (i < n) {
        const l = i;
        i += 1;
        while (i < n && nums[i - 1] < nums[i]) i += 1; // find maximal increasing run
        if (i === l + 1) continue; // no real increase, need at least 2 elements
        const p = i - 1; // peak
        let s = nums[p - 1] + nums[p]; // minimal valid increasing prefix ending at p
        while (i < n && nums[i - 1] > nums[i]) { s += nums[i]; i += 1; } // decreasing run
        if (i === p + 1 || i === n || nums[i - 1] === nums[i]) continue;
        const q = i - 1; // valley
        s += nums[i];
        i += 1;
        // extend third (increasing) part as far as beneficial
        let mx = 0, t = 0;
        while (i < n && nums[i - 1] < nums[i]) { t += nums[i]; i += 1; mx = Math.max(mx, t); }
        s += mx;
        // extend first part backward from p-2 as far as beneficial
        mx = 0; t = 0;
        let j = p - 2;
        while (j >= l) { t += nums[j]; mx = Math.max(mx, t); j -= 1; }
        s += mx;
        ans = Math.max(ans, s);
        i = q; // restart scan from q (allows overlapping trionic patterns)
    }
    return ans;
}

function minimumTimeToActivateString(s, order, k) {
    const n = s.length;
    const totalSubstrings = n * (n + 1) / 2;
    if (k <= 0) return 0;
    if (k > totalSubstrings) return -1;

    const times = new Array(n).fill(n);
    order.forEach((idx, t) => { times[idx] = t; });

    const goodSubstrings = (t) => {
        let bad = 0, cur = 0;
        for (let i = 0; i < n; i++) {
            if (times[i] > t) cur++;
            else { if (cur) { bad += cur * (cur + 1) / 2; cur = 0; } }
        }
        if (cur) bad += cur * (cur + 1) / 2;
        return totalSubstrings - bad;
    };

    let lo = 0, hi = n - 1, ans = -1;
    while (lo <= hi) {
        const mid = Math.floor((lo + hi) / 2);
        if (goodSubstrings(mid) >= k) { ans = mid; hi = mid - 1; }
        else lo = mid + 1;
    }
    return ans;
}

function maxBalancedShipments(weight) {
    const n = weight.length;
    let count = 0;
    let curMax = -Infinity;
    for (let i = 0; i < n; i++) {
        curMax = Math.max(curMax, weight[i]);
        if (weight[i] < curMax) { count++; curMax = -Infinity; }
    }
    return count;
}

function maxTotal(value, limit) {
    const n = value.length;
    const arr = value.map((v, i) => [v, limit[i]]);
    arr.sort((a, b) => a[1] - b[1] || b[0] - a[0]);
    const status = new Array(n).fill(0);
    let i = 0, j = 0, active = 0, ans = 0;
    while (j < n) {
        const [val, lmt] = arr[j];
        if (active < lmt) {
            status[j] = 1;
            ans += val;
            active += 1;
            if (active === lmt) {
                while (j < n && arr[j][1] === active) j++;
            } else {
                j++;
            }
        } else {
            j++;
        }
        while (i < j && arr[i][1] <= active) {
            active -= status[i];
            i++;
        }
    }
    return ans;
}

function flipSquareSubmatrixVertically(mat, r, c, k) {
    // swap rows inside the square sub-matrix
    for (let i = 0; i < Math.floor(k / 2); i++) {
        const topRow = r + i;
        const bottomRow = r + k - 1 - i;
        for (let j = 0; j < k; j++) {
            const tmp = mat[topRow][c + j];
            mat[topRow][c + j] = mat[bottomRow][c + j];
            mat[bottomRow][c + j] = tmp;
        }
    }
    return mat;
}

function maxKToSortPermutation(nums) {
    let ans = -1;
    for (let i = 0; i < nums.length; i++) {
        if (nums[i] !== i) {
            ans &= nums[i];
        }
    }
    return Math.max(ans, 0);
}

function minimumSensors(n, m, k) {
    const side = 2 * k + 1;
    return Math.ceil(n / side) * Math.ceil(m / side);
}

function allMultisets() {
    const evenDigits = [2,4,6,8];
    const oddChoices = [null,1,3,5,7,9];
    const result = [];
    const n = evenDigits.length;
    for (let mask = 0; mask < (1<<n); mask++) {
        const combo = [];
        for (let i = 0; i < n; i++) if (mask & (1<<i)) combo.push(evenDigits[i]);
        for (const odd of oddChoices) {
            const digits = combo.slice();
            if (odd) digits.push(odd);
            if (digits.length === 0) continue;
            const counts = {};
            let total = 0;
            for (const d of digits) { counts[d] = d; total += d; }
            result.push({len: total, counts});
        }
    }
    return result;
}

function halfMultiset(counts) {
    const half = {};
    let middle = null;
    for (const d in counts) {
        const c = counts[d];
        if (c % 2 === 1) middle = d;
        half[d] = Math.floor(c/2);
    }
    return {half, middle};
}

function minArrangement(counts) {
    const {half, middle} = halfMultiset(counts);
    let halfDigits = [];
    for (const d of Object.keys(half).sort((a,b)=>a-b)) {
        for (let i=0;i<half[d];i++) halfDigits.push(d);
    }
    halfDigits.sort();
    const prefix = halfDigits.join('');
    const mid = middle !== null ? String(middle) : '';
    return prefix + mid + prefix.split('').reverse().join('');
}

function distinctPermutations(items) {
    // items: array of chars, generate distinct permutations
    items = items.slice().sort();
    const results = [];
    const used = new Array(items.length).fill(false);
    const path = [];
    function backtrack() {
        if (path.length === items.length) {
            results.push(path.join(''));
            return;
        }
        for (let i = 0; i < items.length; i++) {
            if (used[i]) continue;
            if (i > 0 && items[i] === items[i-1] && !used[i-1]) continue;
            used[i] = true;
            path.push(items[i]);
            backtrack();
            path.pop();
            used[i] = false;
        }
    }
    backtrack();
    return results;
}

function bestGreaterArrangement(counts, nStr) {
    const L = Object.values(counts).reduce((a,b)=>a+b,0);
    const {half, middle} = halfMultiset(counts);
    let halfItems = [];
    for (const d of Object.keys(half).sort((a,b)=>a-b)) {
        for (let i=0;i<half[d];i++) halfItems.push(d);
    }
    const perms = halfItems.length > 0 ? distinctPermutations(halfItems) : [''];
    let best = null;
    for (const prefix of perms) {
        const mid = middle !== null ? String(middle) : '';
        const full = prefix + mid + prefix.split('').reverse().join('');
        if (full.length !== L) continue;
        if (full > nStr) {
            if (best === null || full < best) best = full;
        }
    }
    return best;
}

function nextSpecial(n) {
    const nStr = String(n);
    const L0 = nStr.length;
    const multisets = allMultisets();
    const byLen = {};
    for (const {len, counts} of multisets) {
        if (!byLen[len]) byLen[len] = [];
        byLen[len].push(counts);
    }
    if (byLen[L0]) {
        let best = null;
        for (const counts of byLen[L0]) {
            const res = bestGreaterArrangement(counts, nStr);
            if (res !== null && (best === null || res < best)) best = res;
        }
        if (best !== null) return best; // return as string (BigInt-safe)
    }
    const lens = Object.keys(byLen).map(Number).sort((a,b)=>a-b);
    for (const l of lens) {
        if (l <= L0) continue;
        let best = null;
        for (const counts of byLen[l]) {
            const arr = minArrangement(counts);
            if (best === null || arr < best) best = arr;
        }
        return best;
    }
    return null;
}

var nextSpecialPalindrome = function(n) {
    return Number(nextSpecial(n));
};

var minCost = function(grid, k) {
    const m = grid.length, n = grid[0].length;
    const INF = Infinity;
    const f = Array.from({length: k + 1}, () => Array.from({length: m}, () => new Array(n).fill(INF)));
    f[0][0][0] = 0;
    for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) {
        if (i > 0) f[0][i][j] = Math.min(f[0][i][j], f[0][i-1][j] + grid[i][j]);
        if (j > 0) f[0][i][j] = Math.min(f[0][i][j], f[0][i][j-1] + grid[i][j]);
    }
    const g = new Map();
    for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) {
        const v = grid[i][j];
        if (!g.has(v)) g.set(v, []);
        g.get(v).push([i, j]);
    }
    const keys = [...g.keys()].sort((a, b) => b - a);
    for (let t = 1; t <= k; t++) {
        let mn = INF;
        for (const key of keys) {
            const pos = g.get(key);
            for (const [i, j] of pos) mn = Math.min(mn, f[t-1][i][j]);
            for (const [i, j] of pos) f[t][i][j] = mn;
        }
        for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) {
            if (i > 0) f[t][i][j] = Math.min(f[t][i][j], f[t][i-1][j] + grid[i][j]);
            if (j > 0) f[t][i][j] = Math.min(f[t][i][j], f[t][i][j-1] + grid[i][j]);
        }
    }
    let ans = INF;
    for (let t = 0; t <= k; t++) ans = Math.min(ans, f[t][m-1][n-1]);
    return ans;
};

function numberOfPerfectPairs(nums) {
    // condition simplifies to: max(|a|,|b|) <= 2*min(|a|,|b|) -- sort abs values, two pointer
    const arr = nums.map(x => Math.abs(x)).sort((a, b) => a - b);
    const n = arr.length;
    let start = 0, ans = 0;
    for (let i = 1; i < n; i++) {
        const need = Math.floor((arr[i] + 1) / 2);
        while (arr[start] < need) start++;
        ans += i - start;
    }
    return ans;
}

function maxProfit(prices, strategy, k) {
    const n = prices.length;
    const h = Math.floor(k / 2);

    let pOriginal = 0;
    for (let i = 0; i < n; i++) pOriginal += strategy[i] * prices[i];

    let newSeg = 0;
    for (let i = h; i < k; i++) newSeg += prices[i];
    let oldSeg = 0;
    for (let i = 0; i < k; i++) oldSeg += strategy[i] * prices[i];
    let maxDelta = Math.max(0, newSeg - oldSeg);

    for (let j = 1; j <= n - k; j++) {
        oldSeg += -strategy[j-1]*prices[j-1] + strategy[j+k-1]*prices[j+k-1];
        newSeg += -prices[j-1+h] + prices[j+k-1];
        maxDelta = Math.max(maxDelta, newSeg - oldSeg);
    }

    return pOriginal + maxDelta;
}

const tests = [
    [[[4,2,8], [-1,0,1], 2], 10],
    [[[5,4,3], [1,1,0], 2], 9],
];
for (const [args, exp] of tests) {
