function minCostReversal(n, edges) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v, w] of edges) {
        adj[u].push([v, w]);       // forward: cost w
        adj[v].push([u, 2 * w]);   // reversed: cost 2*w
    }
    const INF = Infinity;
    const dist = new Array(n).fill(INF);
    dist[0] = 0;
    // simple array-based min-priority queue (fine for correctness-testing scale)
    const pq = [[0, 0]];
    while (pq.length) {
        pq.sort((a, b) => a[0] - b[0]);
        const [d, u] = pq.shift();
        if (d !== dist[u]) continue;
        if (u === n - 1) break;
        for (const [v, w] of adj[u]) {
            const nd = d + w;
            if (nd < dist[v]) {
                dist[v] = nd;
                pq.push([nd, v]);
            }
        }
    }
    return dist[n - 1] === INF ? -1 : dist[n - 1];
}

var xorAfterQueries = function(nums, queries) {
    const MOD = 1000000007n;
    const arr = nums.map(x => BigInt(x));
    for (const [l, r, k, v] of queries) {
        const vv = BigInt(v);
        for (let idx = l; idx <= r; idx += k) {
            arr[idx] = arr[idx] * vv % MOD;
        }
    }
    let x = 0n;
    for (const n of arr) x ^= n;
    return Number(x);
};

function minimumSumAfterDivisibleSumDeletions(nums, k) {
    const total = nums.reduce((a, b) => a + b, 0);
    let pref = 0, dp = 0;
    const best = new Map([[0, 0]]);
    const negInf = -1e30;
    for (const x of nums) {
        pref += x;
        const r = ((pref % k) + k) % k;
        const cand = pref + (best.has(r) ? best.get(r) : negInf);
        if (cand > dp) dp = cand;
        const val = dp - pref;
        if (best.has(r)) { if (val > best.get(r)) best.set(r, val); }
        else best.set(r, val);
    }
    return total - dp;
}

function xorAfterQueries(nums, queries) {
    const MOD = 1000000007n;
    const arr = nums.map(BigInt);
    for (const [l, r, k, v] of queries) {
        const bv = BigInt(v);
        for (let idx = l; idx <= r; idx += k) {
