function maximumWallsDestroyed(robots, distance, walls) {
    const n = robots.length;
    const arr = robots.map((pos, i) => [pos, distance[i]]).sort((a, b) => a[0] - b[0]);
    walls = walls.slice().sort((a, b) => a - b);

    function bisectLeft(arr, target) {
        let lo = 0, hi = arr.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (arr[mid] < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    const memo = new Map();
    function dp(i, j) {
        if (i < 0) return 0;
        const key = i * 2 + j;
        if (memo.has(key)) return memo.get(key);
        const [pos, dist] = arr[i];

        let left = pos - dist;
        if (i > 0) left = Math.max(left, arr[i - 1][0] + 1);
        let l = bisectLeft(walls, left);
        let r = bisectLeft(walls, pos + 1);
        const optLeft = dp(i - 1, 0) + (r - l);

        let right = pos + dist;
        if (i + 1 < n) {
            const [npos, ndist] = arr[i + 1];
            if (j === 0) right = Math.min(right, npos - ndist - 1);
            else right = Math.min(right, npos - 1);
        }
        l = bisectLeft(walls, pos);
        r = bisectLeft(walls, right + 1);
        const optRight = dp(i - 1, 1) + (r - l);

        const res = Math.max(optLeft, optRight);
        memo.set(key, res);
        return res;
    }

    return dp(n - 1, 1);
}

function uniquePaths(grid) {
  const MOD = 1000000007n;
  const n = grid.length, m = grid[0].length;
  const memo = new Map();

  function dp(i, j, direction) {
    // direction: 0 = came from moving down (dx=1,dy=0), 1 = came from moving right (dx=0,dy=1)
    while (i >= 0 && i < n && j >= 0 && j < m && grid[i][j] === 1) {
      direction = 1 - direction;
      if (direction === 0) { i += 1; } else { j += 1; }
    }
    if (i < 0 || i >= n || j < 0 || j >= m) return 0n;
    if (i === n - 1 && j === m - 1) return 1n;
    if (grid[i][j] === 0) {
      const key = i + ',' + j;
      if (memo.has(key)) return memo.get(key);
      const res = (dp(i + 1, j, 0) + dp(i, j + 1, 1)) % MOD;
      memo.set(key, res);
      return res;
    }
    return 0n; // unreachable due to while loop above
  }

  return Number(dp(0, 0, 0) % MOD);
}

function partitionArrayIntoKDistinctGroups(arr, k) {
