function maximumProductOfTwoIntegersWithNoCommonBits(arr) {
    const n = arr.length;
    if (n < 2) return 0;

    const maxVal = Math.max(...arr);
    let bits = maxVal === 0 ? 1 : (32 - Math.clz32(maxVal));
    if (bits === 0) bits = 1;
    const size = 1 << bits;
    const fullMask = size - 1;

    const best = new Array(size).fill(-1);
    const cnt = new Array(size).fill(0);
    for (const v of arr) {
        cnt[v]++;
        if (v > best[v]) best[v] = v;
    }

    for (let i = 0; i < bits; i++) {
        const step = 1 << i;
        for (let mask = 0; mask < size; mask++) {
            if (mask & step) {
                const sub = mask ^ step;
                const b = best[sub];
                if (b > best[mask]) best[mask] = b;
            }
        }
    }

    let ans = 0;
    for (const v of arr) {
        const partner = best[fullMask ^ v];
        if (partner === -1) continue;
        if (partner === v && cnt[v] < 2) continue;
        const prod = v * partner;
        if (prod > ans) ans = prod;
    }
    return ans;
}

