function sumOfBeautifulSubsequences(nums) {
  const MOD = 1000000007n;
  const n = nums.length;
  const maxV = Math.max(...nums);
  // dp[g] = number of strictly increasing subsequences with GCD divisible by g (ending anywhere so far)
  // We process elements left to right; for each element v, for each divisor d of v,
  // cntByGCDmultiple[d] += (sum over subsequences ending before this pos with all elements < v and gcd multiple of d) + 1 (itself alone)
  // Standard technique: f[d] = number of increasing subsequences (so far) whose GCD is a multiple of d.
  // But "increasing" constraint interacts with GCD tracking non-trivially; use per-value list & divisors.
  function gcd(a, b) { while (b) { [a, b] = [b, a % b]; } return a; }

  // g[d] = total count of strictly-increasing subsequences ending with value having last element's value's divisor d covering GCD multiple-of-d, using elements processed so far, restricted to increasing order
  // We need, for value v at position i: for each divisor d of v, newContribution = 1 (itself) + sum of g[d] restricted to subsequences ending with element < v -- but that requires per-value dp, not per-divisor global.
  // Proper approach: dp[v_index][d] too large. Use: for each d, maintain cntByLastVal? Standard editorial approach:
  // f[d] = array over "value" not needed; use: for each d, keep running total of (number of increasing subsequences with gcd multiple of d) as we sweep values in increasing order (process nums sorted by value, but must preserve original index order for "subsequence" -- since subsequence requires increasing VALUE, and original array order doesn't matter for counting count of increasing subsequences by value comparison only if we also require index increasing... actually "subsequence" just needs original index order preserved AND strictly increasing VALUES. This is trickier since we can't just sort by value.

  // Use classic LIS-counting-by-GCD DP: dpText[i][d] = number of increasing subsequences ending at index i with gcd multiple of d.
  // dp[i][d] = 1 (just nums[i]) + sum over j<i, nums[j]<nums[i], d | nums[j] of dp[j][d]
  // We maintain, for each d, a running sum "S[d]" but only counting dp[j][d] for j with nums[j] < current nums[i] -- need per-value ordering too.
  // Efficient version: process indices left to right; maintain for each d a Fenwick tree over VALUE (to get sum of dp[j][d] for nums[j] < v). That's O(n * numDivisors * log(maxV)).
  const divisorsCache = new Map();
  function divisorsOf(v) {
    if (divisorsCache.has(v)) return divisorsCache.get(v);
    const res = [];
    for (let d = 1; d * d <= v; d++) {
      if (v % d === 0) { res.push(d); if (d !== v / d) res.push(v / d); }
    }
    divisorsCache.set(v, res);
    return res;
  }

  // Fenwick tree per divisor d, indexed by value (1..maxV)
  const fenwicks = new Map(); // d -> Array
  function getFenwick(d) {
    if (!fenwicks.has(d)) fenwicks.set(d, new Array(maxV + 2).fill(0n));
    return fenwicks.get(d);
  }
  function fenUpdate(tree, i, val) {
    for (; i <= maxV; i += i & (-i)) tree[i] = (tree[i] + val) % MOD;
  }
  function fenQuery(tree, i) {
    let s = 0n;
    for (; i > 0; i -= i & (-i)) s = (s + tree[i]) % MOD;
    return s;
  }

  const beautyByG = new Map(); // g -> count of subsequences with GCD exactly g
  const dpMultiple = new Map(); // d -> total sum of dp[j][d] over all j processed (for final "exactly g" via Mobius-like subtraction), also we directly need per-d TOTAL (not just prefix) for exact-gcd computation via inclusion-exclusion at the end.

  for (let i = 0; i < n; i++) {
    const v = nums[i];
    const divs = divisorsOf(v);
    const dpForThisElement = new Map(); // d -> dp[i][d]
    for (const d of divs) {
      const tree = getFenwick(d);
      const sumLess = fenQuery(tree, v - 1); // sum of dp[j][d] for nums[j] < v (values 1..v-1)
      const val = (sumLess + 1n) % MOD; // +1 for the subsequence consisting of just this element
      dpForThisElement.set(d, val);
    }
    for (const [d, val] of dpForThisElement) {
      const tree = getFenwick(d);
      fenUpdate(tree, v, val);
      dpMultiple.set(d, ((dpMultiple.get(d) || 0n) + val) % MOD);
    }
  }

  // Now dpMultiple[d] = total number of increasing subsequences whose GCD is a MULTIPLE of d.
  // Use Mobius-style downward subtraction to get EXACT count for each g: exact[g] = multiple[g] - sum(exact[k*g] for k>=2)
  const exact = new Map();
  const ds = Array.from(dpMultiple.keys()).sort((a, b) => b - a);
  for (const g of ds) {
    let val = dpMultiple.get(g) || 0n;
    for (let k = 2 * g; k <= maxV; k += g) {
      if (exact.has(k)) val = (val - exact.get(k) + MOD) % MOD;
    }
    exact.set(g, ((val % MOD) + MOD) % MOD);
  }

  let ans = 0n;
  for (const [g, cnt] of exact) {
    ans = (ans + BigInt(g) * cnt) % MOD;
  }
  return Number(ans);
}

