function countBowlSubarrays(arr) {
    const n = arr.length;
    if (n < 3) return 0;

    // nextGreater[i] = nearest index to the right with a strictly greater value, or -1
    const nextGreater = new Array(n).fill(-1);
    let stack = [];
    for (let i = 0; i < n; i++) {
        while (stack.length && arr[stack[stack.length - 1]] < arr[i]) {
            nextGreater[stack.pop()] = i;
        }
        stack.push(i);
    }

    // prevGreater[i] = nearest index to the left with a strictly greater value, or -1
    const prevGreater = new Array(n).fill(-1);
    stack = [];
    for (let i = n - 1; i >= 0; i--) {
        while (stack.length && arr[stack[stack.length - 1]] < arr[i]) {
            prevGreater[stack.pop()] = i;
        }
        stack.push(i);
    }

    let count = 0;
    // Case A: left endpoint is the smaller one -> r = nextGreater(l)
    for (let l = 0; l < n; l++) {
        const r = nextGreater[l];
        if (r !== -1 && r - l >= 2) count++;
    }
    // Case B: right endpoint is the smaller one -> l = prevGreater(r)
    for (let r = 0; r < n; r++) {
        const l = prevGreater[r];
        if (l !== -1 && r - l >= 2) count++;
    }
    return count;
}

