function countBinaryPalindromesOpt(N) {
    if (N < 0) return 0;
    // FIXED: original returned 0 for N===0 and never counted the number 0 at all
    // in the general case, even though "0" (binary "0") is itself a valid palindrome
    // that must always be included whenever N >= 0.
    if (N === 0) return 1;
    const binLen = N.toString(2).length;   // length of N in binary

    let total = 1; // count the number 0 itself

    // count all palindromes whose length is smaller than binLen
    for (let len = 1; len < binLen; len++) {
        const half = Math.ceil(len / 2);
        total += 1 << (half - 1);            // 2^(half-1) possibilities
    }

    // count palindromes that have the same length as N
    const halfLen = Math.ceil(binLen / 2);
    const start = 1 << (halfLen - 1);        // smallest prefix with leading 1
    const end = 1 << halfLen;                // exclusive upper bound

    for (let prefix = start; prefix < end; prefix++) {
        const palindrome = buildPalindrome(prefix, binLen);
        if (palindrome <= N) total++;        // keep only those ≤ N
    }

    return total;
}

