            if ((x >> bit & 1) === 0) continue;
            if (basis[bit] === 0) {          // insert new independent vector
                basis[bit] = x;
                break;
            }
            x ^= basis[bit];                 // eliminate highest set bit
        }
    }
    // greedy combine basis vectors to obtain maximum XOR
    var maxXor = 0;
    for (var bit = 31; bit >= 0; bit--) {
        if ((maxXor ^ basis[bit]) > maxXor) {
            maxXor ^= basis[bit];
        }
    }
    return maxXor;
}

