function subsequenceSumAfterCapping(nums, k) {
    const n = nums.length;
    const freq = new Array(n + 2).fill(0);
    for (const v of nums) freq[v]++;
    const mask = (1n << BigInt(k + 1)) - 1n;
    // freeDP: achievable sums using items whose true value <= current x (uncapped, contributing their real value)
    let freeDP = 1n;
    let runningCappedCount = n; // items still strictly above current x, each contributing exactly x
    const ans = new Array(n).fill(false);
    for (let x = 1; x <= n; x++) {
        const cntX = freq[x] || 0;
        // items with true value == x join the "free" group at value x (add one at a time)
        for (let i = 0; i < cntX; i++) {
            freeDP |= (freeDP << BigInt(x));
            freeDP &= mask;
        }
        runningCappedCount -= cntX;
        const m = runningCappedCount; // count of items still capped (true value > x), each worth exactly x now
        // combine freeDP with 0..m copies of value x (harmonic-series bitset trick)
        const maxJ = Math.min(m, Math.floor(k / x));
        let combined = 0n;
        let shifted = freeDP;
        for (let j = 0; j <= maxJ; j++) {
            combined |= shifted;
            shifted = (shifted << BigInt(x)) & mask;
        }
        ans[x - 1] = ((combined >> BigInt(k)) & 1n) === 1n;
    }
    return ans;
}

