}

var generateSchedule = function(n) {
    if (n <= 4) return [];
    const remaining = new Map();
    const deg = new Array(n).fill(0);
    for (let a = 0; a < n; a++) {
        for (let b = 0; b < n; b++) {
            if (a !== b) {
                remaining.set(a*1000+b, true);
                deg[a]++; deg[b]++;
            }
        }
    }
    const seq = [];
    let last = null;
    const total = n*(n-1);
    for (let step = 0; step < total; step++) {
        let best = null, bestScore = -1;
        for (const [key, avail] of remaining) {
            if (!avail) continue;
            const a = Math.floor(key/1000), b = key%1000;
            if (last && (a===last[0]||a===last[1]||b===last[0]||b===last[1])) continue;
            const score = deg[a]+deg[b];
            if (score > bestScore) { bestScore = score; best = [a,b]; }
        }
        if (!best) return [];
        const [a,b] = best;
        remaining.set(a*1000+b, false);
        deg[a]--; deg[b]--;
        seq.push([a,b]);
        last = [a,b];
    }
    return seq;
};

