function minSplitMerge(nums1, nums2) {
    const n = nums1.length;
    const start = nums1.join(',');
    const target = nums2.join(',');
    if (start === target) return 0;

    const visited = new Set([start]);
    let queue = [nums1.slice()];
    let steps = 0;

    while (queue.length) {
        steps++;
        const next = [];
        for (const cur of queue) {
            for (let l = 0; l < n; l++) {
                for (let r = l; r < n; r++) {
                    const sub = cur.slice(l, r + 1);
                    const rest = cur.slice(0, l).concat(cur.slice(r + 1));
                    for (let pos = 0; pos <= rest.length; pos++) {
                        const newState = rest.slice(0, pos).concat(sub, rest.slice(pos));
                        const key = newState.join(',');
