    // comparing GROUP SIZES (how many distinct characters share a frequency) -
    // the problem requires the group with the most distinct characters, only
    // using frequency value as a tiebreaker when group sizes are equal.
    const freqToChars = {};
    for (const ch in freq) {
        const k = freq[ch];
        if (!freqToChars[k]) freqToChars[k] = [];
        freqToChars[k].push(ch);
    }

    let bestSize = 0, bestFreq = 0;
    for (const k in freqToChars) {
        const size = freqToChars[k].length;
        const kNum = Number(k);
        if (size > bestSize || (size === bestSize && kNum > bestFreq)) {
            bestSize = size;
            bestFreq = kNum;
        }
    }

    return bestFreq === 0 ? '' : freqToChars[bestFreq].join('');
}

