}

function distinctPointsAfterDeletion(s, k) {
    const n = s.length;
    const prefX = new Int32Array(n + 1);
    const prefY = new Int32Array(n + 1);
    for (let i = 0; i < n; i++) {
        prefX[i + 1] = prefX[i];
        prefY[i + 1] = prefY[i];
        const c = s[i];
        if (c === 'L') prefX[i + 1]--;
        else if (c === 'R') prefX[i + 1]++;
        else if (c === 'U') prefY[i + 1]++;
        else if (c === 'D') prefY[i + 1]--;
    }
    const totalX = prefX[n], totalY = prefY[n];
    const seen = new Set();
    for (let i = k; i <= n; i++) {
        const removedX = prefX[i] - prefX[i - k];
        const removedY = prefY[i] - prefY[i - k];
        const finalX = totalX - removedX;
        const finalY = totalY - removedY;
        seen.add(finalX + ',' + finalY);
    }
    return seen.size;
}

function maxAlternatingSum(arr, swaps) {
    const n = arr.length;
    const parent = new Array(n);
    const rank = new Array(n).fill(0);
    for (let i = 0; i < n; ++i) parent[i] = i;
    function find(x) {
        while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; }
        return x;
    }
    function union(a, b) {
        let ra = find(a), rb = find(b);
        if (ra === rb) return;
        if (rank[ra] < rank[rb]) [ra, rb] = [rb, ra];
        parent[rb] = ra;
        if (rank[ra] === rank[rb]) rank[ra]++;
    }
    for (const [u, v] of swaps) union(u, v);
    const groups = new Map();
    for (let i = 0; i < n; ++i) {
        const r = find(i);
        if (!groups.has(r)) groups.set(r, []);
        groups.get(r).push(i);
    }
    let total = 0;
    for (const idxList of groups.values()) {
        const values = idxList.map(i => arr[i]);
        values.sort((a, b) => b - a);
        let posCnt = 0;
        for (const i of idxList) if (i % 2 === 0) posCnt++;
        let posSum = 0, negSum = 0;
        for (let k = 0; k < values.length; ++k) {
            if (k < posCnt) posSum += values[k]; else negSum += values[k];
        }
        total += posSum - negSum;
    }
    return total;
}

function decimalRepresentation(n) {
