function splitArrayMinDiff(arr) {
    const n = arr.length;
    if (n < 2) return -1;
    const s = new Array(n);
    s[0] = arr[0];
    const f = new Array(n).fill(true);  // f[i]: arr[0..i] strictly increasing
    const g = new Array(n).fill(true);  // g[i]: arr[i..n-1] strictly decreasing
    for (let i = 1; i < n; i++) {
        s[i] = s[i - 1] + arr[i];
        f[i] = f[i - 1] && arr[i] > arr[i - 1];
    }
    for (let i = n - 2; i >= 0; i--) {
        g[i] = g[i + 1] && arr[i] > arr[i + 1];
    }
    let ans = Infinity;
    for (let i = 0; i < n - 1; i++) {
        if (f[i] && g[i + 1]) {
            const leftSum = s[i];
            const rightSum = s[n - 1] - s[i];
            ans = Math.min(ans, Math.abs(leftSum - rightSum));
        }
    }
    return ans === Infinity ? -1 : ans;
}

function numberOfZigZagArrays(n, m) {
    const MOD = 1000000007n;
    if (n === 1) return BigInt(m) % MOD;
    let dp = new Array(m + 1).fill(1n);
    for (let i = 2; i <= n; i++) {
        const pref = new Array(m + 1).fill(0n);
        for (let v = 1; v <= m; v++) pref[v] = (pref[v - 1] + dp[v]) % MOD;
        const total = pref[m];
        const ndp = new Array(m + 1).fill(0n);
        if (i % 2 === 0) { for (let v = 1; v <= m; v++) ndp[v] = pref[v - 1]; }
        else { for (let v = 1; v <= m; v++) ndp[v] = (total - pref[v] + MOD) % MOD; }
        dp = ndp;
    }
    let half = 0n;
    for (let v = 1; v <= m; v++) half = (half + dp[v]) % MOD;
    return Number((half * 2n) % MOD);
}

