function zigZagArrays(n, l, r) {
    const MOD = 1000000007n;
    const m = r - l + 1;
    function matMul(A, B) {
        const sz = A.length;
        const C = Array.from({length: sz}, () => new Array(sz).fill(0n));
        for (let i = 0; i < sz; i++) for (let k = 0; k < sz; k++) {
            if (A[i][k] === 0n) continue;
            for (let j = 0; j < sz; j++) {
                if (B[k][j] === 0n) continue;
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD;
            }
        }
        return C;
    }
    function matPow(M, e) {
        const sz = M.length;
        let R = Array.from({length: sz}, (_, i) => Array.from({length: sz}, (_, j) => i === j ? 1n : 0n));
        let base = M;
        while (e > 0n) {
            if (e & 1n) R = matMul(R, base);
            base = matMul(base, base);
            e >>= 1n;
        }
        return R;
    }
    const T = Array.from({length: m}, () => new Array(m).fill(0n));
    for (let j = 0; j < m; j++) for (let i = m - j; i < m; i++) T[i][j] = 1n;
    const powT = matPow(T, BigInt(n - 1));
    let total = 0n;
    for (let i = 0; i < m; i++) for (let j = 0; j < m; j++) total = (total + powT[i][j]) % MOD;
    return Number((total * 2n) % MOD);
}

function countNoZeroPairs(n) {
    const digits = String(n).split('').map(Number).reverse();
    digits.push(0);
    const L = digits.length;
    let dp = [[[0, 0], [0, 0]], [[0, 0], [0, 0]]]; // dp[carry][aliveA][aliveB]
    dp[0][1][1] = 1;
    for (let pos = 0; pos < L; pos++) {
        const ndp = [[[0, 0], [0, 0]], [[0, 0], [0, 0]]];
        const target = digits[pos];
        for (let carry = 0; carry <= 1; carry++) {
            for (let aliveA = 0; aliveA <= 1; aliveA++) {
                for (let aliveB = 0; aliveB <= 1; aliveB++) {
                    const ways = dp[carry][aliveA][aliveB];
                    if (ways === 0) continue;
                    let A;
                    if (aliveA) {
                        A = [];
                        for (let d = 1; d <= 9; d++) A.push([d, 1]);
                        if (pos > 0) A.push([0, 0]);
                    } else {
                        A = [[0, 0]];
                    }
                    let B;
                    if (aliveB) {
                        B = [];
                        for (let d = 1; d <= 9; d++) B.push([d, 1]);
                        if (pos > 0) B.push([0, 0]);
                    } else {
                        B = [[0, 0]];
                    }
                    for (const [da, na] of A) {
                        for (const [db, nb] of B) {
                            const sm = da + db + carry;
                            if (sm % 10 !== target) continue;
                            ndp[Math.floor(sm / 10)][na][nb] += ways;
                        }
                    }
                }
            }
        }
        dp = ndp;
    }
    return dp[0][0][0];
}

class ExamTracker {
    constructor() { this.times = []; this.prefix = [0]; }
    record(time, score) { this.times.push(time); this.prefix.push(this.prefix[this.prefix.length - 1] + score); }
    totalScore(startTime, endTime) {
        let lo = 0, hi = this.times.length;
        while (lo < hi) { const mid = (lo + hi) >> 1; if (this.times[mid] < startTime) lo = mid + 1; else hi = mid; }
        const lo2 = lo;
        lo = 0; hi = this.times.length;
        while (lo < hi) { const mid = (lo + hi) >> 1; if (this.times[mid] <= endTime) lo = mid + 1; else hi = mid; }
        if (lo2 >= lo) return 0;
        return this.prefix[lo] - this.prefix[lo2];
    }
}

function removeKBalanced(s, k) {
    const stack = []; // each element: [char, count]
    for (const c of s) {
        if (stack.length && stack[stack.length - 1][0] === c) {
            stack[stack.length - 1][1]++;
        } else {
            stack.push([c, 1]);
        }
        if (c === ')' && stack.length > 1) {
            const top = stack[stack.length - 1];
            const prev = stack[stack.length - 2];
            if (top[1] === k && prev[1] >= k) {
                stack.pop();
                prev[1] -= k;
                if (prev[1] === 0) stack.pop();
            }
        }
    }
    let result = '';
    for (const [ch, cnt] of stack) result += ch.repeat(cnt);
    return result;
}

