    let maxLen = 2;                          // longest length found so far
    let curLen = 2;                          // length of current Fibonacci subarray
    for (let i = 2; i < n; i++) {
        // if current element continues the Fibonacci property, extend; otherwise reset
        if (arr[i] === arr[i - 1] + arr[i - 2]) {
            curLen++;
        } else {
            curLen = 2;
        }
        if (curLen > maxLen) maxLen = curLen;
    }
    return maxLen;
}

function sumElementsWithFreqDivisibleByK(arr, k) {
