    for (let i = 0; i < arr.length; i++) { // count frequencies
        const v = arr[i];
        freq[v] = (freq[v] || 0) + 1;
    }
    let total = 0;
    // add value * its frequency when frequency % k == 0
    for (const key in freq) {
        const count = freq[key];
        if (count % k === 0) total += Number(key) * count;
    }
    return total;
}

var sumOfAncestors = function(n, edges, nums) {
    function squarefree(num) {
        let i = 2;
        while (i * i <= num) {
            while (num % (i * i) === 0) num = Math.floor(num / (i * i));
            i++;
        }
        return num;
    }
    const vals = nums.map(squarefree);
    const graph = Array.from({length: n}, () => []);
    for (const [u, v] of edges) { graph[u].push(v); graph[v].push(u); }
    let ans = 0;
    const history = new Map();
    function dfs(u, p) {
        const v = vals[u];
        ans += history.get(v) || 0;
        history.set(v, (history.get(v) || 0) + 1);
        for (const w of graph[u]) {
            if (w !== p) dfs(w, u);
        }
        history.set(v, history.get(v) - 1);
    }
    dfs(0, -1);
    return ans;
};

function maximumPartitionFactor(points) {
    const n = points.length;
    if (n < 2) return 0;
    let maxSum = -Infinity, minSum = Infinity, maxDiff = -Infinity, minDiff = Infinity;
    for (const [x, y] of points) {
        const s = x + y, d = x - y;
        if (s > maxSum) maxSum = s;
        if (s < minSum) minSum = s;
        if (d > maxDiff) maxDiff = d;
        if (d < minDiff) minDiff = d;
    }
    return Math.max(maxSum - minSum, maxDiff - minDiff);
}

function smallestMissingMultiple(arr, k) {
