    }
    let candidate = k;                               // start checking from the first positive multiple
    while (multiples.has(candidate)) {               // find the first multiple that is absent
        candidate += k;
    }
    return candidate;
}

function smallestPermutationGreater(s, target) {
    const n = s.length;
    const baseCount = new Array(26).fill(0);
    for (const c of s) baseCount[c.charCodeAt(0) - 97]++;

    let best = null;
    for (let i = n - 1; i >= 0; i--) {
        const count = baseCount.slice();
        let ok = true;
        for (let j = 0; j < i; j++) {
            const idx = target.charCodeAt(j) - 97;
            if (count[idx] === 0) { ok = false; break; }
            count[idx]--;
        }
        if (!ok) continue;
        const tIdx = target.charCodeAt(i) - 97;
        let pick = -1;
        for (let d = tIdx + 1; d < 26; d++) {
            if (count[d] > 0) { pick = d; break; }
        }
        if (pick === -1) continue;
        count[pick]--;
        let suffix = '';
        for (let d = 0; d < 26; d++) suffix += String.fromCharCode(97 + d).repeat(count[d]);
        const candidate = target.slice(0, i) + String.fromCharCode(97 + pick) + suffix;
        if (best === null || candidate < best) best = candidate;
    }
    return best === null ? '' : best;
}

