function longestBalancedOptimal(s) {
  function calc1(str) {
    let res = 0, i = 0, n = str.length;
    while (i < n) {
      let j = i + 1;
      while (j < n && str[j] === str[i]) j++;
      res = Math.max(res, j - i);
      i = j;
    }
    return res;
  }
  function calc2(str, a, b) {
    let res = 0, i = 0, n = str.length;
    while (i < n) {
      while (i < n && str[i] !== a && str[i] !== b) i++;
      const pos = new Map([[0, i - 1]]);
      let d = 0;
      while (i < n && (str[i] === a || str[i] === b)) {
        d += str[i] === a ? 1 : -1;
        if (pos.has(d)) res = Math.max(res, i - pos.get(d));
        else pos.set(d, i);
        i++;
      }
    }
    return res;
  }
  function calc3(str) {
    const pos = new Map([['0,0', -1]]);
    let ca = 0, cb = 0, cc = 0, res = 0;
    for (let i = 0; i < str.length; i++) {
      if (str[i] === 'a') ca++; else if (str[i] === 'b') cb++; else cc++;
      const key = (ca - cb) + ',' + (cb - cc);
      if (pos.has(key)) res = Math.max(res, i - pos.get(key));
      else pos.set(key, i);
    }
    return res;
  }
  const x = calc1(s);
  const y = Math.max(calc2(s, 'a', 'b'), calc2(s, 'b', 'c'), calc2(s, 'a', 'c'));
  const z = calc3(s);
  return Math.max(x, y, z);
}

