function countWaysToChooseCoprimeIntegersFromRows(rows) {
    const MOD = 1000000007n;
    if (!rows.length) return 0;

    let maxVal = 0;
    for (const row of rows) for (const v of row) if (v > maxVal) maxVal = v;
    if (maxVal === 0) return 0;

    const mu = new Array(maxVal + 1).fill(1);
    mu[0] = 0;
    const isPrime = new Array(maxVal + 1).fill(true);
    const primes = [];
    for (let i = 2; i <= maxVal; i++) {
        if (isPrime[i]) { primes.push(i); mu[i] = -1; }
        for (const p of primes) {
            const ip = i * p;
            if (ip > maxVal) break;
            isPrime[ip] = false;
            if (i % p === 0) { mu[ip] = 0; break; }
            else mu[ip] = -mu[i];
        }
    }

    const divisors = Array.from({length: maxVal + 1}, () => []);
    for (let d = 1; d <= maxVal; d++) for (let mult = d; mult <= maxVal; mult += d) divisors[mult].push(d);

    let ways = new Array(maxVal + 1).fill(1n);
    for (const row of rows) {
        const cnt = new Array(maxVal + 1).fill(0);
        for (const v of row) for (const d of divisors[v]) cnt[d]++;
        for (let d = 1; d <= maxVal; d++) ways[d] = (ways[d] * BigInt(cnt[d])) % MOD;
    }

    let ans = 0n;
    for (let d = 1; d <= maxVal; d++) {
        ans = (ans + BigInt(mu[d]) * ways[d]) % MOD;
    }
    return Number(((ans % MOD) + MOD) % MOD);
}

function removeZeros(n) {
    const sign = n < 0 ? -1 : 1;          // keep sign
    n = Math.abs(n);
    let result = 0;
    let place = 1;
    while (n > 0) {
        const digit = n % 10;
        if (digit !== 0) {                // skip zero digits
            result += digit * place;
            place *= 10;
        }
        n = Math.floor(n / 10);
    }
    return sign * result;                 // restore sign
}

function maxAlternatingSumSquares(arr) {
