    // first ceil(n/2) slots), the smallest get '-' (the rest).
    const sorted = [...arr].sort((x, y) => Math.abs(y) - Math.abs(x));
    const plusCount = Math.ceil(sorted.length / 2);
    let total = 0;
    for (let i = 0; i < sorted.length; i++) {
        const sq = sorted[i] * sorted[i];
        total += (i < plusCount ? 1 : -1) * sq;
    }
    return total;
}
