function minimumCost(s, t, flipCost, swapCost, crossCost) {
    // diff0: mismatches where s[i]='0',t[i]='1'; diff1: mismatches where s[i]='1',t[i]='0'
    let diff0 = 0, diff1 = 0;
    for (let i = 0; i < s.length; i++) {
        if (s[i] !== t[i]) {
            if (s[i] === '0') diff0++; else diff1++;
