var wordSquares = function(words) {
    const n = words.length;
    const res = [];
    for (let i = 0; i < n; i++) {
        const top = words[i];
        for (let j = 0; j < n; j++) {
            if (j === i) continue;
            const left = words[j];
            if (top[0] !== left[0]) continue;
            for (let k = 0; k < n; k++) {
