            }
        }
    }
    res.sort((a,b) => {
        for (let idx = 0; idx < 4; idx++) {
            if (a[idx] < b[idx]) return -1;
            if (a[idx] > b[idx]) return 1;
        }
        return 0;
    });
    return res;
};

function countCaesarCipherPairs(words) {
    const patternCount = Object.create(null); // map pattern → occurrences
    for (let i = 0; i < words.length; i++) {
        const w = words[i];
        let key = '';
        // build pattern of successive character differences (mod 26)
        for (let j = 1; j < w.length; j++) {
            const diff = (w.charCodeAt(j) - w.charCodeAt(j - 1) + 26) % 26;
            key += diff + ',';
        }
        patternCount[key] = (patternCount[key] || 0) + 1;
    }
    let pairs = 0;
    // sum nC2 for each pattern group
    for (const k in patternCount) {
        const c = patternCount[k];
        pairs += c * (c - 1) / 2;
    }
    return pairs;
}

