function maximumAND(nums, k, m) {
    let mx = 0, tmp = Math.max(...nums) + k;
    while (tmp > 0) { mx++; tmp = Math.floor(tmp / 2); }
    let ans = 0;
    const cost = new Array(nums.length).fill(0);
    for (let bit = mx - 1; bit >= 0; bit--) {
        const target = ans | (1 << bit);
        for (let i = 0; i < nums.length; i++) {
