function minimumEdgeToggles(n, edges, start, target) {
    const adj = Array.from({ length: n }, () => []);
    edges.forEach(([u, v], idx) => {
        adj[u].push([v, idx]);
        adj[v].push([u, idx]);
    });

    const d = [];
    for (let i = 0; i < n; i++) d.push((start[i] === target[i]) ? 0 : 1);

    const parent = new Array(n).fill(-1);
    const edgeToParent = new Array(n).fill(-1);
    const order = [];
    const visited = new Array(n).fill(false);
    const stack = [0];
    visited[0] = true;
    while (stack.length) {
        const u = stack.pop();
        order.push(u);
        for (const [v, idx] of adj[u]) {
            if (!visited[v]) {
                visited[v] = true;
                parent[v] = u;
                edgeToParent[v] = idx;
                stack.push(v);
            }
        }
    }

    const need = new Array(n).fill(0);
    for (let i = order.length - 1; i >= 0; i--) {
        const u = order[i];
        let parity = 0;
        for (const [v] of adj[u]) {
            if (v !== parent[u]) parity ^= need[v];
        }
        need[u] = d[u] ^ parity;
    }

    if (need[0] !== 0) return [-1];

    const result = [];
    for (let u = 1; u < n; u++) {
        if (need[u] === 1) result.push(edgeToParent[u]);
    }
    result.sort((a, b) => a - b);
    return result;
}
module.exports = { minimumEdgeToggles };

function maxCapacity(costs, capacity, budget) {
    const n = costs.length;
    const arr = [];
    for (let i = 0; i < n; i++) if (costs[i] < budget) arr.push([costs[i], capacity[i]]);
    if (arr.length === 0) return 0;
    arr.sort((a, b) => a[0] - b[0]);
    const m = arr.length;
    let ans = Math.max(...arr.map(x => x[1]));
    const LOG = Math.max(1, Math.ceil(Math.log2(m + 1)));
    const sparse = Array.from({length: LOG}, () => new Array(m).fill(0));
    for (let i = 0; i < m; i++) sparse[0][i] = arr[i][1];
    for (let j = 1; (1 << j) <= m; j++) {
        const half = 1 << (j - 1);
        for (let i = 0; i + (1 << j) <= m; i++) sparse[j][i] = Math.max(sparse[j-1][i], sparse[j-1][i+half]);
    }
    function query(l, r) {
        if (l > r) return -Infinity;
        const length = r - l + 1;
        const k = Math.floor(Math.log2(length));
        return Math.max(sparse[k][l], sparse[k][r - (1 << k) + 1]);
    }
    let hi = m - 1;
    for (let i = 0; i < m; i++) {
        if (hi < i) hi = i;
        while (hi > i && arr[i][0] + arr[hi][0] >= budget) hi--;
        if (hi > i) {
            const bp = query(i + 1, hi);
            if (bp !== -Infinity) ans = Math.max(ans, arr[i][1] + bp);
        }
    }
    return ans;
}

