// LC 3826 - Minimum Partition Score
// value(subarray) = sumArr*(sumArr+1)/2 -- this is convex increasing in sumArr, so DP over prefix sums works.
function minPartitionScoreOptimal(nums, k) {
  const n = nums.length;
  const prefix = new Array(n+1).fill(0);
  for (let i = 0; i < n; i++) prefix[i+1] = prefix[i] + nums[i];
  function value(sum) { return sum * (sum+1) / 2; }
  const INF = Infinity;
  // dp[i][j] = min score partitioning first i elements into j subarrays
  const dp = Array.from({length:n+1}, () => new Array(k+1).fill(INF));
  dp[0][0] = 0;
  for (let i = 1; i <= n; i++) {
    for (let j = 1; j <= Math.min(k, i); j++) {
      for (let p = j-1; p < i; p++) {
        if (dp[p][j-1] === INF) continue;
        const sum = prefix[i] - prefix[p];
        const v = dp[p][j-1] + value(sum);
        if (v < dp[i][j]) dp[i][j] = v;
      }
    }
  }
  return dp[n][k];
}

