// LC 3825 - Longest Strictly Increasing Subsequence With Non-Zero Bitwise AND
// Key insight: if the AND of a subsequence is non-zero, some bit b is set in ALL elements.
// So for each bit b (0..~20), find LIS among elements that have bit b set. Answer = max over bits.
function longestSubseqOptimal(nums) {
  const BITS = 20;
  let best = 0;
  for (let b = 0; b < BITS; b++) {
    const filtered = nums.filter(v => (v >> b) & 1);
    if (filtered.length === 0) continue;
    // standard O(n log n) LIS (strictly increasing)
    const tails = [];
    for (const v of filtered) {
      let lo = 0, hi = tails.length;
      while (lo < hi) { const mid = (lo+hi)>>1; if (tails[mid] < v) lo = mid+1; else hi = mid; }
      if (lo === tails.length) tails.push(v); else tails[lo] = v;
    }
    best = Math.max(best, tails.length);
  }
  return best;
}

function nthSmallestWithKOnes(n, k) {
    function binom(a, b) {
        if (b < 0 || b > a) return 0;
        let res = 1;
        if (b > a - b) b = a - b;
        for (let i = 0; i < b; i++) res = res * (a - i) / (i + 1);
        return Math.round(res);
    }
    if (k === 0) return n === 1 ? 0 : -1;
    let pos = k - 1;
    while (binom(pos + 1, k) < n) pos++;
    let remaining = n - 1, bitsLeft = k, result = 0;
    for (let p = pos; p >= 0; p--) {
        if (bitsLeft === 0) break;
        const count = p >= bitsLeft ? binom(p, bitsLeft) : 0;
        if (remaining >= count) { result |= (1 << p); remaining -= count; bitsLeft--; }
    }
    return result;
}

function reverseLettersThenSpecials(s) {
    const chars = s.split('');                 // work on a mutable array
    const letters = [];                        // store letters
    const specials = [];                       // store special characters

    // collect letters and specials
    for (let i = 0; i < chars.length; i++) {
        const ch = chars[i];
        if ((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z')) {
            letters.push(ch);
        } else {
            specials.push(ch);
        }
    }

    // reverse the two groups
    letters.reverse();
    specials.reverse();

    // rebuild the string using the reversed groups
    for (let i = 0; i < chars.length; i++) {
        const ch = chars[i];
        if ((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z')) {
            chars[i] = letters.shift();   // take next reversed letter
        } else {
            chars[i] = specials.shift();  // take next reversed special
        }
    }

    return chars.join('');
}
