function minimumK(nums, limit) {
    let total = 0, maxVal = 0;
    for (let v of nums) { total += v; if (v > maxVal) maxVal = v; }
    if (total <= limit) return 0;
    let low = 0, high = maxVal;
    while (low < high) {
        const mid = Math.floor((low + high) / 2);
        let reducedSum = 0;
        for (let v of nums) reducedSum += v > mid ? v - mid : 0;
        if (reducedSum <= limit) high = mid; else low = mid + 1;
    }
    return low;
}

