    let dp = Array.from({length: m+1}, () => new Array(K+1).fill(NEG));
    dp[0][0] = 0;
    for (let i = 1; i <= n; i++) {
        const ndp = Array.from({length: m+1}, () => new Array(K+1).fill(NEG));
        ndp[0][0] = 0;
        for (let j = 1; j <= m; j++) {
            for (let t = 0; t <= K; t++) {
