        while (stack.length >= 2) {
            const top = stack[stack.length - 1];
            const next = stack[stack.length - 2];
            if (top !== next) break;
            stack.pop();                  // remove top
            stack.pop();                  // remove next
            stack.push(top + next);       // push merged value
        }
    }
    return stack;
}
