function solve(n, edges, s, queries) {
    const LOG = Math.max(1, Math.ceil(Math.log2(n+1)));
    const adj = Array.from({length:n}, () => []);
    for (const [u,v] of edges) { adj[u].push(v); adj[v].push(u); }
    const charBit = Array.from(s).map(ch => 1 << (ch.charCodeAt(0)-97));
    const up = Array.from({length:n}, () => new Array(LOG).fill(0));
    const depth = new Array(n).fill(0);
    const tin = new Array(n).fill(0), tout = new Array(n).fill(0);
    const initMask = new Array(n).fill(0);
    let timer = 0;
    const stack = [[0,-1,0]];
    while (stack.length) {
        const [node, parent, state] = stack.pop();
        if (state === 0) {
            tin[node] = timer++;
            up[node][0] = parent !== -1 ? parent : node;
            for (let k=1;k<LOG;k++) up[node][k] = up[up[node][k-1]][k-1];
            depth[node] = parent === -1 ? 0 : depth[parent]+1;
            initMask[node] = (parent !== -1 ? initMask[parent] : 0) ^ charBit[node];
            stack.push([node,parent,1]);
            for (const nb of adj[node]) if (nb !== parent) stack.push([nb,node,0]);
        } else {
            tout[node] = timer - 1;
        }
    }
    function lca(u,v) {
        if (depth[u] < depth[v]) [u,v]=[v,u];
        let diff = depth[u]-depth[v], bit=0;
        while (diff) { if (diff&1) u = up[u][bit]; diff >>= 1; bit++; }
        if (u === v) return u;
        for (let k=LOG-1;k>=0;k--) if (up[u][k] !== up[v][k]) { u = up[u][k]; v = up[v][k]; }
        return up[u][0];
    }
    const bit = new Array(n+1).fill(0);
    function bitUpdate(idx, val) { let i = idx+1; while (i<=n) { bit[i]^=val; i += i&(-i); } }
    function bitPrefix(idx) { let res=0, i=idx+1; while(i>0) { res^=bit[i]; i -= i&(-i);} return res; }
    const answers = [];
    for (const q of queries) {
        const parts = q.split(' ');
        if (parts[0] === 'update') {
            const node = Number(parts[1]);
            const newBit = 1 << (parts[2].charCodeAt(0)-97);
            const oldBit = charBit[node];
            if (newBit !== oldBit) {
                const delta = oldBit ^ newBit;
                bitUpdate(tin[node], delta);
                if (tout[node]+1 < n) bitUpdate(tout[node]+1, delta);
                charBit[node] = newBit;
