        } else {
            const u = Number(parts[1]), v = Number(parts[2]);
            const w = lca(u,v);
            const maskU = initMask[u] ^ bitPrefix(tin[u]);
            const maskV = initMask[v] ^ bitPrefix(tin[v]);
            const curW = charBit[w];
            const pathMask = maskU ^ maskV ^ curW;
            answers.push((pathMask & (pathMask-1)) === 0);
        }
    }
    return answers;
}

