function sumKDigitNumbers(L, R, K) {
    const MOD = 1000000007n;
    function modpow(base, exp, mod) {
        base %= mod;
        let res = 1n;
        while (exp > 0n) {
            if (exp & 1n) res = res * base % mod;
            base = base * base % mod;
            exp >>= 1n;
        }
        return res;
    }
    const l = BigInt(L), r = BigInt(R), k = BigInt(K);
    const d = r - l + 1n;
    const inv2 = modpow(2n, MOD - 2n, MOD);
    const sumDigits = ((l + r) % MOD) * (d % MOD) % MOD * inv2 % MOD;
    const pow_d = modpow(d % MOD, k - 1n, MOD);
    const pow10k = modpow(10n, k, MOD);
    const inv9 = modpow(9n, MOD - 2n, MOD);
    const geo = ((pow10k - 1n + MOD) % MOD) * inv9 % MOD;
    return sumDigits * pow_d % MOD * geo % MOD;
}

function countSequences(nums, k) {
    const n = nums.length;
    const memo = new Map();
    function gcd(a, b) { while (b) { [a, b] = [b, a % b]; } return a; }
    function dfs(i, p, q) {
        if (i === n) return (p === k && q === 1) ? 1 : 0;
        const key = i + ',' + p + ',' + q;
        if (memo.has(key)) return memo.get(key);
        let res = dfs(i + 1, p, q);
        const x = nums[i];
        const g1 = gcd(p * x, q);
        res += dfs(i + 1, (p * x) / g1, q / g1);
        const g2 = gcd(p, q * x);
        res += dfs(i + 1, p / g2, (q * x) / g2);
        memo.set(key, res);
        return res;
    }
    return dfs(0, 1, 1);
}

