function minOperationsParityAlternating(nums) {
    const n = nums.length;
    const parity = nums.map(x => ((x % 2) + 2) % 2);
    let mismA = 0, mismB = 0;
    for (let i = 0; i < n; i++) {
        const expA = i % 2;
        const expB = 1 - i % 2;
        if (parity[i] !== expA) mismA++;
        if (parity[i] !== expB) mismB++;
    }
    const bestOps = Math.min(mismA, mismB);
    const candidates = [];
    if (mismA === bestOps) candidates.push(0);
    if (mismB === bestOps) candidates.push(1);

    function bestRangeForPattern(startParity) {
        const fixedVals = [];
        const mismVals = [];
        for (let i = 0; i < n; i++) {
            const exp = startParity === 0 ? i % 2 : 1 - i % 2;
            if (parity[i] === exp) fixedVals.push(nums[i]);
            else mismVals.push(nums[i]);
        }
        if (mismVals.length === 0) {
            return fixedVals.length ? Math.max(...fixedVals) - Math.min(...fixedVals) : 0;
        }
        const lo = fixedVals.length ? Math.min(...fixedVals) : Math.min(...mismVals.map(v => v - 1));
        const hi = fixedVals.length ? Math.max(...fixedVals) : Math.max(...mismVals.map(v => v - 1));
        const chosen = mismVals.map(v => v - 1);
        const allVals = fixedVals.concat(chosen);
        let loBound = 0, hiBound = Math.max(...allVals) - Math.min(...allVals);

        function feasible(W) {
            const baseLo = hi - W, baseHi = lo;
            if (baseLo > baseHi) return false;
            const events = [];
            for (const v of mismVals) {
                const aLo = v - 1 - W, aHi = v - 1;
                const bLo = v + 1 - W, bHi = v + 1;
                if (aHi + 1 >= bLo) {
                    events.push([aLo, 1]);
                    events.push([bHi + 1, -1]);
                } else {
                    events.push([aLo, 1]); events.push([aHi + 1, -1]);
                    events.push([bLo, 1]); events.push([bHi + 1, -1]);
                }
            }
            const ptsSet = new Set(events.map(e => e[0]));
            ptsSet.add(baseLo); ptsSet.add(baseHi);
            const pts = Array.from(ptsSet).sort((a, b) => a - b);
            const eventsSorted = events.slice().sort((a, b) => a[0] - b[0]);
            let idx = 0, cur = 0;
            const needed = mismVals.length;
            for (const p of pts) {
                while (idx < eventsSorted.length && eventsSorted[idx][0] <= p) {
                    cur += eventsSorted[idx][1];
                    idx++;
                }
                if (p >= baseLo && p <= baseHi && cur >= needed) return true;
            }
            return false;
        }

        while (loBound < hiBound) {
            const mid = Math.floor((loBound + hiBound) / 2);
            if (feasible(mid)) hiBound = mid;
            else loBound = mid + 1;
        }
        return loBound;
    }

    const bestRange = Math.min(...candidates.map(bestRangeForPattern));
    return [bestOps, bestRange];
}
