    for (let i = 1; i < n; i++) if (s[i] < s[i - 1]) { sorted = false; break; }
    if (sorted) return 0;
    if (n === 2) return -1;
    let mn = s[0], mx = s[0];
    for (const c of s) { if (c < mn) mn = c; if (c > mx) mx = c; }
