    const memo = new Map();
    // dfs(x,y): min cost to partition s[x..y-1], choosing between keeping it whole
    // or (only if length is even) splitting into two equal halves recursively
    function dfs(x, y) {
        const key = x + ',' + y;
        if (memo.has(key)) return memo.get(key);
        const whole = segCost(x, y);
        const L = y - x;
        let res = whole;
        if (L % 2 === 0) {
            const mid = x + L / 2;
            const split = dfs(x, mid) + dfs(mid, y);
