        let sum = 0n;

        // full blocks of numbers with fewer digits than N
        for (let len = 1; len < digits; len++) {
            const count = 9n * (10n ** BigInt(len - 1));          // how many numbers have this length
            const commasPer = Math.floor((len - 1) / 3);          // commas each such number needs
            sum += count * BigInt(commasPer);
        }

