class EventManager {
    constructor() {
        this.byName = new Map();       // name -> timestamp
        this.sorted = [];              // array of [timestamp, name], kept sorted by timestamp
    }

    _bisectLeft(ts) {
        let lo = 0, hi = this.sorted.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (this.sorted[mid][0] < ts) lo = mid + 1; else hi = mid;
        }
        return lo;
    }

    addEvent(name, timestamp) {
        if (this.byName.has(name)) return;
        this.byName.set(name, timestamp);
        const idx = this._bisectLeft(timestamp);
        this.sorted.splice(idx, 0, [timestamp, name]);
    }

    deleteEvent(name) {
        if (!this.byName.has(name)) return;
        const ts = this.byName.get(name);
        const idx = this._bisectLeft(ts);
        this.sorted.splice(idx, 1);
        this.byName.delete(name);
    }

    getNextEvent(name) {
        if (!this.byName.has(name)) return -1;
        const ts = this.byName.get(name);
        const idx = this._bisectLeft(ts);
        if (idx + 1 < this.sorted.length) return this.sorted[idx + 1][1];
        return -1;
    }

    getPreviousEvent(name) {
        if (!this.byName.has(name)) return -1;
        const ts = this.byName.get(name);
        const idx = this._bisectLeft(ts);
        if (idx - 1 >= 0) return this.sorted[idx - 1][1];
        return -1;
    }
}

var sortableIntegers = function(nums) {
