function minOperations(nums, k) {
    const n = nums.length;
    const INF = Infinity;
    // solve(start,end): DP over candidate peak positions [start,end), skip-or-take at each,
    // taking a position forces the next one to be skipped (peaks can't be adjacent)
    function solve(start, end) {
        const memo = new Map();
        function dp(i, need) {
            if (need === 0) return 0;
            if (i >= end) return INF;
            const key = i + ',' + need;
            if (memo.has(key)) return memo.get(key);
            const skip = dp(i + 1, need);
            const prevV = nums[(i - 1 + n) % n];
            const nextV = nums[(i + 1) % n];
            const cost = Math.max(Math.max(prevV, nextV) + 1, nums[i]) - nums[i];
            const take = cost + dp(i + 2, need - 1);
            const res = Math.min(skip, take);
            memo.set(key, res);
            return res;
