        else if (ch === '1') close++;
    }
    return 2 * Math.min(open, close);
}

function multiSourceFloodFill(rows, cols, sources) {
    const result = Array.from({ length: rows }, () => new Array(cols).fill(0));
    const visited = Array.from({ length: rows }, () => new Array(cols).fill(false));
    // min-heap keyed by [dist, -value] using a simple binary heap
    const heap = [];
    function push(item) { heap.push(item); let i = heap.length - 1;
        while (i > 0) { const p = (i - 1) >> 1;
            if (heap[p][0] > heap[i][0] || (heap[p][0] === heap[i][0] && heap[p][1] > heap[i][1])) { [heap[p], heap[i]] = [heap[i], heap[p]]; i = p; } else break; } }
    function pop() { const top = heap[0]; const last = heap.pop();
        if (heap.length) { heap[0] = last; let i = 0;
            while (true) { let l = 2*i+1, r = 2*i+2, s = i;
                if (l < heap.length && (heap[l][0] < heap[s][0] || (heap[l][0]===heap[s][0]&&heap[l][1]<heap[s][1]))) s = l;
                if (r < heap.length && (heap[r][0] < heap[s][0] || (heap[r][0]===heap[s][0]&&heap[r][1]<heap[s][1]))) s = r;
                if (s === i) break; [heap[s], heap[i]] = [heap[i], heap[s]]; i = s; } }
        return top; }
    for (const [r, c, v] of sources) push([0, -v, r, c]);
    const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
    while (heap.length) {
        const [dist, negV, r, c] = pop();
        if (visited[r][c]) continue;
        visited[r][c] = true;
        result[r][c] = -negV;
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && !visited[nr][nc]) push([dist + 1, negV, nr, nc]);
        }
    }
    return result;
}

function firstStableIndex(nums, k) {
    const n = nums.length;
    const right = new Array(n).fill(nums[n - 1]);
    for (let i = n - 2; i >= 0; i--) right[i] = Math.min(right[i + 1], nums[i]);
    let left = -Infinity;
    for (let i = 0; i < n; i++) {
        left = Math.max(left, nums[i]);
        if (left - right[i] <= k) return i;
    }
    return -1;
}

function smallestStableIndex(nums, k) {
    const n = nums.length;
    const prefixMax = new Array(n);
    prefixMax[0] = nums[0];
    for (let i = 1; i < n; i++) prefixMax[i] = Math.max(prefixMax[i - 1], nums[i]);
    const suffixMin = new Array(n);
    suffixMin[n - 1] = nums[n - 1];
    for (let i = n - 2; i >= 0; i--) suffixMin[i] = Math.min(suffixMin[i + 1], nums[i]);
    for (let i = 0; i < n; i++) if (prefixMax[i] - suffixMin[i] <= k) return i;
    return -1;
}

function countEvenConnectedSubgraphs(values, edges) {
    const n = values.length;
    const adj = Array.from({length: n}, () => []);
    for (const [u, v] of edges) { adj[u].push(v); adj[v].push(u); }
    const sumMask = new Array(1 << n).fill(0);
    for (let mask = 1; mask < (1 << n); mask++) {
        const lsb = mask & -mask;
        const idx = Math.log2(lsb);
        sumMask[mask] = sumMask[mask ^ lsb] + values[idx];
    }
    let answer = 0;
    for (let mask = 1; mask < (1 << n); mask++) {
        if (sumMask[mask] & 1) continue;
        let start = 0;
        while (((mask >> start) & 1) === 0) start++;
        const visited = new Array(n).fill(false);
        visited[start] = true;
        const stack = [start];
        let visitedCount = 0;
        while (stack.length) {
            const v = stack.pop();
            visitedCount++;
            for (const nb of adj[v]) {
                if (visited[nb]) continue;
                if ((mask >> nb) & 1) { visited[nb] = true; stack.push(nb); }
            }
        }
        let popcount = 0, m = mask;
        while (m) { popcount += m & 1; m >>= 1; }
        if (visitedCount === popcount) answer++;
    }
    return answer;
}

function countGoodIntegersOnPath(l, r, directions) {
    const key = new Array(16).fill(false);
    let row = 0, col = 0;
    key[0] = true;
    for (const c of directions) {
        if (c === 'D') row++; else col++;
        key[row * 4 + col] = true;
    }
    let s = '';
    function dfs(pos, last, lim, memo) {
        if (pos === 16) return 1;
        const memoKey = lim ? -1 : pos * 10 + last;
        if (!lim && memo.has(memoKey)) return memo.get(memoKey);
        let res = 0;
        const start = key[pos] ? last : 0;
        const end = lim ? parseInt(s[pos], 10) : 9;
        for (let i = start; i <= end; i++) {
            res += dfs(pos + 1, key[pos] ? i : last, lim && (i === end), memo);
        }
        if (!lim) memo.set(memoKey, res);
        return res;
    }
    function calc(x) {
        if (x < 0) return 0;
        s = String(x).padStart(16, '0');
        return dfs(0, 0, true, new Map());
    }
    return calc(r) - calc(l - 1);
}

function kthSmallestEven(arr, queries) {
    const results = [];
    for (const [l, r, k] of queries) {
        const evensSet = new Set();
        for (let i = l; i <= r; i++) if (arr[i] % 2 === 0) evensSet.add(arr[i]);
        const evens = Array.from(evensSet).sort((a, b) => a - b);
        let ans = 2 * k;
        for (const e of evens) {
            if (e <= ans) ans += 2;
            else break;
        }
        results.push(ans);
    }
    return results;
}

function findValidElements(nums) {
    const n = nums.length;
    const sufMax = new Array(n);
    sufMax[n - 1] = nums[n - 1];
    for (let i = n - 2; i >= 0; i--) sufMax[i] = Math.max(sufMax[i + 1], nums[i]);
    const ans = [];
    let preMax = -Infinity;
    for (let i = 0; i < n; i++) {
        const x = nums[i];
        if (x > preMax || i === n - 1 || x > sufMax[i + 1]) ans.push(x);
        preMax = Math.max(preMax, x);
    }
    return ans;
}

function isValidDigitNumber(n, x) {
    const s = String(n);
    return s.includes(String(x)) && s[0] !== String(x);
}

function minOperations(nums) {
    let ans = 0;
    for (let i = 1; i < nums.length; i++) ans += Math.max(0, nums[i - 1] - nums[i]);
    return ans;
}

function compareBitonicParts(arr) {
    if (!arr || arr.length === 0) return -1;
    let total = 0;
    let peakVal = arr[0];
    let leftSum = 0;
    let cum = 0;
    for (const v of arr) {
        total += v;
        if (v > peakVal) {
            peakVal = v;
            leftSum = cum;
        }
        cum += v;
    }
    const rightSum = total - leftSum - peakVal;
    if (leftSum > rightSum) return 0;
    if (leftSum < rightSum) return 1;
    return -1;
}

function countIndices(nums) {
    var result = 0;
    for (var i = 0; i < nums.length; i++) {
        // compare parity of element and its index
        if ((nums[i] & 1) !== (i & 1)) result++;
    }
    return result;
}

var maxAlternatingSum = function(nums, k) {
    const MAXV = 100001;
    const bitDown = new Array(MAXV+2).fill(0);
    const bitUp = new Array(MAXV+2).fill(0);
    const n = nums.length;
    function update(bit, i, val) {
        for (; i <= MAXV; i += i & (-i)) if (bit[i] < val) bit[i] = val;
    }
    function query(bit, i) {
        let res = 0;
        for (; i > 0; i -= i & (-i)) if (bit[i] > res) res = bit[i];
        return res;
    }
    const up = new Array(n).fill(0);
    const down = new Array(n).fill(0);
    let ans = -Infinity;
    let inserted = -1;
    for (let i = 0; i < n; i++) {
        const limit = i - k;
        while (inserted < limit) {
            inserted++;
            update(bitDown, nums[inserted], down[inserted]);
            update(bitUp, MAXV + 1 - nums[inserted], up[inserted]);
        }
        const bestDown = query(bitDown, nums[i]-1);
        up[i] = nums[i] + Math.max(0, bestDown);
        const bestUp = query(bitUp, MAXV + 1 - (nums[i]+1));
        down[i] = nums[i] + Math.max(0, bestUp);
        ans = Math.max(ans, up[i], down[i]);
    }
    return ans;
};

function sortVowels(s) {
    const vowelsSet = new Set(['a','e','i','o','u']);
    const freq = new Map();
    const firstOcc = new Map();
    const positions = [];
    const arr = s.split('');
    for (let i = 0; i < arr.length; i++) {
        const c = arr[i];
        if (vowelsSet.has(c)) {
            positions.push(i);
            freq.set(c, (freq.get(c) || 0) + 1);
            if (!firstOcc.has(c)) firstOcc.set(c, i);
        }
    }
    const letters = Array.from(freq.keys());
    letters.sort((a, b) => {
        const fa = freq.get(a), fb = freq.get(b);
        if (fa !== fb) return fb - fa;
        return firstOcc.get(a) - firstOcc.get(b);
    });
    const sortedVowels = [];
    for (const c of letters) for (let k = 0; k < freq.get(c); k++) sortedVowels.push(c);
    for (let idx = 0; idx < positions.length; idx++) arr[positions[idx]] = sortedVowels[idx];
    return arr.join('');
}

function sumPrimesBetweenReverse(n) {
    // reverse the digits of n
    let rev = 0, tmp = n;
    while (tmp > 0) {
        rev = rev * 10 + (tmp % 10);
        tmp = Math.floor(tmp / 10);
    }

    const low = Math.min(n, rev);
    const high = Math.max(n, rev);
    if (high < 2) return 0;                     // no primes possible

    // Sieve of Eratosthenes up to the larger bound – optimal for a single range query
    const isPrime = new Uint8Array(high + 1);
    isPrime.fill(1);
    isPrime[0] = isPrime[1] = 0;
    for (let i = 2; i * i <= high; i++) {
        if (isPrime[i]) {
            for (let j = i * i; j <= high; j += i) {
                isPrime[j] = 0;
            }
        }
    }

    let sum = 0;
    for (let i = low; i <= high; i++) {
        if (isPrime[i]) sum += i;                // accumulate prime numbers in the interval
    }
    return sum;
}

function minFlips(s) {
    const n = s.length;
    let totalOnes = 0;
    for (const c of s) if (c === '1') totalOnes++;
    const costAll0 = totalOnes;
    const costAll1 = n - totalOnes;
    const bestSingle1 = totalOnes >= 1 ? totalOnes - 1 : 1;
    let costTwoEnds;
    if (n === 1) {
        costTwoEnds = s[0] === '1' ? 0 : 1;
    } else {
        const left = s[0] === '1' ? 0 : 1;
        const right = s[n - 1] === '1' ? 0 : 1;
        let middleOnes = 0;
        for (let i = 1; i < n - 1; i++) if (s[i] === '1') middleOnes++;
        costTwoEnds = left + right + middleOnes;
    }
    return Math.min(Math.min(costAll0, costAll1), Math.min(bestSingle1, costTwoEnds));
}

function minCosts(nums, queries) {
    const n = nums.length;
    const closest = new Array(n).fill(0);
    for (let i = 0; i < n; i++) {
        if (i === 0) closest[i] = 1;
        else if (i === n - 1) closest[i] = n - 2;
        else {
            const dl = nums[i] - nums[i - 1], dr = nums[i + 1] - nums[i];
            closest[i] = dl <= dr ? i - 1 : i + 1;
        }
    }
    const adj = Array.from({ length: n }, () => []);
    for (let i = 0; i < n - 1; i++) {
        const w = nums[i + 1] - nums[i];
        adj[i].push([i + 1, w]);
        adj[i + 1].push([i, w]);
    }
    for (let i = 0; i < n; i++) adj[i].push([closest[i], 1]);

    function dijkstra(src) {
        const dist = new Array(n).fill(Infinity);
        dist[src] = 0;
        const visited = new Array(n).fill(false);
        for (let iter = 0; iter < n; iter++) {
            let u = -1, best = Infinity;
            for (let i = 0; i < n; i++) if (!visited[i] && dist[i] < best) { best = dist[i]; u = i; }
            if (u === -1) break;
            visited[u] = true;
            for (const [v, w] of adj[u]) {
                if (dist[u] + w < dist[v]) dist[v] = dist[u] + w;
            }
        }
        return dist;
    }
    const cache = new Map();
    const ans = [];
    for (const [l, r] of queries) {
        if (!cache.has(l)) cache.set(l, dijkstra(l));
        ans.push(cache.get(l)[r]);
    }
    return ans;
}

function scoreValidator(events) {
    let score = 0, counter = 0;
    for (const e of events) {
        if (counter === 10) break;
        if (e === 'W') counter++;
        else if (e === 'WD' || e === 'NB') score += 1;
        else score += Number(e);
    }
    return [score, counter];
}

function maxFixedPoints(nums) {
    const n = nums.length;
    const req = nums.map((v, i) => i - v);
    const dp = new Array(n).fill(0);
    for (let i = 0; i < n; i++) {
        if (req[i] < 0) { dp[i] = 0; continue; }
        dp[i] = 1;
        for (let j = 0; j < i; j++) {
            if (dp[j] > 0 && nums[j] < nums[i] && req[j] <= req[i]) {
                dp[i] = Math.max(dp[i], dp[j] + 1);
            }
        }
    }
    return n ? Math.max(...dp) : 0;
}

