function minGenerations(points, target) {
    const targetKey = target.join(',');
    let pointSet = new Set(points.map(p => p.join(',')));
    if (pointSet.has(targetKey)) return 0;
    for (let gen = 1; gen <= 40; gen++) {
        const pts = Array.from(pointSet).map(s => s.split(',').map(Number));
        const newPoints = new Set();
        const n = pts.length;
        for (let i = 0; i < n; i++) {
            for (let j = i + 1; j < n; j++) {
                const a = pts[i], b = pts[j];
                const avg = a.map((v, k) => Math.floor((v + b[k]) / 2));
                newPoints.add(avg.join(','));
            }
        }
        let addedNew = false;
        for (const p of newPoints) if (!pointSet.has(p)) { pointSet.add(p); addedNew = true; }
        if (pointSet.has(targetKey)) return gen;
        if (!addedNew) break;
    }
    return -1;
}

var countWordOccurrences = function(chunks, queries) {
    const s = chunks.join("");
    const n = s.length;
    const cnt = new Map();
    let i = 0;
    while (i < n) {
        const c = s[i];
        if (c === ' ' || c === '-') { i++; continue; }
        let j = i;
        while (j < n) {
            const cj = s[j];
            if (cj === ' ') break;
            if (cj === '-') {
                const isLower = ch => ch >= 'a' && ch <= 'z';
                const joiner = (j > i) && isLower(s[j-1]) && (j+1 < n) && isLower(s[j+1]);
                if (!joiner) break;
            }
            j++;
        }
        const word = s.substring(i, j);
        cnt.set(word, (cnt.get(word) || 0) + 1);
        i = j;
    }
    return queries.map(q => cnt.get(q) || 0);
};

function minimumThresholdPath(n, edges, s, t, K) {
    const adj = Array.from({ length: n }, () => []);
    const weights = new Set();
    for (const [u, v, w] of edges) {
        adj[u].push([v, w]);
        adj[v].push([u, w]);
        weights.add(w);
    }
    let uniq = Array.from(weights).sort((a, b) => a - b);
    if (uniq.length === 0 || uniq[0] > 0) uniq = [0, ...uniq];
    function feasible(limit) {
        const dist = new Array(n).fill(Infinity);
        const deque = [];
        dist[s] = 0;
        deque.push(s);
        while (deque.length) {
            const u = deque.shift();
            for (const [v, w] of adj[u]) {
                const cost = w > limit ? 1 : 0;
                const nd = dist[u] + cost;
                if (nd < dist[v] && nd <= K) {
                    dist[v] = nd;
                    if (cost === 0) deque.unshift(v);
                    else deque.push(v);
                }
            }
        }
        return dist[t] <= K;
    }
    let lo = 0, hi = uniq.length - 1, ans = -1;
    while (lo <= hi) {
        const mid = (lo + hi) >> 1;
        const thr = uniq[mid];
        if (feasible(thr)) { ans = thr; hi = mid - 1; }
        else lo = mid + 1;
    }
    return ans;
}

function minimizeArraySum(arr) {
    const n = arr.length;
    if (n === 0) return 0;

    // find the maximum value to size auxiliary arrays
    const maxVal = Math.max(...arr);

    // mark which numbers actually appear in the array
    const exists = new Uint8Array(maxVal + 1);
    for (const v of arr) exists[v] = 1;

    // sentinel must fit in Int32Array; maxVal + 1 is larger than any real divisor
    const INF = maxVal + 1;
    const minDiv = new Int32Array(maxVal + 1).fill(INF);

    // MAIN LOGIC: for each present value d, update all its multiples
    for (let d = 1; d <= maxVal; d++) {
        if (!exists[d]) continue;
        for (let m = d; m <= maxVal; m += d) {
            if (exists[m] && d < minDiv[m]) {
                minDiv[m] = d;
            }
        }
    }

    let total = 0;
    for (const v of arr) total += minDiv[v];
    return total;
}

function concatenateArrayWithReverse(arr) {
    var n = arr.length;
    var result = new Array(2 * n);
    for (var i = 0; i < n; i++) {
        result[i] = arr[i];                     // copy original element
        result[2 * n - 1 - i] = arr[i];         // place it in reverse position
    }
    return result;
}

function minCostToBuyApples(N, cost, weight) {
    const m = cost.length;
    const maxW = Math.max(...weight);
    const limit = N + maxW;
    const dp = new Array(limit + 1).fill(Infinity);
    dp[0] = 0;
    for (let i = 0; i < limit; i++) {
        if (dp[i] === Infinity) continue;
        for (let j = 0; j < m; j++) {
            const next = Math.min(limit, i + weight[j]);
            if (dp[i] + cost[j] < dp[next]) dp[next] = dp[i] + cost[j];
        }
    }
    let ans = Infinity;
    for (let i = N; i <= limit; i++) ans = Math.min(ans, dp[i]);
    return ans === Infinity ? -1 : ans;
}

function checkAdjacentDigitDifferences(s) {
    for (let i = 0; i + 1 < s.length; i++) {
        const cur = s.charCodeAt(i) - 48;
        const nxt = s.charCodeAt(i + 1) - 48;
        if (Math.abs(cur - nxt) > 2) return false;
    }
    return true;
}

function countKthRoots(l, r, k) {
    if (k === 1) return r - l + 1;
    let ans = 0;
    for (let x = 0; ; x++) {
        let y = 1;
        let over = false;
        for (let i = 0; i < k; i++) {
            y *= x;
            if (y > r) { over = true; break; }
        }
        if (over) break;
        if (y >= l && y <= r) ans++;
        if (x > 0 && y > r) break;
    }
    return ans;
}

function smallestUniqueSubarray(nums) {
    const n = nums.length;
    if (n === 0) return -1;
    const MOD1 = 1000000007n, MOD2 = 1000000009n, BASE = 91138233n, OFFSET = 1000000007n;
    const pow1 = new Array(n + 1).fill(1n), pow2 = new Array(n + 1).fill(1n);
    for (let i = 1; i <= n; i++) { pow1[i] = (pow1[i-1]*BASE)%MOD1; pow2[i] = (pow2[i-1]*BASE)%MOD2; }
    const pref1 = new Array(n + 1).fill(0n), pref2 = new Array(n + 1).fill(0n);
    for (let i = 0; i < n; i++) {
        const val = BigInt(nums[i]) + OFFSET;
        pref1[i+1] = (pref1[i]*BASE + val) % MOD1;
        pref2[i+1] = (pref2[i]*BASE + val) % MOD2;
    }
    function hasUnique(L) {
        const cnt = new Map();
        for (let i = 0; i + L <= n; i++) {
            let h1 = (pref1[i+L] - pref1[i]*pow1[L]) % MOD1; if (h1 < 0n) h1 += MOD1;
            let h2 = (pref2[i+L] - pref2[i]*pow2[L]) % MOD2; if (h2 < 0n) h2 += MOD2;
            const key = h1 + ',' + h2;
            cnt.set(key, (cnt.get(key) || 0) + 1);
        }
        for (const c of cnt.values()) if (c === 1) return true;
        return false;
    }
    let lo = 1, hi = n, answer = -1;
    while (lo <= hi) {
        const mid = (lo + hi) >> 1;
        if (hasUnique(mid)) { answer = mid; hi = mid - 1; }
        else lo = mid + 1;
    }
    return answer;
}

function countNonAdjacentSubsets(parent, nums, k) {
    const MOD = 1000000007n;
    const n = parent.length;
    const children = Array.from({length: n}, () => []);
    for (let i = 0; i < n; i++) if (parent[i] !== -1) children[parent[i]].push(i);

    // iterative post-order to avoid deep recursion
    const order = [];
    const stack = [0];
    while (stack.length) {
        const u = stack.pop();
        order.push(u);
        for (const v of children[u]) stack.push(v);
    }
    const dpNot = new Array(n), dpSel = new Array(n);
    for (let i = order.length - 1; i >= 0; i--) {
        const u = order[i];
        let dn = new Array(k).fill(0n); dn[0] = 1n;
        let ds = new Array(k).fill(0n); ds[nums[u] % k] = 1n;
        for (const v of children[u]) {
            const cn = dpNot[v], cs = dpSel[v];
            const comb = new Array(k);
            for (let j = 0; j < k; j++) comb[j] = (cn[j] + cs[j]) % MOD;
            const newNot = new Array(k).fill(0n);
            for (let a = 0; a < k; a++) {
                if (dn[a] === 0n) continue;
                for (let b = 0; b < k; b++) {
                    if (comb[b] === 0n) continue;
                    const idx = (a + b) % k;
                    newNot[idx] = (newNot[idx] + dn[a] * comb[b]) % MOD;
                }
            }
            const newSel = new Array(k).fill(0n);
            for (let a = 0; a < k; a++) {
                if (ds[a] === 0n) continue;
                for (let b = 0; b < k; b++) {
                    if (cn[b] === 0n) continue;
                    const idx = (a + b) % k;
