    for (let i = 0; i < word.length; i++) {
        const ch = word[i];
        if (!node[ch]) node[ch] = {};
        node = node[ch];
    }
    node.isEnd = true;                  // mark end of a word
};

/* Search word; return true only if the full word exists and is marked as end */
Trie.prototype.search = function (word) {
    let node = this.root;
    for (let i = 0; i < word.length; i++) {
        const ch = word[i];
        if (!node[ch]) return false;
        node = node[ch];
    }
    return !!node.isEnd;
};

/* Check whether any word in the trie starts with the given prefix */
Trie.prototype.startsWith = function (prefix) {
    let node = this.root;
    for (let i = 0; i < prefix.length; i++) {
        const ch = prefix[i];
        if (!node[ch]) return false;
        node = node[ch];
    }
    return true;
};

function lowestCommonAncestor(root, p, q) {
    let node = root;
    const pVal = p.val, qVal = q.val;
    while (node) {
        // main logic: move left or right depending on both values, else current node is LCA
        if (pVal < node.val && qVal < node.val) {
            node = node.left;
        } else if (pVal > node.val && qVal > node.val) {
            node = node.right;
        } else {
            return node;
        }
    }
    return null; // not found (shouldn't happen for valid input)
}

function isValidBST(root) {
    // helper checks node value within allowed range
    function validate(node, lower, upper) {
        if (node === null) return true;                     // leaf reached
        if (node.val <= lower || node.val >= upper) return false; // violation
        // recurse left with updated upper bound, then right with updated lower bound
        return validate(node.left, lower, node.val) && validate(node.right, node.val, upper);
    }
    return validate(root, -Infinity, Infinity);
}

function kthLargest(nums, k) {
    // Convert k to index for the (n‑k)th smallest element
    let target = nums.length - k;

    // Quickselect loop
    let left = 0, right = nums.length - 1;
    while (true) {
        // Partition around a pivot and get its final position
        let pivotIdx = partition(nums, left, right);
        if (pivotIdx === target) return nums[pivotIdx];   // found
        if (pivotIdx < target) left = pivotIdx + 1;       // search right side
        else right = pivotIdx - 1;                        // search left side
    }
}

// Lomuto partition scheme
function partition(arr, left, right) {
    // Choose rightmost element as pivot
    let pivot = arr[right];
    let i = left;
    for (let j = left; j < right; j++) {
        if (arr[j] <= pivot) {
            [arr[i], arr[j]] = [arr[j], arr[i]];
            i++;
        }
    }
    [arr[i], arr[right]] = [arr[right], arr[i]];
    return i; // final pivot position
}

function countComponents(n, edges) {
    // initialise DSU
    var parent = new Array(n);
    var rank = new Array(n);
    for (var i = 0; i < n; i++) {
        parent[i] = i;
        rank[i] = 0;
    }

    function find(x) {                     // path compression
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    function union(a, b) {                 // union by rank, returns true if merged
        var ra = find(a);
        var rb = find(b);
        if (ra === rb) return false;
        if (rank[ra] < rank[rb]) {
            parent[ra] = rb;
        } else if (rank[ra] > rank[rb]) {
            parent[rb] = ra;
        } else {
            parent[rb] = ra;
            rank[ra]++;
        }
        return true;
    }

    var components = n;                    // count components
    for (var i = 0; i < edges.length; i++) {
        if (union(edges[i][0], edges[i][1])) components--; // merge reduces count
    }
    return components;
}

// TIME: O(n + m α(n)) SPACE: O(n)

function rangeSumQuery(nums, queries) {
    const n = nums.length;
    const tree = new Array(4 * n).fill(0);

    // build segment tree
    function build(node, l, r) {
        if (l === r) { tree[node] = nums[l]; return; }
        const mid = (l + r) >> 1;
        build(node * 2, l, mid);
        build(node * 2 + 1, mid + 1, r);
        tree[node] = tree[node * 2] + tree[node * 2 + 1];
    }
    build(1, 0, n - 1);

    // point update
    function update(node, l, r, idx, val) {
        if (l === r) { tree[node] = val; return; }
        const mid = (l + r) >> 1;
        if (idx <= mid) update(node * 2, l, mid, idx, val);
        else update(node * 2 + 1, mid + 1, r, idx, val);
        tree[node] = tree[node * 2] + tree[node * 2 + 1];
    }

    // range sum query
    function query(node, l, r, ql, qr) {
        if (ql <= l && r <= qr) return tree[node];
        const mid = (l + r) >> 1;
        let sum = 0;
        if (ql <= mid) sum += query(node * 2, l, mid, ql, qr);
        if (qr > mid) sum += query(node * 2 + 1, mid + 1, r, ql, qr);
        return sum;
    }

    const ans = [];
    for (const op of queries) {
        if (op[0] === 'update') {
            update(1, 0, n - 1, op[1], op[2]);
        } else { // 'sum'
            ans.push(query(1, 0, n - 1, op[1], op[2]));
        }
    }
    return ans;
}

// TIME: O((n + q) log n) SPACE: O(n)

function maxProfit(prices) {
    if (prices.length === 0) return 0;

    let cash = 0;                     // profit without stock today
    let hold = -prices[0];            // profit with stock today (bought on day 0)
    let prevCash = 0;                 // cash value from two days ago

    for (let i = 1; i < prices.length; i++) {
        const price = prices[i];
        const newCash = Math.max(cash, hold + price);          // sell or stay idle
        const newHold = Math.max(hold, prevCash - price);     // buy (after cooldown) or stay idle
        prevCash = cash;                                       // shift window for next iteration
        cash = newCash;
        hold = newHold;
    }
    return cash;                     // best profit ends without holding a stock
}

function countHouses(n, x, y) {
    const adj = Array.from({ length: n + 1 }, () => []);
    for (let i = 1; i < n; i++) {
        adj[i].push(i + 1);
        adj[i + 1].push(i);
    }
    if (x !== y) {
        adj[x].push(y);
        adj[y].push(x);
    }

    const result = new Array(n).fill(0); // index 0..n-2 => distance 1..n-1

    for (let src = 1; src <= n; src++) {
        const dist = new Array(n + 1).fill(-1);
        dist[src] = 0;
        const queue = [src];
        let head = 0;
        while (head < queue.length) {
            const cur = queue[head++];
            for (const nxt of adj[cur]) {
                if (dist[nxt] === -1) {
                    dist[nxt] = dist[cur] + 1;
                    queue.push(nxt);
                }
            }
        }
        for (let dest = 1; dest <= n; dest++) {
            if (dest === src) continue;
            const d = dist[dest];
            if (d >= 1 && d <= n - 1) result[d - 1]++;
        }
    }
    return result;
}

function minCost(nums) {
    let minCost = Infinity;
    // iterate over all possible first subarray endings
    for (let i = 0; i < nums.length - 2; i++) {
        // iterate over all possible second subarray endings
        for (let j = i + 1; j < nums.length - 1; j++) {
            // calculate the cost of the current subarray division
            let cost = nums[0] + nums[i + 1] + nums[j + 1];
            // update the minimum cost if the current cost is smaller
            minCost = Math.min(minCost, cost);
        }
    }
    return minCost;
}

function minOperations(nums, k) {
    // calculate the XOR of all elements in the array
    let xor = 0;
    for (let num of nums) {
        xor ^= num;
    }
    // if the XOR is already equal to k, return 0
    if (xor === k) return 0;
    // calculate the number of bits that need to be flipped to make the XOR equal to k
    let diff = xor ^ k;
    // count the number of bits set in the difference
    let count = 0;
    while (diff > 0) {
        // count the number of bits set in the difference
        count += diff & 1;
        diff >>= 1;
    }
    return count;
}

// TIME: O(n + log(max(nums))) SPACE: O(1)

var maximumSubarraySum = function(nums, k) {
    let maxSum = -Infinity;
    let prefix = 0;
    const minPrefixByVal = new Map();
    for (const num of nums) {
        const prefixBefore = prefix;
        prefix += num;
        for (const target of [num+k, num-k]) {
            if (minPrefixByVal.has(target)) {
                const cand = prefix - minPrefixByVal.get(target);
                if (cand > maxSum) maxSum = cand;
            }
        }
        if (k === 0 && num > maxSum) maxSum = num;
        if (!minPrefixByVal.has(num) || prefixBefore < minPrefixByVal.get(num)) {
            minPrefixByVal.set(num, prefixBefore);
        }
    }
    return Math.trunc(maxSum);
};

function countPowerfulIntegers(start, finish, limit, s) {
  for (const ch of s) {
    if (Number(ch) > limit) return 0;
  }
  function countUpTo(x) {
    if (x < 0) return 0;
    const t = String(x);
    if (t.length < s.length) return 0;
    const memo = new Map();
    function dfs(pos, lim) {
      if (t.length - pos === s.length) {
        if (lim) return (s <= t.slice(pos)) ? 1 : 0;
        return 1;
      }
      if (!lim && memo.has(pos)) return memo.get(pos);
      let up = lim ? (t.charCodeAt(pos) - 48) : 9;
      up = Math.min(up, limit);
      let ans = 0;
      for (let d = 0; d <= up; d++) {
        ans += dfs(pos + 1, lim && d === (t.charCodeAt(pos) - 48));
      }
      if (!lim) memo.set(pos, ans);
      return ans;
    }
    return dfs(0, true);
  }
  return countUpTo(finish) - countUpTo(start - 1);
}

function minimumKeypresses(word) {
    let freq = {};
    for (let char of word) { if (!freq[char]) freq[char] = 0; freq[char]++; }
    let sortedFreq = Object.values(freq).sort((a, b) => b - a);
    let pushes = 0;
    for (let i = 0; i < sortedFreq.length; i++) {
        if (i < 8) { pushes += sortedFreq[i]; }
        else if (i < 16) { pushes += sortedFreq[i] * 2; }
        else { pushes += sortedFreq[i] * 3; }
    }
    return pushes;
}

function beautifulIndices(s, a, b, k) {
    let result = []; // store beautiful indices
    for (let i = 0; i <= s.length - a.length; i++) { // iterate over all possible substrings of 'a'
        if (s.substring(i, i + a.length) === a) { // check if current substring matches 'a'
            for (let j = 0; j <= s.length - b.length; j++) { // iterate over all possible substrings of 'b'
                if (s.substring(j, j + b.length) === b && Math.abs(i - j) <= k) { // check if current substring matches 'b' and distance is within 'k'
                    result.push(i); // add current index to result
                    break; // stop searching for 'b' as we've found one
                }
            }
        }
    }
    return [...new Set(result)].sort((a, b) => a - b); // remove duplicates and sort result
}

function maximumSize(nums1, nums2) {
    const half = nums1.length / 2;
    const u1 = new Set(nums1);
    const u2 = new Set(nums2);
    let common = 0;
    for (const v of u1) if (u2.has(v)) common++;
    const only1 = u1.size - common;
    const only2 = u2.size - common;

    const take1 = Math.min(half, only1);
    const take2 = Math.min(half, only2);
    const remainingCap = (half - take1) + (half - take2);
    const takeCommon = Math.min(common, remainingCap);

    return take1 + take2 + takeCommon;
}

function minCost(nums, k, dist) {
    const n = nums.length;
    const INF = Infinity;
    let answer = INF;

    for (let i1 = 1; i1 < n; i1++) {
        const maxLast = Math.min(n - 1, i1 + dist);
        const minLast = i1 + (k - 2) - 1;
        if (minLast > maxLast) continue;
        for (let iLast = minLast; iLast <= maxLast; iLast++) {
            const interiorLen = iLast - i1 - 1;
            const need = Math.max(k - 3, 0);
            if (interiorLen < need) continue;
            const interiorVals = nums.slice(i1 + 1, iLast).sort((a, b) => a - b);
            let sumSmallest = 0;
            for (let x = 0; x < need; x++) sumSmallest += interiorVals[x];
            const total = nums[0] + nums[i1] + nums[iLast] + sumSmallest;
            if (total < answer) answer = total;
        }
    }
    return answer === INF ? -1 : answer;
}

function minimumDamage(power, damage, health) {
  const n = damage.length;
  const enemies = [];
  for (let i = 0; i < n; i++) {
    const t = Math.ceil(health[i] / power);
    enemies.push([t, damage[i]]);
  }
  // sort by t_i / damage_i ascending -> compare via cross multiplication
  enemies.sort((a, b) => a[0] * b[1] - b[0] * a[1]);
  let total = 0;
  let elapsed = 0;
  for (const [t, dmg] of enemies) {
    elapsed += t;
    total += elapsed * dmg;
  }
  return total;
}

function popcount(n) {
  let c = 0;
  while (n) { n &= n - 1; c++; }
  return c;
}

function canSortArray(nums) {
  let i = 0;
  let prevMax = -Infinity;
  const n = nums.length;
  while (i < n) {
    let j = i;
    let curMin = nums[i], curMax = nums[i];
    const pc = popcount(nums[i]);
    while (j < n && popcount(nums[j]) === pc) {
      curMin = Math.min(curMin, nums[j]);
      curMax = Math.max(curMax, nums[j]);
      j++;
    }
    if (curMin < prevMax) return false;
    prevMax = curMax;
    i = j;
  }
  return true;
}

// LC 3066. Minimum Operations to Exceed Threshold Value II
// Fills BOTH js_algo_missing and js_optimal_missing (same slug appears in both lists).
// Verified against both official examples in this repo's handoff notes.

// algo: sorted-array simulation, re-sorting after every merge (O(n^2 log n)).
function minOperationsAlgo(nums, k) {
  const arr = [...nums].sort((a, b) => a - b);
  let ops = 0;
  while (arr.length > 1 && arr[0] < k) {
    const x = arr.shift(), y = arr.shift();
    const merged = Math.min(x, y) * 2 + Math.max(x, y);
    // Re-insert in sorted position.
    let i = 0;
    while (i < arr.length && arr[i] < merged) i++;
    arr.splice(i, 0, merged);
    ops++;
  }
  return ops;
}

// optimal: binary min-heap, O(n log n).
function minOperationsOptimal(nums, k) {
  const heap = [...nums];
  const less = (a, b) => heap[a] < heap[b];
  const swap = (a, b) => { const t = heap[a]; heap[a] = heap[b]; heap[b] = t; };
  const siftDown = (i) => {
    const n = heap.length;
    while (true) {
      let smallest = i, l = 2 * i + 1, r = 2 * i + 2;
      if (l < n && less(l, smallest)) smallest = l;
      if (r < n && less(r, smallest)) smallest = r;
      if (smallest === i) break;
      swap(i, smallest); i = smallest;
    }
  };
  const siftUp = (i) => {
    while (i > 0) { const p = (i - 1) >> 1; if (!less(i, p)) break; swap(i, p); i = p; }
  };
  for (let i = (heap.length >> 1) - 1; i >= 0; i--) siftDown(i);
  const pop = () => { const top = heap[0]; heap[0] = heap[heap.length - 1]; heap.pop(); siftDown(0); return top; };
  const push = (v) => { heap.push(v); siftUp(heap.length - 1); };

  let ops = 0;
  while (heap.length > 1 && heap[0] < k) {
    const x = pop(), y = pop();
    push(Math.min(x, y) * 2 + Math.max(x, y));
    ops++;
  }
  return ops;
}

module.exports = { minOperationsAlgo, minOperationsOptimal };

// LC 1900. The Earliest and Latest Rounds Where Players Compete (Hard, n <= 28)
// Fills js_optimal_missing. Memoized DP over (posFromFront, posFromEnd, playersLeft).
function earliestAndLatest(n, firstPlayer, secondPlayer) {
  const memo = new Map();
  function dp(l, r, k) {
    if (l === r) return [1, 1];
    if (l > r) return dp(r, l, k);
    const key = l + ',' + r + ',' + k;
    if (memo.has(key)) return memo.get(key);
    let earliest = Infinity, latest = -Infinity;
    const half = Math.floor((k + 1) / 2);
    // Enumerate every way the two players' partners can land this round.
    for (let i = 1; i <= l; i++) {
      for (let j = l - i + 1; j <= r - i; j++) {
        if (!(l + r - Math.floor(k / 2) <= i + j && i + j <= half)) continue;
        const [a, b] = dp(i, j, half);
        earliest = Math.min(earliest, a + 1);
        latest = Math.max(latest, b + 1);
      }
    }
    const res = [earliest, latest];
    memo.set(key, res);
    return res;
  }
  return dp(firstPlayer, n - secondPlayer + 1, n);
}
module.exports = { earliestAndLatest };

// LC 3017. Count the Number of Houses at a Certain Distance II (Hard, O(n))
// Fills js_optimal_missing.
//
// n houses on a path 1..n plus one extra edge x-y. result[k] = number of
// ORDERED pairs at shortest distance k, for k=1..n.
//
// For i<j (WLOG x<=y), distance splits by region:
//  - both in leftArm  [1,x-1]  or both in rightArm [y+1,n]: distance = j-i
//  - both in core [x,y]: cycle of C=y-x+1 nodes, distance = min(gap, C-gap)
//  - leftArm x rightArm: shortcut always wins (or ties): (x-i)+1+(j-y)
//  - leftArm x core / core x rightArm: a threshold splits the core range
//    into a "direct wins" side and a "shortcut wins" side, independent of
//    the arm index.
// Every sub-case gives a *contiguous* run of distances as the other index
// sweeps its sub-range, so each is a single O(1) difference-array range-add.
function distanceHouses(n, x, y) {
  if (x > y) [x, y] = [y, x];
  if (x === y) {
    // Self-loop: the extra edge gives no benefit, it's a plain path graph.
    const cnt = new Array(n + 1).fill(0);
    for (let gap = 1; gap <= n - 1; gap++) cnt[gap] = 2 * (n - gap);
    return cnt.slice(1);
  }
  const diff = new Float64Array(n + 2);
  const add = (lo, hi, amt) => {
    lo = Math.max(lo, 1); hi = Math.min(hi, n);
    if (lo > hi) return;
    diff[lo] += amt; diff[hi + 1] -= amt;
  };

  const L = x - 1, R = n - y, C = y - x + 1;

  // Within a single region, distance is just the direct offset.
  for (let gap = 1; gap <= L - 1; gap++) add(gap, gap, 2 * (L - gap));
  for (let gap = 1; gap <= R - 1; gap++) add(gap, gap, 2 * (R - gap));
  for (let gap = 1; gap <= C - 1; gap++) {
    const d = Math.min(gap, C - gap);
    add(d, d, 2 * (C - gap));
  }

  // leftArm x rightArm: shortcut always wins here.
  for (let i = 1; i <= L; i++) {
    add((x - i) + 1 + 1, (x - i) + 1 + R, 2);
  }

  // leftArm x core: direct wins while 2j<=x+y, shortcut wins after.
  if (L > 0 && C > 0) {
    const thr = Math.floor((x + y) / 2);
    for (let i = 1; i <= L; i++) {
      const jHiDirect = Math.min(thr, y);
      if (jHiDirect >= x) add(x - i, jHiDirect - i, 2);
      const jLoShort = Math.max(thr + 1, x);
      if (jLoShort <= y) add((x - i) + 1, (x - i) + 1 + (y - jLoShort), 2);
    }
  }

  // core x rightArm: mirror image of the case above.
  if (R > 0 && C > 0) {
    const thr2 = Math.ceil((x + y - 1) / 2);
    for (let j = y + 1; j <= n; j++) {
      const iLoDirect = Math.max(thr2, x);
      if (iLoDirect <= y) add(j - y, j - iLoDirect, 2);
      const iHiShort = Math.min(thr2 - 1, y);
      if (iHiShort >= x) add(1 + (j - y), (iHiShort - x) + 1 + (j - y), 2);
    }
  }

  const cnt = new Array(n + 1).fill(0);
  let run = 0;
  for (let d = 1; d <= n; d++) { run += diff[d]; cnt[d] = run; }
  return cnt.slice(1);
}
module.exports = { distanceHouses };

// LC 3181. Maximum Total Reward Using Operations II (Hard, O(n * maxVal / 64) via BigInt bitset)
// Fills js_optimal_missing.
// f is a bitset: bit j set means "total reward j is achievable so far".
// For each distinct value v (ascending), a new achievable total v+prev is
// only valid when prev < v, i.e. prev's bits below v shifted up by v.
function maxTotalReward(rewardValues) {
  const vals = [...new Set(rewardValues)].sort((a, b) => a - b);
  let f = 1n; // bit 0 set: reward 0 is achievable
  for (const v of vals) {
    const vb = BigInt(v);
    const mask = (1n << vb) - 1n; // bits 0..v-1: totals strictly less than v
    const shifted = (f & mask) << vb;
    f |= shifted;
  }
  return f.toString(2).length - 1; // index of the highest set bit
}
module.exports = { maxTotalReward };

// LC 3441. Minimum Cost Good Caption (Hard, O(26n))
// Fills js_optimal_missing.
// Suffix DP: suf[i][j][r] = min cost for i..n-1 given position i uses
// letter j and still needs r more same-letter chars (r=2 fresh, 1, 0 done).
// Reconstruction walks left to right, always taking the smallest letter
// consistent with the optimal total cost (standard lex-smallest-optimal
// technique for this DP shape).
function minCostGoodCaption(caption) {
  const n = caption.length;
  if (n < 3) return '';
  const orig = new Int32Array(n);
  for (let i = 0; i < n; i++) orig[i] = caption.charCodeAt(i) - 97;
  const INF = 1e9;
  const suf = new Int32Array(n * 78).fill(INF); // flat [i][j][r], stride 26*3
  const idx = (i, j, r) => i * 78 + j * 3 + r;

  for (let j = 0; j < 26; j++) suf[idx(n - 1, j, 0)] = Math.abs(orig[n - 1] - j);
  for (let i = n - 2; i >= 0; i--) {
    let bestFresh = INF;
    // Cheapest way to start a brand new run at i+1, over every letter.
    for (let j = 0; j < 26; j++) { const v = suf[idx(i + 1, j, 2)]; if (v < bestFresh) bestFresh = v; }
    for (let j = 0; j < 26; j++) {
      const cost = Math.abs(orig[i] - j);
      suf[idx(i, j, 2)] = cost + suf[idx(i + 1, j, 1)];
      suf[idx(i, j, 1)] = cost + suf[idx(i + 1, j, 0)];
      const extend = suf[idx(i + 1, j, 0)];
      suf[idx(i, j, 0)] = cost + (extend < bestFresh ? extend : bestFresh);
    }
  }

  let target = INF, startLetter = -1;
  for (let j = 0; j < 26; j++) {
    const v = suf[idx(0, j, 2)];
    if (v < target) { target = v; startLetter = j; }
  }
  if (target >= INF) return '';

  const out = new Uint8Array(n);
  let letter = startLetter, r = 2, remaining = target;
  for (let i = 0; i < n; i++) {
    out[i] = letter;
    const cost = Math.abs(orig[i] - letter);
    const nextRemaining = remaining - cost;
    if (i === n - 1) break;
    if (r === 2) { r = 1; remaining = nextRemaining; continue; }
    if (r === 1) { r = 0; remaining = nextRemaining; continue; }
    // r === 0: free choice - extend same letter, or start fresh with the
    // smallest letter that still matches the optimal remaining cost.
    let bestLetter = -1, bestR = 0;
    if (suf[idx(i + 1, letter, 0)] === nextRemaining) { bestLetter = letter; bestR = 0; }
    for (let j = 0; j < 26; j++) {
      if (suf[idx(i + 1, j, 2)] === nextRemaining && (bestLetter === -1 || j < bestLetter)) {
        bestLetter = j; bestR = 2;
      }
    }
    letter = bestLetter; r = bestR; remaining = nextRemaining;
  }
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + out[i]);
  return s;
}
module.exports = { minCostGoodCaption };

// LC 3480. Maximize Subarrays After Removing One Conflicting Pair (Hard, O(n log n))
// Fills js_optimal_missing.
//
// For right endpoint r, bound(r) = max 'a' among pairs (a,b), a<b, with
// b<=r (a subarray [left,r] needs left>bound(r) to dodge every such pair).
// Baseline valid count = sum_r (r - bound(r)).
//
// Removing one specific pair only changes bound(r) for r >= its b, and
// only at the r's where it is the UNIQUE pair achieving the current max
// there - then bound(r) drops to the next-highest present value. We sweep
// r left to right and use a segment tree over "present a-values" to find
// that next-highest value in O(log n), crediting the gain to whichever
// pair is currently the sole holder of the max.
function maximumSubarrays(n, conflictingPairs) {
  const pairs = conflictingPairs.map(([x, y]) => (x < y ? [x, y] : [y, x]));
  const m = pairs.length;
  const byB = Array.from({ length: n + 1 }, () => []);
  for (let i = 0; i < m; i++) byB[pairs[i][1]].push(i);

  let size = 1;
  while (size < n + 1) size *= 2;
  const tree = new Uint8Array(2 * size);
  const setPresent = (a) => {
    let i = a + size;
    if (tree[i]) return;
    tree[i] = 1; i >>= 1;
    while (i >= 1 && !tree[i]) { tree[i] = 1; i >>= 1; }
  };
  // Largest present index <= x, or 0 if none (recursive segment-tree walk).
  const findPrevPresent = (x) => {
    if (x < 1) return 0;
    const rec = (node, lo, hi) => {
      if (lo > x || !tree[node]) return 0;
      if (lo === hi) return lo;
      const mid = (lo + hi) >> 1;
      const right = rec(2 * node + 1, mid + 1, hi);
      return right || rec(2 * node, lo, mid);
    };
    return rec(1, 0, size - 1);
  };

  const cnt = new Int32Array(n + 1);
  const soleOwner = new Int32Array(n + 1).fill(-1);
  let top1 = 0;
  const gain = new Float64Array(m);

  let baseline = 0;
  for (let r = 1; r <= n; r++) {
    for (const pi of byB[r]) {
      const a = pairs[pi][0];
      cnt[a]++;
      if (cnt[a] === 1) { setPresent(a); soleOwner[a] = pi; } else soleOwner[a] = -1;
      if (a > top1) top1 = a;
    }
    baseline += r - top1;
    if (top1 > 0 && cnt[top1] === 1) {
      const second = findPrevPresent(top1 - 1);
      const owner = soleOwner[top1];
      if (owner !== -1) gain[owner] += top1 - second;
    }
  }

  let best = 0;
  for (let i = 0; i < m; i++) if (gain[i] > best) best = gain[i];
  return baseline + best;
}
module.exports = { maximumSubarrays };

// LC 3527 (formerly 3245). Alternating Groups III (Hard, O((n+q) log n))
// Fills js_optimal_missing.
//
// isBreak[i] = colors[i] == colors[(i-1+n)%n] (tile i repeats its
// predecessor, breaking any alternating run). Breakpoints partition the
// circle into maximal alternating runs; a window of exact size `size`
// fits inside a run of length L in (L-size+1) ways (0 if size>L).
//
// Toggling one tile can only flip isBreak at two positions (idx and
// idx+1); each flip either splits one run into two or merges two runs
// into one. Run lengths live in two Fenwick trees (count, and
// length*count) for O(log n) suffix-sum queries; a segment tree over
// "is this position currently a breakpoint" gives O(log n) predecessor /
// successor lookups to find which run(s) a flip touches.
class Fenwick {
  constructor(n) { this.n = n; this.a = new Float64Array(n + 1); }
  add(i, v) { for (; i <= this.n; i += i & -i) this.a[i] += v; }
  sum(i) { let s = 0; for (; i > 0; i -= i & -i) s += this.a[i]; return s; }
  rangeSum(l, r) { return l > r ? 0 : this.sum(r) - this.sum(l - 1); }
}

class AlternatingGroups {
  constructor(colors) {
    const n = colors.length;
    this.n = n;
    this.colors = Uint8Array.from(colors);
    this.isBreak = new Uint8Array(n);

    let size = 1;
    while (size < n) size *= 2;
    this.segSize = size;
    this.tree = new Uint8Array(2 * size); // presence of breakpoints

    this.cntBIT = new Fenwick(n); // count[] of run lengths, 1-indexed
    this.sumBIT = new Fenwick(n); // L*count[] of run lengths
    this.breakCount = 0;

    for (let i = 0; i < n; i++) {
      this.isBreak[i] = this.colors[i] === this.colors[(i - 1 + n) % n] ? 1 : 0;
      if (this.isBreak[i]) { this._setPresent(i); this.breakCount++; }
    }
    if (this.breakCount > 0) {
      // Walk the circle once from the first breakpoint to seed every run.
      const breaks = [];
      for (let i = 0; i < n; i++) if (this.isBreak[i]) breaks.push(i);
      const k = breaks.length;
      for (let t = 0; t < k; t++) {
        const start = breaks[t], end = breaks[(t + 1) % k];
        const len = ((end - start + n) % n) || n;
        this._insertRun(len);
      }
    }
    // breakCount === 0 means a fully alternating circle (only possible for
    // even n): no runs are tracked, handled directly in query().
  }

  _setPresent(i) {
    let idx = i + this.segSize;
    if (this.tree[idx]) return;
    this.tree[idx] = 1; idx >>= 1;
    while (idx >= 1 && !this.tree[idx]) { this.tree[idx] = 1; idx >>= 1; }
  }
  _clearPresent(i) {
    let idx = i + this.segSize;
    if (!this.tree[idx]) return;
    this.tree[idx] = 0; idx >>= 1;
    while (idx >= 1) {
      const now = (this.tree[2 * idx] || this.tree[2 * idx + 1]) ? 1 : 0;
      if (this.tree[idx] === now) break;
      this.tree[idx] = now; idx >>= 1;
    }
  }
  _prevPresent(x) { // largest present index in [0,x], or -1
    if (x < 0) return -1;
    const rec = (node, lo, hi) => {
      if (lo > x || !this.tree[node]) return -1;
      if (lo === hi) return lo;
      const mid = (lo + hi) >> 1;
      const r = rec(2 * node + 1, mid + 1, hi);
      return r !== -1 ? r : rec(2 * node, lo, mid);
    };
    return rec(1, 0, this.segSize - 1);
  }
  _nextPresent(x) { // smallest present index in [x,segSize-1], or -1
    if (x >= this.segSize) return -1;
    const rec = (node, lo, hi) => {
      if (hi < x || !this.tree[node]) return -1;
      if (lo === hi) return lo;
      const mid = (lo + hi) >> 1;
      const l = rec(2 * node, lo, mid);
      return l !== -1 ? l : rec(2 * node + 1, mid + 1, hi);
    };
    return rec(1, 0, this.segSize - 1);
  }
  _predOf(p) { // predecessor of p among breakpoints, circularly
    const a = this._prevPresent(p - 1);
    return a !== -1 ? a : this._prevPresent(this.n - 1);
  }
  _succOf(p) { // successor of p among breakpoints, circularly
    const a = this._nextPresent(p + 1);
    return a !== -1 && a < this.n ? a : this._nextPresent(0);
  }

  _insertRun(len) { this.cntBIT.add(len, 1); this.sumBIT.add(len, len); }
  _removeRun(len) { this.cntBIT.add(len, -1); this.sumBIT.add(len, -len); }
  _circLen(from, to) { return ((to - from + this.n) % this.n) || this.n; }

  update(idx, color) {
    const n = this.n;
    if (this.colors[idx] === color) return;
    this.colors[idx] = color;
    // Only the two edges touching idx can change break status.
    for (const e of [idx, (idx + 1) % n]) {
      const newVal = this.colors[e] === this.colors[(e - 1 + n) % n] ? 1 : 0;
      if (newVal === this.isBreak[e]) continue;
      if (newVal === 1) this._insertBreak(e); else this._removeBreak(e);
      this.isBreak[e] = newVal;
    }
  }

  _insertBreak(p) {
    if (this.breakCount === 0) {
      // First breakpoint ever: the whole circle becomes one run of length
      // n, cut open at p. No prior run to remove.
      this._setPresent(p); this.breakCount = 1; this._insertRun(this.n);
      return;
    }
    const pred = this._predOf(p), succ = this._succOf(p);
    this._removeRun(this._circLen(pred, succ));
    this._setPresent(p); this.breakCount++;
    this._insertRun(this._circLen(pred, p));
    this._insertRun(this._circLen(p, succ));
  }

  _removeBreak(p) {
    if (this.breakCount === 1) {
      // Removing the only breakpoint returns to "fully alternating".
      this._clearPresent(p); this.breakCount = 0; this._removeRun(this.n);
      return;
    }
    const pred = this._predOf(p), succ = this._succOf(p);
    this._removeRun(this._circLen(pred, p));
    this._removeRun(this._circLen(p, succ));
    this._clearPresent(p); this.breakCount--;
    this._insertRun(this._circLen(pred, succ));
  }

  query(size) {
    if (this.breakCount === 0) return this.n; // every window fits
    const cntGE = this.cntBIT.rangeSum(size, this.n);
    const sumGE = this.sumBIT.rangeSum(size, this.n);
    return sumGE - (size - 1) * cntGE;
  }
}

function alternatingGroupsIII(colors, queries) {
  const ag = new AlternatingGroups(colors);
  const out = [];
  for (const q of queries) {
    if (q[0] === 1) out.push(ag.query(q[1]));
    else ag.update(q[1], q[2]);
  }
  return out;
}

module.exports = { AlternatingGroups, alternatingGroupsIII };
